  if (!PROFILES["Neville / PAC (Benjamin Satterley)"]) PROFILES["Neville / PAC (Benjamin Satterley)"] = { lead: "英国ニューカッスル出身の空中戦の名手が、リングに立つまでの歩みを語る。強気なリング姿の裏にある繊細さも率直に明かした回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Neville%20/%20PAC%20(Benjamin%20Satterley)"]], moves: [], facts: [] };
  if (PROFILES["Neville / PAC (Benjamin Satterley)"]._weak) { PROFILES["Neville / PAC (Benjamin Satterley)"].lead = "英国ニューカッスル出身の空中戦の名手が、リングに立つまでの歩みを語る。強気なリング姿の裏にある繊細さも率直に明かした回。"; delete PROFILES["Neville / PAC (Benjamin Satterley)"]._weak; }
  PROFILES["Neville / PAC (Benjamin Satterley)"].facts.push(...[{"cat": "暮らし", "t": "ニューカッスル出身の25歳", "b": "イングランド北東部のニューカッスル育ちで、収録時は25歳だったという。スコットランド国境まで車で1時間ほどの街で、地元の人は温かく寛大だと言われていると話す。有名な地元の茶色いエールは、自分の口には合わないそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（6:46〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=406s"]]}, {"cat": "好きなもの", "t": "地元サッカーチームが大好き", "b": "地元はサッカーの町で、ニューカッスル・ユナイテッドが大好きだと話す。収録時は年に8〜9か月ほど日本にいて、地元にいる時間は少ないという。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（7:39〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=459s"]]}, {"cat": "リングに来るまで", "t": "18歳で地元の小さな団体に入門", "b": "18歳のとき、地元の小さな団体付属のスクールでプロレスを始めたという。経験豊富な先生がいたわけではなく、基本だけを教わり、あとは自分で覚えていったそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（9:15〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=555s"]]}, {"cat": "家族", "t": "両親は趣味として見守った", "b": "両親は反対せず、あくまで学業優先の課外活動のように見ていたという。そこから仕事になるとは誰も思っていなかったと話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（10:04〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=604s"]]}, {"cat": "リングに来るまで", "t": "学生の収入の多くを練習代に", "b": "練習代は毎週払う方式で、学生だった当時は自由に使えるお金の大半が消えていたという。それでもリングで練習できる時間は貴重だったと振り返る。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（10:50〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=650s"]]}, {"cat": "リングに来るまで", "t": "名伯楽に見出され集中講座へ", "b": "駆け出しの頃の地元の興行で、有名な指導者マーク・スローンに目を留められ、教え子たちのいる養成所での集中講座に招かれたという。好意で誘ってもらえたことに今も感謝していると話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（12:24〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=744s"]]}, {"cat": "リングに来るまで", "t": "1週間、毎日8〜9時間の基礎漬け", "b": "ジムに7日間こもり、1日8〜9時間、基礎を叩き込まれたという。自分のそれまでの訓練が万全でないと自覚していたので、謙虚に、飢えた気持ちで臨めたそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（13:12〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=792s"]]}, {"cat": "好きなもの", "t": "90年代の軽量級を見て育った", "b": "体操の経験はなく、昔は親のベッドの上でバック宙をして遊んでいたという。憧れたのは90年代半ばの日本の軽量級や、アメリカ団体の軽量級の試合だったそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（14:51〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=891s"]]}, {"cat": "リングに来るまで", "t": "仲間4人で空中技を磨いた", "b": "スクールでは基礎練習が先で、最後の30分ほどで同じ空中技好きの仲間4人と新しい技に挑んでいたという。互いに刺激し合ったことが成長につながったと話す。仲間の多くは今は競技をやめているそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（16:28〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=988s"]]}, {"cat": "家族", "t": "リングネームは父の呼び名から", "b": "父とじゃれ合ってプロレスごっこをしていた幼い頃、腹筋が割れていたことから父にあだ名で呼ばれたのがきっかけだという。デビュー時に他の案が浮かばず、そのまま名乗ったそうだ。有名ラッパーが由来ではないと話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（19:42〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1182s"]]}, {"cat": "暮らし", "t": "自分は「シンプルな人間」", "b": "友人たちからは、単純なものを好む人だと言われているという。リング上の動きも創造性というより、影響を受けたものを積み重ねた結果だと謙遜している。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（21:18〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1278s"]]}, {"cat": "リングの話", "t": "19歳での海外団体の挑戦は不発", "b": "19歳の頃、英国での興行で海外の人気団体の試合に出る機会を得たが、緊張と自信のなさで思うような内容にならなかったという。当時は大きなチャンスだと思い、入念に準備していたそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（23:37〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1417s"]]}, {"cat": "リングの話", "t": "米国デビュー戦で手応えをつかむ", "b": "ロサンゼルスの団体でのデビュー戦は、経験豊富な相手が自分の状態を見て導いてくれたおかげで観客の反応が良かったという。想像以上の歓声に驚き、この道で食べていけるかもしれないと初めて思えたそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（26:05〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1565s"]]}, {"cat": "暮らし", "t": "夜勤の配送会社で働きながら週末に遠征", "b": "その頃は、日曜から木曜まで配送会社の工場で夜勤をし、週末にインディー団体を回っていたという。今振り返ればつらい時期だったが、笑って話せると語る。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（27:40〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1660s"]]}, {"cat": "リングの話", "t": "日本の団体と4年、契約書なしの関係", "b": "日本の団体には約4年専属のように参戦しているが、正式な契約はなく、信頼関係で成り立っているという。全員が一つの目標のために動く家族のような雰囲気に惹かれ、初めて行ったときから温かく迎えられたと話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（28:31〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1711s"]]}, {"cat": "暮らし", "t": "日本の仲間とは練習と体づくりで絆", "b": "日本語は少しだけで、英語が少し分かる仲間とは、トレーニングや食事など真面目な取り組みを通じて仲良くなるという。夜遊びなどはなく、とてもプロ意識の高い環境だそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（30:07〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=1807s"]]}, {"cat": "体のこと", "t": "ストレッチと食事を日本で学んだ", "b": "年に約180試合、週に4〜5試合という忙しい日程のため、日本の選手たちは小さなけがでもすぐ病院に行くという。魚介中心の食事を見習い、試合前は全身を入念に伸ばすのが習慣になったと話す。来日前はほぼやっていなかったそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（34:07〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2047s"]]}, {"cat": "リングの話", "t": "ターザン風の「ジャングル」キャラ", "b": "海外ツアーでは、長髪がターザンに似ていることから、会社からジャングルのキャラクターを提案されたという。しゃべらず叫ぶだけの原始人風で、観客が声を真似して会場中に響いたのは楽しい思い出だと話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（39:52〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2392s"]]}, {"cat": "リングの話", "t": "最大約1万6千人の前で腰布姿", "b": "ツアーでは大観衆の前に立つこともあり、最大は約1万6千人、次がマドリードの約1万人だったという。ホテルや食事の待遇も良く、毎日夢のようで自分をつねっていたそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（40:41〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2441s"]]}, {"cat": "暮らし", "t": "ビジネスは苦手、SNSもほぼやらない", "b": "自分は商売が苦手だと話し、当時はツイッターも持たず、フェイスブックも私用だけだったという。目標も少なく、日々を大切にするタイプだったが、最近は少しずつ目標を持ち始めているそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（43:52〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2632s"]]}, {"cat": "好きなもの", "t": "レゲエ音楽に夢中", "b": "サッカー好きに加え、最近はレゲエ音楽に強く惹かれていると話す。理由は自分でも分からないが、聞くと心に響くのだという。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（46:18〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2778s"]]}, {"cat": "体のこと", "t": "失敗や拒絶への強い不安を告白", "b": "拒絶されること、失敗することへの恐れが強く、そのせいで挑戦を避けてきた面があると打ち明けている。この番組で話すこと自体も怖かったが、終えたあとは前向きな気持ちになったという。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（48:00〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=2880s"]]}, {"cat": "リングの話", "t": "今の居場所を失う怖さ", "b": "専属で安定して食べられている今の環境を離れ、よそで失敗したら何も残らないと考えてしまうという。大手団体への挑戦を勧められたときも、光栄な一方で最悪の結果が先に浮かんだそうだ。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（50:25〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=3025s"]]}, {"cat": "体のこと", "t": "話してみて気持ちが軽くなった", "b": "収録後は達成感があり、人生の転機になるかもしれないと感じたという。変わりたい気持ちは強く、弱さを見せることも悪くないと思い始めたと話す。", "sp": "ネヴィル / PAC", "d": "2014-12-23", "how": "コルト・カバナの番組で（字幕を全文確認）", "art": "ext-WndUnrvbohk", "src": [["番組のYouTube（52:51〜）", "https://www.youtube.com/watch?v=WndUnrvbohk&t=3171s"]]}]);
  ARTICLES.push({ id: "ext-WndUnrvbohk", d: "2014-12-23", show: "ext", who: ["Neville / PAC (Benjamin Satterley)"], t: "ネヴィル / PACの回　下積みから胸の内の告白まで", lead: "コルト・カバナの番組に出た約68分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Neville / PAC (Benjamin Satterley)"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-WndUnrvbohk").map((x) => [x.t, x.b, x.sp])), open: ["字幕の自動認識が崩れており、練習代の金額や一部の固有名詞は確信が持てず省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=WndUnrvbohk"]] });
