  if (!PROFILES["Wade Barrett"]) PROFILES["Wade Barrett"] = { lead: "2016年、WWEを離れた直後に映画の撮影現場で語ったインタビュー。選手時代の不満も率直に話しつつ、「バッド・ニュース・バレット」に込めたイギリス流の笑いへのこだわりが伝わる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Wade%20Barrett"]], moves: [], facts: [] };
  if (PROFILES["Wade Barrett"]._weak) { PROFILES["Wade Barrett"].lead = "2016年、WWEを離れた直後に映画の撮影現場で語ったインタビュー。選手時代の不満も率直に話しつつ、「バッド・ニュース・バレット」に込めたイギリス流の笑いへのこだわりが伝わる。"; delete PROFILES["Wade Barrett"]._weak; }
  PROFILES["Wade Barrett"].facts.push(...[{"cat": "リングの話", "t": "若いころの名前は「ザ・ピナクル」", "b": "これまでいくつものリング名を使ってきたが、21歳ごろに自分で考えた「ザ・ピナクル」は、ザ・ロックの「てっぺん」を狙った名前だったという。すぐに却下されたと笑う。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=0s"]]}, {"cat": "暮らし", "t": "WWEを離れて映画の世界へ", "b": "WWEを離れた後、元特殊部隊員が故郷の町に戻って悪を倒すアクション映画の主演を務めたという。共演したイギリスのアクション俳優ゲイリー・ダニエルズや撮影スタッフから学ぶのが楽しく、スタントもすべて自分でこなしたそうだ。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=45s"]]}, {"cat": "リングの話", "t": "最後のレッスルマニア", "b": "契約の切れる前、最後のレッスルマニアでは、当日になってビンス・マクマホンの発案でショーン・マイケルズ、ストーン・コールド、ミック・フォーリーが乱入し、自分たちを痛めつける形になったという。子どものころから憧れていた3人と並べたのは良い別れになったと話す。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（3:02〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=182s"]]}, {"cat": "リングの話", "t": "「殴られ役」に嫌気がさした", "b": "2015〜16年は選手としてみじめな時期だったという。負けること自体は構わないが、物語もなく毎晩数分で負けるだけの役割では、子どものころに夢中になった筋書きやキャラクターの面白さがないと感じたそうだ。会議で推してくれる人もいなくなり、3年の新契約には署名しなかったと話す。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（5:32〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=332s"]]}, {"cat": "暮らし", "t": "辞めてから番組は見ていない", "b": "WWEを離れて約4か月、番組は1秒も見ておらず、辞めたことを後悔した瞬間もないという。ここ数年で一番幸せだと話す。プロレスを引退したわけではなく、裏方や解説なら戻る可能性もあると語っていた。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（9:45〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=585s"]]}, {"cat": "好きなもの", "t": "サッカー好きの仲間たち", "b": "シェイマスとは長い付き合いで、通算では1勝しかしていないと笑う。ルセフやアルベルト・デル・リオら仲間はみなサッカー好きだったという。ルセフは自然体で面白く、映画でも活躍できると話している。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（14:25〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=865s"]]}, {"cat": "リングの話", "t": "ネビルとの幻のタッグ案", "b": "親友のネビルと組みたくて、最後の2年はさまざまな案を出していたという。イギリス北部出身の2人がハンチング帽をかぶり、ブリティッシュ・ブルドッグスへの敬意を込めて犬を連れて入場する案もあったそうだ。採用されず、おもちゃの王冠をかぶる役になったと苦笑する。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（18:34〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=1114s"]]}, {"cat": "リングの話", "t": "バッド・ニュース・バレットは代表作", "b": "ネクサス以外で一番大きな仕事は「バッド・ニュース・バレット」だったという。少し笑いを効かせた悪役で、殿堂入り式典での乱入はイギリスのファンも多く大きく沸いたそうだ。バレンタインデーの放送で台本を勝手に変え、ビンスが叱るに叱れず笑い転げていた話も明かしている。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（21:02〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=1262s"]]}, {"cat": "リングの話", "t": "ビンスとの関係", "b": "キャラクターの扱いに不満を持ったことは多いが、ビンスは顔を合わせればいつも敬意を持って接し、提案が通らないときも理由を説明してくれたという。辞めた後もわだかまりはないと話す。", "sp": "ウェイド・バレット", "d": "2016-08-19", "how": "ゴリラ・ポジション（イギリスのプロレス番組）で（字幕を全文確認）", "art": "ext-vnLxnGDi_ZA", "src": [["番組のYouTube（23:26〜）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA&t=1406s"]]}]);
  ARTICLES.push({ id: "ext-vnLxnGDi_ZA", d: "2016-08-19", show: "ext", who: ["Wade Barrett"], t: "ウェイド・バレットの回　WWEを離れた直後、映画の撮影現場で", lead: "ゴリラ・ポジション（イギリスのプロレス番組）に出た約27分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Wade Barrett"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-vnLxnGDi_ZA").map((x) => [x.t, x.b, x.sp])), open: ["映画の宣伝の部分は簡単にまとめた。2016年当時の発言で、この後に解説者としてWWEに戻っている。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=vnLxnGDi_ZA"]] });
  if (!ROSTER.find((r) => r[1] === "Berto")) ROSTER.push(["ベルト", "Berto", "lg", "", "", "", ""]);
  if (!PROFILES["Berto"]) PROFILES["Berto"] = { lead: "メキシコ・モンテレイ出身、ガルサ一家の血を引くベルト（当時の名前はウンベルト・カリージョ）。子どもの頃にテレビの前で口にした夢を、覆面を脱いでかなえた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Berto"]], moves: [], facts: [] };
  if (PROFILES["Berto"]._weak) { PROFILES["Berto"].lead = "メキシコ・モンテレイ出身、ガルサ一家の血を引くベルト（当時の名前はウンベルト・カリージョ）。子どもの頃にテレビの前で口にした夢を、覆面を脱いでかなえた。"; delete PROFILES["Berto"]._weak; }
  PROFILES["Berto"].facts.push(...[{"cat": "リングの話", "t": "けが人の代役で、急に素顔デビュー", "b": "育成ブランドでのデビューは予定になかったと、ベルトは話す。出るはずだった選手がけがで欠場し、急きょ代わりに出ることになったという。その日に「覆面なし、本名で」と告げられ、それまで素顔で戦ったことがなかったので大きな変化だったそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（1:37〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=97s"]]}, {"cat": "リングの話", "t": "心の中には今も「ウルティモ・ニンジャ」", "b": "メキシコのインディーでは覆面の「ウルティモ・ニンジャ」として戦っていたと、ベルトは話す。素顔で戦うのは今ではとても居心地がいいが、覆面が恋しくなることもあるという。技は同じなので、心の奥ではまだウルティモ・ニンジャのままだと感じているそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=143s"]]}, {"cat": "家族", "t": "祖父といとこたちが誇りに思ってくれる", "b": "祖父やいとこたちと話す機会があり、みんなが自分の歩みを誇りに思ってくれていると、ベルトは話す。新しい番組への起用が決まったときは、まず父に電話して説明したという。家族がいつも支えてくれると分かっているのが心強いそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（3:14〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=194s"]]}, {"cat": "信仰", "t": "チャンスは神さまからの贈り物", "b": "自分は神さまに頼って生きる人間で、ここまで来られたのは神さまのおかげだと感じていると、ベルトは話す。年の初めに立てた目標とは違う道が開けたが、「神の計画は完ぺき」だと受け止めたという。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（4:52〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=292s"]]}, {"cat": "リングの話", "t": "新しい舞台に合わせて「倍」鍛える", "b": "年の初めは育成ブランドで王座を取ることを目標にしていたが、クルーザー級の番組にも出ることになり、計画を切り替えたと、ベルトは話す。体も心も2倍準備して、2つのブランドで結果を出したいという。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（5:42〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=342s"]]}, {"cat": "リングの話", "t": "王座挑戦で敗れ、悔しさが残った", "b": "クルーザー級王者バディ・マーフィーの公開挑戦に名乗り出て戦い、あと一歩で敗れたと、ベルトは振り返る。相手は体も強く技術も高い選手だったが、横やりでの決着に心残りがあるという。再戦の機会がほしいそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（7:13〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=433s"]]}, {"cat": "リングの話", "t": "同郷グラン・メタリックとの再会", "b": "グラン・メタリックとは、地元モンテレイのインディーで戦って以来の2度目の対戦だったと、ベルトは話す。似たスタイルで、リング上で通じ合えたという。番組で初勝利を挙げたときは信じられない気持ちだったそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（8:50〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=530s"]]}, {"cat": "リングの話", "t": "夢はレイ・ミステリオと戦うこと", "b": "いつかレイ・ミステリオと戦うのが夢だと、ベルトは話す。アンドラーデともメキシコで戦ったことがなく、ぜひ当たってみたいという。メキシコらしい空中殺法の試合は観客が喜ぶと感じているそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（11:17〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=677s"]]}, {"cat": "リングに来るまで", "t": "「いつかあそこに立つ」と言って笑われた", "b": "子どもの頃、いとこや母とテレビでプロレスを見ていたとき、母に「いつかあそこに立つ」と言ったと、ベルトは振り返る。そばにいた別のいとこには大笑いされたという。心から本気で口にしたことは実現できると信じているそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（16:06〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=966s"]]}, {"cat": "家族", "t": "いとこと一緒にトライアウトから始めた", "b": "いとこのアンヘル（アンヘル・ガルサ）とは、2015〜2016年ごろのトライアウトから一緒に歩んできたと、ベルトは話す。自分だけ先に契約が決まったときは悲しかったという。いとことして、兄弟として、2人でガルサの名を高く掲げたいと願っていたそうだ。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で（字幕を全文確認）", "art": "ext-uI5xfQnyn9U", "src": [["番組のYouTube（22:21〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=1341s"]]}]);
  if (PROFILES["Andrade"]) PROFILES["Andrade"].facts.push({"cat": "暮らし", "t": "アンドラーデは中南米の選手の顔になれる", "b": "アンドラーデは十分な力を持つ選手で、SmackDownで中南米の選手の顔になりつつあると、ベルトが話している。", "sp": "ベルト", "d": "2019-02-05", "how": "ルチャ・リブレ・オンラインの番組で、ベルトの話（字幕を全文確認）", "src": [["番組のYouTube（20:47〜）", "https://www.youtube.com/watch?v=uI5xfQnyn9U&t=1247s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-uI5xfQnyn9U", d: "2019-02-05", show: "ext", who: ["Berto"], t: "ベルトの回　覆面を脱いだ日、ガルサ家の誇り、いとこと交わした約束", lead: "ルチャ・リブレ・オンラインの番組に出た約26分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Berto"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-uI5xfQnyn9U").map((x) => [x.t, x.b, x.sp])), open: ["自動字幕の崩れが大きい箇所は載せていない。", "途中で参加した実況者の話や、聞き手の家族の事情の話は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=uI5xfQnyn9U"]] });
  if (!ROSTER.find((r) => r[1] === "Corey Graves")) ROSTER.push(["コーリー・グレイブス", "Corey Graves", "lg", "解説者", "", "", ""]);
  if (!PROFILES["Corey Graves"]) PROFILES["Corey Graves"] = { lead: "脳しんとうで選手の道を断たれ、解説者として生き直した人。人前は苦手で、休みがあると落ち着かない自分の性分やうつとの付き合い方まで、率直に語っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Corey%20Graves"]], moves: [], facts: [] };
  if (PROFILES["Corey Graves"]._weak) { PROFILES["Corey Graves"].lead = "脳しんとうで選手の道を断たれ、解説者として生き直した人。人前は苦手で、休みがあると落ち着かない自分の性分やうつとの付き合い方まで、率直に語っている。"; delete PROFILES["Corey Graves"]._weak; }
  PROFILES["Corey Graves"].facts.push(...[{"cat": "家族", "t": "父と一緒に見て育ったプロレス", "b": "父が大のプロレス好きで、物心ついたころから一緒に見ていたという。2〜3歳の写真ではもうハルク・ホーガンの人形を持っていて、プロレス好きは父のせいだと笑う。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（11:35〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=695s"]]}, {"cat": "リングに来るまで", "t": "舌ピアスの代わりにプロレス", "b": "14〜15歳のころ、悩みの解決策として舌にピアスを開けたいと父に言ったところ、「何か打ち込むことをしろ、ボディビルかボクシングかレスリングでも」と返されたという。消防署長だった父のつてで地元の団体に入り、暖房も冷房もない空き店舗で練習を始めたそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（12:22〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=742s"]]}, {"cat": "リングの話", "t": "悪役でいるのが好きだった", "b": "選手時代は、歓声を浴びるより悪役として負け、3カウントの後にマットに寝転んで「やり遂げた」と息をつく瞬間が一番の喜びだったという。勝った側のように見せ場を作らなくてよいのが性に合っていたと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（14:01〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=841s"]]}, {"cat": "暮らし", "t": "実は人見知り", "b": "人前では意外と恥ずかしがりで、無愛想に見られることもあるという。解説は自分の声で物語を伝えても注目の的にはならないので落ち着くそうで、レッスルマニアのメインを実況するより、カメラの前に立つ方が緊張すると話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（15:40〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=940s"]]}, {"cat": "家族", "t": "4人きょうだいの長男", "b": "4人きょうだいの一番上で、弟もプロレスラーとして日本などで活躍しているという。一番下の妹とは17歳ほど離れていて、家を出た後に生まれたため、大人になった今ようやく少しずつ知り合っている感覚だと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（18:50〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1130s"]]}, {"cat": "家族", "t": "消防車を売る父と911の母", "b": "父は消防車の販売業、母は長年911の通信指令員という、救急の世界に囲まれて育ったという。自分も高校時代に救急車で実習し、救急救命士を目指したが、合わないと感じてやめたそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（20:32〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1232s"]]}, {"cat": "暮らし", "t": "ピアス職人から911へ", "b": "タトゥー店で約7年、ボディピアスの仕事をしていたという。舌ピアスを止められた話の通り、いろいろな改造をしても舌だけは開けていないと笑う。子どもが生まれることになって安定した仕事が必要になり、ピッツバーグ市の911の指令員として働いていたそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（21:22〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1282s"]]}, {"cat": "リングに来るまで", "t": "知らずに出た日本のデスマッチ", "b": "イギリスや日本でも試合をし、日本では行ってみて初めてデスマッチを求められていると知ったという。蛍光灯やフォークで打ち合う世界だったが、1か月ほど暮らして文化に触れたことは最高の経験の一つだと振り返る。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（23:43〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1423s"]]}, {"cat": "リングに来るまで", "t": "諦めかけたころの契約", "b": "WWEにはエキストラとして何度も呼ばれたが、契約には届かず、家庭を持ってほぼ夢を諦めていたという。911の休みの日に小遣い稼ぎで出たテレビ収録で「見違えた」と声をかけられ、数週間後に契約の電話が来たそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（24:34〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1474s"]]}, {"cat": "暮らし", "t": "タトゥーは人を遠ざけるため", "b": "たくさんのタトゥーは、人を寄せつけるより、話しかけにくい見た目になるために入れたのだという。夜中に戻ったホテルでファンに待たれるのは今も苦手で、自分ではいまだにピッツバーグの普通の男だと思っていると話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（26:11〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1571s"]]}, {"cat": "家族", "t": "長男の誕生はスペイン遠征中", "b": "長男が生まれたとき、家族を養うためスペイン遠征に出ていて立ち会えなかったという。闘牛場でギャングレルと戦った記事が、誕生日の日付入りでスポーツ面に載っていて、「パパは吸血鬼と戦っていた」と笑い話にしているそうだ。2人の娘の誕生には立ち会えたと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（31:50〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=1910s"]]}, {"cat": "体のこと", "t": "1年で4度の脳しんとう", "b": "WWEで1年に4度、脳しんとうと診断されたという。それ以前のインディー時代にも、今思えば数えきれないほどあったはずだと話す。当時は危険性を分かっておらず、早く検査をパスして復帰することしか考えていなかったそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（34:10〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=2050s"]]}, {"cat": "リングの話", "t": "人生最悪の日", "b": "なかなか復帰の許可が出ず、トリプルHに直接聞いたところ、その場で「最悪を覚悟しろ」と告げられたという。泣き顔を見せまいと控室へ駆け込むと、ウィリアム・リーガルが黙って抱きしめてくれたそうだ。生活の不安もあり、人生で一番つらい瞬間だったと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（35:43〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=2143s"]]}, {"cat": "リングの話", "t": "ダスティと過ごした1年", "b": "解雇はされず、音響や制作など何でも手伝わせてもらったという。中でもダスティ・ローデスのプロモ講座を手伝い、約1年そばにいられたことが一番の幸運だったそうだ。ダスティにジェームズ・ディーンの映画を見ろと言われ、昔の映画にはまったと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（38:55〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=2335s"]]}, {"cat": "体のこと", "t": "休まずに仕事へ", "b": "引退を告げられた後、週末2日だけ家にこもり、すぐ仕事に戻ったという。とはいえ長い間ふさぎ込み、身近な人には怒りっぽい時期もあったと認めている。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（42:08〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=2528s"]]}, {"cat": "リングの話", "t": "シールドの3人は大切な友", "b": "同期のシールドの3人は業界で一番好きな仲間だという。今は彼らの名場面に「音楽をつける」立場として関われるのがうれしいそうで、大会後にロリンズが抱きついて声をかけてくれたことは一生の思い出だと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（48:29〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=2909s"]]}, {"cat": "リングの話", "t": "レネイは姉妹のような友", "b": "解説席で組んだレネイ・ヤングは、悩みがあれば真っ先に話す、姉妹のような親友だという。マイケル・コールを放送中に笑わせられたら冗談は成功だと話す。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（52:25〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=3145s"]]}, {"cat": "リングの話", "t": "耳に指示が入る難しさ", "b": "解説を始めたころは、イヤホンで指示を言われると話が止まってしまったという。今は半音遅れで言われたことを口にできるようになったが、放送中にカメラの前で突然ビンス・マクマホンの声が入ったときは頭が真っ白になったと振り返る。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（54:49〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=3289s"]]}, {"cat": "暮らし", "t": "休みがあると落ち着かない", "b": "3年ほど1週も休まず働き続けていたという。休みがあると、自分の欠点ばかり考えてしまうので、何かに集中していた方が楽だと話す。働き者なのも睡眠が短くても平気なのも、夜勤明けに子どもたちを学校へ送り出していた母譲りだそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（1:02:54〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=3774s"]]}, {"cat": "体のこと", "t": "うつと瞑想", "b": "ここ数年、重いうつと闘ってきたという。いろいろな治療を試し、薬を飲んでいた時期もあるが、最近は瞑想を続けて頭がすっきりしていると話す。アプリで49日連続を記録したそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（1:08:37〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=4117s"]]}, {"cat": "家族", "t": "離婚を経て良い父に", "b": "離婚は子どものためにと長引かせたが、今は子どもと過ごす時間を大切にでき、長男にも「今の方が一緒の時間が濃い」と言われたという。家にいたころは自分のことで手一杯で、良い父ではなかったと振り返る。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（1:13:29〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=4409s"]]}, {"cat": "リングの話", "t": "解説者として残すもの", "b": "思い描いた道とはまったく違ったが、今はこれが自分の役目だったのかもしれないと思えるようになったという。いつかIC王者になりたかったとしつつ、選手を続けるより強い足跡を残せると話す。苦しい時期を支えてくれた人たちの存在が大きかったそうだ。", "sp": "コーリー・グレイブス", "d": "2019-05-07", "how": "リリアン・ガルシアの番組（Chasing Glory）で（字幕を全文確認）", "art": "ext-LWXN6y6Kiug", "src": [["番組のYouTube（1:20:00〜）", "https://www.youtube.com/watch?v=LWXN6y6Kiug&t=4800s"]]}]);
  ARTICLES.push({ id: "ext-LWXN6y6Kiug", d: "2019-05-07", show: "ext", who: ["Corey Graves"], t: "コーリー・グレイブスの回　断たれた夢から解説席へ", lead: "リリアン・ガルシアの番組（Chasing Glory）に出た約86分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Corey Graves"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-LWXN6y6Kiug").map((x) => [x.t, x.b, x.sp])), open: ["インターネットで広まった私生活の話題は、本人が事実と違うと話しているので詳しくは載せていない。", "スポンサーの宣伝部分は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=LWXN6y6Kiug"]] });
  if (!ROSTER.find((r) => r[1] === "Candice LeRae")) ROSTER.push(["キャンディス・レラエ", "Candice LeRae", "lg", "NXTの人気女子選手", "", "", ""]);
  if (!PROFILES["Candice LeRae"]) PROFILES["Candice LeRae"] = { lead: "カリフォルニア育ちのおてんば娘で、ディズニーとマッチョマンが大好き。姪っ子たちに背中を押され、夢だったプロレスの道を貫いてきた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Candice%20LeRae"]], moves: [], facts: [] };
  if (PROFILES["Candice LeRae"]._weak) { PROFILES["Candice LeRae"].lead = "カリフォルニア育ちのおてんば娘で、ディズニーとマッチョマンが大好き。姪っ子たちに背中を押され、夢だったプロレスの道を貫いてきた。"; delete PROFILES["Candice LeRae"]._weak; }
  PROFILES["Candice LeRae"].facts.push(...[{"cat": "リングの話", "t": "カナダ出身の設定は実は作り物", "b": "ウィニペグ生まれとされているが、本当はカリフォルニア州リバーサイド生まれだという。デビュー当初、悪役が足りないという理由で「カナダ出身」の設定にされたそうだ。好きな選手にウィニペグ出身が多かったので、その街を選んだと話す。ネットの情報を直したくても直せずにいるという。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（5:46〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=346s"]]}, {"cat": "家族", "t": "家族はミネソタ系と思っていたが違った", "b": "母方の家族はミネソタ出身と聞いていて、カナダの血が入っているかもと期待したという。しかし遺伝子検査の結果はまったく違ったと笑って話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（8:14〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=494s"]]}, {"cat": "暮らし", "t": "結婚式はディズニーランドで挙げた", "b": "夫のジョニー・ガルガノとはディズニーのリゾートで式を挙げたと話す。本当はスペインのマドリードで挙げたかったが、事情で実現しなかったそうだ。人数は45人ほどに絞ったという。子どもの頃からの夢がディズニーだったと語る。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（9:01〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=541s"]]}, {"cat": "暮らし", "t": "夫はテーマパーク未体験だった", "b": "ジョニーは結婚前に本格的なテーマパークへ行ったことがなく、キャンディスが連れて行ったそうだ。式の準備では、夫が「どうでもいい」と言ったら本人が嫌いなものを選ぶと宣言したという。夫が選んだのは花だけで、準備はとても楽だったと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（11:29〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=689s"]]}, {"cat": "家族", "t": "父の胸の花は白バラを赤く塗ったもの", "b": "大好きな映画『不思議の国のアリス』にちなみ、父のブートニアを赤く塗った白バラにしてほしいと頼んだという。ブーケにはミッキーの隠しモチーフもたくさん入れてもらったそうだ。とても良い経験だったので、また挙げたいと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（13:06〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=786s"]]}, {"cat": "暮らし", "t": "結婚10周年にマドリードで誓い直す予定", "b": "マドリードで育った経験があり、そこで二人きりで誓いを新たにしたいと考えているそうだ。ただ夫は派手好きで、もっと大きな部屋にしたがるという。出会って10年というのが節目だと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（14:45〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=885s"]]}, {"cat": "好きなもの", "t": "入場曲はマッチョマンの流れで", "b": "結婚式では、新婦の自分がマッチョマン・ランディ・サベージの入場に合わせて入ったそうだ。介添えの親族や友人はピアノ版のレッスルマニアのテーマで入場した。新郎のジョニーは自分の入場曲で踊りながら登場し、会場がぽかんとしたという。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（15:37〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=937s"]]}, {"cat": "暮らし", "t": "夫は酒を飲まず、二人とも内向的", "b": "ジョニーはお酒を飲まない生き方をしており、新婚旅行も飲み会の多い場所は避けたそうだ。二人とも根は内向的で、知らない人に話しかけられるのは苦手だと話す。本人は結婚式のあと2週間ほどでオーランドへ引っ越したという。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（20:30〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1230s"]]}, {"cat": "家族", "t": "おてんばな少女で、兄と弟がいた", "b": "男の兄弟2人に囲まれて育ち、母も叔母もいわゆる女の子らしいタイプではなかったという。草野球のリトルリーグに入り、ソフトボールではなく野球を選んだ。父は兄弟と同じ練習をさせてくれたと話す。いとこたちとも、あらゆるスポーツで遊んだそうだ。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（22:06〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1326s"]]}, {"cat": "リングに来るまで", "t": "学校ではプロレス好きを隠していた", "b": "スポーツが得意なことも、プロレスが好きなことも学校ではからかわれたため、隠していたという。学校の女友達の前では体育でも本気を出さなかったそうだ。家では木登りや自転車も楽しむ「家では男の子、学校では女の子」の二重生活だったと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（22:54〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1374s"]]}, {"cat": "リングに来るまで", "t": "姪の誕生で夢をあきらめないと決めた", "b": "21歳の頃、最初の姪が生まれたことが転機になったという。夜中にベッドへ入ってくるほど慕ってくれる姪を見て、自分も最高の自分でいなければと思ったそうだ。諦めたら姪に何を教えることになるのか、と考えて子どもの頃の夢に挑み直したと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（23:44〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1424s"]]}, {"cat": "家族", "t": "ロイヤルランブルの出場は家族に内緒で準備", "b": "2019年のロイヤルランブルに出ることを、両親には先に伝えて来てもらったという。姪たちには秘密にしていた。義姉が入場の瞬間を撮影しており、姪が驚く姿の映像を見て感極まったそうだ。普段は人前で泣かない性格だと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（25:18〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1518s"]]}, {"cat": "リングの話", "t": "男女混合の試合は賛否があると承知", "b": "インディー時代は男性選手とも闘い、「男女混合の旗手」のような存在だったという。会社がそうした暴力的な見せ方を推せないことも理解していると話す。一方で、その闘い方に励まされたと言う観客が男女問わずいて、意味のある活動だったと感じているそうだ。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（27:44〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1664s"]]}, {"cat": "リングの話", "t": "姪が学校で「男の子にも勝てる」と言った", "b": "野球をしている姪が、男の子にからかわれたとき「キャンディスの姪だから負けない」と返した話を紹介している。性別で自分を限るべきではないと強く思うそうだ。ダメだと言われるほど言い返さずに実力で見せる頑固な性格だと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（29:19〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1759s"]]}, {"cat": "リングに来るまで", "t": "練習で手加減されるのが嫌だった", "b": "道場では女性が少なく、男の子たちと練習することが多かったという。「女の子だから軽めに」と言われると、見下されたようで本気で悔しかったそうだ。わざと厳しく当たる人もいたが、痛がるそぶりは見せずに耐えたと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（30:55〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=1855s"]]}, {"cat": "体のこと", "t": "中学時代は体重40キロほどで小柄", "b": "中学の頃は80ポンド(約36キロ)ほどしかなく、重い教科書を背負って歩いていたという。大人っぽい服と厚底の靴に挑戦したら、坂で転んでひざをすりむいたと笑って話す。そこから、自分に合わない服もあると受け入れたそうだ。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（36:33〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=2193s"]]}, {"cat": "体のこと", "t": "体の成長が遅く、劣等感があった", "b": "高校生になっても成長が遅く、同級生に比べて幼く見えるのが悩みだったという。ブラスバンド部でフルートを吹き、部の男子に片思いしたが妹扱いされたそうだ。今は30代がいちばん充実していると話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（41:14〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=2474s"]]}, {"cat": "暮らし", "t": "20代は遠回りでも今は納得している", "b": "20代は迷いが多く、夢の場所には遅すぎたのではと不安だったという。いま振り返ると、すべてが必要な時間だったと感じているそうだ。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（43:40〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=2620s"]]}, {"cat": "体のこと", "t": "お酒に頼りかけた時期を自分で断ち切った", "b": "交際していた相手の影響で、ベッド脇にお酒を置くほど依存しかけた時期があったという。これは問題だと気づき、自分で止めたそうだ。姪たちのためにも良い姿でいたいと思い、一緒に過ごす時間を増やしたと話す。今は飲む量を自分で決められるという。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（44:32〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=2672s"]]}, {"cat": "暮らし", "t": "夫といると一番自分らしくいられる", "b": "ジョニーは飲まず、いつも冷静でいてくれるため、自分の限度を守りやすいと話す。これまでの人生で一番自分らしくいられる関係だという。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（54:03〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=3243s"]]}, {"cat": "リングの話", "t": "NXTがUSAネットワークで放送される喜び", "b": "子どもの頃から見てきた団体のテレビ放送に出られることに驚いているという。ただ、新しい空気のNXTの一員であること自体がさらに特別だと語る。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（54:50〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=3290s"]]}, {"cat": "暮らし", "t": "SNSを見る時間を減らしている", "b": "自分のコントロールできないことは受け入れるようにしているという。インター・ジェンダーの試合を通じて、全員に好かれなくていいと学んだそうだ。リングではファンのために全力を出すだけだと話す。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で（字幕を全文確認）", "art": "ext-sYVk7vbRMLU", "src": [["番組のYouTube（56:31〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=3391s"]]}]);
  if (PROFILES["Johnny Gargano"]) PROFILES["Johnny Gargano"].facts.push({"cat": "暮らし", "t": "ジョニー・ガルガノはショーマン気質", "b": "ジョニーは派手な演出が好きで、役所での簡素な式など考えられないタイプだと、キャンディスが話している。実はテーマパークに行ったことがなく、パワーレンジャーなどが好きな子どもっぽい面もあるそうだ。", "sp": "キャンディス・レラエ", "d": "2019-09-19", "how": "リリアン・ガルシアの番組で、キャンディス・レラエの話（字幕を全文確認）", "src": [["番組のYouTube（10:41〜）", "https://www.youtube.com/watch?v=sYVk7vbRMLU&t=641s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-sYVk7vbRMLU", d: "2019-09-19", show: "ext", who: ["Candice LeRae"], t: "キャンディス・レラエの回　男の子に混ざって育った少女の物語", lead: "リリアン・ガルシアの番組に出た約61分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Candice LeRae"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-sYVk7vbRMLU").map((x) => [x.t, x.b, x.sp])), open: ["信仰・宗教に関する発言は特になかった。", "元交際相手との出来事のうち、重い場面の詳細は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=sYVk7vbRMLU"]] });
  if (!ROSTER.find((r) => r[1] === "Dean Ambrose")) ROSTER.push(["ディーン・アンブローズ", "Dean Ambrose", "gn", "元シールド。現在は他団体", "", "", ""]);
  if (!PROFILES["Dean Ambrose"]) PROFILES["Dean Ambrose"] = { lead: "元シールドとして活躍し、自らWWEを離れたモクスリー。去った経緯と、離れた後に抱く気持ちを淡々と語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dean%20Ambrose"]], moves: [], facts: [] };
  if (PROFILES["Dean Ambrose"]._weak) { PROFILES["Dean Ambrose"].lead = "元シールドとして活躍し、自らWWEを離れたモクスリー。去った経緯と、離れた後に抱く気持ちを淡々と語った。"; delete PROFILES["Dean Ambrose"]._weak; }
  PROFILES["Dean Ambrose"].facts.push(...[{"cat": "退団の理由", "t": "他団体の存在を知る前に退団を決めた", "b": "モクスリーは、WWEを離れると決めた時点では、現在の移籍先はまだ存在すらしていなかったと話す。その後に話が持ち上がり、うまく噛み合ったのだという。離れた後の半年は、これ以上ないほど順調だと振り返っている。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=50s"]]}, {"cat": "退団の理由", "t": "創作面の自由を求めていた", "b": "聞き手は、以前のポッドキャストで語っていた「表現者でありたい」という思いに触れた。モクスリーは今、自分の見せ方を自分で決められる環境にいると話す。それが大きな重荷が下りたような感覚だという。上の顔色をうかがう必要がないことも、その理由に挙げている。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（3:14〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=194s"]]}, {"cat": "退団の理由", "t": "去った直後は沈黙を貫いた", "b": "WWEを離れた後の数か月は、何を聞かれても黙っていたという。その間も噂は広がり続けた。モクスリーは、出番に向けて予告映像づくりに力を入れ、噂をさらにあおる形になったと話している。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（12:44〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=764s"]]}, {"cat": "退団の理由", "t": "シールドの人間は去らないと思われていた", "b": "モクスリーは、噂が飛び交っても、実際に目にするまでは誰も信じなかっただろうと話す。特にシールドの面々は去らない存在だと思われていたからだという。予告映像が下地になったので、姿を見せた瞬間に観客は状況を理解したそうだ。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（13:32〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=812s"]]}, {"cat": "退団の理由", "t": "苦しかった数か月を経て迎えた瞬間", "b": "退団後は一か月ほど身を隠し、契約の終わりまで続いた期間も含めて、奇妙な時期だったという。その末に観客が自分の名を叫んだとき、深い満足を覚えたと話す。観客の歓声そのものより、それまでの数か月がどれほどつらかったかが理由だと説明している。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（14:17〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=857s"]]}, {"cat": "退団の理由", "t": "見返してやりたい気持ちはないという", "b": "聞き手に、会長に「今の気分はどうだ」と言いたくならないかと問われた。モクスリーは、見返したいという動機はないと答える。向こうでは良い時間を過ごせたし、今さら証明すべきことはないと話す。会社のすることには関心がなく、幸運を祈る程度だという。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（15:03〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=903s"]]}, {"cat": "WWEでの日々", "t": "WWEでの日々には満足している", "b": "モクスリーは、WWEで素晴らしい期間を過ごせたと振り返る。恨みを抱えると後ろ向きになるだけだと考え、今は新しいものを生み出す方にエネルギーを向けているという。普通の仕事をせずに夢を生きられていることに感謝していると話す。", "sp": "ディーン・アンブローズ", "d": "2019-11-27", "how": "CBSスポーツの番組 State of Combatで（字幕を全文確認）", "art": "ext-JIN_pmWL5Zg", "src": [["番組のYouTube（15:51〜）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg&t=951s"]]}]);
  ARTICLES.push({ id: "ext-JIN_pmWL5Zg", d: "2019-11-27", show: "ext", who: ["Dean Ambrose"], t: "ディーン・アンブローズの回　WWEを離れて半年", lead: "CBSスポーツの番組 State of Combatに出た約23分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Dean Ambrose"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-JIN_pmWL5Zg").map((x) => [x.t, x.b, x.sp])), open: ["公開しているのは、WWEを離れた経緯とWWEでの日々の話だけに絞った。", "自動字幕の乱れで、契約の終わりに触れた箇所の言葉は聞き取れない部分があり、要点のみ書いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=JIN_pmWL5Zg"]] });
  if (!ROSTER.find((r) => r[1] === "Haku")) ROSTER.push(["ハク", "Haku", "lg", "トンガ出身の伝説的レスラー", "", "", ""]);
  if (!PROFILES["Haku"]) PROFILES["Haku"] = { lead: "トンガから相撲を目指して日本に渡り、世界中のリングを回った伝説の男。恐れられる腕っぷしとは裏腹に、言葉と文化を学ぶことを楽しみ、出会った人への感謝を忘れない。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Haku"]], moves: [], facts: [] };
  if (PROFILES["Haku"]._weak) { PROFILES["Haku"].lead = "トンガから相撲を目指して日本に渡り、世界中のリングを回った伝説の男。恐れられる腕っぷしとは裏腹に、言葉と文化を学ぶことを楽しみ、出会った人への感謝を忘れない。"; delete PROFILES["Haku"]._weak; }
  PROFILES["Haku"].facts.push(...[{"cat": "リングの話", "t": "アンドレとのタッグ", "b": "アンドレ・ザ・ジャイアントとタッグ王者になったのは光栄だったという。飛行機では隣の席で窮屈だったそうだ。アンドレは食べるのも飲むのも好きで、食後には2種類の酒を混ぜた一杯を勧めてきたと話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（1:42〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=102s"]]}, {"cat": "暮らし", "t": "言葉と文化を学ぶのが楽しい", "b": "英語もまだ勉強中だったころ、フランス語圏のモントリオールに行くことになり、周りには「嫌な思いをする」と脅されたという。でも言葉や文化を学ぶのは楽しく、妻に「ここに住もう」と言ったほど気に入ったそうだ。若いころはバーでけんかをするなど無茶もしたと笑う。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（4:57〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=297s"]]}, {"cat": "リングの話", "t": "プエルトリコでの初めての主役", "b": "プエルトリコでは、スペイン語が話せないのに見た目が地元の人に似ていて、憎まれながらも尊敬されたという。ダスティ・ローデスの紹介で行ったそこで、初めてメインの扱いを受けたそうだ。言葉が分からなくても、懸命に働けば受け入れられると話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（12:25〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=745s"]]}, {"cat": "リングの話", "t": "日本で付き人を務めたハーリー・レイス", "b": "日本では若手として先輩の世話を学んだという。ジャイアント馬場に英語を覚えるよう言われ、ハーリー・レイスの付き人を任されたそうだ。無口でたばこをよく吸うレイスを毎朝ロビーに呼びに行くうちに気に入られ、のちにWWFで「キング」の役を継いだときもレイスの許しを得たと話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（15:38〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=938s"]]}, {"cat": "信仰", "t": "毎日神に感謝", "b": "たくさんの恵みを受けてきたので、毎日神に感謝しているという。新しい団体が増えることも、レスラーに仕事が生まれるので良いことだと話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（17:13〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1033s"]]}, {"cat": "暮らし", "t": "ホーガンの助言でフロリダに家", "b": "WWFの会議でハルク・ホーガンが「フロリダは今が家の買い時だ」と勧め、その言葉通りフロリダに家を買ったという。ホーガンはクリスマスパーティーに皆を招いてくれたそうだ。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（18:00〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1080s"]]}, {"cat": "家族", "t": "物静かな父", "b": "静かな人ほど怖いもので、自分の父もそうだったという。バーバリアンが自分を「自分より強い」と言うのは謙遜だと話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（22:00〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1320s"]]}, {"cat": "リングに来るまで", "t": "相撲を目指してトンガを出た", "b": "同郷のバーバリアン（シオネ）とはトンガの同じ高校の先輩後輩で、2人とも相撲の稽古をして島を出たのだという。6人で日本に渡り、自分は一番年下だったそうだ。バーバリアンは体の芯の強さが別格だったと振り返る。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（22:47〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1367s"]]}, {"cat": "家族", "t": "息子たちもプロレスラー", "b": "息子のタマ・トンガたちも新日本プロレスで活躍していて、とても誇らしいという。末の息子も修行中で、娘の夫もプロレスラーだそうだ。子どもたちには自分を超えてほしいと話す。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（23:37〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1417s"]]}, {"cat": "好きなもの", "t": "ザ・ロックから贈られたトラック", "b": "財団の活動のためにサインをもらいに行ったとき、ザ・ロック（ドウェイン・ジョンソン）に車を見せられ、感想を言うと「それはあなたのだ」とトラックを贈られたという。母親と2人で驚いて立ち尽くしたそうだ。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（29:24〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1764s"]]}, {"cat": "リングの話", "t": "ロッキー・ジョンソンは恩人", "b": "17〜18歳のころ、日本から来たばかりの自分に控室で最初に声をかけてくれたのがロッキー・ジョンソンだったという。義父のピーター・メイビアと共に面倒を見てくれ、家族同然になったそうだ。", "sp": "ハク", "d": "2020-03-13", "how": "ハンニバルTV（カナダのプロレス番組）で（字幕を全文確認）", "art": "ext-GlckWtbOv3s", "src": [["番組のYouTube（31:46〜）", "https://www.youtube.com/watch?v=GlckWtbOv3s&t=1906s"]]}]);
  ARTICLES.push({ id: "ext-GlckWtbOv3s", d: "2020-03-13", show: "ext", who: ["Haku"], t: "ハクの回　トンガから日本、そして世界へ", lead: "ハンニバルTV（カナダのプロレス番組）に出た約45分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Haku"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GlckWtbOv3s").map((x) => [x.t, x.b, x.sp])), open: ["ブルーザー・ブロディの死などをめぐる噂話は、本人が「聞いた話」と前置きしているので載せていない。", "後半は試合映像で、話の部分ではない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GlckWtbOv3s"]] });
  if (!ROSTER.find((r) => r[1] === "Berto")) ROSTER.push(["ベルト", "Berto", "lg", "", "", "", ""]);
  if (!PROFILES["Berto"]) PROFILES["Berto"] = { lead: "ファンの質問に答えたベルト（当時の名前はウンベルト・カリージョ）。サッカーのゴールキーパーに憧れた少年時代や、RAWデビューの夜の緊張を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Berto"]], moves: [], facts: [] };
  if (PROFILES["Berto"].lead === "ファンの質問に答えたベルト（当時の名前はウンベルト・カリージョ）。サッカーのゴールキーパーに憧れた少年時代や、RAWデビューの夜の緊張を語る。") PROFILES["Berto"]._weak = 1;
  PROFILES["Berto"].facts.push(...[{"cat": "リングに来るまで", "t": "モンテレイ出身、レスラーでなければサッカー", "b": "メキシコ北部のヌエボ・レオン州モンテレイ出身だと、ベルトは誇らしげに話す。レスラーにならなかったら、憧れていたサッカーの道、特にゴールキーパーを選んでいただろうという。", "sp": "ベルト", "d": "2020-03-20", "how": "本人のYouTubeチャンネルで（字幕を全文確認）", "art": "ext-O_ye_p2fetY", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=O_ye_p2fetY&t=50s"]]}, {"cat": "リングの話", "t": "RAWデビューの夜は緊張で食事ものどを通らず", "b": "ドラフトでRAW行きを知ったのは、自宅で妻と番組を見ていたときだったと、ベルトは話す。2日後、移動中に「今夜セス・ロリンズとデビュー」と告げられ、緊張でその日は食事もできなかったという。試合後、ブーツを脱ぎながら「これは本当なのか」と何秒も固まったそうだ。", "sp": "ベルト", "d": "2020-03-20", "how": "本人のYouTubeチャンネルで（字幕を全文確認）", "art": "ext-O_ye_p2fetY", "src": [["番組のYouTube（2:32〜）", "https://www.youtube.com/watch?v=O_ye_p2fetY&t=152s"]]}, {"cat": "好きなもの", "t": "今の好物は寿司", "b": "好きな食べ物は時期によって変わるが、今は寿司が大好きでたまらないと、ベルトは話す。映画『シュレック』の悪役ファークアード卿のものまねを披露している。", "sp": "ベルト", "d": "2020-03-20", "how": "本人のYouTubeチャンネルで（字幕を全文確認）", "art": "ext-O_ye_p2fetY", "src": [["番組のYouTube（5:51〜）", "https://www.youtube.com/watch?v=O_ye_p2fetY&t=351s"]]}, {"cat": "暮らし", "t": "2020年の願いはみんなの健康", "b": "新型コロナが広がり始めた2020年、一番の願いは家族や妻、知り合い、世界中の人の健康だと、ベルトは話す。仕事はその次で、何より家族と健康が大事だという。", "sp": "ベルト", "d": "2020-03-20", "how": "本人のYouTubeチャンネルで（字幕を全文確認）", "art": "ext-O_ye_p2fetY", "src": [["番組のYouTube（9:10〜）", "https://www.youtube.com/watch?v=O_ye_p2fetY&t=550s"]]}, {"cat": "リングに来るまで", "t": "14歳で練習を始め、18歳でデビュー", "b": "14歳ごろから練習を始め、18歳でプロデビューしたと、ベルトは話す。", "sp": "ベルト", "d": "2020-03-20", "how": "本人のYouTubeチャンネルで（字幕を全文確認）", "art": "ext-O_ye_p2fetY", "src": [["番組のYouTube（10:46〜）", "https://www.youtube.com/watch?v=O_ye_p2fetY&t=646s"]]}]);
  ARTICLES.push({ id: "ext-O_ye_p2fetY", d: "2020-03-20", show: "ext", who: ["Berto"], t: "ベルトの回　ファンの質問に答える", lead: "本人のYouTubeチャンネルに出た約12分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Berto"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-O_ye_p2fetY").map((x) => [x.t, x.b, x.sp])), open: ["自動字幕の崩れが大きく、聞き取れない質問は載せていない。", "妻の名前は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=O_ye_p2fetY"]] });
