  if (!PROFILES["Piper Niven"]) PROFILES["Piper Niven"] = { lead: "自信のなさを抱えていた自分を、リング上の「強い自分」で少しずつ変えてきたパイパー・ニーヴン。恐竜とディズニー、ゲームを愛するスコットランドのレスラー。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Piper%20Niven"]], moves: [], facts: [] };
  if (PROFILES["Piper Niven"]._weak) { PROFILES["Piper Niven"].lead = "自信のなさを抱えていた自分を、リング上の「強い自分」で少しずつ変えてきたパイパー・ニーヴン。恐竜とディズニー、ゲームを愛するスコットランドのレスラー。"; delete PROFILES["Piper Niven"]._weak; }
  PROFILES["Piper Niven"].facts.push(...[{"cat": "暮らし", "t": "外出自粛中はヨガと瞑想、田舎の散歩", "b": "田舎に住んでいて、婚約者と犬と一緒に田園を散歩して過ごしていると、パイパーは話す。初めてヨガに挑戦し、甘く見ていたらとてもきつかったという。瞑想も楽しんでいるが、気分の浮き沈みが激しい日々だったそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（0:54〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=54s"]]}, {"cat": "好きなもの", "t": "ゲームで田舎道を爆走してストレス発散", "b": "レースゲーム『Forza Horizon 4』で田舎道を猛スピードで走るのが妙に癒やしになると、パイパーは笑う。『レッド・デッド』や、選択で話が変わるバットマンのゲーム、『ウルフ・アマング・アス』も遊んだという。物語を選んで進める形は、子どもの頃に読んだ分岐する本のようで好きだそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（1:44〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=104s"]]}, {"cat": "好きなもの", "t": "ユニコーン人気への反発から恐竜好きに", "b": "恐竜好きは少しずつ強くなったものだと、パイパーは話す。ユニコーンが大流行したとき、流行り物にはあえて乗らない性分から「歯もないし危なくもない」と思い、恐竜の方を推すようになったという。恐竜の小物やおもちゃをたくさん持ち、恐竜の服も着ているそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（3:26〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=206s"]]}, {"cat": "リングに来るまで", "t": "デビュー当初は人の目も見られなかった", "b": "レスリングを始めた頃はまったく自信がなく、人の目を見ることもできなかったと、パイパーは振り返る。つらい人間関係から抜け出したばかりで、自己評価がとても低かったという。レスリングは自信を取り戻すための手段だったそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（5:07〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=307s"]]}, {"cat": "リングの話", "t": "「強いのはバイパー」と考えて人前に立った", "b": "観客の前にタイツ姿で立つのが怖くてたまらず、「自分は自信がなくても、リングの上のバイパーは自信がある」と考えるようにしたと、パイパーは話す。バイパーは着たい物を着て、周りの目を気にしない存在だったという。演じるうちに本人の自信も育ち、今はリング上の自分と素の自分の差がほとんどないそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（5:54〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=354s"]]}, {"cat": "リングの話", "t": "日本遠征で生まれた「メガトン・バービー」", "b": "日本遠征の2回目のとき、怒った大柄な役を求められたが、3か月ほどのうちに「本当はそういうタイプじゃない」と周りに見抜かれたと、パイパーは笑う。日本での異名「メガトン」に引っかけて、当時の仲間が「メガトン・バービー」という呼び名を考えたという。そこからピンクやキラキラの衣装で自分らしく戦うようになり、日本でも人気が出たそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（7:31〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=451s"]]}, {"cat": "体のこと", "t": "「プラスサイズのレスラー」を自分から名乗る", "b": "SNSのプロフィールに自らプラスサイズのレスラーと書いているのは、体型を悪く言われ続けてきたからこそ、それを自分の看板にしたかったからだと、パイパーは話す。長い間、大きな体を恥ずかしく思っていた時期もあったという。女子プロレスの見られ方がこの10年で大きく変わったとも感じているそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（8:18〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=498s"]]}, {"cat": "リングの話", "t": "体型をめぐる失礼な質問には答えなかった", "b": "ある取材で「体の大きい人にはプロレスは難しいのでは」という質問が届き、ばかげていると感じたと、パイパーは振り返る。プロレスは相手を3秒押さえ込む競技で、それなら体の大きい方が有利だろうと考えたという。その取材には返事をしなかったそうだ。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（9:54〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=594s"]]}, {"cat": "好きなもの", "t": "一番好きなディズニープリンセスはポカホンタス", "b": "見た目からアリエルだと思われがちだが、一番好きなのはポカホンタスだと、パイパーは話す。自然や日差しを眺めてうれしくなるような性格だからかもしれないという。『リロ・アンド・スティッチ』の姉ナニは苦労して妹を育てているのに評価されていない、と熱く語っている。", "sp": "パイパー・ニーヴン", "d": "2020-06-30", "how": "アリシア・アトゥの番組で（字幕を全文確認）", "art": "ext-lL2WIPJDJUY", "src": [["番組のYouTube（11:34〜）", "https://www.youtube.com/watch?v=lL2WIPJDJUY&t=694s"]]}]);
  ARTICLES.push({ id: "ext-lL2WIPJDJUY", d: "2020-06-30", show: "ext", who: ["Piper Niven"], t: "パイパー・ニーヴンの回　自信をくれたリングの自分、恐竜と『リロ・アンド・スティッチ』", lead: "アリシア・アトゥの番組に出た約14分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Piper Niven"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-lL2WIPJDJUY").map((x) => [x.t, x.b, x.sp])), open: ["婚約者の名前や、過去の人間関係の詳しい話は載せていない。", "自動字幕で崩れている箇所（日本での異名の由来など）は、聞き取れた範囲で要約した。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=lL2WIPJDJUY"]] });
  if (!ROSTER.find((r) => r[1] === "Cruz Del Toro")) ROSTER.push(["クルス・デル・トロ", "Cruz Del Toro", "lg", "元ラウル・メンドーサ", "", "", ""]);
  if (!PROFILES["Cruz Del Toro"]) PROFILES["Cruz Del Toro"] = { lead: "メキシコ・ベラクルス州の町で育ち、10歳でリングに通い始めたという。仮面を脱ぎ、日本遠征と世界最大級の団体への挑戦を重ねた歩みを、仲間への感謝とともに語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cruz%20Del%20Toro"]], moves: [], facts: [] };
  if (PROFILES["Cruz Del Toro"]._weak) { PROFILES["Cruz Del Toro"].lead = "メキシコ・ベラクルス州の町で育ち、10歳でリングに通い始めたという。仮面を脱ぎ、日本遠征と世界最大級の団体への挑戦を重ねた歩みを、仲間への感謝とともに語った。"; delete PROFILES["Cruz Del Toro"]._weak; }
  PROFILES["Cruz Del Toro"].facts.push(...[{"cat": "家族", "t": "学校でよく呼び出されたやんちゃな子", "b": "子どものころは普通の暮らしだったが、とにかくいたずら好きで、学校の問題でよく母が呼び出されたという。幼稚園では、仲間と一緒に丸いテーブルを次々に飛び移って叱られた思い出を話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（8:34〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=514s"]]}, {"cat": "好きなもの", "t": "幼いころから大のプロレス好き", "b": "テレビでプロレスを見て育ち、覆面レスラーの人形やぬいぐるみをバケツ2〜3杯ぶん持っていたという。将来の夢を聞かれるたびにレスラーと答え、事務所勤めや医者になる自分は想像できなかったと話す。代わりの道は考えたことがなかったそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（9:27〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=567s"]]}, {"cat": "家族", "t": "両親は離婚、でも二人ともそばにいた", "b": "両親は離婚していたが、どちらとも変わらず一緒に過ごせたので、幼少期は楽しかったと話す。母には4人、父には5人の子どもがいるという。ケーブルテレビがなかった家で育ったことも笑い話にしている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（11:08〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=668s"]]}, {"cat": "リングに来るまで", "t": "家族で最初のレスラー", "b": "家族にレスラーはおらず、自分が最初だという。住んでいた地区には地元で人気のあった覆面レスラー一家が暮らしており、父から聞いた話や、その人たちの存在に憧れが育ったと語る。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（12:48〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=768s"]]}, {"cat": "リングに来るまで", "t": "10歳で練習開始、15歳でデビュー", "b": "メキシコでは子どもが8〜10歳で練習を始めることも珍しくなく、自身も10歳で地元のレスラーのもとへ通い始めたという。当時リングにいる子どもは自分だけで、ほかは全員大人だった。デビューは15歳のときだったそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（14:28〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=868s"]]}, {"cat": "体のこと", "t": "川での大けがでデビューが1年遅れた", "b": "14歳のとき、川に飛び込んで底の石に頭を打ち、血だらけになって病院に運ばれたという。そのけがが原因で、予定していたデビューが1年延びたと笑って振り返っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（14:28〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=868s"]]}, {"cat": "リングに来るまで", "t": "朝7時の練習に炊き込みご飯とコーヒーを差し入れた師", "b": "首都での練習の先生は、朝7時の練習の前に、肉と野菜入りの炊き込みご飯と大鍋のコーヒーを用意して生徒に振る舞ってくれたという。生徒たちもライバルというより兄弟のように仲が良く、その時間を今も温かい気持ちで思い出すと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（25:11〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=1511s"]]}, {"cat": "リングに来るまで", "t": "プエブラと首都を往復する猛練習の日々", "b": "17〜18歳のころは、プエブラに住みながら首都のジムにも通い、週に何度も朝から晩まで練習していたという。あとで考えると相当無茶な生活だったが、うまくなりたい一心で乗り切ったそうだ。体力も技もしだいに伸びていくのが分かったと話す。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（27:50〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=1670s"]]}, {"cat": "リングの話", "t": "テスト出場の試合で相方の大技事故", "b": "テレビ収録のテスト試合で、組んでいた仲間が高い所から飛ぶ技を出し、そのまま着地で脚を痛めたという。本人は動けたが、言葉が通じにくい中で医師とのやりとりがうまくいかず、試合が止められたと話す。この出来事を、思い込みと連絡の行き違いが重なった一件として振り返っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（30:20〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=1820s"]]}, {"cat": "リングの話", "t": "若い選手中心の団体で新しい試合スタイルを学ぶ", "b": "大手団体のテストがうまくいかない中、仲間に誘われて若手中心の団体に参加したという。日本やアメリカのプロレスの映像を見て、従来のメキシコのスタイルとは違う「空中も打撃も混ぜた」試合を作る世代だったと話す。自分たちはその第一世代で、今のインディーはほぼ皆そのスタイルだと語っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（40:04〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=2404s"]]}, {"cat": "リングの話", "t": "覆面が合わず、2012年に素顔になった", "b": "覆面をかぶっての試合では、自分の気持ちが客席に届かないと感じていたという。練習ではバンダナを巻いていたところ、仲間の選手から「素顔のほうが似合う」と言われて悩み、2012年の終わりごろ、地方巡業の最終戦で覆面を脱いだそうだ。素顔になってから自分らしさをつかみ、チャンスが増えたと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（43:20〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=2600s"]]}, {"cat": "リングの話", "t": "5回目のテストで即デビュー", "b": "5回目のテストには朝10時の集合に1時間半遅刻して到着したという。慌てて着替えて組んだ相手とは息が合い、ビンタを打ち合う激しい試合になって大いに褒められた。その日の夜、会場でそのまま大手団体のデビューを告げられ、メキシコのことわざ「5回目は悪くない」を引いて祝われたそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（50:40〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=3040s"]]}, {"cat": "リングに来るまで", "t": "日本の団体の合宿に、迷った末に参加", "b": "2014年、仲間のレスラーが日本の団体に送り出す選手を選ぶ合宿を開いたという。大手団体からは仕事がほとんど来ない時期で、行くかどうか迷ったが、当日の朝に決めて会場へ向かった。日本で戦うのは昔からの夢だったと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（55:33〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=3333s"]]}, {"cat": "リングに来るまで", "t": "6人の中から3人目の枠をつかんだ", "b": "合宿の最終日は6人が戦って審査員が選ぶ形で、一度は3人目に落ちたと思って悔しさとあきらめで更衣室に戻りかけたそうだ。ところがその後に名前を呼ばれ、仲間に抱きしめられて祝福されたという。家族もいないのに夢をかなえられたことが信じられなかったと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:00:27〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=3627s"]]}, {"cat": "リングに来るまで", "t": "日本の団体で3か月、小川良成との友情", "b": "日本では寮に住み、最初の2週間はきつい練習で筋肉痛が続いたという。後楽園ホールで戦い、森嶋猛や小川良成ら先輩とも親しくなり、特に小川とは友人になったと語る。出発の一か月前に足の甲を切って痛めたまま行ったが、よい経験になったと振り返っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:03:35〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=3815s"]]}, {"cat": "リングに来るまで", "t": "日本で学んだ「最後まで折れない」姿勢", "b": "日本の選手は練習も試合も徹底して真面目で、遊びに行った翌朝でも練習は必ず行うと話している。「最後まであきらめない」精神は、試合だけでなく日常にも役立っているそうだ。リングには左側から入るなど、世界の標準を覚えた経験も今に生きていると語っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:10:17〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=4217s"]]}, {"cat": "暮らし", "t": "帰国後は半年、地元で休んでいた", "b": "3か月の日本遠征を終えて帰国したが、団体の体制が変わって再び日本へは戻れなかったという。メキシコ国内の別の団体で戦う道に切り替えたが、半年ほどは地元で試合もせず過ごした。ある日「このままでは時間がもったいない」と思い立ち、首都へ出て働き始めたそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:11:59〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=4319s"]]}, {"cat": "リングに来るまで", "t": "アメリカの大手団体からの突然の連絡", "b": "2016年、アメリカ滞在中に、現地の仲間の家でSNSのメッセージが次々届いたという。「メールアドレスを教えて」「電話番号を」と急かされ、半信半疑で友人の番号を教えると、世界最大級の団体の担当者から電話が来ていた。その場にいた仲間も驚いたそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:21:02〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=4862s"]]}, {"cat": "リングに来るまで", "t": "練習施設のプロ意識に驚いた", "b": "2016年6月、フロリダの練習施設に入ったという。駐車場所や入る入口をメールで細かく指示され、服装の決まりも伝えられるなど、すべてがきちんとしていて夢のようだったと話す。7つのリングがあり、2日目か3日目には団体の最高責任者が自ら挨拶に来て、一人ひとりと握手したそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:26:38〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=5198s"]]}, {"cat": "リングの話", "t": "大舞台の初戦はベテランとの対戦", "b": "トーナメントの初戦の相手は、長年活躍してきたブライアン・ケンドリックに決まったという。喜びと驚きが入り混じり、映像を見返すと自分でも分かるほど緊張していたそうだ。主催側の女性スタッフに「数千人の向こうで何百万人が見ている」と言われ、さらに固くなったが、客席がケンドリックの名前を叫ぶ中でも落ち着いて試合をやりきったと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:29:48〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=5388s"]]}, {"cat": "リングに来るまで", "t": "決勝は見に行けず、でもハロウィンの夜にメールが来た", "b": "トーナメントの決勝を見に行きたいと頼んだが、その時は断られたという。悔しさを抱えて仕事を続け、ハロウィンの時期にシカゴの宿でメールを確認すると、フロリダに移って育成部門に入らないかという契約のオファーだったそうだ。拒まれた後だっただけに信じられなかったと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:38:40〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=5920s"]]}, {"cat": "リングに来るまで", "t": "ビザの手続きで渡米が延び、4月9日にフロリダへ", "b": "契約の話はまとまったが、ビザの申請に時間がかかり、最初に伝えられた4月1日の到着は大きなイベントの週末と重なって延期されたという。結局フロリダに着いたのは4月9日で、翌日から練習施設に入った。最初の指導者は元レスラーのノーマン・スマイリーで、その後もテリー・テイラーら多くの指導者から学んだと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:40:12〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=6012s"]]}, {"cat": "リングの話", "t": "育成部門の初戦は親友ウンベルト・カリージョと", "b": "育成部門の番組での初試合は、メキシコの同胞でもあるウンベルト・カリージョが相手だったという。試合後は互いに感極まって抱き合い、今も仲のよい友人だと話している。この日はメキシコからの飛行機が遅れ、乗り継ぎを何度も逃しながらも、どうにか間に合って登場したそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:50:17〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=6617s"]]}, {"cat": "リングの話", "t": "伝統的なルチャの誇りを見せるユニット", "b": "2020年、ジョアキン・ワイルド、サントス・エスコバーとの3人組を結成したという。メキシコの往年の覆面レスラーが、映画やテレビにも出る「国民的スター」だったことにふれ、ただ飛び回る存在ではなく、見た目も立ち居振る舞いも堂々とした本物のルチャを見せたいと話している。まずはタッグ王座を狙い、将来は北米王座や育成部門の頂点も目指したいそうだ。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（1:56:23〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=6983s"]]}, {"cat": "リングの話", "t": "夢の対戦相手はエディ・ゲレーロ", "b": "もし過去の選手と一試合できるなら、エディ・ゲレーロと戦いたいと話している。メキシコ式、日本式、アメリカ式の戦い方をどれもこなして成功した人物だと称え、亡くなって10年以上たった今も人々を励まし続けているという。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（2:03:00〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=7380s"]]}, {"cat": "暮らし", "t": "ブラジル出身の友人たちと、言葉の壁を越えて仲良くなった", "b": "育成部門に入ったころは英語が苦手で、同じように英語に苦労していたブラジル出身の女性選手たちとスペイン語とポルトガル語を混ぜて話すうちに仲良くなったという。同じ練習クラスに通い、今も親しい友人だと話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（2:07:54〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=7674s"]]}, {"cat": "暮らし", "t": "同居した親友と、毎週大鍋のパスタ", "b": "長年の親友である同業の選手とは、苦しい時期に居場所のなかった自分を泊めてくれ、同居していた時期は週の食事を大鍋のパスタで乗り切ったという。笑い話も多いが、人生の大切な場面にいつもそばにいた「兄弟」のような存在だと語る。いつか彼も大舞台に立ってほしいと願っている。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で（字幕を全文確認）", "art": "ext-NhVF3zuT69c", "src": [["番組のYouTube（2:11:06〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=7866s"]]}]);
  if (PROFILES["Eddie Guerrero"]) PROFILES["Eddie Guerrero"].facts.push({"cat": "暮らし", "t": "異なる3つの流儀で成功した伝説", "b": "メキシコ式、日本式、アメリカ式のどれでもスターになり、団体の王者にもなった選手だと、クルス・デル・トロが話している。没後も人々を励まし続けていることを尊敬している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で、クルス・デル・トロの話（字幕を全文確認）", "src": [["番組のYouTube（2:03:00〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=7380s"]], "by": "第三者の話"});
  if (PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"].facts.push({"cat": "暮らし", "t": "「次のレイ」と呼ばれないでほしい", "b": "若い選手を「新しいレイ・ミステリオ」「新しいゲレーロ」と呼ぶ風潮に触れ、そうした比較は不要で、一人ひとりが自分らしさで評価されてほしいと、クルス・デル・トロが話している。", "sp": "クルス・デル・トロ", "d": "2020-07-26", "how": "PLL Classics（Conexão Wrestling）の番組で、クルス・デル・トロの話（字幕を全文確認）", "src": [["番組のYouTube（2:04:41〜）", "https://www.youtube.com/watch?v=NhVF3zuT69c&t=7481s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-NhVF3zuT69c", d: "2020-07-26", show: "ext", who: ["Cruz Del Toro"], t: "クルス・デル・トロの回　少年時代から日本、そして夢の団体まで", lead: "PLL Classics（Conexão Wrestling）の番組に出た約145分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Cruz Del Toro"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-NhVF3zuT69c").map((x) => [x.t, x.b, x.sp])), open: ["字幕は自動認識でスペイン語が大きく崩れており、親友や師匠、プロモーターなどの名前は確信が持てないため、一部は名前を省いている。", "同時期の仲間を紹介する場面や、番組後半のあいさつ・宣伝は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=NhVF3zuT69c"]] });
  if (!ROSTER.find((r) => r[1] === "Tama Tonga")) ROSTER.push(["タマ・トンガ", "Tama Tonga", "lg", "新日本の人気レスラー", "", "", ""]);
  if (!PROFILES["Tama Tonga"]) PROFILES["Tama Tonga"] = { lead: "一年の約8割を日本で過ごし、軍隊経験を持つタマ・トンガ。パンデミックで家族との時間を得て、ヒゲを剃り、シングルでの頂点を目指す決意を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Tama%20Tonga"]], moves: [], facts: [] };
  if (PROFILES["Tama Tonga"]._weak) { PROFILES["Tama Tonga"].lead = "一年の約8割を日本で過ごし、軍隊経験を持つタマ・トンガ。パンデミックで家族との時間を得て、ヒゲを剃り、シングルでの頂点を目指す決意を語る。"; delete PROFILES["Tama Tonga"]._weak; }
  PROFILES["Tama Tonga"].facts.push(...[{"cat": "暮らし", "t": "ヒゲを剃ったのは気分転換", "b": "パンデミックで家にいる時間が続くなか、変化が欲しくなってヒゲを剃ったとタマ・トンガは話す。レスラーとして新しい章に入るための「進化」のつもりでもあるという。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=0s"]]}, {"cat": "暮らし", "t": "一年の約8割は日本で暮らす", "b": "例年は年間の8割ほどを日本で過ごしているという。家は持たず、部屋を掃除してもらえて、シーツも替わるホテル暮らしが好きだと話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（6:23〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=383s"]]}, {"cat": "家族", "t": "娘の誕生と成長を間近で見られた", "b": "娘はパンデミックが始まった頃に生まれたそうだ。2歳の息子の最初の1年は巡業で見逃したため、今回は成長を見守れたことを恵みだと話す。オーランドの実家に滞在して両親とも過ごしている。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（7:12〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=432s"]]}, {"cat": "体のこと", "t": "自宅ではスクワットなどで体を維持", "b": "3月以降は自宅でのスクワットなどトレーニングを続け、体型を保ってきたという。ジムが再開したことにも触れ、いちばんの過ごし方は妻や子どもと過ごす時間だと話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（8:02〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=482s"]]}, {"cat": "暮らし", "t": "SNSで新しい見せ方を試す", "b": "アイデアはまず SNS に出して、ファンの反応を見ながら続けるか決めるという。壁に投げてくっつくか試すようなやり方だと笑う。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（8:50〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=530s"]]}, {"cat": "リングの話", "t": "エンツォとの件は「仕事」と割り切る", "b": "エンツォ・アモーレとは友人であり、ビジネスとして受け止めていると話す。マイクの才能は認めつつ、リングでの勝負ならいつでも受けて立つという姿勢だ。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（10:27〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=627s"]]}, {"cat": "リングの話", "t": "MSGでの乱入に本気で怒った", "b": "マディソン・スクエア・ガーデンでの出来事について、乱入した選手本人ではなく、断りもなく仕掛けた主催側に腹が立ったと話す。日本の文化では敬意が重く、他団体の舞台で勝手にやるのは失礼だという考えだ。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（11:18〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=678s"]]}, {"cat": "リングの話", "t": "ハクは優しい家庭人だが怒らせると別人", "b": "ハクはとても穏やかで愛情深い家族思いの人だが、敬意を欠く扱いをすると全く違う一面が出ると話す。あのシーンについて、本人にはあらかじめ伝えていたが、少し早く伝えすぎたかもしれないと笑う。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（17:00〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1020s"]]}, {"cat": "リングに来るまで", "t": "父はトンガ人で初めてのプロレスラー", "b": "父はトンガ出身者として初めてプロレス界に入った人だという。そのため、他の一族のように何代も遡る系図はなく、自分の家系は父のところから始まると話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（17:38〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1058s"]]}, {"cat": "暮らし", "t": "キャラと私生活は切り分けている", "b": "リング外でもリングネームで呼ばれることがあるが、ギミックを信じ込みすぎないよう、役と私生活を分けるようにしているという。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（18:26〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1106s"]]}, {"cat": "リングに来るまで", "t": "軍の任務で約8か月イラクに滞在した", "b": "軍に所属し、約8か月ほどイラクで過ごしたという。生活の規律や学びが多く、仲間もできた良い時間だったと振り返る。高校卒業後に最低2年は軍に入ればいいとも話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（20:05〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1205s"]]}, {"cat": "リングに来るまで", "t": "軍で学んだのは「適応して乗り越える」", "b": "計画どおりにいかなくても、状況に合わせて適応し乗り越えるという軍隊の考え方を、人生にもリングにも活かしていると話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（20:55〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1255s"]]}, {"cat": "暮らし", "t": "バレットクラブでお金の面は大きく変わった", "b": "ユニットのおかげで経済的に大きく変わったと、冗談めかして話す。プロレスの見方や、あるべき姿への考え方も変わったという。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（21:43〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1303s"]]}, {"cat": "リングに来るまで", "t": "軍の経験をユニットにも持ち込んだ", "b": "バレットクラブの初期は銃のモチーフなど軍隊風の見せ方で、自分の軍隊経験をかなり反映させたという。チームワークや適応力の考え方も取り入れたと話す。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（22:30〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1350s"]]}, {"cat": "リングの話", "t": "バレットクラブは外国人選手をまとめる形で始まった", "b": "会社側から、団体にいた外国人選手をまとめる話があり、最初はプリンス・デヴィットを中心にバッドラック・ファレらと組んだという。のちにカール・アンダーソンと自分が加わったと話す。名前はもともと「ブリゲード」案だったが、ファレの出身を踏まえて「クラブ」になったそうだ。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（23:20〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1400s"]]}, {"cat": "リングの話", "t": "ロゴは新日本のデザイナーが作った", "b": "ガロウズが目の下に黒を塗っていた姿と、軍隊風のスタイルが銃のデザインにつながったと話す。ロゴを変えたい気持ちもあったが、象徴的すぎて変えない方がいいと聞き、納得したようだ。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（28:14〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1694s"]]}, {"cat": "リングの話", "t": "仲間の離脱は寂しいが応援する", "b": "巡業では家族以上に長く一緒にいるため、仲間が移籍するのは寂しいが、稼げる場に進むことは喜ぶと話す。WWEに人材が流れたときは団体にとって痛手だったが、下の世代にとってはチャンスだったとも振り返る。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（31:24〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=1884s"]]}, {"cat": "リングの話", "t": "今後はシングルで頂点を目指す", "b": "タッグ王座を6度獲って満足し、これからはシングルの最高峰を目指すと話す。タッグで安定しすぎて慣れてしまったと感じていたという。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（35:23〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=2123s"]]}, {"cat": "暮らし", "t": "目標を紙に書き出すようになった", "b": "自粛期間中、何も開いていなかった3月・4月に、1年後までの目標を書き出し始めたという。安定した立場に慣れすぎたと感じ、変わる必要があると思ったからだそうだ。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-GdYiZ87fFGA", "src": [["番組のYouTube（37:45〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=2265s"]]}]);
  if (PROFILES["Enzo Amore"]) PROFILES["Enzo Amore"].facts.push({"cat": "暮らし", "t": "エンツォ・アモーレは友人で、マイクが武器", "b": "エンツォ・アモーレは友人であり、マイクの才能があると、タマ・トンガが話している。", "sp": "タマ・トンガ", "d": "2020-08-18", "how": "クリス・ヴァン・ヴリートの番組で、タマ・トンガの話（字幕を全文確認）", "src": [["番組のYouTube（10:27〜）", "https://www.youtube.com/watch?v=GdYiZ87fFGA&t=627s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-GdYiZ87fFGA", d: "2020-08-18", show: "ext", who: ["Tama Tonga"], t: "タマ・トンガの回　家族、軍隊、バレットクラブの始まり", lead: "クリス・ヴァン・ヴリートの番組に出た約44分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Tama Tonga"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GdYiZ87fFGA").map((x) => [x.t, x.b, x.sp])), open: ["信仰や宗教に関する話は、この回には出ていない。", "MSGの件など、実名の出る言い争いの部分は、事実関係を断定せず本人の受け止め方として書いた。", "字幕の誤認識が多く、固有名詞が不確かな箇所は載せなかった。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GdYiZ87fFGA"]] });
  if (!ROSTER.find((r) => r[1] === "Asuka")) ROSTER.push(["アスカ", "Asuka", "lg", "日本出身の女子王者", "", "", ""]);
  if (!PROFILES["Asuka"]) PROFILES["Asuka"] = { lead: "世界各国の記者からの質問に、通訳を介して答えた合同取材の回。仲間への思いや、海を渡った決断への誇りが語られている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Asuka"]], moves: [], facts: [] };
  if (PROFILES["Asuka"]._weak) { PROFILES["Asuka"].lead = "世界各国の記者からの質問に、通訳を介して答えた合同取材の回。仲間への思いや、海を渡った決断への誇りが語られている。"; delete PROFILES["Asuka"]._weak; }
  PROFILES["Asuka"].facts.push(...[{"cat": "リングの話", "t": "ベッキーと分かち合った王座の瞬間", "b": "RAWでベッキー・リンチと迎えた、王座を獲得した場面を語った。アスカにとって魔法のような瞬間だったという。ベッキーの妊娠発表についても、うれしく思っていると話す。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=0s"]]}, {"cat": "リングの話", "t": "カイリ・セインは大切な存在", "b": "カイリ・セインはアスカにとって大切な人で、組んでいて楽しく、互いに助け合い励まし合ってきたと話す。サーシャ・バンクスに勝ったあとは、カイリとの対戦を楽しみにしているそうだ。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=95s"]]}, {"cat": "リングの話", "t": "無観客の試合は特別な経験", "b": "観客がいない状況は難しく、特別な経験だと受け止めているという。それでも、ファンが会場に戻ってくる日にはまた試合を見てほしいと話している。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=336s"]]}, {"cat": "リングの話", "t": "一番手ごわい相手はナイア・ジャックス", "b": "これまで戦った中で最も厄介な相手として、ナイア・ジャックスの名を挙げた。背が高く体も重い、怪物のような相手だと話す。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（8:08〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=488s"]]}, {"cat": "リングの話", "t": "育成ブランドへの復帰を望む", "b": "かつて所属した育成ブランドに戻りたい気持ちがあると話す。そこで若い選手たちと多くの試合をしたいという。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（8:08〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=488s"]]}, {"cat": "リングに来るまで", "t": "海を渡った決断は正しかった", "b": "日本からWWEに移ったことは大きな決断だったが、世界中で見られる団体であり、正しい選択だったと話す。育成ブランドの王座、年間最大の祭典での優勝など、多くを手にしたことを挙げている。日本人初の快挙として自分の試合が世界に届くことを誇りに思うという。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（10:55〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=655s"]]}, {"cat": "リングの話", "t": "女子の改革の流れを変えた自負", "b": "女子部門が大きく変わった5年間について、自分がWWEに来て部門全体を変えたと話す。以前は女子が大会のメインを務めることは少なかったが、いまはタッグでもシングルでもメインに立てるようになったという。そのことを誇りに思っている。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（14:28〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=868s"]]}, {"cat": "リングの話", "t": "コミカルな一面も好き", "b": "クールな役柄だけでなく、コメディ寄りの表現も何でもこなせると話す。コメディ的な演技は好きで、その一面を観客に見せる時が来たという。リング上で踊る姿にも触れていた。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（19:00〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1140s"]]}, {"cat": "リングの話", "t": "最も大切な王座をめぐる思い", "b": "獲得した王座の中で何が大切かを問われ、育成ブランドの王座を挙げたとみられる。ベッキー・リンチから王座を受け取った魔法のような瞬間と、RAW女子王者であることの名誉も語った。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（19:52〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1192s"]]}, {"cat": "リングの話", "t": "シャイナ・ベイズラーとは同じタイプ", "b": "シャイナ・ベイズラーは腕のたつ選手で、アスカと同じ関節技を得意とするタイプだと話す。実現すれば手ごわい勝負になると考えているそうだ。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（26:37〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1597s"]]}, {"cat": "リングの話", "t": "日本ブランドができたら参加したい", "b": "日本を拠点にした新ブランドができたら、ぜひ関わりたいと話す。選手としてでも付き人のような形でも構わず、そこに加わって力になるという。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（27:23〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1643s"]]}, {"cat": "リングの話", "t": "一番の誇りは女子初の大舞台での優勝", "b": "WWE生活で最も誇りに思うことを聞かれ、女子として初めて開かれた年間最大の祭典前哨戦の勝者になったことを挙げた。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（28:08〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1688s"]]}, {"cat": "リングの話", "t": "本社で撮った一発勝負は楽しかった", "b": "本社を舞台にした特別な形式の試合は、普段と何もかも違い、大変なことも面白いこともあったという。勝ったことも含め、とても楽しんだと話す。", "sp": "アスカ", "d": "2020-11-05", "how": "マルコ・エルコレの番組で（字幕を全文確認）", "art": "ext-ZXPhs6YznSE", "src": [["番組のYouTube（29:53〜）", "https://www.youtube.com/watch?v=ZXPhs6YznSE&t=1793s"]]}]);
  ARTICLES.push({ id: "ext-ZXPhs6YznSE", d: "2020-11-05", show: "ext", who: ["Asuka"], t: "アスカの回　世界の記者に答えた合同取材", lead: "マルコ・エルコレの番組に出た約32分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Asuka"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ZXPhs6YznSE").map((x) => [x.t, x.b, x.sp])), open: ["通訳を介した取材のため、アスカの答えは通訳の言葉から読み取っており、細部は正確でない可能性がある。", "ゲームの仕事の経験についての質問への答えは、聞き取れなかったため載せていない。", "今後の試合の見通しや意気込みの話は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ZXPhs6YznSE"]] });
  if (!ROSTER.find((r) => r[1] === "Big Cass")) ROSTER.push(["ビッグ・キャス", "Big Cass", "lg", "元WWEタッグ戦線の大型選手", "", "", ""]);
  if (!PROFILES["Big Cass"]) PROFILES["Big Cass"] = { lead: "約18か月のブランクと依存症からの回復を経て、リングに戻った大型選手。仮面を外して体験を語り、人を助けることを人生の目標にしているという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Big%20Cass"]], moves: [], facts: [] };
  if (PROFILES["Big Cass"]._weak) { PROFILES["Big Cass"].lead = "約18か月のブランクと依存症からの回復を経て、リングに戻った大型選手。仮面を外して体験を語り、人を助けることを人生の目標にしているという。"; delete PROFILES["Big Cass"]._weak; }
  PROFILES["Big Cass"].facts.push(...[{"cat": "リングに来るまで", "t": "約18か月のブランクを経てリングに復帰", "b": "リング復帰までに約18か月かかったという。その間は先に向き合うべきことがあったと話す。復帰を決めたのは、プロレスが最初に好きになったものだと気づいたからだそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=144s"]]}, {"cat": "リングに来るまで", "t": "一時はプロレスを憎んでいた", "b": "離れていた間は、プロレスを恨めしく思うほどだったという。約4カ月前の朝、情熱を持てるのはやはりプロレスだと素直に認めたと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=144s"]]}, {"cat": "体のこと", "t": "復帰への道はポッドキャストと過去映像から", "b": "まずプロレス関連のポッドキャストを聞き、昔のペイ・パー・ビューやリング・オブ・オナーの映像を見直したという。気づけばプロレスに夢中になっていたそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=192s"]]}, {"cat": "体のこと", "t": "ジムは心の回復の支え", "b": "ジムは回復期を通じて精神面を支えてくれたと話す。復帰を決めてからは朝に有酸素運動、日中に筋トレ、食事制限と徹底し、人生最高の体で戻るつもりだったという。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=192s"]]}, {"cat": "リングに来るまで", "t": "社会福祉学の修士も考えていた", "b": "復帰前は大学院で社会福祉学の修士を取ることも考えていたという。依存症からの回復に強い思いがあり、同じ立場の人を助けたかったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=238s"]]}, {"cat": "リングに来るまで", "t": "ギャローズの誘いで復帰戦へ", "b": "12月ごろ、ギャローズが自宅に呼んでくれた。健康で前向きな様子を見て、2月の大会に出してくれたという。直前は観客が盛り上がらなかったらと不安だったが、ギャローズは信じろと言い続けたそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（5:31〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=331s"]]}, {"cat": "体のこと", "t": "明るく振る舞い、心の中は暗かった", "b": "最後にリングに立っていた頃は、幸せなふりをして仮面をかぶっていたという。特に仲間の前では前向きに見せていたが、内側はとても暗かったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（7:10〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=430s"]]}, {"cat": "体のこと", "t": "最初の発作でも問題を認められなかった", "b": "フィラデルフィアの大会で最初の発作を起こした後も、問題だとは思えなかったという。周囲の人に勧められて入ったリハビリは、人を安心させるためだったので最初は続かず、出てすぐ飲酒に戻ったそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（7:59〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=479s"]]}, {"cat": "体のこと", "t": "発作の夜の記憶はほとんどない", "b": "発作の夜は、サイン会の前に控室でトミー・ドリーマーらと話したところまでしか覚えておらず、次の記憶は救急車の中だという。病院では疲労や脱水と嘘をついたが、実際は離脱症状だと分かっていたと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（10:21〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=621s"]]}, {"cat": "暮らし", "t": "解雇後は一日中飲んでいた", "b": "在籍中は毎週飛行機に乗る責任があったが、解雇後は住まいもお金も車もあるのにやる気がなく、朝から晩まで飲んでいたという。責任のない生活は依存症の人には最悪だったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（11:57〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=717s"]]}, {"cat": "体のこと", "t": "2017年頃から悪化、仮面の裏で隠れ飲み", "b": "問題が悪化したのは2017年頃だという。部屋で隠れて飲み、誰にも見られないようにしていたそうだ。心の不調を口にするのが恥ずかしく、強くなれという空気の中で言い出せなかったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（13:33〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=813s"]]}, {"cat": "体のこと", "t": "ファンレターが支えになった", "b": "リハビリ中、ファンからの手紙がダイヤモンド・ダラス・ペイジ経由でたくさん届いたという。今も落ち込んだ日には読み返すと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（16:49〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1009s"]]}, {"cat": "体のこと", "t": "話すことで誰かの助けになれる", "b": "自分が話さなければ誰の助けにもならないと考え、依存症や心の問題を公に語るようになったという。サイン会でも断酒の仲間が声をかけてくれるそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（18:25〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1105s"]]}, {"cat": "体のこと", "t": "命の危険を感じて本気で回復へ", "b": "リハビリの後も何度か発作があり、このままでは死ぬと分かったという。リハビリ仲間や断酒の集まりの人たちに助けを求め、タンパに戻って再び入所したと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（19:14〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1154s"]]}, {"cat": "暮らし", "t": "タンパが2017年からの拠点", "b": "2017年からタンパを拠点にしているという。ダイヤモンド・ダラス・ペイジの家に数カ月、出入りしながら世話になった時期もあり、ニュージャージーやニューヨークにもいたと話す。ダラスは最初に語る場を与えてくれた人だそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（20:53〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1253s"]]}, {"cat": "体のこと", "t": "回復の転機は「自分のやり方はない」と認めたこと", "b": "転機は、自分がすべてを分かっているわけではないと認め、人に助けを求めたことだという。自分のやり方という選択肢はなく、皆と同じことをするしかないと悟ったそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（22:28〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1348s"]]}, {"cat": "家族", "t": "恋人はダラスの義理の娘", "b": "恋人とはダラスを通じて知り合ったという。彼女は回復の過程をほぼずっと支え続けてくれたそうだ。私生活は公にしたくなかったが、そうも言っていられないと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（24:08〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1448s"]]}, {"cat": "暮らし", "t": "タンパで犬2匹と穏やかに暮らす", "b": "出る大会は自分で選べる今の生活が気に入っているという。恋人とタンパで過ごし、フレンチブルドッグを2匹飼っている。9カ月の子犬はバンバンと名付け、ベーブ・ルースの愛称バンビーノから取ったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（26:27〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1587s"]]}, {"cat": "リングの話", "t": "単独の主役として記憶に残りたい", "b": "もう一度大きな舞台に戻りたいという。王座にこだわるより、記憶に残ることが大事で、今度は単独の選手として残りたいと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（27:12〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1632s"]]}, {"cat": "リングの話", "t": "世界王者を目指し、体験も語り続ける", "b": "いつかどこかの団体でトップに立つのが目標だという。同時に依存症やメンタルヘルスの体験を語り、人を助けることが人生の目標だと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（28:00〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1680s"]]}, {"cat": "リングの話", "t": "エンゾは何度も救ってくれた親友", "b": "エンゾ・アモーレは、ニュージャージーで同居させてくれ、リハビリ入所のきっかけにもなったという。遠征先で帰れなくなった時に迎えに来てくれたこともあり、変わらぬ友情に感謝していると話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（28:50〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1730s"]]}, {"cat": "リングの話", "t": "他団体への思い", "b": "AEW、インパクト、新日本、リング・オブ・オナーなど、どこでも行きたいと話す。ギャローズとアンダーソンとも話はあるが、時期が来ればという姿勢で、一日ずつ進めているそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（30:25〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1825s"]]}, {"cat": "体のこと", "t": "再発を心配されるのも現実", "b": "興行側に危険だと見られるのは当然で、信頼は積み上げるしかないと話す。それでも今は仮面をかぶらず、毎日やることを続ければ大丈夫だと確信しているという。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（31:12〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1872s"]]}, {"cat": "家族", "t": "子どもの頃は心配性で神経質", "b": "子どもの頃から神経質で、いつも最悪の事態を心配していたという。クラスでは大柄だったが晩成型で、高校の頃は身長が175センチほどだったそうだ。今は回復のおかげで心配を手放せたと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（31:59〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1919s"]]}, {"cat": "リングに来るまで", "t": "医者を目指すと言いつつレスラーが夢だった", "b": "周囲には医者になると言い、大学で医学部進学課程を取りMCATも受けたが、本当はプロレスラーになりたかったという。大学卒業の翌日にはジョニー・ロッドのレスリングスクールで練習を始めたそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（33:34〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2014s"]]}, {"cat": "リングに来るまで", "t": "憧れた大型レスラーたち", "b": "憧れはアンダーテイカー、ケビン・ナッシュ、JBLだという。特にJBLは大柄なのに動けるところが、自分と重なったと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（34:22〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2062s"]]}, {"cat": "好きなもの", "t": "好きな試合の思い出", "b": "子どもの頃から好きな試合として、オースチン対ブレット・ハートのレッスルマニア13を挙げる。高校時代に見たレイ・ミステリオ対カート・アングルのサマースラム2002の開幕戦も好きだったそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（35:10〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2110s"]]}, {"cat": "リングの話", "t": "エンゾの入団テストで組みたいと思った", "b": "エンゾがFCWの入団テストで見せたマイクに感動し、契約してほしい、一緒に何かやりたいと思ったという。入団後はすぐに仲良くなったそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（36:49〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2209s"]]}, {"cat": "リングの話", "t": "ニュー・エイジ・アウトローズを手本にした入場マイク", "b": "二人のおなじみの入場の流れは、ニュー・エイジ・アウトローズの型に近かったという。ビリー・ガンがコーチだった縁もあるそうだ。決まった型の合間に毎回新しい言葉を考え、ライターと作り込んでいたと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（38:25〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2305s"]]}, {"cat": "リングの話", "t": "「ソフト」のかけ声が生まれた夜", "b": "ジョン・シナとのダークマッチの後、観客が二人に向けてかけ声を叫んだことで、これは受けると気づいたという。デビュー前の無名の頃の出来事だそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（40:05〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2405s"]]}, {"cat": "リングの話", "t": "本戦デビュー時の大歓声", "b": "レッスルマニア翌日の番組で、終盤にようやくデビューした時は大歓声だったという。今見返しても鳥肌が立つと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（40:50〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2450s"]]}, {"cat": "リングの話", "t": "仲間割れの展開は受け入れていた", "b": "2017年のエンゾ襲撃の筋書きでは、当初は自分の役ではなかったという。決まってからは悪役になることを受け入れ、エンゾは受けの名手なので組みやすいと話す。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（43:13〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2593s"]]}, {"cat": "体のこと", "t": "解雇時の面談とその受け止め", "b": "解雇は当時は悔しかったが、危うい存在だったので正当な判断だったと話す。対面の面談で、話は選手としてでなく本名の自分のことが中心だったそうだ。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-4Y2U46J3SME", "src": [["番組のYouTube（44:47〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=2687s"]]}]);
  if (PROFILES["Enzo Amore"]) PROFILES["Enzo Amore"].facts.push({"cat": "暮らし", "t": "リハビリ前後を支えた親友", "b": "自宅に泊めてくれ、遠征先まで迎えに来てくれたこともあるなど、長く支えてくれたと、ビッグ・キャスが話している。復帰を応援してくれているという。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で、ビッグ・キャスの話（字幕を全文確認）", "src": [["番組のYouTube（28:50〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1730s"]], "by": "第三者の話"});
  if (PROFILES["Diamond Dallas Page"]) PROFILES["Diamond Dallas Page"].facts.push({"cat": "暮らし", "t": "語る場を与えた恩人", "b": "自宅に滞在させ、体験を公に語る場を与えてくれた最初の人だったと、ビッグ・キャスが話している。", "sp": "ビッグ・キャス", "d": "2021-04-15", "how": "クリス・ヴァン・ヴリートの番組で、ビッグ・キャスの話（字幕を全文確認）", "src": [["番組のYouTube（20:53〜）", "https://www.youtube.com/watch?v=4Y2U46J3SME&t=1253s"]], "by": "第三者の話"});
