  if (!PROFILES["Shinsuke Nakamura"]) PROFILES["Shinsuke Nakamura"] = { lead: "料理もサーフィンも空手も本気で楽しむ、自由な素顔の持ち主。祖母と観たプロレスがすべての始まりだったという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Shinsuke%20Nakamura"]], moves: [], facts: [] };
