  PROFILES["Shinsuke Nakamura"].facts.push(...[{"cat": "暮らし", "t": "パンデミック中に豚骨ラーメンを自作", "b": "昨年の外出自粛中、中邑は豚の頭の骨からスープを作ったと話す。地元の肉屋で骨を手に入れ、仕込みには10時間以上かかったという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（0:51〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=51s"]]}, {"cat": "家族", "t": "九州出身の妻に家での豚骨は禁止された", "b": "家の中で煮ようとしたが、豚骨のにおいが家中に広がるため妻に止められたという。妻は九州の出身で、豚骨の強いにおいをよく知っている。そのため中邑は屋外でバケツを使って煮込み、毎日のようにラーメンを作っていたそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（1:42〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=102s"]]}, {"cat": "好きなもの", "t": "焼肉やホルモンなど内臓料理も好き", "b": "得意料理として焼肉やイタリアンを挙げ、腸などの内臓料理も好きだと話す。アメリカでは手に入りにくいが、メキシコ系の人が食べるため大型スーパーで牛の腸を見つけ、自分で洗って下ごしらえしたという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（2:28〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=148s"]]}, {"cat": "好きなもの", "t": "料理はあくまで趣味、店を出す気はない", "b": "料理は自分や友人のための趣味で、周りから店を出すよう勧められても「ただ食べたいだけ」と笑う。引退後にラーメン店を開くかは決めていないそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（4:03〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=243s"]]}, {"cat": "リングに来るまで", "t": "祖母と一緒に金曜夜のプロレス中継を観ていた", "b": "子どものころ、祖母と一緒に金曜夜8時の新日本プロレスの中継を観ていたという。父が野球をやらせたがったため、野球の話が出ると祖母の部屋へ逃げてプロレスを観ていたそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（4:55〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=295s"]]}, {"cat": "家族", "t": "父は野球を望み、母は大学進学を望んだ", "b": "父は息子に野球をやらせたがり、プロレスにはまったく関心がなかったという。母は大学に進むことを望んでいた。中邑が学生時代のレスリングで州大会を制し、全国大会まで進んだことで、両親もようやく認めてくれたと話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（5:41〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=341s"]]}, {"cat": "リングに来るまで", "t": "幼いころは泣き虫だった", "b": "2人の姉にいつもからかわれ、泣き虫の子どもだったと話す。年上の相手にもすぐ向かっていったという。「女の子みたいだから男らしくなりたい」と思ったのが、格闘技に興味を持ったきっかけだそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（6:30〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=390s"]]}, {"cat": "リングに来るまで", "t": "忍者・侍・ジャッキー・チェンに憧れた", "b": "強い男になりたくて武道に関心を持ち、忍者や侍が好きだったという。小学生のころからジャッキー・チェンの映画を観ており、千葉真一ら日本のアクションスターも憧れの存在だった。ほぼ毎日試合をするプロレスラーなら、自分も鍛えられると考えたそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（7:16〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=436s"]]}, {"cat": "リングに来るまで", "t": "英語は辞書と仲間に頼って身につけた", "b": "学校で習った英語は発音がきれいとは言えず、サイレントレターすら知らないままアメリカへ渡ったという。2002年ごろは翻訳アプリもなく、いつも辞書を持ち歩いていた。プロレスは体で通じ合う共通言語だと話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（8:01〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=481s"]]}, {"cat": "リングに来るまで", "t": "ロッキー・ロメロらに英語を助けてもらった", "b": "英語の習得ではロッキー・ロメロなど周りの友人に助けられたと話す。一時期はブライアン・ダニエルソンと同居しており、お互いの英語を見てもらっていたという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（9:33〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=573s"]]}, {"cat": "体のこと", "t": "英語のマイクは今でも緊張する", "b": "WWEでのマイクは今も緊張するという。短いセリフでも、アメリカで育っていないため分からない有名なジョークが出てくることがあり、それが難しいと話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（10:22〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=622s"]]}, {"cat": "好きなもの", "t": "姉の影響とマイケル・ジャクソンが服の原点", "b": "姉の1人は服作りの学校に通っており、おしゃれへの関心はその影響もあるという。マイケル・ジャクソンも大きな影響源で、筋肉質ではないのに重力を操るように動く姿が、武道の達人のようだと感じたそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（11:09〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=669s"]]}, {"cat": "好きなもの", "t": "赤は幸運の色", "b": "赤は自分にとってラッキーカラーだと話す。青を使うこともあり、年に一度の大舞台のために白の衣装も作ったが使えなかったという。今は他の色も試している。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（11:56〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=716s"]]}, {"cat": "リングに来るまで", "t": "デビュー当時から地味な黒の装いは避けた", "b": "新日本プロレスでのデビューは大きな試合の場だったため、見た目を大きく見せようと、若手の定番とは違う装いを選んだという。メキシコと日本で一度ずつ顔にペイントをしたこともあるそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（12:46〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=766s"]]}, {"cat": "リングに来るまで", "t": "最年少王者になったが社内に味方はいなかった", "b": "最年少でIWGPヘビー級王者になったとき、経験もないまま団体の看板を背負うことになったと話す。周囲に嫉妬もあり、社内に友人はいなかったと感じていたという。当時の友人は総合格闘技のジムなど団体の外にいたそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（13:36〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=816s"]]}, {"cat": "リングに来るまで", "t": "最年少IWGP王者の記録は永遠に残る", "b": "新日本がヘビー級とインターコンチネンタルの王座を統合したことについて、自分の最年少記録は永遠に残るとうれしそうに話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（14:27〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=867s"]]}, {"cat": "リングの話", "t": "ブロック・レスナーとの再戦は望んでいる", "b": "もしブロック・レスナーがWWEに戻るなら、再戦の機会があれば当然やりたいと中邑は話す。新日本時代にはお互い若く、当時の関係は一言では言えないという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（14:27〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=867s"]]}, {"cat": "リングの話", "t": "今の新日本を今も追いかけている", "b": "新日本プロレスには今も友人が多く、試合を観ていると話す。注目する選手としてオカダ・カズチカの名を挙げ、結婚式にも出席したという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（15:14〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=914s"]]}, {"cat": "リングに来るまで", "t": "若手時代は永田裕志の付き人を務めた", "b": "日本で修行していた若手のころ、永田裕志の付き人を務めたと話す。試合用のコスチュームの用意や、試合後のアイシングの手伝いなどをしたという。永田は日本のプロレスの師の1人だそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（16:53〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1013s"]]}, {"cat": "暮らし", "t": "ガレージジムで鍛え、今は空手に取り組む", "b": "自宅にガレージジムを作り、ウェイトだけでなく自重トレーニングも重視していると話す。コロナ前に再開したブラジリアン柔術は感染リスクが気になるため、今は空手を始めたという。中学時代にも空手の経験があり、流派が違うと黒帯でも白帯からやり直しになるのが楽しいそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（18:30〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1110s"]]}, {"cat": "好きなもの", "t": "サーフィンは毎日違うから面白い", "b": "日本にいたころからサーフィンを続けているという。天候や海面の状態で毎回条件が変わるため難しいが、そこが面白くて飽きないと話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（19:18〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1158s"]]}, {"cat": "暮らし", "t": "キャンプ好きだがキャンピングカーは修理待ち", "b": "キャンプにもよく行くが、昨年購入したキャンピングカーにエンジンの不具合が見つかり、修理工場に預けたままだという。今年はキャンプに行けていないそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（19:18〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1158s"]]}, {"cat": "リングの話", "t": "引退試合の相手は棚橋弘至を挙げる", "b": "空想の引退試合として、もう一度棚橋弘至と戦いたいと話す。また、今は知らない新世代のスターとも戦ってみたいそうだ。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（20:04〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1204s"]]}, {"cat": "リングの話", "t": "WWEでの成功はまだ途中だと感じている", "b": "ロイヤルランブル優勝や大舞台のメインイベントを経験しても、自分はまだ苦戦していると話す。挑戦したくてアメリカに来たと語り、ふさわしいタイミングを待っているという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（20:51〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1251s"]]}, {"cat": "リングの話", "t": "ビンスにアイデアを売り込むことは少ない", "b": "ビンス・マクマホンと話すのは試合の前後に少しだけで、自分からアイデアを出すことは多くないという。マイクの案を向こうから出されることもあるが、忙しい相手と時間を取るのには慣れが必要だと話す。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で（字幕を全文確認）", "art": "ext-71bbPFtjhbI", "src": [["番組のYouTube（21:38〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1298s"]]}]);
  if (PROFILES["Kazuchika Okada"]) PROFILES["Kazuchika Okada"].facts.push({"cat": "暮らし", "t": "オカダ・カズチカはまだ伸びると見ている", "b": "オカダ・カズチカは今も大きな存在で、男前だと、中邑真輔が話している。結婚式にも出席したという。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で、中邑真輔の話（字幕を全文確認）", "src": [["番組のYouTube（15:14〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=914s"]], "by": "第三者の話"});
  if (PROFILES["Kota Ibushi"]) PROFILES["Kota Ibushi"].facts.push({"cat": "暮らし", "t": "飯伏幸太にはさらなる飛躍を期待", "b": "飯伏幸太はこれからもっと大きくなる、責任を見せようとしていると、中邑真輔が話している。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で、中邑真輔の話（字幕を全文確認）", "src": [["番組のYouTube（15:14〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=914s"]], "by": "第三者の話"});
  if (PROFILES["Hiroshi Tanahashi"]) PROFILES["Hiroshi Tanahashi"].facts.push({"cat": "暮らし", "t": "棚橋弘至とは引退前にもう一度戦いたい", "b": "空想の引退試合の相手に棚橋弘至を挙げ、もう一度戦いたいと、中邑真輔が話している。", "sp": "中邑真輔", "d": "2021-05-22", "how": "レネー・パケットの番組で、中邑真輔の話（字幕を全文確認）", "src": [["番組のYouTube（20:04〜）", "https://www.youtube.com/watch?v=71bbPFtjhbI&t=1204s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-71bbPFtjhbI", d: "2021-05-22", show: "ext", who: ["Shinsuke Nakamura"], t: "中邑真輔の回　ラーメン作りと、祖母と観たプロレス", lead: "レネー・パケットの番組に出た約24分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Shinsuke Nakamura"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-71bbPFtjhbI").map((x) => [x.t, x.b, x.sp])), open: ["聞き手のレネー・パケットは番組の最後に自身の出産予定の話をしているが、本人の話ではないため載せていない。", "一部の名前（英語の勉強仲間など）は自動字幕が崩れており、確信の持てないものは省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=71bbPFtjhbI"]] });
  if (!ROSTER.find((r) => r[1] === "Buddy Matthews")) ROSTER.push(["バディ・マシューズ", "Buddy Matthews", "gn", "元バディ・マーフィー", "", "", ""]);
  if (!PROFILES["Buddy Matthews"]) PROFILES["Buddy Matthews"] = { lead: "ミステリオ親子との抗争が突然消え、控室で待つ日々が続いたバディ。解雇の電話は驚きよりも解放感があったと語り、WWEでの歩みを細部までふり返る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Buddy%20Matthews"]], moves: [], facts: [] };
  if (PROFILES["Buddy Matthews"]._weak) { PROFILES["Buddy Matthews"].lead = "ミステリオ親子との抗争が突然消え、控室で待つ日々が続いたバディ。解雇の電話は驚きよりも解放感があったと語り、WWEでの歩みを細部までふり返る。"; delete PROFILES["Buddy Matthews"]._weak; }
  PROFILES["Buddy Matthews"].facts.push(...[{"cat": "退団の理由", "t": "解雇の電話は予感していた", "b": "バディは、会社名が表示された着信を見たとき、用件がすぐ分かったと話す。自分が不満を抱え、もっと役割が欲しいとはっきり伝えていたため、解雇は予想できたという。電話に出る前に、ひとまず用事の印刷を済ませたそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（0:51〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=51s"]]}, {"cat": "退団の理由", "t": "解雇は「肩の荷が下りる」感覚", "b": "解雇された人は皆、重荷が下りたように感じると聞いていたと、バディは話す。自分も実際にそう感じ、自由になった気がしたという。ただ、不意に殴られたような衝撃もあり、新鮮な空気を吸ったような感覚もあったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（1:40〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=100s"]]}, {"cat": "退団の理由", "t": "いちばんの心配はビザだった", "b": "解雇直後のバディにとって、試合ができなくなることよりも、米国での滞在資格の行方が最大の心配だったという。人生の4分の1をアメリカで過ごし、家も動物もあるからだと話す。バックアップになる手続きをできる限り進め、あとは待つしかないと考えているそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（2:28〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=148s"]]}, {"cat": "退団の理由", "t": "競業避止期間をめぐる行き違い", "b": "解雇の翌日、会社から電話があり、競業避止の期間が30日のままだったので90日に延ばしたいという話が出たという。バディの手元の通知書には8月31日と書かれていたため、別の選手と取り違えられたようだと本人は受け止めている。時間があるほどビザの準備に有利なので、延長はむしろ必要だったと話す。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（5:41〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=341s"]]}, {"cat": "退団の理由", "t": "荷物がゴミ袋で届く話への見方", "b": "解雇された選手の私物がゴミ袋で送られた話について、バディは悪意があったとは思わないと話す。ただ、解雇で人生が変わる人に対して印象のよいやり方ではないとも述べている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（7:18〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=438s"]]}, {"cat": "退団の理由", "t": "控室で待つだけの日々への不満", "b": "ミステリオ親子との抗争が突然なくなったあとも、バディは毎週テレビ収録に呼ばれ、控室にいたという。ほかの選手は登場しない期間があるのに自分は出社を求められ、「大好きなことをさせてもらえない」と見せつけられているように感じたと話す。会社が意図したとは思っていないとも付け加えている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（8:52〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=532s"]]}, {"cat": "退団の理由", "t": "評価の浮き沈みと、遠のいた熱意", "b": "バディは、自分のキャリアはずっと好調と不調の繰り返しだったと話す。同じ流れで仲間が去り、一時は物語の中心に近づいたものの、また消えてしまったという。その時期は、プロレスそのものから気持ちが少し離れたと認めている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（10:24〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=624s"]]}, {"cat": "WWEでの日々", "t": "ミステリオ親子との抗争の裏側", "b": "自分の物語ではなく、レイとセスの抗争に絡む立場だったとバディは説明する。大きな大会に呼ばれなかったり、抗争が途中で動かなくなったりして、事情を聞かされないことも多かったという。仲間から情報を集めても答えが得られなかったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（11:59〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=719s"]]}, {"cat": "WWEでの日々", "t": "「セスと再合流」が本来の筋書きだった", "b": "抗争を長引かせるうえでの最終地点は、セス・ロリンズのもとへ戻ることだったとバディは聞いていたという。最初の敗戦で相手を超えられないと知り、師と仰ぐ形で戻る流れだったそうだ。しかし途中で「バディは戻らない」という展開に変わったと話す。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（13:36〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=816s"]]}, {"cat": "WWEでの日々", "t": "ベビーフェイス初日と奇妙な勝ち方", "b": "ベビーフェイスに転向した最初の夜、バディはミステリオ家の手を借りて勝つ展開になった。勝利のために4人の助けが必要という設定が不自然で、自分は気に入らなかったと話す。ミステリオ側も同じように感じていたのではないかと振り返っている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（15:11〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=911s"]]}, {"cat": "WWEでの日々", "t": "連絡のないまま話が消えた", "b": "家族に感染者が出たため、ミステリオ親子が欠席し、バディ自身も隔離された時期があったという。復帰すると共演者のいない状態になり、誰に聞いても返事がなかった。最後は担当者に直接確認し、話が打ち切られたと知ったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（19:13〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1153s"]]}, {"cat": "WWEでの日々", "t": "ロマン・レインズ襲撃役は想定外の注目だった", "b": "スマックダウンで、背景にバディが映った場面が話題になったが、あれは意図した演出ではなかったと本人は話す。収録前にプロモを重ねて撮り直したり、気持ちを抑えて取り組んだりしていたという。ファンが盛り上がったのは偶然だが、嬉しい誤算だったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（21:39〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1299s"]]}, {"cat": "WWEでの日々", "t": "ロマン戦が「世に出た」きっかけ", "b": "バディは、ロマン・レインズとの試合を自分の大きな飛躍だったと語る。一度は試合が取りやめになったが、ロマンが試合を組む形を一緒に考えてくれたという。クルーザー級の自分の持ち味を思い切り出せた試合で、今も話題にされるそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（26:33〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1593s"]]}, {"cat": "WWEでの日々", "t": "ポール・ヘイマンの後押し", "b": "ヘイマンは、バディが番組に出ていない理由が分からないと、控室でよく声をかけてくれたという。RAWに移ってからはアイデアを聞き入れてくれたそうだ。バディはヘイマンを信頼できる人物と話している。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（28:57〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1737s"]]}, {"cat": "WWEでの日々", "t": "アリスター・ブラックとの試合づくり", "b": "友人同士の2人が、遠慮なくぶつかり合うのが良い試合になると、バディは話す。同じ組み合わせの再戦を急ぐのは、良いものを使いすぎる行為だと考え、ヘイマンに相談して間隔を空けたそうだ。入場への割り込みや座り込みなど、見せ場のアイデアも本人が出したという。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（31:20〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1880s"]]}, {"cat": "WWEでの日々", "t": "弟子役の名前は自分のアイデア", "b": "バディという名前を捨てて新しい人物に生まれ変わる設定を、自分から提案したと本人は話す。師に名前を捧げるという聖書的な物語のつもりだったが、理由が劇中で説明されなかったことを残念がっている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（37:01〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2221s"]]}, {"cat": "WWEでの日々", "t": "細部が省かれることへのもどかしさ", "b": "セスが復帰した場面で、バディはミステリオ親子の近くにいない配置にされ、なぜそこにいるのか分からなかったと話す。自分は「穴埋めの人員」だったと感じ、詳細を詰めてほしかったと語る。細部が丁寧な番組ほど視聴者の目も肥えると、本人は考えているそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（39:29〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2369s"]]}, {"cat": "WWEでの日々", "t": "ビンス・マクマホンとの距離", "b": "バディは、ビンス・マクマホンと直接話す機会はほとんどなかったという。台本の一言が気に入らなくても、そこで争うと全体が変わってしまうので、できるだけ自分の気持ちを乗せて話す工夫をしたと話す。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（43:28〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2608s"]]}, {"cat": "WWEでの日々", "t": "弟子役は話さないことに意味があった", "b": "弟子の役柄では、あえて話さないことで、口を開いたときの重みが増すと考えていたとバディは話す。決め技を何度も返されると価値が薄れるのと同じ理屈だという。ただ、思い描いたほど大きく見せる機会はなかったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（45:02〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2702s"]]}, {"cat": "WWEでの日々", "t": "205ライブでの「いじめっ子」役", "b": "バディは、軽量級の計量時に体を絞り、計量後に水分と食事で大きく戻る設定の役を演じていたという。軽い相手を押しつぶす役で、実際の格闘技の階級の話をヒントにしたそうだ。軽量級の枠を超える選手の存在も、試合の見せ方に生かしたかったと話す。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（48:13〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2893s"]]}, {"cat": "WWEでの日々", "t": "205ライブの終わりと仲間の離脱", "b": "バディは、205ライブが新しい時代として盛り上がった時期、自分たちの意見も聞いてもらえたと振り返る。仲間が次々に去り、最後は事実上の終わりを感じたという。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（53:11〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=3191s"]]}, {"cat": "WWEでの日々", "t": "205ライブからの昇格と最後の試合", "b": "レッスルマニアでの対戦は良い試合になるが、その後の展開に何も残らないと感じ、バディは疑問を伝えたという。結局、相手をベビーフェイスにする形で終わらせる流れに協力したと話す。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（59:30〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=3570s"]]}, {"cat": "WWEでの日々", "t": "ドラフトの舞台裏", "b": "ドラフトの行き先は直前まで知らされず、ヘイマンの下に行けるだろうと予想していたとバディは話す。のちの移籍では、セスとともに物語ごと移る形になり、発表の仕方にもう少し工夫がほしかったと振り返っている。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（1:01:55〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=3715s"]]}, {"cat": "WWEでの日々", "t": "無観客時代の長い一日", "b": "バディは、無観客のパフォーマンスセンターで、1日に複数の試合を連続でこなしたと話す。温まっては冷えることの繰り返しで、帰りの車ではハンドルを回すのもつらいほど体が痛んだそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（1:06:45〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=4005s"]]}, {"cat": "退団の理由", "t": "全力で働いても立場は変わらなかった", "b": "コロナ禍の無観客期間、バディは1日に複数の試合をこなし、体がぼろぼろになるほど働いたという。信頼できる選手だと思われたくてやったが、他の選手を呼べるようになると、自分たちは後ろに下がったと感じたそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（1:09:12〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=4152s"]]}, {"cat": "退団の理由", "t": "「自分はまだ全力を出していない」", "b": "32歳のバディは、まだピークではないと話す。薬物検査に落ちたことも遅刻したこともなく、問題を起こさない社員だったと自負しているそうだ。いつも脇役だったので、主役級の存在になれると心の底で信じていると語る。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで（字幕を全文確認）", "art": "ext-VR5f3IGvz2A", "src": [["番組のYouTube（1:18:02〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=4682s"]]}]);
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "ロマンが試合づくりを手伝った", "b": "試合が一度なくなったとき、ロマン・レインズは「今夜は急ぎすぎだ」と声をかけてくれたと、バディ・マシューズが話している。後日、試合の骨組みを任せ、自分も少し手を加える形で一緒に作り上げてくれたという。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで、バディ・マシューズの話（字幕を全文確認）", "src": [["番組のYouTube（27:22〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1642s"]], "by": "第三者の話"});
  if (PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"].facts.push({"cat": "暮らし", "t": "ヘイマンは裏でも味方だった", "b": "ポール・ヘイマンは、なぜ毎週テレビに出られないのかと、いつも裏で声をかけてくれたと、バディ・マシューズが話している。意見を聞いたうえで一緒に作る進め方だったそうだ。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで、バディ・マシューズの話（字幕を全文確認）", "src": [["番組のYouTube（29:44〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=1784s"]], "by": "第三者の話"});
  if (PROFILES["Edge"]) PROFILES["Edge"].facts.push({"cat": "暮らし", "t": "エッジから学んだ「本物の感情」", "b": "エッジとプロモを練習したとき、台詞の中に自分が共感できる本物の要素を入れるとよいと助言されたと、バディ・マシューズが話している。", "sp": "バディ・マシューズ", "d": "2021-07-08", "how": "Fightful（ショーン・ロス・サップ）のシュートインタビューで、バディ・マシューズの話（字幕を全文確認）", "src": [["番組のYouTube（44:15〜）", "https://www.youtube.com/watch?v=VR5f3IGvz2A&t=2655s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-VR5f3IGvz2A", d: "2021-07-08", show: "ext", who: ["Buddy Matthews"], t: "バディ・マシューズの回　解雇の瞬間と、WWE時代のふり返り", lead: "Fightful（ショーン・ロス・サップ）のシュートインタビューに出た約80分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Buddy Matthews"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-VR5f3IGvz2A").map((x) => [x.t, x.b, x.sp])), open: ["WWE以外の話題（ほかの選手とのうわさ、他団体の話、私生活）は公開項目から外した。", "字幕は自動生成で固有名詞が崩れている箇所があり、確信の持てない名前は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=VR5f3IGvz2A"]] });
  if (!ROSTER.find((r) => r[1] === "Dusty Rhodes")) ROSTER.push(["ダスティ・ローデス", "Dusty Rhodes", "lg", "", "", "", ""]);
  if (!PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"] = { lead: "「アメリカン・ドリーム」ダスティ・ローデス。黒人教会の説教に耳を傾けた少年時代から、晩年に後進へ伝えた「伝える力」まで、自分の言葉で語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dusty%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Dusty Rhodes"]._weak) { PROFILES["Dusty Rhodes"].lead = "「アメリカン・ドリーム」ダスティ・ローデス。黒人教会の説教に耳を傾けた少年時代から、晩年に後進へ伝えた「伝える力」まで、自分の言葉で語る。"; delete PROFILES["Dusty Rhodes"]._weak; }
  PROFILES["Dusty Rhodes"].facts.push(...[{"cat": "好きなもの", "t": "何より大事なのは狩り場での心の平穏", "b": "ジョージア州南部の農場で、ほぼ毎週末シカ狩りをしていると、ローデスは話す。大きなシカも来年育つまで見逃すことが多いという。業界で45年働いて分かったのは、お金よりも心の平穏が大事だということだそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=93s"]]}, {"cat": "家族", "t": "狩りは父に連れられて覚えた", "b": "子どもの頃、父に連れられてテキサスの祖父母の土地で狩りをしたと、ローデスは振り返る。早起きもじっと待つのも嫌いだったが、父はただ一緒にいたかったのだという。一時離れていたが、WCWで仕事が減った頃に再び始め、長男ダスティンとも一緒に行くそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（3:59〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=239s"]]}, {"cat": "リングに来るまで", "t": "マイクの原点は黒人教会の説教", "b": "子どもの頃、父の仕事についてテキサス州バストロップへ行くと、こっそり黒人のバプテスト教会に忍び込み、ゴスペルや説教を聴いていたと、ローデスは話す。黒人や中南米系の人が多い地域で育ったことが、自分の話し方の土台になったという。台本を渡されても、口から出る言葉は自分のものでなければならない、と教えているそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（8:47〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=527s"]]}, {"cat": "リングの話", "t": "「ハード・タイムズ」は準備ゼロの即興", "b": "有名な「ハード・タイムズ」のプロモは、番組を仕切りながら控室から呼ばれ、何も考えずに出て行って口から出た言葉だったと、ローデスは話す。国中が苦しい時期だと分かっていたが、話し出すまで一度も内容を考えなかったという。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（10:22〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=622s"]]}, {"cat": "リングの話", "t": "観客が自分と一緒に痛がるように", "b": "弁護士とは高級レストランで、黒人の家族とはリビングで食事ができる、そんなカウボーイでありたかったと、ローデスは話す。自分が痛がれば客席も痛がり、自分が勝てば客も勝つ、その一体感を作るのが大事だという。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（12:48〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=768s"]]}, {"cat": "暮らし", "t": "育成拠点で「伝える授業」を担当", "b": "WWEの育成拠点で、約80人の若手に週2回、演技ではなく「伝える力」の授業をしていると、ローデスは話す。1分のプロモを切らせ、カメラの赤いランプの向こうの観客にどう伝わるかを見ているという。学校の子どもやメディアへの話し方まで教えているそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（13:38〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=818s"]]}, {"cat": "リングに来るまで", "t": "プロフットボールをクビになり、ボストンで初試合", "b": "1968年、所属していたフットボールチームが解散し、新聞でボストンのプロレス興行を見つけて訪ねたと、ローデスは話す。お金がなく車で寝泊まりし、腕試しのスパーで認められ、翌週には世界王者フランク・スカーパと戦ったという。仲間と金を出し合い、炊き出しで感謝祭の夕食をとったそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（17:40〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=1060s"]]}, {"cat": "リングに来るまで", "t": "最初の平手打ちで「痛がる」ことを学んだ", "b": "父は給料日の金曜にプロレスを見に行くのが楽しみで、自分も裏庭でまねをして育ったと、ローデスは話す。初試合で相手に平手打ちされ、やり返したい気持ちを抑えて「痛がらなきゃ」と思ったのが始まりだという。そこから週7日、日曜は2試合の生活で腕を磨いたそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（23:13〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=1393s"]]}, {"cat": "リングの話", "t": "腰を振る動きは自然に出てきたもの", "b": "腰を振る動きや手を回す仕草は、考えて作ったものではなく、自然に出てきたものだと、ローデスは話す。エルビス・プレスリーが「自然にそうなる」と語っていたのと同じだという。動きの多くは、ドクター・ジェリー・グラハムとサンダーボルト・パターソンから学んだそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（36:25〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=2185s"]]}, {"cat": "リングの話", "t": "大歓声は「麻薬」のようなもの", "b": "会場が自分の名前で揺れる瞬間を一度味わうと、この仕事から離れられなくなると、ローデスは話す。お金ではなく、あの大歓声のために生きているのだという。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（42:05〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=2525s"]]}, {"cat": "家族", "t": "相棒ディック・マードックとのビールの旅", "b": "テキサス・アウトローズとして組んだディック・マードックとは、旅とカントリー音楽とビールを愛する点で同じだったと、ローデスは話す。町に着くとまず会場ではなくビールを買いに行き、毎晩ラジオを聴きながら車で走ったという。ある朝、安宿で目覚めて、一人でやってみようと決めたそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（49:12〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=2952s"]]}, {"cat": "リングの話", "t": "マードックとは兄弟のような関係のまま", "b": "シングルで独り立ちすると伝えたとき、マードックも最初は受け入れられなかったと思うと、ローデスは話す。それでも2人はずっと親しく、コロラドに共同で土地を持ち、一緒に狩りをしたという。マードックを弟のように愛し、最後まで彼を擁護するそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（54:51〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=3291s"]]}, {"cat": "リングの話", "t": "師エディ・グラハムに「タイミング」を学ぶ", "b": "フロリダの興行主エディ・グラハムは、タイミングの天才だったと、ローデスは話す。55分の時点で何をするかまで決められ、守らなければ厳しく叱られたという。言葉にはしなかったが、自分はエディの「プロレスの息子」だったそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（57:14〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=3434s"]]}, {"cat": "リングの話", "t": "「アメリカン・ドリーム」は何げない一言から", "b": "1974年、テレビのインタビューで「誰もがアメリカン・ドリームを持つべきだ」と口にしたら、それが一気に広まったと、ローデスは話す。自分がアメリカン・ドリームだという意味ではなく、みんなに信じてほしかったという。一番好きなプロモは、残り数秒でカメラに「オーランド、愛してる」と言っただけのものだそうだ。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（1:02:50〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=3770s"]]}, {"cat": "家族", "t": "80年代は家族との時間を失った", "b": "一番楽しかったのは70年代で、80年代は頂点にいる重圧から仕事になってしまったと、ローデスは話す。年中巡業で、家にいても心は巡業にあったという。もっと家族を大事にできたはずだ、と振り返っている。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で（字幕を全文確認）", "art": "ext-D_VZsnN2l5k", "src": [["番組のYouTube（1:06:51〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=4011s"]]}]);
  if (PROFILES["Stone Cold Steve Austin"]) PROFILES["Stone Cold Steve Austin"].facts.push({"cat": "暮らし", "t": "オースチンを大スターにしたのは「痛がり方」", "b": "ブレット・ハートとの試合で、血を流しながらシャープシューターに耐え、失神するまで降参しなかった姿を見て、オースチンが大スターになったと確信したと、ローデスが話している。", "sp": "ダスティ・ローデス", "d": "2021-08-11", "how": "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）で、ダスティ・ローデスの話（字幕を全文確認）", "src": [["番組のYouTube（27:14〜）", "https://www.youtube.com/watch?v=D_VZsnN2l5k&t=1634s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-D_VZsnN2l5k", d: "2021-08-11", show: "ext", who: ["Dusty Rhodes"], t: "ダスティ・ローデスの回　狩りと心の平穏、マイクの原点、相棒ディック・マードック", lead: "ストーン・コールドのポッドキャスト（スティーブ・オースチン・ショー）に出た約70分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Dusty Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-D_VZsnN2l5k").map((x) => [x.t, x.b, x.sp])), open: ["投稿は2021年だが、収録はデビュー45年（2013年ごろ）の時期。", "広告の読み上げは除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=D_VZsnN2l5k"]] });
  if (!ROSTER.find((r) => r[1] === "Bryan Danielson")) ROSTER.push(["ブライアン・ダニエルソン", "Bryan Danielson", "gn", "元ダニエル・ブライアン。他団体", "", "", ""]);
  if (!PROFILES["Bryan Danielson"]) PROFILES["Bryan Danielson"] = { lead: "WWEで11年を過ごし、強制引退からの復帰を経てAEWへ移ったブライアン・ダニエルソン。去る決断は怖くも難しかったが、前の職場への愛着は変わらないと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bryan%20Danielson"]], moves: [], facts: [] };
  if (PROFILES["Bryan Danielson"]._weak) { PROFILES["Bryan Danielson"].lead = "WWEで11年を過ごし、強制引退からの復帰を経てAEWへ移ったブライアン・ダニエルソン。去る決断は怖くも難しかったが、前の職場への愛着は変わらないと話す。"; delete PROFILES["Bryan Danielson"]._weak; }
  PROFILES["Bryan Danielson"].facts.push(...[{"cat": "退団の理由", "t": "怖さと興奮が決め手だった移籍", "b": "AEWへの移籍は少し怖く、それが逆に自分を興奮させたとブライアン・ダニエルソンは話す。とても難しい決断だったという。前の職場もそこにいる人たちも好きだったので、自分が離れたこと自体がAEWの魅力を物語っていると考えているそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（4:07〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=247s"]]}, {"cat": "退団の理由", "t": "試合中心の場でやりたかった", "b": "ケニー・オメガらの試合を見て、AEWでは長く激しい試合ができ、物語もリングの中で語られると感じたという。舞台裏のストーリーより試合に重きが置かれる場所で、最高の水準の試合をしたかったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（4:54〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=294s"]]}, {"cat": "退団の理由", "t": "これからの数年を頂点にしたい", "b": "これからの3年ほどは全力で動ける最後の時期になると見ており、キャリアの頂点だと考えているという。今が自分の最高の状態だと感じ、その力を身体的に完全な自由のもとで出したかったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（5:43〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=343s"]]}, {"cat": "WWEでの日々", "t": "強制引退のあとは全てが贈り物", "b": "WWEで引退を余儀なくされ、その後に復帰を認められてからは、何もかもが贈り物のように思えるという。WWE最後期にフィラデルフィアでドリュー・ガラクと戦ったときも、WWEらしくない試合ができたことに深い感謝を覚えたそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（7:19〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=439s"]]}, {"cat": "WWEでの日々", "t": "インディー10年のあとWWEに11年", "b": "インディー団体に10年、その後WWEに11年いたと話す。入団時は独立系の選手という見られ方だったが、WWEの方が長くなったため、ダニエル・ブライアンの名で覚えている人が多いのも理解できるという。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（17:48〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1068s"]]}, {"cat": "WWEでの日々", "t": "CMパンクも名前を言えなかった", "b": "WWE時代、昔から知る人ほど新しい名前に慣れるのに苦労したと振り返る。CMパンクが自分の試合の解説をしたとき、どうしてもダニエル・ブライアンと言えなかったことを覚えているそうだ。NXT時代だったかもしれないと話す。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（18:38〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1118s"]]}, {"cat": "WWEでの日々", "t": "王者の間にイエス・チャントをやめた", "b": "WWEでは長く王者でいた時期に、イエス・チャントの動きをやめたと話す。今は音楽が変わったのに観客がイエス・チャントを続けるため、拍子が二つ混ざって体が少し戸惑うそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（20:16〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1216s"]]}, {"cat": "WWEでの日々", "t": "花道を歩く30〜45秒が落ち着かない", "b": "リングに入れば完全に落ち着くが、WWEの長い花道を歩く30〜45秒はとても居心地が悪かったという。インディー時代はドアから出てすぐリングに向かえたので、時間を埋める入場のパフォーマンスが必要になる理由が分かったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（21:08〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1268s"]]}, {"cat": "WWEでの日々", "t": "野心スコアが歴代最低だった", "b": "WWEが成功した選手たちに性格診断を行い、自分は100点満点で1点という、診断した人が見たことのない低さの野心スコアだったと話す。目標を並べるタイプではなく、上手くなり続けることと今を楽しむことを大切にしているそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（22:47〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1367s"]]}, {"cat": "WWEでの日々", "t": "ショーン・マイケルズの教えと緊張", "b": "ショーン・マイケルズに教わった時代に、試合前に緊張しなくなったら引退のときだと言われたという。実際に引退して復帰してからは、緊張が喜びに近い高揚感に変わったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2021-10-06", "how": "Fight（ファイト）の対談番組「Fight and Focus」で（字幕を全文確認）", "art": "ext-EuBvBiubUBI", "src": [["番組のYouTube（26:01〜）", "https://www.youtube.com/watch?v=EuBvBiubUBI&t=1561s"]]}]);
  ARTICLES.push({ id: "ext-EuBvBiubUBI", d: "2021-10-06", show: "ext", who: ["Bryan Danielson"], t: "ブライアン・ダニエルソンの回　WWEを離れてAEWを選んだ理由", lead: "Fight（ファイト）の対談番組「Fight and Focus」に出た約29分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bryan Danielson"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-EuBvBiubUBI").map((x) => [x.t, x.b, x.sp])), open: ["聞き手の発言とブライアン本人の発言を区別し、本人の話だけを載せた。", "家族・暮らし・体のこと・他団体での日々の話は公開せず控えに回した。", "自動字幕の崩れた固有名詞は、意味が確実なものだけを載せた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=EuBvBiubUBI"]] });
  if (!ROSTER.find((r) => r[1] === "Malakai Black")) ROSTER.push(["マラカイ・ブラック", "Malakai Black", "gn", "元アレイスター・ブラック", "", "", ""]);
  if (!PROFILES["Malakai Black"]) PROFILES["Malakai Black"] = { lead: "WWE時代はアレイスター・ブラック名義で凝った入場演出を経験し、NXTでは台本式のプロモに苦労したという。契約が切れた後は自由の身となり、次の構想を練った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Malakai%20Black"]], moves: [], facts: [] };
  if (PROFILES["Malakai Black"]._weak) { PROFILES["Malakai Black"].lead = "WWE時代はアレイスター・ブラック名義で凝った入場演出を経験し、NXTでは台本式のプロモに苦労したという。契約が切れた後は自由の身となり、次の構想を練った。"; delete PROFILES["Malakai Black"]._weak; }
  PROFILES["Malakai Black"].facts.push(...[{"cat": "WWEでの日々", "t": "WWE時代は装飾の多い入場だった", "b": "以前いた団体では、演出を盛り込んだ手の込んだ入場をしていたと話す。それが悪いわけではないが、自分はミニマルなものが好みだったという。のちに最小限の要素で見せる入場を新たに作ろうと考えたそうだ。", "sp": "マラカイ・ブラック", "d": "2021-10-11", "how": "AEWアンリストリクテッド（AEW公式ポッドキャスト）で（字幕を全文確認）", "art": "ext-0M7bzbG-sNU", "src": [["番組のYouTube（2:29〜）", "https://www.youtube.com/watch?v=0M7bzbG-sNU&t=149s"]]}, {"cat": "WWEでの日々", "t": "アレイスターという名の重み", "b": "アレイスターは旧約聖書を思わせる、重みのある名前だったと話す。そのため新しい名前にも同じ重みを求め、ほかの名を選んだという。名前の移り変わりを、自分にとって大事な転換点として語っている。", "sp": "マラカイ・ブラック", "d": "2021-10-11", "how": "AEWアンリストリクテッド（AEW公式ポッドキャスト）で（字幕を全文確認）", "art": "ext-0M7bzbG-sNU", "src": [["番組のYouTube（9:04〜）", "https://www.youtube.com/watch?v=0M7bzbG-sNU&t=544s"]]}, {"cat": "退団の理由", "t": "契約が切れ、自由契約に戻った", "b": "契約が満了したのは次の舞台に姿を見せる3日前だったと話す。それまでは新しい会社の社長と直接連絡を取れる立場になかったそうだ。自由契約に戻った時点で、次にやりたいことの構想はすでに頭にあったという。", "sp": "マラカイ・ブラック", "d": "2021-10-11", "how": "AEWアンリストリクテッド（AEW公式ポッドキャスト）で（字幕を全文確認）", "art": "ext-0M7bzbG-sNU", "src": [["番組のYouTube（12:16〜）", "https://www.youtube.com/watch?v=0M7bzbG-sNU&t=736s"]]}, {"cat": "WWEでの日々", "t": "NXTで台本式のプロモに苦戦", "b": "NXTでは当初、台本を渡されるやり方を試されたと話す。母語がオランダ語のため、読んだ内容を頭の中で訳して覚えることができず、うまくいかなかったという。要点だけ示されて自分の言葉で話すほうが、役の心から話せると語っている。", "sp": "マラカイ・ブラック", "d": "2021-10-11", "how": "AEWアンリストリクテッド（AEW公式ポッドキャスト）で（字幕を全文確認）", "art": "ext-0M7bzbG-sNU", "src": [["番組のYouTube（46:45〜）", "https://www.youtube.com/watch?v=0M7bzbG-sNU&t=2805s"]]}, {"cat": "WWEでの日々", "t": "台本通りに話すと感情が消える", "b": "書かれた台詞を話すと、自分の感情が自然に出なくなると感じていたそうだ。作り込んだ役柄だからこそ、それは創作を壊されるような感覚だったと話す。活動を始めて最初の3〜4年がとくに苦しく、経験を重ねて楽になったという。", "sp": "マラカイ・ブラック", "d": "2021-10-11", "how": "AEWアンリストリクテッド（AEW公式ポッドキャスト）で（字幕を全文確認）", "art": "ext-0M7bzbG-sNU", "src": [["番組のYouTube（49:08〜）", "https://www.youtube.com/watch?v=0M7bzbG-sNU&t=2948s"]]}]);
  ARTICLES.push({ id: "ext-0M7bzbG-sNU", d: "2021-10-11", show: "ext", who: ["Malakai Black"], t: "マラカイ・ブラックの回　WWE時代の記憶と、自由契約になるまで", lead: "AEWアンリストリクテッド（AEW公式ポッドキャスト）に出た約53分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Malakai Black"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-0M7bzbG-sNU").map((x) => [x.t, x.b, x.sp])), open: ["ほとんどが新しい団体での入場演出や活動の話で、WWE時代に触れたのは数か所のみ。", "契約満了の経緯の詳細や、以前の会社とのやりとりは本人が語っていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=0M7bzbG-sNU"]] });
  if (!ROSTER.find((r) => r[1] === "Brock Lesnar")) ROSTER.push(["ブロック・レスナー", "Brock Lesnar", "lg", "異名 The Beast", "", "", ""]);
  if (!PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"] = { lead: "テレビのない酪農家で育ち、今はカナダの広大な農場で畑と精肉に打ち込む。けた外れの体と裏腹に、金の使い方は堅実で「良い父でいること」を何より大事にしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Brock%20Lesnar"]], moves: [], facts: [] };
  if (PROFILES["Brock Lesnar"]._weak) { PROFILES["Brock Lesnar"].lead = "テレビのない酪農家で育ち、今はカナダの広大な農場で畑と精肉に打ち込む。けた外れの体と裏腹に、金の使い方は堅実で「良い父でいること」を何より大事にしている。"; delete PROFILES["Brock Lesnar"]._weak; }
  PROFILES["Brock Lesnar"].facts.push(...[{"cat": "リングに来るまで", "t": "テレビのない酪農家育ち", "b": "サウスダコタ州ウェブスターの酪農家で育ち、5歳でアマチュアレスリングを始めたという。家にはテレビもなく、働いて暮らしを立てるのに精いっぱいだったそうだ。プロレスを見たのは大学の寮のロビーで流れていたRAWが初めてだったと話す。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=145s"]]}, {"cat": "家族", "t": "けんか早い兄たち", "b": "6歳上の兄が2人いて、地元では「レスナー家はけんか早い」と知られていたという。家の中も戦争のようで、18歳ごろには兄を食器棚に突っ込ませたこともあり、両親はさぞ苦労しただろうと振り返る。母に「どうせなら戦ってお金を稼ぎなさい」と言われたそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（5:44〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=344s"]]}, {"cat": "リングの話", "t": "総合格闘技は本気で準備した", "b": "総合格闘技に挑んだときは、柔術や打撃の一流のコーチを雇い、真剣に取り組んだという。初戦で何百回と対策してきた膝関節技で負けたときは自分に腹が立ち、「もう1試合だけ」とダナ・ホワイトに頼み込んだそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（7:16〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=436s"]]}, {"cat": "リングの話", "t": "ビンスは父親のような存在", "b": "ビンス・マクマホンとは20年、愛憎入り混じった関係だが、若いころに出会い多くを学んだ父親のような存在だという。ダナ・ホワイトとも良い関係で、たくさん稼がせてもらったと笑う。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=580s"]]}, {"cat": "暮らし", "t": "カナダで5000エーカーの農場", "b": "狩りで通っていたカナダのサスカチュワン州で農場を買い、土地を買い足すうちに移住したという。今は小麦などを育てる約5000エーカーの農場を経営しているそうだ。「貧乏な農家の子が、お金ができたから本気で農業をやってみた」と話す。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（12:00〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=720s"]]}, {"cat": "家族", "t": "息子たちには石拾いから", "b": "2人の息子には働くことを教えたいので、楽はさせず、畑の石拾いからやらせているという。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（12:50〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=770s"]]}, {"cat": "好きなもの", "t": "狩りと釣りと雪上バイク", "b": "狩り（弓も銃も）と釣り、氷上の穴釣り、スノーモービルが好きで、家族と静かに過ごすのが一番だという。仕留めた獲物を自宅のガレージでさばいていたが、本格的な精肉小屋を建て、さらに大きくしたいそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（12:50〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=770s"]]}, {"cat": "好きなもの", "t": "動画で学んだ精肉", "b": "コロナ禍の間、精肉の仕方を動画で学び、その動画の人気精肉店の人たちと知り合って意気投合したという。子どもを連れて数日間一緒に解体をし、今は自分の名前のついた調味料も作っていると話す。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（13:40〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=820s"]]}, {"cat": "体のこと", "t": "8年続けるケトジェニック", "b": "肉中心のケトジェニックな食事を8年続けているという。トレーナーとは17年の付き合いで、10〜12年前に重いバーベルをやめ、空気圧式のマシンで鍛えているそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（17:41〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1061s"]]}, {"cat": "リングに来るまで", "t": "恩人は少年時代のコーチ", "b": "今の自分があるのは運と、高校と少年時代のレスリングのコーチのおかげだという。良い親と、本気で気にかけてくれる大人に出会えたことが大きかったと話す。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（18:31〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1111s"]]}, {"cat": "リングの話", "t": "ホテルでの「投げ」は本物", "b": "ロイヤルランブル前に泊まったホテルのレストランで、居合わせたテレビのいたずら番組の一団に絡まれ、メンバーの一人をテーブルに投げ落としたという。あれは台本のない本当の出来事で、勘定を置いてすぐ立ち去ったそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（19:16〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1156s"]]}, {"cat": "リングの話", "t": "殿堂より、良い父でいたい", "b": "殿堂入りや後に残すものには関心がないという。大事なのは良い人間で、良い父親であることだと話す。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（26:41〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1601s"]]}, {"cat": "暮らし", "t": "お金で破産しかけたことも", "b": "今は好きでやっているだけで、お金のためにリングに上がる必要はないという。ただ若いころ、最初の大きな契約の後に破産しかけたこともあり、多くの人から学んで堅実になったそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（30:42〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1842s"]]}, {"cat": "リングの話", "t": "今も緊張する", "b": "20年たった今もリングの前には緊張するが、それも含めて楽しいという。総合格闘技の試合前は、慣れるために自宅に本物の八角形のケージを取り寄せて練習したそうだ。", "sp": "ブロック・レスナー", "d": "2022-02-14", "how": "パット・マカフィーの番組で（字幕を全文確認）", "art": "ext-9PYzlRu6zUQ", "src": [["番組のYouTube（33:02〜）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ&t=1982s"]]}]);
  ARTICLES.push({ id: "ext-9PYzlRu6zUQ", d: "2022-02-14", show: "ext", who: ["Brock Lesnar"], t: "ブロック・レスナーの回　農場、フットボール、プロレス、総合格闘技", lead: "パット・マカフィーの番組に出た約50分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Brock Lesnar"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-9PYzlRu6zUQ").map((x) => [x.t, x.b, x.sp])), open: ["兄たちの若いころのトラブルの詳細は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=9PYzlRu6zUQ"]] });
  if (!ROSTER.find((r) => r[1] === "Keith Lee")) ROSTER.push(["キース・リー", "Keith Lee", "gn", "元NXT王者", "", "", ""]);
  if (!PROFILES["Keith Lee"]) PROFILES["Keith Lee"] = { lead: "三度のトライアウトを経てWWEに入り、体調不良による長い欠場も乗り越えた。解雇から数日でAEW側の連絡を受けたと本人は話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Keith%20Lee"]], moves: [], facts: [] };
  if (PROFILES["Keith Lee"]._weak) { PROFILES["Keith Lee"].lead = "三度のトライアウトを経てWWEに入り、体調不良による長い欠場も乗り越えた。解雇から数日でAEW側の連絡を受けたと本人は話す。"; delete PROFILES["Keith Lee"]._weak; }
  PROFILES["Keith Lee"].facts.push(...[{"cat": "退団の理由", "t": "解雇の数日後にAEWから連絡が来た", "b": "WWEを解雇されてから3日ほどで、AEWのトニー・カーンが連絡を取る手段を見つけて接触してきたという。それまで二人は話したこともなかったが、最初は気楽な雑談から始まったとキースは話す。人は直接会って確かめたい性格で、会ってみて人柄に好感を持ち、やがて仕事の話に進んだそうだ。解雇の理由そのものについては、この回では語っていない。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=336s"]]}, {"cat": "WWEでの日々", "t": "入団前に三度のトライアウトを受けた", "b": "WWEのトライアウトは三度受けていて、うち二つは自力で、最後は2013年に育成施設で開かれた最初のトライアウトだったという。その最後の場でのプロモは自分でも散々な出来で、フットボールをやめてこの道を選んだのは正しかったのかと考え込んだとキースは話す。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（20:13〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=1213s"]]}, {"cat": "WWEでの日々", "t": "ジム・ロスの「100万ドルの才能」", "b": "その最後のトライアウトの終わりに、ジム・ロスが脇へ呼んで、会社の判断がどうであれ君は100万ドルの才能だと信じていると伝えてくれたという。率直な人として知られる相手からの言葉で、深く心に残ったとキースは話す。本人は、ロスは覚えていないかもしれないと言っている。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（21:02〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=1262s"]]}, {"cat": "WWEでの日々", "t": "ダスティ・ローデスとリーガルの支え", "b": "ダスティ・ローデスは最初のトライアウトから見てくれた人で、しゃべりの下手さを指摘する一方、上達すれば誇らしいと言ってくれたという。「栄光に浸れ」という決め台詞の元になったのも、この人の言葉だそうだ。ウィリアム・リーガルも初対面のころからの味方で、二人から受けた影響は、試合での考え方や立ち居振る舞いにまで及んでいるとキースは話す。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（21:49〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=1309s"]]}, {"cat": "WWEでの日々", "t": "体調不良で長く試合から離れた", "b": "2021年の初め、職場で体調を崩して3週間ほど休み、練習に早めに戻って2月8日にマット・リドルと試合をしたという。ところが翌日、会社から検査に異常があるので何もしないようにと連絡があり、ほぼ歩く程度の生活になった。何度かの検査と五時間以上に及ぶ病院での一日を経て、最後に医師から問題はないと告げられ、5週間ほどの調整で復帰できた。あと少しで競技を失うところだったので、今は以前より人生にも仕事にも感謝しているとキースは話す。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（28:11〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=1691s"]]}, {"cat": "WWEでの日々", "t": "アンダーテイカーに言われた言葉", "b": "ずっと前にアンダーテイカーから、何をするにも意味のあるものにしろ、無駄なことはするなと言われたという。以来、インディー時代から一試合ごとに特別な意味を持たせようとしてきて、それが自分の成長を助けたとキースは話す。", "sp": "キース・リー", "d": "2022-03-21", "how": "AEW公式ポッドキャスト AEW Unrestrictedで（字幕を全文確認）", "art": "ext-UnKXtuc0IpY", "src": [["番組のYouTube（41:57〜）", "https://www.youtube.com/watch?v=UnKXtuc0IpY&t=2517s"]]}]);
  ARTICLES.push({ id: "ext-UnKXtuc0IpY", d: "2022-03-21", show: "ext", who: ["Keith Lee"], t: "キース・リーの回　WWEでの歩みと、解雇のあと", lead: "AEW公式ポッドキャスト AEW Unrestrictedに出た約50分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Keith Lee"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-UnKXtuc0IpY").map((x) => [x.t, x.b, x.sp])), open: ["解雇の理由や、WWEを離れる際の会社とのやりとりは、この回では本人がほとんど語っていない。", "体調不良の話は、病名を伏せて要点だけにまとめた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=UnKXtuc0IpY"]] });
  if (!ROSTER.find((r) => r[1] === "Johnny Gargano")) ROSTER.push(["ジョニー・ガルガノ", "Johnny Gargano", "lg", "元NXT王者の人気選手", "", "", ""]);
  if (!PROFILES["Johnny Gargano"]) PROFILES["Johnny Gargano"] = { lead: "生後6週間の息子クイルの子育てに追われる、新米パパのジョニー。ピザ屋ならぬイタリア料理店育ちの「太った少年」の心を、いまも抱え続けている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Johnny%20Gargano"]], moves: [], facts: [] };
  if (PROFILES["Johnny Gargano"]._weak) { PROFILES["Johnny Gargano"].lead = "生後6週間の息子クイルの子育てに追われる、新米パパのジョニー。ピザ屋ならぬイタリア料理店育ちの「太った少年」の心を、いまも抱え続けている。"; delete PROFILES["Johnny Gargano"]._weak; }
  PROFILES["Johnny Gargano"].facts.push(...[{"cat": "家族", "t": "生後6週間の息子との毎日", "b": "ジョニーは妻のキャンディスと、生後約6週間の息子クイルを育てている。睡眠はほとんど取れず、取材の直前にも初めての「漏れ」事件でおむつと着替えに追われたという。二人がかりで服を頭から脱がせたと笑って話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=0s"]]}, {"cat": "家族", "t": "鼻を吸わせる子育ての小技", "b": "お腹がすいた息子は、顔に近づけるとジョニーの鼻に吸いつくそうだ。映画『バットマン リターンズ』のペンギンのようだと笑い、家に来た人に見せて回っていると話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=196s"]]}, {"cat": "家族", "t": "赤ちゃんを抱くのが苦手だった", "b": "もともと他人の赤ちゃんを抱くのが怖かったという。泣かれると人柄まで疑われる気がするからだ。自分の子なら責任は自分にあると思えて、おむつ替えも上達したと話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（4:05〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=245s"]]}, {"cat": "家族", "t": "仲間のパパたちと育児の情報交換", "b": "数週間先に父親になったカイル・オライリーに、睡眠のとり方をたずねているという。向こうは一晩7〜9時間寝ていると聞いて驚いたそうだ。夫婦は、お風呂のあとに包んで白い雑音を流す睡眠ルーティンの本を試している。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（5:42〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=342s"]]}, {"cat": "家族", "t": "48時間のお産のすえ帝王切開に", "b": "出産は誘発分娩で、予定の12〜48時間を使い切るほど長引いたという。胎児の心拍が落ちる場面もあり、最後は帝王切開で生まれた。ジョニーは点滴の気泡まで気にして看護師を呼んだと振り返る。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（8:06〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=486s"]]}, {"cat": "家族", "t": "名前のクイルは妻の発案", "b": "「クイル」は映画『ガーディアンズ・オブ・ザ・ギャラクシー』のスター・ロードの名字にちなむ。考えたのは自分ではなく妻で、2年ほど前から温めていたという。名前を盗まれないよう、教える人を選んでいたそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（12:55〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=775s"]]}, {"cat": "リングの話", "t": "育成ブランドでの最後の夜", "b": "最後の生放送では、自分で書いた言葉で別れを告げられたという。登場前、憧れのショーン・マイケルズに、自分の入場ギアを入れた額を渡し、ショーンが泣き出して自分も泣き出したそうだ。妻がジョニーの涙を見たのはこれが初めてだったと話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（15:19〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=919s"]]}, {"cat": "暮らし", "t": "毎日会っていた仲間と会えなくなる寂しさ", "b": "6年間、育成施設で毎週のように仲間と顔を合わせてきたという。契約が終わりかけた頃にはその友人たちも次々に去り、会えなくなるのが何よりつらいと話す。同じオーランドに住んでいても会わなくなるのが不思議だという。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（18:30〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1110s"]]}, {"cat": "暮らし", "t": "家族と犬と過ごす時間を選んだ", "b": "契約を更新せず、妻と息子と愛犬と過ごす時間を持つことにしたという。退団の意思は約1年前に固めていて、赤ちゃんのことは決断を後押しする形になったそうだ。退団の翌月に妊娠が分かった、という妻の話も紹介された。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（20:04〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1204s"]]}, {"cat": "リングの話", "t": "最後の1年は後輩に場を譲る", "b": "同じキャラが5〜6年続くと飽きられるので、離れて「恋しがられる」ことが大事だと考えていたという。最後の1年は、インディ・ハートウェルやオースティン・セオリー、クシダのような後輩に見せ場を作ることを意識したそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（21:43〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1303s"]]}, {"cat": "体のこと", "t": "ネットの声で心がすり減っていた", "b": "5〜6年テレビに出続け、SNSの「次はこうしろ」という声に打ちのめされた感覚があったという。ファンのためにやる仕事でも、批判に耐えるのが当たり前という考え方には違和感があると語る。創作の自由と楽しさがなくなったら続けたくない、というのが本人の軸だ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（22:31〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1351s"]]}, {"cat": "リングに来るまで", "t": "エキストラ扱いから始まった育成時代", "b": "最初は盟友トマーゾと、空きがないと言われつつ一度きりの大会に出る「エキストラ」だったという。ウィリアム・リーガルが毎週のように出場を推してくれた。のちに二人まとめて正式契約となり、結婚の1〜2週間後にオーランドへ引っ越したが、新婚旅行には行けていないそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（25:46〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1546s"]]}, {"cat": "リングの話", "t": "創作に口を出せるようになった経緯", "b": "入団して2〜3年して大会のメインを任されるようになると、自分でマイクを書き、やりたいことを聞いてもらえるようになったという。以後は大きな方針転換を感じず、一貫して信頼されていたと振り返る。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（28:50〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1730s"]]}, {"cat": "リングの話", "t": "インディー出身者を推す理由", "b": "ヘッドロックは教えられても、プロレスを愛する気持ちはお金では教えられないと話す。自腹で練習し、遠くまで通ってきた人には、それだけで強みがあると考えている。素質のある新人が当たりくじのような存在だということも理解していると語る。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（30:28〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1828s"]]}, {"cat": "リングに来るまで", "t": "8歳でリングに上がった日", "b": "オハイオ州クリーブランドで、父のケータリング会社の砂利の駐車場でインディー団体の興行が開かれた。8歳のジョニーは母が手作りした衣装とスノーブーツで友達と試合をしたという。リングネームは本名のイニシャルからとった「JAG」だった。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（32:04〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1924s"]]}, {"cat": "リングに来るまで", "t": "イタリア料理店で育った少年時代", "b": "父はイタリア料理店とバーを営み、学校帰りはカウンターでチーズラビオリを食べながらアニメを見て過ごしたという。母はポーランド系で、ピエロギは市販品を温めているだけだと笑う。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（35:14〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2114s"]]}, {"cat": "リングに来るまで", "t": "大学へ行かず父の店で働きながら修行", "b": "高校卒業後は大学に進まず、プロレスラーを目指すと決めたそうだ。平日は父の店でケータリングを手伝い、週末に試合をする生活を4〜5年続けたという。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（36:46〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2206s"]]}, {"cat": "体のこと", "t": "インディー時代は「とにかく大きく」", "b": "インディーの頃は体を大きくしろと言われ、サブウェイのダブルミートや大盛りのブリトーボウルを食べていたという。栄養士をつけて数値を管理し始めたのは、NXT時代に入ってからだそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（37:32〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2252s"]]}, {"cat": "体のこと", "t": "腹筋が割れても自分は太って見える", "b": "体の見え方に悩む身体醜形の問題を、レスラーの間でもっと語るべきだと話す。いちばん絞れていた頃も、自分では太っていて不完全に見えたという。画面で自分を見て落ち込み、しばらくテレビから離れたい理由のひとつにもなったそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（39:06〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2346s"]]}, {"cat": "体のこと", "t": "男性が語らない悩みを口にする理由", "b": "自分が悩んでいるなら、同じ思いの人が何百人もいるはずだと考えて話しているという。この感覚は消えないが、「本当にそう見えるのか、頭の錯覚か」と自分に問う癖をつけたと話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（41:28〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2488s"]]}, {"cat": "体のこと", "t": "試合の後は毎回「あれで大丈夫でしたか」", "b": "プロレスだけが得意なことで、いい試合をすれば愛されると思い込んできたという。ネットの一言の悪評だけが一日中残り、1万5千人が沸いた夜でも、カーテンを抜けると周囲に出来を確かめたそうだ。ホテルで落ち込む夜も多かったと妻の存在を挙げて話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（43:05〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2585s"]]}, {"cat": "体のこと", "t": "リングを離れて感じるアイデンティティの揺らぎ", "b": "プロレスが自分のすべてだったので、離れると自分は誰なのかと考えてしまうという。夜中に目が覚める時期もあったが、息子の世話に集中することで今は先のことを考えすぎずにいられると話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（44:42〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2682s"]]}, {"cat": "暮らし", "t": "離れていても毎週プロレスは見ている", "b": "AEWもNXTも見ていて、いまもファンの目で友人たちの活躍を楽しんでいるという。出産の日の分娩室でも、夫婦でエリミネーション・チェンバーを流していたそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（45:31〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2731s"]]}, {"cat": "暮らし", "t": "サイン会は月に3〜4回だけ", "b": "ファンと直接話す楽しさが恋しくなり、サイン会の仕事を月3〜4回に絞って受けているという。夜は家にいたいので、朝に飛んで日帰りできるものを選んでいるそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（47:06〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2826s"]]}, {"cat": "リングの話", "t": "「NXTは金を稼がなかった」は違うと言う", "b": "当時のNXTは1万5千人規模の会場を埋め、アダム・コールとの大会の試合で約100万ドルを動かしたと話す。最盛期にもっと味わっておけばよかった、と今は思うそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（49:33〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=2973s"]]}, {"cat": "リングの話", "t": "全力で飛ぶ姿勢は父になっても変わらない", "b": "ビギーの事故のようにこの仕事は危険だと承知しつつ、ファンへの恩を考えると手を抜けないと話す。守りに入れば「ファンから何かを奪う」気がするそうだ。復帰については、時期も場所もまだ決めず、ふさわしい時に自然と見えてくるはずだと考えている。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（51:12〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=3072s"]]}, {"cat": "好きなもの", "t": "子どもの頃のおもちゃを集め直している", "b": "部屋にはアクションフィギュアが並び、子どもの頃に持っていたものを買い直しているという。アニメ版『スパイダーマン』のシリーズは全部そろえ、プロレスのフィギュアも収集している。息子が大きくなったら、箱を開けて遊んでほしいと話す。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（53:41〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=3221s"]]}, {"cat": "リングの話", "t": "突然のメイン番組への昇格", "b": "クリーブランドで父の誕生日を祝っているとき、突然電話で昇格を告げられたという。北米王座を持ち、NXT王者との試合を準備している最中の出来事で、何の計画も聞かされていなかったそうだ。移動中はトマーゾに頼んで衣装を準備してもらい、重い気持ちで飛んだと振り返る。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（55:14〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=3314s"]]}, {"cat": "リングの話", "t": "計画のない舞台は落ち着かない", "b": "筋書きを知り、持ち時間も分かっているほうが力を出せるタイプだと話す。生放送直前に台本が書き換わる現場では、先が読めずに戸惑ったという。元の育成ブランドに戻る話が出たが、そのまま話は立ち消えになったそうだ。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で（字幕を全文確認）", "art": "ext-FugJwo6iVMI", "src": [["番組のYouTube（1:00:05〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=3605s"]]}]);
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "息子との指さしポーズの写真を約束", "b": "息子の誕生にトリプルHから祝福のメッセージが届いたという。会うときは、あの指さしポーズで一緒に写真を撮ってほしいと頼み、光栄だと答えてもらったと、ジョニー・ガルガノが話している。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で、ジョニー・ガルガノの話（字幕を全文確認）", "src": [["番組のYouTube（1:01:40〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=3700s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "贈り物を受け取って涙したショーン", "b": "退団の登場直前に、入場ギアの額と手書きの手紙を渡したところ、ショーン・マイケルズが泣き出したと、ジョニー・ガルガノが話している。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で、ジョニー・ガルガノの話（字幕を全文確認）", "src": [["番組のYouTube（16:54〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1014s"]], "by": "第三者の話"});
  if (PROFILES["William Regal"]) PROFILES["William Regal"].facts.push({"cat": "暮らし", "t": "二人を毎週のように推してくれた恩人", "b": "ウィリアム・リーガルは、まだ契約がなかった頃から二人の可能性を見込み、番組に出られるよう働きかけてくれたと、ジョニー・ガルガノが話している。", "sp": "ジョニー・ガルガノ", "d": "2022-04-04", "how": "レニー・パケットの番組で、ジョニー・ガルガノの話（字幕を全文確認）", "src": [["番組のYouTube（26:33〜）", "https://www.youtube.com/watch?v=FugJwo6iVMI&t=1593s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-FugJwo6iVMI", d: "2022-04-04", show: "ext", who: ["Johnny Gargano"], t: "ジョニー・ガルガノの回　新米パパの日々と、体と心の話", lead: "レニー・パケットの番組に出た約63分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Johnny Gargano"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-FugJwo6iVMI").map((x) => [x.t, x.b, x.sp])), open: ["「ジョニーはなぜ退団したのか」にまつわる契約や会社への不満の話は、聞き手の質問への答えが中心のため、要点だけにした。", "犬の名前は字幕が崩れていて確信が持てず、載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=FugJwo6iVMI"]] });
  if (!ROSTER.find((r) => r[1] === "Athena")) ROSTER.push(["アテナ", "Athena", "gn", "元エンバー・ムーン", "", "", ""]);
  if (!PROFILES["Athena"]) PROFILES["Athena"] = { lead: "WWE時代はエンバー・ムーンとして活躍したアテナ。育成部門で輝いた後、起用への不満が募り、契約更改を断って去った経緯を率直に語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Athena"]], moves: [], facts: [] };
  if (PROFILES["Athena"]._weak) { PROFILES["Athena"].lead = "WWE時代はエンバー・ムーンとして活躍したアテナ。育成部門で輝いた後、起用への不満が募り、契約更改を断って去った経緯を率直に語る。"; delete PROFILES["Athena"]._weak; }
  PROFILES["Athena"].facts.push(...[{"cat": "WWEでの日々", "t": "引退寸前で受けた最後のトライアウト", "b": "約10年の下積みで望む試合はやり尽くし、インディーでは楽しさも薄れ、引退して普通の仕事に就くつもりだったという。それでも周囲に背中を押され、「最後にもう一度」とトライアウトを受けた。落ちると思っていたが、数日の期間のうち2日目に契約を告げられたと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（13:34〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=814s"]]}, {"cat": "WWEでの日々", "t": "外見を言われ続けた10年と、実力で得た契約", "b": "トライアウトのたびに「もっと痩せろ」「筋肉がつきすぎ」などと言われてきたという。だからこそ、ようやく得た契約は外見ではなく技術と実績で勝ち取ったものとして特別に感じたと話す。セクシーさで売るタイプではないとも語っている。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（17:36〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1056s"]]}, {"cat": "WWEでの日々", "t": "トリプルHの「一緒に考えよう」に救われた", "b": "育成部門で組んでいた相方がドラフトで移籍し、タッグが急に解消された。アテナは戸惑ったが、トリプルHに相談すると「何が起きているか自分も分からない、一緒に考えよう」と言われ、それがありがたかったという。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（21:35〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1295s"]]}, {"cat": "WWEでの日々", "t": "ヒール転向を前に、起用が宙に浮いた", "b": "トリプルHと脚本担当と話し合い、連敗でフラストレーションをためてヒールに転向する案が決まったという。しかし最初の試合の後は数週間テレビに出られず、体調の問題で試合が流れることもあった。別の若手との試合でも転向の表現が曖昧なまま、本人にもヒールになったのか分からない状態だったと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（23:17〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1397s"]]}, {"cat": "WWEでの日々", "t": "旧キャラ復活のため、髪を8時間かけて染め直した", "b": "ヒールとして旧キャラのエンバー・ムーンに戻る指示を受け、髪のエクステを火のような色に自分で染め直したという。1回に最低8時間かかり、コロナ禍で染料の仕入れ先も閉じて、材料探しに多くの費用をかけた。復帰に向けて気持ちは上向いていたと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（25:41〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1541s"]]}, {"cat": "退団の理由", "t": "「無期限でテレビから外す」と告げられた", "b": "撮影した復帰用の映像を見せようとした矢先、無期限でテレビから外すと伝えられたという。理由を聞くと「何も悪くない」と言われ、会社に求められたことはすべてやってきたつもりだったアテナは、深夜の会場で涙をこらえきれなかったと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（26:31〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1591s"]]}, {"cat": "退団の理由", "t": "トリプルHがいなくなってから雰囲気が変わった", "b": "トリプルHが現場を離れた頃から下り坂に入ったと感じていたという。選手に向けて、より肌を見せる衣装にするよう求める長い会議が開かれた。子どもたちのファンを意識してきたアテナは、全員が同じ路線である必要はないと感じ、不満を募らせたと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（29:01〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1741s"]]}, {"cat": "退団の理由", "t": "コーチ役の打診を断り、「飛行機をキャンセルして」と伝えた", "b": "テレビから外す代わりに、後進の指導や非公開の育成番組を手伝ってほしいと言われたという。肘とアキレス腱の手術を経てきた自分に何の見返りもないまま、と感じたアテナは、創作の内容を事前に確認できなければ会場へ行かないと伝えた。言った瞬間に「辞めたかもしれない」と思ったと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（30:36〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1836s"]]}, {"cat": "退団の理由", "t": "更衣室の空気と、すでに用意していた荷造り用の鞄", "b": "退団の数か月前から、更衣室ではねたみや陰口が増えたと感じていたという。アテナは場を前向きに保つ役を担っていたが、荷物をまとめるための鞄をすでにロッカーに置いていたと話す。目指していたのは試合の芸術性であり、メインロースターで離れたはずの空気が戻ってきたと感じたそうだ。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（32:59〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1979s"]]}, {"cat": "退団の理由", "t": "数倍の年俸提示を断った", "b": "契約期間は4月までで、残留すれば現在の約5倍にもなる金額を提示されたという。アテナは「人生が変わる額」と認めつつ、不満を抱えたままでは受けられないと断った。お金で幸せは買えないという判断を、愚かだと言う人もいるだろうと話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（34:38〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=2078s"]]}, {"cat": "退団の理由", "t": "解雇の電話は、ゲームの最中に届いた", "b": "契約満了の約3週間後、幹部から連絡が来たという。アテナは直前の創作担当とのやりとりで察しており、夫が横でお酒を用意する中、電話を受けたと話す。会社側は「解雇ではなく契約解除」と表現し、質問はあるかと聞かれたが、ひとつもないと答えたそうだ。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（37:51〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=2271s"]]}, {"cat": "WWEでの日々", "t": "メインロースターに上がると勢いを失いがち", "b": "育成部門で人気を集めても、上のブランドでは脚本担当が一新され、自分を知っている人が少ないと感じたという。デビュー時に「観客が反応しないかもしれない」と言われた経験も語る。役柄が合わなかったために苦しんだ選手の例を挙げ、番組をまたいだ連携がもっと要ると話す。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（40:16〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=2416s"]]}, {"cat": "WWEでの日々", "t": "他団体の盛り上がりを羨ましく眺めていた", "b": "退団前の数か月、AEWの楽しそうな様子を研究のためでなく、羨ましさから見ていたという。AEWにいる旧知のダスティンに連絡すると「こっちは楽しくやっているよ」と返され、からかわれたと話す。会社からは、競合を見るなという空気もあったそうだ。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（45:43〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=2743s"]]}, {"cat": "WWEでの日々", "t": "育成施設で学んだ客の動かし方が武器になった", "b": "トリプルHやショーン・マイケルズ、マット・ブルームら多くの指導者から、観客の反応を読み、試合の組み立てを変える技術を学んだという。インディーを世界中回っても得られなかった知識が、一か所に集まっていたと話す。この経験が復帰後の試合に活きていると語る。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（48:07〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=2887s"]]}, {"cat": "WWEでの日々", "t": "ラダーからのエクリプスを認めてもらうまで", "b": "年間最大の祭典の一つで、はしごの上から跳ぶ技を提案したが、危険だとして最初は許可が出なかったという。翌年に再び挑み、試合直前になっても最終確認を求められた。時間のない中、一度だけ見せて許可を得たと話す。安全への配慮は理解しつつ、男女で扱いが違うと感じる場面もあったという。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（57:45〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=3465s"]]}, {"cat": "WWEでの日々", "t": "試合中にヘッドセット越しで結末が変わる", "b": "メインロースターでは、試合の途中で結末を変える指示が飛んでくることがあるという。アテナ自身も、試合前から何度も変わった結末が、さらに試合中に変更され、人生で最も焦った経験になったと話す。それでも試合はうまくいったという。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（1:01:44〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=3704s"]]}, {"cat": "WWEでの日々", "t": "WWEでやり遂げたこと", "b": "ベルトを獲り、世界中を回り、多くの強豪と戦い、友人もできたと振り返る。子どもの頃に掲げた目標は叶い、同じ道を歩みながら機会に恵まれなかった人もいるので、不満ばかりは言いにくいと話す。一方で、まだ戦いたい相手や叶えたい目標も残っていたという。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（1:06:25〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=3985s"]]}, {"cat": "退団の理由", "t": "「円満退社」と言われることへの本音", "b": "努力しても「役に立たない」と見られたなら、人の使い方が合わなかっただけではと感じているという。周囲からは円満な別れと言われがちだが、実際には怒りが大きく、自分から離れる決断につながったと話す。悪く言うつもりはなく、いまは前向きだとも語る。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-LsdkTn1E400", "src": [["番組のYouTube（1:10:22〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=4222s"]]}]);
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "トリプルHの現場での姿勢", "b": "育成部門の頃、先が見えない状況で「一緒に考えよう」と声をかけてくれたと、アテナが話している。また、女子選手にも挑戦を許し、「楽しんでおいで、ただしケガはするな」という姿勢で任せてくれたとも話している。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で、アテナの話（字幕を全文確認）", "src": [["番組のYouTube（21:35〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=1295s"]], "by": "第三者の話"});
  if (PROFILES["Vince McMahon"]) PROFILES["Vince McMahon"].facts.push({"cat": "暮らし", "t": "ビンス・マクマホンの事前確認", "b": "はしごからの技を認める直前、「先に見ないと許可しない」とビンス・マクマホンに言われ、慌てて一度だけ試したと、アテナが話している。", "sp": "アテナ", "d": "2022-04-29", "how": "クリス・ヴァン・ヴリートの番組で、アテナの話（字幕を全文確認）", "src": [["番組のYouTube（58:31〜）", "https://www.youtube.com/watch?v=LsdkTn1E400&t=3511s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-LsdkTn1E400", d: "2022-04-29", show: "ext", who: ["Athena"], t: "アテナの回　WWE退団の経緯と、いま感じていること", lead: "クリス・ヴァン・ヴリートの番組に出た約74分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Athena"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-LsdkTn1E400").map((x) => [x.t, x.b, x.sp])), open: ["字幕は自動生成のため、一部の人名の綴りが崩れており、確信の持てない人物名は省いた。", "退団の経緯はすべてアテナ本人の説明であり、会社側の見解は含まれていない。", "夫の名前や家庭の話、AEW以外のインディー団体での出来事は、この項目には載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=LsdkTn1E400"]] });
  if (!ROSTER.find((r) => r[1] === "Toni Storm")) ROSTER.push(["トニー・ストーム", "Toni Storm", "gn", "元NXT UK女子王者", "", "", ""]);
  if (!PROFILES["Toni Storm"]) PROFILES["Toni Storm"] = { lead: "2018年に契約し、NXT UK女子王者にもなったが、メインロースターで楽しめなくなり突然退団した。会社への恨みはなく、自分には合わなかったと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Toni%20Storm"]], moves: [], facts: [] };
  if (PROFILES["Toni Storm"]._weak) { PROFILES["Toni Storm"].lead = "2018年に契約し、NXT UK女子王者にもなったが、メインロースターで楽しめなくなり突然退団した。会社への恨みはなく、自分には合わなかったと話す。"; delete PROFILES["Toni Storm"]._weak; }
  PROFILES["Toni Storm"].facts.push(...[{"cat": "退団の理由", "t": "待機期間と競業避止", "b": "退団後は90日の待機期間があり、その後、突然AEWから連絡が来たという。本人は12か月の競業避止期間があったとも話すが、もう過ぎたことで気にしていないそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=95s"]]}, {"cat": "WWEでの日々", "t": "期待を集めた若手時代", "b": "メイ・ヤング・クラシックに出た頃は大きな注目を集め、NXT UKでは王者にもなった。トニーはWWEで良い時間も過ごしたが、あるところから楽しくなくなり、関わりたくないと思うまでになったと話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（2:21〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=141s"]]}, {"cat": "退団の理由", "t": "メインロースターで感じた違和感", "b": "目標はRAWやSmackDownに上がることだったが、行ってみてすぐ、ここは自分の居場所ではないと気づいたという。26歳で、仕事を楽しみながら良いキャリアを築きたかったが、長く楽しめない状態が続いたと、トニーは話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（3:14〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=194s"]]}, {"cat": "退団の理由", "t": "朝までは辞める気がなかった", "b": "退団を決めた日の朝は、自分が辞めるとは思っていなかったそうだ。何かのスイッチが入ったように突然辞めたと、本人は説明する。その後、90日の待機期間に入ったという。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（3:14〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=194s"]]}, {"cat": "退団の理由", "t": "いつ切られるか分からない不安", "b": "人が突然解雇されるのを目にしていて、自分もいつ切られるか分からないと感じていたという。それなら続ける意味は何なのか、と思えて無意味に感じたそうだ。ファンや業界外の人には伝わりにくいとも、トニーは話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=338s"]]}, {"cat": "WWEでの日々", "t": "WWEで得た思い出と成長", "b": "会社を悪く言うつもりはなく、ほとんどの期間は楽しかったと、トニーは話す。若い年齢で契約し、メイ・ヤング・クラシックを2度経験したことなど、一生大切にしたい思い出があり、そこで大人になったと感じているそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（6:27〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=387s"]]}, {"cat": "WWEでの日々", "t": "NXT UKからアメリカ遠征へ", "b": "2018年に契約を結び、NXT UKでの活動の合間にアメリカにも遠征したという。ロイヤルランブルやサバイバー・シリーズ周辺の興行も経験し、素晴らしいコーチたちと仕事ができたと話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（7:15〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=435s"]]}, {"cat": "退団の理由", "t": "長い間たまっていた不満", "b": "辞めた日の経緯は複雑だったが、積もった不満が前から長くあったという。会社の中は独特の閉じた世界で、日々は過酷だったと話す。このまま行っても成功できず、先が見えてしまったと感じていたそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（8:06〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=486s"]]}, {"cat": "退団の理由", "t": "大切にされていないという思い", "b": "十分に評価されていない、時に敬意も感じられないと思っていたという。やがてプロレスへの愛まで押しつぶされ、プロレスとさえ言えない空気だったと、トニーは話す。プロモでも「プロレス」という言葉は使わないよう指示が来ていたそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（9:47〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=587s"]]}, {"cat": "退団の理由", "t": "好きなのは会社ではなくプロレス", "b": "WWEに入ることが人生の目的だと思っていたが、離れて、自分が好きなのは会社ではなくプロレスそのものだと気づいたという。不幸なまま続けて、世間から恩知らずと言われないことを優先する理由はなかったと、トニーは話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（10:33〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=633s"]]}, {"cat": "退団の理由", "t": "愛が冷めていく恐ろしさ", "b": "プロレスへの愛を失いかけたことは、ひどく怖くて悲しかったという。人生の恋を失うような感覚だったそうだ。NXT時代は出社が楽しみだったのに、頂点とされる場所で自分も周りも疲れていて、そうなりたくないと思ったと話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（11:21〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=681s"]]}, {"cat": "退団の理由", "t": "解放されたときの気持ち", "b": "解雇ではなく契約解除が決まったときは、とにかく早く離れたい気持ちだったという。悪い意味ではなく、あの場所の空気を落としたかったと話す。自分の人生を取り戻す感覚があったそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（12:11〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=731s"]]}, {"cat": "退団の理由", "t": "WWEの外の人生を考えたことがなかった", "b": "10歳の頃からWWEに入るための努力を続けてきて、外の人生は想像したこともなかったという。WWEの王者になることに人生がかかっているなら、それは違うと思うようになったと、トニーは話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（12:58〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=778s"]]}, {"cat": "退団の理由", "t": "決め手は生活の縛り", "b": "最後の決め手は、救急隊員のように常に呼び出しを待つような拘束感だったという。厳しいスケジュールが理由ではなく、インディー時代のほうがずっと忙しかったと、トニーは話す。忙しさは好きだが、あのやり方は違ったそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（14:35〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=875s"]]}, {"cat": "退団の理由", "t": "待機期間中に戻ってきた気持ち", "b": "待機中、ROHの大会に出ないかと声がかかり、また試合をするのだと思うと久しぶりに胸が高鳴ったという。やはりプロレスは大好きで、最高の仕事であって苦しいものであるべきではない、と気づいたと話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（15:24〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=924s"]]}, {"cat": "退団の理由", "t": "合う人もいる、自分は違った", "b": "あの環境で活躍する人がいることは素晴らしいと、トニーは話す。WWEで成功する人もいれば外でも成功する人もいて、合う人には合う方式だという。自分は経験して良かったが、すっきり抜けて今のほうが調子が良いと語る。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（16:13〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=973s"]]}, {"cat": "退団の理由", "t": "合わないなら去ると決めた", "b": "自分が会社に合わないなら、時間を無駄にさせずほかの人に席を譲ればいいと考えたという。恨みはなく、WWEが悪いというより自分に合わなかっただけかもしれないと、トニーは話す。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで（字幕を全文確認）", "art": "ext-xlCx-CP6_YA", "src": [["番組のYouTube（18:40〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=1120s"]]}]);
  if (PROFILES["William Regal"]) PROFILES["William Regal"].facts.push({"cat": "暮らし", "t": "リーガルは頼れる相談相手", "b": "NXT UKの頃から、ウィリアム・リーガルがずっと自分を助けてくれたと、トニー・ストームが話している。今も困ったときには相談できる存在だそうだ。", "sp": "トニー・ストーム", "d": "2022-06-07", "how": "ルネ・パケットの番組 The Sessions with Renee Paquetteで、トニー・ストームの話（字幕を全文確認）", "src": [["番組のYouTube（39:38〜）", "https://www.youtube.com/watch?v=xlCx-CP6_YA&t=2378s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-xlCx-CP6_YA", d: "2022-06-07", show: "ext", who: ["Toni Storm"], t: "トニー・ストームの回　WWEを去った理由とその後の心境", lead: "ルネ・パケットの番組 The Sessions with Renee Paquetteに出た約42分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Toni Storm"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-xlCx-CP6_YA").map((x) => [x.t, x.b, x.sp])), open: ["他団体での活動や私生活の話は、WWEの話ではないため省いた。", "字幕は自動生成で話者の切り替わりが不明瞭な箇所があり、固有名詞が崩れている部分は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=xlCx-CP6_YA"]] });
  if (!ROSTER.find((r) => r[1] === "Alexa Bliss")) ROSTER.push(["アレクサ・ブリス", "Alexa Bliss", "lg", "人気女子スーパースター", "", "", ""]);
  if (!PROFILES["Alexa Bliss"]) PROFILES["Alexa Bliss"] = { lead: "ボディビルからWWEへ、自分で応募した動画がきっかけで入団したアレクサ・ブリス。結婚式の計画やポテト好き、90年代の音楽の話まで気さくに語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Alexa%20Bliss"]], moves: [], facts: [] };
  if (PROFILES["Alexa Bliss"]._weak) { PROFILES["Alexa Bliss"].lead = "ボディビルからWWEへ、自分で応募した動画がきっかけで入団したアレクサ・ブリス。結婚式の計画やポテト好き、90年代の音楽の話まで気さくに語った。"; delete PROFILES["Alexa Bliss"]._weak; }
  PROFILES["Alexa Bliss"].facts.push(...[{"cat": "リングに来るまで", "t": "体操からソフトボールまで多くの競技を経験", "b": "アレクサ・ブリスは子どものころ、体操、チアリーディング、キックボクシング、ソフトボール、陸上など何でもやったと話す。両親がとにかく忙しく習い事を入れてくれたそうだ。大学卒業後は「まだ大人になりたくない」という気持ちもあり、ボディビルに打ち込んでいたという。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（4:55〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=295s"]]}, {"cat": "リングに来るまで", "t": "ボディビルでプロ資格を取り燃え尽きた", "b": "20歳のころ最年少でプロ資格を取ることを目標にし、達成した直後に「もう十分」と思ったという。早朝の有酸素運動、2時間おきの食事、食材の計量、夜のブートキャンプと、厳しい生活を5〜6年続けていたそうだ。当時のトレーナーがWWEの入団テストを教えてくれた。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（5:44〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=344s"]]}, {"cat": "リングに来るまで", "t": "WWEの公式サイトから自分で応募した", "b": "子どものころからWWEを見て育ち、公式サイトの「WWEスーパースターになりたいか」というリンクを押して応募したという。送ったのはビキニ姿のアピール動画で、いま見ると恥ずかしくて仕方ないと話す。応募者のなかで、自分で動画を送ったのは自分だけだったと聞いたそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（6:33〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=393s"]]}, {"cat": "リングに来るまで", "t": "1500人から50人に絞られたロサンゼルスの選考", "b": "動画を送った2週間後に電話があり、約1500人から50人に絞る選考のためロサンゼルスへ呼ばれたという。背の高い女優やモデルばかりで、母に「失敗したかも」とメッセージを送ったほどだったと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（7:22〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=442s"]]}, {"cat": "リングに来るまで", "t": "審査員のトリプルHに話しかけて笑わせた", "b": "面接では印象に残ることを言うよう求められ、トリプルHに「あなたトリプルHですよね」と声をかけたという。志望理由を聞かれて「ディズニーのティンカー・ベルになりたい」と冗談を言い、場が和んだそうだ。実技はなく、10分ほど話しただけだったという。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（8:55〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=535s"]]}, {"cat": "家族", "t": "家族みんながプロレスファンだった", "b": "祖母はダスティ・ローデスと結婚するつもりだったといい、おばはストーン・コールド・スティーブ・オースチンと結婚する気だったそうだ。毎週月曜はピザを囲んで家族でRAWを見て、いとこはハーティ・ボーイズのまねをしていたと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（9:45〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=585s"]]}, {"cat": "リングに来るまで", "t": "合格の連絡は急に決まった", "b": "ロサンゼルスの選考のあと、30日間の試験に進む連絡が来たが、その約1週間後に「試験は不要、採用する。3か月後にフロリダへ引っ越して」と告げられたという。21歳で入団し、いまは30歳だと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（10:33〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=633s"]]}, {"cat": "リングに来るまで", "t": "初日は何も分からずリングに立った", "b": "リングで練習した経験が一度もなく、ロープの固さにも驚いたという。当時のコーチが辛抱強く教えてくれたと感謝を語っている。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（11:23〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=683s"]]}, {"cat": "リングの話", "t": "最初のキャラは明るすぎて没になった", "b": "最初はティンカー・ベル風の自分らしいキャラでデビューしたが、脚本家に「一面的で共感しにくい」と言われたという。悪役側でブレイクとマーフィーと組むことになり、どう意地悪になるか悩んだそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（13:48〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=828s"]]}, {"cat": "リングの話", "t": "高校時代のいじめの経験を悪役づくりに生かした", "b": "「男子は夢中になるが、女子には嫌われる高校の女王」のような人物を目指し、自分が高校でいじめられた経験も材料にしたという。演じるうちに、自分とは別人になるのがとても楽しくなったと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（14:35〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=875s"]]}, {"cat": "リングの話", "t": "控室を行き来して気持ちを切り替える", "b": "舞台裏では歩き回りながら少しずつ意地悪な気持ちを高めるという。演技のコーチに習った、感覚を思い出して感情をつくる方法も使うそうだ。母と最後に会う場面を想像して涙を出す練習が最初の課題だったと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（16:11〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=971s"]]}, {"cat": "リングの話", "t": "入場前は今でもとても緊張する", "b": "入場のたびに強い不安があるが、ランプを歩ききれば、あとはキャラクターに切り替わると話す。リングの広さはどこでも同じなので、そこが安心できる場所だという。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（17:51〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1071s"]]}, {"cat": "リングの話", "t": "キャラクターはこれまで8種類ほど", "b": "最近の不気味な人形を持つキャラクターは、パートナーだった人の助けも借りて作ったという。子どものころに見た幼児番組のピエロと人形、映画『エスター』から着想を得たそうだ。人形のリリーは自分でラフ画を描いて依頼し、グッズとしても売れ行きがよかったと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（19:26〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1166s"]]}, {"cat": "リングの話", "t": "ハロウィンで子どもたちがまねをしてくれた", "b": "ハロウィンで自分の仮装をする人が大勢いて、子どもがポーズや入場のしぐさをまねする動画も見たという。子どもに響いていることが何よりうれしいと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（21:01〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1261s"]]}, {"cat": "リングの話", "t": "初めての王座戦は新人のころに訪れた", "b": "NXTでは試合数が少なく、付き人役が中心だった時期に、ベッキー・リンチとテーブルが使える試合で初めて王座を獲得したという。当時は「レッスルマニアに出られるのも5年は先」と母に話していて、王座を取ってから慌てて切符を買うよう頼んだそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（25:49〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1549s"]]}, {"cat": "リングの話", "t": "仲のよいエンバー・ムーンとの失敗談", "b": "ロープが緩んだ試合で、エンバー・ムーンの飛び技が高く上がりすぎて落ちた際、受け止めきれずマットに落としてしまったという。その場はアドリブで切り抜け、今では会うたびに笑い合うそうだ。エンバーは自分の結婚式の付き添い役でもある。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（29:05〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1745s"]]}, {"cat": "暮らし", "t": "年間を通して移動の連続", "b": "非テレビの興行も含めて、家にいられるのは週に1日か1日半ほどだという。休みなく旅を続けるせいで、止まると「飛行機に乗らなきゃ」と落ち着かなくなると話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（30:37〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1837s"]]}, {"cat": "暮らし", "t": "今は食事制限をしない", "b": "ボディビル時代の厳しさへの反動で、巡業中は食事管理をほとんどしないという。フライドポテトが大好きで、ニュージャージーの店のポテトを特においしいと話す。家族に似て代謝が良いのだとも話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（31:24〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1884s"]]}, {"cat": "好きなもの", "t": "ポテトは「揚げ具合を混ぜる」派", "b": "ハンバーガーチェーンでは、よく揚げたものと普通のものを2袋頼んで混ぜるのが好きだという。外はカリッと、中はやわらかく、少し油を感じるくらいが理想らしい。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（32:59〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1979s"]]}, {"cat": "暮らし", "t": "婚約者ライアン・カブレラとの結婚式の計画", "b": "4月にカリフォルニア州で、型にはまらない式を開く予定だと話す。ケーキはなく、新郎新婦ともに男女の付き添いがいて、バーガーとポテトとフードトラックを用意するそうだ。式のあとはカクテルアワーに参加し、一日中お礼を言って回らずに楽しむつもりだという。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（34:41〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2081s"]]}, {"cat": "暮らし", "t": "計画が苦手で準備は婚約者に任せている", "b": "旅の多い生活のせいで、先の予定を決めるのが苦手だという。ライアンが計画好きで、好みも似ているため、結婚式の準備は任せて助かっていると話す。ドレスは伝統的だが派手な特注品だそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（38:45〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2325s"]]}, {"cat": "好きなもの", "t": "最初に行ったコンサートはボウリング・フォー・スープ", "b": "初めて行ったコンサートはオハイオの州のお祭りでの、ボウリング・フォー・スープだったという。ゲームの取材で好きなバンドを聞かれて彼らの名を挙げ、それを知ったボーカルのジャレット・ダットンと交流が始まったそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（39:30〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2370s"]]}, {"cat": "好きなもの", "t": "誕生日に自分の曲が贈られた", "b": "誕生日に、バンドから自分をテーマにした曲が贈られ、泣いたという。ミュージックビデオにも出演し、クリスマスイブに撮影した。ライアンとも、ジャレットの知り合いという共通点があったそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（41:08〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2468s"]]}, {"cat": "暮らし", "t": "出会った有名人に緊張して余計なことを言いがち", "b": "リン＝マニュエル・ミランダとは互いのファンだと分かって喜んだという。憧れのバンドのメンバーには子どものころのコンサートの話を持ち出して気まずくなり、テイラー・ハンソンには昔のファンだったことを婚約者に暴露されたと、笑いながら話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（42:46〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2566s"]]}, {"cat": "暮らし", "t": "体調が最悪だった機内で偶然出会った人物", "b": "咳が止まらない状態で飛行機に乗り、降りるときに前の席の人物がジョーイ・ファトーンだと気づいて気まずくなったという。のちにライアンを通じて再会し、あの機内にいたことを謝ったそうだ。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（46:01〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2761s"]]}, {"cat": "好きなもの", "t": "『ナポレオン・ダイナマイト』が好きで子ども時代は変わり者", "b": "子ども時代は、ほかの子がファッションに興味を持つなか、風変わりな服装で通っていたという。ハロウィンではライアンと映画の仮装をし、レストランで曲が流れるとトイレから飛び出して踊ったと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（47:39〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=2859s"]]}, {"cat": "好きなもの", "t": "音楽は90年代と2000年代ばかり", "b": "スマホにも昔の曲しか入れていないという。結婚式の音楽も90年代・2000年代の曲にするそうだ。ヒップホップも大好きで、カラオケの定番だと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（50:07〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=3007s"]]}, {"cat": "暮らし", "t": "ライアン・カブレラとの出会い", "b": "ライアンの公式SNSが自分の投稿に「いいね」を重ね、噂が広まったのがきっかけだという。会ってみると、数都市連続で同じ街にいるなど予定が重なり、友人から恋人になった。外出自粛の時期に関係が一気に進んだと話す。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（51:43〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=3103s"]]}, {"cat": "暮らし", "t": "ゲームやフィギュアになった喜び", "b": "ゲームのキャラクターや人形になったことが夢のようだと話す。子どものころ、先生に「バービー人形にはなれない」と言われた話を、人形をもらったときに先生へ投稿したそうだ。兄弟はおらず、婚約者の甥とゲームの話ができるのもうれしいという。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（55:49〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=3349s"]]}, {"cat": "好きなもの", "t": "もし組むならエミネムやアイス・キューブ", "b": "社外のタッグパートナーなら、ラップが大好きなのでエミネムかアイス・キューブがいいと話す。カラオケはN.W.A.やエミネムが定番で、ゴルフのイベントで酔った勢いでリュダクリスを歌った話もしている。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-08xUUKmp2Xg", "src": [["番組のYouTube（57:22〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=3442s"]]}]);
  if (PROFILES["Ember Moon"]) PROFILES["Ember Moon"].facts.push({"cat": "暮らし", "t": "試合中に落としてしまった親友", "b": "ロープが緩んで飛び技が失敗し、受け止められなかったが、笑い話になっていると、アレクサ・ブリスが話している。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で、アレクサ・ブリスの話（字幕を全文確認）", "src": [["番組のYouTube（29:05〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1745s"]], "by": "第三者の話"});
  if (PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"].facts.push({"cat": "暮らし", "t": "初タイトル戦の相手として感謝", "b": "初の王座戦で一緒に戦ったことに感謝しており、とても組みやすい相手だったと、アレクサ・ブリスが話している。", "sp": "アレクサ・ブリス", "d": "2022-06-14", "how": "ザ・レジデンシー・ポッドキャストの番組で、アレクサ・ブリスの話（字幕を全文確認）", "src": [["番組のYouTube（25:49〜）", "https://www.youtube.com/watch?v=08xUUKmp2Xg&t=1549s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-08xUUKmp2Xg", d: "2022-06-14", show: "ext", who: ["Alexa Bliss"], t: "アレクサ・ブリスの回　応募動画から婚約者との結婚式まで", lead: "ザ・レジデンシー・ポッドキャストの番組に出た約64分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Alexa Bliss"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-08xUUKmp2Xg").map((x) => [x.t, x.b, x.sp])), open: ["字幕に話者名がなく、ライアン・カブレラ関連の細部（SNSの経緯など）は聞き取りに揺れがあるため一部省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=08xUUKmp2Xg"]] });
  if (!ROSTER.find((r) => r[1] === "Claudio Castagnoli")) ROSTER.push(["クラウディオ・カスタニョーリ", "Claudio Castagnoli", "gn", "元セザーロ。他団体", "", "", ""]);
  if (!PROFILES["Claudio Castagnoli"]) PROFILES["Claudio Castagnoli"] = { lead: "ROHからWWEへ渡って11年を過ごし、2022年に静かに退団。王座に届かない時期の迷いも含め、自分の道を信じて進んだ歩みを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Claudio%20Castagnoli"]], moves: [], facts: [] };
  if (PROFILES["Claudio Castagnoli"]._weak) { PROFILES["Claudio Castagnoli"].lead = "ROHからWWEへ渡って11年を過ごし、2022年に静かに退団。王座に届かない時期の迷いも含め、自分の道を信じて進んだ歩みを語る。"; delete PROFILES["Claudio Castagnoli"]._weak; }
  PROFILES["Claudio Castagnoli"].facts.push(...[{"cat": "WWEでの日々", "t": "WWE時代も自問を重ねた", "b": "WWEでは世界王座に届かず、「この選択でよかったのか」と悩んだ時期があったと話す。試合が思うようにいかない夜や、しばらくテレビで使われない時期は特にそうだったという。そんなとき、ライブ会場の観客の大歓声に、忘れられていないと励まされたそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（5:39〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=339s"]]}, {"cat": "退団の理由", "t": "退団は熟慮と「自分に賭ける」で決めた", "b": "WWEを離れるまで、かなり考えたと話す。しばらく前から変化が必要だと感じていて、周囲の何気ない言葉がいくつも背中を押したという。決め手のひとつは、育成施設出身の後輩が最後の語りで口にした「自分自身に賭けろ」という言葉だったそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（9:34〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=574s"]]}, {"cat": "退団の理由", "t": "退団を大きく発表しなかった理由", "b": "11年いた会社を去るとき、あえて大げさに発表しなかったと話す。去る人が対戦したい相手の一覧を出す流行に逆らい、静かに去れば次に現れたときの驚きが大きいと考えたという。プロレスは「瞬間」がすべてで、言葉より行動で示したかったと本人は話す。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（10:23〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=623s"]]}, {"cat": "退団の理由", "t": "新しい挑戦と対戦相手を求めた", "b": "やりたい対戦相手の数は、WWEに残る選手より他団体のほうが多かったと話す。根っこには常に上達したい、新しい挑戦をしたいという思いがあったという。最初にROHからWWEへ移ったときも、テレビに出たいからではなく、次の段階に進むためだったそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（11:59〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=719s"]]}, {"cat": "WWEでの日々", "t": "ROHからWWEへ移った動機", "b": "ROHで多くを経験したあと、次の挑戦の場として、最高の選手が集まるWWEを選んだと話す。出世よりも「次の段階」に進みたい気持ちが先にあったという。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（12:45〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=765s"]]}, {"cat": "WWEでの日々", "t": "頂点に近づいては方針が変わった", "b": "観客の支持を得て勢いに乗りかけた場面が何度もあり、頂点が見えたと感じたこともあったと話す。ただ、そのたびに会社の方針が変わって振り出しに戻ることが何度もあったという。それでも、すべては旅の一部で、今につながったと受け止めているそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（14:20〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=860s"]]}, {"cat": "WWEでの日々", "t": "「カリスマ性がない」との評に", "b": "当時の会社のトップが番組で「カリスマ性が足りない」と評したと聞かれ、自分は違うと思ったと話す。カリスマにはいろいろな形があり、自分はリング上の動きで世界中のファンとつながってきたという。長い語りが必要ない分、言葉の壁を越えて届くと考えているそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（16:42〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1002s"]]}, {"cat": "WWEでの日々", "t": "ポール・ヘイマンとの組み合わせ", "b": "ヘイマンと組んだのは、年間最大の祭典で無敗記録が止まった直後だったと話す。同じ頃にジャック・スワガーとのタッグを解消し、自分は本来悪役のはずが観客に好かれ、ややこしい状況だったという。結局は不運が重なったと考えているそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（18:21〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1101s"]]}, {"cat": "WWEでの日々", "t": "壊れてしまった優勝トロフィー", "b": "大人数のバトルロイヤルで勝ったとき、あまりに重いトロフィーを自分で持ち上げ、控室まで運んだという。翌日に台車で運ばれる途中、ケーブル用の小さなスロープで倒れて粉々に割れたそうだ。接着して倉庫に保管されており、本人の手元には最初のプレートだけがあると話す。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（20:44〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1244s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典で少年と対戦", "b": "試合の直前までマッチメイクの相手が知らされず、同じ日の数時間前に会った少年だったと後から知ったという。試合は大がかりな入場演出もあって楽しく、客席の子どもが「自分もなれる」と思える瞬間になったと話す。あの試合に出られたことを誇りに思っているそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1638s"]]}, {"cat": "WWEでの日々", "t": "レフェリーを巻き込んだ悪ふざけ", "b": "3WAYタッグの初日、フィニッシュの伝え忘れでレフェリーが恥をかいたという。翌日は全員で正確に伝えたが、技の途中でカウントが乱れ、またレフェリーが失態を見せてしまったそうだ。試合後に激怒されたが、全員が笑いをこらえきれなかったと話す。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（32:06〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1926s"]]}, {"cat": "WWEでの日々", "t": "タイソン・キッドとのタッグ結成", "b": "タイソン・キッドとのタッグ結成は、ツイッターで知ったと話す。もともと友人だったが、組んだのはその夜が初めてで、すぐに息が合ったという。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（34:28〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=2068s"]]}, {"cat": "WWEでの日々", "t": "シェイマスとの連戦からタッグへ", "b": "シェイマスと何試合も続けて戦う連戦があり、最後は引き分けのあとタッグを組む流れになったと話す。この案はミック・フォーリーの発案だったという。ファンに終わってほしくないと思われたことが、良い企画だった証拠だと考えているそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（35:17〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=2117s"]]}, {"cat": "WWEでの日々", "t": "ザ・バー時代の思い出の試合", "b": "好きな試合を一つに絞るのは苦手だと話す。年間最大の祭典での6人タッグ、ボルチモアのケージ戦、30分のアイアンマン戦などが記憶に残っているという。シェイマスとは兄弟のような関係で、世界各地のライブでも楽しく戦ったそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（36:03〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=2163s"]]}, {"cat": "WWEでの日々", "t": "育成時代、タイラー・ブリーズとの初対戦", "b": "育成施設に入ってすぐの初めてのテレビ収録で、タイラー・ブリーズと対戦したという。相手を持ち上げて下ろしながらアッパーを打つ場面で、相手の受けが見事で周囲の評価が一気に上がったそうだ。以来、親友になったと話す。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（48:09〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=2889s"]]}, {"cat": "WWEでの日々", "t": "2020年のUNO動画は楽しみ優先", "b": "2020年にブリーズと配信していたUNOの動画は、誰も見なくても続けていたと話す。日曜の夜10時に収録を始めても、おしゃべりが長引いて0時になることがよくあったという。素の姿を見せられたのがうれしかったそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（50:32〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=3032s"]]}, {"cat": "退団の理由", "t": "新体制になっても考えは変わらない", "b": "トリプルHが指揮を執るようになっても、自分の考えは変わらないと話す。自分がいたときは別の体制で、過去は変えられず、そこから学ぶだけだという。今の居場所に心から満足していると語る。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（56:55〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=3415s"]]}, {"cat": "WWEでの日々", "t": "ヘイマンから学んだこと", "b": "ヘイマンとの組み合わせがうまくいかなかった理由について、本人は憶測と断ったうえで、無敗記録を止めた選手の話をするための起用だったと話す。その後その選手が戻り、自然に組む機会が減ったという。それでも約4カ月は移動を共にして多くを学べた、良い経験だったと振り返っている。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（57:41〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=3461s"]]}, {"cat": "WWEでの日々", "t": "CMパンクが去った日の控室", "b": "CMパンクと試合が組まれていた最後の日、クリーブランドの通路で、帰ろうとするパンクと会ったという。その場で試合が消えたことを本人から知らされたそうだ。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で（字幕を全文確認）", "art": "ext-Iv_estB1S2A", "src": [["番組のYouTube（1:04:03〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=3843s"]]}]);
  if (PROFILES["Mark Henry"]) PROFILES["Mark Henry"].facts.push({"cat": "暮らし", "t": "マーク・ヘンリーの怪力", "b": "トレーニング中にマーク・ヘンリーが懸垂を軽々こなし、そのまま約250kgのデッドリフトを平然と上げたと、クラウディオ・カスタニョーリが話している。人類史上最も強い人物ではないかと語っている。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で、クラウディオ・カスタニョーリの話（字幕を全文確認）", "src": [["番組のYouTube（25:37〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1537s"]], "by": "第三者の話"});
  if (PROFILES["Big Show"]) PROFILES["Big Show"].facts.push({"cat": "暮らし", "t": "ビッグ・ショーの規格外の力", "b": "ある試合でビッグ・ショーに飛びかかったところ、空中でそのまま掴まれ、猫を抱え上げられたように宙づりになったと、クラウディオ・カスタニョーリが話している。とんでもない力だったという。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で、クラウディオ・カスタニョーリの話（字幕を全文確認）", "src": [["番組のYouTube（25:37〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=1537s"]], "by": "第三者の話"});
  if (PROFILES["Sheamus"]) PROFILES["Sheamus"].facts.push({"cat": "暮らし", "t": "シェイマスとは兄弟のよう", "b": "シェイマスとは兄弟のような関係で、世界各地のライブ会場でも楽しく試合ができたと、クラウディオ・カスタニョーリが話している。", "sp": "クラウディオ・カスタニョーリ", "d": "2022-09-13", "how": "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）で、クラウディオ・カスタニョーリの話（字幕を全文確認）", "src": [["番組のYouTube（37:43〜）", "https://www.youtube.com/watch?v=Iv_estB1S2A&t=2263s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Iv_estB1S2A", d: "2022-09-13", show: "ext", who: ["Claudio Castagnoli"], t: "クラウディオ・カスタニョーリの回　WWE11年と退団の決断", lead: "クリス・ヴァン・ヴリートの番組 Insight（ライブ収録）に出た約73分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Claudio Castagnoli"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Iv_estB1S2A").map((x) => [x.t, x.b, x.sp])), open: ["「退団の理由」と「WWEでの日々」以外の話題（家族、体づくり、趣味、他団体での日々など）は公開項目から省いた。", "字幕は自動生成のため、固有名詞が崩れている箇所があり、確信の持てない名前は載せていない。", "会場の質疑応答では、ファンの質問に答える形で語られた話を、本人の発言の範囲で要約した。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Iv_estB1S2A"]] });
