  if (!PROFILES["Solo Sikoa"]) PROFILES["Solo Sikoa"] = { lead: "プロレス一家の末っ子として、巡業先の楽屋で育ったソロ・シコア。初めて受けた取材で、家族への敬意と大きな野心をまっすぐに語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Solo%20Sikoa"]], moves: [], facts: [] };
