  PROFILES["Solo Sikoa"].facts.push(...[{"cat": "リングの話", "t": "6万人の前でのデビューは寝耳に水", "b": "主力ロスターへの登場の仕方は、連絡を受けるまで全く予想していなかったという。6万人の観客の前に出た夜は、いまも信じられない気持ちだと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=94s"]]}, {"cat": "リングの話", "t": "家族と頂点に立てるのが何より楽しい", "b": "家族と同じ最高の舞台に立てることが、いちばんの楽しみだという。血のつながった仲間と一緒にいられるうえ、サミ・ゼインも名誉ファミリーのように思っていると話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（2:22〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=142s"]]}, {"cat": "家族", "t": "兄たちとは8〜9歳差の末っ子", "b": "兄たちとの年の差は8、9歳ほどで、ソロ・シコアは家族の中でいちばん年下だと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（2:35〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=155s"]]}, {"cat": "リングに来るまで", "t": "レスリングは昔から心の中にあった", "b": "物心ついたころから、いつかレスリングをやってみたい気持ちがあったという。何をして育ったとしても、最後はこの世界に戻ってきただろうと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=190s"]]}, {"cat": "家族", "t": "金髪の父のデビューをテレビで見た夜", "b": "ソロ・シコアは1993年生まれ。小学生のころ、学校の前夜に家族みんなでテレビに集まり、金髪の父がデビューする場面を見たそうだ。昨日まで見ていた父と別人のようで驚き、そこから一気に人気が出たと振り返っている。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（3:55〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=235s"]]}, {"cat": "家族", "t": "父は人気が出るまで何度もキャラを変えた", "b": "父は大きな成功をつかむまで、5つほどのキャラクターを経験したという。金髪の大柄な父は、どこへ行っても気づかれる有名人だったと、ソロ・シコアは笑って話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=287s"]]}, {"cat": "家族", "t": "学校より巡業先の楽屋にいた子ども時代", "b": "子どものころは学校にいるより、父について巡業先を回る時間のほうが長かったという。楽屋で多くのレジェンドに会い、誕生日を会場で過ごしたことも、大きな祭典に何度も連れていってもらったこともあると話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（6:18〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=378s"]]}, {"cat": "リングに来るまで", "t": "本命はアメフト、プロレスは保険だった", "b": "プロレスはいつでも戻れる場所だと思い、アメフトでNFL入りを第一志望にしていたという。家族にその道へ進んだ人がいなかったので、挑戦したかったそうだ。うまくいかなくなって家業に足を踏み入れ、すぐに夢中になったと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（7:05〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=425s"]]}, {"cat": "リングに来るまで", "t": "家で技をまねて遊んだ少年時代", "b": "父や叔父たちの試合を見て、自分にもできると思っていたという。ソファや寝室で兄弟と技をまねて遊んだそうだ。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（8:41〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=521s"]]}, {"cat": "リングに来るまで", "t": "基礎は父から習い、勘は家族の姿から", "b": "本格的に習ったのは父からで、受け身やロープワークなど基礎を学んだという。経験年数を聞かれると驚かれることが多いが、家族を見て育った本能のおかげだと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（9:30〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=570s"]]}, {"cat": "リングに来るまで", "t": "練習は約3年、父の指導は1年ほど", "b": "本格的な練習とレスリングを始めて約3年で、コロナ禍で1年ほど空いたという。父の指導を1年受けたあと、インディー団体に送り出され、実戦で覚えていったと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（10:18〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=618s"]]}, {"cat": "リングの話", "t": "家族の良いところを全部混ぜたスタイル", "b": "叔父のウマガやヨコヅナ、父、兄たち、ローマン・レインズの良さを一つに混ぜたのが自分のスタイルだという。兄たちのように飛べて、叔父や父のようなパワーもあると話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（10:50〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=650s"]]}, {"cat": "リングの話", "t": "上を見続ける限り、頂点に太陽はない", "b": "自分の可能性を聞かれ、すべてを手に入れたいと答えている。ただしそれは家族みんなで、という意味で、止まるつもりはないと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（11:53〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=713s"]]}, {"cat": "リングの話", "t": "サミ・ゼインは家族のうるさい弟分", "b": "踊って騒ぐが、困ると兄たちのところへ逃げてくる弟分のような存在だと、ソロ・シコアは話す。何百万人に一人のキャラクターで、話術もリングの技も真剣に磨く職人だという。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（13:27〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=807s"]]}, {"cat": "家族", "t": "ローマンは昔、兄たちの遊び相手だった", "b": "ローマン・レインズは兄たちと同じ世代で、子どものころは自宅によく来て兄たちと遊んでいたという。年の差があり、ソロ・シコア自身はあまり親しくなかったが、いま同じ世界で働くようになって距離が縮まりつつあると話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（15:03〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=903s"]]}, {"cat": "リングの話", "t": "カーディフの夜はほぼ無言で集中していた", "b": "大一番の前、ローマン・レインズからは「タイミングを外さないように」と言われたという。控室は静かで、お互いに自分のやるべきことに集中していたそうだ。試合後はひとこと「良かった」と言われたと話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（15:49〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=949s"]]}, {"cat": "リングの話", "t": "トリプルHとの初対面は昇格の日", "b": "トリプルHとは主力ロスターに上がる日が初対面だったという。事務所に呼ばれて昇格を告げられ、試合のあとも毎回アドバイスをもらえているそうだ。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（16:38〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=998s"]]}, {"cat": "リングの話", "t": "ポール・ヘイマンにはいつも相談する", "b": "ポール・ヘイマンは家族と40年ほどの付き合いだという。ソロ・シコアは会うたびに、どう動くか、何を言うかを相談していると話す。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（17:29〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=1049s"]]}, {"cat": "家族", "t": "双子の兄たちは今も張り合っている", "b": "兄たちは双子で、今でもお互いに競い合っているという。バスケットボールやゲームでも勝負していて、ソロ・シコアは子どものころからそれを横で見ていたそうだ。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（18:19〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=1099s"]]}, {"cat": "リングの話", "t": "戦ってみたい相手はレイ・ミステリオ", "b": "家族ぐるみの付き合いがあるレイ・ミステリオと、いつか戦いたいと話す。デビュー戦の相手だったドリュー・マッキンタイアも印象深く、いずれは兄たちと戦うのもいいと語っている。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で（字幕を全文確認）", "art": "ext-T0nYJybH3Ec", "src": [["番組のYouTube（19:05〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=1145s"]]}]);
  if (PROFILES["Rikishi"]) PROFILES["Rikishi"].facts.push({"cat": "暮らし", "t": "リキシ：何度もキャラを変えて掴んだ成功", "b": "デビュー後の長い下積みで5つほどのキャラクターを経験し、金髪の姿で一気に人気が出たと、ソロ・シコアが話している。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で、ソロ・シコアの話（字幕を全文確認）", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=287s"]], "by": "第三者の話"});
  if (PROFILES["Sami Zayn"]) PROFILES["Sami Zayn"].facts.push({"cat": "暮らし", "t": "サミ・ゼイン：騒がしい弟分で職人肌", "b": "踊って目立つ一方、困ったときは兄たちに頼る愛されキャラで、話術も試合も真剣に磨く職人だと、ソロ・シコアが話している。", "sp": "ソロ・シコア", "d": "2022-10-12", "how": "Rosenberg Radio（ロゼンバーグ・レディオ）の番組で、ソロ・シコアの話（字幕を全文確認）", "src": [["番組のYouTube（13:27〜）", "https://www.youtube.com/watch?v=T0nYJybH3Ec&t=807s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-T0nYJybH3Ec", d: "2022-10-12", show: "ext", who: ["Solo Sikoa"], t: "ソロ・シコアの回　末っ子が語る家族とデビューの夜", lead: "Rosenberg Radio（ロゼンバーグ・レディオ）の番組に出た約22分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Solo Sikoa"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-T0nYJybH3Ec").map((x) => [x.t, x.b, x.sp])), open: ["聞き手の発言とゲストの発言が続けて書かれた字幕のため、話者が曖昧な箇所は載せていない。", "ローマン・レインズの話は、年齢差などあいまいな数字を省いている。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=T0nYJybH3Ec"]] });
  if (!ROSTER.find((r) => r[1] === "Talla Tonga")) ROSTER.push(["タラ・トンガ", "Talla Tonga", "lg", "タマ・トンガの兄弟", "", "", ""]);
  if (!PROFILES["Talla Tonga"]) PROFILES["Talla Tonga"] = { lead: "フロリダ育ちで、トンガ系の厳しくも温かい家庭に支えられてきた長身の選手。食べ歩きの動画と音楽、ゲームを楽しむ穏やかな素顔を見せている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Talla%20Tonga"]], moves: [], facts: [] };
  if (PROFILES["Talla Tonga"]._weak) { PROFILES["Talla Tonga"].lead = "フロリダ育ちで、トンガ系の厳しくも温かい家庭に支えられてきた長身の選手。食べ歩きの動画と音楽、ゲームを楽しむ穏やかな素顔を見せている。"; delete PROFILES["Talla Tonga"]._weak; }
  PROFILES["Talla Tonga"].facts.push(...[{"cat": "暮らし", "t": "ハリケーン後のフロリダで過ごす", "b": "中部フロリダの自宅と家族は無事だったが、街は浸水があちこちに残ったと話す。停電は出たり戻ったりした程度で、道が通れず遠回りが必要になったという。英国遠征の直前に出発できて助かり、帰国後は学校も再開したそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=93s"]]}, {"cat": "家族", "t": "トンガ流は年長者への敬意が土台", "b": "トンガの文化は親や年上を最大限に敬うことが基本で、日本式の礼儀にも近いと話す。父が日本のプロレス界で育った人なので、その影響もあるという。きょうだい、とくに姉妹は親友のような存在で、親は親であると同時に友人にもなっていくそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（9:28〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=568s"]]}, {"cat": "家族", "t": "家族の結びつきが強く、恋愛もきょうだい全員の承認制", "b": "一族はカリフォルニアを経由してアメリカに渡った人が多く、そこから距離を置いて、両親はフロリダに根を下ろしたという。人数が少ないぶん結束が固く、付き合う相手も兄弟姉妹、親、いとこ全員に認められる必要があったと話す。厳しかったが愛情のある育ちだったそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（11:02〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=662s"]]}, {"cat": "家族", "t": "人前では出身の島を背負っている意識がある", "b": "パーティーで羽目を外すような行動は避け、常に家族と島の名前を代表している感覚があると話す。悪い印象を残さないことが大切で、島や家族に恩返ししたい気持ちも強いそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（11:50〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=710s"]]}, {"cat": "体のこと", "t": "お酒は軽く、昔ほど飲まない", "b": "最近は缶のハイボールのウイスキーを遠征先で少し飲むのが定番だという。創作のアイデアが出やすくなるが、酔うほどは飲まないそうだ。3〜4年前に飲みすぎる時期は終えたと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（16:38〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=998s"]]}, {"cat": "リングに来るまで", "t": "兄の動画編集を手伝ったのがVlogの原点", "b": "兄のタマ・トンガが悪の軍団にいた頃にVlogを撮っていて、大学を出て実家にいた時期に編集を手伝ったのが始まりだという。学校でもニュース番組や映画、劇の映像づくりに関わっていたそうだ。2017年に来日してからは、道場で練習後にVlogばかり見ていたと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（17:28〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1048s"]]}, {"cat": "リングの話", "t": "悪の軍団にいた時期は素顔をあまり出さなかった", "b": "以前はVlogを公開で出さず、見たい人だけが有料のファンサイトで観る形にしたという。その分、公の目から離れた場所で、役を離れた素の姿を少し多めに見せられるようになったと話す。いまはそれが楽しくて仕方ないそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（18:21〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1101s"]]}, {"cat": "リングに来るまで", "t": "日本の巡業の裏側を見せたくて動画を始めた", "b": "日本には、特に巡業の舞台裏のように、知られていない面白い光景がたくさんあると感じたという。兄と一緒に毎日の動画づくりを始め、けがをする前までは続けていたそうだ。復帰後にまた再開したと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（18:21〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1101s"]]}, {"cat": "暮らし", "t": "毎週のように映像を作り、日本の旅を発信", "b": "いまは日本の巡業やアメリカでの出来事をVlogにして、有料のファンサイトで公開していると話す。2019年ごろまでの動画はYouTubeに残っているそうだ。聞き手からは、本人を知らなくても見たくなる編集だと褒められていた。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（19:11〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1151s"]]}, {"cat": "好きなもの", "t": "日本の食べ物の見せ方に感動した", "b": "日本の商業施設では、食べ物が宝石のように美しくガラスケースに並んでいるのが印象的だったと話す。その魅力を共有したくて動画にしたという。食べているときの自分らしさが出るのが気に入っているそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（19:59〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1199s"]]}, {"cat": "好きなもの", "t": "アメリカでは巨大ハンバーガーが好き", "b": "よく通っていたフードトラックの、パティ4枚にソーセージやベーコン、チーズ、ハラペーニョまで載った特大バーガーが印象に残っているという。手袋を渡されるほど大きく、握りつぶすように食べたそうだ。最近は日本の辛いラーメンや500グラムのステーキなど、シンプルなものにも惹かれると話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（21:40〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1300s"]]}, {"cat": "好きなもの", "t": "ステーキはミディアムレアが好み", "b": "焼き加減はミディアムレアで、眠りたいときはリブアイ、肉の質を味わいたいときはヒレを選ぶという。数週間前に初めて和牛を食べ、バターのような柔らかさに感動したそうだ。帰宅が2日だけなので、夜は外食で済ませると話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（24:05〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1445s"]]}, {"cat": "体のこと", "t": "数十万人の前より、小さなジムの視線が苦手", "b": "何十万人もの前で試合をしても緊張しないが、小さなジムで数人に見られると途端に緊張すると話す。自分の動きをすべて見られている気がするそうだ。褒め言葉をもらっても、どう返せばいいか分からなくなるという。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（27:22〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1642s"]]}, {"cat": "暮らし", "t": "SNSの誘いは削除して終わらせる", "b": "きわどいメッセージが届いても返信せず、すぐ消すと話す。過去には海外から届いた誘いの文面を見て、すぐに削除したこともあるという。自分も兄弟もここまで積み上げた仕事があるので、失うリスクを考えて飲酒量も減らしたそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（34:56〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2096s"]]}, {"cat": "リングに来るまで", "t": "父から「今は昔とは違う」と教わった", "b": "この世界に入る前から、父にたくさんの昔話を聞かされたという。昔はケンカで業界を守る面もあったが、今はカメラとSNSだらけで、手を出せば必ず悪者になると言われたそうだ。だから何か言われても笑って立ち去り、前向きさで受け流すと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（36:30〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2190s"]]}, {"cat": "リングに来るまで", "t": "きょうだい全員がスポーツ少年少女だった", "b": "兄弟はサッカー、野球、フットボール、バスケットボール、陸上とあらゆる競技をやり、姉妹は水泳をしていたという。本人の本命はバスケットボールだったそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（38:55〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2335s"]]}, {"cat": "リングに来るまで", "t": "背が高く、ずっと「センター」役だった", "b": "幼いころから一番背が高く、チームではセンターを任されて、ほかのポジションを覚える機会がなかったと話す。高校と大学で周りも大きくなったが、すでに役割が固まっていたそうだ。陸上では走り高跳びで約198センチ（6フィート6インチ）を跳び、ハードルは遅かったが、フォームは良かったと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（39:44〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2384s"]]}, {"cat": "体のこと", "t": "髪の手入れは夜が中心で、とにかく時間がかかる", "b": "朝は髪を濡らしてリーブイン・コンディショナーをつける程度だという。2〜3日おきに洗い、アルガンオイルをつけてタオルで包み、さらにコンディショナーを重ねる流れだそうだ。数日間の英国遠征のあとは絡まりがひどく、ブラッシングに長時間かかったと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（42:12〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2532s"]]}, {"cat": "体のこと", "t": "生え際は後退したが、気にせず受け入れている", "b": "生え際が少しずつ後退してきたが、無理に隠そうとは思わないという。髪型で見栄を張るより、自然に任せることにしたそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（43:49〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2629s"]]}, {"cat": "好きなもの", "t": "ゲームは移動中のスイッチ派", "b": "以前は2Kやマッデンなど王道のスポーツゲームを遊び、アサシンクリードやスパイダーマンもやったという。いまは遠征にスイッチを持ち歩いて2Kをやり、「ブレス オブ ザ ワイルド」をクリアしたと話す。友達とオンラインで対戦したい気持ちもあるそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（44:36〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2676s"]]}, {"cat": "好きなもの", "t": "音楽はヒップホップが中心で、何でも聴く", "b": "ほぼ毎日トレーニングで音楽を聴き、主にラップが好きだという。新作が出たらすぐ聴くのはドレイク、カニエ、J・コールの3人だと話す。ケンドリック・ラマーは一度ハマると一週間ずっと繰り返し聴くそうで、パラモアも好きだと話す。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（48:39〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=2919s"]]}, {"cat": "好きなもの", "t": "夢は俳優で、地元の小さなCMにも出た", "b": "プロレス以外の夢の仕事は俳優だと話す。フロリダの銀行などの小さなCMに出た経験もあるそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（53:25〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=3205s"]]}, {"cat": "好きなもの", "t": "パイナップル入りピザは譲れない", "b": "自分の譲れない意見として、パイナップルをピザに載せるのは正しいと主張している。バーベキューソースにハム、玉ねぎと合わせたハワイアンが好きだそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（56:39〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=3399s"]]}, {"cat": "暮らし", "t": "スマホはアイフォーン派", "b": "20代前半まではアンドロイドを使っていたが、家族が全員アイフォーンで、メッセージの色の違いが気になり、21〜22歳で乗り換えたという。いまは慣れてしまい、毎年同じと感じながらも使い続けているそうだ。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（58:10〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=3490s"]]}, {"cat": "好きなもの", "t": "欲しい超能力は人の心を読むこと", "b": "ひとつ選べるなら相手の考えを読む力が欲しいと話す。特にプロレス界では、誰が本物か見分けられるからだそうだ。瞬間移動にも憧れがあり、日本や英国、国内の移動が楽になると語っている。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pgSeEZ1lqIo", "src": [["番組のYouTube（1:02:07〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=3727s"]]}]);
  if (PROFILES["Tama Tonga"]) PROFILES["Tama Tonga"].facts.push({"cat": "暮らし", "t": "タマ・トンガのVlogが弟の手本になった", "b": "悪の軍団にいた頃のタマ・トンガは、よくVlogを撮っていて、その編集を手伝ったことが動画づくりの原点になったと、タラ・トンガが話している。", "sp": "タラ・トンガ", "d": "2022-10-12", "how": "ブラック・ラッスリン・ポッドキャストの番組で、タラ・トンガの話（字幕を全文確認）", "src": [["番組のYouTube（17:28〜）", "https://www.youtube.com/watch?v=pgSeEZ1lqIo&t=1048s"]], "by": "第三者の話"});
