  if (!PROFILES["Bryan Danielson"]) PROFILES["Bryan Danielson"] = { lead: "WWEでは番組の悪ふざけも創作の会議も楽しんだという。退団は三つの選択肢の末、日程と創作の自由、新しい刺激を求めての決断だったと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bryan%20Danielson"]], moves: [], facts: [] };
  if (PROFILES["Bryan Danielson"]._weak) { PROFILES["Bryan Danielson"].lead = "WWEでは番組の悪ふざけも創作の会議も楽しんだという。退団は三つの選択肢の末、日程と創作の自由、新しい刺激を求めての決断だったと話す。"; delete PROFILES["Bryan Danielson"]._weak; }
  PROFILES["Bryan Danielson"].facts.push(...[{"cat": "WWEでの日々", "t": "台本なしの「Talking Smack」が大好きだった", "b": "WWE時代に出演したトーク番組は、台本がなく好き勝手にふざけられる、自分にとって特別な仕事だったと話す。演者が自由に楽しめる雰囲気が心地よかったそうだ。今の同番組はスタジオで作り込んだ別物になったという。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=98s"]]}, {"cat": "WWEでの日々", "t": "試合に出られず、わざとクビ覚悟で暴れた", "b": "医師の許可が複数出ているのに試合出場を認められず、苛立っていた時期だったという。その不満から、番組内で会社が嫌がる話題をわざと繰り返し持ち出し、クビになってもいいくらいの気持ちだったと話す。試合をしないままテレビに呼ばれる状況が続いていたそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=144s"]]}, {"cat": "WWEでの日々", "t": "ミズとの番組内の衝突は、殴る案を直前でやめた", "b": "互いに不満を抱えていた二人で、本気で殴りかねないほど相手を挑発する筋立てを考えたという。殴れば解雇されるか、試合を見たいと世間が望んで出場許可につながるかのどちらかを狙っていたそうだ。ただ、直感で歩み去るほうが良いと判断した。相手の演技が見事で、怒りの熱を残したままにしたかったからだと話す。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（6:24〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=384s"]]}, {"cat": "WWEでの日々", "t": "無観客期間の試合が意外と好きだった", "b": "退団前の最後の一年について、観客のいない育成施設での試合が気に入っていたと話す。特に演出を気にせず、仲間と自由に動き回れたのが楽しかったそうだ。ただ、本当に求めていたのはそれではなかったとも語っている。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（8:52〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=532s"]]}, {"cat": "WWEでの日々", "t": "創作チームの会議に加わった", "b": "コロナ禍で妻の出産が近く出社を控えていた時期に、会社の幹部から創作チームの会議に参加しないかと誘われたという。リモートの会議に加わって楽しんだと話す。のちに他の人が出社するようになってからも、書き手たちと気軽に意見を交わしていたそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（10:30〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=630s"]]}, {"cat": "WWEでの日々", "t": "脚本チームを悪く言う声には反対", "b": "ネットでは脚本家が批判されがちだが、会ってみると賢くて面白い人ばかりだったと話す。レスラーではない立場の制約のなかで働いているだけで、能力は高いと感じているそうだ。一緒に仕事をした書き手たちとの時間は心から楽しかったという。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（12:05〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=725s"]]}, {"cat": "退団の理由", "t": "選択肢は二つではなく三つだった", "b": "世間ではWWE残留か他団体かの二択だと思われているが、実際には専業レスラーをやめて父親業に専念する道も考えていたと話す。決め手は、日程、創作の自由度、そして長く同じ場所にいたので新しい環境を試してみたい気持ちだったという。各社の条件を妻に伝えたときは怒られそうな金額だったと笑っている。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（13:47〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=827s"]]}, {"cat": "退団の理由", "t": "もう一度、血を流す試合がしたかった", "b": "退団を考えた理由のひとつに、観客の前で血を流して闘いたい気持ちがあったと話す。満員の会場で必死に闘う感覚は、生きていると強く感じさせてくれるそうだ。理屈では説明できない魅力だと本人は語っている。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（14:35〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=875s"]]}, {"cat": "退団の理由", "t": "日本の団体との掛け持ち案もあった", "b": "WWEに残りつつ新日本プロレスの大会にも出る形を、双方が模索していた時期があったという。結果的にその案は実現しなかったが、いま振り返れば全員にとって良かったと思うそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（16:11〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=971s"]]}, {"cat": "退団の理由", "t": "退団後は初めて子どもたちと長く過ごした", "b": "WWEを離れてから他団体に登場するまでの間、タホで子どもたちとハイキングをして過ごしたという。人生で初めてのそんな時間は素晴らしく、何もしない選択肢が魅力的に見えた理由でもあると話す。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（16:58〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=1018s"]]}, {"cat": "WWEでの日々", "t": "引退スピーチは会社の求めで故郷シアトルで行った", "b": "当時の最高責任者から土曜日に電話があり、出場許可は出さないので月曜に引退を発表してほしいと告げられたという。年間最大の祭典が近く、復帰を期待するファンに希望を持たせないためだった。最初は考えさせてほしいと答えたが、妻と話し、どうせ試合できないなら家族や友人の前で話そうと決めたそうだ。父が最後に自分の試合を見た会場でもあり、非常につらい一日だったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（17:44〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=1064s"]]}, {"cat": "WWEでの日々", "t": "引退直後のリアリティ番組の撮影が苦手だった", "b": "引退を発表した直後に、人気選手の家に滞在しながらリアリティ番組を撮影することになったという。着替えを重ねて別の日を装うなど作り込みが多く、好きなものを奪われた直後で心が弱っていた時期には特にきつかったと話す。妻が遠征で不在がちだったことも重なったそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（19:21〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=1161s"]]}, {"cat": "WWEでの日々", "t": "復帰が決まった日は慌ただしい長旅だった", "b": "中東でサイン会に出ていた際に復帰の知らせを受けたという。そこから米国へ飛び、医師の検査で出場許可を得て、翌朝にはテキサスへ向かった。その医師は感動して涙が出るほどだったと話す。到着後はスマートフォンに会場にいるはずだと連絡が殺到していたそうだ。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（34:43〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=2083s"]]}, {"cat": "WWEでの日々", "t": "出場を認めなかった医師やトップとの関係はむしろ深まった", "b": "自分の出場を認めなかった脳神経外科医とも、健康を案じてくれているのは分かっていたので、対立ではなく理解し合えたと話す。会社のトップとも、許可が出ない理由をきちんと話し合ううちに、関係はかえって強くなったそうだ。意見の違う相手でも、じっくり話せば似ている部分が多いと感じているという。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（36:20〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=2180s"]]}, {"cat": "WWEでの日々", "t": "ゼネラルマネージャーの役で番組に駆け込んでいた", "b": "ゼネラルマネージャー役を務めていた時期は多忙で、トーク番組には収録ぎりぎりに駆け込むことがよくあったという。マイクを付けてそのまま出演する日が続いたため、少し気難しくなっていた時期でもあったと話す。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで（字幕を全文確認）", "art": "ext-sEiYoY2A83Y", "src": [["番組のYouTube（51:46〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=3106s"]]}]);
  if (PROFILES["The Miz"]) PROFILES["The Miz"].facts.push({"cat": "暮らし", "t": "ミズは本当に努力家で、尊敬している", "b": "ものすごく懸命に働く人として尊敬していると、ブライアン・ダニエルソンが話している。番組内の衝突のときも、その熱量があったからこそ最高の場面になったという。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで、ブライアン・ダニエルソンの話（字幕を全文確認）", "src": [["番組のYouTube（7:14〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=434s"]], "by": "第三者の話"});
  if (PROFILES["Bruce Prichard"]) PROFILES["Bruce Prichard"].facts.push({"cat": "暮らし", "t": "創作チーム参加を誘ってくれたのはブルース・プリチャード", "b": "ブルース・プリチャードから創作チームに入らないかと声をかけられ、楽しく働けたと、ブライアン・ダニエルソンが話している。悪く言う人もいるが自分は好きだと語っている。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで、ブライアン・ダニエルソンの話（字幕を全文確認）", "src": [["番組のYouTube（11:20〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=680s"]], "by": "第三者の話"});
  if (PROFILES["Nigel McGuinness"]) PROFILES["Nigel McGuinness"].facts.push({"cat": "暮らし", "t": "ナイジェル・マクギネスは運が違っただけ", "b": "自分が頂点に立てたのも運に恵まれたからで、実力ある仲間が報われなかった例としてナイジェル・マクギネスを挙げていると、ブライアン・ダニエルソンが話している。診断で上腕の断裂を正直に伝えたため、WWEでは一度も試合ができなかったという。", "sp": "ブライアン・ダニエルソン", "d": "2022-12-30", "how": "スターキャスト会場の公開収録ポッドキャストで、ブライアン・ダニエルソンの話（字幕を全文確認）", "src": [["番組のYouTube（22:31〜）", "https://www.youtube.com/watch?v=sEiYoY2A83Y&t=1351s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-sEiYoY2A83Y", d: "2022-12-30", show: "ext", who: ["Bryan Danielson"], t: "ブライアン・ダニエルソンの回　WWE時代の思い出と退団までの迷い", lead: "スターキャスト会場の公開収録ポッドキャストに出た約52分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bryan Danielson"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-sEiYoY2A83Y").map((x) => [x.t, x.b, x.sp])), open: ["家族、体のこと、他団体での日々、趣味などの話題は、公開項目から外しています。", "自動字幕のため、番組名や一部の人名は確認できず、番組名は仮に会場名から記しています。", "引退直後の撮影中に起きた個人的な口論の話は、要点が不確かなため載せていません。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=sEiYoY2A83Y"]] });
  if (!ROSTER.find((r) => r[1] === "Piper Niven")) ROSTER.push(["パイパー・ニーヴン", "Piper Niven", "lg", "", "", "", ""]);
  if (!PROFILES["Piper Niven"]) PROFILES["Piper Niven"] = { lead: "長い欠場から戻ったばかりのパイパー・ニーヴン（当時の名前はドゥードロップ）。先の見えない休養の不安と、ロイヤルランブルへの思いを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Piper%20Niven"]], moves: [], facts: [] };
  if (PROFILES["Piper Niven"].lead === "長い欠場から戻ったばかりのパイパー・ニーヴン（当時の名前はドゥードロップ）。先の見えない休養の不安と、ロイヤルランブルへの思いを語る。") PROFILES["Piper Niven"]._weak = 1;
  PROFILES["Piper Niven"].facts.push(...[{"cat": "リングの話", "t": "女子タッグ大会でブランドを飛び回った日々", "b": "女子タッグ王座の大会が行われていた頃、ニッキー（ニッキー・クロス）と組んでRAW、SmackDown、NXTを行ったり来たりしたと、パイパーは振り返る。大変だったが、自分たちはプロとしてこなせると分かったという。", "sp": "パイパー・ニーヴン", "d": "2023-02-23", "how": "ファイトフルの番組で（字幕を全文確認）", "art": "ext-UxZp_ZZUo7Y", "src": [["番組のYouTube（2:27〜）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y&t=147s"]]}, {"cat": "リングの話", "t": "試合中に看板が燃えても続行", "b": "ベッキー・リンチとの試合中、ベッキーに「看板が燃えてる」と言われ、最初は意味が分からなかったと、パイパーは笑う。避難するのかと思ったが、そのまま試合を続けたという。ベッキーとはまた戦いたいそうだ。", "sp": "パイパー・ニーヴン", "d": "2023-02-23", "how": "ファイトフルの番組で（字幕を全文確認）", "art": "ext-UxZp_ZZUo7Y", "src": [["番組のYouTube（3:19〜）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y&t=199s"]]}, {"cat": "好きなもの", "t": "一番好きな大会はロイヤルランブル", "b": "一年で一番好きな大会はロイヤルランブルだと、パイパーは話す。誰が出てくるか分からない驚きと、新しい抗争がそこから始まるところが好きだという。", "sp": "パイパー・ニーヴン", "d": "2023-02-23", "how": "ファイトフルの番組で（字幕を全文確認）", "art": "ext-UxZp_ZZUo7Y", "src": [["番組のYouTube（4:12〜）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y&t=252s"]]}, {"cat": "体のこと", "t": "心拍を上げることも禁じられた3か月", "b": "3か月以上、何もしてはいけないと言われ、心拍数を上げることさえ許されなかったと、パイパーは話す。ふつうのけがなら復帰の目安があるが、自分の場合は「分からない」と言われ続けたという。復帰できないかもしれないと不安になり、少しおかしくなりそうだったそうだ。練習の許可が出たのは、この取材の1か月ほど前だという。", "sp": "パイパー・ニーヴン", "d": "2023-02-23", "how": "ファイトフルの番組で（字幕を全文確認）", "art": "ext-UxZp_ZZUo7Y", "src": [["番組のYouTube（5:01〜）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y&t=301s"]]}, {"cat": "リングの話", "t": "相棒ニッキーの変化を後押し", "b": "ニッキー・クロスが不気味なキャラクターへ変わっていく様子を、自然な流れでうれしく見ていると、パイパーは話す。舞台裏の短い映像もとても面白いと感じているという。", "sp": "パイパー・ニーヴン", "d": "2023-02-23", "how": "ファイトフルの番組で（字幕を全文確認）", "art": "ext-UxZp_ZZUo7Y", "src": [["番組のYouTube（5:01〜）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y&t=301s"]]}]);
  ARTICLES.push({ id: "ext-UxZp_ZZUo7Y", d: "2023-02-23", show: "ext", who: ["Piper Niven"], t: "パイパー・ニーヴンの回　復帰目前の不安と、炎上した看板の夜", lead: "ファイトフルの番組に出た約7分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Piper Niven"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-UxZp_ZZUo7Y").map((x) => [x.t, x.b, x.sp])), open: ["冒頭の広告読み上げは除いた。", "欠場の原因の病名や詳しい診断は、本人がはっきり語っていないため載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=UxZp_ZZUo7Y"]] });
  if (!ROSTER.find((r) => r[1] === "Rey Mysterio")) ROSTER.push(["レイ・ミステリオ", "Rey Mysterio", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"] = { lead: "2023年の殿堂入りスピーチから約3分の抜粋。エディ・ゲレロとの縁と、夢を支えてくれた妻への感謝を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Rey%20Mysterio"]], moves: [], facts: [] };
  if (PROFILES["Rey Mysterio"].lead === "2023年の殿堂入りスピーチから約3分の抜粋。エディ・ゲレロとの縁と、夢を支えてくれた妻への感謝を語る。") PROFILES["Rey Mysterio"]._weak = 1;
  PROFILES["Rey Mysterio"].facts.push(...[{"cat": "リングに来るまで", "t": "12歳で会ったエディ・ゲレロ", "b": "まだレスリングを始める前の12歳のとき、叔父と試合をしたエディ・ゲレロに会ったという。何年も後にWCWで再会したエディは、あのころと同じ温かい心のままだったと話す。", "sp": "レイ・ミステリオ", "d": "2023-03-31", "how": "WWE殿堂入り式典のハイライト（WWE公式）で（字幕を全文確認）", "art": "ext-ygYyIAfXsJY", "src": [["番組のYouTube（0:01〜）", "https://www.youtube.com/watch?v=ygYyIAfXsJY&t=1s"]]}, {"cat": "家族", "t": "医学の道を置いて支えた妻", "b": "夢を追っていたころ、妻は医学を学んでいたが、その道をいったん脇に置いて働き、自分に仕送りをしてくれたという。夢を追い続けられたのは妻のおかげだと感謝を伝えた。", "sp": "レイ・ミステリオ", "d": "2023-03-31", "how": "WWE殿堂入り式典のハイライト（WWE公式）で（字幕を全文確認）", "art": "ext-ygYyIAfXsJY", "src": [["番組のYouTube（0:47〜）", "https://www.youtube.com/watch?v=ygYyIAfXsJY&t=47s"]]}]);
  ARTICLES.push({ id: "ext-ygYyIAfXsJY", d: "2023-03-31", show: "ext", who: ["Rey Mysterio"], t: "レイ・ミステリオの回　2023年殿堂入りスピーチの抜粋", lead: "WWE殿堂入り式典のハイライト（WWE公式）に出た約3分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Rey Mysterio"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ygYyIAfXsJY").map((x) => [x.t, x.b, x.sp])), open: ["公式チャンネルの約3分のハイライト版だけを読んだ。スペイン語の部分は字幕に起こされていないため載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ygYyIAfXsJY"]] });
  if (!ROSTER.find((r) => r[1] === "Sami Zayn")) ROSTER.push(["サミ・ゼイン", "Sami Zayn", "lg", "カナダ出身の人気レスラー", "", "", ""]);
  if (!PROFILES["Sami Zayn"]) PROFILES["Sami Zayn"] = { lead: "シリア系の両親のもと、モントリオールで育ったサミ・ゼイン。20ドルの試合から始めた下積みと、ブランド物より人の事情に目を向ける優しさを、コメディアンと語り合った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Sami%20Zayn"]], moves: [], facts: [] };
  if (PROFILES["Sami Zayn"]._weak) { PROFILES["Sami Zayn"].lead = "シリア系の両親のもと、モントリオールで育ったサミ・ゼイン。20ドルの試合から始めた下積みと、ブランド物より人の事情に目を向ける優しさを、コメディアンと語り合った。"; delete PROFILES["Sami Zayn"]._weak; }
  PROFILES["Sami Zayn"].facts.push(...[{"cat": "家族", "t": "両親はシリア生まれ、本人はカナダ育ち", "b": "両親はシリアで生まれ、カナダに移り住んだと話す。お金に余裕がなかったので、里帰りは数年に一度ためてから行く程度だったそうだ。最後にシリアを訪れたのは1998年で、大人になってからは行っていないという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=143s"]]}, {"cat": "リングに来るまで", "t": "ロサンゼルスは名を上げた思い出の街", "b": "2004年の終わりごろから、ロサンゼルスの小さなインディー団体の興行に通い始めたという。約8年間、毎月のように出場し、その試合がDVDで出回って名前が広まった。大きな祭典がこの街で開かれるのは、一回りして戻ってきたような感覚だと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（9:43〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=583s"]]}, {"cat": "リングに来るまで", "t": "最初の履歴書はVHSテープ", "b": "アメリカの大きなインディー団体に初めて呼ばれたとき、自分の試合を録ったVHSテープを履歴書代わりに送ったと話す。写真と住所を添えて郵送するのが当時のやり方だったそうだ。それほど昔でもないのに、時代の変化の速さに驚くという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（10:32〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=632s"]]}, {"cat": "暮らし", "t": "食料品店とおもちゃ店の短い仕事", "b": "下積み時代は、ギリシャ系の小さな食料品店で働いていたのが一番長いという。出勤時間があいまいで、気楽だったそうだ。クリスマス時期だけおもちゃ店で働いたが、きっちりした時間管理についていけずすぐ辞めたといい、テレマーケティングの仕事もしたと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（13:49〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=829s"]]}, {"cat": "暮らし", "t": "試合のギャラを細かく書き留めていた", "b": "いつ、どこで、いくらもらったかをノートに書いていたそうだ。ギャラが20ドルから50ドル、さらに100ドルに上がったときは驚いたという。最初の年の収入は、月1回の20ドルの試合で合計240ドルだったと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（15:24〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=924s"]]}, {"cat": "暮らし", "t": "大手との契約で収入は大きく下がった", "b": "インディー最後の年は10万ドルほど稼いでいたのに、最初の大手との契約は年3万9千ドルだったという。育成の段階なので仕方ないと割り切り、あとで取り戻せると考えたと話す。結果的に、その通りになったそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（17:01〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=1021s"]]}, {"cat": "暮らし", "t": "初めての遠征の小切手で気づいたこと", "b": "所属から約8か月で、数日間の地方巡業に出されたという。そのときの小切手が6〜7千ドルほどで、「ここで稼げるんだ」と初めて実感したそうだ。それまでお金のことはほとんど考えず、好きだからやっていたと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（18:34〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=1114s"]]}, {"cat": "リングに来るまで", "t": "ボブ・ディランの言葉が心に残っている", "b": "ボブ・ディランが、60年代の名曲について「あれはもう書けないが、一度は書いた」と語る映像が印象に残っているという。一度でも何かを成し遂げたなら、それで十分だと思えるようになったそうだ。長い目で見れば、10本の番組でも1本でも、最後は一文にまとまると話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（25:47〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=1547s"]]}, {"cat": "リングに来るまで", "t": "子どもの頃からプロレスに夢中", "b": "子どものころからプロレスが大好きで、ずっとなりたかった職業だったという。最初の憧れはハルク・ホーガンで、次にカナダ人としてブレット・ハート、10代ではミック・フォーリーとハーディー・ボーイズが好きになったそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（40:19〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=2419s"]]}, {"cat": "リングの話", "t": "インディー時代は細身で、練習も少なかった", "b": "2010〜11年ごろのインディー時代は、ほとんど鍛えず、何か月もトレーニングしない時期もあったそうだ。細身であることが、当時のキャラクターの魅力でもあったと話す。自分がどう見えているかを理解し、それを活かすのが演じ手の仕事だという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（41:59〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=2519s"]]}, {"cat": "リングの話", "t": "誰も自分を知らない前提で演じる", "b": "若い選手には、観客の誰も自分のことを知らないと思って演じるよう伝えていると話す。8千人の会場でも、数十人から100人ほどはプロレスを知らない人だと考えているそうだ。最初の数分で、どんな人物かを伝えるのが大事だという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（42:50〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=2570s"]]}, {"cat": "リングの話", "t": "手を抜いた試合は一度もないと話す", "b": "疲れていても、体調が悪くても、手を抜いた試合は思い出せないという。インディー時代、小さな団体でも前の試合の評判がかかっていると考え、毎回が自分の名前を背負った場だと感じていたそうだ。今もその気持ちが変わらないと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（50:53〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3053s"]]}, {"cat": "リングの話", "t": "どの試合も観客にとっては「すべて」", "b": "観客が一度しか観ない試合の印象が、そのままその選手の印象になると話す。だから日曜日の地方の興行でも、全力でやるべきだという考えだ。日常の悩みを忘れる約20分間を作るのがこの仕事の良さだと語っている。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（53:14〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3194s"]]}, {"cat": "リングの話", "t": "20年目に訪れた「瞬間的な追い風」", "b": "ここ1年は、ストーリーと共演者がうまく噛み合い、一気に注目が高まったと話す。業界に入って約20年目の出来事で、本人は「20年かかった一夜の成功」と笑っている。苦労してきた過程があるから、ファンにも響くのだろうと考えているそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（55:42〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3342s"]]}, {"cat": "リングの話", "t": "ブーツは長年同じデザインを使い続けている", "b": "駆け出しのころは1サイズ小さいブーツを借り、約400ドルのブーツを買ったという。キャリア全体で同じデザインを守り、約4、5年ごとに作り替えているそうだ。数年前に、タイツからパンツスタイルに変えたが、ブーツだけは変えなかったと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（59:45〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3585s"]]}, {"cat": "好きなもの", "t": "愛車は2004年式のニッサン・アルティマ", "b": "もう12年乗っている2004年式のアルティマを手放さないという。いい車を買えるようになった今も、成功する前から乗っている車は、地に足をつけるための最後のこだわりだそうだ。ストーン・コールドも古いフォード車に乗っていると聞いて驚いたと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:04:35〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3875s"]]}, {"cat": "暮らし", "t": "ブランド物にはあまり興味がない", "b": "お金がなかったころから、ステータスを示す持ち物をばかばかしいと思っていたそうだ。ルイ・ヴィトンのバッグを見ると、つい批判的に考えてしまうと笑っている。ただ、品質が本当に良いものは別で、そこにお金を払うのは納得できると話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:06:19〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3979s"]]}, {"cat": "好きなもの", "t": "コーヒーにはこだわりがあり、食事はヴィーガン", "b": "コーヒーは、こだわりの強い人が淹れたものを好み、スターバックスは緊急時だけだそうだ。食事はヴィーガンで、夜中にファストフードに寄るのではなく、場所や料理を選んで食べると話す。質の高さを大事にしているという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:07:58〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4078s"]]}, {"cat": "暮らし", "t": "人を責めず、事情を想像するようにしている", "b": "昔は何にでも文句を言う性格だったが、落ち着いた友人たちの影響で、気にしないようになってきたという。今は、誰もがそれぞれ何かを抱えていると考え、相手を気の毒に思う気持ちのほうが強いそうだ。自分は人間の苦しみの中でごくわずかしか経験していない、と話している。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:10:24〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4224s"]]}, {"cat": "暮らし", "t": "貧しい時代、同居人3人と古い部屋で暮らした", "b": "お金がなかったころは、男3人で住む荒れた部屋で、毎晩ラーメンを食べていたという。車に空き巣が入ってCDを盗まれたこともあったそうだ。隣の建物に新しいポルシェを持つ人がいて、当時は腹が立ったが、今は好きにすればいいと思えるようになったと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:12:03〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4323s"]]}, {"cat": "リングの話", "t": "長いマイクは削るほど強くなる", "b": "数分のマイクの場面では、話したいことを多く用意してから削っていくという。ここ1〜3年で、生放送やインタビューの経験を重ね、言葉は少ないほうが伝わると感じるようになったそうだ。ときには、一言だけで客席を沸かせることもあると話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:18:31〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4711s"]]}, {"cat": "リングに来るまで", "t": "ハーディー・ボーイズとミック・フォーリーの本が背中を押した", "b": "ハーディー・ボーイズが裏庭で試合をしていた少年たちだったので、自分にもできると思えたという。ミック・フォーリーの自伝で、遠征や下積みの現実を知り、苦労する生き方にも憧れたそうだ。15、16歳のころ、レスラーの養成を受けようと決めたと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:20:06〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4806s"]]}, {"cat": "暮らし", "t": "苦労した頃の思い出は温かい", "b": "バスルームを仲間と共有していた時期も、今は良い思い出として振り返るそうだ。同じ苦労をしている仲間と寒さや愚痴を分かち合う感覚が好きだと話す。苦労そのものを大事にしたい、というのが本人の考えのようだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:20:53〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4853s"]]}, {"cat": "リングに来るまで", "t": "高校の転校と、昔の友だちからの電話", "b": "14歳のときに学区が変わり、高校の後半の2年は別の学校に通ったという。卒業間際、2年ぶりに旧友から電話があり、地元のプロレスのラジオ番組で働いていると聞いた。昔から一緒にプロレスの話をしていた仲で、地元のインディー選手が教えてくれると誘われ、卒業後に練習を始めたそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:21:41〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4901s"]]}, {"cat": "リングに来るまで", "t": "市バスで練習に通い、どんな小さな興行にも頼み込んだ", "b": "市バスで20分かけて練習に通いながら、ミック・フォーリーの遠征話を思い出して自分も同じだと感じていたという。ケベックの小さな団体に出場を頼むと、たいてい「いいよ」と言われたそうだ。ギャラのない試合でも、リングに立てるだけで十分だったと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:23:19〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=4999s"]]}, {"cat": "リングの話", "t": "ケビン・オーエンズとは、出会いからずっと並走している", "b": "ケビン・オーエンズとは、ケベックでデビューした1年目に出会ったという。その後もインディーで並んで成長し、大手に入ったあとも敵、味方を行き来してきたと話す。二人ともファンに「同じ試合を見せない」という考えを持っていて、フランス語で気軽に話せる戦友のような仲だそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:26:31〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=5191s"]]}, {"cat": "家族", "t": "両親は夢を応援してくれたが、試合は観に来なかった", "b": "プロレスラーになる夢を、両親はいつも応援してくれたという。ただ、小さな会場の試合には来ず、初めて観に来たのは10年ほど前のモントリオールの大会だったそうだ。1万人の観客の前で、それまで本人の試合を観たことがなかったと話す。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:32:05〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=5525s"]]}, {"cat": "家族", "t": "男5人きょうだいの家庭で育った", "b": "5人兄弟の家に育ち、年齢は少しずつ離れていたという。両親は学校行事にあまり関わらなかったと話す。友だちの家に泊まる「お泊まり」も、両親は強く反対していて、許してもらうには大きな交渉が要ったそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:32:54〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=5574s"]]}, {"cat": "家族", "t": "家と学校で、二つの文化の間で育った", "b": "学校ではカナダの子、家ではシリアの文化という二つの世界で育ったと話す。そのおかげで、世の中の当たり前は文化によって違うと早くから分かったそうだ。「これが唯一の正解ではない」という感覚は、運の良い贈り物だったと考えている。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で（字幕を全文確認）", "art": "ext-MSMKAW_qmco", "src": [["番組のYouTube（1:35:22〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=5722s"]]}]);
  if (PROFILES["Kevin Owens"]) PROFILES["Kevin Owens"].facts.push({"cat": "暮らし", "t": "ケビン・オーエンズ：ケベックで出会った親友", "b": "ケベックでデビューした1年目に出会い、今は一緒にタッグ王座を目指す仲だと、サミ・ゼインが話している。インディー時代から別々の道を歩きながら、何度も交わってきたという。フランス語で何でも話せる間柄だそうだ。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で、サミ・ゼインの話（字幕を全文確認）", "src": [["番組のYouTube（1:26:31〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=5191s"]], "by": "第三者の話"});
  if (PROFILES["Stone Cold Steve Austin"]) PROFILES["Stone Cold Steve Austin"].facts.push({"cat": "暮らし", "t": "ストーン・コールド・スティーブ・オースチン：愛車は古いフォード", "b": "自分の司会するポッドキャストで、2003年式のフォード・フォーカスに乗っていると話していた、とサミ・ゼインが話している。自分の古い車より1年古いと知って驚いたという。", "sp": "サミ・ゼイン", "d": "2023-04-28", "how": "アンドリュー・サンティーノの番組で、サミ・ゼインの話（字幕を全文確認）", "src": [["番組のYouTube（1:05:27〜）", "https://www.youtube.com/watch?v=MSMKAW_qmco&t=3927s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-MSMKAW_qmco", d: "2023-04-28", show: "ext", who: ["Sami Zayn"], t: "サミ・ゼインの回　20ドルの試合から、人を見る目まで", lead: "アンドリュー・サンティーノの番組に出た約112分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Sami Zayn"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-MSMKAW_qmco").map((x) => [x.t, x.b, x.sp])), open: ["今後の予測や社会論、聞き手側の話題（聞き手の仕事や経験）は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=MSMKAW_qmco"]] });
  if (!ROSTER.find((r) => r[1] === "Vic Joseph")) ROSTER.push(["ヴィック・ジョセフ", "Vic Joseph", "lg", "実況", "", "", ""]);
  if (!PROFILES["Vic Joseph"]) PROFILES["Vic Joseph"] = { lead: "地元クリーブランドでの安定したスポーツ実況の仕事を手放し、「12か月で決める」と自分に賭けてWWEの実況席をつかんだ人。目標はレッスルマニアのメインを実況すること。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Vic%20Joseph"]], moves: [], facts: [] };
  if (PROFILES["Vic Joseph"]._weak) { PROFILES["Vic Joseph"].lead = "地元クリーブランドでの安定したスポーツ実況の仕事を手放し、「12か月で決める」と自分に賭けてWWEの実況席をつかんだ人。目標はレッスルマニアのメインを実況すること。"; delete PROFILES["Vic Joseph"]._weak; }
  PROFILES["Vic Joseph"].facts.push(...[{"cat": "リングに来るまで", "t": "クリーブランドのラジオ出身", "b": "もとはクリーブランドのスポーツラジオで働いていて、司会のクリス・ヴァン・ヴリートとは同じ局の向かいの部屋同士だったという。今も地元のNFLブラウンズの大ファンだそうだ。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=46s"]]}, {"cat": "暮らし", "t": "インスタのフォローは43人だけ", "b": "インスタグラムでフォローしているのは43人ほどで、家族と仕事仲間ばかりだという。かつてザ・ロックがモハメド・アリしかフォローしていなかったのがかっこよくて、まねしているそうだ。妻には「変な方針」と言われると笑う。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（2:19〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=139s"]]}, {"cat": "リングに来るまで", "t": "契約更新を断って自分に賭けた", "b": "地元局とブラウンズの中継から2年の契約更新を打診されたとき、WWEに入るために「12か月本気でやる」と決めたという。インディー団体の実況も続けていたところ、ロックバンドのライブに向かう前日に、マイケル・コールのオーディションに来ないかと電話が来たそうだ。NBAファイナルも扱った憧れの職場を離れたことは、これまで誰にも話していなかったと明かす。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（5:33〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=333s"]]}, {"cat": "リングの話", "t": "夢はレッスルマニアのメイン", "b": "WWEで働くことだけでなく、レッスルマニアのメインイベントを実況することが目標だという。それが毎週の原動力で、組んだ解説者のおかげで自分も引き上げてもらってきたと話す。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（9:36〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=576s"]]}, {"cat": "リングに来るまで", "t": "人生最大の影響はショーン・マイケルズ", "b": "父に連れられて最前列で見た大会がファンになったきっかけで、一番の憧れはショーン・マイケルズだという。マイケルズが筋書きでリングに倒れたときは、悲しくて学校に行けず、母が休ませてくれたそうだ。今はそのマイケルズがイヤホン越しに指示をくれる立場で、「仕事の上で人生最大の影響を与えた人」と本人にも伝えたと話す。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（10:27〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=627s"]]}, {"cat": "家族", "t": "子どもには好きなことを", "b": "息子はゴミ収集車が大好きで、「それなら最高の収集員になれ」と言っているという。娘は歌って踊るのが好きだそうだ。好きなことを仕事にすれば一日も働いた気がしない、と子どもたちにも伝えたいと話す。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（13:36〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=816s"]]}, {"cat": "好きなもの", "t": "植物の水やりが生きがい", "b": "仕事のない日は、朝コーヒーを手に植物に水をやるのが日課だという。草刈りは嫌いでも水やりは好きで、花が枯れたときは妻に「生きる目的を失った」と言ったほどだそうだ。自分を「退屈な人間」と言い、だからSNSにも投稿しないと笑う。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（15:10〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=910s"]]}, {"cat": "リングの話", "t": "実況は主役ではない", "b": "実況者は主役ではなく、選手の名場面に寄り添って一緒に残る存在だと考えているという。一番ほめられるのは、レイ・ミステリオ対ブロック・レスナーで思わず一ファンに戻って声が裏返った実況だそうだ。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（16:45〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=1005s"]]}, {"cat": "暮らし", "t": "リング名の由来", "b": "本名の名字はつづりも発音も難しく、リング名の「ジョセフ」は兄と大叔父の名前から取ったという。本当はゲームで作った架空の選手の名前を使いたかったが、通らなかったそうだ。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（21:36〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=1296s"]]}, {"cat": "家族", "t": "妻もWWEのインタビュアー", "b": "妻もWWEで控室インタビューなどを担当していて、職場で出会ったという。服装や髪型を整えてくれるのも妻で、仕事の上の影響はマイケルズ、人として良くなりたいと思わせてくれるのは妻だと話す。アイスクリーム好きで、ジムに行くよう勧められているそうだ。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（23:12〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=1392s"]]}, {"cat": "好きなもの", "t": "トム・クルーズの大ファン", "b": "一番好きな俳優はトム・クルーズで、パリで本人に会えたことがあるという。映画館では大きなポップコーンのバケツを抱えて見て、そのバケツを今も使っているそうだ。", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-SPIYC9ZwCL4", "src": [["番組のYouTube（27:16〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=1636s"]]}]);
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "子どもにカップケーキ", "b": "レインズは、ヴィックの息子にカップケーキを渡し、「人の子が甘いものではしゃぐのを見るのが好きなんだ」と冗談を言ったと、ヴィック・ジョセフが話している", "sp": "ヴィック・ジョセフ", "d": "2023-06-01", "how": "クリス・ヴァン・ヴリートの番組で、ヴィック・ジョセフの話（字幕を全文確認）", "src": [["番組のYouTube（27:16〜）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4&t=1636s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-SPIYC9ZwCL4", d: "2023-06-01", show: "ext", who: ["Vic Joseph"], t: "ヴィック・ジョセフの回　自分に賭けた12か月", lead: "クリス・ヴァン・ヴリートの番組に出た約58分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Vic Joseph"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-SPIYC9ZwCL4").map((x) => [x.t, x.b, x.sp])), open: ["後半（30分以降）の話は今回は読んでいない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=SPIYC9ZwCL4"]] });
  if (!ROSTER.find((r) => r[1] === "Dory Funk Jr.")) ROSTER.push(["ドリー・ファンクJr.", "Dory Funk Jr.", "lg", "元NWA世界王者", "", "", ""]);
  if (!PROFILES["Dory Funk Jr."]) PROFILES["Dory Funk Jr."] = { lead: "テキサスのプロレス一家に生まれ、父の教えでアマレスと大学を経てリングへ。日本でも愛された名王者が、父や弟テリー、若き日の仲間との思い出を笑いまじりに語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dory%20Funk%20Jr."]], moves: [], facts: [] };
  if (PROFILES["Dory Funk Jr."]._weak) { PROFILES["Dory Funk Jr."].lead = "テキサスのプロレス一家に生まれ、父の教えでアマレスと大学を経てリングへ。日本でも愛された名王者が、父や弟テリー、若き日の仲間との思い出を笑いまじりに語る。"; delete PROFILES["Dory Funk Jr."]._weak; }
  PROFILES["Dory Funk Jr."].facts.push(...[{"cat": "家族", "t": "父はアマレスの名選手", "b": "父ドリー・ファンク・シニアはインディアナ州の高校レスリングで3度州王者になり、インディアナ大学でも活躍した名選手だったという。父が期待するすべてに応えようと努めてきたそうで、自分もアマチュアレスリングで西テキサスの大会を制したと話す。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（2:18〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=138s"]]}, {"cat": "リングに来るまで", "t": "大学ではアメフト選手", "b": "ウェストテキサス州立大学でアメフトをしていたという。同じ大学からは弟テリーやダスティ・ローデスら多くのレスラーが出たが、在籍を名乗るだけの人もいたと冗談を言う。大学最後の試合となったボウルゲームでは、1度のブロックで2人を倒したと胸を張っている。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（3:54〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=234s"]]}, {"cat": "家族", "t": "インディアナからテキサスへ", "b": "子どものころ、一家は国道66号線で約1800キロ離れたインディアナからテキサス州アマリロへ移ったという。父はいつも飛ばし屋で、24時間で行き来していたそうだ。父は地元の団体をわずか1万ドルで買い取ったと話す。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（8:40〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=520s"]]}, {"cat": "家族", "t": "父の2つの条件", "b": "父はプロレスが心から好きで、亡くなる直前まで選手を続けていたという。息子たちには「運動選手であること」と「大学を卒業すること」を求め、弟テリーも大学ではアメフトをし、シーズンが終わるとリングに上がっていたそうだ。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（10:17〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=617s"]]}, {"cat": "リングに来るまで", "t": "1年目でアメフトより稼げた", "b": "プロのアメフト選手になるつもりはなかったという。当時のプロ選手の年俸が1万5千ドルほどだったのに、プロレス1年目で2万ドル稼げたので迷いはなかったそうだ。ボウルゲームから戻った飛行機のタラップで、そのまま契約書に署名したと話す。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（14:14〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=854s"]]}, {"cat": "リングの話", "t": "ルー・テーズと60分", "b": "1963年、地元アマリロでNWA世界王者ルー・テーズと60分引き分けの試合をしたという。テーズは素晴らしいレスラーだったと話す。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（18:10〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=1090s"]]}, {"cat": "リングの話", "t": "1969年に初来日", "b": "初めて日本に行ったのは1969年だという。当時の日本はいすで殴るような反則より、アマレスに近い本格的なレスリングが中心で、報酬も世界王者並みに良かったそうだ。自分のベストバウトは、ブリスコ兄弟との試合ばかりだと話す。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（19:46〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=1186s"]]}, {"cat": "家族", "t": "弟テリーと車3台", "b": "弟テリーとジャック・ブリスコが、1日に車を3台壊したという話は本当だという。父の車を2台壊したと知った父の反応は、放送では言えないほどの言葉だったと笑う。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（26:20〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=1580s"]]}, {"cat": "リングの話", "t": "エディ・グラハムの操縦で冷や汗", "b": "フロリダでプロモーターのエディ・グラハムが操縦する小型機に乗った際、酒が入った状態で雨雲を避けようと海の上に出てしまったという。自分も操縦免許を持っていたが後ろの席で何もできず、叫んで引き返させたそうだ。神様が見守ってくれたと振り返る。", "sp": "ドリー・ファンクJr.", "d": "2023-07-06", "how": "ブリスコとブラッドショーの番組（WWE関連のトーク番組）で（字幕を全文確認）", "art": "ext-jJBvbSQ_Qik", "src": [["番組のYouTube（33:43〜）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik&t=2023s"]]}]);
  ARTICLES.push({ id: "ext-jJBvbSQ_Qik", d: "2023-07-06", show: "ext", who: ["Dory Funk Jr."], t: "ドリー・ファンクJr.の回　父と弟、テキサスの日々", lead: "ブリスコとブラッドショーの番組（WWE関連のトーク番組）に出た約72分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Dory Funk Jr."].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-jJBvbSQ_Qik").map((x) => [x.t, x.b, x.sp])), open: ["39分以降（世界王者時代の話など）は今回は読んでいない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=jJBvbSQ_Qik"]] });
