  if (!PROFILES["Adam Cole"]) PROFILES["Adam Cole"] = { lead: "NXTで試合の組み立てを磨き、ショーン・マイケルズを師と仰いだアダム・コール。進行中の抗争を最後までやり切ってから、自ら他団体への移籍を選んだ経緯を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Adam%20Cole"]], moves: [], facts: [] };
  if (PROFILES["Adam Cole"]._weak) { PROFILES["Adam Cole"].lead = "NXTで試合の組み立てを磨き、ショーン・マイケルズを師と仰いだアダム・コール。進行中の抗争を最後までやり切ってから、自ら他団体への移籍を選んだ経緯を語った。"; delete PROFILES["Adam Cole"]._weak; }
  PROFILES["Adam Cole"].facts.push(...[{"cat": "WWEでの日々", "t": "二人のボスの共通点を語る", "b": "WWE側のトリプルHと、移籍先のトニー・カーンの両方の下で働いた経験があるという。違いより共通点を挙げるほうが簡単だと話す。二人ともプロレスに全身全霊を注ぎ、団体運営でも似た考え方をしていて、意見が合う点が多いと感じているそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（18:31〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1111s"]]}, {"cat": "WWEでの日々", "t": "著名人との試合を任された重圧", "b": "NXT時代、プロレスラーではない人物との注目度の高い一戦を任された。大きな重圧だったが、その役を託されたことを大きな褒め言葉としても受け止めたという。外から来た相手が新しい観客を連れてくる意味も理解していたと話す。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（20:05〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1205s"]]}, {"cat": "退団の理由", "t": "抗争を終えてから去ると決めていた", "b": "NXTを離れる際、進行中だった長年の相棒との抗争を途中で終わらせたくなかったと本人は話す。ストーリーを最後までやり切ることが、相手への敬意であり自分にとって最優先だったという。迷いはなく、考えるまでもない決断だったそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（23:27〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1407s"]]}, {"cat": "WWEでの日々", "t": "NXTで演者として大きく成長した", "b": "NXTでは学ぶことが多く、自分らしさをさらに掘り下げられたと感じているという。トリプルH、ショーン・マイケルズ、マット・ブルームら団体の人々への愛情と敬意は今も変わらないと話す。「じゃあね」と去る気にはなれなかったそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（24:13〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1453s"]]}, {"cat": "WWEでの日々", "t": "憧れのショーン・マイケルズが師に", "b": "ショーン・マイケルズは子どもの頃からの一番好きなレスラーで、NXTで師として学べたことを何より大切にしているという。観客の反応を聞き取って試合を調整する力は、彼の下で大きく変わったと話す。大舞台の試合後、控室で飛び跳ねて喜び、抱きしめてくれたことは観客の歓声以上にうれしかったそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（25:02〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1502s"]]}, {"cat": "退団の理由", "t": "マネージャー転向の話は聞いていない", "b": "契約更新の場合に、マネージャーにして髪を切らせる案があったと報じられたが、自分はそんな提案を一度も聞いていないと本人は話す。そうした案が社内で出て伝言のように広まった可能性までは否定しないが、実際のところは分からないという。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（27:29〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1649s"]]}, {"cat": "退団の理由", "t": "他団体を選んだ複数の理由", "b": "仮にその提案を受けていても、同じ選択をしただろうと本人は話す。理由のひとつは、他団体の作品そのもののファンだったこと。もうひとつは、当時は週に1日ほどしか会えなかった大切なパートナーと一緒に移動できること。さらに、WWE時代は禁じられていた配信活動を続けたい思いもあったという。親しい仲間のそばで働けることも後押しになったそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（29:04〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1744s"]]}, {"cat": "退団の理由", "t": "不慣れな役でも挑む姿勢は変わらない", "b": "もしマネージャー役を与えられていたとしても、全力で成立させようとしただろうと本人は話す。居心地のよくない役に挑み、与えられたものに適応することこそ優れたレスラーの条件だと考えているそうだ。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で（字幕を全文確認）", "art": "ext-byNjZ1_P5Rc", "src": [["番組のYouTube（29:49〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1789s"]]}]);
  if (PROFILES["Pat McAfee"]) PROFILES["Pat McAfee"].facts.push({"cat": "暮らし", "t": "パット・マカフィーの適性", "b": "意見は合わないと冗談めかしつつ、パット・マカフィーは魚が水に入るようにプロレスになじんだと、アダム・コールが話している。口の達者さと運動能力に加え、長年見てきたプロレスへの愛と敬意があり、経験の割にとても優れていると評価しているという。", "sp": "アダム・コール", "d": "2023-09-22", "how": "インサイド・ドロップスの番組（Inside Drops）で、アダム・コールの話（字幕を全文確認）", "src": [["番組のYouTube（20:55〜）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc&t=1255s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-byNjZ1_P5Rc", d: "2023-09-22", show: "ext", who: ["Adam Cole"], t: "アダム・コールの回　WWEを離れた理由と、NXTでの日々", lead: "インサイド・ドロップスの番組（Inside Drops）に出た約38分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Adam Cole"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-byNjZ1_P5Rc").map((x) => [x.t, x.b, x.sp])), open: ["移籍後の試合や他団体での話、パートナーや相棒の体の話など、WWE以外の話題は公開項目から省いた。", "自動字幕のため、一部の固有名詞や時期の発言は聞き取れず、確信の持てない箇所は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=byNjZ1_P5Rc"]] });
  if (!ROSTER.find((r) => r[1] === "Carmelo Hayes")) ROSTER.push(["カーメロ・ヘイズ", "Carmelo Hayes", "lg", "NXTの若きスター", "", "", ""]);
  if (!PROFILES["Carmelo Hayes"]) PROFILES["Carmelo Hayes"] = { lead: "インディー団体で腕を磨き、育成ブランドNXTで頭角を現したカーメロ・ヘイズ。「未来」と呼ばれる重圧を受け止めつつ、いまこの瞬間を楽しんでほしいと語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Carmelo%20Hayes"]], moves: [], facts: [] };
  if (PROFILES["Carmelo Hayes"]._weak) { PROFILES["Carmelo Hayes"].lead = "インディー団体で腕を磨き、育成ブランドNXTで頭角を現したカーメロ・ヘイズ。「未来」と呼ばれる重圧を受け止めつつ、いまこの瞬間を楽しんでほしいと語る。"; delete PROFILES["Carmelo Hayes"]._weak; }
  PROFILES["Carmelo Hayes"].facts.push(...[{"cat": "リングの話", "t": "「自分は本当に主役か」と自問する", "b": "王座を持っていない状態で、それでも「主役」と言えるのかを自分に問い続けているという。勝っているときに主役を名乗るのは簡単で、何も持たない時こそ中身が試されると話す。その答えをまだ探している最中だそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=45s"]]}, {"cat": "リングの話", "t": "学ぶのは勝ちより負けから", "b": "勝ちより負けから学ぶことのほうが多いと話す。NXTでは王座を持っていた期間のほうが長く、追いかける側に回る経験は少なかったという。頂点から落ちて這い上がる過程にこそ自分が現れると考えている。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=94s"]]}, {"cat": "リングの話", "t": "王者でない気楽さと、それでも王座を欲しい理由", "b": "王座を持たないと、常に注目される重圧からは少し解放されるという。ただ、レスラーである以上は王者を目指さないなら意味がないとも話す。もう一度王座に戻りたいという思いははっきりしているそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（2:21〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=141s"]]}, {"cat": "リングの話", "t": "NXTでの活躍が「NXT版レッスルマニア」と呼ばれた", "b": "NXTの大きな大会で、ジョン・シーナやアンダーテイカーが登場する流れの中心にいた。周囲からも大きな反響があり、翌日は連絡が相次いだという。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（2:21〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=141s"]]}, {"cat": "リングの話", "t": "大物との共演は夢のようだった", "b": "大きな舞台でレジェンドたちと絡んだ日を、熱に浮かされた夢のようだったと振り返る。プロとして役割に集中する自分と、子どもに戻って感動する自分が同時にいたという。最後の場面は事前に知らされておらず、一緒に歩いて戻る間、少年のように興奮していたそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=190s"]]}, {"cat": "リングの話", "t": "アンダーテイカーらとは以前から交流があった", "b": "あの共演が初対面だったわけではなく、アンダーテイカーには以前に1時間ほど座って話を聞いてもらったことがあるという。ジョン・シーナにも同じように話を聞いている。お互いに顔見知りだったから、なおさら良かったと話す。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=238s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズから学んだのは表情と人物像", "b": "毎週のように接するショーン・マイケルズからは、技そのものより表情や佇まい、キャラクターの作り方を多く学んだという。本人から、いま作っているものを誇りに思うと言われたことが励みになっているそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（4:45〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=285s"]]}, {"cat": "リングの話", "t": "独立系で培った技術に演技を足した", "b": "入ったばかりの頃のNXTは技の完成度を重視する時期で、その後キャラクター重視に変わったという。インディーでは演技派ではなかったが、テレビで通用するには両方が必要だと気づいたそうだ。いまも学び続けていると話す。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=336s"]]}, {"cat": "リングに来るまで", "t": "18、19歳で体験キャンプに誘われた", "b": "友人に誘われた一日限りの体験キャンプで、初めてレスリングの練習に触れたという。昔からレスラーに憧れていたが、体が小さく、どうやって入るのかも分からず遠い夢だと思っていたそうだ。その頃は団体の番組もあまり見ていなかったと話す。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（6:23〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=383s"]]}, {"cat": "リングの話", "t": "「カーメロ・ヘイズ」の名前は上層部との合作", "b": "契約にあたり、人に伝わりやすく使い古されていない名前を探したという。スポーツや音楽の文化を意識して「カーメロ」を出し、「ヘイズ」は別の綴りの案だった。幹部に派手すぎると言われ、結果として今の形になったそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（7:14〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=434s"]]}, {"cat": "リングに来るまで", "t": "インディー時代の名前はクリスチャン・カサノバ", "b": "体験キャンプで名前を求められ、本名のクリスチャンに「カサノバ」を付けて、なめらかな響きで決めたという。初めての試合会場で主催者に悪い名前だと言われたが、結局そのまま使い続けたそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（7:14〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=434s"]]}, {"cat": "リングに来るまで", "t": "名前を変えたのは自分の成長に合わせて", "b": "プロレスの世界では変化が必要だと考え、少年期からこの世界で育った自分の変化が名前にも表れたと話す。契約時に新しい名前になるのは当然だとも受け止めている。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（8:01〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=481s"]]}, {"cat": "好きなもの", "t": "ミュージシャンのマイケル・ヘイズに「父」と呼ぶ", "b": "リングネームの流れから、マイケル・ヘイズと会うたびに冗談で「父さん」と呼んでいるという。向こうも「うちの息子だ」と返してくれるそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（8:47〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=527s"]]}, {"cat": "好きなもの", "t": "プロレスにハマったのは29歳の世代ならではの時期", "b": "本人は29歳で、団体の過激な時代の終わりから、ルースレス・アグレッション期の番組に夢中になったという。ケーブルのない家庭で、たまたまチャンネルを回していて見たスマックダウンの物語性に引き込まれたそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（8:47〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=527s"]]}, {"cat": "好きなもの", "t": "見逃せない時代、ビデオで何度も観た", "b": "ケーブルが入ってからは月曜や木曜、日曜の番組まで何でも見たという。ネットで見直せない時代で、友人が録画したビデオを借りたり、2、3本のビデオを繰り返し再生したりして、当時のアティテュード時代を知ったと話す。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（10:20〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=620s"]]}, {"cat": "好きなもの", "t": "憧れはレイ・ミステリオやエディ・ゲレロ", "b": "見始めた頃に好きだったのは、レイ・ミステリオ、エッジ、エディ・ゲレロ、ジョン・シーナ、ケイン、ロブ・ヴァン・ダム、ストーンコールドなどだという。レイ・ミステリオのデビューを見たことが時期の目安になっているそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（11:05〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=665s"]]}, {"cat": "リングの話", "t": "インディー出身の経験が強みになっている", "b": "同期にはインディー経験者が少なく、ほかの人が初めて味わう失敗や生放送のトラブルも、自分は観客50人・報酬50ドルの会場で先に経験してきたという。そのため大きな舞台でも落ち着いていられると話す。仲間への敬意も口にしている。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（13:26〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=806s"]]}, {"cat": "リングの話", "t": "イリヤ・ドラグノフとは言葉なしで全力を出す", "b": "試合前にイリヤ・ドラグノフと細かい打ち合わせはなく、「全力でいくのが当たり前」という暗黙の了解があるという。激しい試合ほど評価されるので、迷わず出し切ると話す。ブロン・ブレイカーとの対戦では、自分が3戦3敗だと笑っている。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（15:04〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=904s"]]}, {"cat": "リングの話", "t": "先取りで語られず、いまを楽しんでほしい", "b": "「メインロースターへ行く」という話ばかりされるのは嫌ではないが、いまの時期を味わってほしいと話す。一年前は先のことで落ち着かなかったが、今の姿は一度しかないと思うようになったそうだ。上に行けばまた一からの出直しで、今の形は同じではないとも語る。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（16:42〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1002s"]]}, {"cat": "好きなもの", "t": "夢の対戦相手はエディ・ゲレロ", "b": "年齢も全盛期も関係なく一人選ぶなら、エディ・ゲレロとの試合がしたいと話す。ほかにもたくさんいるが、ずっと好きな存在だという。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（17:30〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1050s"]]}, {"cat": "リングの話", "t": "表情と間は先輩から無意識に受け継いでいる", "b": "ショーン・マイケルズの試合の見せ方から、場面の作り方や表情のつけ方を無意識に受け取っているという。ただ、長年積み上げた信頼があるから許される動きもあると理解していて、なんでも真似はしないそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（19:05〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1145s"]]}, {"cat": "リングの話", "t": "コーディ・ローデスの復帰戦の相手に選ばれた", "b": "コーディ・ローデスが年間最大級の大会へ向けて復帰する際、練習相手にジョー・ゲイシーと自分が選ばれたという。ゲイシーは大柄、自分は俊敏という組み合わせだったらしい。助けるどころか自分が教わったと話し、テンポや緩急の付け方に大きな差を感じたそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（22:18〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1338s"]]}, {"cat": "暮らし", "t": "試合を見すぎないようにしている", "b": "レスリングの映像は、見すぎると他人に似てしまうので意識して控えているという。誰かの後継者のように言われるより、自分だけの型を作りたいそうだ。数々の先輩から小さな要素だけを拾い、将来は「カーメロのようになりたい」と言われる存在を目指している。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（24:01〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1441s"]]}, {"cat": "暮らし", "t": "技のアイデアは眠る前や夢から生まれる", "b": "寝つく前に新しい動きを思いつくことが多く、夢で見たものを翌日に試すこともあるという。技だけでなく、その場面で本当に何を感じるかも考えるそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（24:51〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1491s"]]}, {"cat": "暮らし", "t": "先輩の助言はノートに書き留める", "b": "ベテランから聞いた話は、真剣に聞いている証しになり、忘れないためにもなるので、必ず書き留めているという。人ごとに分けたメモ帳もあると話す。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（25:37〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1537s"]]}, {"cat": "リングの話", "t": "「世代交代の瞬間」とは受け止めていない", "b": "アンダーテイカーが腕を上げた場面を「バトンタッチ」と見るファンもいるが、本人は仕事として臨んだという。来週もテレビ収録があり、先輩たちはそこにいないので、意味を考え込まないようにしていると話す。最高にかっこよかったことは認めている。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（26:27〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1587s"]]}, {"cat": "リングの話", "t": "見てほしい試合はリコシェ戦とドラグノフ戦", "b": "初めて見る人にすすめたい試合として、実力を試された感覚があったリコシェ戦と、派手さとは違う一面を見せられた夏の大会でのドラグノフ戦を挙げている。どちらも互いに打ち合った試合だったという。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（27:16〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1636s"]]}, {"cat": "リングの話", "t": "仲間への襲撃疑惑には身の潔白を主張", "b": "仲間のトリック・ウィリアムズを襲ったのではと聞かれ、証拠はなく、まるで魔女狩りだと笑って返している。自分は潔白で、そのうち謝ってもらうことになると話す。王座のことで大事な友人にそんなことはしないと言い切った。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（28:05〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1685s"]]}, {"cat": "暮らし", "t": "毎日感謝を数える習慣がある", "b": "感謝していることは、健康、心の持ちよう、周りの人たちとその支えの三つだと話す。毎日自分の中で感謝すべきことを振り返っており、挙げればまだ続くそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Tq49l3iHEOw", "src": [["番組のYouTube（29:46〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1786s"]]}]);
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "膝を固めれば今でも動けると話すショーン・マイケルズ", "b": "膝をテーピングすれば、今でも若手を相手に動き回れると本人が話していた、と、カーメロ・ヘイズが話している。体は別として、やる気はあるという口ぶりだったそうだ。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で、カーメロ・ヘイズの話（字幕を全文確認）", "src": [["番組のYouTube（18:18〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1098s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "若手が見る名勝負は積み上げの結果だと語るショーン・マイケルズ", "b": "育成施設で自分たちの名勝負が教材に使われることについて、何十年もかけて名前を作ってきたから成り立つのだと冗談を言っていた、と、カーメロ・ヘイズが話している。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で、カーメロ・ヘイズの話（字幕を全文確認）", "src": [["番組のYouTube（19:55〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1195s"]], "by": "第三者の話"});
  if (PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"].facts.push({"cat": "暮らし", "t": "緩急の付け方が学びになるベッキー・リンチ", "b": "経験豊富なベッキー・リンチの試合を近くで見ると、盛り上げどころと緩めるところの使い分けに何年分もの知恵を感じる、と、カーメロ・ヘイズが話している。", "sp": "カーメロ・ヘイズ", "d": "2023-10-31", "how": "クリス・ヴァン・ヴリートの番組で、カーメロ・ヘイズの話（字幕を全文確認）", "src": [["番組のYouTube（23:08〜）", "https://www.youtube.com/watch?v=Tq49l3iHEOw&t=1388s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Tq49l3iHEOw", d: "2023-10-31", show: "ext", who: ["Carmelo Hayes"], t: "カーメロ・ヘイズの回　「未来」と呼ばれる重圧と、憧れの先輩たち", lead: "クリス・ヴァン・ヴリートの番組に出た約30分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Carmelo Hayes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Tq49l3iHEOw").map((x) => [x.t, x.b, x.sp])), open: ["トリック・ウィリアムズへの襲撃疑惑など、当時進行中の筋書きに関する発言は、本人の主張として短く触れるにとどめた。", "聞き手が語った放送キャリアの話や、番組中の聞き手側の発言は載せていない。", "字幕は自動生成で固有名詞が崩れている箇所があり、確信の持てない名前は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Tq49l3iHEOw"]] });
