  if (!PROFILES["B-Fab"]) PROFILES["B-Fab"] = { lead: "音楽が最初の恋人だと語るBファブ。ジャンルを混ぜるソロ活動と仲間との曲づくり、父や母の影響を明るく話している。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=B-Fab"]], moves: [], facts: [] };
