  PROFILES["B-Fab"].facts.push(...[{"cat": "好きなもの", "t": "ローリン・ヒルとニッキー・ミナージュ", "b": "二択ではローリン・ヒルを選ぶが、ジャンルを越えて活躍するニッキー・ミナージュの幅広さも尊敬していると話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（3:06〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=186s"]]}, {"cat": "好きなもの", "t": "ソロでは全部の味を出せる", "b": "ソロとグループでは、自分らしさをいちばん出せるのはソロだと話す。ポップもトラップも気分次第で作れるのが楽しいそうだ。熱心なファンはソロ作を好み、広く届くのはグループ曲だと感じているという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（3:52〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=232s"]]}, {"cat": "好きなもの", "t": "カントリーまで歌う音楽好き", "b": "ラップだけでなく、ロックやカントリー、ポップなど色々なジャンルに挑戦してきたという。曲を作るなら、あらゆる音楽を自由に行き来できるのが本当の自分だと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（4:41〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=281s"]]}, {"cat": "好きなもの", "t": "レーベルを作るならアリシア・キーズ", "b": "全盛期の歌手と組んでレーベルを作るなら、アリシア・キーズを選ぶと話す。ピアノも弾き、色々な音楽に触れてきた彼女なら、良いアーティストを見抜けるはずだと考えているそうだ。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（5:32〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=332s"]]}, {"cat": "好きなもの", "t": "理想の一曲はアイス・キューブとイヴ", "b": "番組の遊びで曲づくりをする企画に参加。レーベルは南部で人気の高いところ、ラッパーはアイス・キューブ、女性ラッパーはイヴ、サビはレディー・ガガを選んだ。曲名は「Nothing Like It」だという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（7:05〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=425s"]]}, {"cat": "リングの話", "t": "入場曲を贈るならサーシャ・バンクスに", "b": "その曲をレスラーの入場曲にするなら誰かと聞かれ、サーシャ・バンクスだと答える。自分が入るグループ向けにしてもよいと言われ、仲間のヒットメイカーズに贈ることにしたと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（11:57〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=717s"]]}, {"cat": "リングに来るまで", "t": "テキサスのツアーとLAの前座", "b": "ジューシーJとテキサスを回るツアーに参加し、ポール・ウォールらも一緒だったという。アリゾナに住みながら車でカリフォルニアへ通い、ソルジャ・ボーイなどの前座を何度も務めた。必死に動いて人脈を作った経験が大切だと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（13:32〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=812s"]]}, {"cat": "家族", "t": "スタジオで育った父親の影響", "b": "父親がラップのグループにいて、週末に会いに行くとずっとスタジオにいたという。そこで音楽の作り方を見て育ち、自分も早くから書き始めたと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（15:04〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=904s"]]}, {"cat": "リングに来るまで", "t": "7歳から書き、13歳で父に初披露", "b": "7歳ごろからノートにラップを書いていたが、恥ずかしくて誰にも聞かせなかったそうだ。父に初めて聞かせたのは13歳ごろで、父はその出来に驚いたという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（15:53〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=953s"]]}, {"cat": "家族", "t": "ヴァースは父に勝ち、フックは父が上", "b": "今の自分は父よりヴァースが上だと笑って話す。ただ父は何もないところからフックを作れる名人で、その技は父から受け継いだと認めている。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（17:29〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1049s"]]}, {"cat": "好きなもの", "t": "ミッシー・エリオットに開かれた視界", "b": "幼いころはミッシー・エリオットが大好きだったという。ヒップホップを個性的な映像や他ジャンルと混ぜる姿に、ヒップホップの見せ方は一つではないと気づかされ、自分もジャンルを混ぜたいと思うようになった。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（19:04〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1144s"]]}, {"cat": "暮らし", "t": "作りかけの名曲は消えるが慌てない", "b": "車の中などで思いついた曲を録音し忘れ、消えてしまうことがよくあるそうだ。ただ、また別の良いものが浮かぶと信じていて、あまり落ち込まないと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（20:42〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1242s"]]}, {"cat": "暮らし", "t": "歌詞を忘れるのがいちばん怖い", "b": "ステージで歌詞が飛ぶのは準備不足の証拠だと考え、パフォーマンスに誇りがあるぶん、いちばん嫌なことだと話す。もしそうなったら即興のラップで乗り切る自信はあるという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（21:27〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1287s"]]}, {"cat": "暮らし", "t": "一度に4、5曲を並行して作る", "b": "一曲をじっくり磨くタイプではなく、リル・ウェインのように何曲も同時に進めるタイプだと話す。創造力が落ちたら別の曲に移って新鮮さを保ち、仕上げの段階で一気に整えるそうだ。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（23:07〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1387s"]]}, {"cat": "好きなもの", "t": "共作したいのはウィロー・スミス", "b": "自分が挑戦を受ける共作相手として、オルタナ寄りで流れが次々変わるウィロー・スミスを挙げる。ファレルとの共作も、勢いのある自分の癖を抑えさせられそうで面白いと話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（24:42〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1482s"]]}, {"cat": "リングの話", "t": "グループは全員が輝ける関係", "b": "ヒットメイカーズは互いの持ち味が違い、競い合う必要がないのが幸運だと話す。入場曲を作るときも先に出番を譲り合ったそうだ。自分はノリと色気で勝負するタイプだという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（27:54〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1674s"]]}, {"cat": "暮らし", "t": "ソロ曲「Focus」を準備中", "b": "単発の曲を重ねてEPにするやり方が好きで、ソロの新曲を出す予定だと話す。ビジュアライザーも付けるそうで、最近は客演が多かったので自分名義の曲は久々だという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（31:49〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=1909s"]]}, {"cat": "体のこと", "t": "ジムは「習慣」だと割り切る", "b": "運動は選択の余地がない生活の一部だと話す。ジムが大好きなわけではなく、鏡で自分を見て納得できるかが大事だという。体重計や他人と比べないことを人にも勧めている。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（33:28〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2008s"]]}, {"cat": "体のこと", "t": "高校ではフットボール、短時間集中", "b": "高校ではフットボールをしていたという。今も約45分で濃く終わらせて、浜辺などほかのことをする時間を取りたいと話す。長時間いるより集中して終えるのがよいと考えているそうだ。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（35:03〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2103s"]]}, {"cat": "暮らし", "t": "直したいのは予定の把握", "b": "予定が詰まりすぎていて日々が溶け合い、何があるかをうっかり忘れることがあると話す。実際に落とすことはないが、もっと把握しておきたいそうだ。人に任せるのは信頼の面で難しいとも話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（36:43〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2203s"]]}, {"cat": "家族", "t": "家族の問題から自分の道を選んだ", "b": "育つ中で家族の問題が多く、それに引きずられず自分の道を選ぶ必要があったと話す。今は一部の親族とは連絡を取っていないが、愛していても生活に入れない距離の取り方を学んだという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（38:18〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2298s"]]}, {"cat": "リングに来るまで", "t": "夢は大ヒット曲と、腰にベルト", "b": "まだ叶えていないことは、ヒットする大きな曲を出すことだと話す。音楽は最初の恋人のような存在で、プラチナ認定を受けたいそうだ。ベルトも腰に巻けたら最高だと笑っている。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（40:44〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2444s"]]}, {"cat": "暮らし", "t": "投資や暗号資産を学びたい", "b": "暗号資産やトレードに興味があり、教えてくれる人がいれば吸収したいと話す。友人から泊まりで教える提案を受けていて、教え合う約束を番組で交わしていた。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（42:20〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2540s"]]}, {"cat": "家族", "t": "母は大きな夢を否定しなかった", "b": "11歳の自分に声をかけるなら、感じていた大きな予感は正しいと伝えたいと話す。母は子どもたちのどんな大きな夢も否定せず、育ててくれたという。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（45:37〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2737s"]]}, {"cat": "暮らし", "t": "30年後は知らないまま生きたい", "b": "30年後の自分と話せるとしても、結果を知らずに体験していきたいと答える。生え際が今のままで、見た目と自信が保てていればいいと冗談まじりに話す。", "sp": "Bファブ", "d": "2023-11-10", "how": "モンティージー（Teasy's Table）の番組で（字幕を全文確認）", "art": "ext-ptxuSjjYjo4", "src": [["番組のYouTube（46:22〜）", "https://www.youtube.com/watch?v=ptxuSjjYjo4&t=2782s"]]}]);
  ARTICLES.push({ id: "ext-ptxuSjjYjo4", d: "2023-11-10", show: "ext", who: ["B-Fab"], t: "Bファブの回　ラップと家族、ジムと夢", lead: "モンティージー（Teasy's Table）の番組に出た約50分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["B-Fab"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ptxuSjjYjo4").map((x) => [x.t, x.b, x.sp])), open: ["広告や宣伝、ホストの友人とのやりとりは省いた。", "家族との不和は要点のみ記載。字幕の崩れで聞き取れない箇所があった。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ptxuSjjYjo4"]] });
  if (!ROSTER.find((r) => r[1] === "Shinsuke Nakamura")) ROSTER.push(["中邑真輔", "Shinsuke Nakamura", "lg", "元新日本の人気レスラー", "", "", ""]);
  if (!PROFILES["Shinsuke Nakamura"]) PROFILES["Shinsuke Nakamura"] = { lead: "子供の頃から海外に憧れ、プロレスでその夢をかなえた中邑真輔。弱みさえ武器に変える発想と、観客と熱を交換する喜びを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Shinsuke%20Nakamura"]], moves: [], facts: [] };
  if (PROFILES["Shinsuke Nakamura"]._weak) { PROFILES["Shinsuke Nakamura"].lead = "子供の頃から海外に憧れ、プロレスでその夢をかなえた中邑真輔。弱みさえ武器に変える発想と、観客と熱を交換する喜びを語る。"; delete PROFILES["Shinsuke Nakamura"]._weak; }
  PROFILES["Shinsuke Nakamura"].facts.push(...[{"cat": "リングの話", "t": "最後に立っていた方が勝つ特別ルールの一戦", "b": "番組で流れた映像は、反則もすべて認められ、場外で戦ってもよい特別ルールの試合だったと中邑真輔は説明する。相手が倒れて10カウントを数えられたら決着という形式だという。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（3:17〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=197s"]]}, {"cat": "リングの話", "t": "テレビ向けの規制は日本より厳しいと話す", "b": "所属する団体はテレビの年齢区分に沿った作りで、安全面の基準は日本よりも厳しいくらいだと中邑真輔は話す。過激に見える試合でも、そこは見せ方の工夫だという。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=242s"]]}, {"cat": "リングの話", "t": "日本での経験を米国向けに微調整してきた", "b": "米国での見せ方は、ほぼ日本で積み重ねてきた経験を土台に、微調整したものだという。米国に渡って7年目になり、その時々のタイミングや流行を敏感に感じ取りながら、変わっていないようで実は結構変えていると中邑真輔は話す。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（4:52〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=292s"]]}, {"cat": "リングの話", "t": "人の戦いは世界共通で見たいもの、客は家族", "b": "世界中に格闘技があるように、人の戦いを見たい気持ちは誰にでもあると中邑真輔は話す。放送先が多い分、ねらう客層は子供を中心にした家族で、親や祖父母も一緒に来るそうだ。先日行ったドイツでも、テレビでしか見られなかった興行を近くで見ようと周辺から客が集まったという。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（7:20〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=440s"]]}, {"cat": "リングに来るまで", "t": "海外への憧れをプロレスでかなえた", "b": "子供の頃から海外への憧れが強く、外国で勉強したいと思っていたという。ただ経済的な理由で留学はできず、プロレスラーになれば海外武者修行という形で夢がかなうと考えた。強くなること、お金持ちになること、海外に行くこと。その夢をすべてかなえてくれたのがプロレスだったと話す。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（8:50〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=530s"]]}, {"cat": "暮らし", "t": "ネット時代は分かった気になりやすい", "b": "昔は雑誌やテレビでしか海外の情報が手に入らなかったが、今はネットですぐ調べられる。そのせいで若い人が知った気になり、実際に行って知りたいという気持ちが満たされてしまうのではないか、と中邑真輔は話す。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=580s"]]}, {"cat": "リングに来るまで", "t": "若手の頃の弱みがキャラの武器になった", "b": "若手の頃、体に芯が入っておらずふにゃふにゃしていると言われ、ひどく怒られたそうだ。ところがあるときその動きをあえて強調してみたところ、それが観客の記憶に残るフックになり、キャラクターになっていったという。自分の強みはよく分かっていないが、弱みも含めた自分の特徴をどう生かすかが大事だと考えている。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（10:29〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=629s"]]}, {"cat": "リングの話", "t": "日本の客は静かで、ドイツの客と似ている", "b": "海外のレスラーの間では、日本の客は難しいとよく言われると中邑真輔は話す。大技が決まっても叫ばず、静かに驚くような反応が多いのだという。ドイツの客も国民性が近く、米国のテレビを見て、恥ずかしがりながらも米国の客のように叫んでいるのが面白かったそうだ。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（11:20〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=680s"]]}, {"cat": "リングの話", "t": "悪役として子供を煽るのが楽しい", "b": "今は悪役の立場で、親指を下に向けて子供たちを煽ると、さらに盛り上がると中邑真輔は話す。汚い言葉は使わず、「お前の母ちゃんデベソ」くらいは言うこともあるそうだ。会場が大きいほど投げかけたものが何倍にもなって返ってきて、次のパフォーマンスも大きくなる。気持ちよすぎるほどのエネルギーの交換だという。", "sp": "中邑真輔", "d": "2023-11-17", "how": "ABEMA Primeの番組で（字幕を全文確認）", "art": "ext-cJMvhh5Ohmo", "src": [["番組のYouTube（13:05〜）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo&t=785s"]]}]);
  ARTICLES.push({ id: "ext-cJMvhh5Ohmo", d: "2023-11-17", show: "ext", who: ["Shinsuke Nakamura"], t: "中邑真輔の回　弱みを武器に、世界で観客を煽る", lead: "ABEMA Primeの番組に出た約15分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Shinsuke Nakamura"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-cJMvhh5Ohmo").map((x) => [x.t, x.b, x.sp])), open: ["字幕が自動生成で名前が崩れているため、日本人レスラー2名への言及は誰か確信が持てず載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=cJMvhh5Ohmo"]] });
  if (!ROSTER.find((r) => r[1] === "Shinsuke Nakamura")) ROSTER.push(["中邑真輔", "Shinsuke Nakamura", "lg", "WWEスーパースター", "", "", ""]);
  if (!PROFILES["Shinsuke Nakamura"]) PROFILES["Shinsuke Nakamura"] = { lead: "アメリカで一人旅のように転戦する日々や、犬にかまれた災難を笑いを交えて語る。猪木や長州ら、新日本時代の思い出も明かしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Shinsuke%20Nakamura"]], moves: [], facts: [] };
  if (PROFILES["Shinsuke Nakamura"]._weak) { PROFILES["Shinsuke Nakamura"].lead = "アメリカで一人旅のように転戦する日々や、犬にかまれた災難を笑いを交えて語る。猪木や長州ら、新日本時代の思い出も明かしている。"; delete PROFILES["Shinsuke Nakamura"]._weak; }
  PROFILES["Shinsuke Nakamura"].facts.push(...[{"cat": "リングの話", "t": "日本語の挑発がアメリカで通じるように", "b": "最近は日本語で相手を挑発することがあるという。ある選手につけられたあだ名の意味を日本語で教えてあげたところ、本人は褒め言葉だと勘違いして喜んだそうだ。観客も日本語が分からないので、みんなが盛り上がったと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（2:26〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=146s"]]}, {"cat": "リングの話", "t": "字幕に慣れた若者たち", "b": "以前のアメリカ人は吹き替えでないと外国映画を見ないほどだったが、最近はアニメの影響もあって字幕を読めるようになったという。日本に一時帰国した夏には、服屋の若い店員から、その日本語の挑発が印象的だったと声をかけられたそうだ。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（4:10〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=250s"]]}, {"cat": "体のこと", "t": "身長は188センチ、サバ読みなし", "b": "身長は実際に188センチで、サバは読んでいないと話す。藤波のトークショーの司会者に身長を聞かれ、藤波が185センチと答えたため、自分は並んで立てなくなったという笑い話もある。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（4:58〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=298s"]]}, {"cat": "暮らし", "t": "移動も宿の手配も自分でこなす", "b": "会場から会場への移動は自分で運転し、ホテルも自分で取るという。四時間半かかる道のりなら、途中のホテルで半分ずつ走ることもあるそうだ。ツアーバスと運転手を雇う選手もいるが、自分はそうしないと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（8:57〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=537s"]]}, {"cat": "好きなもの", "t": "遠征先の日系スーパーと観光めぐり", "b": "移動の合間に日系のスーパーを見つけて立ち寄ったり、観光地を回ったりするのが好きだという。以前は他の選手と動いていたが、今は一人で行動し、洞窟のツアーにも出かけると話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（9:45〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=585s"]]}, {"cat": "体のこと", "t": "爆弾探知犬に足をかまれた", "b": "カリフォルニアの会場で、警察の爆弾探知犬に足をかまれたという。もともと犬は苦手だったが、自分で犬を飼ってから慣れたつもりでいた時のできごとだったそうだ。足にはかまれた跡がくっきり残っている。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（9:45〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=585s"]]}, {"cat": "暮らし", "t": "犬を飼っている", "b": "今は犬を飼っていて、もともとは犬が苦手だったと話す。飼ったことで犬に慣れたと思っていたそうだ。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（10:38〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=638s"]]}, {"cat": "体のこと", "t": "救急車は有料、応急処置は自分で", "b": "かまれたのは試合前で、そのまま出場できなかったという。アメリカでは救急車が有料で、すぐには呼んでもらえなかったそうだ。タオルで巻いて足を上げ、氷を当てるなど、応急処置はほぼ自分でしたと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（12:17〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=737s"]]}, {"cat": "体のこと", "t": "松葉づえで日本ツアーへ", "b": "会社に報告をしたところ帰ってよいと言われたが、二日後には日本ツアーが控えていたという。結局、松葉づえをついたまま日本へ行き、試合には出られなかったと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（13:49〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=829s"]]}, {"cat": "暮らし", "t": "毎日シャワーを浴びるのは日本人くらい", "b": "アメリカでは試合を終えてもシャワーを浴びない選手もいて、国民性の違いだと感じるという。ツアーで着るコスチュームの数も少なく、動くとふわっと匂うことは普通にあるそうだ。毎日髪を洗うのは日本人くらいだと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（16:11〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=971s"]]}, {"cat": "リングの話", "t": "トップ選手とも普通に話す", "b": "ジョン・シナやトリプルHのような大物とも、普通に話をしているという。ただ、プライベートで遊ぶことはなく、みんな住む場所が別々だと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（16:11〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=971s"]]}, {"cat": "暮らし", "t": "アメリカ在住、練習は一人ずつ", "b": "アメリカのレスラーは住む場所がばらばらで、中邑はフロリダのオーランドから会場へ向かうという。日本のように一つの道場に集まることはなく、練習もそれぞれで行うと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（17:02〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1022s"]]}, {"cat": "リングの話", "t": "アメリカの若い選手との養成所生活", "b": "移籍後の最初の1年は、プロレス学校のような育成施設で過ごしたという。自分はすでに十数年のキャリアがあり、けがを避けるためウェイトもしないよう言われ、腫れ物のような扱いだったそうだ。それでも会場の撤収を若手と一緒にやり、面白い経験だったと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（17:50〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1070s"]]}, {"cat": "リングに来るまで", "t": "新日本の象徴から、独断でWWEへ", "b": "新日本プロレスの象徴的な存在だった時期に、アメリカ行きを決めたという。周囲は驚いたが、誰にも相談せず自分ひとりで決めたそうだ。決めたら一気に話が進み、慌ただしい日々だったと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（18:37〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1117s"]]}, {"cat": "リングの話", "t": "他競技出身の新人は上から目線", "b": "若手の中には、インディー団体でプロレスを知り先輩を敬う者もいれば、陸上や野球などから来て先輩にも上から話す者もいたという。そうした人はたいてい消えていったそうで、日本と同じだと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（18:37〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1117s"]]}, {"cat": "リングに来るまで", "t": "もとは新日本の原理主義者だった", "b": "若い頃からアメリカの団体に行きたかったわけではなく、むしろ新日本プロレスの考え方を強く信じていたという。ストロングスタイルを重んじる気持ちが強かったと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（19:31〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1171s"]]}, {"cat": "リングの話", "t": "猪木にビンタされた日", "b": "ロサンゼルスであいさつに行った際、猪木が周囲を集めて驚かせる場面があったという。反射的によけてしまい、これは怒られると思ったが、結局ビンタを受けたと笑って話す。ロサンゼルスの猪木は日本にいる時よりリラックスしていたそうだ。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（20:18〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1218s"]]}, {"cat": "リングの話", "t": "ロサンゼルスで猪木と練習", "b": "ロサンゼルス時代の猪木とは、一緒に練習をして細かい技を教わったり、スパーリングをしたりしたという。早朝にサンタモニカの海岸沿いの公園で、棒を振り回して練習に付き合ったとも話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（21:04〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1264s"]]}, {"cat": "リングの話", "t": "長州の誘いを断り続けた", "b": "2002年に入団した当時、長州が現場の責任者として戻ってきたという。帰りのバスなどで食事に誘われたが、家で待つ人がいると二回ほど断ってしまい、それから誘われなくなったそうだ。最近は共演して一緒に食事もしたと話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（22:39〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1359s"]]}, {"cat": "リングの話", "t": "武藤とは敵として出会った", "b": "若手の頃に武藤と初めて会ったのは敵としてで、自分がチャンピオンの時に挑戦を受け、ベルトを奪われたという。もう一度戦ったが再び負けて悔しく、ファンとしての気持ちをずっと押し殺していたそうだ。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（28:13〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1693s"]]}, {"cat": "リングの話", "t": "グレート・ムタ戦で忘れていた感情", "b": "今年の1月にグレート・ムタと戦った試合では、子供の頃から好きだった気持ちが出てきたという。最後のマイクでもその思いを語り、自分でも忘れていた感情だったと話す。WWEの契約は厳しく、実現は奇跡的なタイミングだったとも話す。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（28:13〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1693s"]]}, {"cat": "リングに来るまで", "t": "藤波の付け人をしていた", "b": "若手の頃は藤波辰爾の付け人を務めたことがあるという。背中を流したりリングシューズを運んだりして、ついて回ったそうだ。付け人から離れられるとほっとしていた頃の話でもある。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で（字幕を全文確認）", "art": "ext-62J7mf9qfpA", "src": [["番組のYouTube（33:01〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1981s"]]}]);
  if (PROFILES["Kazuchika Okada"]) PROFILES["Kazuchika Okada"].facts.push({"cat": "暮らし", "t": "いい人だが、突飛な話はない", "b": "オカダ・カズチカについて、とてもいい人だが、ぶっ飛んだエピソードはないと、中邑真輔が話している。年齢の割に純粋で、大学生のようなスタンプをLINEで送ってくることがあるという。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で、中邑真輔の話（字幕を全文確認）", "src": [["番組のYouTube（35:23〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=2123s"]], "by": "第三者の話"});
  if (PROFILES["Manabu Nakanishi"]) PROFILES["Manabu Nakanishi"].facts.push({"cat": "暮らし", "t": "犬と間違えられた中西", "b": "中西学について、道場の近くで犬が鳴いているのかと思い追い払いに行ったら、実は中西だったという話を、中邑真輔が紹介している。豪快な人柄を伝える逸話として語られている。", "sp": "中邑真輔", "d": "2023-11-24", "how": "鬼越トマホーク喧嘩チャンネルの番組で、中邑真輔の話（字幕を全文確認）", "src": [["番組のYouTube（31:24〜）", "https://www.youtube.com/watch?v=62J7mf9qfpA&t=1884s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-62J7mf9qfpA", d: "2023-11-24", show: "ext", who: ["Shinsuke Nakamura"], t: "中邑真輔の回　ぶっ飛んだレスラーたちの逸話", lead: "鬼越トマホーク喧嘩チャンネルの番組に出た約36分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Shinsuke Nakamura"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-62J7mf9qfpA").map((x) => [x.t, x.b, x.sp])), open: ["先輩レスラーの名前が自動字幕で崩れていた箇所は、確信が持てず名前を載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=62J7mf9qfpA"]] });
  if (!ROSTER.find((r) => r[1] === "Kyoki")) ROSTER.push(["キョウキ", "Kyoki", "lg", "元・高橋ヒロム", "", "", ""]);
  if (!PROFILES["Kyoki"]) PROFILES["Kyoki"] = { lead: "WWEに来る前、高橋ヒロムとして新日本プロレスで戦っていたころのインタビュー。新日本以外から給料をもらいたくなかったという筋金入りのファン気質と、デスマッチ好きの意外な一面が見える。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kyoki"]], moves: [], facts: [] };
  if (PROFILES["Kyoki"]._weak) { PROFILES["Kyoki"].lead = "WWEに来る前、高橋ヒロムとして新日本プロレスで戦っていたころのインタビュー。新日本以外から給料をもらいたくなかったという筋金入りのファン気質と、デスマッチ好きの意外な一面が見える。"; delete PROFILES["Kyoki"]._weak; }
  PROFILES["Kyoki"].facts.push(...[{"cat": "リングの話", "t": "防衛記録への思い", "b": "当時は新日本のジュニア王座を7回防衛していて、自己最多を更新中だったという。それまでは最多でも4回ほどしか防衛したことがなかったそうだ。「言いすぎると実現しない」と言いつつ、最多防衛記録は心の中で意識していると話している。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（0:01〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=1s"]]}, {"cat": "リングの話", "t": "悔しさが顔に出るタイプ", "b": "悔しいことがあると、隠そうとしても顔に出てしまう性格だという。ただ同期のエル・デスペラードの前でだけは、絶対に悔しさを見せたくないというプライドがあると話す。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=238s"]]}, {"cat": "リングの話", "t": "同期デスペラードへの複雑な思い", "b": "デスペラードとは約14年前に同じ時期に入門した同期で、若手時代はほとんど口をきかなかったという。正直、性格が好きではなく、若手時代は思い出したくないほどつらかったそうだ。ただ目指しているものは同じで、今は「いいやつになったんじゃないか」と思っていると話す。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（4:45〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=285s"]]}, {"cat": "リングに来るまで", "t": "最初の給料は新日本からと決めていた", "b": "新日本プロレスが大好きで、入門するまではアルバイトもせず、最初にもらう給料は新日本からと決めていたという。ファン時代も、いずれ戦う相手と握手するのは違うと考え、サイン会や握手会には一度も行かなかったそうだ。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（7:03〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=423s"]]}, {"cat": "リングの話", "t": "他団体を見て知ったプロレス", "b": "新日本しか知らなかった反省から、2022年ごろから他団体の選手を見て研究し、ジュニアの選手が団体の垣根を越えて集まる大会を実現させたという。翌年はいろいろな団体に自ら出場したと話す。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（8:36〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=516s"]]}, {"cat": "リングの話", "t": "試合前はいつも怖い", "b": "試合前はいつもドキドキして「リングに上がるのが怖い」と思うタイプだという。それでも入場曲が鳴って観客の前に出ると不安が消え、楽しくなってにやけてしまうそうだ。ある試合で初めてリング上で心拍が上がるほど緊張したと振り返っている。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（9:25〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=565s"]]}, {"cat": "好きなもの", "t": "人生初の写真は葛西純", "b": "ファン時代から今もデスマッチが大好きで、人生で初めて写真を撮った相手は、デスマッチの第一人者・葛西純だったという。自分がやるのは恐ろしすぎて想像できないが、もしやるなら人生で一度、ものすごいデスマッチをやりたいと話している。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（12:39〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=759s"]]}, {"cat": "リングの話", "t": "夢はスポーツニュースで5秒", "b": "目標の一つは、プロレスの結果がスポーツニュースで普通に取り上げられることだという。プロレスを知らない若い人が「へえ」と思うきっかけになるとして、「5秒でいいので取り上げてほしい」とテレビ局に呼びかけていた。", "sp": "キョウキ", "d": "2023-12-29", "how": "新日本プロレスの公式インタビュー（高橋ヒロム時代）で（字幕を全文確認）", "art": "ext-wTURYbXKR3M", "src": [["番組のYouTube（19:07〜）", "https://www.youtube.com/watch?v=wTURYbXKR3M&t=1147s"]]}]);
  ARTICLES.push({ id: "ext-wTURYbXKR3M", d: "2023-12-29", show: "ext", who: ["Kyoki"], t: "キョウキの回　高橋ヒロム時代のインタビュー", lead: "新日本プロレスの公式インタビュー（高橋ヒロム時代）に出た約23分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kyoki"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-wTURYbXKR3M").map((x) => [x.t, x.b, x.sp])), open: ["新日本プロレス時代（高橋ヒロム）の発言。WWEに来てからの話ではない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=wTURYbXKR3M"]] });
  if (!ROSTER.find((r) => r[1] === "Matt Riddle")) ROSTER.push(["マット・リドル", "Matt Riddle", "gn", "元WWEタッグ王者", "", "", ""]);
  if (!PROFILES["Matt Riddle"]) PROFILES["Matt Riddle"] = { lead: "元UFC選手からWWEの主力へ上り詰め、ランディ・オートンとのタッグで人気を集めた。解雇は予想していたと語り、恨みはないという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Matt%20Riddle"]], moves: [], facts: [] };
  if (PROFILES["Matt Riddle"]._weak) { PROFILES["Matt Riddle"].lead = "元UFC選手からWWEの主力へ上り詰め、ランディ・オートンとのタッグで人気を集めた。解雇は予想していたと語り、恨みはないという。"; delete PROFILES["Matt Riddle"]._weak; }
  PROFILES["Matt Riddle"].facts.push(...[{"cat": "WWEでの日々", "t": "毎週走り続けたWWE時代の忙しさ", "b": "WWE在籍中は週に4日ほど、スマックダウンやRAW、ライブイベント、さらに関連番組の出演までこなしていたと話す。休みなく移動を続けるのは非常に過酷な仕事で、今も残る仲間への敬意があるという。現在は試合数こそ減ったが、自分で出る場を選べるのがうれしいそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（3:06〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=186s"]]}, {"cat": "WWEでの日々", "t": "WWEとの縁は小さな団体の育成ルートから", "b": "最初の入団テストでは見送りとなったが、WWEと提携関係にあった小さな団体を勧められたという。そこで最初は観客にブーイングを浴び、「ベビー・レスナー」と呼ばれたが、試合を重ねるうちに「ブロ」の大合唱が起きるようになったと話す。人気が出て多くの団体から声がかかり、WWEの目にも留まったそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（21:04〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=1264s"]]}, {"cat": "WWEでの日々", "t": "「ブロ」は誰でも言える万能の決め台詞", "b": "人の集中力が短くなった時代に、世界中の誰でも叫べる短い言葉が武器になると考えたという。普段から口癖で、名前を覚えるのが苦手な自分にも都合がよかったと話す。ダニエル・ブライアンの「イエス！」と同じく、チャントにしやすい点も狙いだったそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（23:28〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=1408s"]]}, {"cat": "WWEでの日々", "t": "入場曲は西海岸風のブラスで頼んだ", "b": "UFC時代はウォーレン・Gの曲を使っていたという。WWEでは怒りに満ちた音楽が多い中、観客を盛り上げつつ落ち着いた雰囲気にしたいと考えた。ゲーム『GTA5』のテーマのような金管楽器と西海岸の空気を希望し、できあがった曲をそのまま気に入ったと話す。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（25:54〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=1554s"]]}, {"cat": "WWEでの日々", "t": "WWEが「420」のシャツを出すまで", "b": "家族連れの多い会社が420にちなんだシャツを出すまでには、何か月も説得が必要だったという。前日になって1日限定で出すと連絡があり、本人もランディ・オートンも全力で宣伝した。結果的に好調で販売が続き、会社も喜んだと話す。オートンが負傷離脱したあとも関連商品は売れ続けたそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（29:07〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=1747s"]]}, {"cat": "WWEでの日々", "t": "オートンとの出会いは「嫌われた」ところから", "b": "初対面はサバイバー・シリーズでの試合で、試合後に強烈なRKOを受けたという。控室で挨拶しなかったことをオートンが無礼と受け取り、後日親しくなってから「どうやってクビにさせようか考えていた」と明かされたと話す。本人は人の輪に割り込まない性格が誤解されただけだと説明している。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（32:21〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=1941s"]]}, {"cat": "WWEでの日々", "t": "セス・ロリンズとの誤解は謝って解いた", "b": "家族の発言をきっかけに、セス・ロリンズとしばらくぎくしゃくしたという。本人は同じ考えではなかったと説明し、ロリンズに直接謝ったと話す。のちにロリンズから、聞いていた評判と違って感じのいい人だと言われたそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（33:58〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2038s"]]}, {"cat": "WWEでの日々", "t": "ゴールドバーグとの確執は本人の言い分で", "b": "ゴールドバーグの試合スタイルは好みではないと公言し、相手がそれを失礼と受け取って関係がこじれたと話す。一方で集客力や興行の面では今でも多くの選手より上だと認め、本人にもそう伝えたという。バックステージでぶつかった場面もあったが、互いに話はしたそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（34:43〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2083s"]]}, {"cat": "WWEでの日々", "t": "ロリンズ戦を本物らしく見せる工夫", "b": "ロリンズとの抗争では、現実の事情も絡めて口で攻め合うことで、本当に不仲に見える空気をつくろうとしたという。放送で禁句を口にする場面は会社側から与えられたものだと話す。ロリンズの実力も信頼しており、あの対決を長年やりたかったと語っている。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（38:41〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2321s"]]}, {"cat": "WWEでの日々", "t": "オートンとのタッグ誕生の裏側", "b": "タイトルを落とした直後の週、試合を組み直す形でオートンと戦うことになったという。まず単発で戦い、そのあとタッグを組ませて裏切らせる筋書きが用意されていた。ところが試合後にオートンが非常に気に入ってくれ、タッグ継続の流れになったと話す。「アーケード・ブロ」は自分が出した案だそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（42:00〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2520s"]]}, {"cat": "WWEでの日々", "t": "ペテ・ダンとの組み合わせも偶然から", "b": "NXT時代、ペテ・ダンとは一度限りのつもりで組んだタッグが好評を呼び、そのまま大会を勝ち上がったという。オートンとの関係も同じ流れだが、メインロスターで規模は百倍だったと話す。本人は気さくな役、相手は冷酷な蛇という対照が良かったそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（43:36〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2616s"]]}, {"cat": "WWEでの日々", "t": "オートンから学んだのは「間」", "b": "一番の学びは間の取り方で、急がず待つことで観客が反応する余地が生まれると話す。入場や決めポーズだけで場面にしてしまうのがオートンのすごさだと語る。独立系の会場に戻ってからも、この考え方を意識しているそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（44:26〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2666s"]]}, {"cat": "WWEでの日々", "t": "ロイヤルランブルの優勝話は「可能性」止まり", "b": "優勝を言い渡されたことはなく、制作陣との間で候補として話が出たにとどまると話す。当日は予定していた見せ場が変わり、思い描いた展開にはならなかったという。マネー・イン・ザ・バンクでも似た経験があり、WWEでは直前の変更は日常だと語る。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（45:15〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2715s"]]}, {"cat": "WWEでの日々", "t": "大会当日に結果が変わるのは日常", "b": "レッスルマニアの当日に、防衛予定だったUS王座の結末が変更されたことがあるという。王座を初めて獲った時も、本来の予定が体調不良で変わった末のことだったと話す。若手の例も挙げ、本人でさえ直前まで結果を知らされないのが普通だと説明している。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（46:56〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2816s"]]}, {"cat": "退団の理由", "t": "WWEへの復帰の扉は閉じていない", "b": "CMパンクなど復帰した前例があるので、自分にも可能性はあると話す。会社への悪意はなく、与えられた機会に感謝しているという。レッスルマニアやロイヤルランブルを経験し、子どもたちに見てもらえたことも財産だそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（49:23〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2963s"]]}, {"cat": "退団の理由", "t": "解雇は予想していた", "b": "レッスルマニア後の経費削減で切られるのではと、数か月前から考えていたという。親会社の変化の報道もあり、不安は強まったそうだ。その前から自分の扱いが少し変わったと感じており、事情は理解できると話す。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（50:08〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=3008s"]]}, {"cat": "退団の理由", "t": "責めるべきは自分、恨みはない", "b": "問題を起こす選手と見られがちで、自分の見られ方も会社には負担だったと話す。会社を批判する気はなく、オートンとの物語を終えられなかったのが心残りだそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（51:42〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=3102s"]]}, {"cat": "退団の理由", "t": "解雇されたときはむしろ安堵した", "b": "解雇を知ったとき、動揺よりも肩の荷が下りた気持ちだったと話す。TVの時間に左右される日々や、期待を裏切られる経験が重なり、ストレスが大きかったという。インドへ長距離を移動して剣を持つだけの仕事もあり、割に合わないと感じる場面があったそうだ。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-U5Z2jRLral4", "src": [["番組のYouTube（59:45〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=3585s"]]}]);
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "ランディ・オートンは「間」の達人", "b": "入場も決めポーズも、それ自体が見せ場になるのがランディ・オートンだと、マット・リドルが話している。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で、マット・リドルの話（字幕を全文確認）", "src": [["番組のYouTube（44:26〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2666s"]], "by": "第三者の話"});
  if (PROFILES["Seth Rollins"]) PROFILES["Seth Rollins"].facts.push({"cat": "暮らし", "t": "セス・ロリンズは抗争を長持ちさせたがった", "b": "セス・ロリンズも自分と同じく、一過性で終わらせず長く続く対決にしたいと考えていた、とマット・リドルが話している。", "sp": "マット・リドル", "d": "2024-01-30", "how": "クリス・ヴァン・ヴリートの番組で、マット・リドルの話（字幕を全文確認）", "src": [["番組のYouTube（39:29〜）", "https://www.youtube.com/watch?v=U5Z2jRLral4&t=2369s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-U5Z2jRLral4", d: "2024-01-30", show: "ext", who: ["Matt Riddle"], t: "マット・リドルの回　WWEでの日々と解雇への思い", lead: "クリス・ヴァン・ヴリートの番組に出た約61分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Matt Riddle"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-U5Z2jRLral4").map((x) => [x.t, x.b, x.sp])), open: ["ゴールドバーグとの確執、解雇の経緯はマット・リドル本人の言い分のみを要約している。", "家族、UFC時代、他団体での活動、ゲームの趣味などWWE以外の話題は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=U5Z2jRLral4"]] });
  if (!ROSTER.find((r) => r[1] === "Joaquin Wilde")) ROSTER.push(["ホアキン・ワイルド", "Joaquin Wilde", "lg", "WWEの実力派レスラー", "", "", ""]);
  if (!PROFILES["Joaquin Wilde"]) PROFILES["Joaquin Wilde"] = { lead: "シングルマザーの家で育ち、MTVを見て音楽に夢中になったという。DJや曲づくりを自力で学び、命の危機も乗り越えて、いまも音楽とリングの両方を追う。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Joaquin%20Wilde"]], moves: [], facts: [] };
  if (PROFILES["Joaquin Wilde"]._weak) { PROFILES["Joaquin Wilde"].lead = "シングルマザーの家で育ち、MTVを見て音楽に夢中になったという。DJや曲づくりを自力で学び、命の危機も乗り越えて、いまも音楽とリングの両方を追う。"; delete PROFILES["Joaquin Wilde"]._weak; }
  PROFILES["Joaquin Wilde"].facts.push(...[{"cat": "家族", "t": "シングルマザーの家庭で育つ", "b": "移民の母親に女手ひとつで育てられたと話す。母は仕事を掛け持ちして家計を支え、幼い頃から家で一人きりになる時間が長かったという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（1:41〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=101s"]]}, {"cat": "好きなもの", "t": "幼少期はMTV漬けだった", "b": "1990年代前半、5〜6歳のころ周りの子がアニメ専門チャンネルを見ている中、自分はMTVを見ていたそうだ。プロレスは土曜の朝だけで、それ以外の日は音楽番組だったという。音楽は最初期の記憶と結びついていると話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（2:31〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=151s"]]}, {"cat": "好きなもの", "t": "ビーバス・アンド・バットヘッドで母に叱られた", "b": "6〜7歳のころ人気だったアニメ番組が親たちの間で話題になり、母とその友人たちに「見せるべきでない」と説得されたことがあるという。それでもこっそり見ていたと笑って話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（3:21〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=201s"]]}, {"cat": "暮らし", "t": "楽器のない貧しい家で育った", "b": "家には音楽がなく、母は外国出身で家計も苦しかったため、ギターを習う機会など頭に浮かびもしなかったと話す。アメリカンフットボールやバスケットボールなど、普通の外遊びが当たり前だったそうだ。聴く側、ライブに通う側の人間として育ったという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（5:50〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=350s"]]}, {"cat": "好きなもの", "t": "本当はラッパーになるのが夢", "b": "音楽の世界に関わるのが一番の夢で、いまもラップは憧れだと話す。ただ、本気で追いかける目標ではなく、20年かけて何とか形になる程度だろうと考えているそうだ。一度きりの人生を適当に過ごしたくないという思いがある。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（6:38〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=398s"]]}, {"cat": "リングに来るまで", "t": "プロレスも音楽も「やらずに人生は終われない」", "b": "プロレスラーは長年の夢で、音楽も同じくらい好きだと話す。19歳のときにギターのレッスンを受けたが、小指が弦に届かず挫折したという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（8:15〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=495s"]]}, {"cat": "リングに来るまで", "t": "2012年にDJの道へ", "b": "大学を出てワシントンDCに引っ越した2012年ごろ、大学の友人がニューヨークの電子音楽シーンで名を上げるのをSNSで見て、DJなら早く音楽に関われると考えたという。調べるとDJ教室が家から5分の距離にあり、運命のように感じたそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（10:39〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=639s"]]}, {"cat": "リングに来るまで", "t": "DJの師匠たちから音楽制作へ", "b": "その教室で3人のDJに基礎を教わったという。やがてDJよりも曲づくりやビートメイクのほうが本当にやりたいことだと気づいたと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（12:14〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=734s"]]}, {"cat": "暮らし", "t": "クレジットカードの返済直後にまた音楽学校へ", "b": "大学卒業後の20代前半、カードを使いすぎて限度額まで借り、返済に1〜2年かかったという。借金をゼロにして喜んだ1週間後、ニューヨークの音楽制作学校のオンライン講座に払うため、またカードを使い切ったそうだ。それほど本気だったと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（14:40〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=880s"]]}, {"cat": "暮らし", "t": "お金がない中で機材をそろえた", "b": "2014〜2015年は試合のない時間をほとんどノートパソコンの前で過ごしたという。金がなく、機材を手に入れるために相当な手段をとったと笑い、スピーカーを買ってもらったこともあったと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（16:16〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=976s"]]}, {"cat": "家族", "t": "母はフィリピンから渡米した", "b": "母の夢はフィリピンを出ることで、そのために手段を選ばなかったと話す。母はカタログを通じて結婚相手を探して渡米したそうで、その「何としても道を切り開く」姿勢が自分の原動力になっているかもしれないという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（18:46〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1126s"]]}, {"cat": "体のこと", "t": "メキシコの試合で内出血し、死にかけた", "b": "メキシコシティでの試合中にけがをして体内で出血が続き、命を落としかけたと話す。人生で最も怖い夜で、選手生活も終わりかけたという。周囲には引退を勧められたが、生き延びたのは何か果たすべきことがあるからだと考え、現役を続けたそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（20:24〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1224s"]]}, {"cat": "家族", "t": "妻と娘に出会い、生きる理由が増えた", "b": "事故のあと、いまの妻と出会い、子どもが生まれたと話す。生き残った意味は団体入りだけでなく、家族を持つことだったのかもしれないと考えているという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（22:04〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1324s"]]}, {"cat": "暮らし", "t": "新曲を出しても聴かれず、プロレスのテーマのリミックスで反応を得た", "b": "オリジナルの電子音楽を公開しても誰も聴かなかったが、ファンの多くがプロレス好きだと気づき、入場曲のリミックスを出したところ急に聴かれるようになったという。2020年にノートパソコンが壊れ、約3年はほぼ制作できなかったが、数か月前に新しいパソコンを買ってまた作り始めたそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（23:44〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1424s"]]}, {"cat": "好きなもの", "t": "音楽の名義を新しく「ワイルド・ウェスト」にした", "b": "以前の名義は昔の団体での役柄と結びつきが強く、混乱もあるため、新しいパソコンを機に名前を変えたと話す。ワイルドで無法だった時代への憧れが込められており、アティテュード時代育ちの自分にも響くという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（24:31〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1471s"]]}, {"cat": "リングの話", "t": "「ショックと驚き」を与えるスタイルが評価された", "b": "NXTで見せたスタント的な無謀な試合ぶりが、この一年で注目を集めたと話す。友人が「見ていて衝撃と驚きがある」と評してくれたのが励みになったそうだ。公式の型にはまった試合より、何が起こるか分からない空気を目指しているという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（27:00〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1620s"]]}, {"cat": "リングの話", "t": "タイミングの感覚はリングも音楽も同じ", "b": "ビートに合わせる電子音楽とリングの動きでは、タイミングが重要だという話題になった。「規則を学んだ上で芸術家のように破る」という言葉が好きで、基礎をしっかり固めたことが大事だったと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（30:13〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1813s"]]}, {"cat": "好きなもの", "t": "音楽はプロレスと切り離せる唯一の趣味", "b": "自分の生活はほとんどプロレスにつながっている、と話す。妻との出会いも、体を鍛える習慣もプロレスのおかげだという。ビートづくりだけはその外にあり、バランスをとる意味でも大切な存在だそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（31:00〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1860s"]]}, {"cat": "リングに来るまで", "t": "「元レスラーの音楽」と見られる悔しさ", "b": "プロレスラーが音楽をやると本気で見てもらえないと感じることがあるという。実際は何年も修業を重ねてきたと話す。DJを始めた2012年は、キックやスネアが何かも知らなかったそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（32:36〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=1956s"]]}, {"cat": "リングに来るまで", "t": "ラジオ番組でDJをしたが、共演俳優を取り違えた", "b": "2014年、ニューヨークの人気ラジオ番組で生DJをしたと話す。スタジオにいた俳優を、あるロックバンドのボーカルと勘違いしていて、当人に曲を聴かせてくれと促していたという笑い話だ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（34:11〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2051s"]]}, {"cat": "リングに来るまで", "t": "シカゴに移りDJとして活動した", "b": "2014年、ハウスミュージックが盛んなシカゴへDJ目的で引っ越したという。2019年には大きなレスリングイベント前の屋外パーティで6時間通しでDJをし、後にある団体の初の大会でも公式DJを務めたと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（34:57〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2097s"]]}, {"cat": "リングに来るまで", "t": "客層に合わせて選曲を変える大切さ", "b": "最初は人が聞き流すだけだったが、2000年代半ばのポップパンクをかけたら一気に盛り上がったという。ワシントンDCのクラブでも、前夜に仲間のDJから客に合わせるよう助言され、救われたと話す。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（36:35〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2195s"]]}, {"cat": "リングの話", "t": "観客を読む力はレスラーの経験から", "b": "会場の反応を見て作戦を変える力は、プロレスで身につけたものだと話す。自分の案にこだわりすぎないことをリングでも学んだという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（36:35〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2195s"]]}, {"cat": "好きなもの", "t": "フィリピン系のパーティとカラオケの思い出", "b": "フィリピン系の集まりでは親たちがタガログ語で語らい、子どもたちが遊び、必ずカラオケがあったと話す。カラオケは非常に真剣なもので、歌が上手くなるよう言われて育ったが、音楽的な影響は受けていないという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（39:44〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2384s"]]}, {"cat": "好きなもの", "t": "ラップはしないが、ビートで関わりたい", "b": "フリースタイルは技術への敬意が強すぎて挑戦できず、自分はビートづくりが向いていると話す。ラッパーとの共作を通じて、ラップの世界に関わっていきたいそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（41:17〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2477s"]]}, {"cat": "好きなもの", "t": "一番弾きたい楽器はピアノ", "b": "ピアノはあらゆる楽器の役割を担えるので、もし弾けるなら一番に選ぶと話す。娘にも、いやがらなければピアノを触らせたいという。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（43:34〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2614s"]]}, {"cat": "好きなもの", "t": "10代はゴス少年で、インダストリアル音楽が好き", "b": "10代から20代前半にかけてゴスに傾倒し、いまもその文化と音楽に関心があるという。昔のインダストリアル曲をサンプリングして新しい電子音楽にしてみたいと話す。19歳でギターを習ったのも、ゴスのバンドを組みたかったからだそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（44:22〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2662s"]]}, {"cat": "リングの話", "t": "昔のDJ役は今も反応がよく、進化版に期待", "b": "以前の団体でDJの役柄を演じていた頃を、周囲がいまも褒めてくれるという。最近も関係者に「あれは良かった」と言われ、いまの団体でその進化版ができないかと考え始めているそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（46:00〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2760s"]]}, {"cat": "リングの話", "t": "入場曲のリミックス集を公式で出したい", "b": "クラシックな入場曲をリミックスしたEPを出し、団体側に宣伝してもらうのが夢だと話す。ラッパーを招く案もあるという。トリプルHの入場曲のリミックスも自作したが、本人には見せていないそうだ。", "sp": "ホアキン・ワイルド", "d": "2024-02-05", "how": "RRBGポッドキャストの番組(RRBG Inc.)で（字幕を全文確認）", "art": "ext-jGpAn23B8jk", "src": [["番組のYouTube（47:31〜）", "https://www.youtube.com/watch?v=jGpAn23B8jk&t=2851s"]]}]);
  ARTICLES.push({ id: "ext-jGpAn23B8jk", d: "2024-02-05", show: "ext", who: ["Joaquin Wilde"], t: "ホアキン・ワイルドの回　貧しい少年時代、DJと音楽制作、死にかけた夜", lead: "RRBGポッドキャストの番組(RRBG Inc.)に出た約52分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Joaquin Wilde"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-jGpAn23B8jk").map((x) => [x.t, x.b, x.sp])), open: ["聞き手自身の話(事故の体験など)は載せていない。", "字幕が自動で崩れていた固有名詞(友人の名前など)は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=jGpAn23B8jk"]] });
