  PROFILES["Akira Tozawa"].facts.push(...[{"cat": "リングの話", "t": "ユニットの仲間との活動を楽しんでいる", "b": "所属するユニットでの活動を楽しんでいると、戸澤陽は話す。リーダーのゲーブルには全幅の信頼を置いていて、元五輪選手でとても素晴らしい人だという。仲間の相性もよく、動画などの発信も好評のようだ。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=0s"]]}, {"cat": "リングの話", "t": "ユニットの空気感を紹介", "b": "ユニットのメンバーについて、マキシーンはとても美しいと語り、自分は「ハッピーな担当」だと話す。互いの個性がうまくかみ合っているという。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=50s"]]}, {"cat": "リングの話", "t": "入団7年でまだ大乱戦に出ていない", "b": "入団して7年になるが、年明けの大乱戦形式の試合にはまだ一度も出たことがないと、戸澤陽は話す。ただ、いつでも準備はできているとも語り、出るかどうかは当日までのお楽しみだと笑った。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=50s"]]}, {"cat": "リングの話", "t": "夢はその試合と年間最大の祭典", "b": "ひとつの夢は、大乱戦の試合に出て、そのあと年間最大の祭典のリングに立つことだと戸澤陽は話す。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=96s"]]}, {"cat": "好きなもの", "t": "ゲームが大好き", "b": "ビデオゲームが大好きだと、戸澤陽は話す。発売前のWWEのゲームも、自分でプレーするのを楽しみにしているそうだ。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=96s"]]}, {"cat": "リングの話", "t": "王座にはこだわらず、どのベルも狙う", "b": "狙っているベルを聞かれ、どのタイトルでもチャンスがあれば欲しいと戸澤陽は答える。ユニットのリーダーはシングルのベルに集中するのではないか、とも話している。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（2:26〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=146s"]]}, {"cat": "リングの話", "t": "人気タッグと戦ってみたい", "b": "まだ戦っていない相手として、人気タッグチームのDIYとの対戦に興味があると戸澤陽は話す。聞き手も盛り上がっていた。", "sp": "戸澤陽", "d": "2024-02-22", "how": "BCP+の番組で（字幕を全文確認）", "art": "ext-x5pRxRE-cxw", "src": [["番組のYouTube（3:15〜）", "https://www.youtube.com/watch?v=x5pRxRE-cxw&t=195s"]]}]);
  ARTICLES.push({ id: "ext-x5pRxRE-cxw", d: "2024-02-22", show: "ext", who: ["Akira Tozawa"], t: "戸澤陽の回　ユニットの仲間と、まだ見ぬ大乱戦への夢", lead: "BCP+の番組に出た約4分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Akira Tozawa"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-x5pRxRE-cxw").map((x) => [x.t, x.b, x.sp])), open: ["番組の大半はスポンサー紹介で、本人の発言は冒頭の約4分間のみ。", "タッグを組みたい相手として名前を挙げた箇所は、字幕が崩れていて聞き取れず載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=x5pRxRE-cxw"]] });
