  PROFILES["Paul Heyman"].facts.push(...[{"cat": "リングの話", "t": "ECWは今も生きている", "b": "ECWは長続きするための団体ではなく、業界をかき回すために燃え尽きる運命だったと語った。2001年に倒産しても、その精神は今の試合や業界全体が取り入れた考え方、ファンの熱の中に生きていると強調した。", "sp": "ポール・ヘイマン", "d": "2024-04-05", "how": "WWE殿堂入り式典のハイライト（WWE公式）で（字幕を全文確認）", "art": "ext-8w6w2hBH9Yw", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=8w6w2hBH9Yw&t=50s"]]}, {"cat": "リングの話", "t": "「また炎上だな」とCMパンク", "b": "際どい言葉で締めた直後、CMパンクが隣の息子に「親父さんまた炎上だな」とささやいたと明かして笑わせた。そのうえで、自分は消されたら前より大きくなって戻ってくると言い切った。", "sp": "ポール・ヘイマン", "d": "2024-04-05", "how": "WWE殿堂入り式典のハイライト（WWE公式）で（字幕を全文確認）", "art": "ext-8w6w2hBH9Yw", "src": [["番組のYouTube（2:28〜）", "https://www.youtube.com/watch?v=8w6w2hBH9Yw&t=148s"]]}]);
  ARTICLES.push({ id: "ext-8w6w2hBH9Yw", d: "2024-04-05", show: "ext", who: ["Paul Heyman"], t: "ポール・ヘイマンの回　2024年殿堂入りスピーチの抜粋", lead: "WWE殿堂入り式典のハイライト（WWE公式）に出た約3分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Paul Heyman"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-8w6w2hBH9Yw").map((x) => [x.t, x.b, x.sp])), open: ["公式チャンネルの約3分のハイライト版だけを読んだ。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=8w6w2hBH9Yw"]] });
