  if (PROFILES["Piper Niven"].lead === "「ドゥードロップ」時代を経て名前を取り戻したパイパー・ニーヴン。手の骨折で休んだ期間を、自分を見つめ直す時間にしたという。") PROFILES["Piper Niven"]._weak = 1;
  PROFILES["Piper Niven"].facts.push(...[{"cat": "好きなもの", "t": "緑が好きでグッズ売り場で買い物", "b": "ファンイベントの会場で、ほかの選手のグッズがかっこよくて自分用に買いに来たと、パイパーは話す。一番好きな色は緑で、緑のジャケットを狙ったが売り切れていたという。友人や家族へのお土産も選んだそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（0:47〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=47s"]]}, {"cat": "体のこと", "t": "練習中に手を骨折、初めての大けが", "b": "2月7日に練習中に手の骨を折ったと、パイパーは話す。それまで病気はあっても骨折のような大けがは一度もなかったという。治った今も骨のこぶが残っているそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=98s"]]}, {"cat": "体のこと", "t": "骨折は必要な回り道だったと考える", "b": "けがでリングを離れている間も、自分の内面やリングでの動き、仕事について学び続けていたと、パイパーは話す。もっと良い表現者になるための必要な挫折だったと受け止めているという。自分に自信が持てれば、それがリングにも自然と出ると考えているそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=145s"]]}, {"cat": "リングの話", "t": "「ドゥードロップ」の頃は手がかりがなかった", "b": "10年以上育ててきた「バイパー」「パイパー」の名前から急に離され、アメリカで泳ぐか沈むかの状況だったと、パイパーは振り返る。名前を告げられただけで、役柄の説明はほとんどなかったという。それでも精いっぱい役を理解しようとし、今ではその経験にも感謝しているそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（3:57〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=237s"]]}, {"cat": "リングの話", "t": "パイパーに戻れて「自分を取り戻した」", "b": "パイパーの名前に戻れたことは、自分のアイデンティティを取り戻すことだったと、パイパーは話す。子どもの頃は怒ることも、立ち向かうことも許されなかったという。パイパーはそのとき「なりたかった自分」で、体の大きな子やいじめられている子が勇気をもらえる存在になれたらと願っているそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（4:43〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=283s"]]}, {"cat": "リングの話", "t": "本心から出た表現でないとファンに伝わらない", "b": "ファンは本物でないものをすぐ見抜くので、心からの表現でないと響かないと、パイパーは話す。今は自分のままでリングに立ち、すべてを見せられていることがとても大切だという。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（5:33〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=333s"]]}, {"cat": "リングの話", "t": "故郷スコットランドでの大会に「行かせて」と直訴", "b": "スコットランドの大会が発表された瞬間、運営席にいたブルース・プリチャードとウィリアム・リーガルのモニターの前に顔を出し「行ってもいい？」と頼んだと、パイパーは笑う。英国のプロレスブームはスコットランドが大きな支えで、地元のファンはこの大会を待つ資格があると話す。以前より自信がつき、意見を言えるようになったことも大きいそうだ。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（7:08〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=428s"]]}, {"cat": "好きなもの", "t": "ゲームではボタン連打派", "b": "WWEのゲームは大好きだが、自分はボタンを連打するタイプなので、思うように技が出ずにストレスがたまることもあると、パイパーは笑う。物を投げられるようになった点がお気に入りだという。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（9:33〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=573s"]]}, {"cat": "リングの話", "t": "夢はアルバ・ファイアと大舞台に立つこと", "b": "引退するなら、アルバ・ファイアとの年間最大の祭典での場面を実現してからが理想だと、パイパーは話す。組んでも戦っても、互いの一番良いところを引き出し合う間柄だという。", "sp": "パイパー・ニーヴン", "d": "2024-04-17", "how": "ゴリラ・ポジションの番組で（字幕を全文確認）", "art": "ext-csNIB06qS9E", "src": [["番組のYouTube（10:21〜）", "https://www.youtube.com/watch?v=csNIB06qS9E&t=621s"]]}]);
  ARTICLES.push({ id: "ext-csNIB06qS9E", d: "2024-04-17", show: "ext", who: ["Piper Niven"], t: "パイパー・ニーヴンの回　名前を取り戻した日、初めての骨折、故郷スコットランドへの思い", lead: "ゴリラ・ポジションの番組に出た約12分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Piper Niven"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-csNIB06qS9E").map((x) => [x.t, x.b, x.sp])), open: ["聞き手の自身の体験の話は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=csNIB06qS9E"]] });
