  if (!PROFILES["La Catalina"]) PROFILES["La Catalina"] = { lead: "チリ生まれのピンク好きな元チアリーダーで、プロレスラーに。厳しい父に鍛えられ、米国での苦労を経て、メキシコで人気を築いた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=La%20Catalina"]], moves: [], facts: [] };
  if (PROFILES["La Catalina"]._weak) { PROFILES["La Catalina"].lead = "チリ生まれのピンク好きな元チアリーダーで、プロレスラーに。厳しい父に鍛えられ、米国での苦労を経て、メキシコで人気を築いた。"; delete PROFILES["La Catalina"]._weak; }
  PROFILES["La Catalina"].facts.push(...[{"cat": "家族", "t": "学校でも親戚からも反対されたが両親は支えた", "b": "チリで選手を目指し始めた頃、学校では同級生にいじめられ、親戚からも勉強に専念するよう言われたという。両親はそれに耐えながら支え続けてくれたそうだ。今では家族の誇りだと言われるが、本当に支えが欲しかった時期の言葉は忘れていないと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（0:49〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=49s"]]}, {"cat": "リングに来るまで", "t": "医学を志して大学で運動療法学を学んでいた", "b": "もともとは医者になりたく、学校の成績は優秀だったという。医学部には点数が少し届かず、まず運動療法学の学部に進み、成績が良ければ医学へ移る計画を父と立てた。ところが米国行きの機会が訪れ、大学は1年で離れたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=94s"]]}, {"cat": "家族", "t": "母は体操、父はサッカーをしていた運動一家", "b": "母は体操競技、父は小さなリーグでサッカーをしていた家庭で育ち、本人も昔からスポーツ少女だったという。学校ではチアリーダーとして活動し、全国規模の大会にも出ていたそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（2:22〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=142s"]]}, {"cat": "好きなもの", "t": "子どもの頃はピンク色とお姫様が大好きだった", "b": "バービー人形やお姫様の物語が好きで、髪型や化粧、ピンクの服が大好きな女の子だったという。リングでの「ディーバ」の呼び名やピンクと輝きのこだわりは、この少女時代から来ていると話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（3:09〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=189s"]]}, {"cat": "リングに来るまで", "t": "ゲームで見たトリッシュ・ストラタスに憧れた", "b": "父のゲーム機で遊んでいたプロレスゲームで、ピンクの衣装のトリッシュ・ストラタスを見たのが出会いだったという。相手に平手打ちをする姿に衝撃を受け、自分も華やかな入場で注目を集め、優雅で美しい女子レスラーになりたいと思ったそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（4:00〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=240s"]]}, {"cat": "リングに来るまで", "t": "チリのプロレスは男の世界で、周囲の偏見も強かった", "b": "当時の周囲には、女子レスラーは男のレスラーの恋人というような偏見があり、家族もそう思っていたという。父と見に行った最初の団体は荒っぽい試合で驚き、別の団体の道場では練習の厳しさに他の生徒がほとんど脱落したそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=336s"]]}, {"cat": "リングに来るまで", "t": "道場でただ一人の女性、ただ一人の卒業生になった", "b": "従兄が数か月で辞めるほうに賭けたこともあり、悔しさから必ず一番になると決めたという。男子約10人の中で唯一の女性だったが、最後まで残ってデビューし、「リングのディーバ」として売り出されたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（6:28〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=388s"]]}, {"cat": "リングに来るまで", "t": "15歳前後でデビューし、気品あるキャラを貫いた", "b": "最初はマネージャー役を経て、15、16歳ごろにリングに上がったという。わがままで上品なお嬢様というキャラで、話し方も学んで品を保つようにしたそうだ。どの国に行ってもリングのディーバでいると決めていると語る。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（7:18〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=438s"]]}, {"cat": "リングに来るまで", "t": "年上の先輩の嫌がらせで一時リングから離れた", "b": "女性の少ない道場で、年上の女性が自分を悪く言うようになり、14、15歳の本人は深く傷ついたという。一時は競技から離れたが、親しい先輩が道場側に話してくれて問題が整理されたそうだ。それでも続けて今に至ると話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（8:53〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=533s"]]}, {"cat": "リングに来るまで", "t": "チリで報道されるほど知られていたことに後で気づいた", "b": "チリでは新聞やニュース、ドキュメンタリーで取り上げられていたが、渡米して忙しく本人は気づいていなかったという。帰国して初めてその反響の大きさを知ったそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（12:05〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=725s"]]}, {"cat": "好きなもの", "t": "子どものファンを大切にしている", "b": "自身もファンだった頃は好きなレスラーの格好をして応援していたという。今は子どものファンに写真やぬいぐるみ、Tシャツを贈ることもあり、家が裕福でなかった自分の経験が重なると話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（14:25〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=865s"]]}, {"cat": "家族", "t": "厳しいマネージャー役の父に育てられた", "b": "父は競技を始めた時から本人のマネージャーでもあり、契約書を交わして、成績とレスラーの両立を条件に応援したという。子どもの頃は憎く思ったが、貯金のしかたや働くこと、勉強の大切さを教えてくれたと感謝している。体型や体調にもはっきり指摘する人で、今の自己管理の土台になったそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（15:11〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=911s"]]}, {"cat": "暮らし", "t": "初めて自分のお金で買った靴は安物だった", "b": "自分で稼いだお金で初めて買った靴は、品質の悪いゴム底で、日差しで底が焦げるようなものだったという。それでも毎日の練習に履き、自分で手にしたことがうれしかったと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（16:47〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1007s"]]}, {"cat": "体のこと", "t": "父がコロナで重症になり、幼い弟を守ろうとした", "b": "米国で暮らしていた時期に父がコロナで長く入院し、一時は危ないと言われたという。母は落ち込み、幼い弟には知らせないよう、ゲームで遊んだり誕生日に贈り物をしたりして支えたそうだ。本人は仕事を続けながら家の事情も整理していたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（20:01〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1201s"]]}, {"cat": "体のこと", "t": "多嚢胞性卵巣症候群で体型が大きく変わった", "b": "米国に渡ってから多嚢胞性卵巣症候群と診断され、体重の増加や体毛の変化があったという。食事を極端に絞っても体重が落ちず、前糖尿病の疑いも出たそうだ。母にも同じ体質があり、遺伝とみられると話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（21:37〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1297s"]]}, {"cat": "体のこと", "t": "契約が終わった後に体調が回復した", "b": "団体を離れた時は落ち込んだが、気持ちが楽になった面もあり、前糖尿病の数値や卵巣の問題は落ち着いたという。ストレスの大きい競争の環境だったとも振り返る。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（24:03〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1443s"]]}, {"cat": "リングに来るまで", "t": "2017年の見学で年齢が足りず待つことになった", "b": "2017年に米国の団体の関係者が練習を見に来て注目されたが、当時は年齢が足りず契約は見送りになったという。その後も連絡は続き、数年後に入団テストを受けたそうだ。父は英語の勉強も大学も並行してさせてくれたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（24:50〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1490s"]]}, {"cat": "リングに来るまで", "t": "入団からわずか4か月でテレビ出演が決まった", "b": "育成施設に入って4か月で、突然、毎週のテレビ番組に出ると告げられたという。仮面をつけたキャラで、試合前に生放送でスペイン語のマイクをすることになったそうだ。クラスは週2回ほどで、マイクの練習はほとんどなかったと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（28:05〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1685s"]]}, {"cat": "リングの話", "t": "初のテレビ出演は即興のマイクだった", "b": "生放送の入場前に与えられた役は、既存の仮面レスラーと並ぶ新しい仮面の選手だったという。台本はなく、緊張の中で即興でマイクをやり切ったそうで、何を言ったかも覚えていないと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（29:44〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1784s"]]}, {"cat": "暮らし", "t": "免許を取ってすぐ米国で運転し、一人暮らしを始めた", "b": "渡米した週に運転免許を取り、現地で借りた車で大きな道路を走って慣れていったという。家具をそろえ、すべて一人で整えたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（31:26〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1886s"]]}, {"cat": "リングの話", "t": "仮面の役と素顔の役を日によって使い分けた", "b": "契約は約3年で、満了の2か月前に解雇されたという。その間は、テレビでは仮面、会場の興行では素顔というように、日によって二つの役をこなしていたそうだ。後に新しい仮面の名前とデザインに変わり、メインのテレビ番組やほかの番組にも出たと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（33:05〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=1985s"]]}, {"cat": "リングの話", "t": "解雇は安心でもあり落ち込みでもあった", "b": "パンデミックの終わりごろの人員整理で解雇されたという。重荷から解放された安心と、大きな落ち込みの両方があったと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（34:40〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2080s"]]}, {"cat": "リングの話", "t": "メキシコの団体を選び、素顔で再出発した", "b": "別の団体の誘いもあったが、より本格的な環境で学びたくメキシコの団体の門を叩いたという。すぐに就労ビザが出て、仮面は外して素顔で戦うことにしたそうだ。以前の仮面のキャラは、ありがちなラテンの役に感じて合わなかったと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（35:28〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2128s"]]}, {"cat": "リングの話", "t": "ウルティモ・ゲレーロの厳しい指導に鍛えられた", "b": "米国の大きな育成施設では、名門の家系の選手が多く、自分は劣っていると感じていたという。ウルティモ・ゲレーロは宙返りを何度もやり直させ、頭から落ちても続けさせたそうで、それが成長につながったと感謝している。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（37:09〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2229s"]]}, {"cat": "リングの話", "t": "メキシコで2年、大観衆に温かく迎えられた", "b": "2022年にメキシコへ来て2年余りになるという。アリーナ・メヒコでの歓声や、ファンの反応に支えられていると話す。チリ式の話し方も米国時代に中立的なスペイン語に変えたことで変わったそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（38:45〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2325s"]]}, {"cat": "暮らし", "t": "メキシコでは近所も含めて家族のように接してもらえる", "b": "メキシコでは近所の人や会場でもあたたかく声をかけられ、二つの大家族を得たように感じているという。米国で専門医を探すのに苦労したのに比べ、周囲が助けてくれるとも話す。最近は食事で胃の調子を崩すこともあるそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（39:36〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2376s"]]}, {"cat": "家族", "t": "メキシコで出会った人と結婚した", "b": "来た頃に出会った人に一目ぼれしたが、その人は一度カナダへ行き、その後に交際が始まったという。今は夫婦で、そばで支えてもらっていると話す。ジムでパーソナルトレーナーとしても働いていた時期があるそうだ。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（41:58〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2518s"]]}, {"cat": "リングの話", "t": "アリーナ・メヒコで代表格になりたい", "b": "当面はメキシコで時間を使い、団体の代表的な存在になって王座も狙いたいと話す。米国の団体からは再び声がかかっているが、まずメキシコで力をつけるつもりだという。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（42:44〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2564s"]]}, {"cat": "リングの話", "t": "敗れた試合で泣いたファンに会いに行った", "b": "王座を落とした試合のあと、会場で泣いていた少女の映像を見て、後で本人を探して会ったという。自分も子どもの頃そうしたかったと語る。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（44:17〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2657s"]]}, {"cat": "好きなもの", "t": "トリッシュ・ストラタスに会って感謝を伝えた", "b": "サイン会で憧れの選手に会い、あなたが私を作ってくれたと伝えたところ、抱きしめてもらったという。デビューしたニューヨークの会場と同じ場所だったそうだ。ほかにも多くのベテランに会えたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（45:59〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2759s"]]}, {"cat": "リングの話", "t": "アンダーテイカーらの練習に付き合った", "b": "練習の場でアンダーテイカーの練習に基盤役として付き合い、その妻も同席していたという。ルチャ(メキシコ式)との違いを学べ、成功談も聞けたと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（47:00〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2820s"]]}, {"cat": "体のこと", "t": "心の健康に投資することの大切さを説く", "b": "先輩たちから、レスラーは体だけでなく心も鍛える必要があり、心理士への相談も勧められたという。自身もその考えに沿って心の安定に投資してきて、うまくいっていると話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（48:26〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=2906s"]]}, {"cat": "暮らし", "t": "パンデミックのころ同郷の人々を助けていた", "b": "パンデミックの時期、米国でチリ出身の家族を見つけて食事を届けたり助けたりしていたという。人を見返りなく助けたことが成長につながったと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（50:01〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=3001s"]]}, {"cat": "リングに来るまで", "t": "二重国籍も考えており、メキシコへの恩返しを望む", "b": "結婚を機に二重国籍の取得を考えているという。チリを代表しつつ、メキシコにも恩返しがしたいと話す。", "sp": "ラ・カタリナ", "d": "2024-04-19", "how": "W Deportesの番組で（字幕を全文確認）", "art": "ext-HkUaSQ36AFE", "src": [["番組のYouTube（52:24〜）", "https://www.youtube.com/watch?v=HkUaSQ36AFE&t=3144s"]]}]);
  ARTICLES.push({ id: "ext-HkUaSQ36AFE", d: "2024-04-19", show: "ext", who: ["La Catalina"], t: "ラ・カタリナの回　チリからメキシコへ、ディーバが歩いた道", lead: "W Deportesの番組に出た約52分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["La Catalina"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-HkUaSQ36AFE").map((x) => [x.t, x.b, x.sp])), open: ["自動字幕のため、固有名詞が崩れている箇所は載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=HkUaSQ36AFE"]] });
  if (!ROSTER.find((r) => r[1] === "Jaida Parker")) ROSTER.push(["ジェイダ・パーカー", "Jaida Parker", "lg", "NXTの新星", "", "", ""]);
  if (!PROFILES["Jaida Parker"]) PROFILES["Jaida Parker"] = { lead: "サッカー少年のように兄と育ち、WWEにスカウトされて飛び込んだ新星。ベルトに名前を刻むという強い思いと、憎まれ役を楽しむ姿勢が伝わる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jaida%20Parker"]], moves: [], facts: [] };
  if (PROFILES["Jaida Parker"]._weak) { PROFILES["Jaida Parker"].lead = "サッカー少年のように兄と育ち、WWEにスカウトされて飛び込んだ新星。ベルトに名前を刻むという強い思いと、憎まれ役を楽しむ姿勢が伝わる。"; delete PROFILES["Jaida Parker"]._weak; }
  PROFILES["Jaida Parker"].facts.push(...[{"cat": "家族", "t": "兄の影響で技の名前を知っていた", "b": "幼いころ、兄と一緒にプロレスをよく見ていたという。祖父も一緒にのめり込み、業界に入る前からRKOという技を知っていたそうだ。兄には今も感謝していると話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（1:47〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=107s"]]}, {"cat": "リングに来るまで", "t": "育ったのはサッカー漬けの日々", "b": "プロレスよりもサッカーを見て育ち、競技もサッカーだったという。プロレスは「もう一度子どもに戻れる機会」だと感じ、迷わず飛び込んだと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（1:47〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=107s"]]}, {"cat": "リングに来るまで", "t": "体を使う部分に移行の苦労はなかった", "b": "プロレスへの転向で、体のぶつかり合いには戸惑いがなかったという。殴られたら殴り返す環境で育ったおかげで、難しかったのは気持ちの面のほうだと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（2:33〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=153s"]]}, {"cat": "リングに来るまで", "t": "入場口で「ここに来たことがある」と感じた", "b": "初めて入場口に立ったとき、不思議な既視感があったという。サッカー場のような場所を想像していたが、この場所だと分かったそうだ。これまで誰にも話していなかったと明かす。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（3:24〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=204s"]]}, {"cat": "リングに来るまで", "t": "チームから「一人きり」の舞台へ", "b": "団体競技の出身なので、大勢の視線が自分だけに集まる状況には慣れが必要だったという。リングの上では自分と観客だけだと受け止められるようになったそうだ。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（4:12〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=252s"]]}, {"cat": "リングに来るまで", "t": "大学5年目にSNSでスカウトされた", "b": "大学の5年目に、WWEからSNSのメッセージで連絡が来たという。詐欺ではと疑ってマネージャーに相談し、メールや面談を経て本物だと分かったそうだ。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（4:57〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=297s"]]}, {"cat": "リングに来るまで", "t": "サッカーのドラフトを先に受けたかった", "b": "WWEに頼んでサッカーのドラフトを先に受けさせてもらったが、希望どおりにはならなかったという。その結果がWWE入りにつながり、与えられた機会を全力でつかんだと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（4:57〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=297s"]]}, {"cat": "家族", "t": "兄のフットボール仲間に囲まれて育った", "b": "兄がよくフットボール部の仲間を家に連れてきたため、男の子たちに囲まれて育ったという。手加減されない環境だったそうで、人形遊びより外で体を動かすタイプだったと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（7:25〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=445s"]]}, {"cat": "リングの話", "t": "モットーは「血を流すのは相手も同じ」", "b": "育ちの影響で、リングでも臆さずに行くのが信条だという。殴られるなら自分も全力で返すという考えで、怖がる理由はないと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（7:25〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=445s"]]}, {"cat": "暮らし", "t": "SNSで私生活が開かれ、家族が視線に戸惑う", "b": "有名になって、SNSのせいで私生活が丸見えになったと感じているという。大きな大会の後、家族は人に見られることに慣れておらず、父が冗談めかして護衛を申し出てきたそうだ。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（9:08〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=548s"]]}, {"cat": "リングに来るまで", "t": "身内を亡くした時期にトーナメント出場が決まった", "b": "若手のトーナメントに代役で出る連絡が来たとき、続けて親族を亡くした直後だったという。電話を受けて泣き崩れ、人生で最高の瞬間の一つになったと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（9:58〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=598s"]]}, {"cat": "体のこと", "t": "緊張の種類はサッカーの頃と別物", "b": "試合前の緊張はサッカー時代にもあったが、カメラや観客が近いと感じ方が違うという。「緊張は大きなことをやる前に出るもの」と教わり、そのまま力に変えたそうだ。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（10:49〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=649s"]]}, {"cat": "リングの話", "t": "ベルトに自分の名前を刻みたい", "b": "大会は歴史に残る王座決定戦で、その一員ではなく「ベルトに名前が残る人」になりたいと語る。ほかの出場者より100％以上を出す覚悟で、自分のための戦いだとも話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（11:36〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=696s"]]}, {"cat": "リングの話", "t": "「ミス・パーカー」の呼び名はブッカーTから", "b": "ファンの間に広まった「ミス・パーカー」は、デビュー戦でブッカーTが口にした呼び方が元だという。気に入って受け入れていると笑って話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（13:13〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=793s"]]}, {"cat": "リングの話", "t": "ファンには「憎まれたい」と思っている", "b": "ファンに愛されるのは嬉しいが、相手を倒す役なので憎まれることも必要だと語る。応援と野次の両方を受け止め、自分は自分のままでいると話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（13:13〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=793s"]]}, {"cat": "好きなもの", "t": "映画やアニメから試合の発想を得る", "b": "試合の組み立ての考え方は、当時のコーチのノーマン・スマイリーに「映画を見るように人の動きを見ろ」と言われたのがきっかけだという。以来、映画を普通には見られなくなったと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（16:25〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=985s"]]}, {"cat": "好きなもの", "t": "アニメは兄に勧められて好きになった", "b": "もともとアニメ好きではなかったが、兄に勧められて見るようになったという。今では見ながら「これは使える」と考えが止まらなくなり、昔の試合映像も好んで見るそうだ。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（17:16〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=1036s"]]}, {"cat": "リングの話", "t": "憧れの選手を絞って学んでいる", "b": "男子ではエディ・ゲレロとノーマン・スマイリー、女子ではメルセデス・モネ、サーシャ・バンクス、チャイナ、リア・リプリーを挙げたという。学ぶ相手を絞るほうが成果が出ると話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（18:49〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=1129s"]]}, {"cat": "リングの話", "t": "OTMの仲間が気持ちを支えてくれた", "b": "入団当初はOTMのブロンコ、ルシアン、スクリプスに助けられ、その後の合流で緊張が和らいだという。似た過去を持つ仲間だと分かり合え、自分の声を出せる居場所だと話す。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で（字幕を全文確認）", "art": "ext-bAiP1xb-USU", "src": [["番組のYouTube（22:03〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=1323s"]]}]);
  if (PROFILES["Norman Smiley"]) PROFILES["Norman Smiley"].facts.push({"cat": "暮らし", "t": "ノーマン・スマイリーの仕事への姿勢", "b": "リングでの見方をすべて変えてくれたコーチで、仕事に向き合う姿勢と試合の考え方を尊敬していると、ジェイダ・パーカーが話している。", "sp": "ジェイダ・パーカー", "d": "2024-05-28", "how": "リアリティ・オブ・レスリングの番組で、ジェイダ・パーカーの話（字幕を全文確認）", "src": [["番組のYouTube（18:49〜）", "https://www.youtube.com/watch?v=bAiP1xb-USU&t=1129s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-bAiP1xb-USU", d: "2024-05-28", show: "ext", who: ["Jaida Parker"], t: "ジェイダ・パーカーの回　サッカーからリングへ、新星の素顔", lead: "リアリティ・オブ・レスリングの番組に出た約25分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jaida Parker"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-bAiP1xb-USU").map((x) => [x.t, x.b, x.sp])), open: ["試合の宣伝や次の大会への意気込みだけの話は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=bAiP1xb-USU"]] });
  if (!ROSTER.find((r) => r[1] === "Christian Cage")) ROSTER.push(["クリスチャン・ケイジ", "Christian Cage", "gn", "元WWEタッグ王者。他団体", "", "", ""]);
  if (!PROFILES["Christian Cage"]) PROFILES["Christian Cage"] = { lead: "WWEでタッグ王者として名を上げ、自分を証明するために一度は会社を離れた。頭部のけがによる引退宣告からの復帰までを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Christian%20Cage"]], moves: [], facts: [] };
  if (PROFILES["Christian Cage"]._weak) { PROFILES["Christian Cage"].lead = "WWEでタッグ王者として名を上げ、自分を証明するために一度は会社を離れた。頭部のけがによる引退宣告からの復帰までを語る。"; delete PROFILES["Christian Cage"]._weak; }
  PROFILES["Christian Cage"].facts.push(...[{"cat": "WWEでの日々", "t": "会場入りのたび「今日こそ見せる」と唱えた", "b": "体が大きくも速くも強くもない自分は、人より努力が要ると感じていたという。そのため会場に着いて車を降りるたびに、「今日、お前の実力を皆に見せろ」と心の中で言い聞かせていたそうだ。下から追いかける気持ちが原動力だったと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（11:57〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=717s"]]}, {"cat": "退団の理由", "t": "頭を強く打つ場面が続いた", "b": "短い期間に何度も脳しんとうを起こしたと話す。バトルロイヤルで意識を失った試合や、生放送の試合で途中から記憶が飛んだ試合を、特に鮮明に覚えているという。最後は頭を蹴られて回転するようなめまいが止まらなくなったそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（24:06〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=1446s"]]}, {"cat": "退団の理由", "t": "検査に落ち、試合出場の資格を失った", "b": "大学の脳しんとう専門施設で検査を受けたが、本人は症状が残る状態で受けたと感じているという。結果は伝えられず、大きな大会の前に対戦カードから名前が消えていて、あとから医学的に出場不可と告げられたそうだ。選択の余地はなく、永久の扱いだと言われたと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（25:45〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=1545s"]]}, {"cat": "退団の理由", "t": "再検査は一度もなく、そのまま受け入れた", "b": "あとで再評価をしようという話は出ず、しばらくは自分の健康のためだと受け止めていたと話す。ただ体を戻してから同じ施設で検査を受けると、成績は平均以上で、医師から「続けたいなら続けられる」と言われたそうだ。これが復帰への大きな力になったという。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=1638s"]]}, {"cat": "退団の理由", "t": "復帰戦への後悔と、最後の記憶への思い", "b": "復帰した年の大会前の試合は、無観客に近い状況で、本人は万全ではなかったと話す。観客の期待に応えきれなかったと感じ、これが最後の姿になってよいのかとも考えたそうだ。画面越しに観客の顔が見えて、入場曲が流れたときの感触は良かったという。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（28:51〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=1731s"]]}, {"cat": "退団の理由", "t": "復帰後の契約話は、数字の前で止まった", "b": "復帰した大会の反響は大きかったが、会社との話し合いは金額の段階まで進まなかったと話す。主にスケジュールや自分がどこまで働けるかの調整だったという。同じ頃、友人の選手から「どこで終えるか選べるのは自分だ。話くらいはしたほうがいい」と背中を押されたそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（30:32〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=1832s"]]}, {"cat": "退団の理由", "t": "認められたくて最初にWWEを離れた", "b": "自分はずっと、認められるために証明し続けなければと感じてきたと話す。最初に会社を離れた理由もそこにあったという。英国での興行では本来ベビーフェイスの大物より自分への歓声が大きく、その後の三者抗争には後から別の選手が加えられた。自分に任せてもらえないのかと悔しく、「変えるなら自分で変えるしかない」と思ったそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（36:53〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2213s"]]}, {"cat": "退団の理由", "t": "噂は気にせず、道は人それぞれと考える", "b": "なぜ会社が自分を大きく扱わなかったのかは今も分からないと話す。噂は多いが、そこに時間や考えを割かないようにしているという。人の歩む道はそれぞれで、すべては理由があって起きると思っているそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（37:39〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2259s"]]}, {"cat": "退団の理由", "t": "別の団体は成長の場だったと振り返る", "b": "当時は他に移る選手がほとんどいなかったが、移った先の団体は活躍の場を与えてくれたと感謝している。社長への敬意もあり、楽しい時間だったという。35歳の自分にとって、今戻らなければ二度と戻れないという思いと、やり残した感覚があったと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（38:25〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2305s"]]}, {"cat": "退団の理由", "t": "8年休みなしで、自分を見失いかけていた", "b": "24歳でツアー生活に入り、8年間ほぼ休みなく走り続けたと話す。誕生日や記念日、家族の集まりを逃し続け、自分らしさを忘れかけていたそうだ。少しのあいだ本来の自分に戻る時間が必要だったという。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（39:12〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2352s"]]}, {"cat": "退団の理由", "t": "再入団後に感じた「もう合わないかも」", "b": "最初の在籍期より年を重ねて成熟し、日々の過酷な移動にも対応しやすくなったと話す。一方で大会に復帰して出てみると、自分はここで同じことをやる体制にはもう向いていないのかもしれないとも感じたそうだ。それが別の道を考える気持ちにつながったという。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（40:53〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2453s"]]}, {"cat": "WWEでの日々", "t": "「ピープス」は入場の偶然から生まれた", "b": "入場口に出たとき、観客席の一列に文字を一つずつ掲げて「ピープス」と並べた人たちがいたという。気づいたと手を上げて合図したのが始まりだったそうだ。入場時にいつも何かしゃべっていたが、中身は自分でも覚えていないと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（41:43〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2503s"]]}, {"cat": "WWEでの日々", "t": "地元トロントでの大舞台で相手を支えた", "b": "年間最大の祭典がカナダの地元で開かれたときの話だ。相手の伝説的な選手はWWEの流儀に慣れず苦労していて、お互いに必要な存在だったという。自分は試合と番組にとって最善を尽くす考えで、相手も信頼してくれて、良い連戦になったと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（47:14〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2834s"]]}, {"cat": "WWEでの日々", "t": "大事な場面は舞台袖で生で感じる", "b": "大きな場面は、モニターではなく舞台袖まで出て生で見るようにしていたと話す。会場の空気を肌で感じたいからだという。あの大会で感じた熱は、今も他で味わったことがないそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（48:50〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=2930s"]]}, {"cat": "WWEでの日々", "t": "TLCは「はしご戦」を大きくする発想だった", "b": "最初の企画の細かい点は覚えていないが、テーブル、はしご、イスという要素は納得できたという。はしご戦だけの繰り返しから抜け出し、賭けるものを大きく見せる狙いがあったそうだ。回数を重ねて、事故のような試合にならないための組み立て方を学んだと話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（54:30〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3270s"]]}, {"cat": "WWEでの日々", "t": "上のものを取ることを忘れないのが鉄則", "b": "はしごの試合では、最終的な目標は頭上のものを取ることだと強調する。余計な動きで目的を見失う選手が多いという。上に行ける機会があれば、必ず上に行くのが基本の考え方だそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（55:22〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3322s"]]}, {"cat": "WWEでの日々", "t": "初のタッグはしご戦で仲間から総立ちの拍手", "b": "タッグでのはしご戦は前例がなく、受け入れられるか分からなかったと話す。試合を終えて幕の裏に戻ると、各部署の仲間がみな立って拍手してくれたそうだ。その瞬間、特別なことをやったと感じたという。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（56:10〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3370s"]]}, {"cat": "WWEでの日々", "t": "ハリケーンで相棒が試合直前に滑り込んだ", "b": "その興行の前、相棒はバハマで嵐に足止めされ、マイアミ経由で長距離を移動して、開演の数時間前にやっと会場に着いたという。本番は何が起きるか分からなかったが、あの夜は偶然うまくいったと話す。人生が変わった一夜だったそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（56:57〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3417s"]]}, {"cat": "WWEでの日々", "t": "今も親子で当時の試合を見たと言われる", "b": "サイン会などで、小さな子が「親に見せられた」と当時の試合の話をしてくるという。まだ生まれていない時代の試合だと笑う。時代を越えて残るものを作れたのだと感じていると話す。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（57:45〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3465s"]]}, {"cat": "退団の理由", "t": "会社の枠から自由になった今の心境", "b": "WWE時代の自分と今の自分は、頭の中では完全に別の存在だと話す。今は誰かに「これを言うな、あれをしろ」と言われず、うまくいくかどうかも自分次第だという。当時の自分は今の自分に遠く及ばないと本人は考えているそうだ。", "sp": "クリスチャン・ケイジ", "d": "2024-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-TdfRElAhmEs", "src": [["番組のYouTube（58:33〜）", "https://www.youtube.com/watch?v=TdfRElAhmEs&t=3513s"]]}]);
  ARTICLES.push({ id: "ext-TdfRElAhmEs", d: "2024-06-04", show: "ext", who: ["Christian Cage"], t: "クリスチャン・ケイジの回　WWEを離れた理由と、けがによる引退宣告、そして復帰まで", lead: "クリス・ヴァン・ヴリートの番組に出た約60分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Christian Cage"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-TdfRElAhmEs").map((x) => [x.t, x.b, x.sp])), open: ["WWEの話の中でも、試合結果や筋書きの細部は本人の説明が断片的なため省いた。", "他団体での日々や家庭・健康の話は公開項目に含めていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=TdfRElAhmEs"]] });
  if (!ROSTER.find((r) => r[1] === "Mercedes Mon\u00e9")) ROSTER.push(["メルセデス・モネ", "Mercedes Mon\u00e9", "gn", "元サーシャ・バンクス。他団体", "", "", ""]);
  if (!PROFILES["Mercedes Mon\u00e9"]) PROFILES["Mercedes Mon\u00e9"] = { lead: "10歳からの夢だったWWEで約10年を過ごしたメルセデス・モネ。心の声に従って去った決断を、最もつらく、今は最良だったと振り返る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Mercedes%20Mon\u00e9"]], moves: [], facts: [] };
  if (PROFILES["Mercedes Mon\u00e9"]._weak) { PROFILES["Mercedes Mon\u00e9"].lead = "10歳からの夢だったWWEで約10年を過ごしたメルセデス・モネ。心の声に従って去った決断を、最もつらく、今は最良だったと振り返る。"; delete PROFILES["Mercedes Mon\u00e9"]._weak; }
  PROFILES["Mercedes Mon\u00e9"].facts.push(...[{"cat": "WWEでの日々", "t": "年間最大の祭典で黒人女性初のメインイベント", "b": "第37回の年間最大の祭典で、アフリカ系の女性として初めてメインイベントに立ったとモネは語る。37は13歳の頃から自分のエンジェルナンバーだったそうだ。かつて「ディーバ」と呼ばれた女性選手が「スーパースター」になった流れの先頭にいられたことを誇りに思っているという。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（6:30〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=390s"]]}, {"cat": "WWEでの日々", "t": "指導者に否定された2年後に入団", "b": "駆け出しの頃、コーチから「小さすぎる」「地味だ」と言われ、見込みがないとまで言われたという。モネは見返してやると決め、その2年後にWWEと契約したと話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（10:31〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=631s"]]}, {"cat": "退団の理由", "t": "辞めたいのは雑音であって、リングではなかった", "b": "退団の前後の約2年間、プロレスそのものをやめるべきか悩んだという。しかし嫌だったのはネット上の騒ぎや社内の政治で、リングや観客の前で立てる場所ではないと気づいたとモネは話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（10:31〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=631s"]]}, {"cat": "WWEでの日々", "t": "10歳からの夢の団体に約10年在籍", "b": "WWEは10歳の頃からの夢で、約10年在籍したとモネは話す。プロとしては14年のキャリアを積んでいた時期に退団を決めたという。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=726s"]]}, {"cat": "退団の理由", "t": "最大の理由は自分の心の声", "b": "理由はいくつもあるが、一番は心と魂の声に従ったことだとモネは話す。あの日、自分に向けられた言葉の調子が心に落ちず、居場所がないように感じたという。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=726s"]]}, {"cat": "退団の理由", "t": "「ここで動かなければ幸せになれない」", "b": "14年も続けてきたのに、そこまで低く扱われたように感じたとモネは語る。ここで自分の人生の主導権を握らなければ、そこでは一生幸せになれないと直感したそうだ。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=726s"]]}, {"cat": "退団の理由", "t": "人生で最も難しい決断が、最良の決断に", "b": "10歳からの夢の会社を自分から去ることは、人生で一番難しい決断だったという。しかし今になってみると、人生で最良の決断だったとモネは話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=726s"]]}, {"cat": "退団の理由", "t": "出た先には開いた扉がたくさんあった", "b": "ドアの外に出たことで、より多くの扉が開いたとモネは話す。恐れても失敗してもいい、それが成長になると考え、この2年が最も成長した時期だったという。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（12:57〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=777s"]]}, {"cat": "退団の理由", "t": "収入が不安定な2年間への不安", "b": "夢だった会社を離れる決断は、自分だけの問題ではなかったとモネは話す。家族を経済的に支えているため、収入が安定しない約2年間、次にどこへ行けるのかが見えない不安があったそうだ。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（13:45〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=825s"]]}, {"cat": "WWEでの日々", "t": "「危ない選手」という声に落ち込んだ", "b": "2017〜2018年頃、ある試合をきっかけに「安全ではない選手」という声が出たという。最高の選手を目指してきただけに、その言葉でひどく落ち込んだとモネは話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（20:11〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1211s"]]}, {"cat": "WWEでの日々", "t": "2015年の一戦で実力は否定できないと確信", "b": "2015年にベイリーと戦った試合を終えて、自分の仕事ぶりはもう否定できないと思ったという。「無視できないほど良くなれ」という言葉を信条にしてきたと話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（24:16〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1456s"]]}, {"cat": "WWEでの日々", "t": "ドラマ出演を巡る会社とのやりとり", "b": "スター・ウォーズのドラマへの出演をめぐり、WWEは撮影の日に興行をあてるなど、なかなか出演させたがらなかったとモネは話す。出演にこぎつけるのは骨が折れる作業だったという。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（24:16〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1456s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典の入場をラッパーが支えた", "b": "16歳のとき、親戚のスヌープ・ドッグに連れられて初めて年間最大の祭典を観に行ったという。それから約10年後、第32回大会ではスヌープ・ドッグがモネと一緒に入場ランプを歩き、入場曲も手がけたと話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（26:42〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1602s"]]}, {"cat": "WWEでの日々", "t": "セーラームーン風のコスチュームが大好評", "b": "夫が手がけた衣装の中で一番のお気に入りは、女子の王座戦へ向かう大会でのセーラームーンのギアだったという。会場の反応も大きく、自分でも最高の気分だったとモネは話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（30:47〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1847s"]]}, {"cat": "WWEでの日々", "t": "ブリーフケース戦の衣装は大の不満", "b": "出世のかかるブリーフケース争奪戦の衣装は色の組み合わせが気に入らず、泣いて怒ったそうだ。自信を持てないまま入場し、少し滑ってしまったと本人は話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（31:33〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1893s"]]}, {"cat": "WWEでの日々", "t": "リングネームは名前を書き出して決まった", "b": "育成の場で、百個ほど名前を書き出すよう言われたという。モネが書いた名前の組み合わせから、会社側が使えるキャラクターとして「サーシャ・バンクス」を決めたと話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（32:21〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1941s"]]}, {"cat": "WWEでの日々", "t": "名前の権利は会社が持っていた", "b": "WWEでは所属選手の名前の知的財産を会社が持つため、辞めるとその名前は使えなくなるとモネは説明する。今のメルセデス・モネという名前は自分で権利を持っていると話す。", "sp": "メルセデス・モネ", "d": "2024-07-01", "how": "ニューヨークの番組インタビュー（WYSチャンネル）で（字幕を全文確認）", "art": "ext-7isFj9MlSG8", "src": [["番組のYouTube（33:10〜）", "https://www.youtube.com/watch?v=7isFj9MlSG8&t=1990s"]]}]);
