  PROFILES["Byron Saxton"].facts.push(...[{"cat": "リングに来るまで", "t": "4歳からのファン", "b": "ワシントンDC近郊のバージニア州フェアファックスで育ち、4歳でレッスルマニア3のホーガン対アンドレを見てからのファンだという。初めて生で見たのはDCの会場でのWCWの金網戦だったそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=145s"]]}, {"cat": "好きなもの", "t": "子ども団体の「王者」", "b": "子どものころ、友だちと「キッズ・レスリング連盟」を作り、ビデオカメラで収録や大会まで開いていたという。友だちが来られない日は一人で10人分を演じたので、自然と自分が王者になったと笑う。おもちゃのベルトに手作りのロゴを貼っていたそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=196s"]]}, {"cat": "リングに来るまで", "t": "記者からWWEへ", "b": "WWEに入る前はテレビ局でニュースやスポーツ、交通情報のリポーターをしていたという。インディーでのリングアナ、選手、実況の映像もまとめた売り込み用のテープを持ってきたところ、ダスティ・ローデスに「マネージャーも実況もリングアナも全部やれ」と言われたそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（5:45〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=345s"]]}, {"cat": "リングの話", "t": "ダスティの「ニワトリになれ」", "b": "ダスティのプロモ講座を手伝っていたという。話すのが苦手な選手には「1分間ニワトリになれ」と課し、言葉に頼らず感情を表すことや、恥をかく覚悟を教えていたそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（7:21〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=441s"]]}, {"cat": "リングの話", "t": "選手たちで演劇を上演", "b": "ダスティの発案で、練習後に選手たちと映画を下敷きにした舞台劇を上演したことがあるという。配役の募集ポスターを貼り、台本を書き、自分が監督を務めたそうだ。ダスティはレインズの初試合を見て「あれはスターになる」と言ったと話す。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（8:55〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=535s"]]}, {"cat": "リングの話", "t": "コフィの戴冠と父", "b": "レッスルマニア35でコフィ・キングストンが王者になった瞬間を実況し、涙が出たという。昔ロン・シモンズが王者になったとき、プロレスファンではなかった父が大喜びしていたのを思い出したそうだ。そのころ父は重い病気で、試合を見ることはできなかったと話す。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（17:50〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=1070s"]]}, {"cat": "リングの話", "t": "コーリー・グレイブスとの掛け合い", "b": "解説席での名コンビ、コーリー・グレイブスとは育成時代からの付き合いで、どちらも選手としての道が突然終わった者同士だという。放送での言い合いは打ち合わせなしで自然に生まれていたそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（21:09〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=1269s"]]}, {"cat": "リングの話", "t": "ストーン・コールドに打たれた夜", "b": "無観客時代にストーン・コールドのスタナーを受けたことは、まったく予想していなかったという。高校時代は友人に「ストーン・コールドのまねをやめろ」と言われるほどのファンだったそうだ。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（22:47〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=1367s"]]}, {"cat": "暮らし", "t": "お酒はほぼ飲まない", "b": "お酒はほとんど飲まず、ビールは人生で一口飲んだだけだったという。スタナーの後のビールでむせそうになり、投げ込まれた缶が目に当たってあざもできたそうだ。帰りの車で母に「捕まったら酒臭いと思われるよ」と言われたと笑う。", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で（字幕を全文確認）", "art": "ext-cp9_q0w8UlA", "src": [["番組のYouTube（24:21〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=1461s"]]}]);
  if (PROFILES["Kofi Kingston"]) PROFILES["Kofi Kingston"].facts.push({"cat": "暮らし", "t": "昔から変わらない人", "b": "コフィは育成時代に知り合ったころから変わらず、練習後にビュッフェで食べ物を投げ合っていたような気さくな人のまま王者になったと、バイロン・サクストンが話している", "sp": "バイロン・サクストン", "d": "2024-07-02", "how": "スクエアド・サークル・ラジオ（ファンのポッドキャスト）で、バイロン・サクストンの話（字幕を全文確認）", "src": [["番組のYouTube（17:50〜）", "https://www.youtube.com/watch?v=cp9_q0w8UlA&t=1070s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-cp9_q0w8UlA", d: "2024-07-02", show: "ext", who: ["Byron Saxton"], t: "バイロン・サクストンの回　何でも屋の17年", lead: "スクエアド・サークル・ラジオ（ファンのポッドキャスト）に出た約41分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Byron Saxton"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-cp9_q0w8UlA").map((x) => [x.t, x.b, x.sp])), open: ["後半（29分以降）の話は今回は読んでいない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=cp9_q0w8UlA"]] });
  if (!ROSTER.find((r) => r[1] === "Adam Pearce")) ROSTER.push(["アダム・ピアース", "Adam Pearce", "lg", "RAWの総支配人", "", "", ""]);
  if (!PROFILES["Adam Pearce"]) PROFILES["Adam Pearce"] = { lead: "元NWA王者から総支配人になった人物。悪役を貫いた現役時代の裏話に加え、妻との出会いや家族、「誰かを愛そう」という信条など素顔が語られた回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Adam%20Pearce"]], moves: [], facts: [] };
  if (PROFILES["Adam Pearce"]._weak) { PROFILES["Adam Pearce"].lead = "元NWA王者から総支配人になった人物。悪役を貫いた現役時代の裏話に加え、妻との出会いや家族、「誰かを愛そう」という信条など素顔が語られた回。"; delete PROFILES["Adam Pearce"]._weak; }
  PROFILES["Adam Pearce"].facts.push(...[{"cat": "リングに来るまで", "t": "約20年、インディーで戦った", "b": "WWEで総支配人を務める前に約20年間レスラーとして活動してきたという。NWAの世界ヘビー級王座を5度獲得した経歴の持ち主だ。観客の多くはその過去を知らず、驚いた顔をされることが多いと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=95s"]]}, {"cat": "リングに来るまで", "t": "NWA王座が今の自分をつくった", "b": "NWAの王座がなければ今の自分の立場はなかったと話す。王座を巻くときは、ハーレー・レイスやジャック・ブリスコのような先人にならい、伝統を受け継ぐ気持ちで守ってきたそうだ。ダスティ・ローデスらからも、その姿勢を評価してもらえたという。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=145s"]]}, {"cat": "リングに来るまで", "t": "最後の試合は10年前の12月21日", "b": "ピアースが最後にプロの試合をしたのは、2014年12月21日だという。中邑真輔に勝ったことや、ブラウン・ストローマンと組んだタッグ戦が終盤の思い出だと話す。復帰の話には「もう終わった」と笑って応じている。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=242s"]]}, {"cat": "暮らし", "t": "総支配人は物語を支える脇役", "b": "ピアースは総支配人を、スーパースターを目立たせるための「情報の橋渡し役」と考えているそうだ。物語の向きを整えたり変えたりはするが、主役は常に選手だという。とても楽しい仕事だと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（6:24〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=384s"]]}, {"cat": "暮らし", "t": "1回の放送で最大10回登場", "b": "1回の3時間番組で、画面に10回出たことがあるという。ウィリアム・リーガルが13回出たと聞いたことがあるそうだ。裏方では番組のプロデューサーも務め、以前はライブイベントの責任者として興行を組んでいたと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（8:44〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=524s"]]}, {"cat": "リングに来るまで", "t": "ROHで番組作りを学んだ", "b": "ピアースは5年間ROHと契約し、うち2年は会社の運営にも関わったという。そこで初めてテレビ番組の脚本や興行日程、選手との契約交渉を経験したそうだ。当時の仲間の多くと、今も一緒に働いていると話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（10:23〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=623s"]]}, {"cat": "リングに来るまで", "t": "WWEからの一本の電話", "b": "2012年、尊敬する人物から「二度と靴を履かないが、25年続く仕事がある」と持ちかけられたという。ピアースは「いつから？」と即答したと話す。同年8月には、他の選手と同じ入団テストを実際に受けたそうだ。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（10:23〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=623s"]]}, {"cat": "リングに来るまで", "t": "育成施設の完成を待った日々", "b": "テスト後、会社から新しい育成施設の完成まで待つよう言われたという。当時はサンディエゴ在住で、その間は宙ぶらりんの状態だったそうだ。2014年にゲストコーチを務め、2015年5月に正式にコーチ陣へ加わったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（12:02〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=722s"]]}, {"cat": "リングに来るまで", "t": "「道具箱」を増やせと教える", "b": "若手には、技の引き出しを増やして将来の選択肢を持つよう説いているという。ピアース自身は36歳で引退し、40代でも地方の小さな会場で体を張り続ける道は選ばなかったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（13:40〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=820s"]]}, {"cat": "家族", "t": "座右の銘は両親の教え", "b": "インスタのプロフィールにある「一生懸命働き、人に公平に接し、尊敬を得る」は両親から学んだものだという。父は工場の整備士として30年働いたのち、水道関係の仕事にも20年就いたそうだ。公平に接するという教えは母からで、時には厳しさも必要だと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（14:25〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=865s"]]}, {"cat": "リングの話", "t": "ヒールとして嫌われるのが仕事", "b": "レスラー時代は、観客から否定的な反応を引き出すことだけを考えていたという。それが人生で一番楽しい経験だったと目を輝かせて話す。観客に自分を応援させたくはなく、誰もが相手の勝利を願う状況を狙っていたそうだ。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（16:04〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=964s"]]}, {"cat": "リングに来るまで", "t": "観客2人の試合と電話機", "b": "インディアナポリスで観客がたった2人の興行に出たことがあるという。最初の試合でリングが壊れ、ギャラの代わりに主催者の机の電話と、ソフトドリンクを半ケースもらったそうだ。その電話は約15年、実家の台所に掛かっていたと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（16:51〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1011s"]]}, {"cat": "リングに来るまで", "t": "引退に迷いはなかった", "b": "引退を決めたのは36歳で、子どもが生まれて間もない頃だったという。次の道を探さないのはむしろ身勝手だと思ったそうだ。引退に未練はなかったと、きっぱり話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（19:15〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1155s"]]}, {"cat": "リングに来るまで", "t": "1998年頃、複数団体の誘いを断った", "b": "20歳前後のとき、WWF、WCW、ECWから話があったという。WCWの条件のほうが魅力的に思えて、WWFの入団テストをキャンセルしたそうだ。のちにWCWの試験も受けたが、当時の婚約者の家族が引っ越しに反対したこともあり、契約書には署名しなかったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（20:03〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1203s"]]}, {"cat": "リングに来るまで", "t": "3週間で消えた全国放送", "b": "その後は小さな団体で戦い続け、全国放送の団体に3週間だけ出たそうだ。番組はやがて消えたという。2000年11月、レスラーをやめるつもりでシカゴからカリフォルニアへ引っ越したが、結局は業界に戻ったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（23:18〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1398s"]]}, {"cat": "家族", "t": "兄との旅行がきっかけの出会い", "b": "海軍にいた兄を迎えにサンディエゴへ行ったところ、除隊が3週間延びたという。暇つぶしに国境を越えてメキシコのティファナへ遊びに行き、そこで後に妻となる女性と出会ったそうだ。約25年たった今も一緒にいて、人生で一番いいことだったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（25:41〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1541s"]]}, {"cat": "暮らし", "t": "妻の友人宅のソファに居候", "b": "出会いから半年後、ピアースは妻と3人のルームメイトが暮らす家のソファに住んでいたという。「あのレスラーは誰？」と不思議がられたそうだ。妻はレスラー人生の喜怒哀楽すべてを支えてくれたと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（27:19〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1639s"]]}, {"cat": "好きなもの", "t": "パドレスの場内アナ選考に残った", "b": "サンディエゴ・パドレスの場内アナウンサーのオーディションを友人と受けたところ、自分だけ残ったという。結果は5位ほどで、全国中継を3回担当したそうだ。大の野球好きで、場内アナはレスリングの司会と共通点が多いと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（27:19〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1639s"]]}, {"cat": "好きなもの", "t": "ヴィン・スカリーとの縁", "b": "ESPNの中継で、伝説の実況者ヴィン・スカリーと同じ場にいたという。食事中のスカリーに写真をお願いしようとしたが、先に別の人が声をかけていたため遠慮したそうだ。今は、失礼にならない範囲なら写真は撮るべきだと考えていると話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（29:45〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=1785s"]]}, {"cat": "暮らし", "t": "「誰かを愛そう」と投稿する理由", "b": "ピアースは毎日のように「今日は誰かを愛そう」とSNSに投稿しているという。ネット上の否定的な空気に気持ちが揺れ、妻に指摘された経験がきっかけだそうだ。見返りを求めずに愛を向けることが大切で、自分の心の支えにもなっていると話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（34:31〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2071s"]]}, {"cat": "暮らし", "t": "シカゴ育ちの挨拶好き", "b": "シカゴ出身のため、すれ違う人に挨拶する習慣があるという。ロサンゼルス育ちの妻には不思議がられたそうだ。ロサンゼルスは地元出身者が少なく、街への帰属意識が薄いと感じていると話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（36:04〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2164s"]]}, {"cat": "リングの話", "t": "ウォーゲームズの宣言は自分らしく", "b": "リーガルのウォーゲームズ宣言の後を任されたとき、本人に相談したという。リーガルは「自分らしくやればいい」と助言したそうだ。ピアースは、観客を沸かせる主役は選手だと考え、真似をしないよう心がけたと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（39:15〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2355s"]]}, {"cat": "リングの話", "t": "ブロック・レスナーに2回F5を受けた", "b": "レスナーのF5を受けた際、事前に持ち上げ方を相談し、自分も協力して軽く跳ぶと伝えたという。ズボンが破けたのは1回目で、控室に戻って気づいたそうだ。観客の「もう1回」の声に応えて2発目を受け、レスナーのプロ意識に感心したと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（40:50〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2450s"]]}, {"cat": "リングの話", "t": "レスナーとのムース話と携帯電話", "b": "レスナーがガラケーを手に、仕留めたヘラジカの重さを語る場面があったという。ピアースは「240ポンドだ」と言い返したかったそうだ。笑いが起きるやりとりで、楽しい仕事だったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（42:28〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2548s"]]}, {"cat": "リングの話", "t": "表情だけで受ける芝居", "b": "チェルシー・グリーンとの場面では、言葉を出さず目や顔で反応することを心がけたという。相手の勢いを受けるだけで成り立つ面白さがあると話す。若手にも、目と顔で「売る」ことを勧めているそうだ。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（43:16〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2596s"]]}, {"cat": "リングの話", "t": "ブレイ・ワイアットの家に配達員として", "b": "ブレイ・ワイアットの世界に郵便配達員として登場したのは、一度だけだったという。現場では自由度が高く、あの場所に圧倒される自分をそのまま演じたそうだ。衣装は今も持っていると話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（44:05〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=2645s"]]}, {"cat": "好きなもの", "t": "グリーンベイ・パッカーズの大ファン", "b": "アメフトのパッカーズを熱烈に応援していて、チームが不調だと熱くなってしまうという。批評家のように見るより、子どもの目で楽しむほうが番組も試合も楽しめると考えているそうだ。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（50:30〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=3030s"]]}, {"cat": "家族", "t": "16歳の息子は身長190cm超", "b": "息子は16歳でアメフトのタイトエンドをしているそうだ。子どもたちにはレスラーになることを強いるつもりはなく、やりたいことを応援する方針だという。本人たちもプロレスに進む気はなさそうだと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（52:56〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=3176s"]]}, {"cat": "家族", "t": "子どもに試合を見せなかった理由", "b": "現役時代は悪役だったため、幼い子どもに父の振る舞いを見せたくなかったという。子どもたちは、父は空港で働いていると思っていたそうだ。息子は荷物のバッグに入って遊んでいたが、成長して仕事を知ったと話す。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext--9x_6UuFha0", "src": [["番組のYouTube（54:31〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=3271s"]]}]);
  if (PROFILES["Seth Rollins"]) PROFILES["Seth Rollins"].facts.push({"cat": "暮らし", "t": "セス・ロリンズへの敬意", "b": "長年、別の場所で交差してきたセス・ロリンズを人としても尊敬していて、役作りの考え方に引かれると、アダム・ピアースが話している。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で、アダム・ピアースの話（字幕を全文確認）", "src": [["番組のYouTube（55:22〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=3322s"]], "by": "第三者の話"});
  if (PROFILES["Bron Breakker"]) PROFILES["Bron Breakker"].facts.push({"cat": "暮らし", "t": "ブロン・ブレイカーは超一流の素材", "b": "ブロン・ブレイカーを「一流の素質を持つ若手」と評価し、アメフト時代は今より軽く速かったそうだと、アダム・ピアースが話している。", "sp": "アダム・ピアース", "d": "2024-08-08", "how": "クリス・ヴァン・ヴリートの番組で、アダム・ピアースの話（字幕を全文確認）", "src": [["番組のYouTube（56:15〜）", "https://www.youtube.com/watch?v=-9x_6UuFha0&t=3375s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext--9x_6UuFha0", d: "2024-08-08", show: "ext", who: ["Adam Pearce"], t: "アダム・ピアースの回　総支配人の素顔と20年のレスラー人生", lead: "クリス・ヴァン・ヴリートの番組に出た約59分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Adam Pearce"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext--9x_6UuFha0").map((x) => [x.t, x.b, x.sp])), open: ["宣伝や雑談、スポーツ談義の一部は省いた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=-9x_6UuFha0"]] });
