  if (!PROFILES["Giulia"]) PROFILES["Giulia"] = { lead: "ロンドン生まれで、母は日本人、父はイタリア人。多様な環境で育った素顔と、女子プロレスを大きくしたいという熱い思いを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Giulia"]], moves: [], facts: [] };
  if (PROFILES["Giulia"]._weak) { PROFILES["Giulia"].lead = "ロンドン生まれで、母は日本人、父はイタリア人。多様な環境で育った素顔と、女子プロレスを大きくしたいという熱い思いを語る。"; delete PROFILES["Giulia"]._weak; }
  PROFILES["Giulia"].facts.push(...[{"cat": "家族", "t": "ロンドン生まれで1歳のころ日本へ", "b": "ジュリアはイギリスのロンドンで生まれたという。1歳ごろに日本へ戻り、その後はずっと日本で暮らしてきたと話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（0:02〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=2s"]]}, {"cat": "暮らし", "t": "英語は猛勉強中で、映画で理解を深める", "b": "ロンドン生まれでも英語が堪能なわけではなく、日本語とイタリア語で育ったという。いまは英語を猛勉強中で、映画をゆっくり止めながら見て理解を深めていると話す。以前よりかなり分かるようになったそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（0:47〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=47s"]]}, {"cat": "リングに来るまで", "t": "「学校には行っておくべき」と強く勧める", "b": "学校に行かず女子プロレスをやりたいという若い子もいると聞くが、ジュリアは「学校には行っておくべき、後悔するから」と強く言うという。自分が学校でちゃんと勉強しておけばよかったと思っているそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=94s"]]}, {"cat": "家族", "t": "母は日本人、父はイタリア人", "b": "母が日本人、父がイタリア人だという。実家はイタリアンレストランを営んでいると話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=94s"]]}, {"cat": "家族", "t": "周りに外国人や格闘家が多い環境で育った", "b": "小さいころから周りには外国人や格闘技の関係者が多く、人とは少し違う人生を生まれたときから送っていたと思うと話す。詳しくは自伝に書いたそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=94s"]]}, {"cat": "リングの話", "t": "旗揚げ戦は一生の宝物になった", "b": "団体の旗揚げ戦は、人生で一度経験できるかどうかの場だったという。そこに至るまで何か月も辛く大変なことがあったが、会場にいた選手、お客さん、スタッフ全員が大切な宝物だと感じたと話す。大変だった分、楽しさや幸せがより厚くなったそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（2:20〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=140s"]]}, {"cat": "体のこと", "t": "けがで試合ができず、悔しさを抱えた日々", "b": "けがをしたとき、なぜこんな目にと悔しさを忘れた日は一日もなかったという。毎晩その気持ちのまま布団に入り、興行に行っても試合はできなかったそうだ。それでも「神様がそうしているのだ」と思うことにして、できることを精一杯やったと話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=190s"]]}, {"cat": "リングの話", "t": "団体での負けが、挑戦への原動力になっている", "b": "自分はこの団体に来て、旗揚げ戦で負け、その後もまた負けたという。その悔しさがモチベーションになっていて、これからどんな戦いが待つのか楽しみにしていると話す。できるだけ多くの選手と戦いたいそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（4:43〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=283s"]]}, {"cat": "リングの話", "t": "桜井との対戦はけじめ、と語る", "b": "桜井に「こっちに来いよ」と声をかけたのが自分で、すべての始まりだったと振り返る。いまは自分がいなくても一人前になったと感じるが、けじめとして桜井と戦いたいという。団体の中心になってほしいから、一対一で戦って得るものがあるはずだと話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=336s"]]}, {"cat": "リングの話", "t": "残り時間が少ないからこそ、すべてがけじめ", "b": "日本にいられる時間は少ないが、だからこそ直感でこの団体に来ないと心に引っかかったまま日本を離れることになると感じたという。日本に対してのすべてがけじめだと話す。教えられることはすべて伝えたいと考えている。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（6:26〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=386s"]]}, {"cat": "リングの話", "t": "きつい言葉も、誰かに響けばいいと考えている", "b": "後輩にはきつい言葉も遠慮なく言うが、それで何かを感じる人がいればいいと思っているという。与えられた枠の中だけでは新しいものは生まれないと話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（7:17〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=437s"]]}, {"cat": "リングに来るまで", "t": "女子プロレスに出会い、その世界に引き込まれた", "b": "この世界と出会って「こんなにすごい世界があるのか」と引き込まれたという。知り合いに見せるとたいていハマってくれるので、日本中に女子プロレスを届けたいと話す。きっかけが今は少ないと感じているそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（7:17〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=437s"]]}, {"cat": "リングの話", "t": "自分は小さな存在、だから大きくなるしかない", "b": "自分には会社を動かす力もなく、ちっぽけな存在だと気づかされたという。それなら誰よりも大きな存在になるしかないと本気で思い、大きくなって日本に戻ってきて女子プロレスを変えたいと話す。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=487s"]]}, {"cat": "リングに来るまで", "t": "自伝は生まれた時から包み隠さず書いた", "b": "初の自伝は生まれたときから現在までを、デビュー前のことも含めて包み隠さず書いたという。幼少期の話はもともと書くつもりがなかったが、書くうちにすべてが今の自分につながっていると気づき、さらけ出すことにしたそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=487s"]]}, {"cat": "リングに来るまで", "t": "お金の面に驚き、引退を考えたこともあった", "b": "女子プロレスの世界に入って驚いたことのひとつがお金の面で、生活がかかっていたので、一度は本当に引退を考えたという。それでも続けてよかったと今は思っていると話す。内部をもっと改善すれば、憧れて夢を持って入ってくる世界になると信じているそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（8:58〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=538s"]]}, {"cat": "暮らし", "t": "自伝は8月23日発売、全部自分で書いた", "b": "自伝は8月23日の発売で、プロレスを知らない人にも面白く読んでもらえると思うという。すべて自分で書いたと話す。お渡し会のイベントも予定されているそうだ。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（9:47〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=587s"]]}, {"cat": "リングの話", "t": "デビュー7年、日本の女子プロレスを変えてみせる", "b": "デビューからもうすぐ7年になり、色々なことがあったと振り返る。どこにいても団体のことを思い、女子プロレスがもっと盛り上がるのが夢だと話す。日本の女子プロレス界を必ず変えてみせると語る。", "sp": "ジュリア", "d": "2024-08-18", "how": "MARIGOLD（公式）の番組で（字幕を全文確認）", "art": "ext-RxbsO9q74ME", "src": [["番組のYouTube（10:33〜）", "https://www.youtube.com/watch?v=RxbsO9q74ME&t=633s"]]}]);
  ARTICLES.push({ id: "ext-RxbsO9q74ME", d: "2024-08-18", show: "ext", who: ["Giulia"], t: "ジュリアの回　生い立ちと自伝、日本への思い", lead: "MARIGOLD（公式）の番組に出た約12分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Giulia"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-RxbsO9q74ME").map((x) => [x.t, x.b, x.sp])), open: ["字幕は日本語の自動字幕で、一部の人名（対戦を語った別の選手など）が崩れていたため、確信が持てない名前は載せていない。", "「桜井」は字幕の表記のままで、フルネームは確認できなかった。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=RxbsO9q74ME"]] });
  if (!ROSTER.find((r) => r[1] === "Otis")) ROSTER.push(["オーティス", "Otis", "lg", "元マネー・イン・ザ・バンク王者", "", "", ""]);
  if (!PROFILES["Otis"]) PROFILES["Otis"] = { lead: "大柄な体に似合わず身のこなしは軽く、いつも陽気なオーティス。アマレス、ホラー映画、ロック好きという素顔と、仲間思いの人柄が伝わる回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Otis"]], moves: [], facts: [] };
  if (PROFILES["Otis"]._weak) { PROFILES["Otis"].lead = "大柄な体に似合わず身のこなしは軽く、いつも陽気なオーティス。アマレス、ホラー映画、ロック好きという素顔と、仲間思いの人柄が伝わる回。"; delete PROFILES["Otis"]._weak; }
  PROFILES["Otis"].facts.push(...[{"cat": "暮らし", "t": "会場では室温と椅子が気になる", "b": "番組収録では室温を低めにし、丈夫な椅子を用意してほしいと頼んだという。海外のケータリングで仲間に椅子を勧められて断ったことがあり、座る前に必ず強度を試すと話す。体が大きい人ならではの習慣だそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=45s"]]}, {"cat": "体のこと", "t": "体重は約360ポンド、かつては420ポンド", "b": "いまの体重は約360ポンド（約163kg）だと話す。以前は420ポンドあったという。栄養士と相談しながら食事を管理しており、1日4000キロカロリーほどとるそうだ。マヨネーズの代わりにギリシャヨーグルトを使うのが気に入っているという。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=94s"]]}, {"cat": "体のこと", "t": "小3で思春期、生まれつき大きな体", "b": "生まれたときから体は大きく、きょうだいの中でも兄のフィルは9ポンド台だったという。小学3年で思春期に入り、目の下のくまのせいで夜ごと治療を受けたと話す。自分は「レスラーになるために生まれた」体だったと冗談めかして語っている。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=190s"]]}, {"cat": "リングに来るまで", "t": "小1でアマレスを始めたきっかけ", "b": "ロイヤルランブル97を見て、覆面レスラーの兄弟を子どもだと思い込み、母にレスリングをやりたいと頼んだという。連れて行かれたのはアマチュアレスリングの教室で、母に「これが本物のレスリングだ」と言われたそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=190s"]]}, {"cat": "リングに来るまで", "t": "アマレスで伸び悩み、気持ちが離れた", "b": "大会で2位や3位が続き、アマレスへの熱が冷めていったという。そんなとき、ゲーブルがNXTに入るのを見て、自分も挑戦しようと思ったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（3:56〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=236s"]]}, {"cat": "リングに来るまで", "t": "大学は単位が足りず、プロの道へ", "b": "スカウトのジェラルド・ブリスコに毎年声をかけられていたという。大学では代数が通らず、卒業まであと6単位だったそうだ。そこで気持ちはレスリング一本に切り替わったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（4:43〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=283s"]]}, {"cat": "リングに来るまで", "t": "デンバーで半額の月謝で下積み", "b": "デンバーのインディー団体の人物に頼み、月謝を半額にしてもらったという。片道3時間かけて通い、ときには相手のソファに泊まったそうだ。練習を始めて3か月ほどで育成施設のトライアウトを受け、ロープワークの軽さで周囲を驚かせたと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（6:19〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=379s"]]}, {"cat": "暮らし", "t": "自宅は一年中ハロウィン仕様", "b": "自宅を年中ハロウィンの飾りでいっぱいにしているという。そのせいで近所に「あのハロウィンの家の人」と知られてしまったと笑っている。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（8:42〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=522s"]]}, {"cat": "リングの話", "t": "リングネーム「オーティス」の由来", "b": "候補は「ドーザー」「テリー・デュークス」「オーティス」の3つだったという。リング上でトリプルHが紙を見せ、いずれドーザーと呼ぶと言われたが、結局オーティスに定着したそうだ。ドーザーはほかの選手からのあだ名として今も残っていると話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（11:07〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=667s"]]}, {"cat": "リングの話", "t": "タッカーとの「ヘヴィ・マシナリー」結成", "b": "二人とも大柄なので、ヘヴィ・マシナリーという名前がぴったりだと話す。ジムで体重を競い合う仲だったという。失恋したときタッカーに励まされたが、その言い方がそっけなく、今では笑い話になっているそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（12:47〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=767s"]]}, {"cat": "好きなもの", "t": "遠征にはバイソン肉とパンを持参", "b": "遠征には、バイソンのパティを20枚ほど袋に入れ、パンも服の間に挟んで持っていくという。ジムの電子レンジで温めて食べるそうだ。朝食は新鮮な卵が欠かせないと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（14:27〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=867s"]]}, {"cat": "好きなもの", "t": "音楽は80年代ロックからジャズまで", "b": "普段は80年代のロックをよく聴き、最近はソウルやジャズ、アウトロー・カントリーにも興味があるという。ビートルズやAC/DCも好きだそうだ。姉の部屋ではニルヴァーナやマリリン・マンソンが流れていたと話す。ホットソースも数か月ごとに替えるタイプで、今はチョルーラだという。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（16:46〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1006s"]]}, {"cat": "好きなもの", "t": "ホラー映画とレスリングは客層が近い", "b": "ホラーのイベントでは歓迎されるので、ファン層はレスリングと重なると話す。好きなホラーシリーズは『13日の金曜日』で、レンタル店で毎週末借りていた思い出があるという。単発で一番好きなのは『悪魔のいけにえ』だそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（18:23〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1103s"]]}, {"cat": "家族", "t": "父は旧ユーゴ出身、母はウェイトレス", "b": "父は旧ユーゴスラビア出身で、顔立ちがロバート・デ・ニーロによく似ているという。母はウェイトレスとして働きながら、家でビートルズの曲を歌っていたそうだ。年上のきょうだいが見る映画を何でも一緒に見て育ったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（20:01〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1201s"]]}, {"cat": "リングに来るまで", "t": "子どものころはWCWとサンダーに夢中", "b": "最初の記憶は、父が煮込み料理の準備をする横で見たサンダーだという。レイヴンの姿が忘れられず、WCWのアティテュード路線を見て育ったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（20:49〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1249s"]]}, {"cat": "リングに来るまで", "t": "憧れのスコッティ・2・ホッティとの出会い", "b": "インディー興行の会場で、のちにNXTでコーチを務めるスコッティ・2・ホッティと偶然出会ったという。2009年に全米大会で優勝した直後で、ステージでワームを踊った話をしたそうだ。子どものころからの憧れだったと語っている。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（21:35〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1295s"]]}, {"cat": "リングに来るまで", "t": "ワームを踊り始めたのは小5のダンスパーティー", "b": "小学5年の「ソックホップ」で、ネリーの曲に合わせてワームをしたのが始まりだという。会場が沸いたのが、観客の反応にハマるきっかけだったと話す。家では床が響くので練習できなかったそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（23:59〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1439s"]]}, {"cat": "家族", "t": "家族は最初レスラーを反対していた", "b": "家族は最初、医者になってほしいと思っていて、この道には反対だったという。いまは家族もレスリングが大好きになったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（25:33〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1533s"]]}, {"cat": "好きなもの", "t": "リキシとランディ・サベージに憧れて", "b": "同じ大柄なリキシの動きに惹かれたという。400ポンド超なのに軽やかなところが好きだそうだ。ランディ・サベージも幼いころから大好きで、古いビデオで年齢を重ねた試合運びを見直して感心したと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（25:33〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=1533s"]]}, {"cat": "リングの話", "t": "マンディ・ローズとの恋愛路線のきっかけ", "b": "この路線は、マンディ・ローズが上層部に話を通したことで実現したという。SNSでふざけて彼女にコメントしていたのが発端だそうだ。毎回生放送の撮影だったので、ケーキを持つ場面などは冷や汗ものだったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（34:29〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2069s"]]}, {"cat": "リングの話", "t": "初の単独戦はドルフ・ジグラーと", "b": "大舞台の初シングルはドルフ・ジグラー相手の試合で、観客がいなかったことを惜しんでいる。ドルフへの敬意があるぶん、もっと良い環境でやりたかったと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（36:01〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2161s"]]}, {"cat": "リングの話", "t": "ロイヤルランブルでマンディを助けた場面", "b": "リング下に隠れて、マンディ・ローズを助ける場面を担当したという。靴で正体がばれそうになり、冷や冷やしたそうだ。リング下で出番を待つ間は、モニターで試合を見ていたと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（37:36〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2256s"]]}, {"cat": "リングの話", "t": "マネー・イン・ザ・バンクはまさかの勝利", "b": "勝つとは思っていなかったと話す。撮影は屋上で長時間待たされ、高所が苦手なのに梯子を登るはめになったという。ジェイミー・ノーブルに促されて、ポーズの撮影をしたそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（38:23〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2303s"]]}, {"cat": "リングの話", "t": "ゲーブルに堪忍袋の緒が切れた場面", "b": "ついにゲーブルに怒りを爆発させた場面は、舞台裏の入口で「めちゃくちゃ興奮している」と言ったほど印象的だったという。ゲーブルとは打ち合わせが少なくても通じ合えると話す。息ができなくなるほど入り込んでいたそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（41:33〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2493s"]]}, {"cat": "リングの話", "t": "NXT時代の大歓声", "b": "NXTで6人タッグをやったとき、ワームの前で観客が沸いたのが忘れられないという。その日は興奮で眠れなかったそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（43:08〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2588s"]]}, {"cat": "暮らし", "t": "試合後は眠れず、ホラーを見て過ごす", "b": "試合のあとは眠れず、ホテルで過ごすことが多いという。昔は次の街で飲み歩いていたが、最近は落ち着いて、ホラー映画を見るそうだ。好きな酒はジョニー・ウォーカーの赤ラベルとビールだと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（43:55〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2635s"]]}, {"cat": "暮らし", "t": "契約後の最初の買い物は大きなテレビ", "b": "WWEと契約してまず買ったのは大型テレビで、ベッドは後回しだったという。テレビ台がなく、トランプの束を台にしたと笑っている。ベッドは長いこと買わず、ソファで寝ていたそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（44:44〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2684s"]]}, {"cat": "暮らし", "t": "オーランドの暮らしは暑くて遅い", "b": "育成施設のあるフロリダに6年ほど暮らしたが、暑さとのんびりした空気が合わなかったという。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（45:30〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2730s"]]}, {"cat": "暮らし", "t": "車は同じ乗用車を長く乗り続ける", "b": "いま乗っているのはフォード・フュージョンだという。シートのエアコンが気に入って買ったそうだ。何年も同じ車に乗っており、タイヤが取れるまで乗るつもりだと話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（47:09〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2829s"]]}, {"cat": "好きなもの", "t": "ジョン・キャンディと『大災難P.T.A.』が好き", "b": "笑いの好みはクリス・ファーリーよりジョン・キャンディに近いという。母がよく見ていた『大災難P.T.A.』は特別な一本だそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（47:57〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2877s"]]}, {"cat": "好きなもの", "t": "一番好きな映画は『ワンス・アポン・ア・タイム・イン・ハリウッド』", "b": "映画の細かい配役や日付を覚えるのが得意で、昨日のことより映画の記憶のほうが鮮明だと話す。一番好きな映画はこの作品で、登場人物どうしの仲の良さが仲間を思わせるからだという。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（48:43〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=2923s"]]}, {"cat": "リングの話", "t": "目標はレッスルマニアでの単独戦", "b": "レッスルマニアでのシングル戦と、ゲーブルとの大一番が目標だという。王座も望むが、好きなことを続けられること自体が幸せだと話す。ずっと戦いたかった憧れの選手がいるが、もう叶わない夢だと話している。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（51:00〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=3060s"]]}, {"cat": "暮らし", "t": "移動では仲間たちが同乗を取り合う", "b": "遠征では同じ車に乗りたがる仲間が多いという。後部座席にリコシェと二人で座ると、肩が触れるほど窮屈だったと笑っている。エアコンは全開が好みだそうだ。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（53:24〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=3204s"]]}, {"cat": "リングに来るまで", "t": "五輪代表選考の合宿にも参加", "b": "2012年に五輪代表選考の合宿に参加したが、周囲の実力に圧倒されたという。その後、精神的に燃え尽きて競技をやめたそうだ。最重量級に合わせるため2年だけ減量していたとも話す。", "sp": "オーティス", "d": "2024-09-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Sx0pv-xYVIk", "src": [["番組のYouTube（55:05〜）", "https://www.youtube.com/watch?v=Sx0pv-xYVIk&t=3305s"]]}]);
