  if (PROFILES["Undertaker"]._weak) { PROFILES["Undertaker"].lead = "ヒューストンで育った少年が、下積みや「誰も金を払って見ない」という酷評を越えて葬儀屋になるまでを語る。役を生き抜く覚悟と、引き際への本音も明かす。"; delete PROFILES["Undertaker"]._weak; }
  PROFILES["Undertaker"].facts.push(...[{"cat": "体のこと", "t": "30年超のキャリアと今の体調", "b": "長いキャリアを経た今の体調は「そこそこ良い」と話す。トレーニングと食事を見直し、何でも知っているつもりの考えを捨てて頭を柔らかくしたのが良かったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（0:52〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=52s"]]}, {"cat": "リングに来るまで", "t": "ヒューストンのプロレス少年", "b": "ヒューストンで育ち、地元の会場に通う熱心なファンだったという。友だちと一週間かけて気合を入れ、悪役の乱入に逃げ回ったことや、子どものころに巨人アンドレの手を握って圧倒されたことを今も鮮明に覚えている。その後はほかのスポーツに打ち込み、やがてプロレスへ戻ってきたと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（2:33〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=153s"]]}, {"cat": "リングに来るまで", "t": "高い月謝を払った最初の道場", "b": "1986年ごろ、有名な悪役レスラーのもとで練習を始めた。月謝を払って集まったものの、リングはなく、行われたのは前庭での関節技の稽古だけだったという。夏はバスケットボールのリーグ戦に出ながら通ったが、参加者は週ごとに減り、ある日訪ねると本人は別の地区へ移ったあとだった。残された2匹のロットワイラー犬だけは引き取ったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（4:09〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=249s"]]}, {"cat": "好きなもの", "t": "今も続く大の犬好き", "b": "最初の道場に置き去りにされた犬を引き取ったのが、犬との縁の始まりだという。当時はお金もなかったが、よい飼い主を探して譲ったと話す。今も大の犬好きだと認めている。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（7:27〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=447s"]]}, {"cat": "リングに来るまで", "t": "メンフィスで味わった洗礼", "b": "南部の地方団体では、この世界の厳しさを一から学んだという。最初の遠征では屈辱的な扱いにも耐えたそうだ。自分と同じく経験の浅い大型選手とタッグを組まされたとも話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（8:18〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=498s"]]}, {"cat": "リングに来るまで", "t": "長身コンビで全国放送の団体へ", "b": "同じ身長約2メートルの相棒ダニーとのコンビで、大手団体に上がるチャンスをつかんだ。大きな興行で悪役の人気チームを相棒が椅子で打ちのめしたとき、自分は報復を覚悟して控室で身構えていたという。ところが相手は笑顔で礼を言いに来て、拍子抜けしたそうだ。駆け出しの自分にはまだ分からない世界の裏側を知った出来事だったと振り返る。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（15:55〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=955s"]]}, {"cat": "リングに来るまで", "t": "契約更改で突きつけられた酷評", "b": "契約の更新時に昇給を期待して重役たちと会ったところ、「運動能力は高いが、誰も金を払ってあなたの試合は見ない」と告げられたという。目を見て言い切られ、誇りを傷つけられて、そこで見切りをつけたと話す。今の自分を思えば皮肉な言葉だと語る。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（19:57〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=1197s"]]}, {"cat": "リングに来るまで", "t": "破れたズボンで臨んだ大一番の面談", "b": "後に所属する団体の社長宅で面談する前夜、買ったばかりのズボンの尻が破れてしまったという。ナイトクラブで一晩座り通し、明け方に借りた針と糸で自分で縫って面談に向かった。「隠し芸は?」と聞かれて「シャワーで歌う」と口走り、後悔したと話す。その日は「今は用意できる役がない」と言われて終わったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（21:34〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=1294s"]]}, {"cat": "リングに来るまで", "t": "エッグマンになると思い込んだ日々", "b": "連絡を待つ間、髪を伸ばして新しい姿を考えていたという。番組に巨大な卵が登場したとき、自分がその卵から出てくる「エッグマン」にされると思い込み、腹が痛くなるほどだったと話す。ある日電話が鳴り「アンダーテイカーか」と聞かれ、エッグマンよりずっと良いと思って即答した。翌日に来るよう言われ、そこから運命が動いたそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=1638s"]]}, {"cat": "リングの話", "t": "黒い世界に惹かれ、役を理解する", "b": "昔から暗い雰囲気のものに興味があり、新しい役にすぐ引き込まれたという。西部劇で決闘のあとに棺の寸法を測る葬儀屋が登場する場面を思い浮かべて、役のイメージをつかんだ。ただ、運動能力を生かした動きは役に合わないと気づくまでには時間がかかったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（29:42〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=1782s"]]}, {"cat": "リングの話", "t": "動きを遅くして怖さを出す", "b": "忍び寄る「ブギーマン」を目指し、マイケル・マイヤーズやジェイソンのように、走らなくても必ず現れる存在をイメージしたという。高く跳びたい気持ちを抑え、ゆっくり動いて油断させ、一瞬だけ素早く動く形を身につけた。自分のエゴを抑えて「少ないほうが効果的」と学んだことが、30年続いた理由だと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（32:01〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=1921s"]]}, {"cat": "リングの話", "t": "私生活でも役を崩さなかった", "b": "最初の5、6年は、街でも黒い服を着て口数を少なくし、役のまま過ごしたという。クローゼットには黒以外の服がなかったそうだ。テレビで見せる姿と違う自分を、ファンに見せたくなかったと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（35:22〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=2122s"]]}, {"cat": "リングの話", "t": "憧れの名選手を倒した初期の葛藤", "b": "年間でも大きな団体戦で、憧れのレジェンドをロープ越しに投げ捨てる役目を任されたという。本人は「自分なんかが」と思いつつ、会場が静まり返って何かが起きていると感じていた。試合後、まずその憧れの人に謝意を伝えに行ったそうだ。周囲の先輩たちには歓迎されなかったが、これで自分の道が少し見えたと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（36:10〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=2170s"]]}, {"cat": "リングの話", "t": "役作りの師はジェイク・ロバーツ", "b": "役を作るうえで一番頼りにしたのは、独特の発想を持つジェイク・ザ・スネーク・ロバーツだったという。音楽や聖書の言葉まで幅広く参考にするよう教わり、「音楽が鳴ったらその人物になる」という考えを自分は一歩進めた。大声で叫ぶタイプではなく、低く静かに語る話し方を選んだのも、聞き手の耳を引きつけるためだと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（41:06〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=2466s"]]}, {"cat": "リングの話", "t": "アメリカン・バッドアスへの転身", "b": "飽きられる前に変化を入れるのが得意で、観客が先に飽きを感じ始めると考えているという。過激な時代の内容に合わず、役に手枷をはめられた状態だったため、キャラクターを変えたと話す。それでも元の要素を少しずつ残したので、のちに元の姿へ戻したときも不自然にならなかったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（48:14〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=2894s"]]}, {"cat": "体のこと", "t": "長い離脱を経たバイクでの復帰", "b": "股関節付近の大けがで離れたあと、復帰の3週間ほど前に胸の筋肉まで断裂し、8か月から9か月ほど画面から消えていたという。そのうえ新しい役柄で、バイクに乗って大会に登場するという不安な復帰だった。うまくいかなければ全てが終わると感じたが、時期に合った選択だったと振り返る。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（50:38〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=3038s"]]}, {"cat": "暮らし", "t": "ツアー先で飲み明かした夜", "b": "若いころは、仕事を最優先にしつつ、仲間と酒を飲みながら語り合う時間も大好きだったという。17日間のツアー終盤、1日だけ休むつもりで酒場に顔を出したところ、巡業中の音楽グループに「飲めるらしいな」と挑発され、閉店まで付き合ってしまった。翌朝の集合には何事もなかったように現れたそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（53:08〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=3188s"]]}, {"cat": "リングの話", "t": "苦しい時期も会社を離れなかった理由", "b": "ライバル団体に視聴率で負け続けた時期、挑戦的な内容に手を出せない状況にもどかしさを感じていたという。それでも、最初にチャンスをくれた社長への恩を忘れず、船が沈むなら一緒に沈む覚悟だったと話す。あの時代の苦しさは、その後に収入が大きく伸びたときのため、心に刻んでいるそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:01:08〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=3668s"]]}, {"cat": "リングの話", "t": "4年続いたライバルたちとの物語", "b": "ショーン・マイケルズとの大一番の抗争は、トリプルHとの対決へと続く、4年がかりの物語だったという。ショーンとは別の方向で勝負するしかないと考え、トリプルHとの試合はあえて荒々しく、重い内容にした。4試合とも物語が筋になっていたことを誇りにしている。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:04:12〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=3852s"]]}, {"cat": "体のこと", "t": "試合後の高揚は1時間だけ", "b": "大舞台を終えたあとの充実感は、長くても1時間ほどだという。その後、着替えようと立ち上がる段階で、体の痛みが現実として戻ってくるそうだ。それは今も変わらず、試合後の数週間は痛みと付き合うことになると話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:07:18〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4038s"]]}, {"cat": "体のこと", "t": "最大の不安は自分のパロディになること", "b": "今の試合は内容よりも、期待に応える水準まで自分を仕上げられるかという個人的な挑戦だと話す。残された時間は少なく、最大の不安は「自分のパロディ」になることだという。長居しすぎないと決めていたのに、そうなった日もあると認めている。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:08:09〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4089s"]]}, {"cat": "体のこと", "t": "連勝記録の終わった夜の記憶喪失", "b": "連勝が止まった大会の夜、試合開始から5分ほどで脳しんとうを起こしたという。当日の記憶は午後3時半ごろ、会場で妻と話したところで途切れ、次に覚えているのは午前4時半ごろの病院だった。名前も誕生日も居場所も分からず、覚えていたのは妻の名前だけだったそうだ。妻に居場所を電話で尋ねると、答えを教えてもらえなかったと笑って話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:10:31〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4231s"]]}, {"cat": "体のこと", "t": "自信を揺らした脳しんとう", "b": "試合を何度も見返したが、どこで頭を打ったのか特定できず、それが自信を大きく揺さぶったという。ボクサーのように準備を重ね、頂点を合わせすぎて、体が衝撃に耐えられなかったのではと分析している。医師には「プラグを抜かれた電気スタンドのように、記憶を作る働きが止まった」と説明された。最後の試合を覚えていないまま終わるのは嫌だと思い、気持ちが固まったそうだ。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:13:51〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4431s"]]}, {"cat": "体のこと", "t": "考えすぎると体が壊れる", "b": "「ここで技をかけたら膝が壊れるのでは」と考え始めると、動きに流れがなくなり、一番危ないと話す。恐れを抱えたままでは試合はできないし、相手は命を預けてくれているのだから、澄んだ頭でやるべきことに集中すべきだという。自分の終わり方は自分で決めたいと語る。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:18:37〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4717s"]]}, {"cat": "家族", "t": "引退宣言は15回、妻は呆れ顔", "b": "サウジアラビアでの試合が悪い夜になり、それを最後の記憶にされたくないという思いで現役を続けてきたという。冗談まじりに、これまで15回は引退したと話す。妻のミシェルに「これで終わりだ」と告げるたび、「また11月になれば練習を始めるくせに」と目を丸くされるそうだ。引退の時期は、尊敬する人から言われたら聞くが、他人に決められるのは嫌だという。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:20:10〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4810s"]]}, {"cat": "リングの話", "t": "「誰も金を払わない」と言われた男の自負", "b": "30年以上、毎日好きなことを仕事にできたことを幸運だと感じ、手術の痛みも含めて全て報われたと話す。準備と運が重なってチャンスが生まれたという考えだ。10年後にも、自分のやったことを誰かが覚えていてくれたらうれしいと語る。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:21:51〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=4911s"]]}, {"cat": "リングの話", "t": "役を崩さない男が笑ってしまった夜", "b": "30年間で役を崩したのは片手で数えるほどだという。中東の遠征で、観客がまばらな大きなスタジアムの試合中、数人が肩を組む「数珠つなぎのヘッドロック」の乱戦になり、隣り合ったコーナーで目が合って吹き出してしまったそうだ。隣のスティーブ・オースティンも同時に笑い出し、少数の観客しかいなくて助かったと話す。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-tPwERXiuj6o", "src": [["番組のYouTube（1:27:24〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=5244s"]]}]);
