  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "憧れのアメリカン・ドリーム", "b": "ダスティ・ローデスは子どものころから憧れていた存在で、デビュー間もない時期に彼を投げ飛ばした後、真っ先に礼を言いに行ったと、アンダーテイカーが話している。フレアー、ローデス、スティームボートらは今も別格だという。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、アンダーテイカーの話（字幕を全文確認）", "src": [["番組のYouTube（39:22〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=2362s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "試合の名手として評価", "b": "ショーン・マイケルズは「あの男は試合がうまい」と認めざるを得ない存在で、後のトリプルHとの対決では同じ方向では勝負できないと考えたと、アンダーテイカーが話している。", "sp": "アンダーテイカー", "d": "2024-09-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、アンダーテイカーの話（字幕を全文確認）", "src": [["番組のYouTube（1:04:57〜）", "https://www.youtube.com/watch?v=tPwERXiuj6o&t=3897s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-tPwERXiuj6o", d: "2024-09-27", show: "ext", who: ["Undertaker"], t: "アンダーテイカーの回　下積みから不死身の葬儀屋、そして引き際まで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約98分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Undertaker"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-tPwERXiuj6o").map((x) => [x.t, x.b, x.sp])), open: ["聞き手のスティーブ・オースティン自身の体験談（初期の遠征、電話の依頼、機内の騒動など）は、本人の話ではないため載せていない。", "字幕は自動生成で乱れた箇所が多く、固有名詞が不確かな部分（初期の相棒、団体の重役の名前など）は名前を伏せるか言い換えた。", "ツアー中の酒や飲み会、仲間との裏話、2001年の機内の件など、聞き手との共同の思い出話は話者の切り分けが難しく、一部を省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=tPwERXiuj6o"]] });
  if (!ROSTER.find((r) => r[1] === "Dusty Rhodes")) ROSTER.push(["ダスティ・ローデス", "Dusty Rhodes", "lg", "", "", "", ""]);
  if (!PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"] = { lead: "1999年、2時間にわたって業界の裏側を語ったダスティ・ローデス。名前の由来から、父の死と長男の誕生が重なった日、父親としての後悔まで。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dusty%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Dusty Rhodes"].lead === "1999年、2時間にわたって業界の裏側を語ったダスティ・ローデス。名前の由来から、父の死と長男の誕生が重なった日、父親としての後悔まで。") PROFILES["Dusty Rhodes"]._weak = 1;
  PROFILES["Dusty Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "大学を転々とし、西テキサス州立大へ", "b": "野球とフットボールの奨学金で入った大学を問題を起こして退学になり、別の大学でも授業についていけなかったと、ローデスは笑う。最後に入った西テキサス州立大学では、ファンクス、スタン・ハンセン、ブルーザー・ブロディら多くの未来のレスラーと一緒だったという。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=50s"]]}, {"cat": "リングに来るまで", "t": "7、8歳で裏庭の「興行主」", "b": "7、8歳の頃から裏庭にリングを作って試合を組み、いつも自分が勝つように「ブッキング」していたと、ローデスは話す。子どもの頃からプロレスという世界に夢中だったという。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（3:59〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=239s"]]}, {"cat": "家族", "t": "父が亡くなった日に長男が生まれた", "b": "テキサスで駆け出しだった頃、父が亡くなった同じ日に長男ダスティンが生まれたと、ローデスは話す。葬式代もなかったとき、興行主フリッツ・フォン・エリックが「仕事に戻れ」と言って280ドルを渡してくれたという。数年後に返しに行ったが、受け取らなかったそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（8:11〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=491s"]]}, {"cat": "リングに来るまで", "t": "初めての師はジョー・ブランチャード", "b": "ボストンで数試合して27ドルを手にテキサスへ戻り、ジョー・ブランチャードに一から教わったと、ローデスは話す。試合の組み立てや話し方だけでなく、リングの設営やポップコーン売りまで教えてくれたという。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（9:38〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=578s"]]}, {"cat": "リングの話", "t": "「スターケード」の名前は車の中で生まれた", "b": "11月の大会の名前を考えるため、バリー・ウィンダムの運転する車で名前を書き出していたと、ローデスは話す。帰り道にビールを飲みながら「世紀の一戦」をもじって「スターケード」を思いついたという。ウォーゲームズやブルロープ戦も、車での移動中に考えたそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（36:25〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=2185s"]]}, {"cat": "リングの話", "t": "水玉模様の衣装は気にしなかった", "b": "WWFで水玉模様の衣装を着たのは、ビンス・マクマホンに「やるか」と聞かれて引き受けたからで、屈辱とは思わなかったと、ローデスは話す。フロリダ時代から水玉のヘッドバンドや帽子を身につけていたという。それを観客に受け入れさせてみせたそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:17:15〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=4635s"]]}, {"cat": "家族", "t": "長男ダスティンに寂しい思いをさせた", "b": "年中巡業に出ていて、長男ダスティンや娘の子ども時代をほとんど一緒に過ごせなかったと、ローデスは話す。離婚もし、お金を送れば十分だと思っていたが、それは間違いだったという。今は関係を修復し、次男コーディとの時間は逃したくないそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:22:01〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=4921s"]]}, {"cat": "家族", "t": "ゴールダストという役への評価", "b": "長男ダスティンがゴールダストという前例のない役を引き受け、成功させたことを高く評価していると、ローデスは話す。もっと突き詰めれば世界王者にもなれたはずだという。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:22:50〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=4970s"]]}, {"cat": "リングの話", "t": "「ダスティ・ローデス」の名前の由来", "b": "子どもの頃から「ダスティ」と呼ばれていて、野球好きの父はニューヨーク・ジャイアンツのダスティ・ローズという選手が大好きだったと、ローデスは話す。テキサスの団体の関係者が「ダスティ・ローデスと名乗れ」と言ってくれたという。「アメリカン・ドリーム」は1974年に自分の頭から生まれたそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:38:56〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=5936s"]]}, {"cat": "暮らし", "t": "子どもたちへの思いと、次の夢", "b": "長女はダラス・カウボーイズのチアリーダーだと、ローデスは話す。子どもと関わるのが好きで、レスリング学校や、素人が試合を体験できるファンタジーキャンプを開きたいという。脚本を2本書いていて、映画の監督や主演もしてみたいそうだ。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:45:16〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=6316s"]]}, {"cat": "リングの話", "t": "日本には30回以上遠征", "b": "日本には37、8回行き、アントニオ猪木の団体で戦って、猪木とは個人的な友人になったと、ローデスは話す。ジャイアント馬場のことも大好きだったという。国を問わず名前を知られていることこそ「アメリカン・ドリーム」だ、と語っている。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で（字幕を全文確認）", "art": "ext-hJJU-LfXryk", "src": [["番組のYouTube（1:51:43〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=6703s"]]}]);
  if (PROFILES["Magnum TA"]) PROFILES["Magnum TA"].facts.push({"cat": "暮らし", "t": "マグナムTAは「選ばれし者」だった", "b": "マグナムTAは次の時代を担うはずの選手で、自分の一番の親友だったと、ローデスが話している。事故の後、自分の足で病院を出て、今は家庭を持ち事業も成功させていることを誰より尊敬しているという。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で、ダスティ・ローデスの話（字幕を全文確認）", "src": [["番組のYouTube（42:05〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=2525s"]], "by": "第三者の話"});
  if (PROFILES["Barry Windham"]) PROFILES["Barry Windham"].facts.push({"cat": "暮らし", "t": "バリー・ウィンダムは天性の才能", "b": "バリー・ウィンダムは、ダスティンを除けば見たことがないほどの天性の才能の持ち主で、自分の右腕だったと、ローデスが話している。", "sp": "ダスティ・ローデス", "d": "2024-10-06", "how": "RFビデオの番組（タイトル・マッチ・レスリング）で、ダスティ・ローデスの話（字幕を全文確認）", "src": [["番組のYouTube（45:59〜）", "https://www.youtube.com/watch?v=hJJU-LfXryk&t=2759s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-hJJU-LfXryk", d: "2024-10-06", show: "ext", who: ["Dusty Rhodes"], t: "ダスティ・ローデスの回　1999年の2時間インタビュー：名前の由来、スターケードの誕生、父としての後悔", lead: "RFビデオの番組（タイトル・マッチ・レスリング）に出た約114分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Dusty Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-hJJU-LfXryk").map((x) => [x.t, x.b, x.sp])), open: ["1999年の収録。他の選手や記者への批判の部分は載せていない。", "師エディ・グラハムの最期についての話は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=hJJU-LfXryk"]] });
  if (!ROSTER.find((r) => r[1] === "Bronson Reed")) ROSTER.push(["ブロンソン・リード", "Bronson Reed", "lg", "体格自慢の大型レスラー", "", "", ""]);
  if (!PROFILES["Bronson Reed"]) PROFILES["Bronson Reed"] = { lead: "オーストラリア出身で、娘の誕生が人生を変えたと話すブロンソン・リード。ゴジラや音楽、スニーカーが好きという素顔も語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bronson%20Reed"]], moves: [], facts: [] };
  if (PROFILES["Bronson Reed"]._weak) { PROFILES["Bronson Reed"].lead = "オーストラリア出身で、娘の誕生が人生を変えたと話すブロンソン・リード。ゴジラや音楽、スニーカーが好きという素顔も語った。"; delete PROFILES["Bronson Reed"]._weak; }
  PROFILES["Bronson Reed"].facts.push(...[{"cat": "家族", "t": "生後7か月の娘がいる父親", "b": "ブロンソン・リードには生後7か月近い娘がいるという。5か月のころから夜7時ごろ〜朝6時半ごろまで眠ってくれるそうだ。子どもが生まれて人生が良い方向に変わり、毎日が娘中心になったと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=50s"]]}, {"cat": "リングに来るまで", "t": "契約解除から約1年半で復帰", "b": "契約を解除されたとき、復帰まで3〜4年はかかると見込んでいたという。日本で数年活動する計画だったが、実際は16〜17か月で戻ることになったそうだ。昔からWWEの大ファンで、定期放送や大きな大会に出る夢が残っていたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=144s"]]}, {"cat": "リングに来るまで", "t": "日本風のプロレスへの強い憧れ", "b": "リードを育てたトレーナーは、日本の有名レスラーの下で学んだ人だったという。そのため日本風のプロレスに憧れが強く、WWEがだめなら日本へ行こうと考えていたそうだ。日本でも自分のスタイルが合い、残るか戻るかを悩んだと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=192s"]]}, {"cat": "リングの話", "t": "6連続の大技で一気に注目の的に", "b": "当初の予定はもっと少なかったが、展開しながら回数が増えたという。観客がブーイングから大合唱に変わる空気を感じたそうだ。上の人から語り継がれる場面になると言われたといい、自分の代名詞になることを願っていると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=287s"]]}, {"cat": "リングの話", "t": "「ビッグ」の呼び名は最高責任者の判断", "b": "復帰時に自分でいろいろな呼び名を提案したが、最も単純な「ビッグ」が採用されたという。当時の最高責任者の判断だったそうだ。分かりやすいぶん、見る人の頭に残りやすいと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（8:50〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=530s"]]}, {"cat": "暮らし", "t": "フロリダでは顔を覚えられている", "b": "フロリダでは買い物先でもよく気づかれるという。以前は「テレビの人」と言われたが、いまは「ビッグ・ブロンソン・リード」と呼ばれることが多いそうだ。呼び名が定着したことを実感していると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（9:38〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=578s"]]}, {"cat": "体のこと", "t": "体が大きく座席に収まらない", "b": "体が大きく、普通の飛行機の座席には収まらないという。契約交渉でファーストクラスでの移動を頼み、いまは肘掛けも使えて食事も出て快適だそうだ。育成時代には、大柄な選手と隣り合わせになり窮屈だったこともあると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=674s"]]}, {"cat": "リングに来るまで", "t": "インディー時代は長距離フライトで中央席", "b": "アメリカのインディー団体に呼ばれ、オーストラリアから14時間ほどかけて飛んだという。予算が少なく、真ん中の席になったこともあったそうだ。体が大きいので、隣の人に頼んで通路側や窓側を譲ってもらっていたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（12:01〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=721s"]]}, {"cat": "リングの話", "t": "車を使った場面は生放送の一発勝負", "b": "ブラウン・ストローマンとの車の場面は、リハーサルなしの一発撮りだったという。練習すると車が壊れてしまうためで、昼のうちに壁へ登って高さだけ確かめたそうだ。車に投げられた場面は、裏で首を痛めたのではと心配されたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（14:27〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=867s"]]}, {"cat": "体のこと", "t": "膝パッドと受け身で体を守る", "b": "高い所から飛ぶときは、いつも膝パッドを着けているという。インディー時代に蛙跳び式の技でけがをしてから、普通の形に変えたそうだ。車に投げられた場面でも、顎を引く受け身と首まわりの筋肉に助けられたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（15:17〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=917s"]]}, {"cat": "リングに来るまで", "t": "13歳で屋根から飛び降りた", "b": "90年代に育ち、金網の上から投げ落とされた名勝負に衝撃を受けたという。13歳のとき、憧れの選手をまねて家の屋根からマットレスへ飛び降りたそうだ。昔から飛ぶことは好きだったと笑う。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（17:44〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1064s"]]}, {"cat": "リングの話", "t": "大きな相手には試合の運びを変える", "b": "ブラウンほど大きな相手と戦うのは初めてで、勝手が違うと話す。テンポは遅めになり、受け方も変えているそうだ。誰に対しても同じやられ方をする選手がいるが、相手で変えるべきだと考えている。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（20:07〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1207s"]]}, {"cat": "リングの話", "t": "観客を投げた場面が最も再生された", "b": "試合の中で、観客役の男性を投げた映像が最も再生されたという。壁を壊す場面のほうが話題になると予想していたそうだ。相手は自分と同じくらいの体格で、事前に打ち合わせたうえでベルトをつかんで投げたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（22:32〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1352s"]]}, {"cat": "リングに来るまで", "t": "地元オーストラリアでハードコアを経験", "b": "育った州では、ハードコア形式の試合が昔から定番だったという。インディー時代に何度もこなしたそうだ。WWEではまだ見せていない技や武器の使い方も残していると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（24:50〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1490s"]]}, {"cat": "リングの話", "t": "ツナミは片足から踏み出す形に変えた", "b": "昔は両足をロープに乗せてから跳んでいたが、日本へ行く前後に古い選手の映像を見て片足で踏み出す形に変えたという。人と違うことが印象を残すと考えたそうだ。観客が一歩ごとに沸いてくるのを感じると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（26:23〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1583s"]]}, {"cat": "リングに来るまで", "t": "10代に影響を受けたのはサモア・ジョー", "b": "10代のころはサモア・ジョーに強く影響されたという。大きな体で機敏に動く姿に惹かれたそうだ。WWEに入ってからは、バンバン・ビガロなど大型の古い選手にも近づいたと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（27:59〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1679s"]]}, {"cat": "リングの話", "t": "最初の復帰は物足りなかったと振り返る", "b": "復帰直後の使われ方は、衝撃に欠けたと感じているという。会社も使い方を決めかねて急いで起用したのだろうと見ている。ただ、共演した先輩から多くを学んだとも話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（32:43〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1963s"]]}, {"cat": "リングの話", "t": "大乱戦のトロフィーの扱いへの思い", "b": "年間最大の祭典の大乱戦に勝ったが、その後トロフィーがあまり扱われなかったと感じているという。数か月持ち歩いて話題にしたかったそうだ。前年は決勝で敗れており、翌年に勝てたのは雪辱だったと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（34:19〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2059s"]]}, {"cat": "リングに来るまで", "t": "オーストラリアで夢を信じられなかった", "b": "子どものころは夢はあっても、現実になるとは誰も思っていなかったという。10代になったとき、まず日本へ行くことを目標にしたそうだ。のちに同郷の女子選手が契約し、自分にも道があると考え直したと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（36:47〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2207s"]]}, {"cat": "好きなもの", "t": "バンドTシャツで素顔を出す", "b": "昔から音楽が好きで、入場時にバンドTシャツを着ると視聴者に好評だという。以前は無地の服を勧められたが、自分らしさを出すことにしたそうだ。ヒップホップのほか、英国のニューウェーブやメタルも聴くと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（41:39〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2499s"]]}, {"cat": "好きなもの", "t": "筋金入りのゴジラ好き", "b": "子どものころからゴジラが大好きで、入場の演出にも取り入れたかったという。育成時代に少し試み、復帰後に上司へ頼んで実現したそうだ。今後もゴジラらしい演出が増えると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（42:30〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2550s"]]}, {"cat": "好きなもの", "t": "スニーカーは150足以上", "b": "ジョーダンの3をよく履き、デザインでは4が一番好きだという。子どものころは貧しくて靴が買えなかったため、今は少し度を越した収集になっていると話す。履かなくなったものは古着店へ寄付しているそうだ。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（43:18〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2598s"]]}, {"cat": "好きなもの", "t": "ポップパンクの四大バンドを選ぶ", "b": "ポップパンクが大好きで、ブリンク182を土台となる存在に挙げた。ほかにも好きなバンドを挙げ、再結成後のブリンク182のライブにも行ったという。ライブに行きたいバンドは多く、バンド側から反応をもらうこともあるそうだ。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（49:40〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2980s"]]}, {"cat": "好きなもの", "t": "映画の好みは日によって変わる", "b": "好きな映画は日によって変わるそうで、「ジョーズ」「ブルース・ブラザース」「ドライヴ」などを挙げた。レスラーでは小橋建太とストーン・コールドを不動の二人とし、三人目はダスティ・ローデスが多いという。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（51:19〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3079s"]]}, {"cat": "暮らし", "t": "批判の声は気にしない", "b": "ネットの評価は好意と批判が半々くらいだが、気にしないと話す。誰かに語られること自体が大事で、悪役として嫌われるのは仕事の一部だと考えているそうだ。解雇を願うような書き込みには、家族の収入を奪う行為だと強い嫌悪感を示した。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（54:33〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3273s"]]}, {"cat": "暮らし", "t": "腕の伝統的なタトゥー", "b": "腕のタトゥーは20代前半に入れた模様と、後から専門の彫り師に足してもらった鎧のような模様があるという。サモアの血を引くが、育ったのは主にオーストラリア側の家族のもとで、サモアの親族とのつながりは強くないそうだ。ウーソズやロックの親戚かとよく聞かれると笑う。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（56:56〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3416s"]]}, {"cat": "好きなもの", "t": "フィギュアは最初の一体がお気に入り", "b": "フィギュアはこれまで入場衣装の違いで作られてきたという。一番好きなのは、バンバン・ビガロ風の衣装を着た最初の一体だそうだ。新しいフィギュアも近く出ると話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（59:24〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3564s"]]}, {"cat": "リングの話", "t": "ポール・ヘイマンから学んでいる", "b": "毎週の収録日にポール・ヘイマンと話し込んでいるという。教わったのは、大きな体を生かして自分をどう見せるかと、言葉の使い方だそうだ。キャリアの大きな影響は、最初のトレーナーと、首脳陣のひとりだと話す。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（1:00:57〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3657s"]]}, {"cat": "家族", "t": "感謝するのは娘・妻・ファン", "b": "番組の最後に、感謝していることとして娘、妻、ファンの順に挙げた。移動のない日は妻と娘と過ごしているという。妻は娘を授かるまでに大きな苦労をしたと明かした。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-MbiKaddOizI", "src": [["番組のYouTube（1:02:34〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=3754s"]]}]);
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "同じ街の出身で、観客だった時代から知る仲", "b": "リアは同じ街の出身で、インディー時代の会場に観客として来ていたと、ブロンソン・リードが話している。訓練を始めたころから有名になると感じていたそうだ。WWEに入ってからは本来の自分を出せるようになって人気が出たと、ブロンソン・リードが話している。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で、ブロンソン・リードの話（字幕を全文確認）", "src": [["番組のYouTube（40:52〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=2452s"]], "by": "第三者の話"});
  if (PROFILES["Mark Henry"]) PROFILES["Mark Henry"].facts.push({"cat": "暮らし", "t": "大型で動ける選手が久しぶりだと助言", "b": "マーク・ヘンリーは、リードの戦い方に連絡をくれたと、ブロンソン・リードが話している。大きくて動ける選手は久しぶりだと言い、古参の大型選手たちも応援していると、ブロンソン・リードが話している。", "sp": "ブロンソン・リード", "d": "2024-10-08", "how": "クリス・ヴァン・ヴリートの番組で、ブロンソン・リードの話（字幕を全文確認）", "src": [["番組のYouTube（28:45〜）", "https://www.youtube.com/watch?v=MbiKaddOizI&t=1725s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-MbiKaddOizI", d: "2024-10-08", show: "ext", who: ["Bronson Reed"], t: "ブロンソン・リードの回　父になった巨漢と、自分らしさの話", lead: "クリス・ヴァン・ヴリートの番組に出た約63分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bronson Reed"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-MbiKaddOizI").map((x) => [x.t, x.b, x.sp])), open: ["聞き手の誕生日の話題や、広告の読み上げ部分は載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=MbiKaddOizI"]] });
