  PROFILES["Goldberg"].facts.push(...[{"cat": "リングに来るまで", "t": "祖母と見たプロレスと、ルームメイトの勧め", "b": "育ったタルサでは、祖母と一緒に地元のプロレス中継を見ていたと話す。ただ本人はフットボール一筋で、プロレスに夢中だったわけではないという。ラムズ時代のルームメイトがプロレスの物真似がうまく、業界入りを最初に勧めた人物だったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（4:57〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=297s"]]}, {"cat": "リングに来るまで", "t": "フットボールだけが生きがいだった", "b": "ヘルメットをかぶって相手にぶつかること以外、先のことは何も考えていなかったと話す。個人の成績より、チームで同じ目標に向かうことが好きだったという。ひとつのプレーは平均18秒で、その短い時間に人間性が出ると語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（5:46〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=346s"]]}, {"cat": "リングに来るまで", "t": "NFLの夢を二度断たれた", "b": "ラムズから二度解雇され、ただひとつ抱いていた夢を失ったと話す。先の見えない状態で、生き方に迷う時期でもあったそうだ。その後は別のリーグに移り、チームの優勝を経験している。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（9:01〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=541s"]]}, {"cat": "リングに来るまで", "t": "腹部の大けがで、フットボールを離れた", "b": "ファルコンズ時代の最後の試合前後に腹部を痛め、原因が分からないまま1年を過ごしたという。移籍先でも歩けないほどで、自分から監督に「もう無理だ」と告げてチームを去ったと話す。会計士から「そろそろ動け」と電話を受けたことも明かしている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（9:49〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=589s"]]}, {"cat": "リングに来るまで", "t": "ジムにこもって体を鍛え直した", "b": "チームを離れたあとは、地元のジムで人並み外れた量のウェイトを挙げたと話す。そこで知り合いを通じてプロレスの世界が近づいてきたそうだ。当時の自分は、プロレスラーに見られるのを避けていたという。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（10:40〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=640s"]]}, {"cat": "リングに来るまで", "t": "目立たず、壁のハエでいたい性分", "b": "心理学を専攻していたこともあり、人を観察するのが好きだと話す。仕事以外では誰にも注目されず、静かに過ごしたい性格なのだという。派手に振る舞うレスラーたちを見て、自分は同じ種類の人間になりたくないと思っていたそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（11:32〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=692s"]]}, {"cat": "リングに来るまで", "t": "毎日の練習を自分で録画して見返した", "b": "養成所では、練習の初日から最後の日まで毎日ビデオカメラで自分を撮っていたと話す。その映像は今も手元に残っているという。家に帰って見返しつつ、総合格闘技の映像も研究し、これは将来大きくなると感じていたそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（13:13〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=793s"]]}, {"cat": "リングに来るまで", "t": "恩師サージへの敬意", "b": "養成所の指導者サージの存在がなければ、続けていたかどうか分からないと話す。厳しいしごきも、フットボールで鍛えられた経験があるから笑って受けられたという。同じ時期に練習した仲間の何人かは、相手役としてずいぶん助けてくれたそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（15:32〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=932s"]]}, {"cat": "リングに来るまで", "t": "アトランタで巨大な格闘技ジムを共同経営", "b": "デビューの頃、アトランタに3万平方フィート級の格闘技ジムを共同で持っていたと話す。有名な格闘家も練習に来ていて、技を試す場になったという。のちに共同経営者にお金を持ち逃げされたことも語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（17:18〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1038s"]]}, {"cat": "リングの話", "t": "リングネームは「ゴールドバーグ」に決まった", "b": "最初の試合の場で、呼び名を聞かれて「ハイブリッド」と答えたが、商標の問題で断られたと話す。そこで自分の名字を選んだのだという。フィニッシュを聞かれ、相手役にただ体を預けてくれと頼んで、フットボールのタックルをそのまま決めたそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（18:03〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1083s"]]}, {"cat": "リングの話", "t": "無敗の連勝は計画されていなかった", "b": "連勝は自然に始まったもので、最初に誰かが筋書きを描いていたわけではないと話す。大きな対戦が決まったことも、自宅のテレビを見て初めて知ったという。自分は大きなパズルの一片で、言われたことをこなしていただけだと語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（19:44〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1184s"]]}, {"cat": "リングの話", "t": "短く強く、が自分のスタイル", "b": "長い試合を組み立てる普通のプロレスとは違い、相手を一気に仕留めるのが自分の売りだったと話す。練習で相手を何発も殴っていると、一発で倒せと指導者に言われたという。ホーガンからは「少ないほうがいい」と教わったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（21:25〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1285s"]]}, {"cat": "リングの話", "t": "ボビー・イートンに勝たせたかった", "b": "連勝のさなか、世話になった先輩ボビー・イートンの地元で、自分が負けて彼を主役にしたいと頼んだと話す。業界のことを知らなかったので、そう言い出せたのだという。今でも、人に恩を返したいという自分らしさが出た出来事として誇りにしているそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（27:02〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1622s"]]}, {"cat": "リングの話", "t": "生まれ故郷での初戴冠", "b": "アトランタで初めて世界王座を獲った夜、試合の進め方は「リングで決めよう」とだけ言われたと話す。思い出すと、フットボール時代に憧れた元チームメイトが、ファルコンズの選手として会場にいたという。彼らが自分のようになりたがっていることが、人生でも指折りの満足感だったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（32:35〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=1955s"]]}, {"cat": "リングに来るまで", "t": "子どもたちのヒーローになりたかった", "b": "フットボール選手を目指した理由のひとつは、子どもたちにとっての「スーパーヒーロー」になることだったと話す。殿堂入りの挨拶でも、NFL選手になるのが夢だったと述べたという。結果的にプロレスの殿堂のほうが、その存在に近づける道だったと振り返っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（34:21〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=2061s"]]}, {"cat": "リングの話", "t": "最初のWWE時代は居場所がなかった", "b": "移籍当初は、WCW時代の相手と同じ側に立つことになり、自分から壁を作ってしまったと話す。ブロック・レスナーとの大舞台は、観客に冷めた空気で迎えられたという。長年WWEへの不満が残ったが、あの時はただ仲間として受け入れられたかったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（43:13〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=2593s"]]}, {"cat": "家族", "t": "妻ワンダとの出会いは映画の撮影現場", "b": "映画の殺人サンタ役で撮影中、スタントウーマンのワンダと出会ったと話す。ジェフ・ゴールドブラムだと思って現場に来たという彼女に、レスラーは「偽物の世界の人」と言われたそうだ。恋愛しないと決めていた職業の条件にすべて当てはまっていたのに、3か月後に結婚したという。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（47:14〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=2834s"]]}, {"cat": "家族", "t": "息子ができて、すべてが変わった", "b": "家族を持つ前にやりたいことは済ませていて、始めたからには全力だと話す。妻のおかげで素晴らしい息子に恵まれたと語る。息子には自分の良いところを受け継いでほしく、悪いところは母に似てほしいと冗談めかしている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（49:40〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=2980s"]]}, {"cat": "体のこと", "t": "50歳での復帰は体との戦いだった", "b": "フットボールもけがで終えており、プロレス入りの前から歩くことも走ることも満足にできなかったと話す。16年のブランクを経て、積み重なったけがや限られた技の数を考えると、50歳で体重約130キロへ戻すのは簡単ではなかったという。それでも覚悟を決めて挑んだそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（52:51〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3171s"]]}, {"cat": "家族", "t": "復帰の理由は家族に見せるため", "b": "もう一度リングに立ったのは、もう一度主役になるためではなかったと話す。妻と息子にかつての自分の姿を少しだけ見せたい、その一心だったという。それまで家族を画面に出すことは考えられなかったが、年を重ねた自分の弱さを見せる形にしたそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（53:37〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3217s"]]}, {"cat": "体のこと", "t": "悲観的な性格で、緊張のかたまりだった", "b": "生まれつき悲観的で、次の5分を全力で生きることだけを考えていると話す。復帰前は不安で、信頼する先輩に電話して「ありのままのゴールドバーグでいい」と励まされたという。家族の前で失敗するのが何より怖かったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（57:58〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3478s"]]}, {"cat": "リングの話", "t": "復帰を支えたポール・ヘイマンの存在", "b": "復帰はポール・ヘイマンなしには成り立たなかったと話す。本人をよく知る人にしか任せられない、試行錯誤の余地がない状況だったという。レスナーとの短い試合で勝った時は、周囲の力で実現したことに深く感謝していると語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（1:00:26〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3626s"]]}, {"cat": "リングの話", "t": "最後と決めた試合を、初めて楽しめた", "b": "レスナーとの再戦では、これが最後と決めて、入場のカーテンで初めて笑顔になれたと話す。入場前に気持ちを高めるため水をかぶるなど、自分なりの儀式があるという。家族に誇りを持ってもらえる機会をもらえたことが、何より大きかったそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（1:03:49〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3829s"]]}, {"cat": "リングの話", "t": "負けた瞬間、どう振る舞えばいいか分からなかった", "b": "勝ち続けた自分にとって、負けは稀で、決定的に敗れた直後は戸惑ったと話す。解説の流れを壊したくないと考え、どう反応するかを必死で考えていたという。今でも業界のことは勉強中で、遅いスタートの身だと語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（1:06:20〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=3980s"]]}, {"cat": "信仰", "t": "ユダヤ系の自分を、クリスマスの役で見せる", "b": "近く出演するクリスマスの作品では、サンタ役を務めると話す。ハヌカーの季節に、ユダヤ系の自分の信仰を前向きに表現できる役だと語っている。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（1:08:54〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=4134s"]]}, {"cat": "暮らし", "t": "ふるさとに近いテキサスへ引っ越す", "b": "次の暮らしの場として、テキサスへ移ると話す。オクラホマにルーツがあり、その地方に戻る感覚だそうだ。新しい章の始まりを楽しみにしているという。ドラマの出演や、車の番組の企画も控えているそうだ。", "sp": "ゴールドバーグ", "d": "2024-10-27", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QC-CipptCAA", "src": [["番組のYouTube（1:09:43〜）", "https://www.youtube.com/watch?v=QC-CipptCAA&t=4183s"]]}]);
  ARTICLES.push({ id: "ext-QC-CipptCAA", d: "2024-10-27", show: "ext", who: ["Goldberg"], t: "ゴールドバーグの回　フットボールの夢、無敗神話、そして家族のための復帰", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約72分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Goldberg"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-QC-CipptCAA").map((x) => [x.t, x.b, x.sp])), open: ["ストーン・コールド側の思い出話や評価、番組のあいさつは取り上げていない。", "学生時代の薬物検査の話や、団体間の対立をめぐる細かな言い分は、載せるか迷って省いた。", "自動字幕で崩れていた名前（一部の同僚レスラー名など）は確信が持てず、記載していない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=QC-CipptCAA"]] });
  if (!ROSTER.find((r) => r[1] === "Omos")) ROSTER.push(["オモス", "Omos", "lg", "", "", "", ""]);
  if (!PROFILES["Omos"]) PROFILES["Omos"] = { lead: "ナイジェリアから15歳でひとり渡米し、バスケ選手として育った巨漢。修士号まで取ってからプロレスの世界に入った経歴を、気さくに語っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Omos"]], moves: [], facts: [] };
  if (PROFILES["Omos"]._weak) { PROFILES["Omos"].lead = "ナイジェリアから15歳でひとり渡米し、バスケ選手として育った巨漢。修士号まで取ってからプロレスの世界に入った経歴を、気さくに語っている。"; delete PROFILES["Omos"]._weak; }
  PROFILES["Omos"].facts.push(...[{"cat": "リングの話", "t": "アンダーテイカーが支えになっている", "b": "アンダーテイカーのような大物が自分の味方でいてくれることに感謝していると話す。会場で声をかけてもらうだけでなく、連絡をもらえることもあり、ありがたく感じているそうだ。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=94s"]]}, {"cat": "リングの話", "t": "出番が少ない時期は立て直しの期間", "b": "テレビでの出番が少ないことについて、妻から「上り調子だった流れを整え直す時期かもしれない」と言われたという。その間に演技や話し方など、レスラーとして必要な別の技術を磨く時間にできると話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（3:15〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=195s"]]}, {"cat": "リングに来るまで", "t": "ナイジェリアから15歳でひとり渡米", "b": "生まれはナイジェリアで、15歳のときにたった一人でアメリカへ渡ったと話す。きっかけは、のちにNBAチームの幹部になる人物が現地で開いていたバスケットボールのキャンプだったという。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（4:49〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=289s"]]}, {"cat": "リングに来るまで", "t": "13歳で約2メートル、年齢を疑われた", "b": "初めてキャンプに行ったのは13歳のときで、すでに身長は約2メートルあったそうだ。靴は穴だらけの1足しかなく、成長が早くて買い替えもできなかったという。受付で年齢を疑われたが、たまたまその施設で働いていた叔母が来て本当の年齢を証明してくれたと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（5:39〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=339s"]]}, {"cat": "リングに来るまで", "t": "始めて数か月でバスケの世界へ", "b": "バスケを始めたのはキャンプの2〜3か月前で、周りは何年も続けている子ばかりだったという。それでも通い続けて人生が変わり、15歳で奨学金を得た。最初に決まっていた名門校は、移民手続きの面接の都合で話が流れたが、別の強豪校に進めたと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（7:12〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=432s"]]}, {"cat": "リングに来るまで", "t": "祖母の家で見ていたプロレス", "b": "祖母がプロレス好きで、子どものころは祖母の家の小さなテレビで一緒に見ていたという。契約が決まったとき、そうした記憶が一気によみがえったと話す。のちに、アンダーテイカーの試合を見て引き込まれたとも語っている。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（17:30〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=1050s"]]}, {"cat": "リングに来るまで", "t": "バスケ仲間のコーチの冗談が現実に", "b": "高校時代、父親のように慕っていたコーチが、調子の悪い日に「明日ダンクを決めなければプロレス団体に電話するぞ」と脅していたという。本人は本気で怒っていたそうだ。WWEと契約したと電話で伝えると、コーチは「ずっと種をまいていたんだ」と喜んだと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（26:12〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=1572s"]]}, {"cat": "リングに来るまで", "t": "2018年に契約、パンデミックで観客役に", "b": "契約は2018年で、育成施設には2年ほどいたという。パンデミックの最初のころは、妻の実家があるタンパ近くで過ごし、自宅でテレビ収録を見ていたそうだ。ところが翌日、観客役として呼び戻され、そこで大柄な姿が目に留まったことが転機になったと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（27:51〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=1671s"]]}, {"cat": "好きなもの", "t": "高校時代はシャキール・オニールの映像が教科書", "b": "高校のころは、シャキール・オニールの映像を見て動きを真似しようとしていたという。圧倒的な体の強さだけでなく、あの大きさでの足さばきのうまさもあまり語られないと感じていたと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（32:35〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=1955s"]]}, {"cat": "リングに来るまで", "t": "早く始めすぎてバスケは燃え尽きた", "b": "バスケを早い時期から始めたため燃え尽きてしまい、今は試合を見るのも少しつらいと話す。ゴール下で攻めずに外からの3点ばかり狙う現代のバスケにも、もどかしさを感じているそうだ。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（34:11〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=2051s"]]}, {"cat": "リングの話", "t": "最初の試合をスコット・ホールが仕切った", "b": "育成施設に来たスコット・ホールが、大柄な本人を見て「あいつと試合をしたい」と声をかけてくれたという。リングで動きを教えてくれたうえ、初試合の会場にも来て試合を取り仕切ってくれたと話す。その後も「元気か」と電話をくれる気さくな人だったそうだ。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（42:52〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=2572s"]]}, {"cat": "リングの話", "t": "初めてアンダーテイカーに会った日", "b": "育成施設の収録で初めて会ったとき、幽霊を見たような気持ちになったという。落ち着こうと自分に言い聞かせていたが、「ビッグ・フェラ」と名前で呼ばれ、認められたようでうれしかったと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（45:18〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=2718s"]]}, {"cat": "リングの話", "t": "リング上でズボンが破けても笑わなかった", "b": "大きな大会の週に育成施設で行った公開イベントで、細身のズボンのまま技を試すよう言われ、お尻のあたりまで裂けてしまったことがあるという。周りの視線を浴びながらも、表情を変えずに演じ切ったと話している。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（46:07〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=2767s"]]}, {"cat": "リングに来るまで", "t": "2014年のトライアウトを前に迷った", "b": "学部を終えた2014年、バスケに気持ちが落ち込んでいたころ、WWEのトライアウトを受けようと飛行機とホテルまで押さえていたという。しかし友人から、行くと大学で残っていた1年間の競技資格を失うと言われて断念した。それ以前からWWE関係者に誘われていたが、すぐには行けなかったそうだ。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（49:18〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=2958s"]]}, {"cat": "リングに来るまで", "t": "修士号を取ってからレスラーに", "b": "アフリカ出身の親は教育を重んじるため、まず学業を終えようと考えたという。ビジネスの修士号を取り、そのうえで「これで学位は取れたから、プロレスをやる」と決めたと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（50:05〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=3005s"]]}, {"cat": "リングに来るまで", "t": "リングに立った瞬間にバスケをやめた", "b": "プロレスを始めたとたん、バスケへの未練はなくなったという。今でもボールに触りたい気持ちはなく、スニーカーをつるして引退するような感覚だったと話す。ロープに初めて入ったとき「自分の居場所はここだ」と思ったそうだ。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（52:30〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=3150s"]]}, {"cat": "暮らし", "t": "妻はプロレスをよく見ているのに驚く", "b": "バスケをやっていたころは試合を全然見なかったのに、今はプロレスの大会を見続けているため、妻に驚かれると話す。バスケは次第に仕事のようになったが、プロレスは巡業でも苦にならず、むしろ楽しみだという。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（54:05〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=3245s"]]}, {"cat": "好きなもの", "t": "古い試合をよく見て勉強している", "b": "ケイン、アンドレ・ザ・ジャイアント、ヘイスタックス・カルホーン、キング・コング・バンディなど、昔の大型選手の試合をよく見るという。昔の試合はテンポが遅く、最初は見るのに時間がかかったが、経験を積んで物語の運びが分かるようになったと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（55:38〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=3338s"]]}, {"cat": "リングの話", "t": "最初のコーチたちの教えで脚を叩かなくなった", "b": "育成施設の最初のコーチだったロビー・ブルックサイドとジョニー・モスは、脚を叩いて音を出すやり方を嫌っていたという。叩くたびに腕立て伏せ10回だったため、今も自然としなくなったと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（1:01:21〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=3681s"]]}, {"cat": "リングの話", "t": "何でも試した結果、けがが増えた", "b": "育成施設では運動能力を見込まれて何でも試され、8割ほどはこなせたという。しかしけがが増えたため、派手な技は「持っていても出さなくていい道具」と考えるようになったと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（1:06:57〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=4017s"]]}, {"cat": "リングの話", "t": "「ゆっくりやれ」と教わった", "b": "若いころはすぐ速く動きたがったが、アンダーテイカーに「もっとゆっくり」と教えられたという。大きな体を生かし、相手をじっくり追い詰める見せ方が大切だと学んだと話す。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（1:11:45〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=4305s"]]}, {"cat": "好きなもの", "t": "ロマン・レインズとランディ・オートンをよく見る", "b": "最近はロマン・レインズとランディ・オートンの試合をよく見ているという。特にロマンについては、レスラーというより名優だと評価している。", "sp": "オモス", "d": "2024-11-04", "how": "When Wrestling Was Realの番組で（字幕を全文確認）", "art": "ext-_sHG3ClgjGk", "src": [["番組のYouTube（1:21:24〜）", "https://www.youtube.com/watch?v=_sHG3ClgjGk&t=4884s"]]}]);
  ARTICLES.push({ id: "ext-_sHG3ClgjGk", d: "2024-11-04", show: "ext", who: ["Omos"], t: "オモスの回　ナイジェリアからバスケ、そしてプロレスへ", lead: "When Wrestling Was Realの番組に出た約90分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Omos"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-_sHG3ClgjGk").map((x) => [x.t, x.b, x.sp])), open: ["アンダーテイカーが聞き手の回で、話者の入れ替わりが多く、判断がつかなかった発言は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=_sHG3ClgjGk"]] });
  if (!ROSTER.find((r) => r[1] === "Ricochet")) ROSTER.push(["リコシェ", "Ricochet", "gn", "元WWE。他団体へ移籍", "", "", ""]);
  if (!PROFILES["Ricochet"]) PROFILES["Ricochet"] = { lead: "WWEで長く空中戦と見せ場づくりを担い、契約満了を機に自ら団体を離れたリコシェ。自分が一番楽しめる場所を探した末の決断だったと語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ricochet"]], moves: [], facts: [] };
  if (PROFILES["Ricochet"]._weak) { PROFILES["Ricochet"].lead = "WWEで長く空中戦と見せ場づくりを担い、契約満了を機に自ら団体を離れたリコシェ。自分が一番楽しめる場所を探した末の決断だったと語る。"; delete PROFILES["Ricochet"]._weak; }
  PROFILES["Ricochet"].facts.push(...[{"cat": "退団の理由", "t": "最後の試合から約2か月半の空白", "b": "WWEでの最後の出演は、アンドラーデとの試合と、ブロン・ブレイカーに叩きのめされる場面だったという。そこから6月上旬〜8月下旬まで、リコシェは試合をせず家族と過ごした。キャラクターが退場したように見えたが、会社側は含みを持たせていたのではないか、と本人は話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=145s"]]}, {"cat": "退団の理由", "t": "契約は6月中旬まで、決断は直前まで未定", "b": "契約が6月中旬に切れることは分かっていたものの、その場面の時点では退団すると決めていなかったという。ブロン・ブレイカーとの場面も、すぐ戻れるように余白を残した形だったのだろう、とリコシェは見ている。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（3:11〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=191s"]]}, {"cat": "退団の理由", "t": "3年半前から芽生えていた迷い", "b": "WWEでの3年半ほど前から、これは自分が本当にやりたいことではないと感じ始めたという。それでも求められた通りに負け役も引き受け、努力を見せれば次の機会につながると考えていた。出番は常にあったが、物語はいつも他の選手のためのもので、リコシェ自身の物語ではなかったと感じていたと話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（4:00〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=240s"]]}, {"cat": "WWEでの日々", "t": "WWEに入るとは思っていなかった少年期", "b": "子どもの頃はWWEの人形が大好きだったが、自分がその舞台に立つとは考えたことがなかったという。レスリングを始めたのは楽しくて仲間ができたからで、チャンスが重なるうちに育成の場や別の団体の仕事へと道が広がっていった、とリコシェは振り返る。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（5:34〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=334s"]]}, {"cat": "退団の理由", "t": "3年後の自分を想像して決めた", "b": "決め手を聞かれて、3年後、その先に自分がどこにいるかを考えたという。誰にでも状況は分からないが、自分の経験から判断するしかなかったと話す。何か一つの出来事が引き金になったわけではないそうだ。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（6:23〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=383s"]]}, {"cat": "退団の理由", "t": "新世代の登場で「やり直し」の気分に", "b": "ブロン・ブレイカーなど新しく上がってきた選手たちと並ぶと、在籍5〜6年の自分がまた一から始めるような感覚になったという。条件の一番良い所へ行くつもりはなく、もう一度火をつけてくれる場所を選びたかった、と本人は話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（7:14〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=434s"]]}, {"cat": "WWEでの日々", "t": "WWEでも技を抑えてはいなかった", "b": "WWE時代も、場外の実況席へ飛ぶ大技や高難度の空中技を出していたので、他団体に来て解き放たれたわけではないとリコシェは話す。観客を沸かせる技をWWEでも普通に出していたという。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（12:02〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=722s"]]}, {"cat": "WWEでの日々", "t": "勝てない試合では大技を温存した", "b": "ロガン・ポールにはコーナー上からテーブル越しにスパニッシュフライを決めたこともあるという。ただ自分はあまり勝たなかったので、勝てない試合で最大級の技を使うことは避けていたと話す。相手がランディ・オートンやドリュー・マッキンタイアのような選手か、軽量級の選手かでも、試合の組み立ては変わるという。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（12:54〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=774s"]]}, {"cat": "退団の理由", "t": "「自分ももっとやれる」と感じたから", "b": "WWEの仕事への愛と敬意は今も強いが、自分はもっとできるはずだと感じたことが、団体を離れた理由の一つだったとリコシェは話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（26:35〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=1595s"]]}, {"cat": "WWEでの日々", "t": "「見事な負け方を考えろ」と言われ続けた", "b": "WWEでは、相手を良く見せる役回りが増えていったという。派手な負け方を工夫してくれ、という趣旨のことを何度も言われたそうだ。リコシェはそれを人のせいにはせず、状況を受け入れてきたと話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（47:54〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=2874s"]]}, {"cat": "WWEでの日々", "t": "責任は自分にある、でも身動きは取れなかった", "b": "思うようにいかなかった部分は自分の責任だと考えている、と本人は話す。WWEが押さえつけたとは思わないが、動きにくい位置に置かれたとは感じていたという。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（48:41〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=2921s"]]}, {"cat": "WWEでの日々", "t": "衝突より、与えられた仕事で示す姿勢", "b": "アイデアを出しても通らない経験を重ねるうち、毎週のように売り込みに行く性格ではないので、言われたことをこなして結果で見せる方針に落ち着いたという。努力すれば次第に大きな機会が来ると信じていた、とリコシェは話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（49:30〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=2970s"]]}, {"cat": "WWEでの日々", "t": "「なぜ勝てないのか」という思い", "b": "高難度の技を次々出しても勝たせてもらえず、テレビに出て数週間負け続けることに疑問を持ったという。家族が試合を見る夜に「どうせ負けるのは分かっているが楽しみだ」と父親に言われたこともあり、見る側の印象がそのまま現実になると感じたそうだ。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（51:12〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3072s"]]}, {"cat": "WWEでの日々", "t": "オートンのRKOで頭から落ちた場面", "b": "ランディ・オートンのRKOを受けて頭から落ち、すぐ立ち上がった場面は、狙ったものではなく自然に起きた動きだったという。相手が重くて落ちるのが予想より早かったのだろう、とリコシェは話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（54:22〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3262s"]]}, {"cat": "WWEでの日々", "t": "ムーンサルトを蹴られた場面の裏側", "b": "ドリュー・マッキンタイアのクレイモアを受けた場面や、アダム・コールに蹴り飛ばされた場面は、今も動画で話題になるという。相手の立っている状態でムーンサルトを狙ったのは意図通りで、相手の正確さのおかげで見映えがしたと話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（55:09〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3309s"]]}, {"cat": "WWEでの日々", "t": "ブロック・レスナーの投げは任せるしかない", "b": "レスナーに投げられるときは、自分では動きを制御できず、ただ飛ばされるだけだったという。自分の体格だと特にそうで、見映えを作る余地がほとんどなかった、とリコシェは話す。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（55:58〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3358s"]]}, {"cat": "WWEでの日々", "t": "ロイヤルランブルでのロガン・ポールとの空中場面", "b": "年間最大級の試合形式の大会で、ロガン・ポールとの空中場面が注目を集めたが、当日に会場でハリケーン・ヘルムズから案内されたものだったという。リコシェは話題になる場面を作るのが自分の役目だと考えていたそうだ。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（56:48〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3408s"]]}, {"cat": "WWEでの日々", "t": "空中で向かい合った瞬間の印象", "b": "着地でロガンは頭を打ったようだが大丈夫だと話していた、とリコシェは振り返る。この場面を描いた絵を海外のファンが送ってくれたそうで、二人が飛びかかる姿を映画の有名な場面になぞらえて話している。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-zD6rdG83LdM", "src": [["番組のYouTube（59:13〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3553s"]]}]);
  if (PROFILES["Hurricane Helms"]) PROFILES["Hurricane Helms"].facts.push({"cat": "暮らし", "t": "当日に場面を持ちかけた制作担当", "b": "ロガン・ポールの試合の制作を担当しているハリケーン・ヘルムズが、大会当日に会場で空中場面のアイデアを持ちかけてきたと、リコシェが話している。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で、リコシェの話（字幕を全文確認）", "src": [["番組のYouTube（58:21〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3501s"]], "by": "第三者の話"});
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "投げの強さは別格", "b": "ブロック・レスナーは大型選手を軽々と投げ飛ばす選手で、自分のような小柄な選手は飛ばされるまま見映えを任せるしかなかったと、リコシェが話している。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で、リコシェの話（字幕を全文確認）", "src": [["番組のYouTube（55:58〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3358s"]], "by": "第三者の話"});
  if (PROFILES["Logan Paul"]) PROFILES["Logan Paul"].facts.push({"cat": "暮らし", "t": "何をしても話題になる", "b": "ロガン・ポールは動画の時代から、やることがすべて広まる選手で、その試合の場面も注目されると思っていたと、リコシェが話している。", "sp": "リコシェ", "d": "2024-11-05", "how": "クリス・ヴァン・ヴリートの番組で、リコシェの話（字幕を全文確認）", "src": [["番組のYouTube（57:35〜）", "https://www.youtube.com/watch?v=zD6rdG83LdM&t=3455s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-zD6rdG83LdM", d: "2024-11-05", show: "ext", who: ["Ricochet"], t: "リコシェの回　WWEを離れた理由と、見せ場を作り続けた日々", lead: "クリス・ヴァン・ヴリートの番組に出た約76分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ricochet"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-zD6rdG83LdM").map((x) => [x.t, x.b, x.sp])), open: ["パートナーの退団に関するリコシェの推測は、本人以外の内心にあたるため載せていない。", "他団体での日々や家族・好きなものの話は、公開項目に入れていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=zD6rdG83LdM"]] });
  if (!ROSTER.find((r) => r[1] === "Austin Theory")) ROSTER.push(["オースティン・セオリー", "Austin Theory", "lg", "元US王者", "", "", ""]);
  if (!PROFILES["Austin Theory"]) PROFILES["Austin Theory"] = { lead: "夢だけを見て生きてきた27歳が、シナ戦やロック復帰の裏側まで率直に語る。祖父母や弟、読書や筋トレへの思いから、まっすぐな人柄が伝わる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Austin%20Theory"]], moves: [], facts: [] };
  if (PROFILES["Austin Theory"]._weak) { PROFILES["Austin Theory"].lead = "夢だけを見て生きてきた27歳が、シナ戦やロック復帰の裏側まで率直に語る。祖父母や弟、読書や筋トレへの思いから、まっすぐな人柄が伝わる。"; delete PROFILES["Austin Theory"]._weak; }
  PROFILES["Austin Theory"].facts.push(...[{"cat": "リングに来るまで", "t": "2019年のインディー興行で再会した旧知の仲", "b": "インタビュアーとは2019年、フロリダのインディー団体の興行で出会っている。当時は契約前で、リングネームを何通りも名乗って観客の怒りを買う悪役だったという。その頃すでにジョン・シナを名指しで挑発していたと、オースティン・セオリーは振り返っている。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=94s"]]}, {"cat": "好きなもの", "t": "筋トレは「ゆっくり、丁寧に」が信条", "b": "腕のトレーニングを12歳から続けているという。最近の2年は、筋肉に意識を向ける「マインド・マッスル・コネクション」を理解してから変わったそうだ。セット間のストレッチや、ゆっくり戻す動作、スーパーセットなどを重視し、重さの競争はしないと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（3:11〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=191s"]]}, {"cat": "リングに来るまで", "t": "8歳で地元の団体に魅了された", "b": "8歳のとき、地元ジョージア州マクドナで開かれていた育成団体の試合を見て夢中になったという。選手たちは街の人とは違う姿で、生のマーベル映画を見ているようだったと話す。12歳のとき母に「ジムに連れて行って」と頼み、体づくりを始めた。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（5:35〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=335s"]]}, {"cat": "リングに来るまで", "t": "11歳でジムのリングに通い詰めた", "b": "11歳のころ、母が通うジムの一角に格闘技教室が去り、リングが1つだけ残っていたそうだ。そこでビル・デモットが若手に受け身を教えていて、毎回母について行って見学した。「もうすぐ18歳」と本人は伝え続けていたという。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（6:24〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=384s"]]}, {"cat": "リングに来るまで", "t": "夢は「空が青い」のと同じ確信だった", "b": "学校では夢を笑われたが、本人にとってはプロレスラーになることは空が青いのと同じ当たり前の事実だったという。ほかの道は現実的に思えず、9時から5時の仕事も想像できなかったと話す。トレーニングの積み重ねそのものが好きだったそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（7:58〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=478s"]]}, {"cat": "リングに来るまで", "t": "車で暮らしてでもフロリダへ行くつもりだった", "b": "18歳のころ、1997年式のフォード・エクスプローラーに乗ってフロリダで暮らし、道を探すつもりだったという。実際にはもっと良い道が開けたが、何があっても叶えるという覚悟だったと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（8:46〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=526s"]]}, {"cat": "リングに来るまで", "t": "21歳で契約を目標にし、22歳の誕生日前に達成", "b": "契約の目標は21歳だった。8月2日の誕生日の少し後、8月中旬に契約したため22歳になっていたが、ほぼ狙いどおりだったという。育成施設では、リング、ジム、試合映像を見直す授業が毎日あり、自分のまずさを思い知らされたそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（9:38〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=578s"]]}, {"cat": "リングに来るまで", "t": "育成時代は日曜以外休みなしの毎日", "b": "育成施設では打たれ続ける日々で、筋肉を保つためにジムにも通ったという。さらに木・金・土は興行があり、休みは日曜だけだったそうだ。それが映像に出るまで続く、きつい下積みだったと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（10:23〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=623s"]]}, {"cat": "リングに来るまで", "t": "リングネームを守った経緯", "b": "契約の際、名前を手放せば何かを提供するという話もあり、変えられそうな空気もあったという。子どものころ裏庭のプロレスごっこで考えた名前なので、渡す理由はないと思ったそうだ。のちに本隊で「セオリー」だけの名前にされかけたが、話し合って元に戻したと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（13:37〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=817s"]]}, {"cat": "リングに来るまで", "t": "名前の意味は「未証明だから成長できる」", "b": "「セオリー(理論)」は証明されていないもの、証明されていないなら常に良くなれる、という意味を込めたという。養成学校の時代から、そう説明しようとして周りを混乱させてきたそうだ。今も、現状に満足しないという考え方は変わらないと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（15:12〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=912s"]]}, {"cat": "好きなもの", "t": "俳優の本とゴーギンズの本を読んでいる", "b": "最近は演技の指導書を読んでいて、授業を見ているような感覚だという。自己啓発書も好きで、デビッド・ゴーギンズの本を読んで、自分は精神的に強いと思っていたが上には上がいると感じたそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（17:31〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1051s"]]}, {"cat": "暮らし", "t": "「いちばんきつい種目をやる」と決めている", "b": "脚の日のハックスクワットが大嫌いで、だからこそそこで追い込むのだという。ポッドキャストで、嫌なことをすると脳の一部が育つと聞いたとも話す。体がきつくても、あと1回だけやると決めるのが習慣だそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（18:18〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1098s"]]}, {"cat": "好きなもの", "t": "映画のエキストラ出演をいろいろ経験", "b": "「ネイバーズ2」では、ザック・エフロンの場面で壇上に立つ大学生役だったという。「スパイダーマン ホームカミング」では、刑務所での撮影で囚人服を着て歩いた。「フィスト・ファイト」ではチャーリー・デイの教室にいたと、思い出を楽しそうに話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（21:28〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1288s"]]}, {"cat": "好きなもの", "t": "「ワイルド・スピード」にも兵士役で出た", "b": "兵士役で出演した作品があるが、どの作品かは覚えていないと笑う。真夏のジョージアで雪の場面を撮り、厚い軍服で気を失う人も出たという。現場でザ・ロックと初めて会い、思わず声をかけたと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（25:24〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1524s"]]}, {"cat": "リングの話", "t": "ザ・ロックの復帰回で、直前に呼ばれた", "b": "試合開始の1時間ほど前、トリプルHの部屋に呼ばれ、パット・マカフィーとの掛け合いから入ると告げられたという。ロックの出番は本人にも直前まで詳しく伝わらなかったそうだ。バスの中で会ったロックから「魔法になる」と言われ、リングでは目の合図だけで間が分かったと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（28:39〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1719s"]]}, {"cat": "家族", "t": "父がそばにいなかった子ども時代", "b": "子どものころ、父親がそばにおらず、いじめられた経験もあるという。そんなとき、仲間が大勢いても、自分の言うことを曲げずに戦う人を見て、決してあきらめない気持ちを学んだと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（34:18〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2058s"]]}, {"cat": "リングの話", "t": "ジョン・シナ戦への道、プロモで求められたもの", "b": "シナからは「本当の自分を出せ」と求められたが、悪役を演じることで精一杯だったという。ただ、本気で向き合ってくれていると感じたそうだ。シナから届く長いメッセージを今も読み返し、その細かさに驚くと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（35:08〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2108s"]]}, {"cat": "リングの話", "t": "レッスルマニアのシナ戦は打ち合わせなし", "b": "練習リングで少し組んだだけで、技の打ち合わせはしなかったという。シナから「今日は生の大会として戦おう」と言われ、緊張はなかったそうだ。入場のとき、祖母を感じたことが心に残っていると話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（41:32〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2492s"]]}, {"cat": "家族", "t": "亡き祖母は親友のような存在", "b": "祖母は本人にとって親友のような人で、契約の前後の時期に立ち会ってくれたという。その後亡くなり、WWEでの活躍は見せられなかったそうだ。ただ、ジョン・シナ戦の入場のとき、祖母を感じたと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（42:20〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2540s"]]}, {"cat": "家族", "t": "祖父との約束はシナ戦の観戦", "b": "幼いころから、祖父は「ジョン・シナと戦う姿をレッスルマニアで見たい」と言っていたそうだ。ホットドッグとコーラを持ってきてくれとも言われたという。本人は、ホットドッグは無理でも試合ならできると答えたと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（43:06〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2586s"]]}, {"cat": "リングの話", "t": "スタンナーで高く跳んだ理由", "b": "ストーン・コールドのスタンナーを受けて場外に落ちたとき、片目を開けて様子を見ていたという。高く跳ぶことは誰にも相談せず、自分で決めて実行したそうだ。試合後、彼から「いい受けだった」と声をかけられたと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（43:51〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2631s"]]}, {"cat": "暮らし", "t": "人生で一度もお酒を飲んだことがなかった", "b": "試合のあと、ストーン・コールドからビールをもらえると思い、初めて飲む覚悟をしていたという。実際には彼のシャツについたビールの匂いと味を感じただけで、「十分だった」と話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（44:43〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2683s"]]}, {"cat": "リングの話", "t": "タイソン・フューリーのパンチを受けた", "b": "ブリーフケースを手に出ていく場面で、本物のパンチを覚悟していたという。トリプルHから「歯を折られないように」と冗談を言われたそうだ。ボクシング王者に倒されるならそれでいいと思い、そのまま倒れたと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（46:23〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2783s"]]}, {"cat": "リングの話", "t": "ジェリー・ロールのチョークスラム", "b": "最初は背負い投げの案だったが、リング外の人に技をかける難しさを考え、チョークスラムに変えてもらったという。トリプルHに「任せてほしい」と伝え、約3メートル近く浮いたと笑う。着地の衝撃は全身で感じたそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（48:03〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2883s"]]}, {"cat": "リングの話", "t": "エリミネーション・チャンバーでの肩車からの落下", "b": "前日の稽古で、AJスタイルズが肩の上から落とされるのを見て、同じことを自分にもと言われたという。本番ではブロック・レスナーの肩の上からF5のように投げられ、足から着地して転がったそうだ。脚を折ってもおかしくなかったと振り返る。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（50:28〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3028s"]]}, {"cat": "リングの話", "t": "マネー・イン・ザ・バンクの優勝を知ったのは当日", "b": "その日の試合の前に、あとで全員のいる部屋に来るよう言われ、そこで知ったという。小学生のころ、ラダー戦のブリーフケースに憧れていたと話す。獲得した瞬間は、子どものころの夢が重なる出来事だったそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（55:12〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3312s"]]}, {"cat": "リングの話", "t": "ベルトの位置づけについての考え", "b": "世界王座に近い位置にいると言われるが、毎週テレビに出て、与えられた役割に全力で応えることが大事だと話す。ロックの復帰やジェリー・ロール戦など、どの場面でも自分のやるべきことは変わらないという。ミズを例に、長く続けて結果を残すことが大きいとも語っている。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（59:06〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3546s"]]}, {"cat": "リングに来るまで", "t": "インディー時代に見た景色が原点", "b": "インディー団体の大会で、メインを務めるマット・リドルやドリュー・マッキンタイアを見て、どうやってあそこまで行くのかと考えたという。今も、あの頃の学校に入ったばかりの自分を失いたくないと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（59:56〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3596s"]]}, {"cat": "家族", "t": "弟たちにとっての誇りでありたい", "b": "幼かった弟は、移住前に本人と試合ごっこをしていたという。その弟たちが、レッスルマニアの実況席の後ろで兄の試合を見たことが何より大きかったそうだ。地元は決して恵まれた土地ではなく、そこから何でもできると示せたのが嬉しいと話す。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（1:06:23〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3983s"]]}, {"cat": "暮らし", "t": "SNSとは距離を置いている", "b": "SNSで有名人が批判に反応するのは違うと思っているそうだ。ショーン・マイケルズが養成学校で話した「返事がないからこそ生まれる神秘性」の考え方に共感していると話す。悪口にも、気にかけてくれた証だと受け止めることにしているという。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（1:08:53〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=4133s"]]}, {"cat": "暮らし", "t": "毎日の感謝と、病院訪問で受けた気づき", "b": "感謝するものとして、家族、自分の考え方、そして朝ベッドから起き上がって好きなことをできることを挙げている。子ども病院を訪ね、重い治療を受けながら笑う子どもたちを見て、小さな不満は言えないと感じたという。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-pU89aflaRn4", "src": [["番組のYouTube（1:12:11〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=4331s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "シナは短い返事をしない人", "b": "ジョン・シナは、メッセージを送ると、細かく考えられた長い返信をくれる人だと、オースティン・セオリーが話している。何度も読み返して、足りない点を探していたそうだ。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で、オースティン・セオリーの話（字幕を全文確認）", "src": [["番組のYouTube（39:10〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=2350s"]], "by": "第三者の話"});
  if (PROFILES["The Rock"]) PROFILES["The Rock"].facts.push({"cat": "暮らし", "t": "ロックは入場前の稽古でも気さくだった", "b": "ザ・ロックは、リングでは目の合図だけで間を作ってくれた人だと、オースティン・セオリーが話している。ピープルズ・エルボーのとき脱げた自分の靴を、客席に投げられたのがいまも悔しいと笑っている。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で、オースティン・セオリーの話（字幕を全文確認）", "src": [["番組のYouTube（31:56〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=1916s"]], "by": "第三者の話"});
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "トリプルHの「いつも全開」という考え方", "b": "トリプルHは、その場しのぎで済ませず、いつも最高を目指そうと選手に言い続けていると、オースティン・セオリーが話している。", "sp": "オースティン・セオリー", "d": "2024-11-07", "how": "クリス・ヴァン・ヴリートの番組で、オースティン・セオリーの話（字幕を全文確認）", "src": [["番組のYouTube（1:05:32〜）", "https://www.youtube.com/watch?v=pU89aflaRn4&t=3932s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-pU89aflaRn4", d: "2024-11-07", show: "ext", who: ["Austin Theory"], t: "オースティン・セオリーの回　夢を信じ続けた27歳のこれまでと今", lead: "クリス・ヴァン・ヴリートの番組に出た約75分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Austin Theory"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-pU89aflaRn4").map((x) => [x.t, x.b, x.sp])), open: ["同席者や聞き手の話は除いた。", "映画の出演作や一部の年代の話は本人も記憶があいまいなため、細部は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=pU89aflaRn4"]] });
  if (!ROSTER.find((r) => r[1] === "Giulia")) ROSTER.push(["ジュリア", "Giulia", "lg", "スターダム出身の人気選手", "", "", ""]);
  if (!PROFILES["Giulia"]) PROFILES["Giulia"] = { lead: "母語は日本語で、英語は勉強中。笑顔でアメリカ暮らしを楽しみ、どの相手とも戦いたいと話す前向きな人柄が伝わる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Giulia"]], moves: [], facts: [] };
  if (PROFILES["Giulia"]._weak) { PROFILES["Giulia"].lead = "母語は日本語で、英語は勉強中。笑顔でアメリカ暮らしを楽しみ、どの相手とも戦いたいと話す前向きな人柄が伝わる。"; delete PROFILES["Giulia"]._weak; }
  PROFILES["Giulia"].facts.push(...[{"cat": "暮らし", "t": "母語は日本語、英語は勉強中", "b": "ジュリアは第一言語が日本語で、いま英語を練習しているところだという。番組では同席した日本人の元レスラーが言葉の助けに入った。ゆっくり話してもらいながら、持ち前の明るさで会話を楽しんでいた。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（0:51〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=51s"]]}, {"cat": "リングの話", "t": "米国では持久力の練習が中心", "b": "アメリカに来てからは、ランニングなど心肺機能を鍛える練習をいつもしていると話す。日本では筋力を付ける練習が多かったそうだ。リングで長く動くための体づくりに合わせて、練習内容を変えているという。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=192s"]]}, {"cat": "リングの話", "t": "アメリカの試合は難しいが好き", "b": "アメリカ流のレスリングは自分にはとても難しいと感じているという。それでも、即興の要素が多いところが好きだと話す。日本とはスタイルがまったく違うそうだ。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（3:59〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=239s"]]}, {"cat": "リングの話", "t": "日米で客席の雰囲気が違う", "b": "日本の観客は静かで、敬意をもって真剣に見る人が多いと話す。アメリカの観客はもっと楽しんで盛り上がり、エンターテインメントとして見るという。ジュリアは、リングで観客を楽しませる役割も当然好きだと話している。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（4:00〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=240s"]]}, {"cat": "暮らし", "t": "オーランドの暮らしが心地よい", "b": "アメリカが大好きだと話す。毎日のように誰かが気軽にあいさつしてくれる人の近さが魅力で、日本はもう少し落ち着いた雰囲気だという。街や建物のスケールが大きいところも気に入っているそうだ。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=338s"]]}, {"cat": "リングの話", "t": "目標は全員と戦って王者になること", "b": "育成ブランドの女子王座を目指していて、同じ場所の選手全員と戦いたいと話す。王座にこだわる理由を聞かれると、レスラーだからと答えた。一軍の番組でも同じ気持ちだが、肩書きより常に自分のベストを出すことが大事だという。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（6:31〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=391s"]]}, {"cat": "リングの話", "t": "ステファニー・ヴァケールとは仲良し", "b": "同じ時期に注目を集めたステファニー・ヴァケールとは、リングの外でも毎日いっしょにいる友だちだと話す。対戦する可能性も出てきたが、戦ってみたいと前向きだという。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=487s"]]}, {"cat": "リングの話", "t": "戦ってみたい日本の選手たち", "b": "日本出身の選手と戦いたい気持ちが強いと話す。その中の一人については、大ファンだとも語った。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（9:41〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=581s"]]}, {"cat": "好きなもの", "t": "かっこいい英語を教わる場面", "b": "聞き手に「かっこいい英語を教えて」と頼み、決め台詞を教わった。眼鏡を借りてその台詞を口にし、スタジオを沸かせたという。", "sp": "ジュリア", "d": "2024-11-20", "how": "Busted Open Podcastの番組で（字幕を全文確認）", "art": "ext-z_i3N8fqoZc", "src": [["番組のYouTube（10:29〜）", "https://www.youtube.com/watch?v=z_i3N8fqoZc&t=629s"]]}]);
  ARTICLES.push({ id: "ext-z_i3N8fqoZc", d: "2024-11-20", show: "ext", who: ["Giulia"], t: "ジュリアの回　アメリカ暮らしと日米のちがい", lead: "Busted Open Podcastの番組に出た約13分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Giulia"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-z_i3N8fqoZc").map((x) => [x.t, x.b, x.sp])), open: ["番組の聞き手と日本人ゲストの発言は区別して省いた。", "対戦したい選手の名前は、字幕が崩れていて確信が持てないため載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=z_i3N8fqoZc"]] });
