  PROFILES["Kane"].facts.push(...[{"cat": "暮らし", "t": "郡長に立候補したきっかけ", "b": "地元の郡の首長を務めるケインは、立候補の理由を「地域に良い影響を与えたかったから」と話す。昔から政治や行政に少し関心があったという。ある朝ふと「やってみたら面白そうだ」と思いついたのが始まりだそうだ。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=0s"]]}, {"cat": "リングに来るまで", "t": "大学フットボールとひざのけが", "b": "ケインは大学でフットボールをしていたが、ひざをけがして進路に迷ったと話す。昔からプロレスのファンで、自分にはそれを仕事にできる素質があると考えたという。この道に入って「思ってもみなかった人生を送れた」と振り返っている。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=93s"]]}, {"cat": "家族", "t": "「何でもできる」と教えた両親", "b": "ケインの両親は、あきらめさえしなければ何でもできると子どもたちに教えていたという。1970年代に育ち、景気が良くない苦しい時期もあったが、家族でやり過ごしたそうだ。つまずいても「明日がある」と励ましてくれる親だったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（2:20〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=140s"]]}, {"cat": "リングに来るまで", "t": "電波とおばあちゃんの家で見たプロレス", "b": "ケインはミズーリ州北東部の人口300人ほどの町で育った。ケーブルテレビがなく、風向きが良い土曜の夜だけ隣州のプロレス中継が映ったという。月に一度、祖母の家があるセントルイスへ行き、会場で名門団体の興行を見るのが楽しみだったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（3:08〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=188s"]]}, {"cat": "リングに来るまで", "t": "初めての大会と、納屋でのリング修行", "b": "初めて見に行った大会でホーガンの入場に会場が揺れ、「これがやりたい」と思ったという。友人のマークと一緒に地元の団体に入り、最初の練習場は納屋の干し草置き場に組まれたリングだったそうだ。その後ジェフ・ジャレットの教室や地方団体を経て、マレンコの道場にも通ったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（4:43〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=283s"]]}, {"cat": "暮らし", "t": "ダッジ・ディプロマットで12時間の旅", "b": "ケインは愛車のダッジ・ディプロマットで、セントルイスからタンパまで約12時間運転して移動した。道中ずっと「タンパまで持ってくれ」と祈っていたそうだ。その車はさらに3、4年乗り続けたと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（6:21〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=381s"]]}, {"cat": "リングに来るまで", "t": "コーネットが付けた名前と好調な時期", "b": "プエルトリコの後、ケインはジム・コーネットの団体で「ユナボマー」という名前で戦った。コーネットが響きを気に入って付けたもので、特別な意味はなかったという。この時期の試合ぶりをオースティンに褒められ、アンダーテイカーとも当時から馬が合ったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（9:30〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=570s"]]}, {"cat": "リングの話", "t": "歯医者の役を告げられた日", "b": "ビンス・マクマホンに「歯医者は怖いか」と聞かれ、のちに歯医者キャラの案だと明かされたそうだ。ケインはうれしさと不安が一度にきて、帰りの飛行機で「どうやって演じるのか」と悩んだという。衣装には名前が歯で綴られていて、入場曲も歯医者のドリルだったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（11:08〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=668s"]]}, {"cat": "リングの話", "t": "キャラの重さで自信を失った時期", "b": "ケインは当時、ブレット・ハートやアンダーテイカーの試合をテレビで見ては「自分は何をすればいいのか」と迷っていたという。キャラクターのせいで自信がすっかり抜けてしまったと話す。ビンスはこの役を成功させたがっていたが、自分には噛み砕けなかったそうだ。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（13:38〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=818s"]]}, {"cat": "リングの話", "t": "次の役で自信が戻った", "b": "ケインによると、歯医者の役を経験したことで怖気づく気持ちが消え、次のキャラでは自信を取り戻せたという。ビンスも「あの若者は見込みがある」と見たようで、そのおかげで会社に残れたと話す。遅刻せず、頼れる人間であることが大事で、代わりはいくらでもいるのでプロらしくあるべきだとも語っている。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（16:03〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=963s"]]}, {"cat": "リングの話", "t": "ケインの衣装案と、ビンスの説明", "b": "最初に見た衣装案は、精神病院から逃げた殺人鬼風を想像していた自分とは違うヒーロー風だったという。ケインが電話で率直に意見を伝えると、ビンスは「彼は自分の劣等感を埋めるためにヒーローの格好をしている」と説明したそうだ。その一言で役の見え方がまるで変わったと話す。ビンスは「ケインの大事な言葉はクールだ」とも言っていたという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（18:34〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=1114s"]]}, {"cat": "リングの話", "t": "革のマスクを作った職人たち", "b": "ケインのマスクと衣装は、ニューヨークの衣装職人テリー・アンダーソンの夫婦が作っていたという。頭の型を取って作る革製で、今でも一番気に入っている衣装だと話す。汗で形が崩れ、赤と黒のはずが最後は茶色っぽくなり、4、5か月で替えたそうだ。目の部分は、マリリン・マンソンの話から出たアイデアだったという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（21:00〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=1260s"]]}, {"cat": "リングの話", "t": "顔が見えない分、体で見せる", "b": "マスクの下でも表情は作っていたが、顔が見えない分、動きを大きくして体の言葉で伝えたとケインは話す。顔の表情そのものは、マスクの下でも続けていたそうだ。マスクをかぶると、考えなくても体が動くような感覚があったそうだ。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（23:27〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=1407s"]]}, {"cat": "好きなもの", "t": "首をかしげる癖は愛犬から", "b": "ケインの代名詞になった首をかしげるしぐさは、飼っていたセント・バーナードのアニーから思いついたという。犬が首を左右に傾けるのを見て試したところ、観客が大きく反応したそうだ。何を考えているのか分からない不気味さが出て、ブルースに「20分のマイクより効く」と言われたと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（24:14〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=1454s"]]}, {"cat": "暮らし", "t": "デビュー当日に友人の車が煙を噴いた", "b": "デビューの大会はセントルイスで、地元育ちのケインは数日前に現地入りしていたという。会場へ向かう途中、友人マークの古い車のカセットから煙が上がり、道端で立ち往生したそうだ。携帯電話のない時代で、友人の知り合いに拾ってもらい何とか間に合ったが、そのときは本当に焦ったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（26:43〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=1603s"]]}, {"cat": "リングの話", "t": "レッスルマニア14の入場に圧倒された", "b": "リングで待つケインは、トーチを持った一団を従えて歩くアンダーテイカーの入場に、心臓が破れそうなほど緊張したという。マネージャーに「発作を起こすぞ」と言われたほどで、観客が2万人でも誰もいなくても同じ迫力だったと話す。あの試合でトゥームストーンを2度返したことが、自分を押し上げたと振り返っている。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（35:32〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2132s"]]}, {"cat": "リングの話", "t": "アンダーテイカーはずっと味方だった", "b": "ケインは、団体に入れたのはアンダーテイカーが推薦してくれたおかげだと思っているという。歯医者の役でくさっていた時期には、結果を気にせず見せ続けろと励まされたそうだ。ケインというキャラは彼が後押ししたから続いたと話し、迷った時期も「楽しめて動けるなら続けろ」と背中を押されたという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（38:36〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2316s"]]}, {"cat": "家族", "t": "母の「私がケインを育てた」の看板", "b": "ケインの母は、息子の試合を見に来たとき「I raised Cane」と書いた看板を掲げていたという。プロレスラーになりたいと伝えたとき、両親は戸惑ったが、いつも応援してくれたそうだ。両親が試合を見に来た回数は多くないと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（43:21〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2601s"]]}, {"cat": "体のこと", "t": "ぶどう球菌感染で3日半入院", "b": "ケインはオースティンとの大一番の少し前、試合後にふるえが止まらなくなって救急車で運ばれたという。右腕のぶどう球菌感染で、病院に3日半入院したそうだ。入院中も「あの試合に出なければ」と考えていたと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（44:08〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2648s"]]}, {"cat": "リングの話", "t": "王座を失った夜こそ思い出に残る", "b": "ケインは、王座を勝ち取ったことより、翌日にオースティンへ王座を戻した夜のほうが重要だったと話す。あの夜は人生で最も熱狂的な会場で、煙の立ち込める満員の客席が映画のようだったという。この流れが、のちのアンダーテイカーとの兄弟タッグにつながったとも語っている。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（53:46〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=3226s"]]}, {"cat": "好きなもの", "t": "1対1よりタッグ戦が好き", "b": "ケインは、単独の試合より、むしろタッグ戦のほうが好きだと話す。変えられる組み合わせが多く、ヒーロー側の「ホットタッグ」にしかない盛り上がりがあるからだそうだ。王座戦でも、三つ巴などより、1対1の戦いが好みだという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（57:04〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=3424s"]]}, {"cat": "暮らし", "t": "移動を全部引き受けた付き人", "b": "ケインによると、マネージャーのポール・ベアラーは宿の手配や運転まで引き受け、試合以外の心配を一切させなかったという。サンディエゴでは、体調が悪いというポールを乗せてケインが覆面姿で運転したそうだ。会場前の行列を通る途中でポールが窓から「ケインが運転してるぞ」と叫び、これ以上ないほど恥ずかしかったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（57:50〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=3470s"]]}, {"cat": "リングの話", "t": "マスクを外す決断", "b": "ケインは、マスクで顔が隠れて表現に限界を感じ、キャラを一新したくなったという。会社でそう考えたのはビンスとケインの二人だけで、周りは「うまくいっているのに」と反対したそうだ。外してみると、顔が見える分、怒りがそのまま伝わる新しいキャラになったと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（1:00:21〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=3621s"]]}, {"cat": "家族", "t": "長い髪を切って妻を驚かせた", "b": "ケインは、妻が長い髪を気に入っていたので、驚かせたくて事前に話さなかったという。実際に驚かれたものの、試合後の会話はあまりうまくいかなかったそうだ。結局その髪型は1日ほどで丸刈りにして、子どもの迎えもあるので無理だとビンスに伝えたと話す。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（1:03:39〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=3819s"]]}, {"cat": "リングの話", "t": "コメディ路線は燃え尽き防止にもなった", "b": "同じ暗いキャラを15年以上続けるうちに、ケインは退屈さを感じていたという。怒りの管理を扱った寸劇などのコメディは、これまでと正反対で新鮮だったと話す。自分にもユーモアや間の取り方があると見せられたのが良かったそうだ。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（1:10:49〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=4249s"]]}, {"cat": "体のこと", "t": "今も古傷のひざだけが気になる", "b": "ケインは、大きなけがはほとんどなく、フットボール時代に痛めたひざだけが今も気になると話す。上腕の腱を切って数か月休んだ時期はあったが、体の調子は良いそうだ。現在も楽しみながら時々リングに上がっており、アンダーテイカーと組んで夢のカードを戦えたこともあるという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Z8cJypSRwzE", "src": [["番組のYouTube（1:18:08〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=4688s"]]}]);
  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "足首を痛めたまま戦っていた", "b": "アンダーテイカーは、オースティンとの大一番の頃に足首を骨折していて、足を引きずって入場していた、とケインが話している。テレビ収録で起きたことが原因だったと聞いたという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ケインの話（字幕を全文確認）", "src": [["番組のYouTube（48:13〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2893s"]], "by": "第三者の話"});
  if (PROFILES["Mick Foley"]) PROFILES["Mick Foley"].facts.push({"cat": "暮らし", "t": "檻から落ちたとき本気で心配した", "b": "ミック・フォーリーはケインと一緒に移動する仲のいい友人で、檻の天井が抜けて落ちたときはケインは「死んだ」と思ったと、ケインが話している。無事に戻ってきたときは何より安心したそうだ。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ケインの話（字幕を全文確認）", "src": [["番組のYouTube（45:43〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=2743s"]], "by": "第三者の話"});
  if (PROFILES["Pete Rose"]) PROFILES["Pete Rose"].facts.push({"cat": "暮らし", "t": "何でも引き受ける一流のプロ", "b": "ピート・ローズは、野球殿堂にいなければ最高の悪役になれたと思う人で、バットをケインにくれたこともあった、とケインが話している。何でも引き受けてショーを盛り上げようとする、一流のプロだったという。", "sp": "ケイン", "d": "2024-11-23", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ケインの話（字幕を全文確認）", "src": [["番組のYouTube（1:17:16〜）", "https://www.youtube.com/watch?v=Z8cJypSRwzE&t=4636s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Z8cJypSRwzE", d: "2024-11-23", show: "ext", who: ["Kane"], t: "ケインの回　仮面の下の素顔と、25年の歩み", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約79分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kane"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Z8cJypSRwzE").map((x) => [x.t, x.b, x.sp])), open: ["Isaac Yankemの時期の試合内容、インフェルノ戦、ピート・ローズの寸劇などの試合・演出の細部は、項目数の都合で一部を省いた。", "ケインが推薦者や制作側として名前を挙げた人物のうち、字幕で聞き取りにくい箇所は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Z8cJypSRwzE"]] });
  if (!ROSTER.find((r) => r[1] === "Laredo Kid")) ROSTER.push(["ラレド・キッド", "Laredo Kid", "lg", "空中戦の名手", "", "", ""]);
  if (!PROFILES["Laredo Kid"]) PROFILES["Laredo Kid"] = { lead: "国境の街で育ち、兄と二人でリングを目指した空中戦の名手。命に関わる大けがや兄の死を乗り越え、「何も私を止められない」を信条に歩んできたという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Laredo%20Kid"]], moves: [], facts: [] };
  if (PROFILES["Laredo Kid"]._weak) { PROFILES["Laredo Kid"].lead = "国境の街で育ち、兄と二人でリングを目指した空中戦の名手。命に関わる大けがや兄の死を乗り越え、「何も私を止められない」を信条に歩んできたという。"; delete PROFILES["Laredo Kid"]._weak; }
  PROFILES["Laredo Kid"].facts.push(...[{"cat": "家族", "t": "国境の街ヌエボ・ラレドの出身", "b": "メキシコ北東部、米国との国境にあるヌエボ・ラレドで生まれ育ち、両親やきょうだいも同じ街の出身だという。国境の街なので、アメリカの団体とメキシコの団体の両方の試合をテレビで見て育ったそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（2:18〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=138s"]]}, {"cat": "リングに来るまで", "t": "新聞広告と兄の誘いで入門", "b": "新聞でプロレス教室の広告を見つけ、兄に誘われて一緒に通い始めたという。もともとは兄のほうが熱心なファンで、最初は趣味のつもりだったと話す。子どものころから父の勧めで武道を続けていた。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（3:04〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=184s"]]}, {"cat": "リングに来るまで", "t": "16歳で「エクステルミナドール」として初めてリングへ", "b": "16歳ごろから地元で別のリングネームを名乗り、アマチュアとして試合を始めたという。地元の興行主や、叔父が所属していた団体の関係者に引き上げられ、少しずつ名前を知られていったと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（4:38〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=278s"]]}, {"cat": "リングに来るまで", "t": "無観客の「テスト」で今のリングネームを授かる", "b": "地元の有力な興行主に呼ばれ、観客のいない会場で兄と二人で試合を見せたという。合格となり、現在のリングネームと兄の覆面名をもらい、衣装も一式作ってもらったそうだ。2004年に本格デビューし、兄も同じ日にデビューした。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（5:25〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=325s"]]}, {"cat": "リングに来るまで", "t": "デビュー戦で伝説的な先輩と対戦", "b": "デビューの場で、メキシコ・プロレス界の大物とも組み合ったという。先輩は技を譲らず見せ場を作らせてくれ、緊張する自分を落ち着かせてくれたそうで、テレビで見ていた人たちと同じリングに立ったことに感動したと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（7:02〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=422s"]]}, {"cat": "家族", "t": "亡き兄の名を腕に彫っている", "b": "兄は覆面レスラーとして活動していて、その名を腕のタトゥーにしているという。約4年前に事故で亡くなった。ラスベガス遠征から戻った直後に弟から連絡を受けたと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（8:40〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=520s"]]}, {"cat": "体のこと", "t": "兄の訃報の日は試合に出なかった", "b": "兄の死を知った日、団体の幹部から「上がれるなら上がっていい、無理なら帰っていい」と言われ、地元に帰されたという。頭が真っ白で試合どころではなかったと話す。キャリアで最も重い出来事のひとつで、そこから「あきらめずに進む」という考え方を大切にしているそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（9:28〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=568s"]]}, {"cat": "リングに来るまで", "t": "学業と遠征の両立が難しくなる", "b": "大学に通いながらメキシコシティの団体の試合に出ていたが、長距離バスで16時間かけて往復するのは厳しかったという。兄が先にやめ、自分は2007年の日本ツアーの話をきっかけに大学をやめて上京した。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（11:04〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=664s"]]}, {"cat": "家族", "t": "父の「やるなら世界一になれ」", "b": "大学をやめると伝えた時、技術者だった厳しい父は「機会は一度きり。やるなら世界一になれ」と背中を押してくれたという。アイスキャンディー売りでも世界一を目指せ、というたとえで励まされたと話す。その後、父はマネージャー役も務めた。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（12:37〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=757s"]]}, {"cat": "リングに来るまで", "t": "米大手団体のトライアウトに呼ばれる", "b": "誕生日に父から「アメリカの大手団体が試験をしたいと言っている」と伝えられ、冗談だと思ったという。フロリダの練習施設で練習し、興行にも出場した。残れなかったが、人としても選手としても大きく学んだと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（13:27〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=807s"]]}, {"cat": "リングの話", "t": "亡き先輩との激しい試合", "b": "亡くなった実力派の先輩とは、互いに本気で打ち合う試合をしたという。周囲から険悪に見えたほどだが、報酬分の仕事をしたいだけだったと話す。この先輩に鍛えられて自分も打たれ強くなったと感謝している。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（16:00〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=960s"]]}, {"cat": "リングの話", "t": "急きょ先輩の衣装を着てリングに上がった夜", "b": "2009年、同じ衣装で現れるはずの先輩が会場に着かず、満員の観客がざわついたため、代役として入場したという。先輩の覆面と衣装を着け、相手に殴られる場面だけを演じた。翌日その先輩の訃報を聞き、鳥肌が立ったと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（16:45〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1005s"]]}, {"cat": "リングの話", "t": "王座にあと一歩届かなかった悔しさ", "b": "ライバルの反則の連発に屈し、あと一歩で王座を逃したことがあるという。相手の悪知恵やずる賢さに経験で負けたと振り返り、また挑戦するつもりだと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（20:07〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1207s"]]}, {"cat": "暮らし", "t": "リアリティ番組で5か月間の共同生活", "b": "同じ団体の人気選手の推薦でアスリート対抗のリアリティ番組に参加し、ドミニカ共和国で撮影したという。携帯電話もなく外界と断絶され、半年近く子どもたちの様子が分からず泣いたこともあったそうだ。負けた週は粗末な小屋で床に寝る生活だったと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（20:55〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1255s"]]}, {"cat": "リングの話", "t": "プロレスラーもアスリートだと示したかった", "b": "番組で五輪級の選手と競い、プロレスは「ただのショー」ではないと見せたかったという。番組をきっかけにプロレスを知った人が増えたと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（21:45〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1305s"]]}, {"cat": "好きなもの", "t": "番組出演後にボディビルへ挑戦", "b": "番組でほかの競技の選手から刺激を受け、ボディビルの大会に出たという。35歳前後でタマウリパス州の大会に出場した。リングでの見た目も良くなり、子どもたちにも自慢の父になれたそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（29:05〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1745s"]]}, {"cat": "リングの話", "t": "折れた足で臨んだ覆面を賭けた試合", "b": "かつて足を骨折した復帰後、檻の中の試合で飛び技を出して同じ場所を再び痛めたという。覆面を賭けた展開を相手に迫られたが、足の状態を理由に会場の係員に頼んで場外へ逃げた。観客にはブーイングされ、悔しい思い出になったと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（30:47〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1847s"]]}, {"cat": "体のこと", "t": "腸に穴が開き命の危機に", "b": "タイトルを奪った試合のあと、控室で急に気分が悪くなり、救急車で運ばれて緊急手術を受けたという。小腸に穴が開き、血液にも影響が出て、死ぬかもしれないと感じたそうだ。約6か月休んだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（34:53〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=2093s"]]}, {"cat": "体のこと", "t": "傷跡に落ち込み、引退も考えた", "b": "手術の傷跡が残り、ボディビルで鍛えた体に目立つ線が入ったことで気持ちが沈んだ時期があるという。家族が泣く姿を見て引退も頭をよぎったが、結局リングへ戻ったと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（37:49〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=2269s"]]}, {"cat": "家族", "t": "父がマネージャーとして道を開いてくれた", "b": "所属団体を離れて4年間はフリーで活動し、仕事の取り方が分からず苦労したという。父がアメリカやプエルトリコの興行主に何度も交渉してくれたと話す。父は大きな試合の前に亡くなったが、活躍は見届けてくれたと信じている。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（38:00〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=2280s"]]}, {"cat": "リングの話", "t": "元の団体で若手を育てるコーチ役に", "b": "大規模大会では、最初の数試合の進行や若手への助言を任されたという。「エゴや嫉妬は脇に置いて働こう」と若手に伝えたと話す。当日の一戦は夜の名試合のひとつに挙がったそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（48:34〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=2914s"]]}, {"cat": "リングの話", "t": "アメリカのテレビ向けは「キャラ」と「時間」が大事", "b": "現在所属するアメリカの団体では、空中技よりも人物像や見せ方、カメラへのポーズを重視されると話す。10分の試合なら、CM前に見せ場を置き、CM明けにすぐ盛り上げるなど、時間配分が厳密だという。台本と即興を両立させるのがプロレスの技だと語る。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（54:52〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=3292s"]]}, {"cat": "リングの話", "t": "「ダンスの3曲目」にたとえる試合の組み立て", "b": "試合の1本目は相手と客を探り、2本目で動きを増やし、3本目で空中技や決着で盛り上げる、と考えているという。観客層によって好みが違うので、相手や会場に合わせて何でも演じ分けられる「万能型」でありたいと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（58:49〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=3529s"]]}, {"cat": "家族", "t": "二人の子どもと、仕事人間だった祖父", "b": "15歳の娘と17歳の息子がいて、離婚後も子どもたちを中心に暮らしてきたという。祖父は鉄道の仕事で片腕を失ったが働き続け、息子たちを学校に出したそうだ。その祖父から「仕事が人を生かす」と教わった。決め台詞の「何も私を止められない」は父から受け継いだ言葉だと話す。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（1:06:53〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=4013s"]]}, {"cat": "暮らし", "t": "貯金はしている", "b": "収入が落ちる12月などの閑散期に備え、貯金はしていると話す。レスラーにとって貯金は大切だと考えている。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（1:10:01〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=4201s"]]}, {"cat": "暮らし", "t": "プロレスを恨んだことはない", "b": "試合で子どもと過ごす時間が減っても、プロレスを責めたことはないという。生活を支えてくれたもので、情熱を100%注ぐべきだと話す。死を覚悟した時も自分の歩みに満足していたそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（1:10:50〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=4250s"]]}, {"cat": "体のこと", "t": "けがを重ねても、観客の声で体が動く", "b": "けがから学んだつもりでも、試合になると観客の声とアドレナリンで大技に走ってしまうという。「分かっていてまたやってしまう」と笑って話す。家族からは止められるが、この情熱は何にも代えがたいそうだ。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で（字幕を全文確認）", "art": "ext-HwPU3WbjuC8", "src": [["番組のYouTube（1:14:52〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=4492s"]]}]);
  if (PROFILES["Abismo Negro"]) PROFILES["Abismo Negro"].facts.push({"cat": "暮らし", "t": "アビスモ・ネグロの荒っぽい人柄", "b": "アビスモ・ネグロは試合でも日常でも気性が激しく、事務所の外でほかの選手と殴り合って戻ってきたこともあったと、ラレド・キッドが話している。若い頃のキッドに容赦なく攻めたが、試合後は優しい言葉をかけてくれたという。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で、ラレド・キッドの話（字幕を全文確認）", "src": [["番組のYouTube（19:17〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1157s"]], "by": "第三者の話"});
  if (PROFILES["Silver King"]) PROFILES["Silver King"].facts.push({"cat": "暮らし", "t": "シルバー・キングの昔ながらのトレーニング", "b": "シルバー・キングはトランプを引いて腕立てとスクワットを交互にこなす昔ながらの練習を好み、ジムに行けない遠征先でも付き合ってくれたと、ラレド・キッドが話している。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で、ラレド・キッドの話（字幕を全文確認）", "src": [["番組のYouTube（41:16〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=2476s"]], "by": "第三者の話"});
  if (PROFILES["Dragon Lee"]) PROFILES["Dragon Lee"].facts.push({"cat": "暮らし", "t": "ドラゴン・リーが番組出演を推薦", "b": "リアリティ番組の出演は、ドラゴン・リーが制作側にラレド・キッドを推してくれたのがきっかけだったと、ラレド・キッドが話している。親しい仲ではなかったが、見返りなしで助けてくれる人だと感謝している。", "sp": "ラレド・キッド", "d": "2024-11-25", "how": "ラティーノ・ラバーのチャンネルの番組で、ラレド・キッドの話（字幕を全文確認）", "src": [["番組のYouTube（20:55〜）", "https://www.youtube.com/watch?v=HwPU3WbjuC8&t=1255s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-HwPU3WbjuC8", d: "2024-11-25", show: "ext", who: ["Laredo Kid"], t: "ラレド・キッドの回　兄の死と大けがを越えて", lead: "ラティーノ・ラバーのチャンネルの番組に出た約77分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Laredo Kid"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-HwPU3WbjuC8").map((x) => [x.t, x.b, x.sp])), open: ["聞き手（ラティン・ラバー）の話や、仲間の死の場面の詳細は省いた。団体名・人名は自動字幕で崩れた箇所があり、確信の持てないものは載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=HwPU3WbjuC8"]] });
  if (!ROSTER.find((r) => r[1] === "Ivar")) ROSTER.push(["アイバー", "Ivar", "lg", "ウォー・レイダーズの一員", "", "", ""]);
  if (!PROFILES["Ivar"]) PROFILES["Ivar"] = { lead: "首の大けがで引退寸前まで追い込まれながら、相棒とウォー・レイダーズに復帰したアイバー。大柄でも空を飛び、10年以上ひげを剃らない素顔を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ivar"]], moves: [], facts: [] };
  if (PROFILES["Ivar"]._weak) { PROFILES["Ivar"].lead = "首の大けがで引退寸前まで追い込まれながら、相棒とウォー・レイダーズに復帰したアイバー。大柄でも空を飛び、10年以上ひげを剃らない素顔を語る。"; delete PROFILES["Ivar"]._weak; }
  PROFILES["Ivar"].facts.push(...[{"cat": "体のこと", "t": "休暇中に腕が上がらず、首の異変が発覚", "b": "大きな試合の前に首を痛め、試合の後半で右腕の力が抜けたという。その後の休暇で動物とふれあう体験中、腕を上げられないことに気づき、すぐ検査を受けた。結果を見た医療陣からは、現役を終える可能性まで伝えられたと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=94s"]]}, {"cat": "体のこと", "t": "引退と言われた5日後に流れが変わった", "b": "すでに首の骨を2か所つなぐ手術を受けており、さらに追加でつなげば現役は終わりだと言われていたという。ところが5日後、専門の外科医が画像を自分で確認し、手術なしでリハビリできる見込みがあると判断した。医師からは「大きな弾丸をかわした」と何度も言われたそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（3:08〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=188s"]]}, {"cat": "体のこと", "t": "23年の消耗と、数えきれない「九死に一生」", "b": "助かったのは運で、筋肉量のおかげではないと話す。23年間で体にはかなりの負担がかかっており、最初の首のけがも、何千回もやった動きの中で起きた不運な事故だったという。命は9つどころか、もう12個目くらいだと冗談めかしている。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（5:34〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=334s"]]}, {"cat": "体のこと", "t": "2020年、試合中に一時的なまひを経験", "b": "場外への飛び込み技の最中に顔へ手が当たって頭が後ろに押され、椎間板が脊髄に飛び出したという。数秒間は体の感覚がなくなり、助けを呼ぶ合図の腕のバツ印も、自分では感じられなかったそうだ。救急車では冗談で昇給をお願いしたが、通らなかったと笑っている。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（5:34〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=334s"]]}, {"cat": "体のこと", "t": "感染症対策の最中で、誰も病院に入れなかった", "b": "当時は救急車に誰も同乗できず、駆けつけた相棒や審判、スタッフも病院に入れなかったという。ただでさえ大変な出来事が、世の中の状況のせいでさらに重く感じられたと振り返る。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（7:58〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=478s"]]}, {"cat": "体のこと", "t": "つなぐ手術しか選べなかった", "b": "首の手術は避けたほうがいいという声が多いが、自分には選択肢がなかったと話す。脊髄が圧迫されたままだと現役どころか日常生活にも響くところで、遠方の主治医のもとへ行く許可を取るのにも苦労したそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（9:32〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=572s"]]}, {"cat": "体のこと", "t": "残った神経の痛みと、ヨガの支え", "b": "手の神経の損傷と痛みは一生残るが、首の動きはほぼ戻り、腕の力も回復したという。可動域を保てているのはヨガのおかげだと話す。痛みが強い日と感じない日があり、全体としては調子がいいそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（10:18〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=618s"]]}, {"cat": "リングの話", "t": "本来のウォー・レイダーズに戻れた", "b": "単独で活動していた時期、重たいバイキングの演出を少しずつ減らす話があったという。再びけがをしたあと、チームとして戻らないかと連絡が来た。素の自分でいられるのは久しぶりだが、バイキングの文化は今も自分たちの一部だと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（11:06〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=666s"]]}, {"cat": "リングの話", "t": "昔の名前に戻さなかった理由", "b": "以前の名前に戻す案もあったが、約5年間の実績を消したくなかったという。単独の活動も、タッグ王座も、他のチームとの抗争も、すべて自分たちの歴史だと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（13:31〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=811s"]]}, {"cat": "リングの話", "t": "二人とも「死」を見たチーム", "b": "自分は首のけがで一時的にまひし、相棒のエリックは2014年のバイク事故で命を落としかけたという。いつ終わってもおかしくないと知ったので、毎回の試合が最後のつもりで全力を出すと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（15:55〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=955s"]]}, {"cat": "リングの話", "t": "大きな体で空中技をやる理由", "b": "デビューは2001年で、当時は大柄な選手は大柄らしく戦うのが決まりだったという。練習前のウォームアップでは空中技をふざけて試していたが、本番では封印していた。業界が変わっていくのを見て、安全にできるなら自分もやろうと、型を破ることにしたそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（16:41〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1001s"]]}, {"cat": "リングの話", "t": "一番盛り上がるのは、ロープに登るとき", "b": "観客が一番驚く技は月面宙返りだが、状況によって別の技のこともあるという。大きな体でロープに登っていくとき、観客が期待を高めるのがいいと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（19:08〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1148s"]]}, {"cat": "リングに来るまで", "t": "エキストラとして出ていた時期", "b": "2003年から2010年ごろまで、番組にエキストラとして何度も出たという。客席に紛れて警備役をしたり、大型選手の試合で重い棺を運んだりした。試合後に経営トップから握手されて、仕事がもらえると思い込んだ話も笑いながら語っている。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（22:18〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1338s"]]}, {"cat": "リングに来るまで", "t": "地元の道場とのつながり", "b": "練習していたニューハンプシャーの道場には、WWEの採用担当者がたびたび来ていたという。師のマイク・ホロウは、育成施設の前の段階として使ってもらおうと長年働きかけていた。その道場が今、公式の育成プログラムに加わったことを、アイバーは心から喜んでいる。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（24:37〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1477s"]]}, {"cat": "リングの話", "t": "「うますぎる」と言われた過去", "b": "若い頃に「うますぎる」と言われ、最初は意味が分からなかったという。のちに、見た目に対して動きが滑らかすぎると魅力が薄れる、もっと荒々しく迫力が欲しいという意味だと理解したそうだ。いまもそのバランスを探っていると話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（27:46〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1666s"]]}, {"cat": "リングに来るまで", "t": "2011年、肩の手術と落ち込み", "b": "肩の手術で、関節の縁の組織が6割以上壊れていたことが分かったという。何度も失敗してきたこともあり、深く落ち込んだ。それでも爪痕を残したいと考え、別の団体に挑戦すると決めたそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（28:36〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1716s"]]}, {"cat": "リングに来るまで", "t": "41キロの減量とひげの始まり", "b": "体重は約160キロあったが、ジュース断食とリハビリで約41キロ落としたという。ひげは2011年12月1日から伸ばし始め、首の手術のとき以外は整えていないそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（30:17〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1817s"]]}, {"cat": "リングに来るまで", "t": "腰の防具が、バイキングの道への入り口に", "b": "減量後のたるんだお腹を隠すために巻いた腰の防具が、バイキング文化に入るきっかけになったという。2014年の新人選抜大会には直前に呼ばれ、決勝でエリックを破って優勝した。その後タッグを組み、二人ともバイキング好きだと知って意気投合したそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（31:06〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1866s"]]}, {"cat": "リングに来るまで", "t": "二人でタッグに懸けると決めた", "b": "体型を理由に大きな団体で通用しなかった二人は、タッグに絞って成功を目指すと決めたという。小さな団体から始めて日本の団体でも活動し、その後WWEから声がかかった。単独で上を目指す気持ちはいったん脇に置いたと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（32:45〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=1965s"]]}, {"cat": "暮らし", "t": "ひげは10年以上、剃っていない", "b": "ひげは2011年から伸ばしていて、首の手術のとき以外は整えていないという。長くて、試合のときは束ねるが、遊園地の乗り物では二つに割れて顔に回ることもあると笑っている。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（35:11〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=2111s"]]}, {"cat": "リングの話", "t": "コメディ路線の舞台裏", "b": "感染症対策の時期にコメディ寄りの路線を言い渡され、最初は解雇の前触れではと不安だったという。それでも与えられた役を全力でやろうと決めた。忍者との共演は自分たちの案で、通るとは思っていなかったと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（41:37〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=2497s"]]}, {"cat": "リングの話", "t": "あの抗争が持っていた意味", "b": "当時の経営トップが、登場人物が抗争中も友人でいることにこだわっていたという。途中でその意味に気づき、異なる背景の人たちが友好的に競う姿を見せられたことを誇りに思うと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（43:12〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=2592s"]]}, {"cat": "リングの話", "t": "次の目標はタッグ王座", "b": "取材時点では挑戦者の立場にいるといい、その王座を目指す方向へ進むと話す。大きくて空を飛ぶ自分と、小柄で力の強い相棒という、前例のない組み合わせだと自負している。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（54:37〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3277s"]]}, {"cat": "暮らし", "t": "解雇の波の中で、常に「その後」を考えていた", "b": "感染症対策の時期は解雇が続き、自分たちも次だと毎回覚悟していたという。いつか終わる日のあとをどう生きるか、相棒と何度も話し合ったそうだ。支えにしているのは「役に立つ人であれ」という言葉だと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（55:27〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3327s"]]}, {"cat": "リングの話", "t": "けがのあとの試合の考え方", "b": "医療陣が安全面を細かく見てくれていて、とてもありがたいと話す。やめた技は、最初の首のけがの原因になった場外への飛び込み技だけで、そのほかは工夫して見せ方を調整しているという。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（58:39〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3519s"]]}, {"cat": "暮らし", "t": "毎週、育成施設で大型選手のクラスを指導", "b": "公式の役目ではないが、毎週育成施設で体の大きな新人向けのクラスを見ているという。教えることが励みで、将来は試合の演出を支える仕事と育成の橋渡しをしたいと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（1:00:18〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3618s"]]}, {"cat": "好きなもの", "t": "憧れの大型選手はバンバン・ビガロ", "b": "理想の大柄な選手にバンバン・ビガロを挙げ、ボスマンやヴェイダーの名前も出している。子どもの頃、90年代の初めに見ていた選手で、体の大きさに似合わない動きが印象に残っているそうだ。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（1:01:56〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3716s"]]}, {"cat": "好きなもの", "t": "感謝の三つ目は、日本で通った店の味", "b": "感謝していることを3、2、1の順に挙げ、3番目にロサンゼルスでペッパーランチを食べられることを選んでいる。日本でよく行っていたステーキの店で、アメリカにも増えているのがうれしいと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（1:06:04〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3964s"]]}, {"cat": "家族", "t": "一番の感謝は、妻と家族、友人、ファン", "b": "地元の団体で別れのスピーチをしたとき、見返したい気持ちより、信じてくれた人が正しかったと示したい気持ちになったという。妻や家族、友人、ファンに支えられてきたと話す。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8o8Fz9gXEFU", "src": [["番組のYouTube（1:07:40〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=4060s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "セナと地元の慈善興行", "b": "2008年ごろ、警察官の兄弟を支えるためにジョン・シナが地元の団体で開いた慈善興行に、若い頃のアイバーも出ていたという。当時のWWE王者だったシナが審判を務め、会場が大いに沸いたと、アイバーが話している。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で、アイバーの話（字幕を全文確認）", "src": [["番組のYouTube（47:17〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=2837s"]], "by": "第三者の話"});
  if (PROFILES["Vince McMahon"]) PROFILES["Vince McMahon"].facts.push({"cat": "暮らし", "t": "経営トップの唯一のインディー出演", "b": "その興行には、事前に知らされていなかった当時のWWE経営トップ、ビンス・マクマホンがサプライズで現れたという。インディー団体の興行に出たのはこのときだけのはずだと、アイバーが話している。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で、アイバーの話（字幕を全文確認）", "src": [["番組のYouTube（51:21〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=3081s"]], "by": "第三者の話"});
  if (PROFILES["Erik"]) PROFILES["Erik"].facts.push({"cat": "暮らし", "t": "エリックも首の手術を経験", "b": "相棒のエリックも首の手術を受けており、二人とも大けがから戻ってきたことが、今回の復帰の特別さにつながっていると、アイバーが話している。", "sp": "アイバー", "d": "2024-12-19", "how": "クリス・ヴァン・ヴリートの番組で、アイバーの話（字幕を全文確認）", "src": [["番組のYouTube（14:19〜）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU&t=859s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-8o8Fz9gXEFU", d: "2024-12-19", show: "ext", who: ["Ivar"], t: "アイバーの回　首の大けがと復帰、地元のインディー時代", lead: "クリス・ヴァン・ヴリートの番組に出た約69分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ivar"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-8o8Fz9gXEFU").map((x) => [x.t, x.b, x.sp])), open: ["同じ回の中盤の広告読み上げは除いた。他の選手の解雇の話は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=8o8Fz9gXEFU"]] });
  if (!ROSTER.find((r) => r[1] === "Bret Hart")) ROSTER.push(["ブレット・ハート", "Bret Hart", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Bret Hart"]) PROFILES["Bret Hart"] = { lead: "レスリング一家に育ち、幼いころからリングを見て学んだブレット・ハート。モントリオール事件やレッスルマニア13を、本人の言葉で振り返る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bret%20Hart"]], moves: [], facts: [] };
  if (PROFILES["Bret Hart"]._weak) { PROFILES["Bret Hart"].lead = "レスリング一家に育ち、幼いころからリングを見て学んだブレット・ハート。モントリオール事件やレッスルマニア13を、本人の言葉で振り返る。"; delete PROFILES["Bret Hart"]._weak; }
  PROFILES["Bret Hart"].facts.push(...[{"cat": "暮らし", "t": "ハワイ帰りで、地元は氷点下45度", "b": "ブレットはカルガリーからハワイへ休暇に出かけていたそうだ。ほぼ毎日雨だったというが、地元の氷点下45度の寒さよりはずっとましだったと話す。収録時のカルガリーは凍える寒さで、そこを離れられてうれしかったという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（0:01〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1s"]]}, {"cat": "リングの話", "t": "契約をめぐる不信が発端", "b": "ブレットは、当時の会社が結んだ契約を守ろうとしていなかったと感じていたと話す。社長が他団体との交渉を手伝うと言い出したことにも不信感を抱いたという。ショーン・マイケルズとの確執もあり、事態はこじれていったそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（3:59〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=239s"]]}, {"cat": "リングの話", "t": "敬意のない相手には王座を譲れない", "b": "ブレットは、自分が負けを受け入れると言っても、ショーンは同じことをしないと言い切ったのが決定的だったと話す。契約上、最後の60日は自分に創作面の決定権があったこともあり、そんな相手に王座は渡せないと社長に伝えたという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（5:41〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=341s"]]}, {"cat": "リングの話", "t": "最高の試合にするつもりで入場した", "b": "ブレットは、モントリオールのリングには最高の試合をして会社に最後の一戦を届けるつもりで上がったと話す。前日、レフェリーのアール・ヘブナーに「自分を裏切らないでくれ」と確かめ、誓ってやらないと言われていたという。アールを責めたことは一度もないそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（11:32〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=692s"]]}, {"cat": "暮らし", "t": "14年間、年300日働き続けた", "b": "ブレットは、14年にわたって年に300日ほど、不満を言わずに会社のために働いてきたという。だからこそ、あの夜の仕打ちには裏切られた思いが強かったと話す。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（14:45〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=885s"]]}, {"cat": "リングの話", "t": "社長を殴り、握手で別れた", "b": "ブレットは、控室で社長と向き合い、14年分の思いを込めてアッパーを一発入れたと話す。その拍子に自分の手の骨を折り、相手は気を失ったという。その後ショーンには「試合をありがとう」と握手したが、翌日の番組で悪く言われたそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（20:28〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1228s"]]}, {"cat": "リングの話", "t": "他団体では何も計画がなかった", "b": "ブレットは、移籍した他団体を、組織がめちゃくちゃで先の計画がなかったと振り返る。飛行機で呼ばれても控室で一日待たされ、出番なしで帰されることもあり、次第にやる気をなくしたという。もったいない時間だったと話す。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（27:04〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1624s"]]}, {"cat": "家族", "t": "レスリング漬けの家で育った", "b": "ブレットが目を覚ますと、家の中はいつもレスリング一色だったという。地下室ではレスラーたちが酒を飲みながらマットで軽く組み合い、きょうだいもみんなレスリングに夢中だったと話す。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（29:29〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1769s"]]}, {"cat": "リングに来るまで", "t": "4歳でヒットマン、5歳でファン", "b": "ブレットは、4歳ごろにはもうヒットマンだったようなものだと話す。5歳ごろから熱心なファンになり、将来の仕事とは意識しないまま試合を見て、誰がなぜうまいのかを研究していたそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（29:29〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1769s"]]}, {"cat": "リングに来るまで", "t": "父の団体で物語を語る技を磨いた", "b": "ブレットは、父が率いた地元の団体スタンピード・レスリングでも、現実に見える物語を紡ぐことを大切にしていたと話す。同じ団体の先輩レスラーから、はしごを使った試合を「人生で見た最高の試合」とほめられたことも覚えているという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（30:19〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1819s"]]}, {"cat": "リングの話", "t": "客席の最前列で見たい試合を作る", "b": "ブレットは、自分が最前列でブレット・ハートの試合を見る観客だと想像して組み立てていたと話す。名勝負は自分で名乗るものではなく、何年も語り継がれるものだと考えているそうだ。会社に名勝負の財産を残すのが願いだったという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（31:55〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=1915s"]]}, {"cat": "暮らし", "t": "グッズの印税がかなりの収入だった", "b": "ブレットは、当時は商品の売り上げに応じた印税が収入の大きな部分だったと話す。特にイギリス、ヨーロッパ、インド、ドイツなど海外で人気が高く、社内でも指折りのグッズ売り上げだったと振り返る。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（37:44〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=2264s"]]}, {"cat": "リングの話", "t": "悪役への転向は社長の提案", "b": "ブレットは、悪役になるよう持ちかけたのは社長のほうだったと話す。収入に響くので最初は乗り気でなかったが、悪役になればショーンとの対立も解消できると考え直したという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（37:44〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=2264s"]]}, {"cat": "リングの話", "t": "レッスルマニア13は「学校のけんか」", "b": "ブレットは、サブミッション戦は偽のフィニッシュが使えず難しいと考えていた。そこで新入りの強い生徒と人気者のけんかという、学校のけんかのイメージを提案したという。本物の格闘技のように見える試合になった、と誇らしげに話す。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（41:03〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=2463s"]]}, {"cat": "リングの話", "t": "映画の名場面になぞらえた終わり方", "b": "ブレットは、技から抜け出そうとして一度は抜け切れず、再び極めて勝つ展開を、映画『カッコーの巣の上で』の名場面に重ねて説明したという。観客が敗れる側に心を寄せる、決定的な瞬間になったと話す。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（57:14〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3434s"]]}, {"cat": "家族", "t": "弟オーエンに名誉を", "b": "ブレットは、弟のオーエンは仲間みんなに愛され、この世界を心から愛していたと話す。だから殿堂入りなどで称えられることを望むはずだ、という考えのようだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:01:57〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3717s"]]}, {"cat": "体のこと", "t": "23年で誰もけがさせなかった", "b": "ブレットは、23年のキャリアで相手を一人もけがさせなかったことを誇りにしていると話す。打撃は硬く本物に見えたが、自分が痛い思いをしても相手は傷つけない、という教えを守ってきたという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:04:21〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3861s"]]}, {"cat": "好きなもの", "t": "90年代のプロレスがいちばん好き", "b": "ブレットは、数々の名勝負が生まれた1990年代のプロレスを、どの時代よりも好きだと話す。社長から与えられた数々の名場面は、不満があっても大切な思い出として残っているそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:04:21〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3861s"]]}, {"cat": "リングの話", "t": "「最高の存在」として覚えてほしい", "b": "ブレットは、いちばん覚えていてほしいのは、物語を語る力と試合を組み立てる力だと話す。決まり文句の「最高の存在」として記憶されたいという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:04:21〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3861s"]]}, {"cat": "リングに来るまで", "t": "日本人レスラー2人から基本を教わった", "b": "ブレットは、2人の日本人レスラーから技のかけ方や受け身を丁寧に教わったと話す。そこで、相手を傷つけず、プロとして安全に動く姿勢を学んだという。そのうちの1人はすでに亡くなったそうだ。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:05:08〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3908s"]]}, {"cat": "体のこと", "t": "現役を終わらせたけがの試合", "b": "ブレットは、最後に戦った相手とのその試合の前に、無茶はしないでほしいと頼んだと話す。それでもその試合でのけがが、自身の現役生活の終わりになったという。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-P9pbp6gnsbc", "src": [["番組のYouTube（1:06:00〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=3960s"]]}]);
  if (PROFILES["Vader"]) PROFILES["Vader"].facts.push({"cat": "暮らし", "t": "ヴェーダーとの試合は暴れ象のよう", "b": "ヴェーダーは試合のたびに強烈にぶつかってきたが、あとで申し訳なく思っていたそうだ。ブレットは、暴走する象と戦うような感覚だったと、ブレット・ハートが話している。", "sp": "ブレット・ハート", "d": "2024-12-21", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ブレット・ハートの話（字幕を全文確認）", "src": [["番組のYouTube（39:25〜）", "https://www.youtube.com/watch?v=P9pbp6gnsbc&t=2365s"]], "by": "第三者の話"});
