  if (!PROFILES["Mustafa Ali"]) PROFILES["Mustafa Ali"] = { lead: "育成施設からメインロースターまでWWEで歩み、NXT在籍中に契約を解除された。やり切ったと語り、会社への感謝と復帰の可能性にも触れている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Mustafa%20Ali"]], moves: [], facts: [] };
  if (PROFILES["Mustafa Ali"]._weak) { PROFILES["Mustafa Ali"].lead = "育成施設からメインロースターまでWWEで歩み、NXT在籍中に契約を解除された。やり切ったと語り、会社への感謝と復帰の可能性にも触れている。"; delete PROFILES["Mustafa Ali"]._weak; }
  PROFILES["Mustafa Ali"].facts.push(...[{"cat": "WWEでの日々", "t": "あの復帰回の足元が揺れた", "b": "あるスーパースターの復帰の夜、花道にロースター全員が並んだとアリは振り返る。会場全体が震えるのを初めて感じたそうだ。その人物が舞台裏で一言かけてくれたことも、一流の振る舞いとして覚えているという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（20:37〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=1237s"]]}, {"cat": "WWEでの日々", "t": "名前を言い直せなかった入団当初", "b": "入団したころは波風を立てたくなく、周りに「ムスタファ」ではなく崩した呼び方をされても訂正できなかったとアリは話す。自分でもその発音で名乗るようになり、今は誇れることではなかったと振り返る。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（22:59〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=1379s"]]}, {"cat": "WWEでの日々", "t": "名前が「アリ」の一語になった経緯", "b": "ライブイベントの報告書で、観客が二つの呼び名に割れて盛り上がりに欠けた夜があったと、ロード・ドッグから聞いたという。そこから上の判断で一語の呼び名にする話が決まったそうだ。アリに悪意は感じず、勝たせるための判断だと受け止めた一方、意見を言える余地はなかったと話す。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（24:36〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=1476s"]]}, {"cat": "WWEでの日々", "t": "番組で名前を言い直させた場面", "b": "悪役のころ、トーク番組で自分の名前を正しく言い直させる場面があったとアリは話す。悪役らしい演技のつもりだったが、同じ悩みを持つ人たちから「胸に刺さった」と今も声をかけられるそうだ。意図しない形で多くの人に響いたことに驚いていると話す。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（26:17〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=1577s"]]}, {"cat": "退団の理由", "t": "解除の電話を受けた日", "b": "契約を解除するという電話を受けたとき、アリは有酸素運動を終えて自宅に戻ったところだったという。すぐに次の手を考え始めたが、その直後に家族の大きな出来事が重なり、仕事どころではなくなったと話す。この経験で、リングの上のことより大事なものがあると痛感したそうだ。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（28:46〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=1726s"]]}, {"cat": "退団の理由", "t": "解雇は「起きたこと」には驚かなかった", "b": "契約を解除されたとき、起きたこと自体には驚かなかったが、そのタイミングには驚いたとアリは話す。当時はNXTにいて、その週末にはタイトルマッチが組まれていたという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（33:32〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2012s"]]}, {"cat": "退団の理由", "t": "王座の計画が数か月前に変わっていた", "b": "NXT北米王座はもともとアリに乗せる予定だったと、本人は聞いていたそうだ。ところが放映契約の更新を控え、視聴率を押し上げるために人気ユニットの選手へ王座を回すことになったという。育成部門のトップからその理由を直接説明され、納得して受け入れたと話す。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（34:20〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2060s"]]}, {"cat": "退団の理由", "t": "自分の評価が下がるのを感じていた", "b": "WWE自体が勢いを増す一方で、自分の評価は下がっていると感じていたとアリは話す。結局は会社がどの選手に演出と音楽と宣伝を注ぐかという制作の判断で決まる、というのが本人の見方だ。そのため解雇の知らせには、悲しさとともに安堵に近い感覚もあったという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（35:58〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2158s"]]}, {"cat": "退団の理由", "t": "やれることはやった、という納得", "b": "先に解雇された仲間たちは「もっと粘ればよかった」と悔やんでいたそうだ。アリは、自分から企画を出し、メインイベントなどの番組出場も願い出て、数字の分析まで求めたと話す。だから「試しもしなかった」という後悔はなく、うまくいかなかったのは巡り合わせだと受け止めているという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（37:30〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2250s"]]}, {"cat": "WWEでの日々", "t": "育成契約と、会社の人に助けられた話", "b": "育成契約には移住が条件だったが、家庭の事情でアリは最初の半年だけ単身で過ごしたという。出産が近づいたころ、遠慮がちに相談すると、育成部門を率いる人が「父親であることに勝るものはない」と帰郷を許してくれたそうだ。会社には冷たい面もあるが、そうした人間的な付き合いもあったと感謝している。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（38:17〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2297s"]]}, {"cat": "退団の理由", "t": "WWEへの復帰の道は閉じていない", "b": "経営陣とは良い関係が続いており、解除のときも丁寧な連絡や温かいメッセージがあったとアリは話す。復帰するには、自分が価値あるものを築き、場所もタイミングも双方に合うことが必要だと考えているそうだ。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（42:20〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2540s"]]}, {"cat": "WWEでの日々", "t": "エリミネーション・チェンバー直前の頭のけが", "b": "メインロースターに上がり、大きな機会が続いていた時期に、試合中の事故で頭を痛めたとアリは話す。本人は大丈夫と思っていたが、ライブイベントの途中で医師に止められ、チェンバーの出場は見送りになった。のちに、会社が自分を守ってくれたと受け止めているという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（44:43〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2683s"]]}, {"cat": "WWEでの日々", "t": "仲間の躍進を複雑な思いで見た", "b": "自分が欠場した間に、ある先輩の快進撃が起きたとアリは振り返る。悔しさもあったが、長年実績を積んだ人が報われたことを心から喜んだそうだ。その先輩はアリを気遣って何度も連絡をくれたという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（49:30〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=2970s"]]}, {"cat": "WWEでの日々", "t": "ランディ・オートンの必殺技を切り返した夜", "b": "オートンの決め技を切り返す場面を、本人と相談しながら作ったとアリは話す。失敗すれば自分が悪く見えると言われ、緊張したが成功させたそうだ。自分の決め技を任せてくれたことに感謝しているという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（53:30〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=3210s"]]}, {"cat": "WWEでの日々", "t": "マネー・イン・ザ・バンクの当日に変わった筋書き", "b": "当初は勝つ予定と聞かされ、一日中祝福されていたとアリは話す。ところが入場の直前に会長から急きょ筋書きを変えると告げられ、勝利はなくなったという。他の出場者は知らされないまま、自分だけがその役を担ったそうだ。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（57:30〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=3450s"]]}, {"cat": "WWEでの日々", "t": "ロイヤルランブルでのニア・ジャックスとの場面", "b": "もともと自分の役ではなかった場面を、頼まれて引き受けたとアリは話す。見え方に不安を持つ人もいたが、プロとして役割を果たす姿勢を見せたかったそうだ。相手とは友人で、安全面でも気遣ってもらったという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（1:05:31〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=3931s"]]}, {"cat": "WWEでの日々", "t": "サウジでの試合と、同じ背景を持つ相手", "b": "サウジアラビア出身の選手との試合は、同じ宗教的背景の二人が大きな舞台に立てた点で意義深かったとアリは話す。当日は相手のパスポートの問題で到着が遅れ、アリが演出を組み立てて待ったそうだ。そこで周囲に評価されたと感じているという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（1:07:55〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=4075s"]]}, {"cat": "WWEでの日々", "t": "リトリビューション誕生と、足りなかった理由づけ", "b": "最初の登場の演出は当初の案が分かりにくく、サモア・ジョーの助言で形を変えたとアリは話す。一方、名前や仮面の意味づけを最後まで示せなかったことが、ユニットが伸びなかった理由だと考えているそうだ。自分なりの筋書きも提案したが、実現には至らなかったという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（1:13:36〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=4416s"]]}, {"cat": "WWEでの日々", "t": "契約がもらえず、自分から頼みに行った", "b": "クルーザー級の大会のあと、補欠だったアリだけが契約を得られなかったという。恐る恐る責任者に直接聞きに行き、丁寧にかわされたが、その週のうちに連絡が来たそうだ。聞かなければ今ここにいなかったと話す。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-8I77y501r78", "src": [["番組のYouTube（1:21:42〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=4902s"]]}]);
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "オートンが伝えた気持ち", "b": "数年後、けがの件をずっと気に病んでいたとオートンが打ち明けてくれたと、アリが話している。アリは気にしていないと答えたという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で、ムスタファ・アリの話（字幕を全文確認）", "src": [["番組のYouTube（56:43〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=3403s"]], "by": "第三者の話"});
  if (PROFILES["Samoa Joe"]) PROFILES["Samoa Joe"].facts.push({"cat": "暮らし", "t": "ジョーの助言で変わった登場", "b": "ユニットの登場の演出について、解説席にいたサモア・ジョーが細かく助言をくれたと、アリが話している。アリはその通りに演じたという。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で、ムスタファ・アリの話（字幕を全文確認）", "src": [["番組のYouTube（1:14:24〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=4464s"]], "by": "第三者の話"});
  if (PROFILES["Kofi Kingston"]) PROFILES["Kofi Kingston"].facts.push({"cat": "暮らし", "t": "コフィの気遣い", "b": "自分が欠場した間、コフィ・キングストンが何度も連絡して気遣ってくれたと、アリが話している。", "sp": "ムスタファ・アリ", "d": "2024-12-24", "how": "クリス・ヴァン・ヴリートの番組で、ムスタファ・アリの話（字幕を全文確認）", "src": [["番組のYouTube（51:53〜）", "https://www.youtube.com/watch?v=8I77y501r78&t=3113s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-8I77y501r78", d: "2024-12-24", show: "ext", who: ["Mustafa Ali"], t: "ムスタファ・アリの回　WWE退団と、去るまでの日々", lead: "クリス・ヴァン・ヴリートの番組に出た約92分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Mustafa Ali"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-8I77y501r78").map((x) => [x.t, x.b, x.sp])), open: ["家族、身体、他団体での活動、信仰などの話題は公開項目から除いた。", "試合の結果や細かな筋書きの詳細は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=8I77y501r78"]] });
  if (!ROSTER.find((r) => r[1] === "Big Show")) ROSTER.push(["ビッグ・ショー", "Big Show", "gn", "元WWE王者。WWEを離れた", "", "", ""]);
  if (!PROFILES["Big Show"]) PROFILES["Big Show"] = { lead: "ライバル団体から移り、控室での孤立や育成地への降格、テイカーの厳しい指導を経て巨人の戦い方をつかんだ。ビンスとの距離感も率直に語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Big%20Show"]], moves: [], facts: [] };
  if (PROFILES["Big Show"]._weak) { PROFILES["Big Show"].lead = "ライバル団体から移り、控室での孤立や育成地への降格、テイカーの厳しい指導を経て巨人の戦い方をつかんだ。ビンスとの距離感も率直に語った。"; delete PROFILES["Big Show"]._weak; }
  PROFILES["Big Show"].facts.push(...[{"cat": "WWEでの日々", "t": "2年ぶりの復帰はビンスの深夜の連絡から", "b": "金曜の深夜12時すぎにビンスから「月曜に出られるか」とメッセージが届いたという。2年間リングに立っておらず、心肺の鍛錬とリングでの体の使い方は別物だと実感したそうだ。受け身も体が覚えていて、復帰後の反応に感謝していると話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（3:19〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=199s"]]}, {"cat": "WWEでの日々", "t": "WWEを目指した理由", "b": "前にいた団体が消えたときは、働ける場所が一つ減ることを悲しく思ったと話す。人気の悪役ユニットが場を席巻し、善玉が埋もれていく流れを見て、自分に合う場所はWWEだと考えるようになったそうだ。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（26:02〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=1562s"]]}, {"cat": "WWEでの日々", "t": "初登場の週と、次の一手の後悔", "b": "初登場のあと、ビンスから次の対戦についてどうしたいかと聞かれたという。新人だった本人は「何でも会社の考えに従う」と答えたそうだ。今思えば自己主張のできない仕事ぶりで、会社側もそう受け取ったと感じていると話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（31:42〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=1902s"]]}, {"cat": "WWEでの日々", "t": "歓迎されなかった控室", "b": "入団当初の控室は親しみやすい空気ではなく、誰かの出番や居場所を奪う存在として見られたと話す。大きな契約を結んでいたことも周囲の反感を買ったそうだ。上位の選手とは話せず、最初は別の選手たちと行動していたという。のちにビリー・ガンらが助けてくれたと話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（34:19〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2059s"]]}, {"cat": "WWEでの日々", "t": "北極海に放り込まれた子ども", "b": "当時の自分を、浮き輪をつけて遊んでいた子どもが、いきなり北極海でホッキョクグマやシャチの群れに放り込まれたようだったと表現する。相手の試合の組み立てに口を出せる経験もなかったそうだ。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（36:02〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2162s"]]}, {"cat": "WWEでの日々", "t": "テイカーが厳しく指導してくれた", "b": "転んだあとにアンダーテイカーが面倒を見てくれたのは、仲のよかったブライアン・アダムスが口添えしてくれたからだと思うと話す。動きすぎ、受けすぎ、攻めの強さ、スタミナなど、容赦なく注意されたそうだ。試合後は説教を避けて別の通路から戻ったこともあるという。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（36:51〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2211s"]]}, {"cat": "WWEでの日々", "t": "指示が食い違い、迷い続けた日々", "b": "「巨人らしく戦え」と言われても具体的な意味が分からず、ビンスやパット・パターソン、周囲の仲間から別々の助言を受けて悩んだという。仕事を愛していたのに答えが出ず、鏡の前で自分を責めるほど苦しんだと話す。一人でレンタカーを運転しながら考え込む時期もあったそうだ。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（38:26〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2306s"]]}, {"cat": "WWEでの日々", "t": "「安定した試合を積め」という教え", "b": "テイカーからは、良い試合を一度するだけでなく、何度も続けて習慣にしろと言われたという。慣れた相手とは良い試合ができても、新しい相手になると自分の役割が分からず迷っていたそうだ。当時はまだ自分の立ち位置を理解できていなかったと振り返る。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（40:03〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2403s"]]}, {"cat": "WWEでの日々", "t": "巨人らしさをつかんだ夜", "b": "ヨーロッパ巡業でオースティンと戦った際、何度も顎を打たれて頭で考えるのをやめ、自然に攻め返したら感覚が一気につながったという。強い相手を前に自分から出ていけばよく、待つ必要はないと気づいたそうだ。のちに後輩にも同じ考え方を伝えていると話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（43:22〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2602s"]]}, {"cat": "WWEでの日々", "t": "育成地へ送られた理由は膝の手術明け", "b": "メインの舞台にいた時期から育成地へ移されたのは、膝の手術後に十分なリハビリをしないまま巡業の試合に出たのが原因だと、本人は考えているという。動きを何度か外し、テイカーを激怒させたそうだ。責任は自分にあると話し、当時はリハビリの知識がなかったと振り返る。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（46:28〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2788s"]]}, {"cat": "WWEでの日々", "t": "育成地での降格が教えてくれたこと", "b": "育成地ではバティスタやジョン・シナ、ブロック・レスナーらと知り合い、悪い癖を直す機会になったという。当時は力量への評価が追いつかず、周囲に味方も少なかったそうだ。高級車で現れた本人がリング設営を任され、謙虚さを学んだ高い授業料だったと話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（48:54〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=2934s"]]}, {"cat": "WWEでの日々", "t": "ビンスとの関係はまだらだった", "b": "ビンスは自分を好いてくれていたと思うが、潜在能力の引き出し方が分からなかったのではないかと話す。電話はいつも仕事の話で、世間話をする関係ではなかったそうだ。ジョン・ローリネイティスが現場を動かす立場になってから、関係が良くなっていったと感じているという。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（51:14〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3074s"]]}, {"cat": "WWEでの日々", "t": "体重を巡るJRの忠告", "b": "JRからは体重を落として長く続けろと繰り返し言われたが、当時は「自分は唯一無二の巨体」と受け止めてしまったという。のちに、JRがアンドレの晩年を知ったうえで気遣ってくれていたのだと分かったそうだ。当時はからかわれたと感じていたと話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（52:46〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3166s"]]}, {"cat": "WWEでの日々", "t": "ビンスは「それ以上」を求めていた", "b": "ビンスはアンドレと同じ枠に入れようとはせず、頭の良さや魅力まで含めて、それ以上のものを期待していたと話す。当時の自分は仲間の中で満足してしまい、積極性が足りなかったと反省しているそうだ。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（54:21〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3261s"]]}, {"cat": "WWEでの日々", "t": "コミカルな役も会社への「義理」", "b": "契約書に名前を書いた以上、会社の求めることは何でもやるという義理の感覚があったという。数々のコミカルな役は、テレビに出る機会や観客の親しみを生んだとも話す。ファンから「悪役転向の回数はNASCARより多い」と冗談にされたことも語った。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（55:54〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3354s"]]}, {"cat": "WWEでの日々", "t": "一番充実していたのは2011〜14年ごろ", "b": "キャラクターのバランスが取れ、どんな相手とも良い試合ができた時期だと話す。ビンスから見ても、任せて安心できる存在になれたそうだ。ジョン・シナとは打ち合わせなしでもうまく進み、巨人であることを任せてもらえたと振り返る。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（1:01:43〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3703s"]]}, {"cat": "WWEでの日々", "t": "「毎日を初出勤のつもりで」", "b": "ビンスに昔言われた「毎日を初日のつもりで働け」という言葉が心に残っているという。移動や遅延が続くと保ちにくいが、最高の仕事をしていると思うようにしているそうだ。20年以上続くとは思わなかったと話す。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（1:11:40〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=4300s"]]}, {"cat": "WWEでの日々", "t": "控室で後輩の相談役になる", "b": "若い軽量級の選手が相談に来ると、見せ場の最大の盛り上がりをフィニッシュに置くよう助言しているという。ルセフやミロの面倒も見たと話す。入ってきたときより業界を良い状態にして去りたいと考えているそうだ。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（1:13:20〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=4400s"]]}, {"cat": "WWEでの日々", "t": "今のWWEに望む「ハングリーさ」", "b": "今は運動能力の高い選手がそろっているが、全員が仲がよく居心地が良すぎるのは気になると話す。ビンスの教えを引き、他人に遠慮しすぎず上を狙う姿勢をもっと見たいという。ドリュー・マッキンタイアの変化には感心していると語った。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-O2euijFt1yc", "src": [["番組のYouTube（1:20:34〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=4834s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "ジョン・シナの実用的な強さ", "b": "ジョン・シナは、背中や体幹が揺れず、肩に担がれると機械のフォークリフトのように安定している、とビッグ・ショーが話している。", "sp": "ビッグ・ショー", "d": "2025-01-11", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ビッグ・ショーの話（字幕を全文確認）", "src": [["番組のYouTube（1:02:32〜）", "https://www.youtube.com/watch?v=O2euijFt1yc&t=3752s"]], "by": "第三者の話"});
