  if (!PROFILES["Matt Hardy"]) PROFILES["Matt Hardy"] = { lead: "1994年に前座の出場から始め、弟ジェフとのハーディー・ボーイズでタッグ戦線を変えた。体を酷使して一度リングを離れた経緯や、WWE再登場への思いを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Matt%20Hardy"]], moves: [], facts: [] };
  if (PROFILES["Matt Hardy"]._weak) { PROFILES["Matt Hardy"].lead = "1994年に前座の出場から始め、弟ジェフとのハーディー・ボーイズでタッグ戦線を変えた。体を酷使して一度リングを離れた経緯や、WWE再登場への思いを語る。"; delete PROFILES["Matt Hardy"]._weak; }
  PROFILES["Matt Hardy"].facts.push(...[{"cat": "WWEでの日々", "t": "1999年に自然体で人気が出たという", "b": "WWEで最初に注目された1999年当時、キックウェアのパンツにぴったりしたシャツという普段着に近い姿が受けたと、マットは話す。「友達になれそうな普通の連中」に見えたことと、小柄な自分たちでも夢をつかめるという見え方が支持につながったと考えているそうだ。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（8:46〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=526s"]]}, {"cat": "WWEでの日々", "t": "弟から離れて1人の役柄に入った喜び", "b": "ジェフの存在が大きいことは認めつつ、弟から離れて1人の役柄を演じられた機会をマットは喜んだという。やりすぎなくらい大げさで、現実離れした人物を演じるときに自分は一番輝くと話している。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（11:11〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=671s"]]}, {"cat": "WWEでの日々", "t": "1994年から前座として本名で出ていた", "b": "WWEには1994年から前座の選手として出ていたという。本名のマット・ハーディーとジェフ・ハーディーのまま出ていたところ、会社が2人を組ませて「ハーディー・ボーイズ」と名づけた。探偵小説のようで耳に残る名前だと言われ、その後も本名で通せたことをマットは恵まれていたと振り返る。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（12:44〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=764s"]]}, {"cat": "WWEでの日々", "t": "名前の最後のZは会社の持ち物にするため", "b": "WWE時代はチーム名の最後にZが付いていて、これは会社が名前の権利を持つためだったとマットは考えている。ダッドリー兄弟の名前も同じ事情だと推測している。いまは他団体では「ハーディーズ」を名乗っていると話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（13:30〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=810s"]]}, {"cat": "WWEでの日々", "t": "重みを増したヘイズ時代とブルード加入", "b": "その後、マイケル・ヘイズのもとで2人の雰囲気はやや重く陰のあるものになったそうだ。さらにギャングレルのグループ「ブルード」に加わったが、その間もハーディー・ボーイズらしい試合は続けていたという。登場の演出は、会場に舞台がないときは火をたいてその中に立ってから出ていくこともあったと話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（13:30〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=810s"]]}, {"cat": "WWEでの日々", "t": "ひざの手術から2005年に戻った", "b": "弟との路線が分かれたあと、マットは1人の役柄で進んだ。ひざの手術後の2005年に戻ってきたときは「死なない男」のような見せ方だったという。さらにロイヤルランブルで弟を裏切り、年間最大の祭典で弟との壮絶な試合へ進んだと振り返る。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（14:16〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=856s"]]}, {"cat": "退団の理由", "t": "黒雲の役柄は広まらず、路線が定まらなかった", "b": "弟との試合のあと「黒い雲」と呼ばれる役柄で進んだが、大きくは広まらなかったとマットは振り返る。ジェフが離れていく時期と重なり、会社は自分を再び正統派に戻したがったという。その後は別の団体に移り、心身ともに疲れ果てていたため、休んでから出直す必要があったと本人は話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（15:05〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=905s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典での復帰は限られた人にだけ伝えられた", "b": "2017年の年間最大の祭典への復帰は、ごく少人数にしか知らされていなかったという。直前に会場へ着いて駆け上がるように出ていき、幕の向こうの大観客を見たときの感覚は、まるで夢のようで周囲がぼやけて見えたとマットは話す。以前の団体で広めた決まり文句の大合唱が起きたことにも感謝しているそうだ。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（16:40〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=1000s"]]}, {"cat": "WWEでの日々", "t": "WWEへの再登場に前向き", "b": "弟とWWEの試合に出るという予想について、マットは悪くないと感じているそうだ。いまの団体もWWEへの愛着を理解してくれていて、関係もよいという。条件がそろえば、いまの王座を持ったままWWEの番組に出る可能性もあるかもしれないと話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（42:15〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2535s"]]}, {"cat": "WWEでの日々", "t": "殿堂入りは望んでいる", "b": "兄弟でWWEの殿堂に入ることを、いつか実現したいとマットは話す。殿堂の名前がつくものなら、どこでも入りたいと考えているそうだ。WWE向けに撮った映像の公開も近いと話している。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（43:03〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2583s"]]}, {"cat": "WWEでの日々", "t": "「危ない」と止められたことはなかった", "b": "危険な試合をするなとWWEの誰かに言われたことはなかったという。初のタッグ・ラダー戦では、自分たちの色を描いていいと任されたと感じたそうだ。そこから雪だるまのように大きくなり、2000年初頭のタッグ・テーブル戦、年間最大の祭典での三つ巴ラダー戦（のちのTLC戦の原型）へとつながったと話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（47:03〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2823s"]]}, {"cat": "WWEでの日々", "t": "試合よりも役柄と物語が大事だと考えるようになった", "b": "1999年から2001年ごろは毎晩自分を壊すような試合をしていたが、今ならもっと役作りを大切にしたいとマットは話す。移動中にスティーブ・オースティンから聞いた、観客の求める水準が上がりすぎたという話が心に残っているそうだ。体は同じことを繰り返せないが、役柄と物語は何度でも変えられると考えているという。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（47:52〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2872s"]]}, {"cat": "退団の理由", "t": "休みを願い出たが、病院で薬に頼る流れになった", "b": "2010年にかけて体を酷使して働き、休みたいと会社に伝えたが、頼りにされている選手だからとツアーに帯同したまま治療を受ける形になったという。そこで痛み止めに頼るようになり、きちんと立て直すためにリングを離れる決断をしたとマットは話す。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（50:15〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=3015s"]]}, {"cat": "退団の理由", "t": "戻ってからは賢くなったと感じている", "b": "戻ったときは以前よりずっと賢くなっていたと、マットは話す。若くて動けるうちは役柄の物語を考えないが、体が壊れてから初めて役作りの大切さに気づくという。この仕事は「ねじれた商売」だとも話している。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（51:02〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=3062s"]]}, {"cat": "WWEでの日々", "t": "2008年は兄弟そろって王座を持っていた", "b": "2008年、ジェフがWWEの世界王座、マット自身がECW王座を同時に持っていた時期があったという。番組の最後に自分が王者として出ていったことを、とても誇らしい思い出として話している。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（55:06〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=3306s"]]}, {"cat": "WWEでの日々", "t": "最初の目標はタッグ王座を1回取ること", "b": "2人の当初の目標は、WWFかWCWのどちらかでタッグ王者になることを1回だけ達成することだったという。それ以上は「おまけ」で、目標は何度も超えたとマットは話す。単独でも成功できると考え始めたのは、人気が伸びた2002年ごろだそうだ。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-BEHwi6GaRmY", "src": [["番組のYouTube（56:38〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=3398s"]]}]);
  if (PROFILES["Jeff Hardy"]) PROFILES["Jeff Hardy"].facts.push({"cat": "暮らし", "t": "ジェフのアンダーテイカー戦が印象深い", "b": "マットが一番心に残っている弟の試合は、アンダーテイカーとのラダー戦だと、マットが話している。アンダーテイカーも良い試合にしようと力を入れ、ジェフが何度倒れても立ち上がる終盤が大きな瞬間になったという。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で、マット・ハーディーの話（字幕を全文確認）", "src": [["番組のYouTube（54:16〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=3256s"]], "by": "第三者の話"});
  if (PROFILES["The Dudley Boyz"]) PROFILES["The Dudley Boyz"].facts.push({"cat": "暮らし", "t": "ダッドリー兄弟とのタイトル数の話", "b": "バッバ・レイとディーボンの2人は「史上最多の王座を持つタッグ」と言われるが、影響力ならハーディー・ボーイズだと、マットが話している。自分たちも彼らより多く王座を取りたいと考えているそうだ。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で、マット・ハーディーの話（字幕を全文確認）", "src": [["番組のYouTube（47:03〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2823s"]], "by": "第三者の話"});
  if (PROFILES["Stone Cold Steve Austin"]) PROFILES["Stone Cold Steve Austin"].facts.push({"cat": "暮らし", "t": "オースティンが話した観客の水準の話", "b": "ヨーロッパからの帰りの機内で、オースティンが「観客の水準が上がりすぎて、もうこれ以上は難しい」といった趣旨の話をしたと、マットが話している。この言葉が、役柄と物語を大事にする考えにつながったという。", "sp": "マット・ハーディー", "d": "2025-01-16", "how": "クリス・ヴァン・ヴリートの番組で、マット・ハーディーの話（字幕を全文確認）", "src": [["番組のYouTube（47:52〜）", "https://www.youtube.com/watch?v=BEHwi6GaRmY&t=2872s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-BEHwi6GaRmY", d: "2025-01-16", show: "ext", who: ["Matt Hardy"], t: "マット・ハーディーの回　WWEの日々と、離れた後に思うこと", lead: "クリス・ヴァン・ヴリートの番組に出た約58分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Matt Hardy"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-BEHwi6GaRmY").map((x) => [x.t, x.b, x.sp])), open: ["WWE離脱そのものを詳しく語る場面は少なく、2010年前後の休養の話を中心にまとめた。", "他団体での日々、家族、体のことの話は公開項目から外している。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=BEHwi6GaRmY"]] });
  if (!ROSTER.find((r) => r[1] === "Baron Corbin")) ROSTER.push(["バロン・コービン", "Baron Corbin", "lg", "元WWEの大型選手", "", "", ""]);
  if (!PROFILES["Baron Corbin"]) PROFILES["Baron Corbin"] = { lead: "元アメフト選手から13年間WWEで戦い続け、契約満了後は自由な挑戦に踏み出したバロン・コービン。家族とコーヒー、柔術、ホラー映画を愛する素顔を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Baron%20Corbin"]], moves: [], facts: [] };
  if (PROFILES["Baron Corbin"]._weak) { PROFILES["Baron Corbin"].lead = "元アメフト選手から13年間WWEで戦い続け、契約満了後は自由な挑戦に踏み出したバロン・コービン。家族とコーヒー、柔術、ホラー映画を愛する素顔を語った。"; delete PROFILES["Baron Corbin"]._weak; }
  PROFILES["Baron Corbin"].facts.push(...[{"cat": "リングに来るまで", "t": "リングの経験はWWEが最初だった", "b": "バロン・コービンは、13年間のWWEでの経験が自分にとって初めてのリング経験だったと話す。インディー団体で腕を磨く道を通らず、大学スポーツ出身者が直接入ってくる流れの一人だったそうだ。契約満了後に初めて小さな団体に上がり、別世界だと実感したという。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（0:51〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=51s"]]}, {"cat": "リングの話", "t": "初のインディー出場で観客が味方に", "b": "過激な試合で知られる団体の「ブラッドスポーツ」形式の試合に初めて出場し、観客がどう受け止めるか分からず強く緊張したという。本名のトム・ペストックとして上がったが、試合では大きな声援が起き、「戻ってきて」というチャントまで出たそうだ。10年間ネットで批判してきたファンの反応が変わったことに、自己肯定感を感じたと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:42〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=102s"]]}, {"cat": "リングの話", "t": "ニューヨークの街角で味わった感慨", "b": "試合前に水を買いに出た通りで、かつてメインを張った大会場と、今夜出る小さな会場が背中合わせに見えたという。大会場ではアンダーテイカーやローマン・レインズ、ジョン・シナとも戦った。立ち止まって15分ほど寒さの中で眺め、過去と未来の間にいる自分を実感したと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（7:18〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=438s"]]}, {"cat": "リングに来るまで", "t": "アメフトを去った日から貯金を意識", "b": "アメフトを離れたとき、卓球をして遊んでいる間に突然仕事がなくなったという経験があるそうだ。以来、収入が一瞬で途絶えることを意識し、WWEでの収入も堅実に管理してきたと話す。いまは「やらなければならない仕事」ではなく、やりたいことを選べる立場にいるという。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=726s"]]}, {"cat": "好きなもの", "t": "ホラーやB級映画が大好き", "b": "バロン・コービンは、ホラー映画やスリラー、暗めのアクション作品に出たいと語る。B級ホラーは「ひそかな楽しみ」だそうだ。先週すでに一本撮影を終え、年末にはポルトガルで血みどろのホラー映画の撮影を目指しているとも話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（12:58〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=778s"]]}, {"cat": "リングの話", "t": "新日本プロレスでやってみたい", "b": "日本で戦うことに強い憧れがあり、AJスタイルズや中邑真輔らが通った道を自分も歩みたいという。日本のプロレスの歴史や文化が好きだと話す。ほかにも料理番組や柔術大会など、あらゆる方向に挑戦したい気持ちがあるそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（14:35〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=875s"]]}, {"cat": "好きなもの", "t": "ブラジリアン柔術で紫帯に", "b": "柔術を4年半続け、2週間前に紫帯を取ったという。昇格時には、先生から8分ラウンドを延々と繰り返す厳しい稽古を課されたそうだ。さらにパンアメリカン大会など、大会出場を続けたいと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（15:26〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=926s"]]}, {"cat": "リングの話", "t": "新しいリング名はビショップ・ダイア", "b": "今後はバロン・コービンの名を捨て、新しい名で戦うと話す。ビショップ・ダイアは、孤高の狼にちなみつつ、男爵よりさらに上の位という意味を込めた名前だそうだ。ほかの団体に行ってもWWE帰りと見られたくなく、新しい自分を作りたいと語る。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（17:05〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=1025s"]]}, {"cat": "リングの話", "t": "作り直した後のベビーフェイス人気", "b": "育成ブランドで体を絞り、技も作り直して主力に戻ったところ、観客から名前を呼ばれる場面が増えたという。悪役を長く続けてきたぶん、声援の中で戦うことがうれしく、まだやり残したことがあると感じたそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（18:44〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=1124s"]]}, {"cat": "リングの話", "t": "選手を押し上げる役を担ってきた", "b": "ローマン・レインズやセス・ロリンズといった花形選手の大一番に向けて、長く相手を務めてきたという。誰とでも良い試合ができ、相手を安全に守れるからこそ回ってきた役だそうだ。もちろん世界王者になりたい気持ちは人一倍あったが、自分の役割は受け入れていたと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（31:36〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=1896s"]]}, {"cat": "家族", "t": "子どもに伝える「感情を渡さない」教え", "b": "他人の言動に振り回されないことを、子どもたちにも教えていると話す。娘が同級生の腕を叩いたときも、感情を人に左右されてはいけないと諭したそうだ。自分自身も、怒りやすい性格ではなく、人に感情を支配させないよう心がけているという。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（35:39〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=2139s"]]}, {"cat": "リングの話", "t": "王座獲得の構想が途中で変わった", "b": "大型ブリーフケース戦の勝利後、王座を持たせる構想があったが、状況の変化でそのまま進まなかったという。カート・アングルの最後の試合で相手を務めた件でも、翌週に流れが急に変わったと話す。いまは最後まで構想を貫く体制になってきたと感じているそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（43:53〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=2633s"]]}, {"cat": "リングの話", "t": "評価が行ったり来たりした過去", "b": "ファンからは「過大評価」と「過小評価」の両方で言われてきたという。担ぎ上げられて入場する役で出番も多く、反感を買ったのは自分のせいではないと話す。その同じファンが後に「もっと評価されるべき」と言い出したのが面白いそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（47:49〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=2869s"]]}, {"cat": "暮らし", "t": "自分で焙煎するコーヒー会社", "b": "コーヒー会社を立ち上げ、すでに年商は7桁ドル規模になっているという。コスタリカやエクアドルなど産地への旅も計画し、生豆の仕入れ、焙煎、袋詰め、手書きのラベルまで自分で手がけているそうだ。レスラーとして働きながら、ものづくりへの意欲が尽きないと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（59:52〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=3592s"]]}, {"cat": "体のこと", "t": "40歳でも週3〜4日の鍛錬", "b": "40歳になったいまも、柔術やジムのトレーニングを週に3〜4日続けているという。年末年始の後は食事を引き締めるが、妻は好きな料理を作ってほしがるそうだ。止まれない性分で、自分でも不思議だと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:01:30〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=3690s"]]}, {"cat": "好きなもの", "t": "銀メダルでは終われず1日6試合", "b": "最近の大会で重量級に出て銀メダルを取ったが、納得できなかったという。そのまま無差別級に申し込み、すでに3試合戦ったあとで追加の3試合を勝ち抜き、金メダルを手にしたそうだ。妻には夕食に帰れないと連絡したと笑って話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:02:16〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=3736s"]]}, {"cat": "リングの話", "t": "ジョン・シナの目を突いた夜", "b": "メインロスターに上がって間もない頃、6人タッグの序盤でジョン・シナの目に指が入ってしまったという。シナからはその場で激しく罵られ、育成ブランドに戻されると思って泣きそうになりながら試合を続けたそうだ。試合後にシナが「お互い様だ」と許してくれ、安堵したと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:06:21〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=3981s"]]}, {"cat": "リングに来るまで", "t": "育成時代のコーチとの衝突と和解", "b": "育成ブランドにいた頃、コーチのマット・ブルームとは意見が合わず衝突していたという。3年たっても昇格できない焦りもあり、自分も苛立っていたと振り返る。のちに和解し、いまでは助けを頼める信頼関係だそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:12:04〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=4324s"]]}, {"cat": "リングに来るまで", "t": "揃いの練習着をめぐる出来事", "b": "育成時代、支給の練習着が気に入らず、フィン・ベイラーに贈られた別のパンツで移動バスに乗ったところ、みんなの前で叱られたという。直後に同じパンツで現れたフィンは何も言われず、悔しかったそうだ。当時は体重を70ポンド（約32キロ）落とした直後で、体型を見せたい気持ちもあったと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:12:49〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=4369s"]]}, {"cat": "好きなもの", "t": "生粋のチーフスファン", "b": "カンザスシティ生まれ育ちで、地元チーフスの熱烈なファンだと話す。この日も地元ブランドの帽子をかぶり、荷物の中でつぶれないところが気に入っているそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:17:34〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=4654s"]]}, {"cat": "暮らし", "t": "地元の小児病院への慈善活動", "b": "カンザスシティの慈善イベントに毎年参加し、小児病院への寄付を集めているという。ソフトボールや競技番組形式の催しに加え、入院中の子どもたちを訪問する活動もあり、年間で300万ドル以上を集めるそうだ。自分も子を持つ親として、心を打たれる体験だと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:21:33〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=4893s"]]}, {"cat": "暮らし", "t": "アメフト選手の知人からスイートに招待", "b": "慈善イベントで知り合ったトラヴィス・ケルシーに誘われ、叔父と兄を連れて試合のスイートで観戦したという。そこへテイラー・スウィフトが現れて気さくに抱擁してくれ、家族のように迎えられたそうだ。のちにクリスマスパーティーにも招かれ、有名人になっても偉ぶらない人柄に感銘を受けたと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:26:25〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5185s"]]}, {"cat": "好きなもの", "t": "ホラー好きが縁で名プロデューサーに会う", "b": "パーティーで、ホラー映画の話で盛り上がった相手が、実はホラー映画の大手制作会社の創業者ジェイソン・ブラムだったという。気づくまで自分の好きな作品を並べ続けていたそうだ。文脈のない場所では気づけないものだと笑って話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:30:18〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5418s"]]}, {"cat": "好きなもの", "t": "初めて見たブロードウェイ", "b": "数か月前、妻とブロードウェイの舞台を初めて観て、人生で最高の体験だったと話す。出演者の歌とせりふの暗記に感心し、自分のマイク練習やアドリブとも通じるものを感じたそうだ。雨の中の乱闘シーンの演出にも感動し、もう一度観に行きたいと話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:32:41〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5561s"]]}, {"cat": "リングの話", "t": "相手を守る安全な試合運び", "b": "安全に試合ができる選手として知られていることを誇りにしているという。足を滑らせたドルフ・ジグラーを受け止めた場面など、危ない瞬間を何度も防いできたそうだ。派手な技を使わず、パンチひとつでも同じ反応を引き出せると話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:34:18〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5658s"]]}, {"cat": "暮らし", "t": "毎朝の娘の送迎と家での時間", "b": "いまは自宅にいる時間が増え、上の娘を週5日学校に送っていると話す。遠征で家を空けた分を取り戻そうとしているそうだ。見知らぬ人と話すことも好きで、相手の話に耳を傾ける時間を大切にしていると語った。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:39:11〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5951s"]]}, {"cat": "リングに来るまで", "t": "契約で自分に賭けてきた", "b": "WWEとの契約を5回結んできたと話す。条件に納得できないときは粘って交渉し、一年契約で自分に賭けたこともあるという。育成ブランドに行く際も、給料を下げる提示を受け入れ、周囲の助言で決断したそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:42:27〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=6147s"]]}, {"cat": "体のこと", "t": "330ポンドから絞った体", "b": "もともとは約330ポンド（約150キロ）の巨体だったと話す。減量を求められて痩せたが、皮膚が余るなど体型の変化はあったという。自分では太っていたと思っていなかったそうだ。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:45:38〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=6338s"]]}, {"cat": "家族", "t": "支えてくれる妻と家族への感謝", "b": "感謝していることの第一に家族を挙げた。5歳と3歳の子ども、犬がいて、妻は社員を抱える会社を経営しているが、遠征や仕事にも快く送り出してくれるそうだ。母親や妻の両親も活動を応援してくれていると話す。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Xy4pBaE4d4g", "src": [["番組のYouTube（1:52:45〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=6765s"]]}]);
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "契約終了後に気遣ってくれた", "b": "契約が更新されなかったと知ったランディ・オートンが、まだ10年は居ると思っていたと驚き、上層部に掛け合おうかと言ってくれたと、バロン・コービンが話している。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で、バロン・コービンの話（字幕を全文確認）", "src": [["番組のYouTube（22:49〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=1369s"]], "by": "第三者の話"});
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "偉ぶらない人柄", "b": "ローマン・レインズは業界の頂点にいながら、後輩に助言を求められれば快く応じ、人を見下さない人だと、バロン・コービンが話している。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で、バロン・コービンの話（字幕を全文確認）", "src": [["番組のYouTube（1:28:44〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=5324s"]], "by": "第三者の話"});
  if (PROFILES["Jacob Fatu"]) PROFILES["Jacob Fatu"].facts.push({"cat": "暮らし", "t": "遅れて評価された実力者", "b": "ジェイコブ・ファトゥは長く機会を与えられなかったが、実力が認められて契約に至り、よい父親でもあると、バロン・コービンが話している。", "sp": "バロン・コービン", "d": "2025-01-23", "how": "クリス・ヴァン・ヴリートの番組で、バロン・コービンの話（字幕を全文確認）", "src": [["番組のYouTube（55:47〜）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g&t=3347s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Xy4pBaE4d4g", d: "2025-01-23", show: "ext", who: ["Baron Corbin"], t: "バロン・コービンの回　契約満了後の自由と、尽きない向上心", lead: "クリス・ヴァン・ヴリートの番組に出た約116分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Baron Corbin"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Xy4pBaE4d4g").map((x) => [x.t, x.b, x.sp])), open: ["契約が更新されなかった経緯で触れた特定の人物や、他団体の契約をめぐる話題は、名前が出ていないため載せていない。", "自動字幕のため、一部の人名や固有名詞は確信が持てず省いている。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Xy4pBaE4d4g"]] });
