  if (!PROFILES["Axiom"]) PROFILES["Axiom"] = { lead: "スペイン出身の覆面レスラー。10歳でプロレスに夢中になり、母国の小さなプロレス界から一通のメールでWWEへ。マスクの下では、普通の暮らしを楽しむ気さくな人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Axiom"]], moves: [], facts: [] };
  if (PROFILES["Axiom"]._weak) { PROFILES["Axiom"].lead = "スペイン出身の覆面レスラー。10歳でプロレスに夢中になり、母国の小さなプロレス界から一通のメールでWWEへ。マスクの下では、普通の暮らしを楽しむ気さくな人だ。"; delete PROFILES["Axiom"]._weak; }
  PROFILES["Axiom"].facts.push(...[{"cat": "暮らし", "t": "火曜日以外は普通の暮らし", "b": "ふだんは普通の生活を送っていて、番組収録のある火曜日だけが特別なのだという。リングに立つときの感覚は何ものにも代えがたいと話す。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（3:11〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=191s"]]}, {"cat": "暮らし", "t": "マスクは年に12枚", "b": "マスクは専門の職人に作ってもらっていて、毎月新しいものを使えるよう年に12枚ほど作るという。傷みが早いので、色違いを頼むこともあるそうだ。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=242s"]]}, {"cat": "リングに来るまで", "t": "10歳で始めたプロレス", "b": "スペインのテレビでプロレスが大ブームになったころ、人形やカード、ゲームを集める子どもの一人だったという。10歳ごろからマドリードの小さな団体で練習を始め、4〜5年練習して2012年にデビューしたそうだ。当時のスペインのプロレスは、今とは比べものにならないほど素人同然だったと振り返る。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=242s"]]}, {"cat": "リングに来るまで", "t": "WWEからのメールは詐欺かと", "b": "WWEから「1週間試したい」というメールが届いたときは、詐欺かと疑ったという。内容がすべて正しいと分かって本物だと信じたそうだ。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=338s"]]}, {"cat": "リングに来るまで", "t": "「スペイン人初」と「ケイン」", "b": "WWEに入った初のスペイン人と言われるが、マドリード近郊の米軍基地で生まれたケインがいるので、ネットではずっと冗談のネタになっているという。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（6:27〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=387s"]]}, {"cat": "好きなもの", "t": "憧れはレイ・ミステリオ", "b": "子どものころからレイ・ミステリオが好きで、今も好きだという。実際に会ったミステリオはとても気さくな人だったそうだ。ブルース・リーよりジャッキー・チェンのファンだとも話している。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（7:59〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=479s"]]}, {"cat": "リングの話", "t": "負ければマスクも脱ぐ", "b": "マスクを賭けて負けたら、約束は守ってマスクを脱ぐという。自分たちの仕事は物語を伝えることなので、それに見合う物語ならもちろん受け入れると話す。ベルトは、相棒のネイサン・フレイザーと自分が良い物語を届けられるという信頼の証だと考えているそうだ。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（22:23〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=1343s"]]}, {"cat": "リングの話", "t": "スペインのプロレスの未来", "b": "子どものころはWWEのヨーロッパ巡業を見に行っていたが、コロナ禍で来なくなった時期もあったという。WWEがバルセロナで収録するのは、あのころの自分には信じられないことで、スペイン出身のWWE選手がまた生まれるはずだと話す。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（26:21〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=1581s"]]}, {"cat": "好きなもの", "t": "柔術は体でするチェス", "b": "今はブラジリアン柔術を習っていて、けがのこともあり試合には出ていないが、大好きだという。「体でするチェス」のようなものだと話す。", "sp": "アクシオム", "d": "2025-01-28", "how": "グライミーTV（スペインのバラエティ番組）で（字幕を全文確認）", "art": "ext-GgSzXS_Mb00", "src": [["番組のYouTube（27:56〜）", "https://www.youtube.com/watch?v=GgSzXS_Mb00&t=1676s"]]}]);
  ARTICLES.push({ id: "ext-GgSzXS_Mb00", d: "2025-01-28", show: "ext", who: ["Axiom"], t: "アクシオムの回　スペインのバラエティ番組で", lead: "グライミーTV（スペインのバラエティ番組）に出た約51分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Axiom"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GgSzXS_Mb00").map((x) => [x.t, x.b, x.sp])), open: ["番組の大半はコントやゲームで、本人の話は一部だけ。30分以降は今回は読んでいない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GgSzXS_Mb00"]] });
  if (!ROSTER.find((r) => r[1] === "Jordynne Grace")) ROSTER.push(["ジョーディン・グレース", "Jordynne Grace", "lg", "TNAの女子王者", "", "", ""]);
  if (!PROFILES["Jordynne Grace"]) PROFILES["Jordynne Grace"] = { lead: "クッキーとアイスをやめられない筋肉派のレスラー。犬6匹と暮らし、子どもの頃の夢を叶えた幸運に、飾らない言葉で感謝を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jordynne%20Grace"]], moves: [], facts: [] };
  if (PROFILES["Jordynne Grace"]._weak) { PROFILES["Jordynne Grace"].lead = "クッキーとアイスをやめられない筋肉派のレスラー。犬6匹と暮らし、子どもの頃の夢を叶えた幸運に、飾らない言葉で感謝を語る。"; delete PROFILES["Jordynne Grace"]._weak; }
  PROFILES["Jordynne Grace"].facts.push(...[{"cat": "好きなもの", "t": "甘いものは止まらない", "b": "クッキーとアイスが大好物だという。ベン&ジェリーズのアイスなら1日に3パイント食べられるほどで、好みは「フィッシュフード」味。甘党仲間のムースと食べ物の写真を送り合っているそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（0:48〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=48s"]]}, {"cat": "体のこと", "t": "食べた分は有酸素運動で帳尻合わせ", "b": "インソムニア・クッキーを12個入りで食べきることもあり、そのあと1時間の有酸素運動で自分を罰するのだという。真似はすすめないと笑っている。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=95s"]]}, {"cat": "リングに来るまで", "t": "パワーリフティングから筋肥大型へ", "b": "関節への負担が大きく、試合と両立できないため、パワーリフティングはやめたという。切り替えは2021年ごろ、コロナ禍が落ち着いたころだと話す。大会で何度か優勝して、もう十分だと思ったそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=143s"]]}, {"cat": "リングに来るまで", "t": "目立つために体を作った", "b": "かつては特徴のない普通の体型で、部屋に入っても誰も気づかない存在だったという。大きな腕があれば、背が低くても何かに打ち込む人だと伝わると考え、鍛え上げたと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=190s"]]}, {"cat": "暮らし", "t": "街では上着で筋肉を隠している", "b": "飛行機などでは「何をしている人か」とよく聞かれるため、上着で体を隠すことが多いという。聞かれたときは、プロレスラーと答えると質問攻めになるので、ボディビルダーだと答えるのが楽だそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=238s"]]}, {"cat": "体のこと", "t": "減量大会は一度きり", "b": "ボディビルの大会には一度だけ出たが、人生で最悪の時期だったという。電気フライパンを会場に持ち込み、空港に着くたび買い出しと作り置きをし、深夜のホテルで有酸素運動をしていたそうだ。仕上がりは最高だったが、二度とやりたくないと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（4:45〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=285s"]]}, {"cat": "体のこと", "t": "食事はクッキーで崩れてもやり直す", "b": "1日5〜6食を基本にしているが、クッキーを断れないという。昔は一度崩れるとそのまま止まらなかったが、今は崩れてもすぐ元に戻せるようになったと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（6:20〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=380s"]]}, {"cat": "体のこと", "t": "筋トレより有酸素が中心", "b": "筋肉はもう十分あるので、維持には週3〜4回の筋トレと多めのたんぱく質で足りるという。そのぶん休みの日も含め、有酸素運動は週7日続けているそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（7:10〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=430s"]]}, {"cat": "暮らし", "t": "自宅のステアマスターは最高の買い物", "b": "自宅に業務用のステアマスターがあり、約1万ドルのローンを払い終えたという。毎日、ときには1日に何回も使い、後悔したことは一度もないと話す。夫は使わず、もっぱらトレッドミル派だそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（7:57〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=477s"]]}, {"cat": "リングの話", "t": "年間最大の祭典への出場は1週間前の電話", "b": "2024年のロイヤルランブルの話は、スコット・ドーレから試合のわずか1週間前に電話で知らされたという。最初は冗談だと思い、メールで済むのにと疑ったそうだ。提案してくれたのはTJ・ウィルソンだと聞いたと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（9:31〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=571s"]]}, {"cat": "リングの話", "t": "会場入りは緊張で胃が痛かった", "b": "リハーサルのため3日前から現地入りし、当日は驚きを保つために別の車で会場へ向かったという。緊張で胃が痛くなり、同じ人に二度握手して恥ずかしい思いもしたそうだ。入場は5番目で、TNA代表として失敗できないと集中していたと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（11:06〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=666s"]]}, {"cat": "家族", "t": "妹がTikTok経由でリア・リプリーに夢中", "b": "プロレスは見ない妹がいて、TikTokで有名なリア・リプリーの大ファンだという。姉がリアと並ぶ写真を見て、電話で大騒ぎし、連絡先まで聞いてきたそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（14:24〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=864s"]]}, {"cat": "リングの話", "t": "NXTへの登場は最後まで秘密だった", "b": "NXTでの電撃登場は、相手が誰か本人以外には漏れていなかったという。夕方に会場へ呼ばれ、部屋に入場禁止の札まで貼られた。相手を務めたロクサーヌも直前まで知らなかったそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（16:52〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1012s"]]}, {"cat": "リングの話", "t": "契約が切れた状態で次を決めずにいた", "b": "TNAには2018年からいて、契約が切れるのを待ったのは初めてだという。先が見えない不安もあったが、2024年に手応えを得たので動く時だと感じたそうだ。スコット・ドーレの退団後、予定より早く契約を終わらせたいと伝えると、会社が応じてくれたと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（18:26〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1106s"]]}, {"cat": "リングの話", "t": "オールインのあと、すぐTNAと契約", "b": "第1回オールインに出たあと、ツイッターでスコット・ドーレから声をかけられ、ほぼ即決でTNAに入ったという。ほかの団体と話す余裕はなかったそうだ。女子部門に力を入れていた点も決め手だと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（22:26〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1346s"]]}, {"cat": "リングの話", "t": "入場曲のサイレンはスコット・スタイナーへの敬意", "b": "入場曲の頭にサイレンを入れたのは、スコット・スタイナーが好きだと知る作曲者の案だという。許可は取っていないが、そのまま鳴らしていると笑っている。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（27:12〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1632s"]]}, {"cat": "リングの話", "t": "ベストバウトの一つはマーシャ・スラモビッチ戦", "b": "2022年の大会でのマーシャ・スラモビッチ戦が、当時は自分の頂点だったと感じたという。その後も何度か戦い、三本勝負の試合のほうが好きだったと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（30:26〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1826s"]]}, {"cat": "リングの話", "t": "いちばん強く打ってくるのはマーシャ", "b": "マーシャのバックフィストで本当に失神したことがあるという。キックパッドをつけない時期は、音が出ないのに痛くて大変だったが、今は聞き入れてもらえたそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（32:02〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1922s"]]}, {"cat": "リングの話", "t": "ブリー・レイ戦では決め技を信じて出した", "b": "ブリー・レイは大柄なため、決め技が決まるか心配していたという。以前に大柄な選手へ技をかけた映像を見せて納得してもらった。直前にトミー・ドリーマーが止めたが、自分は決められると確信していて、試合後に彼が「間違っていた」と言ってくれたそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（32:53〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=1973s"]]}, {"cat": "リングの話", "t": "マット・カルドナとの初のデジタルメディア戦", "b": "マット・カルドナの初のインジェンダー戦の相手を務めたという。キーボードやDVDプレーヤーを使い、古い携帯電話は約300ドルで200台ほどまとめ買いしたそうだ。のちにサインして売ったと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（34:31〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2071s"]]}, {"cat": "リングに来るまで", "t": "変わった綴りの名前は12歳のときのもの", "b": "ジョーディンの綴りが独特なのは、12歳のころに考えた名前だからだという。長く気に入らなかったが、プロレス団体に入れば変えられるだろうと仮の名前のつもりだった。結局、変えられることはなかったと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（37:42〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2262s"]]}, {"cat": "体のこと", "t": "日焼けは偽物、家系に皮膚がんがある", "b": "家族に皮膚がんの人がいるため、日焼けサロンには行かず、日にもあまり当たらないという。肌の色はスプレータンだと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（48:43〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2923s"]]}, {"cat": "体のこと", "t": "視力はレーシックで回復", "b": "もともと法的な失明に近い視力で、マイナス2.5ほどだったという。マイアミでレーシックを受けたところ、手術は数分で終わり、今は何でもよく見えると話す。眼鏡姿も気に入っているそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（49:33〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2973s"]]}, {"cat": "リングに来るまで", "t": "プロレス専業になる前は裁判の文字起こしの仕事", "b": "2021年ごろまで、家庭裁判所や刑事事件の音声を自宅で文字起こしする仕事をしていたという。足元のペダルで音声を止め、飛行機や日本にも持ち込める働き方だった。家庭裁判所の事件は子どもっぽい争いが多く、面白かったそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（52:50〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=3170s"]]}, {"cat": "リングに来るまで", "t": "子どものころはディーバに憧れた", "b": "幼いころはモデル系のレスラーに憧れていたという。その後TNAを見るようになり、オーサム・コングのような女性を見て、自分もああなれるかもしれないと感じたそうだ。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（56:48〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=3408s"]]}, {"cat": "家族", "t": "母はいつも大舞台に来てくれる", "b": "母は大きな場面にいつも来てくれ、ロイヤルランブルにもテキサスからフロリダまで車で駆けつけたという。母から「子どものころの夢を叶えた唯一の人」と言われ、胸にきたと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（59:10〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=3550s"]]}, {"cat": "暮らし", "t": "犬6匹と猫2匹と暮らす", "b": "犬はバリー、バーニー、バート、ブービー、ブルー、パイパーの6匹で、猫も2匹いるという。パイパーは保護犬で、もとの名前を変えない主義だそうだ。ブービーは家に届いたタコスを食べていた野良犬を迎えた子で、デリバリーの名前から付けたという。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（1:08:45〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=4125s"]]}, {"cat": "体のこと", "t": "大きなけがをしたことがない", "b": "骨折もなく、長く休むほどの捻挫や肉離れもないのが幸運だという。悩みは体の硬さくらいで、もっとストレッチをしたいと話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（1:11:55〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=4315s"]]}, {"cat": "リングに来るまで", "t": "14歳でデビュー、キャリアは約14年", "b": "テキサスにはアスレチック・コミッションがなく、14歳から試合に出られたという。キャリアは約14年で、自分の人生の半分ほどにあたると話す。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-912twnOAYb8", "src": [["番組のYouTube（1:12:41〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=4361s"]]}]);
  if (PROFILES["Scott Steiner"]) PROFILES["Scott Steiner"].facts.push({"cat": "暮らし", "t": "地元の空港で会うスコット・スタイナーは穏やか", "b": "初めて会ったときは、親切でとても物静かな人だったと、ジョーディン・グレースが話している。ネットはほとんどしない様子で、近所のおじいさんのような雰囲気だという。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で、ジョーディン・グレースの話（字幕を全文確認）", "src": [["番組のYouTube（38:51〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2331s"]], "by": "第三者の話"});
  if (PROFILES["Diamond Dallas Page"]) PROFILES["Diamond Dallas Page"].facts.push({"cat": "暮らし", "t": "DDPとは友人でトレーニングも経験", "b": "DDPは友人で、彼のトレーニングを何度か受けたことがあると、ジョーディン・グレースが話している。血流制限を使う軽い重量のトレーニングが気になっているという。", "sp": "ジョーディン・グレース", "d": "2025-01-29", "how": "クリス・ヴァン・ヴリートの番組で、ジョーディン・グレースの話（字幕を全文確認）", "src": [["番組のYouTube（43:05〜）", "https://www.youtube.com/watch?v=912twnOAYb8&t=2585s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-912twnOAYb8", d: "2025-01-29", show: "ext", who: ["Jordynne Grace"], t: "ジョーディン・グレースの回　甘党の筋肉と、夢を叶えた14年", lead: "クリス・ヴァン・ヴリートの番組に出た約75分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jordynne Grace"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-912twnOAYb8").map((x) => [x.t, x.b, x.sp])), open: ["夫の名前は字幕で確信が持てず載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=912twnOAYb8"]] });
