  if (!PROFILES["Danhausen"]) PROFILES["Danhausen"] = { lead: "素顔のダンハウゼンは、あがり症で、シンプソンズとホラーが大好きな人だった。家族や友人に支えられてきた道のりを、化粧を落として語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Danhausen"]], moves: [], facts: [] };
  if (PROFILES["Danhausen"]._weak) { PROFILES["Danhausen"].lead = "素顔のダンハウゼンは、あがり症で、シンプソンズとホラーが大好きな人だった。家族や友人に支えられてきた道のりを、化粧を落として語る。"; delete PROFILES["Danhausen"]._weak; }
  PROFILES["Danhausen"].facts.push(...[{"cat": "体のこと", "t": "ひどいあがり症で、化粧が仮面代わり", "b": "ひどいあがり症で、学校で発表するたびに手が震えたとダンハウゼンは話す。化粧をして役に入ると人前に出るのがずっと楽になり、話すことにも慣れたそうだ。素顔でキャラクターの声を出すのは今でも落ち着かないという。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（3:13〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=193s"]]}, {"cat": "体のこと", "t": "声を出し続けると気分が悪くなる", "b": "長時間キャラクターの声を出すと、喉の奥から出しているせいか吐き気がして声も枯れてくるという。そのため声は、テレビや動画の撮影、コミコンなど必要な場面にとっておくと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（4:49〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=289s"]]}, {"cat": "リングに来るまで", "t": "看護助手として12時間勤務をしていた", "b": "以前は看護助手として12時間の勤務をこなし、12日連続で働いたこともあるという。今は化粧をして人を笑わせる仕事なので、あの頃よりずっと楽だと思い返すそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=336s"]]}, {"cat": "家族", "t": "父が毎年ハロウィンの化粧をしてくれた", "b": "ハロウィンを大事にする家で、父が毎年ゾンビなどの特殊メイクを施して学校へ送り出してくれたという。父はお化け屋敷の仕事や、コミック店の壁にヒーローを描く仕事もしていた芸術家肌で、手作りの衣装も作ってくれたそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（8:44〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=524s"]]}, {"cat": "リングに来るまで", "t": "週1回の地方興行と早朝のコーヒー店勤務", "b": "スターバックスで朝5時からの勤務をしながら、毎週3時間以上かけて地方の小さな興行に通っていた時期があるという。収入はほとんどなく、体を痛めるばかりで、キャラクターもまだ固まっていなかったと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（11:07〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=667s"]]}, {"cat": "リングに来るまで", "t": "喉を蹴られ、本気で辞めようと考えた", "b": "ある試合で喉を思い切り蹴られ、喉がつぶれたかと思うほどの痛みで、このまま辞めようと車の中で考えたという。そんなときハロウィンの興行で好きにやっていいと声をかけられ、それが転機になったそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（11:55〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=715s"]]}, {"cat": "リングに来るまで", "t": "自分の化粧で出てみたら、周りも後押しした", "b": "動画を見ながら化粧を覚えて出た興行がきっかけで、素の自分に戻ると違和感があったという。知り合いの選手から「化粧のときのほうが自然だ」と言われ、少しずつ今の姿に寄せていったそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（13:26〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=806s"]]}, {"cat": "リングの話", "t": "化粧のおかげで危険な技を選べる", "b": "今のスタイルなら、無理な受け身を毎回取らなくても試合ができるという。大きな試合のときだけ体を張る、というように場面を選べるのが強みだと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（15:50〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=950s"]]}, {"cat": "リングの話", "t": "コナン・オブライエンに悪魔が憑いたような人物像", "b": "ホラーだけの役ではお客が限られ、行き詰まったという。そこでコナン、ピーウィー、エルヴァイラ、B級ホラーなどを混ぜ、「悪魔にとりつかれたコナン」と呼べるキャラクターにしたと話す。いつも笑顔なのは、宣伝写真は笑うものだと考えたからだという。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（16:41〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1001s"]]}, {"cat": "リングの話", "t": "ごく短い試合で見せた奇策が話題に", "b": "時間が4分ほどに削られた試合で、前から試したかった変わった仕掛けを使い、評判を呼んだという。勢いが出たら止めずに続けるべきで、初めて見る客にはいつも初めての気持ちで見せるのがよいと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（19:59〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1199s"]]}, {"cat": "リングの話", "t": "大舞台の週に予定が12試合あった", "b": "大型大会の週に、3日間で12試合が組まれていたという。自分たちで開く企画興行も用意していたが、世界的な中止で全部なくなったと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（22:22〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1342s"]]}, {"cat": "リングの話", "t": "骨折中に呼ばれて、観客に即座に受け入れられた", "b": "足を骨折した状態で呼ばれ、呪いをかける役で登場したという。観客がすぐに自分を知っていてくれたのが何よりうれしかったと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（25:32〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1532s"]]}, {"cat": "リングの話", "t": "笑わせる悪役も、本気の場面では本気で", "b": "表情づくりの手本になった大先輩や、ふざけながらタッグ王者にもなった名選手を挙げて、笑いと強さは両立すると話す。笑える場面があるからこそ、人気者の名場面が生きると考えているそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（29:32〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1772s"]]}, {"cat": "好きなもの", "t": "コナン・オブライエンとシンプソンズで育った", "b": "夏休みに夜更かしして、深夜のコナン・オブライエンの番組を見ていたという。子どもも大人も笑える少し変わった笑いが好きで、髪型もコナン風を意識していると話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（33:31〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=2011s"]]}, {"cat": "リングの話", "t": "「ケツ」の兄弟という呼び名が生まれた経緯", "b": "仲間の苗字をもじって呼んだのがきっかけで、その兄弟分たちが「ケツの子ども」と呼ばれるようになったという。冗談を受け入れてくれた彼らも、そこから人気を広げたと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（34:19〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=2059s"]]}, {"cat": "体のこと", "t": "技の着地で胸の筋肉を断裂した", "b": "試合の終盤の技で着地が少しずれ、胸の筋肉が骨から外れたという。その場では肩を痛めただけだと思い、翌朝になって断裂に気づいたそうだ。手術の傷あとは目立たないと話している。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（38:22〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=2302s"]]}, {"cat": "体のこと", "t": "試合から離れると体が痛みに弱くなる", "b": "プロレスは、数をこなすほど痛みに慣れ、間が空くと毎回初心者のように痛いと話す。復帰後は週2〜3回ほど地方の興行に出て、体を試合向きに保っているという。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（43:57〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=2637s"]]}, {"cat": "暮らし", "t": "批判の書き込みは見ないようにしている", "b": "自分の名前を検索することはしないが、おすすめ欄などで悪い評判が目に入ることはあるという。100人が喜んでくれても、1人の否定的な声のほうが記憶に残ってしまうと話す。それでも応援してくれる人への感謝が増すそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（50:19〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3019s"]]}, {"cat": "リングの話", "t": "人気の大型選手との異色コンビ", "b": "初めて会った日に撮った写真が反響を呼び、そこから二人の組み合わせが生まれたという。相手の人間味が出たと思っていて、またコンビを組みたいと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（55:20〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3320s"]]}, {"cat": "暮らし", "t": "自分のアニメ企画を持ち込んだ", "b": "友人の脚本家と一緒に、自分のキャラクターを主役にしたアニメを企画し、制作会社に売り込んだという。採用には至らなかったが、そのうち声がかかるかもしれないと前向きに話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（59:21〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3561s"]]}, {"cat": "家族", "t": "妻はバーレスクの人気ダンサー", "b": "妻はバーレスクの世界で高い評価を得ているダンサーだという。自分も、ドラァグの審査員やお菓子作りの番組など、そうした世界に関わってみたいと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:01:49〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3709s"]]}, {"cat": "暮らし", "t": "化粧を商標登録した", "b": "自分の化粧に似たトレーディングカードの絵を見つけたのをきっかけに、弁護士に頼んで化粧を商標登録したという。レスラーとしては最初の例だと話している。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:02:35〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3755s"]]}, {"cat": "家族", "t": "故郷デトロイトの会場に家族を招いた", "b": "子どもの頃に初めて観戦した会場で、団体の大舞台に出ることができたという。小さな会場に通ってくれた友人や、母、父、姉が最前列で見てくれたそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:04:09〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3849s"]]}, {"cat": "好きなもの", "t": "アクションフィギュアやコミックの収集", "b": "スパイダーマンのフィギュアに始まり、今ではエイリアンの大型像まで集めているという。子どもの頃に買えなかったものを買うのが楽しみで、最近はレスリングのカードにも手を出しているそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:05:47〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=3947s"]]}, {"cat": "暮らし", "t": "自宅に劇場のような部屋を作っている", "b": "改装中の家の地下に、映画やシンプソンズの等身大像を置く部屋を作ろうとしているという。等身大のエイリアン像を妻に贈ったこともあり、買い物は控えめにしつつ、値打ちが上がるものを選ぶようにしていると話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:07:26〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4046s"]]}, {"cat": "リングの話", "t": "いつかやりたい組み合わせ", "b": "兄弟分たちと本格的にタッグを組む、伝説の選手と組むなど、実現しなかった組み合わせにも未練があると話す。真面目な試合用の強い人物像も用意しているそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:09:45〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4185s"]]}, {"cat": "好きなもの", "t": "体のタトゥーはシンプソンズや映画の絵柄", "b": "腕にはエイリアンのキャラクター、禁断のドーナツ、イッチー&スクラッチーなどが入っているという。子どもの頃は夕方のシンプソンズを毎日欠かさず見ていて、今も日常でせりふを引用してしまうそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:13:00〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4380s"]]}, {"cat": "家族", "t": "妻は自由に仕事を選べて、背中を押してくれる", "b": "自分が家を空けても妻は快く送り出してくれるという。妻自身も裁縫で衣装を作りながら、ヨーロッパなど好きな舞台を選んで活動していると話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:15:28〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4528s"]]}, {"cat": "暮らし", "t": "映画館で働いていた頃からの親友と作る", "b": "動画の撮影を手伝ってくれる親友たちとは、映画館で働いていた頃からの長い付き合いだという。自分の動画の登場人物にもなってもらい、一緒に上へ上がっていきたいと話す。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:16:19〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4579s"]]}, {"cat": "家族", "t": "両親がコミックやホラーを教えてくれた", "b": "コミックを読むよう勧めた両親、ホラー映画を見せ、ハロウィンの仮装をさせた父、絵を描いていた母に感謝していると話す。一緒に見たアニメやディズニー映画が、声の演技にもつながったそうだ。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1flj9G-QNaM", "src": [["番組のYouTube（1:17:56〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=4676s"]]}]);
  if (PROFILES["William Regal"]) PROFILES["William Regal"].facts.push({"cat": "暮らし", "t": "表情づくりの手本にした大先輩", "b": "コメディもこなす名ヒールで、自分の表情の多くは彼から学んだと、ダンハウゼンが話している。", "sp": "ダンハウゼン", "d": "2025-01-30", "how": "クリス・ヴァン・ヴリートの番組で、ダンハウゼンの話（字幕を全文確認）", "src": [["番組のYouTube（29:32〜）", "https://www.youtube.com/watch?v=1flj9G-QNaM&t=1772s"]], "by": "第三者の話"});
