  ARTICLES.push({ id: "ext-1flj9G-QNaM", d: "2025-01-30", show: "ext", who: ["Danhausen"], t: "ダンハウゼンの回　素顔で語る、化粧と家族と収集癖", lead: "クリス・ヴァン・ヴリートの番組に出た約78分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Danhausen"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-1flj9G-QNaM").map((x) => [x.t, x.b, x.sp])), open: ["友人・同僚の個人名や、話者が判別しにくい箇所は省いた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=1flj9G-QNaM"]] });
  if (!ROSTER.find((r) => r[1] === "Penta")) ROSTER.push(["ペンタ", "Penta", "lg", "ルチャの人気マスクマン", "", "", ""]);
  if (!PROFILES["Penta"]) PROFILES["Penta"] = { lead: "約20年のルチャ人生を経てWWEにたどり着いたペンタ。家族への愛と、素顔を守る信念、そして決め台詞「恐れるな」の由来を、片言の英語に心を込めて語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Penta"]], moves: [], facts: [] };
  if (PROFILES["Penta"]._weak) { PROFILES["Penta"].lead = "約20年のルチャ人生を経てWWEにたどり着いたペンタ。家族への愛と、素顔を守る信念、そして決め台詞「恐れるな」の由来を、片言の英語に心を込めて語る。"; delete PROFILES["Penta"]._weak; }
  PROFILES["Penta"].facts.push(...[{"cat": "家族", "t": "デビュー戦に家族が会場へ来ていた", "b": "ペンタは、WWEでの初戦の夜に家族が来てくれたことが特別だったと話す。出発前、小さな娘から「ネットフリックスで見たい」と言われていたという。サンノゼでのあの試合が、キャリアの転機になったと感じているそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=95s"]]}, {"cat": "家族", "t": "前列で泣いた娘を見て胸がいっぱいに", "b": "勝った喜びと、最前列で泣く娘を見た気持ちが重なり、感情があふれたとペンタは話す。控室に戻るとみんなに迎えられ、20年前に夢を追い始めた自分を思い返したという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=144s"]]}, {"cat": "リングの話", "t": "「ノー・フィアー」は生き方になった", "b": "ペンタの決め台詞を、がんを乗り越えた人などが励みにしていると聞くそうだ。その声を知り、毎日心と体を磨く責任を感じたという。この言葉はもう自分だけでなく、みんなの生き方だと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=242s"]]}, {"cat": "リングの話", "t": "決め台詞の由来はメキシコの民衆歌", "b": "ペンタは、この言葉がメキシコ音楽のコリードから来ていると話す。ある歌の歌詞に「恐れるな、友よ」という趣旨の一節があり、気に入ったという。メキシコのテレビで初めてのインタビューの最後に使ったところ、みんなが真似し始めたそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（4:48〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=288s"]]}, {"cat": "リングに来るまで", "t": "20年かけてたどり着いた夢の舞台", "b": "ペンタは約20年前にメキシコで夢を追い始め、リングがない日も報酬が出ない日もあったと振り返る。それでもWWEに行けないかもしれないと疑ったことは一度もなかったそうだ。恐れているのは「夢のために戦わなくなること」だけだと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（6:29〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=389s"]]}, {"cat": "リングの話", "t": "マスクはドラゴンと忍者のイメージ", "b": "ペンタのマスクは、自分の文化を表すドラゴンがいちばん大事な要素だという。黒は自分の好きな色で、真剣さと格好よさがあると話す。忍者も好きで、本当の人柄が少し入っているそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（7:19〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=439s"]]}, {"cat": "リングに来るまで", "t": "父に連れられて見た小さな会場", "b": "子どものころ、父に連れられてメキシコの小さな会場でルチャを初めて見たとペンタは話す。会場の空気や選手たちに心を奪われ、いつか自分もマスクとマントのルチャドールになりたいと思ったという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（8:09〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=489s"]]}, {"cat": "家族", "t": "弟とベッドやソファでプロレスごっこ", "b": "子どものころは、実の弟と毎日のように家でルチャごっこをして遊び、ベッドやソファをリング代わりにしていたという。40歳になった今でも、ふと振り返って当時を思い出すことがあると話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（8:56〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=536s"]]}, {"cat": "家族", "t": "車を追いかけた弟が泣いた日", "b": "メキシコシティでレイ・ミステリオのサイン会に何時間も並んだことがあるそうだ。ミステリオが車で去ると、ペンタは6歳下の弟と車を追いかけて走ったが、写真は撮れず、弟は泣いてしまったという。ペンタは弟に「いつかきっと会える」となだめたと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（10:39〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=639s"]]}, {"cat": "リングに来るまで", "t": "ミステリオとの初対面は米国の大会の控室", "b": "本人どうしが初めて話したのは、アメリカ西海岸の大会の控室だったとペンタは話す。ミステリオがスペイン語で気さくにあいさつしてくれて、魔法のような時間だったと振り返る。その後、何度も対戦することになったそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（11:28〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=688s"]]}, {"cat": "リングに来るまで", "t": "ルチャ・アンダーグラウンドの激闘", "b": "ペンタはルチャ・アンダーグラウンドの大ファンで、そこでの試合を何度も思い出すという。テーブルなどを使った激しい試合が多く、伝説のヴァンピーロとの一戦はキャリアの転機になったと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（12:20〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=740s"]]}, {"cat": "リングの話", "t": "ヴァンピーロとの試合が転機に", "b": "ルチャ・アンダーグラウンドでの伝説のヴァンピーロ戦を、ペンタはキャリアの転機のひとつに挙げる。テーブルなど何でもありの激しい試合で、今も印象深いと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（13:11〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=791s"]]}, {"cat": "暮らし", "t": "素顔は絶対に見せないと決めている", "b": "ペンタはマスクを脱いだ姿を見せない。素顔のときは子どもも親も友人もいる一人の人間で、その私生活を大切にしたいからだと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（13:56〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=836s"]]}, {"cat": "リングの話", "t": "二代目ではなく初代ペンタになりたい", "b": "ミステリオと比べられることについて、ペンタは憧れの存在で尊敬しているが、次のミステリオになりたいわけではないと答える。スタイルも違うので、WWEで最初のペンタになりたいのだという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（13:56〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=836s"]]}, {"cat": "暮らし", "t": "息抜きはフロントンと雄牛乗り", "b": "素顔のペンタは、メキシコの庶民的なスポーツ「フロントン」が好きだという。ブルライダーを見るのも好きだと話す。マスクをかぶり、ギアを着けると、気持ちが切り替わって別人のようになると語る。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（14:46〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=886s"]]}, {"cat": "暮らし", "t": "マスクを外すと感じることは全部感じる", "b": "マスクをつけているときは何も感じず、外して一人の人間に戻ると、あらゆる感情を感じるとペンタは話す。この切り替えが自分にとって本当のことだという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（15:33〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=933s"]]}, {"cat": "リングの話", "t": "炎の入場はトリプルHの発案", "b": "炎を使った入場は、すべてトリプルHのアイデアだとペンタは話す。ドラゴンは火を吹くので、炎を背にすると力があふれるように感じるという。テレビで見ると、大スターになった気分になるそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（17:54〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1074s"]]}, {"cat": "リングに来るまで", "t": "心で話すから英語でも伝わる", "b": "英語が完璧でないことは自分でも分かっていると、ペンタは話す。それでも魂で話せば客席にもテレビの向こうにも伝わると考えているそうだ。作ったキャラではなく、自分そのままだという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（18:44〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1124s"]]}, {"cat": "リングに来るまで", "t": "初めての米国で空腹でも英語が話せなかった", "b": "7〜8年前、初めてアメリカのロサンゼルスに来たとき、英語がほとんど話せず、食べ物を頼むのも大変だったとペンタは振り返る。「困るのはそっちの問題」と思われたこともあったという。その悔しさもあり、のちに英語の勉強を続けたそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（19:33〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1173s"]]}, {"cat": "家族", "t": "実の弟フェニックスは世界一のレスラー", "b": "ペンタは実の弟のフェニックスを「世界最高のレスラー」と呼ぶ。タッグではコーナーで弟の動きを楽しめるし、シングルでは自分一人で観客と向き合えると話す。どちらも好きで、選べないという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（20:22〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1222s"]]}, {"cat": "暮らし", "t": "NFL選手が親友になったいきさつ", "b": "数年前、ニューオーリンズの大会で、ペンタの試合を見ていたNFL選手が楽屋を訪ねてきた。その選手は自分のユニフォームをくれて、ペンタはマスクと交換したという。以来、親友になり、メキシコ遠征にも連れて行く仲だと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（23:37〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1417s"]]}, {"cat": "暮らし", "t": "ほかの競技の選手も決めポーズをまねる", "b": "ペンタの決めポーズを、サッカー選手やメキシコの女子ボクサーなどが試合の場でまねしているという。自分の言葉がライフスタイルとして広がっていることに責任を感じ、毎日心と体を磨いていると話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（25:21〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1521s"]]}, {"cat": "体のこと", "t": "ホテルの鏡の前で自分を励ます夜", "b": "試合後に体が痛む夜は、ホテルの部屋で鏡に向かい「まだやれる」と自分に言い聞かせるとペンタは話す。悪いことを考える時間はなく、明日はまた新しい日だと気持ちを切り替えるそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（26:54〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1614s"]]}, {"cat": "リングの話", "t": "自分のデストロイヤーは情熱が違う", "b": "ペンタは自分の技をメキシカン・デストロイヤーと呼ぶ。他の選手と同じ技でも、情熱とエネルギーで差が出ると話す。試合の中で最高の瞬間を待って決めるそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（28:27〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1707s"]]}, {"cat": "暮らし", "t": "試合は必ず見返して直す", "b": "ペンタは毎試合後に映像を見返し、直すところを探すという。WWEのスタイルは違うので、基本の技を磨きつつ新しい技も増やしているそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（30:05〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1805s"]]}, {"cat": "家族", "t": "家族が自分を支える一番の柱", "b": "最前列で見ていた家族は、仕事でも私生活でも一番大切な柱だとペンタは話す。デビュー後のマイクはストーリーを考えず、心のままに話したという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（32:36〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1956s"]]}, {"cat": "リングの話", "t": "四つのテーブルを突き抜けた技の後悔", "b": "王座を獲った技で、ダンテ・マーティンがテーブルを突き抜けた場面について、ペンタは友人を傷つけた気がして心が痛んだと話す。危険な技だったので、その記憶は消したいほどだという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（36:35〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=2195s"]]}, {"cat": "リングの話", "t": "契約なしで取ったインパクト世界王座", "b": "ペンタは、TNA（インパクト）で世界王座を獲ったとき、実は契約を結んでいなかったと話す。相手はオースティン・エリーズで、特別な経験だったという。次はWWEでの初ベルトを狙いたいと語る。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（37:25〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=2245s"]]}, {"cat": "家族", "t": "感謝していることは家族と仕事と未来", "b": "最後の質問で、感謝していることを3つ尋ねられると、ペンタは家族、仕事、これからの未来を挙げた。英語の拙さを謝りながらも、心にあることを伝えたかったと話す。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-VvoGXeWu26k", "src": [["番組のYouTube（39:55〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=2395s"]]}]);
  if (PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"].facts.push({"cat": "暮らし", "t": "食事をともにして教えてくれた先輩", "b": "メキシコで初めて会ったとき、有名なスターなのに一緒に食事をして、普通の人として接してくれたと、ペンタが話している。その姿から、大スターになる道を教わったという。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で、ペンタの話（字幕を全文確認）", "src": [["番組のYouTube（31:44〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1904s"]], "by": "第三者の話"});
  if (PROFILES["Rey Fenix"]) PROFILES["Rey Fenix"].facts.push({"cat": "暮らし", "t": "実の兄弟でもあるタッグの相棒", "b": "弟のフェニックスは世界一のレスラーで、コーナーから弟の動きを見るのが楽しいと、ペンタが話している。WWEでの共演は、タッグでもシングルでもいいと考えているそうだ。", "sp": "ペンタ", "d": "2025-02-08", "how": "クリス・ヴァン・ヴリートの番組で、ペンタの話（字幕を全文確認）", "src": [["番組のYouTube（20:22〜）", "https://www.youtube.com/watch?v=VvoGXeWu26k&t=1222s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-VvoGXeWu26k", d: "2025-02-08", show: "ext", who: ["Penta"], t: "ペンタの回　20年の夢と、家族と、マスクの下の素顔", lead: "クリス・ヴァン・ヴリートの番組に出た約41分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Penta"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-VvoGXeWu26k").map((x) => [x.t, x.b, x.sp])), open: ["NFL選手の友人は、字幕で名前が崩れていたため名前を載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=VvoGXeWu26k"]] });
  if (!ROSTER.find((r) => r[1] === "Ric Flair")) ROSTER.push(["リック・フレアー", "Ric Flair", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Ric Flair"]) PROFILES["Ric Flair"] = { lead: "「ネイチャー・ボーイ」として一時代を築いた殿堂入りレスラー。大病を乗り越え、家族への思いと破天荒な半生、仲間への敬意を率直に語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ric%20Flair"]], moves: [], facts: [] };
  if (PROFILES["Ric Flair"]._weak) { PROFILES["Ric Flair"].lead = "「ネイチャー・ボーイ」として一時代を築いた殿堂入りレスラー。大病を乗り越え、家族への思いと破天荒な半生、仲間への敬意を率直に語る。"; delete PROFILES["Ric Flair"]._weak; }
  PROFILES["Ric Flair"].facts.push(...[{"cat": "体のこと", "t": "倒れてから約2年、体調は絶好調", "b": "8月17日に倒れてから2年ほどたち、入院とリハビリを経て9月末に退院したという。記憶は翌年の2〜3月ごろに戻り、先のことは覚えられても過去が思い出せない時期があったそうだ。心臓の処置も短期間に4回受けたと話す。今は「最高の気分」だと語っている。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（0:48〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=48s"]]}, {"cat": "暮らし", "t": "旅暮らしと酒は、行き過ぎた時期もあった", "b": "道の上が家のような生活で、酒の付き合いも多く、「ときどきやりすぎた」と認めている。若い頃の生活は楽しかったと振り返りつつ、節度の大切さを今は意識していると話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=98s"]]}, {"cat": "家族", "t": "3か月旅して1日だけ帰る暮らしだった", "b": "数か月家を空けて1日だけ帰る生活では、家のことを何も解決できず、帰るのが苦手になったという。年上の子どもたちはミネアポリスに住んでいて、下の子たちが生まれる前はむしろ帰るのが楽しみだったそうだ。目的地の前日に高級ホテルへ先に入り、自分を大物だと思っていたと笑う。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（2:29〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=149s"]]}, {"cat": "家族", "t": "若い頃、下の子との時間を作れなかった悔い", "b": "若いうちに仕事を断って、下の子どもたちとしっかり過ごせばよかったと、感情的になりながら語っている。実際に子どもと過ごせたのは、会社から外されたり休んだりした時期だけで、それが人生で最高の日々だったという。今は妻ウェンディの子どもたちと旅行に出かけ、スイスへの旅も決まったと話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（3:15〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=195s"]]}, {"cat": "暮らし", "t": "移動先で服を買い、いつも一流の装い", "b": "遠征の道中で新しい服を買い足し、いつも高級に見えるようにしていたという。カンザスシティの仕立て店のスーツは1着1500ドルほどだと話す。身なりへのこだわりは、昔から変わらないそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（4:56〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=296s"]]}, {"cat": "家族", "t": "身なりの原点は医師だった父の教え", "b": "父は医師で、いつもきちんとした服装だったという。子どもの頃、「診察室にサンダルとジーンズで現れたら患者はどう思う」と言われた言葉が、のちの装いの考え方につながったと話す。当時はその意味の大きさに気づいていなかったそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（6:30〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=390s"]]}, {"cat": "リングの話", "t": "顔から倒れる名物の受け身の由来", "b": "若い頃にタッグを組んだジョニー・ヴァレンタインが、ロープに振られても走らず、ただ倒れていたのを見て面白いと思ったという。そこから、もう少し見せ場になるようにと自分流の倒れ方を作ったと話す。本当の理由は、お客さんが喜んでくれたからだそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（7:16〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=436s"]]}, {"cat": "暮らし", "t": "レブロンに「スワッグの創始者」と呼ばれる", "b": "バスケットボール選手のレブロン・ジェームズが、子どもの頃にテレビで見たロレックスやリムジンの暮らしに憧れ、それが自分をトラブルから遠ざけたと語ってくれたという。そう評価されたことをとても誇らしく思っているそうだ。翌日はレブロンの試合を観に行く予定だったと話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（11:12〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=672s"]]}, {"cat": "リングの話", "t": "初めての王座は、まだ準備ができていなかった", "b": "初めて王者になったときは、各地を回っても勝手がつかず苦しんだという。相手ごとに試合を組み立てる術を学ぶ必要があり、2度目に王座についたときに、ようやく一人前になれたと話す。2度目は大物の対戦相手が各地に揃っていて、会場も満員が続いたそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（18:24〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=1104s"]]}, {"cat": "リングの話", "t": "ヴェイダー戦で相手の師匠に叱られた", "b": "シャーロットでの王座戦は、予定の相手が出場停止になったため急きょ引き受けたという。試合中に相手が本気で攻めてきたため、フレアーも反撃したところ、相手のマネージャーだったハーリー・レイスに「自分自身を恥ずかしめているぞ」と声をかけられたと話す。フレアーは本気で応じて相手の目の周りを腫らせたが、のちの試合後には何も言われなかったそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（22:28〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=1348s"]]}, {"cat": "家族", "t": "息子の一言でムーンサルトに挑みかけた", "b": "息子のリードに「ムーンサルトはできる？」と聞かれ、できないと答えたものの気になったという。体操をしていた娘のコーチを訪ね、安全ベルトをつけて練習できないか相談したと笑って話す。結局、挑戦はしなかったそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（26:31〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=1591s"]]}, {"cat": "リングの話", "t": "観客が沸いている間は、相手を止めない", "b": "会場の反応は町ごとに違い、幕の向こうに出るまで分からないと話す。客席が大盛り上がりなら、その勢いをそぐ必要はないというのが持論だという。タッグ戦でも、相方の「そろそろ攻めを止めろ」という声に、長く楽しませた方がいいと考えていたそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（35:23〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=2123s"]]}, {"cat": "リングの話", "t": "3番手から1時間超、年間最大の祭典の優勝", "b": "1992年の大乱戦形式の大会に3番目に登場し、1時間以上リングに立ち続けたという。前夜は同僚とずっと飲み歩いていたが、緊張せず、ただ出られるのが嬉しかったそうだ。優勝後のインタビューでは思わず涙が出て、「人生で最高の瞬間」と語ったのは、考える間もなく出た本音だったと話す。その夜は、ホテルでマティーニを12杯以上飲んだという。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（40:17〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=2417s"]]}, {"cat": "好きなもの", "t": "金とダイヤのロレックスが好きで、4本失った", "b": "腕時計は金とダイヤのロレックスが好みで、ステンレスは身につけないと話す。ヨーロッパ巡業ではアンダーテイカーに4本も取られたという。ヨーロッパ巡業は楽しい思い出ばかりだそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（54:06〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=3246s"]]}, {"cat": "リングの話", "t": "若きスティングを、60分近い試合に導いた", "b": "スティングを60分の試合に導いたが、実際は55分ほどだったという。スティングは穏やかで気取らない人柄で、限られた動きの中でも自然に見せ場を作れる選手だったと話す。最後にはお客さんも熱狂し、フレアーは今も称賛の言葉が尽きないそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（54:56〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=3296s"]]}, {"cat": "家族", "t": "妻ウェンディに出会うまで63年かかった", "b": "落ち着くまでに長い時間がかかり、自分で悪い選択を重ねてきたと話す。倒れて入院していた間、妻のウェンディが31日間ずっとそばにいて、病室から離れなかったという。今は、財産よりも大切な人がいることがすべてだと感じているそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（57:29〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=3449s"]]}, {"cat": "暮らし", "t": "浮き沈みのあったお金の話", "b": "裕福な時期も、お金に苦しんだ時期もあったと振り返る。ビンス・マクマホンにお金を借りたときに破産を勧められたが、自分に誠実でいたくて断り、返済したという。今は借金がないと話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（59:12〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=3552s"]]}, {"cat": "リングの話", "t": "自信を失っていた時期に、アンダーテイカーが相手に", "b": "復帰後は周りがみんな年下で、なじめずにいたという。そんな中、アンダーテイカーが対戦相手に自分を選んでくれたと聞いて信じられなかったそうだ。入場の最中も、自分にできるのか不安だったが、試合を終えた後にジャック・ランザから「やり遂げたな」と声をかけられたと話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:01:35〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=3695s"]]}, {"cat": "体のこと", "t": "自信を失うと、取り戻すのは本当に難しい", "b": "2001年に復帰してから引退するまで、自信の浮き沈みと戦い続けたという。周りに褒められても、酒を飲んでも一時的に気分が上がるだけで、目が覚めれば同じ気持ちに戻ってしまったと話す。リングに上がって調子が出ると楽になることが多かったそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:08:08〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=4088s"]]}, {"cat": "リングの話", "t": "引退試合でショーン・マイケルズが全てを導いた", "b": "引退試合で、ショーン・マイケルズは試合前に「何も言わず、ついてこい」と告げたという。組み合った後もしゃべろうとすると「黙れ」と制され、試合を完全に任せることになったと話す。自分の調子が戻るまで15分ほどかかったが、7万5千人の観客の反応は想像を超えるもので、生涯で最高の瞬間だったそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:13:49〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=4429s"]]}, {"cat": "暮らし", "t": "別団体に出たのは、お金が必要だったから", "b": "別団体での出演は、お金が必要だったからだと率直に話す。午後3時に会場へ入り、夜7時にはホテルのバーにいたといい、仲間と過ごす時間は楽しかったそうだ。ただ、上層部のもとで働くのは好きではなく、そのことをビンスには深く謝ったと話す。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:17:57〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=4677s"]]}, {"cat": "暮らし", "t": "「ブランド」という考え方は、ずっと後で知った", "b": "数年前までブランドという言葉も知らなかったが、今はSNSや仕事の見せ方が大事だと感じているという。自分は無責任なタイプだが、今は妻のウェンディが責任を持たせてくれると話す。昔は財布の中身も気にせず、飛行機に乗って何とかなると思っていたそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:19:34〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=4774s"]]}, {"cat": "リングの話", "t": "口上の秘密は、生活そのものを語ったこと", "b": "マイクで話す内容は、誰かに台本を書いてもらったものではなく、自分が送っていた暮らしそのものだったという。派手なスーツ、トカゲ革の靴、ロレックス、長いリムジンといった話は、実際の自分の姿だったそうだ。口の立つ相手と組むと楽しくなるとも話している。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:22:49〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=4969s"]]}, {"cat": "リングの話", "t": "一番思い入れの深い抗争は、ダスティ・ローデスとの対決", "b": "最も楽しかった抗争はダスティ・ローデスとの長い戦いだと話す。毎日のように言い争う仲でもあったが、天才的で、話術もカリスマ性も抜群の人だったという。満員の会場で向き合った夜のことは、今も強く覚えているそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:27:39〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=5259s"]]}, {"cat": "好きなもの", "t": "「ウー！」は、昔好きだった音楽から生まれた", "b": "夜によくカントリー音楽を聴いていたという。ジェリー・リー・ルイスの「火の玉ロック」や、リトル・リチャードの歌声から、あの叫びを思いついたと話す。1974年に始めて、それ以来ずっと続けているそうだ。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:31:44〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=5504s"]]}, {"cat": "家族", "t": "娘のシャーロットは、自分より上手いと思う", "b": "娘のアシュリー（リング名シャーロット）は、最初はプロレスにあまり関心がなく、兄の影響で入ったという。本気で打ち込むようになってから一気に開花したと話す。偉大な父の影の下にいると言われがちだが、自分よりリングで優れているし、実力は父親の名前に関係ないと、強く言い切っている。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:32:29〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=5549s"]]}, {"cat": "暮らし", "t": "悪い面より良い面で覚えてほしい", "b": "振り返ると、悪意を持って何かをしたことはないが、制御できない時期があったと話す。家族を助けられたはずの場面でそばにいられなかったことは、今も心に残っているという。「最高のレスラー」より、周りの人に良い影響を与えた人として覚えられたいと語っている。", "sp": "リック・フレアー", "d": "2025-02-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-boMjMplnG3E", "src": [["番組のYouTube（1:36:30〜）", "https://www.youtube.com/watch?v=boMjMplnG3E&t=5790s"]]}]);
