  if (PROFILES["Angelo Dawkins"]._weak) { PROFILES["Angelo Dawkins"].lead = "シンシナティ育ちで、サッカーのレアル・マドリードに夢中なアンジェロ。母を亡くした悲しみと、二人の息子への思いまで率直に語った。"; delete PROFILES["Angelo Dawkins"]._weak; }
  PROFILES["Angelo Dawkins"].facts.push(...[{"cat": "暮らし", "t": "床屋は会社が連れてくる", "b": "ツアー中の散髪は、会社が理容師を同行させてくれると話す。専属の理容師を雇えるほどの余裕はない、と笑っている。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=242s"]]}, {"cat": "好きなもの", "t": "お笑いはバーニー・マック派", "b": "好きなコメディアンの一位はバーニー・マックだと言い切る。キャット・ウィリアムズも好きで、同じシンシナティ出身だという点にも親近感があるそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（6:25〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=385s"]]}, {"cat": "暮らし", "t": "靴のサイズは15", "b": "アメリカでも15は珍しい大きさで、チームメイトとモールへ行った際、店員に13と聞き間違えられたことがあるという。ほしい靴が自分のサイズでは見つからないのは日常だと話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（8:54〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=534s"]]}, {"cat": "好きなもの", "t": "結婚式を止めてサッカーを見た", "b": "結婚式が始まる直前、ユーロの初戦でベリンガムがバイシクルシュートを決めた。式を始めようとしていたのに試合を見届けたくなり、あと30分は待ってほしいとフィン・ベイラーにメッセージを送ったと話す。周りは呆れ、栄光だけ追う人だとからかっていたそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（11:19〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=679s"]]}, {"cat": "好きなもの", "t": "レアル・マドリードを好きになった理由", "b": "ロナウドだけが理由ではなく、入場時に歌われるクラブの歌を聞いて引き込まれたと話す。レスラーの入場曲のようで、これ以上の歌はないと熱く語る。選手ではマルセロ、セルヒオ・ラモス、ベリンガムなどが好きだという。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（12:54〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=774s"]]}, {"cat": "好きなもの", "t": "アトレティコ戦を現地で観戦", "b": "マドリードで、同じ街のライバルとのチャンピオンズリーグ第2戦を現地で見たという。マフラーやフラッグを持ち、黒い上着の下にベリンガムのユニフォームを着込んでいたため、周りの視線が痛かったと笑う。PK戦の判定には驚いたそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（14:32〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=872s"]]}, {"cat": "リングの話", "t": "ランディ・オートンとの関係", "b": "オートンとは仲が良く、昔から試合を研究してきたと話す。まだRKOを食らったことがない、と冗談めかして言う。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（21:44〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1304s"]]}, {"cat": "リングの話", "t": "レジェンド・オブ・ドゥームに憧れて", "b": "子どものころ好きだったタッグ王者はレジェンド・オブ・ドゥームだと話す。ストリート・プロフィッツの決め技は、彼らの技から受け継いだものだという。全盛期の彼らとなら面白い試合になると語る。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（24:56〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1496s"]]}, {"cat": "リングに来るまで", "t": "陸上・フットボール・レスリング", "b": "高校や大学ではスポーツをいくつも掛け持ちし、フットボールのロッカールームではビートボックスやDJ役を担うムードメーカーだったと話す。ただし大学は中退していると、自分から語っている。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（29:45〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1785s"]]}, {"cat": "リングに来るまで", "t": "子ども時代はケーブルがなかった", "b": "幼いころは家にケーブルがなく、プロレスを毎週見られる環境ではなかったという。それでもストーン・コールドやザ・ロック、アンダーテイカー、ケインなどの名前は知っていたと話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（30:33〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1833s"]]}, {"cat": "リングに来るまで", "t": "初めてのリングは腰にきた", "b": "トライアウトのときは、レスリングのシーズン明けで体は仕上がっていたのに、ロープに走る動きで腰がひどく痛んだという。マットやフィールドとはまったく別物で、走り方も倒れ方も慣れが要ると話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（32:09〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1929s"]]}, {"cat": "リングの話", "t": "ブラウン・ストローマンへの一撃", "b": "ブラウン・ストローマンの頭にぶつけた攻撃は、フットボールのタックルのような感覚だったと話す。その年の序盤にブラウンからテーブルへ叩きつけられていたので、お返しだったと笑う。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（33:01〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=1981s"]]}, {"cat": "リングの話", "t": "ブーイングも悪くない", "b": "試合ではまず全力を出すことだけを考えているという。観客が味方についてくれれば最高で、ブーイングならもっといいと話す。バルセロナでは相手の応援の中で堂々と戦えたそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（35:24〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2124s"]]}, {"cat": "リングの話", "t": "スペイン語のカウントに驚いた", "b": "バルセロナの会場では、レフェリーの数え声がスペイン語だったことに驚いたと話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（36:59〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2219s"]]}, {"cat": "リングの話", "t": "4年ぶりのタッグ王座", "b": "最後にタッグ王座を獲ったのは2020年で、その直後に世の中が止まってしまったと話す。その後は惜しいところで届かない時期が続き、数週間前にようやく戴冠したという。母の件もあり、この戴冠で肩の荷が下りたと話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（38:34〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2314s"]]}, {"cat": "家族", "t": "1年前に母を亡くした", "b": "去年の金曜、スマックダウンへ向かう支度中に母の訃報を知ったと話す。以来、毎週金曜は気持ちが重く、カメラの前では明るく振る舞っても、朝起きるたびにその日を思い返していたそうだ。タッグ王座を獲ったことで、少しだけ心が軽くなったという。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（39:21〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2361s"]]}, {"cat": "家族", "t": "レスラー志望への家族の反応", "b": "トライアウトを受けると母に伝えたとき、母は高校や大学で始めたときと同じように「ふうん、そう」という反応だったという。フロリダへ発つ前の親戚の集まりでも、祝う人もいれば冷ややかな冗談を言う人もいたそうだ。いまになって、あれは「百万人に一人の世界」だと思われていたからだと分かると話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（40:06〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2406s"]]}, {"cat": "リングに来るまで", "t": "インディー経験なしのWWE一筋", "b": "最初からインディー団体の経験はなく、WWEのやり方しか知らない状態で育ったという。上達を感じ始めて自信がついたころ、コーチに失敗を指摘された出来事があり、そのコーチは今でも自分をネタに若手へ話すそうだ。帰ってあいさつするたびに言われる、と笑う。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（43:19〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2599s"]]}, {"cat": "リングの話", "t": "ベテランから学び続ける", "b": "ランディ・オートン、レイ・ミステリオ、R・トゥルース、AJスタイルズなど、今も周りの先輩から学ぶことばかりだという。そうした豊富な知識を、みんなで引き出させてもらっていると話す。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（44:08〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2648s"]]}, {"cat": "暮らし", "t": "シンシナティ出身、オハイオっ子", "b": "生まれ育ちはオハイオ州シンシナティだと話す。NXT入りするまでに行った一番遠い場所はシカゴで、それも地元からのことだったという。オハイオ代表として、地元の偉人の話題にはよく乗っている。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（48:55〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2935s"]]}, {"cat": "リングに来るまで", "t": "育成部門に7年半いた", "b": "育成部門のNXTには7年半いたと話す。今の一軍のトップ陣は、同じ時期にNXTにいた仲間だという。海外経験の豊富なケビン・オーエンズやフィン・ベイラーのような先輩と比べ、自分は経験の浅さを自覚し、謙虚に学ぼうとしたそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（49:44〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2984s"]]}, {"cat": "リングに来るまで", "t": "静かに努力する姿を見られていた", "b": "自分は静かでのんびりして見えるが、黙って練習に打ち込んできたと話す。その姿を先輩たちも見ていて、フィンやケビンなどとは今も仲が良いという。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（50:33〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3033s"]]}, {"cat": "暮らし", "t": "自宅のゲーム部屋", "b": "自宅にゲーム部屋があり、テレビを何台も置いているという。ジョン・シナの悪役転向を見た夜も、片方の画面で大会を流し、もう片方で大学フットボールのゲームを遊んでいたそうだ。子どもたちは寝ていて、妻も別のことをしていたという。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（56:13〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3373s"]]}, {"cat": "リングの話", "t": "シナの悪役転向を自宅で見た", "b": "エリミネーション・チェンバーの放送を自宅で見ていて、シナの動きに驚いたと話す。どうなるのかと画面に釘づけになったそうだ。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（56:13〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3373s"]]}, {"cat": "リングの話", "t": "初めてのアクションフィギュア", "b": "自分のアクションフィギュアが出たとき、家族や友人へのプレゼントが一番楽になると思ったという。冗談まじりに、「クリスマスには何をくれるんだ」と周りに言ってみたくなったと笑う。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（1:00:14〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3614s"]]}, {"cat": "家族", "t": "二人の息子の父", "b": "息子が二人いて、下は生後6か月、上は4歳でもうすぐ5歳になると話す。上の子は父の仕事にかなり興味を示しているそうだ。どのスポーツをやってもいいが、学校はきちんと終えてほしいと伝えるつもりだという。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（1:01:52〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3712s"]]}, {"cat": "家族", "t": "妻は学校の副校長", "b": "妻は学校の副校長で、息子の宿題は妻に任せればいいとおどけて話す。家族みんなでフロリダに住んでいるという。子どもが望むことには、自分がいまは資源を用意してあげられる立場にあると語る。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で（字幕を全文確認）", "art": "ext-LnLpKv_wZ_E", "src": [["番組のYouTube（1:03:31〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=3811s"]]}]);
  if (PROFILES["Montez Ford"]) PROFILES["Montez Ford"].facts.push({"cat": "暮らし", "t": "年初に祖父を亡くした", "b": "モンテス・フォードは年初に祖父を亡くし、気持ちの面でつらい時期を過ごしていたと、アンジェロ・ドーキンスが話している。", "sp": "アンジェロ・ドーキンス", "d": "2025-04-08", "how": "フロム・マイ・レフトの番組で、アンジェロ・ドーキンスの話（字幕を全文確認）", "src": [["番組のYouTube（39:21〜）", "https://www.youtube.com/watch?v=LnLpKv_wZ_E&t=2361s"]], "by": "第三者の話"});
