  if (!PROFILES["Swerve Strickland"]) PROFILES["Swerve Strickland"] = { lead: "インディーとルチャで名を上げ、育成施設NXTを経てスマックダウンへ。ドラフトの約1か月後にまとめて解雇されるまでの歩みを振り返る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Swerve%20Strickland"]], moves: [], facts: [] };
  if (PROFILES["Swerve Strickland"]._weak) { PROFILES["Swerve Strickland"].lead = "インディーとルチャで名を上げ、育成施設NXTを経てスマックダウンへ。ドラフトの約1か月後にまとめて解雇されるまでの歩みを振り返る。"; delete PROFILES["Swerve Strickland"]._weak; }
  PROFILES["Swerve Strickland"].facts.push(...[{"cat": "WWEでの日々", "t": "WWE入りのきっかけは一戦", "b": "スワーブはルチャ・アンダーグラウンドでの有刺鉄線とガラスの激闘が、2019年のWWEとの契約につながったと思うと話す。あの試合の話題が広まり、知らない相手でも「あの試合の人」と通じる状態を狙っていたという。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（29:27〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=1767s"]]}, {"cat": "WWEでの日々", "t": "インディー出身の同期と入団", "b": "育成施設NXTには、インディーや日本の団体から来た選手が同じ時期にまとめて入ったという。トレヴァー・リー、AC・ガルザ、キース・リーらの名前を挙げ、全員でリング名を考え直すことになったと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（31:54〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=1914s"]]}, {"cat": "WWEでの日々", "t": "アイザイア・スコットという名前", "b": "好きなラッパー2人にちなんでアイザイア・スコットを名乗ったそうだ。「スワーブ」の名は会社に貸す形にして、解雇されたら自分に戻る約束にしていたという。スワーブはビッグ・ショーンの曲の掛け声から取ったと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（32:45〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=1965s"]]}, {"cat": "WWEでの日々", "t": "トリプルHとは噛み合わなかった", "b": "スワーブはトリプルHに実力は認められていたが、ほかの選手を食わないよう抑えて使われていたと感じていたという。ドラフト下位の選手を使えば上位指名の選手が霞む、というたとえで説明している。今も関係は良好だと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（33:34〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2014s"]]}, {"cat": "WWEでの日々", "t": "「あなたの秘蔵っ子にしてほしい」", "b": "数か月おきに、トリプルHに自分を主力として使ってほしいと直接頼んだという。1年たっても話がはぐらかされるので、何が障害なのかと正面から聞いた。トリプルHは制作担当との面談を段取りしてくれたそうだ。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（35:11〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2111s"]]}, {"cat": "WWEでの日々", "t": "ケガの間に自分でキャラ変更", "b": "半月板を痛めて数週間テレビを離れた間に、復帰後の見た目と役柄を自分で作り替えたという。創作側の許可は取らずに進めたが、ウィリアム・リーガルは気に入ってくれたと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（36:01〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2161s"]]}, {"cat": "WWEでの日々", "t": "205 Liveで18分の勝負", "b": "スマックダウンの後に行われる番組で、ドリュー・ガルークのクルーザー級王座に挑み、18分戦って敗れたという。観客は「スワーブ」コールで応援してくれ、控室でも多くの選手に褒められたそうだ。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（36:51〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2211s"]]}, {"cat": "WWEでの日々", "t": "大舞台のあとの基礎練習に不満", "b": "6000人の前で戦った翌日に、育成施設で基本の受け身から教え直されて納得がいかなかったという。スワーブはこれをNBAで30点取った選手をGリーグに戻すようなものだと例えている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（37:36〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2256s"]]}, {"cat": "WWEでの日々", "t": "ショーン・マイケルズとは気が合った", "b": "スワーブは、トップに立つ術を本当に教えられるのはショーン・マイケルズだけだと考えていたという。トリプルHは本編の仕事で不在も多く、ショーンが現場で選手を見ていたと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（38:25〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2305s"]]}, {"cat": "WWEでの日々", "t": "契約残り1年半での本音", "b": "昇給の面談で、自分の価値を分かっていると伝え、契約が切れるまでに結果を出してほしいと話したという。本人はこの発言を後から思い出して語っている。希望を聞かれ、ショーンの教えを受けたいと答えた。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（39:10〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2350s"]]}, {"cat": "WWEでの日々", "t": "ショーンの事務所を訪ねて映像研究", "b": "ショーンの事務所は目の前だと言われ、その場で訪ねると、映像を一緒に見る勉強会を快く受けてくれたそうだ。1年半も遠回りしていたが、そういう道筋は誰も教えてくれないと話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（40:51〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2451s"]]}, {"cat": "WWEでの日々", "t": "ヒット・ロウ結成の裏側", "b": "ショーンからトリップス（トリプルH）が見たがっているものを聞かされ、ブロンソン・リードとの試合で出し切ったという。のちに6人制の戦いで25分もたせると、ステファニー・マクマホンから「番組で一番好きなヒール」と声をかけられたそうだ。その流れでヒット・ロウが生まれたと、スワーブは受け止めている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（41:40〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2500s"]]}, {"cat": "WWEでの日々", "t": "スマックダウン入りと初の本編契約", "b": "ヒット・ロウは10月のボルチモアでスマックダウンにドラフトされたという。ヴィンスと会って本隊の契約に署名したことを、長い下積みが報われた瞬間として語っている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（43:23〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2603s"]]}, {"cat": "退団の理由", "t": "飛行機の中で解雇を知った", "b": "ドラフトの4週間後、グループの一人だけ飛行機の手配が来ないまま、全員で移動したという。着陸前から同僚の解雇の知らせが次々に届き、同じ日にグループの8人ほどが解雇されたとスワーブは話す。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（45:47〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2747s"]]}, {"cat": "退団の理由", "t": "コロナ禍の人員整理だったと本人は見る", "b": "その年は会社全体で約150人の出演者とスタッフが切られたと、スワーブは聞いている。巡業ができない中で番組を続けるためにコストを抑える必要があったからだと受け止めている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（46:37〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2797s"]]}, {"cat": "退団の理由", "t": "ヴィンスとの面会で叱られた", "b": "グループ内の問い合わせの件で、ヴィンスと廊下で話すことになったという。他人のことは気にせず自分の仕事に集中しろと言われたそうだ。スワーブは、この件で自分たちにも心証が悪く映ったのではと考えている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（47:26〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2846s"]]}, {"cat": "退団の理由", "t": "解雇の2週間前にまとめ役を任された", "b": "番組の演出に満足されなかったらしく、メンバーの一人が急病で欠場したこともあったという。リハーサル前、ブルース・プリチャードから「最古参のお前が仕切れ」と言われたが、その2週間後に全員が解雇された。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（49:53〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2993s"]]}, {"cat": "退団の理由", "t": "噂は多いが真相は分からない", "b": "解雇後にはさまざまな報道や噂が出て、特定の一人が原因だという話も耳にしたとスワーブは話す。本人にも確かなことは分からないとしている。その後は90日間、次の仕事に就けない期間を過ごしたという。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（50:38〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=3038s"]]}, {"cat": "WWEでの日々", "t": "WWEを経由してよかったと思う", "b": "解雇が報じられると、他団体の社長がすぐ動いたと聞いたそうだ。実はWWEから声がかかる前にも、その団体が自分に関心を持っていたという。それでも、WWEでの経験があったから今の物語に重みが出たと考えている。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（53:08〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=3188s"]]}, {"cat": "WWEでの日々", "t": "NXTでは却下されたホッチキス案", "b": "ホッチキスを凶器に使う案をNXT時代に出したが、ショーン・マイケルズに即座に断られたという。普通のステープラーならと食い下がっても通らなかったそうだ。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で（字幕を全文確認）", "art": "ext-w1qr-N3BqWA", "src": [["番組のYouTube（1:06:17〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=3977s"]]}]);
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "主力になる術を教えられる唯一のコーチ", "b": "NXTのコーチの中で、スター選手の育て方を本当に教えられるのはショーン・マイケルズだけだったと、スワーブが話している。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で、スワーブ・ストリックランドの話（字幕を全文確認）", "src": [["番組のYouTube（38:25〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2305s"]], "by": "第三者の話"});
  if (PROFILES["Stephanie McMahon"]) PROFILES["Stephanie McMahon"].facts.push({"cat": "暮らし", "t": "「一番好きなヒール」と声をかけた", "b": "6人制の戦いの後で、番組で一番好きな選手だと直接言われたと、スワーブが話している。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で、スワーブ・ストリックランドの話（字幕を全文確認）", "src": [["番組のYouTube（42:31〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2551s"]], "by": "第三者の話"});
  if (PROFILES["William Regal"]) PROFILES["William Regal"].facts.push({"cat": "暮らし", "t": "新しいキャラを気に入った", "b": "自分で作り替えた役柄を見て、自分の現役時代にも思いついていたかったと喜んでくれたと、スワーブが話している。", "sp": "スワーブ・ストリックランド", "d": "2025-04-10", "how": "ヴラッドTV（DJ Vlad）で、スワーブ・ストリックランドの話（字幕を全文確認）", "src": [["番組のYouTube（36:01〜）", "https://www.youtube.com/watch?v=w1qr-N3BqWA&t=2161s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-w1qr-N3BqWA", d: "2025-04-10", show: "ext", who: ["Swerve Strickland"], t: "スワーブ・ストリックランドの回　NXT時代と解雇までの全部", lead: "ヴラッドTV（DJ Vlad）に出た約117分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Swerve Strickland"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-w1qr-N3BqWA").map((x) => [x.t, x.b, x.sp])), open: ["生い立ち、家庭、他団体での日々の話は公開項目に含めていない。", "解雇前後の第三者の言動や噂は、本人も確証がないと話しているため、断定を避けて要約した。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=w1qr-N3BqWA"]] });
  if (!ROSTER.find((r) => r[1] === "Shawn Michaels")) ROSTER.push(["ショーン・マイケルズ", "Shawn Michaels", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"] = { lead: "親友トリプルHを殿堂に送り出す紹介役として登壇。30年来の友情と、NXTで上司と部下になった今の関係を笑いを交えて語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Shawn%20Michaels"]], moves: [], facts: [] };
  if (PROFILES["Shawn Michaels"].lead === "親友トリプルHを殿堂に送り出す紹介役として登壇。30年来の友情と、NXTで上司と部下になった今の関係を笑いを交えて語る。") PROFILES["Shawn Michaels"]._weak = 1;
  PROFILES["Shawn Michaels"].facts.push(...[{"cat": "リングの話", "t": "親友を殿堂に送り出す夜", "b": "親友のトリプルHを殿堂入りさせる役を任され、自分にとって特別な夜だと話した。自分はクリックの仲間たちと、彼が入ってきた最初のころから見てきたと語る。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（1:57:28〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7048s"]]}, {"cat": "家族", "t": "妻たちにも誓った関係", "b": "2人の仲を怪しむファンがいるのは知っていて、実は自分の妻も気にしていたという。2人がキスしたのは生中継のテレビの前だけだと、妻たちにも観客にも約束すると笑わせた。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:00:39〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7239s"]]}, {"cat": "暮らし", "t": "「変わった自分」を自虐", "b": "若いころの自分は付き合いやすい人間ではなく、周りの多くは離れていったが、トリプルHだけは親友でい続けてくれたという。いつか自分がまともな人間に生まれ変わるとは知らなかったはずなのに、と自虐まじりに話す。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:03:02〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7382s"]]}, {"cat": "リングの話", "t": "1本の電話から始まったNXTの仕事", "b": "NXTの仕事は「ちょっと寄って見ていかないか」という電話から始まったという。最初は週3日、1日2時間だったのが、今では休みのない毎日になったが、何にも代えがたい仕事だと話す。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:06:57〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7617s"]]}, {"cat": "暮らし", "t": "夜9時に寝るのに深夜1時のメール", "b": "夜9時に寝る自分のもとに、上司のトリプルHから深夜1時にメールが届くと嘆いた。90年代に自分がさんざん振り回した仕返しをされているのだと気づいたと笑い、それでも当時彼が自分を見捨てなかったように、自分も彼のもとを離れないと語った。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:07:48〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7668s"]]}]);
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "最初はただのレスラー志望だった", "b": "入ってきたころのトリプルHは、業界一の権力者になろうとしていたわけではなく、ただプロレスラーになりたいだけの若者で、自分の価値を証明しなければと分かっていたと、ショーン・マイケルズが話している。「上司の娘と結婚したから」という見方は違い、誰よりも働く人だから実績は変わらなかったはずだという。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で、2025年WWE殿堂入り式典の話（字幕を全文確認）", "src": [["番組のYouTube（1:59:01〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7141s"]], "by": "第三者の話"});
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "車中の夢が形になったNXT", "b": "昔、移動の車の中で「いつもこんなふうに熱くいられたら」と2人で語り合っていたことを、トリプルHはNXTという形で実現したと、ショーン・マイケルズが話している。13年たち、年間最大の祭典のカードのほとんどがNXT出身者になったという。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で、2025年WWE殿堂入り式典の話（字幕を全文確認）", "src": [["番組のYouTube（2:04:36〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7476s"]], "by": "第三者の話"});
  if (PROFILES["Triple H"]) PROFILES["Triple H"].facts.push({"cat": "暮らし", "t": "会社の未来を任せられる人", "b": "有名ミュージシャンとの共演から看板選手との仕事まで幅広くこなし、経営と現場の両方を、リングで起きることへの愛を失わずに回せる人で、会社を未来へ導くのに彼以上の人はいないと、ショーン・マイケルズが話している。", "sp": "ショーン・マイケルズ", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で、2025年WWE殿堂入り式典の話（字幕を全文確認）", "src": [["番組のYouTube（2:09:21〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=7761s"]], "by": "第三者の話"});
  if (!ROSTER.find((r) => r[1] === "Triple H")) ROSTER.push(["トリプルH", "Triple H", "lg", "WWEの最高責任者", "", "", ""]);
  if (!PROFILES["Triple H"]) PROFILES["Triple H"] = { lead: "殿堂入りの夜、自分をここまで押し上げてくれた人たちを一人ずつ挙げて感謝を伝える。心不全で倒れた経験から、何が大切かを見直したとも語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Triple%20H"]], moves: [], facts: [] };
  if (PROFILES["Triple H"].lead === "殿堂入りの夜、自分をここまで押し上げてくれた人たちを一人ずつ挙げて感謝を伝える。心不全で倒れた経験から、何が大切かを見直したとも語る。") PROFILES["Triple H"]._weak = 1;
  PROFILES["Triple H"].facts.push(...[{"cat": "リングの話", "t": "親友の紹介に涙が止まらず", "b": "ショーン・マイケルズの紹介を聞きながら15分ほど泣いていたので、水分が足りないかもしれないと笑わせてから話し始めた。本当の友人が一人いれば人は豊かだと言われるが、ショーンのおかげで自分は大富豪だと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:13:42〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8022s"]]}, {"cat": "リングの話", "t": "自分の話ではなく恩人の話", "b": "スピーチを考えるほど難しくなり、これは自分ではなく自分をここへ連れてきてくれた人たちの話だと気づいたという。自力だけで成功した人間などこの世にいない、というのがこの夜の軸になっている。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:17:55〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8275s"]]}, {"cat": "リングに来るまで", "t": "5、6歳で見たストロングボウ", "b": "ニューハンプシャーの子どもだった5、6歳のころ、父親のひざの上でチーフ・ジェイ・ストロングボウを見て、それからはプロレスしか考えなくなったという。やりたいこと、なりたいものはそれだけだったと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:17:55〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8275s"]]}, {"cat": "家族", "t": "働く姿勢を教えた両親", "b": "両親から教わったのは、金持ちになるためではなく、それが正しいから懸命に働くという姿勢だったという。信じるものがあるなら手に入るまで働け、と教えられたそうだ。式典の夜はちょうど両親の結婚61周年だった。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:18:41〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8321s"]]}, {"cat": "家族", "t": "いじめっ子をこらしめた姉", "b": "4歳上の姉がいて、子どものころ年上の子に殴られて帰ると、姉が家を飛び出してその子をやり返してくれたという。いつも味方でいてくれる人だと話し、姉の子どもたちも会場に来ていた。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:20:13〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8413s"]]}, {"cat": "リングに来るまで", "t": "14歳でジム通いを始める", "b": "テレビの選手のように大きくならなければと考え、14歳でジムに通い始めて夢中になったという。身長185センチほどで体重60キロ足らずのひょろひょろの少年を、年上のトレーニング仲間が鍛え上げてくれたそうで、40年来の友人だと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:20:59〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8459s"]]}, {"cat": "好きなもの", "t": "シュワルツェネッガーが手本", "b": "そのころ映画でアーノルド・シュワルツェネッガーを知り、彼の本を人生の設計図のように読んだという。努力すればするほど得るものも大きいと学び、今も変わらず尊敬するお手本だと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:22:30〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8550s"]]}, {"cat": "リングに来るまで", "t": "「この世界には来るな」と言われて", "b": "20代前半、業界にいた力自慢の先輩にどこで練習すればいいかを聞くと、「君はいい子だからこの業界はやめておけ」と止められたという。それでも諦められず、キラー・コワルスキーを紹介してもらったそうだ。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:24:07〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8647s"]]}, {"cat": "リングに来るまで", "t": "月謝は払えるときでいい", "b": "コワルスキーの冷房もない硬いリングで初めて練習した日、これが自分の道だと感じたという。まだ月謝が払えないと伝えると、「明日も来い、払えるときに払えばいい。お前は大スターになる」と言われ、その言葉は一生忘れないと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:25:03〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8703s"]]}, {"cat": "リングの話", "t": "WCWで出会った恩人たち", "b": "WCWに雇ってくれたのはエリック・ビショフで、最初に会ったのは、その日がブッカー最後の日だったダスティ・ローデスだったという。ダスティには後に「ブッキングは楽じゃないぞ」と教わり、今もその言葉を胸に刻んでいるそうだ。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:26:34〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8794s"]]}, {"cat": "暮らし", "t": "酒を飲まないので運転役", "b": "WCW時代、アーン・アンダーソンに試合後の外出に誘われ、酒も薬もやらないと分かると毎晩の運転役になったという。夜中にポパイズのフライドチキンを買いに行かされたが、その分たくさんのことを教わったと笑う。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:28:04〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=8884s"]]}, {"cat": "暮らし", "t": "アトランタで家族になってくれた人", "b": "テリー・テイラーに声をかけられ、育成施設パワープラントに毎日通ってウィリアム・リーガルとも練習したという。家族と仲が良かったので一人のアトランタは寂しかったが、テイラーが家に招いて家族のように迎えてくれたと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:31:18〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9078s"]]}, {"cat": "リングの話", "t": "「WWFへ行け」と背中を押したリーガル", "b": "リーガルとはWCWでコンビを組む予定だったが、本人は毎日のように「ここを出てWWFへ行き、スターになれ」と言ってくれたという。今も親友の一人で、リーガルのためなら体を張れると話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:32:55〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9175s"]]}, {"cat": "リングの話", "t": "空港でクリックの車に拾われる", "b": "WWFに来たころ、仕事の話をしない移動仲間に物足りなさを感じていたという。ある日ボストンの空港でレンタカーの列に並んでいると、ケビン・ナッシュが乗ったワゴン車に呼ばれ、ショーンやスコット・ホールと一緒に移動することになったそうだ。道中ずっと仕事の話ばかりで、それが楽しかったと振り返る。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:33:40〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9220s"]]}, {"cat": "リングの話", "t": "クリック4人の強みとホールの思い出", "b": "ナッシュは映画のように大きな絵で業界を見て、Xパックは相手の力量をはかる物差しで、ショーンはすべてを組み立てられる人だったという。スコット・ホールは物事をとことん単純にする天才で、毎日彼のことを思い出し、今も寂しいと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:40:59〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9659s"]]}, {"cat": "リングの話", "t": "DXの土台だったチャイナ", "b": "ホテルのロビーで職を探していたチャイナを紹介され、自分の用心棒役にぴったりだと感じたという。DXはやや暴走気味の集団だったが、チャイナがいたから崩れずにすんだそうで、今の女子選手たちにつながる道を開いた人だと話す。2度目のDXは、キャリアで一番楽しかった時期だったそうだ。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:44:02〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9842s"]]}, {"cat": "リングの話", "t": "ミック・フォリーにもらった「タフさ」", "b": "ストーン・コールドとは、気に入らない部分があればはっきり言い合う正直な関係だったという。ミック・フォリーは、自分にトップに立つ力があるのかと周りが疑っていた時期に、試合を通してそれを証明してくれた恩人で、生涯で好きな対戦相手の一人だと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:45:39〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=9939s"]]}, {"cat": "リングの話", "t": "エボリューションで学んだ恩返し", "b": "リック・フレアーは自分のヒーローだったという。ランディ・オートンとバティスタをスターにしようとエボリューションを組み、2人が大きく成長していく姿を見たことで、人を育てたいという思いに火がついたと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:48:06〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10086s"]]}, {"cat": "体のこと", "t": "体中を痛めても復帰できた", "b": "現役中に体のほとんどの部分を痛めたという。初めて大腿四頭筋を断裂したときは「もうレスリングはできないだろう」と言われたが、医師とリハビリの専門家が支えてくれたおかげで最後まで戦えたと感謝している。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:50:35〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10235s"]]}, {"cat": "リングの話", "t": "給料なしで会議に通った", "b": "1996年ごろから番組の制作会議に呼ばれるようになり、給料は出ないのに誰よりも早く会場に着いて耳を傾けたという。パット・パターソンに「お前は引退したらこちら側をやるべきだ」と言われたことが、裏方の仕事を目指すきっかけになったそうだ。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:51:24〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10284s"]]}, {"cat": "リングの話", "t": "NXTは若返りの泉", "b": "地方団体がなくなり次の世代の育つ場所が見えなかったことから、パフォーマンスセンターとNXTを作ったという。キャリアで最も意味のある仕事の一つで、若手のまっすぐな情熱に、少し冷めかけていた自分がもう一度この仕事を好きになれたと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（2:53:42〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10422s"]]}, {"cat": "家族", "t": "義理の家族への思い", "b": "義母のリンダは、娘たちにとって強く力のある女性の最高のお手本だと話す。シェインのことは「自分にはいなかった兄弟」と呼び、ビンス・マクマホンとの関係は「複雑」だとしたうえで、仕事でも家族の面でも、彼なしでは今の自分はいないと語った。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:00:02〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10802s"]]}, {"cat": "リングの話", "t": "ウイスキー2杯で始まった友情", "b": "アンダーテイカーは控室のリーダーで、何か月もあいさつ以外は口をきいてもらえなかったという。ある晩バーで手招きされ、ウイスキーを2杯並べられて一緒に飲み干すと「お前は大丈夫だ」と言われ、そこから友情が始まったそうだ。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:02:30〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10950s"]]}, {"cat": "家族", "t": "ステファニーとの交際を後押しした言葉", "b": "ステファニーとの交際は、うまくいかなければ自分のキャリアも彼女のキャリアも終わりかねないものだったという。迷ってアンダーテイカーに相談すると「リスクを取るのはお前だ。愛しているなら行け」と言われ、それが人生を決めたと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:04:03〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=11043s"]]}, {"cat": "体のこと", "t": "心不全で知った大切なもの", "b": "数年前、全米を飛び回る生活の中で肺炎だと思っていたら、実際は心不全だったという。命の危険がある状態の中で考えたのは仕事ではなく妻と娘たちのことだけだったそうで、今は同じように働きながらも、小さなことが気にならなくなったと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:05:41〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=11141s"]]}, {"cat": "家族", "t": "3人の娘たち", "b": "3人の娘は、小さいころスーツケースに乗せて制作会議に連れて行き、強面の男たちの前で童謡を歌わせたこともあったという。今はそれぞれ大学や高校で自分の道を進んでいて、自分がその証拠だから、努力すれば何にでもなれると伝えている。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:08:49〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=11329s"]]}, {"cat": "家族", "t": "ステファニーは親友", "b": "ステファニーは親友であり支えであり、これ以上の伴侶も母親も考えられないという。「出世のための結婚」と言われたことを逆手に取り、20年たって娘3人、どっぷり本気だと笑わせた。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:11:49〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=11509s"]]}, {"cat": "リングの話", "t": "ヘッドセットの中の少年", "b": "今はソファではなくヘッドセットをつけて椅子に座っているだけで、中身はプロレスに夢中だった子どものままだという。人を励ますひと言がその人の人生を変えると信じ、若い選手の成功を見ることが今の人生で一番の喜びだと話す。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（3:15:07〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=11707s"]]}]);
  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "トリプルHが最も尊敬する人", "b": "この業界で誰よりも尊敬しているのがアンダーテイカーで、控室のリーダーという言葉に本当の意味があった時代の、落ち着いた支えだったと、トリプルHが話している。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で、2025年WWE殿堂入り式典の話（字幕を全文確認）", "src": [["番組のYouTube（3:03:17〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10997s"]], "by": "第三者の話"});
  if (PROFILES["Bruce Prichard"]) PROFILES["Bruce Prichard"].facts.push({"cat": "暮らし", "t": "会社と選手の間に立ち続けた", "b": "会社と選手の間に壁があった時代に、その間をつなぐ役を品位を持ってこなしてきた人で、今も毎日一緒に働けることに感謝していると、トリプルHが話している。", "sp": "トリプルH", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で、2025年WWE殿堂入り式典の話（字幕を全文確認）", "src": [["番組のYouTube（2:56:54〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=10614s"]], "by": "第三者の話"});
  if (!ROSTER.find((r) => r[1] === "Undertaker")) ROSTER.push(["アンダーテイカー", "Undertaker", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Undertaker"]) PROFILES["Undertaker"] = { lead: "妻ミシェル・マックールを殿堂に送り出す紹介役として登壇。「今夜はデッドマンではなく、夫で父親のマークとして来た」と話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Undertaker"]], moves: [], facts: [] };
  if (PROFILES["Undertaker"].lead === "妻ミシェル・マックールを殿堂に送り出す紹介役として登壇。「今夜はデッドマンではなく、夫で父親のマークとして来た」と話す。") PROFILES["Undertaker"]._weak = 1;
  PROFILES["Undertaker"].facts.push(...[{"cat": "家族", "t": "今夜は夫で父親として", "b": "妻ミシェル・マックールの殿堂入りで紹介役を務め、今夜はフェノムでもデッドマンでもなく、夫で父親のマークとしてここにいると話した。", "sp": "アンダーテイカー", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（36:39〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=2199s"]]}, {"cat": "家族", "t": "付き合い始めのひと言", "b": "付き合い始めたころ、妻に「私の代わりに話さないで」と言われ、思わず「俺が話すときはちゃんと聞けよ」と返したという。そのあと3か月は固い物が食べられなかったと冗談を言い、会場を笑わせた。どちらが追いかけたかについては、夫婦で言い分が食い違っている。", "sp": "アンダーテイカー", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（38:17〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=2297s"]]}, {"cat": "家族", "t": "自分を立ち直らせてくれた妻", "b": "妻のすごさはタイトルではなく、カメラが回っていないときの姿だという。信仰を持ち、愛情で子どもを導く母親で、家族で一番強い人だと話す。自分が立ち上がれなかったときに支えてくれ、より良い夫、父親、人間にしてくれたと感謝した。", "sp": "アンダーテイカー", "d": "2025-04-19", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-fUPEH9JP7zc", "src": [["番組のYouTube（40:47〜）", "https://www.youtube.com/watch?v=fUPEH9JP7zc&t=2447s"]]}]);
  ARTICLES.push({ id: "ext-fUPEH9JP7zc", d: "2025-04-19", show: "ext", who: ["Shawn Michaels", "Triple H", "Undertaker"], t: "2025年WWE殿堂入り式典の回　トリプルH、ショーン・マイケルズ、アンダーテイカー", lead: "WWE殿堂入り式典（WWE公式）に出た約200分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Shawn Michaels", "Triple H", "Undertaker"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-fUPEH9JP7zc").map((x) => [x.t, x.b, x.sp])), open: ["トリプルHの殿堂入りで紹介役を務めた部分だけをまとめた。", "同じ式典のほかの殿堂入り（レックス・ルガー、ミシェル・マックール、ナチュラル・ディザスターズほか）の部分は、ロスターの選手に関わる話だけを拾った。", "家族の私的な話（家族の病気、娘たちの学校の詳細など）は省いた。移動中のハプニングの話も省いた。", "ミシェル・マックール本人のスピーチはロスター外のため載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=fUPEH9JP7zc"]] });
  if (!ROSTER.find((r) => r[1] === "Kurt Angle")) ROSTER.push(["カート・アングル", "Kurt Angle", "lg", "五輪金メダリストの名レスラー", "", "", ""]);
  if (!PROFILES["Kurt Angle"]) PROFILES["Kurt Angle"] = { lead: "五輪の金メダルから、デビュー翌年にWWE王者へ駆け上がった人。首の大けがや薬物依存を乗り越え、いまは六人の子の父でありサプリ会社も営むという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kurt%20Angle"]], moves: [], facts: [] };
  if (PROFILES["Kurt Angle"]._weak) { PROFILES["Kurt Angle"].lead = "五輪の金メダルから、デビュー翌年にWWE王者へ駆け上がった人。首の大けがや薬物依存を乗り越え、いまは六人の子の父でありサプリ会社も営むという。"; delete PROFILES["Kurt Angle"]._weak; }
  PROFILES["Kurt Angle"].facts.push(...[{"cat": "暮らし", "t": "WWEを離れ、サプリ会社を経営", "b": "アングルは「フィジカリー・フィット・ニュートリション」というサプリ会社を営んでいると話す。WWEを離れてから約半年、鶏むね肉のスナックを11種類の味で売り出す準備を進めてきたそうだ。高たんぱく・低カロリーが売りで、植物性たんぱくの商品もある。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（0:02〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=2s"]]}, {"cat": "体のこと", "t": "首の検査で三つの骨が癒合と判明", "b": "症状が出たため医師の検査を受けたところ、首の骨3本（C5〜7）がくっついていたという。過去に三度の手術を受けたが、完全な固定術はしていなかったと話す。頭の回りはあまり良くないが、体は大丈夫だと笑う。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=94s"]]}, {"cat": "リングに来るまで", "t": "初の五輪、決勝は判定にもつれた", "b": "アングルは1996年の五輪が初出場で、階級最強の世界王者が相手だったため震えるほど怖かったという。試合は同点のまま審判の判断に委ねられ、最終的に判定で勝ったそうだ。途中、股関節まわりを痛めながらも、組み伏せられた場面で踏ん張って失点を防いだと話す。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（6:27〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=387s"]]}, {"cat": "リングに来るまで", "t": "首を折ったまま五輪へ出場", "b": "五輪の直前に首の骨を4本折り、椎間板も脊髄に食い込む状態だったという。どの医師にも出場許可をもらえなかったが、ようやく見つけた医師が試合の約10分前に麻酔の注射を打ってくれた。痛みは10段階で10か11、1時間後にはまた痛んだと話す。師と仰ぐコーチを半年前に亡くし、ほぼ一人で乗り切った時期でもあったそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（8:47〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=527s"]]}, {"cat": "家族", "t": "兄たちに無理やり鍛えられた末っ子", "b": "アングルは兄弟の末っ子で、兄たちはみなレスラーだったという。本人は団体球技が好きで、レスリングはやりたくなかったが、兄たちに競技をやらされたと話す。勤勉さや技術は兄たちから学び、世界のどこへ行っても兄たちが駆けつけたそうだ。五輪では立入禁止の会場フロアにも忍び込んで励ましてくれたという。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（9:33〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=573s"]]}, {"cat": "リングに来るまで", "t": "月250時間、4年間の猛練習", "b": "アングルは五輪に向けて月250時間の練習を目標に、毎日8〜9時間を練習日誌につけていたという。休むのは月に1日だけで、それを4年続けたと話す。重量級で27歳の金メダルは比較的若いほうだそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（11:04〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=664s"]]}, {"cat": "リングに来るまで", "t": "年50万ドルの10年契約を一度は見送った", "b": "五輪の後、WWEから10年契約を提示されたが、代理人に反対されて断ったという。それまで収入がなかったので大金は魅力だったが、数年は出演で稼ぎ、コーチ業も考えていたと話す。契約を解消して改めて連絡すると、条件はずっと厳しくなっていたそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（11:49〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=709s"]]}, {"cat": "リングに来るまで", "t": "本物のレスリングと聞かされ、過激な団体へ", "b": "旧友に「五輪のような本格的なレスリングの新団体がある」と誘われ、深く確かめずに出向いたという。着いてみると凶器も罵声も飛び交うハードコア路線で、「何をしているんだ」と思ったと話す。それでも、後で入ったWWEはそれよりずっとましだったので、結果的に良い経験だったそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（13:26〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=806s"]]}, {"cat": "リングに来るまで", "t": "入団テストは20分で合格", "b": "WWEの入団テストは年俸5万ドルからの条件で始まったという。テスト開始から約20分で、見ていた幹部が「もう契約する」と声をかけてきたと話す。受け身とやられ方の飲み込みが早かったのが理由らしく、5年契約を結んだそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（14:16〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=856s"]]}, {"cat": "リングに来るまで", "t": "まず受け身から、名レスラーに学ぶ", "b": "アングルは、攻める前にやられ方と受け身を覚えようと決めたという。大ベテランが技を一つずつ手取り足取り導いてくれ、「良いリーダーになるには良い従う側から」と教わったと話す。攻撃力は温存し、やられても対応できる姿を見せたことが評価につながったそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（16:39〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=999s"]]}, {"cat": "リングに来るまで", "t": "先輩の試合を毎回見て学んだ", "b": "デビュー当初から、会場では先輩たちの試合を全部見るようにしていたという。中堅から上位の選手の試合を、どの技を使うかまで観察して勉強したと話す。そのおかげで上達がぐんと早まったそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（19:03〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=1143s"]]}, {"cat": "リングの話", "t": "「五輪の英雄」を嫌われ役に仕立てられた", "b": "アングルは、憧れの先輩のように「格好いい悪ガキ」になりたかったが、会社の方針は違ったと話す。真面目に五輪や3つのIを語る紹介映像は、見ていて恥ずかしいほど大げさだったという。社長の狙いは、実は観客に嫌われる悪役を作ることだったと、後になって気づいたそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（20:37〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=1237s"]]}, {"cat": "リングの話", "t": "町をけなす決め台詞が生まれた", "b": "アングルは、会場の町をけなしたあとに「本当のことだ」と言い返すスタイルを、作家のブライアン・ガーツが書いてくれたと話す。観客がブーイングするほど、本当のことだと押し通す形がはまったという。無敗記録を守るため、窒息で失神させられた試合を「反則だから負けではない」と主張したのも、会場を沸かせたそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（26:17〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=1577s"]]}, {"cat": "暮らし", "t": "グッズでもっと稼ぎたかったと悔やむ", "b": "アングルは会社の社長を父のように慕っていたが、商売にはうとかったと振り返る。キャラクターが用意されたものだったので、自分でグッズの案を出せなかったという。金メダルや五輪の名前は使えず、その分もっと報酬がほしいと頼んだが通らなかったそうだ。お金の交渉は苦手だったと話す。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（28:38〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=1718s"]]}, {"cat": "リングの話", "t": "デビュー翌年に怒涛の出世", "b": "アングルは、欧州王座、インターコンチネンタル王座、キング・オブ・ザ・リングと立て続けに獲ったと話す。主役級との試合では負け役が多く、自分は中堅の上だと思っていたそうだ。ところが突然、10日後にザ・ロックと戦えと告げられ、夢が叶うと思ったという。世界王座を取ったときは、五輪で勝ったときと同じくらい興奮したと話す。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（30:25〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=1825s"]]}, {"cat": "リングの話", "t": "アマとプロの違いは「感情を出すか」", "b": "アマレスでは感情を一切見せず、相手の目ではなく腰を見るよう教わったと、アングルは話す。プロでは観客を巻き込む見せ方を覚える必要があり、最初は戸惑ったそうだ。1時間にも及ぶ試合の流れを覚え、即興で埋める力も、先輩たちから学んだという。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（34:30〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=2070s"]]}, {"cat": "リングの話", "t": "大舞台で受けた脳しんとうを、相手が支えた", "b": "アングルは、初の大きな主戦場となった三つ巴戦で、テーブルが先に割れて頭から硬い床に落ちたと話す。意識がもうろうとする中、技をかけた相手が30分近く試合を引っ張ってくれたそうだ。映像で見返しても、けがを抱えているとはまったく分からなかったという。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（36:07〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=2167s"]]}, {"cat": "リングの話", "t": "会長の息子との激闘で背骨を痛めた", "b": "アングルは、会長の息子との試合を、自分にとって「最高にひどくて最高に良い経験」と話す。パンチで鼻を折られ、自分も背中の骨を3本折ったが、最後まで戦い抜いたという。ガラスを突き破る技など危険な場面が続き、途中で試合を止める話も出たそうだ。激闘が評価され、強さの印象を残せたと振り返る。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（40:07〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=2407s"]]}, {"cat": "リングの話", "t": "故郷で母に見守られながら戴冠", "b": "アングルは、地元ピッツバーグで母や家族が見守る前で王座を取ったことを、五輪の金メダルと並ぶ二大誇りだと話す。9/11のあと、観客に元気を与えたいと自分から提案して実現した勝利だったという。長く持つ王座ではなく、一夜の盛り上がりのためだったと明かす。快く譲ってくれた相手への感謝も語っている。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（57:15〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=3435s"]]}, {"cat": "体のこと", "t": "首を折って緊急手術へ", "b": "アングルは、ある試合で相手の突進を受けた際に首が「ぱきっ」と折れたという。翌日は腕が上がらず、ジムで10ポンドのダンベルすら持てなかったそうだ。年間最大の祭典に出たいと自分で医師の許可を取り、出場した翌日に手術を受けたと話す。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:05:09〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=3909s"]]}, {"cat": "体のこと", "t": "痛み止めに頼り、姉の死で悪化", "b": "けがが相次ぎ、痛み止めの量がどんどん増えていったという。いったん立て直したものの、姉を亡くしたことをきっかけに再び頼ってしまったと話す。試合中に薬の影響があったという噂は事実ではないと強調している。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:23:45〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=5025s"]]}, {"cat": "体のこと", "t": "飲酒と運転で逮捕を重ね、更生へ", "b": "別の団体に移った後、薬と酒が重なってひどい判断を重ね、飲酒運転で逮捕されたこともあったという。妻に別れを告げられたのが転機となり、30日間の入院治療を受けた。それから7年間、薬も酒も断っているそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:31:01〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=5461s"]]}, {"cat": "家族", "t": "六人の子と妻が、いまを支えている", "b": "アングルは、立ち直りを支えているのは子どもたちと家族、そして「人生の愛」と呼ぶ妻だと話す。いまは六人の子の父だそうだ。WWEを引退するまでの49年間は自分のことしか考えていなかったが、妻に「もうあなたが主役ではない」と言われて納得したという。人生の後半は家族のためにあると語る。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:33:22〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=5602s"]]}, {"cat": "体のこと", "t": "1年休んだら、体が固まってしまった", "b": "アングルは、試合から離れて1年たつうちに体が関節炎のように固まってしまったと話す。毎晩のように受け身を取らない生活は、体にはとても重いのだという。再びリングに立つのは「できなくはないが、本当に大変」だそうだ。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:35:56〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=5756s"]]}, {"cat": "リングの話", "t": "殿堂入りの自負と、歴史に残る立ち位置", "b": "アングルは、自分は在籍年数が足りず「歴代最高」には数えられないと語る。ただ、長く嫌われ役を務めたことで、今のファンは「当時は憎かったが、今ならその意味が分かる」と言ってくれるそうだ。山の頂上には届かなくても、名前が挙がる一人にはなれたと思うと話している。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-cDsqSHq4oUg", "src": [["番組のYouTube（1:39:09〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=5949s"]]}]);
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "ブロック・レスナーとの力試し", "b": "入団当初のレスナーに、周囲が「五輪王者ならどうなる」とあおったという。アングルは自分より約60〜70ポンド重い相手と実際に組み、位置取りと経験で優位に立って、タックルを1回決めたと、カート・アングルが話している。レスナーは体も動きも一級品で、選手の中でも最高の運動能力だと評している。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、カート・アングルの話（字幕を全文確認）", "src": [["番組のYouTube（1:09:07〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=4147s"]], "by": "第三者の話"});
  if (PROFILES["Eddie Guerrero"]) PROFILES["Eddie Guerrero"].facts.push({"cat": "暮らし", "t": "エディ・ゲレロとの「兄弟のような」関係", "b": "試合後に抱き合う日もあれば、怒鳴り合う夜もあったという。交通事故の後遺症と、当時は誰も気づかなかった心臓の不調を抱え、昼は青白い顔でも、ゲートをくぐればスイッチが入ったと、カート・アングルが話している。生きるために演じているようにも見えたと振り返っている。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、カート・アングルの話（字幕を全文確認）", "src": [["番組のYouTube（1:11:38〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=4298s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "ショーン・マイケルズ戦の裏話", "b": "年間最大の祭典での試合の前、マイケルズに「あなたは怖くない」と告げられたことを、カート・アングルが話している。事前の合わせは1つの技だけで、あとは流れを話し合っただけだったという。マイケルズは自分が戦った中で最高のパフォーマーだと語っている。", "sp": "カート・アングル", "d": "2025-04-26", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、カート・アングルの話（字幕を全文確認）", "src": [["番組のYouTube（1:17:17〜）", "https://www.youtube.com/watch?v=cDsqSHq4oUg&t=4637s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-cDsqSHq4oUg", d: "2025-04-26", show: "ext", who: ["Kurt Angle"], t: "カート・アングルの回　金メダルから王者、そして立ち直りまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約106分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kurt Angle"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-cDsqSHq4oUg").map((x) => [x.t, x.b, x.sp])), open: ["聞き手のスティーブ・オースティン自身の思い出話や、アングルの試合・経歴についての本人以外の発言は載せていない。", "字幕は話者表記が乱れており、聞き手とアングルの発言が混ざる箇所があったため、確信のあるアングル本人の発言だけを採用した。", "年間最大の祭典の前の手術、殿堂入り、旅客機の中での出来事など、筋書き中心または裏づけが弱い話題は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=cDsqSHq4oUg"]] });
  if (!ROSTER.find((r) => r[1] === "Erik")) ROSTER.push(["エリック", "Erik", "lg", "WWEタッグ王者", "", "", ""]);
  if (!PROFILES["Erik"]) PROFILES["Erik"] = { lead: "エリックは、大事故と首の大手術を乗り越えたタッグ王者。農場で家族と暮らし、バイキングの再現活動に夢中な、剛腕の素顔を持つ人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Erik"]], moves: [], facts: [] };
  if (PROFILES["Erik"]._weak) { PROFILES["Erik"].lead = "エリックは、大事故と首の大手術を乗り越えたタッグ王者。農場で家族と暮らし、バイキングの再現活動に夢中な、剛腕の素顔を持つ人だ。"; delete PROFILES["Erik"]._weak; }
  PROFILES["Erik"].facts.push(...[{"cat": "リングに来るまで", "t": "クリーブランド西側育ちの父の仕事", "b": "エリックは、クリーブランドの西側育ちだと話す。父は製鉄所で働いていたが会社が傾き、子どものころは家計が苦しかったそうだ。その後は父がビール醸造所に勤め、エリックは隣の名門男子校に通っていたという。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=46s"]]}, {"cat": "リングに来るまで", "t": "一度は試合で食べていくのを諦めた", "b": "2010年にクリーブランドを離れたころは、レスラーとしての収入がゼロで仕事もなかったと、エリックは話す。「好きでも向こうは好きになってくれない」と感じ、友人の誘いでヒューストンへ移り、6年暮らしたという。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=98s"]]}, {"cat": "リングに来るまで", "t": "ヒューストンでは月1回ほどの小さな興行だけ", "b": "ヒューストン時代は、地元の小さな団体とサンアントニオの団体の2つに出るだけだったそうだ。数週間に1回ほどの試合を「趣味」と割り切り、お金にはならないと思っていたとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=143s"]]}, {"cat": "リングに来るまで", "t": "2013年の電話が人生を変えた", "b": "2013年に米インディー団体から試合の誘いの電話が来て、「もう辞めたと思っていた」と言われたという。そこから新人トーナメント、相棒との契約、日本、育成施設、WWEへと道がつながったと、エリックは振り返る。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=192s"]]}, {"cat": "リングに来るまで", "t": "相棒は団体の「見た目」判断で組まされた", "b": "相棒のアイバーとのタッグは、自分たちの発案ではなかったそうだ。トーナメントの試合で2人とも髭の力自慢タイプだったため、団体側が組ませたという。当初は「少しやって別れよう」と話していたが、11年たっても解散の気配はないとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（4:55〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=295s"]]}, {"cat": "体のこと", "t": "バイク事故で「死んでいるはずだった」", "b": "2014年、ジムの帰りにバイクで走行中、停止線から出てきた車に時速約90キロで突っ込んだという。左腕の骨は粉々になり、顔も大けがをしたが、医師から「普通は助からない」と言われたとエリックは話す。ヘルメットはかぶっていなかった。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（5:45〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=345s"]]}, {"cat": "体のこと", "t": "事故のあと自分で歩いて救急車へ", "b": "事故後、エリックは自分で立ち上がって救急隊のほうへ歩いたそうだ。隊員は通報内容から亡くなっていると思い、遺体袋を出していたという。笑い話のように、「病院まで歩く？」と冗談を言われたとも話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（8:17〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=497s"]]}, {"cat": "体のこと", "t": "半年で復帰、「第二の人生」と感じた", "b": "腕にはプレート2枚とピン・ネジ18本が入り、数時間の手術を受けたが、半年後にはリングへ戻ったという。無駄にした時間を悔い、人をよく抱きしめ、感謝を忘れないと決めたそうだとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（10:46〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=646s"]]}, {"cat": "暮らし", "t": "「35歳まで生きないと思っていた」", "b": "若いころは悪い選択も多く、35歳までに死ぬか刑務所に入ると思っていたそうだ。結婚して父になった今は、35歳以降の毎年が人生で最高の年だとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（12:21〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=741s"]]}, {"cat": "暮らし", "t": "誕生日に450ポンドのデッドリフト", "b": "毎年の誕生日に、450ポンド（約204キロ）のデッドリフトを引くのが恒例だという。「まだ死んでいない」の確認だと、エリックは話す。普段は重量を追わず、メイスやケトルベルなどでのトレーニングが中心だそうだ。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（12:50〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=770s"]]}, {"cat": "体のこと", "t": "首のヘルニアと長引いた治療", "b": "ライブ興行でスープレックスを受けた際に頭から落ち、首の椎間板ヘルニアになったという。リハビリや針治療などで手術を避けようとしたが、腕や背中の筋肉が急に痩せ、手術を決めたとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（14:01〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=841s"]]}, {"cat": "体のこと", "t": "首の手術と13か月の離脱", "b": "首の前から入る固定手術を受けたが、骨がなかなかつかず、復帰は約13か月後になったそうだ。バイク事故のときは半年で戻ったため、今回は「引退かも」と怖くなり、妻や相棒と毎日話していたとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（16:26〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=986s"]]}, {"cat": "家族", "t": "二人の息子との子育て", "b": "上の息子キャッシュは4歳、下のゼカライアは感謝祭の日に生まれたという。眠れない日々でも、赤ん坊を抱いて妻を寝かせる時間を大切にしたいと、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（18:57〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1137s"]]}, {"cat": "好きなもの", "t": "レスリングを好きな理由は「感情」", "b": "技は物語を伝える手段で、記憶に残るのは見ている人の気持ちだと、エリックは話す。格闘ゲームは数字の計算に近く、感情は生まれないとも語っている。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（23:03〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1383s"]]}, {"cat": "リングの話", "t": "王座獲得は「会社の信頼」の証", "b": "タッグ王座を取った瞬間は言葉にできないほどの証しだったそうだ。会社が部門の顔に選んだという信頼でもあり、もう来ないと思っていた瞬間だったとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（28:40〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1720s"]]}, {"cat": "リングの話", "t": "入場前に「噛みしめろ」と声をかけ合う", "b": "試合の前に、相棒と互いに「この瞬間を味わえ」と声をかけ合うのだという。年間最大の祭典では、妻も一緒に長い花道の上で立ち止まったと、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（29:27〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1767s"]]}, {"cat": "リングの話", "t": "役はほぼ「自分の延長」だという", "b": "最も効果的なレスラーのキャラクターは、本人の延長だとエリックは話す。そのため、ファンの批判が自分自身への言葉に感じられ、とても無防備な仕事だと語っている。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（31:02〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1862s"]]}, {"cat": "暮らし", "t": "飲酒も薬物もしないストレートエッジ", "b": "エリックは、お酒も薬物もやらないと話す。それでも会場の歓声が体に響く感覚は、何にも代えがたい依存性があると語る。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（32:40〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=1960s"]]}, {"cat": "リングの話", "t": "「バイキング・エクスペリエンス」の一週間", "b": "一軍デビュー時、チーム名が急に変えられ、1週間足らずで元に戻ったという。見た目も入場曲も同じで名前だけが違い、今でも番組のたびにネタにされるとエリックは笑って話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（35:08〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=2108s"]]}, {"cat": "リングの話", "t": "チーム名の変遷にまつわる話", "b": "前の名前は、あるまずい理由で使えなくなり、育成施設時代に改名したそうだ。複数案を出し、自分たちが推した名前は通らず、最終的に別の名前に決まったと、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（36:47〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=2207s"]]}, {"cat": "リングの話", "t": "相棒とは名前の取り合いを回避", "b": "当時の名前は、バイキングの有名人から取られた2つだったそうだ。相棒が「自分の兄の名前だから嫌だ」と頼み込み、エリックが今の名前を引き受けたという。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（41:32〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=2492s"]]}, {"cat": "リングの話", "t": "今のチームは「素の自分」に最も近い", "b": "現在のチームは、化粧も角つき兜もなく、革ベスト姿で登場できるそうだ。私服と同じ黒Tとジーンズで話すことが多く、これまでで最も自然体だと、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（43:08〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=2588s"]]}, {"cat": "暮らし", "t": "バイキングの再現活動に夢中", "b": "エリックは妻と、バイキング時代の暮らしや戦いを再現する活動に夢中だと話す。デンマークの大きな催しにも参加し、テント泊や火での調理、当時の布や装身具の再現までするそうだ。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（48:45〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=2925s"]]}, {"cat": "暮らし", "t": "地元で再現戦闘のクラブを運営", "b": "クリーブランドでは、国際的なバイキング再現団体の地域支部を運営しているという。本物の鋼の剣や斧で稽古し、エリックは世界大会の決勝に米国人として初めて進むのが目標だと話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（50:18〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3018s"]]}, {"cat": "暮らし", "t": "自宅の農場にバイキングの長屋を建てた", "b": "農場には、年1回の合宿イベント用に長い家を建てたそうだ。仲間や子どもも集まり、子どもたちは小さな剣や盾で遊ぶと、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（51:54〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3114s"]]}, {"cat": "家族", "t": "バイキング式の結婚式", "b": "結婚式は10世紀の風習を調べて再現したそうだ。花嫁の父から剣を、花婿側から鍵を贈る儀式を行い、WWEが撮影に来て動画が公開されているとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（55:50〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3350s"]]}, {"cat": "リングに来るまで", "t": "2006年のエキストラ時代", "b": "クリーブランドに住んでいた2006年、WWEの収録に端役として出た経験があるという。大きな選手に走り込む役を受け持ち、その場にいた友人が契約を得る場面にも居合わせたとエリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（59:55〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3595s"]]}, {"cat": "リングの話", "t": "「暴力を信じさせる」のが最大の武器", "b": "自分の最大の強みは、攻撃を本物のように見せる力だとエリックは話す。裏で注意されたのに、相手からは感謝された経験もあるそうだ。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（1:00:41〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3641s"]]}, {"cat": "リングの話", "t": "相棒とは「いつか別れるチーム」にしたくない", "b": "一人で試合に出たい気持ちはあるが、チームを壊してまでは望まないと、エリックは話す。多くのタッグと違い、大柄な相棒が宙返りをし、自分が力役という珍しい組み合わせが強みだと語る。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（1:04:40〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=3880s"]]}, {"cat": "暮らし", "t": "農場で肉と野菜を自給", "b": "クリーブランドの郊外から約45分の農場で、牛や羊を育てて肉にし、野菜も自分たちで作るそうだ。家族を頼れる地元へ戻って暮らしていると、エリックは話す。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（1:08:41〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=4121s"]]}, {"cat": "家族", "t": "五人きょうだいの真ん中", "b": "エリックは五人きょうだいの真ん中だそうだ。キャッシュは親族の中で11人目の孫、ゼカライアは13人目で、祝日には皆が集まるという。", "sp": "エリック", "d": "2025-05-01", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gkP4n6x-Fvg", "src": [["番組のYouTube（1:08:41〜）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg&t=4121s"]]}]);
  ARTICLES.push({ id: "ext-gkP4n6x-Fvg", d: "2025-05-01", show: "ext", who: ["Erik"], t: "エリックの回　事故と手術を越えた「暴力を売る」男", lead: "クリス・ヴァン・ヴリートの番組に出た約70分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Erik"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-gkP4n6x-Fvg").map((x) => [x.t, x.b, x.sp])), open: ["チーム名の話題などは、番組内の話し方から要点のみを載せた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=gkP4n6x-Fvg"]] });
  if (!PROFILES["Bianca Belair"]) PROFILES["Bianca Belair"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bianca%20Belair"]], moves: [], facts: [] };
  if (PROFILES["Bianca Belair"].lead === "") PROFILES["Bianca Belair"]._weak = 1;
  PROFILES["Bianca Belair"].facts.push(...[{"cat": "リングの話", "t": "緊張はいつも一緒、父の言葉が支え", "b": "ビアンカ・ブレアは、レッスルマニアの主役を経験した今でも、ライブの会場ではいつも緊張すると話す。NXT時代、ベテランが並ぶ4人での試合の前に震えていると、父が楽屋に現れて「緊張はいい。ただ怖がるな」と励ましてくれたという。その言葉は今も心の支えだそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（8:53〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=533s"]]}, {"cat": "リングの話", "t": "自分で作る入場衣装の制作時間", "b": "ビアンカ・ブレアは、テレビ用の簡単な衣装なら数時間、大舞台用の凝ったものでも1〜2日で作れると話す。一番時間がかかるのは完成像が浮かばない時で、布や飾りを前に何時間も考え込むこともあるという。今年のレッスルマニアの衣装には、合計で3〜4日かかったそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（13:49〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=829s"]]}, {"cat": "リングの話", "t": "同期の盟友と、初めて黒人女性として大舞台のメインを務めた", "b": "ビアンカ・ブレアは、サーシャ・バンクスと共に黒人女性として初めてレッスルマニアのメインイベントに立ったと話す。「表現は頼みではなく必要なもの」という考えを持ち、手本を見せることが次の世代の道を開くと語る。一軍入りして最初の年に実現したことにも誇りを持っているという。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（36:32〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=2192s"]]}, {"cat": "リングの話", "t": "当日は雷雨、涙をこらえたリングの上", "b": "ビアンカ・ブレアは、メインイベントと知らされた時に二人で泣いたと話す。当日は雷雨で開催も危ぶまれ、試合中に落雷があれば中断との話まで出たという。入場後に涙があふれそうになったが、サーシャに「行こう」と促されて気持ちを切り替えたそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（38:54〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=2334s"]]}, {"cat": "リングの話", "t": "初めて肌を合わせたのに魔法のような一戦", "b": "ビアンカ・ブレアは、サーシャとはタッグ経験こそあったが、シングルで組み合うのはあの試合が初めてだったと話す。普段は反省点が多いのに、あの試合はほぼ完璧だったという。トップロープからの技で息が止まったことが唯一の出来事だったそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（43:50〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=2630s"]]}, {"cat": "リングの話", "t": "大舞台直前は節制で気が立ち、衣装は直前まで作る", "b": "ビアンカ・ブレアは、レッスルマニア前は食事制限と水で空腹とだるさを抱え、気が立つと話す。過去には楽屋で、ダコタ・カイがラインストーンを貼って手伝ってくれたこともあったという。今年は家族の流れ作業で早く完成したが、入場用の飾りが硬すぎて動けるか心配しているそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:07:41〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4061s"]]}, {"cat": "リングの話", "t": "兄の憧れの前で、メインに勝った夜", "b": "ビアンカ・ブレアは、ストーン・コールドのファンである兄が、ダラスの会場でポスターに並ぶ姿を見て驚いたと話す。レッスルマニアのメインで勝った時には、父が感激して柵を越えそうになったという。兄に「いま勝ったぞ」と言われ、実感が湧いたそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:17:22〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4642s"]]}, {"cat": "リングの話", "t": "最初の頃は「ここにいていいのか」と悩んだ", "b": "ビアンカ・ブレアは、この業界の出身ではなかったため、今もインポスター症候群に悩むことがあると話す。契約の目前に、空港で同じ夢を持つ志望者たちと一緒になり、自分はまだ誰かの夢の中にいるように感じたという。それでもレッスルマニアの舞台では、努力して得たものだと受け止めるようにしたそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:22:16〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4936s"]]}]);
  if (!PROFILES["Bianca Belair"]) PROFILES["Bianca Belair"] = { lead: "陸上の挫折と心の不調を乗り越え、クロスフィットを経てリングにたどり着いた。入場コスチュームは独学の裁縫ですべて自作する、家族思いの努力家だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bianca%20Belair"]], moves: [], facts: [] };
  if (PROFILES["Bianca Belair"]._weak) { PROFILES["Bianca Belair"].lead = "陸上の挫折と心の不調を乗り越え、クロスフィットを経てリングにたどり着いた。入場コスチュームは独学の裁縫ですべて自作する、家族思いの努力家だ。"; delete PROFILES["Bianca Belair"]._weak; }
  PROFILES["Bianca Belair"].facts.push(...[{"cat": "家族", "t": "父の教え「緊張はしても怖がるな」", "b": "幼いころから競技をしてきて、今でも毎回緊張するという。父からは、緊張するのは本気で大事に思っている証拠だと教わったそうだ。育成時代の大一番の前にも父が楽屋に現れ、震える彼女に「緊張はいいが、怖がるな。そういうふうには育てていない」と声をかけたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（8:04〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=484s"]]}, {"cat": "好きなもの", "t": "裁縫は一度も習わず完全独学", "b": "コスチュームはすべて自作だが、裁縫教室に通ったことは一度もないという。ネットや動画、試行錯誤だけで覚えたそうだ。表彰式に急に出ることになった際はドレスがなく、夫と顔を見合わせて自分で縫ったと話し、それを機に新しいことに挑むようになったという。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（12:14〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=734s"]]}, {"cat": "家族", "t": "誕生日は家族総出のギア作り", "b": "今年は誕生日が年間最大の祭典の前に来たため、両親が駆けつけ、ほぼギア作りで祝ったという。母が部品を外して父に渡し、父がラメをまぶし、彼女が接着し、夫も手伝う流れ作業だったそうだ。夫は一緒に大舞台に立っている気分だと喜んでいたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（14:34〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=874s"]]}, {"cat": "体のこと", "t": "減量中は水とブロッコリーと鶏肉", "b": "大一番に向けた減量中、体の中身は水とブロッコリー、焼いた鶏肉ばかりだと笑う。寿司も食べるが、一度ひどい食中毒になって以来、なかなか戻れないという。空腹でいらだち、水を飲むのにも飽きると本音も漏らしている。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（16:17〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=977s"]]}, {"cat": "リングに来るまで", "t": "6歳でクッキー缶の針と糸から", "b": "家にあったクッキーの缶に、母が針と糸をしまっていたという。6歳ごろからそれを持ち出し、穴の開いた靴下を自分で繕っていたそうだ。子どものころからおしゃれが好きだったと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（18:00〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1080s"]]}, {"cat": "リングに来るまで", "t": "地元を出るため陸上に打ち込んだ高校時代", "b": "地元ノックスビルを出るには奨学金が道だと考え、陸上に全てを注いだという。友人が遊びに出かける間も、毎朝腹筋千回、腕立て300回をこなしていたそうだ。振り返ると、楽しむことを忘れていたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（19:32〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1172s"]]}, {"cat": "リングに来るまで", "t": "クロスフィットで「楽しむ」を取り戻す", "b": "陸上の後に始めたクロスフィットでは、楽しむことを最優先にしたという。チュチュや花飾りの衣装で大会に出て、側転をしたりマイクで観客に話しかけたりしていたそうだ。いつしか彼女の衣装を見に来る人が現れ、知らないうちに自分をブランド化していたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（19:32〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1172s"]]}, {"cat": "暮らし", "t": "夫から贈られたミシンが原点", "b": "入団後は衣装係に頼んだこともあったが、頭の中のイメージをうまく伝えられず自分で作り始めたという。2016年に夫がミシンを買ってくれ、使い方を覚えたそうだ。時間がないときはホテルの部屋に宅配でミシンを届けてもらい、試合前夜まで縫うこともあると話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（21:11〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1271s"]]}, {"cat": "体のこと", "t": "体重への執着から摂食障害に", "b": "もともと筋肉質で肩幅が広く、太ももは母譲りの体格だという。速く走るには痩せるべきだと思い込み、行き過ぎて摂食障害になり、コーチにも両親にも隠していたそうだ。奨学金は得たものの、大学で体を壊してけがをしたのは不健康だったせいだと振り返る。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（26:47〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1607s"]]}, {"cat": "体のこと", "t": "大学で抑うつ、薬の自己中断で悪化", "b": "18歳で地元を離れ、成績が自分の価値だと思い詰めて落ち込んだという。サウスカロライナ大学からテキサスA&M大学へ移ったが状態は悪化し、うつの薬を飲み始めたものの、良くなったと思って急にやめてしまい大きく崩れたそうだ。「選手より人として大事だ」と言ってくれたコーチが支援につないでくれ、両親に打ち明けてから回復に向かったと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（28:19〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1699s"]]}, {"cat": "リングに来るまで", "t": "地元大学で再起、自己ベストで競技に区切り", "b": "一度は実家に戻って競技を離れたが、陸上への思いが残り、テネシー大学で再挑戦したという。2年実績のない自分を受け入れたコーチが1年間練習を見てくれ、次のコーチには毎朝三つの前向きな言葉を送るよう課されたそうだ。最後のシーズンで自己ベストを出し、悔いなく陸上を終えられたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（30:53〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1853s"]]}, {"cat": "好きなもの", "t": "憧れはフロー・ジョー", "b": "夢は五輪のハードル選手で、子どものころは実家の部屋の壁一面に陸上の絵を描いたという。その壁は今も残っているそうだ。ファッションの面でも、陸上界のおしゃれの先駆けだったフロー・ジョーに影響を受け、彼女に着想を得たギアも作ったと話す。ジャッキー・ジョイナー＝カーシーに取材できたときは緊張しきりだったという。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（32:31〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1951s"]]}, {"cat": "家族", "t": "育成施設で出会い、自然に同居から結婚へ", "b": "夫モンテス・フォードとは育成施設で出会い、彼は1年先輩だったという。けがから戻った彼と仲間の寿司会で意気投合し、互いの賃貸契約が切れる時期に流れで一緒に住み始めたそうだ。その1年後に婚約、さらに1年後に結婚し、継母にもなった。子どもたちのおかげで「最高に幸運な継母」だと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（53:16〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=3196s"]]}, {"cat": "暮らし", "t": "苦手だったはずのリアリティ番組に出演", "b": "リアリティ番組は実は一番好きな娯楽だが、自分が出ることは絶対ないと思っていたという。夫婦で「完璧を目指さず、ありのままで」と決めて臨み、自分たちだけの場所は残すことを学んだそうだ。王者として戦いながら撮影とギア作りを重ね、約5か月ほぼ休みなしだったと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（53:16〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=3196s"]]}, {"cat": "家族", "t": "仕事に集中するため受精卵を凍結", "b": "夫はロマンチストで、仕事に没頭しがちな彼女を休ませる役だという。自分の子どもはまだいないが、子どもができれば生活は変わるので今は全力で働きたいと話す。そのために最近、夫婦で受精卵を凍結し、心の余裕を得たそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（59:37〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=3577s"]]}, {"cat": "リングに来るまで", "t": "夢は「足元にバラを投げてほしい」", "b": "幼いころ将来の夢を聞かれ、「足元にバラを投げてもらいたい」と答えて母を困らせたという。舞台のカーテンコールを見た影響で、本当は人前で演じたかったのだと後で気づいたそうだ。素は内気だが、家族旅行ではビデオカメラを回させて自分がホテルを案内するなど、カメラの前では生き生きしていたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:09:15〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4155s"]]}, {"cat": "家族", "t": "兄はプロレス好き、自分はゴールダスト", "b": "4歳上の兄がプロレス好きで、ストーン・コールドやアンダーテイカーのポスターを貼っていたという。リモコン争いで兄が勝ったときだけ見ていたが、彼女の方が力が強いのでめったに見られなかったと笑う。見るとゴールダストに目が離せなかったそうだ。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:12:37〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4357s"]]}, {"cat": "リングに来るまで", "t": "母が見ていた番組と観客の前での入団テスト", "b": "母が女子選手の私生活を追う番組を見て勧めてくれたが、一度は考えただけで忘れていたという。マーク・ヘンリーに声をかけられて受けた最初のテストは、大会の休憩中に観客の前で行う形式だったそうだ。コーリー・グレイブスからマイクを奪いかけて注意されつつ、自己紹介で歓声をもらい、すっかり虜になったと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:13:22〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4402s"]]}, {"cat": "家族", "t": "心配した母は今や一番の応援団", "b": "入団が決まると、母は目にあざを作るのではと心配したが、父は「本人ができると思うならできる」と後押ししたという。今では両親とも手作りの帽子で応援する一番の応援団だそうだ。兄の子ども3人は熱心なファンで、なぜか彼女を「ビンコおじさん」と呼ぶと笑う。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:15:44〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4544s"]]}, {"cat": "家族", "t": "興奮した父が柵を越えかけた日", "b": "兄は大会のポスターで憧れのストーン・コールドと妹が並んだことに驚いていたという。年間最大の祭典のメインで勝った日には、父が興奮して客席の柵を飛び越えようとし、警備に止められかけたそうだ。勝った瞬間に兄と目が合い、「お前、勝ったんだぞ」と言われたと話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:17:22〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4642s"]]}, {"cat": "体のこと", "t": "今も続くインポスター症候群", "b": "業界出身ではないため、自分はここにいていいのかという気持ちに今も悩むという。合格を告げられた帰りの空港で、幼いころからの夢だと語るほかの受験者を前に、他人の夢の中にいるようだと感じたそうだ。だからこそ全てを注ぐと決め、自分は努力で居場所を勝ち取ったと考えるようにしていると話す。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dnRq7C5TeeY", "src": [["公式YouTube（1:21:27〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=4887s"]]}]);
  if (PROFILES["Montez Ford"]) PROFILES["Montez Ford"].facts.push({"cat": "暮らし", "t": "妻の晴れ舞台を支え続ける夫", "b": "自分は大舞台に出られなかった年も、悔しさを見せず妻の瞬間を奪わないよう支えてくれたと、ビアンカが話している。自信のある男性だからこそ脅威に感じずに応援できるのだと言い、いつか立場を逆にして恩返しするのが楽しみだと語っている。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で、ビアンカ・ブレア の話（公式字幕を全文確認）", "src": [["公式YouTube（55:45〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=3345s"]], "by": "第三者の話"});
  if (PROFILES["Mark Henry"]) PROFILES["Mark Henry"].facts.push({"cat": "暮らし", "t": "クロスフィット時代の動画で見いだした", "b": "衣装で入場し、コートを脱いで重量挙げをするクロスフィット時代の動画を見て、「それはもうプロレスのギアだ」と声をかけてくれたと、ビアンカが話している。彼が現れなければ夢に出会えなかったかもしれないと振り返っている。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で、ビアンカ・ブレア の話（公式字幕を全文確認）", "src": [["公式YouTube（21:11〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=1271s"]], "by": "第三者の話"});
  if (PROFILES["Sasha Banks"]) PROFILES["Sasha Banks"].facts.push({"cat": "暮らし", "t": "泣き崩れそうな新人を一言で立て直した", "b": "年間最大の祭典のメインで向き合った際、感極まって泣きそうになった彼女に気づき、「行くよ」と声をかけて立て直してくれたと、ビアンカが話している。まだ新人だった自分をしっかり導いてくれたと語っている。", "sp": "ビアンカ・ブレア", "d": "2025-05-08", "how": "ステファニーの番組で、ビアンカ・ブレア の話（公式字幕を全文確認）", "src": [["公式YouTube（42:59〜）", "https://www.youtube.com/watch?v=dnRq7C5TeeY&t=2579s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-dnRq7C5TeeY", d: "2025-05-08", show: "wys", who: ["Bianca Belair"], t: "ビアンカ・ブレア の回　陸上の挫折、自作のコスチューム、夫モンテスとの歩み", lead: "ステファニー・マクマホンの番組に出た約93分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bianca Belair"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-dnRq7C5TeeY").map((x) => [x.t, x.b, x.sp])), open: ["大学時代のコーチや、高校時代にハードルを買ってくれた恩人、兄の子どもたちなど一般の方の実名は伏せた。母校の陸上部にハードル一式を寄贈した話や、若者のメンタルヘルスを支える活動をしたいという話も今回は省いた。", "ステファニー自身や同席スタッフの家族の話、試合の筋書きに関わる話は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=dnRq7C5TeeY"]] });
  if (!ROSTER.find((r) => r[1] === "Joe Hendry")) ROSTER.push(["ジョー・ヘンドリー", "Joe Hendry", "lg", "TNA世界王者", "", "", ""]);
  if (!PROFILES["Joe Hendry"]) PROFILES["Joe Hendry"] = { lead: "大舞台に立つたび、愛犬との散歩や両親への電話で自分を保つ。目標を思い描き、仲間に感謝する人柄が語られた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Joe%20Hendry"]], moves: [], facts: [] };
  if (PROFILES["Joe Hendry"]._weak) { PROFILES["Joe Hendry"].lead = "大舞台に立つたび、愛犬との散歩や両親への電話で自分を保つ。目標を思い描き、仲間に感謝する人柄が語られた。"; delete PROFILES["Joe Hendry"]._weak; }
  PROFILES["Joe Hendry"].facts.push(...[{"cat": "リングの話", "t": "NXT初登場は想定外の30秒だった", "b": "NXTでは入場の演出が普段と違い、ジョー・ヘンドリーは手持ち無沙汰の30秒間をそのまま素で過ごしたという。長年の努力が報われた気持ちで会場を見回した様子が自然に映り、WWE公式で最も見られた動画の一つになったと分析している。実は大舞台より、距離の近いNXTのほうが緊張するそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=192s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズは台詞を任せてくれた", "b": "NXTでの場面について、ショーン・マイケルズは何を言うか一切確認せず、自由に話させてくれたと語る。彼は「どんな場所でも、いつでも」という言葉で次の出番への種をまいたつもりだったと話す。その後、素の自分を見せる大切さを語り合う面談につながったという。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（5:42〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=342s"]]}, {"cat": "リングの話", "t": "2019年の入場曲が今になって花開いた理由", "b": "同じ曲はリング・オブ・オナー時代からあったが、当時は細かい笑いに寄りすぎていたと話す。プロレスは舞台のように大きく見せるものだと気づき、TNAでキャラクターを大きく作り直したことが転機になったという。第二の入場映像でそれが形になったそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（7:21〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=441s"]]}, {"cat": "リングに来るまで", "t": "友人RDエヴァンスが進む道を言葉にしてくれた", "b": "ほかの選手の真似をしてもうまくいかず悩んでいたとき、友人のRDエヴァンスが自分に合うタイプと参考にすべき選手を整理してくれたという。自分の活動は二人でやっていることだと話すほどで、そこから人生が変わったそうだ。シナのように自分らしさを軸にした戦い方をするようになり、ジョシュ・アレクサンダー戦は自分らしく臨めた最高の試合の一つだという。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=487s"]]}, {"cat": "リングに来るまで", "t": "ウィリアム・リーガルの2時間の話", "b": "キャリアの早い時期に、ウィリアム・リーガルが約2時間かけてこの業界の考え方を教えてくれたという。プロレスは観客、仲間、同僚、会社との信頼を築く仕事だという話が心に残っていると話す。WMの日はそのリーガルと並んで試合の続きを見たそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（20:03〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1203s"]]}, {"cat": "リングの話", "t": "オートン戦は1週間前に電話で決まった", "b": "トリプルHから直接電話があり、相手はランディ・オートンだと告げられて即答で受けたという。知っていたのはTNA側でごく少数で、友人や家族にも言えず、約1週間黙っていたそうだ。賭けの選択肢にも名前がなく、「その他」を選ばないと入れられない状態だったと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（24:03〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1443s"]]}, {"cat": "リングの話", "t": "ジョン・シナの助言が試合の組み立てを変えた", "b": "ロイヤルランブルで「どうすれば自分の見せ場を大きくできるか」と尋ねると、シナは「そうしなくていい」と答えたという。自分の見せ場は入場ですでに済んでおり、あとは大きな流れの一部として相手を引き立てるべきだと教わったそうだ。この考えでオートン戦も「番組のための瞬間」を意識して臨んだと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（28:04〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1684s"]]}, {"cat": "リングの話", "t": "変装して会場に入った", "b": "WWE関連のイベント会場から車に乗り、ありふれたパーカー、マスク、サングラスで全身を隠して移動したという。着替えは車内と会場で済ませ、控室は他の選手から離れた部屋だった。出番まではスタッフが順に様子を知らせてくれたと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（30:34〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1834s"]]}, {"cat": "リングの話", "t": "入場の瞬間は「体を押す波」のようだった", "b": "ランブルの入場は仮想現実のゴーグルをつけたように現実感がなかったという。レッスルマニアではオートンの20回目の舞台と気づいて重みを実感し、歩く間は歓声が物理的な波のように押し寄せたと話す。緊張はなく、その場にいることに集中していたそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（32:56〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1976s"]]}, {"cat": "好きなもの", "t": "トリプルHに教わった『今に集中する』", "b": "トリプルHがポッドキャストで語っていた、今この瞬間に集中することの大切さを大事にしているという。ティム・フェリスの本『タイタンの道具』にも通じる考えで、話すときは話し、リングではリングに集中し、家族といるときは家族に向き合うと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（33:44〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2024s"]]}, {"cat": "リングの話", "t": "試合後のオートンは満足そうだった", "b": "オートンは自分の動きをやるかどうか迷い、その場の流れで決めようと言っていたという。試合後は感謝の言葉をかけてくれて、本人は王座をそんな大舞台に連れていけたことが何より嬉しかったと話す。15歳のころ学校帰りに友だちとオートンの話をしていた自分を思い出し、友人にその画像を送ると「誇りに思う」と返ってきたそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（35:19〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2119s"]]}, {"cat": "リングに来るまで", "t": "アマレスの経験と苦労を番組に出すことに", "b": "ショーンは、ヘンドリーがプロの前後にアマレスをしていたことも、12年の浮き沈みも知らなかったという。同居していた友人からは「少しだけ素の自分を見せれば人気が出る」と言われていて、同じ助言だったそうだ。実名で戦うことに長く悔いがあったが、今は夢を叶える様子がリアルタイムで見えるのが魅力だと考えている。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（39:19〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2359s"]]}, {"cat": "リングに来るまで", "t": "育成施設では「生徒」に徹した", "b": "育成施設では授業に遅れず、栄養士やトレーナーも含めてあらゆる資源を使うと決めていたという。TNAやNXT、サイン会、地方団体も並行していたが、教わる姿勢を貫いたそうだ。テリー・テイラーには「それは自分は知らない」と素直に言って教わり、レスラーとして別人のように変わったと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（40:04〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2404s"]]}, {"cat": "暮らし", "t": "ジムでは目標を何度も思い描く", "b": "目標を考えるとき、実現までの道筋を考え、トレーニング中に決まった曲を聴きながら何度も思い描くという。重いものを持ち上げる時間は、瞑想のようなものだそうだ。ランブルも「次は出る」と口にしていたが、会う人には「今回は違う」と答える癖がついたと笑っている。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（44:04〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2644s"]]}, {"cat": "リングの話", "t": "ランブル前にトリプルHが肩を抱いてくれた", "b": "出番直前、言葉もなくトリプルHが近づき、肩を抱いて指をさしてくれたという。TNA王座を持ったままその写真に収まれたことを、眠りから覚めた人が信じないような光景だと話す。TNAとWWEが協力することで、双方のファンにも選手にも利益があると考えている。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（47:22〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2842s"]]}, {"cat": "暮らし", "t": "スコットランドへは日帰りで帰る", "b": "最近は大西洋を越えて、ほぼ丸1日だけ実家に帰ることもあるという。それでも落ち着くために帰りたくなるそうだ。留守中の愛犬は父が世話しており、家族の支えに感謝していると話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（49:50〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=2990s"]]}, {"cat": "リングに来るまで", "t": "「自分らしくやる」と決めた夜", "b": "エディ・エドワーズから、ジョー・ヘンドリーがやるタックルなら十分に盛り上がると教わり、器用さを競う必要はないと気づいたという。大事な試合の前、ミネソタの小さな会場で曲芸を足さず、自分らしく楽しむ試合をして手応えを得たそうだ。トップの人ほど、いつも自分自身であることが共通点だと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（56:28〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3388s"]]}, {"cat": "暮らし", "t": "ファンとの対面に全力を尽くす", "b": "握手会では限られた時間で相手が何を求めているか考えるようにしているという。腕には最近もらった「感謝」と書かれたブレスレットをつけ、家にはもらった贈り物をしまう引き出しがあるそうだ。ハーディーズの丁寧な対応を見習い、雑になったと感じたらサインを書き直すこともあると話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:00:31〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3631s"]]}, {"cat": "暮らし", "t": "本当のことを言ってくれる人だけを近くに", "b": "友人の条件は本当のことを言ってくれることだという。あるときTNAの番組で披露する曲を友人に見せると「だめだ」と言われ、書き直して良い出来になったそうだ。シナのように病気の子どもを支える活動もいつかしたいと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:04:38〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3878s"]]}, {"cat": "リングの話", "t": "シナ戦は「自分が動かすしかない」と話す", "b": "シナとの試合は実現すると本人は信じているが、そのためにはTNAとWWEにとって意味のある形に自分で持っていく必要があると語る。シナ本人からも、発言するのは構わないが実現させるのは君だと言われたそうだ。「やらなければ答えは必ずノー。挑戦しない理由がない」と話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:06:10〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3970s"]]}, {"cat": "好きなもの", "t": "弟と遊んだPUBGが公式タイアップに", "b": "2017年ごろ、弟と一緒に配信でよく遊んでいたのがPUBGだったという。その縁でPUBG Mobileから声がかかり、シナがフォートナイトに出ているのと並ぶようで感慨深いと話す。映画なら出来すぎだと笑っている。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:13:21〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4401s"]]}, {"cat": "リングに来るまで", "t": "音楽も配信もやっていたが、プロレス一本に絞った", "b": "数年前までアマレス、プロレス、音楽、配信などを並行していたという。どれも得意だったが、伝える物語は一つに絞るべきだと考え、プロレスに専念したそうだ。2017年にはレスラーとして早い時期にTwitch配信を始めていたとも話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:15:00〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4500s"]]}, {"cat": "暮らし", "t": "連絡の量が多すぎて返せないことも", "b": "昔の知り合いや同僚から毎日たくさん連絡が来て、5日返せないこともあるという。今はチームに事業面を任せ、創作に集中できるようにしている。誘いが増えるなか、伝えたい物語は一つに絞ると決めて断る判断をしていると話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:15:48〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4548s"]]}, {"cat": "暮らし", "t": "アメリカに拠点を持ちたい", "b": "移動が多すぎて、スコットランドへ帰れるのは1日か2日だけだという。洗濯が最大の悩みで、飛行機を含む移動の日は21〜28時間かかると話す。髪を染める場所はオーランドに確保済みで、アメリカに小さな部屋があればと考えている。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:16:36〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4596s"]]}, {"cat": "暮らし", "t": "一番の学びは友人との時間", "b": "忙しくなったのに、むしろ友人との時間を大切にしたと振り返る。オーランドの部屋で音が消えた瞬間、孤独を痛感したことがあるそうだ。今はツアー先に「ロード・ファミリー」がいて、夜中まで起きて一緒に過ごすこともあるという。以前は仕事に精一杯で、交流を避けていたと話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:19:05〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4745s"]]}, {"cat": "暮らし", "t": "愛犬グロメットと公園を歩く時間", "b": "帰郷したら必ず、愛犬を迎えに行ってから家の近くの公園を歩くという。事業の赤字や大きな借金、私生活の悩みを抱えていた頃も、同じ散歩は同じ喜びだったと話す。愛犬は手術が必要なけがをしており、今回は散歩ができないのが寂しいそうだ。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:22:20〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=4940s"]]}, {"cat": "家族", "t": "困ったら両親に電話する", "b": "専門家の助言も受けるが、母、父、継父に「どう思う?」と聞くのが大事だという。業界の事情に詳しくなくても、父が賛成してくれれば結果にかかわらず安心できるそうだ。両親がそろって健在で、時間を過ごせることに感謝していると話す。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-V0UPIBIMkOw", "src": [["番組のYouTube（1:28:50〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=5330s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "シナは目標とする手本の人", "b": "病院訪問や子どもを支える活動も含め、自分の行動の手本はジョン・シナだと、ジョー・ヘンドリーが話している。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で、ジョー・ヘンドリーの話（字幕を全文確認）", "src": [["番組のYouTube（1:04:38〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3878s"]], "by": "第三者の話"});
  if (PROFILES["Matt Hardy"]) PROFILES["Matt Hardy"].facts.push({"cat": "暮らし", "t": "マット・ハーディーが推薦してくれた", "b": "TNA復帰時にマイクを渡されたマット・ハーディーが、自分より先にヘンドリーの名前を挙げて推薦してくれたと、ジョー・ヘンドリーが話している。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で、ジョー・ヘンドリーの話（字幕を全文確認）", "src": [["番組のYouTube（59:45〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=3585s"]], "by": "第三者の話"});
  if (PROFILES["William Regal"]) PROFILES["William Regal"].facts.push({"cat": "暮らし", "t": "リーガルが業界の本質を教えた", "b": "新人のころ、ウィリアム・リーガルが約2時間かけて、プロレスは信頼を築く仕事だと教えてくれたと、ジョー・ヘンドリーが話している。", "sp": "ジョー・ヘンドリー", "d": "2025-05-13", "how": "クリス・ヴァン・ヴリートの番組で、ジョー・ヘンドリーの話（字幕を全文確認）", "src": [["番組のYouTube（20:03〜）", "https://www.youtube.com/watch?v=V0UPIBIMkOw&t=1203s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-V0UPIBIMkOw", d: "2025-05-13", show: "ext", who: ["Joe Hendry"], t: "ジョー・ヘンドリーの回　WMの舞台裏と、孤独を支える仲間と愛犬", lead: "クリス・ヴァン・ヴリートの番組に出た約90分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Joe Hendry"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-V0UPIBIMkOw").map((x) => [x.t, x.b, x.sp])), open: ["聞き手と同席者の話、広告部分、友人や元同居人など私人の名前は載せていない。", "試合の最終的な出来事や意気込みだけの話は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=V0UPIBIMkOw"]] });
