  if (!PROFILES["Lyra Valkyria"]) PROFILES["Lyra Valkyria"] = { lead: "アイルランド出身で、内気な少女が深夜の衝動で道場の扉を叩いた。大けがも乗り越え、素の自分で花道を歩く道を選んだ人。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Lyra%20Valkyria"]], moves: [], facts: [] };
  if (PROFILES["Lyra Valkyria"]._weak) { PROFILES["Lyra Valkyria"].lead = "アイルランド出身で、内気な少女が深夜の衝動で道場の扉を叩いた。大けがも乗り越え、素の自分で花道を歩く道を選んだ人。"; delete PROFILES["Lyra Valkyria"]._weak; }
  PROFILES["Lyra Valkyria"].facts.push(...[{"cat": "リングに来るまで", "t": "膝の前十字靱帯断裂で、目標の再戦を逃した", "b": "英国拠点の育成ブランドにいた頃、当時の女子王者マコ・サトムラへの挑戦に向かう途中で前十字靱帯を断裂したという。ダブリンの会場でシェス・ローリンズが同じけがをした日にその場にいて、自分も同じ技の最中に同じけがを負ったと話す。あの再戦だけは「もしも」が残る唯一の出来事だそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=192s"]]}, {"cat": "体のこと", "t": "けがの重さを知らず、手術のほうがこたえた", "b": "断裂と知らず、松葉杖を断って空港へ向かったほど軽く考えていたという。電話で全治9か月〜1年と告げられ、角の店で涙が止まらなかったそうだ。のちに婚約者となる男性と会う直前で、彼の肩をつかんで泣き顔を見せたと話す。本人は、けがそのものより手術と回復のほうがきつかったと振り返っている。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（4:49〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=289s"]]}, {"cat": "体のこと", "t": "離脱の期間が「働く理由」を見直すきっかけになった", "b": "休んでいる間も世の中は待ってくれないと学んだという。それでも戻りたい気持ちが、なぜ続けるのかを考え直させてくれたと話す。今は、あのけがで打たれ強くなったと感じていて、小さな傷あとも自分だけの勲章だそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（7:10〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=430s"]]}, {"cat": "暮らし", "t": "コーヒーは飲まず、エナジードリンクが好き", "b": "インタビュー中は黒いアメリカーノを手にしているが、普段はコーヒーを飲まないという。エナジードリンクはやや依存気味だと笑う。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（8:44〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=524s"]]}, {"cat": "体のこと", "t": "手首の記録計は常に「黄色」、火曜は睡眠3時間", "b": "手首に着けた回復度の計測機器は長く使ってきたという。数値はいつも黄色の領域で、完全に回復した日はないそうだ。毎週火曜は睡眠が3時間ほどで、緑にはなれないと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（8:44〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=524s"]]}, {"cat": "体のこと", "t": "トレーニングはクロスフィット中心", "b": "クロスフィットを知って夢中になり、もう他のやり方はしないという。きっかけは育成施設の隣のジムに通うアイビー・ナイルとその夫だそうだ。週にクロスフィット3回、ホットヨガ1回、自重トレ、時間があれば試合形式の練習を入れると話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（9:33〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=573s"]]}, {"cat": "好きなもの", "t": "踊ることが好きで、また始めたい", "b": "時間があればダンスに戻りたいと話す。ダンスもレスリングも体で個性を語る自己表現で、動きを見れば人柄が分かると考えているそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（10:22〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=622s"]]}, {"cat": "リングに来るまで", "t": "最初の憧れはベッキー・リンチのアイルランド舞踊", "b": "育成番組で最初に見たのがベッキー・リンチのアイルランド舞踊の登場場面だったという。同じ国の人が出ているなら自分にも道があるはずだと、ネットで国内の練習場所を調べ始めたと話す。兄の影響で見始め、最初は兄をからかっていたのに、自分のほうがのめり込んだそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（11:09〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=669s"]]}, {"cat": "好きなもの", "t": "ハマったきっかけは2011年頃の抗争", "b": "放課後に流れていた番組を見続け、ランディ・オートンとクリスチャンの抗争やジョン・シナ対CMパンクの大一番で決定的に引き込まれたという。その頃から有料の大会を購入するようになったと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（12:01〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=721s"]]}, {"cat": "リングに来るまで", "t": "マットで鍛えたアイルランド流の根性", "b": "始めた頃の練習場にはリングがなく、マットの上で受け身を習ったという。腕立てで隣の人に負けるな、と競い合う空気があった一方、互いを助け合う雰囲気もあったそうだ。「誰かを拍手で称えても自分の成功は減らない」という言葉が好きだと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（12:54〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=774s"]]}, {"cat": "リングに来るまで", "t": "内気な少女が、深夜に衝動で道場へ", "b": "当時は内気で、何かを始めるには友だちの付き添いが必要なタイプだったという。深夜1時開始の番組を見たまま午前3時に道場を調べ、偽名で行こうかとまで考えたそうだ。「今寝たら来週もやらない」と思い、翌日の練習に向かったと話す。この決断が人生を変えたという。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（14:31〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=871s"]]}, {"cat": "家族", "t": "初日の練習で、のちの婚約者に出会った", "b": "初日の練習は痛みの記憶が強く、細部はあまり覚えていないという。ただ、道場の外で最初に握手した相手が、のちに婚約者になる男性だったと話す。小さな選択が重なって今があると感じ、宇宙が味方してくれているようだと語る。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（15:20〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=920s"]]}, {"cat": "リングに来るまで", "t": "4分の壁の話で語る「前例がある強さ」", "b": "1マイル4分の壁を最初に破る人が出ると、その後に続く人が出るという例を挙げる。アイルランド出身の女性がここまで来たことで、自分にもできるはずだと思えたと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（16:56〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1016s"]]}, {"cat": "リングに来るまで", "t": "憧れの人との最初の出会いは地元の練習場", "b": "ベッキーが里帰りして撮影に来た日が最初の出会いだったという。当時は地元団体の初代女子王者として紹介され、急に視線が集まって慌てたと話す。そのとき感激して大泣きしたことを、今は少し恥ずかしい思い出として話している。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（17:43〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1063s"]]}, {"cat": "家族", "t": "両親は「芸能の世界に進むとは」と驚いた", "b": "内気だったので、父は娘がエンターテインメントの道に進んだのが信じられないと言うそうだ。本人も、花道の自分は無理に明るく振る舞うより、そのままの自分で出ていくほうがいいと考えるようになったと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（18:32〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1112s"]]}, {"cat": "リングの話", "t": "大一番の入場は翼つきの衣装で、煙に包まれた", "b": "白と金の翼の衣装を、事前に会場の舞台で試さなかったことが心残りだったという。入場では背を向けて登場し、振り向くと煙で観客が見えなかったため、足元を見て「転ぶな」と念じたそうだ。顔を上げた瞬間に煙が晴れ、満員の会場が見えたと話す。家族も婚約者も客席にいて、夢がかなったと語る。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（25:46〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1546s"]]}, {"cat": "リングの話", "t": "歴史的な王座の知らせはその日に聞いた", "b": "初代の女子大陸間王者に選ばれる話し合いには加わらず、当日に知らされたという。実感がわいたのは火曜に帰宅して荷物を出すとき、ベルトがバッグに入っているのを見た瞬間だったそうだ。空港の保安検査では毎回ベルトを預けられず、余裕を持って向かうと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（26:32〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1592s"]]}, {"cat": "リングの話", "t": "リングネームは愛読書と神話に由来", "b": "別名義のヴァルキリーは、12歳で出会った愛読書の主人公が名乗る名前に由来するという。移籍時に改名が必要となり、その本の作者デレク・ランディに相談したそうだ。提案されたアイルランド神話のモリガンは、カラスに姿を変えて戦場の勝敗を決める戦士で、ヴァルキリーともつながると話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（28:10〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1690s"]]}, {"cat": "好きなもの", "t": "「バードレディ」と呼ばれることを楽しんでいる", "b": "SNSの自己紹介にも鳥の女の意味の言葉を入れているという。ネットではハトが飛び込む動画に、ベルトを付け足した画像が出回っていて、それが気に入っていると話す。覚えてもらえるなら悪くないという考えだそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（30:28〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1828s"]]}, {"cat": "リングの話", "t": "タッグを組んだ相手との別れは複雑な思い出", "b": "大一番の直後、組んでいたベイリーが倒されるかたちで、憧れのベッキーとの抗争になったという。ベッキーもベイリーも自分に影響を与えた人なので、晴れ舞台の喜びに陰がさしたと話す。ベイリーとは数週間しか組まなかったが、会った瞬間から長い友だちのように話せる人だったそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（31:17〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1877s"]]}, {"cat": "リングに来るまで", "t": "遠征してでも名のある先生に学んだ", "b": "地元で学生をしながら練習に通い、試験を欠席し大学も休みがちだったという。収入より遠征費のほうが多く、試合で稼ぐ前にお金を払って練習する時期が長かったそうだ。学校で一番の人が各地を回っていたので、同じようにマーティ・ジョーンズやジョニー・モスの教室に通ったと話す。のちにジョニー・モスが育成施設の指導者になるとは思わなかったそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（36:14〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2174s"]]}, {"cat": "リングに来るまで", "t": "お金や契約ではなく、上達が目的だった", "b": "最初は台本のある世界を想像し、試合を早送りして抗争場面を見ていたほどだという。だが練習に通ううちに試合そのものの魅力に目覚め、今は逆になったと話す。睡眠不足で安い宿に泊まって移動する日々も好きだったそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（40:14〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2414s"]]}, {"cat": "リングに来るまで", "t": "ドイツの練習で「誰も成功しない」と言われた", "b": "ドイツの団体の教室で、先生に「この部屋の誰も成功しない」と告げられたが、自分は必ず成功すると思ったという。団体に選ばれたから選手になったのではなく、選手であることを自分で決めたので、団体がなくなっても続けると話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（42:35〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2555s"]]}, {"cat": "リングの話", "t": "得意なのは技術派の試合運び", "b": "育った道場が技術重視の流儀で、相手を上回ろうと競い合う試合の感覚が好きだという。台本のない手合わせでは、やり取りと競争が本物になる楽しさがあると話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（44:10〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2650s"]]}, {"cat": "リングの話", "t": "女王の座を争った試合で、巨体の技を受けた", "b": "ニア・ジャックとの試合の終盤、肋骨が壊れそうな技を受けたが、骨折はしなかったという。特にサモアンドロップのほうがきつく、息が上がったそうだ。入団から約1か月の時期に自分で作った大きな瞬間として、価値があったと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（45:46〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2746s"]]}, {"cat": "リングの話", "t": "シェイマスの「ケルト戦士の運動」に参加した", "b": "同郷のシェイマスの運動企画に招かれたという。重りは軽くしたが、十分きつかったそうだ。シェイマスは「一番きつかった」と言ってくれたが、誰にでも言うのかは分からないと笑う。彼は何でも試す姿勢がよいと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（47:24〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2844s"]]}, {"cat": "リングの話", "t": "試合の日の朝、コーヒー店で泣いた", "b": "年間最大級の大会の日、コーヒーを買う列で急に涙が出たという。王座のベルトを腰に巻いて入場する実感が、突然わいたそうだ。悲しみではなく、感謝と喜びの涙だったと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（50:41〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=3041s"]]}, {"cat": "リングの話", "t": "役を演じず、自分のまま出ていく", "b": "声量や口数が多いタイプではないが、素のまま花道を歩くほうが良いと決めたという。最近はマイクも強気になり、「まだまだ出せる言葉がある」と話す。最終的には大会の主役の試合に立ちたいという。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（51:30〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=3090s"]]}, {"cat": "暮らし", "t": "毎晩、寝る前と起きたときに感謝を3つ言う", "b": "婚約者、機会に恵まれたこと、健康、そして長い道のりをともにした友人たちへの感謝を挙げる。初試合の相手たちとも今も親しく、オーランドの友人も大切だそうだ。婚約者とはキャリアの始まりから互いを見てきて、地に足をつけさせてくれる存在だと話す。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PGyK-wmlCXs", "src": [["番組のYouTube（53:03〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=3183s"]]}]);
  if (PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"].facts.push({"cat": "暮らし", "t": "道を切り開いた最初の人", "b": "ベッキー・リンチは、誰も不可能と思った壁を最初に越えた人で、自分が選手を目指した理由でもあると、ライラ・ヴァルキュリアが話している。育成番組時代の四天王の一人としても、大きな存在だったという。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で、ライラ・ヴァルキュリアの話（字幕を全文確認）", "src": [["番組のYouTube（16:08〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=968s"]], "by": "第三者の話"});
  if (PROFILES["Bayley"]) PROFILES["Bayley"].facts.push({"cat": "暮らし", "t": "会えば昔からの知り合いのような人", "b": "ベイリーは話しやすく人柄が良く、会ってすぐ打ち解けられる人だと、ライラ・ヴァルキュリアが話している。婚約者に紹介したときも、初対面なのに知っているように感じたと言っていたそうだ。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で、ライラ・ヴァルキュリアの話（字幕を全文確認）", "src": [["番組のYouTube（33:02〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=1982s"]], "by": "第三者の話"});
  if (PROFILES["JD McDonagh"]) PROFILES["JD McDonagh"].facts.push({"cat": "暮らし", "t": "根性の人", "b": "JD・マクドナーは肺に重傷を負いながら試合を続けた鉄人のような人で、目標にできる存在だと、ライラ・ヴァルキュリアが話している。", "sp": "ライラ・ヴァルキュリア", "d": "2025-05-20", "how": "クリス・ヴァン・ヴリートの番組で、ライラ・ヴァルキュリアの話（字幕を全文確認）", "src": [["番組のYouTube（46:32〜）", "https://www.youtube.com/watch?v=PGyK-wmlCXs&t=2792s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-PGyK-wmlCXs", d: "2025-05-20", show: "ext", who: ["Lyra Valkyria"], t: "ライラ・ヴァルキュリアの回　内気な少女から初代女子大陸間王者へ", lead: "クリス・ヴァン・ヴリートの番組に出た約55分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Lyra Valkyria"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-PGyK-wmlCXs").map((x) => [x.t, x.b, x.sp])), open: ["婚約者の名前や、聞き取れなかった固有名詞は、本人の発言を追いきれない箇所があり載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=PGyK-wmlCXs"]] });
  if (!PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dominik%20Mysterio"]], moves: [], facts: [] };
  if (PROFILES["Dominik Mysterio"].lead === "") PROFILES["Dominik Mysterio"]._weak = 1;
  PROFILES["Dominik Mysterio"].facts.push(...[{"cat": "リングの話", "t": "初めての練習試合はいきなり4連戦", "b": "ドミニク・ミステリオは20歳のとき、タンパでジェイ・レセルの教室に初めて顔を出し、前の晩に「明日が初試合だ」と告げられたという。実際は同じ日に練習生を相手に4試合を続けてこなすことになったそうだ。当時は体重250〜260ポンドほどで、1試合目の後はトイレで横になり「もう無理だ」と思ったと話す。それでも「ここで諦めるな」と思い直し、何度か吐きながら最後までやり切ったという。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（14:28〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=868s"]]}, {"cat": "リングの話", "t": "8歳の舞台裏は三輪車とテープ玉", "b": "8歳の頃は学校を休んで会場に同行し、舞台裏で選手たちと過ごしていたと、ドミニクが話す。ビッグ・ショーやランディ・オートンらにテープを丸めた玉を投げたり、BWOの三輪車を勝手に乗り回したりしたそうだ。エディ・ゲレロとも写真が残っていて、今の自分の仕事は彼への敬意でもあると語る。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（20:13〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1213s"]]}, {"cat": "リングの話", "t": "父とのコント動画では銃のまねをした", "b": "父レイ・ミステリオと一緒に撮った寸劇について、ドミニクが内容を明かした。試合に向けて相手を脅す設定で、「準備しておけ、でないと俺が準備する」と言いながら銃を構えるしぐさをしたという。思った以上に多くの人に見られていたと笑っている。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（28:10〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1690s"]]}, {"cat": "リングの話", "t": "悪役転向は「何かが切り替わった」", "b": "ステファニーから、転向の少し前に「人生が変わるよ」と言われていたと、ドミニクが振り返る。当時は善玉に慣れ始めたばかりで意味が分からなかったが、実際に転向すると頭の中で何かが切り替わり、「これだ、めちゃくちゃ楽しい」と感じたそうだ。観客に嫌われる理由は自分でも分からないが、「俺たちが上手いからだと思う」と話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（29:45〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1785s"]]}, {"cat": "リングの話", "t": "家族相手の悪役は母にだけ気が引けた", "b": "物語の中で家族に手を出すことについて、ドミニクは「父を叩いても全然悪いと思わない」と話す。一方、母の顔の前で怒鳴りつけた場面は少しだけ気が引けたという。母に平手打ちをするのはとてもできないと語っている。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（31:22〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1882s"]]}, {"cat": "リングの話", "t": "骨のファルコンは自分の発案", "b": "試合で身につける骨柄のファルコンのデザインは、ドミニク自身のアイデアだという。父や叔父は長年ファルコンのモチーフを使ってきたが、骨の形にしたものはなかったそうだ。体のタトゥーもレントゲン風に統一していて、骨のファルコンがよく合うと考えていると話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（40:16〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2416s"]]}, {"cat": "リングの話", "t": "ミステリオの名をどう広げるか", "b": "ドミニクは、父がミステリオの名前を世界に広めて殿堂入りまで果たしたので、自分に残された役目が何か考え続けていると話す。それでも長くこの仕事を続けるつもりで、父を超える選手になりたいと語る。それがほぼ不可能な課題だと分かったうえで、挑戦するという。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（48:04〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2884s"]]}]);
  if (!PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"] = { lead: "サンディエゴ育ちの三世レスラーで、14歳で出会った妻を4度目の告白で射止めた粘り強さが持ち味。チキンテンダーとタトゥーを愛し、自分をさらけ出すことを大切にしていると話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Dominik%20Mysterio"]], moves: [], facts: [] };
  if (PROFILES["Dominik Mysterio"]._weak) { PROFILES["Dominik Mysterio"].lead = "サンディエゴ育ちの三世レスラーで、14歳で出会った妻を4度目の告白で射止めた粘り強さが持ち味。チキンテンダーとタトゥーを愛し、自分をさらけ出すことを大切にしていると話す。"; delete PROFILES["Dominik Mysterio"]._weak; }
  PROFILES["Dominik Mysterio"].facts.push(...[{"cat": "好きなもの", "t": "地元パドレスの熱狂的ファン", "b": "サンディエゴ育ちで、野球のパドレスの大ファンだという。子どものころの自分に贈るなら、トニー・グウィンのサイン入りユニフォームを選ぶと話す。家の中は何でも競い合う空気で、父もパドレス好きなため、わざと別のチームを応援したこともあったそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（9:44〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=584s"]]}, {"cat": "家族", "t": "妻とは14歳の同級生", "b": "妻とは14歳のときに出会った。最初は嫌われていたと感じており、彼女が受けていたスペイン語の初級クラスにわざわざ入ったという。スペイン語は母語で、先生に10まで数えられるかと聞かれて50まで数え、かえって生意気だと思われたそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（11:15〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=675s"]]}, {"cat": "家族", "t": "4度目の告白で交際に", "b": "友人経由で連絡先を手に入れ、少しずつ話すようになった。交際を申し込んで3回断られ、4回目でようやく受け入れてもらえたという。この粘り強さが、人生でいちばん大きな教訓だと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（13:39〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=819s"]]}, {"cat": "リングに来るまで", "t": "初練習試合は4本連続", "b": "20歳のころフロリダ州タンパでジェイ・リーサルのもとで練習を始め、初めての練習試合で予告なしに4本続けて組まれたという。当時は身長約183cm、体重は約113〜118kgあり、1本目の後にはトイレの床に寝転んでしまったそうだ。あきらめかけたが思い直し、何度か吐きながらも最後までやり切ったと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（14:28〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=868s"]]}, {"cat": "リングに来るまで", "t": "小学6年で停学になった", "b": "子どものころは好奇心が強く、ナイフに興味があったという。11〜12歳のころ、友人とスクールバスの中でナイフを交換しようとして見つかり、停学になったそうだ。迎えに来た母には「お父さんが帰るまで待ちなさい」と言われ、父にもきつく叱られたと振り返る。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（16:07〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=967s"]]}, {"cat": "リングに来るまで", "t": "8歳の舞台裏の思い出", "b": "8歳ごろは学校を休んで父の巡業についていき、舞台裏で過ごしたという。三輪車を勝手に乗り回したり、テープを丸めてビッグ・ショーやランディ・オートンらに投げたりしていたそうだ。エディ・ゲレロとリングに上がった記憶も含め、今振り返るとありがたい経験だと話し、エディをたたえたい気持ちも口にしている。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（20:13〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1213s"]]}, {"cat": "好きなもの", "t": "憧れはジェフ・ハーディー", "b": "子どものころはずっとプロレスファンで、大会にも行き、フィギュアも集めていたという。いちばん好きだったのはジェフ・ハーディーで、派手な色づかいや身なりに引かれたそうだ。DXも大好きで、ショーン・マイケルズのファンだったと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（24:09〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1449s"]]}, {"cat": "リングに来るまで", "t": "短大で経営を学んだ時期も", "b": "もともとプロレスを仕事にすると決めていたわけではなく、まず挑戦してみたかったという。高校卒業後は短期大学で経営学を少し学んだが、勉強はあまり得意ではなかったそうだ。専攻は当時交際中だった今の妻に「とにかく何か選んで」と言われて決めたと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（25:43〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1543s"]]}, {"cat": "リングに来るまで", "t": "カナダ、タンパ、オーランドで修業", "b": "カナダのカルガリーでランス・ストームに、タンパでジェイ・リーサルに習い、契約後はオーランドの育成施設に1年〜1年半ほどいたという。地元に残って練習したいと渋ったこともあったが、妻に「お父さんがそう言うなら行くべき」と背中を押されたそうだ。妻はずっと支えてくれた心の支えだと話す。結婚式の準備も妻に任せきりで、言われた日時に会場へ行っただけだという。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（26:34〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1594s"]]}, {"cat": "暮らし", "t": "首の「ビジャーノ」は反発心から", "b": "首のタトゥーはスペイン語で「悪役」を意味する言葉だという。妻の親族はポルトガル系の大家族で、集まりの席で年配のおじに「首だけは彫るな」と言われたのがきっかけだったそうだ。翌日ラスベガスの彫り師に予約を入れ、飛行機の中で文字を決めて彫ったと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（31:22〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=1882s"]]}, {"cat": "暮らし", "t": "お気に入りは内ももの絵柄", "b": "タトゥーは気分次第で、両脚を3日連続で彫ったこともあるという。いちばん気に入っているのは、映画『スクリーム』の仮面の殺人鬼を内ももに入れたもの。想像以上に痛く、耐え抜いて手に入れた一枚だと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（33:45〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2025s"]]}, {"cat": "好きなもの", "t": "両手にルチャの名レスラー", "b": "最近は両手にマスクの絵柄を入れたという。片手には名付け親のサイコシス、コナン、ビジャーノ4号と、子どものころ好きだったラ・パルカ。もう片方の手にはエル・ラヨ・デ・ハリスコ、ミル・マスカラス、ブルー・デモン、エル・サントの4人を入れ、敬意を表したそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（34:35〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2075s"]]}, {"cat": "家族", "t": "初タトゥーは15歳、父の贈り物", "b": "15歳の誕生日に何が欲しいか父に聞かれ、タトゥーと答えたという。年齢的に店に行けないため、父の彫り師に自宅のガレージで彫ってもらったそうだ。背中を希望したが、父に「いちばん痛いあばらにしろ」と言われ、あばらに入れたと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（37:55〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2275s"]]}, {"cat": "家族", "t": "子どもは考えているが今は二人で", "b": "結婚して1年ほどで、子どもを持つつもりはあるが、まずは夫婦の時間を楽しみたいという。自分はその日暮らしの性格だが、妻は計画好きだそうだ。最近もインド遠征中に妻の帰りの便を月を間違えて予約してしまい、妻が自分で直してくれたと明かしている。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（41:50〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2510s"]]}, {"cat": "好きなもの", "t": "愛犬カリはボクサー系の白い犬", "b": "ボクサーとピットブルのミックスの小型犬を飼っており、名前はカリ。ドラマ『ゲーム・オブ・スローンズ』のカリーシにちなんだ名前で、妻にこのドラマを勧めたのも自分だという。全身白で青い目、体重は約27kgだそうだ。大の犬好きで、猫はそれほどでもないと話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（43:21〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2601s"]]}, {"cat": "暮らし", "t": "マレットは毎日シャンプー", "b": "靴が好きで、帽子もよくかぶるという。髪は毎日シャンプーとコンディショナーをし、日に2回シャワーを浴びることもあるそうだ。父は髪がないことで知られているので、自分の髪は大事にしたいと笑う。ひげは伸びないが口ひげだけは濃いと話す。子どものころのように髪を全部金色に脱色する案も考えているそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（49:39〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2979s"]]}, {"cat": "好きなもの", "t": "チキンテンダーは毎晩でも", "b": "メニューにあれば必ずチキンテンダーを頼み、ソースはランチ派だという。子ども用セットを頼んで店員に驚かれることもあり、3本ではなく5本を選ぶそうだ。好きな店はレイジング・ケインズとウィングストップで、ランチソースは持参することもある。家では妻が恐竜形ナゲットとマカロニチーズ、フライドポテトを作ってくれると話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（52:44〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=3164s"]]}, {"cat": "暮らし", "t": "隠しごとはしない主義", "b": "自分は隠しごとのない人間で、聞かれれば何でも話すという。自分らしくいなければ成功はないし、取り繕わないほうが良い関係が築けると考えているそうだ。1997年生まれでポケベルを知らなかったと明かし、毎日何かを学んでいると話す。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（59:13〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=3553s"]]}, {"cat": "好きなもの", "t": "イン・アンド・アウトは裏メニュー", "b": "二番目の好物はハンバーガー店のイン・アンド・アウトだという。肉とチーズ4枚ずつの裏メニューを、野菜抜き・特製ソースのみ・マスタード焼き・刻み唐辛子入りで頼むそうだ。野菜は食べないと話している。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（1:00:53〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=3653s"]]}, {"cat": "好きなもの", "t": "機内ではシナトラを聴いて眠る", "b": "大の音楽好きで、カントリー、R&B、ヒップホップ、レゲエ、メキシコの伝統音楽、クラシックまで何でも聴くという。飛行機の中や寝る前にはフランク・シナトラをかけて眠ることもあるそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（1:08:50〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=4130s"]]}, {"cat": "家族", "t": "正反対でも価値観は同じ", "b": "妻は音楽より実録犯罪もののポッドキャストが好きで、趣味は正反対だという。それでも価値観や考え方が同じなので結婚生活がうまくいっていると話す。妻の父は庭で野菜や鶏を育てており、妻は野菜を何でも食べるので、偏食の自分とバランスが取れているそうだ。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-KLIRLjItQcw", "src": [["公式YouTube（1:09:38〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=4178s"]]}]);
  if (PROFILES["Liv Morgan"]) PROFILES["Liv Morgan"].facts.push({"cat": "暮らし", "t": "サウジで野良猫を保護した", "b": "サウジアラビア遠征中、リブ・モーガンが野良猫をホテルの部屋で3日ほど世話し、ルームサービスでサーモンを頼んで食べさせていたと、ドミニク・ミステリオが話している。最終的には現地の警備担当者が、ペットを欲しがっていた息子のために引き取ってくれたという。", "sp": "ドミニク・ミステリオ", "d": "2025-05-22", "how": "ステファニーの番組で、ドミニク・ミステリオの話（公式字幕を全文確認）", "src": [["公式YouTube（45:40〜）", "https://www.youtube.com/watch?v=KLIRLjItQcw&t=2740s"]], "by": "第三者の話"});
