  PROFILES["Brandi Rhodes"].facts.push(...[{"cat": "リングの話", "t": "時間が削られた乱戦形式の試合", "b": "ブランディ・ローデスは、乱戦形式の試合で時間が短くなり、予定していた見せ場が出せなかった経験があるという。試合後に裏で全員に怒りをぶつけたと、夫のコーディが振り返っている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（3:14〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=194s"]]}, {"cat": "リングの話", "t": "最初の大会でラシールの偽エリザベスを演じた", "b": "ブランディは、自分たちが初めて開いた大規模大会で、ジェイ・リーサルの偽エリザベス役を務めたことを、お気に入りの思い出のひとつに挙げている。リーサルのマッチョマン物まねは屈指の出来だったという。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（26:05〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1565s"]]}, {"cat": "リングの話", "t": "ニック・アルディスの肘はとても丁寧だった", "b": "ブランディは、ニック・アルディスと当たった試合で、これまで受けた中で一番きれいな肘打ちをもらったと話す。相手を気づかうプロの仕事ぶりに感心していたそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（28:31〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1711s"]]}, {"cat": "リングの話", "t": "最強チームは女子の暴れん坊をそろえる", "b": "ブランディは、できるだけ楽をしたいという理由で、自分、ベッキー・リンチ、シェリー・マーチネット、リア・リプリー、パイパー・ニーヴェンを選ぶと話す。ニーヴェンの大技を受けたら立ち上がれないと言い、コーディも実際に受けたと応じている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（34:13〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2053s"]]}, {"cat": "リングの話", "t": "リングから離れて恋しいのは舞台の空気", "b": "ブランディは、毎回の興行にある特別感と、ヨーロッパなど各地へ行く旅が恋しいと話す。夫と一緒に回った時間も大きいという。一方、毎週トラックにはねられたような疲れだけは恋しくないそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（50:31〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3031s"]]}, {"cat": "リングの話", "t": "裏方としての貢献は自分の信念で選んだ", "b": "ブランディは、団体の中で役割に就くと、周りは表面しか見ないものだと語る。自分は正しいと思う形でだけ貢献し、人の声を後ろ盾にするために誰かとつるむことはしなかったと話す。認めたくない相手の承認は要らないとも言っている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（53:44〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3224s"]]}, {"cat": "リングの話", "t": "スターダストを恥じたことは一度もない", "b": "ブランディは、夫が演じたスターダストを最高のレスラーのひとりだと思っていたと話す。気になっていたのは、本人がそれを気にしていたことだけだったそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（56:55〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3415s"]]}, {"cat": "リングの話", "t": "復帰の日を信じて疑わなかった舞台裏", "b": "ブランディは、夫の復帰がどうなるか直前まで不安だったが、観客のファン目線で見て大歓声になると確信していたと話す。復帰の舞台裏では、ステファニー・マクマホンとジ・アンダーテイカーの間に座り、緊張しながら出番を待っていたという。夫がブーイングを心配したときも、年間最大の祭典だから大丈夫だと言い切ったそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:00:04〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3604s"]]}, {"cat": "リングの話", "t": "初の大会のチケットサイトはすぐ落ちると予想", "b": "ブランディは、最初の大規模大会の発売前に、段階を分けない販売ならサイトが落ちると指摘したという。周囲には取り合われなかったが、発売直後にサイトが落ち、数十秒で完売したと話している。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:02:36〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3756s"]]}, {"cat": "リングの話", "t": "日本でのイヨ・スカイとの初試合", "b": "ブランディは、初めて一人で日本に行ったとき、英語があまり話せないイヨ・スカイと組まされたという。通訳がなく、身ぶりで試合を作ったそうだ。イヨに太ももの裏を何度も強く蹴られて怒り、思いきり胸を打ち返したと話す。試合後は互いにたたえ合い、あの蹴りは自分を奮い立たせるためだったと考えているそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:04:17〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3857s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Brandi Rhodes")) ROSTER.push(["ブランディ・ローデス", "Brandi Rhodes", "lg", "コーディの妻・元リングアナ", "", "", ""]);
  if (!PROFILES["Brandi Rhodes"]) PROFILES["Brandi Rhodes"] = { lead: "リングアナや裏方として道を切り開き、いまはヨガとピラティスのスタジオを営む。認めない相手の評価はいらないと言い切る一方、家では夫の足音に頭を抱えている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Brandi%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Brandi Rhodes"]._weak) { PROFILES["Brandi Rhodes"].lead = "リングアナや裏方として道を切り開き、いまはヨガとピラティスのスタジオを営む。認めない相手の評価はいらないと言い切る一方、家では夫の足音に頭を抱えている。"; delete PROFILES["Brandi Rhodes"]._weak; }
  PROFILES["Brandi Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "いくつもの「初めて」を持つ人", "b": "新日本プロレスの年間最大の大会で試合に関わった初の女性であり、WWE初の黒人女性フルタイムのリングアナウンサーでもあったと、夫コーディが紹介している。北米の団体で初の黒人の役員にもなったという。現在はヨガとピラティスのスタジオのオーナーを務めている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（0:46〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=46s"]]}, {"cat": "体のこと", "t": "胃にやさしいジンジャーの一杯", "b": "年を重ねるにつれて胃が痛むことが多くなったという。そのためジンジャービアを使ったミュールが好きで、胃の調子が悪い日でも飲めるのがありがたいそうだ。夫も同じものを飲んでいる。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（4:52〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=292s"]]}, {"cat": "暮らし", "t": "一日の始まりはベッドメイク", "b": "朝にベッドを整えれば、一つ目の目標を終えた達成感を持って一日を始められるというのが持論だ。結婚してからずっとベッドを整えない夫には不満があるらしい。夫が娘の朝食のワッフルを皿にのせただけで出した日には、シロップや果物、生クリームも添えるよう言ったそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（12:19〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=739s"]]}, {"cat": "暮らし", "t": "感謝されないと引っかかる性分", "b": "人のために何かをしても感謝されないことが重なると、「利用されている」と感じてしまうことがあると自ら認めている。育ち方の違う人どうしがぶつかるのは自然なことで、健全な形でこの気持ちから抜け出したいと話す。お礼を求めない主義の夫とは、この点でよく話し合うそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（15:42〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=942s"]]}, {"cat": "家族", "t": "夫の足音が家じゅうに響く", "b": "12年前に出会ったころから、夫は家の中を恐竜のようにドスドス歩くのだという。寝ている娘を起こさないか、いつも心配しているそうだ。最近は娘も自分で気づいて「また足音がうるさい」と注意するようになったと笑う。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（16:27〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=987s"]]}, {"cat": "暮らし", "t": "ドアをバタンと閉められると怒る", "b": "娘が赤ちゃんのころ、寝かしつけたあとにドアを勢いよく閉めて起こしてしまうナニーがいて、強くいらだったという。ドラマ『ライチャス・ジェムストーンズ』のベイビー・ビリーがナニーに文句を言う場面に共感するそうだ。体調を崩した夜に夫が同じことをしたときも黙っていられなかったと話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（18:05〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1085s"]]}, {"cat": "暮らし", "t": "40代、もっぱらインスタ暮らし", "b": "40代になって、世の中の流行はもっぱらインスタグラムで眺めているという。華やかなイベントの話題には興味が薄く、芸能事情は夫のほうが詳しいそうだ。子育ての知恵も、インスタで発信している人たちから学んでいると話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（19:42〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1182s"]]}, {"cat": "家族", "t": "兄の涙でプロレス禁止の家に", "b": "子どものころ、兄がWWEに夢中で、マッチョマンかアルティメット・ウォリアーを応援していたという。ある大会の結末に兄が怒って泣き、物を投げたため、家でプロレスが禁止になったそうだ。自分がこの世界に入ってから家族も再び見るようになり、今では父が熱烈なファンだと話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（23:45〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1425s"]]}, {"cat": "好きなもの", "t": "非常時に連れて行く仲間", "b": "ゾンビの世界を生き抜くチームを組むなら、娘、ドラマのベイビー・ビリー、フィギュアスケートのミシェル・クワン、何でも手配してくれる自分のマネージャー、そして一番好きな俳優のモーガン・フリーマンを選ぶという。レスラーで組むなら、ベッキー・リンチ、センセーショナル・シェリー、リア・リプリー、パイパー・ニーヴンを挙げた。パイパーの体当たりは実際に受けたことがあり、起き上がるのがやっとだったそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（30:55〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1855s"]]}, {"cat": "家族", "t": "父は元軍人で自動車会社勤め", "b": "父は軍の出身で、その後は自動車メーカーのフォードで長く働いてきた人だという。夫の帽子をかぶって出歩くほどのファンで、夫いわく、プロレス界に入れても成功しそうなほど抜け目ない人だそうだ。両親はネット上の冷やかしなどは知らないだろうし、気にもしないと話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（36:44〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2204s"]]}, {"cat": "家族", "t": "義母のお菓子攻勢と4年の攻防", "b": "夫の母は孫に甘く、娘の誕生日には綿あめを食べさせすぎて、その夜娘が吐いてしまったことがあるという。それ以来お菓子のルールを守ってもらおうとしているが、年間最大の祭典の観覧席でもポケットからチョコを出していたそうだ。「ママ・ローデス」は義母の呼び名で、自分はあくまでブランディ・ローデスだと念を押している。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（38:26〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2306s"]]}, {"cat": "家族", "t": "娘は夫に似て涙もろい", "b": "娘は夫に似て感受性が強く、感情がすぐ表に出るという。自分は涙が出るまでに相当なことが必要なタイプなので、その感覚が分からないこともあるそうだ。リンゴ狩りの日に写真を撮ろうとしたらハエが顔に当たり、娘が大泣きしたのは今では笑い話になっている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（40:44〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2444s"]]}, {"cat": "好きなもの", "t": "娘より先にディズニー好き", "b": "2日空けばすぐディズニーへ行くほどのファンで、SNSでは「住んでいるの？」と聞かれるほどだという。娘が生まれる前からの大人のディズニー好きで、娘はたまたまその恩恵にあずかっているだけだと笑う。園内のレストランで有名俳優の夫妻と意気投合し、相手の夫と同じ地域で育ったと分かったこともあるそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（45:43〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2743s"]]}, {"cat": "好きなもの", "t": "思い入れのジャージはデトロイト", "b": "思い入れのあるスポーツのジャージを聞かれ、アイスホッケーのデトロイト・レッドウィングスのスティーブ・アイザーマン、野球のデトロイト・タイガースのランダル・サイモンを挙げた。「とことんデトロイトでいく」と話している。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（48:52〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2932s"]]}, {"cat": "体のこと", "t": "恋しいのは「特別な夜」の空気", "b": "プロレスの現場で恋しいのは、どの大会にもある特別な場の空気と、ヨーロッパなど普段行けない土地を巡れたこと、そして夫と旅をした時間だという。一方で、毎週トラックにはねられたような体になる感覚は恋しくないそうだ。そこまで多く試合をしたわけではないのに、今でもその影響を感じると話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（50:31〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3031s"]]}, {"cat": "暮らし", "t": "ヨガとピラティスのスタジオ経営", "b": "ジョージア州ロズウェルでヨガとピラティスのスタジオを営んでいる。オンライン配信はせず、通ってもらう形にこだわっているという。100回、200回と通う会員がいて、400回目を迎える人も出るそうだが、日々の対応に追われ「毎日白髪が1本増える」と苦笑する。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（51:16〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3076s"]]}, {"cat": "リングに来るまで", "t": "認めない相手の承認はいらない", "b": "役職についてみて、外から見えるのは仕事のごく一部だと実感したという。自分が正しいと思う形でだけ貢献し、正しくない人とは関わらないと決めていたため、後ろ盾になる声はなかったそうだ。それでも、自分が認めない相手からの評価は必要ないと言い切っている。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（54:29〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3269s"]]}, {"cat": "家族", "t": "スターダスト時代も恥じなかった", "b": "夫が奇抜なキャラクター、スターダストを演じていた時期も、それを恥ずかしいと思ったことは一度もないという。むしろ素晴らしい選手だと思っていて、気になったのは夫自身が悩んでいたことだけだったそうだ。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（56:55〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3415s"]]}, {"cat": "家族", "t": "夫の復帰の夜、迷いはなかった", "b": "夫がWWEへ戻った年間最大の祭典の夜、夫は「ブーイングされたら」と不安がっていたが、自分は大丈夫だと確信していたという。入場口の裏で待機するのは初めてで、周りが見えないほど集中していたそうだ。会場が一気に沸いた瞬間は「最高の出来事」だったと振り返る。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:00:04〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3604s"]]}, {"cat": "リングに来るまで", "t": "初の単身日本で組んだイヨ・スカイ", "b": "初めて一人で日本へ渡った際、イヨ・スカイと対戦したという。通訳もいない中で身ぶりで試合を組み立て、言われた唯一の完全な英文は「しくじるなよ」だったそうだ。試合中に太もも裏を何度も強く蹴られて本気で腹が立ち、生涯で一番強いチョップを返したが、自分を奮い立たせるためだったのだろうと今は話す。", "sp": "ブランディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:04:17〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3857s"]]}]);
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "暮らし", "t": "年を取ったらこうなると予告", "b": "妻はいつまでも若々しいが、自分はそうはいかないと冗談めかして話す。日焼けした大きな体に派手な柄シャツ、短パンとビーチサンダルという、南部の男そのものの姿になると予告している。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（6:32〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=392s"]]}, {"cat": "家族", "t": "父の赤い革ジャンを探している", "b": "父ダスティ・ローデスが着ていた、肩に爬虫類革のついた赤いレザージャケットの行方が分からないという。父は生前、多くの品を売ったり質に入れたりしていたそうだ。欲しかった保安官のバッジも含め、親族の誰かが持っているはずなので名乗り出てほしいと話す。父の遺品の整理はプロを雇って行ったという。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（8:10〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=490s"]]}, {"cat": "好きなもの", "t": "狩りは一度で懲りた", "b": "自分が狩りに行ったのは一度だけで、スコープ付きの銃で20ヤードほど先の鹿を外したうえ、銃まで落としたという。男としての自信が最もしぼんだ瞬間の一つだったと笑う。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（9:48〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=588s"]]}, {"cat": "家族", "t": "父が最後に仕留めた鹿「バック」", "b": "父は狩りそのものより、森で一人で座って次の手を考える時間が好きだったという。専用の階段つきの見張り台を持っていて、今も記念の札が残っているそうだ。父が最後に仕留めた鹿の頭の剥製「バック」を車に載せていたため、妻が乗り込んで飛び上がったこともある。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（10:39〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=639s"]]}, {"cat": "暮らし", "t": "ベッドより先に動き出す朝", "b": "朝はベッドを整えるより、足が床についたらすぐ動き出す派だという。その間に子どもの着替え、犬の世話、朝食の準備、電話を済ませているそうだ。ただ、娘のワッフルを皿にのせただけで出したときは妻にたしなめられた。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（13:13〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=793s"]]}, {"cat": "暮らし", "t": "「どういたしまして」は言わない", "b": "「どういたしまして」という言葉が好きではないという。人に何かするのは感謝されるためではないので、お礼を言われたら自分も「ありがとう」と返すそうだ。年間最大の祭典で知人を手厚くもてなしたときも、お礼を求める気はなかったと話す。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（14:01〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=841s"]]}, {"cat": "家族", "t": "娘に言われれば足音も直す", "b": "家の中をドスドス歩く癖を妻に指摘されても気にしなかったが、娘に言われたら直すつもりだという。自分は娘のために働いているようなものだからと話す。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（18:05〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1085s"]]}, {"cat": "家族", "t": "夢のチームは愛犬と父と兄", "b": "自分のドリームチームには、まず老犬のファラオ、そして父ダスティと兄ダスティンを選んだ。兄のことは大好きなのに、十分に気持ちを伝えられていないと話している。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（33:17〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=1997s"]]}, {"cat": "家族", "t": "ショービジネスの家に生まれた自覚", "b": "自分はショービジネス、見世物の世界、プロレスの家の出だと話す。だからこそ、軍出身で一つの会社に勤め続けた妻の父との違いが面白いという。結婚式では、両家の父が名タッグのようだったそうだ。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（36:44〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2204s"]]}, {"cat": "家族", "t": "モアナ2の試写会と娘", "b": "ザ・ロックに招かれ、家族でハワイでの『モアナと伝説の海2』の試写会に行ったという。周りの子がモアナの格好をする中、娘だけはエルサの衣装だったそうだ。人見知りしていた娘が、後ろの席に来たロックに自分から振り向いて手を振り、笑顔でハグをしたことに驚いたと話す。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（42:26〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=2546s"]]}, {"cat": "家族", "t": "持ち物はすべて妻のもの", "b": "バスも服も車も、持っているものはすべて妻のものだと話す。大物選手を紹介する立場だった妻が、奇抜なキャラクターを演じていた自分を夫として支え続けてくれたからだという。その時期はストレスで髪が抜けそうだったと振り返る。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（56:05〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3365s"]]}, {"cat": "家族", "t": "大統領になりたいと言っても", "b": "ある夜、アメリカ大統領になりたいと話したとき、妻は笑い飛ばさず「あり得る」と受け止めてくれたという。妻はいつもそうして自分の話を否定しないと話す。", "sp": "コーディ・ローデス", "d": "2025-05-28", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-tedOqmtstuo", "src": [["公式YouTube（1:03:28〜）", "https://www.youtube.com/watch?v=tedOqmtstuo&t=3808s"]]}]);
  ARTICLES.push({ id: "wdywta-tedOqmtstuo", d: "2025-05-28", show: "wdywta", who: ["Brandi Rhodes", "Cody Rhodes"], t: "ブランディ・ローデスの回　夫婦で語る、家の中の言い分とリングの思い出", lead: "コーディ・ローデスの番組に出た約69分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Brandi Rhodes", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-tedOqmtstuo").map((x) => [x.t, x.b, x.sp])), open: ["夫婦の掛け合いで話者の切り替わりが追いにくい箇所があり、どちらの発言か確信の持てない話は載せていない。", "他団体時代の試合や筋書きに関わる話（物まね選手との一件、旗揚げ大会での試合内容など）は省いた。", "妻ブランディとの掛け合いが中心のため、話者が追いにくい箇所はどちらの項目にも載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=tedOqmtstuo"]] });
  if (!ROSTER.find((r) => r[1] === "Undertaker")) ROSTER.push(["アンダーテイカー", "Undertaker", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Undertaker"]) PROFILES["Undertaker"] = { lead: "長年守ってきた役柄の幕を上げた迷いと、素顔のマーク・キャラウェイとして生きる今を語った回。仲間との思い出や家族への思い、引退への心境も率直に明かしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Undertaker"]], moves: [], facts: [] };
  if (PROFILES["Undertaker"].lead === "長年守ってきた役柄の幕を上げた迷いと、素顔のマーク・キャラウェイとして生きる今を語った回。仲間との思い出や家族への思い、引退への心境も率直に明かしている。") PROFILES["Undertaker"]._weak = 1;
  PROFILES["Undertaker"].facts.push(...[{"cat": "暮らし", "t": "秘密を明かしたことへの迷い", "b": "長く役柄を守ってきたため、今も話すたびに「これでよかったのか」と自問することがあるという。ファンの多くは思い出話を喜んでくれるが、そっと消えるほうがよかったのではと考える日もあると話す。本音では今もケーフェイブを守る時代が好きで、これは古い人間としての習性だと語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（0:47〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=47s"]]}, {"cat": "暮らし", "t": "普段はほとんど素顔のマーク", "b": "日常の9割は本名のマーク・キャラウェイとして過ごしているという。試合を見ていると、自分ならどうするかと一瞬だけ役柄に戻ることはあるが、それは長続きしないそうだ。有名であることにつきものの注目をことさら求めたことはなく、素顔でいるほうが落ち着くと話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（4:43〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=283s"]]}, {"cat": "好きなもの", "t": "酒好きが高じて自分のワインを出した", "b": "昔からビールが大好きだと話し、いまは自分の名を冠したカベルネのワインも出している。30年やってきたからこそ巡ってきた機会で、ファンにもワイン好きは多いはずだと笑っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（6:23〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=383s"]]}, {"cat": "暮らし", "t": "30年続けて燃え尽きなかった理由", "b": "デビューから30年たっても飽きられず、自分も燃え尽きずにいられたのは、物事がうまくかみ合ってくれたおかげだと話す。毎年270日ほども旅を続ける生活は犠牲も大きいが、情熱を持って毎晩リングに立てたことを幸運に思っているそうだ。動けるなら今でも続けていたいという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（8:49〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=529s"]]}, {"cat": "家族", "t": "子どもたちと過ごせなかった時間", "b": "頂点を維持するには自分を差し出すしかなく、その分、子どもたちと過ごせなかった時間は戻らないと語る。個人的な生活で後悔していることがあり、許しを求めてきたという。いつか子どもたちが、与えられた暮らしに感謝してくれたらと願っていると話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（11:59〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=719s"]]}, {"cat": "暮らし", "t": "休みの日も気が休まらなかった", "b": "家に帰っても荷物を洗って詰め直し、次の出発を待つだけの生活だったという。毎日移動と試合が続くので、数少ない休みにゆっくり映画を見るような過ごし方が分からなかった。誰かが勢いに乗ってくると気になって仕方がなく、頂点を目指さないなら続ける意味がないと考えていたそうだ。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（13:34〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=814s"]]}, {"cat": "リングの話", "t": "王座は持つより追いかけるほうが似合った", "b": "世界王座は客を呼べる人物に渡すべきだという考えで、7度巻いたことは自分の評価の中心ではないと話す。観客の記憶に残っているのは王者としての姿ではなく、追う側のアンダーテイカーだと思うという。王座を長く持つ計画もあったが、そのたびにけがで流れたそうだ。善玉の怪物王者は物語を作りにくいとも語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（16:43〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=1003s"]]}, {"cat": "リングの話", "t": "連勝のきっかけはフレアー戦", "b": "連勝が話題になったのは9連勝のころで、自分で意識して口にしたのはフレアーと戦った年が最初だったという。その年、会社は別の若手との試合を考えていたが、本人がすぐにフレアーを指名した。試合後、フレアーから「自信を取り戻させてくれた」と感謝され、当時は意味が分からなかったと話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（19:56〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=1196s"]]}, {"cat": "体のこと", "t": "脳震とうで初めて自信が揺らいだ", "b": "年間最大の祭典での初黒星の試合で脳震とうを負い、業界で初めて自分が傷つきやすいと感じたという。それまでは、どんなけがでも乗り越えられる気でいたそうだ。自信を失う怖さを知って初めて、フレアーの感謝の意味が分かったと話している。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（24:54〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=1494s"]]}, {"cat": "リングの話", "t": "連勝が止まった日の本音", "b": "連勝を破るなら、本当にそれを必要とする相手にしたかったという。当日の会場で決着の変更を知らされ、会長が自ら楽屋まで来たのを見て内容を察したそうだ。相手が悪いわけではないが、あの相手は十分に出世していたので、数年後の別の若手のほうが適任だったと考えていると語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（26:31〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=1591s"]]}, {"cat": "リングの話", "t": "地獄の金網戦は弟分の登場のために生まれた", "b": "初めての金網の檻の試合は、いちばんの狙いがケインの初登場にあったという。外からの乱入を封じた檻に、ドアを引きちぎったケインが入ってくる場面を作るためだったそうだ。兄弟の対面は今でも印象深く、23年続く長い物語になったと話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（31:54〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=1914s"]]}, {"cat": "リングの話", "t": "王座移動の夜、手にテープを巻いていた", "b": "年間最大の祭典で、当時の王者が約束どおり試合をするか分からず不安だったという。万一のときは自分が出て王座を動かす覚悟で、控え室で手にテープを巻いて待機していたそうだ。当時は相手を好きではなかったが、今は大切な友人だと話す。のちに本人から尋ねられたが、気を遣って否定したという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（45:28〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=2728s"]]}, {"cat": "リングの話", "t": "モントリオール事件の夜に動いた", "b": "あの騒動のとき、会長に話をつけに事務所へ向かう途中、廊下で本人と鉢合わせしたという。そこでブレット・ハートときちんと話すよう迫ったそうだ。のちに会長の事情を聞いて理解はしたが、当時は選手の立場でしか見られなかったと話している。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（51:47〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=3107s"]]}, {"cat": "暮らし", "t": "親友ベアとの出会いと腕時計", "b": "仲間内で「ベア」と呼ぶ親友とは、メンフィスのリングで初めて顔を合わせたという。最初の試合で力任せにやられ、椅子で一撃してから友人になったそうだ。のちに高い腕時計を手にして酔うたびにベアへ譲ろうとし、翌朝には返されることが20回ほどあったと笑って話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（56:36〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=3396s"]]}, {"cat": "暮らし", "t": "仲間うちの法廷で裁判官役", "b": "レスラーたちが開く内輪の裁判は、メンフィスで先輩に教わったのが最初だという。会社に入ってからは大がかりな催しになり、いちばん長く在籍していたため裁判官役を任されることが多かったそうだ。笑いの絶えない場だったが、仲間に身の振り方を気づかせる役目もあったと話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（59:50〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=3590s"]]}, {"cat": "暮らし", "t": "ネイチャー・ボーイとの機内の飲み比べ", "b": "チャーター機でシカゴに戻る途中、リック・フレアーに飲み比べを挑まれたという。2時間ほど前にフレアーが寝てしまったので、座席に寝かせて腕を組ませ、紙ナプキンで牙を作って口にのせたそうだ。1週間ほどして相手から連絡があり、あれは自分の勲章になったと笑っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:06:14〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=3974s"]]}, {"cat": "リングの話", "t": "総合格闘技の試合後に仕掛けた一幕", "b": "元王者が総合格闘技の試合で敗れた直後、あえて近づいて挑発し、話題づくりを狙ったという。相手のほうから自分の近くを通ったので、うまくいかなくてもそのまま仕掛けると決めたそうだ。団体に戻ってくる可能性を考え、真っ先に接触しておきたかったと語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:09:44〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=4184s"]]}, {"cat": "リングの話", "t": "金網の上で幽体離脱のような感覚", "b": "金網の上からミック・フォーリーを投げ落とした瞬間、自分が立つ姿と宙を飛ぶ相手を外から見ているようだったという。この場面は本来の予定にはなく、危ないので気乗りもしていなかったそうだ。足首を骨折したまま試合に臨み、屋根の一部が崩れる直前にとっさに足場へ踏み替えたため、相手の上に落ちずに済んだと話す。倒れた相手が動くのを見たときは、これほどうれしいことはなかったという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:13:48〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=4428s"]]}, {"cat": "体のこと", "t": "入場の炎で腕に大やけど", "b": "王者として登場した夜、入場の花火が近すぎて腕から胸にかけてやけどを負ったという。数週間前に花火が近いと担当者へ伝えていたのに直されなかったそうだ。直前に長袖の上着へ替え、頭から水をかぶっていたおかげで被害が小さく済んだと話す。試合は最後に入る形で20分ほど檻の中で待てたので、気持ちを落ち着かせられたという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:25:04〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=5104s"]]}, {"cat": "リングに来るまで", "t": "ダラスでの初試合と先輩の洗礼", "b": "ダラスでデビューしたころは、音楽もない入場で、後にポール・ベアラーとなる人物がつくことになったという。初戦の相手は強豪のブロディで、手ひどくやられたのが今でも誇らしい思い出だそうだ。のちに大物から日本の大会のタッグ相手に誘われたことと並べ、業界の外の人には分かりにくい大事な出来事だと話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:31:43〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=5503s"]]}, {"cat": "リングの話", "t": "葬儀の知識を持つ付き人との出会い", "b": "後の付き人が、面接で葬儀に関する学位を持っていると話して部屋が沸いたという。これは出会うべくして出会ったとしか思えず、死や埋葬についての知識がキャラクターづくりを大きく助けたそうだ。二人の話し方の対比が観客を引き込み、役柄の成長に欠かせない存在だったと語っている。楽屋では冗談好きで、悪ふざけを仕掛けるのが好きな人だったともいう。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:33:27〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=5607s"]]}, {"cat": "暮らし", "t": "記録映像を撮り始めた理由", "b": "ドキュメンタリーは、最後と思った試合に備えて舞台裏の映像を残したくて始めたという。結局その試合に納得がいかず、もう一度やり直すと決めたため、撮影は3年以上に及んだそうだ。常に守る姿勢だったので、カメラに素顔を見せるまで時間がかかったと話す。誰にも同情されたくはないが、この仕事に何が必要かは知ってほしいという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:36:49〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=5809s"]]}, {"cat": "リングの話", "t": "墓地での試合と最後の相手", "b": "最後に戦いたかった相手から、番組を見て電話で誘われ、迷った末に引き受けたという。本来は大きなスタジアムのリングで行う予定が、感染症の流行で映像作品の形になったそうだ。相手が妻にまで踏み込んだ筋書きで、役柄と素顔のマークが一つになる試合だったと話す。撮影は何時間にも及び、体が冷えて動かしにくかったという。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:41:49〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=6109s"]]}, {"cat": "家族", "t": "撮影前日に届いた兄の訃報", "b": "その試合の撮影前日、兄が亡くなったという。感染症の影響で現地を離れられず、ほかのきょうだいに母のそばにいてもらうよう頼んでから、撮影を待つしかなかったそうだ。つらい数日だったと語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:46:38〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=6398s"]]}, {"cat": "体のこと", "t": "コロナ前はいちばん仕上がっていた", "b": "その試合に向けた準備は、例年より早く進んでいたという。体重も心肺機能も狙いどおりで、本来の形の試合に出られると胸を躍らせていたそうだ。ところが感染症で施設が使えず、数週間後には体の状態が大きく落ちたという。伝統的な試合ができなかった心残りはあると話す。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:51:30〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=6690s"]]}, {"cat": "体のこと", "t": "体の限界を受け入れて引退した", "b": "股関節やけがの蓄積で、人が期待する水準でリングに立てないと自覚したという。名前の力だけで入場して技を一つ決めれば、あと数年は続けられるかもしれないが、それは自分ではないと話す。後輩たちに敬意があるから、手を抜いた試合はしたくないそうだ。生まれて初めて、リングがなくても大丈夫だと思えており、静かに受け入れていると語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:53:10〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=6790s"]]}, {"cat": "暮らし", "t": "仲間の信頼がいちばんの誇り", "b": "キャリアには満足していて、誰の裏切りもせず仕事をしてきたことを誇りに思うという。何よりも、同業の仲間から敬意を持たれていることが大きいそうだ。個人的な確執があっても、会社のためになることを優先してきたと話す。体が拒む夜でも、観客の歓声を聞けば乗り切れたと感謝している。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-qqrEgBK_TEE", "src": [["番組のYouTube（1:56:26〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=6986s"]]}]);
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "ショーン・マイケルズは小さくても説得力があった", "b": "体の小さなショーンは、チャンスを逃さない鋭さと、殴り合いになったときの説得力が抜群だったと、アンダーテイカーが話している。大きな相手に対して必死さを見せる物語づくりも理解しており、ほうきとでも名勝負にできるほどの才能だとたたえている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、アンダーテイカーの話（字幕を全文確認）", "src": [["番組のYouTube（34:22〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=2062s"]], "by": "第三者の話"});
  if (PROFILES["Kane"]) PROFILES["Kane"].facts.push({"cat": "暮らし", "t": "ケインとの出会いは地方団体の試合だった", "b": "ケインがまだ別の名前で地方団体にいたころ、呼ばれて試合をして、これは本社に上げるべき逸材だと思ったと、アンダーテイカーが話している。体つきも動きも自分に近く、兄弟という設定は観客が信じやすかったそうだ。ケインは本当に一流の人物だとも語っている。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、アンダーテイカーの話（字幕を全文確認）", "src": [["番組のYouTube（40:44〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=2444s"]], "by": "第三者の話"});
  if (PROFILES["Mick Foley"]) PROFILES["Mick Foley"].facts.push({"cat": "暮らし", "t": "ミック・フォーリーは自分の持ち味を知っていた", "b": "ミックは自分がショーン・マイケルズのようなタイプではないと理解し、別の形で記憶に残る試合を作ろうとしたと、アンダーテイカーが話している。違う魅せ方だからどちらが上ということではなく、とても賢い人だと評している。", "sp": "アンダーテイカー", "d": "2025-05-31", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、アンダーテイカーの話（字幕を全文確認）", "src": [["番組のYouTube（1:20:58〜）", "https://www.youtube.com/watch?v=qqrEgBK_TEE&t=4858s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-qqrEgBK_TEE", d: "2025-05-31", show: "ext", who: ["Undertaker"], t: "アンダーテイカーの回　幕を上げた今と、仲間・家族への思い", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約121分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Undertaker"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-qqrEgBK_TEE").map((x) => [x.t, x.b, x.sp])), open: ["字幕に話者名がなく、聞き手のストーン・コールド・スティーブ・オースティン本人の話と取り違えそうな箇所は載せていない。", "仲間の名前（亡くなった友人など）や仲間うちのあだ名は、自動字幕で崩れていて確信が持てないため、「ベア」以外は書いていない。", "ほかに、レッスルマニア30の前後の細かい話、番組の宣伝や記念ベルトの話は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=qqrEgBK_TEE"]] });
