  if (!PROFILES["Damian Priest"]) PROFILES["Damian Priest"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Damian%20Priest"]], moves: [], facts: [] };
  if (PROFILES["Damian Priest"].lead === "") PROFILES["Damian Priest"]._weak = 1;
  PROFILES["Damian Priest"].facts.push(...[{"cat": "リングの話", "t": "ロッキングチェア事件の裏側", "b": "コーディとの試合前、「後ろから椅子で殴る場面をやりたい」と言われたが、何の話か全く分からず、あとで古い映像を調べて知ったという。用意されたのは小さな折りたたみ椅子ではなく、巨大なロッキングチェアだった。壊れやすいよう細工したが、補強する側を切ってしまったらしく、3回殴られても壊れず、痛くて振り返ってしまったとダミアン・プリーストは話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（4:09〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=249s"]]}, {"cat": "リングの話", "t": "生活できる初契約でのビッグマッチ", "b": "その試合の頃のダミアン・プリーストは、WWEに何度か断られた直後だった。リング・オブ・オナーと結んだのは、ようやく食料品を普通に買えるようになる最初の1年契約だったという。だから新契約の大一番であるコーディ戦が、自分にはとても大事な試合に思えたと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（5:46〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=346s"]]}, {"cat": "リングの話", "t": "初めてのウォーゲームズ", "b": "ジャッジメント・デイとコーディの抗争は長く続き、その集大成がウォーゲームズだった。ダミアン・プリーストにとっても初めてのウォーゲームズだったと話している。試合ではコーディにフォールを奪われたそうで、「RKOの一発で終わりだと思ったのに、まだ続きがあった」と笑いながら振り返る。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（21:49〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1309s"]]}, {"cat": "リングの話", "t": "レイザー・ラモンに憧れた少年時代", "b": "子どもの頃、レイザー・ラモンを本物のラテン系だと思い込んで見ていて、「自分たちを代表する存在」だと感じたという。強気な振る舞い、決め台詞、サーファーのような歩き方、髪の整え方まで、すべてが最高にかっこよかったそうだ。元ネタの映画『スカーフェイス』も好きで、ラモンがWCWに移ってもファンであり続けたと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（55:29〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3329s"]]}, {"cat": "リングの話", "t": "負け方を教えてくれたクリック", "b": "スコット・ホールたちは、勝つときは容赦なく相手を倒す一方、負けるときは文句を言わずに相手を大きく見せる名人だったという。ダミアン・プリーストは、自分が負ける場面ではその姿を手本にしていると話す。「あれが負け方の見本だ。言い訳せず、楽な逃げ道を探さずにやり切るのがいい」という考えだそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（57:58〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3478s"]]}, {"cat": "リングの話", "t": "ホールに技の使用を直談判", "b": "育成施設時代、友人の紹介でスコット・ホールと長く話す機会を得たという。思い切って「あなたの動きを取り入れていいか」と尋ね、サーファーウォークの名前を初めて知った。決めポーズの踊りはリズムが合わず諦めたが、レイザーズ・エッジは名前ごと使いたいと頼み、ホールに認めてもらったと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（58:47〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3527s"]]}, {"cat": "リングの話", "t": "血のしずくのロゴも許可をもらった", "b": "ギアにも使っている血のしずくのデザインについて、ホールに許可を求めたときの話も語っている。ホールがケビン・ナッシュを呼んで「俺たちのロゴを使いたいらしい」とからかうので、商売に厳しい人だから怒られると身構えたそうだ。ところがナッシュは快く承諾し、ホールも「自分たちを思い出させてかっこよく見せてくれるなら歓迎だ」と言ってくれたという。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:00:23〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3623s"]]}, {"cat": "リングの話", "t": "育成施設の指導者テリー・テイラー", "b": "育成施設で教わったテリー・テイラーとは、最初は衝突して好きになれなかったという。あとから、自分に良くなってほしいから厳しいのだと気づいたと話す。今ではとても仲が良く、その指導に感謝しているそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:04:25〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3865s"]]}, {"cat": "リングの話", "t": "体調最悪のコーディとケージ戦", "b": "コーディが食中毒で青ざめたまま立った、ツアー中のケージ戦について、ダミアン・プリースト側の思いも語っている。傷つけたくないという重圧が大きく、できるだけ相手が楽になる展開にしようと考えたという。それでも自分たちが興行の責任を負う立場だから、やるべきことはやろうと思っていたそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:08:20〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=4100s"]]}, {"cat": "リングの話", "t": "静かな会場を巻き返したサウジの試合", "b": "サウジアラビアでのコーディ戦の前、会場の反応が静かで、幹部から「客が乗らないなら早めに切り上げていい」と言われたという。その言葉には、ふたりとも内心あまりいい気はしなかったそうだ。そこで事前に打ち合わせることなく、短い時間で全力の試合をして客席を引き戻し、戻ったら担当プロデューサーともども称賛されたと誇らしげに話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:09:51〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=4191s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Damian Priest")) ROSTER.push(["ダミアン・プリースト", "Damian Priest", "lg", "元世界ヘビー級王者", "", "", ""]);
  if (!PROFILES["Damian Priest"]) PROFILES["Damian Priest"] = { lead: "ニュージャージーで車上生活を送り、体重400ポンドまで怠けた時期もあったという。クラブ店長の職を捨てたその日から体を作り直し、今もみんなで楽しむ生き方は変わらないと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Damian%20Priest"]], moves: [], facts: [] };
  if (PROFILES["Damian Priest"]._weak) { PROFILES["Damian Priest"].lead = "ニュージャージーで車上生活を送り、体重400ポンドまで怠けた時期もあったという。クラブ店長の職を捨てたその日から体を作り直し、今もみんなで楽しむ生き方は変わらないと話す。"; delete PROFILES["Damian Priest"]._weak; }
  PROFILES["Damian Priest"].facts.push(...[{"cat": "リングに来るまで", "t": "WWEに何度も落ちた末のROH契約", "b": "この頃までにWWEには何度か不採用になっていたという。ROHと結んだ最初の1年契約は、ようやく食料品を普通に買えるようになった額で、とてもうれしかったそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（5:46〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=346s"]]}, {"cat": "暮らし", "t": "車上生活で、装備を盗まれ一時引退", "b": "ニュージャージーでインディーに出ていた頃は家がなく、車で寝泊まりしたり、知り合いの家やパーティー先で寝たりする生活を数年続けていたという。車に置いていたリング用の装備を盗まれ、買い直すお金がなくてプロレスを一度やめたそうだ。仕事を得て装備と部屋を用意できた約1年後に復帰したと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（9:43〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=583s"]]}, {"cat": "暮らし", "t": "変わったのは腕時計くらい", "b": "今の暮らしぶりはかなりにぎやかだと笑う。世界王座を獲った直後に買った腕時計のようなものは手に入れたが、生き方や人との接し方は昔から変わっておらず、変え方も分からないという。自分も周りもみんなで楽しく過ごすことが人生でいちばん好きなことで、余裕ができた今はそれを仲間と分かち合いたいと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（11:21〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=681s"]]}, {"cat": "好きなもの", "t": "タトゥーは今も入れるが、痛みはもう…", "b": "リア・リプリーとは今も一緒にタトゥーを入れに行くという。ただ毎回「なんでまた入れることにしたんだろう」と思うそうで、もう痛みを楽しむ年ではないと笑う。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（19:24〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1164s"]]}, {"cat": "リングに来るまで", "t": "親友QT・マーシャルとはモンスター・ファクトリーで", "b": "QT・マーシャルとは、ニュージャージーの道場モンスター・ファクトリーで2004年ごろに出会ったという。自分が入門して1年ほどたち指導も手伝っていた頃にQTが来て、のちに大人同士として意気投合したそうだ。遠慮なく本音を言うところが好きで、以来の親友だと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（30:35〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1835s"]]}, {"cat": "リングに来るまで", "t": "借金して入門、低く硬いリングで基礎", "b": "道場の入門費は人から借りて工面したという。創設者ラリー・シャープは修業の初期に病気で離れ、元審判のジム・モリノーとエド・アトラスに教わったそうだ。床に近い硬いボクシング用リングで、ほとんど地面に落ちるような受け身を繰り返して基礎を覚えたと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（33:04〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1984s"]]}, {"cat": "体のこと", "t": "体重約400ポンドの怠けた時期", "b": "ドキュメンタリーでも描かれた時期は、ひどく体型が崩れ、言い訳できないほど怠けていたと認める。体重は約400ポンド（約180キロ）。周りから「大きいし才能があるから大丈夫」と言われ続け、努力しなくていいと思い込んでしまったという。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（34:38〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2078s"]]}, {"cat": "暮らし", "t": "アトランティックシティでクラブの店長に", "b": "アトランティックシティの成人向けクラブで店長をしていたという。同じ建物のボードウォーク沿いのペントハウスに住ませてもらい、車も支給されたそうだ。かつてアル・カポネが住んでいた部屋だといい、この仕事でようやく装備も買い直せたと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（35:27〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2127s"]]}, {"cat": "リングに来るまで", "t": "「プロレスをやめろ」に即退職", "b": "ある日オーナーから、昇進と昇給の代わりに週末のプロレスをやめるよう言われたという。ちょうど自分が不幸で自滅的だと気づいていた時期で、迷わずその場で2週間後に辞めると告げたそうだ。オーナーとはそれきり一度も話していないが、人生を変えてくれたと振り返る。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（36:59〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2219s"]]}, {"cat": "体のこと", "t": "その日からジャンク断ちとジム通い", "b": "退職を決めたその日にジャンクフードをやめ、いろいろなものを断ち、ジムに入会して以来振り返らなかったという。聞きたいことだけ言う人やすり寄る人と距離を置いたら、減量が進み、エキストラの仕事やトライアウト、ROHからの声がかかり始めたそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（37:49〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2269s"]]}, {"cat": "家族", "t": "どん底で母に電話した夜", "b": "退職の1週間ほど前、ひどい状態で母親に電話したことがあると、初めて人前で明かした。何を話したかは覚えていないが、母は「全部忘れて帰ってきなさい」と言い、とても心配していたという。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（39:20〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2360s"]]}, {"cat": "好きなもの", "t": "ヤンキースのジャッジ、オースティンと nWo のシャツ", "b": "野球はヤンキースのファン。思い入れのあるユニフォームやグッズの4選では、アーロン・ジャッジのユニフォームを真っ先に挙げた。プロレスものでは、ストーン・コールドの元祖「オースティン3:16」シャツと、元祖 nWo シャツを選んでいる。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（40:56〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2456s"]]}, {"cat": "体のこと", "t": "飛行機は今も苦手", "b": "飛行機は単純に嫌いだという。初めて日本へ遠征するときは怖くてたまらず、同じく飛行機嫌いだったアダム・コールから「長距離便に乗れば慣れる」と言われ、実際そのとおりだったそうだ。今も離陸のときはヘッドホンをつけて気をそらさないと落ち着かず、窓の外を見たり黙って座っていたりはできないと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（46:25〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2785s"]]}, {"cat": "暮らし", "t": "初めて飛行機の前方席を手に入れた", "b": "昨年の契約更新で、初めて前方席に座れる条件を付けてもらったという。大柄でエコノミー席に体が収まらないのに、それまで頼み方も分からなかったそうだ。最初に使ったオーストラリア行きでは、アンダーテイカーやトリプルHと同じ前方席になったが、騒ぎすぎてたしなめられ、結局ほとんど後方で過ごしたと笑う。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（49:41〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2981s"]]}, {"cat": "好きなもの", "t": "チャーター便でスーパーヒーローに変身", "b": "仲間とのチャーター便では、少しお酒が入ると衣装に着替え、スーパーヒーローになりきるという。これまで本格的に扮したのはアクアマン（2回）とバットマン。昼寝から起きた人がぎょっとするのが面白いそうで、アクアマン姿を見たジミー・ウーソには、ひと言も口をきかずに不機嫌にされたという。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（50:29〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3029s"]]}, {"cat": "好きなもの", "t": "子どもの頃のヒーローはレイザー・ラモン", "b": "最初に夢中になったのはレイザー・ラモンで、子どもの頃は本当にラテン系だと思い込み、自分たちを代表する存在だと感じていたという。サビオ・ベガも大好きだった。プロレスラーになるのが夢だったわけではなく、WCWはまったく観ていなかったが、スティングは知っていたそうだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（55:29〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3329s"]]}, {"cat": "好きなもの", "t": "好きな映画は『スカーフェイス』と『クロウ』", "b": "レイザー・ラモンのモデルになった映画『スカーフェイス』が好きだという。スティングを好きになったのも、大好きな映画『クロウ』をもとにしたキャラクターだったからだと話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（56:17〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3377s"]]}, {"cat": "リングに来るまで", "t": "スコット・ホールに直接許しをもらった", "b": "育成時代、親しかったショーン・ウォルトマンの紹介でスコット・ホールと話せるようになり、緊張しながら何度も語り合ったという。サーファー風の歩き方やレイザーズ・エッジ、ロゴのしたたるデザインを使ってよいか頼むと、ホールもケビン・ナッシュも快く認めてくれたそうだ。チャチャチャの動きだけはリズム感がなくてできないと笑う。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（58:47〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3527s"]]}, {"cat": "リングに来るまで", "t": "最初はぶつかった恩師テリー・テイラー", "b": "育成時代のコーチ、テリー・テイラーとは最初は衝突し、好きではなかったという。やがて自分をうまくしたいから厳しいのだと分かり、今では大好きで感謝していると話す。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:04:25〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3865s"]]}, {"cat": "暮らし", "t": "家じゅうに弓矢を置いている", "b": "ゾンビでもエイリアンでも来いと備えていて、家のあちこちに弓と矢を置いているという。腕前もなかなかだそうだ。一緒に戦う仲間には、コーディ、リア・リプリー、シェイマス、ランディ・オートンを選んだ。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:13:00〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=4380s"]]}]);
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "育成施設の「お酒なし」パーティーで意気投合", "b": "親友になったのは育成施設のホリデーパーティーで、アルコールなしの会だと知らずに来たプリーストが場を盛り上げ、音楽の話で打ち解けたのが始まりだという。リアはプリーストのそばだと安心できると感じ、すぐ親友になったと、ダミアン・プリーストが話している。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で、ダミアン・プリーストの話（公式字幕を全文確認）", "src": [["公式YouTube（13:01〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=781s"]], "by": "第三者の話"});
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "家族と離れて地球の反対側へ来た覚悟", "b": "故郷オーストラリアを離れ、家族と会えない寂しさを抱えながら夢を追ってきた姿に刺激を受けているという。型にはまらない見た目で自分らしさを貫き、出会った頃から誰にでも思いやりのある人柄が変わらないところを、ずっと尊敬していると、ダミアン・プリーストが話している。", "sp": "ダミアン・プリースト", "d": "2025-06-11", "how": "ステファニーの番組で、ダミアン・プリーストの話（公式字幕を全文確認）", "src": [["公式YouTube（18:36〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1116s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "好きなもの", "t": "オフの夜はフィギュア開封動画", "b": "遊びに出ていない夜はツアーバスにこもって、アクションフィギュアの新作紹介のような動画をYouTubeで観ていることが多いという。自分でも「あまり華やかではない」と笑う。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（17:03〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1023s"]]}, {"cat": "体のこと", "t": "減量中は人が食べるのを見て満たされる", "b": "食事制限は「食べるか断つか」の極端なやり方だという。減量中は、自分が食べられないスウェーデッシュ・フィッシュやピザを人が食べているのを見ると本気で満たされるそうで、自宅にお菓子のかごを置き、客にピザを頼んで自分はステーキを食べていたのも、だますつもりではなかったと話す。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（28:07〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1687s"]]}, {"cat": "家族", "t": "QT・マーシャルは子どもの名付け親", "b": "QT・マーシャルは自分にとって親友に最も近い存在で、子どもの名付け親（ゴッドファーザー）でもあるという。家族みんなが彼を慕っていて、家にはいつも彼のためにリーセスを用意しているそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（28:57〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=1737s"]]}, {"cat": "暮らし", "t": "敵には構わず、成功することに集中", "b": "自分や妻ブランディを傷つけた人のことはほとんど気にせず、成功することだけを考えてきたという。振り返ると、そうした相手はたいてい自滅していたそうで、敵の多くは自分ではなく因果応報が片付けたと話す。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（43:13〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=2593s"]]}, {"cat": "家族", "t": "父ダスティにならって新人のブーツを買う", "b": "父ダスティ・ローデスは、若き日のスコット・ホールに初めてのリングシューズを買ってあげたという。数か月後、ホールは300ドルを返しに来たそうだ。自分もいつの間にか、人の最初のブーツを買ってあげることが多いと話す。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:01:09〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3669s"]]}, {"cat": "体のこと", "t": "体調不良を隠してツアーを乗り切った", "b": "けがは少なく、胸筋のけがは例外的なものだという。体調が悪くても人に言いたくない性分で、冬のツアー中に食中毒になったときもバスの床で寝込み、高熱と震えのまま数夜を戦い抜いたそうだ。そのとき気づかってくれたプリーストに、番組で改めて礼を言っている。", "sp": "コーディ・ローデス", "d": "2025-06-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-mlIkdiJfEOU", "src": [["公式YouTube（1:05:15〜）", "https://www.youtube.com/watch?v=mlIkdiJfEOU&t=3915s"]]}]);
  ARTICLES.push({ id: "wys-mlIkdiJfEOU", d: "2025-06-11", show: "wys", who: ["Damian Priest", "Cody Rhodes"], t: "ダミアン・プリーストの回　車上生活と400ポンドからの再起、リア・リプリーとの友情", lead: "ステファニー・マクマホンの番組に出た約76分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Damian Priest", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-mlIkdiJfEOU").map((x) => [x.t, x.b, x.sp])), open: ["序盤のROH時代の試合やバレットクラブの話、終盤の大会での試合の裏話は、筋書きにかかわるため省いた。", "字幕の話者表記が途中で入れ替わるため、どちらの発言か追い切れなかったやりとり（機内の飲み物の件など）は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=mlIkdiJfEOU"]] });
  if (!ROSTER.find((r) => r[1] === "Nick Khan")) ROSTER.push(["ニック・カーン", "Nick Khan", "lg", "WWEの社長", "", "", ""]);
  if (!PROFILES["Nick Khan"]) PROFILES["Nick Khan"] = { lead: "WWEの社長として知られる経営者。苦学した若い日々や、家族を最優先にする暮らしぶり、決断と責任についての考え方を、飾らず語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nick%20Khan"]], moves: [], facts: [] };
  if (PROFILES["Nick Khan"]._weak) { PROFILES["Nick Khan"].lead = "WWEの社長として知られる経営者。苦学した若い日々や、家族を最優先にする暮らしぶり、決断と責任についての考え方を、飾らず語った。"; delete PROFILES["Nick Khan"]._weak; }
  PROFILES["Nick Khan"].facts.push(...[{"cat": "家族", "t": "6年生で「最も成功しそうな人」に選ばれた", "b": "小学6年生のとき、同級生から最も成功しそうな人に選ばれたという。本人は、両親から「子どもらしい子ではなかった」と言われると話す。引っ越しが多かったが、行く先々で友人を見つけてきたそうだ。子ども向けのものより、プロレスやスポーツ、芸能の仕事の世界に興味があったという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（7:28〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=448s"]]}, {"cat": "好きなもの", "t": "小説は苦手、でもドラマは好き", "b": "文字で読む小説は今も好きではないと話す。ドラゴンが人をさらうような作り話は映画でも苦手だという。それでも人気ドラマ『ゲーム・オブ・スローンズ』は、ドラゴンが背景にとどまるところがよく、すばらしいテレビ作品だと語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（8:18〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=498s"]]}, {"cat": "体のこと", "t": "2か月前にコーヒーをやめた", "b": "睡眠に悪影響が出ていたため、2か月ほど前にコーヒーをやめたと話す。もともとあまり長く眠らず、いまの睡眠は4〜5時間ほどで十分だという。自分で言うと自慢のようだが、と笑いながら語っている。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（9:56〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=596s"]]}, {"cat": "家族", "t": "夕食で新聞記事を語り合う家で育った", "b": "両親は移民で、自分と姉のために多くの時間を注いでくれたという。子どものころは新聞の一面から好きな記事を選び、夕食で話し合う決まりだった。おかげで年上の人と話が合うようになり、仕事の面でも役立ったと話す。いまは自分も妻と子どもたちに同じことをしており、選挙の日は家族で投票所に行くのが恒例だという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（19:46〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=1186s"]]}, {"cat": "家族", "t": "小1のとき、姉が殴り込んで助けてくれた", "b": "小学1年生のとき、5年生の男子数人に小突かれていたところへ、3年生だった姉が現れて相手を殴ったという。あの場面は昨日のことのように覚えていると話す。きょうだいは理由を問わず、まず守る。叱るのは家の中で後にする。この教えを姉から学び、自分の子どもにも伝えているそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（22:20〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=1340s"]]}, {"cat": "暮らし", "t": "「一緒にいるなら、とことん味方」が信条", "b": "元NBA選手が語った「あなたと一緒なら、とことん一緒だ」という言葉を、自分の生き方に重ねている。友人が500人に嫌われる部屋でも、一緒に入った相手の側に立つのが当たり前だという。友人が職を失ったときも、自分に対してどうだったかで人を見ると話す。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（28:08〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=1688s"]]}, {"cat": "リングに来るまで", "t": "法科大学院の最終年、ローンが通らなかった", "b": "法科大学院の3年目に学費ローンを断られ、卒業できないと思ったという。頼れる裕福な親戚はいなかった。そこで当時の恋人に電話すると、連帯保証人になってくれた。その人が、いまの妻だと話す。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（30:39〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=1839s"]]}, {"cat": "リングに来るまで", "t": "ゲーム番組に出て、司法試験の勉強時間を買った", "b": "フルタイムで働きながら学んでいたが、試験に一度で受かるには2か月仕事を休んで勉強する必要があったという。そこでクイズ番組『ホイール・オブ・フォーチュン』にはがきを送り、オーディションに呼ばれた。会場には高齢の応募者が多く、自分は有利だったそうだ。出場して賞金を得て、その資金で試験対策の講座を受け、無事に合格したと語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（32:13〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=1933s"]]}, {"cat": "暮らし", "t": "趣味はなく、関心は「家族」と「仕事」の二つだけ", "b": "仕事と、キャリアを築くことの違いについて、キャリアなら毎日夢中でいなければ務まらないと話す。自分の関心は、第一が家族と大切な人、第二が仕事の二つだけだという。週末にボートで遊ぶようなこともなく、家族や大切な人と一緒でないとあまり出かけないそうだ。読書は多いが、遊びのためではないと話す。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（34:37〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2077s"]]}, {"cat": "リングの話", "t": "失敗は自分の責任、成功は皆のもの", "b": "経営陣には、うまくいかなければ全責任は自分にあり、成功すれば皆の手柄だと伝えているという。問題を持ってきてくれれば自分たちの問題として一緒に解決するが、隠して自分で片づけようとすれば立場が危うくなると話す。こうすると、社員が失敗を早く打ち明けやすくなるそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（38:52〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2332s"]]}, {"cat": "リングの話", "t": "決断は速く、間違えたらすぐ直す", "b": "良さそうだと感じたらすぐ決めるタイプで、自宅を買ったときも即決だったと話す。仕事でもミスは日常的に起き、間違えたら直せばいいという考えだという。トリプルHとは互いに「あれは違ったかも」と言い合える関係だそうだ。方針を変えるときは幹部会議で伝え、全員で同じ方向に進むようにしていると語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（40:29〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2429s"]]}, {"cat": "暮らし", "t": "過去を蒸し返さない、子どもの「今日」を聞く", "b": "仕事でも妻や子どもとの間でも、一度話し合った問題は二度と蒸し返さないと話す。人は過去に生きる人、今に生きる人、未来を気にする人に分かれ、自分は未来を気にするタイプだという。ただ、家では意識して今に付き合うようにしているそうだ。13歳の娘と9歳の息子が聞いてほしいのは今日の出来事だから、と語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（41:14〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2474s"]]}, {"cat": "暮らし", "t": "お金を貸しても、返済は期待しない", "b": "自分が苦しかった時期、励ましてくれる人はいても、実際にお金を貸してくれる人はいなかったという。その経験から、余裕ができたら力になろうと決めていたと話す。貸した相手はたいてい若い人で、利子はなし、誰にも言わなくていいと伝えるそうだ。返せるのに返さなければ覚えておく、とだけ添え、いまのところ全員が返してくれたという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（46:15〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2775s"]]}, {"cat": "リングの話", "t": "「人ではなく椅子が評価されている」と心得る", "b": "いまの席に座っているから周りが親切にしてくれて、電話にも早く出てもらえると思っているという。自分個人のおかげではないと考えるのが大事だと話す。大きな役職に就いた人はそれを忘れがちで、席を離れたときに痛感することになるそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（49:30〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=2970s"]]}, {"cat": "暮らし", "t": "ネットの評判は気にしない、クラブにも入らない", "b": "SNSやネット検索で自分の名前を調べたことは一度もないと話す。良い評判も悪い評判も、自分には関係がないからだという。カントリークラブなどの会員にならないのも、周りの噂を気にしたくないからだそうだ。一日は夜中の0時でリセットされるので、うまくいかない日があっても翌朝また進めばいいと語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（54:38〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3278s"]]}, {"cat": "リングの話", "t": "一部の批判のためでなく、広い観客のために作る", "b": "トリプルHも同じ考えだと前置きしたうえで、制作チームや脚本陣には、ごく一部の批判する人に向けて作らないよう伝えていると話す。観客全体に向けて良い作品を出せば、収入もファンも結果もついてくるという考えだ。批評は気にせず前に進むよう勧めているそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（56:14〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3374s"]]}, {"cat": "リングに来るまで", "t": "『ザ・ソプラノズ』がメディアの道への入口", "b": "法科大学院を終えるころ、友人宅で見た人気ドラマ『ザ・ソプラノズ』のクレジットを調べて、制作者や主演俳優の経歴をたどったのがきっかけだという。そこからメディアの仕事に関心が向いたと話す。弁護士から代理人への転身には不安もあったが、挑む価値のある賭けだったと振り返る。貧しい家の出身なら、失敗しても元の場所に戻るだけで、冒険しやすいとも語っている。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（57:52〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3472s"]]}, {"cat": "好きなもの", "t": "好きな映画と、スマホに保存する名場面", "b": "映画『トゥルー・ロマンス』は大好きな一本で、冒頭のゲイリー・オールドマンの演技は自分の中で上位に入るキャラクターだという。映画からは仕事の考え方も学んだと話す。気に入った映画の場面や名言、記事はスマホに保存し、ときどき見返すそうだ。ドラマの少女が「死の神には何と言う？　きょうはまだ」と返す場面は、つらい日の励みになっているという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（58:39〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3519s"]]}, {"cat": "暮らし", "t": "今も紙の新聞を購読、読むのは早朝", "b": "今も紙の新聞を購読していて、休暇中も部屋に届けてほしいと頼むので周りを困らせていると笑う。頭にある情報の多くは、読む時間のない人が読んでいない公開情報だという。読むのは家族がまだ起きない早朝の静かな時間だと話す。読書は他人の失敗について書かれたものを好み、過去を知れば未来も予測しやすくなると考えている。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:01:49〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3709s"]]}, {"cat": "リングに来るまで", "t": "ハワイで育ち、リングの外から憧れた", "b": "ラスベガスで生まれ、ロサンゼルス、ホノルルと移り、またラスベガスで高校と大学に通ったと話す。ホノルルでは地元のプロレス興行に通い、のちに大スターとなる同世代の少年とも観客席で出会ったそうだ。祖母がリングに関わっているという話を、当時は子ども心に本当かと思ったという。外から眺める側ではなく、中に入る側になりたいと思ったのがその頃だったと語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:05:53〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3953s"]]}, {"cat": "リングに来るまで", "t": "ボクサーの代理人時代、居場所を探して海外へ", "b": "代理人としてボクサーのマニー・パッキャオとジェームス・トニーを担当していたと話す。携帯の通話が前払い式の国で連絡がつかず、ロサンゼルスからフィリピンまで飛んで本人を探したこともあるという。そのときの苦労に比べれば、あとで担当した「気難しい」と言われる放送関係者は簡単に思えたそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:12:25〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4345s"]]}, {"cat": "リングの話", "t": "どんな大物相手でも率直さと敬意", "b": "億万長者にも、人目のない場で礼を欠かさなければ、何でも言えると話す。過去に担当した気難しい相手に比べれば、ヴィンス・マクマホンも手がかかる顧客ではなかったと笑いながら振り返っている。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:14:01〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4441s"]]}, {"cat": "リングに来るまで", "t": "悔しさを力に、人の2倍動いて追いつく", "b": "大統領には、父が大成功した人か、不在だった人が多いという雑誌記事の話をして、「自分は何者でもない者ではない」と示したい気持ちが力になると語る。自分も外側から来た人間で、買えないものや助けられない人がいることに腹が立ったという。悲しみより怒りのほうが向き合いやすい性格だと話す。出発点が違う相手に追いつくには、働く量で上回るしかないと考えているそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:14:49〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4489s"]]}, {"cat": "リングに来るまで", "t": "大学は長い青春、働き続けた学生時代", "b": "地元の大学では政治学を専攻したが、特別な価値は感じなかったと話す。学部は5年かけて、フルタイムで働いていたという。店ではテーブルの片付け係から給仕長になり、「どんな仕事も自分より下ではない、だから手の届かない仕事もない」という考えを持つようになった。休みなく働けば稼ぎも増えると気づき、その習慣が今のキャリアにもつながっているそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:16:24〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4584s"]]}, {"cat": "暮らし", "t": "法科大学院1年目は、食費を切り詰める日々", "b": "法科大学院の1年目は勉強に集中するため仕事を少し減らし、食費を極限まで抑えていたという。西海岸の安売りスーパーで、袋入りのシリアルや牛乳、米、麺類を買っていたと話す。パンはその日のうちに食べないといけないほどだったそうだ。つらくはなかったが、二度とその立場に戻りたくないと思ったという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:21:07〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4867s"]]}, {"cat": "家族", "t": "子どもを持ったのは37歳、備えてから", "b": "妻と子どもを持ったのは自分が37歳のときで、自分が強く望んで遅らせたと話す。万一自分に何かあっても、子どもたちが今と同じ暮らしを続けられるだけの蓄えを先に作りたかったからだという。自分は子どものころ転居が多かったので、子どもに同じ思いをさせたくなかったとも語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:22:46〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=4966s"]]}, {"cat": "リングの話", "t": "「WWEは人生、人生はWWE」という見方", "b": "世界中の人に響くのは、裏切りや失望、だまし討ちもあれば、感動的な結末もあるという、人生そのものを描いているからだと話す。日常の出来事を悪役の振る舞いになぞらえて語るほど、人生とプロレスは重なって見えるという。プロレスを人生になぞらえる考え方を、トリプルHも日頃から口にしているという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:24:19〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5059s"]]}, {"cat": "リングの話", "t": "海外大会は、現地に人を置いて日程も合わせる", "b": "年間最大級の有料大会を海外でも開き、現地で宣伝する体制をとっていると話す。映像配信サービスは国が変わっても同じ画面で使えるため、世界中で同じ商品として見てもらいやすいという。大切なのは中身で、そのうえで現地に人を置き、地元に合う日を選ぶことだと語る。毎年やり直し、信頼を築き続けなければならず、去年の記録に浸る気はないそうだ。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:29:11〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5351s"]]}, {"cat": "リングの話", "t": "小さな局から大手配信へ、先人の積み重ね", "b": "WWEは約25年前、小さなテレビ局で放送されていたが、いまは大手の放送局と配信サービスに載っていると振り返る。先に携わった人たちの仕事のおかげだと話す。世界で5〜10ほどの大きなチャンネルに集約されていくという仲間の見方に賛成で、できるだけ広い客層に届けることが大切だと語る。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:31:41〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5501s"]]}, {"cat": "リングの話", "t": "迷ったら「NFLを真似る、ボクシングの逆をやる」", "b": "判断に迷うとき、WWEには二つの指針があるという。ひとつはアメリカンフットボールの運営を参考にすること、もうひとつはボクシングのやり方の逆をすることだそうだ。ボクシングは団体や王座が乱立して、誰がいつどこで見られるのか分かりにくくなったと話す。新しいボクシング事業の名称はまだ検討中で、気に入った名前はすでに他人が商標を取っていたという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xLtsVW7ZpJQ", "src": [["公式YouTube（1:33:14〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5594s"]]}]);
  if (PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"].facts.push({"cat": "暮らし", "t": "コーディ・ローデスの「出て、戻る」賭け", "b": "コーディ・ローデスは名レスラーの息子として育ち、保証契約を自分から断って団体を離れ、インディーで新会社の立ち上げにも関わったという。大人になるには一度家を出る必要があり、父の息子というだけで終わらないための決断だったと、ニック・カーンは見ている。2022年のダラス大会で戻ったとき、観客が熱狂したことから、その賭けは成功したと思ったと、ニック・カーンが話している。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で、ニック・カーンの話（公式字幕を全文確認）", "src": [["公式YouTube（1:24:19〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5059s"]], "by": "第三者の話"});
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "雑誌のローマン・レインズ特集を読んで会いに行った", "b": "ローマン・レインズを取り上げた最近の雑誌記事は、人物像と信念を的確に描いた秀逸な内容だったと、ニック・カーンが話している。次に本人に会うとき、その記事を話題にできたことが強みになったという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で、ニック・カーンの話（公式字幕を全文確認）", "src": [["公式YouTube（1:02:34〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=3754s"]], "by": "第三者の話"});
  if (PROFILES["Penta"]) PROFILES["Penta"].facts.push({"cat": "暮らし", "t": "ペンタが「やるなら闘牛」と答えた", "b": "プロレス以外ならどの競技をやりたいかと選手に聞く動画で、ペンタが「プロの牛乗り競技」と答えたと、ニック・カーンが話している。担当者を通じて本人に連絡し、安全のため絶対に乗らないよう頼んだという。", "sp": "ニック・カーン", "d": "2025-06-19", "how": "ステファニーの番組で、ニック・カーンの話（公式字幕を全文確認）", "src": [["公式YouTube（1:27:31〜）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ&t=5251s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-xLtsVW7ZpJQ", d: "2025-06-19", show: "wys", who: ["Nick Khan"], t: "ニック・カーンの回　苦学の日々と、家族と仕事の考え方", lead: "ステファニー・マクマホンの番組に出た約100分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nick Khan"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-xLtsVW7ZpJQ").map((x) => [x.t, x.b, x.sp])), open: ["冒頭のスタッフ2人による振り返りと、聞き手ステファニー自身や家族の話、聞き手が語った逸話は載せていない。話者ラベルが入れ替わるため、文脈で本人の発言だけを選んだ。", "金額の話（賞金、学費、生活費、記録的な興行成績など）は載せていない。ほかに、UFCやボクシング事業の詳細、メディア業界の展望の一部も省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=xLtsVW7ZpJQ"]] });
  if (!ROSTER.find((r) => r[1] === "Ethan Page")) ROSTER.push(["イーサン・ペイジ", "Ethan Page", "lg", "北米王座を巻くレスラー", "", "", ""]);
  if (!PROFILES["Ethan Page"]) PROFILES["Ethan Page"] = { lead: "自信とおしゃべりで道を切り開いてきたイーサン・ペイジ。裏庭のレスラーから北米王者になるまでの歩みを、ユーモアたっぷりに語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ethan%20Page"]], moves: [], facts: [] };
  if (PROFILES["Ethan Page"]._weak) { PROFILES["Ethan Page"].lead = "自信とおしゃべりで道を切り開いてきたイーサン・ペイジ。裏庭のレスラーから北米王者になるまでの歩みを、ユーモアたっぷりに語る。"; delete PROFILES["Ethan Page"]._weak; }
  PROFILES["Ethan Page"].facts.push(...[{"cat": "リングの話", "t": "最近の「意地悪さ」はショーン・マイケルズが引き出した", "b": "ここ12か月は人生で最も激しい期間だったと振り返る。もともと自分の中にあった意地悪さを、ショーン・マイケルズが引き出したのではと語る。人に優しくするのは今は難しく、いまが最高の波に乗っていると話す。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（7:06〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=426s"]]}, {"cat": "リングの話", "t": "北米王座は最も格が高いと主張", "b": "北米王座を持つ自分は、3か国分の王者だと冗談まじりに語る。以前は同じ王座を「自分より下」と言っていたが、考え直して最も格式ある王座だと位置づけたそうだ。会場の観客に向けた、いつもの強気の演説だった。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（8:45〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=525s"]]}, {"cat": "リングに来るまで", "t": "WWEの契約は移動中の電話から", "b": "イーサン・ペイジは、ウィニペグからデトロイトを経てオハイオの大会へ向かう乗り継ぎの最中にWWEから電話を受けたという。最初の着信は切れてしまい、いたずら電話だと思ったそうだ。2度目でようやく本物だと気づき、契約を提示された。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（12:43〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=763s"]]}, {"cat": "リングに来るまで", "t": "若いころからWWE入りを公言していた", "b": "若いころのインタビューでも、WWEに行きたいのではなく「行く」と言い切っていたと話す。理由を聞かれても「ただ分かっていた」としか答えられないそうだ。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（14:14〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=854s"]]}, {"cat": "暮らし", "t": "動画投稿を続け、登録者10万人に", "b": "自分のYouTubeでVlogを続けていて、登録者が10万人に届いたと話す。聞き手の後押しで一気に伸びたと冗談まじりに語っている。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（15:02〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=902s"]]}, {"cat": "リングに来るまで", "t": "断られた日に自分へ向けて撮った動画", "b": "TNA時代の契約が切れそうなころ、WWEに断られて今後の連絡も控えるよう言われたという。そのとき、自分を励ますために「夢は終わっていない」と語る動画を撮ったと話す。その動画は友人の聞き手にも送ったそうだ。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（15:47〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=947s"]]}, {"cat": "リングの話", "t": "ザ・ロックとの場面は夢だった", "b": "ザ・ロックと同じ場面に立つことは、昔からの夢だったと話す。自分が思い描いてきた世界の頂点にいる人に直接思いを伝えられ、時間も延びて助言をもらえたそうだ。「手加減するな」と言われたのが心に残っているという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（20:41〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1241s"]]}, {"cat": "リングの話", "t": "ロックから受けた影響は「自信」", "b": "ロックから学んだのは、マイクの前や観客の前で、何でも自信を持って言い切る姿勢だという。少しおかしなことでも楽しめる人で、魅力の水準がとても高いと話す。自分も同じ熱量で観客に応えたいそうだ。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（22:19〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1339s"]]}, {"cat": "リングに来るまで", "t": "しゃべりは身を守る手段だった", "b": "マイクは一生の得意技で、おしゃべりが生き残るための手段だったのかもしれないと話す。高校のころから軽口をたたいていて、それがごく自然だったそうだ。リングでの自信は、ここ12か月でついたという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（23:04〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1384s"]]}, {"cat": "リングに来るまで", "t": "テレビゲームもスポーツもせず、目立つ道へ", "b": "ゲームもスポーツもせず、舞台の演技や映画、プロレスなど、中心に立てるものだけを選んできたという。友達は現実にいる、とも話している。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（23:49〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1429s"]]}, {"cat": "暮らし", "t": "パーティーでは主役にも脇役にもなれる", "b": "誕生日会などでは、目立つこともあれば、相手を大事に思って一歩引くこともあるという。いつでも主役になれると分かっているから、あえて出なくても平気だと話す。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（23:49〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1429s"]]}, {"cat": "リングの話", "t": "舞台裏にアンダーテイカーがいる日常", "b": "この1年で一番信じられなかったのは、ロックとの共演と、舞台裏にアンダーテイカーがよくいることだという。言葉を交わし、少し褒められただけで夢のようだったと話す。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（24:43〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1483s"]]}, {"cat": "リングの話", "t": "コーチ陣のおかげで、仕事の本質が分かった", "b": "17年の試行錯誤の末、プロレスとは何かをこの1年でようやく理解したと話す。きっかけはテリー・テイラーとショーン・マイケルズとの対話で、団体の考え方を教わったからだという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（27:57〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1677s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズが勧めたメガネと装い", "b": "今の洗練されたスタイルは、コーチ陣の導きなしにはなかったと話す。メガネを付けたまま出ることも、背の高い先輩に「似合う」と言われて決めたそうだ。ショーン・マイケルズとは最初から良好な関係で、今も良くなり続けているという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（28:45〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1725s"]]}, {"cat": "体のこと", "t": "メガネは本物で、外すと何も見えない", "b": "試合中は外すので、ほぼ見えないまま相手を殴っているという。コンタクトレンズは目に触れたくなくて使わず、レーシックも「拷問のようだ」と避けている。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（29:33〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1773s"]]}, {"cat": "リングに来るまで", "t": "19歳の誕生日はECWアリーナの試合", "b": "19歳の誕生日に、伝説的な会場で出来の悪い試合をしたことが長く心に残っていたという。のちにWWEの一員として同じ会場に戻れたのは、名誉挽回になったそうだ。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（35:52〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2152s"]]}, {"cat": "体のこと", "t": "試合前に全身じんましんが出た日", "b": "その19歳の試合の日は感染症のような症状で、全身にじんましんが出ていたという。試合前に症状を抑えてから出場し、勝ったと話す。会場が原因だったのかもしれないと笑っている。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（35:52〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2152s"]]}, {"cat": "リングに来るまで", "t": "裏庭レスラーから実況まで、独学で業界入り", "b": "最初は裏庭で「ジュリアン・ローガン」という名のレスラーをしていたという。その後、地元の団体で運営側になり、撮影係の代わりに実況も務めた。正式な訓練を受けないまま、しゃべりの勢いで業界に入り込んだと話す。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（36:40〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2200s"]]}, {"cat": "リングの話", "t": "TNAでは夢だった王座に挑戦", "b": "以前の団体名はインパクトだったが、自分はずっと元の名前のTNAのファンだったという。WWEの選手としてTNAのリングに戻り、世界王座に挑戦できたことを喜んでいる。かつての仲間と昔話もできたそうだ。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（38:19〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2299s"]]}, {"cat": "リングの話", "t": "自分の入場曲は7回作り直した", "b": "入場曲は最初に耳へ入るものなので、頭に残ることを重視したという。完成まで7回作り直し、1年かけて観客に覚えてもらうのが狙いだと話す。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（40:00〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2400s"]]}, {"cat": "家族", "t": "妻にはダジャレを言って呆れられる", "b": "ダジャレは、ふざけすぎず少し寒いくらいがちょうどいいと話す。妻は2時半の歯医者ネタを聞くたびに目を回すそうだ。ふだんは冗談を言うのではなく、場面に反応して笑いにするタイプだという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（41:36〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2496s"]]}, {"cat": "リングの話", "t": "夢の対戦相手を挙げる", "b": "まだ戦っていない相手として、ランディ・オートン、ジョン・シナ、ザ・ロックを挙げた。ロックには、まだ試合ができるなら最後の相手になりたいと話す。さらにCMパンクにも、面と向かって本音を言いたいと語った。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（45:36〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2736s"]]}, {"cat": "家族", "t": "感謝するのは健康と家族", "b": "最後の質問で感謝していることを3つ挙げ、健康、家族、そしてWWEが育ててくれたレスラーとしての自分だと答えた。この1年を妻と振り返り、今年やっとプロレスが分かったと話す話もあった。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2A9fVTRsib8", "src": [["番組のYouTube（47:20〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2840s"]]}]);
  if (PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"].facts.push({"cat": "暮らし", "t": "自分の団体で一緒にタッグ王者になった", "b": "自分が運営していた団体で、コーディ・ローデスと組んで王者になったことがあり、チーム名は「ツー・スターズ」だったと、イーサン・ペイジが話している。今も仲が良く、活躍を喜んでいるという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で、イーサン・ペイジの話（字幕を全文確認）", "src": [["番組のYouTube（42:30〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=2550s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "職場のボスは憧れの存在", "b": "ショーン・マイケルズのもとで働けることが信じられず、これまでにない良い関係だと、イーサン・ペイジが話している。この1年で自分を一番助けてくれた人だという。", "sp": "イーサン・ペイジ", "d": "2025-06-24", "how": "クリス・ヴァン・ヴリートの番組で、イーサン・ペイジの話（字幕を全文確認）", "src": [["番組のYouTube（25:33〜）", "https://www.youtube.com/watch?v=2A9fVTRsib8&t=1533s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-2A9fVTRsib8", d: "2025-06-24", show: "ext", who: ["Ethan Page"], t: "イーサン・ペイジの回　王者になるまでと、この1年の舞台裏", lead: "クリス・ヴァン・ヴリートの番組に出た約48分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ethan Page"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-2A9fVTRsib8").map((x) => [x.t, x.b, x.sp])), open: ["観客や聞き手とのやりとりが多く、話者が追いにくい冗談の部分は載せていない。", "聞き手の宣伝・スポンサー部分と、試合や抗争の細かな展開は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=2A9fVTRsib8"]] });
