  PROFILES["Kevin Owens"].facts.push(...[{"cat": "リングの話", "t": "ダミアン・プリーストを親友にする案を断った", "b": "2021年、ケビン・オーエンズはローマン・レインズとの抗争の最中だった。大会の3週間ほど前に「新しい親友としてダミアン・プリーストを出す」と告げられたが、二人があまりに正反対で誰も信じないと断ったという。ケビンは何年も仲間を裏切る役をやってきたので、急に親友を出すのは不自然だと感じたそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（2:30〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=150s"]]}, {"cat": "リングの話", "t": "観客をばかにする案は引き受けない", "b": "ケビン・オーエンズは、役柄の案を受けるかどうかの基準は、観客がそれを侮辱と感じないかどうかだと話す。プリーストとの親友案は、その点で納得できなかったという。何でも引き受けるより、自分のブランドに合わないものは断るという考え方だ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（5:54〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=354s"]]}, {"cat": "リングの話", "t": "若手の頃、試合中の一蹴りでビッグ・ショーを笑わせた", "b": "ケビンは育成施設時代、メインロースターの大型選手ビッグ・ショーが同じ会場で試合をしたあと、少し落ち込んでいたと話す。自分の試合中、倒れていた選手にわざと蹴りを入れる動きをすると、ショーは大笑いして椅子を壊したそうだ。あとでトリプルHから、あの蹴りが面白かったと言われ、ショーから「お前はずっとここにいる」と言われたという。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（22:04〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1324s"]]}, {"cat": "リングの話", "t": "トリプルHが新人3人を一段上に座らせた", "b": "ケビンは、育成施設に正式に入る前に呼ばれた週末の収録で、トリプルHが全員を前に話したと振り返る。ほかの選手を片側に座らせ、ケビンたち3人だけを反対側に座らせて「この3人がすべてを変える」と言ったそうだ。その翌日に5人が解雇され、緊張感の強い出来事だったという。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（44:28〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2668s"]]}, {"cat": "リングの話", "t": "タッグ王者の役目は、番組の最後で客を起こすこと", "b": "ケビンは、サミ・ゼインと組んでタッグ王者だった頃、毎週の長いテレビ番組の締めくくりを任されていたと話す。ジャッジメント・デイとは何度も試合をしたが、そのたびに客席が盛り上がったという。ケビンは、その功績の9割以上はサミにあると語る。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:03:39〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3819s"]]}, {"cat": "リングの話", "t": "ミズは評価が低すぎるとケビンは話す", "b": "ケビンは、インディー時代にWWEを外から見ていたとき、なぜミズがレッスルマニアのメインやトップの抗争にいるのか分からなかったそうだ。実際に試合をして理由が分かったという。ミズは何を頼まれても引き受けて良い試合にし、ガンサーとの試合も予想以上だったと称賛している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:04:29〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3869s"]]}, {"cat": "リングの話", "t": "怒って立ち去る場面でも、ウインカーとシートベルト", "b": "ケビンは、レッスルマニア前の抗争中、サミから怒って車で去る場面を演じたと話す。そのとき、先にシートベルトを締め、発進するときにウインカーを出したので、客がそれに気づいたそうだ。怒っていても安全運転は忘れない、と笑う。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:09:25〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4165s"]]}, {"cat": "リングの話", "t": "車の中で収録するはずが、ランディにトラックで潰される案", "b": "レッスルマニアに向けた展開で、ケビンは車の中で話している場面に、ランディ・オートンがトラックで突っ込む案を出したそうだ。自分のランボルギーニを壊してもよいと思ったが、会社に断られたという。ケビンは、あとで首を痛めたこともあり、すべて裏目に出たと冗談めかして話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:10:10〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4210s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Kevin Owens")) ROSTER.push(["ケビン・オーエンズ", "Kevin Owens", "lg", "王座を総なめした実力者", "", "", ""]);
  if (!PROFILES["Kevin Owens"]) PROFILES["Kevin Owens"] = { lead: "家族を養うため2012年に本業を辞め、インディーでシャツを売って家賃を払ってきたという。首の大けがで手術を待つ今も、息子オーウェンや仲間への思いを飾らずに語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kevin%20Owens"]], moves: [], facts: [] };
  if (PROFILES["Kevin Owens"]._weak) { PROFILES["Kevin Owens"].lead = "家族を養うため2012年に本業を辞め、インディーでシャツを売って家賃を払ってきたという。首の大けがで手術を待つ今も、息子オーウェンや仲間への思いを飾らずに語る。"; delete PROFILES["Kevin Owens"]._weak; }
  PROFILES["Kevin Owens"].facts.push(...[{"cat": "暮らし", "t": "めったに飲まない酒と特製カクテル", "b": "収録会場の蒸留所では、自分のために作られた特製カクテルを手にしていた。ふだんはほとんど酒を飲まず、この日は少なくとも5年ぶりくらいの量だと笑う。首もひざも悪いので「走る」より「早足で歩く」が精一杯だと冗談を言っている。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（6:41〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=401s"]]}, {"cat": "リングに来るまで", "t": "インディーで取った最高額は600ドル", "b": "大手団体での実績も有名な家名もなかったので、インディーで取った出場料は最高でも600ドルだったという。それでも出場の声は多く、シャツもたくさん売れて暮らしは成り立っていたそうだ。親友サミ・ゼインとは、ある団体では言われた額だけで出ていたと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（12:22〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=742s"]]}, {"cat": "リングに来るまで", "t": "SNSもグッズもコルトの助言から", "b": "インディー時代の手本は先輩コルト・カバーナの助言だったという。SNSには関わりたくなかったが、コルトに「毎日ツイートしろ」と言われて始めたそうだ。シャツを売るよう勧めたのもコルトで、受注生産のグッズ販売サイトが生まれたきっかけは自分だと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（28:34〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1714s"]]}, {"cat": "リングに来るまで", "t": "2012年に本業を辞めて一本立ち", "b": "2012年に勤めていた仕事を続けられなくなり、プロレスを唯一の収入源にすると決めたという。当時すでに子どもがいて、どうしても稼ぐ必要があったそうだ。グッズを作ろうにも、シャツをまとめて発注するお金すらなかったと振り返る。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（29:24〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1764s"]]}, {"cat": "暮らし", "t": "シャツの「連続販売記録」で家賃を払う", "b": "サイト開設以来、毎日必ず1枚はシャツが売れていることを「連続記録」と呼び、毎日ツイートしていたという。売れていない日に「今日で記録が止まりそう」と書くと、ファンが次々に買ってくれたそうだ。おかげで毎月の家賃の心配がなくなったと語る。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（31:46〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1906s"]]}, {"cat": "リングに来るまで", "t": "ダスティ像の除幕に一人だけ駆けつけた", "b": "ダスティの銅像が朝9時に除幕されたとき、育成ブランドの選手で見に来たのは自分だけだったという。ファンと一緒に見ていたらコーディに呼ばれ、ローデス家の記念写真に加わったそうだ。勝手に写り込んだように言われてきたが、本当は招かれたのだと笑って訂正している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（40:28〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2428s"]]}, {"cat": "暮らし", "t": "3週間で家と学校を見つけた引っ越し", "b": "2014年3月に入団テストを受け、5月に契約の連絡があったという。子どもたちを学年の途中でアメリカの学校に移したくないと、8月からの合流を希望したそうだ。カナダから家族を呼ぶため、ある朝オーランドの評判のよい小学校を調べ、その学区で借家を探したと振り返る。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（42:52〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2572s"]]}, {"cat": "リングに来るまで", "t": "空港で隣に座ったダスティ", "b": "家探しで頭がいっぱいのまま空港にいると、隣にダスティ・ローデスが座ったという。同じ便だった2人は1時間、プロレスの話は一切せず、人生や家族のことを語り合ったそうだ。「3週間では無理だ」と言われたが、初出勤の日にダスティから「やり遂げたか」と聞かれ、家族が原動力なのを見抜かれていたと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（46:04〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2764s"]]}, {"cat": "家族", "t": "息子が生まれて人が変わった", "b": "若い頃は自分とサミがケベックで一番だと思っていて、生意気で未熟だったと認めている。地元の団体を運営していた知人には嫌なやつだと思われていたが、息子オーウェンが生まれてから別人になったと言われたという。それからは子どもに食べ物とおもちゃを与えるためにプロレスで稼ぐことが中心になったそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（48:23〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2903s"]]}, {"cat": "家族", "t": "息子の夢だった初めての日本", "b": "ある夏、日本に行くのが夢だった息子オーウェンを初めて連れて行ったという。会社が息子の渡航費も出してくれたそうだ。現地でコーディ一家と東京ディズニーシーに行き、コーディが息子と話す様子を見て「あんなふうに息子と話せたら」とメッセージを送ったと明かす。息子はいい子だが子育ては難しく、いつも心配が尽きないとも話している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（50:50〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3050s"]]}, {"cat": "好きなもの", "t": "集めているのは友人たちのフィギュア", "b": "子どもの頃のフィギュアは実家に置いてきたが、今も店で友人のフィギュアを見つけると買っているという。若手時代からの仲間たちのものがそろっているそうだ。家に飾って「自分と仲間たちはこんなことを成し遂げた」と眺めるのが楽しみだと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（54:10〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3250s"]]}, {"cat": "暮らし", "t": "マグカップが壁に刺さった少年時代", "b": "祖父母の家に住んでいた頃、人形遊びでストーン・コールドの入場のガラスの割れる音を再現しようと、マグカップを壁に投げつけたという。カップは割れずに石膏ボードの壁に刺さり、ちょうど帰宅した父をひどくがっかりさせたそうだ。当時の年齢をごまかしていたが、実は17〜18歳だったと白状している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（58:07〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3487s"]]}, {"cat": "家族", "t": "運転免許を取ったばかりの息子", "b": "息子が最近運転免許を取ったばかりだと話す。フロリダのドライバーの大半より上手いと親バカぶりを見せ、シートベルトとウインカーの大切さを熱心に説いていた。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:08:33〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4113s"]]}, {"cat": "体のこと", "t": "首の脊髄損傷で手術待ち", "b": "収録時点で、首の脊髄を痛めて手術を待っている状態だと明かした。最後の試合は3月1日で、4月初めのMRIで「打撃を受けるのも危険」と言われたという。脊髄の回復を待ってから、7月中旬に手術を予定しているそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:10:10〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4210s"]]}, {"cat": "体のこと", "t": "痛みのなかった数か月から一転", "b": "けがの判明後もしばらくは痛みもなく元気だったが、収録の前の週になって首の痛みや腕・脚の不調が一気に出てきたと話す。以前にもリング上で2度、脚がしびれたように感覚がなくなったことがあったという。今は復帰のためだけでなく、痛みから解放されるためにも手術が待ち遠しいそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:11:47〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4307s"]]}, {"cat": "暮らし", "t": "砂漠でカートが横転した夜", "b": "サウジアラビアの夜の砂漠で、仲間と乗ったカートが砂丘で横転したという。安全説明を聞いていなかった同乗のスタッフの腕を、転がりながらとっさに押さえたそうだ。逆さまで砂まみれのまま最後まで取り残され、外から自分を探すサミの声が聞こえたと笑い話にしている。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:15:06〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4506s"]]}, {"cat": "好きなもの", "t": "寝室で枕相手に獲った白いベルト", "b": "子どもの頃に夢見た王座は、白いストラップのインターコンチネンタル王座だったという。寝室で枕やテディベアを相手に、何度もそのベルトを獲っていたそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:20:04〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4804s"]]}, {"cat": "リングに来るまで", "t": "父が借りてきた年間最大の祭典のビデオ", "b": "父が借りてきた年間最大の祭典のビデオがプロレスラーを目指すきっかけだったという。出場者で一番小柄なショーン・マイケルズが一番輝いて見え、やせっぽちだった自分も「彼にできるなら」と思ったそうだ。ストーン・コールドやリングマスター時代のファンで、WCWは見ようともしなかったと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:21:43〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4903s"]]}, {"cat": "家族", "t": "10歳上の兄とオーエン・ハート", "b": "10歳上の兄がいて、子どもの頃はよくやられていたという。今は水に流して兄のことが大好きだそうだ。そのせいで兄ブレットに反抗する弟オーエン・ハートに肩入れし、カナダ育ちながらブレット派ではなかったと笑う。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:23:21〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=5001s"]]}, {"cat": "好きなもの", "t": "子どもの頃に戻ってきたホッケー熱", "b": "子どもの頃はホッケーを見ていたが、プロレスに夢中になってからは他のスポーツに興味がなくなったという。最近またホッケーにはまり、モントリオールとタンパの2チームの年間シートを買ったそうだ。好きな選手はマリオ・ルミューとパトリック・ロワだと話す。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:25:43〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=5143s"]]}]);
  if (PROFILES["Big Show"]) PROFILES["Big Show"].facts.push({"cat": "暮らし", "t": "笑いすぎて椅子を壊した大男", "b": "育成ブランド時代、試合後に倒れている相手へ逃げざまに蹴りを入れたのを見て、ビッグ・ショーが笑いすぎて椅子を壊したという。それ以来「お前は一生仲間だ」と言われ、今も連絡を取り合っているそうだ。とても親切な人だと、ケビン・オーエンズが話している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で、ケビン・オーエンズの話（公式字幕を全文確認）", "src": [["公式YouTube（24:27〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1467s"]], "by": "第三者の話"});
  if (PROFILES["Finn Balor"]) PROFILES["Finn Balor"].facts.push({"cat": "暮らし", "t": "大切に保存しているメッセージ", "b": "フィン・ベイラーは誠実で正直な人で、もらったメッセージの中には一生大事にしたいものがあると、ケビン・オーエンズが話している。見た目は正反対でも根っこはよく似ているという。友人たちが褒めすぎるので会う前は少し反発していたが、会ってすぐに意気投合したそうだ。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で、ケビン・オーエンズの話（公式字幕を全文確認）", "src": [["公式YouTube（56:30〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=3390s"]], "by": "第三者の話"});
  if (PROFILES["Colt Cabana"]) PROFILES["Colt Cabana"].facts.push({"cat": "暮らし", "t": "仲間のために生まれた受注生産サイト", "b": "シャツを作る資金がない後輩のため、コルト・カバーナが知り合いの業者に掛け合い、注文が入ってから印刷する仕組みを提案したという。最初に並んだのはゲストやヤングバックス、コルト自身のシャツだったと、ケビン・オーエンズが話している。", "sp": "ケビン・オーエンズ", "d": "2025-06-25", "how": "コーディの番組で、ケビン・オーエンズの話（公式字幕を全文確認）", "src": [["公式YouTube（30:15〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1815s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "インディーでは「取りすぎない」", "b": "退団後のインディー時代、ギャラは公正に設定し、主催者がきちんと元を取れるようにしていたという。試合後にリング上での写真撮影を引き受けるなどして、主催者に損をさせないよう心がけたそうだ。ある団体には750ドルで出場したと明かしている。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（11:35〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=695s"]]}, {"cat": "リングに来るまで", "t": "退団直後に背中を押したビッグ・ショー", "b": "退団を決めたとき、真っ先に手を差し伸べてくれたのがビッグ・ショーとケビンだったという。ビッグ・ショーは自分のハリウッドの代理人を紹介してくれ、俳優の仕事につながったそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（27:47〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1667s"]]}, {"cat": "暮らし", "t": "グッズサイトから外された夫婦の写真", "b": "受注生産のグッズサイトでは、ずっと自分と妻ブランディの写真が看板に使われていたが、最近ようやく外されたという。当然だと笑いつつ、本音では残っていてほしかったそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（30:15〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=1815s"]]}, {"cat": "家族", "t": "母はダスティ像があまり好きではない", "b": "父ダスティの銅像はローデス家では賛否が分かれていて、母は気に入っていないという。ほかの家族は、いい表情をとらえていると気に入っているそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（42:52〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2572s"]]}, {"cat": "家族", "t": "娘リバティが変えたプロレスの理由", "b": "娘リバティが生まれるまで、自分は本当の意味でうまくなれていなかったと思うという。それまでは誰かの先を行くことばかり考えていたが、娘の誕生で、なぜこれをやるのかが見えたそうだ。父ダスティも家族のために戦う人だったと話す。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（47:38〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=2858s"]]}, {"cat": "家族", "t": "父の口ぐせ「その翌日は何をする？」", "b": "父ダスティはよく「年間最大の祭典のメインを張って、その翌日は何をするんだ」と冗談まじりに言っていたという。一夜の成功より、それを続けることが大事だという教えとして、今は生徒たちに伝えているそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:07:46〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=4066s"]]}, {"cat": "リングに来るまで", "t": "退団を決めた「それ、大事か？」", "b": "退団の理由はいくつもあったが、そのひとつは、シャーロットが連れてきた子どもが「スターダスト」を知らず、それ以前の自分のことも知らなかったことだという。同じ相手との11回目の試合の結末を尋ねたとき「それ、大事か？」と返され、もう潮時だと悟ったそうだ。", "sp": "コーディ・ローデス", "d": "2025-06-25", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-u-CFGPwPhwI", "src": [["公式YouTube（1:27:16〜）", "https://www.youtube.com/watch?v=u-CFGPwPhwI&t=5236s"]]}]);
  ARTICLES.push({ id: "wdywta-u-CFGPwPhwI", d: "2025-06-25", show: "wdywta", who: ["Kevin Owens", "Cody Rhodes"], t: "ケビン・オーエンズの回　首のけが、インディー時代、ダスティとの出会い", lead: "コーディ・ローデスの番組に出た約92分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kevin Owens", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-u-CFGPwPhwI").map((x) => [x.t, x.b, x.sp])), open: ["子どもについては、息子オーウェンと「子どもたち」という言い方だけを載せた。番組中の「リバティ」はコーディの娘のことで、ケビンの子どもではない。", "字幕に話者名がなく、マット・カルドナとのディズニー旅行の掛け合いなど話者が追いきれなかった部分は載せていない。1:25台後半〜1:27の字幕は欠けている。", "首のけがと手術の予定は収録時点（2025年6月）の話。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=u-CFGPwPhwI"]] });
  if (!ROSTER.find((r) => r[1] === "Bron Breakker")) ROSTER.push(["ブロン・ブレイカー", "Bron Breakker", "lg", "スタイナー家の若手", "", "", ""]);
  if (!PROFILES["Bron Breakker"]) PROFILES["Bron Breakker"] = { lead: "元フットボール選手で、父と同じ道を選んだブロン・ブレイカー。昔気質の家で育ち、釣りと家族を大切にする素顔を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bron%20Breakker"]], moves: [], facts: [] };
  if (PROFILES["Bron Breakker"]._weak) { PROFILES["Bron Breakker"].lead = "元フットボール選手で、父と同じ道を選んだブロン・ブレイカー。昔気質の家で育ち、釣りと家族を大切にする素顔を語った。"; delete PROFILES["Bron Breakker"]._weak; }
  PROFILES["Bron Breakker"].facts.push(...[{"cat": "家族", "t": "末っ子だから早く強くなった", "b": "きょうだいの中でいちばん下だったため、早く強くならなければならなかったと話す。タフさは家族の中で身についたものだという。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:40〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=100s"]]}, {"cat": "リングの話", "t": "動画配信者スピード戦の舞台裏", "b": "動画配信者のスピードとの試合は、事前に入場の流れを確認して臨んだという。バク宙のあとの向きを何度も打ち合わせていたが、本人は余裕の様子だったそうだ。ブロンは「迷ったら向きだけ変えて」と頼んだと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（2:26〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=146s"]]}, {"cat": "リングの話", "t": "NXT時代の70ヤード助走", "b": "NXT時代、テーブル破壊の場面で、会場の外の駐車場まで下がって約70ヤードを全力で走ったと話す。ぶつかった勢いで実況席の端から壁際まで飛んだといい、「かなり危険だった」と振り返っている。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（5:37〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=337s"]]}, {"cat": "家族", "t": "父の試合は見ずに育った", "b": "父が現役を退いていたため、父のリングは生で見ていないという。家にはアクションフィギュアがあった程度で、大きな大会をきっかけに番組を観始め、動画で父やおじの昔の試合を追うようになったと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（8:54〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=534s"]]}, {"cat": "リングに来るまで", "t": "三競技とレスリング州王者", "b": "フットボール、レスリング、野球の三つをやっていたという。レスリングでは無敗の州王者で大学の誘いもあったが、奨学金の面でフットボールを選んだそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（10:35〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=635s"]]}, {"cat": "家族", "t": "父に認められたかった", "b": "父は大学で全米選手に選ばれたレスラーで、その背中を追って「父に誇りに思ってほしい」という気持ちが原動力だったと話す。家は昔気質でタフな家庭だったという。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（11:29〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=689s"]]}, {"cat": "リングに来るまで", "t": "NFL挑戦のあとプロレスへ", "b": "NFLでの短い挑戦のあと、コロナ禍で契約が取れず、父に「プロレスをやりたい」と切り出したという。父は当時と今の業界の違いからためらったが、しつこく頼み続けて折れさせたそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（12:26〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=746s"]]}, {"cat": "体のこと", "t": "スポーツのない数か月がつらかった", "b": "人生で唯一スポーツから離れた2〜3か月は、目標がなく気持ちが崩れそうだったと話す。目標に向かう規律がないと自分は落ち着かない、と感じたという。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（13:13〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=793s"]]}, {"cat": "リングに来るまで", "t": "ナッシュ経由で届いた道", "b": "父がケビン・ナッシュに連絡し、ナッシュがトリプルHに伝えてくれたという。無観客の育成施設で、人のいない中、極秘のようなトライアウトに呼ばれたそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（13:59〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=839s"]]}, {"cat": "リングに来るまで", "t": "二日間のトライアウト", "b": "トライアウトはマット・ブルームが仕切り、初日は父の名を背負う気持ちで全ドリルに全力を出したという。二日目のマイクテストでは、それまで黙っていた分、スタイナー流の一分間で周りを笑わせたと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（15:36〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=936s"]]}, {"cat": "リングに来るまで", "t": "おじスコットの会場で初試合", "b": "ジョージアのサイン会におじのスコットと行ったところ、急きょ試合に出ることになったという。やり方が分からず動画を見て覚え、最後はスコットと組んで戦ったそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（20:45〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=1245s"]]}, {"cat": "家族", "t": "スタイナーの息子という重み", "b": "父とおじはどちらも業界を守る昔気質で、その基準を保たなければと感じているという。今は「スタイナーの息子」を少し抜け出せたが、父に誇りに思われたい気持ちは変わらないと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（23:06〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=1386s"]]}, {"cat": "リングの話", "t": "経験数か月でテレビデビュー", "b": "同期は経験がほぼないまま契約し、本人も練習は数か月で基本の組み技を学んでいる最中だったという。番組の大きな転換期と重なり、ある日突然「明日テレビに出る」と告げられ、眠れなかったそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（24:43〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=1483s"]]}, {"cat": "リングの話", "t": "リングネームと不安な週末", "b": "スタイナーの名を使う案もあったが、どのみち付いてくるものとして気持ちは複雑だったという。リストラが続く週末で、自分は会社に何も貢献していないと不安だったと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（27:11〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=1631s"]]}, {"cat": "リングの話", "t": "LAナイトに導かれたデビュー", "b": "観客の前に立つのは初めてで、LAナイトが導いてくれたことに感謝している。そのあとは毎晩のようにツアーを回り、いろいろな試合を経験して力がついたと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（30:30〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=1830s"]]}, {"cat": "好きなもの", "t": "子どもの頃から続くバス釣り", "b": "水辺で育ち、岸からの釣りに始まり、父のジョン・ボートでも釣っていたという。大学で離れたが、フロリダに来てまた熱が入ったと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（36:57〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2217s"]]}, {"cat": "好きなもの", "t": "仲間とボートを買い替えた", "b": "NXTの仲間のトニー・ディアンジェロと岸釣りをするうち、ボートが欲しくなったという。古いボートで操縦を覚え、サマースラム出場の翌週に今のボートを買ったそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（37:49〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2269s"]]}, {"cat": "好きなもの", "t": "釣り大会で準優勝", "b": "最近は釣り大会に出ており、水曜の夜の大会で2位になったという。船は2006年製で、練習用に高すぎないものを選んだと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（39:26〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2366s"]]}, {"cat": "暮らし", "t": "バッテリー切れも自力で解決", "b": "大会の日に生け簀のポンプで電池が上がってしまい、計量の10分前にエンジンがかからなかったという。北ジョージア育ちらしく自分で直し、ジャンプボックスで復旧したと笑う。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（40:17〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2417s"]]}, {"cat": "暮らし", "t": "常に見られる生活の逃げ場", "b": "メインロスターに上がると生活のすべてが人目にさらされ、悪い日も許されない感覚になるという。釣りや狩りに行くのは、その緊張から離れられるからだと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（41:49〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2509s"]]}, {"cat": "好きなもの", "t": "引退後はプロの釣り師も", "b": "プロレスが最優先で、釣りは趣味だという。体がきかなくなって引退する日が来たら、プロとして釣りをするのも面白いかもしれないと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（43:29〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2609s"]]}, {"cat": "リングの話", "t": "初のWM前、舞台裏での悪ふざけ", "b": "年間最大の祭典に初出場する4人の試合を控え、舞台裏の入口でトリプルHにいつもの調子で絡んだという。NXT時代にショーン・マイケルズにしていたいたずらが始まりで、出番直前にも声をかけて笑わせたと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（45:07〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=2707s"]]}, {"cat": "リングの話", "t": "新しい立場への感謝", "b": "セス・ロリンズとポール・ヘイマンとの合流は大きなチャンスで、とても謙虚な気持ちだと話す。自分の言葉より行動で示すタイプだという。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（58:00〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=3480s"]]}, {"cat": "暮らし", "t": "誰より先に準備する習慣", "b": "大学時代、試合後にみんなが遊びに行く間にジムへ通い、相手との差をつけていたという。今も夜中に走りやスピードの練習をし、相手の映像を見て研究すると話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（58:51〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=3531s"]]}, {"cat": "暮らし", "t": "口数は少なく、行動で語る", "b": "自分を大きく語るのは好きではなく、「自信は静かなもの」という考えだという。大学でも相手を挑発せず、プレーで見せていたと話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:00:26〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=3626s"]]}, {"cat": "家族", "t": "母は家族のヒーロー", "b": "兄弟3人がいつもスポーツをしていて、父が仕事や遠征で忙しいなか、母が送り迎えや練習を支えてくれたという。「母にはすべてを負っている」と話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:02:06〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=3726s"]]}, {"cat": "家族", "t": "鶏の世話とバナナ合戦", "b": "森の中の農場のような家で育ち、鶏が苦手で、末っ子の自分だけが暗い中で餌やりに行かされたという。傷んだバナナで兄弟と1時間半投げ合い、帰宅した父の車に当たったが、父は笑って許してくれたそうだ。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:08:03〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=4083s"]]}, {"cat": "暮らし", "t": "最近始めた家庭菜園", "b": "最近家庭菜園を始め、トマト、ピーマン、キュウリを育てていると話す。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:11:12〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=4272s"]]}, {"cat": "好きなもの", "t": "憧れはボー・ジャクソン", "b": "史上最高のアスリートはボー・ジャクソンだと話す。フットボールのキャンプ時代にレイ・ルイスたちに会えたのも良い思い出だという。", "sp": "ブロン・ブレイカー", "d": "2025-06-26", "how": "WWE公式チャンネルの番組で（字幕を全文確認）", "art": "ext-YzadkjU1Psg", "src": [["番組のYouTube（1:12:01〜）", "https://www.youtube.com/watch?v=YzadkjU1Psg&t=4321s"]]}]);
  ARTICLES.push({ id: "ext-YzadkjU1Psg", d: "2025-06-26", show: "ext", who: ["Bron Breakker"], t: "ブロン・ブレイカーの回　父の背中と釣りの時間", lead: "WWE公式チャンネルの番組に出た約77分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bron Breakker"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-YzadkjU1Psg").map((x) => [x.t, x.b, x.sp])), open: ["同席者の話と本人の話が混ざる箇所（ワニ狩り、サッカー場の逸話など）は載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=YzadkjU1Psg"]] });
