  if (!PROFILES["Randy Orton"]) PROFILES["Randy Orton"] = { lead: "三世代続くレスラー一家に生まれながら、もとは熱心なファンではなかったという。海兵隊での挫折を越えてリングに立ち、今は若手への恩返しに喜びを見いだしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Randy%20Orton"]], moves: [], facts: [] };
  if (PROFILES["Randy Orton"].lead === "三世代続くレスラー一家に生まれながら、もとは熱心なファンではなかったという。海兵隊での挫折を越えてリングに立ち、今は若手への恩返しに喜びを見いだしている。") PROFILES["Randy Orton"]._weak = 1;
  PROFILES["Randy Orton"].facts.push(...[{"cat": "家族", "t": "何より大切なのは妻と子どもたち", "b": "40歳になった今は、人生が幸せな時期だと話す。仕事で最高の状態でいることも大事だが、いちばん大切なのは妻と子どもたちが元気でいることだという。家族がうまくいっていれば、ほかのことも自然と整うと考えているそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:40〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=100s"]]}, {"cat": "リングの話", "t": "長く弱点だったマイクを、気持ちで変えた", "b": "長年、試合に集中するあまり、マイクの話は並程度だったと認める。1年ほど前に、台本の友情の場面で気持ちが乗らず、19歳でエッジに声をかけられた本当の思い出を足して語ったところ、うまくいったという。以来、自分が感じていれば伝わるという手応えを持っていると話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=196s"]]}, {"cat": "家族", "t": "父が不在がちで、ファンではなかった子ども時代", "b": "祖父も父もレスラーという家に育ったが、幼いころは自分がレスラーのファンだとは思っていなかったと話す。父はただ長く家を空ける仕事をしている人で、日本から帰ってくると土産をくれるのが楽しみだったという。このことをカメラの前で語るのは初めてだそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（11:16〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=676s"]]}, {"cat": "リングに来るまで", "t": "父の後を継ぐ自信がなく、大学にも進まなかった", "b": "高校の終わりごろにはプロレスに夢中になったが、父のようにはなれないと思い、道に進む自信がなかったという。大学へ行く気もなく、スポーツも得意だったが奨学金を取るほどではなかったそうだ。高校ではレスリング部で、まずまずの成績だったと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（12:52〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=772s"]]}, {"cat": "リングに来るまで", "t": "海兵隊を無断で離れ、不名誉除隊になった", "b": "海兵隊では訓練を優秀な成績で終え、昇進もしたという。しかし配属先の雰囲気になじめず、約83日間無断で隊を離れた。戻って出頭したものの任務を拒み、営倉で約45日を過ごして不名誉除隊となったそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（13:38〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=818s"]]}, {"cat": "リングに来るまで", "t": "地下室暮らしの末に、父へ頼み込んだ", "b": "除隊後は実家に戻り、父と地下室に自分の部屋を作って、近所のガソリンスタンドで夜勤をしていたという。もうすぐ19歳というころ、プロレスの道に進めるか父に尋ねたが、父はもう業界に居場所がないと乗り気ではなかったそうだ。どん底まで落ちてから頼みに行ったと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（15:19〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=919s"]]}, {"cat": "リングに来るまで", "t": "父の一本の電話から始まった入団テスト", "b": "父が昔の関係者に電話をすると、古参たちは父を慕っていて、息子の話に乗ってくれたという。当時は身長190cm台、体重110kg前後で、すぐ施設に呼ばれた。初めてのタックルの練習で相手の指導役を倒してしまったと思い込んで慌てたが、その間に育成契約の話が決まっていたそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（16:07〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=967s"]]}, {"cat": "リングに来るまで", "t": "育成施設で周りに追いつこうと火がついた", "b": "育成施設にはバティスタ、ブロック・レスナー、ジョン・シナらがいたという。元アスリートばかりの中で、自分だけが父のおかげで機会を与えられた立場だと感じていた。ドロップキックもまともに当たらず「ボブの息子か」と言われ、そこから約1年半で証明しようと打ち込んだそうだ。レスナーと同じ時期に最初の昇格組になったと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（16:57〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1017s"]]}, {"cat": "リングの話", "t": "小さな動きを積み重ねて試合が引き締まった", "b": "トリプルHとフレアーと一緒に動く中で、観客が気づかないような小さな点を磨いたという。何度も肩を痛めたことから、技を減らして休み技にせず、表情や体の使い方で見せる試合運びを覚えたそうだ。リング外での振る舞い方も、二人から多く学んだと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（20:16〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1216s"]]}, {"cat": "リングの話", "t": "22歳の自分に技を受けてくれたアンダーテイカー", "b": "22歳のころ、アンダーテイカーとの試合でたくさんの攻撃をさせてもらったという。試合後、ヴィンスが叱るように問いかけたが、アンダーテイカーは若手を押し上げるのが仕事だという趣旨の答えをしたそうだ。それをそばで聞き、期待に応えたいと感じたと話す。放送では見せ場が大幅に切られたが、一生忘れない試合だという。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（22:37〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1357s"]]}, {"cat": "リングに来るまで", "t": "ユニット入りのきっかけは、地味な練習だった", "b": "試合前の会場のリングで、ほかの若手と一緒に受け身や痛がり方の練習をしていたところを、トリプルHが見ていたという。あとで声がかかり、トリプルHとリック・フレアーのユニットに加わることになった。フレアーは「道中の父親」のような存在で、車の中で人生の相談にも乗ってくれたと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1638s"]]}, {"cat": "家族", "t": "毎週、父が空港へ送り迎えしてくれる", "b": "父は番組の仕事に口を出さず、頼まれたときだけ助言をくれたという。今も毎週、空港への送り迎えをしてくれていて、30分の車中で前夜の番組について話すのが親子の時間だそうだ。父は昨年70歳になり、息子の活躍を喜んでいると話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（32:23〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1943s"]]}, {"cat": "家族", "t": "家が破産した子ども時代と親への恩返し", "b": "幼いころ家が破産し、安い赤い運動靴を2年はいて指先が出ていたという。母がジーンズを切って夏用にしてくれたが丈が短すぎて、からかわれたそうだ。父が苦労して支えてくれたぶん、今は両親の生活を助けていると話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（33:11〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=1991s"]]}, {"cat": "リングの話", "t": "RKOの名前は、頭文字から本人が提案した", "b": "今の決め技は、ジョン・ローリナイティスの勧めで別の技を作り替えたのが始まりだという。どんな場面でも使える技ができたと感謝している。名前は自分の頭文字から思いつき、ヴィンスに伝えると、歩きながら「いいね」と答えただけで決まったそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（36:17〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=2177s"]]}, {"cat": "リングの話", "t": "レジェンド・キラーと、ミック・フォーリーとの試合", "b": "この異名の発案者は覚えていないが、ミック・フォーリーが深く関わったと話す。伝説の人たちが、父のおかげで自分を受け入れてくれたと感じていたそうだ。2004年の有刺鉄線バットの試合は、満員の会場の中でも特に大きな歓声を浴び、見られ方が変わった試合だったという。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（41:18〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=2478s"]]}, {"cat": "リングの話", "t": "24歳の世界王者は、まだ準備ができていなかった", "b": "24歳で当時最年少の世界王者になったとき、嬉しくて控室にいつまでも残り、最後の一人になったという。ただ、王座を守る難しさを分かっておらず、準備はできていなかったと認める。約1か月後に王座を失ったそうだ。続く善玉への転向では、無理に笑顔を作る方向に迷ったと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（46:59〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=2819s"]]}, {"cat": "体のこと", "t": "2005年ごろから続いた、自分を見失った時期", "b": "2005年ごろから2007年ごろまでが、自分を壊していた時期だったと振り返る。大きな試合の前日の朝、徹夜明けで練習に寝過ごし、父を含む全員を待たせてしまった。その夜は父の殿堂入りの式典でスピーチをしたが、準備が足りず、今も悔いが残る出来事だそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（52:34〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=3154s"]]}, {"cat": "体のこと", "t": "バイク事故で鎖骨を2度折った", "b": "2008年の夏、試合で鎖骨を折って約1か月固定したという。その後バイクに乗って戻る途中、対向車の光で目がくらんで転び、同じ鎖骨をまた折ったそうだ。好きだったバイクはすべて手放した。このころには以前の生活を断ち、自分の心の強さを知ったと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（56:31〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=3391s"]]}, {"cat": "体のこと", "t": "今は筋肉より、体を長持ちさせる練習", "b": "古傷を抱えながら移動を続けているため、準備運動とストレッチを重視していると話す。ウェイトは回数を多く、フォームを大切にし、筋肉を大きくするより現状維持が目的だという。体を作る人ではなかったとも話し、妻に昔の体型でも満足していなかったと指摘されたそうだ。40歳でもあと10年は続けたいと話す。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（58:05〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=3485s"]]}, {"cat": "リングの話", "t": "ジョン・シナから学んだ、観客を聞くこと", "b": "シナとは数百試合を重ね、努力と誠実さの人だったと話す。質問を重ね、居心地のいい場所から飛び出す姿勢にも刺激を受けたという。観客の反応を聞くことが何より大切だと教わったのは、彼からだったそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:07:48〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=4068s"]]}, {"cat": "リングの話", "t": "エッジ夫妻に向けたマイクが、ヴィンスの心に届いた", "b": "2020年、エッジの妻に向けて語るマイクの直前、ヴィンスに19歳のときの思い出を伝えると、そのまま話すよう言われたという。自分に五人の子がいることもあり、相手の家族に向けた言葉を本気で語れた。終わるとヴィンスが立ち上がって握手し、最高の瞬間だったと言ってくれたそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:16:49〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=4609s"]]}, {"cat": "家族", "t": "二人の娘と三人の息子の父", "b": "5人の子の父で、娘が2人、息子が3人いると話す。同じく娘を持つ父親として、2020年のあの語りに気持ちを重ねやすかったという。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:18:26〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=4706s"]]}, {"cat": "リングの話", "t": "14度目の王座に込めた思い", "b": "14回目の世界王座は、自分にとって大きな意味があると話す。リック・フレアーとジョン・シナが16回、トリプルHが14回という歴史の中で、その仲間入りができたことが誇りだという。外から何と言われても、自分には本物の出来事だと語る。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:32:54〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=5574s"]]}, {"cat": "リングの話", "t": "今度は自分が若手に返す番", "b": "若手の質問に答えたり、ドリュー・マッキンタイアに王座を渡した後に感謝されたりして、教える喜びを感じているという。かつて自分がしてもらったように、技を受け、自信を持たせる側に回りたいと話す。第一線に立ちながら後進を育てるのが、これからの満足だそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-lINxXSxsDFM", "src": [["番組のYouTube（1:35:17〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=5717s"]]}]);
  if (PROFILES["Edge"]) PROFILES["Edge"].facts.push({"cat": "暮らし", "t": "19歳で声をかけてくれたエッジ", "b": "育成契約を結んだばかりの19歳のとき、エッジが「いつか一緒に試合をしよう」と声をかけてくれたことを、今もはっきり覚えていると、ランディ・オートンが話している。2007年ごろには兄貴分のように支えてくれた存在だったという。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ランディ・オートンの話（字幕を全文確認）", "src": [["番組のYouTube（6:32〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=392s"]], "by": "第三者の話"});
  if (PROFILES["Christian"]) PROFILES["Christian"].facts.push({"cat": "暮らし", "t": "試合の発想がずば抜けているクリスチャン", "b": "2011年の対戦で、クリスチャンは試合の組み立てを考える力が抜群で、彼の案をそのまま形にした場面が多かったと、ランディ・オートンが話している。2011年は自分のキャリアでも特に良い年の一つだったという。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ランディ・オートンの話（字幕を全文確認）", "src": [["番組のYouTube（1:01:11〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=3671s"]], "by": "第三者の話"});
  if (PROFILES["Drew McIntyre"]) PROFILES["Drew McIntyre"].facts.push({"cat": "暮らし", "t": "最初は気乗りしなかったドリューとの抗争", "b": "最初はドリュー・マッキンタイアと組む気がなかったが、数回の大きな試合を重ねるうちに人柄が分かり、業界を大事にする男だと思うようになったと、ランディ・オートンが話している。試合後に「誰よりも自分のためになった」と言われたことが心に残っているそうだ。", "sp": "ランディ・オートン", "d": "2025-06-28", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ランディ・オートンの話（字幕を全文確認）", "src": [["番組のYouTube（1:27:14〜）", "https://www.youtube.com/watch?v=lINxXSxsDFM&t=5234s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-lINxXSxsDFM", d: "2025-06-28", show: "ext", who: ["Randy Orton"], t: "ランディ・オートンの回　恩返しと、声で伝える術", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約104分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Randy Orton"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-lINxXSxsDFM").map((x) => [x.t, x.b, x.sp])), open: ["ホスト（ストーン・コールド・スティーブ・オースティン）自身の思い出話や評価、試合映像の実況部分、番組冒頭の乾杯などの宣伝・スポンサー要素は載せていない。", "字幕は話者の表示が入れ替わっており、文脈でオートン本人の発言だけを拾った。試合の勝敗や展開の細部、他選手への細かな評価は項目にしていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=lINxXSxsDFM"]] });
  if (!PROFILES["Randy Orton"]) PROFILES["Randy Orton"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Randy%20Orton"]], moves: [], facts: [] };
  if (PROFILES["Randy Orton"].lead === "") PROFILES["Randy Orton"]._weak = 1;
  PROFILES["Randy Orton"].facts.push(...[{"cat": "リングの話", "t": "手錠のトリプルHの前でDDTをかけた日", "b": "ランディ・オートンは、2009年のあの場面を振り返っている。リハーサルでは、ビンス・マクマホンが見守る中、手錠をかけられたトリプルHが届かない位置やDDTの落とし所を確認したという。当時20代で気まずくてたまらず、時間切れで企画ごと消えないかと内心願っていたそうだ。顔は真っ赤だったと笑い、トリプルHは「どうすれば一番印象に残るか」だけを考えていたと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（8:20〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=500s"]]}, {"cat": "リングの話", "t": "プロレス生活は四半世紀、忘れたことも多い", "b": "ランディ・オートンは、育成契約を結んで最初の受け身を取ってから、およそ25年になると話す。会ったたくさんの人やこなした仕事を振り返ると、どれだけ忘れているかに驚くという。こうした対談で記憶がよみがえることがあり、子どもたちが見せてくる当時の試合動画で「2009年のパパはかっこよかった」と言われるのも楽しみの一つだそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（11:42〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=702s"]]}, {"cat": "リングの話", "t": "24歳で世界王座、トロントで一人きりに", "b": "ランディ・オートンは、24歳で世界王座を獲った夜のことを、細部は霧の中でも感情ははっきり覚えていると話す。入場口の裏で借りた電話で父に報告し、会場を最後に出た一人になって、王座ベルトを膝に載せたまま「これは現実か」と繰り返し思っていたという。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（11:42〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=702s"]]}, {"cat": "リングの話", "t": "アクションフィギュアはいまも実感がわかない", "b": "ランディ・オートンは、店で子どもと一緒に自分のアクションフィギュアが棚に並んでいるのを見ると、いまも実感がわかず頬をつねりたくなると話す。何度見ても慣れることはなく、ただただ恵まれているという気持ちだそうだ。人生の分かれ道では、いつも業界の誰かが正しい道へ導いてくれたとも語る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（13:29〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=809s"]]}, {"cat": "リングの話", "t": "導いてくれた先輩たちと、いまの自分", "b": "ランディ・オートンは、いちばんの恩人にトリプルHの名を挙げる。若くして天狗になり、真剣さが足りなかった自分に、早くから何かを見いだして付き合い続けてくれたという。ほかにもザ・アンダーテイカー、ショーン・マイケルズ、リックらの導きがあり、いまは自分が若い選手に助言する側になって、一周したと感じるそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（14:20〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=860s"]]}, {"cat": "リングの話", "t": "選手に優しくなった今のスケジュール", "b": "ランディ・オートンは、最近の日程は選手に寄り添ったものになったと話す。トリプルHが娘の大事なソフトボールの試合のためにテレビ収録を欠席したと知り、うれしく思ったという。昔ならあり得なかったことで、リーダーが自ら手本を見せているのだと感じるそうだ。大きな大会の主役でもない限り、早めに頼めば家族の行事のための休みは認めてもらえると、ランディ・オートンは話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（25:52〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1552s"]]}, {"cat": "リングの話", "t": "娘の誕生日にリングの真ん中へ", "b": "ランディ・オートンは、ニューヨークのバークレイズ・センターで、娘ブルックリンの誕生日にリングへ連れていった話をする。名前と開催地がブルックリンで重なる日で、観客に歌ってもらう案もあった。最初は尻込みしたが、マット・リドルに「やれよ」と背中を押されて実行したという。会場全体が大声で歌ってくれた、忘れられない場面だそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（40:12〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2412s"]]}, {"cat": "リングの話", "t": "若い頃は、建物でいちばん自信のない男だった", "b": "ランディ・オートンは、若い頃に周りへきつく当たったことがあると認める。理由は父の影響などではなく、自分が会場でいちばん自信のない男だったからで、それが身を守る方法だったと振り返る。いまは疲れや不満を人にぶつけないよう、自分の反応を意識しているという。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（45:09〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2709s"]]}, {"cat": "リングの話", "t": "試合のある日も「いま、この瞬間」だけを見る", "b": "ランディ・オートンは、この日も会場入りの前に別の仕事があり、そのあとにプロモ、さらにサミ・ゼインとの試合の予定があって、考えるとすぐ圧倒されてしまうと話す。そんなときは「いま、この瞬間」だけに集中し、一日ずつ生きることを心がけているという。先々のことを心配しすぎて消耗してきた過去があるそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（49:11〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2951s"]]}, {"cat": "リングの話", "t": "徹夜明けのギュンター戦、控室で90分眠る", "b": "ランディ・オートンは、背中の手術から復帰した後に、ギュンターと大きな一対一の試合をした話をする。ドイツかサウジのどちらかだったと記憶している。前夜は眠れず、控室で1時間半ほど気を失うように仮眠して持ち直し、30〜40分の試合は「最高の出来」になったという。試合前に不安を口にするたび、妻のキムに「あなたはプロよ、いつもそうなる」と言われるそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（51:43〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=3103s"]]}, {"cat": "リングの話", "t": "子どもの頃の自分に贈りたいプロレスの品", "b": "ランディ・オートンは、過去の自分に贈るならと聞かれ、プロレスの品だと答える。父が着けていたギプスを一つ持っているが、そこに父の帽子と、ロディ・パイパーのキルトを加えたいという。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:36:18〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=5778s"]]}]);
  if (!PROFILES["Randy Orton"]) PROFILES["Randy Orton"] = { lead: "脊椎固定術のあとに続いたパニック発作と、抗不安薬を飲んでいた日々を率直に明かした。5人の子と妻キムへの感謝、筋金入りの甘党ぶりも笑いながら語っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Randy%20Orton"]], moves: [], facts: [] };
  if (PROFILES["Randy Orton"]._weak) { PROFILES["Randy Orton"].lead = "脊椎固定術のあとに続いたパニック発作と、抗不安薬を飲んでいた日々を率直に明かした。5人の子と妻キムへの感謝、筋金入りの甘党ぶりも笑いながら語っている。"; delete PROFILES["Randy Orton"]._weak; }
  PROFILES["Randy Orton"].facts.push(...[{"cat": "リングに来るまで", "t": "1999年秋に育成契約を結んだ", "b": "WWEの育成契約を結んだのは1999年10月で、初めてリングで受け身を取ったのは翌年1月だという。テレビデビューからは約23年、キャリアは25年ほどになると数える。長く続けるうちに、忘れてしまったことの多さに驚くと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（10:45〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=645s"]]}, {"cat": "リングに来るまで", "t": "24歳の初戴冠、会場に最後まで残った", "b": "24歳で世界王座を初めて取った夜、借りた電話で父と、たしか祖父にも電話をかけたそうだ。会話の中身は覚えていないが、感情があふれたことは覚えているという。トロントの会場に最後まで一人で残り、ベルトをひざに置いて「本当なのか」と繰り返していたと振り返る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（11:42〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=702s"]]}, {"cat": "暮らし", "t": "自分のフィギュアにいまも慣れない", "b": "子どもと店に行き、棚に並ぶ自分のアクションフィギュアを見ても、いまだに実感がわかないという。人生には浮き沈みや個人的な問題もあったが、分かれ道ではいつも業界の誰かが正しい方へ導いてくれたと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（13:29〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=809s"]]}, {"cat": "リングに来るまで", "t": "恩人の筆頭はトリプルH", "b": "一番の恩人にはトリプルHを挙げ、本人も気づいていなかった素質を早くから見抜いてくれたと話す。若くして天狗になり真剣さを欠いた時期も見捨てずにいてくれたという。ほかにアンダーテイカー、ショーン・マイケルズ、リック・フレアーの名を挙げ、いまは自分が若手に助言する側になったと語る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（14:20〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=860s"]]}, {"cat": "体のこと", "t": "若い頃の無茶を「生きていて幸運」と語る", "b": "若い頃にひどい判断をいくつもしたと認め、生きているのが幸運だと思う、と口にしている。具体的な中身は語っていない。そうした時期に先輩たちがまっすぐにしてくれたと振り返る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（15:08〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=908s"]]}, {"cat": "体のこと", "t": "家族が増えてパニック発作が始まった", "b": "妻キムと出会い、3人の継息子と2人の娘を抱えるようになってから、気持ちが追いつかなくなりパニック発作が出始めたという。飛行機に乗ることや、自宅以外のベッドで眠ることがつらくなり、一晩中眠れない夜もあったそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（17:31〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1051s"]]}, {"cat": "体のこと", "t": "脊椎固定術で約1年半リングを離れた", "b": "症状が最も重くなったのは、脊椎固定術を受けて1年半ほど欠場した時期だという。半年ほどは引退するしかないと思い込み、「自分が得意で尊敬される唯一のこと」を失った感覚だったと話す。カリフォルニア州ニューポートビーチの医師に、筋肉を切らずに済む手術をしてもらい、選手に戻れたそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（18:22〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1102s"]]}, {"cat": "体のこと", "t": "抗うつ・抗不安薬を数年飲んでいた", "b": "暗い時期に昔の悪い習慣へ戻りかけたが、妻が早く気づき、抗うつ・抗不安の薬を処方されたという。夜は横になると考えが止まらず、家族が寝ている間に庭を歩いて深呼吸していたそうだ。薬は自分らしさを失う感じがして好きではなかったが、数年続け、収録の約半年前にやめた。それ以来、発作は起きていないと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（19:08〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1148s"]]}, {"cat": "体のこと", "t": "打ち明けたのは妻と医療スタッフだけ", "b": "当時はひとりで抱えている感覚で、話した相手は妻と担当のセラピストくらいだったという。復帰後は会社の医療スタッフに服薬を伝え、同じような薬を飲む人は珍しくないと聞いて、孤独感が和らいだそうだ。いまは話すこと自体が治療のように感じると語っている。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（21:44〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1304s"]]}, {"cat": "家族", "t": "泣く姿を見たことがない父", "b": "発作が出ても、強い父親でいたくて末娘には隠していたという。自分の父は知る限り一番タフな男で、泣いたところを一度も見たことがないそうだ。だからこそ「なぜ自分は」と悩んだと振り返る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（23:21〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1401s"]]}, {"cat": "家族", "t": "5人の子のうち3人が車持ち", "b": "息子たちは22歳、20歳、もうすぐ16歳になり、5人の子のうち3人が車を持っているという。家の前が中古車販売店のようで、ナンバー更新やオイル交換に追われていると笑う。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（24:11〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1451s"]]}, {"cat": "家族", "t": "子どもの行事に顔を出せるようになった", "b": "スケジュールに融通がきくようになり、卒業式や誕生日、ソフトボールやバレーボールの試合に行けるようになったと喜ぶ。末の息子はフットボールとレスリングをこなし、バスケや陸上にも手を出す「3競技の子」だという。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（28:15〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1695s"]]}, {"cat": "体のこと", "t": "けがを理解するトレーナーで体が変わった", "b": "人生で初めて、自分のけがを理解して個別にメニューを組むトレーナーに出会ったという。もともと太もも前側に頼る体で、背中やもも裏、お尻が弱かったことが今回の故障につながったと説明されたそうだ。いまは自重中心の地味な練習で、フォームや止める時間、どこに効いているかを意識していると話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（30:35〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1835s"]]}, {"cat": "体のこと", "t": "休養中の冬に300ポンドを超えた", "b": "以前はプロテインをミキサーで混ぜて済ませる食生活だったが、肉などからたんぱく質をとるように変えたという。体重は240〜250ポンドほどだったが、休みの冬には300ポンドを超えたそうだ。その後は体重を保ったまま脂肪を筋肉に置きかえていったと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（32:57〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1977s"]]}, {"cat": "好きなもの", "t": "自称「地獄の甘党」", "b": "大の甘党で、クリスマスにはチョコとキャラメル味のポップコーン缶を2晩で空けたと明かす。一番好きなのは「ハンクス」というダークチョコ入りのオートミールクッキーだそうだ。シリアルにチョコチップをのせるのも好物で、食事に厳しいトリプルHの目を盗んで食料庫でお菓子を食べ、見つかったこともあるという。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（33:42〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2022s"]]}, {"cat": "暮らし", "t": "何でも入ったバッグを持ち歩く", "b": "どこへでも持ち歩くバッグには、つまようじ、リップクリーム、ハンドクリーム、アイマスク、耳栓、鎮痛薬などが入っているという。SNSで見つけた小型の扇風機は10個も買ったそうだ。出会った頃の妻にはあきれられたが、ときどき家族の役に立つと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（36:10〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2170s"]]}, {"cat": "家族", "t": "娘の誕生日を会場全体で祝った", "b": "末娘の誕生日がブルックリンの大会と重なり、リングに上げて観客にハッピーバースデーを歌ってもらったという。うまくいくか不安で迷ったが、マット・リドルに背中を押されて決めたそうだ。最近のファンイベントでは、娘が隣で誇らしげにしている姿に胸を打たれたと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（41:05〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2465s"]]}, {"cat": "暮らし", "t": "娘の手書きの名前をタトゥーに", "b": "腕には、末娘が自分で書いた名前と小さなハートをそのまま彫ったタトゥーがあるという。6歳ごろの娘に「サプライズがある」と伝えたら、おもちゃを期待されてがっかりされたと笑う。いまでは一番気に入っているタトゥーだそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（55:43〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=3343s"]]}, {"cat": "家族", "t": "継息子も「自分の子」と思う", "b": "高校生の長女はバレーボールで全国大会に出ていて、成績も優秀だという。母親と暮らしているため離れていることを気にかけ、家族で出かけるときは彼女も来られる日にするそうだ。継息子たちも自分の子と同じに思っているが、実の父から電話が来るたび複雑な気持ちになると語る。家族でニューヨークからミズーリ州セントルイスへ移ったことも、子どもたちには大きな変化だったと振り返る。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:00:38〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=3638s"]]}, {"cat": "暮らし", "t": "真夜中の食料庫でシリアルを食べる", "b": "妻にお菓子を隠してもらうと自分で探し出してしまうため、息子たちは好きなシリアルを自分の部屋に置くようになったという。夜中に食料庫で目を閉じたまま大袋のシリアルを食べていて、妻に見つかったこともあるそうだ。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:05:38〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=3938s"]]}, {"cat": "家族", "t": "看護師の母と、苦しかった子ども時代", "b": "父の稼ぎが不安定で、子どもの頃に一家で自己破産を経験したという。夏にはジーンズを切って短パンにし、安い靴をはいていたそうだ。父は半ば引退後に約20年車を売り、母は彼が高校生の頃に看護学校へ通って看護師になった。盲腸が破裂した父を病院へ運んで命を救ったのも母だと話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:18:26〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=4706s"]]}, {"cat": "家族", "t": "妻キムから学んだ「自分は最後」", "b": "妻は毎晩子ども一人ひとりの好みに合わせて料理を作り、自分が食べるのは最後だという。家にいる夜は、映画を観ながらずっと妻の足をもんでいるそうだ。妻が子どもたちのためにしたことを、本人のいないところで息子たちに伝えるようにしていると話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:19:16〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=4756s"]]}, {"cat": "暮らし", "t": "家に入る前に「セルフチェック」", "b": "移動疲れでいら立ったまま帰ると家族に伝わるため、家に入る前に自分の気分を確かめるようにしているという。収録の朝もホテルの水が茶色く出て遅刻したが、昔の自分なら周りに当たっていたところを抑えられたそうだ。間違えたときは子どもの前で謝ることも大事にしていると話す。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:29:06〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=5346s"]]}, {"cat": "好きなもの", "t": "少年時代の自分に贈るならパイパーのキルト", "b": "子どもの頃の自分に贈りたい品を聞かれ、ロディ・パイパーのキルトを挙げた。父が試合で着けていたギプスと帽子はすでに手元にあるといい、それとキルトをそろえたいそうだ。スポーツはあまり観ないので、プロレスに絞って選んだと話している。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-UObUiKCwwN8", "src": [["公式YouTube（1:36:18〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=5778s"]]}]);
  if (PROFILES["Sheamus"]) PROFILES["Sheamus"].facts.push({"cat": "暮らし", "t": "筋トレ企画を4年かわしていた", "b": "シェイマスの筋トレ企画への出演を4年ほど断り続けていたが、ついに自宅の小さなガレージジムで撮ることになったという。鍛えたい部位を聞かれて腕と答え、軽いダンベルを持ち出してあきれられたと、ランディ・オートンが話している。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で、ランディ・オートンの話（公式字幕を全文確認）", "src": [["公式YouTube（28:15〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=1695s"]], "by": "第三者の話"});
  if (PROFILES["Matt Riddle"]) PROFILES["Matt Riddle"].facts.push({"cat": "暮らし", "t": "娘をリングに上げる決断を後押し", "b": "娘の誕生日を会場で祝うか迷っていたとき、マット・リドルが「やれよ」と強く勧めてくれたという。彼がいなければやらなかった、と、ランディ・オートンが話している。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で、ランディ・オートンの話（公式字幕を全文確認）", "src": [["公式YouTube（41:05〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=2465s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "昔の失敗をいじられても受け止める", "b": "復帰したばかりのショーン・マイケルズが、親友のトリプルHらに昔の失敗を蒸し返されている場面を見てきたという。自分も同じように昔の振る舞いをいじられる立場になったと、ランディ・オートンが話している。", "sp": "ランディ・オートン", "d": "2025-07-03", "how": "ステファニーの番組で、ランディ・オートンの話（公式字幕を全文確認）", "src": [["公式YouTube（1:33:06〜）", "https://www.youtube.com/watch?v=UObUiKCwwN8&t=5586s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-UObUiKCwwN8", d: "2025-07-03", show: "wys", who: ["Randy Orton"], t: "ランディ・オートンの回　パニック発作と回復、5人の子の父としての素顔", lead: "ステファニー・マクマホンの番組に出た約97分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Randy Orton"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-UObUiKCwwN8").map((x) => [x.t, x.b, x.sp])), open: ["若い頃の「ひどい判断」について本人は具体的に語っておらず、中身は書いていない。", "字幕の話者表示が途中で入れ替わっているため、文脈で判断した。同席スタッフのエリスの体験談など、ゲスト以外の話は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=UObUiKCwwN8"]] });
