  if (PROFILES["Ricky Saints"].lead === "") PROFILES["Ricky Saints"]._weak = 1;
  PROFILES["Ricky Saints"].facts.push(...[{"cat": "リングの話", "t": "自腹の映像でキャラを売り込んだ", "b": "リッキー・セインツは、インディー時代に自分のキャラクターを見せる映像集を自腹で作っていたという。まだ前座で、客を沸かせる立場ではなかったそうだ。その映像がNWAの関係者の目に留まって契約につながったが、途中で「ここには天井がある」と感じて更新を断ったと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（6:28〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=388s"]]}, {"cat": "リングの話", "t": "控室の床で聞いた「撮り直せばいい」", "b": "2012年のSmackDownで、リッキー・セインツはエキストラとして控室の床で着替え、初めての試合前に緊張していたという。そこでコーディに「収録番組だから失敗してもやり直せばいい」と言われ、肩の力が抜けたと話す。実際の試合では相手の手が重く、顔の片側にあざができたそうだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（10:24〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=624s"]]}, {"cat": "リングの話", "t": "炎のテーブルでやけどをした直後の呼び出し", "b": "NWAを辞めた直後、リッキー・セインツはサミの動画企画で炎のテーブルを突き破り、レザーのパンツに火が移って「死ぬかと思った」と話す。2度のやけどを負ったが、3週間ほどでコーディの番組の挑戦者募集に呼ばれたという。契約は取れないと思い、インディーで報酬を上げるための実績にするつもりだったそうだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（12:51〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=771s"]]}, {"cat": "リングの話", "t": "「今月の名勝負」止まりと言われた試合", "b": "試合後、コーディに「いい仕事だった」と声をかけられたと、リッキー・セインツは振り返る。試合前には「年間最高試合になる」と言ったが、コーディには「月間最高くらいだろう」と返されたそうだ。放送後に契約のオファーが届き、一人きりの部屋で泣きながら、ツイッターの反応を眺めたという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（13:38〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=818s"]]}, {"cat": "リングの話", "t": "NXTの電話は空港のトラムの中で", "b": "リッキー・セインツは、シアトルの空港に着いた直後、知らない番号からの電話に出たらトリプルHだったと話す。空港が騒がしく聞き取りづらかったが、誘いを即座に受けたという。ショーン・マイケルズに会わせてもらえる話が一番うれしく、自分は磨けば光る原石だと思っていたそうだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（15:12〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=912s"]]}, {"cat": "リングの話", "t": "客席と舞台裏から学んだプロレス", "b": "リッキー・セインツは、基本はトレーナーに教わったが、本当にプロレスを学んだのは会場の客席に座って人の動きを見たり、舞台裏の会話を耳にしたりしたからだと話す。2012年から会社の近くにいたので、自然と身についたという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（23:10〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1390s"]]}, {"cat": "リングの話", "t": "NXTと呼ばれても、目指すのは本隊", "b": "リッキー・セインツは、NXT所属と言われても「WWEスーパースターだ」と答えたくなる自分がいると話す。一方で、今の環境は楽しいと感じているそうだ。インディー出身ではない選手のやり方を見たり、逆に質問を受けたりするのも新鮮で、コーディからは更衣室のリーダーの一人に名前が挙がったと聞いて誇らしかったという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（27:11〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1631s"]]}, {"cat": "リングの話", "t": "友情を理由に叩かれても退かない", "b": "コーディとの親しさで評価が揺れないかと聞かれ、リッキー・セインツは「友情を武器に使わせない」と答える。親友の晴れ舞台に駆けつけたことで怒られるのは筋が通らず、リングとマイクで見せればいい、後悔はしていないと話す。ロイヤルランブルの日に会場へ行ったのも、特別な瞬間にその場にいたかったからだという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（46:25〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2785s"]]}, {"cat": "リングの話", "t": "思い出のコスチューム、最初の2つ", "b": "リッキー・セインツは、特別なコスチューム4つのうち1つ目に、スティングの引退試合が続いたころの対戦で着たものを挙げる。2つ目はコーディと戦ったデビュー戦のもので、そのときショーツの鎖を引きちぎられて以来、一度も着ていないそうだ。ほかにニューオーリンズ・セインツのドリュー・ブリーズのジャージも選んだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（48:55〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2935s"]]}, {"cat": "リングの話", "t": "友人のジェイドと、常に練習している", "b": "リッキー・セインツは、親友のジェイドと一緒に何度も練習していると話す。ともに受け身を取り、同じ熱量の相手と動くのが好きだという。自分のプロレスは型にはまらないので、売り方など学んだことを教えることもあるそうだ。ジェイドの初戦と王座獲得を見届けた昨年の大会は、自分のことのようにうれしかったと語る。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（57:46〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=3466s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Ricky Saints")) ROSTER.push(["リッキー・セインツ", "Ricky Saints", "lg", "NXTの選手", "", "", ""]);
  if (!PROFILES["Ricky Saints"]) PROFILES["Ricky Saints"] = { lead: "ニューオーリンズに生まれ、カトリーナ後はラスベガス、オースティンへと移り住んだ。自腹で作った映像で道を切り開き、「見てもらう、聞いてもらう、分かってもらう」ことを何より大切にしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ricky%20Saints"]], moves: [], facts: [] };
  if (PROFILES["Ricky Saints"]._weak) { PROFILES["Ricky Saints"].lead = "ニューオーリンズに生まれ、カトリーナ後はラスベガス、オースティンへと移り住んだ。自腹で作った映像で道を切り開き、「見てもらう、聞いてもらう、分かってもらう」ことを何より大切にしている。"; delete PROFILES["Ricky Saints"]._weak; }
  PROFILES["Ricky Saints"].facts.push(...[{"cat": "リングに来るまで", "t": "自腹で作ったキャラクター映像", "b": "インディーでは前座が多かったが、自分のキャラクターを見せる映像を自腹で作ってSNSに載せていたという。それがニック・オルディスの目に留まり、別団体の記念大会に呼ばれて初めての契約を結んだそうだ。しかし「天井がある」と感じて再契約を断り、パンデミック中は自分でデザインしたシャツをネットで売って暮らし、その売上で次の映像を作ったと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（6:28〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=388s"]]}, {"cat": "暮らし", "t": "恋人に求めるのは「理解」", "b": "3年前に別の番組で独身だと話したが、今も独身だという。相手に求める条件は前より増えたが、いちばんは理解してくれる人であることだそうだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（8:51〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=531s"]]}, {"cat": "リングに来るまで", "t": "トイレの床で着替えたエキストラ時代", "b": "2012年、テキサス州ラレドでの収録にエキストラとして呼ばれ、着替える場所がなくトイレの床で支度をしたという。緊張していると話すと、隣で歯を磨いていたコーディに「収録だからしくじったら撮り直せばいい」と言われ、気が楽になったそうだ。試合後は顔の片側があざだらけになったと振り返る。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（10:24〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=624s"]]}, {"cat": "体のこと", "t": "燃えるテーブルで脚にやけど", "b": "仲間のレスラーの動画企画で、合皮のパンツをはいたまま火のついたテーブルに突っ込み、服に火が燃え移ったという。人生が走馬灯のように見え、本気で死ぬかと思ったそうだ。脚に2度のやけどを負ったが、約3週間後に大きな仕事の電話が来たころには、ほぼ治っていたと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（12:51〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=771s"]]}, {"cat": "リングに来るまで", "t": "契約の知らせに部屋で一人泣いた", "b": "テレビ出演の話が来たときは、契約は期待しておらず、インディーのギャラを上げる材料にするつもりだったという。ところが放送後にメッセージで契約の申し出が届き、アパートで一人泣いたそうだ。SNSにも反響が一気に押し寄せたと振り返る。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（13:38〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=818s"]]}, {"cat": "暮らし", "t": "知らない番号の電話にも必ず出る", "b": "知らない番号からの電話でも「冒険が好きだから」と必ず出るという。トリプルHからの誘いの電話もシアトルの空港で受けたが、騒がしくてよく聞き取れず、聞き返せないまま「はい」と答え続けたそうだ。何より望んでいたのはショーン・マイケルズのもとで学ぶことで、自分は磨けば光る原石だと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（15:12〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=912s"]]}, {"cat": "リングに来るまで", "t": "故郷は3つ、生まれはニューオーリンズ", "b": "ニューオーリンズで生まれ育ち、ハリケーン・カトリーナをきっかけにラスベガスへ移ったという。その後、看護師の母により良い仕事の口があったことから、テキサス州オースティンに移り住んだそうだ。そのため「地元が3つある」と話し、コーディにはからかわれている。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（17:36〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1056s"]]}, {"cat": "家族", "t": "いちばん大切なのは母", "b": "自分にとっていちばんは母だと話す。コーディが母に会ったときは、母がその場を仕切る人のようにふるまい、笑いになったという。WWE入りの前には母から「家を空けることが増えるのは分かっているの？」と電話で念を押されたが、長くこの世界のそばにいたので覚悟はできていると伝えたそうだ。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（18:24〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1104s"]]}, {"cat": "リングに来るまで", "t": "デビューは2011年10月", "b": "最初のトレーナーは、ロディ・パイパーとよく組んでいたことが自慢の人で、基本はその人から学んだという。2011年10月にデビューし、翌年1月にはWWEからエキストラの声がかかったそうだ。ただ、本当にプロレスを覚えたのは、裏で先輩たちの打ち合わせを見たり会話に耳をすませたりして、自然に身につけたおかげだと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（21:32〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1292s"]]}, {"cat": "暮らし", "t": "マイクロソフトの店で働いていた", "b": "当時はマイクロソフトの店舗で働いていたという。WWEに呼ばれた日、そりの合わない同僚に「契約するから辞める」と告げて休憩から戻らず、エキストラの仕事へ向かったそうだ。結局は職場に戻り、飼ってもいない犬が死んだことにして許してもらい、すぐにゲーム機を売る仕事に戻ったと笑う。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（22:22〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1342s"]]}, {"cat": "好きなもの", "t": "ニューオーリンズの食の案内人", "b": "大の食通だが、ラスベガスの食にはこだわらないという。ニューオーリンズでは、観光地から離れたガソリンスタンド併設のポーボーイ店を勧め、えびだけを山盛りにしてケチャップとピクルスを添えるのがいつもの注文だそうだ。ベニエはカフェ・デュ・モンドで深夜2時ごろに食べるのが最高だと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（30:15〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1815s"]]}, {"cat": "暮らし", "t": "誰にも教わらず手探りで", "b": "コーヒーはコールドブリューで、それ以前は何も入れずに飲んでいたという。ネクタイの結び方も知らないそうで、「正しいやり方を誰にも教わってこなかったことが多い」と話す。私生活でもプロレスでも、手探りでやってきたという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（32:36〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1956s"]]}, {"cat": "リングに来るまで", "t": "肌の色をめぐり、けんか続きの学校時代", "b": "クレオールの血を引き肌の色が明るく、ニューオーリンズ東部の、黒人の生徒がほとんどの学校に通っていたという。白人だと思われてもめ事が絶えず、幼稚園から9年生ごろまでほぼ毎週けんかになり、そのたびに母が仕事を休んで学校に来ていたそうだ。自分から挑発したこともあったと認めている。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（36:45〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2205s"]]}, {"cat": "体のこと", "t": "短気と向き合ったカウンセラー室", "b": "幼いころはひどく短気で、一気に頭に血がのぼるたちだったという。学校ではカウンセラーの部屋に通い、「これはプライドの問題か、筋の問題か」と自分に問いかけて、流せることは流す練習をしたそうだ。最後は、ありのままの自分を受け入れることで乗り越えたと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（38:23〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2303s"]]}, {"cat": "暮らし", "t": "どこにもなじめない孤独", "b": "家族の多くは自分より肌の色が濃く、黒人の側にも白人の側にもなじめない孤独を抱えて育ったという。大人になった今も、情熱や言い方を誤解され、理解されていないと感じることがあるそうだ。「見てもらえる、聞いてもらえる、分かってもらえる」、その3つさえあればいいと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（39:56〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2396s"]]}, {"cat": "暮らし", "t": "友情を武器にはさせない", "b": "家族は多くなく、友人と呼べる人も少ないという。だからこそ分かってくれる人への思いは深く、何気ないメッセージ1通が何よりうれしいそうだ。コーディの晴れ舞台を会場で見届けて喜ぶ姿が広まったことも、まったく後悔していないと言い切る。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（46:25〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2785s"]]}, {"cat": "好きなもの", "t": "宝物はドリュー・ブリーズのジャージー", "b": "思い入れのあるユニフォームとして、地元セインツの名クォーターバック、ドリュー・ブリーズの2009年のジャージーを挙げた。自分の衣装では、スティングの現役最後から2番目の試合で着たものと、デビュー戦の衣装を大切にしているという。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（48:55〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2935s"]]}, {"cat": "好きなもの", "t": "子どものころのいちばんはテイカー", "b": "子どものころ好きだった選手はアンダーテイカー、ミック・フォーリー、ザ・ロックの3人で、なかでもアンダーテイカーがいちばんだという。今では育成施設で顔を合わせると、昔のプロレス談義で冗談を言い合う仲だそうだ。ドリームチームには俳優マシュー・マコノヒーや、同郷の歌手ハリー・コニック・ジュニアの名も挙げた。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（52:12〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=3132s"]]}, {"cat": "好きなもの", "t": "ガンビット役は自分のほうが本物", "b": "映画でのガンビットの描かれ方は気に入らなかったという。演じたチャニング・テイタムは良い俳優だと認めつつ、自分なら本物らしく、もっとうまくやれると話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（54:33〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=3273s"]]}, {"cat": "暮らし", "t": "コーディの道場でジェイドと特訓", "b": "コーディが開いたプロレス学校によく通い、業界でいちばんの親友ジェイド・カーギルと練習しているという。同じ熱量の相手と組むのが好きで、受け身を取りすぎて心配になるほど激しく練習するそうだ。自分が学んだことを人に伝えるのも好きで、自分のプロレスの理解は少し型破りだと話す。", "sp": "リッキー・セインツ", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（57:46〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=3466s"]]}]);
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "暮らし", "t": "「今使え、また稼げ」の本当の由来", "b": "若いころ、交際相手に車を買ったが、別れて車は相手のもとに残ったという。走り去る車を見送って落ち込む自分に、アーン・アンダーソンがかけたのが「金は今使え、また稼げばいい」という有名な言葉の始まりだそうだ。本人は「ひどい助言だ」と笑う。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（3:17〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=197s"]]}, {"cat": "暮らし", "t": "ネクタイはニック・オルディス仕込み", "b": "ずっと自己流の結び方でネクタイを締めていたが、それでは通用しないと正しい結び方を教えてくれたのはニック・オルディスだったという。「これから大事な場に出ることになる」と言われたそうだ。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（5:39〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=339s"]]}, {"cat": "暮らし", "t": "友情の条件は「一緒に押してくれるか」", "b": "業界では本当の友人はなかなかできないとして、「友達」という言葉はあまり好きではないという。関係を車に例え、ガス欠になったときに降りて一緒に押してくれるかどうかが唯一の条件だそうだ。友情のルールは「必要なときに顔を出すこと」だとも話す。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（9:37〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=577s"]]}, {"cat": "暮らし", "t": "予告編で泣くほど涙もろく", "b": "かつてはまったく感情を出さない人間だったが、ある時期から堰を切ったように涙もろくなったという。映画「リロ&スティッチ」の予告編を見ただけで顔がぐしゃぐしゃになったそうだ。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（14:26〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=866s"]]}, {"cat": "家族", "t": "父は生粋のテキサス人", "b": "父ダスティ・ローデスは生粋のテキサス人だったという。テキサス人同士には、言葉以上の独特の通じ合い方があり、それをうらやましく、かっこいいと感じているそうだ。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（16:50〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=1010s"]]}, {"cat": "リングに来るまで", "t": "恩人はオートンとシナ", "b": "2007〜08年ごろに上がってきたとき、ランディ・オートンやジョン・シナに目をかけてもらったという。一方、団体を離れて自分で活動していたころは誰とでも親しくしたが、年間最大の祭典で戻ったとき連絡をくれたのは片手で数えるほどだったそうだ。その経験から、若手を自分の下に抱え込むことにはためらいがあると話す。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（33:26〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2006s"]]}, {"cat": "暮らし", "t": "酔うと昔の仲間を褒めたくなる", "b": "育成時代の仲間に、今でも時々酔って「お前はすごいレスラーだ」と突然メッセージを送ってしまうという。コフィ・キングストンに送ったこともあるそうだ。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（43:06〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2586s"]]}, {"cat": "暮らし", "t": "素顔は物静か、スーツは先入観破り", "b": "仕事のイベントでは控えめで静かなので、「これが連れてきたレスラー？」と思われがちだという。スーツを着るようになったのも、レスラーへの先入観を変えたかったのが理由のひとつだそうだ。", "sp": "コーディ・ローデス", "d": "2025-07-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-uytj31qK8sM", "src": [["公式YouTube（44:47〜）", "https://www.youtube.com/watch?v=uytj31qK8sM&t=2687s"]]}]);
  ARTICLES.push({ id: "wdywta-uytj31qK8sM", d: "2025-07-09", show: "wdywta", who: ["Ricky Saints", "Cody Rhodes"], t: "リッキー・セインツの回　3つの故郷と、自腹の映像から始まった道", lead: "コーディ・ローデスの番組に出た約61分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ricky Saints", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-uytj31qK8sM").map((x) => [x.t, x.b, x.sp])), open: ["エキストラ時代の対戦相手や、やけどをした動画企画の仲間の名前は字幕から確定できず、名前を出していない。", "家族の肌の色の話の流れで出た、コーディの娘に触れた発言は、話者と文脈が追い切れず載せていない。", "舞台裏で「にらまれた」件やNXTの仲間（イーサン・ペイジら）の話は、素顔の話に関わる部分だけにとどめた。", "番組スポンサーの酒にまつわるやりとりや、プロレス学校での教え方の話は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=uytj31qK8sM"]] });
  if (!ROSTER.find((r) => r[1] === "Booker T")) ROSTER.push(["ブッカーT", "Booker T", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Booker T"]) PROFILES["Booker T"] = { lead: "自分の名場面を映像で見返しながら、兄とのデビューからキング・ブッカーまでを振り返る。刑務所を経てレッスルマニアの舞台に立った道のりを、笑いを交えて語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Booker%20T"]], moves: [], facts: [] };
  if (PROFILES["Booker T"]._weak) { PROFILES["Booker T"].lead = "自分の名場面を映像で見返しながら、兄とのデビューからキング・ブッカーまでを振り返る。刑務所を経てレッスルマニアの舞台に立った道のりを、笑いを交えて語る。"; delete PROFILES["Booker T"]._weak; }
  PROFILES["Booker T"].facts.push(...[{"cat": "リングに来るまで", "t": "兄と吹雪の中20時間かけて", "b": "兄と2人、愛車で吹雪の中を約20時間走ってテキサス州アマリロへ行ったのが始まりだという。そこで知り合ったプロモーターに誘われ、3か月後に兄のトライアウトについて行ったところ、エディ・ギルバートの目に留まってタッグを組むことになったと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（0:01〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1s"]]}, {"cat": "リングの話", "t": "WCW入りしてシッドの家に居候", "b": "テレビ中継のあった団体で戦っていたころ、会場にシッド・ヴィシャスから電話があり、WCWに誘われたという。WCWに移ってしばらくは、兄と2人でシッドのアパートに住まわせてもらっていたそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（1:41〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=101s"]]}, {"cat": "リングの話", "t": "最初の衣装は自分の手作り", "b": "ハーレム・ヒートの最初の衣装は自分の発案で、カントリー歌手のシャツを切り、袖の布で帽子まで作ってもらったという。お金がなかったので、あるものでやりくりしたと振り返る。チーム名はダスティ・ローデスが付け、最初の案は寒いシカゴにちなんだ名前だったそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（2:33〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=153s"]]}, {"cat": "リングの話", "t": "自信をくれたのはダスティ", "b": "若手のころ一番自信をくれたのはダスティ・ローデスだったという。第1試合で会場を沸かせて戻ると「もう第1試合には出されないぞ」と言われ、認められたと感じたと話す。ダスティは自分を「T・ブック」と呼び、今そう呼ぶのは息子のコーディだけだそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（4:49〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=289s"]]}, {"cat": "リングの話", "t": "負け続きからのタッグ王座", "b": "WCWに来たころはハウスショーや海外遠征で一度も勝てないほどだったが、テレビでは支持されていたという。初めてタッグ王座を取れたのはマネージャーのシェリー・マーテルのおかげで、その夜はシャンパンを開けて喜んだと振り返る。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（6:22〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=382s"]]}, {"cat": "リングの話", "t": "ブーツ忘れで転がり込んだ王座", "b": "初めてのテレビ王座は、本来ベルトを巻くはずだったリック・マーテルがリングシューズを忘れたため、代わりに自分が王者になったのだという。つなぎの王者のつもりでも、渡すものかと思って戦い、最終的に6回王者になったと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=487s"]]}, {"cat": "好きなもの", "t": "ブレット・ハートの大ファン", "b": "子どものころからブレット・ハートの大ファンで、WCWに来ると聞いて対戦を夢見たという。実際に向き合ったときはファンの顔を見せまいと、最初にほぼ全力で突き飛ばしたそうで、その試合だけは昨日のことのように覚えていると話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（10:36〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=636s"]]}, {"cat": "リングの話", "t": "試合10分前に知った世界王座戦", "b": "初めて世界王座を取った夜は、別の試合を終えて帰ろうとしていたところ、10分前に王座戦を告げられたという。その夜は飲みにも行かず、ベッドの端に30分座り込んで動けなかったそうだ。黒人の王者がファンに受け入れられるかを考え、先人ロン・シモンズの後を継ぐ重みを感じたと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（13:09〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=789s"]]}, {"cat": "リングの話", "t": "WCW最後の夜に二冠", "b": "団体が売却され、仲間の多くが次の仕事を案じる中、最終回で世界王者とUS王者を兼ねたという。何事も永遠には続かないと考えていたので、次に備えていたと振り返る。WWEでは一からはい上がるつもりで、教え子にも「まず控室でやっていけないとリングでは成功できない」と伝えているそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（17:11〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1031s"]]}, {"cat": "リングの話", "t": "スーパーでの乱闘と小麦粉", "b": "ストーン・コールドとスーパーマーケットで乱闘した場面は一発撮りだったという。髪に小麦粉がつきすぎて3回洗ったそうだ。半年ほど前に初めて見返したときは、良い娯楽だと思って涙が出たと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（19:31〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1171s"]]}, {"cat": "リングの話", "t": "ゴールダストとの名コンビ", "b": "ゴールダスト（ダスティン・ローデス）とは昔からの友人で、性格の違う2人が組んだことで化学反応が起きたという。「これでお金がもらえるなんて」と2人で言い合っていたほど楽しい時期だったと振り返る。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（22:06〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1326s"]]}, {"cat": "リングに来るまで", "t": "高校中退と刑務所を経て", "b": "テキサスの下町で育ち、高校を中退して刑務所に入ったこともあるという。そこからはい上がり、レッスルマニアでトリプルHと王座戦をしたことは、負けたとしても人生最大の勝利だったと話す。教え子には「負けを勝ちより良いものにしろ」と伝えているそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（24:30〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1470s"]]}, {"cat": "好きなもの", "t": "笑いをこらえるコメディが好き", "b": "子どものころ見ていたコメディ番組で、演者が笑いをこらえきれなくなる場面が大好きだったという。キング・ブッカーを演じていたときも、内心はずっと笑いをこらえていたそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（25:18〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1518s"]]}, {"cat": "リングの話", "t": "キング・ブッカーは一番の誇り", "b": "キング・ブッカーの小指を立てる仕草は、マッチョマン・ランディ・サベージへの敬意だったという。脇役のはずの役を番組の中心にまで押し上げ、王の姿で世界王座を取ったことが、キャリアで一番誇らしいと話す。今でも行く先々で「キング」と呼ばれるそうだ。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（26:54〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1614s"]]}, {"cat": "リングの話", "t": "久々の試合で祈った1回転", "b": "久しぶりにリングに上がった試合では、得意の回転技スピナルーニーの前に「1回転だけでいい」と神に祈ったという。コーナーで見ていたシェイマスが、子どものようにのぞき込んでいたのがうれしかったと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（29:19〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1759s"]]}, {"cat": "家族", "t": "102歳まで生きた祖父", "b": "祖父は1889年生まれで、102歳まで生きたという。祖父の人生を振り返る写真があったら見たかったと語り、自分のキャリアを映像で見返すのは不思議な気分だと話す。", "sp": "ブッカーT", "d": "2025-07-11", "how": "WWE公式の回顧番組（WWE Vault）で（字幕を全文確認）", "art": "ext-AOMSvEb7hV4", "src": [["番組のYouTube（31:44〜）", "https://www.youtube.com/watch?v=AOMSvEb7hV4&t=1904s"]]}]);
  ARTICLES.push({ id: "ext-AOMSvEb7hV4", d: "2025-07-11", show: "ext", who: ["Booker T"], t: "ブッカーTの回　名場面を見ながら振り返るキャリア", lead: "WWE公式の回顧番組（WWE Vault）に出た約33分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Booker T"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-AOMSvEb7hV4").map((x) => [x.t, x.b, x.sp])), open: ["試合の細かい展開の解説は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=AOMSvEb7hV4"]] });
  if (!ROSTER.find((r) => r[1] === "Matt Matthews")) ROSTER.push(["マット・マシューズ", "Matt Matthews", "lg", "コメディアン", "", "", ""]);
  if (!PROFILES["Matt Matthews"]) PROFILES["Matt Matthews"] = { lead: "アラバマ出身の人気コメディアン。苦しい家庭で育ち「二度と貧乏には戻らない」という思いで成功をつかんだ。今は広い土地で馬や動物たちと暮らしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Matt%20Matthews"]], moves: [], facts: [] };
  if (PROFILES["Matt Matthews"]._weak) { PROFILES["Matt Matthews"].lead = "アラバマ出身の人気コメディアン。苦しい家庭で育ち「二度と貧乏には戻らない」という思いで成功をつかんだ。今は広い土地で馬や動物たちと暮らしている。"; delete PROFILES["Matt Matthews"]._weak; }
  PROFILES["Matt Matthews"].facts.push(...[{"cat": "体のこと", "t": "バスケで前十字じん帯を断裂", "b": "収録の少し前、バスケットボール中に濡れた床で足を取られ、ひざの前十字じん帯を切ったという。手術の前にまずリハビリでひざを曲げられるようにする必要があるそうだ。体重管理のため栄養素の量も記録していると話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=46s"]]}, {"cat": "暮らし", "t": "毎週末6公演のツアー", "b": "ツアーはチケットが売り切れ、追加公演も含めて毎週末6公演をこなしているという。ツアーバスも買ったが、税金やスタッフへの支払いも多く、世間が思うほど手元には残らないと話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（2:20〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=140s"]]}, {"cat": "暮らし", "t": "お酒は飲まない", "b": "お酒は飲まないという。ネットの心ない書き込みには言い返したくなるが、なるべく見ないようにしているそうだ。成功しても変わらない人だと言われるのが一番うれしいと話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=287s"]]}, {"cat": "家族", "t": "夫がグッズ販売を担当", "b": "結婚して10年近くになる夫がツアーに同行し、グッズ販売を任されているという。自分とは正反対の落ち着いた人で、けんかもほとんどしないそうだ。夫はネットに出るのを好まないので、私生活はなるべく出さないようにしていると話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（7:13〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=433s"]]}, {"cat": "リングに来るまで", "t": "苦しい家庭で育った", "b": "アラバマ州ベッセマーの公営住宅で育ち、近所で白人の子どもは自分だけだったという。家庭はとても苦しく、家族とのつらい経験も多かったそうだ。父と、9歳から育ててくれた継母のことは大好きだと話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（10:20〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=620s"]]}, {"cat": "リングに来るまで", "t": "「抜け出せる」と伝えたい", "b": "生い立ちを笑いのネタにすることはあまりないという。かわいそうだと思われたいのではなく、同じような環境からでも抜け出せると知ってほしいから話すのだそうだ。自分がやらなければ、周りと同じ道をたどっていたと思っていると話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（13:27〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=807s"]]}, {"cat": "暮らし", "t": "104エーカーの夢の家", "b": "地元アラバマに約1年かけて夢の家を建てたという。104エーカーの土地に建つ約560平方メートルの家で、階下が馬小屋になっているそうだ。馬5頭、ニワトリ30羽、犬と猫2匹ずつ、豚2頭と暮らしていると話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（16:32〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=992s"]]}, {"cat": "好きなもの", "t": "バレルレーサー", "b": "馬でたるの周りを速く回る競技、バレルレースの選手でもあるという。夢の家を建てたのも、動物たちに良い暮らしをさせたかったからだそうだ。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（16:32〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=992s"]]}, {"cat": "暮らし", "t": "貧乏への恐怖が原動力", "b": "「二度と貧乏には戻らない」という思いが成功への原動力だという。とても倹約家で、服は今も通販の安いシャツを買っているそうだ。大金を使ったのは家くらいだと話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（17:23〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=1043s"]]}, {"cat": "リングに来るまで", "t": "最初のバイトはクビ", "b": "15歳で始めた最初のアルバイトはファストフード店で、決まり文句を言うのを拒んでクビになったという。バーベキュー店の給仕や病院の仕事も長続きせず、父に「お前は仕事が続かない」と心配されていたそうだ。芸能の仕事を始める前は写真の会社を経営していて、今も続けていると話す。", "sp": "マット・マシューズ", "d": "2025-07-23", "how": "アウト・アンド・アバウト（ポッドキャスト）で（字幕を全文確認）", "art": "ext-G-ZT1vj-h3c", "src": [["番組のYouTube（22:05〜）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c&t=1325s"]]}]);
  ARTICLES.push({ id: "ext-G-ZT1vj-h3c", d: "2025-07-23", show: "ext", who: ["Matt Matthews"], t: "マット・マシューズの回　アラバマ育ちのコメディアン", lead: "アウト・アンド・アバウト（ポッドキャスト）に出た約63分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Matt Matthews"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-G-ZT1vj-h3c").map((x) => [x.t, x.b, x.sp])), open: ["家族（きょうだい）の薬物や逮捕に関する話は、本人以外の私人の話なので載せていない。", "下ネタの掛け合いは省いた。25分以降は今回は読んでいない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=G-ZT1vj-h3c"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wdywta-nikki" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wdywta-nikki" ? Object.assign(x, { art: "wdywta-zs3l9iujk4g" }) : x);
  for (let i = ARTICLES.length - 1; i >= 0; i--) if (ARTICLES[i].id === "wdywta-nikki") ARTICLES.splice(i, 1);
  if (!ROSTER.find((r) => r[1] === "Nikki Bella")) ROSTER.push(["ニッキー・ベラ", "Nikki Bella", "lg", "", "", "", ""]);
  if (!PROFILES["Nikki Bella"]) PROFILES["Nikki Bella"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nikki%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Nikki Bella"].lead === "") PROFILES["Nikki Bella"]._weak = 1;
  PROFILES["Nikki Bella"].facts.push(...[{"cat": "リングの話", "t": "WrestleMania直前に消えた試合を振り返る", "b": "ニッキー・ベラは、妹ブリーやダミアン・サンドウと撮った舞台裏の写真と、WrestleManiaで試合が土壇場でカットされた件を振り返る。ドラマ作りのためにわざとカットされたという噂には、本当ならむしろ腹が立つと話す。当日はシルクハットにステッキという衣装で、ニューヨークやシナトラのイメージだったそうだ。あの日は人生で最悪の恥ずかしい思いをしたと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（2:24〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=144s"]]}, {"cat": "リングの話", "t": "海外ツアーで本気で叱られた夜", "b": "ニッキーは、海外ツアーの試合でブロダス・クレイとのキスの場面が行き過ぎてしまい、上の人にひどく叱られた思い出を語る。キャリアを通じて、あれほど怒られたのを見たのは一度きりだったという。ライブのプロモ中にコーディの口ひげに自分の指が引っかかるハプニングもあった。リアリティ番組に出始めたばかりで、何もかもが新しかった時期の話だと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（3:59〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=239s"]]}, {"cat": "リングの話", "t": "ヴィンスの前でやり直しはきかなかった", "b": "ニッキーは、プロレスラーは生放送でも事故でも立て直せる危機対応のプロだと語る。以前はヴィンスの前で試合や演技を見せるのが当たり前で、チャンスは限られていたと話す。そのうえ、WrestleManiaの試合をカットされて機会を失ったこともあり、重みが違ったという。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（19:22〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1162s"]]}, {"cat": "リングの話", "t": "6年ぶりの試合、Evolutionのバトルロイヤル", "b": "ニッキーは、30人ほどの人の前で話すほうが、何千人の知らない観客の前より難しいと感じると話す。この夜は6年ぶりにまとまった形で戦うことになり、バトルロイヤルとはいえトップ女子が大勢いたので緊張したという。しかも舞台は女子だけの大会Evolutionで、ゴリラ（ステージ裏の司令室）の空気も特別だったと語る。それでも最高の夜になったと振り返る。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（20:14〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1214s"]]}, {"cat": "リングの話", "t": "殿堂入りの指輪を持ち歩く理由", "b": "ニッキーは、殿堂入りの指輪をスーツケースに入れて持ち歩いていると話す。内側には2020年の年号と「Fearless Nikki」の刻印があるそうだ。ベラ・アーミー（ファン）に会う写真撮影の場では、実物を見てもらいたくて必ず着けると語る。近年の殿堂入りはダイヤの指輪になったので、過去の殿堂入りにも交換のルールがほしいと冗談めかして話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（49:35〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2975s"]]}, {"cat": "リングの話", "t": "ディーバの時代は女の力が武器だった", "b": "ニッキーは、ディーバとは、知性や鼓舞する力に加えて、女性ならではの美しさも強さとして使う存在だったと語る。ファイターでありながら、セクシーさや自分の体への自信を見せる瞬間を大事にしてきたという。当時は仕事を頑張りすぎると女らしさを求められ、男っぽさを出しすぎると言われる、綱引きのような環境だったそうだ。ディーバという名前に問題はなく、特別な呼び名にしてきたと思っていて、ディーバ王座の復活を望むファンの声も多いと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（53:37〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3217s"]]}, {"cat": "リングの話", "t": "ナタリアとTJが教えてくれたこと", "b": "ニッキーは、ナタリアやTJ・ウィルソンと同じ時期に育ったと話す。TJはレスリングの知識が百科事典級で動きも見事、ナタリアは教えていると言わずに場を引っ張る名コーチだという。大技よりも、技と技の間の「つなぎ」や根性、試合を運ぶ力が大事で、それを学べるのが彼らの道場だと語る。WWEの外の人たちも通うほどの場所で、復帰後も頼りにしているそうだ。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（59:24〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3564s"]]}, {"cat": "リングの話", "t": "復帰を支える「ナタリアの檄」", "b": "ニッキーは、ナタリアなしでは今回の復帰はできなかったと話す。復帰後に出る試合のたび、入場曲が鳴る直前に最後に来て気合を入れてくれるのがナタリアだという。舞台の下で入場を待つ時間は誰もおらず、とても怖いが、飛び出すと8万人の観衆が待っていて、その瞬間に「だから私はこれをやっている」と思うと語る。自分にも誰か一人こういう人が必要だと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:03:31〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3811s"]]}, {"cat": "リングの話", "t": "プロレスを目指す女の子への助言", "b": "ニッキーは、プロレスラーを目指す女性には、断られても決してあきらめないことと、悪いことを良いことに変えることを伝えているという。技の基本を磨くのは当然としつつ、キャラクターの層を深く作り込み、オーディションで目が離せなくなる存在になるよう勧める。ただ自分らしくいるだけでなく、断れないほどの何かになることが大事だと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:06:52〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=4012s"]]}, {"cat": "リングの話", "t": "プロレスは「ボディスラムのあるブロードウェイ」", "b": "ニッキーは、WWEをブロードウェイにボディスラムを足したものだと考えていて、物語を技でマットの上に描くのが自分たちの仕事だと語る。スポーツでも娯楽でもなく、その両方がそろうから世界中にファンがいるという。観客とのつながりこそが一番大事で、つながりとはストーリーでありキャラクターだと話す。ストーリーが感じられない試合を見るのは嫌いだそうだ。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:08:26〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=4106s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Nikki Bella")) ROSTER.push(["ニッキー・ベラ", "Nikki Bella", "lg", "殿堂入りの元ディーバ王者", "", "", ""]);
  if (!PROFILES["Nikki Bella"]) PROFILES["Nikki Bella"] = { lead: "息子とはコアラの親子のようにべったりで、双子のブリーとは1日4回は電話する。司会業に夢中になり、殿堂入りの指輪をはめてファンに会うのが楽しみだという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nikki%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Nikki Bella"]._weak) { PROFILES["Nikki Bella"].lead = "息子とはコアラの親子のようにべったりで、双子のブリーとは1日4回は電話する。司会業に夢中になり、殿堂入りの指輪をはめてファンに会うのが楽しみだという。"; delete PROFILES["Nikki Bella"]._weak; }
  PROFILES["Nikki Bella"].facts.push(...[{"cat": "リングに来るまで", "t": "年間最大の祭典で試合が直前に消えた", "b": "かつてコーディやブリーらと組んだ年間最大の祭典の試合が、入場口の直前で取りやめになったという。舞台裏で4人で抱き合って撮った写真は今もよく覚えていると話す。大学時代にも気まずい朝帰りはあったが、あの日の引き揚げほどつらいものはなかったそうだ。もし盛り上げのためにわざと削ったのなら腹が立つ、とも語っている。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:32〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=92s"]]}, {"cat": "暮らし", "t": "司会の仕事にすっかり夢中", "b": "ブリーとのワイン事業に加え、いま一番好きになったのはテレビ番組の司会だという。ブレイク・シェルトンやカーソン・デイリーと組んだ番組では、毎回ライブで歌うシェルトンの魅力に圧倒されたそうだ。初回のニッキー・ベラがグウェン・ステファニーとシェリル・クロウで緊張したが、デイリーが何でも相談してと支えてくれたと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（15:12〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=912s"]]}, {"cat": "暮らし", "t": "初日にポルシェで走ってから審査員", "b": "サイモン・コーウェルやテリー・クルーズらと審査員を務めた番組では、何かを審査するのは初めてで、初日にいきなりポルシェでレースをしてから審査に入ったという。怖いと言われるコーウェルはとても親切で助けてくれたそうだ。何が起きても立て直すプロレスラーの性分が生きて、司会や収録の現場はとても居心地がいいと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（17:44〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1064s"]]}, {"cat": "家族", "t": "息子とはコアラの親子", "b": "もうすぐ5歳になる息子は大のママっ子で、自分もかまってほしい性分なので、二人はコアラやラッコの親子のようにくっついているという。5歳になって幼稚園に入ると何もかも変わると言われ、身構えているそうだ。復帰で2日ほど家を空けるようになったのは、離れる不安を抱えていた自分にも、たくましくなってほしい息子にも良いことだと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（21:52〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1312s"]]}, {"cat": "家族", "t": "学資から健康まで息子のために", "b": "母になってからは、自分の子ども時代になかったものを与えたいという思いが原動力になったという。教育や健康、大学の学資の準備まで、しっかり取り組んでいるそうだ。11月で42歳になるので、ブリーと二人で長く元気に生きることも意識していると話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（26:40〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1600s"]]}, {"cat": "家族", "t": "「ブリー・モード」の名付け親", "b": "16分早く生まれた姉で、ブリーの酔ったときの状態を「ブリー・モード」と高校時代に名付けたのは自分だという。数杯目でスイッチが入ると怖いもの知らずで踊り出し、ときには取っ組み合いまで始めるので、自分は飲まずに見張り役をして、最後は寝かしつけたそうだ。大学に入って母と飲みに行き、この気質は母譲りだと気づいたと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（27:25〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1645s"]]}, {"cat": "家族", "t": "最強チームはブリーと母", "b": "ゾンビの世界に誰を連れていくかと聞かれ、まずブリーさえいれば十分だと答えた。知恵と計画担当として母も加えたいという。100頭のゴリラにも勝てると言い張りそうなのは兄で、プロとの対決企画に出たがっていたが、自分は無理だと止めていたそうだ。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（31:38〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1898s"]]}, {"cat": "家族", "t": "その場で守るのは私、人生で守るのはブリー", "b": "姉として目の前の場面ではブリーを守るが、人生全体で見れば守ってくれているのはブリーのほうだと、ここ数年で気づいたという。悪口を書いた人に直接メッセージを送って抗議するほどの番犬だそうだ。会えない日も最低4回は電話し、ビデオ通話もして、一日も連絡を欠かさないと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（34:01〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2041s"]]}, {"cat": "好きなもの", "t": "笑いのツボは転ぶ映像", "b": "猫の動画のようなものでは笑わず、ブリーと二人で泣くほど笑うのは人が転ぶ映像だという。きわどい冗談や、ある種のいたずらも好きだそうだ。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（37:15〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2235s"]]}, {"cat": "暮らし", "t": "恋愛は息子が優先", "b": "巡業でホテル暮らしが寂しくなり、業界の人向けの会員制アプリに登録したという。ただ、いまは真剣な交際は何年も考えておらず、息子を誰かに会わせるつもりもないそうだ。息子がいない日はネットフリックスを見てくつろぐのが幸せで、いずれ付き合うなら、遊び心のある実業家タイプがいいと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（43:02〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2582s"]]}, {"cat": "暮らし", "t": "殿堂入りの指輪を持ち歩く", "b": "殿堂入りの指輪をスーツケースに入れて持ち歩いているという。内側には年号と自分の異名が刻まれているそうだ。ファンとの撮影会では、本物を見てもらいたくて指にはめていくと話す。最近の指輪にはダイヤが付いているので、昔の殿堂者にも付け替えてほしいと冗談まじりに語る。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（49:35〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2975s"]]}, {"cat": "リングに来るまで", "t": "「ディーバ」という呼び名に誇り", "b": "ディーバ時代の女性たちは、強さと美しさの両方を武器にし、限られた枠の中で居場所を勝ち取らなければならなかったという。戦う者であると同時に女性らしさも見せることを大事にしてきたそうだ。ディーバという呼び名に悪いところは何もなく、今も好きだと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（53:37〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3217s"]]}, {"cat": "好きなもの", "t": "推しのユニフォームはフィラデルフィア", "b": "好きなスポーツのユニフォームを4枚選ぶなら、まずアメフトのイーグルス（ジェイレン・ハーツ）、バスケットボールのシクサーズ（アレン・アイバーソン）だという。さらにサッカー女子代表と、テニスのセリーナ・ウィリアムズを挙げた。ブリーに「あなたがビーナスで私がセリーナ」と冗談を言ったら、嫌がられたそうだ。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（56:02〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3362s"]]}, {"cat": "リングに来るまで", "t": "復帰を支えるダンジョンの仲間", "b": "ナタリヤやTJ・ウィルソン（タイソン・キッド）、ハリー・スミスらと一緒にキャリアを始め、ナタリヤとは姉妹のような仲だという。大技より、試合のつなぎの部分や観客を引き込む力を教えてくれるので、ハート家の道場「ダンジョン」に通い続けているそうだ。ナタリヤの父の枕元には、ナタリヤと双子と父の4人の写真が飾られていたと話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（59:24〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3564s"]]}, {"cat": "リングに来るまで", "t": "女性志望者への助言は「ノーを受け入れない」", "b": "プロレスを目指す女性には、ノーという答えを受け入れないこと、悪いことは良いことに変えることを伝えているという。自分も何度も断られてきたそうだ。技術の基本を磨いたうえで、審査で目を離せなくなるほど作り込んだキャラクターを持つよう勧めていると話す。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:06:52〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=4012s"]]}]);
  if (PROFILES["Natalya"]) PROFILES["Natalya"].facts.push({"cat": "暮らし", "t": "入場直前に背中を押してくれる", "b": "ニッキーの復帰後、試合に出るときには入場曲が鳴る直前に必ず最後に声をかけ、気合いを入れて送り出してくれるという。本人は指導しているつもりはないと言うが、実際には部屋をまとめて教えるのが抜群にうまいと、ニッキーが話している。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で、ニッキー・ベラの話（公式字幕を全文確認）", "src": [["公式YouTube（1:03:31〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3811s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "育成時代のベラ双子の守り役", "b": "育成団体時代、ベラ双子は彼を「ダディ」と呼び、本当に父親のように守ってもらったという。南部なまりで「僕のベイビーたち」と呼び、練習中にすぐ姉妹げんかを始める二人を見て、こんなに愛し合っていて憎み合っているタッグは初めてだと言っていたと、ニッキーが話している。", "sp": "ニッキー・ベラ", "d": "2025-07-23", "how": "コーディの番組で、ニッキー・ベラの話（公式字幕を全文確認）", "src": [["公式YouTube（38:45〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2325s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "試合が消えた日、ステージ下でトランプに蹴られた", "b": "年間最大の祭典の試合が直前で取りやめになった日、怒りで誰かに当たってしまわないよう、ステージの下に一人で座り込んでいたという。すると足を蹴られ、「失礼、お若いの」と声をかけてきたのは、家族を連れて通りかかったドナルド・トランプ現大統領だったそうだ。この日が、もう辞めようと初めて思った瞬間だったと話す。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（3:14〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=194s"]]}, {"cat": "暮らし", "t": "口ひげは白髪染めで黒く", "b": "かつての口ひげは実際には毛が薄く、テレビ映えするよう男性用の白髪染めで黒くしていたという。手入れの仕方も知らず、バリカンで整えていたら一度短くしすぎてしまい、空港を歩きながら、これはもう剃るしかないと決めたそうだ。当時あの姿に付き合ってくれた妻ブランディには驚くと話す。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（10:14〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=614s"]]}, {"cat": "家族", "t": "ギプスを車窓から投げた父", "b": "小学5年で脚を折り、7か月もギプスをしていたという。外した日に病院でもらった補助用のギプスを、父ダスティは帰りのトラックの窓から投げ捨てたそうだ。自分には冗談まじりでも本気で厳しかったが、姉たちへの接し方はまるで違ったと話す。4歳の娘リバティにはまだ「パパ」と呼ばれていて、その呼び名にできるだけ長くしがみつきたいという。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（24:19〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1459s"]]}, {"cat": "家族", "t": "遺伝子検査で分かった家族のルーツ", "b": "姉が遺伝子検査を受け、母方のキューバの血筋は本当だったと分かったという。父は自分には先住民の血が入っていると話していたが、検査ではほぼドイツ系だったそうだ。ところが最近、チョクトー族の高祖父がいたことが分かり、父の話もうそではなかったと語る。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（29:57〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=1797s"]]}, {"cat": "暮らし", "t": "舞台裏ではいつも緊張している", "b": "舞台裏ではいつも緊張していて、スーツを着て背筋を伸ばし、分かっているふりをしてやり過ごしているという。テレビ収録が怖くてたまらない夜もあるそうだ。入場前、ステージ下から登場するときは周りに誰もおらず、ただ怖いと話す。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（42:11〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2531s"]]}, {"cat": "家族", "t": "妻に褒められた脚を見せる短パン", "b": "以前、妻ブランディに脚が好きだと言われたことがあるという。それ以来、家で気を引きたいときは、ワンサイズ小さめの短いトレーニング用ショーツをはくそうだ。長く連れ添っても、どうしたら相手を振り向かせられるか考えるのが楽しいと話す。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（46:21〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2781s"]]}, {"cat": "リングに来るまで", "t": "高校のレスリング部コーチになる計画", "b": "14歳から体を鍛えてきたが、プロレスがなくなったら高校のアマレスのコーチになるつもりだという。実際、祭典の試合が消えたころから別のキャラクターを演じていた時期には、ジョージア州の公立学校でコーチになるため学位を取ろうとしていたそうだ。芸能の道はあきらめ、自分を哀れんでいた数年間は、自分らしくなかったと振り返る。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（47:56〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=2876s"]]}, {"cat": "家族", "t": "父の形見はポケットナイフ", "b": "父ダスティは友と認めた相手にナイフを贈る人で、亡くなったときも家族でポケットナイフを配ったという。父の一番の教え子はTJ・ウィルソンで、彼には3本ほど渡したそうだ。甥たちも兄ダスティンのもとでプロレスの練習を積んでおり、父の素質は自分を飛ばして甥たちに受け継がれたと話す。", "sp": "コーディ・ローデス", "d": "2025-07-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-zs3l9iujk4g", "src": [["公式YouTube（1:01:48〜）", "https://www.youtube.com/watch?v=zs3l9iujk4g&t=3708s"]]}]);
  ARTICLES.push({ id: "wdywta-zs3l9iujk4g", d: "2025-07-23", show: "wdywta", who: ["Nikki Bella", "Cody Rhodes"], t: "ニッキー・ベラの回　司会業の楽しさ、ブリー・モード、ダンジョンの仲間たち", lead: "コーディ・ローデスの番組に出た約75分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nikki Bella", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-zs3l9iujk4g").map((x) => [x.t, x.b, x.sp])), open: ["試合や筋書き、復帰戦のバトルロイヤルの話は控えめにした。", "字幕の話者表示がたびたび入れ替わるため、ニッキーとコーディの発言は内容から判断した。舞台裏で吠えるという女性選手の話は、誰のことか特定できず載せていない。", "ブライアン・ダニエルソンに関するきわどい話題と、ワイン・ウォッカなどスポンサー関連の話は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=zs3l9iujk4g"]] });
  if (!PROFILES["John Cena"]) PROFILES["John Cena"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=John%20Cena"]], moves: [], facts: [] };
  if (PROFILES["John Cena"].lead === "") PROFILES["John Cena"]._weak = 1;
  PROFILES["John Cena"].facts.push(...[{"cat": "リングの話", "t": "重量挙げは年210試合を支える道具だった", "b": "ジョン・シナは、挙上競技のリフトを爆発的な力をつける手段として使い、年間約210試合を戦う中で二人を持ち上げる技の土台にしていたと話す。リフトにのめり込んだのは、あくまでリングで動くための道具としてだったという。今はその数字を追わず、健康に動けることを目標にしているそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（20:03〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1203s"]]}, {"cat": "リングの話", "t": "技の数が減るのは、リスクを抑えているから", "b": "ジョン・シナは、キャリア終盤になって技の切れが落ちたのは、取るリスクを減らしているからだと話す。守るものが増え、リングの外にも叶えたい目標があるため、動きに歯止めをかけているという。無茶をして崩れていく選手を見てきて、確率は自分に不利だと考えているそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（20:55〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1255s"]]}, {"cat": "リングの話", "t": "2006年のシナは、ラップのギミックそのものだった", "b": "ジョン・シナは、2006年当時はヒップホップ風の服装にダイヤの装飾品を身につけ、アルバムのデビューも目指していたと振り返る。自分は「WWEスーパースターとして生まれた」と答えていた時期だという。ステファニーがそのキャラクターを作った張本人だとも話している。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（36:24〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2184s"]]}, {"cat": "リングの話", "t": "客席の声が何より大事だと学んだ", "b": "ジョン・シナは、うまくいかなかった夜は数えきれないと話す。大きなブーイングは関心の表れで、日本のような静かに見守る客席も別の反応として受け止められるが、無関心な沈黙が一番つらいという。そこで謙虚に戻って原因を探せるかが分かれ道だと語っている。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:08:03〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4083s"]]}, {"cat": "リングの話", "t": "ヒップホップ路線の再起を支えたベテランたち", "b": "ジョン・シナは、ヒップホップのキャラクターで再び機会をもらったとき、エディ、リキシ、ブッカーT、JBLといったベテランと組めたと話す。彼らは何がまずかったかをはっきり言い、理由まで教えてくれたという。叱責ではなく、学びの時間だったそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:08:57〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4137s"]]}, {"cat": "リングの話", "t": "うまくいかない原因を自分に向ける", "b": "ジョン・シナは、技をひととおりこなしただけで満足し、客席に伝わっていなかったと認めない選手が多いと話す。「客が分かっていない」と考えるのは長続きしない型で、まず自分が何を間違えたかを見直すべきだという。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:09:44〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4184s"]]}, {"cat": "リングの話", "t": "WWEは「なくてはならない夢の仕事」", "b": "ジョン・シナは、WWEの仕事を、存在すること自体が幸運な夢のような仕事だと表現する。自分にどれだけ必要なものか当時は分からず、今も欠かせないという。一方で、誰にとっても必ず終わりが来る仕事だとも話している。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:12:56〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4376s"]]}, {"cat": "リングの話", "t": "2008年ごろは「稲妻に乗る」ことしか頭になかった", "b": "ジョン・シナは、2008年ごろは呼ばれればすぐ飛行機に乗り、仕事を最優先にしていたと振り返る。約15〜16年間、自分の最優先事項は興行に出ることだったという。家族との話し合いを後回しにしたことも含め、後悔はなく、自分の選択から学んだと話している。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:19:33〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4773s"]]}, {"cat": "リングの話", "t": "引退を決めた理由は、日程が体と関係を壊すから", "b": "ジョン・シナは、2013年のような試合日程をいまこなせば自分が壊れ、家庭との関係も壊れると話す。体は動き、見た目も保っているが、最優先は家族だと決めているという。だから一つの章を閉じる、というのが引退の理由だそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:23:33〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=5013s"]]}, {"cat": "リングの話", "t": "ヒールの手本はステファニーから盗んだ", "b": "ステファニーが長年ヒールをやってほしいと誘っていたという話を受け、ジョン・シナは、悪役の振る舞いの多くをステファニーから堂々と盗んでいると話す。学べる相手が少ない中で、ステファニーはその数少ない一人だという。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:24:25〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=5065s"]]}]);
  if (!PROFILES["John Cena"]) PROFILES["John Cena"] = { lead: "いじめから逃れたくて12歳でバーベルを握り、35年間一度も休まず鍛え続けてきた。父との関係を結び直し、妻を軸に生き方を選び直した素顔を率直に語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=John%20Cena"]], moves: [], facts: [] };
  if (PROFILES["John Cena"]._weak) { PROFILES["John Cena"].lead = "いじめから逃れたくて12歳でバーベルを握り、35年間一度も休まず鍛え続けてきた。父との関係を結び直し、妻を軸に生き方を選び直した素顔を率直に語る。"; delete PROFILES["John Cena"]._weak; }
  PROFILES["John Cena"].facts.push(...[{"cat": "暮らし", "t": "自分のジムは重荷を下ろす場所", "b": "収録場所は、2008年ごろから通ってきた自身のトレーニングジム。ストレスを抱えて入っても、出るときには軽くなっている場所だと話す。重い器具を扱う以上、いまに集中するしかないのが理由だという。館内ではスマホをいじるのは禁止で、用事は外で済ませるルールにしている。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（3:09〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=189s"]]}, {"cat": "暮らし", "t": "撮影で半年単位の海外暮らし", "b": "ここ1年半ほどは映画の撮影で現場暮らしが続き、ジムで最後に鍛えたのは半年前だそうだ。ブダペストに半年、メルボルンに9か月といった長期滞在になり、プロレス専念時代とはまったく違う移動生活に慣れる必要があったという。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（4:00〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=240s"]]}, {"cat": "体のこと", "t": "自己ベストから下がる自分を受け入れた", "b": "ジムの壁には自分の最高記録が掲げられ、全盛期のリフト動画も流れている。体が傷んでもうその重量を挙げられず、来るたびに自分は足りないと感じていた時期があったという。当時の重量挙げは、年200試合以上をこなし人を担ぎ上げるための手段だったと振り返る。いまの目標は80歳、90歳になっても深くスクワットし、床からデッドリフトを引ける体でいることだと話す。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（17:39〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1059s"]]}, {"cat": "体のこと", "t": "毎日つける5つの数字", "b": "「毎日の夕日を自分で勝ち取る」を合言葉にしている。体重、水分量、カロリー、カフェイン、睡眠の5項目を記録し、調子が悪いときはまずその数字から原因を探すという。数字で答えが出なければ、何が心に引っかかっているのかを自分に問うそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（22:39〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1359s"]]}, {"cat": "リングに来るまで", "t": "春休みにベニスへ下見に行った", "b": "2000年を過ぎたころ、ほかの学生がカンクンへ遊びに行く春休みに、健康・フィットネスの本場ロサンゼルスのベニスへ下見に行った。健康的な食事の店があり、誰もが体づくりに熱心な土地に感動し、地元では浮いていた自分の居場所だと感じたという。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（25:12〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1512s"]]}, {"cat": "リングに来るまで", "t": "車中泊とガレージ暮らしから出発", "b": "ほとんどお金のないまま移り住み、友人宅に転がり込んだ後は車で寝泊まりし、やがてベニスのガレージに住んだ。兄弟と部屋を分けたときはベッドを譲ってソファで寝たそうだ。父は家に戻るよう言ってくれていたので、あくまで自分で選んだ苦労だったと強調している。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（25:57〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1557s"]]}, {"cat": "家族", "t": "父の口癖は「2週間ももたない」", "b": "5月25日に大学を卒業し、27日の便を予約していた。父からは何度も「2週間ももたない」と言われたが、それが本気だったのか発奮させるためだったのかはいまも分からないという。持って行ったのは服を詰めたダッフルバッグ2つと500ドルだけで、車は向こうで買ったそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（27:28〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=1648s"]]}, {"cat": "好きなもの", "t": "2006年の自分のいでたち", "b": "2006年ごろの自分は、リーボックのポンプにポロのカーゴショーツ、バスケのタンクトップに新品のキャップ、そして25万ドル分のダイヤを身につけていたと笑う。当時はアルバムを出そうとしていて、生まれてきた理由はWWEのスーパースターになるためだと本気で思っていたという。48歳のいまは、そうは思っていないそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（36:24〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2184s"]]}, {"cat": "リングに来るまで", "t": "いじめがきっかけで12歳から筋トレ", "b": "マサチューセッツ州北東部の農村育ちで、周りはロックやメタルを聴く土地柄だった。ラップに夢中になり、水玉のレーヨン服やハマーパンツ、ハイトップフェードという格好で目立ち、いじめの標的になったという。バスを降りると高校生の間を歩かねばならず、ちょうど兄をからかい終えた彼らにとって格好の的だったそうだ。話し合いでは解決せず、強くなれば放っておいてもらえると考えて体を鍛え始め、12歳から35年間、一度も休まず続けている。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（40:22〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2422s"]]}, {"cat": "好きなもの", "t": "最初に買ったCDはファット・ボーイズ", "b": "2歳上のいとこに憧れ、週末にいとこのところで初めてラップを聴いた。親に聴くなと言われるような曲ばかり夢中になったという。最初に手にしたCDはファット・ボーイズとビースティ・ボーイズで、1985年ごろの話だそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（43:55〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2635s"]]}, {"cat": "家族", "t": "祖父の説得で12歳のクリスマスにベンチ", "b": "祖父が父を説得してくれ、12歳のクリスマスにトレーニングベンチと重りのセットをもらった。両親は家の小さな一角を彼専用にしてくれ、そこでラップを流しながら鍛えたという。学校から帰ると2時間トレーニングし、それから友達と遊ぶのが日課になったそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（46:17〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2777s"]]}, {"cat": "リングに来るまで", "t": "15歳で始めたアメフトと地下のジム", "b": "地元には少年アメフトがなく、高校1年の15歳で初めてプレーした。すでに2年半鍛えていたので力だけは同級生より上で、そこからチームに溶け込めたという。仲間に誘われて通い始めたのが、ボウリング場の地下にある月12ドルのジム。初めは合鍵を持つ仲間に入れてもらい、ゲスト料を置かずに使っていたが、やがて料金を払うようになりオーナーとも知り合ったそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（47:57〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=2877s"]]}, {"cat": "家族", "t": "自分の「家族」と呼ぶ6人", "b": "妻シェイを含む、好奇心が強く聞き上手な6人を自分の家族と呼んでいる。一方で、同じシナの姓を持つ兄弟とは物の見方が違い、長く一緒にいると自分も悲観的な側に引っぱられてしまうと率直に話す。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（52:44〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=3164s"]]}, {"cat": "家族", "t": "80歳の父はいまも自主興行を主催", "b": "80歳の父はいまも地元で独立系のプロレス興行を続けており、地元ニュースでは息子を「ジョン・シナ」と呼んで話していたという。父は昔から大のプロレス好きで、プロレスを教えてくれたのも父だった。5人兄弟は紙で作ったベルトを巻き、チャンピオンごっこをするときだけは堂々とけんかできたそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:02:19〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=3739s"]]}, {"cat": "家族", "t": "父とは「ルール付き」で関係を結び直した", "b": "父に父親らしさを求めるのをやめ、ありのままを受け入れることにした。距離を置いた時期もあり、会うのは公共の場から、と条件を決めて少しずつ関係を戻したという。この数年の父との関係は最高だそうで、10年前ならできなかった心のこもった弔辞が、いまなら言えると話す。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:04:46〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=3886s"]]}, {"cat": "家族", "t": "母は妻シェイを実の娘のように", "b": "母とは父とはまったく違う関係で、深い話までできる仲だという。母は妻のシェイと多くの時間を過ごしており、シェイは母にとって持てなかった娘のような存在になっているそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:06:20〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=3980s"]]}, {"cat": "リングに来るまで", "t": "若手時代にしごいてくれたベテランたち", "b": "ヒップホップキャラとして再チャンスをもらった若手時代、エディ・ゲレロ、リキシ、ブッカーT、JBLといったベテランと組まされた。試合後には呼びつけられ、どこが悪かったか、なぜそうなのかを叩き込まれたという。観客に伝わらなかったら、それは自分の責任だと考えるようになったのはこの経験からだそうだ。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:08:57〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4137s"]]}, {"cat": "暮らし", "t": "SNSは自分への約束の置き場", "b": "SNSでの言い争いにはなるべく関わらないようにしているという。考えを発信するのは、言ったからにはそのとおりに行動するよう自分を縛るためだと説明している。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:09:44〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4184s"]]}, {"cat": "体のこと", "t": "「自分はこれで十分」と思えた転機", "b": "どんな自分でも十分だと思えるようになったのは、妻と出会う直前だったという。自分を受け入れられたことで、人を愛するとはどういうことかの指針ができたそうだ。そのぶん、10年、15年前の友人とは自然と距離ができた人も多いと話す。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:14:28〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4468s"]]}, {"cat": "家族", "t": "2008年、食事中に前妻を置いて出発", "b": "2008年ごろ、前妻との夕食中に呼び出しの電話が入り、現金を置いてそのまま飛行機に乗ったことがあるという。当時は仕事がすべてで、話し合うことすらしなかった。後悔はしていないが、愛やつながりを求めるならあり得ない行動だったと振り返っている。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:19:33〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4773s"]]}, {"cat": "暮らし", "t": "いちばん大事なのは朝目覚めること、次に妻", "b": "人生で最大の贈り物は毎朝目が覚めることで、そのすぐ下に妻がいるという。自分と夫婦が健やかでいられるかどうかを基準に、リスクを取るかどうかを決めているそうだ。2013年ごろのような日程をいまこなせば体も夫婦関係も壊れてしまうと考え、区切りをつける決断をしたと話す。", "sp": "ジョン・シナ", "d": "2025-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-QOEUrn9CWI8", "src": [["公式YouTube（1:21:13〜）", "https://www.youtube.com/watch?v=QOEUrn9CWI8&t=4873s"]]}]);
  ARTICLES.push({ id: "wys-QOEUrn9CWI8", d: "2025-07-31", show: "wys", who: ["John Cena"], t: "ジョン・シナの回・前編　いじめ、ベニスの車中泊、父との和解", lead: "ステファニー・マクマホンの番組に出た約86分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["John Cena"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-QOEUrn9CWI8").map((x) => [x.t, x.b, x.sp])), open: ["柔術や自信を失った時期、夫の病気の話は聞き手ステファニー自身の話のため載せていない。", "字幕の40:22〜43:03は欠落しており、その間の話は追えていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=QOEUrn9CWI8"]] });
  if (!ROSTER.find((r) => r[1] === "Jacob Fatu")) ROSTER.push(["ジェイコブ・ファトゥ", "Jacob Fatu", "lg", "名門一族の巨漢レスラー", "", "", ""]);
  if (!PROFILES["Jacob Fatu"]) PROFILES["Jacob Fatu"] = { lead: "18歳で収監された過去から、家族を支えに立ち直った7児の父。うそのない素の自分のまま、一族の看板を背負ってリングに立つ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jacob%20Fatu"]], moves: [], facts: [] };
  if (PROFILES["Jacob Fatu"]._weak) { PROFILES["Jacob Fatu"].lead = "18歳で収監された過去から、家族を支えに立ち直った7児の父。うそのない素の自分のまま、一族の看板を背負ってリングに立つ。"; delete PROFILES["Jacob Fatu"]._weak; }
  PROFILES["Jacob Fatu"].facts.push(...[{"cat": "リングの話", "t": "ベルトは従弟ソロに奪われたまま", "b": "番組には王座ベルトを持たずに登場した。従弟のソロ・シコアと、その仲間の軍団にベルトを取られたままだと冗談めかして話す。年間最大の祭典で取り返すつもりで、赤い服を着てきたという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（0:00〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=0s"]]}, {"cat": "リングに来るまで", "t": "18歳で刑務所に入った", "b": "少年院に入るやんちゃな少年時代を経て、18歳で刑務所に入ったという。当時すでに子どもがいた。独房に近い環境で、トイレのすぐ前に大勢が並ぶような暮らしだったと振り返る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=45s"]]}, {"cat": "リングに来るまで", "t": "独房のテレビで従兄たちを見て決意", "b": "房内でチャンネルを回していて、従兄のウーソズが映ったのが転機になったという。「このままではだめだ」と思い、出所後にすべてを変えたと話す。環境の産物にならないことが大事だとも語る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=93s"]]}, {"cat": "家族", "t": "7人の子の父親", "b": "子どもは全部で7人いて、年齢は19、16、15、13、12、8、4歳だという。収監中に子どもの名前を決めたことを今も悔やんでいる。35歳だと明かしている。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=93s"]]}, {"cat": "家族", "t": "妻が刑務所の外で支えてくれた", "b": "差し入れの購入費も面会の電話も、妻がずっと面倒を見てくれたという。本来は自分が家族を支える立場なのにと感じたそうだ。出所後は妻が北カリフォルニアまで迎えに来て、一緒に南へ引っ越した。今の自分があるのは妻のおかげだと何度も話す。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=145s"]]}, {"cat": "リングに来るまで", "t": "おじの学校で修行を始めた", "b": "南カリフォルニアには、おじたちが開いたレスリング学校があった。ジェイコブは従兄弟の中でいちばん最後に入門した。素行の悪さから最初は敬遠されたが、おじたちは受け入れてくれたという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（3:13〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=193s"]]}, {"cat": "リングに来るまで", "t": "練習1か月で師匠に見込まれた", "b": "練習を始めて約1か月のころ、師匠のギャングレルがリングで遊んでいる姿を見たという。ギャングレルは「この男はリングにつなぎ止めておけ」とおじたちに言ったそうだ。ほかの親族にも挑戦した人はいたが、続かなかった。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=242s"]]}, {"cat": "リングに来るまで", "t": "本当はラッパーになりたかった", "b": "レスラーを目指していたわけではなく、ラッパー志望だったと話す。一族の若者は、年長者から「レスリングは最後の手段」と言われて育ち、フットボールなど別の道を探した。それでも結局レスリングに戻ってきたという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（4:49〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=289s"]]}, {"cat": "リングの話", "t": "「野蛮人」と呼ばれても気にしない", "b": "サモア系の一族が昔から「野蛮人」と呼ばれてきたことは気にならないと話す。父もそう呼ばれたレスラーで、時代が変わっただけだという。ネットの書き込みも、この仕事の一部として受け流している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（6:24〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=384s"]]}, {"cat": "リングの話", "t": "おじに「天狗」を戒められた", "b": "修行を始めたころ、ベルトが必要だと言うと、おじに「勝てばいい」と言われた。有名な名レスラーのようにベルトを掲げるつもりだと答えたところ、掲げた瞬間に丸め込んで3カウントを取ると返されたそうだ。謙虚さと打たれ強さを教える話だったと振り返る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（7:12〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=432s"]]}, {"cat": "体のこと", "t": "練習は週4日、移動がいちばんこたえる", "b": "練習は週に4日ほどだという。体にこたえるのは移動で、最終便で会場に入り、試合をして始発で帰る生活だと話す。一族の中で育ったので楽だろうと思っていたが、この仕事への敬意を学び直したそうだ。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（9:37〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=577s"]]}, {"cat": "体のこと", "t": "けがは一瞬、だから正しい訓練が要る", "b": "けがは1秒もかからずに起き、倒れ方ひとつで決まることもあるという。おじたちの訓練は「何者でもなかった自分を一人前にした」と感謝している。控室での振る舞いも含めて学び、もう街で張り合うような生き方はやめたと話す。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（10:27〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=627s"]]}, {"cat": "家族", "t": "子どものころ、おじの活躍で人気を知った", "b": "幼いころは家業の大きさを知らなかったが、おじが人気を集めた時代に、学校でからかわれてけんかになったことがあるという。おじをかばううちに、自分の家は注目されているのだと気づいたそうだ。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（12:00〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=720s"]]}, {"cat": "リングの話", "t": "キャラクターは作らず素のまま", "b": "演じているキャラクターではなく、あくまで自分自身だと話す。出身の北カリフォルニアの空気を持ち込み、地元の有名ラッパーたちにも敬意を示した。出身地を知ってもらいたいという気持ちが強いそうだ。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（12:00〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=720s"]]}, {"cat": "リングの話", "t": "「いとこ」で終わりたくない", "b": "一族に大勢のレスラーがいるので、いとこと呼ばれるだけで終わりたくないと話す。従兄のローマン・レインズやウーソズ、ソロの存在が入団の助けになったことも認めている。そのうえで、12年間続けてきた素の自分を見せるのが唯一の道だという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（12:50〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=770s"]]}, {"cat": "暮らし", "t": "スーパーや家具店の夜勤で働いた", "b": "大手スーパーやホームセンターの夜勤など、食べるためにいろいろな仕事をしてきたという。昼休みに家族の試合を見るほどのファンだった。コロナ禍は特に苦しく、何でもやったと話す。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（13:36〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=816s"]]}, {"cat": "家族", "t": "空き缶を拾う父の姿", "b": "子どものころ、フットボールの試合の日に、空き缶を拾い集める父を見て泣いたことがあるという。母に「恥ずかしがるな、あなたの父だ」と諭された。翌週に昼食代をねだると、父は財布から出して「この10ドルは缶を拾って作った金だ」と教えた。だから自分もどんな仕事でも恥じないと語る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（14:24〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=864s"]]}, {"cat": "好きなもの", "t": "自分のアクション・フィギュアが発売に", "b": "大手スーパーで売られる人形が出ることを、本人は心から喜んでいる。リングのセットに同梱されるのが自分の人形だという。5年前は、おじのサイン会の手伝いで同じ大型イベントに来ていたが、今年は壇上でファンが名前を唱えた。ゲームにも登場している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（15:13〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=913s"]]}, {"cat": "リングに来るまで", "t": "独立系で育ててもらった", "b": "入団前は別の団体に所属していた。コロナ禍で興行がなかった時期もあり、王座の保持期間は公式の数字の半分ほどだと正直に話す。ニューヨークとフィラデルフィアの独立系の客席に鍛えられたと感謝している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（16:51〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1011s"]]}, {"cat": "好きなもの", "t": "11年前に録音したラップの曲", "b": "新曲として話題の曲は、実は11年前に録ったものだという。当時はラッパーを目指していて、いとこが用意したスタジオで作った。おじがコーラスに加わっていたが、本人は存在を忘れていたそうだ。歌詞には「浜辺に家を建てる」という夢を入れたという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（17:40〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1060s"]]}, {"cat": "家族", "t": "娘たちはレスラー志望", "b": "子どもにレスラーになってほしいかと聞かれ、移動続きの生活を知るので本音は「いいえ」だと答える。ただ本人に情熱があればかまわず、特に娘たちはやる気があるという。子どもたちは、テレビに出るようになって初めて試合を見始めたそうだ。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（18:26〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1106s"]]}, {"cat": "暮らし", "t": "地元サクラメントへの思い", "b": "故郷のサクラメントが好きだが、帰るたびにつらくなるという。かつて頼りにしていた仲間が薬物でぼろぼろになっていたり、姿を消していたりするからだ。親やきょうだい、子どもに良い暮らしをさせたい気持ちが強かったと話す。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（20:02〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1202s"]]}, {"cat": "リングに来るまで", "t": "刑務所は軽い違反の繰り返しだった", "b": "長期の刑務所暮らしではなく、保護観察の違反などで短期の収監を繰り返していたという。薬物の問題はなかったそうだ。若くて愚かだったと振り返る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（21:42〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1302s"]]}, {"cat": "暮らし", "t": "地元を離れたから立ち直れた", "b": "時間を持て余すと崩れていく、と母に言われてきたという。自分は街を出て初めて集中できた、とも話す。打ち込める何かを見つけることが大事で、レスリングは偶然ぴったりはまったそうだ。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（22:33〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1353s"]]}, {"cat": "家族", "t": "妻のおかげで今がある", "b": "妻の存在を何度も強調し、本人は話されるのを嫌がるだろうがと笑う。ふたりでここまで来たという意識で、感謝を口にしている。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（23:24〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1404s"]]}, {"cat": "リングの話", "t": "本当に一つの家族", "b": "一族がやらせの関係だと思われがちだが、本当に血のつながった家族だと強調する。1970年代から続く一族で、父やおじ、ローマン・レインズ、ウーソズ、ソロまで連なると説明した。ハワイにいる兄弟のことにも触れた。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（23:24〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1404s"]]}, {"cat": "リングの話", "t": "檻の中でソロと戦う心境", "b": "年間最大の祭典で、檻の試合でソロと戦うことについて、とても感情的になると話す。ソロは幼いころから兄弟同然で、愛情しかないという。「相手を倒してやる」とは言い切れず、家族や妻も見ている中で戦うのは難しいと正直に語る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（25:53〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1553s"]]}, {"cat": "リングの話", "t": "初の屋外会場と2夜開催", "b": "今年は史上初の2夜開催で、会場は屋外のスタジアムだ。団体での屋外大会は初めてで、独立系時代に酒場の駐車場で試合をした経験はあるという。雨が降れば観客が気の毒だと心配している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（26:38〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1598s"]]}, {"cat": "体のこと", "t": "試合前は緊張で動悸がする", "b": "レスラーはみな緊張するもので、緊張しなくなったらやる気が失せた証拠だという言い習わしを紹介した。本人も入場前はパニックになりかけるそうだ。そのあと、ひざをついて気持ちを落ち着け、本番に入る。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（27:28〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1648s"]]}, {"cat": "暮らし", "t": "人が見ていないところで正しく生きる", "b": "長く務めるうちに、人気者になったと思い込まないことを教わったという。目標は、人が見ていない場面でも正しい行動を取ることだ。子どもたちに「父はいい人だった」と言われたいと話す。店員やすれ違う人にあいさつするだけで、相手の一日が変わることもあるという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で（字幕を全文確認）", "art": "ext-JmpyvwGkOZw", "src": [["番組のYouTube（29:11〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1751s"]]}]);
  if (PROFILES["Rikishi"]) PROFILES["Rikishi"].facts.push({"cat": "暮らし", "t": "リキシ：ベルトの戒めと曲への参加", "b": "おじのリキシは、修行中の甥に「勝つのはいいが、ベルトを掲げたら丸め込む」と告げて謙虚さを教えたという。また、11年前の曲にコーラスで加わっていたとも、ジェイコブが話している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で、ジェイコブ・ファトゥの話（字幕を全文確認）", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=45s"]], "by": "第三者の話"});
  if (PROFILES["Solo Sikoa"]) PROFILES["Solo Sikoa"].facts.push({"cat": "暮らし", "t": "ソロ・シコア：幼いころからの兄弟", "b": "従弟のソロは、幼いころから兄弟同然の間柄で、愛情しかないと、ジェイコブが話している。檻の試合では、その相手と戦うことになるという。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で、ジェイコブ・ファトゥの話（字幕を全文確認）", "src": [["番組のYouTube（25:53〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1553s"]], "by": "第三者の話"});
  if (PROFILES["Michael Hayes"]) PROFILES["Michael Hayes"].facts.push({"cat": "暮らし", "t": "マイケル・ヘイズ：自分が「売れた」と思うな", "b": "現場の担当者であるマイケル・ヘイズは、「自分が人気者だと思った時点で、もう人気者ではない」と言うそうだと、ジェイコブが話している。", "sp": "ジェイコブ・ファトゥ", "d": "2025-08-02", "how": "ブレックファスト・クラブ（パワー105.1 FM）の番組で、ジェイコブ・ファトゥの話（字幕を全文確認）", "src": [["番組のYouTube（29:11〜）", "https://www.youtube.com/watch?v=JmpyvwGkOZw&t=1751s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-JmpyvwGkOZw", d: "2025-08-02", show: "ext", who: ["Jacob Fatu"], t: "ジェイコブ・ファトゥの回　刑務所のテレビから年間最大の祭典まで", lead: "ブレックファスト・クラブ（パワー105.1 FM）の番組に出た約32分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jacob Fatu"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-JmpyvwGkOZw").map((x) => [x.t, x.b, x.sp])), open: ["ハルク・ホーガンの訃報への言及や、聞き手側の家族や結婚の話は省いた。", "子どもの名前や妻の名前は語られておらず、一部のおじの名前は字幕の崩れで確信が持てないため載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=JmpyvwGkOZw"]] });
