  if (PROFILES["Jade Cargill"]) PROFILES["Jade Cargill"].facts.push({"cat": "暮らし", "t": "握手で驚いた怪力", "b": "ジェイド・カーギルと握手したとき力の強さに驚き、腕立て伏せを50回続けられると聞いたことがあると、ティファニーが話している。", "sp": "ティファニー・ストラットン", "d": "2025-08-05", "how": "IMPAULSIVEの番組で、ティファニー・ストラットンの話（字幕を全文確認）", "src": [["番組のYouTube（11:13〜）", "https://www.youtube.com/watch?v=XJvU_dVIvsE&t=673s"]], "by": "第三者の話"});
