  PROFILES["Ivy Nile"].facts.push(...[{"cat": "リングに来るまで", "t": "家庭学習で育ち、6〜7歳でテコンドーを始めた", "b": "アイビーは学校に通わず家庭学習で育ったという。6〜7歳からテコンドーを続け、十代で試合に負けてばかりだったため、強くなろうとジムに通い始めたと話す。当時は体が小さく、筋肉の知識もなかったそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（4:06〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=246s"]]}, {"cat": "体のこと", "t": "ジムではあらゆる人から学んで自分流を作った", "b": "筋トレの知識は、いかにも筋肉自慢の人から食事に気を使う女性まで、いろいろな人から吸収したという。そのうえで自分に合うやり方を見つけたと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（4:54〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=294s"]]}, {"cat": "暮らし", "t": "自宅にサウナと水風呂、ガレージジムがある", "b": "トレーニングはほぼクロスフィット系で、専門のプログラムに沿って行っているという。疲れがたまる週は量を減らす。自宅にはサウナと水風呂があり、フロリダの暑さの中で屋外でも鍛えていて、ジムも増設中だそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（4:54〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=294s"]]}, {"cat": "体のこと", "t": "熱を出していたのにシーマスと対決した", "b": "元王者シーマスとのトレーニング企画の収録時、実はインフルエンザで声が出なかったという。声が戻るようお茶を飲みながら臨み、断る選択肢はなかったと話す。本調子ならもっと厳しかったと笑っている。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（5:44〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=344s"]]}, {"cat": "暮らし", "t": "生まれはフロリダ、育ちは東テネシー", "b": "フロリダ北西部で生まれ、幼いころに東テネシーへ移り、20年ほど過ごしたという。ジョンソンシティやノックスビルで暮らし、地元に帰ると南部なまりが出ると話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（8:10〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=490s"]]}, {"cat": "リングに来るまで", "t": "小さな町を出なければ成長できないと感じていた", "b": "地元は同じ人が同じことを続ける町で、ここにいては伸びないと思ったという。家庭学習で憧れの人も少なかったが、自分にはトレーニングの才能があると信じていたそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（8:57〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=537s"]]}, {"cat": "リングに来るまで", "t": "柔術とMMAにのめり込んだ", "b": "テコンドーのあと柔術に出会い、大きな相手と組み合うのが好きになったという。MMAやボクシングにも手を出し、何でもできる選手になりたかったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（10:34〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=634s"]]}, {"cat": "リングに来るまで", "t": "昼はマッサージ師、夜はMMAの二重生活", "b": "初のMMA戦に敗れ、減量や合宿のつらさも味わったという。当時はマッサージ師として働いていて、唇を腫らして出勤し、整形と間違われたこともあったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（11:29〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=689s"]]}, {"cat": "リングに来るまで", "t": "姉の勧めで人気オーディション番組に応募した", "b": "テレビでドウェイン・ジョンソンの競技番組を知り、姉に応募を勧められたという。最初はいたずらだと思い込み、途中までしか書かなかった応募用紙を数日後に仕上げて送った。するとすぐ連絡が来たそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（12:16〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=736s"]]}, {"cat": "リングに来るまで", "t": "初めてのカリフォルニアで番組に出た", "b": "最終選考に呼ばれ、人生で初めてカリフォルニアへ行ったという。ドウェイン・ジョンソンと同じ番組に出ることが信じられず、100人以上の中から出場を勝ち取った。優勝は逃したが、人生を変える経験だったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（13:51〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=831s"]]}, {"cat": "リングに来るまで", "t": "番組が放送される夜、オフィスの床を拭いていた", "b": "帰郷後は仕事を失い、夜間のオフィス清掃で生計を立てていたという。ある夜、掃除中のテレビに自分が映っていて、自分を戒める出来事だったと話す。ここで終わる気はないと思えた、と振り返っている。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（17:03〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1023s"]]}, {"cat": "リングに来るまで", "t": "番組を見たWWEから入団テストに誘われた", "b": "番組の初回に登場したことで目に留まり、WWEからテストの声がかかったという。それまでプロレスは考えたこともなかったが、これまでの格闘技経験を全部リングで使えると気づいたそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（18:37〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1117s"]]}, {"cat": "リングに来るまで", "t": "入団テストは「絶対に帰らない」という気持ちで受けた", "b": "テストは40〜50人が受け、採用されたのは6人ほどだったという。ロープ走りとバーピーを繰り返す課題で気を失いかけるほど全力を出した。仲間と一緒に動くのが好きで、最高の日だったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（20:17〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1217s"]]}, {"cat": "家族", "t": "4人きょうだいの3番目で、ひとりだけ筋肉質", "b": "兄と姉、弟がいて、アイビーは3番目だという。家族の中で鍛え込んでいるのは自分だけで、浮いているように感じると笑って話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（25:56〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1556s"]]}, {"cat": "体のこと", "t": "チートミールはせず、食事は自然な食材中心", "b": "以前ボディビルの食事法を試したが、チートミールのあとは気分が悪くなったため、やめたという。プロテインシェイクは苦手で、赤身肉を中心に食べ、炭水化物はサツマイモと米だそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（28:26〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1706s"]]}, {"cat": "好きなもの", "t": "好物は炭火で焼いたミディアムレアのステーキ", "b": "夫が焼くリブアイステーキが得意料理で、顔ほどの大きさでも平らげるという。野菜は子どものころからほとんど苦手で、ブロッコリーを父のソファの下に隠したこともあったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（32:20〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=1940s"]]}, {"cat": "家族", "t": "遠征はクリード兄弟と一緒に回っている", "b": "ダイヤモンド・マインの結成時からクリード兄弟と組み、5年ほどの付き合いだという。毎週同じ車で移動し、兄妹のような関係だそうだ。滞在先でクライミングジムを探すなど、街を楽しむようにしていると話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（34:43〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2083s"]]}, {"cat": "リングの話", "t": "育成時代にダイヤモンド・マインへ加わった", "b": "育成ブランド時代、格闘系のスタイルを持つユニットに女性メンバーが必要で、自然な流れで加わったという。人の出入りが多い中で、兄弟と一緒に上のブランドへ上がれたのは幸運だと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（34:43〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2083s"]]}, {"cat": "リングの話", "t": "ジュリアス・クリードの肩の上で逆立ちをした", "b": "ジュリアス・クリードが重量級のプレスのように持ち上げ、その上でアイビーが逆立ちを保つトレーニングをしたという。初めは無理だと思ったが、彼を信頼していたと話す。体重は約63キロとのこと。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（36:20〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2180s"]]}, {"cat": "リングの話", "t": "ジョーダン・グレイスとは体格も似た者同士", "b": "ジョーダン・グレイスが練習に来て、壁を使ったプランクなど力自慢の技を一緒に試したという。ロイヤルランブルで同時に垂直落下式の技を決めた場面は、好敵手に出会った感覚だったそうだ。対戦も望んでいると話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（37:06〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2226s"]]}, {"cat": "リングの話", "t": "チャド・ゲイブルを昔から尊敬している", "b": "入団したのがコロナ禍の直前で、観客席の係のようにリングを見ていたころからゲイブルを見てきたという。どんな役でも成功させる姿に憧れていると話す。ジャーマンの高さと美しさも、彼に刺激を受けたそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（39:23〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2363s"]]}, {"cat": "家族", "t": "夫との初デートの夜に世界が止まった", "b": "夫からの誘いを何か月も断っていて、2020年3月中旬の木曜に初めてデートしたという。その夜にライブ興行の中止連絡が届き、世界が止まる合図になったと笑っている。いまは夫婦で、同じくらいトレーニングに熱心だそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（45:47〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2747s"]]}, {"cat": "リングの話", "t": "入団の数か月後に世界的な休止で出鼻をくじかれた", "b": "入団の数か月後に世界が止まり、練習が思うようにできず苦労したという。育成ブランドで調子を上げ、のちにクリード兄弟と主力のブランドへ上がった。初期の試合でリア・リプリーと戦い、ここでやれると思えたと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（45:47〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2747s"]]}, {"cat": "リングの話", "t": "誇れる試合は英国の育成ブランドでのマコ・サノムラ戦", "b": "対戦したい相手は、ジョーダン・グレイス、ビアンカ・ベレア、リブ・モーガン、ラッシュ・レジェンドなどだと挙げる。誇れる試合は英国の育成ブランドでのマコ・サノムラ戦で、自分には分不相応とまで思ったが、終えて自信が生まれたという。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（49:03〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2943s"]]}, {"cat": "リングの話", "t": "異名「ピットブル」は柔術の絞め技から来た", "b": "柔術のセミナーで相手を絞め落としたことがきっかけだという。その絞め技の袖にはピットブルの絵があり、決まれば終わりだったため、異名になったそうだ。フィニッシュに絞めや固め技を使うのもこの流れだと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（50:33〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3033s"]]}, {"cat": "リングの話", "t": "体を鍛えたのは、人に付け込まれたくなかったから", "b": "若いころにつらい出来事があり、優しさが弱さと見られたと感じたという。そこで強そうな見た目と表情を身につけ、簡単な標的にならないと決めたそうだ。筋肉が自信になったと話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（53:56〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3236s"]]}, {"cat": "リングの話", "t": "ときに自分を見失い、出発点を思い出すという", "b": "この仕事の中で自分を見失う時期があり、小さな町から来たことを思い出して立て直すという。成功までの10年間の努力が自分を支えていると話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（56:30〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3390s"]]}, {"cat": "リングに来るまで", "t": "15歳から10年の努力が道を開いた", "b": "15歳から25歳までの10年、鍛えることは必ず良い結果に結びつくと信じてきたという。入団後も、白帯の心構えで努力を続けているそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（57:20〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3440s"]]}, {"cat": "リングの話", "t": "レスリングを教えてくれた先輩への感謝", "b": "入団当初、シェイナ・ベイズラーが最初にリングで一緒に転がり、考えすぎないことを教えてくれたという。黒帯になっても学びは始まりという「白帯の心構え」で、いまも学び続けていると話す。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（59:46〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3586s"]]}, {"cat": "体のこと", "t": "自分に厳しすぎる性格を、夫が支えてくれる", "b": "試合を見返すと自分に厳しくなりすぎて、満たされない気持ちが重くなることがあるという。夫が気持ちを落ち着かせてくれると話す。結婚して2年半、交際は5年だそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（1:01:24〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3684s"]]}, {"cat": "家族", "t": "姉が骨のがんを乗り越えた", "b": "姉が骨のがんを患い、脚を失いかけたが、いまは元気だという。姉の経験から、体にできることの大きさを教わったと話す。健康は大きな贈り物だと感謝している。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（1:05:26〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3926s"]]}, {"cat": "好きなもの", "t": "励ましの言葉が好きで、通信学を専攻していた", "b": "トレーニング中は励ましの音声を聞くのが好きで、少ない言葉で深い話をする人に惹かれるという。大学では通信学を専攻していた。ジョン・シナからもらった「自分で変えられることに集中する」という言葉を毎日思い出すそうだ。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-gxvPdYk9Qw8", "src": [["番組のYouTube（1:06:14〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=3974s"]]}]);
  if (PROFILES["Jordan Grace"]) PROFILES["Jordan Grace"].facts.push({"cat": "暮らし", "t": "ジョーダン・グレイスの経歴", "b": "ジョーダンはパワーリフティングやボディビルの世界を経て、この5〜8年で見た目が大きく変わったと、アイビー・ナイルが話している。", "sp": "アイビー・ナイル", "d": "2025-08-07", "how": "クリス・ヴァン・ヴリートの番組で、アイビー・ナイルの話（字幕を全文確認）", "src": [["番組のYouTube（39:23〜）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8&t=2363s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-gxvPdYk9Qw8", d: "2025-08-07", show: "ext", who: ["Ivy Nile"], t: "アイビー・ナイルの回　家庭学習から人気番組、そしてWWEへ", lead: "クリス・ヴァン・ヴリートの番組に出た約73分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ivy Nile"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-gxvPdYk9Qw8").map((x) => [x.t, x.b, x.sp])), open: ["聞き取りが不確かな固有名詞やバンプの話題、夫の名前などは載せていない。", "若いころのつらい出来事は、本人も詳しく話していないため要点のみにとどめた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=gxvPdYk9Qw8"]] });
  if (!PROFILES["John Cena"]) PROFILES["John Cena"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=John%20Cena"]], moves: [], facts: [] };
  if (PROFILES["John Cena"].lead === "") PROFILES["John Cena"]._weak = 1;
  PROFILES["John Cena"].facts.push(...[{"cat": "リングの話", "t": "中国進出のために中国語を学んだ", "b": "2012年ごろ、団体が所属選手に教育や語学の支援を始めたのをきっかけに、ジョン・シナは中国語の勉強を始めたという。まだ団体が足を踏み入れていない市場が中国で、そこを開くことが「業界を前より良くして去る」という自分の目的に合うと考えた。休みの日に家庭教師を迎えて何年も勉強し、上海では中国語で提携発表のスピーチもした、と話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（3:12〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=192s"]]}, {"cat": "リングの話", "t": "試合は「どう意味を持たせるか」だけを考える", "b": "ジョン・シナは、不朽の名声や後世の評価を目指すと、いま目の前の瞬間を見失うと話す。次の試合をどうすれば意味のあるものにできるか、どうすれば際立つか、と考え続けてきた結果が今の評価だという。うまくいく時もそうでない時もあるが、25年試みれば良い試合のほうが多くなるはず、と語る。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（24:36〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=1476s"]]}, {"cat": "リングの話", "t": "団体を前より良くして去れたと思う", "b": "最後の年を迎え、団体を自分が来た時より良い状態にして去れたかと問われ、ジョン・シナは「そう思う」と答える。以前とは違う姿になっており、自分が懐かしく思うものを全員に味わってほしい気持ちはあるが、今の団体にそれを求めるのは違うとも話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（29:29〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=1769s"]]}, {"cat": "リングの話", "t": "低迷期から現在までの団体の変化", "b": "ジョン・シナは、入団したころは株価が数ドルで、名称変更や主力の離脱、旧リーグの失敗、金融危機が続いた苦しい時期だったと振り返る。今は選手に寄り添う会社になり、生の興行だけでなくメディア企業の色が強まったと話す。育成部門も独立したブランドとして成立し、若手がすぐテレビで活躍する時代になった、とも語る。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（30:19〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=1819s"]]}, {"cat": "リングの話", "t": "引退の花道を自分で会社に提案した", "b": "ジョン・シナは、本物のレスリング的な「farewell」の形を自分で会社側に提案したという。選手との関係を固める機会にもなると説明し、会社も賛成した。提案しなければ、自分が引退をSNSで一言発表するだけになるところだった、と話す。こうした話が通ること自体が、団体の進化の表れだという。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（31:09〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=1869s"]]}, {"cat": "リングの話", "t": "団体への愛は肩書きがなくても変わらない", "b": "ジョン・シナは、どんな人が会社を持ち、誰が運営し、知らない選手が増えても、団体への愛は変わらないと話す。「レスリング」ではなく団体そのものが好きだと言い、役目を終えて感謝を告げられる日が来ても、悪く言うことはなく、これからも人に観てもらう側に立つつもりだという。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（33:36〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2016s"]]}, {"cat": "リングの話", "t": "観客席のファミリーのために試合で応える", "b": "難病の子どもの願いをかなえる活動で、ジョン・シナは試合前に家族の希望を聞き、相手や技の希望に応える工夫をしてきたという。客席のどこにいるかを確かめ、試合中にその家族に気づいて応えると、ふたりだけの特別な瞬間になる。観客も本人たちも事情を知らないまま、番組の質は少しも落ちない、と話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（41:45〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2505s"]]}, {"cat": "リングの話", "t": "入場曲が鳴る中でも子どもと過ごす時間を取る", "b": "ジョン・シナは、試合に出る日でも、願いをかなえる家族と会う数秒を必ず作るという。入場曲が流れている最中に対面したことや、子どもを連れて入場に向かったこともあると話す。数秒でも大きな違いになるため、頼まれたら迷わず引き受けるそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（44:24〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2664s"]]}, {"cat": "リングの話", "t": "全力で動けないなら試合を辞める勇気", "b": "ジョン・シナは、現役を続ければ体のコンディションも家庭も保てなくなる危険があると考え、愛するものに「ノー」と言うのも勇気だと話す。リングの上ほど家のように感じる場所は妻の腕の中以外にないといい、観客とやりとりしながら試合を作る感覚が好きだったそうだ。それでも、できるなら永遠に続けたいが、18歳に戻れるわけではないと語る。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:09:56〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=4196s"]]}]);
  if (!PROFILES["John Cena"]) PROFILES["John Cena"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=John%20Cena"]], moves: [], facts: [] };
  if (PROFILES["John Cena"].lead === "") PROFILES["John Cena"]._weak = 1;
  PROFILES["John Cena"].facts.push(...[{"cat": "暮らし", "t": "中国語は会社の支援制度で学んだ", "b": "2012年ごろ、会社が選手向けに語学や学位取得、資産相談などを無償で支援する制度を始めた。自分が率先して使おうと決め、まだ団体が進出していなかった中国を開拓するため中国語を選んだという。休みの日に家庭教師が自宅に来て、何年も数時間ずつ勉強したそうだ。上海で中国語のスピーチをした際、聴衆が通訳のヘッドホンを外したのを見て手応えを感じたと振り返る。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（3:12〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=192s"]]}, {"cat": "暮らし", "t": "ジャッキー・チェンの映画で中国に8か月", "b": "上海での会見を見たジャッキー・チェンが彼を映画に起用し、中国で約8か月暮らした。撮影が5月から9月に延び、その間ジャッキーのスタント班と1日2回、各4時間半のトレーニングを続けたという。パルクールや柔軟、武術、ボクシングと苦手なものばかりで、4人がかりで体を伸ばされ、ストレッチだけで汗だくになったのは初めてだったそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（5:40〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=340s"]]}, {"cat": "体のこと", "t": "中国で255ポンドから235ポンドに", "b": "慣れない運動量で体重も筋力も大きく落ち、渡航時の約255ポンドから約235ポンドになった。いまもその体重で過ごしているという。背が伸びたように感じ、動きやすく健康的になって調子がいいそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（7:20〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=440s"]]}, {"cat": "暮らし", "t": "中国語の取材で人を傷つけた失敗", "b": "ある映画の宣伝で取材の大半を中国語でこなす目標を立て、用意された文をそのまま読み上げて多くの人を怒らせてしまった。謝罪でさらに反発を招き、長く恥を抱えていたという。当時撮影中だったドラマの監督ジェームズ・ガンに降板も覚悟して打ち明けると、すぐ仕事に戻れと励まされたそうだ。言葉を知っていても文化を知っているとは限らない、というのが最大の教訓だと話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（8:11〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=491s"]]}, {"cat": "家族", "t": "妻シェイとはバンクーバーのバーで出会った", "b": "約6年前のスーパーボウルの日、熱狂的なペイトリオッツファンの彼は験担ぎで家から出ないつもりだったが、友人に頼まれて近くの店へ。向かいの席にいたシェイから目が離せなかったが、声をかける勇気は出なかったという。彼女の友人が写真を頼んできたのをきっかけに連絡先を交換し、最初のデートは夕方6時から深夜1時まで話し込んだそうだ。いまでも夫婦で夕食に出ると、気づけば深夜まで話しているという。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（14:46〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=886s"]]}, {"cat": "体のこと", "t": "よく眠れる日を目指して", "b": "眠れない夜を何度も経験し、ぐっすり眠る方法をあれこれ試してきたという。その日を悔いなく過ごせば眠りも深くなる、と話している。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（27:09〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=1629s"]]}, {"cat": "暮らし", "t": "ジムの自己ベストの鐘", "b": "よそのジムで見た「自己ベストを出したら鳴らす鐘」を気に入り、自分のジムには船の鐘を置いた。誰もいなくても自分で鳴らせばいい、思っていた限界を超えたことを確かめる合図だと説明する。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（38:27〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2307s"]]}, {"cat": "暮らし", "t": "メイク・ア・ウィッシュとの出会いは偶然", "b": "難病の子の夢をかなえる団体の活動に最初に関わったのは偶然で、控室で握手した家族が実はその家族だったと後から知ったという。以来、依頼があれば必ず引き受けてきたそうだ。会場ではその子に合わせた技を見せたり、入場曲が流れていても時間を作ったりする。回数を公表するのは団体を知ってもらうためで、それが自分を定義するものではないと話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（40:00〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2400s"]]}, {"cat": "リングに来るまで", "t": "本当は海兵隊に入るつもりだった", "b": "大学で運動生理学系の学位を取ったが、フィットネス企業には採用されず、倉庫で器具を分解する仕事をしていた。警察官を目指して州のハイウェイパトロールの試験も受けたが落ちたという。ジムの受付をしながら先を考え、体を鍛え続けられて衣食住も保証される海兵隊に入ろうと決めていたそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（49:14〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=2954s"]]}, {"cat": "リングに来るまで", "t": "入隊予定の週末にリングと出会う", "b": "入隊手続きに行くはずだった週末、友人にオレンジ郡での練習に誘われた。ガラス張りの平屋の建物の中にリングが見えた瞬間、つまらない仕事を続けてでもこれを趣味でやると決めたという。稼げるとは思っておらず、ベニスのジムでトイレ掃除をしてでも、週末に衣装を着て屋外のバーベキュー会場で試合をしたかったと話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（50:50〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=3050s"]]}, {"cat": "暮らし", "t": "軍人を英雄と仰ぐ理由", "b": "アメリカに生まれ育ったことを幸運に思い、自由と幸福追求を尊重する国の理念が好きだという。いざという時に命をかけると誓った軍人は、自分にはその勇気があるか分からないからこそ英雄だと話す。テキサスからアフガニスタンまで、兵士と過ごした時間は特別なものだそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（51:44〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=3104s"]]}, {"cat": "リングに来るまで", "t": "初めてのプロレスはMTVで", "b": "1984年ごろ、7〜8歳のときにMTVでハルク・ホーガンがアイアン・シークを破って王座を取った試合を丸ごと見たのが原点だという。家ではMTVを見せてもらえず、森の小道を抜けた先の隣家で見ていたそうだ。プロレス好きの父も一緒に楽しめるもので、ヒーローは本当にいるんだと興奮したと振り返る。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（54:23〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=3263s"]]}, {"cat": "家族", "t": "手のつけられない5人兄弟", "b": "5人兄弟の上から2番目で、子どものころは本当に手のつけられない兄弟だったと話す。森の中の家だったのでチェーンソーも身近にあり、けんかは度を越していたという。母が2人を見ているすきに、残りの3人がクレヨンで壁に落書きしていたそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:01:41〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=3701s"]]}, {"cat": "家族", "t": "母に「一番ひどかったこと」を聞いた", "b": "10歳になる前、兄弟げんかを止めに入った母を突き飛ばしてしまったことを、長年一番の親不孝だと恥じていたという。4年ほど前から母と深く話すようになり、自分が手のかかる子だったか、子を持つ前の夢は何だったかなどを尋ねた。一番ひどかったことを聞くと、母が挙げたのは20代後半の彼の言葉で、本人は覚えていなかったそうだ。受け止め方は人それぞれだと学んだと話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:02:29〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=3749s"]]}, {"cat": "暮らし", "t": "「タイタニックを沈めてみる」", "b": "新しい挑戦を考えるときは、起こりうる最悪の事態をあえて想像するのが口癖だという。最悪でも自分と妻が健やかでいられるなら挑戦し、そうでなければ見送る。大好きなリングを離れるのも、この考え方でたどり着いた「やめる勇気」だと話す。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:09:01〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=4141s"]]}, {"cat": "リングに来るまで", "t": "15歳で寄宿学校へ", "b": "誰も町を出ないような地元を離れ、15歳で寄宿学校に入った。多様な人とのつきあいや年上の男性の指導、本格的なチームスポーツを経験し、それが大学の学費にもつながったという。ほかの生徒が正装で夕食をとる間、食堂で皿洗いをしていたこともあったそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:11:32〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=4292s"]]}, {"cat": "暮らし", "t": "「ご褒美」ではなく「勝ち取った」", "b": "「チートデー」という言葉は、自分に責任を持たなくていい日と聞こえるので使わないという。「〜に値する」という言い方も避け、代わりに「勝ち取った」と言うようにしているそうだ。何もせずに受け取れるものはなく、毎日目覚められることに感謝すべきだと考えている。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:19:40〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=4780s"]]}, {"cat": "家族", "t": "「いい兄弟になる」は毎年の未達目標", "b": "毎年「いい兄弟になる」と口にするが、何も行動していないので毎年失敗していると認める。父や母との関係は実際に取り組んで良くなったのと対照的だという。悩んでいた兄弟とコーヒーを飲みながら「何があれば幸せか」を一緒に考えた話も明かしている。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:22:12〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=4932s"]]}, {"cat": "体のこと", "t": "ボウリングは苦手", "b": "ボウリングは下手だという。指が入るのは一番重い球だけで、手首には小さな石灰の沈着があってうまく曲がらないそうだ。", "sp": "ジョン・シナ", "d": "2025-08-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-vkZRDqhIrX8", "src": [["公式YouTube（1:30:21〜）", "https://www.youtube.com/watch?v=vkZRDqhIrX8&t=5421s"]]}]);
  ARTICLES.push({ id: "wys-vkZRDqhIrX8", d: "2025-08-07", show: "wys", who: ["John Cena"], t: "ジョン・シナの回・後編　中国語での失敗、妻との出会い、海兵隊志望", lead: "ステファニー・マクマホンの番組に出た約93分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["John Cena"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-vkZRDqhIrX8").map((x) => [x.t, x.b, x.sp])), open: ["字幕の1:04:15〜1:06:42は欠落しており、母との会話の続きは追えていない。", "前編と重なる父との関係、日々の記録、ジムへの思いの話は前編側にまとめた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=vkZRDqhIrX8"]] });
  if (!ROSTER.find((r) => r[1] === "Kevin Nash")) ROSTER.push(["ケビン・ナッシュ", "Kevin Nash", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Kevin Nash"]) PROFILES["Kevin Nash"] = { lead: "バスケ選手、軍人、工場労働者を経て、28歳でプロレスの世界に入った大男。ネクタイ嫌いで仲間思い、巡業の思い出を笑って語る人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kevin%20Nash"]], moves: [], facts: [] };
  if (PROFILES["Kevin Nash"]._weak) { PROFILES["Kevin Nash"].lead = "バスケ選手、軍人、工場労働者を経て、28歳でプロレスの世界に入った大男。ネクタイ嫌いで仲間思い、巡業の思い出を笑って語る人だ。"; delete PROFILES["Kevin Nash"]._weak; }
  PROFILES["Kevin Nash"].facts.push(...[{"cat": "暮らし", "t": "愛車は2005年式のマスタング", "b": "いまの愛車は2005年式のマスタングだという。シートを下げても、後ろに乗れるのはチワワくらいだと笑って話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:39〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=99s"]]}, {"cat": "リングに来るまで", "t": "心理学専攻、目標はネクタイなし", "b": "大学では心理学を専攻し、教育哲学を副専攻にしていたという。ただ人生の目標は「一生ネクタイを締めないこと」だったそうだ。葬式でもネクタイはしないと冗談めかして話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（2:31〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=151s"]]}, {"cat": "体のこと", "t": "膝の手術後でも身長は2メートル級", "b": "いまは膝の人工関節の手術を受けていて、それでも身長は6フィート10インチ前後だという。17歳のころは7フィートに近かったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（2:31〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=151s"]]}, {"cat": "リングに来るまで", "t": "大学バスケからドイツのリーグへ", "b": "長く続けたバスケットボールで大学に進み、その後ドイツでプレーしたという。ドイツのリーグは「アメリカの中堅リーグ並み」で、報酬は少なかったそうだ。前十字靭帯を痛めて競技生活を終えた。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（3:22〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=202s"]]}, {"cat": "リングに来るまで", "t": "映画に憧れて陸軍へ入隊", "b": "バスケをやめたあと、映画『Stripes』を見て「これは選択肢になる」と思い、陸軍に入ったという。軍には3年間いたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（3:22〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=202s"]]}, {"cat": "リングに来るまで", "t": "自動車工場とクラブの用心棒", "b": "除隊後はデトロイトの自動車工場の組立ラインで働いたという。その後アトランタのクラブで用心棒をしていたとき、客として来たバリー・ウィンダムに体格を見込まれ、プロレスを勧められたそうだ。当時の稼ぎを聞いて心が動いたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（4:08〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=248s"]]}, {"cat": "リングに来るまで", "t": "初日の洗礼と、9か月で初試合", "b": "道場では腕立てやステップアップを大量にこなし、ロープ走を終えると、先輩2人にきびしく絞られたという。多くの人が二度と来ないなかで、月曜にまた顔を出して周りを驚かせたそうだ。デビューは28歳で、リングに上がれるまで約9か月かかったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（5:49〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=349s"]]}, {"cat": "リングに来るまで", "t": "夢は「いい職人」と呼ばれること", "b": "駆け出しのころは運転手役で、先輩たちの昔話を車内で聞いていたという。「あいつはいい職人だ」と誰かに言われる日が来ることだけを望んでいたそうだ。世界王者になる野心より、仲間の敬意がほしかったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（8:16〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=496s"]]}, {"cat": "リングの話", "t": "重い木箱と「オズ」、そしてビニー・ベガス", "b": "最初の大きな役柄は、ダスティ・ローデスが考えた木箱から登場するキャラクターだったという。衣装とマントだけで約45キロあり、客席からはブーイングを浴びたそうだ。ダスティは恩人だが、同時に重荷でもあったと話す。その後は映画『マイ・ブルー・ヘヴン』のスティーブ・マーティンを元にしたビニー・ベガスに変わり、移動中の仲間から率直な指摘をもらって成長したそうだ。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（9:03〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=543s"]]}, {"cat": "家族", "t": "「業界をやめて」と妻に言われた時期", "b": "WCW時代の終わりごろ、妻から業界をやめないと家を出ると言われたという。辞めるつもりで会社に辞表を出し、ファックスで送ったところ、その直後にWWEから連絡があったそうだ。翌日には飛行機で呼ばれたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（13:55〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=835s"]]}, {"cat": "リングに来るまで", "t": "ビンス・マクマホンの自宅に初訪問", "b": "初めて会ったとき、ビンスはゆるいズボンに帽子という普段着で玄関を開けたという。野球選手がヤンキースのオーナーに迎えられたような気分で、足が震えたそうだ。以後、ビンスの言葉は何でも絶対に感じたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（15:32〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=932s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズに学んだこと", "b": "初対面のショーンは自分を厳しく責めるタイプで、実力は誰より上なのに自信が足りなかったという。リッチモンドでは「もっと自分を信じろ」と声をかけたそうだ。ショーンは一日も休まず試合をしていて、それが一番の学びだったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（17:08〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1028s"]]}, {"cat": "リングの話", "t": "ヨーロッパ巡業のあと、突然の世界王座の話", "b": "1994年、ヨーロッパ巡業でバスの冷房が止まり、冷蔵庫のビールが傷む前に飲んでしまったという。その夜の試合は散々で、クビを覚悟したそうだ。ところが呼ばれたビンスの家で、プールサイドから世界王座の話を切り出されたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（19:35〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1175s"]]}, {"cat": "リングの話", "t": "マディソン・スクエア・ガーデンの前夜", "b": "試合の前日にニューヨークへ入り、一人で街を歩いたという。道ではファンに追いかけられ、自分に務まるのか不安になったそうだ。それでも断る選択肢はなく、「自分から断る人間にはならない」と決めたと話す。大舞台の高揚感は、試合の決勝点を決めたときより大きかったそうだ。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（21:58〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1318s"]]}, {"cat": "リングの話", "t": "最初の相手はバックランドとバンディ", "b": "王者になってすぐの相手は、動きが合わないボブ・バックランドと、持ち上げられないほど重いキング・コング・バンディだったという。バックランドにサンセットフリップを頼まれて決めたところ、アンダーテイカーに「今度やったら俺がリングに入る」と詰め寄られたそうだ。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（23:31〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1411s"]]}, {"cat": "暮らし", "t": "巡業は安宿とぼろぼろのタオル", "b": "若手のころは、仲間と一番安いモーテルをわざと選んで泊まったという。メンフィスの有名な安宿や、海に面していても窓から駐車場しか見えない部屋もあったそうだ。トップの選手が使う上等なタオルの横で、薄く擦り切れたタオルを使うのが少し恥ずかしかったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（25:57〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1557s"]]}, {"cat": "リングの話", "t": "レッスルマニア12、テイカーとの試合", "b": "アンダーテイカーとの試合では、体重が10〜15ポンドほど自分のほうが重かったのに、持ち上げられると赤ん坊のように感じたという。試合後はリング中央に5分ほど寝転び、ピーパーたちが戻るまで起き上がらなかったそうだ。テイカーは一緒にやりやすい人だったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（30:04〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=1804s"]]}, {"cat": "リングの話", "t": "契約を更新しなかった理由とカーテンコール", "b": "契約が終わる前に、更新しないとビンスに手紙で伝えたという。条件が合えば残るつもりで、辞めたくなかったそうだ。カーテンコールには悪意がなく、会場の熱でその場の流れに乗ったと話す。ブレットのことは「自分を作ってくれた人」として悪く言わないという。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（33:25〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=2005s"]]}, {"cat": "リングの話", "t": "アルミバットで終わったナイトロ", "b": "WCWの試合でアルミのバットが欲しいと頼み、本物と見せかけ用の2本を用意させたという。本物で階段を叩いて音を響かせ、観客に本気だと思わせたそうだ。生放送は警察が出る騒ぎで終わり、移動の車ではビンスの会社を潰すと息巻く上司に冷静に返したと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（41:47〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=2507s"]]}, {"cat": "暮らし", "t": "「財産は300万ドル」という考え方", "b": "保証された契約金で、人生で初めて裕福になれると思ったという。ナッシュにとって豊かさとは300万ドルで、ホイールを替えるような散財はしないそうだ。愛車は93年式のブロンコで、昔と変わらない人間でいたいと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（49:52〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=2992s"]]}, {"cat": "家族", "t": "ブッカー時代も家族のいるフェニックスへ", "b": "WCWで台本づくりも任された時期、アトランタで3日ほど書き、あとはフェニックスの家族に会いに帰る生活だったという。家で過ごせるのは一日半ほどで、そのあと巡業に出たそうだ。仕事は自分から求めたわけではなく、頼まれて引き受けたと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:03:48〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=3828s"]]}, {"cat": "家族", "t": "WWE復帰の電話のあとの妻との会話", "b": "WWEの幹部から復帰を持ちかけられたとき、いったんは断ったという。電話を切った後、妻に「断ったの？」と聞かれ、「明日の昼までに必ず連絡が来る」と答えたそうだ。結果はその予想どおりになったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:07:53〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4073s"]]}, {"cat": "好きなもの", "t": "映画『ロードハウス』のサム・エリオット", "b": "映画の中で一番かっこいいキャラクターは『ロードハウス』のサム・エリオットだと思っているという。その影響で髪を白くしたそうだ。ビンスは気に入らず、殿堂入りの直前にも「まだ染められるぞ」と声をかけてきたが、そのまま出たと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:09:28〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4168s"]]}, {"cat": "暮らし", "t": "TNA時代は車で71マイル通勤", "b": "TNAでは自宅から71マイル運転して会場に通っていたという。着いて6人タッグをこなし、ホテルで焼き加減がミディアムレアのバーガー2個とサラダ、ワインを楽しんで、報酬は1万5千ドルだったそうだ。当時はもうキャリア20年だったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:11:00〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4260s"]]}, {"cat": "リングの話", "t": "黒い手袋は五輪の拳から", "b": "2011年のロイヤルランブルでディーゼルの黒い手袋をつけたときの話。右手を突き上げる決めポーズは、1968年メキシコ五輪の黒い拳の表彰台に着想を得たもので、政治的な意味もあったという。本人は左利きで、手袋は右手用のものを渡されたそうだ。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:11:46〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4306s"]]}, {"cat": "リングの話", "t": "殿堂入りの翌日、8万人の歓声", "b": "殿堂入りの翌日、サンフランシスコで約8万人の前に出たという。これが人生で最後に浴びる大観衆だと感じ、花道をゆっくり歩いて味わったそうだ。帰りの飛行機ではジーン・オーカーランドらと酒を飲み、「ここで何があっても悔いはない」と思ったと話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:14:09〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4449s"]]}, {"cat": "好きなもの", "t": "演じたい役はハーマン・マンスター", "b": "俳優にも関心があり、大きな体では出られる映画が限られるが、演じること自体が好きだという。ロブ・ゾンビが権利を持つ『マンスターズ』のハーマンが理想の役だそうだ。ハーマンには繊細さと優しさがあり、そこに惹かれると話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:17:28〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4648s"]]}, {"cat": "暮らし", "t": "週末のイベントでファンと話す", "b": "最近は週末のイベントで、nWoのシャツを着たファンと並んで話すのが楽しいという。年齢は4歳から35歳までさまざまだそうだ。ファンの忠誠を、同じ車番のステッカーを貼り続けるNASCARのファンにたとえて話す。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:18:16〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4696s"]]}, {"cat": "暮らし", "t": "引退試合がなくても後悔はない", "b": "最後の試合を決めて去る場面はなかったという。それでも30年以上この仕事を続けて、いまも生きて友人と話せていることが何よりの成功だそうだ。「後悔はない」と話し、番組を笑顔で締めくくった。", "sp": "ケビン・ナッシュ", "d": "2025-08-09", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GX7DHvUmA7U", "src": [["番組のYouTube（1:19:55〜）", "https://www.youtube.com/watch?v=GX7DHvUmA7U&t=4795s"]]}]);
  ARTICLES.push({ id: "ext-GX7DHvUmA7U", d: "2025-08-09", show: "ext", who: ["Kevin Nash"], t: "ケビン・ナッシュの回　工場の組立ラインから世界王者、そして殿堂入りまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約82分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kevin Nash"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GX7DHvUmA7U").map((x) => [x.t, x.b, x.sp])), open: ["字幕に話者名がなく、聞き手とナッシュの発言が入れ替わっている箇所が多い。ストーン・コールド側の思い出話や、判別できなかった発言は載せていない。", "WCW末期の経営の話、ゴールドバーグ戦の舞台裏、他の選手の私生活に触れた話は、話者や事実関係が追いきれず省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GX7DHvUmA7U"]] });
  if (!PROFILES["Jimmy Uso"]) PROFILES["Jimmy Uso"] = { lead: "結婚生活の秘訣は「話し続けること」だと語る愛妻家で、大の愛犬家。SNSを2年間断って「今この瞬間」を大切にするようになり、最近はゴルフとゲームに夢中だという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jimmy%20Uso"]], moves: [], facts: [] };
  if (PROFILES["Jimmy Uso"]._weak) { PROFILES["Jimmy Uso"].lead = "結婚生活の秘訣は「話し続けること」だと語る愛妻家で、大の愛犬家。SNSを2年間断って「今この瞬間」を大切にするようになり、最近はゴルフとゲームに夢中だという。"; delete PROFILES["Jimmy Uso"]._weak; }
  PROFILES["Jimmy Uso"].facts.push(...[{"cat": "家族", "t": "夫婦円満の秘訣は「話し続けること」", "b": "結婚生活でいちばん大切なのは、出会ったころから続けてきた会話だという。レストランでくつろぐ年配の夫婦に秘訣を尋ねることもあり、ほとんどが「コミュニケーション」と答えるそうだ。人前では本音を言いにくい仕事なので、互いに「大丈夫か」と確かめ合うようにしていると話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:43〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=103s"]]}, {"cat": "暮らし", "t": "24時間一緒でも平気だと分かっていた", "b": "仕事も移動も一緒で、文字どおり四六時中そばにいる生活だという。付き合い始めのころから、この人となら24時間一緒にいられると分かっていたそうだ。4〜5時間の車移動では、スマホを立てて番組を観ながら過ごすと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（4:18〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=258s"]]}, {"cat": "暮らし", "t": "なかなか大笑いできない", "b": "自分を笑わせるのは難しく、心から腹を抱えて笑ったのはずいぶん前だという。妻はときどき笑わせてくれるそうだ。仲間内では冗談を言い合うのが親しさの証しで、冗談を言わない相手のほうが問題だと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（5:52〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=352s"]]}, {"cat": "体のこと", "t": "SNSを2年断って「今」に集中", "b": "結婚も仕事も順調なのに、なぜか心がすさんでいた時期があったという。そこでテレビに出ている最中ながら約2年間SNSを断ち、気持ちを切り替えたそうだ。今この瞬間に集中できるようになり、人と話すときも目を見て向き合えるようになったと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（26:11〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1571s"]]}, {"cat": "リングに来るまで", "t": "23歳で契約、来月40歳", "b": "23歳で契約し、WWEでの日々はもうすぐ16年になるという。来月40歳を迎えるそうで、時間はあっという間に過ぎたと振り返る。気持ちはいまも子どものままだが体は正直で、栄養管理がすべてだと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（28:40〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1720s"]]}, {"cat": "好きなもの", "t": "母が許した最初のポスターはトリッシュ", "b": "子どものころ、母が部屋に貼るのを許してくれた最初のポスターはトリッシュ・ストラタスだったという。いわば初恋の相手だったそうだ。現役で活躍を続ける彼女の姿が、自分のやる気にもつながっていると話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（29:26〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1766s"]]}, {"cat": "暮らし", "t": "「埋められたのではなく、植えられた」", "b": "暗闇にいて埋められたように感じるときは、実は植えられたのであり、これから芽が出るのだという言葉に救われたという。ブルース・リーの「冗談でも自分をけなすな」という言葉にも影響を受け、話し方まで変わったそうだ。言葉は取り消せないということを、遅くなってから学んだと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（33:28〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2008s"]]}, {"cat": "家族", "t": "19歳の息子に伝える「選択と結果」", "b": "19歳の息子には、これからは自分で決断することになるが、その結果は選べないと言い聞かせているという。高校生の子どもたちが周りの目を気にしすぎるのが心配で、「自分らしくいろ」と伝えているそうだ。自分自身は、学校に行き、練習に行き、家の手伝いもきちんとする子どもだったと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（35:48〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2148s"]]}, {"cat": "暮らし", "t": "WWE以前は会社勤め、税金に四苦八苦", "b": "WWEに来る前はずっと給料から税金が天引きされる勤め人だったため、自分で税金を納める必要があると気づいていなかったという。州ごとに申告が必要で、最初の年は妻と2人で3時間かけて書類に住所を書き、切手を貼ったそうだ。今も毎年の戦いだと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（41:29〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2489s"]]}, {"cat": "好きなもの", "t": "お気に入りはチワワのタンク", "b": "ロットワイラーのマーリーは自分で選んだ子で、女の子と分かってさらに好きになったという。夜中には大きなマーリーにベッドから押し出され、チワワのタンクは脚の間にもぐり込んで寝るそうだ。いちばんのお気に入りはタンクで、子犬のころはマーリーを1時間おきに外へ連れ出してしつけたと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（47:11〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2831s"]]}, {"cat": "体のこと", "t": "初の大けがの翌日に犬を迎えた", "b": "コロナ禍が始まった直後、無観客開催の年間最大の祭典で膝の靭帯を断裂し、それが初めての大きなけがだったという。もともと犬と育ったこともあり、その翌日には犬を迎えようと決めていたそうだ。世界が止まり身近な人も病に倒れる中、犬たちに救われ、夫婦関係も支えられたと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（47:58〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2878s"]]}, {"cat": "家族", "t": "ネズミと暮らした子ども時代", "b": "8歳ごろにフロリダ州ペンサコーラの家へ引っ越したが、古い家で大きなネズミが出たという。床に寝ていた最初の夜、腕の上をネズミが歩いたのを覚えているそうだ。友人を家に入れられず、学校でからかわれたこともあったが、家中を燻煙したあとは出なくなったと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:08:11〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=4091s"]]}, {"cat": "暮らし", "t": "料理担当、甘いものは食べない", "b": "家ではフライドチキンや焼いたチキン、レッドビーンズ・アンド・ライス、キャベツ、魚料理などを作るという。数年間は妻と一緒にペスカタリアンだったそうだ。デザートはあまり食べず、病院に行くのは大の苦手だと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:15:26〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=4526s"]]}, {"cat": "家族", "t": "妻の大家族に見た自分の原風景", "b": "初めて妻の親族に会ったとき、30人以上が集まる昔ながらの大家族に驚いたという。自分たちが育った大人数のバーベキューを思い出したそうだ。10代のいとこたちには「いつもランディ・オートンに負けてる」とからかわれたと笑う。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:22:48〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=4968s"]]}, {"cat": "好きなもの", "t": "最近ハマっているのはゴルフ", "b": "なぜか最近ゴルフに夢中で、まずは打ちっぱなしで練習しているという。コースで周りを待たせたくないので、腕を上げてから服装もそろえて出たいそうだ。リビングの真ん中に練習用ネットを置いていると話す。歌が歌えたら体を張らずに済んだのに、とも笑う。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:29:19〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5359s"]]}, {"cat": "好きなもの", "t": "夜中までコール オブ デューティ", "b": "ゲームはコール オブ デューティが好きで、仲間と夜中の3〜4時まで遊ぶこともあるという。同僚のキャラクターが入ったセットを、初めてお金を出して買ったそうだ。遊ぶ前には家事を済ませ、妻に料理を作ってから始めるのが自分なりの気遣いだと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:31:35〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5495s"]]}, {"cat": "家族", "t": "父から学んだ働きぶり", "b": "父からは働く姿勢を学んだという。父は芝刈り機や熊手を積み込んで、祖母やおばの家まで回って庭の手入れをしていたそうだ。そのせいか庭仕事は苦手で、乗用芝刈り機を買ったもののまだ一度も使っていないと話す。断ることは母から学んだという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:38:59〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5939s"]]}, {"cat": "好きなもの", "t": "ブロードウェイで泣いた『アラジン』", "b": "ニューヨークでブロードウェイの『アラジン』を観て、歌に心を動かされて泣いたという。観客の家の近くまで行って生で見せる自分たちの仕事も同じだと感じたそうだ。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:42:16〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6136s"]]}, {"cat": "家族", "t": "両親の離婚を見て決めたこと", "b": "自分の両親は18年持たずに離婚し、祖母もそうだったという。だから同じことにはしたくなかったそうだ。夫婦の間にも別々の道を考えかけた時期があったが、それを乗り越えて今があると話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:52:07〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6727s"]]}, {"cat": "家族", "t": "最悪のジョークから始まった恋", "b": "育成施設で、妻の好きな選手が父リキシだと聞き、「あの人はダメだよな」と冗談を言ったが完全に滑ったという。練習後に呼び止めて謝り、自己紹介したそうだ。付き合う前に3か月ほど友人として毎日過ごし、タンパでは車がなかったので初デートは彼女に迎えに来てもらったと話す。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:54:27〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6867s"]]}]);
  if (PROFILES["Jey Uso"]) PROFILES["Jey Uso"].facts.push({"cat": "暮らし", "t": "もう一人の自分のような双子の弟", "b": "同じように感じ、同じように考え、互いの言葉を最後まで言い合える存在だと、ジミー・ウーソが話している。言い争って離れているときは周りまで空気が沈むそうで、かけた言葉を取り消したいと悔やんだこともあるという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で、ナオミとジミー・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（35:00〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2100s"]], "by": "第三者の話"});
  if (PROFILES["Solo Sikoa"]) PROFILES["Solo Sikoa"].facts.push({"cat": "暮らし", "t": "大学を出てから入門した末っ子", "b": "兄たちに言われて大学を卒業し、学位を取ってから「本当にやりたいのはプロレスだ」と入門したと、ジミー・ウーソが話している。冗談の言い方も見た目も似ていて自分の双子のようだと感じ、今も素直に質問してくる姿をうれしく思っているという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で、ナオミとジミー・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（1:40:38〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6038s"]], "by": "第三者の話"});
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "愛犬をプライベートジェットで病院へ", "b": "巡業先の獣医を信用できず、愛犬をプライベートジェットでシカゴのかかりつけまで運んだことがあると、ジミー・ウーソが話している。自分ならそこまでは、と言いつつ、結局は自分も同乗するだろうと笑っている。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で、ナオミとジミー・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（1:47:11〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6431s"]], "by": "第三者の話"});
  if (!PROFILES["Jimmy Uso"]) PROFILES["Jimmy Uso"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jimmy%20Uso"]], moves: [], facts: [] };
  if (PROFILES["Jimmy Uso"].lead === "") PROFILES["Jimmy Uso"]._weak = 1;
  PROFILES["Jimmy Uso"].facts.push(...[{"cat": "リングの話", "t": "ブラッドラインの最盛期に板挟み", "b": "ジミー・ウーソは、ブラッドラインが絶好調だった時期、仕事が最高に忙しい一方で、家ではナオミが大変な状況にあり、どちらにも手が回らず苦しかったと話す。自分は自分のことで手一杯だったため、ナオミは感情面も一人で乗り越えるしかなかったと振り返っている。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（9:50〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=590s"]]}, {"cat": "リングの話", "t": "兄弟と本気で戦えた最高に楽しい時期", "b": "ジミー・ウーソは、ナオミが離脱していた頃、自分のスケジュールは一気に忙しくなり、キャリアで一番楽しい時期でもあったと話す。兄弟と本当に一緒に戦えていたからだという。ナオミが別団体でチャンピオンになり、すべてを覆していく姿から学ぶことが多かったそうだ。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（15:28〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=928s"]]}, {"cat": "リングの話", "t": "夢を「仕事」に感じるな、という先輩の教え", "b": "ジミー・ウーソは、移動の多さにぼやいていたとき、ある先輩に「夢を仕事のように感じるな。飛行機に乗って好きなことをやってこい」と言われたと話す。自分で自分を謙虚にしないと、いずれ何かに謙虚にさせられるとも語り、その言葉が今も心に残っているという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（17:04〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1024s"]]}, {"cat": "リングの話", "t": "家族と同じリングに立つ「今」を味わう", "b": "ジミー・ウーソは、弟のソロ・シコアをはじめ家族がロースターに入り、日曜のバーベキューが現実になったようだと話す。先週はソロと試合をして、向かい合いながら今この瞬間にいることを強く感じたそうだ。過去を悔やむより、いまを大事にすることがいちばんの目標だという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（25:20〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1520s"]]}, {"cat": "リングの話", "t": "16年目、初めてのロマン戦を思い出す", "b": "ジミー・ウーソは、23歳で契約して間もなく16年になり、翌月に40歳になると話す。デビューしたころ、初めてローマン・レインズとリングに上がった日や、ハーディー・ボーイズらからタイトルを奪った日を今も覚えているそうだ。心は子どものままだが、体は年を取ってきたとも語る。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（28:40〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1720s"]]}, {"cat": "リングの話", "t": "ソロが「レスラーになりたい」と言った日", "b": "ジミー・ウーソは、弟のソロ・シコアが大学時代にレスラーを志した経緯を振り返る。兄たちに卒業して学位を取れと言われ、その通りにしてから「やりたいことをやる」と打ち明けたそうだ。ソロは助言をよく聞き、質問も欠かさず、自分と笑いのツボも似ていて、双子のように感じると話している。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:41:30〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6090s"]]}, {"cat": "リングの話", "t": "生の興行は「目の前に届ける」から強い", "b": "ジミー・ウーソは、ブロードウェイを観に行って感動した経験から、WWEは同じように目の前にショーを届けられるのが強みだと話す。花火や選手の動きを肌で感じられる点が、他にはない魅力で、今の自分たちは恵まれた夢の中にいるようなものだという。", "sp": "ジミー・ウーソ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:43:05〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6185s"]]}]);
  if (!PROFILES["Naomi"]) PROFILES["Naomi"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Naomi"]], moves: [], facts: [] };
  if (PROFILES["Naomi"].lead === "") PROFILES["Naomi"]._weak = 1;
  PROFILES["Naomi"].facts.push(...[{"cat": "リングの話", "t": "突然の離脱で、引退まで考えた", "b": "ナオミは、リングを離れたとき、生まれて初めて立ち止まって人生を考え直す時間ができたと話す。最初はその状況を受け止めきれず、もうレスラーはやめたのかもしれないと思ったという。そのころジミーはブラッドラインの真っ只中で、自分の中の整理は一人でやるしかなかったそうだ。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（9:00〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=540s"]]}, {"cat": "リングの話", "t": "一人で立て直し、自信を取り戻した", "b": "ナオミは、夫に仕事の不安を支えてもらえない時期を通じて、自分への自信が大きく育ったと話す。家族や社外の人間関係の支えに加え、自分の考え方を変え、怖さの外へ踏み出したのが大きかったそうだ。復帰するときは気持ちが新しくなり、今回はこうしたいという意志をはっきり持って、集中して打ち込んだという。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（10:38〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=638s"]]}, {"cat": "リングの話", "t": "肩の手術で「まだ終わっていない」と気づく", "b": "ナオミは、自分が止まっても番組は止まらず回り続けると実感したという。肩の手術で体の自由を奪われ、別の人生に移る頃合いかとも考えたが、そのとき「まだ終わっていない、こんな形で終わりたくない」と気づいたそうだ。もっと成し遂げられると自分に証明したい気持ちが戻ってきたと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（13:02〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=782s"]]}, {"cat": "リングの話", "t": "悔しさと「やめない」意地が原動力に", "b": "ナオミは、離脱中に目にした書き込みに腹が立ち、見返したい気持ちが火をつけたと話す。家でひとりプロモを練習していたこともあったそうだ。これまで何かを途中でやめたことがなく、その感覚が嫌だったこと、両親や継子たちにもっと良い終わり方を見せたかったことも理由に挙げる。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（21:12〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1272s"]]}, {"cat": "リングの話", "t": "本番前の不安には、前向きな言葉で向き合う", "b": "ナオミは、言葉の力を信じていて、リングに上がる前の「うまくできなかったらどうしよう」という不安に対し、前向きな言葉を自分にかけるようにしていると話す。以前は弱気な声に負けたが、今はそれと戦っているそうだ。大舞台を前に重圧を口にしたときは、ジミーが「自分が何者か思い出せ」と声をかけたという。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（22:52〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1372s"]]}, {"cat": "リングの話", "t": "言うべきことを溜め込んで限界が来た", "b": "ナオミは、仕事の場でも周囲に尽くしすぎ、感謝すべきだと思って声を上げなかったことが、のちの大きな不満につながったと振り返る。気づけば心も体もお金も消耗していたそうだ。吐き出したことは後悔していないが、溜め込まずに早めに声を上げることが大事だと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:36:20〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5780s"]]}]);
  if (!PROFILES["Naomi"]) PROFILES["Naomi"] = { lead: "プロのダンサーから「つなぎ」のつもりで飛び込んだ世界で、夫ジミーと出会ったという。離脱の時期に自分と向き合って自信を取り戻し、いまは2匹の愛犬を「わが子」と呼んで溺愛している。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Naomi"]], moves: [], facts: [] };
  if (PROFILES["Naomi"]._weak) { PROFILES["Naomi"].lead = "プロのダンサーから「つなぎ」のつもりで飛び込んだ世界で、夫ジミーと出会ったという。離脱の時期に自分と向き合って自信を取り戻し、いまは2匹の愛犬を「わが子」と呼んで溺愛している。"; delete PROFILES["Naomi"]._weak; }
  PROFILES["Naomi"].facts.push(...[{"cat": "家族", "t": "育成時代に出会い、5年後に結婚", "b": "夫ジミー・ウーソとは2009年に育成団体で出会い、2014年に女子選手の密着リアリティ番組の中で結婚式を挙げたという。結婚して11年になるそうだ。夫婦そろってのインタビューは、その番組以来ずいぶん久しぶりだと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（0:52〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=52s"]]}, {"cat": "家族", "t": "夫がそばにいると不安が和らぐ", "b": "夫婦の中では自分のほうが「くっつきたがり」で、夫がそばにいると気持ちが落ち着き、不安が減るという。別々に巡業した時期もあり、最初は新鮮だったが数か月で一緒に戻りたくなったそうだ。夫は親友でありパートナーなので、離れるのは大きな変化だと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（3:29〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=209s"]]}, {"cat": "リングに来るまで", "t": "ダンサーから「つなぎ」のつもりで入門", "b": "プロレスの世界に入る前はプロのダンサーとして活動していたという。面白そうだと思って挑戦したものの、うまくやれるか、採用されるかも分からず、次の道が見つかるまでのつなぎのつもりだったそうだ。それがいつの間にか人生の中心になり、生涯の伴侶にも出会えたと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（8:13〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=493s"]]}, {"cat": "体のこと", "t": "離脱期間に初めて立ち止まった", "b": "会社を離れていた時期は、大人になって初めて立ち止まり、これから何をしたいかを考え直す時間になったという。最初はもう試合はしたくないと思い、仕事も仲間とのつながりも失ったように感じたそうだ。夫も多忙だったため一人で心の課題に向き合い、しばらく落ち込むことを自分に許したあと「今日で最後」と決めて動き出し、その経験で自信がついたと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（9:00〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=540s"]]}, {"cat": "体のこと", "t": "肩の手術を経て「まだ終われない」", "b": "家にいた時期に肩の手術も受け、体の面でも何かを奪われたように感じたという。人生の次の段階に移る頃合いかとも考えたが、その中で「まだ終わっていない、この形で終わりたくない」と気づいたそうだ。レスラーとしてだけでなく、一人の女性として成長したいという思いもあったと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（13:02〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=782s"]]}, {"cat": "家族", "t": "両親と継子たちのために", "b": "復帰を決めた理由のひとつは、これまで何ひとつ途中で投げ出したことがなく、その感覚が嫌だったことだという。両親に誇りに思ってほしかったし、継子たちにもより良い結末を見せたかったそうだ。一度腹を決めてからは、気持ちを変えなかったと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（22:01〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1321s"]]}, {"cat": "体のこと", "t": "自分にかける言葉を変えた", "b": "言葉の力を信じていて、自分にはできるだけ前向きに話しかけるよう心がけているという。試合前の不安や失敗への恐れは常にあるが、以前より自分に優しく話せるようになり、見方が変わったそうだ。かつては自信のなさに負けたこともあったが、今は抵抗できていると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（22:52〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1372s"]]}, {"cat": "家族", "t": "母になった選手たちに勇気づけられる", "b": "以前は時間に追われている感覚があったが、出産を経て戻ってくる女子選手たちを見て、自分も望めば休んで子どもを持てると感じるようになったという。16年前は、子どもを産めばキャリアは終わりだと思っていたそうだ。彼女たちの姿は多くの女性を勇気づけていると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（30:17〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=1817s"]]}, {"cat": "家族", "t": "義母は「大当たり」、でもおやつは許さない", "b": "義母は昔気質で、夫と同じ便で帰ってきても「ちゃんと食べさせたか」と気にかけてくるという。留守中は犬を預かってくれる頼れる存在で、義母運には恵まれたそうだ。ただ、犬にこっそりおやつを与えていたことや子どもたちにお菓子をあげていたことには怒っていて、自分が祖母になったら同じように孫を甘やかすと宣言済みだと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（45:34〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2734s"]]}, {"cat": "好きなもの", "t": "ロットワイラーとチワワが「わが子」", "b": "5歳のロットワイラーのマーリーと、チワワのタンクを「わが子」と呼んで溺愛しているという。犬と寝るためにキングサイズ2台分ほどの特大ベッドを買ったそうだ。タンクは巡業に連れて行けるよう小型犬として迎えたが、ティーカップサイズのはずが普通の大きさで、目安の8ポンドを超える13ポンドあると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（47:11〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=2831s"]]}, {"cat": "暮らし", "t": "タンクの椎間板ヘルニア手術", "b": "夜中の2時にタンクが突然悲鳴を上げ、動けなくなったという。胴長で脚の短い犬がかかりやすい椎間板ヘルニアで、2軒の病院を経て神経外科医を探し、手術を受けさせたそうだ。犬の洗体は自宅のシャワーで自分でしているが、爪切りだけは怖くて獣医に任せていると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（50:22〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=3022s"]]}, {"cat": "暮らし", "t": "甘やかしたトイレ問題と白いラグ", "b": "子犬のころのタンクがあまりに小さく、濡れた芝が冷たそうでかわいそうだったため、外に出さず室内のシートで用を足すようしつけたという。その結果、今でもラグに粗相をしてしまい、5年たって後悔しているそうだ。色の濃いラグでは気づけないため、明るい色のラグに替えたと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（55:03〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=3303s"]]}, {"cat": "好きなもの", "t": "保護した子猫と一緒にタンパへ", "b": "育成施設に来る直前、祖母の家の床下にいた子猫を保護し、ディクシーと名付けてタンパへ一緒に連れて行ったという。母が働きづめだったため犬は難しく、子どものころから猫を飼っていたそうだ。避妊手術をしていなかった飼い猫が何度も子猫を産み、家族で世話をしたと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:00:00〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=3600s"]]}, {"cat": "家族", "t": "「ペット」の豚ウィルバーの行方", "b": "祖父母の家に豚がいて、自分たちのペットだと言われて毎日一緒に遊び、餌もあげていたという。ある日学校から帰ると、祖父が揚げ物用に解体していて、とてもショックだったそうだ。田舎暮らしの祖父には子どもが22人おり（祖母との子は8人）、2000年ごろに亡くなったと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:12:16〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=4336s"]]}, {"cat": "暮らし", "t": "数年間のペスカタリアン生活", "b": "夫婦で数年間、魚中心の食生活をしていたという。巡業中にファストフードを避けられ、ツナのパックやスモークサーモンを持ち歩いていたそうだ。今は肉も食べているが、また戻すかもしれず、甘いもの好きながら、食事と健康にはこれまでで一番気を配っていると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:15:26〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=4526s"]]}, {"cat": "家族", "t": "父の心臓の不安と回復", "b": "最近、父が心臓の不調で危うい状態になり、本当に失いかけたと感じたという。ステファニーに相談して専門医につないでもらい、父は今では体重も落として元気になったそうだ。父とはとても仲が良く、健康管理には自分も目を光らせていると話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:24:28〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5068s"]]}, {"cat": "家族", "t": "父譲りの芸人気質、いつか共演を", "b": "父は南フロリダ、自分たちの家は中部フロリダにあり、同じ家では育たなかったが、夏休みは父のもとで過ごしたという。父はいまも舞台に立つ芸人で、子どものころはその横で踊っていたそうだ。父方は音楽一家で、叔父のジョージ・マックレーは70年代に全米1位のヒットを出しており、歌に自信はまだないが、いつか父と一緒にステージに立ちたいと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:27:42〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5262s"]]}, {"cat": "暮らし", "t": "家族とお金に線を引くことを学んだ", "b": "いちばん大きな学びは、自分の心と力を守り、家族に対しても境界線を引くことだという。質素な家庭の出身で、家族の中で「成功した人」と見られる重みから、お金のことも含めて断れずにいたそうだ。与えすぎて心も体もお金も消耗していたと気づき、礼儀を持って「ノー」と言えるようになったと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:34:41〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=5681s"]]}, {"cat": "家族", "t": "初デートでワサビをアボカドと間違えた", "b": "初デートの寿司店で、ワサビをアボカドだと思って丸ごと口に入れてしまったという。吐き出せずに飲み込み、涙が止まらず、その後の映画もやめて帰ったそうだ。今でもワサビは自分の皿から遠ざけていると話す。当日は車のない夫を、初めて買った自分の車で迎えに行ったそうで、その車は今も唯一の愛車だという。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:48:01〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6481s"]]}, {"cat": "リングに来るまで", "t": "知っていた選手はリキシだけ", "b": "子どものころ、兄弟同然に育った向かいの家の男の子たちが金曜夜の番組を観ていて、そこで見たのがリキシとザ・ロックの時代だったという。育成施設に来て好きな選手を聞かれたときも、知っていたのはリキシだけだったのでそう答えたそうだ。それが夫の父親だったと話す。", "sp": "ナオミ", "d": "2025-08-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-k6-p-7DQq_Q", "src": [["公式YouTube（1:54:27〜）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q&t=6867s"]]}]);
  ARTICLES.push({ id: "wys-k6-p-7DQq_Q", d: "2025-08-14", show: "wys", who: ["Jimmy Uso", "Naomi"], t: "ナオミとジミー・ウーソの回　ワサビの初デートから、愛犬2匹と歩む結婚11年まで", lead: "ステファニー・マクマホンの番組に出た約121分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jimmy Uso", "Naomi"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-k6-p-7DQq_Q").map((x) => [x.t, x.b, x.sp])), open: ["車中でシャナイア・トゥエインを歌った話や、次に迎えたい犬、自宅の場所の話は、夫婦のどちらの発言か追えなかったため載せていない。", "高校時代の交際相手の話は、一般の私人にかかわるため省いた。", "車中でシャナイア・トゥエインのアルバムを1枚まるごと歌った話や、次に迎えたい犬（保護犬、チワワ2匹など）の話は、夫婦のどちらの発言か追えなかったため載せていない。", "離脱の経緯や他団体での王座獲得、試合への意気込みなどキャリア面の話は、選手の素顔の項目から外した。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=k6-p-7DQq_Q"]] });
  if (!ROSTER.find((r) => r[1] === "Jimmy Uso")) ROSTER.push(["ジミー・ウーソ", "Jimmy Uso", "lg", "ウーソズの一人", "", "", ""]);
  if (!PROFILES["Jimmy Uso"]) PROFILES["Jimmy Uso"] = { lead: "妻のナオミとともに赤ちゃんを授かったことを番組で明かしたジミー・ウーソ。子どもたちの反応や、リングを少し離れる覚悟を、うれしさいっぱいに語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jimmy%20Uso"]], moves: [], facts: [] };
  if (PROFILES["Jimmy Uso"]._weak) { PROFILES["Jimmy Uso"].lead = "妻のナオミとともに赤ちゃんを授かったことを番組で明かしたジミー・ウーソ。子どもたちの反応や、リングを少し離れる覚悟を、うれしさいっぱいに語った。"; delete PROFILES["Jimmy Uso"]._weak; }
  PROFILES["Jimmy Uso"].facts.push(...[{"cat": "家族", "t": "突然の知らせに、今も気持ちが追いつかない", "b": "ジミーは、赤ちゃんを授かったことを「まるで不意打ちのようだった」と話す。ずっと願ってきたことだが、いまも気持ちの整理がついていないという。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（0:00〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=0s"]]}, {"cat": "家族", "t": "手術の日、待つ時間が長かった", "b": "ナオミが大きな手術を受けた日、予定は数時間のはずが六時間かかったとジミーは話す。世の中が大変な時期で、病院にはふたりきり。何の説明もないまま待ち続け、気が気でなかったそうだ。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（2:29〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=149s"]]}, {"cat": "家族", "t": "助けなしで授かった", "b": "周りからは、授かるには手助けが要るかもしれないと言われていたとジミーは話す。それでも結果として自然に授かり、時間はかかったが、助けはいらなかったと笑っている。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（4:51〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=291s"]]}, {"cat": "家族", "t": "ナオミの気持ちを代弁", "b": "ジミーによると、ナオミは仕事が好調な時期だっただけに、ファンを裏切ったように感じていたという。それでもタイミングがすべてだと受け止め、これを人生最大の挑戦にしようと話した。ナオミがまずファンのことを思い浮かべたと、ジミーはファンに伝えている。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（5:38〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=338s"]]}, {"cat": "家族", "t": "娘には電話で先に伝えた", "b": "ジミーは、早朝の飛行機に乗る日に、学校が終わったら電話するよう娘にメッセージを送ったと話す。叱る話ではないと念を押し、ちょうど午後3時15分に電話が来たそうだ。顔を見ながら通話で打ち明けたという。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（9:43〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=583s"]]}, {"cat": "家族", "t": "ナオミと子どもたちの出会い", "b": "ナオミが子どもたちと初めて会ったのは、息子がまだ3歳の頃だったとジミーは話す。ふたりの交際が始まったばかりで、子どもたちとなじむ様子を見て、この関係はうまくいくと確信したそうだ。いま娘は高校の最終学年、息子は大学2年生になるという。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（10:34〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=634s"]]}, {"cat": "家族", "t": "娘の言葉に救われた", "b": "ネットで妊娠のうわさを見ていた娘は、父から直接聞くまで待っていたという。知らせを聞くと、うれしそうに「ナオミにはそれだけの価値がある」と言ってくれた。ジミーは、その日いちばん聞きたかった言葉だったと話している。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（11:22〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=682s"]]}, {"cat": "リングの話", "t": "ドアは閉めず、少し開けておく", "b": "自分たちの親にもまだ伝えられず、近い家族までがネットを見て確かめようとする状況で、この一週間は大変だったとジミーは話す。しばらくリングを離れるが、ドアを閉めるわけではなく、また戻ってくると語っている。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（12:14〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=734s"]]}, {"cat": "暮らし", "t": "ナオミには少し休んでほしい", "b": "ジミーは、これからナオミが仕事のプレッシャーを減らし、化粧や道具のことを考えずにゆっくり過ごせるといいと話す。自分のことを大事にする時間にしてほしいという。", "sp": "ジミー・ウーソ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（13:52〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=832s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Naomi")) ROSTER.push(["ナオミ", "Naomi", "lg", "女子スーパースター", "", "", ""]);
  if (!PROFILES["Naomi"]) PROFILES["Naomi"] = { lead: "夫のジミー・ウーソとともに、赤ちゃんを授かったことを番組で明かしたナオミ。長い道のりを経ての喜びと、リングを離れる複雑な思いを率直に語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Naomi"]], moves: [], facts: [] };
  if (PROFILES["Naomi"]._weak) { PROFILES["Naomi"].lead = "夫のジミー・ウーソとともに、赤ちゃんを授かったことを番組で明かしたナオミ。長い道のりを経ての喜びと、リングを離れる複雑な思いを率直に語った。"; delete PROFILES["Naomi"]._weak; }
  PROFILES["Naomi"].facts.push(...[{"cat": "体のこと", "t": "妊娠に気づいたのは出張先のホテル", "b": "妊娠が分かったのは先週の日曜日、移動中のホテルの部屋だったとナオミは話す。いつもと違う感覚があり、念のため検査をしてみたそうだ。長く不妊に悩んできたため、まさか自分が、とは思っていなかったという。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（1:40〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=100s"]]}, {"cat": "体のこと", "t": "不妊と向き合ってきた長い道のり", "b": "ナオミはこれまで、不妊の問題を抱えながら歩んできたと話す。過去に手術を受けたことがあり、これまで詳しくは語ってこなかったが、今回あらためて経緯を説明したいと言って話し始めた。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（2:29〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=149s"]]}, {"cat": "リングの話", "t": "手術のため半年間リングを離れた過去", "b": "ナオミは2020年、無観客に近い時期の大会が続いていた頃に大きな手術を受け、半年ほど試合から離れたと話す。そのことは周囲にほとんど伝えず、静かに休んでいたという。回復には時間がかかったそうだ。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（3:15〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=195s"]]}, {"cat": "体のこと", "t": "自然には難しいと思っていた", "b": "37歳という年齢に加え、過去の手術の影響もあり、自分では自然に授かるのはもう無理だと考えていたとナオミは話す。医師からも、助けを借りる道になるだろうと言われていたそうだ。だからこそ、今も信じられない気持ちだという。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（4:00〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=240s"]]}, {"cat": "リングの話", "t": "職場への伝え方に悩んだ", "b": "うれしさと同時に、驚きや緊張、怖さなど、いろいろな感情が一度にきたとナオミは話す。分かった直後も仕事に向かい、職場にどう伝えるかを気に病んでいたそうだ。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（4:51〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=291s"]]}, {"cat": "体のこと", "t": "心音を見て不安が消えた", "b": "妊娠7週目で、先週の木曜日に心音を見て聞いたとナオミは話す。その瞬間、それまで悩んでいたことがすべて消え、これから先で何より大切なのはこの子だと思えたという。うれし涙が出たそうだ。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（6:27〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=387s"]]}, {"cat": "家族", "t": "家族でいちばん遅い出産の報告", "b": "ナオミは家族の中で赤ちゃんを授かるのが最後のほうで、みんなずっと待ち望んでいたと話す。父に伝えると、跳びはねて叫ぶほど大喜びだったそうだ。入場でリングまで付き添ってもらった時間も、いい思い出だと話している。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（8:03〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=483s"]]}, {"cat": "リングの話", "t": "離れるのは本意ではないが、戻るつもり", "b": "今回リングを離れるのは自分で選んだことではなかったと、ナオミは話す。それでも必ずもっと強くなって戻ってくる、と前を向いている。生まれてくる子の手本にもなりたいという。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（8:56〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=536s"]]}, {"cat": "家族", "t": "ジミーの子どもたちへの思い", "b": "ナオミは、ジミーの子どもたちを自分の子どもだと思って接してきたと話す。とくに末の娘にはいつも「いちばんのお気に入り」と声をかけているそうだ。この知らせを喜んでくれるか、赤ちゃんの世話も手伝ってくれるか、とても気にしていたという。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（13:01〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=781s"]]}, {"cat": "体のこと", "t": "よく眠くなり、変化の速さに驚く", "b": "体調は良いが、このところよく昼寝をしているとナオミは話す。ただの疲れだと思っていた体のだるさも、妊娠のせいだと分かって納得したそうだ。変化がこんなに早く出ることに驚いているという。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（14:45〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=885s"]]}, {"cat": "暮らし", "t": "赤ちゃんの名前は人に言わない", "b": "ナオミは、子どもにつけたい名前は人に話さないほうがいいと助言する。誰でも意見を言いたがり、それが良いものとは限らず、自分の気持ちが揺らいでしまうからだそうだ。", "sp": "ナオミ", "d": "2025-08-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-IYhUqLNio5g", "src": [["公式YouTube（17:05〜）", "https://www.youtube.com/watch?v=IYhUqLNio5g&t=1025s"]]}]);
  ARTICLES.push({ id: "wys-IYhUqLNio5g", d: "2025-08-18", show: "wys", who: ["Jimmy Uso", "Naomi"], t: "ナオミとジミー・ウーソの回　赤ちゃんを授かった報告", lead: "ステファニー・マクマホンの番組に出た約19分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jimmy Uso", "Naomi"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-IYhUqLNio5g").map((x) => [x.t, x.b, x.sp])), open: ["妊娠・出産に関する話は、本人たちが番組で発表した範囲の要点だけにとどめ、医療の細かい内容は載せていない。", "字幕の話者表記が当てにならず、ジミーかナオミか判断がつかない発言は載せていない。子どもたちの名前も載せていない。", "妊娠・出産に関する話は、本人たちが番組で発表した範囲の要点だけにとどめ、医療の細かい内容や医師の話は載せていない。", "字幕の話者表記が当てにならず、ナオミとジミーの発言が混ざっている箇所は、迷うものを載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=IYhUqLNio5g"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wdywta-becky" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wdywta-becky" ? Object.assign(x, { art: "wdywta-Pcjw-ksGy9Y" }) : x);
