  if (!ROSTER.find((r) => r[1] === "Becky Lynch")) ROSTER.push(["ベッキー・リンチ", "Becky Lynch", "lg", "", "", "", ""]);
  if (!PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Becky%20Lynch"]], moves: [], facts: [] };
  if (PROFILES["Becky Lynch"].lead === "") PROFILES["Becky Lynch"]._weak = 1;
  PROFILES["Becky Lynch"].facts.push(...[{"cat": "リングの話", "t": "名レスラーは頭の良い人ばかり", "b": "ベッキーは、プロレスラーは頭が悪いというイメージがあると話す。クイズ番組に出た自分もそのイメージを助けなかったと笑う。それでも、本当に優れたレスラーはみんな知性が高いと考えているそうだ。コーディやコルビー、ブライアン・ダニエルソン、トリプルHなどの名前を挙げ、この仕事で大成するには高い知性が欠かせないと語る。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（46:11〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2771s"]]}, {"cat": "リングの話", "t": "悪役のほうが良い仕事ができる", "b": "ベッキーは、悪役を演じるのが大好きで、そのほうが自分は良いレスラーでいられると話す。理由は、相手を良く見せるのが得意だからだという。自分は派手で格好いい技を持つタイプではない、と笑って話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:02:40〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3760s"]]}, {"cat": "リングの話", "t": "相手の見せ場を作る名手", "b": "ベッキーは、ライラやビアンカのように派手な技を持つ選手と戦うとき、相手の技が一番映える位置に立つのが自分の役目だと話す。相手の技をどこでどう受ければ格好良く見えるかを考えるのが得意だという。コーディはこれを、土台になって相手を引き立てる大きな技術だと評している。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:03:30〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3810s"]]}, {"cat": "リングの話", "t": "善玉は自分を格好良く見せ続ける役", "b": "ベッキーは、善玉は好かれるのが仕事なので、ある意味で自分勝手にならざるを得ないと話す。いちばん格好良く、賢く、完璧に見せ続けなければならず、選挙運動のような政治的な気苦労があるという。一方で悪役は、何をしても間違いにならない自由がある、と語る。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:04:21〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3861s"]]}, {"cat": "リングの話", "t": "悪役は気持ちが軽い", "b": "ベッキーは、悪役の仕事は相手を格好良く見せることで、善玉よりずっとストレスが少ないと話す。観客との関係だけでなく、仕事の中身そのものがそうだという。コーディが自分は善玉のほうが向いていると答えても、悪役の気楽さは譲らなかった。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:05:10〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3910s"]]}, {"cat": "リングの話", "t": "即興の経験がリングにも生きる", "b": "ベッキーは、ドラマの収録で即興の名手たちと仕事をした経験が、プロレスにも役立っていると話す。シカゴに住んでいたころには、即興劇の劇団でも少し学んだそうだ。プロレスの試合はいつも即興の連続だと考えていて、経験を重ねるほど自分を信じて最善の反応ができるようになったという。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:11:46〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4306s"]]}, {"cat": "リングの話", "t": "自分を信じる大切さを教わった", "b": "ベッキーは、カナダのバンクーバーで出会ったスコッティ・マックから、自分を信じなければ誰も信じてくれないと教わったと話す。コーディが紹介した「リング上で一番の主役だと思え」という助言と近い、いわばその入門版のような言葉だという。単純な言葉ほど心に残る、というやりとりになった。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:18:54〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4734s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Becky Lynch")) ROSTER.push(["ベッキー・リンチ", "Becky Lynch", "lg", "7度の世界王者", "", "", ""]);
  if (!PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"] = { lead: "客室乗務員の母に連れられ6歳で初めてアメリカへ渡り、自身も客室乗務員を経てリングにたどり着いた。いまは夫と娘との暮らしを何より大切にし、仕事と家庭の両立を一番の誇りだと語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Becky%20Lynch"]], moves: [], facts: [] };
  if (PROFILES["Becky Lynch"]._weak) { PROFILES["Becky Lynch"].lead = "客室乗務員の母に連れられ6歳で初めてアメリカへ渡り、自身も客室乗務員を経てリングにたどり着いた。いまは夫と娘との暮らしを何より大切にし、仕事と家庭の両立を一番の誇りだと語る。"; delete PROFILES["Becky Lynch"]._weak; }
  PROFILES["Becky Lynch"].facts.push(...[{"cat": "暮らし", "t": "機内で隣の人と話し込むのが好き", "b": "アメリカに来たばかりのころから、飛行機で隣になった人とよく話し込んできたという。年配の女性に身の上話や人生の助言を聞かせてもらうのが好きだったそうで、イヤホンをしてスマホを眺めるだけの今の空気を少し寂しく感じていると話す。最近も機内でインテリアデザインのテレビ司会者と意気投合し、知り合いの家族が探していた車いすでも遊べる遊具づくりの話がつながったそうだ。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（4:52〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=292s"]]}, {"cat": "リングに来るまで", "t": "6歳で初渡米、母は客室乗務員", "b": "初めてアメリカに来たのは6歳のときだという。母が客室乗務員で、乗務するクリスマスのフライトに子どもたちを連れてニューヨークへ行き、セントラルパークでスケートをしたそうだ。記憶の中では自由の女神のそばで滑ったことになっているが、実際はそうではなかったと笑う。その後も母の短い滞在に連れてきてもらっていたという。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（7:24〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=444s"]]}, {"cat": "リングに来るまで", "t": "18歳でカナダへ、19歳で一度夢をあきらめる", "b": "18歳でカナダに移り、そこを拠点にアメリカでも試合をしていたという。ところがカナダのビザが切れ、レスリング以外の保険とアメリカに戻る手立てを兼ねてオーランドで別の道を探ったそうだ。そのころには19歳で「もう年を取りすぎた、夢は終わった、まともな仕事に就かないと」と思い込み、レスリングから離れていたと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（8:12〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=492s"]]}, {"cat": "家族", "t": "娘は弟が欲しいと言い続けている", "b": "娘はいつも「弟はいつ来るの」と聞いてくるという。本人ももう1人ほしい気持ちはあるが、レスリングも俳優業も勢いに乗っている今、時期は夫婦で考えているところだそうだ。娘に「ママがお金をたくさん稼いで仕事を終えたら、弟をもらえる？」と言われたときは胸にこたえたと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（10:35〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=635s"]]}, {"cat": "暮らし", "t": "働くのも、家で娘と過ごすのも好き", "b": "仕事が大好きで、試合の夜もドラマの撮影も一瞬一瞬を楽しんでいるという。そのうえで家に帰って娘の世話をする時間も大好きだそうだ。どちらもやりたいのに、とにかく時間が足りないと感じていると話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（11:23〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=683s"]]}, {"cat": "家族", "t": "家族バンドなら歌うのは娘", "b": "家族でバンドを組むなら、ボーカルは娘のルーだという。歌も踊りも得意で、ハーフのアイルランド人とは思えない腰の動きをするそうだ。家族で一番のダンサーは夫で、踊り出すと本当にかっこいいと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（26:22〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1582s"]]}, {"cat": "家族", "t": "家では「ボスは私」ということになっている", "b": "家の中では、夫が「妻がボス」ということにしてくれているという。夫は背が高く寡黙で物思いにふけるタイプだが、本人は夫を誰よりも尊敬していて、一番賢く、一番かっこよく、最高の父親だと話す。家族がいることこそが人生そのもので、キャリアはケーキの上のアイシングのようなものだと語る。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（28:00〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1680s"]]}, {"cat": "暮らし", "t": "ディナーパーティーを絶やさない", "b": "リングを離れていた1年間は、よく友人を招いてディナーパーティーを開いていたという。ディナーパーティーが廃れつつあるという記事を読み、「私の目の黒いうちはそうはさせない」と思ったそうだ。リビングで軽くつまんでからダイニングに移り、前菜、メイン、デザートと進むのが定番で、子どもたちは子ども同士で遊ぶので大人も楽しめると話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（29:38〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1778s"]]}, {"cat": "好きなもの", "t": "食卓での「シングソング」が好き", "b": "アイルランドでは食卓を囲みながら、順番に歌や詩、ジョークを披露する「シングソング」がよくあるという。本人はこれが大好きだが、会話が途切れてしまうので母は嫌がっているらしい。パーティーの余興は会話そのもので十分だと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（30:27〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1827s"]]}, {"cat": "暮らし", "t": "36歳の誕生日にツアーバスが火事", "b": "夫と娘を乗せたツアーバスでタルサからアイオワへ夜通し走っていた36歳の誕生日の夜、運転手のアンディが「火事だ、降りろ」と叫んだという。幼い娘を毛布にくるみ、家族全員はだしで近くのコンビニに駆け込んだそうだ。アンディが消火器で火を消し止めて無事だったが、店員から気遣いの言葉はなく、「消火器は返してくれるのか」と聞かれただけだったと苦笑する。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（40:21〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2421s"]]}, {"cat": "リングに来るまで", "t": "KOとサミとは2006年からの仲", "b": "5人組のドリームチームを組むならと聞かれ、夫に続いてすぐケビン・オーエンズとサミ・ゼインの名を挙げた。2人とは2006年から知り合いだという。5人目にはビアンカ・ブレアを選び、母親は優しすぎて戦えないから外したと笑う。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（43:41〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2621s"]]}, {"cat": "暮らし", "t": "SFドラマ出演は「帰りたくなかった」現場", "b": "最近いくつかの俳優の仕事に恵まれ、どれも心から楽しんでいるという。『スタートレック』の新シリーズでは、ポール・ジアマッティやホリー・ハンターと共演し、1日12〜14時間の撮影でも帰りたくなかったそうだ。第2シーズンにも戻る見込みだと話す。もともとは熱心なファンではなく、子どものころはチャンネルが4つしかなく家でよく流れていた、という程度だったという。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（47:43〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2863s"]]}, {"cat": "リングに来るまで", "t": "客室乗務員時代にヘムズワースと遭遇", "b": "自身も客室乗務員をしていたころ、シカゴでの宿泊中に早朝のジムで、まだアメリカで売れる前のクリス・ヘムズワースに会ったという。アイルランドで毎晩放送されていたオーストラリアのドラマ『ホーム・アンド・アウェイ』が大好きで、思わず声をかけたそうだ。そのうえ「ここでは誰もあなたを知らない」と余計なひと言まで言ってしまい、22歳の自分を今でも恥ずかしく思っていると話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（54:20〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3260s"]]}, {"cat": "体のこと", "t": "ネットから離れて8割増しで幸せ", "b": "できるだけインターネットから距離を置いているという。以前はスクロールが止まらず、人と比べては置いていかれる気がして、楽しくなかったそうだ。今は投稿はするが騒ぎにのまれないようにしていて、知識では遅れても、心の健康と幸せには大きなプラスだったと話す。周りの誕生日を知る機会が減ったのが難点だそうだ。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（58:31〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3511s"]]}, {"cat": "家族", "t": "一番の誇りはキャリアと家庭の両立", "b": "キャリアで一番好きな瞬間を聞かれ、特にないと答えた。それより、キャリアと家族の両方を手にできたことが一番うれしく誇らしいという。女性は家庭を持つためにいったん離れなければならず、戻る場所があるか不安になるからこそ、両立できたことが大きいと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:01:53〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3713s"]]}, {"cat": "リングに来るまで", "t": "17歳の初観戦でオートンと目が合った", "b": "初めてWWEの興行を観たのは17歳のときで、アイルランド公演のチケットを取って前のほうの席で観たという。ランディ・オートンが自分と目を合わせてくれたと確信していて、それだけで人生が輝いたと振り返る。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:08:23〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4103s"]]}, {"cat": "好きなもの", "t": "即興劇やクラウンにも挑戦", "b": "コメディドラマ『Movers』のパイロット版では、『リノ911』の制作陣と組み、即興の名手たちから多くを学んだという。シカゴに住んでいたころには、即興劇の名門セカンド・シティで少し学び、クラウンの稽古もしたそうだ。プロレスも常に即興なので、自分を信じて反応できるようになったと話す。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:10:54〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4254s"]]}, {"cat": "リングに来るまで", "t": "育成時代、見放さずにいてくれた人たち", "b": "育成ブランド時代の自分は見込みのない存在だったと振り返る。コーチだったジョーイ・マーキュリーは、そんな自分にもいつも親切にしてくれたという。カナダのバンクーバー時代には、スコッティ・マックという先輩から「自分を信じなければ、誰も信じてくれない」と言われ、その言葉を覚えているそうだ。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:17:21〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4641s"]]}]);
  if (PROFILES["Seth Rollins"]) PROFILES["Seth Rollins"].facts.push({"cat": "暮らし", "t": "どんな時も落ち着いている夫", "b": "夫のセス・ロリンズは、いつも冷静な人だとベッキー・リンチが話している。祭典前夜に聞き手のバスが燃えたときも、夫は窓の外を静かに眺めていたという。家族で一番のダンサーで、人にどう思われるかを気にしないところも夫らしいと話している。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で、ベッキー・リンチの話（公式字幕を全文確認）", "src": [["公式YouTube（37:55〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2275s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "見込みのない新人に目をかけた", "b": "育成時代の自分は見込みのない存在で、ダスティ・ローデスが何かを見いだしてくれなければ辞めていただろうと、ベッキー・リンチが話している。最後に交わした言葉は、アイデアを売り込もうと付きまとう自分への「黙れ、ベッキー」で、これ以上ない最後の言葉だったと振り返っている。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で、ベッキー・リンチの話（公式字幕を全文確認）", "src": [["公式YouTube（18:30〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1110s"]], "by": "第三者の話"});
  if (PROFILES["Jamie Noble"]) PROFILES["Jamie Noble"].facts.push({"cat": "暮らし", "t": "最初は怖かったが格闘技談義で打ち解けた", "b": "アイルランドでテレビを観ていたころからジェイミー・ノーブルのファンだったが、初めて会ったときは怖くてなかなか話しかけられなかったと、ベッキー・リンチが話している。ある日、総合格闘技の話で盛り上がってからは一気に打ち解け、その後は夫とも縁の深い存在になったという。", "sp": "ベッキー・リンチ", "d": "2025-08-20", "how": "コーディの番組で、ベッキー・リンチの話（公式字幕を全文確認）", "src": [["公式YouTube（1:16:31〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4591s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "好きなもの", "t": "釣りはしないが5時間の船旅", "b": "釣りをする人間ではないが、最近フロリダ州デスティン近くの湾で小さな船を借りたという。座る場所もない船で迷ったが、リッキー・セインツに「1時間くらいいいだろう」と押され、結局5時間近く海に出ていたそうだ。人付き合いも同じで、思い切って乗ってみるのが大事だと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（6:36〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=396s"]]}, {"cat": "家族", "t": "4歳の娘が出張を嫌がり始めた", "b": "4歳の娘が、父親が家を空けることを嫌がるようになってきたという。この日は愛犬ファラオも連れて行かないでと言われたそうだ。新しい広い子ども部屋も楽しい暮らしも父の仕事のおかげだと説明しても、4歳には通じないと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（12:58〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=778s"]]}, {"cat": "暮らし", "t": "バスでは後ろに隠れる静かな乗客", "b": "ツアーバスでは口数が少なく、すぐ後ろの席に引っ込んでしまうという。運転手のマットは好きだが、毎回「娘さんたちは元気？」と聞かれるのが、家族を置いてきた身にはこたえるそうだ。娘のほうはマットが大好きで、先日は助手席で4時間ずっとおしゃべりしていたと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（25:30〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1530s"]]}, {"cat": "好きなもの", "t": "自慢は炭火グリルで焼くステーキ", "b": "ビッグ・グリーン・エッグという炭火グリルで焼くステーキが自慢だという。撮影でアトランタに来ていたセス・ロリンズが立ち寄った際には、骨付きリブアイを焼き、冷めないよう到着に合わせて時間を計ったそうだ。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（31:15〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=1875s"]]}, {"cat": "暮らし", "t": "祭典前夜、寝ていたバスが燃えた", "b": "年間最大の祭典の期間は、町に来ている家族に自分のストレスをぶつけたくないので、会場の外に停めたバスで寝泊まりしていたという。眠って30分ほどで破裂音がし、運転手のマットの声で飛び起きると天井が燃えていたそうだ。家族の写真と試合用のブーツだけをつかんで逃げ、寒空の下、ロリンズ夫妻のバスに駆け込んだと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（36:18〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2178s"]]}, {"cat": "好きなもの", "t": "『スタートレック』を全シリーズ制覇", "b": "ある夜テレビで観た『新スタートレック』の1話に引き込まれ、そこから全シリーズと映画を観たという。WWEのプロデューサーの勧めで『エンタープライズ』、続いて『ヴォイジャー』、最後に『ディープ・スペース・ナイン』の順で観たそうだ。学歴は高校までだが、こうした作品や会話から学ぶのが好きだと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（45:21〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=2721s"]]}, {"cat": "暮らし", "t": "Xでは前向きな声にだけ返す", "b": "2年ほど前から、Xでは前向きな投稿にしか反応しないと決めているという。父や兄、家族、愛犬、娘、妻まで知られている以上、謎めいた存在に戻ることはできないので、ファンをそのまま一緒に連れていきたいそうだ。有酸素運動は近所を歩くのが習慣だと話す。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（51:04〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=3064s"]]}, {"cat": "リングに来るまで", "t": "子どものころの夢は大統領", "b": "ベッキーの母から大統領になるべきだと言われていると聞かされ、子どものころの夢はまさにそれだったと明かした。", "sp": "コーディ・ローデス", "d": "2025-08-20", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-Pcjw-ksGy9Y", "src": [["公式YouTube（1:13:21〜）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y&t=4401s"]]}]);
  ARTICLES.push({ id: "wdywta-Pcjw-ksGy9Y", d: "2025-08-20", show: "wdywta", who: ["Becky Lynch", "Cody Rhodes"], t: "ベッキー・リンチの回　客室乗務員時代の思い出から、夫と娘と過ごす今まで", lead: "コーディ・ローデスの番組に出た約80分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Becky Lynch", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-Pcjw-ksGy9Y").map((x) => [x.t, x.b, x.sp])), open: ["卵白オムレツをめぐる「コーディの嘘」のくだりや、ヒール論など試合・役柄に関わる話は載せていない。", "字幕の話者表示がたびたび入れ替わっており、「敵がほしい」「キャンセルされても構わない」といったやりとりは誰の発言か追い切れず載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=Pcjw-ksGy9Y"]] });
  if (!ROSTER.find((r) => r[1] === "Roxanne Perez")) ROSTER.push(["ロクサーヌ・ペレス", "Roxanne Perez", "lg", "NXTで活躍した若手", "", "", ""]);
  if (!PROFILES["Roxanne Perez"]) PROFILES["Roxanne Perez"] = { lead: "13歳から長距離バスで通い詰め、母に支えられて夢をつかんだ。粘り強さと演劇仕込みの表現力を武器にする、自称プロディジー。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Roxanne%20Perez"]], moves: [], facts: [] };
  if (PROFILES["Roxanne Perez"]._weak) { PROFILES["Roxanne Perez"].lead = "13歳から長距離バスで通い詰め、母に支えられて夢をつかんだ。粘り強さと演劇仕込みの表現力を武器にする、自称プロディジー。"; delete PROFILES["Roxanne Perez"]._weak; }
  PROFILES["Roxanne Perez"].facts.push(...[{"cat": "リングの話", "t": "ジャッジメント・デイと組んだ日常", "b": "取材の日は朝6時半に起きて、フードバンクの手伝いや病院での子どもたちとの面会、サイン会、試合のリハーサルを回ったという。ジャッジメント・デイは出番の多い集団で、男女で打ち合わせを合わせるのが大変だが楽しいと話す。主流のチームに入ることで、自分も注目されると感じているそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（0:47〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=47s"]]}, {"cat": "リングに来るまで", "t": "10歳でプロレスラーを志す", "b": "10歳のころ、物語性と運動能力が合わさったプロレスに惹かれたという。子どものころはスポーツに夢中で、演劇にも憧れていたため、両方を併せ持つ世界だと感じたそうだ。女性選手が活躍する姿を見て「自分にもできる」と思ったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=145s"]]}, {"cat": "好きなもの", "t": "習い事を次々に替えた子ども時代", "b": "サッカー、バレエ、体操、チアリーディング、バスケットボールと、プロレスに出会うまでいろいろな競技を渡り歩いたという。母親は新しい靴や道具を毎回買うことになり、うんざりしていたそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=145s"]]}, {"cat": "好きなもの", "t": "夢中になったロックとジョン・シナの一戦", "b": "幼いころに強く印象に残ったのは、ザ・ロックとジョン・シナの大一番の物語だったという。試合までの流れや、ロックがギターを手に歌った場面なども含め、すべてが格好よく映ったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=196s"]]}, {"cat": "リングに来るまで", "t": "ブッカーTの学校を自分で見つけた", "b": "10歳のころ、家のパソコンで調べてヒューストンにあるブッカーTのプロレス学校を見つけたという。故郷から5、6時間かかる場所だが、電話で「18歳になったら通う」と伝えたそうだ。義父は3歳のころから一緒にいて、実の父のような存在だと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=242s"]]}, {"cat": "リングに来るまで", "t": "地元の小さな団体で裏方から", "b": "義父が見つけた地元の団体の興行に、幼いころから連れて行ってもらったという。11歳のころには主催者に頼まれて選手の上着を運ぶ手伝いをし、大喜びで引き受けたそうだ。13歳のころ、地元の2人の選手から本格的に指導を受け始めたと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=242s"]]}, {"cat": "家族", "t": "母が12歳での入門を「あと1年待って」と言われた", "b": "母親は12歳のときに練習を頼んだが、「あと1年待って、まず体づくりを」と言われたそうだ。13歳で改めて通い始めた初日は、倉庫のようなリングに汗だくの年上の男性ばかりで、母親は「何をさせてしまったのか」と思ったかもしれないと笑う。体操とチアの経験のおかげで動きはすぐ身についたという。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（4:52〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=292s"]]}, {"cat": "家族", "t": "初めての受け身で母に背中を押された", "b": "最初の受け身がいちばん怖く、30分ほど「できない」と言い続けたという。見かねた母親が、暑い中ここまで運転してきた、夢だと言うのにやらないなら帰って二度と来ない、と告げたそうだ。リングに戻って受け身を取ると、母親は「ほら、できたでしょ」と言ったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（6:28〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=388s"]]}, {"cat": "家族", "t": "母は一番の支え。大会を一緒に見た", "b": "母親は練習にも試合にも付き添い、長距離バスで通う日もあったという。女性だけの大型大会を母親とソファで見て、いつかあのリングに立つと話した思い出があり、7年後の2回目の大会では本人が出場し、母親と舞台裏で主役の試合を見たそうだ。その日の夜、他の女性選手と祝杯を挙げる場にも母親を呼んだという。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（7:20〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=440s"]]}, {"cat": "リングに来るまで", "t": "長距離バスで通い、宿題はバスの中", "b": "故郷からヒューストンまで、休みのたびに長距離バスで通ったという。叔母夫婦の家のソファに泊めてもらい、練習場へ通ったそうだ。宿題はバスの中で済ませ、高校の最終学年のころは大学の授業も並行し、試合の合間に控室でオンラインの試験を終わらせたこともあったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（8:05〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=485s"]]}, {"cat": "リングに来るまで", "t": "13歳から始めた憧れの先輩たち", "b": "ペイジ、ベッキー・リンチ、AJ・リーなど、若くして始めた女性選手に憧れていたという。ペイジとベッキーは13歳で練習を始めたと知り、自分もすぐ始めなければと思ったそうだ。18歳までに腕を磨けば追いつけるという思いが支えになったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（9:41〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=581s"]]}, {"cat": "リングに来るまで", "t": "ブッカーTとシャーメルは第二の親", "b": "16歳のころから教わったブッカーTと、その妻のシャーメルを、第二の親のように感じていたという。細くて小柄な16歳の自分を、真剣だと見込んで鍛えてくれたことに感謝しているそうだ。学校ではカメラの位置や表情、時間の合図まで教わり、小さなテレビ番組の現場のような環境だったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（10:33〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=633s"]]}, {"cat": "リングに来るまで", "t": "入場曲が鳴ってもブーツが履けなかった夜", "b": "17、18歳のころ、控室で試合の打ち合わせに手間取り、片方のブーツが履けないまま入場曲が鳴ってしまったことがあるという。ブッカーTに大声で叱られ、仲間が先にリングで場をつないでくれたそうだ。試合後に「挽回したな」と言われた経験から、今は会場に着いたらすぐ準備すると話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（12:58〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=778s"]]}, {"cat": "暮らし", "t": "会場の日課とエスプレッソマシン", "b": "放送日の会場では、まず入場の撮影があれば着替え、ケータリングのエスプレッソマシンでコーヒーを淹れるのが楽しみだという。使い方は挑戦したらすぐ覚えたそうだ。その後リングで試合の打ち合わせをして、メイクの時間を迎える。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（16:59〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1019s"]]}, {"cat": "暮らし", "t": "メイクの時間は気持ちを休める時間", "b": "忙しい日でも、メイクの間は試合のことを考えずに落ち着けると感じているという。他の女性選手と話せる時間でもあり、メイク担当の人たちはとても大切な存在だと話す。みんなで「癒やされる時間」だと言い合っているそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（17:46〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1066s"]]}, {"cat": "リングの話", "t": "ラクエルとの相性と、偶然の入場演出", "b": "ラクエルとは下部団体時代に対戦や共闘があり、14歳の自分の初試合にも彼女がいたという。その日付を手首に刻んでいるそうだ。背が高く力強いラクエルと、素早く攻撃的な自分が噛み合うと話す。2人の入場の動きも、ある日たまたま試したら好評で定番になったという。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（20:12〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1212s"]]}, {"cat": "リングの話", "t": "悪役に合わせた新しい入場曲", "b": "新しい入場曲は、以前よりポップさを抑えた、暗くて神秘的な雰囲気だという。悪役としての自分が以前の明るい性格から変わったためで、気に入っていると話す。悪役の手本として挙げたのは、エディ・ゲレロ、CMパンク、AJ・リー、アレクサ・ブリスだそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（23:21〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1401s"]]}, {"cat": "リングの話", "t": "NXT王座を2度目に取って「ここにいていい」と思えた", "b": "1度目の王座は、移籍して数か月、20歳のときに当日に知らされたという。周囲の声が気になり、マイクにも自信がなかったそうだ。悪役に転向し、1年間の王座期間で多くの試合をこなして、ようやく「プロディジー」の名にふさわしいと実感できたと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（24:59〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1499s"]]}, {"cat": "リングの話", "t": "マイクは台本のように分解して覚える", "b": "演劇出身なので、箇条書きより文章を覚えるほうが得意だという。台本のように段落分けして、丸や下線で印を付け、話の筋ごと頭に入れるそうだ。悪役になってから毎週1ページ分のマイクを任され、それで慣れたと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（29:00〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1740s"]]}, {"cat": "家族", "t": "祖母はスペイン語だけ。故郷は国境の町", "b": "祖母はスペイン語しか話さず、そのおかげで聞き取りはほぼできるという。母親は家ではあまりスペイン語を使わず、怒ったときの言葉だけ覚えたと冗談めかして話す。故郷のラレドは住民のほとんどがヒスパニック系で、国境沿いにある町だそうだ。流暢に話せるようになることが目標で、祖母とも話したいという。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（32:14〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1934s"]]}, {"cat": "リングの話", "t": "決め技「ポップロックス」の名前の由来", "b": "決め技は、ショーン・マイケルズとマット・ブルームらと考えたという。体格差で使えない技を除き、インディー時代のコードレッドに行き着き、名前はショーンの冗談から決まったそうだ。ゼリーナがコードレッドを使うため、同じ番組ではどちらかが控えると話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（33:00〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=1980s"]]}, {"cat": "リングの話", "t": "忘れられない瞬間は、初のNXT王座と母", "b": "忘れられない場面として、初めてNXT王座を取ったとき、ブッカーTに手を上げてもらい、紙吹雪の中で家族が見ていたことを挙げている。もう一つが女性だけの大型大会の夜に母親と迎えた祝杯だという。年下の世代として初めてスマックダウンで試合をした選手かもしれないとも聞いたそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（36:10〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2170s"]]}, {"cat": "リングの話", "t": "目標はグランドスラムとメインイベント", "b": "女子のグランドスラム王者になることと、年間最大の祭典でメインイベントを務めることが目標だという。ルールが変わって、NXTの北米王座なども含めて考え直す必要があると話す。まだ戦っていない相手として、ベイリー、シャーロット・フレアー、ニア・ジャックスらを挙げている。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（40:03〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2403s"]]}, {"cat": "リングに来るまで", "t": "団体の最年少王者から初代王者へ", "b": "ブッカーTがWWEとつながりを持っていても、近道はなく、自分の力で結果を出す必要があったという。地元の団体で最年少の王者になり、その後、別の団体の女子トーナメントで優勝して初代王者になったそうだ。団体が閉鎖されると知ったときは、先が見えず怖かったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（44:04〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2644s"]]}, {"cat": "リングに来るまで", "t": "最後の収録の日にかかってきた電話", "b": "団体の最後の収録の控室で、知らない番号から電話があり、ウィリアム・リーガルからトライアウトの誘いを受けたという。思わず泣いてしまい、母親に電話するとやはり泣いていたそうだ。トライアウトはその2か月後だったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（45:41〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2741s"]]}, {"cat": "リングに来るまで", "t": "「必ずうまくいく」という確信と粘り強さ", "b": "なぜかいつも「自分は成し遂げる」という感覚があり、望むことは諦めない性格だと話す。昨年のドラフトで昇格できなかったときも落ち込まず、毎日追加の練習やマイクの練習に打ち込んだという。1年後に昇格が決まったそうだ。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（47:12〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2832s"]]}, {"cat": "好きなもの", "t": "愛犬ワイアットと恋人", "b": "感謝していることとして、安心できる家、仕事、優しい恋人と愛犬を挙げている。愛犬のゴールデンレトリバーは、好きだったブレイ・ワイアットにちなんで名付けたそうだ。恋人は現在、あるチーム対抗の番組に出ていると話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（50:27〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=3027s"]]}, {"cat": "リングの話", "t": "自信作はラーラ・ヴァルキリアとの一戦", "b": "自分を知ってもらう試合として、2度目のNXT王座を取ったラーラ・ヴァルキリアとの試合を挙げている。自分が「プロディジー」だと証明できた試合だそうだ。相手の技術と相性の良さにも触れ、一緒にやりやすかったと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（50:27〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=3027s"]]}, {"cat": "体のこと", "t": "コロナ禍に落ち込み、母に励まされた", "b": "コロナ禍でプロレスの機会が次々になくなり、一時は気持ちが沈んだという。大会のトライアウトや、ナタリヤとの練習の話も流れてしまったそうだ。母親に「起きて体を動かしなさい、再開したらすぐ走り出せるように」と励まされ、持ち直したと話す。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-z_CDKA170Q4", "src": [["番組のYouTube（52:03〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=3123s"]]}]);
  if (PROFILES["Bailey"]) PROFILES["Bailey"].facts.push({"cat": "暮らし", "t": "ベイリーに母を呼んでもらった夜", "b": "大型大会の後の女性ロッカールームで、ベイリーが「お母さんも連れておいで」と声をかけてくれたと、ロクサーヌ・ペレスが話している。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で、ロクサーヌ・ペレスの話（字幕を全文確認）", "src": [["番組のYouTube（51:18〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=3078s"]], "by": "第三者の話"});
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "CMパンクは若手の試合を見に来てくれた", "b": "NXT時代、大きな興行の日でも早めに会場で若手の試合を見に来てくれ、助言もくれたと、ロクサーヌ・ペレスが話している。", "sp": "ロクサーヌ・ペレス", "d": "2025-08-21", "how": "クリス・ヴァン・ヴリートの番組で、ロクサーヌ・ペレスの話（字幕を全文確認）", "src": [["番組のYouTube（37:48〜）", "https://www.youtube.com/watch?v=z_CDKA170Q4&t=2268s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-z_CDKA170Q4", d: "2025-08-21", show: "ext", who: ["Roxanne Perez"], t: "ロクサーヌ・ペレスの回　バスで通った少女が頂点へ", lead: "クリス・ヴァン・ヴリートの番組に出た約54分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Roxanne Perez"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-z_CDKA170Q4").map((x) => [x.t, x.b, x.sp])), open: ["地元の指導者や同門の私人の名前、恋人の話の詳細は載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=z_CDKA170Q4"]] });
  if (!ROSTER.find((r) => r[1] === "Hijo de Dr. Wagner Jr.")) ROSTER.push(["イホ・デ・ドクトル・ワグナーJr.", "Hijo de Dr. Wagner Jr.", "lg", "", "", "", ""]);
  if (!PROFILES["Hijo de Dr. Wagner Jr."]) PROFILES["Hijo de Dr. Wagner Jr."] = { lead: "祖父、父と受け継いだ覆面を、日本の団体で頂点まで押し上げたイホ・デ・ドクトル・ワグナーJr.。リングで遊んだ子ども時代から、日本での修行、叔父との別れまでを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Hijo%20de%20Dr.%20Wagner%20Jr."]], moves: [], facts: [] };
  if (PROFILES["Hijo de Dr. Wagner Jr."]._weak) { PROFILES["Hijo de Dr. Wagner Jr."].lead = "祖父、父と受け継いだ覆面を、日本の団体で頂点まで押し上げたイホ・デ・ドクトル・ワグナーJr.。リングで遊んだ子ども時代から、日本での修行、叔父との別れまでを語る。"; delete PROFILES["Hijo de Dr. Wagner Jr."]._weak; }
  PROFILES["Hijo de Dr. Wagner Jr."].facts.push(...[{"cat": "リングに来るまで", "t": "2歳から叔父にトペを放っていた", "b": "メキシコ北部のトレオンで生まれ、両親の仕事に合わせてメキシコシティへ移ったと、ワグナーJr.は話す。物心ついた頃には一家が営む会場が遊び場で、2歳の頃から叔父エル・オリエンタルにトペを放っていたという。週末はいすを並べ、売店でビールやおつまみを売る手伝いもしたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（5:39〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=339s"]]}, {"cat": "家族", "t": "父の試合バッグを詰めるのが役目", "b": "平日はおとなしく内気な子どもだったが、日曜になると覆面をかぶった小さなレスラーになったと、ワグナーJr.は振り返る。幼い頃から、仕事に厳しい父の試合バッグを詰めるのが自分の役目だったという。ブーツを磨いてひもを巻き、最後に白い覆面を入れる手順を今も覚えているそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（7:14〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=434s"]]}, {"cat": "家族", "t": "母も名の知れた女子レスラー", "b": "両親が出会った頃は、母ロッシー・モレノの方が父より有名だったと、ワグナーJr.は話す。父は英雄で手本、母は泣きついて何でも話せる「クッション」のような存在だという。母は日本遠征中に妊娠が分かり、ツアーを切り上げたこともあったそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（7:59〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=479s"]]}, {"cat": "家族", "t": "2人の祖父も名レスラー", "b": "父方の祖父ドクトル・ワグナーと、母方の祖父アコラサード・モレノの両方に12歳ごろまでかわいがってもらったと、ワグナーJr.は話す。世界を旅した母方の祖父からは旅好きを受け継いだという。悪役として知られた父方の祖父も、孫には愛情たっぷりだったそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=674s"]]}, {"cat": "リングに来るまで", "t": "11歳で祖父から覆面を託された", "b": "11歳ごろ、祖父ドクトル・ワグナーに小部屋へ呼ばれ、白い覆面を渡されて「これはお前のものだ」と言われたと、ワグナーJr.は話す。覆面をくれたのは父ではなく祖父だったという。とても特別な思い出だそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（13:40〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=820s"]]}, {"cat": "リングに来るまで", "t": "反対する両親の家を出てデビュー", "b": "18歳でレスラーになると告げると、学業を重んじる父に「この道は自分の力で切り開け」と言われ、家を出る覚悟を決めたと、ワグナーJr.は話す。母にも、別の名前で経験を積むよう勧められたが、最初からこの名前で行くと譲らなかったという。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（14:30〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=870s"]]}, {"cat": "リングに来るまで", "t": "最初の機会をくれたのはイホ・デル・ペロ・アグアヨ", "b": "叔父エル・オリエンタルに頼み、イホ・デル・ペロ・アグアヨの団体で2009年12月5日にデビューの場をもらったと、ワグナーJr.は話す。「昔誰かが自分に機会をくれた、その恩を君に返す」と言われた言葉を一生忘れないという。叔父の指導は日本式で厳しく、血だらけになっても立ち上がり続けたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（16:14〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=974s"]]}, {"cat": "リングに来るまで", "t": "「親の七光り」と言われ続けた最初の数年", "b": "最初の数年は「3代目に良いものはない」「父のおかげで出られる」と批判され、自分を疑ったこともあったと、ワグナーJr.は話す。18歳でWWEのトライアウトを受け、ロサンゼルスに1年住んだが、思うようにいかず落ち込んで帰国したという。覆面の下には一人の人間がいる、と訴えている。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（30:40〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=1840s"]]}, {"cat": "暮らし", "t": "父から渡された成功の公式", "b": "父から紙に書いた「態度、継続、規律」という成功の公式を渡されたと、ワグナーJr.は話す。自分はそこに「忍耐」と「情熱」を足し、その上に「犠牲」を置いているという。どこへ行っても空き時間にジムへ通うのは、父に植え付けられた習慣だそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（34:10〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2050s"]]}, {"cat": "体のこと", "t": "何度も外れた鎖骨", "b": "試合でトペを受けたときに初めて鎖骨が外れ、ベテランのピラタ・モルガンが元に戻してくれたと、ワグナーJr.は話す。それ以来、肩はずっと痛めたままで、脱臼や痛みと付き合っているという。けがのことも知らずに「動きが悪い」と言われるのはつらいそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（37:40〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2260s"]]}, {"cat": "家族", "t": "両親が誕生日に来られなかった理由が分かった", "b": "子どもの頃は、遠征で誕生日や卒業式に来られない両親に腹を立てていたと、ワグナーJr.は話す。自分も日本で5年暮らし、母の誕生日に一度も帰れなかったことで、両親の気持ちが分かったという。プロレスが子どもの頃の疑問に答えをくれた、と語っている。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（39:24〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2364s"]]}, {"cat": "リングの話", "t": "メキシコ人で初めてGHCヘビー級王者に", "b": "5年かけて階段を上り、メキシコ人として初めてGHCヘビー級王座を手にしたと、ワグナーJr.は話す。団体の顔としてポスターの中央に載るようになったことも誇りだという。日本ではプロレスは本格的なスポーツで、毎日の練習も仕事として決まっていたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（42:37〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2557s"]]}, {"cat": "リングの話", "t": "「父が引退するまで何もできない」と言われて", "b": "父と組んで戦っていた頃、父に「父さんが引退するまで、お前は何者にもなれない」と言われたと、ワグナーJr.は話す。胸に刺さる言葉だったが、言ってくれてよかったと思っているという。そこから父の影を離れる道を探し始めたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（45:16〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2716s"]]}, {"cat": "暮らし", "t": "日本は「夢の牢獄」", "b": "日本では一人で小さなアパートに住み、試合後は傷だらけで誰もいない部屋に帰ったと、ワグナーJr.は話す。日本のことを「夢の牢獄」と呼んでいるという。寂しくても涙を拭いて前へ進む経験が、自分を人として大きく変えたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（46:41〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2801s"]]}, {"cat": "リングに来るまで", "t": "日本の団体NOAHへ", "b": "女子団体の興行に父と一緒に招かれた日本で、関係者からプロレスリング・ノアに誘われ、2019年ごろから参戦したと、ワグナーJr.は話す。最初のリーグ戦では、メキシコよりはるかに厳しく打ちのめされたという。1発打てば2発、2発打てば4発返ってくる世界だったそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（49:42〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=2982s"]]}, {"cat": "体のこと", "t": "脳しんとうとコロナで、日本に区切り", "b": "最後のリーグ戦の前に新型コロナにかかり、その後の試合で脳しんとうを起こして入院したと、ワグナーJr.は話す。4週間試合を休み、全身の検査を受けたという。5年がたち、全部を勝ち取ったこともあって、成長のために動く時期だと決めたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（52:13〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=3133s"]]}, {"cat": "リングの話", "t": "素顔での誘いは断った", "b": "ある大きな団体から、覆面の下の人物としてなら興味があるという話をもらったが、明確な計画もなかったので断ったと、ワグナーJr.は話す。日本からメキシコを通らずに米国の育成拠点へ行くことは想像できなかったという。まず母国で何かを成し遂げたかったそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（56:11〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=3371s"]]}, {"cat": "リングの話", "t": "大きな合同大会の夜「元は取れた」", "b": "AAAとWWEの合同大会に出たとき、家族に「元は取れた」と伝えたと、ワグナーJr.は話す。3代にわたる覆面を世界中の人に見てもらえたことが何よりうれしかったという。いつも自分に厳しすぎて楽しめないが、あの週だけは宙を飛んでいるようだったそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（57:47〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=3467s"]]}, {"cat": "家族", "t": "叔父シルバー・キングとの突然の別れ", "b": "叔父で2人目の師でもあるシルバー・キングが海外の試合中に倒れて亡くなったとき、家族でジムにいたと、ワグナーJr.は振り返る。泣き崩れる父に代わって電話を受け、祖母に知らせたのが一番つらかったという。叔父は「生まれながらのレスラー」で、その死は自分の人生を変えたそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（1:12:23〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=4343s"]]}, {"cat": "家族", "t": "弟ガレノ・デル・マルに大きな期待", "b": "弟のガレノ・デル・マルは日本で修行していて、大きな体と笑顔の持ち主だと、ワグナーJr.は話す。練習で本気のエルボーを打たれて止めたこともあるという。いつか父と兄弟3人で同じリングに立つのが夢だそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2025-08-25", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-aB4l3Q7DzV0", "src": [["番組のYouTube（1:20:27〜）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0&t=4827s"]]}]);
  ARTICLES.push({ id: "ext-aB4l3Q7DzV0", d: "2025-08-25", show: "ext", who: ["Hijo de Dr. Wagner Jr."], t: "イホ・デ・ドクトル・ワグナーJr.の回　2つの名門、日本での5年、「元は取れた」という夜", lead: "ラテン・ラバーの番組に出た約87分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Hijo de Dr. Wagner Jr."].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-aB4l3Q7DzV0").map((x) => [x.t, x.b, x.sp])), open: ["家族の本名は載せていない。", "叔父の死因や当時の詳しい状況は、要点だけにとどめた。", "広告と、聞き手自身の家族の話は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=aB4l3Q7DzV0"]] });
  if (!PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Roman%20Reigns"]], moves: [], facts: [] };
  if (PROFILES["Roman Reigns"].lead === "") PROFILES["Roman Reigns"]._weak = 1;
  PROFILES["Roman Reigns"].facts.push(...[{"cat": "リングの話", "t": "ポール・ヘイマンと通じ合った瞬間", "b": "一番の思い出を聞かれ、ローマンは王座に君臨していた時期そのものが魔法のようだったと話す。入場のたびに鳥肌が立つことがあり、ヘイマンが背後から「また観客をつかんだぞ」と囁いてくれたそうだ。嵐の目に向かって二人で進んでいく感覚を、今も大切にしているという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（17:17〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1037s"]]}, {"cat": "リングの話", "t": "映画の主演もメインイベントも両立したい", "b": "ローマンは、映画で主役級を務めながらPPVのメインも張る初めての選手になりたいと話す。ジョン・シナも自分なりの形でやったと認めつつ、その責任を両方背負える世代でありたいそうだ。ほかの仕事をするためにWWEのスーパースターをやめたくはなく、どちらかを選ぶつもりもないという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（23:46〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1426s"]]}, {"cat": "リングの話", "t": "シナの後を継ぎ、自分らしさを選んだ", "b": "いつでも電話に出て断らないシナが、会社の基準になっていたとローマンは話す。その後を任された自分は、できる限り努めたうえで、結局は自分に正直でいるしかなかったという。会社が求めたのは仲間の一人ではなくスーパースターで、誰かの真似では独創的なものは生まれないと考えたそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（26:09〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1569s"]]}, {"cat": "リングの話", "t": "崖っぷちでも自分に賭けられた理由", "b": "自分に賭ける決心ができたのは、積み重ねた1万時間があったからだとローマンは話す。盲目的な信仰ではなく、特別なことができる手前まで来ている確信があったという。一度やり遂げれば証明になり、またできると思えるため、まず反復して極めることが先だと語る。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（27:40〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1660s"]]}, {"cat": "リングの話", "t": "プロモは削って短くするもの", "b": "同じことを何度もこなすと、段取りが仕組みになって考えなくて済むようになるとローマンは話す。今のプロモでは、自分は言葉数が多いので、いかに絞って要点だけにするかを考えているそうだ。経験を重ねた準備が本番の余裕につながるという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（30:11〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1811s"]]}, {"cat": "リングの話", "t": "シールド時代は自分の試合映像を一歩ずつ見返した", "b": "デビュー当時のローマンは、シールドの試合映像を一歩ずつ、なぜその腕の使い方をしたのかまで確認していたという。巻き戻しが不便な環境でも何度も見返し、妻が一緒に見ていられないほどだったそうだ。顔の表情は表現が強すぎると、ビンス・マクマホンに抑えるよう言われたこともあると話す。今ではそうした経験が本能になっているという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（31:09〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1869s"]]}, {"cat": "リングの話", "t": "ステフの平手打ちで鼓膜が破れた", "b": "ローマンは、ステフ・マクマホンとの絡みで何度も平手打ちを受けた思い出を笑いながら話す。打つなら本気で打てという考えで、その平手で鼓膜が破れたと冗談めかして語る。ステフは序盤は上手だったが途中から加減を忘れたといい、大舞台での槍は取っておいたとも振り返る。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（44:05〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=2645s"]]}, {"cat": "リングの話", "t": "悪役は王族になったつもりで演じる", "b": "ローマンはヒールを演じるとき、自分が王族だと思い込むのがコツだと話す。部族の長として君臨した時期は、周りの人間は皆自分より下にいる感覚があり、キャラクターとして気持ちよかったという。ステフも同じ考え方だったと話し、その役作りが楽しかったそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（45:41〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=2741s"]]}, {"cat": "リングの話", "t": "「失敗したベビーフェイス」と言われた時期", "b": "ローマンは、あの頃の自分は観客にブーイングされた失敗したベビーフェイスと見られていると話す。ただ本人は、ライブの会場でも毎週最後には観客を取り返そうとしていたという。流れに乗るべき場面でも逆らって摩擦を生んでいたが、自分のペースで学ぶ貴重な時間だったそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:24:05〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=5045s"]]}, {"cat": "リングの話", "t": "安易な悪口には頼らない", "b": "ヘイマンが出してくれる安っぽい挑発のセリフを、ローマンは断るか自分なりに作り替えていたという。ジョージア工科大出身の自分は、もう少し知的で洗練された言葉選びができるはずだと考えたそうだ。ただ、時にはシンプルに笑わせるほうがいい場面もあるとも認める。プロレスは演技と格闘が合わさった、極めるべき芸術だと語る。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:24:52〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=5092s"]]}]);
  if (!PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"] = { lead: "高校生の娘と幼い息子たちを持つ父親で、家庭を何より優先すると話す。大学時代に白血病と診断された経験や、母と姉妹に支えられた日々も率直に振り返っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Roman%20Reigns"]], moves: [], facts: [] };
  if (PROFILES["Roman Reigns"]._weak) { PROFILES["Roman Reigns"].lead = "高校生の娘と幼い息子たちを持つ父親で、家庭を何より優先すると話す。大学時代に白血病と診断された経験や、母と姉妹に支えられた日々も率直に振り返っている。"; delete PROFILES["Roman Reigns"]._weak; }
  PROFILES["Roman Reigns"].facts.push(...[{"cat": "好きなもの", "t": "チョコと甘いものに目がない", "b": "好物を聞かれて、チョコレートやピーナツバターなど甘いものなら何でも好きだと答えている。自分のことを冗談まじりに「食いしん坊」と呼ぶ。妻は逆に食に執着がなく、忙しさで食べるのを忘れてしまうタイプだという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（0:01〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1s"]]}, {"cat": "家族", "t": "5歳半の息子たちが就学、家が静かに", "b": "下の息子たちは5歳半で、幼稚園に通い始めたところだと話す。子どもが全員学校へ行くようになり、昼間の家が急に静かになって戸惑ったそうだ。仕事も家庭も含め、いまが人生でいちばん忙しい時期だと感じているという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（3:20〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=200s"]]}, {"cat": "家族", "t": "高校最上級生の娘が運転デビュー", "b": "娘は高校の最上級生で、最近になって車の運転を始めたという。朝は息子たちを学校に送った帰り道、ハンドルを両手で固く握って運転する娘とすれ違うのを見守っているそうだ。自分を大学に一人で送り出した母はどんな気持ちだったのかと考えるようになったと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（5:03〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=303s"]]}, {"cat": "家族", "t": "娘の進学先に両親の母校も候補", "b": "娘の進学先は、フロリダに残るか、両親が通ったジョージア工科大学に進むかで検討中だという。大学見学にも行き、娘も気に入っていたそうだ。妻の実家は大学から車で2時間ほどの田舎にあり、義父はどこへでも車で駆けつける人だと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（6:35〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=395s"]]}, {"cat": "家族", "t": "11〜12歳で祖父母と大陸横断", "b": "子どもの頃、母方の祖父母が毎夏ペンサコーラを訪ね、孫を一人ずつ連れて帰る習慣があったという。自分の番が来た11〜12歳の夏、フロリダからカリフォルニア州サニーベールまで車で国を横断した。途中のテキサスに親戚が大勢いると、そのとき初めて知ったそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（7:25〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=445s"]]}, {"cat": "家族", "t": "母方のルーツはシチリアと英国系", "b": "母方の曾祖母の一家はシチリアから移民してテキサスに落ち着いたと聞いているという（本人も歴史には詳しくないと前置きしている）。母方の祖父は英国やアイルランド系、祖母は小柄で気の強いイタリア系だったそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（8:16〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=496s"]]}, {"cat": "リングに来るまで", "t": "テキサスの農場で初めて母方の親戚と", "b": "それまでは父方のサモア系の親族とばかり過ごしていたため、テキサスで会った従兄弟たちはほとんど初対面だったという。親戚は大きな農場を営んでおり、町の人がみんな集まる湖で遊んだ夏は、90年代の映画のサマーキャンプのようだったと懐かしむ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（10:44〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=644s"]]}, {"cat": "家族", "t": "祖母の家を「お金持ち」と思った", "b": "サニーベールの祖母の家は数段上がると上の階がある造りで、子どもの目には豪邸に見えたそうだ。当時ペンサコーラの家は経済的に苦しく、カリフォルニアに来て「これが成功か」と感じたという。庭にはイチジクやレモン、柿の木があり、祖母はとにかくプルーンを勧めてくる人だったと笑う。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（11:32〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=692s"]]}, {"cat": "体のこと", "t": "7歳で約34kg、計量のため減量も", "b": "7歳の時点で体重が75ポンド（約34kg）ある大柄な子どもだったという。フットボールの体重制限に収めるため、プルーンジュースを飲んだり、ゴミ袋をかぶって汗をかいたりして減量したそうだ。自分から母に頼み込んだことで、母は乗り気ではなかったと強調している。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（13:10〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=790s"]]}, {"cat": "家族", "t": "父は一時不在、戻ってからはいつも早く", "b": "幼い頃の一時期、父は「巡業中」ということにして、実はサモアに戻って立て直していたという。1年ほどで戻り、両親は別々に暮らしていたが父はいつもそばにいたそうだ。行事には毎回早すぎるほど早く現れ、母が料理を始める前に着いて呆れられていたと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（14:47〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=887s"]]}, {"cat": "暮らし", "t": "遅れがちなのに到着を焦る性分", "b": "父と違って自分は少し遅れがちだが、遅れると到着するまで落ち着かなくなるという。移動のときはとにかく早く目的地に着きたい気持ちになり、自分で自分を追い込んでいると認めている。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（15:39〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=939s"]]}, {"cat": "暮らし", "t": "「家では家族のそばにいろ」が軸に", "b": "若い頃、仕事に没頭しすぎて家庭がおろそかになっていた時期に、ビンス・マクマホンから「家に帰ったらそこに心を置け」と言われたという。その言葉を深く受け止め、いまでは逆に家を離れているときのほうが心ここにあらずになるほど、妻と子どもを最優先にしていると話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（21:16〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1276s"]]}, {"cat": "リングに来るまで", "t": "大学2年で出会った守備ラインのコーチ", "b": "ジョージア工科大学2年のとき、新しく来た守備ラインのコーチとの出会いが転機だったという。説教ではなく自分の経験やたとえ話で伝えてくれる人で、血気盛んな若者だった自分にも言葉が素直に入ったそうだ。いまも連絡を取り合い、試合会場に来てくれたこともあると話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（39:08〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=2348s"]]}, {"cat": "リングに来るまで", "t": "父親代わりは各地のコーチたち", "b": "父が近くにいなかった時期、地域や球場の大人の男性たちに育ててもらったと振り返る。とりわけ少年野球で8年続けて指導してくれたコーチは、車での送り迎えまでしてくれたそうだ。いろいろなコーチから少しずつ良いところを「盗んで」きたと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（42:26〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=2546s"]]}, {"cat": "リングに来るまで", "t": "思い描いていたのはNFLの守備ライン", "b": "自分はペンサコーラ出身の「ただのビーチボーイ」で、アトランタの大学でチームメイトとの絆に支えられたという。自分で筋書きを書いていたら、49ersのディフェンシブタックルとして8年ほどプレーして終わっていただろうと話す。実際の人生はそれよりずっと大きなものになったと感じているそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（49:42〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=2982s"]]}, {"cat": "体のこと", "t": "NFLキャンプの血液検査で白血病が判明", "b": "ミネソタ・バイキングスのキャンプ中、身体検査の血液検査で白血球の数値が異常に高いことが分かり、血液のがんと診断されたという。自覚症状はなく、当時は体重300ポンド（約136kg）の大学生で疲れにも気づかなかったそうだ。抗がん剤や放射線ではなく服薬で治療できたため、同情されることに後ろめたさも感じたと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（52:07〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=3127s"]]}, {"cat": "体のこと", "t": "出場が減った時期の「本番後の落ち込み」", "b": "パンデミックを経て契約が見直され出場日程が減ると、大舞台のあと1か月ほど刺激のない期間が続き、気分が沈むことがあったという。次の目標に向けて日々を組み立てる仕組みを作って乗り越えたそうだ。幸せは常に続く状態ではなく、自分の心の状態に正直でいることが大事だと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（55:20〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=3320s"]]}, {"cat": "体のこと", "t": "重荷を引き受けてくれた母と姉妹", "b": "若かったこともあり、診断をきちんと受け止められていなかったと振り返る。不安や負担の大部分を母が肩代わりしてくれたことに、いまも感謝しきれないという。母や姉妹、家族全員が穴のない安全網のように支えてくれたと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（56:55〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=3415s"]]}, {"cat": "暮らし", "t": "人は許せても自分は責めてしまう", "b": "過去の決断や振る舞いを後悔するタイプだと自己分析している。他人のことはすぐ許せるが、自分のことはいつまでも覚えていて責めてしまうという。ただ、そこから学びを得られるなら意味があると考えているそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（59:25〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=3565s"]]}, {"cat": "暮らし", "t": "双子のいとこと張り合って育った", "b": "子どもの頃からずっとウーソズの双子と競い合ってきたという。「双子のもう一人」のように埋もれたくない、目立ちたいという負けん気がいまもあると話す。一族の若い世代には、電話一本で相談に乗れる存在でいたいそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:07:25〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=4045s"]]}, {"cat": "家族", "t": "姉に蹴られたスナネズミの一件", "b": "子どもの頃に飼っていたスナネズミを透明なボールに入れて遊ばせていたところ、姉がボールごとリビングの端まで蹴り飛ばしたという。腹を立てて仕返しに及び、いとこのウーソズの父リキシに初めて本気で叱られたそうだ。姉妹はどちらも身長180cm超で、当時は自分より大きく強かったと話す。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:10:43〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=4243s"]]}, {"cat": "好きなもの", "t": "お祭りは乗り物より屋台のゲーム", "b": "州のお祭りでは絶叫系の乗り物が怖く、もっぱら屋台のゲームで遊んでいたという。輪投げが得意で、毎年いくつも景品を持ち帰るほどだったそうだ。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:11:30〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=4290s"]]}, {"cat": "家族", "t": "息子たちに昼寝スペースを荒らされ", "b": "自宅のシアタールームに簡易マットレスを敷いて昼寝の「巣」にしているという。戻ると息子たちがおもちゃや毛布、段ボールで散らかしていたため、悲しそうな演技をして反省させたそうだ。演技は上出来だったと笑う。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:15:18〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=4518s"]]}, {"cat": "好きなもの", "t": "ブレイディのヘルメットの隣にジョーダンを", "b": "トム・ブレイディのサイン入りヘルメットを持っているという。子どもの頃の自分に贈るなら、その隣に飾るマイケル・ジョーダンのサインボールが欲しいと答えている。野球ならバリー・ボンズやマーク・マグワイアの名を挙げた。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:29:42〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=5382s"]]}, {"cat": "リングに来るまで", "t": "野球少年、二重関節の速球", "b": "子どもの頃は野球がいちばん好きで、三塁を中心に一塁や外野も守り、投手も務めたという。肘が二重関節で、投げる球が勝手に大きく動いたそうだ。大人になってから、当時の仲間に「打席に立つのが嫌だった」「プロになると思っていた」と言われたと話す。野球は高校2年でやめている。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-gxXtolxyZtY", "src": [["公式YouTube（1:30:28〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=5428s"]]}]);
  if (PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"].facts.push({"cat": "暮らし", "t": "入場中に鳥肌を見つけて声をかける", "b": "入場のたびに背後から「また鳥肌が立ってるぞ」とささやいてくれたのがいちばんの思い出だと、ローマン・レインズが話している。長距離移動の機内での会話や、ヘイマンが自分の子どもたちと話す様子を聞くのも好きだったという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で、ローマン・レインズの話（公式字幕を全文確認）", "src": [["公式YouTube（17:17〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=1037s"]], "by": "第三者の話"});
  if (PROFILES["Rikishi"]) PROFILES["Rikishi"].facts.push({"cat": "暮らし", "t": "子どもたちが恐れた「ジュニア」", "b": "家族の間では「ジュニア」と呼ばれ、その目つきが怖くて、子どもたちは前を通れずに部屋から出られなくなることもあったと、ローマン・レインズが話している。自分の姉とのけんかで叱られたのが、初めて本気で説教された経験だったという。", "sp": "ローマン・レインズ", "d": "2025-08-28", "how": "ステファニーの番組で、ローマン・レインズの話（公式字幕を全文確認）", "src": [["公式YouTube（1:13:00〜）", "https://www.youtube.com/watch?v=gxXtolxyZtY&t=4380s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-gxXtolxyZtY", d: "2025-08-28", show: "wys", who: ["Roman Reigns"], t: "ローマン・レインズの回　白血病の告知、祖父母との大陸横断、甘いもの好きの素顔", lead: "ステファニー・マクマホンの番組に出た約93分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Roman Reigns"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-gxXtolxyZtY").map((x) => [x.t, x.b, x.sp])), open: ["大学時代の恩師のコーチ、少年野球のコーチ、NFLの元同僚が寄せたビデオメッセージは、私人の実名を避けるため名前を出さずに要約した（ビデオメッセージの内容自体は載せていない）。", "スナネズミの件の「仕返し」の中身は、要点のみにとどめた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=gxXtolxyZtY"]] });
  if (!ROSTER.find((r) => r[1] === "Bruce Prichard")) ROSTER.push(["ブルース・プリチャード", "Bruce Prichard", "lg", "創作責任者を務める知恵者", "", "", ""]);
  if (!PROFILES["Bruce Prichard"]) PROFILES["Bruce Prichard"] = { lead: "幼い頃に興行会社で働きはじめ、ダスティの物まねで人気を集めたブルース。聞く力と行動力で、バックステージを支える知恵者の素顔が見える回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bruce%20Prichard"]], moves: [], facts: [] };
  if (PROFILES["Bruce Prichard"]._weak) { PROFILES["Bruce Prichard"].lead = "幼い頃に興行会社で働きはじめ、ダスティの物まねで人気を集めたブルース。聞く力と行動力で、バックステージを支える知恵者の素顔が見える回。"; delete PROFILES["Bruce Prichard"]._weak; }
  PROFILES["Bruce Prichard"].facts.push(...[{"cat": "リングの話", "t": "ゴブルディグーカーの大失敗", "b": "ブルースは、自分の発案ではないが語るのが好きな失敗談として、マスコットのゴブルディグーカーを挙げる。巨大な卵から出てきたのは七面鳥のような着ぐるみで、会場の期待は一気にしぼんだという。巨大な卵の中身をめぐり、アンダーテイカーが自分が入るのではと本気で心配したという噂話も語っている。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（4:00〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=240s"]]}, {"cat": "リングの話", "t": "他団体の選手は呼べない現実", "b": "ブルースは、ファンは他団体と契約中の選手の登場を望みがちだが、実現は難しいと話す。団体が買い取った他団体の資産には選手の契約が含まれず、大物たちは契約を消化して自宅で待つ道を選んだという。その選択を責める気持ちはないそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（8:04〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=484s"]]}, {"cat": "リングの話", "t": "2022年の面談は「戻っておいで」", "b": "ブルースによれば、コーディとの面談で会社側が伝えたかったのは「おかえり」の一言だった。握手のレベルでもいいから、帰る前に今後の約束を取りつけるつもりで臨んだという。話は驚くほど早く進み、すぐ飛行機で駆けつけたと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（10:29〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=629s"]]}, {"cat": "リングに来るまで", "t": "子どもの頃からダスティの物まね", "b": "ブルースは8〜10歳のころ、ヒューストンの興行で聞いたダスティの名物インタビューをまねしていた。ダスティの母が同地に住んでいて、ダスティはクリスマスに帰省して試合に出たのだという。後に身近で働くうちに、仕草や間合いまで身についたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（21:49〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1309s"]]}, {"cat": "リングに来るまで", "t": "ダスティと初めて机を並べた日", "b": "1989年、タンパの事務所でダスティと映像の打ち合わせをしたとブルースは振り返る。緊張で膝の上のカバンを倒し、中身をぶちまけてしまった。するとダスティが「気にするな」と声をかけ、一瞬で場の空気が軽くなったという。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（23:24〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1404s"]]}, {"cat": "好きなもの", "t": "指輪にこめた恩人の記憶", "b": "ブルースは、恩人のプロモーター、ポール・ボーシュのリングをめぐる話を語る。盗難や紛失をくり返したリングは、のちに未亡人のもとへ戻ったという。ブルース自身は、片面にマイク、もう片面にテレビをあしらった指輪を作った。長年の実況とテレビ制作の人生を表したものだそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（26:31〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1591s"]]}, {"cat": "リングに来るまで", "t": "10歳でポスター売り、1枚25セント", "b": "ブルースが業界に入ったのは10歳。ヒューストンでポール・ボーシュの興行のもと、客席でポスターを売り始めた。1枚につき25セントで、その日の稼ぎは12ドルだった。1973年の10歳には大金に感じたと笑う。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（28:06〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1686s"]]}, {"cat": "リングに来るまで", "t": "弟トムと事務所に入りびたる", "b": "ブルースは弟のトムと、いつも事務所に出入りして頼まれた用事をこなす子どもだった。のちにテレビ番組の助手ディレクターになり、CM中の合図や、実況席のボーシュへの指示を出していたという。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（28:55〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1735s"]]}, {"cat": "リングに来るまで", "t": "14歳の急なリングアナデビュー", "b": "14歳のとき、本来のリングアナが洪水で来られず、ブルースが急きょ代役を務めた。最初に紹介したのはトール・タナカで、出身を日本の横浜と告げたという。メインのビリー・グラハムは、試合の合間の2分間ずっと「小僧」と罵り続けたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（29:41〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1781s"]]}, {"cat": "リングに来るまで", "t": "お客の声を聞く、が最大の教え", "b": "ブルースがボーシュから学んだ最大のことは、客の声を聞く姿勢だという。ヒューストンのチケット売り場には前売り客が来て、好き嫌いを率直に話した。批評したいだけの人ではなく、チケットを買う人の声に耳を傾けよ、とブルースは語る。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（30:28〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1828s"]]}, {"cat": "リングの話", "t": "12歳の少年の遠慮ない感想", "b": "ブルースは、友人のマットレス・マックが連れてきた12歳の少年ブライソンの話をする。裏に案内すると、少年は礼儀正しく選手に挨拶しつつ、好き嫌いを率直に語った。一番はローマン・レインズ、二番がコーディだったそうだ。利害のない人の声が一番勉強になると話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（34:36〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=2076s"]]}, {"cat": "暮らし", "t": "SNSの声は小さな一部だと見る", "b": "ブルースは、SNSの意見は声が大きく熱いが観客のごく一部で、わざと逆張りする人もいるので危うい場所だと見ている。自分が耳を傾けるのは、実際にお金を払って見に来る人たちだと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（39:24〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=2364s"]]}, {"cat": "暮らし", "t": "ポッドキャストで「本当の話」を", "b": "ブルースは、業界から離れていたころ、戻るつもりもなくポッドキャストを始めた。ネット上の誤った情報を正したかったからだという。長年同じ秘密を知る3人のうち、1人は亡くなり1人は語らず、自分が話す立場になったと説明する。同じ出来事でも人によって記憶は違うと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（40:14〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=2414s"]]}, {"cat": "リングの話", "t": "キャラになりきって企画を語る", "b": "ブルースは、企画を売り込むときはそのキャラクターになりきって語るという。パーシー・プリングル役の時はポール・ベアラーの声で、アンダーテイカーの母親までまねたそうだ。創作側にいると、コーディやジョン・シナなど、全員の声で考える楽しみがあると話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（44:23〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=2663s"]]}, {"cat": "リングの話", "t": "アンダーテイカーは頭の中の創作", "b": "ブルースは、アンダーテイカーを「自分が管理したくて、頭の中で作ったキャラ」と語る。ミーン・マークを悪役にしたく、舞台裏に残ったまま、パーシー・プリングルをポール・ベアラーにしたという。ケインも自分の頭から生まれたキャラだそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（48:26〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=2906s"]]}, {"cat": "リングの話", "t": "一年かけて種をまくストーリー", "b": "ブルースが今の仕事で懐かしむのは、9か月〜1年かけて物語を作ることだ。マッチョマンとハルクの「メガパワーズ崩壊」では、ランディにリズを肩に乗せさせるなど小さな種を仕込み、あとで一気に回収したという。当人たちが理由を知らずに動いていたこともあったそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（50:13〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3013s"]]}, {"cat": "リングの話", "t": "ダスティが語った「お披露目の日」", "b": "ブルースによれば、ダスティは殿堂入りの式で息子たちに紹介してほしいと話していた。同時に「コーディのお披露目の日になる」とも言っていたという。当日、舞台裏でビンスと共に見守り、「やっと来たな」と感じたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（56:47〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3407s"]]}, {"cat": "暮らし", "t": "25歳でやりたいことを使い切った", "b": "ブルースの夢は、レスラーになり世界王者になり、ヒューストンで興行して引退することだった。25歳でそれをほぼ達成して、MSGにも立ち、ホーガンとも闘い、「これからどうしよう」と思ったという。62歳になった今は、何歳で引退するといった将来像は持っていないと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:02:30〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3750s"]]}, {"cat": "リングの話", "t": "ビンスの先見の明", "b": "ブルースは、ビンス・マクマホンがかつて「自分たちのネットワークを持つ」と語ったとき、すぐには意味がわからなかったという。上場の話が出たときも、利益が個人の成果に直結する非上場の時代しか知らなかったそうだ。後から振り返ると、ビンスは常に今より先を見ていたと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:03:19〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3799s"]]}, {"cat": "暮らし", "t": "人は3種類、全力で挑む者になれ", "b": "ブルースは「世の中には、挑戦する人、全力を尽くす人、何としてもやり遂げる人の3種類がいる」という考えを語る。やり遂げる人は自分に正直でいれば何でもできるそうだ。ダスティも、笑われた夢を現実にした人だったという。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:04:59〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3899s"]]}, {"cat": "暮らし", "t": "主役になるには、行動すること", "b": "今の時代の主役になるには、との問いにブルースは、ばかなことをせず、人の声を聞き、いつでも動ける状態でいて、実際にやりきることだと答える。朝4時に起きて動けるかが分かれ目で、人より上手くやることが大事だという。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:06:38〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3998s"]]}, {"cat": "リングの話", "t": "ダスティと同じ車で移動した日々", "b": "ブルースは、ダスティと自分、ランディとリズ、シェリーとサファイアと、3組に分かれて移動していたという。サファイアはレスリング界の出身ではなく、シェリーが世話役になっていたそうだ。ダスティが、サファイアが換金せず放置していた大会のギャラ小切手に気づかせた、という話も出た。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:11:37〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4297s"]]}, {"cat": "暮らし", "t": "道中のホットドッグと仲間たち", "b": "ブルースは、移動の車内の会話や、道すがらの寄り道を大切な思い出に挙げる。フィラデルフィアの高架下のホットドッグ屋では、客の列を越えてダスティだとわかり、すぐ出されたという。ホテルのバーではなく、地元の人が知る店でチキンポットパイを食べて過ごしたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:13:10〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4390s"]]}, {"cat": "リングの話", "t": "ダスティに5000ドルを貸した賭け", "b": "ブルースの話では、ダスティが「ブラザー・ラブには絶対に捕まらない」と言い、ランディが5000ドルの賭けをけしかけた。数日はいい試合にならず、ある夜ついにダスティの背後から捕まえて勝ったという。その後ダスティが怒ってマイクで脅し、本気でやられたが、賭け金は支払われていないそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:16:24〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4584s"]]}, {"cat": "好きなもの", "t": "お気に入りの腕時計", "b": "ブルースは、オメガのスピードマスター（ダークサイド・オブ・ザ・ムーン）を持っている。コーディのシーマスターに触発され、「月まで行く」つもりで記録を更新し続けるために選んだと語る。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:22:56〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4976s"]]}, {"cat": "好きなもの", "t": "最強の4人は、ほぼテキサス勢", "b": "ブルースは、バーでの乱闘ならアンダーテイカー、ジョン・レイフィールド、ハク、ブッカー・Tを連れて行くという。ほぼ全員がテキサス出身。特にハクは気心が知れた友人であり、素晴らしい人間だと話す。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:26:08〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=5168s"]]}, {"cat": "家族", "t": "子どもたちはポッドキャストで父を知る", "b": "ブルースは、子どもたちが自分のポッドキャストを聞いて父の仕事を知ると話す。家では仕事の自分と違う「お父さん」でいようとしているそうだ。何十年後かに、貢献を思い出してもらえれば子どもたちのためになる、と語る。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:31:39〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=5499s"]]}, {"cat": "家族", "t": "ブッカー・Tとは家族ぐるみの仲", "b": "ブルースとブッカー・Tは同じ町に住んでいながら、WCWにいたころは面識がなかったという。ブッカーがWWEに来てから親しくなり、家族ぐるみで付き合うようになった。ブルースの娘がブッカーの子どもの世話をしていたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:35:39〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=5739s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "シナが戦火を逃れた少年に会いに行った話", "b": "パンデミックのさなか、ウクライナから逃れた少年が「ジョン・シナに会える」を心の支えにしていたと、ブルースが話している。シナは自力で会いに行ったが、物販がなかったため、会社が民間機などで急いでグッズを届けたという。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で、ブルース・プリチャードの話（公式字幕を全文確認）", "src": [["公式YouTube（1:08:18〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4098s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "ダスティが好んだ地元の穴場", "b": "ダスティはどの町にも行きつけがあり、ホテルのバーではなく外れの店でチキンポットパイやビールを楽しんだと、ブルースが話している。店主や支配人が彼を知っていて、気前よく迎えたそうだ。", "sp": "ブルース・プリチャード", "d": "2025-09-03", "how": "コーディの番組で、ブルース・プリチャードの話（公式字幕を全文確認）", "src": [["公式YouTube（1:14:43〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4483s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングの話", "t": "2022年の面談は「車の事故」級", "b": "父ならすぐ「イエス」と言ったはずだと思いつつ、準備して臨んだものの、提示額を聞いて衝撃を受けたとコーディは話す。部屋を出ると子どものような気持ちになり、ブルースに相談したという。帰宅後、妻に電話で状況を伝えたそうだ。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（12:12〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=732s"]]}, {"cat": "リングの話", "t": "セスの初ダークマッチを知っている", "b": "コーディは、オハイオ州デイトンのナッターセンターで行われたセス・ロリンズの初のダークマッチに居合わせたという。その後ライブ興行でも共にしたセスが、自分を追い越して飛躍していくのを見てきたそうだ。同じリングで肩を並べられることに感慨を覚えている。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（17:01〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1021s"]]}, {"cat": "家族", "t": "祖母キャシーはヒューストン在住", "b": "コーディによれば、ダスティの母キャシーはヒューストンに住み、いつも試合に来ていたという。ネイティブアメリカンの血筋と聞いていたが、家系調査で祖母はドイツ系だったと判明したそうだ。ネイティブの血は父方の、別の家系にあり、チョクトー族とチカソー族だったという。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（24:11〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=1451s"]]}, {"cat": "リングの話", "t": "マニア後の舞台裏で待っていた人", "b": "コーディは、レッスルマニア39の直後、ゴリラポジションの手前で自分を気づかって待っていてくれたのがブルースだったと語る。感情的にもへとへとになる試合で、ありがたかったという。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（51:55〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3115s"]]}, {"cat": "家族", "t": "父はテレビ・映画も見据えていた", "b": "コーディは、父ダスティが自分を映画やテレビの道に向いていると見ていたが、レスラーとしても見ていたはずだと考えている。フロリダのプロレス団体で働く夢を見ることもあるそうだ。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（54:21〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3261s"]]}, {"cat": "家族", "t": "父の殿堂入りで語る重み", "b": "コーディは、ダスティは最高の話し手と言われる人なので、息子として弔辞や殿堂入りの場で話すときは相当の準備が必要だという。テリー・ファンクについて語った際も、光栄だったと話す。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（58:25〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=3505s"]]}, {"cat": "好きなもの", "t": "見つかった父ゆかりの腕時計", "b": "コーディによれば、父にまつわる珍しい仕様の腕時計が、レッスルマニア40の後に見つかった。連絡を受けたコーディはその場でクレジットカードを渡して購入し、翌日届いたそうだ。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:21:14〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=4874s"]]}, {"cat": "暮らし", "t": "チップは現金で渡す主義", "b": "コーディは現金派で、レストランで閉店後に奥の通路を通してもらい、従業員に100ドルずつチップを渡した父の流儀を受け継いだという。妻は少し困っているそうだ。", "sp": "コーディ・ローデス", "d": "2025-09-03", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-EzgFMxiCm-I", "src": [["公式YouTube（1:24:34〜）", "https://www.youtube.com/watch?v=EzgFMxiCm-I&t=5074s"]]}]);
  ARTICLES.push({ id: "wdywta-EzgFMxiCm-I", d: "2025-09-03", show: "wdywta", who: ["Bruce Prichard", "Cody Rhodes"], t: "ブルース・プリチャードの回　失敗作から育ての親ダスティまで", lead: "コーディ・ローデスの番組に出た約99分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bruce Prichard", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-EzgFMxiCm-I").map((x) => [x.t, x.b, x.sp])), open: ["字幕に話者名がなく、コーディとブルースの発言の区別が難しい箇所は載せていない", "団体の倉庫での収録で、ポール・ボーシュなど人名の表記は字幕の綴りに基づくため、確認が必要"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=EzgFMxiCm-I"]] });
  if (!ROSTER.find((r) => r[1] === "The Godfather")) ROSTER.push(["ゴッドファーザー", "The Godfather", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["The Godfather"]) PROFILES["The Godfather"] = { lead: "元バスケ選手で、バイク仲間と過ごした青春を経てリングへ入ったチャールズ・ライト。どんな役でも楽しむ姿勢と、友情を大切にする人柄が伝わる回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=The%20Godfather"]], moves: [], facts: [] };
  if (PROFILES["The Godfather"]._weak) { PROFILES["The Godfather"].lead = "元バスケ選手で、バイク仲間と過ごした青春を経てリングへ入ったチャールズ・ライト。どんな役でも楽しむ姿勢と、友情を大切にする人柄が伝わる回。"; delete PROFILES["The Godfather"]._weak; }
  PROFILES["The Godfather"].facts.push(...[{"cat": "暮らし", "t": "60歳を前にしても元気、膝だけが悩み", "b": "この年で60歳になるが、年齢ほどには老けた気がしないと話す。気になるのは膝くらいだという。以前ほど酒は飲まなくなり、人生は短いのだから楽しまないと損だと考えているそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（0:54〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=54s"]]}, {"cat": "暮らし", "t": "夜8時に寝て、朝3時に起きる", "b": "今は夜8時から8時半には寝て、朝3時に起きる生活だという。起きたらまずSNSの更新をして、2時ごろに一日の仕事を終える。そのあとジムに行き、犬や妻と過ごすと話す。朝の静けさと空気のよさが気に入っているそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:47〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=107s"]]}, {"cat": "好きなもの", "t": "ジャック・ダニエルで仲間と乾杯", "b": "酒をやめたわけではなく、一本まるごと空けなくなっただけだと笑う。収録中もジャック・ダニエルで何度も乾杯し、亡くなった仲間やアンダーテイカーのために杯を上げた。昔の巡業仲間とは酒がつきものの思い出が多いという。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（3:26〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=206s"]]}, {"cat": "リングに来るまで", "t": "高校ではバスケ一筋の選手だった", "b": "1979年には地域の年間最優秀バスケ選手に選ばれたと話す。本当はフットボールをしたかったが、けがを心配した両親に許してもらえなかったという。走り高跳びでも跳躍力を見込まれ、高跳びの選手もしていたそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（4:17〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=257s"]]}, {"cat": "リングに来るまで", "t": "短大で筋トレに目覚め、体重が60キロ以上増えた", "b": "成績の都合で短大に進み、フットボール部の仲間とウエイトトレーニングを始めた。4か月ほどで体重が約180ポンドから240ポンドに増え、ベンチプレスも135ポンドから300ポンドに伸びたという。さらにパワーリフティングに打ち込み、500ポンドを挙げるまでになったと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（5:05〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=305s"]]}, {"cat": "リングに来るまで", "t": "ダンクを見せてネバダ大の奨学金を得る", "b": "フットボールのコーチに紹介され、ネバダ大学リノ校へ呼ばれた。体重約300ポンドでバスケットのコートに立ち、360度ダンクまで決めて見せたという。タックルの経験がないまま、全額支給の奨学金を得たそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（5:56〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=356s"]]}, {"cat": "リングに来るまで", "t": "攻撃ラインで活躍するも、膝のけがで挫折", "b": "大学ではオフェンスタックルを任され、パスを守る役は得意だったと話す。体が強く最初の当たりで相手を止められた一方、押し込むブロックのコツはつかめなかったという。その後、膝を痛めて続けられなくなったそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（6:46〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=406s"]]}, {"cat": "リングに来るまで", "t": "けんかが原因で大学を去る", "b": "専攻は経営学で、2年ほど通ったが卒業はしていないという。体が大きくなって調子に乗り、けんかを繰り返したため退学になったと振り返る。当時の自分を「手に負えないやんちゃ者」だったと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（8:22〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=502s"]]}, {"cat": "暮らし", "t": "バイク仲間の中で、刺青だらけの青春時代", "b": "ハーレーに乗り、バイククラブの仲間と過ごしていたという。クラブではただ一人の黒人メンバーで、1985年ごろから胸や背中、脚にまで刺青を入れたそうだ。荒れた環境から、プロレスのおかげで抜け出せたと語っている。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（9:11〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=551s"]]}, {"cat": "リングに来るまで", "t": "映画の撮影を見た人たちから「レスラーになれ」と言われる", "b": "ラスベガスの店で働いていたころ、近くで撮影していた映画の関係者が来店し、見たことのない体格だからプロレスをやるべきだと勧めてくれたという。ただ本人はレスラーのファンではなく、ローラーゲームのファンだったと話す。バンバン・ビガロが大金を稼いだと聞いて、興味を持ったそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（11:34〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=694s"]]}, {"cat": "リングに来るまで", "t": "練習は短期間で、デビュー戦は先輩レスラーとの一戦", "b": "ビガロが通った道場に連絡し、ニュージャージーへ向かった。練習はほんの数か月で、ほとんど身につかなかったという。その後ジェリー・ローラーの目に留まり、デビュー戦はテネシー州メンフィスでローラーが相手になった。何も知らないまま、言われたとおりに動いたと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（13:07〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=787s"]]}, {"cat": "リングに来るまで", "t": "ギャラは少なく、小切手を酒屋で換金", "b": "南部の団体で働いていたころの給料は、1試合で数十ドルという厳しいものだったという。交通費名目の小切手を酒屋で現金に換えており、恥ずかしくて誰にも言えなかったと話す。それでも別の収入の当てがあったので、辞めてもよいと思っていたそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（14:39〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=879s"]]}, {"cat": "リングに来るまで", "t": "赤いモヒカンにされ、いったんは解雇を告げられる", "b": "ダッチ・マンテルらに勧められて、髪を赤いモヒカンにした。技がまだ未熟だったため、マンテルからは解雇を告げられたという。しかしローラーと団体の責任者が引き留めてくれ、背の高い赤毛の新人と組ませると言われて残れたと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（15:25〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=925s"]]}, {"cat": "リングに来るまで", "t": "最初の異名は胸の刺青に由来していた", "b": "「ソウルテイカー」という名は、胸に入れた刺青からきていたと説明する。胸の暗い部分はバイククラブの紋章で、テレビには出せないとビンスに言われて隠したそうだ。クラブが危ない方向へ変わったため、仲間2人と脱退したとも話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（16:57〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1017s"]]}, {"cat": "リングに来るまで", "t": "仲間と小さな車で何百キロも通った、貧しくも楽しい日々", "b": "当時は、200マイル走って約45ドルを稼ぎ、泊まる金がなくまた200マイル戻るような暮らしだったという。アンダーテイカーらと小さな車に乗り合わせて移動した。今でもアンダーテイカーと昔話をすると、その時期の話ばかりになると語る。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（18:45〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1125s"]]}, {"cat": "暮らし", "t": "アンダーテイカーとは最悪の試合から親友に", "b": "初めて組まれた試合は、自分のせいで史上最悪の出来になったと笑う。その後なぜか2人でタッグを組まされ、親友になったという。彼はカントリー音楽より髪の長いバンドが好きだったが、自分がカントリーとハーレーを教えたと話す。今も一番の友人の一人だそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（23:45〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1425s"]]}, {"cat": "暮らし", "t": "雪道を運転したがり、車を溝に落とす", "b": "メンフィスからの帰り道、雪が降る中でアンダーテイカーが運転していたが、自分が代わると言い張った。雪道を走った経験はなく、少し進んだだけで車は回転して溝に落ちたという。人に止められると意地になる性格だったと振り返る。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（27:04〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1624s"]]}, {"cat": "リングに来るまで", "t": "日本とドイツで腕を磨いてWWEの入団テストへ", "b": "日本では人の話を聞いて技を覚え、観客の盛り上げ方も学んだという。続いてドイツで約8か月の長い巡業に参加し、オーウェン・ハートらと同じ興行に出た。帰国後、アンダーテイカーがすでにWWEにいて、アリゾナでの入団テストを経て採用されたと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（29:24〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1764s"]]}, {"cat": "リングの話", "t": "最初の役は映画を見て作ったブードゥーの怪人", "b": "採用時、顔が童顔すぎるので何か役を考えると言われたという。数か月後に「007 死ぬのは奴らだ」を借りて見るよう言われ、そこからパパ・シャンゴが生まれた。ニューオーリンズまで行ってその筋の人たちに話を聞き、本物に近づけようとしたと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（30:09〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=1809s"]]}, {"cat": "リングの話", "t": "パパ・シャンゴがうまくいかなかった理由", "b": "相手のカマラが自分よりずっと役になりきっていて、実力の差を感じたという。まだ経験が浅い状態で、試合よりも呪いをかける役を求められたのが難しかったと話す。メイクをしたら誰とも口をきかず、役に入り込んでいたそうだ。黒い液体は小さなゴム球で出していて、仕組みは見たことがないという。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（33:22〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2002s"]]}, {"cat": "家族", "t": "離婚で荒れた時期、休みをもらう", "b": "離婚の最中で気持ちが荒れていた時期があったという。アンダーテイカーが毎晩のように気にかけて、いったん帰ったほうがいいと勧めてくれ、会社も少しずつ休ませてくれたと話す。今の妻とは結婚して21年になるそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（36:32〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2192s"]]}, {"cat": "暮らし", "t": "プロレスのファンではなく、あくまで仕事のひとつ", "b": "自分はずっとプロレスのファンではなかったと話す。地元ラスベガスで別の仕事をしており、巡業で体を痛めるより家で稼ぐほうが楽だとビンスに伝えていたという。移動の多さが一番つらかったと語る。楽しくないときは辞めるという考えで、出入りを繰り返したそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（38:15〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2295s"]]}, {"cat": "リングの話", "t": "総合格闘技ブームから生まれた新キャラ「ケモ」", "b": "格闘技大会が始まった頃、ビンスから格闘家の役を提案されたという。名前には「相手を蹴散らす男」という意味が込められていた。最初は乗り気ではなかったが、ハーレーに乗れると聞いて引き受けたと話す。結局、あまり受けなかったそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（39:03〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2343s"]]}, {"cat": "リングの話", "t": "棺桶マッチは苦手でも、相手が親友なら全力", "b": "棺桶の試合は閉所が苦手で嫌いだと話し、自分が死んだら火葬にしてほしいと冗談を言う。それでもアンダーテイカーを引き立てたい一心で、受け身を多めに取るなど工夫したという。高い場所から相手を受け止めたことには、自分でも驚いたそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（41:20〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2480s"]]}, {"cat": "リングの話", "t": "他団体の誘いを、ロン・シモンズの助言で見送る", "b": "ライバル団体に行く話が進んでいたが、ロン・シモンズに南部の空気は合わないと止められたという。その後、別の選手が低いギャラで採用された。自分はそれで構わず、のちにゴッドファーザーという役を得たと話す。困ったときは必ずロンに相談したそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（45:26〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2726s"]]}, {"cat": "リングの話", "t": "予定が急変し、ユニットの一員になる", "b": "一人で再登場する予定で準備を重ねていたが、当日ビンスに呼ばれ、ロン・シモンズらのユニットに加わると告げられたという。驚きはしたが、給料をもらう以上やるだけだと受け入れた。そのユニットは多くの選手が飛躍した場になり、ロン・シモンズの存在が大きかったと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（47:02〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=2822s"]]}, {"cat": "暮らし", "t": "ドミノ仲間のグループで過ごした待ち時間", "b": "テレビ収録は待ち時間が長く、仲間と集まってドミノを楽しんだという。ヨコズナを中心に、派閥争いとは無縁の気楽な集まりだったと話す。今もそのメンバーとはSNSのチャットでやり取りし、ロン・シモンズやアンダーテイカーらとも連絡を取り合っているそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（55:16〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=3316s"]]}, {"cat": "リングの話", "t": "妻の提案で生まれた陽気なゴッドファーザー", "b": "ユニットの中で埋もれ始めた頃、妻が悪役をやめて素の自分を出す役を勧めたという。妻は衣装や帽子、アクセサリーを自分で用意し、自分はそれを着て演じるだけだった。ザ・ロックが自分を「ゴッドファーザー」と呼んだのがきっかけで、その呼び名が定着したと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:00:50〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=3650s"]]}, {"cat": "リングの話", "t": "台本なしで自由にできた最高の役", "b": "このキャラは台本がなく、好きに動けたと話す。曲を聞いたときも気に入り、自由に楽しめると感じたそうだ。女性たちを連れて登場するようになると一晩で人気が出て、空港でも声をかけられたという。「ここが自分の居場所だ」と思えた最高の時期で、キャラではなく素の自分だったと語る。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:05:42〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=3942s"]]}, {"cat": "リングの話", "t": "役を抑えられ、楽しさを失った時期", "b": "検閲を掲げるユニットに入れられ、役柄を弱められた時期は、プロレスで唯一楽しくなかったと話す。ビンスは最後までかばってくれたが、周りからの批判が強かったという。それまで素の自分で楽しんでいたのに、仕事に変わってしまったそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:16:52〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=4612s"]]}, {"cat": "家族", "t": "殿堂入りのスピーチで、妻への感謝を言い忘れた", "b": "スピーチは台本なしで臨み、孫の誕生日を客席に祝ってもらったところで盛り上がり、妻に触れる予定を飛ばしてしまったという。降壇後に気づいたが取り返しがつかず、今でも悔やんでいる。衣装やアクセサリーを手がけ、役の生みの親だった妻に、今も許しを請うていると笑う。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:21:39〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=4899s"]]}, {"cat": "リングの話", "t": "殿堂入りの知らせは、ジムへ行く途中の電話", "b": "ジムに向かう途中、WWEの幹部から電話で殿堂入りを知らされたという。家族みんなで来るようにと言われて驚いた。試合の内容よりも個性と娯楽性で選ばれたのだと思うが、これまでの仕事が認められたのは名誉だと話す。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:25:41〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=5141s"]]}, {"cat": "暮らし", "t": "インスタグラムが今の楽しみ", "b": "今はインスタグラムに力を入れていて、ゴッドファーザーとして認証マークも付いていると話す。YouTubeでも活動しているそうだ。最後に、仕事を振り返って、人との出会いと友情に恵まれた、業界への敬意しかないと語った。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-HoF-KqJqSLs", "src": [["番組のYouTube（1:25:41〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=5141s"]]}]);
  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "初めての刺青を勧めた親友", "b": "体が大きくて色も白いのに刺青がないのは似合わないと言い続け、初めての刺青をラスベガスの店で一緒に入れに行ったと、ゴッドファーザーが話している。のちに彼が腕全体に刺青を広げたのを見て、誇らしい気持ちだったという。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ゴッドファーザーの話（字幕を全文確認）", "src": [["番組のYouTube（1:14〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=74s"]], "by": "第三者の話"});
  if (PROFILES["Ron Simmons"]) PROFILES["Ron Simmons"].facts.push({"cat": "暮らし", "t": "全員が頼った頼れる兄貴分", "b": "振る舞い方や、テレビでの見せ方、何を見せて何を見せないかまで教えてくれる師匠のような存在だったと、ゴッドファーザーが話している。ザ・ロックの決め台詞の元も、ロンの口癖だったそうだ。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ゴッドファーザーの話（字幕を全文確認）", "src": [["番組のYouTube（52:50〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=3170s"]], "by": "第三者の話"});
  if (PROFILES["Yokozuna"]) PROFILES["Yokozuna"].facts.push({"cat": "暮らし", "t": "カセットを窓から投げ捨てた陽気な男", "b": "車でカントリーを流していたら、ヨコズナがカセットを取り出して窓から捨てたと、ゴッドファーザーが話している。実はラップが得意で、誰にでも優しい人だったと懐かしんでいる。", "sp": "ゴッドファーザー", "d": "2025-09-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ゴッドファーザーの話（字幕を全文確認）", "src": [["番組のYouTube（57:39〜）", "https://www.youtube.com/watch?v=HoF-KqJqSLs&t=3459s"]], "by": "第三者の話"});
