  PROFILES["MVP"].facts.push(...[{"cat": "WWEでの日々", "t": "2010年の退団は解雇ではなかった", "b": "MVPは、最初の退団を解雇だと思っている人が多いが、実際は残り1年の契約があり、自分から解放を願い出たと話す。会社は5年契約の更新を望んでいたが、当時は会社の仕組みや一部の人に疲れ、プロレスへの情熱を失っていたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（14:28〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=868s"]]}, {"cat": "退団の理由", "t": "戻れる形で去りたいと願い出た", "b": "MVPは、ジョン・ローリナイティスに「戻れなくなる形で去る前に、戻れる形で去りたい」と伝えたと話す。ビンスとは、自分は「スーパースター」ではなく「プロレスラー」になりに来たという冗談を交わしたそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（14:28〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=868s"]]}, {"cat": "退団の理由", "t": "夢は日本のドームと年間最大の祭典", "b": "MVPにとって日本のプロレスは情熱の源で、夢は東京ドーム、目標は年間最大の祭典だったという。情熱を取り戻すために離れる必要があり、会社は「戻りたくなったら戻っていい」という約束つきで解放してくれたと話す。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（15:16〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=916s"]]}, {"cat": "退団の理由", "t": "戻らなかったのは試合数と収入の事情", "b": "その後は戻らず別の団体へ進んだが、MVPはそれを経営判断だったと話す。WWEなら収入は上がっても試合数が3倍になるため、日程と収入の釣り合いで選んだという。復帰の誘いは2回あり、1回は興味がなく、もう1回は金額を高く求めすぎたそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（16:07〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=967s"]]}, {"cat": "WWEでの日々", "t": "2020年ランブル出場は息子のため", "b": "今度は金額ではなく、息子に自分がテレビに出る姿を見せたくて、ポール・ヘイマンに頼んだとMVPは話す。ヘイマンは即答で承諾し、サプライズ出場者としてロイヤルランブルに登場できた。観客席の息子は宣伝映像にも映ったという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（16:07〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=967s"]]}, {"cat": "WWEでの日々", "t": "ミステリオとの試合とプロデューサー職", "b": "試合後、息子の大好きなレイ・ミステリオが時間を取って息子にマスクを渡してくれたと話す。翌日のRAWではミステリオと対戦し、その後ローリナイティスからプロデューサーの打診を受けた。引退も考えていた時期で、挑戦してみることにしたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（17:46〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1066s"]]}, {"cat": "WWEでの日々", "t": "プロデューサーから再びタレントへ", "b": "MVPは、ドリュー・マッキンタイアやエッジとの短い絡みが続いたあと、パンデミックによる人員整理で一度プロデューサーの契約が切られたと話す。ところが2日後に「タレントとして必要」と連絡が来て、契約なしの週ごとの支払いで出演を続けたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（19:29〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1169s"]]}, {"cat": "WWEでの日々", "t": "一回きりの予定が新章になった", "b": "MVPは、毎週のように出演するうちにタレント担当の責任者から「ビンスと話した。契約を結ぶ」と告げられたと話す。一回限りのはずだった復帰が、キャリアの新しい章になったそうだ。その流れでシェルトン、ボビーとハート・ビジネスを組んだという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（21:10〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1270s"]]}, {"cat": "WWEでの日々", "t": "膝のけがで自然にマネージャーへ", "b": "MVPは、ユニットの中では必要なら自分が負ける役を引き受けていたと話す。膝のけがを機に、公式な発表はないまま、リングに上がらず話す役に移っていったという。杖は最初は本当に必要だったが、ファンの声で残したそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（21:57〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1317s"]]}, {"cat": "WWEでの日々", "t": "MVPの衣装は「プロ選手」を元にした", "b": "MVPは、自分のキャラクターは毎週見ていたプロスポーツ選手がモデルだと話す。派手で大きすぎるスーツを着る新人選手を見て、悪役ならこれが似合うと考えたという。育成時代は週500ドルほどで、安いスーツを仕立て直し、小物の合わせ方で高く見せる工夫を覚えたそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（25:11〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1511s"]]}, {"cat": "WWEでの日々", "t": "30秒でいいからと直談判した", "b": "MVPは、ローリナイティスに「採用されるには何が必要か」と30秒だけ時間をもらって尋ねたと話す。返ってきたのは、会社にないものを自分で考えてこいという答えで、その答えがMVPというキャラクターだったという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（27:32〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1652s"]]}, {"cat": "WWEでの日々", "t": "企画書とDVDを送ったら話題になった", "b": "MVPは、キャラクターの企画書、10本のストーリー案、バックステージの寸劇案、衣装の写真、2本のマイク映像を送ったと話す。当時としては珍しい詳しさで、ライターの間で回し見られたそうだ。ビンスが見て「すぐテレビに出せ」と言ったと聞いているという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（28:22〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1702s"]]}, {"cat": "WWEでの日々", "t": "煙の入場演出はダスティ・ローズとの雑談から", "b": "MVPは、ダスティ・ローズと私的な練習をしていた頃、地元の大学フットボールのチームが煙の中から出てくる入場の話をしたと話す。何気ない一言だったが、ダスティが「それをやろう」と乗ってくれて実現したという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（32:27〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1947s"]]}, {"cat": "WWEでの日々", "t": "憧れのベノワとのUS王座戦", "b": "MVPは、クリス・ベノワが一番好きなレスラーで、育成時代から親しい関係だったと話す。ベノワは自分のDVDを見てノートまで取り、「下手じゃない、まだ若いだけだ」と言ってくれたそうだ。王座を移す相手にMVPを推してくれたとも話す。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（34:08〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=2048s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典の一戦が一番の試合", "b": "MVPは、年間最大の祭典でのベノワとのUS王座戦を、自分の一番好きな試合として挙げる。それまでは逃げ回る喜劇的な役が多かったが、ベノワが「実力を見せよう」と言ってくれたという。試合後にステファニー・マクマホンから「あなたがこんなことができるなんて」と言われたそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（39:45〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=2385s"]]}, {"cat": "WWEでの日々", "t": "マット・ハーディと抗争から親友へ", "b": "MVPは、ボルチモアの会場でマット・ハーディから「今夜は一緒に仕事をしよう」と声をかけられたのが始まりだったと話す。抗争は友情に変わり、今も親しいという。ラダーの上での技や、場内が沸いた瞬間は忘れられない思い出だと話す。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（40:39〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=2439s"]]}, {"cat": "WWEでの日々", "t": "名前を持ち続けられた理由", "b": "MVPは、WWEに恨みはないと話す。ビンスとローリナイティスは、MVPの名前が自分の権利であることを契約に書いてくれたそうだ。同世代でそれが認められたのは自分とCMパンクくらいで、おかげで他の団体でも同じ名前で活動できたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（42:59〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=2579s"]]}, {"cat": "WWEでの日々", "t": "ヘイマンから学んだ観察の姿勢", "b": "MVPは、ヘイマンが復帰の扉を開いてくれたことに感謝していると話す。ヘイマンは、舞台裏の人間関係を観察して動きを読むよう教えてくれたそうだ。収録後に周りが拍手した際、ヘイマンが「自分に代わる人間としてここに呼んだ」と話したと聞き、大きな賛辞だと受け止めたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（57:32〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=3452s"]]}, {"cat": "WWEでの日々", "t": "台本は箇条書きで任せてもらえた", "b": "MVPは、WWEでは早くから話術を認められ、ビンスから特定の言い回しを指定された以外は台本どおりでなくてよかったと話す。ライターの箇条書きを元に自分の言葉で話すスタイルで、台本を暗記しないことが大事だと後輩に伝えているそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（1:04:50〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=3890s"]]}, {"cat": "WWEでの日々", "t": "育成時代に出会ったコフィ", "b": "MVPは、コフィ・キングストンとは育成時代の同期で、入ってきた日に最初に会った一人だったと話す。コフィは家族を大事にして夜遊びをしない人だったが、先輩たちも責めず、才能と仕事ぶりを尊重していたという。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（1:14:30〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=4470s"]]}, {"cat": "退団の理由", "t": "ハート・ビジネスの打ち切りに納得できなかった", "b": "MVPは、WWEでのハート・ビジネスの終わりについて、理由を明確に聞かされていないと話す。自分もボビーもビンスに考え直すよう頼んだが、聞き入れられなかったという。多くの人が打ち切りは早すぎたと感じていると、MVPは話す。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（1:19:29〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=4769s"]]}, {"cat": "退団の理由", "t": "契約更新の時期に去ると決めた", "b": "MVPは、契約更新の時期に自分はもう残りたくないとはっきり伝えたと話す。運営側に苦手な人がいると感じていたうえ、経営陣が変われば人の入れ替わりが起きるのは世の常で、去る時期だと考えたそうだ。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（1:19:29〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=4769s"]]}, {"cat": "退団の理由", "t": "ボビーにも再契約しないよう説得した", "b": "MVPは、ボビー・ラシュリーに再契約をしないよう耳元で言い続けたと話す。シェルトンが解雇された後で、3人でAEWに行って物語を続けようと誘ったという。トニー・カーンが価値を認めて迎えてくれたことに感謝していると話す。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-PHo-hsHbM28", "src": [["番組のYouTube（1:20:20〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=4820s"]]}]);
  if (PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"].facts.push({"cat": "暮らし", "t": "ポール・ヘイマンへの感謝", "b": "復帰の扉を開いてくれたことに深く感謝していて、「彼に代わる存在として呼んだ」という言葉が最高の賛辞だったと、MVPが話している。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で、MVPの話（字幕を全文確認）", "src": [["番組のYouTube（57:32〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=3452s"]], "by": "第三者の話"});
  if (PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"].facts.push({"cat": "暮らし", "t": "息子にマスクを渡したレイ・ミステリオ", "b": "ランブルの後、息子の大好きなレイ・ミステリオが時間を取ってマスクを渡し、話をしてくれたことを、MVPが感謝を込めて話している。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で、MVPの話（字幕を全文確認）", "src": [["番組のYouTube（17:46〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=1066s"]], "by": "第三者の話"});
  if (PROFILES["Kofi Kingston"]) PROFILES["Kofi Kingston"].facts.push({"cat": "暮らし", "t": "育成時代からのコフィ・キングストン", "b": "育成時代の同期で、家族を大事にして夜遊びをせず、仕事ぶりで尊敬を集めていたと、MVPが話している。", "sp": "MVP", "d": "2025-09-11", "how": "クリス・ヴァン・ヴリートの番組で、MVPの話（字幕を全文確認）", "src": [["番組のYouTube（1:14:30〜）", "https://www.youtube.com/watch?v=PHo-hsHbM28&t=4470s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-PHo-hsHbM28", d: "2025-09-11", show: "ext", who: ["MVP"], t: "MVPの回　WWEを去ってAEWへ、ハート・シンジケートの物語", lead: "クリス・ヴァン・ヴリートの番組に出た約87分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["MVP"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-PHo-hsHbM28").map((x) => [x.t, x.b, x.sp])), open: ["公開項目はWWEでの歩みと退団の経緯に限った。", "字幕は自動生成のため、固有名詞が崩れている箇所がある。確信の持てない名前は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=PHo-hsHbM28"]] });
