  if (!PROFILES["Ricochet"]) PROFILES["Ricochet"] = { lead: "NXT時代に今のキャラの土台を作り、WWEでは上位陣と戦いながらも後押しの薄さを感じていたリコシェ。契約満了で去ると決めるまでの心境を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ricochet"]], moves: [], facts: [] };
  if (PROFILES["Ricochet"]._weak) { PROFILES["Ricochet"].lead = "NXT時代に今のキャラの土台を作り、WWEでは上位陣と戦いながらも後押しの薄さを感じていたリコシェ。契約満了で去ると決めるまでの心境を語った。"; delete PROFILES["Ricochet"]._weak; }
  PROFILES["Ricochet"].facts.push(...[{"cat": "WWEでの日々", "t": "テレビには出ても後押しはなかった", "b": "WWE時代は常にテレビに出て、上位の選手とも戦っていたが、会社に後押しされている感覚はなかったとリコシェは話す。同じ立場で足踏みする選手は多く、その中で創作面で何かを変えるか、離れるかは本人次第だったという。自分もその一人だったと振り返っている。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（5:45〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=345s"]]}, {"cat": "WWEでの日々", "t": "NXT時代に今のキャラの原型ができた", "b": "若手時代からずっと善玉だったが、NXTでスーツを着て登場し、マイクで語るようになったことで、今のリコシェのキャラクターが形になり始めたと話す。ただその頃も役柄は善玉のままで、大きなキャラの変化を与えられる機会は少なかったという。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（12:23〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=743s"]]}, {"cat": "退団の理由", "t": "契約が残り2年ほどの頃、心境は割り切りに", "b": "のちの妻となる人と出会った頃、契約はあと2年ほど残っていたという。その時期は、渡された台本どおりに話し、相手を引き立てて試合をし、契約が終わったら辞めるつもりだったとリコシェは話している。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（28:36〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1716s"]]}, {"cat": "退団の理由", "t": "辞めるのはWWEであって、プロレスではない", "b": "契約満了で「終わりにする」と決めていたが、それはWWEをという意味で、プロレス自体をやめる考えではなかったと本人は説明する。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（29:23〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1763s"]]}, {"cat": "退団の理由", "t": "上層部に直接、気持ちを伝えた", "b": "一度だけ、会社の上層部の人物の部屋で、来週ここに戻るくらいなら、収入が減っても独立系の団体で活動したいと伝えたことがあるという。理由を問われて、自分が感じていることを具体例とともに話したそうだ。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（30:08〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1808s"]]}, {"cat": "退団の理由", "t": "不満は役の扱いと成長の機会のなさ", "b": "独立系では大物と同格に見られる自分や同僚の選手が、WWEでは大物の相手をするだけで格上げのように扱われることに疑問を感じていたという。引き立て役が必要なことは理解していたが、キャラクターを育てる時間ももらえず、状況は変わらないと思ったとリコシェは話す。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（30:58〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1858s"]]}, {"cat": "退団の理由", "t": "王座戦の打診があったが、気持ちは変わらず", "b": "面談では、王座に就く可能性も考えていたと伝えられ、それでも退団の意思を伝えるかと聞かれたという。リコシェは感謝しつつ、意思は変わらないと答えた。その夜、翌週の王座戦が組まれたと聞いたが、相手はサミ・ゼインだったとされ、これを見て気持ちを切り替え、与えられたことをこなすと決めたと話している。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（31:47〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1907s"]]}, {"cat": "退団の理由", "t": "引き留められた実感はなかった", "b": "契約についてWWE側から条件の提示はあったが、折り合わなかったという。ただ本人の感覚では、残ってほしいと真剣に向き合って言われた覚えはないと話す。残るよう言われても気持ちが変わったかは分からず、人によって感じ方は違うとも付け加えている。", "sp": "リコシェ", "d": "2025-09-16", "how": "AEW大会直前のインタビュー番組で（字幕を全文確認）", "art": "ext-57_XqBq1vOo", "src": [["番組のYouTube（32:35〜）", "https://www.youtube.com/watch?v=57_XqBq1vOo&t=1955s"]]}]);
  ARTICLES.push({ id: "ext-57_XqBq1vOo", d: "2025-09-16", show: "ext", who: ["Ricochet"], t: "リコシェの回　WWEを去った経緯と心境", lead: "AEW大会直前のインタビュー番組に出た約51分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ricochet"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-57_XqBq1vOo").map((x) => [x.t, x.b, x.sp])), open: ["上層部の人物や面談の相手は字幕で名前が崩れていたため、名前を伏せて書いた。", "退団後の会社への発言や、現在の団体の話は、このページの対象外として載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=57_XqBq1vOo"]] });
  if (!PROFILES["Nikki Bella"]) PROFILES["Nikki Bella"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nikki%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Nikki Bella"].lead === "") PROFILES["Nikki Bella"]._weak = 1;
  PROFILES["Nikki Bella"].facts.push(...[{"cat": "リングの話", "t": "「引退」という言葉に違和感がある", "b": "ニッキー・ベラは、復帰したばかりでまたリングに立っていると話す。マイケル・ヘイズにも「この業界はなぜ引退という言葉を使うのか。誰も本当には引退しない」と言ったそうだ。その場の気持ちが本物なら引退もあり、状況が変わることもある、と受け止めているという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（19:30〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1170s"]]}, {"cat": "リングの話", "t": "今回の復帰は「自分に猶予をあげる」と決めた", "b": "ニッキー・ベラは、以前の時代は自分の力を証明しようと必死だったと振り返る。今回は、すごい選手がそろった女子部門に自分がついていけると示したい、という立場だという。そのために「自分に十分な猶予をあげよう」と決めて戻ってきたそうだ。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（20:18〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1218s"]]}, {"cat": "リングの話", "t": "土台はある。限界を押し広げるのが楽しい", "b": "ニッキー・ベラは、自分の土台がどこにあるかは分かっていて、これから積み上げるものがたくさんある時期だと話す。限界を押し広げるのは楽しい挑戦で、根性には自信があるから必ずそこまで行く、と語っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（21:03〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1263s"]]}, {"cat": "リングの話", "t": "サッカーの次に来た、ディーバ・サーチ", "b": "ニッキー・ベラは、短大のサッカーで地区大会に進んだあと、年齢の関係でもう1年は続けられなかったと話す。上のレベルの大学でやる気もなく、サッカーの時期は終わったと感じていた。そのころにディーバ・サーチ（WWEの選考番組）の話が来て、リングへの道が開いたという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（29:56〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1796s"]]}, {"cat": "リングの話", "t": "母になってリングに戻ると、考え方が変わる", "b": "ニッキー・ベラは、母としてリングに戻ると「雌ライオン」のような感覚があると話す。やり遂げるまで止まらない、母親はやるしかないから何とかする、という気持ちを今回の復帰で強く感じているそうだ。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（36:23〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=2183s"]]}, {"cat": "リングの話", "t": "サマースラムの終わり方に、胸を打たれた", "b": "ニッキー・ベラは、パンクが勝って終わったと思った直後にセス・ローリンズの入場曲が鳴り、松葉づえが落ちた瞬間に鳥肌が立ったと話す。以前エボリューションの会場でセスの膝がひどいと30分ほど聞いていたので、本当に驚いたという。ベッキー・リンチが夫の松葉づえ姿の動画を投稿して周りをだましていたことにも、「やり切っていて最高」と笑っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:41:29〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6089s"]]}, {"cat": "リングの話", "t": "あれほど驚かされるから、WWEは別格", "b": "ニッキー・ベラは、あの夜ほど驚いたことは最近なかったと話す。観客にこうした瞬間を届けられるのが、WWEに誰もかなわない理由だと感じたそうだ。自分が仲間に何も告げずに妹のブリーを裏切った時も同じ種類の衝撃だった、と振り返っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:43:08〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6188s"]]}, {"cat": "リングの話", "t": "双子の売り込みを、ビンスたちの前で", "b": "ニッキー・ベラは、20年近く前に妹のブリーと2人で「ツイン・マジック」として自分たちを売り込んだ日のことを話す。ビンスの部屋だったかもしれないと、記憶はあいまいだという。プリンターで資料を刷り、切って貼ってと、アイデアがどんどん出てきた準備の日々も思い出している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:47:02〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6422s"]]}, {"cat": "リングの話", "t": "初めてのバンプで「見つかった」と思った", "b": "ニッキー・ベラは、サッカーを失って迷っていた時期から、ディーバ・サーチを経て初めてリングで受け身を取った時に「自分はここにいるべきだ」と感じたと話す。その後の道のりは学びと成長の連続だったと振り返っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:48:40〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6520s"]]}]);
  if (!PROFILES["Nikki Bella"]) PROFILES["Nikki Bella"] = { lead: "シングルマザーとして5歳の息子を育てながら、41歳でリングに戻ったニッキー・ベラ。農家の家系に生まれ、サッカー一筋だった少女時代の挫折から、ナパのワイン事業まで率直に語った回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nikki%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Nikki Bella"]._weak) { PROFILES["Nikki Bella"].lead = "シングルマザーとして5歳の息子を育てながら、41歳でリングに戻ったニッキー・ベラ。農家の家系に生まれ、サッカー一筋だった少女時代の挫折から、ナパのワイン事業まで率直に語った回。"; delete PROFILES["Nikki Bella"]._weak; }
  PROFILES["Nikki Bella"].facts.push(...[{"cat": "体のこと", "t": "トレーナーを呼び戻して体を鍛え直す", "b": "最近の引き締まった体の秘訣を聞かれ、冗談まじりに「別れたあとの見返しボディ」だと答えている。ピラティス系のクラスや自主トレが好きだったが、限界まで追い込んでもらうためにパーソナルトレーナーを再び付けたという。週3〜4回のトレーニングで、デッドリフトやスクワットを久しぶりに再開したそうだ。サッカーで守備の選手だったこともあり太ももの力が強く、ジムではブリーより重い重量を挙げると話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（0:50〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=50s"]]}, {"cat": "好きなもの", "t": "トレーニングのお供は90年代ヒップホップ", "b": "自分を「90年代生まれ」と呼び、ジムでは90年代から2000年代初めのオールドスクールなヒップホップを聴くと気合いが入るという。クラシックロックも好きだそうだ。中学時代にはブリーとミックステープを作り、ラジオで好きな曲が流れると急いで録音ボタンを押していたと懐かしむ。焼いたCDもずっと持っていたが、処分してしまったことを後悔していると話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:42〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=102s"]]}, {"cat": "家族", "t": "5歳の息子マテオがいちばん", "b": "息子マテオは5歳になったばかり。周りから「いつ恋愛を再開するの」と聞かれるが、41歳のいまは息子と過ごす時間がいちばん大事だという。マテオは毎晩ニッキーのベッドで眠り、来客に家を案内するときは「ここがぼくとママの部屋」と紹介するそうだ。子どもを通して知った無条件の愛ほどのものはない、と語っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（12:31〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=751s"]]}, {"cat": "家族", "t": "根性は生まれつきと育った環境から", "b": "粘り強さはどこから来たのかと聞かれ、生まれつきの部分に加え、子ども時代に多くのことを乗り越え、自力で生き延びるしかなかった経験が大きいと話す。そばにブリーがいたことに救われたという。身近に「ああはなりたくない」という悪い手本と、「こうなりたい」という素晴らしい手本の両方があったことが恵みだったと振り返る。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（21:03〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1263s"]]}, {"cat": "家族", "t": "共同養育はライフコーチと向き合う", "b": "元パートナーとの共同養育について、ライフコーチの助けを借りていると明かす。相手側までコントロールしたくなるものだが、「子どもには良い親が一人いれば十分」と教わり、自分の子ども時代を思い返して腑に落ちたそうだ。同じ立場の親たちにも「良いほうの親でいればいい」と伝えていると話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（22:40〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1360s"]]}, {"cat": "リングに来るまで", "t": "高校卒業の翌日に家を出た", "b": "高校を卒業した翌日、アリゾナ州フェニックスからサンディエゴへ引っ越したという。最初の学期の寮費は祖父母が出してくれたが、その後はウエートレスをしてルームメイトと家賃を分け合う暮らしだったそうだ。息子が巣立つ日を思うと今から寂しく、裏庭にゲストハウスを建てて近くにいてほしいと冗談めかしている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（25:03〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1503s"]]}, {"cat": "リングに来るまで", "t": "迷っていた自分を救ったサッカーの恩師", "b": "けがで奨学金を失い、サンディエゴで「何もかもうまくいかない」と腐っていた時期があったという。そんなとき地元のコミュニティカレッジ、グロスモント・カレッジのサッカー監督が声をかけ、1年後にチームへ復帰。地区大会まで勝ち進んだそうだ。当時はトラウマを抱えて誰にも打ち明けず、ブリーにさえ心を閉ざしていたと振り返り、あの監督は人生への贈り物だったと話す。21歳でチーム最年長になり、遠征ではチームのシャトルバスを運転したこともあったという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（26:43〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1603s"]]}, {"cat": "家族", "t": "16歳から続いたつらい出来事", "b": "サッカーは11年間、自分のすべてだったという。16歳のころ両親が激しい離婚をし、父親とは口をきかなくなり、その父親が薬物で命を落としかけたこともあったと明かす。さらにブリーの恋人が飲酒運転の事故で亡くなり、弟も荒れて家族の手に負えない時期があったそうだ。当時38歳ほどだった母親の苦労を、41歳になったいま思い返し、もっと優しくすればよかったと話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（30:44〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1844s"]]}, {"cat": "体のこと", "t": "高校最後の年に脚を骨折", "b": "高校3年生のとき、守備のスイーパーとしてスライディングタックルに入った瞬間、右脚の骨が真っ二つに折れたという。骨が皮膚を突き破る開放骨折ではなかったが、折れた音はいまも耳に残っていると話す。このけがで大学の奨学金と、決まりかけていた女子プロサッカーチーム入りの道を失ったそうだ。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（33:09〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=1989s"]]}, {"cat": "暮らし", "t": "部屋は片づいていないと気がすまない", "b": "自他ともに認めるきれい好きで、キッチンのカウンターには物を出しておきたくないという。置いてよいのは見た目のいいオリーブオイルくらいだそうだ。毎晩すべてを片づけてから寝るのは、朝起きてキャンドルに火をつけ、コーヒーをいれる時間を気持ちよく迎えたいからだと話す。ただ今の家は「ほとんどマテオの家」だと笑う。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（42:48〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=2568s"]]}, {"cat": "家族", "t": "息子の思い出は箱と壁に", "b": "マテオの作品や思い出の品は、ガレージに置いた「メモリーボックス」にハロウィンの衣装や賞状と一緒にしまっているという。プレイルームには2歳から5歳までの絵を集めたコラージュを飾り、玄関にも息子の絵を飾ったそうだ。最初の母の日にもらった、手形で作った花束の工作はいまも飾っている。巡業中はホテルの部屋で一人、息子の動画を見返していると話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（46:51〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=2811s"]]}, {"cat": "家族", "t": "カリフォルニアの農家の家系に育つ", "b": "家族のルーツは、サンディエゴから車で2時間ほどの国境近くの小さな農業の町ブローリー。夏は気温が50度近くになる土地で、小学3年生まで暮らしたあと、母親の決断でアリゾナへ移ったという。母方の祖父は移民一世の家系で、一族はイタリアからフィラデルフィアへ渡り、露店で青果を売っていたそうだ。そこから南カリフォルニアに来た最初期の農家の一つになり、今では伯父たちが事業を大きく育てていると誇らしげに話す。家族がフィラデルフィアの熱狂的なアメフトファンなのもそのためだという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（56:31〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=3391s"]]}, {"cat": "好きなもの", "t": "スポーツ一家で育ったおてんば娘", "b": "母方のイタリア系の親族みんなでファンタジーフットボールを楽しみ、シーズンの優勝者がサイン入りの帽子をもらうのが恒例だという。子どものころは大の男勝りで、バスケットボール、アメフト、サッカーに夢中だったそうだ。子ども時代のバスケットボールカードは今も持っていて、マグジー・ボーグスにサインをもらえたら大喜びすると話す。サッカー女子米国代表のミア・ハムたちにも刺激を受けたという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:00:40〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=3640s"]]}, {"cat": "暮らし", "t": "ナパの暮らしと花粉対策", "b": "農業に親しんで育ったこともあり、カントリーでありつつ洗練されたナパ・バレーに惚れ込んだという。高い建物も空港もなく、ぶどう畑と朝日・夕日、風が葉を揺らす音のある静かな土地だと語る。ぶどう畑のそばにはバラが植えられ、病気が出るとまずバラに現れるので農家の警報になるのだそうだ。収穫期にはアレルギーが出るようになり、電動の鼻うがい器が手放せないと話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:02:10〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=3730s"]]}, {"cat": "体のこと", "t": "冷水浴にはまっている", "b": "冷水浴が大好きで、水温は華氏52度（約11度）に設定し、3〜5分ほど入るという。気分しだいで1分半で切り上げる日もあり、記録を作るためではなく効果を得るためにやっていると話す。浴槽に水を張っている時期はほぼ毎日入り、関節炎の痛みがしばらく消えるそうだ。最近はホルモンの健康にも関心を持ち、出産後の体の変化について学んでいると語る。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:05:21〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=3921s"]]}, {"cat": "家族", "t": "コロナ禍のさなかに出産", "b": "マテオを産んだのは2020年、パンデミックの始まりの時期だったという。出産中もマスクを外すことを許されず、息が苦しいと酸素マスクをつけられながら、3時間ほどいきんだそうだ。出産から24時間ほどで退院させられ、「この子をどうすればいいの」と途方に暮れたと振り返っている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:10:10〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=4210s"]]}, {"cat": "家族", "t": "飛行機好きで甘え上手な息子", "b": "マテオはシートベルトを外してしまうため、本人が嫌がってもまだチャイルドシートに座らせているという。祖母から言われた「あなたは子どもの親友ではなく母親」という言葉を胸に、心を鬼にしているそうだ。叱ろうとすると大きなキスで機嫌を取りにくる甘え上手で、油性ペンで床に落書きされたこともあったと笑う。動画サイトでロケットから本物の列車や飛行機に夢中になり、航空会社と行き先まで言い当てられるほどだという。数学は自分も得意科目だったと話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:13:16〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=4396s"]]}, {"cat": "暮らし", "t": "ネットの批判との付き合い方", "b": "ネットで声が大きいのは否定的な意見で、それは自分がうまくやっている証拠だと考えるようにしているという。最近のデータを見るまでは、自分がネットでいちばん嫌われていると思っていたそうだ。リアリティ番組で私生活を見せてきたこともあり、批判は多いと話す。言葉が刺さったときは「なぜ傷ついたのか」と自分に問い、瞑想で心を落ち着かせているという。ライフコーチの助けや瞑想アプリも活用し、夜に一日のストレスを抜くことが多いそうだ。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:22:58〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=4978s"]]}, {"cat": "暮らし", "t": "ワインと服、二つの会社を経営", "b": "ブリーと共同のワイン事業と、自分のアパレルブランドの二つを手がけているという。アパレルは環境意識の高いブリーが手を引き、今はニッキー一人で運営しているそうだ。経営で学んだのは、社員や出資者が自分と同じビジョンを持っていることの大切さだと話す。考えの違う人を周りに置いて、自分の名前がついた会社の方向性を見失った失敗もあったと明かしている。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:29:25〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=5365s"]]}, {"cat": "暮らし", "t": "ワインの名前に込めた二つのルーツ", "b": "「ベラ」の名はイタリア系の祖父が姉妹をそう呼んでいたことに由来するという。メキシコ系のルーツにも目を向けたいと考え、名曲「マリア・ボニータ」を聴きながら「ボニータ・ボニータ」と口ずさんだのがワインの名前になったそうだ。自己資金だけで、女性中心の少人数のチームで育ててきたと話す。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:34:15〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=5655s"]]}, {"cat": "好きなもの", "t": "19世紀フランス絵画の収集家", "b": "熱心なアート収集家で、特に19世紀後半のフランス美術や当時の王侯貴族の世界にひかれるという。「前世はフランスにいた気がする」と話すほどだ。集めた原画はナパの中心部にあるワインの試飲室に飾っているそうだ。そこには一族が使った青果の屋台や、第二次世界大戦で女性パイロットとして活躍した大叔母の写真も展示しているという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:35:52〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=5752s"]]}, {"cat": "家族", "t": "二つの家系をつないだ双子", "b": "父方はメキシコ系、母方はイタリア系の農家で、カナダから来た種苗業者の家系も母方にいるという。両親は高校を出てすぐに双子を授かり、当時は交わることの少なかった二つの家系の最初の孫として、ニッキーとブリーがみんなをつないだそうだ。両親が結婚前だったため、法律上の姓は両方を合わせたガルシア＝コレイスのまま。いつか法的に「ベラ」に変えることも考えたと話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:37:31〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=5851s"]]}, {"cat": "暮らし", "t": "恋愛はゆっくり", "b": "独身に戻り、同じく独身になった女子選手仲間と恋愛の話で盛り上がることもあるという。ただ相手がナパに住んでいたり、訪ねてきたりするのは困るし、何年も息子には会わせないと決めているそうだ。ブリーからはもっと楽しんでと背中を押され、少しは試してみたと笑う。最近は年上にひかれる傾向があるが、急ぐつもりはないと話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:39:53〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=5993s"]]}, {"cat": "リングに来るまで", "t": "自分たちを売り込んだ日と最初の受け身", "b": "20年近く前、ブリーと二人で会社の上層部の前に立ち、双子ならではの企画を自ら売り込んだことを覚えているという。家のプリンターで資料を刷り、切り貼りして準備したそうだ。サッカーのあと道に迷っていた時期を経て、女性タレント発掘のオーディションをきっかけにこの世界へ入ったと振り返る。リングで初めて受け身をとったとき「やっと自分の居場所が見つかった」と感じたと話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:47:53〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6473s"]]}, {"cat": "好きなもの", "t": "暗い詩を書くのが心の出口", "b": "詩を書いているが、内容が重く暗いため、ほとんど人に見せていないという。自分にとってはセラピーのようなもので、書いて吐き出し、あとで読み返して「あのときこう感じたけど今はここにいる」と確かめられるのがいいそうだ。読書家ではないが息子とは一緒に本を読み、息子には本好きになってほしいと話す。母親からは毎日のようにAIを勉強するよう言われているという。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Wk3LitLm8E0", "src": [["公式YouTube（1:48:40〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=6520s"]]}]);
  if (PROFILES["Jey Uso"]) PROFILES["Jey Uso"].facts.push({"cat": "暮らし", "t": "海外巡業でも同じ部屋だった双子", "b": "リアリティ番組の撮影を通じてサモア系の一家と親しくなったという。海外巡業中、ニッキーとブリーが同じ部屋から出てきたとき、ジミーとジェイのウーソ兄弟も同じ部屋から出てきて「誰にも言わないで」と頼まれたそうだ。部屋で一緒に映画を観ることもあると聞き、双子の絆はよく分かると、ニッキー・ベラが話している。", "sp": "ニッキー・ベラ", "d": "2025-09-18", "how": "ステファニーの番組で、ニッキー・ベラの話（公式字幕を全文確認）", "src": [["公式YouTube（53:19〜）", "https://www.youtube.com/watch?v=Wk3LitLm8E0&t=3199s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-Wk3LitLm8E0", d: "2025-09-18", show: "wys", who: ["Nikki Bella"], t: "ニッキー・ベラの回　母になって戻ったリング、サッカーの挫折、農家のルーツ", lead: "ステファニー・マクマホンの番組に出た約114分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nikki Bella"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-Wk3LitLm8E0").map((x) => [x.t, x.b, x.sp])), open: ["出産後の体のケア（骨盤底のリハビリなど）の話は、聞き手との発言の区別が追いきれず、細部を省いた。皮肉屋の父親の話、テストで考えすぎる話も話者が判別できず載せていない。", "冒頭と終盤のサマースラムの試合や負傷をめぐる話は筋書きにかかわるため省いた。母方の一族の青果会社の名は字幕から確認できず、記載していない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=Wk3LitLm8E0"]] });
  if (!ROSTER.find((r) => r[1] === "El Fiscal")) ROSTER.push(["エル・フィスカル", "El Fiscal", "lg", "", "", "", ""]);
  if (!PROFILES["El Fiscal"]) PROFILES["El Fiscal"] = { lead: "伝説の悪役アビスモ・ネグロの息子、エル・フィスカル。8歳で父を亡くし、何もかも失った家族を支えながら、父の残した「プロレス」という遺産で立ち上がった。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=El%20Fiscal"]], moves: [], facts: [] };
  if (PROFILES["El Fiscal"]._weak) { PROFILES["El Fiscal"].lead = "伝説の悪役アビスモ・ネグロの息子、エル・フィスカル。8歳で父を亡くし、何もかも失った家族を支えながら、父の残した「プロレス」という遺産で立ち上がった。"; delete PROFILES["El Fiscal"]._weak; }
  PROFILES["El Fiscal"].facts.push(...[{"cat": "家族", "t": "父が大きな服を買えば、自分には小さい同じ服", "b": "父アビスモ・ネグロが生きていた頃は、世界一幸せな子どもだったと、フィスカルは話す。家族で巡業についていき、父が大きなサイズの服やスニーカーを買うと、自分には同じものの小さいサイズを買ってくれたという。ジムで父に宙返りの練習をさせられ、甘やかされることはなかったそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（14:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=840s"]]}, {"cat": "家族", "t": "リングでは悪役、家では優しい父", "b": "父はリング上では完全な悪役だったが、家では穏やかで愛情深く、日本遠征から帰ると学校の送り迎えや料理もしてくれたと、フィスカルは話す。人としての評価は人それぞれでも、自分にとっては非の打ちどころのない父だったという。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（16:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=960s"]]}, {"cat": "家族", "t": "8歳で父を亡くした", "b": "父が亡くなったのは自分が8歳のときだったと、フィスカルは振り返る。母はかねて「お父さんが棺で帰ってきたらどうする」と子どもたちに話していたという。知らせを聞いたときはショックで涙も出ず、父がいないことを実感して泣いたのは、もっと後になってからだそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（17:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1020s"]]}, {"cat": "家族", "t": "何もかも失い、母が4人の子を育てた", "b": "父の死後、家族は母の故郷タバスコ州ビジャエルモサへ移ったと、フィスカルは話す。数年後に戻ると、父が買った家には他人が住みつき、車も盗まれていたという。母は働き詰めで4人の子を育て、困ったときに父の友人たちは姿を見せなかったそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（17:53〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1073s"]]}, {"cat": "暮らし", "t": "大学の学費は恩師が出してくれた", "b": "大学の学費は、中学で知り合った先生が出してくれたと、フィスカルは話す。会計学の学位を取ったという。今は自分が姉妹の大学の学費を助けていて、映画『ペイ・フォワード』のような恩送りだと感じているそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（20:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1200s"]]}, {"cat": "リングに来るまで", "t": "水の配達をしながら練習代を払った", "b": "子どもの頃から働くことを教えられ、食堂の手伝いや水のタンクの配達で、プロレスの練習代を払ったと、フィスカルは話す。サッカーやバスケットボール、テコンドーもこなしてきたので、父が残したプロレスもできるはずだと思ったという。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（22:25〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1345s"]]}, {"cat": "リングに来るまで", "t": "パンデミックで父の遺品を売り、覆面をかぶった", "b": "パンデミックで収入が途絶えたとき、姉の提案で父のポスターや衣装、試合で使った覆面をネット配信で売って家計を支えたと、フィスカルは話す。配信で父の覆面をかぶったところ、ファンから「いつデビューするのか」と聞かれるようになったという。今手元に残る覆面は、もう売らない宝物だそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（24:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1440s"]]}, {"cat": "リングに来るまで", "t": "15、6歳の追悼試合では酷評された", "b": "15、6歳の頃、父の追悼の場で父の最後の衣装と覆面を着たが、体が細く厳しく批判されたと、フィスカルは振り返る。父をたたえたい気持ちだったのに、つらい経験になったという。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（25:30〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1530s"]]}, {"cat": "リングに来るまで", "t": "立ち入り禁止の会場で隠れて練習", "b": "外出もできない時期、友人と会場の持ち主に頼み込んで、隠れて昼も夜も2週間ほど練習したと、フィスカルは話す。父の仲間だったチャーリー・マンソンが最初の師匠になり、サイコシスには「もう遅いくらいだ」と厳しく言われたという。今では2人とも自分を支えてくれる人だそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（26:19〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=1579s"]]}, {"cat": "リングに来るまで", "t": "観光地の常設興行で1年間ほぼ毎日試合", "b": "カンクンの観光客向け常設興行「ルチャティトラン」で1年間、週6日以上試合をしたと、フィスカルは話す。物語仕立ての興行で、王の隠し子の役を演じたという。母や姉妹の誕生日を犠牲にしたが、普通なら10年かかる経験を1年で積めたそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（36:57〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=2217s"]]}, {"cat": "リングの話", "t": "覆面の牙は、父がいたユニットへの敬意", "b": "覆面の牙は、父も所属した悪役ユニット「ロス・バイパーズ」を表していると、フィスカルは話す。最初は口元の化粧をしていなかったが、ファンや先輩の勧めで、父らしさを出すために化粧をするようになったという。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（42:31〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=2551s"]]}, {"cat": "リングの話", "t": "言葉の通じない相手との試合で英語の必要を痛感", "b": "英語を話せないまま米国の選手と試合をし、とても苦労したと、フィスカルは振り返る。プロレスは世界共通の言葉だが、それだけでは足りなかったという。WWEとの提携で控室にも英語が増え、今は英語の授業を受けているそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（44:11〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=2651s"]]}, {"cat": "暮らし", "t": "口ぐせは「甘えるな」", "b": "規律と継続こそ成功の土台だと考え、いつもジムで鍛え、食事も弁当箱に詰めて持ち歩いていると、フィスカルは話す。疲れていても限界以上を出すという意味で「甘えるな」を合言葉にしているという。母は自分の一番のファンで、手が回らないときは食事も作ってくれるそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（47:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=2820s"]]}, {"cat": "リングの話", "t": "「エル・フィスカル」の名前の由来", "b": "父がテレビ番組で演じた役「鉄の検事（フィスカル・デ・イエロ）」から名前を取ったと、フィスカルは話す。ほかの案は使用中の名前や権利の問題で使えなかったという。衣装と覆面の下絵は自分で描き、父がかつて名乗った複数のリングネームへの敬意を込めたそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（56:17〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=3377s"]]}, {"cat": "体のこと", "t": "鼻の骨折と肩のけが", "b": "試合中にアルベルト・デル・リオのストンプで鼻を折り、手術を受けたと、フィスカルは話す。覆面がはがれかけていて、顔を守るのか鼻を押さえるのか分からなかったという。別の試合で仲間の技を受けて首と肩を痛めてから、肩はずっと治りきらず、ひざもバレーボールで痛めたそうだ。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（59:00〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=3540s"]]}, {"cat": "家族", "t": "父の優しさを受け継ぎたい", "b": "父は自分の高価な服や靴を、路上で暮らす人に脱いで渡してしまうほど優しい人だったと、フィスカルは話す。自分もファンには誠実でいたいという。父と同じ道を選ぶかどうかは自分で決められる、人生は選択の連続だとも語っている。", "sp": "エル・フィスカル", "d": "2025-09-22", "how": "ラテン・ラバーの番組で（字幕を全文確認）", "art": "ext-otszTT6fWoA", "src": [["番組のYouTube（1:07:24〜）", "https://www.youtube.com/watch?v=otszTT6fWoA&t=4044s"]]}]);
  ARTICLES.push({ id: "ext-otszTT6fWoA", d: "2025-09-22", show: "ext", who: ["El Fiscal"], t: "エル・フィスカルの回　父アビスモ・ネグロの記憶、パンデミックからの出発、「甘えるな」", lead: "ラテン・ラバーの番組に出た約84分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["El Fiscal"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-otszTT6fWoA").map((x) => [x.t, x.b, x.sp])), open: ["家族の本名、母の病気、家族の私的な事情は載せていない。", "聞き手自身のけがの話や、番組の宣伝は除いた。", "最近の個人的なトラブルの話は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=otszTT6fWoA"]] });
  if (!ROSTER.find((r) => r[1] === "Mick Foley")) ROSTER.push(["ミック・フォーリー", "Mick Foley", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Mick Foley"]) PROFILES["Mick Foley"] = { lead: "体を張ったハードコアの伝説でありながら、物語を語る力と人を思う心でファンに愛されてきた。妻コレットや子どもたちの存在が、長い道のりを支えてきたという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Mick%20Foley"]], moves: [], facts: [] };
  if (PROFILES["Mick Foley"]._weak) { PROFILES["Mick Foley"].lead = "体を張ったハードコアの伝説でありながら、物語を語る力と人を思う心でファンに愛されてきた。妻コレットや子どもたちの存在が、長い道のりを支えてきたという。"; delete PROFILES["Mick Foley"]._weak; }
  PROFILES["Mick Foley"].facts.push(...[{"cat": "リングに来るまで", "t": "約15か月の修行を経てエキストラ時代へ", "b": "ミック・フォーリーは、約15か月の練習を積んだあと、大手団体でエキストラ役としてリングに上がっていたと話す。最高の選手たちの試合を壊さないためには、それなりの技術が要る仕事だったという。やがて名前が覚えられ始めると、一つの場所に頼りきるのは危ないと感じ、独立系の舞台で腕を磨く道を選んだそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（4:06〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=246s"]]}, {"cat": "リングに来るまで", "t": "試合映像を見て自分だけの型を作った", "b": "ミック・フォーリーは、仲間が見せてくれた試合のテープで殴り方や跳び方を学び、ブロディやダイナマイト・キッドらの要素を自分流に混ぜていったと話す。パンチもろくに打てない乱闘型だったので、まねではなく、使える部分だけを取り出して育てたという。若い選手には、年配の選手の助言は何でも聞いておくと、いつか役立つ日が来ると勧めている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=338s"]]}, {"cat": "リングに来るまで", "t": "125ドルの宣材写真で初のテレビ試合へ", "b": "ミック・フォーリーは、倹約家だった当時、プロのカメラマンに125ドルを払って宣材写真を撮ってもらったと話す。その写真のおかげで、メンフィスで最初のテレビ試合に呼ばれたという。ただ、独立系では相手を立てることばかり学んでいて、自分を目立たせる方法が分からず苦労したそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（8:03〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=483s"]]}, {"cat": "暮らし", "t": "遠征は三人相部屋、仲間のいたずらが日常", "b": "ミック・フォーリーは、若いころの遠征では仲間と三人で相部屋になることが多く、簡易ベッドを交代で使っていたと話す。ダラス・ペイジをからかって何日でいらいらさせられるか賭けていたという。ある夜、暗闇の部屋でベッドにクッキーを置いたいたずらを仕掛け、翌日からペイジが別室を求めたと笑って語っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（12:55〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=775s"]]}, {"cat": "リングに来るまで", "t": "恩人エディ・ギルバートに頭を使えと教わる", "b": "ミック・フォーリーは、エディ・ギルバートに出会い、体だけでなく頭を使うよう励まされたと話す。悪役の名手だったエディのもとで、ベビーフェイスとして客に訴える術も学んだという。テリー・ファンクが感情を素直に見せる姿からも多くを学んだが、まねはせず自分のものにしたそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（20:12〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=1212s"]]}, {"cat": "家族", "t": "妻コレットの一言が壁を破るきっかけに", "b": "ミック・フォーリーは、交際を始めたころの自分の試合を見た妻コレットに、もっとできるはずだと言われたと話す。もし何も変えなくていいと言われていたら、今の自分はなかったという。妻の信頼があったから次の段階へ進めたと振り返っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（20:12〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=1212s"]]}, {"cat": "体のこと", "t": "ロープに挟まれて耳を失いかけた夜", "b": "ミック・フォーリーは、ロープに絡まる技を何度もやり、耳の裏を切って救急に行ったこともあったと話す。ある夜、ワイヤー製のロープが固く締まっていて抜け出せず、そのまま耳を傷めたそうだ。今思えば、もっと前にその技をやめるべきだったと振り返っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（23:33〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=1413s"]]}, {"cat": "好きなもの", "t": "試合前に聴くトーリ・エイモスの曲", "b": "ミック・フォーリーは、トーリ・エイモスのカセットを聴いて気持ちを高めてから試合に臨んでいたと話す。特に「Winter」という曲が気持ちを奮い立たせてくれて、試合のあと雲の上を飛んでいるような気分になったという。観客が少ない試合でも、団体を大きくするという思いで全力を出したそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（27:31〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=1651s"]]}, {"cat": "リングの話", "t": "初の対戦相手アンダーテイカーに勝たされて驚いた", "b": "ミック・フォーリーは、WWEでの最初の相手がアンダーテイカーで、勝つ流れを告げられて驚いたと話す。トップの選手と少し戦ってから下がるだろうと思っていたからだ。毎回ゴングが鳴るたびに、観客に勝てるかもと思わせなければと自分に言い聞かせていたという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（31:34〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=1894s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズとの試合は今も鮮明に覚えている", "b": "ミック・フォーリーは、ショーン・マイケルズとの試合を26分間戦い、一つ一つの動きを全部覚えていると話す。体格差が大きく、自分が大きな選手の役を演じるにはちょうどよい相手だったという。ただ、この二人やアンダーテイカーと、年間最大の祭典で戦えなかったことが心残りだそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（34:50〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=2090s"]]}, {"cat": "リングの話", "t": "高校時代に作ったドゥード・ラブを演じるまで", "b": "ミック・フォーリーは、ショーンに「憧れの姿はこれだったのか」と聞かれ、自分が昔作ったドゥード・ラブの話をしたと話す。ホームビデオまで残っていて、ブルース・プリチャードを通して社長に伝わったそうだ。素の自分を見せるインタビューを、役のまま本心で話したところ、社長から素晴らしいと言われたという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（42:21〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=2541s"]]}, {"cat": "リングの話", "t": "ヘル・イン・ア・セルは「恥をかきたくない」一心だった", "b": "ミック・フォーリーは、テリー・ファンクが金網の上から試合を始めればと言ったのが出発点だったと話す。アンダーテイカーには、先代の名勝負に及ばないと恥ずかしいと打ち明けて説得したそうだ。初めて上に立ったときは、これは無理だと思うほど高かったという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（55:07〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=3307s"]]}, {"cat": "家族", "t": "娘ノエルの「いい人だから」という言葉", "b": "ミック・フォーリーは、大一番の直前に家族でニューハンプシャーの山にある遊園地へ行ったと話す。当時3、4歳だった娘のノエルが初めてのジェットコースターで頬にキスをし、「いい人だから」と言ってくれたそうだ。その24時間後に歴史に残る試合に臨んだが、あの旅の思い出が一番心に残っているという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（57:35〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=3455s"]]}, {"cat": "家族", "t": "幼い息子たちと母のペイ・パー・ビュー", "b": "ミック・フォーリーは、あの伝説の試合を、5歳と7歳ほどだった息子たちが見たがったと話す。自分も10年ほど通して見ていなかったが、一緒に見て今でも力があると感じたそうだ。きょうだいからは、母がペイ・パー・ビュー代を払い、翌日に録画を見せていたという話も聞いたと語っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:05:45〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=3945s"]]}, {"cat": "リングに来るまで", "t": "少年時代に見た金網からの飛び技が原点", "b": "ミック・フォーリーは、かつて見たスヌーカの金網からの飛び技の衝撃を、今度は自分が観客に届けたかったと話す。アンダーテイカーから、あの試合は二人がいなくなってもずっと語り継がれると言われたとも話している。それまで一つの試合だけで記憶されることを気にしていたが、その言葉で肩の荷が下りたという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:06:32〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=3992s"]]}, {"cat": "リングの話", "t": "体を守るために温かさとユーモアを足した", "b": "ミック・フォーリーは、あの試合のあと、これ以上は体を危険にさらせないと考えて、キャラクターに温かさを加えたと話す。「木を投げられるなら…」という早口言葉のような決め台詞が受け、会場が一緒に数え始めたという。怖がられていた人物が、観客と心を通わせる存在に変わっていったそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:10:32〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=4232s"]]}, {"cat": "リングの話", "t": "ザ・ロックを引き立てる役に徹した", "b": "ミック・フォーリーは、ザ・ロックの敵役への変身のために、本気の冷酷さを見せる試合が必要だと考えたと話す。結果的にやりすぎで、楽しい試合ではなかったと認めている。自分は道を開ける役で、星はロックだという考えで動いていたそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:18:03〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=4683s"]]}, {"cat": "リングの話", "t": "裏番組に結末を明かされて王者になった夜", "b": "ミック・フォーリーは、年末に収録した放送で王座を奪う試合が、裏番組の他団体に先に結末を明かされたと話す。傷ついたが、結果として視聴者が大きく増え、業界内での見られ方が変わったという。のちに相手のアナウンサーから電話で敬意を伝えられたそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:20:26〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=4826s"]]}, {"cat": "家族", "t": "子どもたちが作った靴下とシューズ", "b": "ミック・フォーリーは、トレードマークの靴下の人形を子どもたちが作ってくれたと話す。その靴下が今どこにあるのか知りたいと、懐かしそうに笑っている。別の大舞台では、子どもたちが飾り付けたシューズを履いて戦ったそうで、それが大きな支えになったという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:22:54〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=4974s"]]}, {"cat": "リングの話", "t": "ロック・ソックは「悪役転向」をやめて守った", "b": "ミック・フォーリーは、ロックと組んだ当初は裏切る予定だったが、客の反応がとても本物だったので転向したくないと社長に伝えたと話す。膝が限界に近づいていたことも理由の一つだったそうだ。名試合は思い出せなくても、客は二人の関係に感じた気持ちを覚えているという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:26:01〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5161s"]]}, {"cat": "体のこと", "t": "膝と腰、記憶力の衰えを感じて引退を決める", "b": "ミック・フォーリーは、本が大ヒットしていたころ、膝や腰だけでなく記憶にも不安を感じていたと話す。ある試合で技の順序を間違えるなど、自分が納得できない出来になり、悔しかったという。その後、会社から最後の試合を告げられ、悔いのない形で終えたいと考えたそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:31:11〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5471s"]]}, {"cat": "体のこと", "t": "約30ポンド絞って最後の大型試合へ", "b": "ミック・フォーリーは、トリプルHとの一連の試合のために、6週間ほど巡業を外れて約30ポンド減量したと話す。かつては体重が280ポンドや300ポンドの時期もあり、腰の痛みに悩まされていたという。復帰戦のころは270ポンドから300ポンドへと体が変わっていて、本来はもっと絞るべきだったと振り返っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:32:52〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5572s"]]}, {"cat": "家族", "t": "引退試合の夜、父ときょうだいは会場にいた", "b": "ミック・フォーリーは、引退試合の会場に父ときょうだいが来て、控室で顔を合わせられたと話す。望んだ形で終えられたが、その夜はいつもよりいい部屋を取り、ルームサービスを頼んで一人で泣いたという。人生で最高の瞬間に、大切な人がそばにいないのは寂しかったそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:34:27〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5667s"]]}, {"cat": "リングの話", "t": "エッジとの一戦で果たした「年間最大の祭典の瞬間」", "b": "ミック・フォーリーは、長年望んでいた年間最大の祭典の名場面を、エッジとの試合でつかんだと話す。有刺鉄線を服の下に隠す仕掛けは、ブレット・ハートの前例にならったものだそうだ。当時は体重が約300ポンドで腰も悪かったが、エッジが弱点をうまくカバーしてくれたという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:37:45〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5865s"]]}, {"cat": "家族", "t": "試合後に妻が最初に聞いたのは相手のこと", "b": "ミック・フォーリーは、大舞台の試合のあと、公衆電話から妻に電話をかけたと話す。同情してもらえると思っていたのに、妻が最初に聞いたのは相手のエッジは大丈夫かということだったそうだ。その夜はあえてもう1泊して、体を休めてから家に帰ったという。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:44:03〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=6243s"]]}, {"cat": "リングの話", "t": "2013年の殿堂入りは、通い詰めた会場で", "b": "ミック・フォーリーは、昔は電車やヒッチハイクで通った会場で殿堂入りできたことを幸運だと話す。紹介役にはテリー・ファンクを選び、短くて笑えて心に残るスピーチだったと振り返っている。同じ年の顔ぶれが最高の殿堂入り組だったと胸を張っている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:48:03〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=6483s"]]}, {"cat": "暮らし", "t": "一人舞台で頭を使い続ける", "b": "ミック・フォーリーは、今はトークの一人舞台に出ていて、語り手であって冗談を言う芸人ではないと話す。金曜の夜は酔った客が多くて間が崩れるので避けているという。脳しんとうの研究者の友人から、話を思い出し即興も交える今のやり方は脳の運動になると言われ、頭が冴える実感があるそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:49:37〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=6577s"]]}, {"cat": "好きなもの", "t": "自作のビアードオイルとペパーミントの香り", "b": "ミック・フォーリーは、自分でビアードオイルを作っていると話し、その香りはペパーミントだという。ペパーミントが大好きなので、ひげだけでなく肌にも使え、朝に塗ると気分がしゃきっとすると勧めている。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:52:04〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=6724s"]]}, {"cat": "体のこと", "t": "痛みを隠さないことの大切さを若い世代に伝えたい", "b": "ミック・フォーリーは、膝や腰の痛みが今も残っているが、それが自分の歩んだ道を思い出させてくれると話す。仲間が病気に苦しむ姿を見るのはつらく、自分もできる限り元気でいようとしているという。ケガを隠すのが強さだと信じていたが、本当は認める方が強いと、若い世代に伝えたいそうだ。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Q5yjO2UsEiE", "src": [["番組のYouTube（1:52:50〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=6770s"]]}]);
  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "アンダーテイカーの励ましの言葉", "b": "アンダーテイカーはミック・フォーリーを今も「ジャック」と呼び、あの金網の試合は二人がいなくなったあとも語り継がれるだろうと言ってくれた、とミック・フォーリーが話している。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ミック・フォーリーの話（字幕を全文確認）", "src": [["番組のYouTube（1:06:32〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=3992s"]], "by": "第三者の話"});
  if (PROFILES["Edge"]) PROFILES["Edge"].facts.push({"cat": "暮らし", "t": "エッジは当時の最高の万能選手", "b": "エッジは当時の業界で一番の万能選手で、体の不安を抱えた自分の弱点を補ってくれた、とミック・フォーリーが話している。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ミック・フォーリーの話（字幕を全文確認）", "src": [["番組のYouTube（1:39:20〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5960s"]], "by": "第三者の話"});
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "ランディ・オートンとの試合で互いに高め合った", "b": "ランディ・オートンとの試合は、互いに高め合えた大切な一戦で、自分は彼を以前は行けなかった高みへ、彼は自分を行けなかった所へ連れて行ってくれた、とミック・フォーリーが話している。", "sp": "ミック・フォーリー", "d": "2025-10-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ミック・フォーリーの話（字幕を全文確認）", "src": [["番組のYouTube（1:35:12〜）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE&t=5712s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Q5yjO2UsEiE", d: "2025-10-05", show: "ext", who: ["Mick Foley"], t: "ミック・フォーリーの回　ヘル・イン・ア・セルから家族への思いまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約115分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Mick Foley"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Q5yjO2UsEiE").map((x) => [x.t, x.b, x.sp])), open: ["字幕は話者表記が入れ替わる箇所が多く、聞き手の発言と区別しにくい部分は載せていない。", "ストーン・コールドの思い出話と試合映像を見ながらの実況的なやり取りは省いた。", "他団体での活動時期の話は、年代があいまいなため詳しく載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Q5yjO2UsEiE"]] });
  if (!ROSTER.find((r) => r[1] === "Karrion Kross")) ROSTER.push(["カリオン・クロス", "Karrion Kross", "gn", "元NXT王者。WWEを離れた", "", "", ""]);
  if (!PROFILES["Karrion Kross"]) PROFILES["Karrion Kross"] = { lead: "WWEでは即興のプロモが評判になる一方、契約交渉で実績を軽く扱われたと感じたという。創作の信念を優先し、自由の身を選んだ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Karrion%20Kross"]], moves: [], facts: [] };
  if (PROFILES["Karrion Kross"]._weak) { PROFILES["Karrion Kross"].lead = "WWEでは即興のプロモが評判になる一方、契約交渉で実績を軽く扱われたと感じたという。創作の信念を優先し、自由の身を選んだ。"; delete PROFILES["Karrion Kross"]._weak; }
  PROFILES["Karrion Kross"].facts.push(...[{"cat": "退団の理由", "t": "契約は8月10日で満了、1月には残留希望を伝えていた", "b": "クロスは、年明けの1月の時点で会社側に「ふたりとも残りたい」と伝えていたと話す。契約は夫婦で同じ日に結んだものの別々の契約で、どちらも8月10日で終わったという。ずっと「何とかうまくいくように」動いていたそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=145s"]]}, {"cat": "退団の理由", "t": "前の契約のときも「彼女は後で」と言われた", "b": "NXTからRAWに上がる契約のときにも、電話で同じように「彼女のことはあとで考える」と言われたと明かす。その結果、彼がRAWに上がったあと、感染症対策で無観客が続いた時期にスカーレットは自宅にいたという。同じことを繰り返したくないという思いがあったと話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（4:05〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=245s"]]}, {"cat": "退団の理由", "t": "グッズや自伝の実績は「関係ない」と言われた", "b": "退団前の最後の話し合いで、本の売り上げや、会社トップクラスだったというグッズの売れ行きを話題にしようとしても、相手は見たがらなかったという。自分の人生を書いた本まで「評価に関係ない」と言われ、クロスは強い違和感を覚えたそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（7:53〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=473s"]]}, {"cat": "退団の理由", "t": "どれだけ働いても評価が動かない感覚", "b": "プロモも試合もグッズも、結局は会社が決めた数字に収まるだけだと感じたと話す。会社勤めで昇給を期待しているのに「ずっとこのままだ」と告げられるようなものだったという。「では何が大事なのか」と聞いても、答えは得られなかったそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（9:32〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=572s"]]}, {"cat": "WWEでの日々", "t": "アドリブのプロモが大反響、その後の行き違い", "b": "年間最大の祭典の会場で、台本なしで受けたインタビューが評判になった。ところが翌日、ある担当者から「制作側が怒っている」と連絡があり、クロスが制作陣に謝りに行くと、見ていない人もいて「何の話か分からない」と言われたという。後日トップとも直接話して誤解は解け、デジタル部門の面々も好意的だったそうだ。大きな会社で部署間の連絡が噛み合わないことがある、とクロスは受け止めている。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（10:17〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=617s"]]}, {"cat": "WWEでの日々", "t": "中継車にこもって番組づくりを学んだ", "b": "出番がない日は中継車に入り、ヘッドホンで演出の間やカメラ切り替えを聴いて学んだという。中継車のスタッフはみんな親切で、番組の仕組みをひとつ残らず知りたかったと話している。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（13:31〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=811s"]]}, {"cat": "WWEでの日々", "t": "グループの解雇後はバックステージ中心に", "b": "クロスは、ミズとのやりとりで普段の陰のある役柄とは違う面を見せられるようになり、観客にも伝わり始めていたと感じていた。ところがグループが解雇された後は舞台裏の場面ばかりになり、試合も年明けから1回だけ。3か月ほどテレビから遠ざかっていたという。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（16:44〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1004s"]]}, {"cat": "WWEでの日々", "t": "彼女だけが画面から消えていくと感じた", "b": "舞台裏の場面で毎週スカーレットを入れてほしいと頼んでも「今週は彼に集中したい」と断られたという。何週も続き、背景に遠く映るだけの扱いになったため、「彼女を外して自分だけ残す意図があるのでは」と思ったそうだ。WWEの在籍中にそう感じたのはその時期だけだと話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（19:05〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1145s"]]}, {"cat": "WWEでの日々", "t": "残された時間で役を演じ込む工夫", "b": "仲間が次々と去るなか、自分に決められるのは与えられた時間の使い方だけだと考えたという。ヘアスタイルや服装を話す相手に合わせて変えるなど、小さな工夫を重ねた。人の言動を映し出し、周りの悪い面を引き出す不気味な役柄として、心理学や社会学の資料を読んで作り込んだと話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（19:52〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1192s"]]}, {"cat": "WWEでの日々", "t": "プロモ直後に「クビになるかも」と思った", "b": "本気に見えるよう、事前に関係者へ「これは作り物の企画だと全員に伝えて」と頼んだが、実際は全員には伝わらなかったという。終えた直後、スカーレットに「解雇されるかな」と聞いたとクロスは話す。信じ込んだ人がいるくらいの手応えだった、という受け止めだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（22:20〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1340s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典の当日に急に出番が決まった", "b": "出番が決まったと知ったのは当日の午後1時半で、サイン会の会場から会場入りまで急いだそうだ。番組から外れかけていた時期で、自分で状況を動かさなければと考えていたという。持ち時間が短くても、台本なしなら勝負できると話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（23:07〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1387s"]]}, {"cat": "WWEでの日々", "t": "殿堂入り式典のレッドカーペットで即興の騒ぎ", "b": "AJスタイルズと会場に向かう途中、記者が並ぶレッドカーペットに出てしまった。その場の空気を変えようと、司会者の発言に反応して怒るふりをしたという。制作側は大喜びで翌日のポッドキャスト出演も頼まれたが、翌日には上の立場の人が「あの件は不適切だった」と謝りに来た。クロスは作り物のつもりだったので、「仕事をしていただけ」と説明したそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（24:46〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1486s"]]}, {"cat": "WWEでの日々", "t": "AJ戦で両手を背中に回した理由", "b": "試合の流れの中で、実況の声まで聞こえるほど集中していたという。相手の技を受ける場面で両手を背中に回したのは、悪の側へ引き込もうとする師弟関係のイメージだった。AJがクロスの肩に手を置き「別のやり方を試してみないか」と諭す役に回る展開を、AJらと期待していたが、実現しなかったそうだ。物語が途切れるのはこの会社ではよくあり、個人的には受け止めていないと話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（29:38〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1778s"]]}, {"cat": "退団の理由", "t": "お金より創作の信念を取る", "b": "創作上の信念が絡まない大金には興味がないと、クロスは話す。お金が目的なら他の仕事でも稼げるし、幼い頃から作品や場面を人の記憶に残すためにこの道に入ったという。WWEの絶頂期の思い出は大切で、独立後も自分に合う場所を探すと話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（40:05〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=2405s"]]}, {"cat": "退団の理由", "t": "WWEの扉が開いているかは「分からない」", "b": "最後に電話で聞いた条件を思うと、どこに戻るのかも、扉の向こうに何があるのかも分からないと話す。戻るなら、お金だけでなく成長の余地や最高の舞台で働けることが条件になる。ずっと話し合いの内容に、いまも戸惑っているそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（41:40〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=2500s"]]}, {"cat": "WWEでの日々", "t": "「クロスを呼べ」のチャントとその後", "b": "夏の大型興行の後の放送で起きたチャントについて、クロスは試合後にホテルで人に動画を見せられて知ったという。数週間続いたチャントに感謝し、「チャントは長く続かないから契約を受けるべきだ」と言う人にも、自分たちの成功は観客の騒ぎに頼ったものではないと答えたそうだ。出ている仲間の試合が目当てで来た観客にも気持ちを配りたい、とも話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（47:13〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=2833s"]]}, {"cat": "WWEでの日々", "t": "上層部に頼んだ映画の紹介は実現しなかった", "b": "約1年半前、電話で上層部に会社への貢献を高める方法を相談したという。数字を伸ばすため、ミズとの即興動画など自主的な発信を増やしたが、映画の関係者を紹介してもらう約束は果たされず、連絡も途絶えたそうだ。そこでクロスは映画づくりを一から学ぶことにした。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（53:40〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=3220s"]]}, {"cat": "退団の理由", "t": "最初の退団後は怒りが残っていた", "b": "最初の退団のあと、格闘技の試合への誘いを考えたのは、裏切られたような気持ちが残っていたからだと振り返る。怒りに任せる自分を抑えて実現しなかったことに、いまは感謝していると話す。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（1:00:06〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=3606s"]]}, {"cat": "WWEでの日々", "t": "ポール・ヘイマンに学んだ「自分を疑わない」こと", "b": "最大の学びは、自分を疑わず、自己認識を持って自分で修正することだとクロスは話す。ヘイマンのそばにいると、教えようとしなくても学べるという。中継車で、カメラが同じ画面に留まる時間を計ってくるよう言われたこともあり、結果は約3.4秒だった。テレビ向けの試合では、会場の観客と画面の向こうの両方を意識する発想が身についたそうだ。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（1:05:48〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=3948s"]]}, {"cat": "WWEでの日々", "t": "ジェシー・ベンチュラの物まねを巡る話", "b": "ジェシー・ベンチュラ側から、番組などで共演する話が何度も出ていたとクロスは話す。制作担当にも聞かれたが、決めるのは会社のトップだと答えて待っていたという。最終的に実現しなかったという。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（1:17:05〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=4625s"]]}]);
  if (PROFILES["The Miz"]) PROFILES["The Miz"].facts.push({"cat": "暮らし", "t": "ミズは惜しみなく教えてくれた", "b": "ミズは情報と知識の泉のような存在で、周りの人を助ける無私の人だったと、カリオン・クロスが話している。一緒に仕事をして学ぶことが多かったという。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で、カリオン・クロスとスカーレットの話（字幕を全文確認）", "src": [["番組のYouTube（16:44〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1004s"]], "by": "第三者の話"});
  if (PROFILES["AJ Styles"]) PROFILES["AJ Styles"].facts.push({"cat": "暮らし", "t": "AJスタイルズも一緒にいるだけで学べた", "b": "AJスタイルズも、そばにいるだけで学びがある人だったと、カリオン・クロスが話している。ポール・ヘイマンとミズも同じだったという。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で、カリオン・クロスとスカーレットの話（字幕を全文確認）", "src": [["番組のYouTube（1:06:37〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=3997s"]], "by": "第三者の話"});
  if (PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"].facts.push({"cat": "暮らし", "t": "ポール・ヘイマンは時間をたっぷり割いてくれた", "b": "ポール・ヘイマンは自分に多くの時間を割き、スカーレットにも親切で、カメラの位置やテレビの進行についてアドバイスをくれたと、カリオン・クロスが話している。", "sp": "カリオン・クロス", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で、カリオン・クロスとスカーレットの話（字幕を全文確認）", "src": [["番組のYouTube（1:06:37〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=3997s"]], "by": "第三者の話"});
