  if (!PROFILES["Scarlett"]) PROFILES["Scarlett"] = { lead: "2019年にWWEと契約し、契約満了の数か月前から離れる予感があったという。夫の交渉の陰で自分の扱いに疑問を抱いたと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Scarlett"]], moves: [], facts: [] };
  if (PROFILES["Scarlett"]._weak) { PROFILES["Scarlett"].lead = "2019年にWWEと契約し、契約満了の数か月前から離れる予感があったという。夫の交渉の陰で自分の扱いに疑問を抱いたと話す。"; delete PROFILES["Scarlett"]._weak; }
  PROFILES["Scarlett"].facts.push(...[{"cat": "退団の理由", "t": "数か月前から離れる予感があった", "b": "契約終了の1週間前の時点で、すでに数か月前から何が起きるか分かっていたと話す。占星術やタロットに通じていて、2月ごろから契約をめぐる揉め事が長引き、WWEを離れることになると感じていたという。ごく少数の人にしか話していなかったそうだ。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=96s"]]}, {"cat": "退団の理由", "t": "「彼が終わってから彼女の話を」と言われた", "b": "契約交渉の最後のほうで、自分の立場を聞くと「彼との話が済んでから」と言われたという。24時間の通知がある中で、自分が彼との交渉の材料にされていると受け止めた。自分のほうが2019年に先に入団しているのに、価値が彼の署名次第のように言われたのは不快だったと話している。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=196s"]]}, {"cat": "WWEでの日々", "t": "最初の離脱は管理役の復帰直後だった", "b": "スカーレットは、管理役としては出られても試合はできない状態だったと話す。会社は夫婦を引き離して自分に試合をさせたい考えだったが、許可が出た数日後に、ふたりとも解雇されたという。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（4:50〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=290s"]]}, {"cat": "退団の理由", "t": "契約は「そのまま切れる」と伝えられた", "b": "通告の翌日に会社側から連絡があり、夫の件ばかりで自分の契約には触れられず、「契約は失効する」と言われたという。「いつでも連絡して」と返したところ、上の人に電話するよう勧められて混乱したそうだ。それ以降、会社との連絡はなく、いまも出演者の仲間とだけ話していると話す。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（7:08〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=428s"]]}, {"cat": "WWEでの日々", "t": "自分の登場を増やしてもらうために", "b": "舞台裏の場面にスカーレットを入れるよう、AJスタイルズやミズが毎週のように動いてくれたという。AJが上層部にかけあって出演が認められたが、撮影後に制作の人から「どうやって入り込んだのか」と聞かれ、自分を外す動きがあったと感じたそうだ。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vjKvQJUqvQE", "src": [["番組のYouTube（18:19〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1099s"]]}]);
  if (PROFILES["AJ Styles"]) PROFILES["AJ Styles"].facts.push({"cat": "暮らし", "t": "AJスタイルズは何度も味方になってくれた", "b": "AJスタイルズは、スカーレットを舞台裏の場面に入れるため、自ら上層部に掛け合ってくれたと、スカーレットが話している。ミズも同じように味方してくれたという。", "sp": "スカーレット", "d": "2025-10-07", "how": "クリス・ヴァン・ヴリートの番組で、カリオン・クロスとスカーレットの話（字幕を全文確認）", "src": [["番組のYouTube（18:19〜）", "https://www.youtube.com/watch?v=vjKvQJUqvQE&t=1099s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-vjKvQJUqvQE", d: "2025-10-07", show: "ext", who: ["Karrion Kross", "Scarlett"], t: "カリオン・クロスとスカーレットの回　WWEを離れた経緯と、自由になってからの日々", lead: "クリス・ヴァン・ヴリートの番組に出た約86分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Karrion Kross", "Scarlett"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-vjKvQJUqvQE").map((x) => [x.t, x.b, x.sp])), open: ["複数人で話が重なる箇所は、誰の発言か判断できたものだけを載せた", "他団体への移籍やAEWの話、個人名が聞き取れない箇所は省いた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=vjKvQJUqvQE"]] });
  if (!ROSTER.find((r) => r[1] === "Nic Nemeth")) ROSTER.push(["ニック・ネメス", "Nic Nemeth", "gn", "元ドルフ・ジグラー。他団体", "", "", ""]);
  if (!PROFILES["Nic Nemeth"]) PROFILES["Nic Nemeth"] = { lead: "元ドルフ・ジグラー。約20年のWWEで休まずリングに立ち続け、使われ方への不満から自ら退団を願い出た。その経緯と思い出を振り返る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nic%20Nemeth"]], moves: [], facts: [] };
  if (PROFILES["Nic Nemeth"]._weak) { PROFILES["Nic Nemeth"].lead = "元ドルフ・ジグラー。約20年のWWEで休まずリングに立ち続け、使われ方への不満から自ら退団を願い出た。その経緯と思い出を振り返る。"; delete PROFILES["Nic Nemeth"]._weak; }
  PROFILES["Nic Nemeth"].facts.push(...[{"cat": "退団の理由", "t": "最後の契約の時点で退団を考えていた", "b": "ニック・ネメスは、最後の契約を結んだ時点で、満額の3年は在籍しないだろうと考えていたという。当時の自分の役割は大きな大会の穴埋めや急な対戦相手が中心で、世界王者を目指せる年数にも限りがあると感じていたそうだ。合意のうえで早めに離れるか、自分から動くつもりだったと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（11:54〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=714s"]]}, {"cat": "退団の理由", "t": "会社の外で自分を試したかった", "b": "20年間ずっとWWEという囲いの中にいたため、15年ぶんも口にしてきた大言を外の世界で実証したかったと話す。どの団体でも世界王者になれると自分で確かめたい、日本やメキシコ、独立系の会場でも通用するかを知りたいという気持ちが強かったそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（12:44〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=764s"]]}, {"cat": "退団の理由", "t": "使われ方への不満を長文メールで伝えた", "b": "当時は8分の試合が現場の事情で4分、さらに入場なしの短い試合に削られることが多く、本人は活かされていないと感じていたという。そこで上層部に、感謝を述べつつも、地元の選手でも務まる役回りに大きな大会の主役級の給料が払われているのは会社にも自分にも良くない、という内容の長いメールを送ったと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（14:23〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=863s"]]}, {"cat": "退団の理由", "t": "解放を願い出て、翌週にリリースされた", "b": "それまでにも辞めたいと伝えたことはあったが、契約があるからと断られてきたという。今回は会社が売却される時期と重なり、早めの解放か別の役割を話し合いたいと求めた。ビンス・マクマホンからは「考える時間がほしい」と言われ、その翌週に解雇者のリストに名前が入っていたそうだ。本人は、売却に向けた人員整理がなければ、あと1年半ほどは在籍していたと思うと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（15:11〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=911s"]]}, {"cat": "WWEでの日々", "t": "育成契約の書類を弁護士に見せた", "b": "最初の育成契約は数ページの短いもので、両親が念のため弁護士に確認させたという。弁護士は本名の権利などに強く懸念を示したが、ニック・ネメスは夢がかなう機会だったため、何があっても署名すると決めていたそうだ。本採用の契約は電話帳のように分厚くなったと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（16:42〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=1002s"]]}, {"cat": "WWEでの日々", "t": "解雇を恐れた15年と、恐れなくなった数年", "b": "最初の15年は解雇のたびに不安だったと話す。負け役が多く、上位で使われない時期が12年ほどあったためだという。やがてどこでも生き残れるという自信がつき、最後の数年は会社を挑発するような発言をすることもあったそうだ。常に働いては愚痴を言うのが自分流だったとも話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（17:32〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=1052s"]]}, {"cat": "WWEでの日々", "t": "「手を抜いている」と言われた冗談の裏話", "b": "「プロレスは見ていない」と口にするのは、現実か演出かを巡る議論を避けるための冗談から始まったという。やがてファンやネット記事に「今週は手を抜いた」と書かれるようになり、本人は冗談が広がりすぎたと話す。実際には一度も手を抜いたことはないという。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（18:19〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=1099s"]]}, {"cat": "WWEでの日々", "t": "受け身を控えめにして怒られた", "b": "一度だけ巡業の試合で、受け身をわざと崩して取ってみたところ、中途半端に倒れて恥ずかしい思いをしたという。もう二度とやらないと決め、どんな試合でも「10点満点の11点」を出すと話す。一方で、うまく受けすぎるなと上の人に注意されたこともあるそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（20:02〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=1202s"]]}, {"cat": "WWEでの日々", "t": "鼠径部の痛みを抱えたまま王座戦に出た", "b": "筋を痛めた時期、医師が脚を幼児用のお箸の練習具のように包帯で固定してくれたという。さらに王座ベルトの下に氷の袋を入れ、入場でベルトを外すと氷が落ちる形で試合に臨んだそうだ。反対側の脚まで痛めて注射を受けた時期もあるが、WWEの王者として痛みの中で試合を盛り上げられることを誇りに思っていたと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（43:05〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=2585s"]]}, {"cat": "WWEでの日々", "t": "受け身の見せ方を映画と格闘技から研究した", "b": "若い頃は何にでも派手に飛ぶ受け身をして、かえって特別感を薄めていたと話す。後に、見せ場は大技の直前に取っておくべきだと気づいたという。映画で悪役がやられる場面や、総合格闘技のKOの倒れ方を参考に、本当に倒されたように見せる受け身を工夫した。そのせいで本気で心配されたことが何度もあったそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（47:16〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=2836s"]]}, {"cat": "WWEでの日々", "t": "自宅にいる時間を「時間単位」で数えた日々", "b": "試合のある週末から収録まで、移動と興行が続き、自宅にいられるのは36時間ほどということが多かったという。昔は働くほど収入が増え、下位の選手は出番を増やして上の目に留まる必要があったため、結婚式なども欠席してしまったと振り返る。本人は、その点は悔やんでいると話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（52:54〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=3174s"]]}, {"cat": "WWEでの日々", "t": "最初の役柄は、新人の集団とキャディー", "b": "最初に出たのは新人ユニットの一員で、その後しばらくはシャボ・ゲレロの付き人役のキャディーだったという。エディ・ゲレロの死でその構想は消えたが、続けば半年から1年ほど、多くは深夜番組の枠で使われたと思うと話す。それでもテレビに出られること自体がうれしかったそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（56:05〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=3365s"]]}, {"cat": "WWEでの日々", "t": "伝説の選手と巡業で学んだ新人時代", "b": "新人ユニットの時期は、トリプルHやショーン・マイケルズ、リック・フレアーらと巡業で何度も対戦し、短期間で急成長できたという。ショーン・マイケルズに試合の流れの一部を任せてもらえたことは、今でも忘れられないと話す。巡業先では、深夜までトリプルHに質問をして過ごし、試合の心理を学んだそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（57:45〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=3465s"]]}, {"cat": "WWEでの日々", "t": "ブーイングで声が通らなかった夜の対応", "b": "ヴィッキー・ゲレロと組んでジョン・シナと絡んだ回では、観客のブーイングが大きく、彼女の声が届かなかったという。その場で番組の進行を変え、試合を2つのコーナーに分けることにしたそうだ。結果的に当初の短い試合より面白くなったと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:02:34〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=3754s"]]}, {"cat": "WWEでの日々", "t": "ゴールドバーグ戦で入れたスーパーキックの狙い", "b": "終了の合図直後に打つスーパーキックで観客を一度沸かせ、それでも倒される、という二段の構成を自分で提案したという。実況席にいたレネが驚いた声を出したのが、ねらいどおりだったと話す。槍のような技は毎回強烈に痛かったが、それも仕事の一部だと受け止めていたそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:08:16〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4096s"]]}, {"cat": "退団の理由", "t": "対戦相手のゴールドバーグ戦で退団を直訴", "b": "2019年の大会で、ゴールドバーグの技を受けるだけの試合を告げられたニック・ネメスは、地元の選手でもできる役だと反発したという。何かをやらせてもらえないなら会社を去るとまで言ったそうだ。結果として、終了の合図直後にスーパーキックを入れるなど、見せ場をつくる形に変えさせたと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:09:01〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4141s"]]}, {"cat": "退団の理由", "t": "2019年の退団希望は、握手の約束が覆された", "b": "2019年、ニック・ネメスは「ゴールドバーグとミズの2人を送り出してから去る」という流れの提案を受け、退団を前提に動いていたという。しかし契約は1年ほど残っており、握手で交わした約束は実現しなかった。本人は強く裏切られた気持ちになったが、ビジネスだと受け止めたと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:12:15〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4335s"]]}, {"cat": "退団の理由", "t": "指示が変わる状況に冷めていった", "b": "独立系の経験がなく、ストーリーの作り方や心理戦のすべてをビンス・マクマホンから学んだという。ところが2018年から2020年ごろは、以前に教わったことと逆の指示が出るようになり、納得できないまま従うことも増えたそうだ。小切手は入る、と割り切るような態度を取った時期もあったと、反省を込めて話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:15:28〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4528s"]]}, {"cat": "WWEでの日々", "t": "流れに乗れそうな場面で止まった悔しさ", "b": "世界王者になった直後、観客の半分は自分を悪役として見ており、悪役にも善玉にも振れる絶好の機会だったという。ところが与えられた台詞の内容が「ただ楽しませたかった」と繰り返す無難なもので、何者なのかが伝わらなかったと話す。同じ流れで、主力が欠場する中でも自分が番組に呼ばれなかった時期があり、上の人に抗議したこともあるそうだ。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:17:57〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4677s"]]}, {"cat": "WWEでの日々", "t": "観客が時計を数えた30分勝負", "b": "2018年の大会で、セス・ロリンズと王座をかけた時間制限の長丁場を行い、メインイベントに押し込んだという。ところが開始数分で観客が残り時間のカウントダウンを始め、画面から時計を消すと10秒ごとの合唱になって、試合に集中してもらえなかったと振り返る。本人は、いつもの出来ではなかったと話す。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Zwl8FNvjTHs", "src": [["番組のYouTube（1:19:32〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=4772s"]]}]);
  if (PROFILES["The Miz"]) PROFILES["The Miz"].facts.push({"cat": "暮らし", "t": "ミズは15年かけて評価が追いついた", "b": "ミズは長年、実力を疑われながらも努力を続け、ようやく周囲に認められたと、ニック・ネメスが話している。自分たちの仲間うちでは、外でも通用する何かを見つけようと競い合っていたという。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で、ニック・ネメスの話（字幕を全文確認）", "src": [["番組のYouTube（35:16〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=2116s"]], "by": "第三者の話"});
  if (PROFILES["Zack Ryder"]) PROFILES["Zack Ryder"].facts.push({"cat": "暮らし", "t": "ザック・ライダーの番組が契約の条件に", "b": "WWEが動画サイトと契約を結ぶ際、ザック・ライダーの番組を入れることが条件の一つだったと、ニック・ネメスが話している。1人の努力が会社の大きな取引に影響した例として挙げている。", "sp": "ニック・ネメス", "d": "2025-10-09", "how": "クリス・ヴァン・ヴリートの番組で、ニック・ネメスの話（字幕を全文確認）", "src": [["番組のYouTube（36:01〜）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs&t=2161s"]], "by": "第三者の話"});
