  ARTICLES.push({ id: "ext-Zwl8FNvjTHs", d: "2025-10-09", show: "ext", who: ["Nic Nemeth"], t: "ニック・ネメスの回　WWEを去った理由と、20年の思い出", lead: "クリス・ヴァン・ヴリートの番組に出た約92分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nic Nemeth"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Zwl8FNvjTHs").map((x) => [x.t, x.b, x.sp])), open: ["他団体での活動、WWEとの提携の話、本人の暮らしや家族の話は公開項目に含めていない。", "字幕は自動生成のため、一部の人名や場面の前後関係が崩れている箇所がある。確信の持てない名前は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Zwl8FNvjTHs"]] });
  if (!ROSTER.find((r) => r[1] === "Big E")) ROSTER.push(["ビッグE", "Big E", "lg", "元WWE王者", "", "", ""]);
  if (!PROFILES["Big E"]) PROFILES["Big E"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Big%20E"]], moves: [], facts: [] };
  if (PROFILES["Big E"].lead === "") PROFILES["Big E"]._weak = 1;
  PROFILES["Big E"].facts.push(...[{"cat": "リングの話", "t": "最初の個性は「フロリダ最強の男」", "b": "育成団体の時代、ビッグEは自分のキャラクターがまだ定まっていなかったという。そこでパワーリフティングの大会に出た経験を生かし、「フロリダ最強の男」という設定で戦っていたそうだ。ビッグE自身は、これが自分にとって最初の個性になったと話している。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（39:19〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2359s"]]}, {"cat": "リングの話", "t": "ジョン・シナのジムで挑んだ記録挑戦", "b": "ビッグEはまだ無名だった頃、ジョン・シナのジムでベンチプレス575ポンドの自己記録に挑んだという。シナの密着ドキュメンタリーの撮影中で、成功すれば映像に使うと約束され、ローマン・レインズが補助についたそうだ。後にトップスターになる面々が周りで応援してくれた、今も誇れる思い出だと話している。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（40:07〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2407s"]]}, {"cat": "リングの話", "t": "真面目な役では観客に届かなかった", "b": "ビッグEは、デビュー当初は真面目な人物を演じようとしたが、観客の心をつかめなかったと話す。下部団体でダスティ・ローデスから、キング・コング・バンディがやっていたカウント芸を勧められ、これが人気を呼んだという。ただしそれは一軍では使えず、ドルフらとの時期を経ても、自分の持ち味はまだ見つからなかったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（59:58〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3598s"]]}, {"cat": "リングの話", "t": "悪役だからこそ自由に試せた", "b": "ビッグEは、悪役は観客に好かれようと気を使わなくてよいぶん、おどけたり図々しくなったりできたと話す。ニュー・デイは2015年ごろから、トロンボーンを持ち出すような突飛なことを次々に試したという。うまくいくこともいかないこともあったが、「自分も創造的でいい」と気づく転機になったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:00:48〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3648s"]]}, {"cat": "リングの話", "t": "悪役なのにブーイングされなかった", "b": "ビッグEは、ニュー・デイは下手な悪役だったと笑う。ほとんどブーイングを受けず、風向きが変わるとすぐ観客が味方についたという。楽しさが伝わったからで、善玉に転じてからも同じ発想で続けたそうだ。ふたりの仲間が自分のアイデアを信頼してくれたことが大きな自信になったと話している。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:02:20〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3740s"]]}, {"cat": "リングの話", "t": "シリアル「ブーティーオーズ」の誕生", "b": "ビッグEによると、ファンが掲げたシリアルの箱の看板を見て、自分たちならどんなシリアルかと考えたのが始まりだという。死語になっていた「ブーティー」という言葉をあえて復活させ、コフィとウッズが別々に同じ名前を挙げたそうだ。制作部門が出した最初の箱のデザインは修正なしでそのまま採用されたと、感謝を語っている。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:03:07〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3787s"]]}, {"cat": "リングの話", "t": "唯一無二を目指した記録的なタッグ王座", "b": "ビッグEは、誰よりも強くなくていいから、ほかにない存在になりたかったと話す。クビを避けようとしていた3人が、デモリッションが20年以上保っていた記録を破り、483日間タッグ王座を保持したことを振り返る。ザ・ロックとのマイクの場面やシナとのシングルマッチ、シリアルまで経験できたと驚いているそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:03:53〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3833s"]]}, {"cat": "リングの話", "t": "コフィマニアに込めた思い", "b": "ビッグEは、コフィが11年も一軍にいながら世界王座戦を一度も戦っていなかったと話す。文句を言わず、常に誠実な仕事ぶりのコフィを、ウッズと自分は「最高の存在」と呼んでいたという。ムスタファ・アリの負傷で代役に入ったコフィが一気に勢いをつけ、観客が押し上げたことを、作り物ではない本物の瞬間だったと語っている。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:05:27〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3927s"]]}, {"cat": "リングの話", "t": "大舞台でコフィが王座を獲った日", "b": "ビッグEは、コフィが年間最大の祭典でダニエル・ブライアンから王座を奪ったのは、同じように地道に歩んだ者同士の勝利だったと話す。コフィの家族がリングで祝い、ウッズが涙を流した姿が忘れられないそうだ。6年後に同じ会場の近くを訪れ、感慨深いと語っている。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:07:06〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=4026s"]]}, {"cat": "リングの話", "t": "3人の絆を描いたユニットの物語", "b": "ビッグEは、ユニットなら仲間割れが定番なのに、ニュー・デイは兄弟愛を描きたかったと話す。コフィにチャンスを与えるため、ウッズとふたりで1時間のガントレット戦を戦った経験もあるそうだ。リーダーは作らず3人が対等という方針を守り、ポップカルチャーへの愛もギアや入場に反映したという。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:08:40〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=4120s"]]}]);
  if (!PROFILES["Big E"]) PROFILES["Big E"] = { lead: "幼いころからうつと向き合い、カウンセリングと毎日の瞑想で自分を取り戻してきたビッグE。「人の一日を少しでも軽くしたい」と語る、やさしさの人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Big%20E"]], moves: [], facts: [] };
  if (PROFILES["Big E"]._weak) { PROFILES["Big E"].lead = "幼いころからうつと向き合い、カウンセリングと毎日の瞑想で自分を取り戻してきたビッグE。「人の一日を少しでも軽くしたい」と語る、やさしさの人だ。"; delete PROFILES["Big E"]._weak; }
  PROFILES["Big E"].facts.push(...[{"cat": "家族", "t": "荒れた家庭が「優しさ」の原点", "b": "何より大事にしているのは人への接し方だという。父のせいで家の空気が張りつめ、母や姉妹が消耗していくのを見て育ったため、幼いころから「あんな人にはならない」と決めていたそうだ。人とのつながりこそが自分の生きる理由だと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:33〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=93s"]]}, {"cat": "家族", "t": "何代も続いた連鎖を自分で断つ", "b": "父はジャマイカ育ちで、その父親から日常的に手を上げられていたという。こうした痛みは何世代も続いてきたのかもしれないと考え、自分の代で終わらせると決めたと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（4:40〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=280s"]]}, {"cat": "体のこと", "t": "9歳で始まったうつの記憶", "b": "うつに苦しんだ最初の記憶は9歳のとき。鏡の前で泣きながら「自分以外の誰かになりたい」と思っていたという。親から否定的な言葉を受け続けたことが自己嫌悪の根になり、それをほどくのに長い時間がかかったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（5:27〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=327s"]]}, {"cat": "家族", "t": "母に抱かれた、やわらかな記憶", "b": "幼いころには、母の腕の中で守られていた温かな瞬間も覚えているという。母も家の中で自分を守るために流されるしかなかったのだと理解しており、母の犠牲には今も感謝していると話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（7:53〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=473s"]]}, {"cat": "リングに来るまで", "t": "姉妹とともに私立の進学校へ", "b": "母が多くを犠牲にして、姉妹と一緒に私立の進学校に通わせてくれたという。中流家庭で食べるものに困ったこともなく、教育にも恵まれたと感謝する一方、「その学歴でプロレスラーになった」と笑う。外泊なども許されない、外の影響の少ない家庭だったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（11:10〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=670s"]]}, {"cat": "リングに来るまで", "t": "奨学金でアイオワ大へ、直後に膝の大けが", "b": "高校でアメフトをしたのは1年だけだったが、土壇場でアイオワ大学から奨学金の誘いを受けた。1年目から試合に出られると告げられた矢先、18歳で左膝の前十字靭帯を断裂。アメフトこそが最初の夢だったという。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（12:46〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=766s"]]}, {"cat": "リングに来るまで", "t": "けがの連続でアメフトの夢が終わる", "b": "9か月のリハビリを経て復帰目前で今度は反対の膝も断裂。その後も胸の筋肉を痛め、ようやく試合に出た年には膝の皿を骨折した。21歳を前に医療上の理由で競技を退き、奨学生として学業だけを続けたそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（14:23〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=863s"]]}, {"cat": "体のこと", "t": "コーチに背中を押され19歳でカウンセリングへ", "b": "「男は気持ちを口にしない」家庭で育ち、内気な性格もあって相談など考えもしなかった。異変に気づいたディフェンスラインのコーチがほぼ強制的にカウンセラーのもとへ行かせ、最初は心を開けなかったが、毎週通ううちに話せるようになったという。そのカウンセラーは家族のような存在だったと振り返る。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（15:14〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=914s"]]}, {"cat": "体のこと", "t": "重いうつと診断され、長く服薬", "b": "19歳で、幻覚などの症状を伴う重度のうつ病と診断されたという。抗うつ薬や抗精神病薬を何年も飲み、合う薬を探して試行錯誤を続けた。19〜23歳がいちばんつらい時期だったと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（16:00〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=960s"]]}, {"cat": "体のこと", "t": "自ら申し出て大学病院の精神科病棟へ", "b": "主治医から「本当に危ないと思ったら知らせて」と言われていた言葉に従い、自分から申し出て入院した。2007年ごろ、およそ1か月を病棟で過ごしたという。長いあいだ、この経験を恥じて誰にも話せなかったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（16:49〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=1009s"]]}, {"cat": "体のこと", "t": "成功しても消えなかった心の穴", "b": "プロレスは生きる目的をくれたが、自分への見方までは変えてくれなかったという。ニュー・デイで親友2人と最高の時間を過ごしていた時期でさえ、うつの波は繰り返し訪れていたと明かす。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（20:56〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=1256s"]]}, {"cat": "暮らし", "t": "コロナ禍に始めた毎日10分の瞑想", "b": "2019年に知人から瞑想アプリを教わったが、早朝便などを理由に続かなかった。一人暮らしで家にこもることになったコロナ禍に「このままでは危ない」と感じ、毎日10分の瞑想を始めたという。数か月続けるうちに、以前なら落ち込んでいた場面でも心が揺れなくなったと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（22:31〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=1351s"]]}, {"cat": "好きなもの", "t": "首の骨折後に届いたサインフェルドのレゴ", "b": "首を骨折したとき、まず感じたのは失ったものではなく、まひが残らなかったことや支えてくれる人への感謝だったという。一番好きな番組は「となりのサインフェルド」で、見舞いにムスタファ・アリから主人公の部屋を再現したレゴセットが届き、毎朝わくわくしながら組み立てたそうだ。瞑想についての本も数多く届いたと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（25:00〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=1500s"]]}, {"cat": "暮らし", "t": "今も毎朝瞑想、歩数を数えて心を戻す", "b": "瞑想は今も毎朝の日課で、早い便の日は時間をずらしてでも必ずやるという。「体が強くなっても筋トレをやめないのと同じ」と考えているそうだ。不安が強いときは歩数を数えるなど、今この瞬間に意識を戻す工夫をしている。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（32:08〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=1928s"]]}, {"cat": "体のこと", "t": "10歳で父のバーベル、17歳でベンチ400ポンド", "b": "10歳ごろ父がくれた古いバーベルでカールをしたのが始まりで、本格的な筋トレは12歳から。17歳でベンチプレス約181キロを挙げたという。筋肉増強剤を疑われたこともあるが一度も使っておらず、14歳でスーパーのアルバイトを始めたときから検査も受けてきたと話す。力の強さは父譲りだそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（36:59〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2219s"]]}, {"cat": "リングに来るまで", "t": "入団後はパワーリフティングで頭角", "b": "2009年に契約し、翌年ごろから育成組がジョン・シナのジムで練習するようになった。そこの指導者に勧められてパワーリフティングの大会に出場し、全米大会にも挑んだ。体重を増やすため冷凍ピザを丸ごと食べ、約116キロから約134キロまで増量、スクワットは約340キロを挙げたという。「フロリダ最強の男」が最初のキャラクターだったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（38:34〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2314s"]]}, {"cat": "リングに来るまで", "t": "自己ベストの瞬間を補助したのはロマン", "b": "シナのドキュメンタリーの撮影中、成功すれば作品に入れると言われ、自己ベストとなるベンチプレス約261キロに挑んで成功した。補助についていたのはまだテレビデビュー前のローマン・レインズで、今見返しても胸が熱くなるという。ジムは今も自分のオアシスだと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（40:54〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2454s"]]}, {"cat": "家族", "t": "婚約者はミチンの妹", "b": "婚約者は同僚ミチンの妹で、先にSNSで連絡をくれたのは彼女だったという。業界内の恋愛、ましてや同僚の妹とは付き合わないと決めていたそうだ。ロサンゼルスでの年間最大の祭典の際に初めて会い、そのときハグしたホテルが二人の思い出の場所になった。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（43:19〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2599s"]]}, {"cat": "家族", "t": "仲間の番組の試写会で恋に落ちる", "b": "2024年初め、地元フロリダでの大会の時期に誘い、モンテス・フォードとビアンカ・ブレア夫妻のリアリティ番組の試写会で隣に座った。彼女の笑い声に心を奪われたという。その後はビデオ通話が30分のつもりが毎回5時間になったそうだ。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（44:54〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2694s"]]}, {"cat": "家族", "t": "家庭を避けてきた二人が数週間で結婚を決意", "b": "父のようになることを恐れ、家庭を持つことからずっと逃げてきたという。互いに一人でいるのが平気な二人だったが、付き合って1か月もたたないうちに結婚したいと分かったそうだ。今は二人きりで過ごす週末を大切にしていると話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（50:27〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3027s"]]}, {"cat": "好きなもの", "t": "地元タンパのアメフトチームを応援", "b": "子どものころから地元タンパのプロアメフトチームと、フロリダ州立大のチームの大ファン。両方で活躍し、勉強を頑張った子どもたちを旅行に連れていくなど地域に尽くした選手に憧れていたという。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（54:17〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3257s"]]}, {"cat": "体のこと", "t": "「10年後は橋の下」と答えた大学時代", "b": "大学のカウンセラーに10年後の自分を聞かれ、本気で「生きていれば橋の下で暮らしている」と答えたという。劇的な転機はなく、治療を続けるうちに少しずつ扱えるようになったそうだ。カウンセリングは魔法ではないが、続ければ良くなると伝えたいと話す。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xV0dfgEv_uo", "src": [["公式YouTube（1:13:42〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=4422s"]]}]);
  if (PROFILES["The Boogeyman"]) PROFILES["The Boogeyman"].facts.push({"cat": "暮らし", "t": "大学時代のコーチが同じだった", "b": "ブギーマンは、自分を支えてくれた大学のディフェンスラインのコーチに、小さな大学時代に教わっていたと後で知り、世間の狭さに驚いたと、ビッグEが話している。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で、ビッグEの話（公式字幕を全文確認）", "src": [["公式YouTube（14:23〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=863s"]], "by": "第三者の話"});
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "大学時代から知っていた存在", "b": "ローマン・レインズのことは、プロレス入り前から同世代の有望なディフェンスラインの選手として大学時代の活躍を追っていたと、ビッグEが話している。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で、ビッグEの話（公式字幕を全文確認）", "src": [["公式YouTube（41:44〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=2504s"]], "by": "第三者の話"});
  if (PROFILES["Kofi Kingston"]) PROFILES["Kofi Kingston"].facts.push({"cat": "暮らし", "t": "仲間が「最高の男」と呼ぶ理由", "b": "コフィ・キングストンはいつも笑顔で、どんな取材もこなし、文句を言わず正しいやり方を貫いてきた、業界で最も尊敬される人の一人だと、ビッグEが話している。王座を取った瞬間、エグゼビア・ウッズは涙が止まらなかったという。", "sp": "ビッグE", "d": "2025-10-09", "how": "ステファニーの番組で、ビッグEの話（公式字幕を全文確認）", "src": [["公式YouTube（1:05:27〜）", "https://www.youtube.com/watch?v=xV0dfgEv_uo&t=3927s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-xV0dfgEv_uo", d: "2025-10-09", show: "wys", who: ["Big E"], t: "ビッグEの回　うつとの長い道のり、瞑想、怪力の原点、婚約者との出会い", lead: "ステファニー・マクマホンの番組に出た約82分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Big E"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-xV0dfgEv_uo").map((x) => [x.t, x.b, x.sp])), open: ["字幕の話者ラベルが後半で入れ替わっており、聞き手との掛け合いは文脈で判断した。判断がつかない短いやりとりは省いた。", "父の暴力や希死念慮に関する話は要点だけにとどめ、婚約者や恩人など一般の方の実名は伏せた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=xV0dfgEv_uo"]] });
  if (!ROSTER.find((r) => r[1] === "Montez Ford")) ROSTER.push(["モンテス・フォード", "Montez Ford", "lg", "", "", "", ""]);
  if (!PROFILES["Montez Ford"]) PROFILES["Montez Ford"] = { lead: "妻のビアンカと並んで出演し、夫婦のなれそめや日常をゆるく語った回。素顔の暮らしぶりと、冷静で少しマイペースな人柄が見える。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Montez%20Ford"]], moves: [], facts: [] };
  if (PROFILES["Montez Ford"]._weak) { PROFILES["Montez Ford"].lead = "妻のビアンカと並んで出演し、夫婦のなれそめや日常をゆるく語った回。素顔の暮らしぶりと、冷静で少しマイペースな人柄が見える。"; delete PROFILES["Montez Ford"]._weak; }
  PROFILES["Montez Ford"].facts.push(...[{"cat": "暮らし", "t": "本名ケネス・クロフォードで自己紹介", "b": "番組冒頭で、WWEでのリングネームとは別に「ケネス・クロフォード」と名乗ったという。妻のビアンカは普段から彼を「ケン」と呼んでいて、共演者もそれに合わせている。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=143s"]]}, {"cat": "リングに来るまで", "t": "育成時代はダウキンスと同室だった", "b": "育成施設にいた頃、遠征先のホテルでは男女で部屋が分けられ、モンテスはタッグ相手のダウキンスと同じ部屋だったという。ビアンカがよく部屋に入りびたっていて、ダウキンスがあきれていたそうだ。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（6:26〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=386s"]]}, {"cat": "家族", "t": "交際は周囲に伏せていた時期があった", "b": "育成時代、ビアンカとの関係は公表前で、まわりに話さないよう気をつけていたという。同じころ仲間の交際も知っていて、自分たちも経験したから言いふらさなかったと話す。早い時期に結婚し、その後は同じ部屋になれたそうだ。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（8:52〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=532s"]]}, {"cat": "体のこと", "t": "ビタミンD不足で日光浴をしている", "b": "ビタミンDが足りないと話し、家の外のデイベッドで日光浴をしているという。ビアンカによると、朝起きて姿が見えず、家中を探すとそこで寝ころんでいることがよくあるそうだ。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（9:46〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=586s"]]}, {"cat": "体のこと", "t": "テレビ映えのために肌の色にこだわる", "b": "肌が濃いほどテレビでは体の線がはっきり見えると考えているという。体を大きくする時期にファイブガイズやマルコズ・ピザを食べると、締まりが甘く見える週もあるそうだ。朝にパウダーをつけて、照明での照り返しを抑える工夫もしている。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（10:33〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=633s"]]}, {"cat": "体のこと", "t": "体を大きくする時期は暑くていびきが出る", "b": "増量中は体が熱くなり、軽い睡眠時無呼吸があっていびきをかくと話す。ビアンカは寝室の温度をかなり低くして掛け布団を取っていくので、寝ている間の布団の取り合いが夫婦の定番だという。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=726s"]]}, {"cat": "好きなもの", "t": "夫婦の定番曲はダニエル・シーザーの曲", "b": "二人の曲を聞かれて、ダニエル・シーザーの「Get You」を挙げた。歌はビアンカのほうが上手だと思うと話している。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（12:57〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=777s"]]}, {"cat": "暮らし", "t": "質問にはじっくり考えてから答える", "b": "ビアンカが何層にも重なった質問をするのに対し、モンテスは答えを考えているうちに時間がたってしまうという。一度は黙っていて、機嫌が悪いと思われたこともあるそうだ。二人は性格が正反対だと話している。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（21:56〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=1316s"]]}, {"cat": "暮らし", "t": "ストレスの中でも落ち着いている", "b": "ビアンカいわく、モンテスはテレビではテンション高く見えるのに、大変な場面では冷静なタイプだという。本人も、周りから同じことをよく言われると話す。ゾンビの話題では、自分のほうが長く生き残ると答えていた。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（22:41〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=1361s"]]}, {"cat": "暮らし", "t": "スマホの充電を気にしない", "b": "自分は携帯をほとんど充電せず、遠出の途中で電池が切れて終わりだと思うタイプだと話す。ビアンカはバッグにモバイルバッテリーを7個入れていて、彼がそれを借りることもあるそうだ。", "sp": "モンテス・フォード", "d": "2025-10-10", "how": "ゼルヴェックスとチャーリー・ガールの番組で（字幕を全文確認）", "art": "ext-W_xk8IKj6HU", "src": [["番組のYouTube（31:06〜）", "https://www.youtube.com/watch?v=W_xk8IKj6HU&t=1866s"]]}]);
  ARTICLES.push({ id: "ext-W_xk8IKj6HU", d: "2025-10-10", show: "ext", who: ["Montez Ford"], t: "モンテス・フォードの回　妻と一緒に語る素顔と夫婦の日常", lead: "ゼルヴェックスとチャーリー・ガールの番組に出た約42分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Montez Ford"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-W_xk8IKj6HU").map((x) => [x.t, x.b, x.sp])), open: ["モンテスとビアンカが同時に出演しており、字幕に話者名がないため、どちらの発言か判断できない箇所は載せていない（結婚式やポケモン、ゾンビ対策の準備の話など）。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=W_xk8IKj6HU"]] });
  if (!ROSTER.find((r) => r[1] === "Iyo Sky")) ROSTER.push(["イヨ・スカイ", "Iyo Sky", "lg", "日本出身の女子王者", "", "", ""]);
  if (!PROFILES["Iyo Sky"]) PROFILES["Iyo Sky"] = { lead: "プロレスを知らないまま姉に誘われて16歳でデビューした、イヨ・スカイ。悔しさをバネに続けた18年が、いまの試合の質につながっているそうだ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Iyo%20Sky"]], moves: [], facts: [] };
  if (PROFILES["Iyo Sky"]._weak) { PROFILES["Iyo Sky"].lead = "プロレスを知らないまま姉に誘われて16歳でデビューした、イヨ・スカイ。悔しさをバネに続けた18年が、いまの試合の質につながっているそうだ。"; delete PROFILES["Iyo Sky"]._weak; }
  PROFILES["Iyo Sky"].facts.push(...[{"cat": "暮らし", "t": "2018年に渡米、英語は独学まじり", "b": "2018年に日本からアメリカへ移り、7年以上たつという。契約後に週1〜2回、30分から1時間ほど英語教室に通ったが、基本は現場で覚えたそうだ。学校では書くことと文法が中心で、話す練習は少なかったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=143s"]]}, {"cat": "暮らし", "t": "カメラの前の英語は今も緊張する", "b": "普段の会話なら多少崩れた英語でも通じるが、テレビではきちんとした英語を覚えて話す必要があるという。画面の向こうには子どもたちも多いので、言葉づかいには気をつけているそうだ。短いセリフでも緊張すると話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=238s"]]}, {"cat": "暮らし", "t": "同郷の選手とは英語まじりで会話", "b": "同じ日本出身のステファニー・バッケルとは、舞台裏で少し日本語を使うが、ほとんどは英語だという。お互い英語が母語ではないので、同じくらいのレベルで話しやすいそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（4:48〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=288s"]]}, {"cat": "リングに来るまで", "t": "プロレスを知らずに姉と道場へ", "b": "イヨ・スカイは、デビュー前にプロレスを一度も観たことがなかったという。3歳上の姉に誘われ、運動のつもりで姉と一緒に道場へ行ったのが始まりだそうだ。わずか3か月の練習でリングに立つことになったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=338s"]]}, {"cat": "リングに来るまで", "t": "16歳、ルールも知らぬまま初陣", "b": "デビュー戦は高校生になったばかりの16歳のときで、肩をマットにつけて3カウントという基本ルールすら知らなかったという。出来は散々で、観客は30人ほどだったそうだ。当時を思い出すと今でも恥ずかしいと話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（6:30〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=390s"]]}, {"cat": "リングに来るまで", "t": "辞めたい気持ちを悔しさで押し返す", "b": "デビュー戦のあとは辞めたいと思ったが、同じくらい悔しかったという。30人の前で見せた下手な試合を、自分の力で塗り替えたかったそうだ。姉の存在も支えになり、続けるうちに3年ほどでプロレスが好きになったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（7:20〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=440s"]]}, {"cat": "リングの話", "t": "年間最大の祭典の三つ巴戦は特別な一戦", "b": "今年の年間最大の祭典で戦った三つ巴戦が、自分にとって特別な試合だという。日本の女子レスラーとして初めて祭典で勝ったことになり、日本の人たちにとっても大きな意味があったと話す。王者として入場し王者のまま退場できたのは、自分でも予想外だったそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（8:58〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=538s"]]}, {"cat": "家族", "t": "祭典での勝利に両親が涙", "b": "年間最大の祭典の三つ巴戦で王座を守った場面には、家族が会場にいたという。3カウントを奪った瞬間、両親が泣いていたと話す。あとで映像を見て、自分も泣きそうになったそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（9:49〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=589s"]]}, {"cat": "リングの話", "t": "契約書のバク宙は偶然の見せ場", "b": "その試合の調印式では、相手の背中を蹴ってバク宙で降り、そのまま署名した。聞き手はこれまで見た中で最高の調印かもしれないと褒めたが、本人は冗談まじりに、さらっとやっただけと笑っていた。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（10:35〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=635s"]]}, {"cat": "リングの話", "t": "マイクが苦手でも強みは試合", "b": "英語が母語ではなく、マイクで他の選手に及ばない面があると自覚しているという。だからこそ自分の強みは試合だと決め、昨日の自分より良い試合を毎回目指していると話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（12:10〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=730s"]]}, {"cat": "リングの話", "t": "過去の試合を見返して次に生かす", "b": "次の試合の前には、これまでの相手との試合を見返すという。そこに何か一つ足して、前回より特別な試合にしたいと考えているそうだ。このやり方で試合の質が上がってきたと話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（13:06〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=786s"]]}, {"cat": "リングに来るまで", "t": "日本で賞を重ねたあとにWWEから声", "b": "WWEと契約した頃は、日本の団体で多くの王座を腰に巻き、賞も数多く受けていたという。外国人選手と食事に行くなどして交流し、WWEで戦うのが夢だと周りに話していたそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（14:50〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=890s"]]}, {"cat": "リングに来るまで", "t": "夢を後押しした元レスラーの一言", "b": "引退してWWEのコーチかプロデューサーになった元同僚から、WWEに興味があるかとメッセージが届いたという。最初は軽い雑談だと思ったが、その人が話を進めてくれたそうだ。当時開かれていた女子の大型トーナメントにも関わるタイミングだったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（16:23〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=983s"]]}, {"cat": "体のこと", "t": "足首の負傷明けに一軍へ呼ばれた", "b": "一軍に呼ばれた頃は、足首を骨折して休み、ほぼ回復したところだったという。そこへ統括の責任者から、準備はできているかと電話があったそうだ。まったく予想していなかったので驚いたと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（17:57〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1077s"]]}, {"cat": "リングの話", "t": "新名義は5日で決めた", "b": "一軍に上がる直前に、新しいリングネームを考えるよう言われたが、期間は5日もなかったという。紫雷という以前の名前から離れ、聞けばすぐ思い浮かぶ言葉として空を選んだそうだ。覚えやすくて忘れられない名前にしたかったと話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（17:57〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1077s"]]}, {"cat": "リングの話", "t": "月面宙返りは外に飛ぶのが特徴", "b": "自分の月面宙返りは、上に跳ぶのではなく後ろへ大きく距離を取るのが特徴だという。相手がロープをつかんで技を避けるのを防ぐため、リングの中央に相手を置いて外へ飛ぶそうだ。狙いのある使い方だと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（21:14〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1274s"]]}, {"cat": "体のこと", "t": "足首を痛めて月面宙返りを封印", "b": "4年ほど前、育成ブランドの大会でリング外への月面宙返りを放ち、実況席に足の指を強くぶつけたという。足が完全に折れたと思うほどの痛みで、人生で一番痛かったと話す。以来、着地で踏みつける型は危ないのでやらないそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（23:46〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1426s"]]}, {"cat": "リングの話", "t": "手錠の案は統括責任者のひらめき", "b": "ブリーフケースを賭けた試合で、手錠を使って相手をつなぐアイデアは、統括の責任者が出したものだという。ほかの選手を拘束している間に、ケースへ手を伸ばす流れがうまくいったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（26:19〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1579s"]]}, {"cat": "リングの話", "t": "権利行使の成功は夢がかなった瞬間", "b": "ブリーフケースの権利を使って王座を奪ったことは、夢がかなったような出来事だったという。それまでの権利行使は失敗が少ないと言われていて、自分が最初の失敗になるかもしれないと不安だったそうだ。結果は成功で、とてもうれしかったと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（27:08〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1628s"]]}, {"cat": "リングの話", "t": "ごみ箱を使った技の練習秘話", "b": "集団戦で毎回新しい見せ場を作ろうとして、ごみ箱をかぶせた月面宙返りを思いついたという。練習施設で普通のごみ箱の中身を片づけ、人目につかないように頭にかぶって試したそうだ。まず高さの低いロープから成功させたと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（28:41〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1721s"]]}, {"cat": "リングの話", "t": "ケージからの跳躍は怖くて動けなかった", "b": "集団戦でごみ箱をかぶってケージから飛んだ一回目は、実は練習せずに本番を迎えたという。ごみ箱の中が真っ暗で何も見えず、立ったまま怖くて動けなくなったそうだ。それでも、カメラが回っているのでやるしかないと思い切ったと話している。二回目は落ち着いてできたそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（31:53〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1913s"]]}, {"cat": "リングの話", "t": "リア・リプリーとは正反対だから合う", "b": "リア・リプリーとは育成ブランドの頃から戦っていて、相性が良いと感じているという。リアは背が高く力強くてかっこよく、自分は小柄で素早くて飛ぶタイプなので、正反対のところが組み合わせのよさにつながっていると話す。会話をしていても、ファンのような気持ちになることがあるそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（32:46〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1966s"]]}, {"cat": "暮らし", "t": "恋しいのは日本のコンビニ", "b": "日本で恋しいのは日本風のプロレスと、コンビニの便利さだという。24時間開いていて、新鮮なケーキやプリン、調理済みの食事まで買えるのが日本の良さだと熱く語った。アメリカのコンビニとは全然違うと話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（36:41〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2201s"]]}, {"cat": "家族", "t": "家族は日本にいて、大舞台に招待", "b": "家族は今も日本にいて、会えないのはさみしいという。年間最大の祭典に家族を招待したこともあり、ときどき会場に来てくれるそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（37:28〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2248s"]]}, {"cat": "リングの話", "t": "自分を指さすポーズが観客を巻き込んだ", "b": "自分を指さす決めポーズは、最初は小さな動きだったという。繰り返すうちに観客の反応が大きくなり、いまの大きな形になったそうだ。観客も一緒に自分を指さしてくれたらうれしいと話しているが、名前はまだついていない。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（39:53〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2393s"]]}, {"cat": "暮らし", "t": "夢はいまも日本語、ときどき英語", "b": "夢を見るときは基本的に日本語だが、最近は英語で言い争う夢を見ることもあるという。英語で考える時間が増えている証拠かもしれないと、笑いながら話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（42:18〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2538s"]]}, {"cat": "体のこと", "t": "丈夫な体は家族からの贈り物", "b": "感謝していることの一つに家族を挙げ、よく眠れない日や忙しい日が続いても健康でいられるのは、両親と祖父母のおかげだと話す。自分の体は祖父母や両親から受け継いだものだという。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（43:07〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2587s"]]}, {"cat": "好きなもの", "t": "日本に猫が2匹、名前はマスクマンから", "b": "大の猫好きで、日本に2匹の猫がいるという。オスは覆面レスラーのサントにちなんだ名前、メスはルチャの先人にちなんだリオという名前だそうだ。どちらもルチャ・ドールの文化から取ったと話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（43:54〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2634s"]]}, {"cat": "好きなもの", "t": "趣味は睡眠とアイスクリーム", "b": "レスリング以外の趣味を聞かれると、トレーニングのほかには特に思いつかず、新しい趣味を探している最中だという。好きなことは寝ることで、アイスクリームを食べると幸せになると話す。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（44:42〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2682s"]]}, {"cat": "好きなもの", "t": "好きな味はチョコミント", "b": "アイスクリームではチョコミントが一番だという。アメリカ人が生のクッキー生地を食べることが不思議で、焼いてから食べればいいのにと笑った。今度試してみると約束していた。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（45:31〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2731s"]]}, {"cat": "好きなもの", "t": "好物は和食、そしてバナナのパンケーキ", "b": "好きな食べ物はまず日本食で、次にアメリカ風のパンケーキだという。特に好きなのは、バナナとホイップクリームを乗せたパンケーキだと話している。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2jDWvh9_tk8", "src": [["番組のYouTube（46:23〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2783s"]]}]);
  if (PROFILES["Stephanie Vaquer"]) PROFILES["Stephanie Vaquer"].facts.push({"cat": "暮らし", "t": "英語より日本語が上手いという評判", "b": "ステファニー・バッケルは日本語がとても上手で、かわいい話し方だと、イヨ・スカイが話している。舞台裏では日本語を少し使うが、ほとんどは英語で会話しているそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で、イヨ・スカイの話（字幕を全文確認）", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=238s"]], "by": "第三者の話"});
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "リア・リプリーは誰より格好いい", "b": "リア・リプリーは背が高く、筋肉質で、普段の会話でも格好よく見えると、イヨ・スカイが話している。自分は力強い彼女と違って、小さくて素早く飛ぶタイプだという。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で、イヨ・スカイの話（字幕を全文確認）", "src": [["番組のYouTube（32:46〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=1966s"]], "by": "第三者の話"});
  if (PROFILES["Asuka"]) PROFILES["Asuka"].facts.push({"cat": "暮らし", "t": "アスカとの金曜の主役級の一戦", "b": "アスカとは、日本人の女子選手が2人で金曜の番組のメインを務めた試合で戦ったと、イヨ・スカイが話している。15分を超える長い試合で、とても楽しかったそうだ。", "sp": "イヨ・スカイ", "d": "2025-10-14", "how": "クリス・ヴァン・ヴリートの番組で、イヨ・スカイの話（字幕を全文確認）", "src": [["番組のYouTube（35:10〜）", "https://www.youtube.com/watch?v=2jDWvh9_tk8&t=2110s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-2jDWvh9_tk8", d: "2025-10-14", show: "ext", who: ["Iyo Sky"], t: "イヨ・スカイの回　姉の誘いで始めたレスラー人生と、猫とアイスクリームの素顔", lead: "クリス・ヴァン・ヴリートの番組に出た約47分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Iyo Sky"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-2jDWvh9_tk8").map((x) => [x.t, x.b, x.sp])), open: ["対戦してみたい相手としてアレクサ・ブリスとベッキー・リンチを挙げていたが、今後の対戦の話題なので載せていない。", "字幕の自動認識で名前が崩れている箇所があり、日本の団体でWWEを勧めた元選手の名前は、確信が持てないため書いていない。", "番組後半の感謝の話では、家族とファンへの思いを中心にまとめた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=2jDWvh9_tk8"]] });
