  if (!PROFILES["Peter Rosenberg"]) PROFILES["Peter Rosenberg"] = { lead: "ニューヨークのヒップホップ局とESPNで働きながら、WWEの大会前番組の顔になったピーター・ローゼンバーグ。少年時代に好きになったラジオ、ヒップホップ、プロレスを全部仕事にした人。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Peter%20Rosenberg"]], moves: [], facts: [] };
  if (PROFILES["Peter Rosenberg"]._weak) { PROFILES["Peter Rosenberg"].lead = "ニューヨークのヒップホップ局とESPNで働きながら、WWEの大会前番組の顔になったピーター・ローゼンバーグ。少年時代に好きになったラジオ、ヒップホップ、プロレスを全部仕事にした人。"; delete PROFILES["Peter Rosenberg"]._weak; }
  PROFILES["Peter Rosenberg"].facts.push(...[{"cat": "リングに来るまで", "t": "ヒップホップ局の朝番組で選手を呼び続けた", "b": "2007年にニューヨークのラジオ局ホット97に入ってから、選手の出演を自分から積極的に受け入れてきたと、ローゼンバーグは話す。当時は朝の情報番組に出ること自体に大きな宣伝効果があり、WWEにとって地元の味方のような存在になったという。ここに何かがあると信じて続けてきたそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=96s"]]}, {"cat": "リングに来るまで", "t": "大学時代はプロレスから離れていた", "b": "子どもの頃は大ファンだったが、1997年に大学に入った頃はヒップホップに夢中で、プロレスからは10年ほど離れていたと、ローゼンバーグは振り返る。寮の仲間が月曜の番組戦争を見ているのをのぞくことはあったという。一番盛り上がった時代を見逃したことを、友人のサム・ロバーツによくからかわれるそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（4:05〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=245s"]]}, {"cat": "リングに来るまで", "t": "出戻りのきっかけはシナの入場曲", "b": "ワシントンの局で働いていた2005年ごろ、実況のマイケル・コールとタズへの取材をきっかけに再び番組を見始めたと、ローゼンバーグは話す。テレビから流れたジョン・シナの入場曲に、好きなヒップホップの音源が使われていて驚いたという。そこから本格的にプロレスへ戻ってきたそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（4:57〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=297s"]]}, {"cat": "リングに来るまで", "t": "ボビー・ヒーナンとの短い電話取材", "b": "駆け出しの頃、ボビー・ヒーナンに電話で取材したことがあると、ローゼンバーグは話す。直前に亡くなったゴリラ・モンスーンへのお悔やみを伝えると、ヒーナンらしい一言の冗談が返ってきたという。何も分からずただファンとして話していたので、今聞いたら恥ずかしいはずだと笑う。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（7:23〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=443s"]]}, {"cat": "体のこと", "t": "スキンヘッドは選手との賭けから", "b": "今のスキンヘッドは、ラジオ番組でミスター・ケネディ（ケン・ケネディ）と勝負をして負け、頭を剃られたのが始まりだと、ローゼンバーグは話す。勝てないことは分かっていて、ちょうど剃るつもりだったという。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（9:00〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=540s"]]}, {"cat": "リングに来るまで", "t": "ヒップホップとの出会いは兄のラジオ", "b": "1987〜88年ごろ、4歳半上の兄に教わり、ニューヨークの祖父母の家で夜のヒップホップ番組を聴いたのが始まりだと、ローゼンバーグは話す。同じ時期にプロレスにも夢中になったという。3つの情熱をつなぐのは「物語を語ること」だと考えているそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（9:46〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=586s"]]}, {"cat": "好きなもの", "t": "心に残るのは80年代後半の会場の景色", "b": "人生の最後に思い浮かべるなら、1987〜88年のランディ・サベージ、ハルク・ホーガン、ブレット・ハート、エリザベスがいた会場の雰囲気だと、ローゼンバーグは話す。懐かしさは強い薬だ、とも語っている。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（11:21〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=681s"]]}, {"cat": "リングに来るまで", "t": "TNAのポッドキャストやインディーでも経験", "b": "2011年ごろにはTNAの公式ポッドキャストを友人と担当し、AJスタイルズやハーディーズに取材したと、ローゼンバーグは話す。リング・オブ・オナーでのゲスト実況や、コニーアイランドの興行でのゲスト付き人など、できることは何でもやったという。今その番組を探しても見つからないそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（17:03〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1023s"]]}, {"cat": "リングに来るまで", "t": "ビンスに直訴した仕事は実現しなかった", "b": "2008年の取材でビンス・マクマホンに「雇ってほしい」と頼み、「話そう」と返された場面は今もときどき話題になると、ローゼンバーグは話す。本気で動いてみたが、社内の人から「来るな」とはっきり断られたという。仕事につながったのは、何年も後の別の人たちとの縁だったそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（17:51〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1071s"]]}, {"cat": "リングに来るまで", "t": "WWE入りのきっかけは会場での立ち話", "b": "ESPNの同僚ジョナサン・コーチマンに誘われて2017年のレッスルマニアの取材に同行し、そこで制作幹部のクリス・チェンバースに声をかけられたと、ローゼンバーグは話す。連絡を取り続け、大会前番組の解説役と、新番組の司会の話をもらったという。コーチマンが誘ってくれなければ今の自分はない、と感謝している。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（21:16〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1276s"]]}, {"cat": "好きなもの", "t": "『バック・トゥ・ザ・フューチャー』は史上最高の映画", "b": "『バック・トゥ・ザ・フューチャー』を史上最高の映画だと言い切り、今もデロリアンを買おうと何度も眺めていると、ローゼンバーグは話す。主人公のスニーカーも欲しかったが、高くなりすぎて手が出ないという。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（26:56〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1616s"]]}, {"cat": "リングに来るまで", "t": "憧れはスポーツ実況とDJと名マネージャー", "b": "メリーランド州チェビー・チェイスで育ち、スポーツ実況のボブ・コスタス、DJのファンクマスター・フレックス、マネージャーのボビー・ヒーナンに憧れたと、ローゼンバーグは話す。コスタスの無駄のない話し方に聞き入り、ヒーナンの笑いの才能と体を張った受け身にひかれたという。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（28:32〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1712s"]]}, {"cat": "好きなもの", "t": "一番のマネージャーはボビー・ヒーナン", "b": "歴代最高のマネージャーはボビー・ヒーナンだと、ローゼンバーグは話す。ポール・ヘイマンはもはやマネージャーの枠を超えた存在で比べられないという。晩年のヒーナンにイベントで感謝を伝える機会があり、亡くなった後はESPNのサイトに追悼文を書いたそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（32:28〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1948s"]]}, {"cat": "好きなもの", "t": "最初に好きになったのはブレットとサベージ", "b": "子どもの頃に最初に夢中になったのはブレット・ハートとランディ・サベージだと、ローゼンバーグは話す。ブレットは理由も分からないまま「うまい」と感じさせる選手で、サングラスのレプリカも買ったという。サベージは善玉でも悪役でも満点で、史上最高の議論から外されがちなのが惜しいと語っている。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（33:17〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1997s"]]}, {"cat": "リングの話", "t": "今の盛り上がりはローマン、コーディ、ニック・カーンから", "b": "今のプロレス人気の土台は、ローマン・レインズとポール・ヘイマンが組んだこと、コーディ・ローデスの復帰、ニック・カーンの経営手腕の3つだと、ローゼンバーグは話す。レインズの横にヘイマンが映った瞬間、番組の収録中に頭が爆発しそうになったという。舞台裏で見るレインズには特別な風格がある、と語っている。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（40:23〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=2423s"]]}, {"cat": "暮らし", "t": "「ダサい」と言われた頃から堂々とファン", "b": "プロレス好きがかっこ悪いと思われていた頃から、堂々とファンを名乗り、昔のTシャツを着続けてきたと、ローゼンバーグは話す。ヒップホップ界でプロレス好きを公言する仲間が少しずつ増えたことを誇りに思っているという。WWEの客席の多様さと、家族で楽しめる雰囲気も大好きだそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（49:14〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=2954s"]]}, {"cat": "家族", "t": "幼い娘をパリの大会に連れて行った", "b": "妻と娘を連れてパリの大会に行き、花火や大音量を避けるため入場が終わってから客席に連れて行ったと、ローゼンバーグは話す。耳当てをさせ、試合の途中で席を立ったという。家族の記録は昔ながらのビデオカメラで残すのが好きだそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（52:16〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=3136s"]]}, {"cat": "好きなもの", "t": "シナのラップの腕前を評価", "b": "ジョン・シナのアルバムは代表曲しか聴いていないが、ラッパーとしては悪くないと、ローゼンバーグは話す。地下で活躍していたラッパーのフレディ・フォックス（バンピー・ナックルズ）を引き立てたことを、ずっと尊敬しているという。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（55:32〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=3332s"]]}, {"cat": "好きなもの", "t": "ヒップホップの「ラシュモア山」を選ぶ", "b": "自分にとってのヒップホップの4人はラキム、2パック、ジェイZ、アンドレ3000だと、ローゼンバーグは話す。心ではビギーの方が好きだが、文化的な影響力では2パックだという。選ぶたびに変わる、と笑っている。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（1:11:27〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=4287s"]]}, {"cat": "家族", "t": "40歳で父になり、すべてが変わった", "b": "ずっと父親になりたいと思っていて、40歳の誕生日の10日後に娘が生まれたと、ローゼンバーグは話す。娘のことを考えると泣けてくるという。高齢の両親が孫に会えたことにも心から感謝しているそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（1:18:07〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=4687s"]]}, {"cat": "家族", "t": "妻とはコロナ禍のSNSのメッセージで出会った", "b": "妻とはコロナ禍に届いた何気ないメッセージがきっかけで出会ったと、ローゼンバーグは話す。最初に会ったとき、妻が好きなバンドの話で音楽好きとして身構えたが、実は妻もアティテュード時代のプロレス好きだったと分かったという。写真家でもある妻を「最高の母」と呼んでいる。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（1:18:54〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=4734s"]]}, {"cat": "暮らし", "t": "15歳の愛犬ベアがまだ元気", "b": "15歳になる愛犬ベアがまだ元気でいてくれることに感謝していると、ローゼンバーグは話す。半年前には同じく15歳だったマルチーズを亡くしたという。ここ10年で友人や同僚を多く見送ってきたので、両親が健在なことがありがたいそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-v-3UQrCGhqU", "src": [["番組のYouTube（1:20:27〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=4827s"]]}]);
  if (PROFILES["Bobby Heenan"]) PROFILES["Bobby Heenan"].facts.push({"cat": "暮らし", "t": "ボビー・ヒーナンは史上屈指の才能", "b": "マネージャーとしての受け身や体を張った笑い、実況席での悪役ぶりまで、ヒーナンほど多才な人はいないと、ローゼンバーグが話している。", "sp": "ピーター・ローゼンバーグ", "d": "2025-10-16", "how": "クリス・ヴァン・ヴリートの番組で、ピーター・ローゼンバーグの話（字幕を全文確認）", "src": [["番組のYouTube（30:07〜）", "https://www.youtube.com/watch?v=v-3UQrCGhqU&t=1807s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-v-3UQrCGhqU", d: "2025-10-16", show: "ext", who: ["Peter Rosenberg"], t: "ピーター・ローゼンバーグの回　ラジオからWWEへ、ボビー・ヒーナンへの敬意、40代で父になって", lead: "クリス・ヴァン・ヴリートの番組に出た約82分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Peter Rosenberg"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-v-3UQrCGhqU").map((x) => [x.t, x.b, x.sp])), open: ["広告の読み上げは除いた。", "シナの引退試合の相手予想など、筋書きの予想の話は載せていない。", "妻や娘の名前は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=v-3UQrCGhqU"]] });
  if (!ROSTER.find((r) => r[1] === "Hornswoggle")) ROSTER.push(["ホーンスワグル", "Hornswoggle", "lg", "元WWEの小柄な人気者", "", "", ""]);
  if (!PROFILES["Hornswoggle"]) PROFILES["Hornswoggle"] = { lead: "ウィスコンシン州オシュコシュ育ちのディラン・ポストルが、4歳の大手術から憧れのリング入りまでを語る。自分を笑い飛ばす明るさと、息子への思いが光る回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Hornswoggle"]], moves: [], facts: [] };
  if (PROFILES["Hornswoggle"]._weak) { PROFILES["Hornswoggle"].lead = "ウィスコンシン州オシュコシュ育ちのディラン・ポストルが、4歳の大手術から憧れのリング入りまでを語る。自分を笑い飛ばす明るさと、息子への思いが光る回。"; delete PROFILES["Hornswoggle"]._weak; }
  PROFILES["Hornswoggle"].facts.push(...[{"cat": "リングの話", "t": "ビッグEをからかい続けて蹴られた話", "b": "ホーンスワグルは移動を共にしたビッグEを、体が大きいという理由でよくからかっていたと話す。ある日、荷物を背負ったまま建物に入ると、後ろから背中のバッグごと蹴り飛ばされ、顔から着地したそうだ。ビッグEは何も言わず歩き去り、「あれは自分が悪かった」と謝りに行ったという。それでもからかうのはやめられなかった、と笑っている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（0:49〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=49s"]]}, {"cat": "リングの話", "t": "ステフが支えてくれた恩を語る", "b": "在籍中も退団後も、ステファニーが一番の味方だったと話す。兄妹役の筋書きをやっていた頃、失恋でつらい時期にミルウォーキーで声をかけてもらったという。ビー・ア・スターの活動の担当を後押ししてくれたことにも感謝している。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（4:47〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=287s"]]}, {"cat": "家族", "t": "憧れはアルティメット・ウォリアー", "b": "子どもの頃のヒーローはスーパーマンでもバットマンでもなく、アルティメット・ウォリアーだったという。スポーツは嫌いで、プロレスのフィギュアやテレビ番組からWWEにのめり込んだそうだ。17歳でプロレスの練習を始めたと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（10:16〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=616s"]]}, {"cat": "リングに来るまで", "t": "19歳で採用、運に恵まれたと話す", "b": "2006年当時は身長180センチ超・体重110キロ級が「型」だったが、自分はその型に当てはまらなかったという。それでも採用されたのは、運とタイミングと機会のおかげだと何度も話す。今は偽名で20年後もサインをしていることが、不思議で嬉しいそうだ。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（11:02〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=662s"]]}, {"cat": "家族", "t": "解雇の日に父がくれた言葉", "b": "2016年に契約を解除されたとき、父に電話で知らせたという。父は「夢が終わって腹が立つ気持ちは分かるが、与えてもらったものを思い出せ。悪く言う理由はない」と諭したそうだ。WWEのおかげで息子を養えていることを、いまも大切に思っていると話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（11:53〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=713s"]]}, {"cat": "リングに来るまで", "t": "ケネディの紹介と、散々だった面接", "b": "2003〜04年にミスター・ケネディ（ケン・アンダーソン）からプロレスを教わり、彼の推薦で面接を受けたという。当時は、フィンレーの相棒にする小柄な妖精役を探していた時期だった。面接ではアイルランド訛りを試されたが、出来が悪く、フィンレーにも「あまり良くなかった」と言われたそうだ。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（12:41〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=761s"]]}, {"cat": "リングに来るまで", "t": "採用の電話を6回無視した", "b": "夢は終わったと思った2、3週間後、トミー・ドリーマーから採用を告げる電話が入ったという。ところが当時19歳で、非通知の番号はクレジットカードの督促だと思い、6回も無視したそうだ。留守電に「WWEのトミー・ドリーマーです」と入っているのを聞き、慌てて折り返したと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（14:18〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=858s"]]}, {"cat": "リングに来るまで", "t": "下積みはほとんどなかった", "b": "プロレスのインディー団体で1年半ほど、月に1、2回出ただけで、名前も売っていなかったという。セス・ロリンズやケビン・オーウェンズのように何年も下積みを重ねた選手を見て、自分は何も勝ち取っていないと感じるそうだ。だからこそ、与えられた機会に強く感謝していると話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（15:52〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=952s"]]}, {"cat": "体のこと", "t": "4歳で背骨の大手術を受けた", "b": "1990年、4歳のときに背中の手術を受けたが、小柄な人への手術が初めての医師が神経に触れ、腰から下がまひしたという。ひざから胸までの全身ギプスをはめ、歩き方を一から練習し直したそうだ。その後ミネアポリスの医師が肋骨を使って背骨を固定し、金属の棒を入れる手術をした。「格闘技とトランポリンは禁止」と言われたが、のちにテレビに出た姿を見た医師が父にメールをくれたと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（15:52〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=952s"]]}, {"cat": "体のこと", "t": "数年前の2度の手術と足の感覚", "b": "リングで受けた一撃をきっかけに、数年前に背中の手術を2回したという。神経の圧迫を取る手術だったが、神経の傷みが大きく、足先の冷えやしびれ、太ももの常時こわばりが残ったそうだ。リハビリを半年続けたが戻っていない。足をぶつけても痛みを感じず、音だけ聞こえて笑ったこともあると話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（18:25〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1105s"]]}, {"cat": "体のこと", "t": "減量とジム通いで体は絶好調", "b": "背骨に痛みはなく、腰から上は人生で一番調子が良いと話す。ジムで追い込んで翌日に筋肉痛があると、良いことをした気になるそうだ。減量の取り組みも順調で、足の状態は気持ちには影響していないという。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（20:08〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1208s"]]}, {"cat": "好きなもの", "t": "映画をほとんど観ない人", "b": "ゴッドファーザーも、トム・ハンクスやマット・デイモンの作品も観ていないという。コメディ、マペット、ディズニー以外はほぼ観ないそうだ。アダム・サンドラー作品は大好きで、「ディーズ氏」を好きな作品の上位に挙げている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（22:30〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1350s"]]}, {"cat": "好きなもの", "t": "マペットが大好き", "b": "一番好きな映画は、最初の「マペット・ムービー」だという。好きなマペットはアニマル、スウィートムズ、アンクル・デッドリーの3体だそうだ。子どもの頃は「マペット・ベイビーズ」を観て育ったと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（23:20〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1400s"]]}, {"cat": "暮らし", "t": "生まれも育ちもオシュコシュ", "b": "ウィスコンシン州オシュコシュで一生暮らしていて、街が大好きだと話す。高校はオシュコシュ・ウェストで、息子も同じ学校に通っているそうだ。同じ街出身のNBA選手タイリース・ハリバートンとは面識がなく、冗談で「地元の顔」の座を争っている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（26:28〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1588s"]]}, {"cat": "リングに来るまで", "t": "裏庭プロレスと動画で技を覚えた", "b": "プロレスの動き方は、動画を見て覚えた部分もあると話す。裏庭でのプロレスごっこもしていたそうだ。ただしそれは勧められないことで、危険なので正しく訓練を受けるべきだと語っている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（28:54〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1734s"]]}, {"cat": "リングの話", "t": "リングでの大きなけがはなかった", "b": "WWEでの活動中、リング上で大きなけがをしたことはなかったと話す。数年前の一撃は別として、背骨のトラブルも在籍中にはなかったそうだ。自分は本当に運が良いと繰り返している。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（30:34〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1834s"]]}, {"cat": "リングの話", "t": "初日にフィンレーから出された「テスト」", "b": "登場の練習で、フィンレーがエプロンを持ち上げ、青信号が出たら飛び出すよう指示されたという。2回目は信号が出ないまま持ち上げられ、待っていると怒鳴られた。それは新人を試す仕掛けで、「6か月どころか6分でクビか」と思ったそうだ。3回目は完璧にこなせたと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（31:23〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1883s"]]}, {"cat": "リングの話", "t": "フィンレーとは父と子のような関係", "b": "フィンレーとは、わずか3週間で父子のような絆が生まれたという。そのおかげで、新人がよく受けるという洗礼を受けずに済んだと話す。周りがフィンレーを怒らせたくなかったからだろう、と見ている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（32:11〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=1931s"]]}, {"cat": "暮らし", "t": "コーヒーも昼寝も苦手、リスト派", "b": "コーヒーは味が大嫌いで飲まず、昼寝も嫌いだという。気力を保つ方法は、やることをリストにして一つずつ消していくことだそうだ。息子が学校にいる間に皿洗いやロボット掃除機を済ませると、達成感があると話す。スティック型とロボット型の掃除機を両方使っている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（34:32〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2072s"]]}, {"cat": "暮らし", "t": "寝る前はボディカメラ動画を見がち", "b": "睡眠を優先する方ではなく、寝る前にSNSや動画を延々と見てしまうという。よく見るのは警察のボディカメラ映像で、万引きが見つかる場面が特に好きだそうだ。ウィスコンシンの動画チャンネルなら道路の場所が分かるのも面白いと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（37:43〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2263s"]]}, {"cat": "家族", "t": "いじめには先に自分で笑う", "b": "ビー・ア・スターの活動で、学校を回って子どもたちに話してきたという。伝えているのは「自分で自分を先にからかえば、いじめっ子は使える材料がなくなる」ということだ。自分は子どもの頃から、自分を深刻に考えすぎなかったと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（42:31〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2551s"]]}, {"cat": "家族", "t": "両親は特別扱いしなかった", "b": "父は自分を中心に世界を変えようとはせず、支えつつも「ディランのための番組」にはしなかったという。実母とは今は連絡を取っておらず、継母が6年前に正式に養子として迎え、母になってくれたそうだ。おかげで社会に出てからも、小柄だからといって特別扱いを求めずに済んだと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（43:22〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2602s"]]}, {"cat": "家族", "t": "息子の誕生前に受けた検査", "b": "息子ランドンの母親が妊娠中、息子が自分と同じ体格になるかを調べる検査を受けたという。いじめや医療費、服の仕立て直しなど、苦労を知っているので心配だったそうだ。標準的な体格と分かって安心したが、そうでなくても「やるしかない」と思っていたと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（44:53〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2693s"]]}, {"cat": "リングの話", "t": "小柄な人の団体にレプラコーン役を批判された", "b": "リトル・ピープル・オブ・アメリカの大会には通っていたが、レプラコーン役の描かれ方を快く思われていなかったという。ホーンスワグルは、夢をかなえた若者の仕事だという点を分かってほしかったと話す。また、小柄な人の役が一人の声だけで語られるのではなく、もっと多くの声が聞かれるべきだと考えている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（48:01〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=2881s"]]}, {"cat": "暮らし", "t": "小柄な人向け以外の役も受けたい", "b": "約10年テレビに出た経験から、自分の声も届くはずだと思っているという。いまは小柄な人向けの役に限らず、一般の役のオーディションも受けているそうだ。仲間の役を増やす声になりたい気持ちはあるが、自分にその資格があるかは分からないと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（51:22〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=3082s"]]}, {"cat": "家族", "t": "小柄な人の全国大会と両親", "b": "十代の頃は、各地で開かれる全国大会に通っていたという。身近に小柄な人がおらず、初対面の年配の男性に会ったときは「自分は自分だ」と戸惑ったそうだ。親にとっては、服や医師の話を交換できる場で、耳の医師ともそこで出会ったらしい。競技大会には、本格的な練習が必要で自分は出なかったと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（53:52〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=3232s"]]}, {"cat": "暮らし", "t": "目標はオシュコシュのディランのまま", "b": "自分は「オシュコシュのディラン」でいたいと話し、本の中でも何度も触れているという。すべて終わったら、地元のスーパーで働く生活に戻ってもいいそうだ。業界に入った当初は天狗になりかけ、友人に指摘されたが、息子が生まれてから「すべては息子のため」に変わったと話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（57:57〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=3477s"]]}, {"cat": "暮らし", "t": "犬が怖く、息子は飼いたがっている", "b": "大型犬が苦手で、飛びかかられると倒されてしまうのが怖いと話す。息子ランドンは犬を飼いたがっているが、家を空けることが多く、息子とは母親と半々で過ごしているため、犬に悪いと考えているそうだ。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（59:29〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=3569s"]]}, {"cat": "暮らし", "t": "寝る前の防犯ルーティン", "b": "出張先のホテルでは、息子をドア側のベッドに寝かせ、自分は奥側で寝るという。侵入者が来ても子どもだと思って帰るだろうし、自分はベッドの下に隠れる時間を稼げる、という冗談混じりの考えだ。家では部屋の電気を順番につけ替え、ドアの前に洗濯かごを置いて音で気づけるようにしていると話す。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（1:10:38〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=4238s"]]}, {"cat": "リングの話", "t": "伝説契約の知らせを真っ先に父へ", "b": "1年前に、WWEの伝説選手向け契約の話が来たという。ブリンク182のライブへ息子と向かう途中、車を道の端に止めて父に電話したそうだ。父の声の反応は、最初に採用されたときよりも大きかったと話す。もうWWEに関われないと思っていたので、今回の収録で「ようこそ」という気持ちになれたと語っている。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-ni_pi4tl500", "src": [["公式YouTube（1:20:21〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=4821s"]]}]);
  if (PROFILES["Fit Finlay"]) PROFILES["Fit Finlay"].facts.push({"cat": "暮らし", "t": "フィンレーは静かに笑わせる人", "b": "フィンレーは、普段は無口で冷静なのに、突然ひと言で場を爆笑させる人だと、ホーンスワグルが話している。", "sp": "ホーンスワグル", "d": "2025-10-23", "how": "ステファニーの番組で、ホーンスワグルの話（公式字幕を全文確認）", "src": [["公式YouTube（14:18〜）", "https://www.youtube.com/watch?v=ni_pi4tl500&t=858s"]], "by": "第三者の話"});
