  PROFILES["Maxxine Dupri"].facts.push(...[{"cat": "家族", "t": "婚約中で、式は3か月後に迫る", "b": "マキシン・デュプリは婚約したばかりで、結婚式の準備は順調だと話す。幼いころから結婚式に憧れていたそうで、準備の時間がおとぎ話のようだという。頼れるウェディングプランナーに、予算の範囲で夢を形にしてもらっているそうだ。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（0:50〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=50s"]]}, {"cat": "家族", "t": "婚約者とは北カリフォルニアで出会った", "b": "婚約者のアンソニーとは、親友が元交際相手と出かけたタホ湖で知り合ったとマキシン・デュプリは話す。そのときは21歳くらいで、半年後に初めてデートをしたという。地元はお互い車で20分ほどの近さだったそうだ。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=96s"]]}, {"cat": "家族", "t": "何度も一緒に引っ越した二人三脚", "b": "二人は3つの州で暮らしてきたと、マキシン・デュプリは話す。契約が決まったとき、彼がカナダのフットボールで遠征中だったため、30日で荷造りをしてフロリダに引っ越したそうだ。彼は「分かった」と受け入れたという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=145s"]]}, {"cat": "家族", "t": "婚約者の夢を、自力の挑戦で支えた", "b": "婚約者は子どものころからのプロレスファンで、父親も熱心なファンだったと話す。マキシン・デュプリは、自分の口利きではなく本人の力で入団テストを受けるよう勧めたそうだ。彼は自分で応募して契約を勝ち取り、いまは夢の中にいるようだという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=190s"]]}, {"cat": "リングの話", "t": "最初の試合はいきなりテレビ番組", "b": "初めての試合がそのままテレビ放送だったとマキシン・デュプリは話す。当時は準備が足りていたとは言えず、最初の試合は緊張でほとんど記憶がないそうだ。いまは見返すと気恥ずかしいが、初々しさが魅力になっていたとも振り返る。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（3:10〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=190s"]]}, {"cat": "リングの話", "t": "地方興行で場数を踏んで成長", "b": "下部ブランドの地方興行に自分から出たいと頼み、場数を重ねているとマキシン・デュプリは話す。三つ巴戦などの初体験も、テレビでなく興行で経験できたのがありがたいそうだ。観客の前で、緊張に慣れることが大事だという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（5:31〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=331s"]]}, {"cat": "体のこと", "t": "最初の1年は足首の骨折を抱えていた", "b": "入団後まもなく足首を骨折し、約8か月は完治していなかったとマキシン・デュプリは話す。そのため最初の1年は十分なトレーニングができず、移動しながら治療を続けていたそうだ。通常の練習に戻れたのはその後だという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（7:09〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=429s"]]}, {"cat": "リングの話", "t": "本当の兄ではないLAナイトとの冗談", "b": "役柄の上でのきょうだいだったLAナイトについて、本人から助言は来ていないと冗談めかして話す。母親も心配していると笑い、いつでも家族の集まりに歓迎するという。いまの名前のままで続くのかについては、何も聞いていないそうだ。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（8:02〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=482s"]]}, {"cat": "家族", "t": "結婚で名字が変わるのが少し寂しい", "b": "結婚まであと3か月で、いまの名字はもうすぐ手放すとマキシン・デュプリは話す。つづりが難しく、電話ではいつも一文字ずつ説明してきたそうだ。一方で、父と同じ名字でなくなることには寂しさも感じているという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=580s"]]}, {"cat": "リングの話", "t": "手応えを感じたのは年明けの大乱戦", "b": "試合が噛み合ってきたと感じたのは、インディアナポリスの大乱戦形式の大会だったとマキシン・デュプリは話す。緊張が疑いではなく楽しみに変わり、父が会場に来てくれたのも嬉しかったそうだ。前年の同じ大会は納得できなかったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（13:39〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=819s"]]}, {"cat": "体のこと", "t": "SNSから距離を置いて心を守っている", "b": "酷評を目にして落ち込んだ経験から、いまはXをほとんど開かないとマキシン・デュプリは話す。見るのは仲間に頼まれた投稿を再投稿するときだけだそうだ。批判は自分が尊敬し、信頼する人からのものだけを受け止めるようにしているという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（15:12〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=912s"]]}, {"cat": "好きなもの", "t": "憧れのベラ姉妹と同じロッカールーム", "b": "ベラ姉妹に憧れていたマキシン・デュプリは、一緒に働けることを夢のようだと話す。パリでは姉妹と食事をして、周りの人たちまで優しいことに感激したそうだ。ブリーは本当に面白く、お笑いもできそうだと笑っていた。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（17:36〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1056s"]]}, {"cat": "好きなもの", "t": "「トータル・ディーバス」を今の顔ぶれで作りたい", "b": "リアリティ番組の新シーズンがあれば、チェルシー・グリーンやティファニー・ストラットンらに出てほしいとマキシン・デュプリは話す。ナタリア、ナオミ、ロクサーヌの名前も挙げ、配信での復活を望んでいるそうだ。自分も根っこはディーバだと話す。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（18:26〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1106s"]]}, {"cat": "リングの話", "t": "「怒りのスイッチ」を道場で探している", "b": "仲間のナタリアと「眉間にしわを寄せる攻撃性」を磨いているとマキシン・デュプリは話す。同僚の試合運びや間、痛がり方を観察して取り入れているそうだ。肩ひもを下ろす仕草は先輩にヒントを得たという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（22:24〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1344s"]]}, {"cat": "リングの話", "t": "後ろ向きのワームは偶然の産物", "b": "得意技のように見える後ろ向きのワームは、前向きがうまくできなかったからだとマキシン・デュプリは話す。先輩に相談したところ、自分のやり方でやっていいと背中を押されたそうだ。結果的にそのほうが楽でうまくいったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（23:16〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1396s"]]}, {"cat": "リングの話", "t": "兄の話を出す演出は自分の発案", "b": "ライバルが兄のことを持ち出した場面は、自分が言い出したアイデアだったとマキシン・デュプリは話す。兄を悪く言われるのではなく、光を当てる機会だと受け止めたそうだ。感情は役ではなく自分自身から出したが、両親には事前に伝えそびれたという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（25:00〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1500s"]]}, {"cat": "家族", "t": "亡くなった兄を、思い出として大切にしている", "b": "マキシン・デュプリには亡くなった兄がいて、いまも心の中で大きな存在だと話す。新しい職場では誰もその事情を知らないため、兄の存在に光を当てられたことが心を温めたそうだ。聞き手の姉の話にも、悲しみは常に身近にあると共感していた。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（28:10〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1690s"]]}, {"cat": "リングに来るまで", "t": "16歳でダンスの道を選び、大学を見送った", "b": "マキシン・デュプリは16歳でロサンゼルスのダンス事務所と契約し、オーディションのため頻繁に通っていたと話す。大学にも合格していたが、成績は良くなかったため、両親と話し合ってロサンゼルスで芸能の道に進むことにしたそうだ。大学はいつでも戻れる選択肢として残してあるという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（28:58〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1738s"]]}, {"cat": "リングに来るまで", "t": "ロサンゼルスでチアを続け、アリゾナへ", "b": "最初はアリーナフットボールのダンスチームに1年、その後プロフットボールの有名チームに2年所属したとマキシン・デュプリは話す。ロンドンやメキシコシティ、スーパーボウルにも同行できたそうだ。その後、アリゾナのバスケットボールチームのチアで2年間踊ったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（30:33〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1833s"]]}, {"cat": "リングに来るまで", "t": "リュック一つで臨んだ入団試験", "b": "アリゾナの試験は日帰りのつもりでリュック一つで向かったと、マキシン・デュプリは話す。二次に進むことになり、そこで出会った同じ志望者の自宅に泊めてもらい、婚約者が着替えを届けてくれたそうだ。見事に合格し、人との縁に恵まれた時期だったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（31:21〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1881s"]]}, {"cat": "リングの話", "t": "初期の大一番は悔しさが残った", "b": "早い時期にトップ選手と戦った試合を、満足にできなかったとマキシン・デュプリは話す。緊張でタイミングが狂い、相手に申し訳なく感じたそうだ。そこから練習の仕方を根本から変えるきっかけになったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（33:44〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2024s"]]}, {"cat": "リングの話", "t": "初のタイトル戦と、再戦への意欲", "b": "ベッキー・リンチとの王座戦は敗れたが、少しは食い下がれたと感じているとマキシン・デュプリは話す。その後は道場で細かい修正を重ね、次の対戦を楽しみにしているそうだ。王座はゴールではなく、努力が実った証にしたいという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（36:59〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2219s"]]}, {"cat": "暮らし", "t": "遠征の相棒と、オーティスとの食事", "b": "移動はいまロクサーヌと一緒のことが多く、コーヒーショップ巡りが楽しいとマキシン・デュプリは話す。空港でオーティスとステーキを食べ、辛い西洋わさびに二人でもだえたこともあるそうだ。オーティスは心が大きく、とても義理がたい人だという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（41:08〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2468s"]]}, {"cat": "暮らし", "t": "婚約者の付き人として出る日は急な仕事", "b": "婚約者のチームの試合に急に呼ばれ、約2時間前の連絡で衣装を用意したとマキシン・デュプリは話す。ちょうど休息日で、家のクローゼットから黒いコルセットを出し、ロゴを手縫いで付けたそうだ。師匠格の人とそっくりの服になり、場が盛り上がったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（42:49〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2569s"]]}, {"cat": "リングに来るまで", "t": "チア時代に身についた人前での基本", "b": "チアリーダーとして、どの位置にいても一番上の観客のために踊る意識を学んだとマキシン・デュプリは話す。時間厳守や身だしなみ、慈善活動や出演仕事の段取りも身についたそうだ。いまの仕事にも役立っていると感じているという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（44:50〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2690s"]]}, {"cat": "好きなもの", "t": "婚約者の影響でバティスタの大ファン", "b": "婚約者が幼いころからバティスタのファンで、自分もすっかり影響を受けたとマキシン・デュプリは話す。交際初期、婚約者が動画を送ってバティスタ本人から返事をもらったことがあるそうだ。着ていたのは、年間最大の祭典の第21回を記念した古着風のシャツだったという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（45:18〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=2718s"]]}, {"cat": "暮らし", "t": "道場の「ノリ」を大事にする練習", "b": "練習前に「今日は誰がノリを持ってくる？」と仲間と連絡を取り合うと、マキシン・デュプリは話す。気軽に楽しめる場所があることで、失敗を恐れずに試せるようになったそうだ。昔に道場で行われた20発の胸への張り手の写真が、いまも壁に飾られているという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（51:38〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=3098s"]]}, {"cat": "体のこと", "t": "ピラティスは本気の運動だと広めたい", "b": "先輩レスラーと一緒にピラティスをして、相手をへとへとにさせたことが話題になったとマキシン・デュプリは話す。ピラティスは優雅に見えても本当はきついと知ってほしいそうだ。自分は「ピラティスのプリンセス」だと笑っている。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（54:52〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=3292s"]]}, {"cat": "体のこと", "t": "体を鍛えて筋肉をつけたい", "b": "背の高さを活かしつつ、筋肉質な体を目指していると、マキシン・デュプリは話す。上半身の日を作り、クレアチンやたんぱく質も増やしているそうだ。細く見られがちなので、見た目の印象を変えたいという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（55:38〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=3338s"]]}, {"cat": "体のこと", "t": "水風呂とリング睡眠の記録で整える", "b": "4月の引っ越し以来しばらく水風呂をやめていたが、ひどい筋肉痛で再開したとマキシン・デュプリは話す。入った日はトレーニングの調子が良く、睡眠中の安静時心拍も数値が下がるそうだ。同僚に勧められた指輪型の計測器を2年使っているという。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（56:30〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=3390s"]]}, {"cat": "家族", "t": "結婚式は大みそかの水曜日", "b": "結婚式は大みそかに決めたと、マキシン・デュプリは話す。仕事を休まずに済む曜日で、親族も休みを取りやすいからだそうだ。みんなの年越しの予定をまとめて引き受けた形になったと笑っている。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-XCq0DXaaq6g", "src": [["番組のYouTube（58:07〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=3487s"]]}]);
  if (PROFILES["Chad Gable"]) PROFILES["Chad Gable"].facts.push({"cat": "暮らし", "t": "口数は少ないが、的確に助言をくれる", "b": "チャド・ゲーブルは言葉数は少ないが、全体を見て本質的な助言をくれる人だと、マキシン・デュプリが話している。試合運びやタイミング、感情の出し方、受け身の巧みさをよく真似しているそうだ。", "sp": "マキシン・デュプリ", "d": "2025-11-06", "how": "クリス・ヴァン・ヴリートの番組で、マキシン・デュプリの話（字幕を全文確認）", "src": [["番組のYouTube（20:49〜）", "https://www.youtube.com/watch?v=XCq0DXaaq6g&t=1249s"]], "by": "第三者の話"});
