  if (!PROFILES["Natalya"]) PROFILES["Natalya"] = { lead: "ハート一家の三世で、デビューから約19年のベテラン。初の著書を通じて、人を喜ばせたがる自分と向き合い、自分に賭けた歩みを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Natalya"]], moves: [], facts: [] };
  if (PROFILES["Natalya"]._weak) { PROFILES["Natalya"].lead = "ハート一家の三世で、デビューから約19年のベテラン。初の著書を通じて、人を喜ばせたがる自分と向き合い、自分に賭けた歩みを語る。"; delete PROFILES["Natalya"]._weak; }
  PROFILES["Natalya"].facts.push(...[{"cat": "リングの話", "t": "親族の名前に頼らず自力で入った", "b": "2005年に練習生の採用を目指してテープを送っていた頃、家族の誰かが一本電話してくれたら、と思っていたという。だが当時は父も叔父のブレットも祖父も、会社に口をきける立場ではなかった。誰も助けてくれなかったおかげで自分の力で押し通せた、とナタリヤは今では感謝している。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（3:16〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=196s"]]}, {"cat": "リングに来るまで", "t": "本の執筆は一番のセラピーだった", "b": "初の著書は、これまでで一番心の整理になった仕事だったと話す。書くうちに、自分が「人を喜ばせたがる人間」だと気づいたそうだ。大家族の中で小さくいるほうが安全か、目立つほうが楽かと考え続けてきたことが背景にあるという。夫のTJからは、これからは自分を喜ばせることだけ考えればいいと言われている。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（4:53〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=293s"]]}, {"cat": "暮らし", "t": "書いた文章は一晩寝かせて決める", "b": "ベッキー・リンチから「心の内を全部吐き出して、一晩寝かせてから残すか直すか決めなさい」と助言をもらったという。夜中の3時まで書き、眠って読み返す作業を1年続けた。結果、残したい内容はすべて残せたと話す。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（6:28〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=388s"]]}, {"cat": "暮らし", "t": "ルイ・ヴィトンが好きでアクセサリーは苦手", "b": "高級ブランドのルイ・ヴィトンが好きで、靴やスカーフを自分へのご褒美にしているという。ジュエリーはあまり着けないので、誕生日やクリスマスの贈り物は宝飾品でなくていいとTJに頼んでいる。結婚指輪も家のどこかにしまい込んだまま、場所を覚えていないと笑う。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（9:43〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=583s"]]}, {"cat": "リングに来るまで", "t": "ウェイトレス時代の金銭感覚が今も残る", "b": "WWEに入る前は何年もレストランで働いていた。高い買い物をするたびに「これは何回分のシフトだっただろう」と考えてしまうそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（11:20〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=680s"]]}, {"cat": "家族", "t": "父の景気で家計が上下した子ども時代", "b": "父がWWEの全盛期だった頃は暮らしも良かったが、仕事がうまくいかない時期は苦しかったという。祖父が興行を仕切っていた地元団体でも、景気がよい時と、電気代すら払えない時が交互に来ていた。「大きなレスリング一家は裕福」という見方とは違う、浮き沈みの激しい家だったと話す。そのため最初の仕事から、誰にも足元をすくわれないよう必死で働いたそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（11:20〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=680s"]]}, {"cat": "家族", "t": "父は砲丸投げ世界上位の万能アスリート", "b": "父は18歳で全米1位、世界5位の砲丸投げ選手だったという。さらにプロのアメリカンフットボールでも活躍し、そのあとWWEに来たので、3つのプロ競技を経験している。著書には、祖父に売り込んだ頃の父の経歴書を載せたと明かす。ベンチプレス570ポンド、スクワット689ポンドなどの記録が並ぶそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（15:30〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=930s"]]}, {"cat": "家族", "t": "父は年に300日も家を空けていた", "b": "全盛期の父は年のほぼ300日を巡業に出ていて、顔を合わせる日は少なかった。帰ってくると家が一気に華やぎ、東京のホテルのアメニティなど、世界中の小物を土産に持ち帰った。それが自分の知らない大きな世界の手がかりだったという。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（16:15〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=975s"]]}, {"cat": "家族", "t": "母はしっかり者で、家計を支えた", "b": "母は美術大学で彫刻を学んだ芸術家だったという。父が仕事を失った時期には、生活のために大型スーパーでホットドッグを売る仕事に就いた。小柄ながら気が強く、人に踏みつけられるなと教えてくれた人で、粘り強さも母から学んだとナタリヤは話す。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（22:39〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1359s"]]}, {"cat": "リングに来るまで", "t": "最初の契約は年2万4千ドル", "b": "WWEとの最初の契約は年収約2万4千ドル、週にして約500ドルだったという。それでも当時は大喜びで、育成時代は人生で一番楽しい時期の一つだったと振り返る。ドクター・トムらの指導を受け、ベラ・ツインズとも出会ったそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（23:30〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1410s"]]}, {"cat": "リングの話", "t": "「ローキー・レジェンド」は本から生まれた", "b": "人にどう思われるかばかり気にしてきた自分を、本の執筆の途中で見つめ直したという。そこで自分に賭けると決めたことが、「ローキー・レジェンド」というキャラクターの出発点になった。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（29:01〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1741s"]]}, {"cat": "リングの話", "t": "地下道場での修行が役作りの土台", "b": "最初のロックアップやバンプなど、すべてを覚えたのは祖父の道場だったそうだ。そのため、役に入り込むのは簡単だったと話す。あの頃の自分は、祖父ストゥ・ハート譲りの荒っぽい粘りを持っていたという。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（30:41〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1841s"]]}, {"cat": "リングの話", "t": "自分でブラッドスポーツ出場を直談判した", "b": "レッスルマニア前、自分に合う役が見つからず焦っていたナタリヤは、ジョシュ・バーネットに話を通したうえでトリプルHに直接頼みに行った。トリプルHは忙しい中で話を聞き、すぐに承諾してくれたという。承諾を待つのではなく自分から動くことが大事だと感じたそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（31:28〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1888s"]]}, {"cat": "リングの話", "t": "オーディションのつもりで臨んだ一戦", "b": "ブラッドスポーツでの試合はオーディションのつもりで臨んだという。結果は2日間話題になり、観客にも好評だった。対戦した山下実優は、WWE所属でなくても世界屈指の女子選手だと称える。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（33:04〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1984s"]]}, {"cat": "リングに来るまで", "t": "育成時代の先輩ランディ・オートンの言葉", "b": "育成団体にいた頃、ランディ・オートンが全員を集めて話してくれたという。道に出ると別の楽しさに変わり仕事になるから、今の仲間と過ごす時間を楽しめ、という内容だったそうだ。ソファでペイ・パー・ビューを見ながら憧れた日々も忘れるなと語ったという。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（33:49〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2029s"]]}, {"cat": "リングの話", "t": "一度きりでないと示すため他団体でも戦った", "b": "あの一戦はまぐれではないと証明したくて、他団体の選手とも戦ったという。NWAではケンジー・ペイジと、ブッカーTの団体ではプロミス・ブラクストンと、サマースラムの時期のブラッドスポーツではマシャと試合を組んだ。いずれも、相手側が選んだ最高の相手を指名したそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（34:35〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2075s"]]}, {"cat": "リングの話", "t": "折れた足首で試合に出た", "b": "ロンドンでナオミと戦う日に、リハーサルで足首を骨折したという。周囲は欠場を勧めたが、勝つ予定の試合を譲りたくなくて、平気だと言い張って出場した。短い試合だったが、アンダーテイカーのようにゆっくり歩いて入場したそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（36:11〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2171s"]]}, {"cat": "リングの話", "t": "「堅実で安全」な自分を超えたい", "b": "ナタリアはいつも堅実で安全、出来が保証された存在だと自分で分析している。それは誇りでもあるが、同じことを続けても同じ結果しか出ないと感じていたという。そこで新しい挑戦に踏み出したそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（36:11〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2171s"]]}, {"cat": "リングの話", "t": "ダンジョンは古びたまま熱くが信条", "b": "TJと運営する練習場は、冷房なしで広さもリングがやっと入る程度。わざと飾り気のない、荒削りな場所にしているという。祖父の原点を受け継ぎ、招待制で、情熱のある人だけを受け入れている。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（41:47〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2507s"]]}, {"cat": "家族", "t": "祖父は全員を関節技で鍛えた", "b": "祖父ストゥは世界一の選手と練習したくて、金は取らなかったという。気に入らない相手や業界に敬意のない相手には、また会いたくないから金を受け取らなかったそうだ。上手い下手に関係なく全員を関節技で痛めつけたが、今のダンジョンでは、そこまではしないとナタリヤは話す。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（47:26〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2846s"]]}, {"cat": "暮らし", "t": "練習に来る若者に求める礼儀", "b": "ダンジョンで一番大事なのは礼儀だと話す。遅れるなら連絡を入れること、ドクター・トムも嘘をつくなと教えていたという。ある若い兄弟は、最初に来て最後に帰り、前日の練習内容を翌日にはこなしていたそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（48:12〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2892s"]]}, {"cat": "暮らし", "t": "年齢を重ねるほど幸せになっている", "b": "年を取って「もう古い」と思われるのが怖かった時期もあったという。今は、キャリアにも会社の行き先にも一緒に働く仲間にも、ワクワクしていると話す。ロッカールームの仲間が大好きで、ベイリーとは同じ空間にいるだけで嬉しいそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（50:38〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=3038s"]]}, {"cat": "リングの話", "t": "若手を光らせる試合づくり", "b": "アイビー・ナイルと戦った時は、すでに地位のある自分が引き立て役になり、観客に彼女の良さを見せようとしたという。最後は自分が勝つとわかっていたからこそだ、と笑う。ロッカールーム全員を満足させたいという気持ちは、人を喜ばせたがる性格の表れでもあると話す。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（51:23〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=3083s"]]}, {"cat": "家族", "t": "夫TJは猫のようにシャイな人", "b": "夫のTJは内気で内向的、打ち解けるまで時間がかかるという。慣れた相手の前では憎まれ口も叩くそうだ。自身もかつて下積みが長かったので、女子部門の誰も置き去りにしないよう気を配る人だと、ナタリヤは話す。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（52:09〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=3129s"]]}, {"cat": "家族", "t": "子どもは持たない選択をした夫婦", "b": "父を看取る世話をしたことで、父が自分の子どものようだったと話す。そのため子どもを持ちたいと思ったことはなく、TJとも納得しているという。代わりに、ある若い兄弟を養子のように可愛がっていて、TJは特に下の子と気が合うそうだ。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（55:16〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=3316s"]]}, {"cat": "好きなもの", "t": "無人島に連れていく最強チーム", "b": "最高のチームを選ぶ質問には、夫が好きなステフィン・カリーとマイケル・ジョーダン、さらにビアンカ・ベルエアとベス・フェニックスを挙げた。ビアンカは人として安定感があるからで、ベスはどんな状況でも戦い抜ける人だからという。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（56:49〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=3409s"]]}]);
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "育成時代のランディ・オートンの話", "b": "育成団体にいた頃、ランディ・オートンが全員を集めて、今の仲間と楽しむ時間を大切にしろと話してくれたと、ナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（25:06〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1506s"]], "by": "第三者の話"});
  if (PROFILES["Stu Hart"]) PROFILES["Stu Hart"].facts.push({"cat": "暮らし", "t": "祖父ストゥ・ハートのダンジョン", "b": "祖父ストゥは金を取らず、世界一の選手と練習するために自宅の地下で全員を関節技で鍛えていたと、ナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（47:26〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2846s"]], "by": "第三者の話"});
  if (PROFILES["Bret Hart"]) PROFILES["Bret Hart"].facts.push({"cat": "暮らし", "t": "叔父ブレットの立場", "b": "自分が採用を目指していた頃、叔父のブレットも会社に口をきける立場ではなかったと、ナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-11-13", "how": "コーディの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（4:07〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=247s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "暮らし", "t": "旅先でつい高級ブランドの袋を買った", "b": "買い物をまとめる袋が必要になり、近くの店で済ませればよいのに、ルイ・ヴィトンで買ってしまったという。自覚があるほどの高級志向だと笑っている。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（9:43〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=583s"]]}, {"cat": "家族", "t": "母のおかげで身についた働き癖", "b": "10代のころ最初のバイト先を怠けてクビになり、母に厳しく叱られたという。以来、働くことに厳しい母の姿勢が根っこにあると話す。母は高校時代に看護師に復帰した人で、自分の勤勉さは母から来ていると語る。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（21:49〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1309s"]]}, {"cat": "リングに来るまで", "t": "育成時代は給料を毎週使い切っていた", "b": "週に約500ドルの給料を、収録後の仲間との飲み会で使い切っていたという。住まいはあったので困らなかったそうだ。練習の合間に、売店のホットドッグを食べるのも日課だった。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（25:06〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1506s"]]}, {"cat": "好きなもの", "t": "ホットドッグが好き", "b": "大型スーパーのホットドッグが今でも一番好きだと話す。育成時代の売店のホットドッグも思い出の味だという。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（26:38〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=1598s"]]}, {"cat": "暮らし", "t": "子どもができて慎重になった", "b": "子どもが生まれてから、ここ最近は自分史上最も慎重で堅実な自分になっていると話す。昔のような思い切った冒険はもうできないが、気持ちの中ではまだ挑戦したいと思っているそうだ。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（41:47〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2507s"]]}, {"cat": "家族", "t": "甥や孫たちの頭文字をブーツに入れた", "b": "レッスルマニア40では、甥や父ダスティの孫たち全員の頭文字をブーツの内側に入れたという。当時は誰もレスリングの道には進まず、自分で終わりだと思っていた。今は彼らが本気で取り組んでいると知り、嬉しいと話す。", "sp": "コーディ・ローデス", "d": "2025-11-13", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-8cG-jNvT2MQ", "src": [["公式YouTube（45:43〜）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ&t=2743s"]]}]);
  ARTICLES.push({ id: "wdywta-8cG-jNvT2MQ", d: "2025-11-13", show: "wdywta", who: ["Natalya", "Cody Rhodes"], t: "ナタリヤの回　三世の重圧と、自分に賭けた決断", lead: "コーディ・ローデスの番組に出た約58分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Natalya", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-8cG-jNvT2MQ").map((x) => [x.t, x.b, x.sp])), open: ["未成年の子どもたちとの交流の詳細は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=8cG-jNvT2MQ"]] });
  if (!PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Paul%20Heyman"]], moves: [], facts: [] };
  if (PROFILES["Paul Heyman"].lead === "") PROFILES["Paul Heyman"]._weak = 1;
  PROFILES["Paul Heyman"].facts.push(...[{"cat": "リングの話", "t": "素の自分より役を演じるほうが楽", "b": "ポール・ヘイマンは、自分は欠点だらけの人間だと自覚していて、カメラの前では役を演じているほうがずっと落ち着くと話す。人が見たがるのは自分ではなく、あのキャラクターのほうだと考えているという。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（5:00〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=300s"]]}, {"cat": "リングの話", "t": "幕をくぐればあの男になる", "b": "体調が悪くても、家で嫌なことが続いた日でも、入場の幕をくぐればその男になるとポール・ヘイマンは話す。あのキャラクターは病気にならず、気分も落ちないという。ただし成功から学んだことはなく、失敗や苦労から学んだものが「賢者」の人物像になったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（32:25〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=1945s"]]}, {"cat": "リングの話", "t": "殿堂入りのスピーチはほぼ即興", "b": "ポール・ヘイマンは殿堂入りを4度断ってきたが、トリプルHに最初に声をかけられ、式の目玉を任されたことが決め手になったという。スピーチは曲だけあって歌詞はない状態で、ほぼ即興だったと話す。過去の自慢話にせず、いま組んでいる若い選手たちに向けた話にしたかったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（47:35〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=2855s"]]}, {"cat": "リングの話", "t": "「あんたにふさわしい」の声に背中を押された", "b": "殿堂入りの壇上で言葉が真っ白になったとき、観客席から「あなたにふさわしい」という声が広がって救われたと、ポール・ヘイマンは話す。あの夜はECWの殿堂入りでもあると考え、革のジャケットや帽子、ヘッドセットの役をここで終わりにする気持ちだったという。冬に長い革のコートを着ないのも、あの役を思い出させるからだそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（54:45〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3285s"]]}, {"cat": "リングの話", "t": "ヒールは失敗しても許される", "b": "ポール・ヘイマンは、ベビーフェイスは常に好かれようとして観客に嫌がられる危険があるのに対し、ヒールは失敗しても怒ってみせれば成立するので気楽だと話す。たとえば言葉に詰まっても「邪魔されたから最初からやり直す」と言えば、ブーイングがそのまま盛り上がりになるという。これは周りにも教えていることだそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（57:07〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3427s"]]}, {"cat": "リングの話", "t": "選手の「泣きどころ」を教えてもらう", "b": "ポール・ヘイマンは、組む選手にまず怒りや喜び、涙のきっかけになる急所をすべて教えてほしいと頼むという。配偶者より深く打ち明けてもらうことで、カメラが回る直前に耳元でひと言ささやき、演技ではない本物の感情を引き出せるからだと話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:01:55〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3715s"]]}, {"cat": "リングの話", "t": "ブロックは一面的、トライバルチーフは多層", "b": "ポール・ヘイマンは、ブロック・レスナーの役はあえて一面的に作り、深くは掘り下げなかったと話す。一方、ローマン・レインズのトライバルチーフは、要所で新しい面を見せ続けたことで目が離せない人物になったという。子役が目の前で成長していくようなものだったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:06:04〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3964s"]]}, {"cat": "リングの話", "t": "ローマンに預けられた秘密は墓まで持っていく", "b": "ポール・ヘイマンは、ローマン・レインズが演じる役の層を探すとき、楽屋のソファで耳打ちするだけで感情に火がついたことがあったと話す。そこで預けられた個人的な話は、誰にも漏らさず墓まで持っていくつもりだという。信頼されて初めて、最高の演技が引き出せると考えているそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:07:35〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=4055s"]]}, {"cat": "リングの話", "t": "ECW時代は全部の決定が自分を通った", "b": "ポール・ヘイマンは、1993年から2001年までECWでは自分が最終決定者で、あらゆる判断が自分を通っていたと話す。選手に十分な報酬を払えないことが多かったが、会社の金を懐に入れたことはなく、7年半は自分の給料も取らなかったという。それが選手の信頼をつなぎとめた救いだったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:17:22〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=4642s"]]}, {"cat": "リングの話", "t": "WWEでは「かき回し役」を任された", "b": "ポール・ヘイマンは、WWEに来たとき、脚本チームを率いる若いステファニーを揺さぶる反対意見の役を頼まれたと話す。ECWで全部自分が決めていた立場から、承認を得る側に回ることに戸惑ったという。深夜の話し合いを重ねるうちに、お互いの立場が分かって信頼が深まったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:22:13〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=4933s"]]}]);
  if (!PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"] = { lead: "15歳で会場に潜り込んだ写真少年は、ホロコーストを生き延びた母とブロンクス育ちの父に「何があっても前へ進め」と教わって育った。素の自分を人前に出すのは苦手だという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Paul%20Heyman"]], moves: [], facts: [] };
  if (PROFILES["Paul Heyman"]._weak) { PROFILES["Paul Heyman"].lead = "15歳で会場に潜り込んだ写真少年は、ホロコーストを生き延びた母とブロンクス育ちの父に「何があっても前へ進め」と教わって育った。素の自分を人前に出すのは苦手だという。"; delete PROFILES["Paul Heyman"]._weak; }
  PROFILES["Paul Heyman"].facts.push(...[{"cat": "暮らし", "t": "素の自分を人前に出すのは苦手", "b": "SNSには何も投稿せず、最近飼い始めた犬の写真も載せないという。演じるキャラクターでいる方が気楽で、家ではくつろげるが、公の場で自分自身として見られるのが落ち着かないと話す。自分はとても私的な人間で、客が観に来るのは自分ではなく「あの男」の方だと考えているそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（4:09〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=249s"]]}, {"cat": "リングに来るまで", "t": "日曜はローワー・イースト・サイドで過ごした", "b": "子どものころ、毎週日曜は値切り交渉が好きな母を市場に降ろし、父と二人で老舗のデリなどを回ってからチャイナタウンで夕食にして帰ったという。街に何十とあった主張の強い無料新聞を読むのが好きで、賛成か反対かに関係なく、意見を雄弁に語る文章に引き込まれたそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（8:52〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=532s"]]}, {"cat": "リングに来るまで", "t": "昼休みの電話1本でプレスパスを得た", "b": "小さな新聞のスポーツ欄で、当時の団体トップのビンス・マクマホン・シニアが試合後に通う店を知った。学校の昼休みに家へ走って帰り、低い声を生かして記者を名乗り「店で会ってパスをもらう約束をした」と電話したという。15歳でマディソン・スクエア・ガーデンの取材パスを手にしたと話す。それ以前から近くの会場で椅子並べや売店の準備を手伝い、リングサイドで撮影させてもらっていたそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（11:14〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=674s"]]}, {"cat": "好きなもの", "t": "自然光で撮る白黒写真が好きだった", "b": "当時は高感度のフィルムで、フラッシュなしの白黒写真を撮るのが好きだったという。通路で話していたビンス・シニアとアンドレ・ザ・ジャイアントを低い位置から36枚撮り、うち数枚がのちに有名なアンドレの写真になったと話す。狙った構図ではなく、追い出される前に必死で撮っただけだそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（20:16〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=1216s"]]}, {"cat": "リングに来るまで", "t": "写真の使用許諾書を添えて売り込んだ", "b": "弁護士の父に写真の使用許諾書を書いてもらい、プリントと一緒に封筒に入れてビンス・シニアに手渡そうとしたところ、警備員につまみ出されかけたという。リングアナのハワード・フィンケルが割って入り、シニアから交通費として50ドルを渡されて、毎月写真を持ってくるよう言われたそうだ。この経験から、のちに自分の団体を持ってからも、自分の控室でさえ常にパスを首から下げていたという。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（22:37〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=1357s"]]}, {"cat": "家族", "t": "ホロコースト生還者の母とブロンクスの父", "b": "母はホロコーストの生還者、父は大恐慌の時代にブロンクスの路上で育った人だという。そのため、どんなにひどい一日でも明日の朝を迎えられればチャンスはある、という考えが生まれたときから身についていると話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（33:13〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=1993s"]]}, {"cat": "家族", "t": "子どもが健康なら、それで十分", "b": "子どもが生まれてから「恵まれている」と口にするようになった。ブロック・レスナーと訪ねた難病の少年から「残りの時間を一瞬も惨めに過ごしたくない」と聞かされ、帰宅して子どもを抱きしめずにいられなかったという。子どもたちが健康であることが全てで、あの言葉は持ちネタではないと話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（35:34〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=2134s"]]}, {"cat": "家族", "t": "親としては自分の両親にかなわない", "b": "親のくじ引きでは大当たりで、最高の父と母に恵まれたと話す。自分はあの二人のような親にはなれないが、娘と息子の父親にふさわしい人間でいることが毎日の目標だという。失敗したら子どもに隠さず見せ、同じ失敗を二度しなければいいと教えているそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（42:46〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=2566s"]]}, {"cat": "暮らし", "t": "殿堂入りを4回断っていた", "b": "現役のうちは受けないつもりで、殿堂入りを4回辞退していたという。子どもたちから、死後に自分たちが代わりにスピーチする羽目になるのは嫌だと言われていたことも、受けた理由のひとつだと笑って話す。スピーチは子どもの話から始めると決めていたが、ほぼ即興だったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（49:06〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=2946s"]]}, {"cat": "暮らし", "t": "冬でもロングのレザーコートは着ない", "b": "殿堂入りを機に、革ジャンや帽子、ヘッドセットといった昔のトレードマークは引退させたと考えているという。冬に出かけるときも、あの姿の男になってしまうので、ロングのレザートレンチは着ずに別の暖かいコートを選ぶそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（54:45〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3285s"]]}, {"cat": "リングに来るまで", "t": "自分の団体では7年半無給だった", "b": "1993年から2001年まで自分の団体を率い、全ての決定を自分が下していたという。選手への支払いに苦労しながらも、会社の金を持ち出すことはせず、7年半自分には一度も給料を払わなかったと話す。最後は自身も破産したそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:17:22〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=4642s"]]}, {"cat": "体のこと", "t": "子どものころADHDと診断された", "b": "1965年生まれで、小学生のときにADHDと診断され、特別支援学級を勧められたという。父は成績に問題がないことを確かめると「障害ではなく、同時にいくつもこなせるということだ」と学校に言い返し、普通のクラスに戻されたそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:30:10〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=5410s"]]}, {"cat": "体のこと", "t": "音楽を流して集中、20時間座り続けることも", "b": "話すときは周りを見回しながら聞く方が頭に入るといい、作業中は音楽を大音量で流して集中するという。少しの物音でも気が散った母とは正反対だそうだ。一度没頭すると、食事もトイレも忘れてパソコンの前に20時間座り続けることもあると話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:33:25〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=5605s"]]}, {"cat": "家族", "t": "母はポーランドのゲットーから生還した", "b": "母はポーランドのウッチで育ち、戦時中にゲットーで多くの親族を失った。1944年8月にアウシュビッツへ送られ、到着時の選別で母親と7歳の妹と引き離されて二人を亡くしたという。死の行進を経て1945年4月に解放されたあとも重い病で生存率1割と言われたが生き延び、ベルリンの難民病院で看護師として働いたそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:36:47〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=5807s"]]}, {"cat": "家族", "t": "大叔父が毎年探しに来て母を見つけた", "b": "戦前に国を出た母の叔父は、毎年1週間分の休みと貯金を使ってポーランドへ親族を探しに行っていたという。1949年にベルリンの病院を訪ねて看護師をしていた母を見つけ、カナダへ連れ帰った。母はそこからアメリカへ移ったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:40:53〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=6053s"]]}, {"cat": "家族", "t": "母の墓石には祖母と叔母の名も刻んだ", "b": "母は自分のためだけでなく、亡くした妹の分まで生きた人で、墓石には母の名と並べて祖母と叔母の名も刻まれているという。どんな幸せな日も心から喜びきれなかった母が、自分のバル・ミツワー（成人の儀式）の日だけは一日中笑っていて、写真の母はどれも満面の笑みだと話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:42:35〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=6155s"]]}, {"cat": "家族", "t": "「私たちが帰らなくても前へ進め」", "b": "一人っ子だった彼に、両親が週末の夜に出かける前、母は毎回「もし事故で帰らなくても、悲しんだら前に進みなさい」と話して聞かせたという。今なら重すぎると言われそうだが、何も恐れない性格はこの教えで形づくられたと話す。同じ教えを自分の子どもたちにも伝えているそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:45:45〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=6345s"]]}, {"cat": "家族", "t": "両親は出会って半年で結婚、食卓は議論の場", "b": "両親は1960年にブロンクスのパーティーで出会い、半年後に結婚、その5年後に彼が生まれた。母は40代で大学に入り直して首席で卒業した人で、父は飛び級で16歳で高校を出て海軍に入り、のちにブロンクスで個人営業の弁護士をしていたという。知性で張り合う二人で、夕食の席はいつもニュースをめぐる議論だったそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:50:29〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=6629s"]]}, {"cat": "家族", "t": "母の最期の夜、父が泣いた言葉", "b": "母が亡くなる前夜、父と二人で寝ずに付き添ったという。明け方に父が泣きながら惜しんだのは、妻の美しさではなく、孫たちがもう触れられなくなる母の「美しい頭脳」だったと話す。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（1:57:42〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=7062s"]]}, {"cat": "家族", "t": "60歳の父として子どもに伝えること", "b": "自分の失敗談は「やってはいけないこと」として、21歳と23歳の子どもたちに話しているという。娘が生まれたとき、父から「自分より大切なものを愛するようになる」と言われ、その言葉は一瞬たりとも外れていないと話す。仕事には執念を燃やす一方で、それは「まともな仕事に就きたくなかった」結果にすぎず、本当に意味があるのは子どもたちとの関わりの方だそうだ。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-Z1B9yqhj7Go", "src": [["公式YouTube（2:05:44〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=7544s"]]}]);
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "一緒に難病の少年を見舞った", "b": "余命わずかと言われた少年をブロック・レスナーと訪ね、少年は「年間最大の祭典に行く」と約束した。その後の記者会見の会場に少年が現れ、控室でブロックに抱きついて「ほら来たよ」と笑ったと、ポール・ヘイマンが話している。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で、ポール・ヘイマンの話（公式字幕を全文確認）", "src": [["公式YouTube（36:19〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=2179s"]], "by": "第三者の話"});
  if (PROFILES["Roman Reigns"]) PROFILES["Roman Reigns"].facts.push({"cat": "暮らし", "t": "殿堂入りの紹介役を務めた", "b": "殿堂入りの式でゲストを紹介したのはローマン・レインズで、業界の頂点にいた彼が引き受けてくれたことに息をのんだと、ポール・ヘイマンが話している。長く組んだ二人にとって、とても感情的な週末だったという。", "sp": "ポール・ヘイマン", "d": "2025-11-13", "how": "ステファニーの番組で、ポール・ヘイマンの話（公式字幕を全文確認）", "src": [["公式YouTube（52:21〜）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go&t=3141s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-Z1B9yqhj7Go", d: "2025-11-13", show: "wys", who: ["Paul Heyman"], t: "ポール・ヘイマンの回　写真少年の始まり、母の生還、子どもたちへの教え", lead: "ステファニー・マクマホンの番組に出た約133分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Paul Heyman"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-Z1B9yqhj7Go").map((x) => [x.t, x.b, x.sp])), open: ["制作会議での聞き手との衝突や、ほかの選手の起用・育成の話は筋書き寄りのため省いた。", "子どもたちの名前と、母の親族の個人名は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=Z1B9yqhj7Go"]] });
  if (!ROSTER.find((r) => r[1] === "Tatum Paxley")) ROSTER.push(["テイタム・パクスリー", "Tatum Paxley", "lg", "NXT女子王者", "", "", ""]);
  if (!PROFILES["Tatum Paxley"]) PROFILES["Tatum Paxley"] = { lead: "パワーリフティングの選手から転身し、不安定さも含めて自分だと語るテイタム・パクスリー。家では夫と静かに過ごすのが一番の幸せだという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Tatum%20Paxley"]], moves: [], facts: [] };
  if (PROFILES["Tatum Paxley"]._weak) { PROFILES["Tatum Paxley"].lead = "パワーリフティングの選手から転身し、不安定さも含めて自分だと語るテイタム・パクスリー。家では夫と静かに過ごすのが一番の幸せだという。"; delete PROFILES["Tatum Paxley"]._weak; }
  PROFILES["Tatum Paxley"].facts.push(...[{"cat": "リングの話", "t": "会社が自分を知るきっかけをくれた", "b": "契約した当時は、自分が何者なのかまだはっきり分かっていなかったとテイタムは話す。この会社で過ごすうちに自分を掘り下げ、精神面も大きく鍛えられたという。数々の壁にぶつかる環境だからこそ強くなれたそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（1:39〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=99s"]]}, {"cat": "リングの話", "t": "キャラクターは素の自分そのもの", "b": "リング上で見せる姿は、そのまま本当の自分だとテイタムは話す。気分が極端に高い日も低い日もあり、不安が強く、強さと弱さが入れ替わる人間だという。その不安定さこそ多くの人が共感できる部分で、観客とつながれたことが一番の誇りだそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（2:26〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=146s"]]}, {"cat": "リングに来るまで", "t": "全米大会を目前に、プロレスの道へ", "b": "以前はパワーリフティングの選手で、全米大会の出場資格を得たところだったという。ただ、何かが足りない気がしてプロレスを探し始め、その約1か月後にラスベガスでの入団テストの誘いが届いたそうだ。結局、全米大会には出ないままプロレスに進んだと話す。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=238s"]]}, {"cat": "リングに来るまで", "t": "プロレスとは無縁で育った", "b": "家にプロレス文化があったわけではなく、興味を持ったのは契約の2年ほど前だという。YouTubeで女子の試合を見あさり、母と一緒に女子レスラーのリアリティ番組も見ていたと話す。いま取材を受けていること自体が信じられないそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=287s"]]}, {"cat": "リングに来るまで", "t": "チアとパワーリフティングが土台に", "b": "人生の大半はチアリーディングに打ち込み、その後にパワーリフティングをしていたという。運動面では役立ったが、プロレスは想像よりずっと難しい別世界だったと話す。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（5:37〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=337s"]]}, {"cat": "リングに来るまで", "t": "体操の経験がリングでの度胸に", "b": "子どもの頃に体操をしていたので、宙返りやバネを使う動きを怖がらずにできるのだとテイタムは話す。体操の経験が、リングで恐れずに動ける理由の一つだと感じているそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（8:03〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=483s"]]}, {"cat": "家族", "t": "結婚して1年、暮らしは穏やか", "b": "9月に結婚1周年を迎えたとテイタムは話す。結婚後も生活は前とほとんど変わらず、夫のランディとは好みが合って、とても穏やかに過ごしているという。この人しかいないと思えたと語る。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=674s"]]}, {"cat": "家族", "t": "夫とは入団テストで出会った", "b": "結婚相手がレスラーになるとは思っていなかったと笑う。夫は入団テストに関わっていて、温かく安心できる雰囲気に引かれたそうだ。交際が始まるまでには約1年かかったという。母には「入団したら夫に会えるかも」と言われていたそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（12:02〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=722s"]]}, {"cat": "暮らし", "t": "理想の休日は家で夫と映画", "b": "出かけるより、家で夫と過ごすのが一番好きで、できれば映画を見ていたいとテイタムは話す。夫が連れ出してくれなければ、ほとんど外に出ないそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（13:35〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=815s"]]}, {"cat": "好きなもの", "t": "誕生日はハロウィーンの催しとお寿司", "b": "誕生日には夫に誘われて、ハロウィーンの大型ホラーイベントへ出かけ、お寿司も食べたという。3時間並んだせいか、思ったほど怖くなかったそうだ。ホラー映画は夫婦そろって好きだが、本当は怖がるのは苦手だと話す。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（13:35〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=815s"]]}, {"cat": "リングの話", "t": "完璧でない王者でいたい", "b": "自分は今も欠点だらけで、気分の波も大きいとテイタムは話す。それでも王座を持つことで、自分の思考と向き合って乗り越えられると示したいという。完璧でなくても最善を尽くす姿を、王座が表すものにしたいそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（16:06〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=966s"]]}, {"cat": "リングの話", "t": "王座を渡してくれた相手との再戦を望む", "b": "王座を奪った相手のJC・ジェーンに、もう一度挑みたいとテイタムは話す。熱い闘志をむき出しにする相手で、リングで向き合うとこちらの闘志も引き出されるという。二人とも誰にも期待されず、陰で長く努力してきた点が似ているそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（18:35〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1115s"]]}, {"cat": "リングの話", "t": "初めてのマディソン・スクエア・ガーデン", "b": "マディソン・スクエア・ガーデンで試合をするのはこれが初めてだという。ここで戦って初めて一人前、という言い伝えがレスリング界にあると聞かされ、喜んでいるそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（20:07〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1207s"]]}, {"cat": "リングの話", "t": "観客まで不安にさせる王者", "b": "普通の王者は「任せて安心」と思われるが、自分の場合は観客が「今日はどのテイタムだろう」とハラハラするのだとテイタムは話す。その空気も含めて面白いと感じているそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（20:53〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1253s"]]}, {"cat": "体のこと", "t": "肌荒れをきっかけにスキンケアの虫に", "b": "以前は化粧をしたまま寝るなど、肌の手入れに無頓着だったという。1年ほど前にひどい肌荒れが顔全体に出て、テレビに映る仕事だけに焦ったそうだ。肌をいじる癖もあったが、エステティシャンに出会って改善し、今は朝晩欠かさないと話す。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（22:24〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1344s"]]}, {"cat": "好きなもの", "t": "行きたい場所はコスタリカ", "b": "新婚旅行で訪れたコスタリカが、人生で一番幸せだった場所だとテイタムは話す。夫と毎日のように「また行きたい」と言い合っているそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（24:02〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1442s"]]}, {"cat": "リングの話", "t": "盗みたい技はJC・ジェーンの回転式ラリアット", "b": "自分の技にしたいのは、JC・ジェーンのローリング・エンコアだとテイタムは話す。いつでも不意に出せる単純な技で、彼女の威力が本物だからだという。試合で自分も試したが相手を倒せず、受ければ自分は倒れてしまうそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（24:51〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1491s"]]}, {"cat": "リングに来るまで", "t": "レスラーでなければパワーリフターに", "b": "プロレスをしていなければ、どこかでパワーリフティングを続けていただろうとテイタムは話す。昔から、将来何をしたいのか分からなかったそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（25:39〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1539s"]]}, {"cat": "暮らし", "t": "試合前のウォリアーポーズと左右そろえる癖", "b": "リングに向かう前にウォリアーのポーズをしないと落ち着かないという。ゲームをしているときなどに、片側に感じたものを反対側でも感じないとバランスが悪く思える癖もあるそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（26:29〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1589s"]]}, {"cat": "リングの話", "t": "一番の思い出は初めての王座戴冠", "b": "NXTでの一番の思い出は、ハロウィーン前後の大会で女子王者になった瞬間だとテイタムは話す。突然で、感動的で、一生忘れないと語る。初めてここで王者になれた日だそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（27:20〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1640s"]]}, {"cat": "リングの話", "t": "座右の銘は「重さを信じ、予想外を楽しむ」", "b": "WWEで過ごす中で大切にしてきた言葉だとテイタムは話す。プロレスは予想外の連続なので、期待しすぎず、何が起きても受け止めて楽しむようになったという。力を抜き、流れを信じる姿勢をこの会社で学んだそうだ。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で（字幕を全文確認）", "art": "ext-ea0O-bFLl50", "src": [["番組のYouTube（28:09〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1689s"]]}]);
  if (PROFILES["JC Jane"]) PROFILES["JC Jane"].facts.push({"cat": "暮らし", "t": "JC・ジェーンは闘志があふれる好敵手", "b": "JC・ジェーンは熱い闘志を持つ競技者で、リングで向き合うと目の力まで伝わってくると、テイタムが話している。自分と同じく、陰で長く努力してきた人だとも語っている。", "sp": "テイタム・パクスリー", "d": "2025-11-17", "how": "ニッキ＆ブリーの番組で、テイタム・パクスリーの話（字幕を全文確認）", "src": [["番組のYouTube（18:35〜）", "https://www.youtube.com/watch?v=ea0O-bFLl50&t=1115s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-ea0O-bFLl50", d: "2025-11-17", show: "ext", who: ["Tatum Paxley"], t: "テイタム・パクスリーの回　弱さも不安定さも自分らしさ", lead: "ニッキ＆ブリーの番組に出た約31分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Tatum Paxley"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ea0O-bFLl50").map((x) => [x.t, x.b, x.sp])), open: ["宣伝やスポンサー読み、同席者どうしの子育て・体操の雑談は省いた。", "字幕で崩れていて確信が持てない人名（初防衛戦の相手など）は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ea0O-bFLl50"]] });
  if (!PROFILES["AJ Lee"]) PROFILES["AJ Lee"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=AJ%20Lee"]], moves: [], facts: [] };
  if (PROFILES["AJ Lee"].lead === "") PROFILES["AJ Lee"]._weak = 1;
  PROFILES["AJ Lee"].facts.push(...[{"cat": "リングの話", "t": "女子部門の待遇を王者の立場から訴えた投稿", "b": "AJ・リーは、女子部門がまだ厳しい位置にいた頃、男女の賃金格差について率直な投稿をしたと話す。当時は王者で、失うものも多かったが、変化には犠牲が必要で、無難にやっていては特別な人生にならないと考えたという。のちにステフ・マクマホンも、その動きが女性たちの進化を後押ししたと語っている。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:44〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=104s"]]}, {"cat": "リングの話", "t": "女性レスラーの先輩たちに憧れた少女時代", "b": "AJ・リーは、レスリングでは特にチャイナ、リタ、モリー・ホリーのような強い女性に憧れたと話す。機会が少ない時代に男性の中で堂々と戦う姿が励みになり、男性ではエディ・ゲレロとロディ・パイパーも好きだったそうだ。やんちゃで憎めない人物に惹かれたという。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（16:15〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=975s"]]}, {"cat": "リングの話", "t": "新人時代に助けてくれた先輩たちの優しさ", "b": "AJ・リーは、1日に4試合をこなした新人の頃、ベス・フェニックスが上層部に掛け合ってくれたことが忘れられないと話す。ウェブ番組時代のNXTでは笑われるような企画が続いて落ち込んだが、レイラが身支度を手伝ってくれたという。この経験から、新人が歓迎されるよう気を配ってきたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（27:36〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1656s"]]}, {"cat": "リングの話", "t": "楽屋で声をかけてくれた人たちへの感謝", "b": "AJ・リーは、地方巡業に出たばかりの頃にマリアが一緒に練習してくれたことや、初対面のミッキー・ジェームスが皆の前で抱きしめてくれたことを挙げる。その安心感は今も忘れられず、最近その気持ちを本人にメッセージで伝えたという。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（30:50〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1850s"]]}, {"cat": "リングの話", "t": "双極性障害を隠したまま立ったテレビの舞台", "b": "AJ・リーは、19歳で診断を受け、21歳でWWEと契約したと話す。薬やカウンセリングにお金をかけられず、仕事を失うことを恐れて誰にも話せなかったという。高いプレッシャーのテレビの世界で症状が悪化しやすく、本格的に治療に向き合えたのは引退後だったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（34:01〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=2041s"]]}, {"cat": "リングの話", "t": "復帰時の演説で起きた「セラピー」コール", "b": "AJ・リーは、復帰後の演説で観客から「セラピー」のチャントが起きたことに本当に驚いたと話す。思わずその場で言葉を返し、プロレスの客席がそこまで心に寄り添ってくれることに感動したという。この場面を見て実際にセラピーを始めた人もいると聞いたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:02:36〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3756s"]]}, {"cat": "リングの話", "t": "試合の流れは脚本と同じ物語の構造", "b": "AJ・リーは、試合の組み立ては脚本とほぼ同じ構造だと話す。山と谷があり、観る人の心をつかんで応援させる普遍的な物語の技法だという。子どもの頃から希望だった物語やヒーローの世界に、自分もいつか入れると思っていたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:11:22〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=4282s"]]}, {"cat": "リングの話", "t": "初めての試合で肺炎、足の骨折も経験", "b": "AJ・リーは、インディー団体での最初の試合の後、痩せすぎていたために肺炎になったと話す。2週間後に練習へ戻ったがすぐに足を骨折し、自分はもろいと感じたという。WWEの育成施設でウエイトトレーニングを始め、体が変わっていくのが楽しかったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:17:40〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=4660s"]]}, {"cat": "リングの話", "t": "初めてのキスはテレビの中、その後に机へ叩きつけた", "b": "AJ・リーは、のちに夫となる人との最初のキスが放送されたストーリーの中だったと話す。そのあと夫を机に叩きつけたとも明かし、実際に交際したのはストーリーの2年ほど後だという。NXTで実況を務めていた頃から、仲間として自分を立ててくれていたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:33:44〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=5624s"]]}, {"cat": "リングの話", "t": "復帰戦では役が体に降りてきた", "b": "AJ・リーは、復帰後の入場でキャラクターが自然と戻ってきて、スキップも体が覚えていたと話す。次は大人数の団体戦で、30分近い試合や檻の試合に挑むつもりだそうだ。かつて檻の中でブリーフケースを投げて審判の腕を痛めた思い出があり、今回は新しい記憶にしたいという。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:39:29〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=5969s"]]}]);
  if (!PROFILES["AJ Lee"]) PROFILES["AJ Lee"] = { lead: "極貧とホームレス生活の少女時代を、プロレスとコミックを心の支えに生き抜いた。双極性障害を公表し、心の健康を語る講演や脚本・制作の仕事にも力を注いでいる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=AJ%20Lee"]], moves: [], facts: [] };
  if (PROFILES["AJ Lee"]._weak) { PROFILES["AJ Lee"].lead = "極貧とホームレス生活の少女時代を、プロレスとコミックを心の支えに生き抜いた。双極性障害を公表し、心の健康を語る講演や脚本・制作の仕事にも力を注いでいる。"; delete PROFILES["AJ Lee"]._weak; }
  PROFILES["AJ Lee"].facts.push(...[{"cat": "家族", "t": "10代の両親のもとで育った", "b": "ニュージャージー州の出身。両親は子どもを持ったとき17歳ほどで、大人として子を育てる術を教わっていなかったという。銀行口座の開き方を自分で覚えて親に教えるなど、家族みんなで手探りで暮らしを学んだと話す。両親を責めるのでなく、若すぎたのだと理解できたのは大人になってからだそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（7:20〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=440s"]]}, {"cat": "暮らし", "t": "車やポーチで寝たホームレス生活", "b": "とても貧しく、人生の大半は家がなかったという。車の中や、知人が貸してくれたガレージや網戸付きのポーチ、モーテルを転々とし、冬もそこで過ごした。家族は両親と兄姉2人の5人で、本人は末っ子。つらい話ではあるが、大切なものを教えてくれた経験として誇りを持って語っているという。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（8:58〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=538s"]]}, {"cat": "好きなもの", "t": "愛犬はピットブルのマグジー", "b": "ホームレス時代も、家族と一緒に45キロほどある大きなピットブルを連れていた。名前はマグジーで、「人生最愛の存在」と話す。車の後部座席で身を寄せ合って眠ることもあり、食事は自分より先に必ず犬にあげていたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（8:58〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=538s"]]}, {"cat": "暮らし", "t": "14歳で清掃の仕事をして家計を支えた", "b": "14歳のとき、保育施設で清掃員として働いて家の支払いを助けていたという。暖房が止められてコンロとオーブンを開けて部屋を温めたり、お湯を沸かして体を洗ったりするのも当たり前だった。当時はそれが普通だと思っていて、セラピーを通じてようやく「大変な状況だった」と気づいたと話す。ドーナツ店の売れ残りのマフィン1個や学校の給食が、その日唯一の食事という日もあったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（10:37〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=637s"]]}, {"cat": "リングに来るまで", "t": "辞書の白紙を綴じてノートにした", "b": "ノートを買えず、図書館の辞書の最初の白紙ページを集めてホチキスで留め、ノート代わりにしていたという。それでも成績は学年トップ。奨学金を取って自力で抜け出すしかないと幼いころから考え、末っ子ながら家族みんなを支えるのは自分だと感じていたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（12:13〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=733s"]]}, {"cat": "好きなもの", "t": "逃げ場だったコミックとプロレス", "b": "プロレス、コミック、テレビゲームは、つらい現実を忘れさせてくれる「命を救ってくれたもの」だったという。マーベルの『X-MEN』の「ダーク・フェニックス・サーガ」をバービー人形で再現して遊び、好きなヒロインはジーン・グレイや『バイオハザード』のジル・バレンタイン。プロレスではチャイナ、リタ、モリー・ホーリーら強い女性にあこがれ、男子ではエディ・ゲレロやロディ・パイパーのような型破りないたずら者が好きだったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（16:15〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=975s"]]}, {"cat": "体のこと", "t": "強い不安症と社交不安を抱える", "b": "ひどい不安症と社交不安があり、昔から友だちを作るのが苦手だという。学校の食堂に自分の居場所がない子だったので、「他人のテーブルに合わせなくていい、自分でテーブルを作って誰でも招けばいい」という考えで生きてきたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（25:12〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1512s"]]}, {"cat": "リングに来るまで", "t": "心細い時期に助けてくれた先輩たち", "b": "新人のころ、一晩に4試合をこなしたのを見たベス・フェニックスが、会社の担当者に「彼女の頑張りを見てほしい」と掛け合ってくれたという。育成番組の時代には、レイラが安い量販店のドレスを着ていた自分に身なりを整える手助けをしてくれた。育成施設で一緒に練習してくれたマリアにも感謝していて、こうした親切を忘れないため自著にも記したそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（27:36〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1656s"]]}, {"cat": "体のこと", "t": "双極性障害とともに生きる", "b": "19歳ごろに双極性障害と診断されたという。家族にも同じ病があり、母親も苦しんでいたと後に分かったそうだ。当時は薬やセラピーのお金がなく、知られたら職を失うと思って誰にも言えなかった。同期のケイトリンだけは、車から出られず泣いていた自分の異変に気づいていたと話す。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（32:30〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1950s"]]}, {"cat": "リングに来るまで", "t": "学費が払えずNYUを半年で離れた", "b": "文章を書くのが好きで、ニューヨーク大学で映画・テレビ制作を学んだが、学費が払えず半年で辞めたという。もうひとつの好きなものだったプロレスの道へ進み、インディー団体で2年ほど戦った末、21歳ごろにWWEと契約したそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（34:01〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=2041s"]]}, {"cat": "体のこと", "t": "うつ病と誤診され命の危機も", "b": "本格的な治療を始めたのは引退後。最初はうつ病と誤診され、合わない薬で状態がかえって悪化し、何度か命を落としかけたという。自分に合う治療と薬、生活の組み立てにたどり着くまで闘わなければならなかったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（35:37〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=2137s"]]}, {"cat": "体のこと", "t": "著書で公表、初めての白髪", "b": "双極性障害を初めて公にしたのは著書『Crazy Is My Superpower』で、全米ベストセラーになったという。発売1週間前に自分のサイトで告知したときは極度に緊張し、初めて白髪が出たと笑う。いまは全米の精神保健団体で講演を行い、啓発活動にも関わっている。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（37:12〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=2232s"]]}, {"cat": "体のこと", "t": "心の中の暗い声に「ジーン」と名付ける", "b": "自分を責める暗い声には名前を付けるとよいと話す。ミドルネームのジャネットから「ジーン」と呼び、「ジーンは嘘つき」と言い聞かせて自分とは切り離すのだという。つらい日には夫と「今日はジーンの機嫌が悪い」と冗談を言い合うそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（48:13〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=2893s"]]}, {"cat": "体のこと", "t": "深いうつを抜けて自分を好きになれた", "b": "5年ほど前、危険なほど深いうつの時期があり、一度死んで生まれ変わったように感じたという。抜け出す過程で、弱っている自分を抱きしめるように受け入れ、自分を深く愛せるようになったそうだ。病は治って終わりではなく、今も毎日向き合い続けていると話す。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（52:15〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3135s"]]}, {"cat": "暮らし", "t": "脚本・制作・出演と広がる仕事", "b": "初めて脚本を書いた『ブレイド・オブ・ザ・47ローニン』はNetflixで上位に入ったという。俳優としても映画やドラマに出演。ラテン系の脚本パートナーと制作会社「スクラッピー・ハート・プロダクションズ」を立ち上げ、短編がトライベッカ映画祭に選ばれたほか、母娘が謎を追う小説も出した。心の病を題材にしたホラーの長編脚本も単独で書き上げたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（54:41〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3281s"]]}, {"cat": "好きなもの", "t": "大のアニメ好き、東映の映画を執筆中", "b": "アニメが大好きで、『美少女戦士セーラームーン』や『ドラゴンボールZ』で育ったという。その東映アニメーションのために映画を書いていると、この番組で初めて明かした。オフィスにドラゴンボールのフィギュアが並ぶのを見て「ここに住みたい」と思ったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（56:15〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3375s"]]}, {"cat": "暮らし", "t": "サイン会は7時間、来た人全員と話す", "b": "不安症があるため、人前に出た後はネットを見ずにクールダウンする時間を取っているという。それでもサイン会では並んだ人全員に対応すると決めていて、2時間の予定が7時間になったこともあるそうだ。ファンからの手紙はすべて取ってあり、全部読んでいると話す。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:04:11〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3851s"]]}, {"cat": "体のこと", "t": "HIITと「ごほうびの日」の食事", "b": "現役後半は重いウエイトリフティングで体が悲鳴を上げ、うつの時期には体重も増えたという。今は週4〜5回、ダンベルとヨガマットだけでできる短い高強度インターバルトレーニングを続け、腹筋は週1日、ダンベルを持って行う。厳しい食事制限は反動で過食してしまうため、好きなものを食べる日は「チートデイ」でなく「トリートデイ」と呼んでいるそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:13:39〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=4419s"]]}, {"cat": "リングに来るまで", "t": "ぜんそく持ち、初試合で肺炎", "b": "子どものころはぜんそくがあり栄養も足りず、スポーツは何もできなかったという。インディーで初めて試合をしたときは、やせすぎていてすぐに肺炎になり、2週間後に練習へ戻るとすぐ足を骨折した。本格的な筋トレは育成施設で初めて覚え、体重の2倍を挙げるスクワット記録を作ったこともあるそうだ。今もぜんそく用の吸入器は念のため持ち歩いているという。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:17:40〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=4660s"]]}, {"cat": "家族", "t": "夫との暮らしは大切にしまっておく", "b": "結婚そのものには懐疑的だったが、夫とは「チームメイト」だと感じ、交際から2か月ほどで結婚したという。心の病については多くを語るぶん、夫婦のことは自分たちだけのものとして守りたいと考え、SNSにもあまり載せないそうだ。夫は反対に気持ちを隠さないタイプだと話す。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-xGjKoYIzKdc", "src": [["公式YouTube（1:36:13〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=5773s"]]}]);
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "育成番組でAJをかばった実況席", "b": "育成番組で解説を務めていたころ、ほかの人が出場者をけなすなか「でもAJはいい」と一人だけ持ち上げてくれたと、AJリーが話している。共演時の生放送のバックステージでは、台本の意地悪な台詞を言わずにアドリブで口説いてかばってくれたという。友人として何年か過ごした後に交際し、2か月ほどで結婚。家族との時間を隠さずSNSに載せる、愛情表現の豊かな人だと、AJリーが話している。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で、AJリーの話（公式字幕を全文確認）", "src": [["公式YouTube（1:35:24〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=5724s"]], "by": "第三者の話"});
  if (PROFILES["Lita"]) PROFILES["Lita"].facts.push({"cat": "暮らし", "t": "少女AJの手紙を受け取ったリタ", "b": "AJが初めて行ったサイン会の相手がリタで、手紙を渡すと「必ず読むね」と受け取り、使っていたペンをくれたという。当時のAJは食べるものにも困りモーテル暮らしだったが、リタの温かい対応がなければプロレスを嫌いになっていたかもしれないと、AJリーが話している。そのペンは何年も大切に持っていたそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で、AJリーの話（公式字幕を全文確認）", "src": [["公式YouTube（1:05:46〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=3946s"]], "by": "第三者の話"});
  if (PROFILES["Mickie James"]) PROFILES["Mickie James"].facts.push({"cat": "暮らし", "t": "初巡業の日に抱きしめてくれたミッキー", "b": "一人で初めてスマックダウンの巡業に加わり不安だった日、面識のなかったミッキー・ジェームスが皆の前で大きなハグをしてくれたと、AJリーが話している。インディー出身者が少なかった時代で、守ってもらえたと感じたという。最近になって本人に感謝のメッセージを送ったそうだ。", "sp": "AJリー", "d": "2025-11-24", "how": "ステファニーの番組で、AJリーの話（公式字幕を全文確認）", "src": [["公式YouTube（30:50〜）", "https://www.youtube.com/watch?v=xGjKoYIzKdc&t=1850s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-xGjKoYIzKdc", d: "2025-11-24", show: "wys", who: ["AJ Lee"], t: "AJリーの回　極貧の少女時代と、双極性障害とともに生きること", lead: "ステファニー・マクマホンの番組に出た約104分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["AJ Lee"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-xGjKoYIzKdc").map((x) => [x.t, x.b, x.sp])), open: ["AJリーがかつてSNSで女子選手の待遇改善を訴えた件と、聞き手との関係をめぐる冒頭のやりとりは、選手の素顔から外れるため載せていない。", "復帰戦や今後の試合についての話、聞き手ステファニーの家族の話（後半の長いくだり）は載せていない。", "精神保健の支援窓口や有色人種コミュニティの受診の壁など、AJリーが紹介した社会問題・支援団体の詳しい話は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=xGjKoYIzKdc"]] });
  if (!ROSTER.find((r) => r[1] === "Kelani Jordan")) ROSTER.push(["ケラーニ・ジョーダン", "Kelani Jordan", "lg", "NXT所属の元体操選手", "", "", ""]);
  if (!PROFILES["Kelani Jordan"]) PROFILES["Kelani Jordan"] = { lead: "体操の名門大学からWWEに飛び込み、ペット7匹と暮らす素顔のケラーニ・ジョーダン。人を楽しませたい気持ちと、少し心配性な一面を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kelani%20Jordan"]], moves: [], facts: [] };
  if (PROFILES["Kelani Jordan"]._weak) { PROFILES["Kelani Jordan"].lead = "体操の名門大学からWWEに飛び込み、ペット7匹と暮らす素顔のケラーニ・ジョーダン。人を楽しませたい気持ちと、少し心配性な一面を語った。"; delete PROFILES["Kelani Jordan"]._weak; }
  PROFILES["Kelani Jordan"].facts.push(...[{"cat": "リングに来るまで", "t": "最初の師匠の言葉が今も支え", "b": "育成施設で最初に教わったコーチのノーマン・スマイリーから、始めて数週間で「君には華がある。アクセルを緩めるな」と言われたという。その一言が今でも心に残っていると話す。恋人のカーメロ・ヘイズやショーン・マイケルズも信じてくれた存在だそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（1:41〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=101s"]]}, {"cat": "リングの話", "t": "初代王座と、より自信をつけた王座", "b": "最初の女子中堅王座の初代王者になったが、実績を早く証明しなければという重圧が大きかったという。のちに別団体の王座を獲った時は「自分で勝ち取った」と思え、別人のように自信がついたと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（3:13〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=193s"]]}, {"cat": "リングに来るまで", "t": "ロープの痛みと、トライアウトの青あざ", "b": "年間最大級の大会の週に受けたトライアウトで、ロープを走る練習をして背中に大きな青あざができたという。痛くて眠れないほどで、受け身の練習もつらかったと話す。それでも「本物ではない」という声には、体の痛みがその証拠だと答えている。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（4:45〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=285s"]]}, {"cat": "リングに来るまで", "t": "偽物だと思ったスカウトのメッセージ", "b": "大学5年目で、進路は報道の仕事を考えていたという。WWEの採用担当からの連絡は認証マークつきでも本物とは思えず、母に相談したところ「受けてみなさい」と背中を押されたと話す。SNSのフォロワーも多くなく、なぜ自分が選ばれたのか分からなかったそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（5:35〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=335s"]]}, {"cat": "リングの話", "t": "悪役としての心の叫び", "b": "自分は正しい道を進もうとして周りに裏切られたから悪役になった、と考えているという。マイクでは観客の反応に応えられるよう練習中で、あの時は「自分の本音を話す」気持ちだったと語る。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（7:12〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=432s"]]}, {"cat": "リングに来るまで", "t": "報道志望の学びが話術に生きる", "b": "大学では報道を専攻し、スポーツ中継のキャスターを夢見ていたという。文章を書いて語る訓練や、カメラの前で話す経験が、今のマイクでの語りに大いに役立っていると話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（8:03〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=483s"]]}, {"cat": "体のこと", "t": "人間らしさを忘れないでほしい", "b": "テレビに出ていても、家に帰れば家族がいて、ネットの声も目に入る普通の人間だと話す。体操と同じく、プロレスも現実から離れられる場所になっていると語る。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（9:36〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=576s"]]}, {"cat": "体のこと", "t": "ネットの批判との向き合い方", "b": "始めた頃はネットの否定的な声が心に刺さったが、大きな名前の先輩に相談して折り合いをつけられるようになったという。今は「人は何を言ってもいろいろ言う」と受け流している。両親の言葉も支えになっていると話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（10:25〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=625s"]]}, {"cat": "リングの話", "t": "自然な髪で出る理由", "b": "体操の世界では髪をまっすぐに整えるのが上品とされ、自然なカールで出ることは長くなかったという。大学で自分らしさを受け入れ、プロレスでも巻き髪のまま、時にはアフロのように広げて試合に出ると話す。若い女性たちから感謝の声が届くそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（12:01〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=721s"]]}, {"cat": "リングに来るまで", "t": "体操の「完璧」とプロレスの「荒さ」", "b": "体操は完璧を目指す競技だが、プロレスは多少荒くても許されるところが違うと話す。一方で失敗の許される幅が小さい点は同じで、体操で重圧への強さが身についたという。ただ、観客の受け止め方が読めないぶん、プロレスのほうが緊張すると語る。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（13:39〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=819s"]]}, {"cat": "体のこと", "t": "人に喜ばれたい気持ちが強い", "b": "人を喜ばせたい性格で、自分や尊敬する人、両親をがっかりさせたくないと思うと話す。出番前に緊張しなくなったら気持ちが薄れた証拠だと教わり、大先輩でも同じだと聞いたそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（14:31〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=871s"]]}, {"cat": "リングの話", "t": "憧れの人にもファン気分を抑える", "b": "ジョン・シナが育成施設に来た時はファンとして興奮したが、同じ職業の仲間として礼儀を守り、写真を一枚頼むだけにしたという。ここは先輩たちが安心できる場所だから、取り囲まないのが暗黙のルールだと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（15:19〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=919s"]]}, {"cat": "リングの話", "t": "空中戦の発想の源", "b": "集団戦で場外から手で歩いてリングに戻る技を出したのは、体操の経験なら手で歩いて失格を避けられるはずと考えたからだという。コフィ・キングストンやナオミの動きを参考にし、派手にかわす自分のキャラクターに合うと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（16:51〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1011s"]]}, {"cat": "リングの話", "t": "危険な技は場面を選ぶ", "b": "高い所からの技も挑戦するが、巡業先の小さな興行では長く続けるために控えると話す。年間最大の祭典のような場なら全力を出すつもりだという。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（18:30〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1110s"]]}, {"cat": "リングの話", "t": "ロブ・ヴァン・ダムにもらった助言", "b": "憧れのロブ・ヴァン・ダムに会い、「人の目を気にせず自分らしくあれ」と言われたという。自分も彼自身も唯一無二の存在だからだそうだ。この助言を、王座を獲った時の言葉にも生かしたそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（19:15〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1155s"]]}, {"cat": "リングの話", "t": "次の目標はNXT女子王座", "b": "次に狙うのはNXTの女子王座だという。主力ブランドに上がれるなら、赤のブランドでは大陸間王座、青のブランドでは米国王座を狙いたいが、今は急いでいないと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（20:07〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1207s"]]}, {"cat": "リングの話", "t": "同じ立場の先輩が支えてくれる", "b": "ビアンカ・ベレアやジェイド・カーギルが手を貸してくれたことが心強かったという。同じ黒人女性として悩みを分かち合える「お姉さん」がいるのはうれしいと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（21:13〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1273s"]]}, {"cat": "暮らし", "t": "ペット7匹と暮らす", "b": "犬のヨギとダミアン、猫のランボー、シャドウ、ネモ、大学時代から飼うモルモットのポピー、ヒゲトカゲのソーサがいるという。子猫を見かけたら、もう3匹いても連れて帰ってしまいそうだと笑う。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（22:00〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1320s"]]}, {"cat": "家族", "t": "7人きょうだいの末っ子", "b": "大家族の末っ子として育ち、実家にも犬2匹、猫、ウサギ、ハムスター、カメ、大きな水槽と動物がたくさんいたという。動物好きは母ゆずりで、二人とも情にあついと話す。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（22:35〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1355s"]]}, {"cat": "暮らし", "t": "朝はペットの世話から始まる", "b": "忙しくても、ペットの世話は苦ではなく朝の習慣だと話す。犬の散歩のおかげで体も動かせるという。猫はベランダでトカゲを眺めて過ごすので、手がかからないそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（23:23〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1403s"]]}, {"cat": "好きなもの", "t": "好きな音楽はR&Bの定番と賛美歌", "b": "昔のR&Bが好きで、体操の仲間と曲を選ぶ時はいつもエイコンを挙げていたという。ほかにアッシャー、ホイットニー・ヒューストンの名も出した。最近は昔の曲に加えて、ゴスペルのような賛美の音楽もよく聴くそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（24:12〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1452s"]]}, {"cat": "好きなもの", "t": "ゲームはほどほど、運動と読書が趣味", "b": "最近スイッチを買い、移動のバスで遊ぶ程度だという。休日はオレンジセオリーやピラティスで体を動かすことが多く、スリラーや恋愛小説も読むと話す。最近は海外ドラマ「オール・アメリカン」を観ているそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（25:47〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1547s"]]}, {"cat": "好きなもの", "t": "一番好きな映画は「ヘアスプレー」", "b": "2007年のミュージカル映画「ヘアスプレー」が生涯のお気に入りだという。子どもの頃にDVDをなくして泣いたら、両親が買い直してくれたそうだ。ミュージカルが好きで、「ウィキッド」も高く評価している。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（27:20〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1640s"]]}, {"cat": "暮らし", "t": "自分のアクションフィギュアは夢のよう", "b": "自分の姿の人形が出たことは夢のようで、少し不思議な感覚だと話す。何体かサインもしたという。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（28:06〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1686s"]]}, {"cat": "暮らし", "t": "二人はプロレス界で一番のカップル", "b": "人気カップルの話題では、ケラーニ・ジョーダンはカーメロと自分たちが一番で、ベッキー・リンチとセス・ロリンズが二番だと答えている。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（28:51〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1731s"]]}, {"cat": "暮らし", "t": "婚約者カーメロ・ヘイズとの出会い", "b": "カーメロ・ヘイズとは入団して数か月で付き合い始めたという。最初は修行に集中したくて断ろうとしたが、母の助言もあり、気持ちに素直になったと話す。人前の印象とは違い、ぬいぐるみのように優しい人だそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（29:40〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1780s"]]}, {"cat": "暮らし", "t": "記念日のハワイでプロポーズ", "b": "7月1日の記念日にハワイを旅行し、夕食前の浜辺で音楽と花のハート形に迎えられたという。当日は夕日に間に合うよう彼が急かしていたが、本人は理由に気づかなかったと話す。靴のかかとで早歩きしたのも笑い話のようだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（30:27〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1827s"]]}, {"cat": "家族", "t": "父がくれた最初の聖書", "b": "幼い頃、父から子ども向けの聖書をもらい、「人から教われることは限られる。自分で読みなさい」と言われたと話す。枕の下に置いて寝ていたそうだ。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で（字幕を全文確認）", "art": "ext-8Qzgk9ni040", "src": [["番組のYouTube（34:26〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=2066s"]]}]);
  if (PROFILES["Carmelo Hayes"]) PROFILES["Carmelo Hayes"].facts.push({"cat": "暮らし", "t": "シナ戦をかけた大会での優勝予想", "b": "ジョン・シナと戦う権利をかけた大会でカーメロ・ヘイズが優勝すると信じている、とケラーニ・ジョーダンが話している。若くて将来性があり、シナが数年前に育成施設で入場に付き添ったことや、同じボストン出身であることから「原点に戻る瞬間」になると語っている。", "sp": "ケラーニ・ジョーダン", "d": "2025-12-04", "how": "ジャスティン・スタッキーの番組で、ケラーニ・ジョーダンの話（字幕を全文確認）", "src": [["番組のYouTube（32:01〜）", "https://www.youtube.com/watch?v=8Qzgk9ni040&t=1921s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-8Qzgk9ni040", d: "2025-12-04", show: "ext", who: ["Kelani Jordan"], t: "ケラーニ・ジョーダンの回　体操からリングへ、7匹のペットと婚約の話", lead: "ジャスティン・スタッキーの番組に出た約39分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kelani Jordan"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-8Qzgk9ni040").map((x) => [x.t, x.b, x.sp])), open: ["大学時代の出来事に触れた話は、内容の性質上、載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=8Qzgk9ni040"]] });
  if (!ROSTER.find((r) => r[1] === "Diamond Dallas Page")) ROSTER.push(["ダイヤモンド・ダラス・ペイジ", "Diamond Dallas Page", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Diamond Dallas Page"]) PROFILES["Diamond Dallas Page"] = { lead: "バーの経営者から35歳前後でリングに転向し、世界王者と殿堂入りまで上り詰めた人物。仲間への感謝と「働き続ける」姿勢が、思い出話のあちこちに表れている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Diamond%20Dallas%20Page"]], moves: [], facts: [] };
  if (PROFILES["Diamond Dallas Page"]._weak) { PROFILES["Diamond Dallas Page"].lead = "バーの経営者から35歳前後でリングに転向し、世界王者と殿堂入りまで上り詰めた人物。仲間への感謝と「働き続ける」姿勢が、思い出話のあちこちに表れている。"; delete PROFILES["Diamond Dallas Page"]._weak; }
  PROFILES["Diamond Dallas Page"].facts.push(...[{"cat": "暮らし", "t": "約17年前にLAへ移り住んだ", "b": "約17年前、ロサンゼルスに引っ越そうと決めたと話す。その際、旧知の友人の家の部屋を借りることになったという。家賃は当時のLAとしては破格の安さだったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（2:30〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=150s"]]}, {"cat": "リングに来るまで", "t": "23歳からクラブを経営していた", "b": "ニュージャージーでバーの仕事をしたのち、フロリダへ渡って自分の店を持ったと話す。23歳から店を回しており、コンテストの司会やDJをこなしていたという。この経験がなければ、大観衆の前に立つ度胸はつかなかっただろうと振り返る。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（8:07〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=487s"]]}, {"cat": "リングに来るまで", "t": "若い頃にレスラー修行を少しだけ", "b": "子どもの頃に習いに行き、試合も3つほどこなしたが、膝を痛めて離れたと話す。その後はクラブ経営とパーティーの日々に気持ちが移ったそうだ。店でプロレスの話になり、あの道に進めばよかったと思い返したのがきっかけだったという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（11:19〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=679s"]]}, {"cat": "リングに来るまで", "t": "机のメモ書きから生まれた名前", "b": "仲間に昔のリングネームをからかわれた晩、机の吸い取り紙に「ダイヤモンド・ダラス・ペイジ」と書きつけたと話す。ダイヤモンド・エクスチェンジという軍団の名も、そのとき一緒に思いついたそうだ。書いたことをあとで確かめたほど、勢いで出てきた名前だったという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（12:05〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=725s"]]}, {"cat": "リングに来るまで", "t": "白いサングラスで「声」が生まれた", "b": "自分のCMを自作していた縁で、地元のケーブル局から取材を受けたと話す。机の上にあった白いサングラスをかけ、その場で「声」の語りをやってみせたという。そのときはまだ夢とも呼べない段階だったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（12:53〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=773s"]]}, {"cat": "リングに来るまで", "t": "ラジオ出演が人脈の入り口に", "b": "映像が流れた1週間ほど後に、ラジオ番組から専門家役としての出演依頼が届いたと話す。知識は足りないと断ろうとしたが、往年の名物マネージャーが来ると聞いて引き受けたという。共演した人たちが仲間として扱ってくれたことを、今も胸が熱くなる思い出として語る。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（15:14〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=914s"]]}, {"cat": "信仰", "t": "神様の巡り合わせを信じている", "b": "ラジオ出演の話が舞い込んだ流れを、自分は神様を強く信じる人間だと前置きして語る。星がそろうように憧れの人と話せる機会がめぐってきた、という受け止め方だそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（16:50〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1010s"]]}, {"cat": "リングに来るまで", "t": "存在しない選手たちのテープを作った", "b": "レスラー団体に送る映像を、手持ちの人脈だけで作り上げたと話す。友人3人を選手に仕立て、ラジオの声の友人に紹介役をしてもらったという。出演した友人たちは試合ができなかったため、正直に打ち明け、自分だけが別の枠で呼ばれることになったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（18:28〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1108s"]]}, {"cat": "リングに来るまで", "t": "バーで教わった「人脈の作り方」", "b": "最初の団体で出会ったカート・ヘニングが、決めゼリフの「グッド・ゴッド」を気に入ってくれたと話す。その夜に連れていかれたバーで、人間関係はリングよりも酒場で築くものだと教わったという。業界の流儀を最初に教えてくれた人だそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（21:51〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1311s"]]}, {"cat": "リングに来るまで", "t": "のどを痛めた夜のダスティとの電話", "b": "のどの炎症で寝込んでいた夜、留守電越しに知人の声が聞こえ、飛び起きて電話に出たと話す。受話器の向こうには憧れのダスティ・ローデスがいて、40秒ほど一気にまくし立てたという。その勢いが気に入られ、フロリダの団体で解説の席をもらうことになったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（25:02〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1502s"]]}, {"cat": "リングに来るまで", "t": "婚約を機にバーの仕事を辞めた", "b": "婚約者と結婚するため、夜の仕事を続けていてはうまくいかないと考えてバー経営をやめたと話す。ダスティが団体に戻ると知り、シカゴかアトランタかで迷って相談したところ、業界に関わるならアトランタがよいと勧められたという。ダスティの妻が間に入って連絡を絶やさずにいてくれたことにも、感謝している。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（29:56〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1796s"]]}, {"cat": "リングに来るまで", "t": "車中のビールで兄弟分になった", "b": "最初の団体で3日続きの興行があったとき、マイケル・ヘイズらと同じ車に乗り、ビール1ケースを空けながら3時間を過ごしたと話す。降りるころには兄弟のような仲になり、「テレビスターが目当てじゃないな」と見抜かれて番号を渡されたという。この縁が後の仕事につながったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（31:37〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1897s"]]}, {"cat": "リングの話", "t": "目立ちすぎてマネージャーを外された", "b": "派手な服や装飾が選手より目立つとして、先輩から「もう付き人はさせられない」と告げられたと話す。それならば自分が試合をすると決め、残り7カ月の契約の中で練習施設に通って技を学び始めたという。仲間は冗談だと思って笑ったが、約3週間後に初戦を迎え、実況席の先輩から出来を褒められたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（33:10〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=1990s"]]}, {"cat": "暮らし", "t": "巡業の暮らしは最初が一番楽しかった", "b": "ツアー生活の始めのころは、気の合う仲間と朝にホテルやジムを探して動くのが好きだったと話す。最初は知らない町で心細かったが、仲間と過ごす時間がいちばんの魅力だったという。やがて同じことの繰り返しになり、生活そのものになっていったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（41:06〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2466s"]]}, {"cat": "体のこと", "t": "肩の腱を切って約半年の離脱", "b": "1992年前後に肩の腱板を痛め、約半年の休養が必要になったと話す。当時は前座の端にいた存在で、復帰して成功すると思う人はまずいなかったそうだ。後に3度の世界王者と殿堂入りまで進むとは、誰も予想しなかったと振り返る。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（41:51〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2511s"]]}, {"cat": "リングに来るまで", "t": "ジェイク・ロバーツが自宅に居候した", "b": "休養中、ジェイク・ロバーツが宿に困っていると聞き、妻の了解を得て自宅の階下の部屋を貸したと話す。ジェイクは「やり方は知っている、足りないのは理由とタイミングだ」と言い、一緒に試合のビデオを見ることで学ばせてくれたという。その後も自分の出張に連れて行ってくれて、見習いとして経験を積めたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（42:41〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2561s"]]}, {"cat": "暮らし", "t": "家で飼っていたコブラが逃げた", "b": "ジェイクが居候していたころ、飼っていた大きなコブラが行方不明になる騒動があったと話す。風呂場の周りを探しても見つからず、本人は「そのうち出てくる」と言ったまま3日ほど家を空けたという。今では笑い話だそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（44:21〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2661s"]]}, {"cat": "リングの話", "t": "サングラスと葉巻をやめろと言われた", "b": "当時の上司から、サングラスや葉巻などの小道具をやめるよう言われたと話す。やめた夜、観客が一斉にダイヤモンドの手のサインを掲げ、手応えを感じたという。格下相手の試合でも、突然出す決め技で観客を沸かせていたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（46:00〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2760s"]]}, {"cat": "リングの話", "t": "自分の案を仲間に持ちかけて実現した", "b": "自分に出番がなかった時期に、ある案を思いつき、実現しなければ契約解除を申し出ると決めてナッシュとホールに相談したと話す。2人が賛成して上に掛け合い、約4カ月後にドーム大会で形になったという。この出来事が人生を変えたと語る。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（49:19〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2959s"]]}, {"cat": "リングの話", "t": "ランディ・サベージと名勝負を作った", "b": "1997年にランディ・サベージと組んだ試合で、前夜の打ち合わせで相手が自ら決め技を受けると申し出たと話す。誰も見ていない場で借りを作ってもらった形で、この一戦以降は常にトップ扱いになったそうだ。サベージが完璧主義で、同じ気持ちで最高の試合を目指せた相手だったという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（50:07〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=3007s"]]}, {"cat": "リングの話", "t": "バスケの名選手を会場に呼んだ", "b": "プロバスケの名選手カール・マローンとデニス・ロッドマンを試合に引き込んだ経緯を話す。自分から連絡して話をつけ、人気トーク番組に2人が出るタイミングで筋書きを仕掛けようと提案したという。反響は翌日に実感し、一般の人にも名前が届いたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（55:54〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=3354s"]]}, {"cat": "リングの話", "t": "ゴールドバーグとの13分間", "b": "1998年の大会でビル・ゴールドバーグと約13分の試合をしたと話す。相手に最初の突進を外してもらうよう前もって説得したが、競争心が強すぎて当日まで折れなかったという。試合は年間最高試合に選ばれ、無料のテレビでも再放送されたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:01:36〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=3696s"]]}, {"cat": "リングの話", "t": "フレアから初めて世界王座を奪った", "b": "1999年のスプリング・スタンピードで、4人で争う試合に勝ち、初めての世界王座を獲得したと話す。当時のレフェリーは旧友のサベージで、確実な3カウントを数えてくれたという。相手のリック・フレアには、殿堂入りのスピーチでも感謝を伝えたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:07:12〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4032s"]]}, {"cat": "リングの話", "t": "WWE入りは「うまくいかない船出」", "b": "45歳でライバル団体から移籍した際、周りの友人からは契約金をもらって一緒に移ろうと止められたと話す。実際には付きまとい役の筋書きを与えられ、妻と一緒の登場が要になった上、団体同士の因縁も読み切れなかったという。その経験から、納得できない話は席を立って断ってよいと学んだそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:11:16〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4276s"]]}, {"cat": "リングの話", "t": "戦ってみたかった相手", "b": "キャリアの悔いを問われ、ストーン・コールドやショーン・マイケルズと戦えなかったことを挙げたと話す。会話や試合運びの相性が合ったはずだと感じているそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:16:54〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4614s"]]}, {"cat": "暮らし", "t": "指輪には「努力は夢に等しい」の言葉", "b": "いつも身につけている指輪の内側に、「努力は夢に等しい」という言葉が刻まれていると話す。世界王座と殿堂の指輪は、ダスティの言葉どおり、本物の宝だという。話しながら声を詰まらせていたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:17:42〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4662s"]]}, {"cat": "体のこと", "t": "自分のヨガで友人の再起を助けた", "b": "自分が広めたヨガのプログラムで、ジェイク・ロバーツやスコット・ホールの再起を助けられたことを誇りにしていると話す。世界王座と殿堂入りに次ぐほど大切な出来事だと位置づけているそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:18:34〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4714s"]]}, {"cat": "リングの話", "t": "殿堂入りの電話はトリプルHから", "b": "2017年の殿堂入りの知らせは、故郷ニュージャージー州ポイント・プレザントにいるときに、トリプルHから届いたと話す。当初は転向を聞いて無理だと思ったが、練習施設での働きぶりを見て考えが変わったと言われたという。話の途中で気づき、息が止まるほど驚いたそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-GFYB9282zVg", "src": [["番組のYouTube（1:21:42〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=4902s"]]}]);
  if (PROFILES["Jake Roberts"]) PROFILES["Jake Roberts"].facts.push({"cat": "暮らし", "t": "ジェイク・ロバーツは「師匠」", "b": "自宅に居候したジェイクが、試合のビデオを一緒に見ながら、技の意味やタイミングを教えてくれたと、ダイヤモンド・ダラス・ペイジが話している。弟子のようについて回った時期を「ヨーダの運転手」と呼んで懐かしがっている。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ダイヤモンド・ダラス・ペイジの話（字幕を全文確認）", "src": [["番組のYouTube（42:41〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=2561s"]], "by": "第三者の話"});
  if (PROFILES["Randy Savage"]) PROFILES["Randy Savage"].facts.push({"cat": "暮らし", "t": "サベージが留守電を父にも聞かせた", "b": "感謝祭の前に感謝を伝える電話を入れたところ、サベージは何度も聞き返し、父親にも聞かせたと言ってくれたと、ダイヤモンド・ダラス・ペイジが話している。気難しい印象の相手が見せた温かさが、強く心に残っているという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ダイヤモンド・ダラス・ペイジの話（字幕を全文確認）", "src": [["番組のYouTube（53:19〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=3199s"]], "by": "第三者の話"});
  if (PROFILES["Goldberg"]) PROFILES["Goldberg"].facts.push({"cat": "暮らし", "t": "ゴールドバーグは負けず嫌い", "b": "試合で最初の突進を外すよう頼んでも聞き入れず、当日の直前まで譲らなかったと、ダイヤモンド・ダラス・ペイジが話している。相手が非協力的なのではなく、世界一の負けず嫌いだからだと理解しているそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2025-12-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ダイヤモンド・ダラス・ペイジの話（字幕を全文確認）", "src": [["番組のYouTube（1:05:39〜）", "https://www.youtube.com/watch?v=GFYB9282zVg&t=3939s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-GFYB9282zVg", d: "2025-12-06", show: "ext", who: ["Diamond Dallas Page"], t: "ダイヤモンド・ダラス・ペイジの回　クラブ経営者から殿堂入りまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約90分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Diamond Dallas Page"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GFYB9282zVg").map((x) => [x.t, x.b, x.sp])), open: ["ストーン・コールドの思い出話やルームメイト時代の冗談（掃除の話など）は、話者を区別しきれない箇所があるため載せていない。", "終盤の映画・配信ドラマ作品の宣伝と、新しいポッドキャストの告知は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GFYB9282zVg"]] });
