  PROFILES["Andrade"].facts.push(...[{"cat": "WWEでの日々", "t": "育成施設で経験の浅い仲間と練習した", "b": "メキシコや日本で長く経験を積んだあと、アメリカの育成施設とNXTに入ったと話す。周りにはリングに立った経験がほとんどない人もいて、そこから学び直す日々だったという。同じ時期にはフィン・ベイラーや中邑真輔らもいたそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（14:34〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=874s"]]}, {"cat": "WWEでの日々", "t": "ストーリーは提案も持ち込みもあった", "b": "ストーリーは、会社側から案を出されることもあれば、自分から提案することもあったと話す。自分の案が通らず、ほかの選手に回ったこともあるという。どの会社でも同じことは起こると受け止めているそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（18:33〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1113s"]]}, {"cat": "WWEでの日々", "t": "入団当初は役割に違和感があった", "b": "入団したころは、少し不満を抱えていたと話す。体重のある自分が空中技を見せても、アメリカの客には響きにくいと感じていたという。軽量級の選手とは土台が違うと考え、自分の見せ方を探したそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（23:21〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1401s"]]}, {"cat": "退団の理由", "t": "一度目は「成長が止まった」と感じた", "b": "約5年いたころ、もう頭打ちだと感じて、ある朝に退団を考えたと話す。その日のうちに身近な人へ打ち明けたという。報酬が良くても、自分の幸せと成長を優先したいと思ったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（28:10〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1690s"]]}, {"cat": "退団の理由", "t": "契約解除を願い出て、理由を伝えた", "b": "会社に契約の解除を願い出ると、理由を聞かれたという。WWEの外で挑戦したいこと、居心地が良くないことをそのまま伝えたと話す。大きな会社だと理解したうえでの判断だったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（30:41〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1841s"]]}, {"cat": "WWEでの日々", "t": "復帰時はトリプルHらが歓迎してくれた", "b": "WWEに戻ったとき、トリプルHをはじめ会社の人たちにも、ほかの選手たちにも温かく迎えられたと話す。トリプルHには以前からずっと良く接してもらったという。不満を言うことはないと語っている。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（48:25〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=2905s"]]}, {"cat": "退団の理由", "t": "年間最大の祭典に出られず落ち込んだ", "b": "復帰した年、年間最大の祭典のカードに入れなかったことで気持ちが沈んだと話す。前の年には同じ相手と何度も戦う流れがあり、手応えもあっただけに、よけいにこたえたそうだ。会社に相談する流れになったという。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（50:47〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3047s"]]}, {"cat": "退団の理由", "t": "予定がないなら自宅で待たせてほしいと頼んだ", "b": "プランがないなら、しばらく自宅で待たせてほしいと会社に伝えたという。会社からは、メキシコの団体との連携で今後は門戸が広がると説明されたと話す。しかし、その場では納得しきれなかったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（51:34〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3094s"]]}, {"cat": "退団の理由", "t": "目指すのは世界的なスターだった", "b": "メキシコや日本ではすでにスターとして活動してきたので、また同じ場所に戻る意味を感じにくかったという。自分が目指すのは世界的なスターで、その舞台はWWEだと考えていたと話す。メキシコの団体への出場を勧められても、気持ちは変わらなかったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（52:19〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3139s"]]}, {"cat": "WWEでの日々", "t": "メキシコ団体で悪役をやる話が出たが流れた", "b": "会社の人から、メキシコの団体で悪役として出る案を持ちかけられたと話す。最初の舞台は王座をめぐる4人の試合になる予定だったが、のちに話は変わったという。以降はWWEの中で別の流れが続いたそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（55:34〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3334s"]]}, {"cat": "WWEでの日々", "t": "メキシコ勢とのタッグが始まった", "b": "メキシコの団体との連携が始まり、フェニックスやペンタと組むことになったと話す。これまでは対戦ばかりで、組むのは初めてだった。会社は互いをよく知っていると見ていたが、本人は慣れるのに工夫が要ったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（57:55〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3475s"]]}, {"cat": "退団の理由", "t": "春から休みを頼んだが通らなかった", "b": "3月ごろから、環境を離れて休みたいと会社に頼んでいたという。しかし大会への出場が続き、休みは認められなかったと話す。家族と過ごす時間も欲しかったそうだ。それが、離れる可能性を考えるきっかけになったという。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（58:45〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3525s"]]}, {"cat": "退団の理由", "t": "検査結果について注意を受けた", "b": "会社の検査で引っかかったと話す。メキシコで買ったサプリメントが原因だと本人は考えていて、会社の医師からはメキシコ産の補助食品は避けるよう言われたそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（59:36〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3576s"]]}, {"cat": "WWEでの日々", "t": "フェニックスとの組み合わせが好評だった", "b": "初めは1人で伸びたい気持ちが強く、タッグに乗り気ではなかったという。しかし客の反応が良く、会社にも評価され、プッシュを感じたと話す。ホテルが同じで一緒に練習や食事をするうちに、親しい仲になったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:01:15〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3675s"]]}, {"cat": "WWEでの日々", "t": "最後の試合は王座戦の4人試合", "b": "WWEでの最後の試合は8月で、タッグ王座をめぐる4チームの試合だったと話す。結果には悔しさが残ったが、流れは悪くなかったという。そのあと、メキシコにいる間に検査を受けるよう連絡があったそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:02:03〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3723s"]]}, {"cat": "退団の理由", "t": "会社と話し合い、9月13日に契約解除", "b": "約2週間ほど話し合いを重ね、合意のうえで9月13日に契約が解除されたと話す。トリプルHらにはお礼を伝えたという。会社と円満にやり取りしたというのが、本人の受け止めだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:02:54〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3774s"]]}, {"cat": "WWEでの日々", "t": "タッグ相手に謝罪と感謝を伝えた", "b": "ここまで息が合ってきた相手に、個人的な判断で迷惑をかけたかもしれないと、番組で謝っている。互いに支え合い、タイトルを目指して乾杯するほどだったという。これまで公には言ってこなかったが、申し訳ない気持ちが強いそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:03:44〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3824s"]]}, {"cat": "退団の理由", "t": "競業避止の確認と、広がったうわさ", "b": "退団後すぐ、競業避止の条項があるのか会社に確認したが、書類はなかなか届かなかったという。その間に「解雇された」といううわさが広がったと話す。本人はそのころ取材に応じる気はなく、独立系の仕事を入れていたそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:06:09〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=3969s"]]}, {"cat": "退団の理由", "t": "競業避止で12か月の出場停止を通知された", "b": "後日、会社から「12か月は試合ができない」と通知が届いたと話す。その間の報酬もないという。本人は驚いたが、手続き上はそうなると受け止めている。サイン会や講演などはできるという説明も受けたそうだ。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:16:28〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=4588s"]]}, {"cat": "退団の理由", "t": "期間の短縮に向けて交渉が続いている", "b": "弁護士を通じて会社と話し合いが続いており、会社の対応は丁寧だと話す。12か月より短くなりそうだという見通しを持ち、半年ほどで復帰できればと考えているそうだ。リング復帰の日を待っている。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で（字幕を全文確認）", "art": "ext-jymHL1lp_eY", "src": [["番組のYouTube（1:22:54〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=4974s"]]}]);
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "育成施設を経ずに上がった人", "b": "ドミニク・ミステリオは育成施設を通らずに上へ上がった、と話している。幼いころからアメリカの選手と練習してきたので順応も早かった、と見ているそうだ。人柄も申し分ない、と、アンドラーデが話している。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で、アンドラーデの話（字幕を全文確認）", "src": [["番組のYouTube（16:57〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1017s"]], "by": "第三者の話"});
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "与えられた物語を生かした", "b": "ドミニクは与えられたストーリーを最大限に活用して名を上げた、と話している。父親や、ほかの人物との関係を描く筋書きが追い風になったという。もらった機会を生かす力があった、と、アンドラーデが話している。", "sp": "アンドラーデ", "d": "2025-12-10", "how": "エル・リング（スペイン語の対談番組）で、アンドラーデの話（字幕を全文確認）", "src": [["番組のYouTube（17:43〜）", "https://www.youtube.com/watch?v=jymHL1lp_eY&t=1063s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-jymHL1lp_eY", d: "2025-12-10", show: "ext", who: ["Andrade"], t: "アンドラーデの回　WWEを二度離れた経緯と、去るまでの日々", lead: "エル・リング（スペイン語の対談番組）に出た約93分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Andrade"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-jymHL1lp_eY").map((x) => [x.t, x.b, x.sp])), open: ["字幕が自動生成のため、団体名やタッグの経緯の一部は聞き取りが不確かで、固有名詞は確かなものだけ載せた。", "元配偶者や私生活にあたる話、他団体での出来事は掲載していない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=jymHL1lp_eY"]] });
