  if (!PROFILES["Natalya"]) PROFILES["Natalya"] = { lead: "父の波乱の人生を許し、その愛を一冊の本にしたナタリヤ。猫に囲まれた家で母と朝のコーヒーを飲むのが、いちばんの幸せだという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Natalya"]], moves: [], facts: [] };
  if (PROFILES["Natalya"]._weak) { PROFILES["Natalya"].lead = "父の波乱の人生を許し、その愛を一冊の本にしたナタリヤ。猫に囲まれた家で母と朝のコーヒーを飲むのが、いちばんの幸せだという。"; delete PROFILES["Natalya"]._weak; }
  PROFILES["Natalya"].facts.push(...[{"cat": "リングの話", "t": "リアリティ番組で犬に襲われる展開に", "b": "共演したロンダ・ラウジーの犬が、撮影中に彼女の股間をやたらと嗅いだという。するとスタッフが「これを筋書きにしよう」と言い出し、気づけば体にピーナッツバターを塗られて犬になめられていた。「何でもやるのがプロ」と笑って振り返る。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（0:01〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1s"]]}, {"cat": "リングの話", "t": "酔って真夜中に電話した番組の一幕", "b": "リアリティ番組では、酔ってステフに夜中の2時に電話してしまう場面も撮られたそうだ。本人はマルガリータを1杯飲んだだけで、それが強かったのだと言う。「あの時、ステフは最高の上司だった」と話している。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（5:47〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=347s"]]}, {"cat": "リングの話", "t": "現実の出来事がそのまま番組のネタになる", "b": "試合で実際に起きたハプニングが、番組側の判断でそのまま筋書きに使われることがよくあったという。ひどく落ち込むほどではなかったが、そういうものだと受け流してきたと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（7:25〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=445s"]]}, {"cat": "リングの話", "t": "年間最大の祭典での衣装トラブル", "b": "バトルロイヤルでベイリーにロープ越しに落とされた日、自作の体のサイドが開いた衣装を着ていたが、下着が付けられないつくりだった。控室に戻る途中でベッキーに衣装が破れていると教えられ、写真や動画が出回ってトレンド入りした。それでも「これで祭典の見せ場ができた」と笑い飛ばしたという。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（8:12〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=492s"]]}, {"cat": "リングの話", "t": "リアリティ番組に9シーズン出演した理由", "b": "リアリティ番組には全9シーズンに出たと話す。「パンチを受け流して、何でもやる人」と制作側に見られていたからだという。コメディだけでなく、何でも成立させようとするのが自分の持ち味だと考えている。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（9:42〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=582s"]]}, {"cat": "体のこと", "t": "本の執筆中にパニック発作が出た", "b": "自伝を書いている間、つらい記憶を思い出して何度もパニック発作に襲われたという。人に嫌われたくない、父や身内を怒らせたくないという気持ちが強く、自分は「人に合わせすぎる人」だと気づいた。きっかけは、友人のレスラーが番組で不安障害について語っていたのを見たことだと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（11:19〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=679s"]]}, {"cat": "暮らし", "t": "自伝は「自分のために」書いた", "b": "ベッキーからは「思い切り全部書いて、寝かせてから見直せばいい」と言われたという。叔父のブレットには「上司や夫、親の目を気にせず、自分のために書け」と励まされた。それで書き方が決まったそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（12:51〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=771s"]]}, {"cat": "暮らし", "t": "育成施設の学生や仲間に本を贈った", "b": "自分が開いている育成施設に来たジョン・シナに本を渡したところ、翌日には半分まで、その夜には読み終えて、泣いたと連絡があったという。ビアンカ・ベレアは巡業の飛行機で最初に読み、「新人のころにこの本が欲しかった」と話したそうだ。本を読んだ人から「心が癒やされた」と言われるのが嬉しいそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（14:29〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=869s"]]}, {"cat": "家族", "t": "父が亡くなった日の最初の電話", "b": "父が亡くなったとき、最初に電話をかけたのは大物プロデューサー（ビンス）だったという。その夜は試合の予定があったが、休ませてほしいと伝えた。彼は写真を送るよう頼み、番組の冒頭で父を送る映像を流してくれた。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（19:11〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1151s"]]}, {"cat": "家族", "t": "家族でWWEに残るのは自分だけに", "b": "父の映像を見て、家族のなかでWWEに残っているのが自分だけだと気づいたという。そこから、自分が残す遺産について考えるようになった。ハート家で最初の世界王者や殿堂入りにはなれなくても、お金に困らず、体も壊さずにこの世界を去る最初の一人になりたいと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（20:42〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1242s"]]}, {"cat": "リングの話", "t": "成功の意味を考え直した", "b": "昔は「この試合に出たい」「この王座を取りたい」と、目の前の目標ばかり追っていたという。本を書き終えるころ、鏡の中の自分を好きでいられるなら、もう勝っているのだと気づいた。お金だけが成功ではないと、読者にも伝えたいそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（21:28〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1288s"]]}, {"cat": "リングの話", "t": "控室の小さな思い出がいちばん残る", "b": "控室で誰かの試合の相談に乗ったり、ベイリーが誕生日の人にケーキを持ってきたりする。そんな番組後のささやかな時間こそ、ずっと心に残るはずだと話す。勝利や栄光よりも、小さな出来事のほうが大切だという考えだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（23:03〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1383s"]]}, {"cat": "好きなもの", "t": "ルイ・ヴィトンとペルシャ猫が好き", "b": "自分は「おしゃれ好き」で、ルイ・ヴィトンとペルシャ猫が好きだと話す。ただ、幸せや成功は物では決まらないとも付け加える。白いフリルのジャケットは、スプレータンが付くので避けたいそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（23:52〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1432s"]]}, {"cat": "暮らし", "t": "母と同居、家には猫が8匹", "b": "父の死後、母と親友のように過ごすようになり、夫のTJに頼んで一緒に住み始めたという。母が飼っていた猫4匹と自分たちの4匹で、いまは猫が8匹いる。自分は犬も好きで、普段から愛犬を可愛がっていると話している。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（24:38〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1478s"]]}, {"cat": "暮らし", "t": "いちばんの幸せは朝のコーヒー", "b": "一番幸せなのは、朝にパジャマのままキッチンで母とコーヒーを飲む時間だという。子どものころから変わらない父の話ばかりしている、と笑って話す。パジャマはゆったりした綿の大きめのものが好みで、できるだけ長く着ていたいそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（25:27〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1527s"]]}, {"cat": "好きなもの", "t": "夫からの贈り物と手持ち掃除機", "b": "夫TJが贈ってくれたのは、伸びないサテンの小さなパジャマと、ロボット掃除機だったそうだ。掃除機は好きだが、欲しかったのは自分で操作できる手持ちのダイソンだったという。「私はコントロールしたい性分」と笑っている。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（26:12〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1572s"]]}, {"cat": "家族", "t": "波乱の子ども時代と父の事情", "b": "父は依存症や不安に苦しみ、亡くなったあとでようやく事情がわかったという。テレビで活躍して家計が潤う日もあれば、次の日に仕事を失う日もあり、子どもの頃は気持ちが落ち着かなかった。その経験から、自分は完璧でいようとする人になったと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（31:02〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1862s"]]}, {"cat": "家族", "t": "家を失い、祖父の家で母や姉妹と同じ部屋に", "b": "お金が尽きて家も車も失い、祖父が家を開いてくれたという。2年間、母と姉妹と一緒に、母が子どものころに使った1つの部屋で眠った。窓の外にはリングがあり、あれが家族の希望だと感じていたそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（33:33〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=2013s"]]}, {"cat": "家族", "t": "父に謝ってほしかった、でも許した", "b": "長い間、父から謝罪の言葉を聞きたいと願っていたという。父は老いたライオンのようにプライドが高く、謝る方法を知らなかったのだと今は思う。本を書くことで、その気持ちを手放し、父を許せたと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（47:50〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=2870s"]]}, {"cat": "家族", "t": "父は砲丸投げで世界5位の選手だった", "b": "父は18歳のとき、砲丸投げで全米1位、世界5位だったという。大学の陸上部に全額奨学金で進み、のちにプロのアメリカンフットボールのチームにも在籍した。素行の問題で退団したのち、祖父に見いだされてプロレスの世界に入ったそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（48:37〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=2917s"]]}, {"cat": "家族", "t": "人を引きつける愉快な父", "b": "父は面白くて魅力的で、スピード違反で止められても警官と一杯飲んでしまうような人だったという。夫TJのことは長いあいだ「ガイ」と呼んでいた。交際していたことは、父には長く友達としか言っていなかったそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（50:07〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3007s"]]}, {"cat": "リングに来るまで", "t": "父は最初、プロレス入りに反対した", "b": "父は、娘が傷つくのを心配して「簡単じゃない」と反対したという。初めて日本へ行く前には大げんかになり、泣いて空港へ向かった。結局、日本でひざを痛めてしまい「やはり父は正しかった」と思ったそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（50:56〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3056s"]]}, {"cat": "家族", "t": "父の事務所で見つけた誇りの跡", "b": "父の事務所を片づけたとき、自分の等身大パネルや、WWE入団前に一緒に出た試合の写真が飾られていたという。口には出さなかった父の誇らしい気持ちを、そのとき初めて実感した。日本で挫折したあとも、父は一番の応援団になってくれたそうだ。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（52:27〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3147s"]]}, {"cat": "リングの話", "t": "巨人の選手を車で送った珍道中", "b": "ある巡業で、大柄なインド出身の人気選手を空港から車で送る役を引き受けた。空港で2時間のファンサービス、次に友人の店で大量の食事、そして友人宅に泊まることになり、全員が眠る場所を譲り合ったという。翌朝、勇気を出して「早く車に乗って」と言い切れたことが、自信につながったと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（54:47〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3287s"]]}, {"cat": "リングの話", "t": "初めて自分で出した案が通った", "b": "珍道中のあとの月曜、勇気を出して大物プロデューサー（ビンス）に筋書きの案を持ち込んだという。彼は「いい案じゃないし、筋も通らない。でも自分から持ってきたからやってみよう」と返した。こうしてハート・ダイナスティが生まれたと話す。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（1:04:01〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3841s"]]}, {"cat": "好きなもの", "t": "カナダ出身であることを誇りに思う", "b": "番組の最後に、カナダ出身の名アスリートを順位づけする企画に参加した。ウェイン・グレツキーは2位、クララ・ヒューズは3位、ボビー・オーはあまり詳しくないので5位とした。叔父のブレット・ハートは迷わず1位に選んでいる。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-63L5_mNfZ-Y", "src": [["公式YouTube（1:08:52〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=4132s"]]}]);
  if (PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"].facts.push({"cat": "暮らし", "t": "本の書き方を助けたベッキー", "b": "ベッキー・リンチは「思い切り全部書いて、寝かせて、あとで見直せばいい」と助言してくれた、とナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（13:37〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=817s"]], "by": "第三者の話"});
  if (PROFILES["Bayley"]) PROFILES["Bayley"].facts.push({"cat": "暮らし", "t": "控室でケーキを用意するベイリー", "b": "ベイリーは誰かの誕生日にケーキを持ってきて、番組後の控室で小さなパーティーを開いてくれる、とナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（23:03〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=1383s"]], "by": "第三者の話"});
  if (PROFILES["The Great Khali"]) PROFILES["The Great Khali"].facts.push({"cat": "暮らし", "t": "人柄が温かいグレート・カリ", "b": "グレート・カリは身長が約2メートル18センチで、インドでは神様のように慕われ、とても温かい心の持ち主だ、とナタリヤが話している。", "sp": "ナタリヤ", "d": "2025-12-11", "how": "ステファニーの番組で、ナタリヤの話（公式字幕を全文確認）", "src": [["公式YouTube（55:32〜）", "https://www.youtube.com/watch?v=63L5_mNfZ-Y&t=3332s"]], "by": "第三者の話"});
