  if (PROFILES["Braun Strowman"]._weak) { PROFILES["Braun Strowman"].lead = "ほぼ家なし状態で入団し、試合数わずか4でテレビデビューした元ストロングマン。けがと向き合い続けた日々と、リングを離れた今の思いを語った。"; delete PROFILES["Braun Strowman"]._weak; }
  PROFILES["Braun Strowman"].facts.push(...[{"cat": "WWEでの日々", "t": "テレビデビュー前に腰を痛めた", "b": "ブラウン・ストローマンは、2015年にテレビデビューする前に腰の骨を痛めたと話す。坐骨神経にまで響いて左脚が動かなくなり、緊急手術を受けたという。手術の後すぐ立って歩けたが、回復は85%ほどだったそうだ。以後、WWEにいた間ずっと左脚の筋肉の衰えを抱えたまま戦ったと本人は話す。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（9:29〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=569s"]]}, {"cat": "WWEでの日々", "t": "育成時代の16か月のうち6か月はけが", "b": "ブラウン・ストローマンは、育成施設に約16か月いたうち、6か月は背中や肋骨のけがで動けなかったと話す。入ってすぐ7日目に肋骨を2本折ったという。それだけ試合の経験が少なく、キャリア全体でも試合数は4つだけの状態でテレビに出たと振り返る。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（11:02〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=662s"]]}, {"cat": "WWEでの日々", "t": "わずか4試合でRAWデビュー", "b": "ブラウン・ストローマンは、2015年の年間最大の祭典のあとの月曜のRAWで、ワイアット・ファミリーとともに初めてテレビに出たと話す。ディーン・アンブローズとローマン・レインズを倒す場面だった。当時は技の名前も分からない状態で、ベテランの3人が面倒を見てくれたことが特別な時間だったと語る。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（11:02〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=662s"]]}, {"cat": "WWEでの日々", "t": "車や友人宅で寝泊まりした入団前後", "b": "入団したころは、人の家のソファや車で寝ていて、ほぼホームレスだったとブラウン・ストローマンは話す。小さな車に全財産を積み、150ドルだけを持ってフロリダに移ったという。着いてからは、知り合いの部屋に居候して契約のスタートに備えたそうだ。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（11:54〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=714s"]]}, {"cat": "WWEでの日々", "t": "育成の下位組織をほぼ飛ばして一軍へ", "b": "ブラウン・ストローマンは、下位の育成ブランドでは暗い会場での試合1つと、ハウスショー3回しか経験していないと話す。ほかにも同じように飛ばした者が数人いたという。業界の出身でも、インディー団体の出身でもないため、当初は「下積みをしていない」と嫌われたと本人は感じていたそうだ。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（18:14〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1094s"]]}, {"cat": "WWEでの日々", "t": "2013年の入団テストは体重405ポンド", "b": "2013年にWWEの入団テストを受けたとき、ブラウン・ストローマンは体重が約405ポンドあったと話す。当時は力自慢の大会に出ていた時期で、その状態のまま会場に入ったという。周りの選手から、扉が開いて光が差し、また暗くなったようだったと言われた、と話している。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（18:14〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1094s"]]}, {"cat": "WWEでの日々", "t": "先輩の助言は「耳は二つ、口は一つ」", "b": "マーク・ヘンリーから、神は耳を二つ、口を一つ与えたのだから、話す倍は聞けと教わったとブラウン・ストローマンは話す。この言葉を胸に、業界の内輪の空気の中で周囲に合わせて進んだという。外から来た者として、先輩への敬意を大切にしようとしたそうだ。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（23:59〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1439s"]]}, {"cat": "退団の理由", "t": "薄れていった「敬意」が心残り", "b": "ブラウン・ストローマンは、業界を去る間際に残念に思ったのは、敬意が失われていったことだと話す。入団当初はアンダーテイカーが出る大会で、その試合を全員が見ていないと怒られたという。のちにローマン・レインズと45分の試合をして戻っても、控えの場所に誰もいなかったことがあり、あの客は自分たちを見に来たのにと感じたそうだ。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（24:47〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1487s"]]}, {"cat": "退団の理由", "t": "2023年の首のけがで突然の幕引き", "b": "ブラウン・ストローマンは、2023年に試合中に頭をはね返され、両腕が数秒動かなくなったと話す。本人も知らなかった脊柱管の狭さがあり、首に金属のプレートとねじ4本を入れる手術を受けたという。8か月後には同じように動けるようになったが、自分のキャリアは思いがけない形で終わったと話し、それでも「リングにはいつでも戻れる」と語る。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（31:04〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1864s"]]}, {"cat": "WWEでの日々", "t": "けがを押しても戦った理由", "b": "ブラウン・ストローマンは、2018年には肘の手術が必要なまま18か月、腕の可動域がわずか15度ほどの状態で戦ったと話す。家族の葬式や結婚式にも出られなかったそうだ。子どもの入院先や夢をかなえる活動で、自分の役を心の支えにする子どもたちを見てきたため、ここで弱い姿は見せられないと思ったと語る。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（32:46〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=1966s"]]}, {"cat": "退団の理由", "t": "リングを離れて恋しいのは控室と慈善活動", "b": "今いちばん恋しいのは、リングに立つことと控室の空気だと、ブラウン・ストローマンは話す。逆にそれ以外の仕事はあまり恋しくないという。いちばんなくなって寂しいのは、子どもたちを笑顔にする慈善活動の時間だと、本人は話している。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで（字幕を全文確認）", "art": "ext-fbaVGHAji6E", "src": [["番組のYouTube（33:35〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=2015s"]]}]);
  if (PROFILES["Chad Gable"]) PROFILES["Chad Gable"].facts.push({"cat": "暮らし", "t": "年間最大の祭典で受けたチャド・ゲイブルの投げ", "b": "チャド・ゲイブルは、五輪の本物のレスリングで6位に入った実力者で、年間最大の祭典で自分に決めた投げ技も印象的だったと、ブラウン・ストローマンが話している。耳の形を見れば強さが分かるとも話している。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで、ブラウン・ストローマンの話（字幕を全文確認）", "src": [["番組のYouTube（1:28:50〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=5330s"]], "by": "第三者の話"});
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "ブロック・レスナーは強い人の代表", "b": "強い選手は誰かと聞かれると、みな真っ先にブロック・レスナーの名を挙げると、ブラウン・ストローマンが話している。何度か激しくやり合ったとも話し、強烈な右の拳をもらっても眠らなかったのは自分だけだと誇らしげに語っている。", "sp": "ブラウン・ストローマン", "d": "2025-12-16", "how": "バート・クライシャーの料理お笑い番組 Something's Burningで、ブラウン・ストローマンの話（字幕を全文確認）", "src": [["番組のYouTube（1:31:21〜）", "https://www.youtube.com/watch?v=fbaVGHAji6E&t=5481s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-fbaVGHAji6E", d: "2025-12-16", show: "ext", who: ["Braun Strowman"], t: "ブラウン・ストローマンの回　けがだらけの下積みと、失ったもの", lead: "バート・クライシャーの料理お笑い番組 Something's Burningに出た約99分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Braun Strowman"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-fbaVGHAji6E").map((x) => [x.t, x.b, x.sp])), open: ["お笑い番組で、同席のコメディアンや司会の話、宣伝、冗談の大半は拾っていない。", "家族、生い立ち、体づくりや食事、事業の話などWWE以外の話は公開項目に入れず、別に控えた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=fbaVGHAji6E"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wdywta-cena" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wdywta-cena" ? Object.assign(x, { art: "wdywta-NSUgyaxzbnA" }) : x);
