  if (PROFILES["Seth Rollins"]) PROFILES["Seth Rollins"].facts.push({"cat": "暮らし", "t": "セス・ロリンズの派手なスーツに助言", "b": "夫のセス・ロリンズが派手なスーツを着るようになったのは、仕事の話をするなかで自分が出した助言がきっかけの一つだったらしいと、ベッキー・リンチが話している。何を言ったか細かくは覚えていないという。", "sp": "ベッキー・リンチ", "d": "2026-01-10", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ベッキー・リンチの話（字幕を全文確認）", "src": [["番組のYouTube（1:10:42〜）", "https://www.youtube.com/watch?v=BLEGrHBosMs&t=4242s"]], "by": "第三者の話"});
  if (PROFILES["Tyson Kidd"]) PROFILES["Tyson Kidd"].facts.push({"cat": "暮らし", "t": "タイソン・キッドの「入場曲を聴け」", "b": "育成施設に入った初日、女子の試合づくりにも関わるタイソン・キッドに助言を求めたところ、「トリプルHの入場曲を聴け」と言われた、とベッキー・リンチが話している。今も頭に残る言葉で、18歳のころから知る業界の宝のような存在だという。", "sp": "ベッキー・リンチ", "d": "2026-01-10", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ベッキー・リンチの話（字幕を全文確認）", "src": [["番組のYouTube（1:03:24〜）", "https://www.youtube.com/watch?v=BLEGrHBosMs&t=3804s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-BLEGrHBosMs", d: "2026-01-10", show: "ext", who: ["Becky Lynch"], t: "ベッキー・リンチの回　アイルランドの少女が「ザ・マン」になるまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約86分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Becky Lynch"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-BLEGrHBosMs").map((x) => [x.t, x.b, x.sp])), open: ["ストーン・コールド側の思い出話や感想、番組冒頭の紹介部分は載せていない。", "宗教や信仰にあたる話は語られていないため、該当項目はない。", "「リングの話」は試合の流れや結果ではなく、本人の考え方や舞台裏の発言を中心にまとめた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=BLEGrHBosMs"]] });
  if (!ROSTER.find((r) => r[1] === "Bayley")) ROSTER.push(["ベイリー", "Bayley", "lg", "", "", "", ""]);
  if (!PROFILES["Bayley"]) PROFILES["Bayley"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bayley"]], moves: [], facts: [] };
  if (PROFILES["Bayley"].lead === "") PROFILES["Bayley"]._weak = 1;
  PROFILES["Bayley"].facts.push(...[{"cat": "リングの話", "t": "女子が番組の締めを飾る時代", "b": "前夜のRAWでは女子の試合がメインイベントになり、ベイリーも王座戦線の物語に加わっていたという。タッグ王座が昔は存在しなかったことにも触れ、出番や物語が増えるほど全員の勝ちだと話す。まだ天井には達していないと考えているそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（38:26〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2306s"]]}, {"cat": "リングの話", "t": "「恵まれすぎ」で腐らないこと", "b": "昔のAJスタイルズやニッキー・ベラは、30秒の試合のために戦い、物語を求め続けたとベイリーは話す。いまの女子は恵まれてきたが、自分たちは何も借りていないし、不満や権利意識が出たときに崩れ始めると語る。自分にも言い聞かせ、手本を見せたいそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（40:03〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2403s"]]}, {"cat": "リングの話", "t": "NXTで築いた絆をRAWとSmackDownへ", "b": "NXT時代に生まれたチームの絆は特別で、RAWやSmackDownに来てからも仲間を落胆させない更衣室になったとベイリーは話す。落ち込んだ若手をリア・リプリーが励ました場面を、誇らしく見ていたという。いつもは自分が声をかける側だったそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（41:40〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2500s"]]}, {"cat": "リングの話", "t": "自我を手放せば試合が良くなる", "b": "ストーン・コールドには「蹴落とし合いのほうがいい」と言われたが、女子は違うとベイリーは話す。助け合えば全員が上手くなり、観客の反応も良くなる一方、裏でとげとげしいと試合のケミストリーが崩れて客席に伝わると語る。本当の姉妹のような関係だという。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（43:16〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2596s"]]}, {"cat": "リングの話", "t": "先輩たちから学んだ「頼れる人」の姿", "b": "上がってきた最初の年、ナタリヤ、タミナ、ナオミが常に気にかけてくれたとベイリーは話す。メルセデス、ベッキー、シャーロットも同じ時期に昇格した仲間だという。自分もそう接しようと決め、その空気が続いてほしいと願っているそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（44:02〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2642s"]]}, {"cat": "リングの話", "t": "AJスタイルズがくれた45分", "b": "NXT時代、AJスタイルズが大会の合間にベイリーを呼び、45分も話してくれたという。相手に歩み寄る努力は必要だが、自分の気持ちに反してまで変わる必要はないという趣旨だったそうだ。この会話はずっと心に残っていて、本人にも今も伝えていると話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（45:37〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2737s"]]}, {"cat": "リングの話", "t": "無料セミナーを開いた理由", "b": "ライブ興行が少なく、テレビで試合が回ってこない時期に、何かして業界に貢献したいと思ったとベイリーは話す。将来は自分の学校を開きたいが、まだ準備はできていないという。参加費は無料で、宿泊と移動も用意し、リア・リプリーやビアンカ・ブレアらがゲストで来るそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（56:37〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3397s"]]}, {"cat": "リングの話", "t": "ステファニー・ヴァケールとの共演", "b": "ベイリーは、ステファニー・ヴァケールの技が毎回正確で、安全なのに目を引くと感心している。ランブル戦で少しだけ一緒に試合をしたことがあり、いつかシングルでも当たりたいと話す。ほかの若い選手の台頭にも刺激を受けているそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:01:17〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3677s"]]}, {"cat": "リングの話", "t": "キャラクターが際立つ今の物語", "b": "ベイリーは、いまの選手たちはキャラクターがはっきりしていて、観客も人それぞれに感情移入できると話す。マクシーンとベッキーの物語を例に、「あの人がこんなことをするとは」と思わせる展開が希望を与えると語る。悔しい結末でも次を期待させる力があるという。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:23:03〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=4983s"]]}, {"cat": "リングの話", "t": "契約初日に問われた「本当に好きか」", "b": "インディー時代は週2回の練習だけだったが、契約が決まったとき、トレーナーに「毎日これが生活になるぞ」と言われたとベイリーは話す。不安もあったが、続けるほど好きだと分かったそうだ。今は、あらゆる物語と役を経験したい、GMも恋愛の筋書きもやりたいと語る。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:29:20〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=5360s"]]}]);
  if (!PROFILES["Bayley"]) PROFILES["Bayley"] = { lead: "12歳で初めて観た小さな会場の大会が、すべての始まりだったという。いまは独立系の女性レスラーを集めて無料のセミナーを開くなど、仲間を引き上げることに力を注いでいる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bayley"]], moves: [], facts: [] };
  if (PROFILES["Bayley"]._weak) { PROFILES["Bayley"].lead = "12歳で初めて観た小さな会場の大会が、すべての始まりだったという。いまは独立系の女性レスラーを集めて無料のセミナーを開くなど、仲間を引き上げることに力を注いでいる。"; delete PROFILES["Bayley"]._weak; }
  PROFILES["Bayley"].facts.push(...[{"cat": "リングに来るまで", "t": "12歳で父と兄と初めての生観戦", "b": "初めてプロレスを生で観たのは12歳のころで、父が兄と一緒に地元の独立系団体の大会へ連れて行ってくれたという。会場は青少年向けクラブの小さなホールで、入口の通路でいきなりバフ・バグウェルと鉢合わせしたそうだ。その瞬間に「ここに来たんだ」と心をつかまれたと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（5:36〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=336s"]]}, {"cat": "リングに来るまで", "t": "選手が「本物の人間」だと知った日", "b": "テレビの中の存在だった選手たちが、マットの上に足をつけて動いているのを見て、実在の人間なのだと実感したという。父もその日、自分を見る目が変わったのが分かったそうで、本人も「自分にもできる」と確信したと振り返る。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（7:13〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=433s"]]}, {"cat": "好きなもの", "t": "毎日つけていたハーディーズのネックレス", "b": "当時の写真では、ハーディー・ボーイズのネックレスを着けており、毎日欠かさず身に着けていたものだという。いつも名前を挙げる憧れはマッチョマンとハーディーズだと話している。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（8:01〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=481s"]]}, {"cat": "家族", "t": "お金がなくリングに座って記念撮影", "b": "休憩中にリング上でポラロイド撮影ができたが、追加料金を払う余裕がなかったため、父が「リングに腰かけて、背景に選手を入れて撮ろう」と工夫してくれたそうだ。その写真には兄も写っている。当時のパンフレットとチケットはいまも自宅の仕事部屋に飾っているという。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（8:49〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=529s"]]}, {"cat": "リングに来るまで", "t": "初観戦の団体でのちに練習を始めた", "b": "初めて観に行ったその団体は、のちに本人がトレーニングを始めた団体でもあったという。地元カリフォルニアで約30年続く団体だと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（9:36〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=576s"]]}, {"cat": "リングに来るまで", "t": "厳しい恩師と唯一の女子練習生", "b": "トレーナーのジェイソン・スタイルズはとても厳しく、高校時代のバスケットボールのコーチに似ていたという。可能性を見込んだからこそ追い込むタイプだったそうだ。練習生のうち女子は本人ひとりで、特別扱いはされず、大会のたびに男子と一緒にリングの設営と撤去をしたと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（10:26〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=626s"]]}, {"cat": "リングに来るまで", "t": "対戦相手の女子を毎回呼んでくれた興行主", "b": "地元には女子レスラーがいなかったため、興行主のカーク・ホワイトが毎回ロサンゼルスなどから女子選手を飛行機で呼んでくれたという。男子と組んだ試合は数回だけだったそうだ。ホワイトはコロナ禍のころに亡くなり、いまは妻と娘が団体を運営していて、本人も今も大会に足を運んでいると話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（11:15〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=675s"]]}, {"cat": "リングに来るまで", "t": "リング設営で学んだ「チームで作る」こと", "b": "学生時代にスポーツをしていたこともありチームプレーの意識はあったが、プロレスは自分本位の世界だと聞かされていたという。それでも仲間とリングを組み、運び、また組み直す毎日の中で、興行は全員で作るものだと学んだそうだ。その考えはWWEに来てからも自分の中に残っていたと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（12:01〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=721s"]]}, {"cat": "家族", "t": "母が恩人一家を感謝祭に招待", "b": "亡き興行主の妻と娘とは家族ぐるみの付き合いになり、母が感謝祭の食事に招いたという。いまでは母と彼女たちが親友同士なのだそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（13:36〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=816s"]]}, {"cat": "暮らし", "t": "チケットは抽選、最前列は一度だけ", "b": "子どものころはチケットを取るだけで精一杯で、地元の会場では並ぶ順番を抽選で決めていたという。いつも一番安い席だったが、一度だけ抽選に当たり、父が高い代金を渋々払って最前列で観たそうだ。その夜はトリプルHの肩に触れ、ショーン・マイケルズも間近で見たと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（20:08〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=1208s"]]}, {"cat": "家族", "t": "母と行ったエディの王座戴冠の夜", "b": "母に連れて行ってもらった大会で、エディ・ゲレロが王座を取った瞬間を地元の会場で観たという。一緒に行った年下の友人が通路でナチョスのチーズを前の客にこぼしてしまい、母が平謝りしたそうだ。これが観戦の思い出のベスト2だと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（21:49〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=1309s"]]}, {"cat": "暮らし", "t": "子どもは「縁があれば」", "b": "子どもについては、昔は持つものだと思っていたが、今は縁があればという考えだという。いまは交際相手はおらず、もし誰かと出会っても、その人が親としてふさわしいかを見極めたいと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（27:19〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=1639s"]]}, {"cat": "暮らし", "t": "郊外に家を買い、何かが変わる予感", "b": "ここ5年ほどは何が起きても受け入れようと思えるようになったという。年末にかけて自分の中で何かが開いていく感覚があり、いとこにも相談したそうだ。街から30分ほど離れた場所に家を買ったため街に出る機会は減ったが、出会いがあるかもしれないと、疲れていても誘いには乗るようにしていると話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（28:50〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=1730s"]]}, {"cat": "リングに来るまで", "t": "トライアウトで周りを手伝って採用に", "b": "WWEのトライアウトでは、ほかの参加者は陸上選手やスタントの女性ばかりで、レスラーは本人だけだったという。列に戻るあいだに受け身のやり方を聞かれて教えていたところ、それが採用の決め手になったのではと話す。自分では「地味で特別なところはなかった」と振り返っている。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（53:28〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3208s"]]}, {"cat": "リングに来るまで", "t": "いつか自分の道場を持ちたい", "b": "いずれは自分でプロレスのトレーニング施設を開きたいとずっと考えてきたという。プロデューサーよりトレーナーの方が向いていると感じているが、まだ準備はできていないそうだ。海外遠征の際には現地の道場を訪ねて交流していると話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（56:37〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3397s"]]}, {"cat": "暮らし", "t": "自費で開く無料セミナー", "b": "ハウスショーが減って時間ができたこともあり、独立系の女性レスラー向けの3日間の無料セミナーを始めたという。約300通の応募から試合映像を見て20人を選び、オーストラリアやイギリス、マレーシアからも参加者が集まるそうだ。参加者は自分の渡航費だけを負担すればよく、宿と移動手段は本人が用意したと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（57:22〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3442s"]]}, {"cat": "暮らし", "t": "10歳からの親友グループ", "b": "10歳のころからの友人たちとずっと仲が良く、互いのセラピストのような存在だという。自分のことは何でも知っている仲で、彼女たちの力になれることがうれしいと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:04:29〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3869s"]]}, {"cat": "体のこと", "t": "心の支えは『四つの約束』", "b": "本『四つの約束』の中でいちばん好きなのは「何事も個人的に受け取らない」という教えだという。人間関係にも仕事にも当てはまり、気持ちを立て直す助けになっているそうだ。自分の幸せは自分で責任を持つという考えにも大きく影響を受けたと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:06:51〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=4011s"]]}, {"cat": "体のこと", "t": "ジャーナルと音楽トレーニングで整える", "b": "気持ちを書き出すジャーナルを、レッスルマニアの前後に1か月ほど休んでいた時期に再開したという。そのころは兄と暮らしていて、友人はカリフォルニアにいたため、ひとりの時間が長かったそうだ。音楽をかけながらの筋トレが自分のセラピーだと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:10:02〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=4202s"]]}, {"cat": "体のこと", "t": "グレイソン・ウォーラーの勧めでランニング再開", "b": "しばらくやめていたランニングを、グレイソン・ウォーラーに背中を押されて再開したという。アプリまで教えてもらったが、まずは自分のペースで距離を伸ばしているそうだ。いつまでも現役ではいられないので、将来はマラソン大会にも出てみたいと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:10:53〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=4253s"]]}, {"cat": "体のこと", "t": "ヒールは膝と腰がもたない", "b": "契約したばかりのころはヒールの靴で会場入りしようとしたが、うまく歩けなかったという。年月がたつにつれ膝や股関節、腰がつらくなり、いまは履かないそうだ。自分はそそっかしいとも話している。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:17:18〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=4638s"]]}, {"cat": "家族", "t": "甥と姪に「夢はかなう」と伝える", "b": "甥たちや1歳半の姪に、やりたいことは何でも実現できると伝えているという。自分自身が、テレビの向こうの別世界だと思っていた場所に本当にたどり着いたからだと話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:24:34〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=5074s"]]}, {"cat": "リングに来るまで", "t": "契約時に問われた「本当に好きか」", "b": "インディー時代の練習は週2回、夜2時間だけで、試合も2か月に1、2回ほどだったという。契約が決まったとき、トレーナーに「これからは毎日レスリングだぞ、それだけ好きか」と聞かれ、急に不安になったそうだ。結果的に心から好きだと分かり、今もその気持ちに感謝していると話す。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-19oLjJbowtw", "src": [["公式YouTube（1:28:34〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=5314s"]]}]);
  if (PROFILES["AJ Lee"]) PROFILES["AJ Lee"].facts.push({"cat": "暮らし", "t": "NXT時代に45分語りかけてくれた", "b": "NXT時代、面識のなかったAJ・リーが45分も話を聞いてくれ、「自分らしさは変えずに、求められることには歩み寄って」と助言してくれたと、ベイリーが話している。その会話をずっと大切にしているという。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で、ベイリーの話（公式字幕を全文確認）", "src": [["公式YouTube（45:37〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2737s"]], "by": "第三者の話"});
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "落ち込む後輩を励ました姿", "b": "自分の試合内容に落ち込んでいた女子選手を、リア・リプリーが「まだ何年もある、気にするな」と励ましていたと、ベイリーが話している。10歳近く年下だが、すでにリーダーの役割を担っていると感心したそうだ。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で、ベイリーの話（公式字幕を全文確認）", "src": [["公式YouTube（41:40〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=2500s"]], "by": "第三者の話"});
  if (PROFILES["Natalya"]) PROFILES["Natalya"].facts.push({"cat": "暮らし", "t": "昇格したての頃に支えてくれた先輩", "b": "メインロスターに上がった最初の1年、ナタリヤ、タミーナ、ナオミがいつも気にかけてくれ、リーダーとしてのふるまい方を教わったと、ベイリーが話している。自分も同じように後輩に接しようと決めたという。", "sp": "ベイリー", "d": "2026-01-15", "how": "ステファニーの番組で、ベイリーの話（公式字幕を全文確認）", "src": [["公式YouTube（58:02〜）", "https://www.youtube.com/watch?v=19oLjJbowtw&t=3482s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-19oLjJbowtw", d: "2026-01-15", show: "wys", who: ["Bayley"], t: "ベイリーの回　12歳の初観戦から、後輩を育てる無料セミナーまで", lead: "ステファニー・マクマホンの番組に出た約95分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bayley"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-19oLjJbowtw").map((x) => [x.t, x.b, x.sp])), open: ["誕生日（6月15日）と父の日が重なる話の部分は、ゲストと同席スタッフの発言が入り混じっていて話者を追えなかったため、載せていない。", "観客から物を投げつけられた話や、ヒール転向の意味についての質問は、話者がはっきりしないか本人の答えが具体的でなかったため省いた。", "セミナーの具体的な講師陣や運営の話、女子部門の今後についての意見は、選手の素顔の項目から外した。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=19oLjJbowtw"]] });
