  if (!PROFILES["Jackie Redmond"]) PROFILES["Jackie Redmond"] = { lead: "アイスホッケー中継が夢だったカナダ出身のインタビュアー。オーディション番組からキャリアを始め、今はホッケーとWWEの両方で活躍している。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jackie%20Redmond"]], moves: [], facts: [] };
  if (PROFILES["Jackie Redmond"]._weak) { PROFILES["Jackie Redmond"].lead = "アイスホッケー中継が夢だったカナダ出身のインタビュアー。オーディション番組からキャリアを始め、今はホッケーとWWEの両方で活躍している。"; delete PROFILES["Jackie Redmond"]._weak; }
  PROFILES["Jackie Redmond"].facts.push(...[{"cat": "リングの話", "t": "手をたたく合図が得意", "b": "収録の始まりに手をたたいて合図するのが得意で、「たたき方には自信がある」と笑う。駆け出しのころは「3、2、1」のすぐ後に話し始めてしまい、上司に「1の後にひと呼吸置いて」と注意されたそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（0:53〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=53s"]]}, {"cat": "リングに来るまで", "t": "初めての司会はプロレス番組", "b": "放送の仕事を始めたころは試合映像の編集ばかりで、初めて本格的に司会を任されたのは、カナダのスポーツ局のプロレス番組だったという。レネイ・ヤングの後任で、「子どものころ4年ほど夢中で見ていた」と答えて引き受けたそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（4:09〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=249s"]]}, {"cat": "家族", "t": "姉と夢中になったハーディーズ", "b": "姉と一緒に、ハーディー・ボーイズにはまってプロレスを見始めたという。ザ・ロックやストーン・コールドの時代で、大会を映画館の中継で見に行っていたそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（4:09〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=249s"]]}, {"cat": "リングに来るまで", "t": "ノバスコシア生まれ、オンタリオ育ち", "b": "生まれはノバスコシア州ハリファックス、育ちはオンタリオ州ロンドンで、ネットに書かれている「トロント出身」は間違いだという。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（5:00〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=300s"]]}, {"cat": "リングに来るまで", "t": "名門校を4日で辞めた", "b": "大学卒業後、地方局でのインターンが仕事になったところで、憧れのジャーナリズム大学院に合格したという。通ってみると教室より現場の方がずっと学べると感じ、学費が戻る翌日に退学して元の局へ戻ったそうだ。この話を公の場でするのは初めてだと話す。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（5:47〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=347s"]]}, {"cat": "リングに来るまで", "t": "夢はホッケー中継", "b": "子どものころからの夢はカナダの国民的なホッケー中継に出ることで、長く追いかけてかなえたという。今はウェイン・グレツキーと一緒に番組に出ていて、子どものころの夢でも想像できなかったと話す。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（9:00〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=540s"]]}, {"cat": "リングに来るまで", "t": "フィギュアからホッケーへ", "b": "3〜4歳でフィギュアスケートを始めたが、姉のホッケーの試合で乱闘が起きて勝ち上がるのを見て、自分もやりたいと母に言ったという。母は泣いたそうだ。9歳でホッケーを始めたのは、カナダではかなり遅いと話す。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（9:52〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=592s"]]}, {"cat": "リングに来るまで", "t": "ホッケーの話をしている時が一番自分らしい", "b": "高校で周りの目が気になり始めたころ、ホッケーの話をしているときだけは自信を持てたという。その気持ちを追いかけようとスポーツの道を選んだそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（11:28〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=688s"]]}, {"cat": "リングに来るまで", "t": "オーディション番組で優勝", "b": "スポーツキャスターを選ぶオーディション番組で優勝し、局と1年契約を結んだのがデビューだという。課題で勝ち続けたことで周りに冷たくされ、テレビで泣いてしまったこともあったと振り返る。駆け出しのころ「ただのコンテスト優勝者」と言われ、見返してやると思ったそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（13:06〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=786s"]]}, {"cat": "リングに来るまで", "t": "恩人はレネイ・パケット", "b": "そのオーディション番組の審査員だったのがレネイ・パケット（レネイ・ヤング）で、キャリアの恩人だという。レネイがWWEに移る際には、ビザのための推薦状を自分が書いたそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（15:33〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=933s"]]}, {"cat": "リングの話", "t": "イヨ・スカイは怖いもの知らず", "b": "今好きな選手はイヨ・スカイ。リングサイドで見ると、何でもやってのける怖いもの知らずぶりに驚かされるという。ジェイ・ウーソやCMパンクも挙げている。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（18:50〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=1130s"]]}, {"cat": "好きなもの", "t": "CMパンクとホッケー仲間", "b": "CMパンクとはWWE入りの前からホッケーを通じて知り合いだったという。自分は約60年優勝のないメープルリーフスのファンで、ブラックホークス好きのパンクから毎週のように冷やかしのメッセージが届くそうだ。控室の人の多さにまだ慣れていなかったころ、パンクの復帰はほっとしたと話す。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（19:37〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=1177s"]]}, {"cat": "暮らし", "t": "WWEで一番大変な移動", "b": "今もカナダ東部のノバスコシア州に住んでいて、毎週入国審査を通り、乗り継ぎで会場に向かうという。直行便は3か月に1度ほどで、3回乗り継ぐ日もあるそうだ。", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ZDbOjVyldRY", "src": [["番組のYouTube（26:41〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=1601s"]]}]);
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "リーフスをからかうメッセージ", "b": "パンクは、メープルリーフスが負けるたびに、からかう画像を前触れもなく送ってくるといい、控室の前で「リーフスはどうした」と大声で冷やかしたこともあると、ジャッキー・レドモンドが話している", "sp": "ジャッキー・レドモンド", "d": "2026-01-15", "how": "クリス・ヴァン・ヴリートの番組で、ジャッキー・レドモンドの話（字幕を全文確認）", "src": [["番組のYouTube（21:58〜）", "https://www.youtube.com/watch?v=ZDbOjVyldRY&t=1318s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-ZDbOjVyldRY", d: "2026-01-15", show: "ext", who: ["Jackie Redmond"], t: "ジャッキー・レドモンドの回　ホッケー少女からWWEの控室へ", lead: "クリス・ヴァン・ヴリートの番組に出た約74分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jackie Redmond"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ZDbOjVyldRY").map((x) => [x.t, x.b, x.sp])), open: ["後半（28分以降）の話は今回は読んでいない。", "スポンサーの宣伝部分は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ZDbOjVyldRY"]] });
  if (!ROSTER.find((r) => r[1] === "Undertaker")) ROSTER.push(["アンダーテイカー", "Undertaker", "lg", "殿堂入りした伝説の王者", "", "", ""]);
  if (!PROFILES["Undertaker"]) PROFILES["Undertaker"] = { lead: "ヒューストンで育ち、マスカラスに憧れた少年が、不気味なキャラを長年生き抜いた伝説になった。酒場の流儀から舞台裏の教え、後輩への思いまで語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Undertaker"]], moves: [], facts: [] };
  if (PROFILES["Undertaker"]._weak) { PROFILES["Undertaker"].lead = "ヒューストンで育ち、マスカラスに憧れた少年が、不気味なキャラを長年生き抜いた伝説になった。酒場の流儀から舞台裏の教え、後輩への思いまで語る。"; delete PROFILES["Undertaker"]._weak; }
  PROFILES["Undertaker"].facts.push(...[{"cat": "暮らし", "t": "ポッドキャストは「時々おもしろい」", "b": "自分のポッドキャストを持っていて、司会をするのは楽しい瞬間もあると話す。会話がはずむ日はいいが、話したがらないゲストだと歯を抜くような苦労になるそうだ。他のポッドキャストはあまり聴かないという。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（0:49〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=49s"]]}, {"cat": "リングの話", "t": "ウイスキーうがいの由来", "b": "新人を呼んで酒を飲ませる習慣では、自分は強要したことも、うがいをしたこともないと話す。もとは景気が悪い時代に、賃金が少ない若手が高い酒を床に捨ててごまかしたことが発端だという。飲んだ証拠にうがいをさせるようになり、のちに男らしさの儀式として広まったそうだ。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（4:11〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=251s"]]}, {"cat": "暮らし", "t": "17日続くヨーロッパ巡業の日々", "b": "全盛期は家より巡業先で過ごす時間のほうが長かったという。毎日国が変わる17日間のツアーでは、気が合って神経に障らない仲間が欠かせなかったと話す。酔って調子に乗る者がいれば、仲間内で厳しく釘を刺したそうだ。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（10:33〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=633s"]]}, {"cat": "リングの話", "t": "オーストラリアの興行で若手に檄を飛ばす", "b": "連戦のあと飛行機で向かったオーストラリアの興行で、満員の会場なのに試合の大半が気の抜けた内容だったと振り返る。見ていて腹が立ち、担当のフィット・フィンレーに断ってから、仲間たちに向けて演説したという。翌日のニュージーランドでは雰囲気が大きく良くなったそうだ。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（12:03〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=723s"]]}, {"cat": "リングの話", "t": "あの名物シーンは教えるための仕掛けだった", "b": "英国ツアーで毎晩見せた、ホットタグ直前に場外を歩き回って水をかぶる動きは、後輩に見せて教えるためのものだったと話す。言葉で説明しても、実際の試合では全く違う形になる若手が多いので、体験させるのが一番だと考えたそうだ。テレビでは一度もやらなかったという。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（18:44〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=1124s"]]}, {"cat": "リングに来るまで", "t": "ヒューストン育ち、憧れはミル・マスカラス", "b": "ヒューストンで育ち、地元のプロレスを見て大きくなったという。いちばん好きだったのは、覆面で動きが流れるように美しいミル・マスカラスだった。意外な答えだと自分でも笑う。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（30:07〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=1807s"]]}, {"cat": "リングに来るまで", "t": "12、13歳でアンドレの手に触れた", "b": "少年時代、地元には巡業の大物が次々にやって来たという。12歳か13歳のころ、アンドレ・ザ・ジャイアントと握手できたのが忘れられないそうだ。当時の選手たちは荒々しく、子どもでも怖さを感じたと話す。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（34:08〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2048s"]]}, {"cat": "家族", "t": "母がとった席でシークに肝を冷やす", "b": "11、12歳のころ、母が通路側の席のチケットを取ってくれ、友だちと大はしゃぎで会場に行ったという。初代シークに何か言ってやると一週間盛り上がっていたが、本人が向かってきた瞬間、観客を何人も巻き込んで逃げ出したそうだ。あのころの悪役は本物に見えたと話す。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（34:59〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2099s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズ以上の相手はいない", "b": "ショーン・マイケルズは、飛んだり受けたりが上手いだけでなく、殴り合いになった瞬間に観客を信じさせる「闘犬」の気迫があったと話す。一緒に試合をするなら、これ以上の相手はいないと感じていたそうだ。試合をするのは「休みの夜のように楽」なのだという。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（38:52〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2332s"]]}, {"cat": "リングの話", "t": "レッスルマニア40の登場シーン", "b": "あの大舞台は、仕掛け人のトリプルHと細かく相談したうえで臨んだ場面だったと話す。照明が落ちる直前のウインクは自分の狙いではなく、偶然だったという。それでも、若い世代に花を持たせる一日になれて光栄だと語る。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（44:31〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2671s"]]}, {"cat": "体のこと", "t": "両ひざを人工関節にして走った", "b": "その少し前に、両ひざを人工関節に取り替えていたという。レッスルマニア40では急いでリングに向かうことになり、新しいひざで初めて走ったそうだ。息は上がったが「まだいける」と驚き、その後も問題はないと話す。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（51:01〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=3061s"]]}, {"cat": "リングの話", "t": "AAAでは一歩下がってから前へ進む", "b": "いまは創作面の手伝いや、メキシコのAAAの仕事に関わっているという。方針は、試合の動きや筋の通り方を大切にする原点に戻ることだと話す。覆面の伝統は守りつつ、演出や物語の見せ方を高めたいそうだ。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（52:36〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=3156s"]]}, {"cat": "リングの話", "t": "キャラを生きるには、信じ切ること", "b": "キャラクターになりきるには、本人がそれを信じて貫くしかないと話す。空港でも黒ずくめで、周囲との接し方を計算していたという。自分に響く何かを見つけて、覚悟を決めることが大事だそうだ。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（57:36〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=3456s"]]}, {"cat": "リングの話", "t": "ブレット・ハートに引き上げられた", "b": "ブレット・ハートは、怪物キャラ一本の自分をどこまでも持ち上げる気はなかったという。そのおかげで、キャラの枠を出て、本物のレスリングの試合をする力がついたと話す。今も感謝していると語る。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:02:34〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=3754s"]]}, {"cat": "リングの話", "t": "サバイバー・シリーズ初登場の緊張", "b": "デビュー戦のサバイバー・シリーズでは、キャラの形もまだ固まっていなかったという。相手は大ベテラン揃いで、独特の気まずい空気だったが、ダスティ・ローデスとは場外のカウントアウトで決着したそうだ。デビューの日は緊張の連続だったと振り返る。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:07:29〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4049s"]]}, {"cat": "リングの話", "t": "初日にココ・B・ウェアに詰め寄られた", "b": "最初のツームストーンを受けたココ・B・ウェアが、控室で強く抗議してきたという。何度も謝ったが収まらず、「外に出るか」と思うほどだったそうだ。しかしその後は仲良くなったと話す。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:13:53〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4433s"]]}, {"cat": "好きなもの", "t": "最強の4人は弟ケインとショーンとアングルとアンドレ", "b": "夢のチームを聞かれ、まず兄弟分のケイン、続いてショーン・マイケルズ、カート・アングルを挙げる。四人目はアンドレだという。ケンカの口火はショーン、仕上げはカートとケインという役割分担まで話す。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:27:35〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=5255s"]]}]);
  if (PROFILES["Mil Mascaras"]) PROFILES["Mil Mascaras"].facts.push({"cat": "暮らし", "t": "シャワーでも覆面をつけていたマスカラス", "b": "WCW時代に同じ大会で、シャワー中も覆面をつけているのを見たと、アンダーテイカーが話している。顔を洗う一瞬だけ外して、すぐ戻したそうだ。この徹底ぶりが、のちに自分がキャラを作るときの支えになったかもしれないという。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で、アンダーテイカーの話（公式字幕を全文確認）", "src": [["公式YouTube（30:55〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=1855s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "ダスティ・ローデスは仕事がわかる人だった", "b": "サバイバー・シリーズで共にカウントアウトに持ち込んだダスティ・ローデスについて、扱いにくいことは全くなく、ビジネスをよくわかっている人だったと、アンダーテイカーが話している。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で、アンダーテイカーの話（公式字幕を全文確認）", "src": [["公式YouTube（1:10:40〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4240s"]], "by": "第三者の話"});
  if (PROFILES["Big Show"]) PROFILES["Big Show"].facts.push({"cat": "暮らし", "t": "ビッグショーには厳しく言った", "b": "ビッグショーは本当に好きだが、才能を全部使ってほしいという愛情から、たくさん小言を言ったと、アンダーテイカーが話している。カリとの控室の殴り合いでは、ショーの右の一撃の音が分厚い肉を置くような音だったという。", "sp": "アンダーテイカー", "d": "2026-01-22", "how": "コーディの番組で、アンダーテイカーの話（公式字幕を全文確認）", "src": [["公式YouTube（1:17:07〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4627s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングの話", "t": "WM39の前週、椅子が顔に当たった", "b": "レッスルマニア39の1週間前、デンバーの6人タッグで、アンダーテイカー流の椅子の動きをしたところ、レフェリーに止められて椅子が顔を直撃したという。初のメインを前に、縫う羽目にならないかと試合中ずっと不安だったそうだ。大事には至らなかった。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（22:43〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=1363s"]]}, {"cat": "家族", "t": "母はポール・ボーシュの大ファン", "b": "母は、ヒューストンのプロレスを仕切ったポール・ボーシュを名プロモーターとして評価していたと話す。自分もボーシュ氏のベルトバックルを持っているという。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（33:17〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=1997s"]]}, {"cat": "家族", "t": "祖父は金曜の観戦で野次を飛ばした", "b": "父ダスティの父で配管工のバージルは、金曜の夜にプロレスを見に行き、悪役に大声で野次を飛ばすのが息抜きだったと、あとで知ったという。ただの観客ではなく、思いを悪役に届けたい人だったと語る。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（37:18〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2238s"]]}, {"cat": "リングの話", "t": "トリプルHの助言で挑んだ一撃", "b": "悪役のダッシング・コーディ時代、トリプルHに「ひるまず向かっていき、もう一発受けろ」と言われたという。一度だけブッカー・Tに試したところ、右手で耳を打たれ、鼓膜をやられてしまったと笑う。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（40:23〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2423s"]]}, {"cat": "家族", "t": "妻に「頂点だった」とは言いたくなかった", "b": "レッスルマニア40のあと、妻に「もう頂点を見てしまった」と言いたくなかったと話す。道はこれから始まるが、あの場所に立てたこと自体が幸運だったと考えているそうだ。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（48:37〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=2917s"]]}, {"cat": "リングの話", "t": "ビッグショーの一言で変わった考え方", "b": "ビッグショーと海外ツアーで10連戦をしたとき、コメディ路線をやめたいと申し出たという。ショーは不満そうだったが、観客は何でも覚えているから、と受け止めてくれたと話す。この経験がキャリアを変えたそうだ。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:18:46〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4726s"]]}, {"cat": "リングの話", "t": "21歳、初ランブルで9秒の見せ場", "b": "初めてのロイヤルランブルは21歳のころで、出番は短かったという。CMパンクに相談してアンダーテイカーに向かっていき、わずか9秒ほどの場面を作ったそうだ。今でも貴重な経験だと話す。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:22:05〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=4925s"]]}, {"cat": "家族", "t": "父は「負けられる人も入れろ」と言った", "b": "子どものころ、車の中で父にウォーゲームスのチームを考えさせられたという。強い選手ばかり選んでいると、「誰か負ける役を入れろ」と言われたそうだ。ブッカー目線の考え方だったと振り返る。", "sp": "コーディ・ローデス", "d": "2026-01-22", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-lyPr8qqVuPI", "src": [["公式YouTube（1:29:15〜）", "https://www.youtube.com/watch?v=lyPr8qqVuPI&t=5355s"]]}]);
  ARTICLES.push({ id: "wdywta-lyPr8qqVuPI", d: "2026-01-22", show: "wdywta", who: ["Undertaker", "Cody Rhodes"], t: "アンダーテイカーの回　酒場の流儀と、教えることへのこだわり", lead: "コーディ・ローデスの番組に出た約90分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Undertaker", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-lyPr8qqVuPI").map((x) => [x.t, x.b, x.sp])), open: ["字幕の1:19:38から1:22:05の間は欠けており、その部分の話題は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=lyPr8qqVuPI"]] });
  if (!ROSTER.find((r) => r[1] === "Trish Stratus")) ROSTER.push(["トリッシュ・ストラタス", "Trish Stratus", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Trish Stratus"]) PROFILES["Trish Stratus"] = { lead: "カナダ出身で、50歳を迎えても鍛えることをやめない努力家。家族と仲間を大切にしながら、いつも新しい挑戦を楽しんでいるという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Trish%20Stratus"]], moves: [], facts: [] };
  if (PROFILES["Trish Stratus"]._weak) { PROFILES["Trish Stratus"].lead = "カナダ出身で、50歳を迎えても鍛えることをやめない努力家。家族と仲間を大切にしながら、いつも新しい挑戦を楽しんでいるという。"; delete PROFILES["Trish Stratus"]._weak; }
  PROFILES["Trish Stratus"].facts.push(...[{"cat": "体のこと", "t": "食事は「ほどよいバランス」派", "b": "普段は食事を整えているが、子どもたちとハンバーガーに行けばポテトも食べるとトリッシュは話す。大きな仕事の前は数週間かけて準備し、そこから緩める時期をつくるという。極端に絞ってまた戻す生活より、一定のペースを保つほうが自分には合っていると語っている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（2:29〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=149s"]]}, {"cat": "体のこと", "t": "コロナ禍で初めて立ち止まった", "b": "22歳でフィットネスモデルを始めてから約20年、いつも見られる前提で働き詰めだったそうだ。パンデミックのときに初めて気を緩め、動画配信サービスを見ながらお菓子を食べる時間を楽しんだという。ただ、年齢とともに戻しにくくなると気づき、2021年の初めから再び毎日の習慣に戻したと話す。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（3:17〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=197s"]]}, {"cat": "体のこと", "t": "トレーニング歴は27年", "b": "雑誌で「秘訣は？」と聞かれ、27年間やめずに続けてきたことだと答えたとトリッシュは話す。大切なのは続けることで、始めるのに遅すぎることはないという考えだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（4:50〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=290s"]]}, {"cat": "リングに来るまで", "t": "子どもの頃からスポーツ少女", "b": "フィールドホッケーやサッカーなど、幼いころから競技に打ち込んできたという。負けず嫌いで、ベンチに座っているのは好きではないと話す。その競争心が、その後の仕事での成功にもつながったと聞き手に評されている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（4:50〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=290s"]]}, {"cat": "暮らし", "t": "居心地のいい場所を出て挑戦する", "b": "自分は挑戦があるほど燃えるタイプで、あえて慣れた場所から踏み出すのが好きだとトリッシュは話す。カナダの殿堂イベントの司会では、歌とダンスのオープニングを自分から提案したそうだ。コーチについて振り付けまで練習し、「自分でやり遂げた」と思えたのがうれしかったという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（5:43〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=343s"]]}, {"cat": "リングの話", "t": "ベッキー・リンチ戦でケージを初体験", "b": "鋼鉄のケージ戦は、かつて男子だけのものだったと聞き手が振り返り、トリッシュ自身も初めての経験だったと話す。昔は女子のケージ戦でも、ケージに触れないよう指示されたほどだったそうだ。復帰後は「昔できなかったこと」に挑むのを楽しんでおり、実際にケージを登って飛び降りたという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（6:32〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=392s"]]}, {"cat": "好きなもの", "t": "自分の名前をつけた造語が好き", "b": "自分の名前を入れて物の呼び名をつけるのが癖で、周囲に呆れ顔をされても気にしないとトリッシュは話す。自分の誕生日の時期を「トリッシュマス」と呼ぶのもその一つだそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（8:10〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=490s"]]}, {"cat": "家族", "t": "妊娠中に殿堂入りが決まった", "b": "殿堂入りの知らせを受けた直後に妊娠が分かり、番組側が望むような展開に応じられないのではと悩んだとトリッシュは話す。まず親友のステファニーに電話で相談し、妊娠を発表する形で式に臨むことになったという。ファンも温かく迎えてくれたそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（12:11〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=731s"]]}, {"cat": "家族", "t": "母の病気を機に一度は引退を決めた", "b": "2006年、会社から5年の契約を提案されたころに、母が血液のがんと診断されたという。治療に付き添える日程ではないと考え、迷った末に引退を選んだとトリッシュは話す。そのとき相談に乗ってくれたのがステファニーだったそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（13:00〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=780s"]]}, {"cat": "家族", "t": "父の最期の時期にも支えがあった", "b": "年間最大の祭典に出る予定だった年、父が入院していて迷ったが、「父のそばにいなさい」と背中を押されたという。のちに母を見送るときも、同じ友人が寄り添ってくれたとトリッシュは話す。長い付き合いの中で、人生の節目に支え合ってきたそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（13:47〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=827s"]]}, {"cat": "リングの話", "t": "お尻より試合を見てほしいと衣装を選んだ", "b": "トリッシュは、観客に「お尻」ではなく試合を見てもらいたい気持ちから、あえてパンツ姿を選んできたと話す。短パンで戦ったのはキャリア全体で3回ほどだそうだ。女性の衣装は、テープでの固定など考えることが多いとも語っている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（27:21〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=1641s"]]}, {"cat": "リングの話", "t": "引退試合はズボンが下がり続けた", "b": "引退試合では、パンツがずり落ちてずっと下着が見えていたという。直すと観客の気持ちが途切れるため、直さずに最後まで戦ったとトリッシュは話す。本当に痛ければ見た目など気にしないはずだ、という考え方だそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（28:09〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=1689s"]]}, {"cat": "暮らし", "t": "「初恋の人」と呼ばれるのは悪くない", "b": "最近の復帰のとき、「あなたは私の初恋」と書かれたシャツを着たファンがいたとトリッシュは話す。サインを頼まれるときも、その一言を添えるよう求められることが増えたそうだ。親子二世代から好かれるのはうれしいし、悪い気はしないと笑っている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（28:59〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=1739s"]]}, {"cat": "暮らし", "t": "集中するときは区画を分けて没頭", "b": "カレンダーの撮影は12のコスチュームを、1日6パターン、15時間かけて撮ったという。トリッシュは何かに打ち込むときは「その区画」だけに集中し、ほかの話は後回しにするタイプだと話す。聞き手も同じ性格で、集中力は長所でも短所でもあると語っている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（32:12〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=1932s"]]}, {"cat": "リングの話", "t": "ストラップ戦で背中にみみず腫れ", "b": "ストラップを使った試合のあと、背中に深いみみず腫れができ、座るのも難しかったとトリッシュは話す。翌朝の打ち合わせで、周囲のスタッフが気遣う言葉をかけてくれたが、本人は「痛くなかった」と平気な顔をしたそうだ。顔の青あざや骨折を経験しても、弱音は見せない姿勢だったという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（39:20〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=2360s"]]}, {"cat": "暮らし", "t": "自分の会社で2026年カレンダーを発売", "b": "チームから勧められ、2026年版のカレンダーを出したという。「いまどき壁掛けのカレンダーを買う人がいるのか」と思ったが、実際によく売れたそうだ。トリッシュは仕事を自分で動かすタイプの実業家でもあると、周りから評されている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（40:33〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=2433s"]]}, {"cat": "リングの話", "t": "女子初のメインイベントは「失敗しないこと」が目標", "b": "女子が初めてメインを務めた試合で、当時のトリッシュたちの目標は「その夜を台無しにしない」ことだけだったという。のちに女子レスリングが広がる一段目になるとは思わず、前列で観ていた若い選手が影響を受けたと知って驚いたそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（48:49〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=2929s"]]}, {"cat": "暮らし", "t": "ファン交流の場で届く声が励みに", "b": "今はサイン会などで、ゆっくりファンと話せるのがうれしいとトリッシュは話す。初めて観た試合の思い出を教えてくれる人や、「あなたのようになりたい」と言う少女に出会うという。レスラーになりたいのではなく、情熱を追う女性の姿に憧れてくれるのだと受け止めている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（49:37〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=2977s"]]}, {"cat": "家族", "t": "子どもたちが初めて生の試合を観戦", "b": "トロントで開かれた大会に、息子と娘が初めて観に来たとトリッシュは話す。それまでは何となく知っている程度だったが、生で見て受け止め方が変わったそうだ。2025年は3度しか試合をしなかったが、その中で家族が見てくれた意味は大きかったという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（54:29〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3269s"]]}, {"cat": "家族", "t": "娘は物語にのめり込み、試合を分析", "b": "女性選手が集まる大会を観た娘は、筋書きにすっかり夢中になったという。母が負けたあとは「どうして転がって避けなかったの？」と真顔で聞いてきたそうだ。観戦中も「なぜそっちに動くの」と実況のように突っ込むとトリッシュは笑って話す。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（55:15〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3315s"]]}, {"cat": "家族", "t": "娘は興味あるが「痛いのは嫌」", "b": "息子はそこまで入れ込まなかったが、娘は面白いと感じたようだとトリッシュは話す。「レスラーになりたい？」と聞くと、少し考えて「やりたいけれど、けがをしたくない」と答えたという。トリッシュはそれを素直に受け止めたそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（56:05〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3365s"]]}, {"cat": "リングの話", "t": "ケインの大技を受けて宙に浮いた", "b": "トロントでの試合で、とても背の高いケインに大技を受ける展開が決まったという。トリッシュは「面白そう」と即答して引き受けたそうだ。落ちるまでが妙に長く、地面はまだかと思うほど高く持ち上げられたと話す。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（56:52〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3412s"]]}, {"cat": "体のこと", "t": "試合中に肩を脱臼しても演じ続けた", "b": "ある試合でコーナーから投げ落とされた際、とっさに受け身を変えた結果、肩を脱臼したという。それでも暗転するまでは役を崩さず、腕がぶら下がったまま相手に挑発を続けたとトリッシュは話す。のちに骨折もあったと分かり、寒い日は今も軋むそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:00:10〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3610s"]]}, {"cat": "体のこと", "t": "一番の助言は「ヨガをやること」", "b": "後輩から「一番のアドバイスは？」と聞かれると、迷わずヨガと答えるとトリッシュは話す。関節の動きを保ち、体幹も安定するため、40代、50代、60代になっても動き続けられるという。痛いからといって止まると体が固まり、悪循環になるので、動かし続けるのが大切だそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:01:47〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3707s"]]}, {"cat": "リングの話", "t": "復帰前に自分でリングを借りて確認", "b": "2018年、史上初の女子ロイヤルランブルの話が来たとき、10年ぶりで二人の子も産んでいたため、すぐには返事をしなかったという。全力で出せないなら受けない、という考えから、先に練習用のリングを用意してもらったとトリッシュは話す。動画で自分を見て「まだやれる」と確信し、出場を決めたそうだ。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:02:32〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3752s"]]}, {"cat": "リングの話", "t": "体を預け合う信頼が絆になる", "b": "同じ目標に向かい、お互いの体を信頼して預け合うことが、リング仲間との特別な絆を生むとトリッシュは話す。しばらく会わなくても、会えばすぐ元に戻れる関係だそうだ。ミッキー・ジェームズとの再会の場面も、会場の都合で枠が少なかったが、自分たちで働きかけて実現させたという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:05:46〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3946s"]]}, {"cat": "リングの話", "t": "車のボンネットに本当に頭をぶつけた", "b": "ある抗争の場面で、車のボンネットに頭をぶつける受け身を、トリッシュは本物のように見せようとして本当にぶつけてしまったという。目の前が真っ白になるほどで、それでも試合は続けたそうだ。今振り返ると、手探りで体当たりしていた時代だったと笑っている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:06:32〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=3992s"]]}, {"cat": "暮らし", "t": "クリスマス映画の撮影で顔にドアが直撃", "b": "出演したクリスマス映画の撮影では、ドアが開いて顔に当たる場面を、日没前に撮り切るため自分で本気でやったという。監督は顔のけがを心配して青ざめ、替え玉を使うべきだったと動揺したそうだ。トリッシュ本人は「大丈夫」と笑って済ませたと話している。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:10:34〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=4234s"]]}, {"cat": "暮らし", "t": "自分にも自信のなさはある", "b": "新しい挑戦のたびに「自分にできるのか」という不安が出るとトリッシュは話す。審査員を務めたカナダの才能発掘番組も、最初は戸惑ったそうだ。出場者の晴れ舞台を断る立場になり、カナダ人らしく先に謝ってしまう場面もあったという。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:12:52〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=4372s"]]}, {"cat": "リングに来るまで", "t": "初撮影に備えて表紙と契約をつかむ", "b": "初めてのプロの撮影のため、トリッシュはポーズや角度を練習し、食事も睡眠も整えて臨んだという。その結果、そのまま雑誌の表紙になり、専属の契約も決まったそうだ。「チャンスは準備した人のところに来る」というのが自分の信条だと話す。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:15:12〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=4512s"]]}, {"cat": "暮らし", "t": "子どもに伝えたいのは好きなことを見つけること", "b": "この25年、自分を動かしてきたのは「好きなことをする」ことだとトリッシュは話す。つらい時期があっても、好きなら続けられるという考えだ。友人の結婚式や出産に出られなかったこともあるが、何も後悔していないそうだ。子どもたちにも、焦らず自分のやりたいことを探してほしいと伝えている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-HAFkxcol9Jw", "src": [["公式YouTube（1:16:43〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=4603s"]]}]);
  if (PROFILES["Becky Lynch"]) PROFILES["Becky Lynch"].facts.push({"cat": "暮らし", "t": "ベッキー・リンチは「やり切る人」", "b": "ベッキー・リンチを一言で表すと「献身的」で、役柄になりきる姿勢は演技の方法に近いと、トリッシュ・ストラタスが話している。一緒に仕事ができて幸運だったとも述べている。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で、トリッシュ・ストラタスの話（公式字幕を全文確認）", "src": [["公式YouTube（1:25:27〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=5127s"]], "by": "第三者の話"});
  if (PROFILES["Lita"]) PROFILES["Lita"].facts.push({"cat": "暮らし", "t": "リタは親友であり変革者", "b": "リタについて、まず「親友」、そして女子レスリングを変えた人だと、トリッシュ・ストラタスが話している。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で、トリッシュ・ストラタスの話（公式字幕を全文確認）", "src": [["公式YouTube（1:25:27〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=5127s"]], "by": "第三者の話"});
  if (PROFILES["Mickie James"]) PROFILES["Mickie James"].facts.push({"cat": "暮らし", "t": "ミッキー・ジェームズは「王道の名選手」", "b": "ミッキー・ジェームズは数多くの団体で多くの選手とライバル関係を築いてきた、時代を超えて語られる存在だと、トリッシュ・ストラタスが話している。", "sp": "トリッシュ・ストラタス", "d": "2026-01-29", "how": "ステファニーの番組で、トリッシュ・ストラタスの話（公式字幕を全文確認）", "src": [["公式YouTube（1:26:21〜）", "https://www.youtube.com/watch?v=HAFkxcol9Jw&t=5181s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-HAFkxcol9Jw", d: "2026-01-29", show: "wys", who: ["Trish Stratus"], t: "トリッシュ・ストラタスの回　50歳の体づくりと、仲間と笑った思い出話", lead: "ステファニー・マクマホンの番組に出た約89分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Trish Stratus"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-HAFkxcol9Jw").map((x) => [x.t, x.b, x.sp])), open: ["ステファニー自身や家族にまつわる話、番組の宣伝、聞き手が語った話は載せていない。", "話者が聞き手かトリッシュか判別しにくい箇所（コスチュームの事故の話、息が止まった経験の話など）は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=HAFkxcol9Jw"]] });
