  if (PROFILES["Jey Uso"].lead === "") PROFILES["Jey Uso"]._weak = 1;
  PROFILES["Jey Uso"].facts.push(...[{"cat": "リングの話", "t": "勝った直後の記者会見は台本なし", "b": "ジェイ・ウーソは、タッグ王座を獲った直後の記者会見は何も仕込んでおらず、コーディ・ローデスとただ「狩り」をしていただけだと話す。見返すと少し恥ずかしいが、気に入っているそうだ。弟以外とタッグ王座を獲ったのはこのときが初めてで、特別な夜だったという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（0:49〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=49s"]]}, {"cat": "リングの話", "t": "「イート」の大合唱と、アンコール6回", "b": "ジェイ・ウーソは、ダークマッチで観客に「イート」をやらせて6回もアンコールしたことがあると話す。そのときアンダーテイカーから「今、本当に仕事してるな」と言われたそうだ。本当に人気が出ると見せ方が変わると分かってきたので、この熱をできるだけ長く保ちたいと語る。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（6:35〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=395s"]]}, {"cat": "リングの話", "t": "試合で信頼を積み、話す場を与えられた", "b": "ジェイ・ウーソは、双子のタッグは会社から特別に押されたことはなく、リング上の内容で道を開いてきたと話す。信頼されるにつれて、しゃべる機会が増え、着たい衣装も選べるようになったそうだ。今は会社に愛されていると感じ、安心して出ていけるという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（24:56〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1496s"]]}, {"cat": "リングの話", "t": "王座を一度獲っても「まだ足りない」", "b": "ジェイ・ウーソは、ドラマ「アンリアル」でトリプルHから背中を押される場面について聞かれ、自分の中ではまだ何も成し遂げていない感覚があると答えた。一度獲った王座はあっという間で実感が薄かったが、仲間の前で先頭に立つ責任の重さは初めて感じたそうだ。今も「全部取りに行く」気持ちは変わらないという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（29:03〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1743s"]]}, {"cat": "リングの話", "t": "「仲間の一人」ではいられなくなる", "b": "ジェイ・ウーソは、上の立場になると、他の選手と同じ感覚では付き合えなくなると話す。感情を結びつけすぎると、いざ対戦になったときにお互い本気で怒ってしまうので、仕事と割り切る必要があるそうだ。仲間と過ごすのは好きだが、一線を引く時期が来ると語る。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（31:25〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1885s"]]}, {"cat": "リングの話", "t": "トップロープを外した姿もカメラに映った", "b": "ジェイ・ウーソは、「アンリアル」にトップロープに飛びそびれて息が上がった自分が映ったと話す。試合が週1回なので、スタミナをつけるべきだと反省したそうだ。舞台裏の撮影は気づかないうちに回っていて、驚いたという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（47:21〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2841s"]]}, {"cat": "リングの話", "t": "子どもたちに向けて戦いたい", "b": "ジェイ・ウーソは、プロレスは子どものためのものだと考え、入場では子どもを探して一緒に「イート」をやると話す。歓声が気にならないわけではなく、食べていくための仕事だとも認めている。それでも、まず目を向けるのは子どもたちだという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（51:23〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3083s"]]}, {"cat": "リングの話", "t": "入場に全力を出して、試合のことを忘れる", "b": "ジェイ・ウーソは、入場で全力を出しすぎて、そのあと試合があることを忘れると自分で笑う。それでも二度目の勢いが出るので悪くないそうだ。試合後は一人で「今夜を無駄にしなかったか」と自問し、席を狙う後輩に渡したくないと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（52:12〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3132s"]]}, {"cat": "リングの話", "t": "ブラッドラインは「走りながら作った」物語", "b": "ジェイ・ウーソは、ブラッドラインの物語が歴史的だと言われても、当時は毎週「先週は何をした？」と考えながら続けていただけだと振り返る。停滞しかけるたびに、ある場面のような出来事が風向きを変えたそうだ。毎回、その場で舵を切っていたという。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（1:00:03〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3603s"]]}, {"cat": "リングの話", "t": "無観客時代に生まれた、言葉で見せる試合", "b": "ジェイ・ウーソは、無観客の時期に、リング上で声を張って会話するスタイルを選んだと話す。バスケットの草試合のように声が聞こえるので、相手の言葉に合わせて演技を重ねたそうだ。観客が戻ってからもその要素を残し、「シネマ」と呼ばれるようになったという。兄弟と向き合うリング上の会話は本物の感情なので、笑いをこらえるのが大変だそうだ。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（1:01:37〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3697s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Jey Uso")) ROSTER.push(["ジェイ・ウーソ", "Jey Uso", "lg", "元世界ヘビー級王者", "", "", ""]);
  if (!PROFILES["Jey Uso"]) PROFILES["Jey Uso"] = { lead: "下積み時代の父リキシのもとで、おさがりの服を着て育ったという。物心ついた頃からプロレスが日常で、今も「これは仕事じゃない」と言い切り、子どもの観客に全力で向き合っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jey%20Uso"]], moves: [], facts: [] };
  if (PROFILES["Jey Uso"]._weak) { PROFILES["Jey Uso"].lead = "下積み時代の父リキシのもとで、おさがりの服を着て育ったという。物心ついた頃からプロレスが日常で、今も「これは仕事じゃない」と言い切り、子どもの観客に全力で向き合っている。"; delete PROFILES["Jey Uso"]._weak; }
  PROFILES["Jey Uso"].facts.push(...[{"cat": "家族", "t": "父の「お前はつかんだ」", "b": "父は口数が少なく、大一番のあとに話しても多くは語らず「お前はつかんだ」とだけ言うという。何をつかんだのか分からず、今もその意味を探っているそうだ。それでも、それが父なりのお墨付きだと受け止めていると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（9:46〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=586s"]]}, {"cat": "好きなもの", "t": "夢のチームは往年の大型選手", "b": "好きなメンバーで組む夢のチームを聞かれ、まずは自分たちのユニットを挙げたという。そのうえで1人加えるなら、ウマガ、ヨコヅナ、ベイダー、そして父リキシといった往年の大型選手たちを選んだそうだ。誰にも負けないチームだと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（12:06〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=726s"]]}, {"cat": "家族", "t": "父の下積みで貧しかった少年時代", "b": "父は各地の団体を回る下積みが長く、ブレイクしたのは自分が高校1年のころだったという。それまでは家にお金がなく、おさがりの服を着て育ち、苦しさが分かる年齢だったそうだ。今自分がこの世界にいて、父がどれだけ必死に稼ごうとしていたかがよく分かると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（13:43〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=823s"]]}, {"cat": "リングに来るまで", "t": "ペンサコーラのサモア系大家族で育つ", "b": "フロリダ州ペンサコーラの小さな町で、サモア系の大家族の中で育ったという。双子の兄弟といとこのローマン・レインズとは同じ球場で一緒に大きくなったそうだ。3人ともフットボールが得意で、貧しさをそれがカバーしてくれたと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（14:33〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=873s"]]}, {"cat": "家族", "t": "父が来ると人だかりができた", "b": "巡業で家を空けがちな父は、フットボールの試合にほとんど来られなかったという。父がリキシとして売れてからは、会場に現れると人の群れがついてくるので、フィールドからでも「父さんが来た」と分かったそうだ。それが「いいプレーをしたい」という力になったと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（14:33〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=873s"]]}, {"cat": "家族", "t": "父の教えは「変わり続けろ」", "b": "父は試合に駆けつけたあとまた仕事に戻り、キャラクター作りにも頭を悩ませていたという。父の口ぐせは「立ち止まるな、進化し続けろ、でないと追い抜かれる」で、いくつもキャラクターを変えた末にリキシにたどり着いたそうだ。うまくいくものを見つけたら手放さず全力を注げ、という教えも受け継いでいると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（15:21〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=921s"]]}, {"cat": "家族", "t": "今も元気な父が一番のファン", "b": "今のレスラー生活も楽ではないが、父の時代はもっと過酷だったと思うという。周りの親世代が年を重ねていく中、父がいまも健在で健康なことをありがたく感じているそうだ。父が自分たちの一番のファンなのは間違いないと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（16:06〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=966s"]]}, {"cat": "体のこと", "t": "重圧を楽しめるようになった", "b": "テレビ収録の日は早く会場入りし、番組中も取材などをこなしながら試合のことを考えるので、ストレスは大きいという。昔はそれで取り乱していたが、今は追い込まれた状況を自分で回せるようになったそうだ。求められたら応える、その感覚が好きだと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（22:34〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1354s"]]}, {"cat": "リングに来るまで", "t": "推されず、リングの実力で上がってきた", "b": "キャリアの初めから、会社に強く後押しされる立場ではなかったという。リングでの働きで少しずつ信頼を得て、マイクを任され、衣装も自由に選べるようになったそうだ。双子のタッグとして見られていた自分が、今では個人として知られるようになったことに誇りを持っていると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（24:56〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1496s"]]}, {"cat": "リングに来るまで", "t": "4、5歳からこの世界が日常", "b": "プロレス一家に生まれ、4、5歳のころからこの世界しか知らずに育ったという。だからプロレスは「仕事」ではなく、やりたいと思って選んだという感覚すらないそうだ。この感覚は、同じように育った人にしか分からないと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（27:28〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1648s"]]}, {"cat": "体のこと", "t": "若くはないが、あと15年いける", "b": "もう若手ではないと自覚しつつ、体は強く調子もいいと感じているという。あと15年でも続けたいそうで、プロレスに人生を捧げてきたし、これからもそうすると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（27:28〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1648s"]]}, {"cat": "家族", "t": "父直伝「黙って考え、あとで返す」", "b": "会議でみんなが案を出し合う場面について、父から「黙って座って考え、『あとで返事する』と言えばいい」と教わったという。コーディが自分も似たやり方をしていると話すと、それは父と同じだと驚いていた。父のことを「OG（大御所）」と笑う。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（32:11〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1931s"]]}, {"cat": "体のこと", "t": "週1の試合でスタミナが課題に", "b": "密着ドキュメンタリーで、ロープを踏み外して息が上がっている姿が映ったことに触れ、疲れることは正直あると認めたという。今は試合が週1回ほどなので、スタミナを上げる必要があったそうだ。舞台裏の小さなカメラにまで気づいていなかったと笑う。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（47:21〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2841s"]]}, {"cat": "家族", "t": "支えは家族と身近な人の愛", "b": "つらいときに踏ん張る秘訣を聞かれ、信頼できる身近な人たちと、愛する人をそばに置くことだと答えたという。自分たちはずっと家族中心でやってきたそうで、結局は愛がすべてだと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（47:21〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2841s"]]}, {"cat": "暮らし", "t": "入場ではまず子どもを探す", "b": "プロレスは子どものためのものだと考えていて、入場では子どもの観客を探して一緒に盛り上がるという。ネットの声が気にならないわけではないが、意識は子どもたちに向けているそうだ。入場で全力を出しすぎて、そのあと試合があることを忘れそうになるのも、気持ちが本物だからいいと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（51:23〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3083s"]]}, {"cat": "暮らし", "t": "毎晩ひとりで「無駄にしなかったか」", "b": "その夜の仕事を終えてシャワーを浴びたあと、ひとりになって「今夜を無駄にしなかったか」と自分に問うという。自分の場所を狙っている仲間がいるので、その座を渡すつもりはないそうだ。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（52:12〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3132s"]]}, {"cat": "好きなもの", "t": "少年時代のヒーローはショーン・マイケルズ", "b": "子どものころの「推し」はショーン・マイケルズだったという。今でも本人がそばにいると、真面目な話をされていても、昔の名場面ばかり頭に浮かんでしまうそうだ。初めてタッグ王座を取った相手が往年の名チームだったときも、リングの上で興奮していたと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（55:22〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3322s"]]}, {"cat": "暮らし", "t": "文句は多いが、仕事はする", "b": "自分は文句が多いほうだと正直に認めているという。イベント出演のために飛行機に乗ることにまで不満を言いそうになるが、恵まれた仕事なのだから謙虚でいなければと自分に言い聞かせているそうだ。それでも、やるべき仕事はきちんとやると話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（56:55〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3415s"]]}, {"cat": "暮らし", "t": "兄弟と移動していた日々が恋しい", "b": "ユニットで活躍していたころはまだハウスショーも多く、ハードな日程の最後の時期だったという。当時は兄弟とどこへ行くにも一緒で、キャリアで一番楽しい時間だったそうだ。今は兄弟と別々に移動していて、ひとりの時間が増えたと話す。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（1:04:51〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3891s"]]}]);
  if (PROFILES["Jimmy Uso"]) PROFILES["Jimmy Uso"].facts.push({"cat": "暮らし", "t": "双子のジミーとなら仕事に感じない", "b": "双子のジミーのそばにいると仕事をしている気がせず、それをありがたく思っているという。タッグ王座を兄弟以外と組んで取ったのはコーディとが初めてで、特別な夜だったそうだ。兄弟でリングに立って向き合うと、つい笑ってしまいそうになると、ジェイが話している。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で、ジェイ・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（28:15〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1695s"]], "by": "第三者の話"});
  if (PROFILES["Goldust"]) PROFILES["Goldust"].facts.push({"cat": "暮らし", "t": "若いウーソズを育てた恩人", "b": "ゴールダストは、自分たち兄弟が初めて巡業に出たときの対戦相手で、マーク・ヘンリーとともに若手の自分たちを育ててくれた存在だという。まだ青かった兄弟が攻め立てていたとき、リングの真ん中で素に戻って「ちょっと待て」と怒ったことがあり、今でも笑い話だと、ジェイが話している。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で、ジェイ・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（41:46〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2506s"]], "by": "第三者の話"});
  if (PROFILES["The Undertaker"]) PROFILES["The Undertaker"].facts.push({"cat": "暮らし", "t": "メキシコ公演でかけられた一言", "b": "メキシコでのハウスショーで、モニターを見ていたアンダーテイカーに、試合後「今のお前は本当にプロの仕事をしている」と声をかけられたという。本当に観客に愛されると、多くをしなくても観客の気持ちを引き出せる段階があり、ようやくそれが分かってきたと、ジェイが話している。", "sp": "ジェイ・ウーソ", "d": "2026-02-05", "how": "コーディの番組で、ジェイ・ウーソの話（公式字幕を全文確認）", "src": [["公式YouTube（6:35〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=395s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "好きなもの", "t": "老犬ファラオは「聞いていないだけ」", "b": "飼っているフレンチブルドッグの中でも、ファラオはかなりの高齢だという。15歳だと人に話したら14歳だと訂正されたそうで、本人は300歳のようにふるまっているらしい。獣医からは「耳が遠いのではなく、話を聞く気がないだけ」と言われたと笑う。", "sp": "コーディ・ローデス", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（12:51〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=771s"]]}, {"cat": "暮らし", "t": "本番前2時間は何も入れない", "b": "最近、社内の人に「番組開始前の2時間は他の予定を入れない」と初めてはっきり伝えたという。試合や話す場面でしくじれば笑われるのは自分なので、その時間は相手を見て、言うべきことを考えるのに使いたいそうだ。早い時間なら喜んで他の仕事もすると話す。", "sp": "コーディ・ローデス", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（21:48〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=1308s"]]}, {"cat": "家族", "t": "兄は両ひざ手術、いまはトレーナー", "b": "兄ダスティンは両ひざを同時に手術したという。現在はレスリングのトレーナーとして精力的に活動しており、まだリングにも上がるだろうと見ているそうだ。甥たちも準備ができていると話す。", "sp": "コーディ・ローデス", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（36:57〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2217s"]]}, {"cat": "家族", "t": "父と兄と一度だけ組んだ6人タッグ", "b": "育成団体の時代に、父ダスティ・ローデス、兄ダスティンと3人で組んだのが、親子3人でタッグを組んだ唯一の機会だったという。兄がロープに走るとリングが鳴るほどの勢いで、父は「何をやってるんだ」という顔で自分を見たそうだ。兄は常に全速力の人だと話す。", "sp": "コーディ・ローデス", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（39:19〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=2359s"]]}, {"cat": "好きなもの", "t": "大のスター・ウォーズ好き", "b": "大のスター・ウォーズファンだという。生みの親ジョージ・ルーカスが、質問攻めにうんざりして「あれは子どものために作った映画だ」と答えたインタビューが印象に残っているそうだ。プロレスも同じで、子どもの観客を大切にしたいと話す。", "sp": "コーディ・ローデス", "d": "2026-02-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-FTlqV8YOClM", "src": [["公式YouTube（53:43〜）", "https://www.youtube.com/watch?v=FTlqV8YOClM&t=3223s"]]}]);
  ARTICLES.push({ id: "wdywta-FTlqV8YOClM", d: "2026-02-05", show: "wdywta", who: ["Jey Uso", "Cody Rhodes"], t: "ジェイ・ウーソの回　父リキシの背中と、フットボール少年からメインイベンターへ", lead: "コーディ・ローデスの番組に出た約69分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jey Uso", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-FTlqV8YOClM").map((x) => [x.t, x.b, x.sp])), open: ["記者会見の舞台裏、ユニットの物語の裏話、王者としての責任など、キャリアや筋書きに関わる話は素顔の項目から外した。", "「毎晩試合をしていたころが恋しい」の前半や、「父と会場で抱き合った」話など、ジェイとコーディのどちらの発言か追えなかった箇所は載せていない。", "記者会見やユニットの物語、他選手との試合の裏話など、キャリアや筋書きに関わる話は素顔の項目から外した。", "ジェイと同席した海外遠征の思い出（全速力で行こうと決めた話）は、試合の裏話寄りのため載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=FTlqV8YOClM"]] });
  if (!ROSTER.find((r) => r[1] === "Ron Simmons")) ROSTER.push(["ロン・シモンズ", "Ron Simmons", "lg", "殿堂入りした名レスラー", "", "", ""]);
  if (!PROFILES["Ron Simmons"]) PROFILES["Ron Simmons"] = { lead: "幼くして母を亡くし、親戚とコーチに支えられて大学フットボールの英雄になった人。初の黒人世界王者となり、仲間とビールを愛した豪快さも持つ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Ron%20Simmons"]], moves: [], facts: [] };
  if (PROFILES["Ron Simmons"]._weak) { PROFILES["Ron Simmons"].lead = "幼くして母を亡くし、親戚とコーチに支えられて大学フットボールの英雄になった人。初の黒人世界王者となり、仲間とビールを愛した豪快さも持つ。"; delete PROFILES["Ron Simmons"]._weak; }
  PROFILES["Ron Simmons"].facts.push(...[{"cat": "家族", "t": "8歳で母を亡くし、父は去った", "b": "ロン・シモンズは、自分と兄弟は孤児院に入れられる寸前だったと話す。母は8歳のときに亡くなり、父は家を出て、そこから12年ほど会わなかったという。身を寄せた祖母も数年後に亡くなり、人生の浮き沈みは一通り経験したと振り返っている。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=144s"]]}, {"cat": "家族", "t": "親戚のおかげで施設行きを免れた", "b": "家を転々としたあと、いとこの家に落ち着いたという。母方のおばたちが年下のきょうだいを引き取ってデトロイトへ連れていったが、13〜14歳だったロンと兄は地元に残った。中学のコーチが才能を見抜き、おじに残してほしいと頼んでくれたおかげだと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（3:15〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=195s"]]}, {"cat": "リングに来るまで", "t": "円盤投げで州記録を持っていた", "b": "高校時代は砲丸投げや陸上にも打ち込み、円盤投げでは州の記録を作ったと話す。記録は180フィート台だったと記憶しているそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（4:05〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=245s"]]}, {"cat": "リングに来るまで", "t": "苦境を抜ける道としてフットボールを選んだ", "b": "得意なことを比べた結果、迫力とパワーが生きるフットボールが一番だと考えたという。今の状況から抜け出せるのはこれだと思い、そこに力を注いだと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（4:51〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=291s"]]}, {"cat": "リングに来るまで", "t": "バッテリー店の恩人の頼みで大学を訪問", "b": "高校時代、バッテリー店で働いており、そこの店主にはとても世話になったという。その人が名将ボビー・ボウデンのもとでプレーした元選手で、見学の枠を一つだけ空けてほしいと頼まれ、恩があるので引き受けたと話す。当時のロンは大学の名前すらよく知らなかったそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（6:34〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=394s"]]}, {"cat": "リングに来るまで", "t": "「1年目から使う」の約束で進学を決めた", "b": "ボウデン監督は、何も差し出せないが、先輩に勝てば新入生でも先発で使うと正直に言ったという。ロンは全国優勝チームの出身で、最優秀ラインマンにも選ばれ、ベンチで待つ生活は考えられなかった。求めていたのは機会だけで、その言葉で心が決まったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（8:10〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=490s"]]}, {"cat": "好きなもの", "t": "愛車のボンネットに自分の絵を描いた", "b": "大学3年のころ、乗っていた車の鳥の絵を消して、自分の姿を描いたことがあるという。当時は交際相手もいて、キャンパスでは大スターだったと笑って話す。背番号50は、守備の番号として初めて永久欠番になったそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（9:00〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=540s"]]}, {"cat": "リングに来るまで", "t": "人目のない場所で積んだ努力", "b": "大学での成績は想像以上だったと誇らしげに語る。裏では、フェンスを越えてウエイト室に忍び込んだり、工事現場のコンクリートブロックを家に運んで重り代わりにしたりしていたという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（9:47〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=587s"]]}, {"cat": "リングに来るまで", "t": "プロのフットボールは満腹だった", "b": "プロでは本来のポジションがずれ、身長約185cm・体重約113kgのノーズタックルとしては小柄だったと話す。大学時代に2人、3人がかりで止められ続けてきたこともあり、フットボールへの気持ちは終わりに近づいていたという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（10:37〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=637s"]]}, {"cat": "好きなもの", "t": "祖母の影響でプロレスが好きに", "b": "祖母がプロレスの大ファンで、一番のお気に入りはボブ・アームストロングだったという。そのそばで見ているうちに、ロンもプロレスが大好きになったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（12:12〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=732s"]]}, {"cat": "リングに来るまで", "t": "友人の電話から始まったプロレス入り", "b": "アメリカンフットボールのリーグでチームメイトだったレックス・ルガーに声をかけられ、名コーチのヒロ・マツダに会うことになったという。簡単だろうと思っていたが、フットボール時代以上にきつかったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（13:01〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=781s"]]}, {"cat": "リングに来るまで", "t": "窓のない蒸し暑い道場で、3か月は基礎体力だけ", "b": "リングに上がるまでに3か月、ひたすら体力づくりだったという。一緒にいた数人が次々に脱落するなか、始めたことは最後までやり通したいという気持ちで残ったそうだ。ロープワークだけで約1か月続け、月謝は取られず無料で教わったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（13:46〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=826s"]]}, {"cat": "リングに来るまで", "t": "右手のパンチは道場の板で磨いた", "b": "得意の右手のパンチは、立てた板の直前でぴたりと止める練習で身についたという。板の後ろは相手の顔という想定で、当てずに本物らしく見せる感覚を叩き込まれたと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（15:28〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=928s"]]}, {"cat": "家族", "t": "赤ちゃんを抱えて巡業、妻に時間をお願いした", "b": "巡業を始めたころ、すでに小さな子どもがいて、生活は厳しかったという。のちの妻とはまだ結婚前で、これからを心配する相手に、もう少し様子を見させてほしいと頼んだと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（18:36〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=1116s"]]}, {"cat": "リングに来るまで", "t": "最初のころは緊張もしていた", "b": "大観衆のフットボールを経験していても、プロレスでは緊張したと素直に話す。相手の体を自分が預かり、自分の体も相手に預けるのだから、いい試合をしたい気持ちが強かったという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（20:09〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=1209s"]]}, {"cat": "リングの話", "t": "ダスティ・ローズが後ろ盾になってくれた", "b": "ダスティ・ローズはアスリートに目をかけ、多様性を広げようとロンを育ててくれたという。ところが体制が変わるにつれ、元の型にはまった扱いに戻ってしまい、行き詰まったと話す。そこで荷物をまとめ、約1年半、日本とを行き来する道を選んだそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（22:28〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=1348s"]]}, {"cat": "リングの話", "t": "ブッチ・リードと組んだドゥームの時代", "b": "タッグ結成は上の判断で、黒人タッグチームを見てみたいという話だったという。ロンは大喜びだったが、経験豊富なブッチ・リードは最初から乗り気ではなかったそうだ。自分も力があると認めてもらうことから始まり、物理的でリアルな試合で作り上げていったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（25:49〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=1549s"]]}, {"cat": "リングの話", "t": "誰も知らなかった王座戦の日", "b": "1992年8月、初の黒人世界ヘビー級王者となった日のことを語る。当日、会社のトップが全員そろうよう強く求めていたが、結末は誰にも知らされていなかったという。試合前に歴史を変える夜だと告げられ、ロンは本物の瞬間だったと呼んでいる。相手のベイダーは最初は乗り気でなかったが、最高の仕事をしてくれたと感謝している。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（37:46〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2266s"]]}, {"cat": "リングの話", "t": "今も届く手紙が一番の誇り", "b": "王者になった意味は、人生に影響を与えられたことだとロンは話す。黒人の選手がこの世界に飛び込む扉が開いたこと、そしてあらゆる肌の人から今も手紙が届くことが何より誇りだという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（43:18〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2598s"]]}, {"cat": "リングの話", "t": "黒人レスラーが少なかった理由を考える", "b": "以前のテレビでは黒人は殴られる役や、型にはまった従属的な役ばかりだったと振り返る。見る側にとって応援する対象がいなかったことも、競技に入る人が増えなかった一因だと考えているそうだ。つらい時期は実力ではなく人種が理由だったが、あえて選んだ道に後悔はないと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（44:59〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2699s"]]}, {"cat": "リングの話", "t": "WCWを離れ、旧知の電話でWWEへ", "b": "世界王者になりながら、社内の黒人は数人だけという状況に疑問を持ったという。裏方の力関係に巻き込まれるのを避けて日本へ通ううち、旧知のブルース・プリチャードとマイケル・ヘイズから電話が来た。日本との契約も切れていたため、ビンスとの面会に進んだと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（47:20〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2840s"]]}, {"cat": "リングの話", "t": "光る鎧を想像したら革のヘルメットだった", "b": "ファルークの役は、剣闘士のイメージだと軽く聞いていたという。ロンは輝く金属の鎧を思い描いて衣装合わせに行ったが、出てきたのは革のヘルメットで、言葉を失ったそうだ。笑いものになるか、容赦なく相手を叩きのめす強い男にするかの二択だと考え、後者を選んだと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（48:07〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2887s"]]}, {"cat": "リングの話", "t": "ネイションのリーダーとして", "b": "ファルークの役柄は、社会への怒りや本音を代わりに語る存在でもあったという。メンバーとは仲が良く、出番や目立ち方を巡って揉めたことはなかったと話す。解散後に、全員が以前より大きく成功したことが何より嬉しいそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（54:46〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=3286s"]]}, {"cat": "暮らし", "t": "人を妬んだことがない", "b": "ロンは、これまで誰に対しても妬みを感じたことがないと話す。やってきたことに満足していて、自分は一通りの人生を経験した完成された男だと思っているという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（58:48〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=3528s"]]}, {"cat": "暮らし", "t": "ブラッドショーは兄弟のような存在", "b": "相棒のブラッドショー（ジョン・レイフィールド）とは、移動の車中で個人的な話もできたという。長く欠けていた、兄弟と並んで旅をする感覚をくれたと話し、結婚式でも感謝を伝えたそうだ。一緒にカントリー風の酒場へ通い、ビールを楽しんだという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（1:03:34〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=3814s"]]}, {"cat": "暮らし", "t": "運転手のテディ・ロングをからかう長旅", "b": "巡業ではテディ・ロングが運転係で、ロンとブラッドショーが後ろでビールを飲んでは缶を窓から捨てていたという。オハイオで警官に止められたが、後から来た警官がベルトを見て、2人を知っているファンだったおかげで写真だけで済んだと笑って話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（1:06:52〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=4012s"]]}, {"cat": "暮らし", "t": "吹雪のなかで置き去りにされた", "b": "シカゴ近くの吹雪の夜、用を足しに車を降りたロンを乗せずにテディが走り去ってしまったという。上着も車に置いたままで、手持ちの葉巻用ライターを掲げて居場所を知らせたそうだ。戻ってきた2人に文句を言いたくても、寒さで口が動かなかったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（1:09:12〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=4152s"]]}, {"cat": "体のこと", "t": "50歳が近づき、股関節と肩が限界に", "b": "50歳近くになり、体のあちこちが言うことを聞かなくなったという。股関節は人工関節が必要で、肩も痛んでいたが、相棒のジョンには何も言わなかったそうだ。言えば彼が気を遣って試合の負担を肩代わりすると分かっていたので、それをさせたくなかったと話す。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（1:15:38〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=4538s"]]}, {"cat": "リングの話", "t": "殿堂入りの夜と、後悔のない現役生活", "b": "2012年にはJBLの紹介で殿堂入りを果たした。初の黒人世界王者になったことが一番誇れる財産だと語っている。キャリアに後悔はなく、全力でやり、品位を持ってやり遂げたと言われたいそうだ。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-S4zFM4_06ns", "src": [["番組のYouTube（1:18:00〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=4680s"]]}]);
  if (PROFILES["Butch Reed"]) PROFILES["Butch Reed"].facts.push({"cat": "暮らし", "t": "ブッチ・リードは業界を知り尽くした人", "b": "ブッチ・リードとテディ・ロングは、この業界のいろいろな立場を経験してきた人で、後輩のロンにとって大きな学びの相手だったと、ロン・シモンズが話している。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ロン・シモンズの話（字幕を全文確認）", "src": [["番組のYouTube（40:29〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=2429s"]], "by": "第三者の話"});
