  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "アンダーテイカーは文句を言わない人", "b": "アンダーテイカーはケガをしていても愚痴を言わず、懸命に働く姿をずっと見てきたと、ロン・シモンズが話している。自分の壁に飾る数少ない人の一人だという。", "sp": "ロン・シモンズ", "d": "2026-02-07", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ロン・シモンズの話（字幕を全文確認）", "src": [["番組のYouTube（59:36〜）", "https://www.youtube.com/watch?v=S4zFM4_06ns&t=3576s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-S4zFM4_06ns", d: "2026-02-07", show: "ext", who: ["Ron Simmons"], t: "ロン・シモンズの回　孤児院を免れた少年から初の黒人世界王者へ", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約84分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Ron Simmons"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-S4zFM4_06ns").map((x) => [x.t, x.b, x.sp])), open: ["対談の聞き手スティーブ・オースティンの思い出話や、試合映像を見ながらの実況的なやりとりは省いた。", "ロンの妻やバッテリー店の恩人など、一般の私人の名前は載せていない。", "自動字幕のため、一部の固有名詞が崩れており、確信が持てない箇所は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=S4zFM4_06ns"]] });
  if (!ROSTER.find((r) => r[1] === "Nathan Frazer")) ROSTER.push(["ネイサン・フレイザー", "Nathan Frazer", "lg", "イギリス出身の選手", "", "", ""]);
  if (!PROFILES["Nathan Frazer"]) PROFILES["Nathan Frazer"] = { lead: "サッカー推薦でアメリカに渡り、夢だったWWEにたどり着いた人。夢をかなえても満たされなかった日々から、信仰によって生き方が変わった経緯を熱く語っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nathan%20Frazer"]], moves: [], facts: [] };
  if (PROFILES["Nathan Frazer"]._weak) { PROFILES["Nathan Frazer"].lead = "サッカー推薦でアメリカに渡り、夢だったWWEにたどり着いた人。夢をかなえても満たされなかった日々から、信仰によって生き方が変わった経緯を熱く語っている。"; delete PROFILES["Nathan Frazer"]._weak; }
  PROFILES["Nathan Frazer"].facts.push(...[{"cat": "リングに来るまで", "t": "10歳で見たバティスタのスパインバスター", "b": "子どものころはサッカーに打ち込み、父はプロ選手になってほしがっていたという。10歳でSmackDownを見て、バティスタのスパインバスターに心を奪われ、これがやりたいと思ったそうだ。枕や弟を相手に技を練習し、16歳で地元の団体に入って初試合をしたと話す。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=95s"]]}, {"cat": "リングに来るまで", "t": "サッカー推薦でアメリカへ", "b": "WWEに入るにはアメリカのインディーで戦う必要があると考え、サッカーの奨学金でテネシー州の大学に進んだという。サッカーをしながら隠れてプロレスの試合にも出ていて、監督にばれて大騒ぎになったそうだ。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=144s"]]}, {"cat": "リングに来るまで", "t": "ビザが切れる寸前の契約", "b": "ビザが切れてイギリスに帰らなければならなくなる数週間前に、急に注目されて複数の団体から声がかかったという。夢だったWWEを選び、コロナ禍のさなかにイギリスの部門で地元に戻って戦えたそうだ。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=242s"]]}, {"cat": "体のこと", "t": "夢をかなえても満たされなかった", "b": "念願のWWE入りで全部解決すると思ったが、喜びはすぐに薄れ、心は空っぽのままだったという。大学時代から吸っていた大麻やたばこに逆戻りし、毎日吸わずにはいられないほどになった時期があったと打ち明けている。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（5:34〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=334s"]]}, {"cat": "家族", "t": "父の変化", "b": "父は怒りっぽく、サッカーの試合ではピッチの脇から怒鳴るような人だったという。12年ほど前に「イエスに出会った」と言ってから、その怒りが消えたのを見て、ずっと心に残っていたそうだ。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（9:27〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=567s"]]}, {"cat": "信仰", "t": "一枚のチラシと祈り", "b": "2023年初めごろ、神の存在を考え始めた時期に、オーランドの教会のチラシが一度だけ郵便受けに届いたという。いろいろな宗教を調べた末に祈り始め、ある夜の祈りで言葉にできないほどの安らぎに包まれる体験をしたそうだ。その日を境に洗礼を受け、生き方がまったく変わったと話す。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（10:12〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=612s"]]}, {"cat": "信仰", "t": "一番大事なものが変わった", "b": "以前は心の一番にプロレスがあったが、今はイエスが一番で、プロレスは今も大好きだが二番目だという。自分の運動能力も授かった才能だと考え、おごらないようにしているそうだ。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（20:35〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=1235s"]]}, {"cat": "リングの話", "t": "憧れのAJスタイルズと語り合う", "b": "15歳のころからAJスタイルズが憧れで、小柄でも負けん気が強く運動神経抜群な姿に自分を重ね、髪型もまねしていたという。今は同じ控室で信仰について深く語り合える仲だそうだ。ウーソズやジェイコブ・ファトゥとも語り合い、ファトゥとは同じ教会に通っていると話す。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（24:37〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=1477s"]]}, {"cat": "暮らし", "t": "遠征中も朝の祈り", "b": "SmackDownの遠征から土曜の朝に戻り、日曜は教会に行くという。遠征中も、朝に一人で祈る時間を何より優先していて、それで一日が整うそうだ。NXTの仲間が洗礼を受けるのを手伝ったこともあると話す。", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で（字幕を全文確認）", "art": "ext-eAswYqy-YDA", "src": [["番組のYouTube（27:46〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=1666s"]]}]);
  if (PROFILES["Jacob Fatu"]) PROFILES["Jacob Fatu"].facts.push({"cat": "暮らし", "t": "同じ教会に通う仲", "b": "ファトゥとは同じ教会に通い、神に導かれて信仰を深めていく姿に自分も励まされていると、ネイサン・フレイザーが話している", "sp": "ネイサン・フレイザー", "d": "2026-02-11", "how": "ユナイテッド・バイ・グレース（信仰をテーマにした番組）で、ネイサン・フレイザーの話（字幕を全文確認）", "src": [["番組のYouTube（26:13〜）", "https://www.youtube.com/watch?v=eAswYqy-YDA&t=1573s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-eAswYqy-YDA", d: "2026-02-11", show: "ext", who: ["Nathan Frazer"], t: "ネイサン・フレイザーの回　信仰が変えた生き方", lead: "ユナイテッド・バイ・グレース（信仰をテーマにした番組）に出た約33分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nathan Frazer"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-eAswYqy-YDA").map((x) => [x.t, x.b, x.sp])), open: ["世の中についての本人の考えのうち、信仰の体験と直接関わらない部分は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=eAswYqy-YDA"]] });
  if (!ROSTER.find((r) => r[1] === "The Miz")) ROSTER.push(["ザ・ミズ", "The Miz", "lg", "元WWE王者・リアリティ出身", "", "", ""]);
  if (!PROFILES["The Miz"]) PROFILES["The Miz"] = { lead: "リアリティ番組から身を起こし、周囲の反対を押し切ってリングに立った男。自分の試合を厳しく見返し続ける努力家で、悪役を楽しむ職人でもある。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=The%20Miz"]], moves: [], facts: [] };
  if (PROFILES["The Miz"]._weak) { PROFILES["The Miz"].lead = "リアリティ番組から身を起こし、周囲の反対を押し切ってリングに立った男。自分の試合を厳しく見返し続ける努力家で、悪役を楽しむ職人でもある。"; delete PROFILES["The Miz"]._weak; }
  PROFILES["The Miz"].facts.push(...[{"cat": "暮らし", "t": "自称WWE一のゴルファー", "b": "ザ・ミズは自分を「WWE最高のゴルファー」と言うが、周りにほとんどゴルフをする人がいないからだと笑う。ゴルフの大会で有名人と回ると、リングでは平気な緊張がゴルフだと出てしまい、うまく打てないと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（1:39〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=99s"]]}, {"cat": "暮らし", "t": "自分の試合は一人で見返す", "b": "他団体の昔の映像より、いま団体で起きていることを見るのが中心だという。自分の試合は一番厳しい批評家として一人で見返し、足運びなどの無駄を細かく探す。入団から20年以上たった今も続けている習慣だそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（7:12〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=432s"]]}, {"cat": "リングの話", "t": "アンダーテイカーとの初試合の思い出", "b": "初めて対戦したとき、できるかと聞かれてドロップキックを「できる」と答えたが、実は何年も打っていなかったと笑う。相手がすべての展開を細かく指示してくれたのが印象に残っているそうだ。ラスト・ライドで持ち上げられたときは、起き上がるのに必死だったと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=580s"]]}, {"cat": "リングの話", "t": "「本物か作り物か」に思うこと", "b": "リアリティ番組でもWWEでも、一番多い質問は本物かどうかだったと話す。娯楽として楽しめるかが大事で、今は仕組みを知る人が増えたと見ている。試合を作るときは、一瞬でも「これは本物だ」と思わせる場面を入れたいという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（12:03〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=723s"]]}, {"cat": "リングに来るまで", "t": "ディープサウスの毎朝は「あと一日」", "b": "育成の拠点で朝起きるたびに「あと一日」と自分に言い聞かせていたと話す。体は慣れても、結果を出さなければという心の消耗は続いたという。アル・スノウら当時のコーチに鍛えられたことを、今は感謝しているそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（19:09〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1149s"]]}, {"cat": "リングの話", "t": "上の世代との駆け引きに悩んだ", "b": "若いころは、下り坂のベテランや上位の選手との楽屋の力関係をうまく泳ぐ必要があったという。助言が自分を助けるものか潰すものか、見極めなければならなかったそうだ。その経験があるから、今は後輩に同じ思いをさせたくないと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（19:57〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1197s"]]}, {"cat": "リングに来るまで", "t": "奨学金を捨ててプロレスの道へ", "b": "バスケットボールの奨学金を得ていたが、大学をやめてプロレスラーになると決めたと話す。両親には「大学に無料で行けるのになぜ」と反対されたという。意地になって援助も断り、車で寝ながらやりくりした時期もあったそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（25:31〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1531s"]]}, {"cat": "リングに来るまで", "t": "お金のない下積みが力になった", "b": "試合に出ても赤字になる時期に、道場代や遠征費を稼ぐため苦労したという。人脈のない出身だったからこそ、その苦労が自分の強みになったと話す。のちに両親も大のファンになったそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（27:13〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1633s"]]}, {"cat": "リングに来るまで", "t": "リアリティ番組の賞金で道場へ", "b": "21歳ごろ、人気リアリティ番組の企画で得た賞金を使い、インディー団体の道場に入ったという。演技やアドリブの教室に通い、栄養士もつけて、賞金を全部この道につぎ込んだと話す。当時はリアリティ出身者がプロレス界から歓迎されない時代だった。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（31:10〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1870s"]]}, {"cat": "家族", "t": "「クリーブランドの王になれ」と父", "b": "大学を離れてカリフォルニアでレスラーになると父に告げたところ、「そんなばかな話は聞いたことがない」と言われたという。父は、地元で顔を知られているのだから地元の王になればいいと勧めた。ザ・ミズは外の世界に出たかったと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（32:00〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=1920s"]]}, {"cat": "リングに来るまで", "t": "小さな会場や縁日で腕を磨いた", "b": "所属した団体のリングは床のバネが傾いて、下にもぐって蹴り直していたという。のちに有名になる選手が顔を出し、ダイヤモンド・ダラス・ペイジとタッグを組んだこともあるそうだ。縁日のような場所で酔った観客の前で試合をした経験も、勉強になったと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（33:38〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2018s"]]}, {"cat": "リングに来るまで", "t": "若手発掘番組には遅れて挑戦", "b": "同じ局の番組だからと最初は応募を断られ、のちに放送局が変わってから出場したという。軽く見られたくなくて先輩に相談すると、100万ドルの契約のチャンスだと背中を押されたそうだ。優勝はできなかったが、育成部門の契約を勝ち取った。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（34:26〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2066s"]]}, {"cat": "リングに来るまで", "t": "日本の団体には受け入れられなかった", "b": "日本の団体に何度か出向いて試合をしたが、結局は採用されなかったと話す。当時は自分は特別だと思っていたが、そうではなかったと苦笑する。だから若手発掘番組が最後の機会に見えたという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（35:12〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2112s"]]}, {"cat": "リングに来るまで", "t": "リアリティ出演中から「ミズ」だった", "b": "高校の友人には「マイク」と呼ばれていたが、ニューヨークの共同生活では知らない7人の中で落ち着かず、自分を前に出す声の大きい人物になったという。最初は誰にも好かれなかったと話す。そのころからマイクパフォーマンスの下地ができていたそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（35:58〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2158s"]]}, {"cat": "家族", "t": "妻マリースとの最初のやりとり", "b": "妻のマリースとは、新人発掘のオーディションで初めて顔を合わせたという。英語で用意してきた答えがありきたりだと指摘して、怒らせてしまったそうだ。次にフランス語で話すよう頼むと、何を言っているか分からないが迫力があったと笑う。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（36:43〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2203s"]]}, {"cat": "リングの話", "t": "王座を持つ重圧は「ベルト」ではない", "b": "ベルトを巻くと、番組全体を背負う責任がのしかかると話す。最初の王座のとき、ベルトを失った後にどう勢いを保てばいいか分からず、負けが続いたという。そこを学ぶのに数年かかったそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（40:47〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2447s"]]}, {"cat": "リングの話", "t": "悪役の仕事は「憎まれること」", "b": "ベビーフェイスが新しいとき、自分の20年分の信用を使って観客に嫌われるのが役目だと話す。そのため試合では、かっこいい技を避けて汚い手を中心に使うこともあるという。最近は人柄が知られて嫌われにくくなり、難しさも感じているそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（46:23〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2783s"]]}, {"cat": "リングの話", "t": "人気歌手との試合の裏側", "b": "人気歌手を迎えた大舞台の試合では、約15分間、攻撃を受ける演技をみっちり教えたという。ゲストを隠さず見せ場に使う方針で、観客が予想しない形で試合に絡ませたそうだ。相手は高級車へのスプレー塗装まで自分から許してくれたと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（48:49〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2929s"]]}, {"cat": "リングの話", "t": "ローガン・ポールへの評価", "b": "練習中の吸収の速さは、これまで見た中で一番だったと話す。自分と同じ「外から来た人」の役を演じていて、自分の役を取られた気分だと冗談めかす。夏の大会で対戦したときは、会場がどちらを応援しても合わせようと決めて臨んだという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（52:06〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=3126s"]]}, {"cat": "リングの話", "t": "一度は楽屋を追い出された", "b": "移動の車で、他人のかばんの上でチキンを食べたことが発端で、楽屋を追い出されたという。着替えは物置のような場所でし、半年以上続いたそうだ。最後はアンダーテイカーが「戻っていいぞ」と言ってくれて、キャリアで最も嬉しい瞬間の一つだったと話す。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（1:05:54〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=3954s"]]}, {"cat": "リングの話", "t": "ダニエル・ブライアンとの口論の舞台裏", "b": "「臆病者」と言われた場面で、普段は経験しない感覚に襲われ、言葉がうまく出なかったと話す。当時は演技の勉強で自分の感情を意識する習慣があり、その最中だったという。映像は絶賛されたが、本人は言葉が出ていないと感じたそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（1:13:11〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=4391s"]]}, {"cat": "暮らし", "t": "人気番組の司会にも挑戦", "b": "WWEに所属しながら、2026年放送予定の格闘バラエティ番組の司会を務めると話す。収録は想像以上に楽しかったそうだ。リングの経験が、司会や演技、アドリブなどあらゆる仕事の土台になっていると語る。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（1:18:41〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=4721s"]]}, {"cat": "家族", "t": "娘の舞台のために予定を変える", "b": "娘が出る劇を見に行くため、仕事の予定を調整することがあるという。良い父であり夫でありたいから、大事な瞬間は逃したくないと話す。ポッドキャストを持たないのも、やるなら全力で作り込んでしまい時間がないからだそうだ。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で（字幕を全文確認）", "art": "ext-hSoGdXAWlZ0", "src": [["番組のYouTube（1:19:31〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=4771s"]]}]);
  if (PROFILES["Bad Bunny"]) PROFILES["Bad Bunny"].facts.push({"cat": "暮らし", "t": "リングにも全力で挑んだ歌手", "b": "試合の準備で早くからリングにいて、授賞式や音楽番組の合間にも練習に戻ってきたと、ザ・ミズが話している。高級車へのスプレー塗装も自分から許したという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で、ザ・ミズの話（字幕を全文確認）", "src": [["番組のYouTube（48:49〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2929s"]], "by": "第三者の話"});
  if (PROFILES["Logan Paul"]) PROFILES["Logan Paul"].facts.push({"cat": "暮らし", "t": "習得の速さに驚いた", "b": "練習で見てきた中で、プロレスの吸収が最も速かった選手だと、ザ・ミズが話している。この先の団体を引っ張る存在になれるとも見ているという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で、ザ・ミズの話（字幕を全文確認）", "src": [["番組のYouTube（52:06〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=3126s"]], "by": "第三者の話"});
  if (PROFILES["JBL"]) PROFILES["JBL"].facts.push({"cat": "暮らし", "t": "新人に助言をくれた先輩", "b": "いじめっ子と言われることもあるが、実際は新人の自分を呼んで丁寧に教えてくれたと、ザ・ミズが話している。むしろ周りの立場の弱い人たちのほうが厳しく当たったという。", "sp": "ザ・ミズ", "d": "2026-02-11", "how": "アンダーテイカー(WWE公式)の番組で、ザ・ミズの話（字幕を全文確認）", "src": [["番組のYouTube（38:23〜）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0&t=2303s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-hSoGdXAWlZ0", d: "2026-02-11", show: "ext", who: ["The Miz"], t: "ザ・ミズの回　リアリティ番組から悪役の職人へ", lead: "アンダーテイカー(WWE公式)の番組に出た約86分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["The Miz"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-hSoGdXAWlZ0").map((x) => [x.t, x.b, x.sp])), open: ["聞き手(アンダーテイカーら)自身の話や、誰の発言か判別しにくい箇所は載せていない。", "番組の広告や宣伝部分は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=hSoGdXAWlZ0"]] });
