  if (!PROFILES["Jacy Jayne"]) PROFILES["Jacy Jayne"] = { lead: "完璧主義で、自分の試合を一秒ずつ見直すという努力家。ソル・ルカへの対抗心を隠さない一方、自分の未熟さも率直に認める。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jacy%20Jayne"]], moves: [], facts: [] };
  if (PROFILES["Jacy Jayne"]._weak) { PROFILES["Jacy Jayne"].lead = "完璧主義で、自分の試合を一秒ずつ見直すという努力家。ソル・ルカへの対抗心を隠さない一方、自分の未熟さも率直に認める。"; delete PROFILES["Jacy Jayne"]._weak; }
  PROFILES["Jacy Jayne"].facts.push(...[{"cat": "リングの話", "t": "ソル・ルカへの強い対抗心", "b": "ジェイシーは、NXT女子王座の次の挑戦者にソル・ルカが決まるのをずっと待っていたと話す。ソルが注目を集めるたびに自分の見せ場を取られている気がして、もう我慢できないのだという。ここ最近の悔しさを一気に語った。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=98s"]]}, {"cat": "リングの話", "t": "二冠の価値をもっと認めてほしい", "b": "TNAとNXTの王座を同時に持った初の女子選手になったのに、世間はソルの二冠ばかり話題にすると不満を口にする。自分のタイトルのほうがずっと重いと考えているそうだ。もっと称賛されてしかるべきだと話す。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=144s"]]}, {"cat": "リングの話", "t": "大型番組の大一番を逃した悔しさ", "b": "人気番組のメインイベントで、以前から対戦したいと言っていたベイリーと戦う枠をソルに取られたと感じている。NXT王者の自分こそ出るべきだったという主張だ。この嫉妬めいた思いを隠さず話している。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=196s"]]}, {"cat": "リングの話", "t": "今のユニットの結束は強い", "b": "今の仲間とは互いに刺激し合えていて、相性がとてもいいと話す。新加入のレイニーは経験が浅いのにベテランの中でも物怖じせず、頭の良い選手だと褒めた。以前のメンバーと比べ、競技にかける熱量がまったく違うとも語っている。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（8:50〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=530s"]]}, {"cat": "体のこと", "t": "完璧主義で自分を責めてしまう", "b": "試合の間合いやタイミングが頭の中の理想と少しでもずれると、一週間は自分を責めるという。ずれた点は必ず直さないと気が済まないそうだ。自分に厳しい性格だと自覚している。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=674s"]]}, {"cat": "暮らし", "t": "自分の試合は全部見返す", "b": "試合後は必ず自分で映像を見て、一秒ずつ細かく分析すると話す。自分の試合を見られないほど落ち込む選手もいるが、本人は平気だという。まず一人で見て、その後でコーチ陣と一緒に見直す習慣がある。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（12:03〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=723s"]]}, {"cat": "暮らし", "t": "コーチ陣と一緒に振り返る", "b": "ベテランのコーチたちと並んで映像を見て、細かい点まで指摘をもらうそうだ。たいていはコーチが言う前に自分で気づけるという。コーチは時にあえて反対意見も言い、それが成長につながっていると話す。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（12:51〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=771s"]]}, {"cat": "リングの話", "t": "ロイヤルランブルでソルに敗れた怒り", "b": "ランブルでソルに投げ落とされ、意識が戻ったときには怒りしかなかったと振り返る。しかも観客が自分の脱落に沸いたのが許せなかったそうだ。この悔しさが、ソルを倒したい理由の一つになっている。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（18:22〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1102s"]]}, {"cat": "リングに来るまで", "t": "子どもの頃からの夢はランブル出場", "b": "ロイヤルランブルは昔からいちばん好きな大会で、幼い頃から「いつか出る」と言っていたという。ここ4年は選ばれず悔しい思いをしたそうだ。今回の出場は、その夢がかなった形だった。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（19:08〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1148s"]]}, {"cat": "暮らし", "t": "ランブル前は一週間ホテルに缶詰め", "b": "サプライズ出場だったため、中東では約一週間ホテルから出られなかったという。ジムでの運動と食事のために館内を歩くのは許されたが、見た景色は空港と会場だけだった。豪華なホテルだったが観光はできなかったと話す。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（19:54〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1194s"]]}, {"cat": "リングの話", "t": "現地ならではの衣装の決まり", "b": "腕も脚も隠す全身タイプの衣装で、体の線が目立たないことが条件だったという。デザイン案を出して会社の承認を受ける必要があった。最初に出した赤い衣装と鎖つきのデザインは、赤は不可、鎖も黒いストラップも不可と断られた。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（20:40〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1240s"]]}, {"cat": "暮らし", "t": "ランブル前夜に自分で衣装を仕上げた", "b": "中東での大会前夜、ホテルの部屋で4時間半から5時間かけ、衣装にクリスタルを一つずつ貼ったという。そんな作業は人生で初めてで、失敗したらどうしようとずっとどきどきしていたそうだ。出来栄えは白がよく映え、褒められた。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（22:21〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1341s"]]}, {"cat": "リングの話", "t": "初めての全身スーツでの試合", "b": "白は透けるため三重に重ねる必要があり、とても窮屈で重くなったそうだ。キックを蹴ろうとして脚が上がらず、スーツと戦っているようだったと話す。膝や脛のパッドも中に入れたので、さらにきつくなったという。次は白にしないと笑っている。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（22:21〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1341s"]]}, {"cat": "体のこと", "t": "ランブル後は27時間ほぼ起きっぱなし", "b": "大会後は明け方5時ごろまで会場にいて、そのままチャーター機で帰ったという。機内に乗った時点で約27時間起きており、すぐ眠り込んだそうだ。試合を見返したのは数日後で、もっとうまくやれたと感じたと話す。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（24:47〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1487s"]]}, {"cat": "リングの話", "t": "ランブルは「就職面接」のつもりだった", "b": "初めての大型大会で、一挙一動が主力番組への面接だと思って緊張したという。実際には選手たちは親切で、みんなが良い試合を作ろうと助け合っていた。スタッフも優しく、思った以上に楽だったと話す。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（26:30〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1590s"]]}, {"cat": "リングの話", "t": "海外の観客が自分を知っていた", "b": "現地ではNXTを知らないのではと不安だったが、技を出し始めると自分の名前のチャントが起きたという。地球の反対側にも見てくれている人がいると実感できて、うれしかったそうだ。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（27:19〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1639s"]]}, {"cat": "暮らし", "t": "会場の照明について", "b": "テレビでは客席の照明が気になると言われたが、会場にいた選手は誰も気にしていなかったと話す。観客の姿は確かに見えたそうだ。席ごとに個別のライトがあるのは珍しい作りだったという。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（28:10〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1690s"]]}, {"cat": "リングに来るまで", "t": "NXT在籍は月末で5年", "b": "今月末でNXTでの活動が丸5年になると話す。主力として長く在籍してきた分、次の段階に進む覚悟もできているという。呼ばれればどこの番組でも行くつもりだ。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（29:00〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1740s"]]}, {"cat": "リングの話", "t": "昇格は「まだ早かった」と今は思う", "b": "かつてのユニット解散後は天狗になり、自分は上に行く準備ができていると思い込んでいたという。今振り返ると全然できておらず、あのとき昇格していたらクビになっていたかもしれないと話す。長くNXTにいたおかげで、今は本当に準備ができたと自信を持って言えるそうだ。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で（字幕を全文確認）", "art": "ext-pAw2NNtNRLU", "src": [["番組のYouTube（29:48〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=1788s"]]}]);
  if (PROFILES["Lainey Reid"]) PROFILES["Lainey Reid"].facts.push({"cat": "暮らし", "t": "レイニーは研究熱心な後輩", "b": "レイニーは競技歴が3年ほどと浅いのに、いつもオープンリングに出て質問を重ねる勉強家で、全力で打ち込んでいると、ジェイシー・ジェインが話している。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で、ジェイシー・ジェインの話（字幕を全文確認）", "src": [["番組のYouTube（9:35〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=575s"]], "by": "第三者の話"});
  if (PROFILES["Jada Parker"]) PROFILES["Jada Parker"].facts.push({"cat": "暮らし", "t": "ジェイダは街の喧嘩屋タイプ", "b": "ジェイダ・パーカーは街の喧嘩屋のようなスタイルで、タフな選手だと、ジェイシー・ジェインが話している。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で、ジェイシー・ジェインの話（字幕を全文確認）", "src": [["番組のYouTube（14:26〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=866s"]], "by": "第三者の話"});
  if (PROFILES["Kendal Grey"]) PROFILES["Kendal Grey"].facts.push({"cat": "暮らし", "t": "ケンドールは長く活躍できる逸材", "b": "ケンドールは非常に才能があり、これから長く活躍する選手だが、試合前には緊張しやすいと、ジェイシー・ジェインが話している。", "sp": "ジェイシー・ジェイン", "d": "2026-02-13", "how": "バステッド・オープン・ポッドキャストの番組で、ジェイシー・ジェインの話（字幕を全文確認）", "src": [["番組のYouTube（5:42〜）", "https://www.youtube.com/watch?v=pAw2NNtNRLU&t=342s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-pAw2NNtNRLU", d: "2026-02-13", show: "ext", who: ["Jacy Jayne"], t: "ジェイシー・ジェインの回　ソル・ルカ戦への執念とロイヤルランブルの裏話", lead: "バステッド・オープン・ポッドキャストの番組に出た約31分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jacy Jayne"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-pAw2NNtNRLU").map((x) => [x.t, x.b, x.sp])), open: ["聞き手が口にした名前の言い間違いや、字幕で崩れた固有名詞は載せていない。他の選手の英語表記は字幕の聞き取りによる。", "ソル・ルカとの王座戦への意気込みや、試合の筋書き中心の発言は、要点のみ載せた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=pAw2NNtNRLU"]] });
