  if (!PROFILES["Rusev"]) PROFILES["Rusev"] = { lead: "ブルガリアの貧しい町で育ち、20歳で単身渡米して下積みを重ねた苦労人。映画好きで前向きな素顔と、WWE復帰後の充実ぶりが語られた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Rusev"]], moves: [], facts: [] };
  if (PROFILES["Rusev"]._weak) { PROFILES["Rusev"].lead = "ブルガリアの貧しい町で育ち、20歳で単身渡米して下積みを重ねた苦労人。映画好きで前向きな素顔と、WWE復帰後の充実ぶりが語られた。"; delete PROFILES["Rusev"]._weak; }
  PROFILES["Rusev"].facts.push(...[{"cat": "好きなもの", "t": "80〜90年代の映画とランボーが大好き", "b": "ランボーが一番好きなシャツで、どこにでも着ていくという。80〜90年代の映画は善と悪が分かりやすく、難しく考えずに楽しめたところが好きだと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=46s"]]}, {"cat": "リングの話", "t": "悪役が大好き、映画の悪役が手本", "b": "役柄は悪役がいちばん好きだという。『キックボクサー』のトン・ポー、『ブラッドスポーツ』のチョン・リーなど、子どもの頃から見てきた悪役を参考にした。『ロボコップ』の悪役も好きだと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=46s"]]}, {"cat": "体のこと", "t": "体重は300ポンドから約260ポンドへ", "b": "デビュー当時は300ポンドほどあったが、今は260ポンドだという。昔と見た目が大きく違うため、友人の子が同一人物かと尋ねたこともあったそうだ。大柄でも動きは悪くないと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（3:59〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=239s"]]}, {"cat": "家族", "t": "体重約15ポンドで生まれた大柄な子", "b": "生まれたときの体重は15ポンド近くあったそうで、母親は3日間入院したという。クリスマスの日に生まれ、子どもの頃はお金がなくプレゼントがない年もあった。今は妻の家族と、誕生日の贈り物交換とクリスマスを別々に祝い、誕生日用のケーキも用意すると話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=287s"]]}, {"cat": "家族", "t": "物不足のブルガリアで育った少年時代", "b": "1996年のブルガリアはハイパーインフレで、パンを求めて行列しても何も買えずに帰ることがあったという。電気もたびたび止まった。逃げ場はスポーツとテレビゲームで、友達も少なかったと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（6:20〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=380s"]]}, {"cat": "リングに来るまで", "t": "6歳で出会ったプロレスと最初の挫折", "b": "6歳のとき、アメリカ帰りの人が持ってきたハルク・ホーガンのビデオを見て夢中になったという。母に頼んで習い事に入ったが、行ってみるとロープのないアマチュアレスリングで、1〜2か月で辞めた。その後もケーブルテレビの普及で毎週プロレスを追い続けたそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（7:07〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=427s"]]}, {"cat": "リングに来るまで", "t": "小3から英語を学び、渡米を決めていた", "b": "アメリカの映画やプロレスが好きで、小学3年生から英語を習い始めたという。目的地はずっとアメリカで、行くための準備をしていたと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（8:41〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=521s"]]}, {"cat": "リングに来るまで", "t": "20歳で渡米、仕事を失い所持金100ドルに", "b": "20歳で就労・旅行の制度を使ってバージニア州リッチモンドに渡り、最初の仕事はペンキ塗りだった。1か月で解雇され、寮も追い出されて所持金は100ドルだったという。仕事先で知り合った人たちの部屋に身を寄せ、6人で床に寝て暮らした。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（9:32〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=572s"]]}, {"cat": "リングに来るまで", "t": "掃除、ハンバーガー店、タクシーと転々とした下積み", "b": "ディスカウントストアの清掃やハンバーガー店で働いたあと、友人の古い車で3日かけてカリフォルニアへ移ったという。そこから建設、ナイトクラブの警備、タクシー、ピザや食べ物の配達と、何でもやったそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（11:10〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=670s"]]}, {"cat": "リングに来るまで", "t": "PPV観戦のチラシがプロレス学校への入口に", "b": "2008年、友人とWWEの大会を見に行った帰りの車で、プロレス学校のチラシを見つけたという。学校があることすら知らなかったが、調べてすぐ連絡し、数日後の木曜に初めての練習に参加した。最初は裏庭のリングで学び、半年後に別の学校へ移ったそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（12:48〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=768s"]]}, {"cat": "リングに来るまで", "t": "仮眠は会場の前、夜はタクシーで稼ぐ", "b": "朝と午後の練習を一つも逃したくなくて、夜通しタクシーを運転し、練習前に会場の前で3〜4時間仮眠したという。技のしくみがまるで魔法のようで、夢中だったと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（14:24〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=864s"]]}, {"cat": "リングに来るまで", "t": "前十字靭帯を痛めたままトライアウトへ", "b": "2010年のサマースラムの時期に、ロサンゼルスで入団テストを受けたという。前十字靭帯を痛めており、トイレでテープを巻いて隠して臨んだ。相手に顔を蹴られ続けて怒りかけたが、終了後に声がかかり、フロリダ行きの話が出たそうだ。ただし書類の問題でさらに1年待つことになり、2011年にようやく入った。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（16:52〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1012s"]]}, {"cat": "家族", "t": "母はボートの世界王者、父も選手", "b": "母はボート競技で世界王者になった人で、父もボート選手だったという。苦しい時代にも施しを求めず働き続けた両親の姿が、今の考え方の土台になっていると話す。家族は今もブルガリアにいて、渡米から21年がたち、人生の半分以上をアメリカで過ごしている。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（20:09〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1209s"]]}, {"cat": "体のこと", "t": "膝の靭帯と首の骨折、解雇寸前の時期", "b": "育成時代に前十字靭帯を手術し、約6か月休んだという。復帰の2か月後には首の骨折が見つかり、再び手術を受けた。会社に費用をかけるばかりで、クビになると覚悟していたそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（22:29〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1349s"]]}, {"cat": "リングの話", "t": "解雇の瀬戸際で初心者クラスから巻き返し", "b": "会社から1〜2か月の猶予を告げられ、初心者クラスに回されたが、悔しさを力に変えたという。1か月後には最も成長した選手として表彰された。悪役映画を見直して立ち方や装い、態度を変え、裸足で戦うスタイルを作ったと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（23:17〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1397s"]]}, {"cat": "リングの話", "t": "ジグラー戦とラナとの組み合わせで一気に出世", "b": "育成から新しい仕組みに移り、体系だった指導が自分に合っていたという。NXTのテレビに出ていない時期にドルフ・ジグラーの相手に選ばれ、相手の配慮で見せ場を作れた。それをトリプルHが気に入り、ロシア語を話すラナと組んで『ロッキー4』を手本に役を作ったそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（24:56〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1496s"]]}, {"cat": "リングの話", "t": "裸足は終わり、ライバックの一撃で足首を痛める", "b": "裸足はウマガに憧れて始めたもので、数年続けたという。ライバックにロープ越しの背面投げを受けて足首を痛め、そこでブーツに替えた。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（28:05〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1685s"]]}, {"cat": "リングの話", "t": "ルセフ・デーは自然に広まった", "b": "ルセフ・デーは最初は計画ではなく、故郷の市長から鍵を贈られるお祝いの場面だったという。悪役の演技を少し緩めて素の自分を出したところ観客が受け入れ、ニュー・デイとの絡みやTシャツで広がった。観客が望むものを見せたいと思い、方向性を会社に訴えたと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（29:50〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1790s"]]}, {"cat": "暮らし", "t": "解雇後はTwitchでゲーム配信", "b": "解雇後、競業禁止の3か月間にTwitchを始めたという。ゲームをして楽しみながら収入を得て、少しずつ視聴者を増やした。その後AEWで試合に復帰したと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（36:11〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=2171s"]]}, {"cat": "リングの話", "t": "パリでのシェイマスとの乱戦", "b": "パリ大会のシェイマス戦は、親友だからこそ思い切りやり合えたという。当日は舞台裏でも苦労があったが、周囲の協力で実現した。樽の上で相手の背に乗る場面は不安定で、頭の中を色々な思いが駆けめぐったそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（36:58〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=2218s"]]}, {"cat": "暮らし", "t": "ナッシュビルに住み、子ども向けも教えるスクールを開設", "b": "ナッシュビルに家を持ち、プロレススクールを始める準備をしているという。3月中旬の開校予定で、8歳からの子どもクラスも設ける。基礎を重んじる古くからの師匠ギャングレルも、講師として加わる予定だそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（40:14〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=2414s"]]}, {"cat": "リングの話", "t": "レッスルマニア31の入場は、書き出して願った案", "b": "ジョン・シナ戦の入場は、新人の頃に紙に案を書き出して考えたものだという。直前になって戦車や銃を使うと知り、望んでいた以上だったと話す。家族が最前列で見てくれたことも大切な思い出だそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（50:02〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=3002s"]]}, {"cat": "リングの話", "t": "シナから学んだ「観客の声を聞く」", "b": "シナとは何千回も会場で試合をしたという。その中で、テレビも巡業も関係なく、観客が反応しないなら見たいものを見せていないだけと学んだ。観客の様子を読み、時間をかけるのが大事で、繰り返しで身につくと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（52:25〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=3145s"]]}, {"cat": "リングの話", "t": "米国王座は「自分の王座」", "b": "米国王座を3度巻き、そのうち2回は誕生日に勝ったことが特別だと話す。世界王座でなくても、与えられた王座を最大限に大きくしたいと考えてきたそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（58:09〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=3489s"]]}, {"cat": "リングの話", "t": "リーグ・オブ・ネイションズとスタナーの受け方", "b": "リーグ・オブ・ネイションズは、ローマン・レインズを大きな人気者にするために作られた面があったと見ているという。レッスルマニアでストーン・コールドのスタナーを受けたことは夢の実現で、首を痛めない高さで受けたと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:00:38〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=3638s"]]}, {"cat": "暮らし", "t": "「ゼロから来た」と前向きに語る", "b": "不満を言っても状況は変わらないと考え、前向きでいることを大事にしているという。何も持たずにアメリカへ来た自分が家族を養えるようになったことを、プロレスのおかげだと感謝している。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:09:03〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=4143s"]]}, {"cat": "暮らし", "t": "両親に家を買い、賃貸用の家を多く持つ", "b": "両親に家を買い、兄弟も良い暮らしをしているという。自分でも貸し出し用の物件を30軒ほど持つと話し、収入は投資に回すべきだと語る。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:09:53〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=4193s"]]}, {"cat": "体のこと", "t": "45歳まで続け、体をいたわって過ごす", "b": "引退の目安は45歳で、そこで体の状態を見直すつもりだという。試合数が減ったぶん今は体の調子が良く、ストレッチやマッサージ、食事と短く濃いトレーニングを心がけている。食事は妻と家で作ると話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:10:40〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=4240s"]]}, {"cat": "暮らし", "t": "引退後は故郷ブルガリアの市長を目指す", "b": "引退後は故郷の市長になりたいという。入学の申し込みを逃したため来年こそ、公共行政を学ぶ学校に通うつもりで、ブルガリアの制度を学びたいと話す。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:10:40〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=4240s"]]}, {"cat": "家族", "t": "体外受精で子どもを授かる道のり", "b": "妻と体外受精に取り組んでおり、年内に子どもが生まれることを楽しみにしていると話す。名前は、女の子ならホーク、男の子ならベアにしたいと冗談めかして語り、妻にはミドルネームにしようと説得されているそうだ。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:13:00〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=4380s"]]}, {"cat": "好きなもの", "t": "一番の映画はターミネーター2、ターミネーターを集める", "b": "完璧な映画は『バック・トゥ・ザ・フューチャー』と言う聞き手に対し、本人はターミネーター2を挙げ、続編として最高だと話す。ほかにダークナイトやロボコップも好きだそうだ。ターミネーター関連の品を集めていて、新しい品も届く予定だという。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-Iekjl3nwEmI", "src": [["番組のYouTube（1:34:00〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=5640s"]]}]);
  if (PROFILES["Sheamus"]) PROFILES["Sheamus"].facts.push({"cat": "暮らし", "t": "シェイマスとは親友", "b": "シェイマスとは親友で、そのため激しい試合のあとでも許し合えると、ルセフが話している。二人ともナッシュビルに住んでいるという。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で、ルセフの話（字幕を全文確認）", "src": [["番組のYouTube（36:58〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=2218s"]], "by": "第三者の話"});
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "シナは観客を読む名人", "b": "ジョン・シナは試合の前に客席の様子を見て会場の空気をつかみ、相手に合わせて動いていたと、ルセフが話している。そうした姿から多くを学んだという。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で、ルセフの話（字幕を全文確認）", "src": [["番組のYouTube（52:25〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=3145s"]], "by": "第三者の話"});
  if (PROFILES["Dolph Ziggler"]) PROFILES["Dolph Ziggler"].facts.push({"cat": "暮らし", "t": "ジグラーの思いやり", "b": "ドルフ・ジグラーは、一方的に潰す試合にしても誰のためにもならないと言い、見せ場を作らせてくれたと、ルセフが話している。", "sp": "ルセフ", "d": "2026-02-17", "how": "クリス・ヴァン・ヴリートの番組で、ルセフの話（字幕を全文確認）", "src": [["番組のYouTube（25:43〜）", "https://www.youtube.com/watch?v=Iekjl3nwEmI&t=1543s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Iekjl3nwEmI", d: "2026-02-17", show: "ext", who: ["Rusev"], t: "ルセフの回　ブルガリアからの下積みと復帰後の日々", lead: "クリス・ヴァン・ヴリートの番組に出た約80分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Rusev"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Iekjl3nwEmI").map((x) => [x.t, x.b, x.sp])), open: ["番組の宣伝、スポンサー読み、試合の細かな解説は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Iekjl3nwEmI"]] });
  if (!ROSTER.find((r) => r[1] === "Seth Rollins")) ROSTER.push(["セス・ロリンズ", "Seth Rollins", "lg", "元WWE世界王者", "", "", ""]);
  if (!PROFILES["Seth Rollins"]) PROFILES["Seth Rollins"] = { lead: "アイオワの小さな町で継父に育てられ、5歳で見たプロレスに人生を決められた。インディーでの下積みを経て頂点に立ち、今は妻と娘との暮らしを大切にしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Seth%20Rollins"]], moves: [], facts: [] };
  if (PROFILES["Seth Rollins"]._weak) { PROFILES["Seth Rollins"].lead = "アイオワの小さな町で継父に育てられ、5歳で見たプロレスに人生を決められた。インディーでの下積みを経て頂点に立ち、今は妻と娘との暮らしを大切にしている。"; delete PROFILES["Seth Rollins"]._weak; }
  PROFILES["Seth Rollins"].facts.push(...[{"cat": "家族", "t": "人口1000人足らずのアイオワの町で育つ", "b": "生まれ育ったのはアイオワ州バッファロー。人口が千人に満たず、信号もなく、中学・高校へはバスで隣町まで通う土地だったという。高校を出たら町を出る人が多く、本人も今は近くのダベンポートで過ごす時間が長いと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=145s"]]}, {"cat": "家族", "t": "継父に養子にされ、ロペスの姓で育った", "b": "2歳のころに継父ロン・ロペスの養子になり、物心ついたときからロペスが自分の姓で、ロンが父だったという。継父の両親やおじたちも自分を実の家族のように迎えてくれたと、セス・ロリンズは話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=238s"]]}, {"cat": "家族", "t": "鉄工所で働く継父は、いつも野球やサッカーの面倒を見てくれた", "b": "継父は製鉄所などで手を動かして働く人で、華やかな仕事ではなかったそうだ。それでも野球チームの監督を引き受け、やり方を知らないサッカーのチームまで受け持った。人を先に思いやること、働くこと、つらくても笑顔でいることを両親の姿から学んだという。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（5:32〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=332s"]]}, {"cat": "家族", "t": "両親の離婚後も、父とのつながりは切れなかった", "b": "両親が離婚したのは10〜11歳のころ。それでも二人は円満で、継父は離婚後も変わらず父であり続けたという。母はその後も再婚し、三番目の夫もよい継父だったそうで、「家庭は崩れたが、よい男の手本には恵まれた」とセス・ロリンズは振り返る。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（6:20〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=380s"]]}, {"cat": "家族", "t": "ヒスパニック系の家族と気づいたのは大人になってから", "b": "ロペス家は町でただ一つのヒスパニック系の家族だったかもしれないが、14歳ごろまで両親が異人種間の関係だとは意識しなかったという。のちに母に聞くと、周りから奇異な目で見られることはあったそうだ。本人はアルメニア系の血も半分ひいていると話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（8:45〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=525s"]]}, {"cat": "家族", "t": "3歳上の兄は「血よりも濃い」親友", "b": "母は三度結婚しており、最初の結婚で生まれた3歳上の兄とは親友のように近いという。二度目の結婚相手の子どもたちとはほとんど連絡を取らず、三度目の結婚で生まれた約6年下の妹は義理の妹のような存在だと考えていると話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（10:16〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=616s"]]}, {"cat": "家族", "t": "遺伝子検査がきっかけで、実の父側のきょうだいと出会った", "b": "家族の病歴を聞かれても答えられず、遺伝子検査サービスを試したのが発端。数年後、サイトに届いた連絡が実の父の娘、つまり異父の妹からだったという。実の父はほかに子がいると誰にも話していなかったため、家族にとっては驚きだったそうだ。今はその妹や弟と良好な関係だと、セス・ロリンズは話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（11:01〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=661s"]]}, {"cat": "家族", "t": "実の父とは電話で一度話しただけ", "b": "実母はシカゴで妊娠し、アイオワに戻って育てることを選んだ。父は子を持つ準備ができていなかったのだろう、とセス・ロリンズは受け止めている。電話で一度会う話が出たが連絡はなく、今も会っていない。恨みはなく、向こうが望めばいつでも会うと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（13:23〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=803s"]]}, {"cat": "好きなもの", "t": "5歳で見たプロレスが人生を変えた", "b": "まだ4〜5歳のころ、父に初めてプロレス興行へ連れて行かれたという。祖父やおじも観ていた90年代初頭で、ハルク・ホーガンやリージョン・オブ・ドゥームが悪者と戦う姿は、本物のスーパーヒーローを見たようだったと話す。そこから夢中になった。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（18:10〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1090s"]]}, {"cat": "リングに来るまで", "t": "野球・バスケ・アメフトをこなすも、野球は顔に当たって辞めた", "b": "子どものころは野球、バスケットボール、アメフト、サッカーをやっていたという。サッカーは苦手で、バスケは14歳ごろまで、アメフトは13〜14歳まで続けた。野球は打席でボールが顔に当たるのが怖くなり、やめたそうだ。アメフトはクォーターバックからセーフティまで、いろいろな位置を守ったと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（19:46〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1186s"]]}, {"cat": "好きなもの", "t": "憧れはショーン・マイケルズとブレット・ハート", "b": "最初に好きになったのはハルク・ホーガンだが、自分はあの体格にはなれないと思っていたそうだ。本当に憧れたのは、小柄で速く、それでもスターだったショーン・マイケルズとブレット・ハート。大きくなくてもスターになれると教えてくれた存在だという。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（20:35〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1235s"]]}, {"cat": "リングに来るまで", "t": "14歳の夏、夕食の席で「プロレスラーになる」と宣言", "b": "中学を終えた夏、両親に「バスケはやめてプロレスラーになる」と言い切ったという。両親は悲しそうだったが、本人は裏庭で兄や友達と試合を始め、学校でチラシを配って観客まで集めていた。ジムに通い、話し方の授業や演技の授業を取り、髪も伸ばした。親は一時の気の迷いと思っていたそうだ。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（22:12〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1332s"]]}, {"cat": "リングに来るまで", "t": "17〜24歳はインディー団体で下積み", "b": "17歳のころから、地元の小さな興行で試合をしていたという。正式に習う前は、20ドルを払って練習に参加するようなこともあった。そこからWWEと契約する24歳ごろまで、約7年をインディー団体で過ごしたと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（24:39〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1479s"]]}, {"cat": "リングに来るまで", "t": "観客10人未満、納屋や公民館でも試合をした", "b": "お金にならず、むしろ持ち出しで、観客が10人に満たない日もあったという。高校の体育館、納屋、労組のホールなど、リングを置ける場所ならどこでも行った。つらくても、仲間と車で何時間も走り、帰りに試合の映像を見て語り合う時間が好きだったと、セス・ロリンズは話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（25:31〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1531s"]]}, {"cat": "リングに来るまで", "t": "母の条件で大学に通い、バイトもしながら続けた", "b": "母は、学校に行かないなら家でレスラーをしてはいけないという考えだったので、大学に通いアルバイトをしながら続けたという。のちに「ここまでやれている、やめさせてほしい」と母に頼み、了承をもらって大学をやめたそうだ。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（27:50〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1670s"]]}, {"cat": "リングに来るまで", "t": "WWEにたどり着いた経緯と、巨額の他団体の誘いを断った話", "b": "インディー団体時代、元WWE選手のジョーイ・マーキュリーが紹介状のように動いてくれ、映像を送ってもらったという。当時のWWEは体の大きな選手を探しており、なかなか返事が来なかった。TNAの契約を明朝サインするつもりで最後の電話をかけたところ、15分後に折り返しが来た。翌日「機会を与える」と言われ、金額も聞かずに受けたそうだ。他団体はおそらく3倍以上の額だったという。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（28:35〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1715s"]]}, {"cat": "リングに来るまで", "t": "育成施設の倉庫で約2年、呼ばれるのを待った", "b": "契約後はフロリダ州タンパの倉庫のような施設に送られ、約2年待ったという。まだ今のような育成ブランドがない時代で、閉じ込められたような時期だったと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（31:48〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1908s"]]}, {"cat": "リングの話", "t": "3人組デビューでSNSが沸いた", "b": "ローマン・レインズ、ディーン・アンブローズ（のちのジョン・モクスリー）との3人でデビューしたとき、インディー時代からのファンがSNSで盛り上がったという。与えられたボールで点を取り続けたから、さらにボールを渡された、とセス・ロリンズは例える。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（31:48〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=1908s"]]}, {"cat": "リングの話", "t": "得意技を封じられ、トリプルHの技を引き継いだ", "b": "初めて世界王座を獲った翌日、ヴィンスから得意技の使用を止められたという。理由の説明はなく、本人は朝の情報番組の映像で名前が問題視されたのではと推測している。数か月フィニッシュ技が定まらなかったが、師匠のトリプルHの技を使うことにし、直接断られないようヴィンスに先に頼んで許可を得たと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（38:27〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=2307s"]]}, {"cat": "リングの話", "t": "シールド解散には反対だったが、実行役を任された", "b": "3人組ザ・シールドの解散は数か月前から提案されていたが、悪役から人気者に変わり、もっと続けられると思っていたため反対したという。解散を知らされたのは当日の事務所で、実行役は自分だと告げられた。部屋は沈黙し、出たあとも本当にいいのかと悩んだそうだ。今も道を歩くと「なぜシールドを裏切ったのか」と聞かれると話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（40:53〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=2453s"]]}, {"cat": "リングの話", "t": "ヒーローか悪役かを決めるのは観客", "b": "会社の希望より、最後は観客が決めるというのがセス・ロリンズの考え。ローマン・レインズやベッキー・リンチが、悪役の立場に回ったり観客に押し上げられたりして大きくなった例を挙げている。悪役のほうが自由が利き、ヒーローは少しの失敗でも見放されやすいので、続けるのは難しいと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（44:06〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=2646s"]]}, {"cat": "体のこと", "t": "けがや脳しんとうへの対処", "b": "プロレスは足の怪我などがあっても試合を続ける場面があると説明している。脳しんとうが疑われるときは審判が止めるのが基本で、選手同士や審判との連絡が大事だと話す。ジョン・シナの鼻を折ったときは偶然の事故で、わざとではなかったと言う。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（50:41〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=3041s"]]}, {"cat": "リングの話", "t": "試合中のけがは、その場で自分を診断して判断する", "b": "オーストラリア・パースでのコーディ・ローデス戦で肩を痛めた経験を語っている。技の直後に自分の状態を確かめ、あと10〜15分は大丈夫と判断して試合をやり切ったという。相手に危険が及ばないか、審判や相手に伝えて決めるのが大切だと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（52:17〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=3137s"]]}, {"cat": "リングの話", "t": "CMパンクとは和解していない", "b": "インディー時代からパンクを見ていて、練習に通う余裕がなかった自分を、WWEに入ってからは泊めたり助けたりしてくれた恩人でもあったという。ところが彼が退団すると連絡が途絶え、その後の発言にも傷ついたと、セス・ロリンズは話している。復帰した今も、仕事上の関係はあっても和解には至っていない。将来、二人とも現役を退いたころに機会があるかもしれないという。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（58:53〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=3533s"]]}, {"cat": "リングの話", "t": "体格差のある相手との試合が好き", "b": "階級のないプロレスだからこそ、小さい選手が巨漢と戦う組み合わせが見られるのが魅力だという。ブロック・レスナーのような相手とも、自分の強みで弱点を突くことで戦える。ビッグ・ショーなどの巨漢とは、相手の協力がなければ技が成立しないと話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:04:38〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=3878s"]]}, {"cat": "リングの話", "t": "ロンダ・ラウジーがWWEを去った理由への見方", "b": "ロンダ・ラウジーのときは試合数が少なく、準備された形で始まるため、現場でたたき上げる普通の道と逆だったという。母になりたい気持ちもあり、驚きはなかったと話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:09:31〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=4171s"]]}, {"cat": "家族", "t": "妻ベッキー・リンチとは長い友人から恋人に", "b": "ベッキー・リンチとは何年も友人だったあと、約6年前に付き合い始めたという。それまで19歳から15年間、ほぼ切れ目なく恋愛を続けていたため、一度は独りになる必要があると考えていた。ベッキーが「友達のままでいよう」と言った瞬間に手放したくないと気づき、約2週間後に付き合うことになったそうだ。交際2か月ほどで指輪を注文していたと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:16:04〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=4564s"]]}, {"cat": "暮らし", "t": "かつては年に215試合、週のほとんどを移動していた", "b": "いちばん忙しい年は試合が215ほどあり、金曜朝に出発して月曜の生中継、火曜の収録、水曜朝に帰宅するという生活を何年も続けたそうだ。自宅にいるのは36時間ほどで、年に300日は旅先だったと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:16:56〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=4616s"]]}, {"cat": "暮らし", "t": "映画の出演シーンがカットされた", "b": "ある大作ヒーロー映画に出演し、撮影も終えたが、制作の方針転換で役が一人に統合されたという。オーディションのように再挑戦もしたが、結局落選した。もともと映画の現場は待ち時間が長く、あまり好きではなく、2016年に作ったWWEの映画も楽しめなかったと話す。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:24:09〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=5049s"]]}, {"cat": "暮らし", "t": "ジムは週4回、40歳を前に量を減らした", "b": "35歳ごろから昔のように回復できなくなり、娘が生まれてからは時間の使い方も変わったという。今は週に4日ほどトレーニングをし、食事の量も管理し、週に1回は整体のようなケアも受ける。家にいるときは、娘の学校の送り迎えをして過ごすそうだ。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:29:51〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=5391s"]]}, {"cat": "暮らし", "t": "娘は2020年12月生まれ、母も近くに引っ越した", "b": "娘が2020年12月に生まれ、妻のベッキー・リンチが7月に復帰してからは、毎週末の遠征に娘を連れて世界中を回ったという。今は就学前の教室に通い始めたため同行は選んだ旅行だけになり、セス・ロリンズの母がロサンゼルスに引っ越したので、祖母が面倒を見てくれると話す。WWEも家庭に配慮してくれるという。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:31:27〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=5487s"]]}, {"cat": "好きなもの", "t": "シカゴ・ベアーズの大ファン", "b": "シカゴ出身の熱烈なベアーズファンで、今季はソルジャー・フィールドにも足を運んだという。ベン・ジョンソン監督とカレブ・ウィリアムズの組み合わせに期待していて、今年は予想以上の成績だったと話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で（字幕を全文確認）", "art": "ext-PjspdxGnKmE", "src": [["番組のYouTube（1:33:45〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=5625s"]]}]);
  if (PROFILES["Bad Bunny"]) PROFILES["Bad Bunny"].facts.push({"cat": "暮らし", "t": "プロレス好きのバッド・バニー", "b": "プエルトリコでのダミアン・プリースト戦は、ストリートファイトとして本格的に戦ってくれたと、セス・ロリンズが話している。世界的なアーティストが机や椅子の攻撃を受けるなんて、とても驚きだったそうだ。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で、セス・ロリンズの話（字幕を全文確認）", "src": [["番組のYouTube（1:12:00〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=4320s"]], "by": "第三者の話"});
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "ブロック・レスナーとの対戦は階級のない面白さ", "b": "階級のないプロレスだからこそ、小柄な選手が巨漢と戦えるのが魅力で、ブロック・レスナーとの対戦もその一例だと、セス・ロリンズが話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で、セス・ロリンズの話（字幕を全文確認）", "src": [["番組のYouTube（1:04:38〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=3878s"]], "by": "第三者の話"});
  if (PROFILES["Logan Paul"]) PROFILES["Logan Paul"].facts.push({"cat": "暮らし", "t": "ローガン・ポールは本気で取り組んでいる", "b": "ローガン・ポールはいつの間にかプロレスにはまり、今ではほぼ毎週のように出ていると、セス・ロリンズが話している。", "sp": "セス・ロリンズ", "d": "2026-02-18", "how": "クラブ・シェイ・シェイの番組で、セス・ロリンズの話（字幕を全文確認）", "src": [["番組のYouTube（1:08:44〜）", "https://www.youtube.com/watch?v=PjspdxGnKmE&t=4124s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-PjspdxGnKmE", d: "2026-02-18", show: "ext", who: ["Seth Rollins"], t: "セス・ロリンズの回　家族の出生の話と、下積みから頂点まで", lead: "クラブ・シェイ・シェイの番組に出た約99分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Seth Rollins"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-PjspdxGnKmE").map((x) => [x.t, x.b, x.sp])), open: ["実の父の名前、異父きょうだい、事件の相手などの私人の話は名前を出さず、要点だけにした。", "番組の宣伝・スポンサー部分と、聞き手側の話は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=PjspdxGnKmE"]] });
  if (!PROFILES["Royce Keys"]) PROFILES["Royce Keys"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Royce%20Keys"]], moves: [], facts: [] };
  if (PROFILES["Royce Keys"].lead === "") PROFILES["Royce Keys"]._weak = 1;
  PROFILES["Royce Keys"].facts.push(...[{"cat": "リングの話", "t": "リングネームは次男への贈り物", "b": "ロイス・キーズは、WWEでのリングネームを次男のロイスにちなんで付けたと話す。自分への献身の気持ちを込めた名前だという。次男は水瓶座の自分とそっくりで、何かを疑われるとすぐ「やってない」と言うところまで似ていると笑っている。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（4:05〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=245s"]]}, {"cat": "リングの話", "t": "育った地元の会場でインディー興行", "b": "ロイス・キーズは、少年時代に初めて生観戦した地元の会場で、インディーの大会に出たことがあると話す。かつての名レスラーを称える催しで、相棒のマーカス・ルイスとライオン・パワーというタッグを組んだそうだ。ウィル・パワーというリングネームでの出場で、その会場の前を通るたびに祖父母の話を思い出すと語っている。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（12:15〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=735s"]]}, {"cat": "リングの話", "t": "目標は王者、伝説、殿堂入り", "b": "ロイス・キーズは、WWEと契約できても一度きりの話題で終わらせるつもりはないと話す。目指すのは王者になること、伝説になること、殿堂入りすること、そして最も圧倒的で恐れられる選手として記憶されることだという。ここまで来るのに何年もかかったので、浮かれる時期は終わり、毎日努力して勝ち取るものだと考えているそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（40:31〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=2431s"]]}, {"cat": "リングの話", "t": "ある試合の夜、母への思いが込み上げた", "b": "ロイス・キーズは、母が亡くなった直後にコーディ・ローズが電話をくれて、すぐに気づかってくれたと話す。その約1か月後にCMパンクと試合をしたとき、パンクが「今夜、お母さんは最前列で見ている」と声をかけたという。ピンフォールの後、胸をたたきながら母の愛称を口にしてくれ、その場で涙が止まらなかったそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（51:45〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=3105s"]]}, {"cat": "リングの話", "t": "入場を見る子どもたちの目", "b": "ロイス・キーズは、家に帰ったとき、子どもたちが自分の入場や試合を見て目を輝かせるのがうれしいと話す。小さいころの自分がテレビの前や祖父母の隣でレスリングを見ていた姿と重なるという。子どもがコメントを読むのは良くないので、そうならないよう気をつけているそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:02:14〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=3734s"]]}, {"cat": "リングの話", "t": "サウジでの「隠し部屋」暮らし", "b": "ロイス・キーズは、サウジアラビアでは登場を伏せるために、ほかの人から見えない部屋に滞在したと話す。ホテルのジムを使いたいと頼むと、しばらく沈黙があり、サプライズなので見られたくないと言われたそうだ。後でベンチやダンベル、バンドが部屋に届き、音楽を流しながら524回のトレーニングをこなしたという。ルームサービスも楽しんだと振り返っている。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:21:35〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=4895s"]]}, {"cat": "リングの話", "t": "リングの上では競争心むき出し", "b": "ロイス・キーズは、子どものころにストリートバスケをしていた影響で、自分はとても負けず嫌いだと話す。リングでは冗談を言う面もあるが、本気になれば相手をたたきのめすと語る。ためこんだ嫌なことや苦しいことを全部リングで出す一方、いつ切り替えるかは自分でコントロールできるそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:40:12〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=6012s"]]}, {"cat": "リングの話", "t": "決め言葉は「アイト」", "b": "ロイス・キーズは、「アイト」という言葉をよく使い、自分のTシャツにも入っていると話す。「アイトと言って、欲しいものは取りに行く」という考え方で、自分で何かできるようになってからずっとそうしてきたという。息子のフラッグフットボールのチームにもこの言葉を使い、子どもたちが「アイト」と返してくるそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:42:49〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=6169s"]]}, {"cat": "リングの話", "t": "入場前の儀式とタイガーバームの失敗", "b": "ロイス・キーズは、試合前に音楽を聴いてストレッチをし、鼻にタイガーバームを塗ってから行く習慣があると話す。ロイヤルランブルのときは、量が多すぎて指に残ったまま試合に入り、目が焼けるように痛くなったそうだ。試合中は何人も倒していったが、目がひりひりしたまま動いていたという。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:45:14〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=6314s"]]}]);
  if (!PROFILES["Royce Keys"]) PROFILES["Royce Keys"] = { lead: "治安の厳しいイーストパロアルトで祖父母に育てられ、レスリング一家の中で夢を追い続けた3児の父。家族の死やトラウマを率直に語りつつ、祖母仕込みの民間療法の話で場を笑わせる人柄だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Royce%20Keys"]], moves: [], facts: [] };
  if (PROFILES["Royce Keys"]._weak) { PROFILES["Royce Keys"].lead = "治安の厳しいイーストパロアルトで祖父母に育てられ、レスリング一家の中で夢を追い続けた3児の父。家族の死やトラウマを率直に語りつつ、祖母仕込みの民間療法の話で場を笑わせる人柄だ。"; delete PROFILES["Royce Keys"]._weak; }
  PROFILES["Royce Keys"].facts.push(...[{"cat": "家族", "t": "3人の子を持つ父親", "b": "20歳近い長男、もうすぐ8歳になる次男、5歳の長女の3人の父だという。性格はそれぞれ違うが、みんな父親にかまってもらうのが大好きだそうだ。父親業で学んだのは忍耐と、子どもを育むことだと話す。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（3:17〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=197s"]]}, {"cat": "家族", "t": "リングネームは次男の名前から", "b": "リングネームの「ロイス」は次男の名前で、息子への思いを込めたものだという。同じ水瓶座で、何でも「やってない」と言い張るところが子どもの頃の自分にそっくりだと笑う。友だちを思いやり、かばう優しい子だとも話している。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（4:05〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=245s"]]}, {"cat": "家族", "t": "末娘は育ての祖母の生き写し", "b": "子どもたちのあだ名は「ババ」「バムバム」「ムーキー」。5歳の末娘はどんな言葉にも即答する仕切り屋で、大きな目でじっと見つめてくる様子が自分を育てた祖母エヴリンにそっくりだという。末娘のミドルネームはその祖母から取ったそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（5:47〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=347s"]]}, {"cat": "家族", "t": "ミシシッピ出身の祖父母に育てられる", "b": "両親にはそれぞれ事情があり、父方の祖父母「ビッグママ」と「パパ」のもとで育ったという。祖母は身長165センチほどの赤毛の女性で、近所でも「容赦しない人」として知られていた。祖父母は1963年ごろ、差別の厳しかったミシシッピから長距離バスでカリフォルニアのデイリーシティへ移り住んだそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（6:33〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=393s"]]}, {"cat": "リングに来るまで", "t": "祖父母の家は大会場の向かい", "b": "祖父母の家はサンフランシスコ近郊の大会場カウ・パレスの向かいにあり、祖父母は隔週で地元団体のプロレス興行に通っていたという。WWEを知る前から、パット・パターソンやレイ・スティーブンスら往年の選手の話を祖父から聞かされて育った。父も子どもの頃に観戦し、パターソンの裏切りに泣いて祖父に担がれて帰ったそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（10:38〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=638s"]]}, {"cat": "リングに来るまで", "t": "思い出の会場で凱旋試合", "b": "自身もカウ・パレスで初めてプロレスを観たという。のちにインディー時代、パット・パターソンをたたえる大会がその会場で開かれ、マーカス・ルイスとのタッグ「ライオン・パワー」（自身は「ウィル・パワー」名義）で出場した。祖父母はすでに亡くなっていたが、会場の前を通るたびに二人を思い出すそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（12:15〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=735s"]]}, {"cat": "リングに来るまで", "t": "録画テープと危ない「家プロレス」", "b": "祖父の知人に試合を録画してもらい、祖母がラベルを書いたVHSで繰り返し観ていたという。額には、姉に祖母の大理石のテーブルをコーナー代わりにされてできた傷が残っている。近所の友人と屋根から石膏ボードに飛び降りたり、アイロン台をテーブル代わりにしたり、裏庭のフェンス越しにロイヤルランブルごっこをしたりしたそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（13:57〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=837s"]]}, {"cat": "リングに来るまで", "t": "周りに笑われても夢は一つ", "b": "地元ではアメフトやバスケが花形で、プロレスラーになりたいと言えばからかわれる環境だったという。それでも幼い頃から自分はレスラーになると決めていた。いまも子ども番組が終わると一人でプロレスを観て研究しており、最近はマーク・ヘンリーやバンバン・ビガロなど大型選手の試合をよく観ているそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（15:34〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=934s"]]}, {"cat": "暮らし", "t": "「全米一の殺人都市」で育つ", "b": "育ったのは面積2平方マイルほどのイーストパロアルトで、かつて全米で最も殺人が多い街と呼ばれていたという。銃声はほぼ毎晩聞こえ、街灯がついたら家に入るのが祖母の絶対のルールだった。多くの友人や身内を亡くし、刑務所に入った知人も多く、祖母がいなければ自分も同じ道をたどっていたと話す。オークランドでも育ったそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（26:40〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=1600s"]]}, {"cat": "家族", "t": "貧しくても愛があった", "b": "祖父は若い頃ミシシッピで綿摘みをし、わずかな稼ぎを母親に渡していたという。家にお金はなかったが、必要なものはそろっていたと振り返る。祖母は家族が何をしても無条件に愛する人で、その愛が自分を支えたと語っている。病気の日は祖母のそばで一緒にクイズ番組や昼ドラを観たそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（29:03〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=1743s"]]}, {"cat": "体のこと", "t": "カウンセリングに通っている", "b": "いまはセラピーに通い、胸の内を話すようにしているという。育った黒人社会では、セラピストに相談すると周りにおかしいと思われる風潮があったそうだ。大人になって、批判せずに話を聞いてくれる人が必要だと気づいたと話す。身内を自殺で亡くした経験もあり、悩んでいる人には誰かに打ち明けてほしいと呼びかけている。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（32:14〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=1934s"]]}, {"cat": "家族", "t": "2021年に母を亡くす", "b": "母は2021年に亡くなったという。プロレスに詳しく、大会に連れて行ってくれたり人形を買ってくれたりした人で、初めてテレビで試合を観た時には長いメッセージを送ってくれた。最期は家族として延命をやめる決断の場に立ち会い、もっと何かできたのではという思いがいまも消えないそうだ。レモンケーキやオージェイズの曲で母を思い出すという。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（33:05〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=1985s"]]}, {"cat": "暮らし", "t": "短気だった自分を変えた子どもたち", "b": "昔は言われたらすぐ言い返す性格で、すぐカッとなるのは父や祖父譲りだという。いまは自分を頼る家族がいるため、一呼吸おいて立ち去ることを心がけているそうだ。「誰もがあなたを好きになるわけじゃない」という祖母の言葉を、自分の子どもにも伝えている。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（41:16〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=2476s"]]}, {"cat": "家族", "t": "兄を銃の暴力で失う", "b": "薬物の売買に関わっていた兄は、自分をかばって命を落としたという。その後何年も、生き残った罪悪感と、兄に憧れた自分への後ろめたさを抱えてきたと明かしている。自身も撃たれたり刺されたりした経験があり、これらすべてが今の自分をつくったと話す。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（45:24〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=2724s"]]}, {"cat": "好きなもの", "t": "食べ物の思い出と好きなシリアル", "b": "感謝祭になると祖母が作ったコーンブレッドのドレッシングやコラードグリーン、スイートポテトパイを思い出すという。いとこと抗議のつもりでごちそうを食べずにコーンフレークを食べ、叱られたこともあったそうだ。チートデイの好物はシリアルで、フルーティーペブルスやコーンポップスが好き。祖母に食べさせられた全粒粉のシリアルは苦手で、こっそりトイレに流していたと笑う。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（54:56〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=3296s"]]}, {"cat": "好きなもの", "t": "馬とスカイダイビングと船は苦手", "b": "大人になってから一度だけ乗馬をしたが、大きな黒馬をあてがわれて生きた心地がせず、二度と乗らないと決めたという。スカイダイビングも船もごめんだそうで、怖いものは「馬と飛行機とスカイダイビングと船」だと笑う。映画『タイタニック』は長すぎて観ていないそうだ。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:12:03〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=4323s"]]}, {"cat": "暮らし", "t": "筋トレはストレス解消", "b": "トレーニングが大好きで、ストレス解消になっているという。遠征先のホテルで部屋から出られなかった時は、届けてもらったベンチとダンベルで計524回のメニューをこなしたそうだ。マイケル・ジャクソンやUB40、AC/DCに映画『KPOPガールズ！デーモン・ハンターズ』の曲まで流しながら、ルームサービスで卵を大量に頼んだと話す。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:23:18〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=4998s"]]}, {"cat": "体のこと", "t": "祖母直伝のヴィックスとホット・トディ", "b": "幼い頃は気管支炎を患っていたという。祖母は塗り薬のヴィックスを胸や足に塗るだけでなく少量を飲み込ませ、5歳の頃にはブランデー入りのホット・トディも飲まされたそうだ。真似はしないでほしいと念を押しつつ、「ヴィックスとホット・トディ」は番組中の決め台詞になった。試合前には鼻にタイガーバームを塗るのが習慣だという。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:31:23〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=5483s"]]}, {"cat": "暮らし", "t": "地元に「ロイス・キーズの日」", "b": "約2年前、地元イーストパロアルトから自分の名前を冠した記念日を贈られたという。日付は3月29日で、偶然にも母の誕生日だったそうだ。今も地元の食料品店に行けば店主が覚えていて、子どもの頃にお菓子を盗もうとした話を毎回されると笑う。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:37:48〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=5868s"]]}, {"cat": "暮らし", "t": "口ぐせは「アイト」", "b": "口ぐせの「アイト（オーライ）」はTシャツにもなっており、「アイトと言って、欲しいものは取りに行く」を信条にしてきたという。息子のフラッグフットボールのチームでも、子どもたちと「アイト」の掛け合いをしているそうだ。ストリートバスケで育った負けず嫌いだとも話す。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-dR0VEwR_ifo", "src": [["公式YouTube（1:42:49〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=6169s"]]}]);
  if (PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"].facts.push({"cat": "暮らし", "t": "母の入院時にすぐ電話をくれた", "b": "母が危篤だと連絡を受けて動揺し電話したところ、すべてを置いてすぐに折り返し、気にかけてくれたと、ロイス・キーズが話している。当時は自身の娘が生後1か月ほどだったはずだという。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で、ロイス・キーズの話（公式字幕を全文確認）", "src": [["公式YouTube（51:45〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=3105s"]], "by": "第三者の話"});
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "「ニータのために」と声をかけた", "b": "母を亡くした1か月後に対戦した際、「今夜はお母さんが最前列で見ている」と励まし、試合後には母の愛称を出して「これはニータのためだ」と声をかけてくれたと、ロイス・キーズが話している。", "sp": "ロイス・キーズ", "d": "2026-02-19", "how": "ステファニーの番組で、ロイス・キーズの話（公式字幕を全文確認）", "src": [["公式YouTube（51:45〜）", "https://www.youtube.com/watch?v=dR0VEwR_ifo&t=3105s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-dR0VEwR_ifo", d: "2026-02-19", show: "wys", who: ["Royce Keys"], t: "ロイス・キーズの回　ビッグママに育てられた少年と「ヴィックスとホット・トディ」", lead: "ステファニー・マクマホンの番組に出た約107分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Royce Keys"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-dR0VEwR_ifo").map((x) => [x.t, x.b, x.sp])), open: ["終盤（1:37:02付近）で父親について触れる一言があるが、別の箇所では父は健在と語っており、字幕の聞き取りも含め確認できないため載せていない。", "祖母が空に向けて発砲した話や、兄が亡くなった場面の詳しい描写は、要点のみ、または省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=dR0VEwR_ifo"]] });
