  if (!PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Rey%20Mysterio"]], moves: [], facts: [] };
  if (PROFILES["Rey Mysterio"].lead === "") PROFILES["Rey Mysterio"]._weak = 1;
  PROFILES["Rey Mysterio"].facts.push(...[{"cat": "リングの話", "t": "殿堂入りの夜のマスクが一番のお気に入り", "b": "レイ・ミステリオは、殿堂入りの式典で着けたマスクを自分の最高傑作に挙げている。大阪から駆けつけた専属デザイナーが、開始の約1時間前に贈ってくれたものだという。素材が硬く、ヘルメットのような作りなのに、かぶるとぴったり合ったと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（3:07〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=187s"]]}, {"cat": "リングの話", "t": "ボタンが外れ続けたWM21のマスク", "b": "年間最大の祭典の21回目で、エディ・ゲレロとオープニングを務めたときの衣装を振り返っている。タトゥーを模したデザインで格好よかったが、下のボタンが外れ続け、試合中ずっと直していたそうだ。ブーツのひもとマスクを同時に直しながら、エディの足を引っぱらないよう必死だったという。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（10:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=615s"]]}, {"cat": "リングの話", "t": "アメリカ流の試合運びはディーンに教わった", "b": "WCWに入った頃のレイ・ミステリオは、アメリカ流の試合づくりを先輩に導かれて学んでいたと話す。最初に教えてくれたのがディーン・マレンコで、組み立ての考え方を学んだという。意見や助言は経験の長短を問わず聞く姿勢だと語っている。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（21:17〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1277s"]]}, {"cat": "リングの話", "t": "初めてのWCW戦はいきなり大会の第1試合", "b": "WCWでの最初の試合を、前座の試し合いだと思い込んでいたらしい。実際は有料中継の第1試合で、相手はディーン・マレンコ。焦ったものの、研究して臨むと相手との呼吸がすぐ合ったそうだ。この経験が、のちのクルト・アングル戦などへの自信になったと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（22:58〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1378s"]]}, {"cat": "リングの話", "t": "メキシコでは1対1の経験が少なかった", "b": "メキシコでは3対3などの形式が多く、1対1は王座戦や賭け試合くらいだったという。相性がよかった相手はサイコシス、ジュベントゥード・ゲレラ、ヘビー・メタルくらいだったと振り返る。WCWで1対1が中心になり、相手を信頼する自信が育ったそうだ。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（26:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1575s"]]}, {"cat": "リングの話", "t": "ルチャは昔のまま、変わったのは3本勝負だけ", "b": "ルチャ・リブレの本質も、マスクの意味も20〜30年前と変わらないと、レイ・ミステリオは話す。メキシコ側で変わったのは、3本勝負をやめて1本勝負にしてきた点だという。アメリカのファンは、まだ見ていない新しい世代を見たがっているとも語っている。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（34:08〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=2048s"]]}, {"cat": "リングの話", "t": "若手には「やりすぎず、筋を通せ」と助言する", "b": "昔は無茶な技を連発していた自分が、若手に「多くをやらず、やることに筋を通せ」と言うことについて、時代遅れかもしれないと迷うと話す。けれど、相手を守りたい気持ちと、長く活躍してほしいという思いからの助言だそうだ。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（39:53〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=2393s"]]}, {"cat": "リングの話", "t": "NWOの控室襲撃で、ケビン・ナッシュに飛びかかった", "b": "有名な控室襲撃の場面で、トレーラーに投げつけられた記憶を語っている。トレーラーから出てきて柵に飛び乗り、ナッシュをクロスボディで倒そうとしたが、当然うまくいかなかったと笑う。あの場面は時代を象徴する出来事の一つだと受け止めている。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:06:42〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4002s"]]}, {"cat": "リングの話", "t": "ヒールは土台役、ベビーフェイスの10倍難しい", "b": "相手を担いで技を見せる「土台」の役目を、コーディとの試合で学んだと話す。ヒールは相手を支え、位置を合わせ、必要なら調整する立場なので、ベビーフェイスの10倍難しいというのが持論だそうだ。ハロウィン・ハボック97のエディ戦も、受け止められてこそ成り立った動きだと語る。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:21:52〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4912s"]]}, {"cat": "リングの話", "t": "前夜の試合後にジョンから学んだ", "b": "レイ・ミステリオは、ジョンやシェイマスとの試合の後に、ジョンから助言をもらったと話す。試合では、新しいことだけでなく、昔からあるのに自分の仕事にまだ取り入れていないことからも学べるという。知っているつもりになるのが一番まちがいだと語っている。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:26:44〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5204s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Rey Mysterio")) ROSTER.push(["レイ・ミステリオ", "Rey Mysterio", "lg", "殿堂入りの覆面レスラー", "", "", ""]);
  if (!PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"] = { lead: "7歳で叔父の教室に入り、恩人コナンに導かれて世界へ出た覆面レスラー。普段は一人でこもりがちだといい、娘のリング挑戦や息子ドミニクの成長を父として見守っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Rey%20Mysterio"]], moves: [], facts: [] };
  if (PROFILES["Rey Mysterio"]._weak) { PROFILES["Rey Mysterio"].lead = "7歳で叔父の教室に入り、恩人コナンに導かれて世界へ出た覆面レスラー。普段は一人でこもりがちだといい、娘のリング挑戦や息子ドミニクの成長を父として見守っている。"; delete PROFILES["Rey Mysterio"]._weak; }
  PROFILES["Rey Mysterio"].facts.push(...[{"cat": "好きなもの", "t": "いちばん好きなのは殿堂入り式典のマスク", "b": "数あるマスクの中でいちばん気に入っているのは、殿堂入り式典でかぶったものだという。専属デザイナーのハヤシが大阪から飛んできて、式典の1時間ほど前に会場で手渡してくれたそうだ。いつもの布地と違いヘルメットのように硬く、かぶれるか不安だったが、すっと収まり「最高にかっこいい」と思ったと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（2:22〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=142s"]]}, {"cat": "リングに来るまで", "t": "採寸なしで衣装を作った大阪のファン", "b": "ハヤシとは1996年の初来日のときに出会ったという。テレビで見ていただけで採寸もせずに衣装とマスク2枚を作ってきて、試合で使ったマスクを譲ってほしいと頼まれたそうだ。着てみると驚くほどぴったりだったと話す。そこから30年近い付き合いになり、最初のコスチュームやレッスルマニアの衣装も数多く手がけてもらっているという。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（3:57〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=237s"]]}, {"cat": "好きなもの", "t": "手こずったのはラテックスのマスク", "b": "逆に苦労したのは、エディ・ゲレロと戦ったレッスルマニア21のマスクだという。ハヤシが初めてラテックス素材で作ったもので、見た目は気に入っていたが、下の留め具が何度も外れたそうだ。試合中ずっと直しながら戦っていて、今の年齢なら慌ててしまうだろうと笑う。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（10:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=615s"]]}, {"cat": "リングに来るまで", "t": "当時はエディよりアート・バーと親しかった", "b": "若いころは、なぜかエディよりもアート・バーとのほうが気が合ったという。SNSもなく、口コミとビデオが頼りの時代だったと振り返る。早くに亡くなったが、生きていればエディが頂点に立ったとき、その隣にいたはずだと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（13:25〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=805s"]]}, {"cat": "リングに来るまで", "t": "米国流を教えたのはディーン・マレンコ", "b": "WCWに来たころは、何でも速くて場外カウントもないメキシコの戦い方からの切り替えを周りに導いてもらったという。最初にアメリカ流の組み立てを教えてくれたのがディーン・マレンコだったそうだ。WCWの初試合は大会前の試しの試合だと思っていたら、大会の第1試合だと分かって慌てたと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（21:17〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1277s"]]}, {"cat": "リングに来るまで", "t": "メキシコではシングル戦が珍しかった", "b": "メキシコでは3対3などの多人数戦が中心で、一騎打ちはタイトルやマスクを懸けた試合くらいだったという。特に手が合ったのはサイコシス、フベントゥ・ゲレーラ、ネグロ・カサスの弟ヘビー・メタルだったそうだ。WCWでシングル戦が中心になり、一対一で相手を信頼する自信がついたと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（26:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1575s"]]}, {"cat": "リングに来るまで", "t": "扉を開いてくれた恩人はコナン", "b": "自分がここにいるのは、初めてメキシコへ行く機会をくれたコナンのおかげだという。コナンは移る先々に自分を連れていき、ECWやWCWにも一緒に入ったそうだ。自分では気づけなかったものを見いだし、今の自分を形づくってくれたと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（54:33〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=3273s"]]}, {"cat": "家族", "t": "息子を見て父ダスティの気持ちを知る", "b": "コーディの父がこっそり写真を撮っていた話を受けて、今は息子ドミニクの成長をそばで見られることが不思議で現実離れしていると話す。選手としてまだ現場にいるからこそ、当時のダスティの誇らしさが分かるようになったという。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（56:58〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=3418s"]]}, {"cat": "暮らし", "t": "毎朝の冷水浴で一日を始める", "b": "毎朝起きると、部屋の外にある冷水浴に入るのが日課だという。水温は華氏39度（約4℃）で、3分ほど浸かるそうだ。気分が乗ればもう少し長く入るが、たいていは3分で出ると話す。これが頭を冴えさせ、一日を始める支えになっているという。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:00:06〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=3606s"]]}, {"cat": "暮らし", "t": "人への接し方は家庭で身につく", "b": "プロレスは自分が愛し、唯一できることで、妻と出会い子どもを持てたのもこの仕事のおかげだという。年上にも年下にも、自分がされたいように接してきたそうだ。それは親の育て方から来るもので、今は自分の子どもたちを見ていてもそう感じると話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:03:20〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=3800s"]]}, {"cat": "暮らし", "t": "リングを離れると一人にこもりがち", "b": "プロレスから離れているときは、一人で閉じこもることが多いという。それに気づいているのは妻と娘、ときどき息子くらいだそうだ。会場では仲間に囲まれて息が詰まるほどだが、それが好きなのだと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:05:57〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=3957s"]]}, {"cat": "家族", "t": "4人きょうだいの末っ子", "b": "自分は4人きょうだいの末っ子だという。コーディが兄への感謝を伝えられないと話したのを受けて、自分も同じで、きょうだいに直接気持ちを伝えるのは苦手だと打ち明けた。他人には言えるのに本人には言えない、と話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:10:39〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4239s"]]}, {"cat": "リングに来るまで", "t": "7〜8歳で叔父の教室に入る", "b": "練習を始めたのは7〜8歳のころで、叔父が講師の一人だった教室に特別に入れてもらったという。次に若い生徒でも16〜17歳だったそうだ。叔父は機会があれば容赦なく自分を鍛えたが、今はそれでよかったと話す。プロレスを好きになったのも、そばで見て育った叔父のおかげだという。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:13:04〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4384s"]]}, {"cat": "家族", "t": "大学を出た娘アリーヤが初めてリングへ", "b": "娘のアリーヤには1年半〜2年前から「リングに上がってみたい」と言われ、卒業してからと先延ばしにしていたという。6月にカリフォルニア大学サンディエゴ校で人間生物学を修めて卒業すると、すぐ約束を迫られたそうだ。けがからの復帰直前に育成施設へ行く際、妻アンジーと3人で向かい、初めてなのに位置取りやロープワークが自然で驚いたと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:14:34〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4474s"]]}, {"cat": "家族", "t": "次は1週間の練習で見極め", "b": "同じ日にTJとナタリヤの道場「ダンジョン」でも体験し、娘は「すごく楽しかった」と言ったという。ロープも受け身も痛いので嫌がるだろうと思っていたが、逆だったそうだ。次は1週間毎日の練習をやり通せるか試すつもりで、怖さとわくわくが半々だと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:16:09〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4569s"]]}, {"cat": "家族", "t": "妻は息子を悪役向きと見ていた", "b": "息子はいつか自分とは違う形で、自分より大きくなると心の奥で思っていたという。妻は以前から、もし息子がレスラーになるなら悪役だと言っていたそうだ。巡業で家を空けていた自分より妻のほうがずっと一緒にいたので、自分が今見ている一面を知っていたのだろうと話す。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:29:56〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5396s"]]}, {"cat": "好きなもの", "t": "ハスキーを取り戻せなかった", "b": "以前飼っていたハスキーには悲しい経緯があるという。世話を頼んでいた人が事故で急に亡くなり、引き取りに行ってもその妻が返してくれなかったそうだ。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:35:34〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5734s"]]}, {"cat": "好きなもの", "t": "夢のチームは愛犬2匹とコナン", "b": "一緒に戦う夢のチームには、サンディエゴで飼っていた犬のキャリーとエリーを連れていきたいという。今はエリーは娘のもと、キャリーは息子のもとで暮らしているそうだ。あとは何があっても支えてくれた右腕のコナン（Kドッグ）がいれば十分で、「犬3匹のチーム」だと笑う。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:36:24〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5784s"]]}]);
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "19歳でプロレスを志した", "b": "子どものころはプロレスが好きだったが、ほかの子と同じように一度離れ、フットボールなどに打ち込んでいたという。19歳になって、ほかにやりたいことが見つからず「プロレスでやれるか試したい」と言い出したそうだ。親に勧められたのではなく、自分でつかみ取ったと、父レイが話している。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で、レイ・ミステリオの話（公式字幕を全文確認）", "src": [["公式YouTube（1:33:05〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5585s"]], "by": "第三者の話"});
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "首のタトゥーは大叔父のマスク", "b": "父が首にタトゥーを入れると話すのを聞いて、先に自分が入れてしまったという。図柄は父の叔父が最初にデザインして着けたマスクで、父がプロレスを好きになるきっかけになった人への敬意が込められていると、父レイが話している。", "sp": "レイ・ミステリオ", "d": "2026-02-19", "how": "コーディの番組で、レイ・ミステリオの話（公式字幕を全文確認）", "src": [["公式YouTube（1:33:55〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=5635s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "家族", "t": "父がブラックベリーで撮った1枚", "b": "レイと戦った初のシングル戦のあと、廊下の先で父ダスティが2人の話す姿を携帯でそっと撮っていたという。機械に疎い父が唯一使いこなせた操作だったそうだ。あれは父自身のための1枚だったと分かっていた、と話す。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（17:21〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=1041s"]]}, {"cat": "家族", "t": "妻ブランディに注意された片言英語", "b": "妻ブランディと日本に行ったとき、飯伏幸太と片言の英語で打ち合わせるのを聞かれ、失礼だと注意されたという。自分は「みんなこうやって通じ合っている」と説明したそうだ。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（43:05〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=2585s"]]}, {"cat": "リングに来るまで", "t": "7歳で表舞台のプロレスに夢中に", "b": "7歳のとき、会場でブラッド・アームストロングのアームドラッグに観客が沸くのを見て、裏側より表のリングに興味が移ったという。家にはビデオが山ほどあり、土曜夜のWCWを見て育ったそうだ。レンタル店で借りたビデオで、初めてWWEの大会を知ったと話す。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:09:04〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4144s"]]}, {"cat": "家族", "t": "兄ダスティンに感謝を言えない", "b": "地元の会場で、女性ファンが熱狂する若き兄ダスティンを見ていたという。兄は基本がしっかりして自分よりずっとうまかったが、その大切さを本人に伝えるのがとても苦手だそうだ。セラピーで時間をかけて話せるほどのことだと笑う。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:09:50〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4190s"]]}, {"cat": "リングに来るまで", "t": "家族がやっていないアマレスを選ぶ", "b": "最初はアマチュアレスリングを始め、プロとの違いを知らずに入ったものの、すっかり好きになったという。父も兄も経験がなかったので、自分だけのものを持ちたかったそうだ。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:12:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4335s"]]}, {"cat": "家族", "t": "父とリングで組んだのは2度だけ", "b": "14歳ごろ、父の興行のリングでロープワークをしていたが、受け身は禁じられていたという。父とリングで向き合ったのは2度だけで、突っ込んだところをボディスラムとヒップトスで強く投げられたそうだ。「そんなに楽しいものじゃない」と見せたかったのだろうと話す。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:12:15〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4335s"]]}, {"cat": "リングに来るまで", "t": "15歳の夏、父が席を外すと始まる特訓", "b": "15歳の夏に本格的に練習していたころ、試合は禁止だったという。父が「事務所に行く」と出ていくと、先輩たちが自分を角に追い込んで鍛え始めたそうだ。父はきっと分かっていたと思うと話し、これで病みつきになり高校どころではなくなったという。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:13:49〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4429s"]]}, {"cat": "リングに来るまで", "t": "デビュー戦は教会の中", "b": "初めての試合は20歳のとき、観客20人ほどの教会の中だったという。初戦にしてはできすぎていて、のちのミズが控室で「あいつは経験者だ」と怒ったそうだ。ミズには今もその話をされると笑う。", "sp": "コーディ・ローデス", "d": "2026-02-19", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-ffMbVFSaSyo", "src": [["公式YouTube（1:18:41〜）", "https://www.youtube.com/watch?v=ffMbVFSaSyo&t=4721s"]]}]);
  ARTICLES.push({ id: "wdywta-ffMbVFSaSyo", d: "2026-02-19", show: "wdywta", who: ["Rey Mysterio", "Cody Rhodes"], t: "レイ・ミステリオの回　叔父から始まった覆面人生と、リングに立つ娘と息子", lead: "コーディ・ローデスの番組に出た約99分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Rey Mysterio", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-ffMbVFSaSyo").map((x) => [x.t, x.b, x.sp])), open: ["字幕の1:06台後半〜1:09前後が欠けており、その区間の話は確認できていない。", "殿堂入り後の目標やAAAへの関わりの話、技の受けや組み立ての話は、意気込みや試合の話として省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=ffMbVFSaSyo"]] });
