  if (!PROFILES["Gunther"]) PROFILES["Gunther"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Gunther"]], moves: [], facts: [] };
  if (PROFILES["Gunther"].lead === "") PROFILES["Gunther"]._weak = 1;
  PROFILES["Gunther"].facts.push(...[{"cat": "リングの話", "t": "シナ引退試合の日は、WrestleManiaより張り詰めていた", "b": "グンターは、ジョン・シナの引退試合の日は楽屋の空気がWrestleManiaより濃く感じられたと話す。自分は若い頃にWWEをあまり追っていなかったので、シナの歴史を同じ重みで経験してはいないという。それでも周りが感情的になる中で、場の空気を逆転させる役を担えたのは自分にとって良いことだったそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（3:56〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=236s"]]}, {"cat": "リングの話", "t": "キャリア最大の舞台で、重圧をむしろ楽しんだ", "b": "あの一戦は自分のキャリアで最大の出来事で、会場全体に影響を与えている実感があったとグンターは振り返る。「重い」という表現がぴったりだったという。単調な仕事はすぐ飽きる性分なので、責任の大きい場面ほど好きだと話し、そうした節目が自分を変えていくのだと語る。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（6:25〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=385s"]]}, {"cat": "リングの話", "t": "目標は「引き受ける責任を大きくすること」", "b": "グンターは、勝ちたい王座の一覧のようなものは昔から持っていないという。難しい状況をこなせたら、次はさらに難しいことを、というふうに任される責任を広げていくのが原動力だそうだ。それが結果として王座や大一番につながるのだと考えている。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（16:00〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=960s"]]}, {"cat": "リングの話", "t": "ロイヤルランブル最長記録は、終盤の時間が生んだ", "b": "グンターは、自分が持つロイヤルランブルの最長出場記録について、記録を狙ったことは一度もなかったと話す。当時はまだ新参で、周りには長くしすぎるなと言われたという。だが復帰してきた主役が登場してすぐ終わっては何も乗り越えていないことになる、と考え、終盤にたっぷり時間を取る形にしたそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（27:49〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1669s"]]}, {"cat": "リングの話", "t": "ファンへのチョップは、頼まれても絶対にやらない", "b": "チョップはヨーロッパの小さな体育館で、いちばん確実に歓声を呼ぶ技だったとグンターは話す。取材などで「やって」と頼まれることは多いが、やらないと決めているという。インディーには数ポンド払えばチョップしてもらえる催しがあるが、長年の修行で身につけた技をファンサービスで遊びに使うのは違うと感じるそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（31:48〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1908s"]]}, {"cat": "リングの話", "t": "「悪い外国人」の型にはまりたくない", "b": "グンターは、自分を「悪い外国人」の悪役として語られるのが少し嫌だと話す。デビューの頃はトランクスに国旗を付けさせられそうになったが、早めに外したという。今は国より人柄で見られる時代だと考えているそうだ。ただ、今も外国人という見られ方が残る場面はあるという。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（33:25〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2005s"]]}, {"cat": "リングの話", "t": "故郷ウィーンの大会で、観客を倍近くに増やした", "b": "グンターは、地元ウィーンでの前回の大会で、前に出た興行から観客がほぼ倍になり、市の大会場が満員になったことが誇らしかったと話す。いつかあの会場で試合をするのが目標というより夢だったそうだ。地元紙の記者も昔からの調子で大きく書いてくれて、うれしかったという。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（35:46〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2146s"]]}, {"cat": "リングの話", "t": "目指すのは頂点で全員と名勝負をする立場", "b": "グンターは、これからの目標は、ローマン・レインズやブロック・レスナーのような長く上にいる立場に入ることだと話す。そこでイルジャ・ドラグノフやブロン・ブレイカー、オバ・フェミら、次の世代と素晴らしい試合をしたいのだそうだ。ファンや取材への対応に追われる「看板」役は自分には向かないと語る。レスラーは互いが必要で、皆が自分のようだったら目立たないとも話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:09:39〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=4179s"]]}, {"cat": "リングの話", "t": "WrestleManiaでのジェイとの結末も、受け入れている", "b": "ジェイ・ウーソとの一戦について、グンターは、終わったことは終わったこととして、プライドを飲み込めるタイプだと話す。観客がそれを弱さと受け取ったとしても構わないという。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:12:58〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=4378s"]]}, {"cat": "リングの話", "t": "実況の「プロレスがスポーツエンターテインメントに勝った」に確証を得た", "b": "マイケル・コールが実況で、プロレスはスポーツエンターテインメントに勝ったという趣旨の言葉を口にしたことを、グンターは聞いていたという。WWEに来る前の自分たちの集団は、まさにスポーツエンターテインメントに対抗するという旗印だったので、大きな「確認」になったと話す。冗談めかして、自分だけがプロレスラーだとも笑っている。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:14:34〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=4474s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Gunther")) ROSTER.push(["グンター", "Gunther", "lg", "ウィーン出身の元世界王者", "", "", ""]);
  if (!PROFILES["Gunther"]) PROFILES["Gunther"] = { lead: "ウィーンの労働者街で育ち、少年時代はサッカーのゴールキーパーだったという。小橋建太やスタン・ハンセンに憧れ、腕時計へのこだわりや大幅な減量の話からも、飾らない素顔がのぞく。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Gunther"]], moves: [], facts: [] };
  if (PROFILES["Gunther"]._weak) { PROFILES["Gunther"].lead = "ウィーンの労働者街で育ち、少年時代はサッカーのゴールキーパーだったという。小橋建太やスタン・ハンセンに憧れ、腕時計へのこだわりや大幅な減量の話からも、飾らない素顔がのぞく。"; delete PROFILES["Gunther"]._weak; }
  PROFILES["Gunther"].facts.push(...[{"cat": "好きなもの", "t": "若い頃はWWEより日本とインディー", "b": "自分がレスラーとして歩み出した頃はWWEの熱心なファンではなく、18〜20代前半は日本のプロレスやインディーばかり見ていたという。だからジョン・シナにまつわる名場面も、リアルタイムで体験したわけではなく結果を読んでいた程度だそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（3:56〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=236s"]]}, {"cat": "暮らし", "t": "単調な仕事にはすぐ飽きる性格", "b": "人生全般で、決まりきった作業にはすぐ退屈してしまう性格だという。以前の仕事でも、任されたことを覚えたら次は何だと考えていたそうだ。だから責任の重い場面が好きで、より難しいことを任される立場へ成長し続けたいのが原動力だと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（7:12〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=432s"]]}, {"cat": "好きなもの", "t": "腕時計はロレックスのGMT", "b": "収録の日に着けていたのはロレックスのGMTマスターIIのローズゴールドだという。大一番の当日はジュビリーブレスのイエローゴールドを着けていたそうだ。若い頃は何も買えなかったので、今は恵まれた分を少し楽しみたいが、ほどほどにしないとと笑う。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（9:32〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=572s"]]}, {"cat": "家族", "t": "ウィーン11区の労働者街で育つ", "b": "育ったのはウィーンの11区、ジンメリングと呼ばれる地区だという。ウィーンは区を番号で呼ぶのがふつうで、11区はブルーカラーの多い地域だそうだ。貧しかったわけではないが、若い頃は欲しいものを買う余裕がなかったと振り返る。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（10:23〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=623s"]]}, {"cat": "リングに来るまで", "t": "原体験はオットー・ワンツの大会", "b": "子どもの頃のWWEはビデオテープの中だけの存在で、最初に触れたプロレスは地元の大物オットー・ワンツが開いていたトーナメントだったという。夏のアイススケート場に屋根付きのリングを置いた野外興行で、その独特の雰囲気が今も心に残っているそうだ。WWEのビデオは友達が持っていたが、手に入れるのは難しかったと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（11:11〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=671s"]]}, {"cat": "リングに来るまで", "t": "17歳で練習開始、夢は「プロとして食べる」", "b": "トレーニングを始めたのは2005年、17歳のときだという。ウィーンの少年にとってWWEは遠すぎて現実的な目標ではなく、当時の大きな夢は仕事を辞めてプロレス一本で生活することだったそうだ。周りの先輩たちもかろうじて食べていける程度で、広い可能性は見えていなかったと振り返る。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（12:44〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=764s"]]}, {"cat": "リングに来るまで", "t": "PWGで初めてのカリフォルニア", "b": "アメリカの団体PWGへの参戦が、ほぼ初めてのカリフォルニア体験だったという。ロサンゼルスでの観光らしいことはベニスのゴールドジムに行ったくらいで、ハリウッドには一度も行ったことがないそうだ。空港から車で会場へ運ばれる道中も含め、ちょっとした冒険のようで楽しかったと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（23:55〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1435s"]]}, {"cat": "好きなもの", "t": "チョップの原点は小橋建太", "b": "ずっと小橋建太のファンで、チョップはそこから来ているという。ヨーロッパ時代は観客100人ほどの小さな体育館で試合をすることが多く、いい音のチョップは他のどんな技より反応を呼んだそうだ。単純な道具で大きな反応を引き出すのが好きだと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（30:05〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1805s"]]}, {"cat": "リングに来るまで", "t": "地元の大ホールで戦うのが夢だった", "b": "ウィーンのシュタットハレでいつか試合をすることを、目標というより夢として描いていたという。前回の地元大会では観客がほぼ倍になり満員になったのがとても誇らしかったそうだ。オットー・ワンツの時代から書き続けている地元紙の記者が、今も古い言い回しで大きく報じてくれるのも楽しみだと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（35:46〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2146s"]]}, {"cat": "暮らし", "t": "オーストリア流は「コーヒーよりビール」", "b": "ドイツにも長く住んでいたが、ドイツの人は倹約家で楽しむのが少し下手だと感じたという。一方オーストリア人は、手持ちがいくらでも出かけて楽しむ気質だそうだ。友達と会うならコーヒーではなくビールを何杯か、というのが今も変わらない古いスタイルだと笑う。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（39:04〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2344s"]]}, {"cat": "リングに来るまで", "t": "恩人は物流会社の上司", "b": "自分を最も形づくった一人は、かつて勤めた物流会社の上司だったという。下の階層ながら数人の部下を持つ管理職で、何度か相談に乗ってもらったそうだ。人を預かる責任や人との接し方は、プロレスの世界でもそのまま役立っていると話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（42:30〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2550s"]]}, {"cat": "家族", "t": "妻も元レスラー、いつも応援してくれる", "b": "いま一番よく話す相手は親友と妻だという。妻のジニーも自らリングに上がっていた人で、競技をやめざるを得なかったが、恨むことなく夫の仕事を心から応援してくれるそうだ。家族はイングランドにいて1か月会えない時期でも、聞こえてくるのは励ましばかりで、家庭が支えてくれることが大きいと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（43:18〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2598s"]]}, {"cat": "体のこと", "t": "300ポンドから約240ポンドへ減量", "b": "一番重い時期は300ポンド（約136キロ）を軽く超えていたが、今はおよそ240ポンド（約109キロ）を保っているという。動きもスタミナも問題はなかったが、テレビに出るならそのほうが良いと判断したそうだ。先に減量した親友に「次はお前だ」と背中を押されたのもきっかけだと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（45:36〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2736s"]]}, {"cat": "体のこと", "t": "体づくりの「ちょうどいい所」は難しい", "b": "厳しい食事制限の時期は、1日5食とトレーニングに生活のすべてを合わせる視野の狭い状態になり、自分もいつも作り置きの食事を持ち歩いていたという。鏡を見るたびにまだ足りないと思ってしまい、自分の適正点を判断するのは難しいそうだ。ボディビルダーでも仕上げるのは年に一度なのに、一年中仕上げ続けるのは現実的ではないと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（48:03〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2883s"]]}, {"cat": "リングに来るまで", "t": "6歳から16歳までサッカーのGK", "b": "子どもの頃に最初に打ち込んだのはサッカーで、6歳ごろから16歳ごろまでゴールキーパーをしていたという。ヨーロッパではサッカーこそが一番のスポーツで、当時の大きな情熱だったそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（53:44〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3224s"]]}, {"cat": "家族", "t": "母はサッカー経験者で今はコーチ", "b": "母親も自らサッカーをしていた人で、今は子どもの女子チームのコーチをしているという。両親は最初こそプロレスの道を心配していたが、今はとても喜んでくれていると話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（53:44〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3224s"]]}, {"cat": "家族", "t": "祖母は今も「引退後の稼ぎ」を心配", "b": "父方の祖母は家業の中で育った人で、仕事とはそういうものだと考えているため、今でも「やめた後はどうやって稼ぐの」と聞いてくるという。ロンドンのフォーシーズンズで挙げた結婚式では「宝くじでも当たったの」と言われたそうで、本人も笑いながら説明のしようがないと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（54:37〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3277s"]]}, {"cat": "好きなもの", "t": "憧れの一人は全日本のハンセン", "b": "一人挙げるなら憧れはスタン・ハンセンで、見ていたのは日本でのハンセンだけだという。皆が静かに入場する中、ブロディとともに暴れ込んで場をかき乱す姿に惹かれ、自分の「かき回す」スタイルの着想もそこにあるかもしれないと話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（59:19〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3559s"]]}, {"cat": "暮らし", "t": "褒めるのも褒められるのも苦手", "b": "何も言われなければ良し、言われるのは悪いことだけという文化の中で育ったため、人を褒めるのも褒められるのも今でも苦手だという。率直さは物事を早く進める利点がある一方、アメリカでは直接的すぎたかもしれないと感じたこともあるそうだ。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:04:02〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3842s"]]}, {"cat": "リングに来るまで", "t": "欧州団体の運営にも関わっていた", "b": "ドイツの団体wXwにいた頃は、年に100大会近くを開き、人も雇う規模になっていて、運営を磨こうとしていた時期だったという。そこへ参戦したコーディをつかまえ、WWEではどう回しているのかを細かく教えてもらったそうで、今もそのことに感謝していると話す。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:05:43〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3943s"]]}, {"cat": "好きなもの", "t": "夢の5人チームは小橋やフィンレー", "b": "自分を含めた5人の夢のチームには、親友のルドウィグ・カイザー、イリヤ・ドラグノフ、小橋建太を選んだという。最後はスタン・ハンセンも考えたが、大きい選手は自分で足りているとして、フィット・フィンレーを入れたそうだ。試合の後に飲みに行くのにもいいチームだと笑う。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:16:10〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=4570s"]]}]);
  if (PROFILES["Ludwig Kaiser"]) PROFILES["Ludwig Kaiser"].facts.push({"cat": "暮らし", "t": "親友グンターの良き相談役", "b": "社内で心を許す相談相手はほとんどいないが、親友のカイザー（マルセル）は物事を客観的に見せてくれる存在だと、グンターが話している。カイザーは自分より3年ほど早く海を渡り、すでに7〜8年のキャリアがありながら育成施設で受け身から学び直したそうで、そのプライドを飲み込んだ姿勢を尊敬しているという。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で、グンターの話（公式字幕を全文確認）", "src": [["公式YouTube（17:39〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1059s"]], "by": "第三者の話"});
  if (PROFILES["Ludwig Kaiser"]) PROFILES["Ludwig Kaiser"].facts.push({"cat": "暮らし", "t": "語学に長け、役者の才能もある", "b": "カイザーは過小評価されがちだがカリスマがあり、話もうまいと、グンターが話している。語学の才能もあり、いつかハリウッドに行くべきだ、舞台俳優になっていてもすごかったはずだと本人によく言っているそうだ。減量もカイザーが先に始め、もともと太りにくい体質を乗り越えて体を作ってきたという。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で、グンターの話（公式字幕を全文確認）", "src": [["公式YouTube（19:12〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1152s"]], "by": "第三者の話"});
  if (PROFILES["Antonio Inoki"]) PROFILES["Antonio Inoki"].facts.push({"cat": "暮らし", "t": "タバスコを日本に広めたという説", "b": "アントニオ猪木がタバスコを日本に持ち込んだ人物だという話を、いろいろな人から何度も聞いたと、グンターが話している。本当かどうかは分からないと前置きしつつ、商売として売り広めたらしいと紹介している。", "sp": "グンター", "d": "2026-03-05", "how": "コーディの番組で、グンターの話（公式字幕を全文確認）", "src": [["公式YouTube（1:00:56〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3656s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "若手時代はシナの運転手役", "b": "若手の頃はハウスショーのたびにジョン・シナを車に乗せて回っていたという。自分は前半の試合に出る一レスラーだったが、まるでロックスターを送り迎えしているような気分だったそうだ。当時はトップと他の差がはっきりしていた時代だったと振り返る。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（4:47〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=287s"]]}, {"cat": "暮らし", "t": "育成時代の街で「自分は変わったか」", "b": "仕事でケンタッキー州ルイビルに降り立ったとき、育成時代を過ごしたその街を窓から眺めながら、自分は当時と同じ人間のままかと自問したという。答えが「同じ」だったら嫌だと思ったそうだ。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（8:45〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=525s"]]}, {"cat": "体のこと", "t": "胸のけがからの復帰戦で目が覚めた", "b": "けがから戻ってきた試合で、胸を痛めていた状態のままグンターの強烈なチョップを受け、かえって気持ちに火がついたという。笑われるかもしれないが、自分のプロレスは本物であってほしいと話す。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（29:20〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=1760s"]]}, {"cat": "暮らし", "t": "巡業先のジムで仲間を探してしまう", "b": "巡業中に用意された地元のジムへ行き、誰もいないと「皆どこにいるんだ」と思ってしまう、細かくて口うるさい性分だという。ブロン・ブレイカーやLAナイトはいつもジムにいると名前を挙げている。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（45:36〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=2736s"]]}, {"cat": "体のこと", "t": "体づくりの手本は2枚の写真", "b": "体を絞るときに見る写真が2枚あり、1枚は年間最大の祭典18回大会のトリプルH、もう1枚は映画『ロッキー3』で頬骨が浮き出るほど絞ったスタローンだという。「アスリート体型」という言い方は好きではないと話す。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（51:25〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3085s"]]}, {"cat": "家族", "t": "母をファーストクラスで招いたら", "b": "イギリスでの大会に母を招き、ファーストクラスや空港の出迎えなど自分と同じ旅を味わってもらったという。母は楽しんでいるように見えたが、帰国後すぐ姉やブランディに「息子がお金を使いすぎて心配」と話していたそうだ。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（54:37〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3277s"]]}, {"cat": "リングに来るまで", "t": "子どもの頃に猪木と対面", "b": "7〜8歳の頃にアントニオ猪木に会ったことがあるという。あいさつの仕方を教え込まれ、まるで外国の要人に会うかのような敬意を払う場面だったと振り返る。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:00:56〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3656s"]]}, {"cat": "暮らし", "t": "いつかは上院議員に", "b": "政界に進んだ猪木にならい、ジョージア州の上院議員になることは自分の「やりたいことリスト」に入っているという。ジョージア州の議席が空くたびに気にしているそうだ。", "sp": "コーディ・ローデス", "d": "2026-03-05", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-4-DZRqB-IWU", "src": [["公式YouTube（1:02:29〜）", "https://www.youtube.com/watch?v=4-DZRqB-IWU&t=3749s"]]}]);
  ARTICLES.push({ id: "wdywta-4-DZRqB-IWU", d: "2026-03-05", show: "wdywta", who: ["Gunther", "Cody Rhodes"], t: "グンターの回　ウィーン11区の少年がたどった道と、時計・減量・家族の話", lead: "コーディ・ローデスの番組に出た約79分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Gunther", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-4-DZRqB-IWU").map((x) => [x.t, x.b, x.sp])), open: ["ジョン・シナ戦やジェイ・ウーソとの因縁、今後の目標など筋書きに関わる話は載せていない。", "恩人として名前を挙げた物流会社の元上司は一般の方のため、実名は載せていない。", "猪木とタバスコの話は、本人も真偽は分からないと前置きしている。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=4-DZRqB-IWU"]] });
  if (!ROSTER.find((r) => r[1] === "Lola Vice")) ROSTER.push(["ローラ・バイス", "Lola Vice", "lg", "", "", "", ""]);
  if (!PROFILES["Lola Vice"]) PROFILES["Lola Vice"] = { lead: "キューバ系の家に生まれ、3歳から武術を叩き込まれて総合格闘技を経てリングへ。ピンクとダンスを貫く、強さと華やかさを併せ持つ人。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Lola%20Vice"]], moves: [], facts: [] };
  if (PROFILES["Lola Vice"]._weak) { PROFILES["Lola Vice"].lead = "キューバ系の家に生まれ、3歳から武術を叩き込まれて総合格闘技を経てリングへ。ピンクとダンスを貫く、強さと華やかさを併せ持つ人。"; delete PROFILES["Lola Vice"]._weak; }
  PROFILES["Lola Vice"].facts.push(...[{"cat": "リングに来るまで", "t": "ケージで戦いながら大手に見つかる日を待った", "b": "エンターテインメントの道に進みたいと昔から思っていて、見つけてもらえるまでケージで戦い続けると自分に言い聞かせていたという。総合格闘技を離れて約4年、この決断が人生で一番正しかったと話す。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=95s"]]}, {"cat": "家族", "t": "祖父母はキューバから何も持たず移民", "b": "祖父母は何も持たずにアメリカへ移り、孫の世代により良い暮らしを残してくれたと、ローラは話す。キューバ系として会社初の女性という立場を、自分の使命のように感じているそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（2:24〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=144s"]]}, {"cat": "家族", "t": "総合格闘技を続けた理由は母の病気", "b": "ローラは、母親が急性骨髄性白血病と診断され、骨髄移植を受けたことが格闘技を続ける大きな動機だったと話す。母は奇跡的に回復したという。母にもっと良い暮らしをさせたいと誓い、母娘で見ていたダンス番組に出て、母に客席から見てもらうのが夢だったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=192s"]]}, {"cat": "家族", "t": "3人姉妹の長女、家族は全員黒帯", "b": "三姉妹の一番上で、妹たちには自分の夢は自分でかなえ、男性に頼らず経済的に自立するよう伝えてきたと話す。母は黒帯の審査を受けたときローラを妊娠していて、父は世界でも指折りの高段位のヒスパニック系グランドマスターだという。回し蹴りなどの動きは3歳から続けてきたものだそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（4:00〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=240s"]]}, {"cat": "体のこと", "t": "減量で重い摂食障害を経験", "b": "格闘技時代、長年の減量で重い摂食障害になったとローラは明かす。プロレスに入ってからは才能ある女性選手ばかりの環境で自信を失い、しばらく気持ちが沈んだという。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（5:33〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=333s"]]}, {"cat": "体のこと", "t": "幸せは仕事の成功に預けないと学んだ", "b": "成績で自分の価値が決まると思って育ったが、人としての価値と仕事上の価値は別だと気づいたと話す。仕事の外にも幸せを見つけたことで、公私のバランスが取れ、今年はこれまで以上に調子が良いそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（6:23〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=383s"]]}, {"cat": "体のこと", "t": "これまで家族のために生きてきた、この道は自分のため", "b": "今まで何でも人のためにやってきたので、プロレスでの成功は自分自身のためだと決めているとローラは話す。家族のことも背負い続けるが、いつか誰もが知る名前になる人間だと信じているそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（7:09〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=429s"]]}, {"cat": "好きなもの", "t": "試合中の踊りはキューバ風サルサ", "b": "相手を倒して踊るのは、挑発ではなく自分そのものだとローラは話す。踊りはツイークではなくキューバのサルサで、英語に加えてスペイン語も試合に織り交ぜるという。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（8:43〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=523s"]]}, {"cat": "好きなもの", "t": "ピンクとキラキラとダンスが好き", "b": "ピンクやヒールやラメが好きで、ケージの中でも踊っていたと話す。総合格闘技の頃は女らしさを出すことで批判も多かったが、今は女性選手が自分らしくいられる流れになり、少しでも自分が貢献できたなら嬉しいそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（9:28〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=568s"]]}, {"cat": "リングに来るまで", "t": "総合格闘技では何度も断られた", "b": "駆け出しの頃、ピンクを着てヒールで戦うなんて遊びだと言われ、練習を断られ続けたとローラは話す。男性中心の世界で、自分を信じ続けるしかなかったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（10:19〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=619s"]]}, {"cat": "リングの話", "t": "メキシコでの経験が自信につながった", "b": "メキシコの団体が現体制に変わる前の2、3大会を現地で見たローラは、薄い板のようなリングで皆が痛みを抱えて戦う様子を見て、育成施設の環境のありがたさを知ったという。その後、設備も運営も整っていくのを目の前で見られたそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（12:00〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=720s"]]}, {"cat": "リングの話", "t": "ミスター・イグアナとの出会いと初のタイトル", "b": "対抗戦で人気になったミスター・イグアナと一緒にSNS動画を撮ったのが縁で、メキシコでも組むことになったとローラは話す。相手の扱いがひどいのを見て自分が助けると決め、混合タッグ王座を獲得。プロレス人生で初のタイトルになったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（13:41〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=821s"]]}, {"cat": "リングの話", "t": "1万人超の満員の会場で鍛えられた", "b": "メキシコでは毎回1万人、大きな大会では2万人ほどの観客の前に立つのに対し、火曜の収録は500人ほどだとローラは話す。大舞台に慣れたことが将来の本隊昇格の準備になっているという。スペイン語で試合の流れを指示する難しさにも、その場で対応しながら成長したそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（16:05〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=965s"]]}, {"cat": "リングの話", "t": "アンダーテイカーはボスであり師匠", "b": "メキシコの団体の責任者になったアンダーテイカーを、ローラは心から尊敬していると話す。彼がリングで4、5時間も選手に付き合って助言してくれ、自分は彼の指示をスペイン語に訳す役もしているという。そこから他の試合の考え方も学べているそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（17:42〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1062s"]]}, {"cat": "リングの話", "t": "年間最大級の30人戦への出場とキューバ系初の快挙", "b": "昨年は出られなかったので、今年は必ず出ると決めて海外の仕事にも全力で臨んだとローラは話す。出場者が読み上げられ自分の名が呼ばれた瞬間は胸が震え、キューバ系の女性として初めて出る誇りを感じたそうだ。入場すると予想以上の歓声があり、驚いたという。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（20:05〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1205s"]]}, {"cat": "リングの話", "t": "本隊の選手たちが温かく迎えてくれた", "b": "出場時、複数の人気女子選手が自分を目立たせようと気づかってくれたとローラは話す。出番直前に感極まって励ましの言葉をかけ合った選手もいて、将来はそのうちの一人と混合タッグ王座を防衛するのが夢だそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（23:20〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1400s"]]}, {"cat": "リングの話", "t": "夢は年間最大の祭典のメインイベント", "b": "長期的な夢は、マイアミ開催の大会でメインイベントに立つことで、歌手のシャキーラに開幕を飾ってほしいと思っているとローラは話す。当面はメキシコの団体を続けながら、今年中に本隊昇格もしたいそうだ。今年7月で入団から4年になる。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（24:06〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1446s"]]}, {"cat": "リングの話", "t": "思い出の試合は地元近くのタイトルマッチ", "b": "お気に入りに、女性初の地下試合形式の試合や、国際色の強い対抗戦を挙げた。なかでも、育ったフォートローダーデール近くの会場でタイトルに挑んだ試合は、家族全員が見に来て、夢のようだったと話す。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（25:37〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1537s"]]}, {"cat": "リングの話", "t": "王座戦では闘いの顔になる", "b": "普段は陽気に踊っているが、王座がかかると、ケージにいる気持ちで相手を倒しに行くとローラは話す。NXTでは邪魔が入って負けることが多く悔しい思いもしたが、情熱を見せ続けると決めているそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1638s"]]}, {"cat": "リングに来るまで", "t": "入団から4年で別人のように成長", "b": "格闘技の頃とは別人で、大きく成長し成熟したとローラは話す。会社の中での人付き合いも学び、自分の価値を別の形で認められるようになったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（28:06〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1686s"]]}, {"cat": "暮らし", "t": "恋人はダミアン・プリースト", "b": "ローラは、恋人ができたのもこの仕事のおかげだと話す。ダミアン・プリーストとは2年ほど友人で、同じラテン系の背景を持つ彼を昔から尊敬していたという。メインイベントを戦った日に彼が助言してくれ、その後、食事の誘いを受けて関係が始まったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（28:06〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1686s"]]}, {"cat": "暮らし", "t": "マイアミ育ちで、ラテン系の若い子に道を見せたい", "b": "キューバ系でマイアミ育ちの自分が世界の舞台で自分らしくいることで、機会に恵まれなかった若いラテン系の女の子たちの力になりたいとローラは話す。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で（字幕を全文確認）", "art": "ext-Vo3bcjCIZtE", "src": [["番組のYouTube（28:55〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1735s"]]}]);
  if (PROFILES["Damian Priest"]) PROFILES["Damian Priest"].facts.push({"cat": "暮らし", "t": "ラテン系の誇りを体現する先輩", "b": "ダミアン・プリーストは、ブロンクス育ちのプエルトリコ系で、ヒスパニックとしての誇りをWWEで一番うまく見せている選手だと、ローラ・バイスが話している。昔からお気に入りの選手だったそうだ。", "sp": "ローラ・バイス", "d": "2026-03-05", "how": "デニース・サルセドの番組で、ローラ・バイスの話（字幕を全文確認）", "src": [["番組のYouTube（29:45〜）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE&t=1785s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Vo3bcjCIZtE", d: "2026-03-05", show: "ext", who: ["Lola Vice"], t: "ローラ・バイスの回　キューバの誇り、母への想い、メキシコでの飛躍", lead: "デニース・サルセドの番組に出た約31分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Lola Vice"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Vo3bcjCIZtE").map((x) => [x.t, x.b, x.sp])), open: ["字幕で名前が崩れていた対戦相手などの固有名詞は、確信が持てないため載せていない。", "番組の宣伝や次の大会の告知は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Vo3bcjCIZtE"]] });
  if (!PROFILES["Sol Ruca"]) PROFILES["Sol Ruca"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Sol%20Ruca"]], moves: [], facts: [] };
  if (PROFILES["Sol Ruca"].lead === "") PROFILES["Sol Ruca"]._weak = 1;
  PROFILES["Sol Ruca"].facts.push(...[{"cat": "リングの話", "t": "フィニッシュ技のもとは段違い平行棒の技", "b": "ソル・ルカの決め技は、体操の段違い平行棒で自分の演技に入れていた技が出発点だという。低い棒から高い棒へ跳び、前に振って後ろに振り戻し、後ろへ動きながら前に回る逆向きのひねりに近い動きだそうだ。体操では棒をつかんでいたが、いまは相手の体をつかむので、そこだけ調整したと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:44〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=104s"]]}, {"cat": "リングの話", "t": "夢の対戦相手は、裏切ったザリア", "b": "ゲーム「WWE 2K26」で組みたい試合を聞かれ、NXTの現状から、自分を裏切ったザリアを挙げたという。お互いの動きを知っているので、立ち上がりから熱い試合になると見ている。スピアへの返し方や、ソウルスナッチャーをスピアで切り返される場面まで想像し、勝敗は分からないと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（8:05〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=485s"]]}, {"cat": "リングの話", "t": "入団後の大けがと「大丈夫」の自己暗示", "b": "体操とアクロバット＆タンブリングの4年間はけがなく終えるのが目標で、それは達成したという。ところがWWEに来てからけがをしてしまった。技が仕上がってきた時期だっただけに、同じ水準に戻れないことを怖がり、回復中は「大丈夫」と自分に言い聞かせ続けたそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（15:17〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=917s"]]}, {"cat": "リングの話", "t": "「キャラは？」と聞かれて驚いた入団当初", "b": "スポーツでは着るものも演技も決められていたので、WWEでも同じだと思っていたという。ところが「あなたのキャラクターは何？」と意見を求められて驚いたそうだ。何が自分に合い、テレビで通じるのかを探るのは大変だったが、ファンの前で素直に試せるのは面白かったと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（59:31〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3571s"]]}, {"cat": "リングの話", "t": "NXTは、プロのない競技の選手の受け皿", "b": "アクロバット＆タンブリングにも体操にもプロの道がなく、競技をやめて普通の仕事に就く仲間を多く見てきたという。NXTがそうしたアスリートを迎え入れていることで、好きなことを続けて表現できる新しい世界が開けたと感じているそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:01:08〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3668s"]]}, {"cat": "リングの話", "t": "NXTで残したい足跡", "b": "NXTでの自分の足跡は、レスリング経験がなかった人間でもここまで来られると示すことにしたいという。心に決めれば何でもできること、失敗や笑われることや転ぶことを怖がらず、何度でも立ち上がることを、自分のキャリアを通じて見せたいと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:04:22〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3862s"]]}, {"cat": "リングの話", "t": "いちばん難しかったのは「キャラになること」", "b": "競技では常にまじめで感情を抑えていたので、リングで感情を出して役を演じるのが最も難しかったという。とくに怒りのプロモは、まだやり方が分からないそうだ。自分を怒らせられるのは兄だけなので、怒る場面では兄を思い浮かべるしかないと笑って話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:07:29〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=4049s"]]}, {"cat": "リングの話", "t": "「素の自分を盛る」のが分からない", "b": "周りからは「自分らしく、少し盛って」と言われるが、いまの自分がすでに素のままなので、どう盛ればいいのか分からなかったという。それでも最近は少しずつ分かってきたと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:08:15〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=4095s"]]}]);
  if (!PROFILES["Sol Ruca"]) PROFILES["Sol Ruca"] = { lead: "体操と大学のアクロバット競技を経て、レスリング未経験から育成ブランドの顔になった。心理学を学び、大人になってからADHDと分かった自分の心の動きを率直に語る人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Sol%20Ruca"]], moves: [], facts: [] };
  if (PROFILES["Sol Ruca"]._weak) { PROFILES["Sol Ruca"].lead = "体操と大学のアクロバット競技を経て、レスリング未経験から育成ブランドの顔になった。心理学を学び、大人になってからADHDと分かった自分の心の動きを率直に語る人だ。"; delete PROFILES["Sol Ruca"]._weak; }
  PROFILES["Sol Ruca"].facts.push(...[{"cat": "リングに来るまで", "t": "必殺技は段違い平行棒の技から", "b": "フィニッシャーの動きは、体操の段違い平行棒で演技に入れていた技がもとになっているという。低い棒から高い棒へ跳び移り、前後に振って回転する技だそうだ。体操では棒をつかんでいたが、今は人をつかむので少し調整したと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:44〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=104s"]]}, {"cat": "リングに来るまで", "t": "バレエ教室で宙返りして体操へ", "b": "最初に習ったのはバレエだった。母は体操の厳しさを知っていて娘を体操に入れたくなかったが、バレエのレッスン中にバーに上がって宙返りを繰り返したため、母も体操の道を認めたという。6歳から大学卒業まで体操と大学の競技を続けてきたそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（2:31〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=151s"]]}, {"cat": "リングに来るまで", "t": "背が高く「向いてない」と言われ続けた", "b": "体操選手としては背が高く、この競技に向いていないとよく言われたという。そのたびに「見ていろ」と思い、言われたことを覆すことを原動力にしてきたと話す。体育館に掲げられていた、できないと言われたからこそやる、という趣旨の言葉が支えだったそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（3:17〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=197s"]]}, {"cat": "リングに来るまで", "t": "未経験の大学競技で奨学金を得た", "b": "オレゴン大学では体操ではなく、体操と競技チアを合わせたような「アクロバット&タンブリング」に取り組んだ。ばねのある床がなく、チームで動きをそろえるため、宙返りを一から覚え直したという。やったことのない競技で奨学金を得て、今また未経験のレスリングでプロになったことを「自分の人生のテーマ」と話す。大学では土台を支えるバックスポットも務めたそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（4:03〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=243s"]]}, {"cat": "家族", "t": "母は体操選手でコーチ、娘には別の夢", "b": "母は元体操選手で体操のコーチだが、娘にはバレリーナと花屋になってほしかったという。どちらにもならなかったと笑う。母は自分のコーチにはならず、指導は切り離していたそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（10:29〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=629s"]]}, {"cat": "家族", "t": "クリスマスに平均台をねだり庭で練習", "b": "ある年のクリスマスに平均台や鉄棒、マットをねだり、家の前の芝生で独学で技を練習していたという。どうしても分からない時だけ母に聞き、母は口を出しすぎないようにしていたそうだ。両親はどちらものんびりした性格で、本人もカリフォルニアらしい気楽さを受け継いでいると話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（11:16〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=676s"]]}, {"cat": "リングに来るまで", "t": "競う相手は他人ではなく自分", "b": "負けず嫌いだが、他人の出来には左右されないようにしているという。順位に関係なく前の自分より良ければそれでいい、という考え方だそうだ。体操のコーチからも、特に平均台では他の選手を見ずに自分の演技だけに集中するよう教わったと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（12:10〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=730s"]]}, {"cat": "体のこと", "t": "身長175cm、平均台は苦手だった", "b": "得意だったのは床と跳馬といった力強い種目で、段違い平行棒も好きだったが背が高いぶん難しかったという。手足が長く足も大きいので、平均台は人より細く感じて好きになれなかったそうだ。身長は5フィート9インチ（約175cm）、靴は女性サイズの10だと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（13:40〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=820s"]]}, {"cat": "体のこと", "t": "体操時代のけがで今も腰に不安", "b": "体操時代のけがが尾を引き、今も腰に不安を抱えているという。手術が必要なほどではなかったそうだ。大学の4年間はけがをせずに終えることを目標にして達成したが、WWEに来てからけがをしたと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（15:17〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=917s"]]}, {"cat": "体のこと", "t": "けがの回復は「大丈夫」と言い聞かせて", "b": "WWEでのけがの回復期には、自分は大丈夫だと言い聞かせ、元のレベルに戻れない可能性を考えないようにしたという。技の構成を磨き始めた時期だったため不安は大きかったそうだ。心の持ち方が体の治り方にも関係すると感じていると話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（16:07〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=967s"]]}, {"cat": "リングに来るまで", "t": "心理学の学士、児童発達を専攻", "b": "大学で心理学の学士号を取っており、児童発達心理学に重点を置いていたという。もともとはカイロプラクターを目指して人体生理学を学び始めたが、化学がどうしても合わず、脳への興味から心理学に移ったそうだ。人それぞれの生い立ちを想像して相手に共感するようにしていると話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（16:57〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=1017s"]]}, {"cat": "暮らし", "t": "刺さる悪口は自分も信じている言葉", "b": "ネットの否定的な書き込みのうち、本当に効くのは自分でも心のどこかで思っていることだと気づいたという。そう分かると、痛むのは相手の言葉のせいではなく自分の思い込みのせいだと切り分けられるそうだ。できたことを並べて見直すようにしているが、今もうまくいかない時があると話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（31:26〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=1886s"]]}, {"cat": "家族", "t": "両親は気持ちより解決を急ぐ人だった", "b": "子どもの頃、落ち込んでいると両親は慰めてくれたが、気持ちを受け止めるより先に解決策を示そうとしたという。今振り返ると、まず泣いて感じる時間がほしかったそうだ。子どもには体のどこで感情を感じているかを尋ねるなど、気持ちを探る手助けが大切だと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（37:06〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=2226s"]]}, {"cat": "好きなもの", "t": "憧れの体操選手はナスティアとバイルズ", "b": "幼い頃は、自分と同じく背の高い体操選手ナスティアに憧れ、サインももらったはずだという。今ならシモーン・バイルズだそうだ。自分も運動能力には自信があったが、彼女には圧倒されると話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（38:52〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=2332s"]]}, {"cat": "体のこと", "t": "大学でADHDと診断された", "b": "母が失読症のため検査に連れて行かれた際、ADHDの兆候を指摘されたが、母は当時の印象から否定したという。体操や女性であることから目立たないよう抑え込み、気づかないまま育ったそうだ。大学で心理学を学ぶうちに自分で気づき、ルームメイトにも後押しされて診断を受けた。非刺激薬を処方されたがあまり効かなかったと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（49:13〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=2953s"]]}, {"cat": "体のこと", "t": "拒絶されたと感じると体がつらくなる", "b": "ADHDに伴う、拒絶に過敏な反応があるという。否定されたと受け取ると、体が熱くなり汗をかくような身体的な苦しさを感じるそうだ。みんなそうだと思っていたが、仕組みを知って「嫌われているわけではない」と思えるようになったと話す。人に合わせすぎてしまう傾向にも今も悩んでいるという。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（51:40〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3100s"]]}, {"cat": "体のこと", "t": "競技がドーパミンの源だった", "b": "ADHDで刺激を求める性質があり、競技で結果を出したり新しい技を覚えたりすることが心の燃料になっていたという。それが今の場所まで自分を押し上げたと話す。興味が次々に移る性分で、入団当初は昔からレスラーを夢見てきた人たちの中で場違いな気持ちもあったそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（53:15〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3195s"]]}, {"cat": "家族", "t": "本名は母の好きな香水から", "b": "本名のカリクスは、母が大好きだった香水の名前から付けられたという。調べると花びらを支える緑の部分（がく）を指す言葉で、花屋に憧れていた母はぴったりだと考えたそうだ。リングネームのソルは太陽の意味だと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（56:24〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3384s"]]}, {"cat": "好きなもの", "t": "夢はハンナ・モンタナと服作り", "b": "幼い頃はハンナ・モンタナになりたかったという。ファッションデザイナーにも憧れ、父が捨てようとしたズボンでドレスを作り、母のハイヒールを履いてポーズを取った写真が残っているそうだ。画家やグラフィックデザイナー、スタントダブル、音楽家も夢見たと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（57:12〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3432s"]]}, {"cat": "暮らし", "t": "リングコスチュームもシャツも自作", "b": "リングで着るギアを自分で作っており、最近はグッズ風のシャツも手作りしているという。番組で着ていたシャツも自作だそうだ。子どもの頃にやりたかったことを、今すべてこの仕事に持ち込めているのがうれしいと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（57:59〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=3479s"]]}, {"cat": "リングに来るまで", "t": "スカウト時はハワイでSNSが本業", "b": "声がかかった時は大学を出たばかりでハワイに住み、SNSの発信を本業にしながらオンラインのパーソナルトレーナーをしていたという。決まった職も定住先もなかったので、受からなくても話の種になると思ってトライアウトを受けたそうだ。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:06:44〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=4004s"]]}, {"cat": "リングに来るまで", "t": "一番難しいのはキャラクターを演じること", "b": "競技では常に真剣な顔でいることを求められてきたため、リングで感情を出すことが一番難しかったという。怒るプロモはまだうまくできないそうだ。本気で腹が立つのは男きょうだいだけだと笑う。「自分らしさを大きく」と言われても最初はピンとこなかったが、少しずつつかめてきたと話す。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:07:29〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=4049s"]]}, {"cat": "家族", "t": "父はアフリカ系、母は白人のミックス", "b": "父がアフリカ系アメリカ人、母が白人のミックスだという。毎年の黒人歴史月間には、黒人ではないと言われたり、父の写真で証明を求められたりするそうだ。幼い頃に両親と入った店から追い出された記憶があり、競技では活躍を出自のせいにされたこともあったと話す。肌の色が濃い人ほどの苦労はしていないと理解しつつ、ミックスの人の居場所が認められてほしいと語っている。", "sp": "ソル・ルカ", "d": "2026-03-12", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-wDP_z80EySc", "src": [["公式YouTube（1:12:19〜）", "https://www.youtube.com/watch?v=wDP_z80EySc&t=4339s"]]}]);
  ARTICLES.push({ id: "wys-wDP_z80EySc", d: "2026-03-12", show: "wys", who: ["Sol Ruca"], t: "ソル・ルカの回　体操少女が心理学とADHDを語る", lead: "ステファニー・マクマホンの番組に出た約79分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Sol Ruca"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-wDP_z80EySc").map((x) => [x.t, x.b, x.sp])), open: ["ザリアとの因縁や対戦予想、ゲーム企画や番組・大会の宣伝部分は筋書き・宣伝にあたるため載せていない。", "WWEに来てからのけがは部位や時期が語られておらず、詳細は不明。", "中盤の感情との向き合い方や子育て論は聞き手の家族の話と交互に進むため、ゲスト本人の発言と確認できた部分だけを要約した。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=wDP_z80EySc"]] });
