  if (!PROFILES["Lita"]) PROFILES["Lita"] = { lead: "メキシコへ単身で渡り、下積みから這い上がったリタ。大けがを乗り越えてきた道のりと、いまの穏やかな暮らしを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Lita"]], moves: [], facts: [] };
  if (PROFILES["Lita"]._weak) { PROFILES["Lita"].lead = "メキシコへ単身で渡り、下積みから這い上がったリタ。大けがを乗り越えてきた道のりと、いまの穏やかな暮らしを語る。"; delete PROFILES["Lita"]._weak; }
  PROFILES["Lita"].facts.push(...[{"cat": "体のこと", "t": "今の体調は「ほとんどの日は絶好調」", "b": "たくさんのけがや受け身を重ねてきたが、ほとんどの日は体の調子がいいとリタは話す。調子の悪い日は「自分は無敵ではない」と思い出させてくれる合図だという。先輩たちの歩き方を見ると、自分が今動けることへの感謝も深まるそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（0:51〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=51s"]]}, {"cat": "リングの話", "t": "久々の王座戦は味わう余裕があった", "b": "年間最大級の大型イベントへの出場から、中東での王座戦までの流れを、リタは「今までで最高の経験の一つ」と話す。現役時代は次へ次へと追われて感慨に浸れなかったが、今回は自分を外から眺めるように一瞬一瞬を味わえたという。前に出た大型戦では緊張の種類が悪く、体がもつか不安だったため、今回は何か月も前から鍛え直したそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（2:33〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=153s"]]}, {"cat": "リングの話", "t": "自分の試合はほとんど見返さない", "b": "新しい技を試したとき以外、リタは自分の試合映像を見ないという。見ると「その首の振り方は変だ」などと粗が気になって、感情で動く自分らしさが失われるからだそうだ。音楽が鳴ると緊張が消えて、その場に集中できると話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（9:53〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=593s"]]}, {"cat": "暮らし", "t": "ふだんは「ごく普通の暮らし」で十分", "b": "リタは今の普通の生活に満足していると話す。フルタイムで活動していた頃は、リングの外では一人の人間だと意識して思い出す必要があったという。復帰が決まって観客や周りの反応に触れたことで、「まだやれると思ってもらえている」と自信を取り戻したそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（11:25〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=685s"]]}, {"cat": "家族", "t": "父の転勤で2、3年ごとに引っ越し", "b": "フロリダ育ちで、地域担当の営業職だった父の仕事のため、2、3年おきに引っ越していたという。友だちは作りやすかったが、すぐ別れる前提でもあったそうだ。この環境が、一匹狼のような気質につながったとリタは見ている。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（13:10〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=790s"]]}, {"cat": "リングに来るまで", "t": "水泳と柔道、個人競技のなかのチーム", "b": "子どもの頃は水泳チームと柔道に打ち込んでいたという。どちらも個人競技でありながらチームでもあり、それがプロレスに向く土台になったとリタは話す。のちに関節技を出すときも、柔道の経験が生きたそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（13:57〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=837s"]]}, {"cat": "リングに来るまで", "t": "家族は観ていなかったプロレスにはまる", "b": "家族はプロレスを観る習慣がなく、当時付き合っていた人が観ているのを部屋の外から覗くうちに引き込まれたという。バンド活動と柔道の大会に出ていたリタは、「ロックスターで運動選手でもある仕事」に見えて憧れたそうだ。周りには子どもが消防士になると言うように、「プロレスラーになる」と話していたという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（14:42〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=882s"]]}, {"cat": "リングに来るまで", "t": "きっかけはレイ・ミステリオの試合", "b": "リタはメキシコ式のプロレスに惹かれ、とくにレイ・ミステリオに心を奪われたという。英語も話せて、体の小さな彼が大きな相手に勝てると信じさせる表現力に感動したそうだ。メキシコの選手たちはなぜ話さないのかと聞いたら、英語が話せないからだと言われ、本場へ行くしかないと考えたという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（15:31〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=931s"]]}, {"cat": "リングに来るまで", "t": "右も左も分からずメキシコへ", "b": "付き合っていた人がバンドのツアーに出る数か月の間に、リタは一人でメキシコへ向かったという。プロレスの会場の場所すら知らず、街で尋ね歩いたそうだ。ダフ屋から10ドルほどで買った最前列の席で、隣の60代の女性から選手のことを教わったという。会場に通い詰める姿が認められ、3回目あたりで団体の道場に入れてもらえたと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（16:19〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=979s"]]}, {"cat": "暮らし", "t": "メキシコの滞在先は安宿のあとシェアハウス", "b": "滞在先は旅行ガイドで見つけた1泊10ドルの宿から始まり、1週間でもっといい場所を探したそうだ。ジャーナリスト志望の留学生たちに出会い、彼らのアパートの空き部屋に滞在することになったという。引っ越しの多い育ちのおかげで、自分を楽しませ自分を頼る力が身についたとリタは話す。滞在は2か月ほどだった。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（18:00〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1080s"]]}, {"cat": "リングに来るまで", "t": "何でも引き受けるインディー団体時代", "b": "帰国後はメリーランドの団体を拠点に、付き人役、試合、タイムキーパー、リングの設営と何でも引き受けたという。楽屋では誰にでも話しかけ、次の興行に同行させてほしいと頼み込んだそうだ。助言は一度聞いて、その人の試合で観客がどう反応するかを確かめてから取り入れていたという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（18:47〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1127s"]]}, {"cat": "リングに来るまで", "t": "ECWには「リング設営を手伝う」と押しかけた", "b": "ガソリン代すら出ない遠征でも、リタは稼ぎを工夫して回り続けたという。ECWは、仲間と先に会場へ行って設営を手伝い、そのまま練習に混ざる形で入り込んだそうだ。トミー・ドリーマーに見つけられ、5分の試合を作ってみせたことが採用につながったという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（20:26〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1226s"]]}, {"cat": "リングに来るまで", "t": "ドリー・ファンク・ジュニアの道場で基礎を学ぶ", "b": "ECWでは役柄が合わず出番が少なかったが、試合前の練習で多くを学んだという。さらに自腹で、ドリー・ファンク・ジュニアの道場に通うため休みをもらったそうだ。そこでは基本を何度もやり直す指導を受け、基礎が固まるほど応用がきくと実感したと話す。その稽古の映像が見られたことが、WWEからの連絡につながったという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（22:53〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1373s"]]}, {"cat": "リングに来るまで", "t": "24歳でWWEへ、レンタカーも借りられない年", "b": "WWEに入ったのは24歳のときで、年齢制限のため車も借りられなかったという。「いつか成功する」と思いつつ、「合わないと思えば別の道へ行ってもいい」とも考えていたそうだ。まず巡業の前座試合から始めたと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（27:41〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1661s"]]}, {"cat": "リングの話", "t": "ハーディー兄弟とは同じ仲間の雰囲気だった", "b": "リタはインディー時代からハーディー兄弟と友人で、運営側にも「一緒に入場する姿がバンドのよう」と見られていたという。その3人で組んだ時期を、仕事に感じないほど魔法のようで、誰もショーを早く出ないほど皆が互いの試合を観ていた時期だったと振り返る。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（28:27〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1707s"]]}, {"cat": "リングの話", "t": "男子選手との試合に感謝している", "b": "男子選手との混合試合や、団体戦での技の受けを「断られても不思議ではなかったのに」と感謝しているとリタは話す。技を決められた後は、毎回ひとことお礼を伝えていたそうだ。それが自分の独自の道につながったと考えている。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（32:31〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1951s"]]}, {"cat": "リングの話", "t": "初めての王座は、実感がわくまで時間がかかった", "b": "初めてのタイトルは、本番前に聞いていても「期待しすぎない」と心の準備をしていたという。入場のときまで半信半疑で、実感したのは控え室に戻ってからだそうだ。大物選手が倒れている横で一人で喜ぶのは失礼だと思い、すぐにリングを降りたという。王者になってからは、売りの技を試合の中で意味のある場面に置く物語作りが必要になったと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（38:17〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=2297s"]]}, {"cat": "リングの話", "t": "チャイナとは友人同士の最後の試合", "b": "チャイナは相手を選ぶ人で、インディー出身のリタを尊敬してくれ、面倒を見てくれたという。二人はもっと多くのアイデアを温めていたが、実現した試合は一度きりだったそうだ。関節技を取り入れたのは、お互い「知られていない技を見せたい」と考えたからだという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（46:18〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=2778s"]]}, {"cat": "体のこと", "t": "撮影中の事故で首を3か所骨折", "b": "ドラマの撮影現場でスタントの練習中に、受け手が崩れて頭から落ちたという。最初は鎖骨の骨折かと思い、周りの人も軽く扱ったが、のちの検査で首の骨が3か所折れていたと分かったそうだ。医師から「咳やくしゃみでも麻痺の危険がある」と言われ、泣いたとリタは話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（48:40〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=2920s"]]}, {"cat": "体のこと", "t": "手術前、同じ経験をした先輩に相談した", "b": "手術で二度と試合ができなくなることを恐れ、リタは首を痛めても現役に戻れた先輩に話を聞きたいと考えたという。その先輩が付き添って一緒に飛行機に乗ってくれ、恐怖が和らいだそうだ。手術は首の骨2段分の固定で、医師は慎重な方針をとったという。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（52:46〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=3166s"]]}, {"cat": "暮らし", "t": "休養中は動物保護施設で「出勤」した", "b": "約15か月の休養中、じっとしていることがいちばんつらかったという。首の固定具を4か月つけて運転もできず、保護施設のボランティアに通う予定を自分で作ったそうだ。放送を観るのは苦しく、解説の仕事も気持ちが整わず辛かったと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（54:22〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=3262s"]]}, {"cat": "体のこと", "t": "復帰は「まだ準備ができていない」と時間をもらった", "b": "復帰の話が出た約1年後も、リタは不安が消えず、さらに3か月の猶予を求めたという。リングに上がっても相手のことだけを考えられる状態になりたかったそうだ。復帰後は体が問題なく動いたが、周囲の判断で大技の出し方が制限されたと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（55:14〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=3314s"]]}, {"cat": "体のこと", "t": "膝の大けがは首より復帰が大変だった", "b": "首のときは骨がつくのを待つだけだったが、膝の前十字靭帯は手術の直後からリハビリが必要だったという。足を数センチ上げる運動すらできず、友人に手を貸してもらい悔しかった日があったそうだ。有名な整形外科医のもとで手術を受けたとリタは話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:04:54〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=3894s"]]}, {"cat": "リングの話", "t": "悪役は「普段と真逆を10倍」で演じた", "b": "長く正統派を務めたため、悪役への転向は最初戸惑ったという。普段の自分と逆のことを大げさにやる、と考えるようになってから楽になったそうだ。ブーイングがあるほど「もっとやろう」と思え、歓声と同じくらいやりがいがあったと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:15:26〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=4526s"]]}, {"cat": "暮らし", "t": "30歳で引退を決めた理由は「お金ではなく情熱」", "b": "年齢の割に控え室は若い世代が中心で、30歳は古参に思えたそうだ。始めたのは給料のためではなく情熱だったのに、つらい時期には仕事のように感じたという。契約の前に巡業から外れて考える時間をもらい、100パーセント全力を出せないなら離れるべきだと判断したと話す。友人の結婚式や出産に行けなかったことも決断に影響したそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:20:08〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=4808s"]]}, {"cat": "暮らし", "t": "引退後はニカラグアで「一般人」に戻る", "b": "引退直後は数日間眠り続け、何年も疲れが取れなかったと感じたという。ニカラグアに家を持ち、マウンテンバイクに乗り、サーフィンをして市場へ歩く穏やかな暮らしに助けられたそうだ。現地ではプロレスもあまり知られておらず、気楽だったと話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:21:44〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=4904s"]]}, {"cat": "家族", "t": "殿堂入りは母を連れて、気楽に楽しんだ", "b": "殿堂入りの知らせはニカラグアで受けたという。式典の週は、母を連れてドレスを選び、準備も楽しめて、ストレスのない思い出になったそうだ。親友のトリッシュ・ストラタスが式で紹介し、彼女の息子（リタの名付け子）も一緒だったとリタは話す。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:22:32〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=4952s"]]}, {"cat": "リングの話", "t": "次の世代に憧れた子どもが今は同じリングに", "b": "今の女子選手の多くが、リタやトリッシュに憧れて入ったと話すのを知っているという。リタは、画面越しに自分を観ていた子どもたちが今は同じリングに立つことを楽しんでいると語る。中東でのイベントでは、自分を目標にしたと話す相手と試合ができたそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:24:58〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=5098s"]]}, {"cat": "暮らし", "t": "動物の救護活動は今も続ける", "b": "リタは動物の救護と教育の団体を立ち上げており、今も動物に関わる活動を続けているという。ニカラグアでは、動物の前に困っている人への支援も必要だと感じ、その活動にも広げたそうだ。声を持たない存在を助けられることを、光栄だと話している。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-InZA5m5f6Xs", "src": [["番組のYouTube（1:26:42〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=5202s"]]}]);
  if (PROFILES["Eddie Guerrero"]) PROFILES["Eddie Guerrero"].facts.push({"cat": "暮らし", "t": "エディ・ゲレロは基本が体に染みた人", "b": "エディ・ゲレロは歴代屈指の選手で、基本が頭に入っているから遊び心を持って試合ができた人だったと、リタが話している。一緒に組んだ物語はとても楽しく、安心して任せられたそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、リタの話（字幕を全文確認）", "src": [["番組のYouTube（26:03〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=1563s"]], "by": "第三者の話"});
  if (PROFILES["Chyna"]) PROFILES["Chyna"].facts.push({"cat": "暮らし", "t": "チャイナは気に入った相手を大切にした", "b": "チャイナは気に入った相手には温かく、そうでなければ距離を置く人だったと、リタが話している。インディー出身のリタを尊敬し、面倒を見てくれたそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、リタの話（字幕を全文確認）", "src": [["番組のYouTube（46:18〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=2778s"]], "by": "第三者の話"});
  if (PROFILES["Kane"]) PROFILES["Kane"].facts.push({"cat": "暮らし", "t": "ケインは業界屈指の優しい読書家", "b": "ケインは業界でもとくに優しい人で、読書家で賢いと、リタが話している。撮影の待ち時間に、本当の暮らしの話をして親しくなったそうだ。", "sp": "リタ", "d": "2026-03-14", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、リタの話（字幕を全文確認）", "src": [["番組のYouTube（1:08:10〜）", "https://www.youtube.com/watch?v=InZA5m5f6Xs&t=4090s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-InZA5m5f6Xs", d: "2026-03-14", show: "ext", who: ["Lita"], t: "リタの回　メキシコ修行から首の大けが、殿堂入りまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約88分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Lita"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-InZA5m5f6Xs").map((x) => [x.t, x.b, x.sp])), open: ["元交際相手に関する話は、番組内の説明にとどめ、私的な場面は省いた。", "ケインとの筋書き、結婚式の場面、中東の王座戦の試合展開の実況部分は、素顔の話ではないため省いた。", "番組の聞き手の発言や、聞き手が先に語った体験談は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=InZA5m5f6Xs"]] });
  if (!PROFILES["Oba Femi"]) PROFILES["Oba Femi"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Oba%20Femi"]], moves: [], facts: [] };
  if (PROFILES["Oba Femi"].lead === "") PROFILES["Oba Femi"]._weak = 1;
  PROFILES["Oba Femi"].facts.push(...[{"cat": "リングの話", "t": "どの会場でも「ただの練習」と思う", "b": "オバ・フェミは砲丸投げ時代、コーチから「リングの大きさはどこでも同じ。練習のつもりでやれ」と教わったという。この考え方をWWEにも持ち込み、観客が400人でも1万6千人でも育成施設と同じ気持ちで上がると話す。重みを背負って臨むと負けやすいので、何も懸かっていないつもりで動くのだそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（6:26〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=386s"]]}, {"cat": "リングの話", "t": "相手の体の反応を見て技を決める", "b": "オバ・フェミは、実家で親の機嫌を読んで育ったため、人の体の動きや表情に敏感になったと話す。試合中に次の展開を相談するときも、相手が嫌がっていると感じたらすぐ引き、乗っていれば押すそうだ。プロレスは人付き合いの仕事で、その感覚が役立っているという。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（13:12〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=792s"]]}, {"cat": "リングの話", "t": "緊張した相手には冗談で力を抜かせる", "b": "オバ・フェミは、相手の体がこわばっているときは、プロレスの話をやめて冗談を言い、落ち着いてから戻すのがよいと話す。それでも進めるべきときは、そのまま押し切ることもあるそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（14:45〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=885s"]]}, {"cat": "リングの話", "t": "試合中にレフェリーの一言で肩の力が抜けた", "b": "駆け出しのころ、関節技の最中にレフェリーから「いい男だな」と言われて、緊張が一気にほどけたことがあるという。オバ・フェミは、レフェリーは相手との距離を埋める唯一の接点であり、会場と舞台裏をつなぐ橋渡し役だと話す。技を忘れたときに思い出させてくれることもあるそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（16:20〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=980s"]]}, {"cat": "リングの話", "t": "悪役が好きな理由", "b": "オバ・フェミは昔から悪役が好きだったと話す。倒すべき大きな存在がなければ英雄は生まれないので、物語ではむしろ悪役のほうが大事だと考えているという。映画では「スター・ウォーズ」のダース・ベイダーが最高だと語る。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（26:35〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1595s"]]}, {"cat": "リングの話", "t": "ブレイ・ワイアットの名ゼリフを演説に借りた", "b": "オバ・フェミは、NXT時代の初期ワイアット・ファミリーが大好きだったと話す。「誰を差し向けてもいいが、取り戻したいと思う相手は送るな」という趣旨のセリフを、数年前に自分のマイクで使ったそうだ。最高の決め台詞だと思って借りたという。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（32:07〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1927s"]]}, {"cat": "リングの話", "t": "NXT時代、ショーン・マイケルズに試合案を直された", "b": "オバ・フェミは育成時代、凝った試合や決着を考えて持っていっても、ショーン・マイケルズにいつも変えられたという。最初は悔しかったが、先の筋書きを知っているのは相手だと割り切り、自分は作品を形にする道具になろうと考えたそうだ。ブッキングを学ぶため、何を求めているか本人に聞いてから案を書き直すこともあったという。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（40:02〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2402s"]]}, {"cat": "リングの話", "t": "見た人に「感じてもらう」レスラーになりたい", "b": "オバ・フェミは、自分がプロレスを見て夢中になった体験を、観客に返したいと話す。NXTに入った日から、本物らしく見せ、感情を揺さぶって引き込みたいと考えてきたそうだ。王座は後からついてくるもので、引退後は「オバ・フェミを感じた」と思われたいという。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（47:14〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2834s"]]}, {"cat": "リングの話", "t": "ランブルの入場と、肩で歩く独特の歩き方", "b": "年間有数の大会ロイヤルランブルのサウジアラビア大会で、オバ・フェミは観客の声援に応えて入場したという。あの歩き方はリック・フレアーの動きを現代風にしたもので、腕よりも肩を大きく動かすのがこつだと話す。花道が長いので歩幅も大きくするそうだ。髪のビーズはナイジェリアの文化への敬意で、約15色を集めているという。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（51:57〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=3117s"]]}, {"cat": "リングの話", "t": "母の「読め！」をスマックダウンで使った", "b": "オバ・フェミは子どものころ、母と一緒に本を読んでいて居眠りすると、いつも突然「読め！」と叫ばれて飛び起きたという。同じ呼び方を、先週金曜のスマックダウンの場面でそのまま使ったと話す。母由来の台詞が画面に出た、という小さな裏話だ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（1:12:57〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=4377s"]]}]);
  if (!PROFILES["Oba Femi"]) PROFILES["Oba Femi"] = { lead: "ナイジェリアで厳しく育ち、砲丸投げの奨学生として渡米した。母への深い愛情と絵を描く感性を持ち、「もっと上へ」と自分を更新し続ける考える人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Oba%20Femi"]], moves: [], facts: [] };
  if (PROFILES["Oba Femi"]._weak) { PROFILES["Oba Femi"].lead = "ナイジェリアで厳しく育ち、砲丸投げの奨学生として渡米した。母への深い愛情と絵を描く感性を持ち、「もっと上へ」と自分を更新し続ける考える人だ。"; delete PROFILES["Oba Femi"]._weak; }
  PROFILES["Oba Femi"].facts.push(...[{"cat": "家族", "t": "規律の厳しいナイジェリアで育つ", "b": "育ったナイジェリアの家庭は規律が厳しく、遊ぶにも許可が必要だったという。それでも両親は愛情深く、できることは何でもしてくれたと話す。とくに母は一番のファンだそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（0:49〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=49s"]]}, {"cat": "家族", "t": "苦しい家計を感じさせなかった両親", "b": "家は国の中では中くらいだが、世界的に見れば貧しい部類だったという。両親は苦しい時期もそれを子どもに感じさせなかったと振り返る。大きくなって事情を知り、自分も家を支えようと思ったそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（3:54〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=234s"]]}, {"cat": "家族", "t": "12歳で弟ができた「ほぼ一人っ子」", "b": "長く一人っ子で、12歳のとき養子の弟が家族に加わったという。両親は結婚から6年待って自分を授かったため、期待とプレッシャーを一身に受けていたと話す。弟が来て周りの目が離れ、自分のことを自分でやり始めるきっかけになったそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（3:54〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=234s"]]}, {"cat": "リングに来るまで", "t": "砲丸投げ8年で身につけた平常心", "b": "WWEに来る前、砲丸投げを約8年続けていたという。試合会場のサークルは滑り具合が毎回違うが、コーチに「大きさは同じ、練習だと思え」と教わったそうだ。何も懸かっていないつもりでやるという考え方を、今もリングに持ち込んでいると話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（6:26〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=386s"]]}, {"cat": "体のこと", "t": "生活を一気に変えるなと言われた", "b": "食事を整え夜8時に寝るなど、生活を一気に改めようとしたことがあるという。そのときコーチに、急に変えると自分の強みまで失うから時間をかけろと止められたそうだ。人は一晩では変われない、というのが一番の教訓だと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（10:40〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=640s"]]}, {"cat": "家族", "t": "親の顔色から学んだ観察力", "b": "両親は仕事の疲れや感情を家に持ち帰ることがあり、それは普通のことだったと前置きしたうえで語った。その空気を察して殻にこもることも多く、人の評価を気にする面が育ったという。一方で相手の表情や体の動きを読む力がつき、今のリング上のやりとりにも役立っているそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（11:34〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=694s"]]}, {"cat": "暮らし", "t": "流行りのネタも笑って受け入れる", "b": "若い世代の流行ネタ「6-7」を見ても、腹は立たず笑ってしまうという。自分たちの世代もVineのネタを真似していたので、時代は移るものだと受け止めているそうだ。番組の時点で27〜28歳だと話している。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（21:10〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1270s"]]}, {"cat": "好きなもの", "t": "ディスクで追いかけたWWE", "b": "ナイジェリアでは生中継がなく、放送は数週遅れだったという。2011年ごろから発売されるディスクで翌日に観るようになり、2016〜17年ごろまでのコレクションができたそうだ。当時はSNSも見ていなかったのでネタバレもなかったと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（24:17〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1457s"]]}, {"cat": "好きなもの", "t": "一番好きだったのはトリプルH", "b": "観ていた頃のお気に入りはトリプルHで、試合をよく研究したという。激しさと正確さを持ち、何も欠けていない「完成された選手」だったのが理由だそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（25:47〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1547s"]]}, {"cat": "好きなもの", "t": "昔から悪役が好き", "b": "子どもの頃から悪役に惹かれてきたという。悪役が大きいほど乗り越えるヒーローも大きくなるので、物語では悪役のほうが大事かもしれないと話す。スター・ウォーズならダース・ベイダーが一番だそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（26:35〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1595s"]]}, {"cat": "好きなもの", "t": "歴代の大型選手ランキング", "b": "名前を伏せたまま順位を付ける企画で、1位アンダーテイカー、2位アンドレ・ザ・ジャイアント、3位ケイン、4位ビッグ・ショーと並べた。最後に自分の名前が出て5位にされかけ、「1位より上だ」と抗議して笑いを誘った。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（28:56〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1736s"]]}, {"cat": "好きなもの", "t": "絵は「義務」になってしまった", "b": "幼い頃、母に車や犬を描いてもらううちに自分でも描き始めたという。周りから「芸術家になる子」と期待され続け、今は正直、絵への熱は冷めてしまったと話す。うまく描けないと紙を破るほどの完璧主義だったが、失敗も作品の一部だと後に学んだそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（29:44〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1784s"]]}, {"cat": "好きなもの", "t": "大学で描いた時計塔の老人", "b": "大学では美術を学んだという。一番人気の作品は、老人が時計塔を背負う絵で、課題として1時間ほどで描いたものだそうだ。「時間には誰も勝てない」ことを表したと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（34:24〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2064s"]]}, {"cat": "家族", "t": "何度も描いた母と、教わった愛", "b": "自分の作品で好きなのは、何度も描いてきた母の絵だという。17歳ごろ、ナイジェリアにいた頃に描いた一枚も気に入っているそうだ。母からは本物の愛がどんなものかを教わり、だから相手の本気が分かるのだと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（36:02〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2162s"]]}, {"cat": "家族", "t": "説明しない父から学んだこと", "b": "父は口数が少なく、行き先を聞いても「黙ってついて来い」という人だったという。そのおかげで理由を聞かずに従うことに慣れ、育成時代もコーチを素直に権威として受け入れられたと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（43:14〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2594s"]]}, {"cat": "家族", "t": "将来の子育てで大事にしたいこと", "b": "いつか子どもがほしいと話す。自分が受けた規律やルールはそのまま引き継ぎたいという。一方で、13歳の頃に学校の悩みや流行りのズボンを軽く扱われた記憶から、子どもの悩みは本人にとって大事なものとして向き合いたいそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（43:59〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2639s"]]}, {"cat": "リングに来るまで", "t": "「次もやれるはず」で渡米から王者へ", "b": "8年前はナイジェリアにいて、WWEに入れるとは思えなかったという。砲丸投げで奨学金を得てミドルテネシーへ渡り、アラバマ大学に移って南東部カンファレンスで優勝、全米選手権でも入賞したそうだ。トライアウトを経て、同じ考え方で育成ブランドの王者まで進んだと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（55:11〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=3311s"]]}, {"cat": "体のこと", "t": "疲れたら休み、普段は90で動く", "b": "燃え尽きそうなときは休みの日をつくり、いったん離れてから戻るという。体力と気力の保ち方は、求められるのが70なら普段から90で動いておくことだそうだ。そうすれば70は楽にこなせると話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（58:23〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=3503s"]]}, {"cat": "好きなもの", "t": "大学時代はジョー・ローガンを聴いた", "b": "成功した人はみな大きな夢を恐れないと気づいたという。大学時代はジョー・ローガンのポッドキャストをよく聴き、デヴィッド・ゴギンズの生き方にも刺激を受けたそうだ。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（1:00:50〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=3650s"]]}, {"cat": "家族", "t": "母の「読みなさい！」が決め台詞に", "b": "子どもの頃、母と一緒に本を読む時間があったという。うとうとしかけると母が突然「読みなさい！」と叫び、慌てて飛び起きたそうだ。その一言を最近、テレビ番組の中でそのまま使ったと話す。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-nFbAanK90lg", "src": [["公式YouTube（1:12:10〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=4330s"]]}]);
  if (PROFILES["Bray Wyatt"]) PROFILES["Bray Wyatt"].facts.push({"cat": "暮らし", "t": "初期ワイアット・ファミリーが大好き", "b": "育成ブランド時代のワイアット・ファミリーが大好きで、ブレイの「戻ってきてほしい奴は送ってくるな」という台詞に痺れ、自分のプロモでも使ったことがあると、オバ・フェミが話している。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で、オバ・フェミの話（公式字幕を全文確認）", "src": [["公式YouTube（32:07〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=1927s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "考えた結末をいつも変えた", "b": "育成時代に凝った試合の結末を考えても、ショーン・マイケルズがいつも変えてしまったという。最初はもやもやしたが、先の展開を知っているのは彼だと気づき、身を預けるようになったと、オバ・フェミが話している。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で、オバ・フェミの話（公式字幕を全文確認）", "src": [["公式YouTube（40:02〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=2402s"]], "by": "第三者の話"});
  if (PROFILES["Terry Taylor"]) PROFILES["Terry Taylor"].facts.push({"cat": "暮らし", "t": "意見は合わないが刺激をくれた人", "b": "テリー・テイラーとは育成時代によく意見がぶつかったが、話のうまい賢い人で、本人の知らないところで刺激を受けていたという。「細部（minutiae）」という言葉も彼から教わったと、オバ・フェミが話している。", "sp": "オバ・フェミ", "d": "2026-03-19", "how": "ステファニーの番組で、オバ・フェミの話（公式字幕を全文確認）", "src": [["公式YouTube（50:26〜）", "https://www.youtube.com/watch?v=nFbAanK90lg&t=3026s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-nFbAanK90lg", d: "2026-03-19", show: "wys", who: ["Oba Femi"], t: "オバ・フェミの回　ナイジェリアの家族、砲丸投げ、絵と母のこと", lead: "ステファニー・マクマホンの番組に出た約74分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Oba Femi"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-nFbAanK90lg").map((x) => [x.t, x.b, x.sp])), open: ["入場時のストラットやビーズの話、50歳までに引退して指導に回りたいという話は、項目数の都合で今回は載せていない。", "ブレイ・ワイアットに試合前に励まされたという話はステファニー本人の体験なので載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=nFbAanK90lg"]] });
