  if (PROFILES["Matt Cardona"].lead === "") PROFILES["Matt Cardona"]._weak = 1;
  PROFILES["Matt Cardona"].facts.push(...[{"cat": "リングの話", "t": "復帰のきっかけは妻の一言", "b": "マット・カードナは、当時は契約なしでTNAに出ており、NXTへの対抗戦に参加したのが発端だったと話す。サウジでの大会の取材中に、妻のチェルシーがWWE社長のニック・カーンに夫の試合の話を持ちかけ、番号を教えてもらったという。マットはすぐにメッセージを送り、返ってきた電話で「戻りたい」と伝えたそうだ。そこから話が動き出したと語っている。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（12:04〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=724s"]]}, {"cat": "リングの話", "t": "目標はずっとWWE王者", "b": "マット・カードナは、タッグ王座やUS王座、IC王座を経験したが、最後に取った王座は2019年だと話す。子どものころからの目標はWWE王者になることで、解雇されたときも「どう戻るか」を常に頭に置いていたという。毎日、頭の中で目標を並べ、その一番上がWWE王者だそうだ。王者になるにはWWEにいなければならないので、まず戻る必要があったと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（13:39〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=819s"]]}, {"cat": "リングの話", "t": "解雇は心の重荷が取れた日", "b": "マット・カードナは、解雇されたのは世界が止まった疫病の初期で、行き先の計画はなかったと話す。前の年に周りが新しい5年契約を提示される中、自分は残るか去るか決められず、1年間不安だったという。解雇は決断を代わりにされたようなもので、肩が軽くなったと話す。ザック・ライダーのままでは変われず、「自分は何者か」を探す必要があったそうだ。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（16:54〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1014s"]]}, {"cat": "リングの話", "t": "インディーでは嫌われるWWE出身を演じた", "b": "マット・カードナは、インディー団体では「WWEから来た男」として嫌われ役になると決めたと話す。GCWの王座を取ってデスマッチ王を名乗ったが、実際にデスマッチをしたのは1回だけだという。ベルトを回転式にしたり、面ファスナーで付け替えられるようにしたりと独自に改造した。どの大会も年間最大の祭典のつもりで扱っていたと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（19:15〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1155s"]]}, {"cat": "リングの話", "t": "ニック・ゲージ戦が人生を変えた", "b": "マット・カードナは、インディー活動を始めて数か月のころ、ニック・ゲージとのデスマッチで注目を集めたと話す。話題になるとは思っていたが、予想以上の反響で、その夜はネット上で五輪より話題になったそうだ。ピザカッターやガラス、蛍光灯が使われる試合で、白いTシャツが血で暗赤色になったという。今日まで一度も後悔しておらず、この試合がなければWWE復帰もなかったと語っている。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（20:55〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1255s"]]}, {"cat": "リングの話", "t": "試合は技の数より客との結びつき", "b": "マット・カードナは、インディーの後輩から助言を求められると、ホーガン対ザ・ロックの名勝負を例に出すと話す。同じ技を同じ順番でインディーの選手が再現しても面白くないはずで、大切なのは観客との結びつきと物語だという。技がすごいだけでは足りず、それ以上のものがあると考えているそうだ。批判する人もいるかもしれないと笑いながら語っている。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（27:54〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1674s"]]}, {"cat": "リングの話", "t": "WWEを去った日の一言", "b": "マット・カードナは、最後の日にタレント担当の人から「来週また」と言われ、大声で「いや、来ない」と返したと話す。そのまま会場を後にして、翌週は姿を見せなかったという。この日の相手がコーディ・ローズだったことが面白いと振り返っている。ライブイベントで組まれていたサミ・ゼインが代わりに試合をする羽目になった、という話も出た。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（43:48〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2628s"]]}, {"cat": "リングの話", "t": "復帰は当然、でも軽くは見ない", "b": "マット・カードナは、WWEに戻れたことは大きな成果だが、同時に戻るべくして戻った気もすると話す。「ふさわしい」とまでは言いたくないが、戻る機会は自分でつかんだものだと考えているそうだ。この機会を軽く受け止めず、どんな出番でも常に準備して全力を出すつもりだという。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（58:58〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3538s"]]}, {"cat": "リングの話", "t": "インディー時代の顔はまだ見せていない", "b": "マット・カードナは、復帰後のファンはまだインディー時代の自分を見ていないと話す。握手をして回るような優しい人物ではなかったといい、時が来ればその姿をWWEでも見せたいと考えているそうだ。デスマッチ王やインディーの王といった過去は一つの区切りで、今は次の形へ変わっていく途中だと語っている。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（59:48〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3588s"]]}, {"cat": "リングの話", "t": "大舞台のラダー戦に父が飛び込んだ", "b": "マット・カードナは、父は初めてのインディー大会でビデオカメラを構えていたほど、いつも応援してくれていたと話す。年間最大の祭典のラダー戦で勝った瞬間、父が柵を飛び越えて客席から駆け寄り、帽子を頭にかぶせてくれたという。本人は「それを外せ」と照れたが、キャリア最高の瞬間だったと振り返る。解雇されたときもその写真を見て、大丈夫だと思えたそうだ。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:07:42〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4062s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Matt Cardona")) ROSTER.push(["マット・カードナ", "Matt Cardona", "lg", "インディーから復帰した元王者", "", "", ""]);
  if (!PROFILES["Matt Cardona"]) PROFILES["Matt Cardona"] = { lead: "解雇をきっかけに自分を探し直し、インディーで自腹を切って派手に打って出た努力家。テーマパークとフィギュアをこよなく愛し、妻チェルシーと犬猫6匹とにぎやかに暮らす。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Matt%20Cardona"]], moves: [], facts: [] };
  if (PROFILES["Matt Cardona"]._weak) { PROFILES["Matt Cardona"].lead = "解雇をきっかけに自分を探し直し、インディーで自腹を切って派手に打って出た努力家。テーマパークとフィギュアをこよなく愛し、妻チェルシーと犬猫6匹とにぎやかに暮らす。"; delete PROFILES["Matt Cardona"]._weak; }
  PROFILES["Matt Cardona"].facts.push(...[{"cat": "暮らし", "t": "インディーでもスーツ姿で会場入り", "b": "会場にはスーツで入るのが流儀だという。インディーの会場でスーツを着ていると、それだけで『何か知っている人』に見られるそうだ。スターらしく振る舞うことが大事だと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（2:23〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=143s"]]}, {"cat": "好きなもの", "t": "テーマパークは絶叫より世界観", "b": "ジェットコースター目当てのタイプではなく、作り込まれた世界に浸れることを重視するという。日常から逃れるために行くのだから、駐車場が見えるような興ざめは避けたいそうだ。ディズニーでは座って休むより、乗り物を全部回りたい派だと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（7:14〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=434s"]]}, {"cat": "リングに来るまで", "t": "復帰の糸口は妻がくれた電話番号", "b": "他団体で活動していた時期、妻チェルシー・グリーンが取材の場で団体幹部のニック・カーンと話し、夫の連絡先を渡したという。番号を受け取るとすぐにメッセージを送り、電話で『戻りたい』と伝えたところから話が動いたそうだ。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（12:52〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=772s"]]}, {"cat": "暮らし", "t": "毎日頭の中で目標を並べる", "b": "子どものころからの夢はWWE王者で、いまも毎日頭の中で目標を順に並べているという。離れていた約5年半は、鏡の前で自分に『やめるな』と言い聞かせてきたそうだ。若い選手に贈る助言も同じで、やめなければ届くかもしれないが、やめたら届かないと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（14:30〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=870s"]]}, {"cat": "リングに来るまで", "t": "解雇で肩の荷が下りた", "b": "解雇はコロナ禍の始まりで、出られるインディー興行すらない時期だった。前年に長期契約を受けず、残るか去るかで1年間不安を抱えていたため、解雇は決断を代わりに下してくれたようで肩の荷が下りたという。旧リングネーム時代に感謝しつつ、本当の自分を探しに出る必要があったと振り返る。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（16:54〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1014s"]]}, {"cat": "リングに来るまで", "t": "デスマッチ王を名乗るも経験は1試合", "b": "インディーでは『WWE帰りの男』として嫌われる役を徹底したという。デスマッチ王と名乗っているが、実際にやったのは1試合だけで、サイン会でいまも『あのデスマッチ全部好き』と言われるそうだ。獲った王座のベルトは回転式に作り替え、大きな興行は毎回年間最大の祭典のつもりで臨んだと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（19:15〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1155s"]]}, {"cat": "リングに来るまで", "t": "人生を変えたニック・ゲイジ戦", "b": "インディーに出て数か月、自分が何者かも分からない時期に、ニック・ゲイジとのデスマッチに挑んだ。話題になるとは思っていたが、その夜はネットで五輪を上回るほど注目され、キャリアも人生も変わったという。血で汚れるのを見越して白いシャツで臨み、後悔した日は一日もないそうだ。再戦は相手と物語と条件がそろえば、と話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（20:55〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1255s"]]}, {"cat": "暮らし", "t": "物販の現金をポーチに入れる快感", "b": "インディー時代は毎年どうやって前年を超えるかに悩みつつ、その奮闘自体が楽しかったという。WWEに戻って唯一恋しいのは、物販の荷物を自分で運ぶことだそうだ。現金をウエストポーチにしまう瞬間は最高だと笑いつつ、本当に大事なのはファンと顔を合わせてつながることだと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（24:49〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=1489s"]]}, {"cat": "体のこと", "t": "ジムと日焼けは日課", "b": "ジムに行き、日焼けをし、早めに会場に入り、身なりを整えるのが基本だという。試合が少ない週でもメインイベントに出るつもりで、新しいコスチュームと仕上がった体で現れるそうだ。ジム通いはトイレに行くのと同じくらい当たり前の日課だと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（33:31〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2011s"]]}, {"cat": "家族", "t": "大みそかのパーティー兼結婚式", "b": "チェルシーとの結婚式は、大みそかのパーティーに結婚式がくっついたような催しだったという。会場は元ナイトクラブで、来場者には記念の靴下が配られたそうだ。誓いの言葉ではコーディ夫妻への感謝も述べたと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（47:45〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2865s"]]}, {"cat": "家族", "t": "妻との出会いはコーディ夫妻の紹介", "b": "2017年にひざを大けがし、オーランドへ越したころ、コーディとブランディに食事の席で他団体の女子選手の話を聞いたという。当時は選手と付き合うつもりはなかったが、1回、2回とデートを重ねるうちに一緒に暮らすようになったそうだ。出会いのきっかけをくれた2人に感謝していると話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（48:31〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2911s"]]}, {"cat": "家族", "t": "新居で犬3匹と猫3匹", "b": "いまは新しい家で、犬3匹と猫3匹と暮らしているという。最初の猫の名前はカイロだそうだ。子どもについては、いつかは、でもまだ先と話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（49:17〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2957s"]]}, {"cat": "家族", "t": "夫婦同室、背中の日焼けは妻の担当", "b": "巡業では夫婦で同じ部屋に泊まっているという。夜の日焼けの際は、背中をチェルシーに手伝ってもらうと楽なのだそうだ。家では皿洗いを担当していると話す。インディー時代は互いに忙しくてほとんど会えなかったが、いまは一緒に忙しくできるのがうれしいという。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（54:58〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3298s"]]}, {"cat": "暮らし", "t": "21歳で出会ったコーディとは10年不仲", "b": "コーディとは21歳で出会い、2人とも40歳になったという。最初の約10年は互いに好きではなかったが、どちらもテーマパーク好きだと分かって打ち解けたそうだ。頭は常に次の番組や物販のことを考えていて止まらない性分だと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:00:37〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3637s"]]}, {"cat": "リングに来るまで", "t": "自主制作の動画番組で首をつないだ", "b": "WWE在籍中、撮影から脚本、編集まで自分で手がけたネット番組を約100回続けたという。目的は動画を作ることではなく、ファンと自分をつなぐことだったそうだ。あの番組がなければ2011年ごろに解雇されていただろうと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:05:21〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3921s"]]}, {"cat": "家族", "t": "最初の試合を撮ってくれた父", "b": "物心ついたときの記憶はすべてプロレス絡みで、両親は応援してくれたという。父は最初のインディー戦でビデオカメラを回していたそうだ。年間最大の祭典のはしご戦で王座を獲った夜には、顔なじみの警備員に止められずに柵を越えてリングまで来て、自分に記念のカウボーイハットをかぶせたという。解雇されたとき、その写真を見て『きっと大丈夫』と思えたと話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:07:42〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4062s"]]}, {"cat": "好きなもの", "t": "少年時代のヒーローはレイザー・ラモン", "b": "地元ロングアイランドの会場やニューヨークの大会場に通って育ったという。ハルク・ホーガンやランディ・サベージも好きだったが、一番はレイザー・ラモンだったそうだ。少年時代に王座を持たせてもらった写真と、自分が同じ王座を獲った後に彼と撮った写真を、2枚とも仕事部屋に飾っていると話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:09:20〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4160s"]]}, {"cat": "好きなもの", "t": "フィギュア収集と自前の玩具会社", "b": "子どものころからフィギュアが大好きで、未発売に終わったグレッグ・バレンタインの人形を、広告写真に使われた実物ごと持っているという。欲しいものはほぼそろったが、まだ知らない試作品があるかもしれないと話す。自分の玩具会社も持ち、インディー時代はコスチュームと新作フィギュアの発売を何か月も前から合わせて計画していたそうだ。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:10:08〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4208s"]]}, {"cat": "好きなもの", "t": "スター・ウォーズは1作目と7作目", "b": "スター・ウォーズの大ファンで、ディズニーの宿泊型体験『ギャラクティック・スター・クルーザー』にも行ったという。好きな作品の上位は1作目と『フォースの覚醒』で、8作目と9作目は最下位だそうだ。カイロ・レンのライトセーバーも手元にあると話す。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:14:51〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4491s"]]}, {"cat": "リングに来るまで", "t": "初日からの相棒ブライアン・マイヤーズ", "b": "自分に欠かせない仲間の一番目には妻チェルシーを挙げ、続いてブライアン・マイヤーズを『初日から』の相棒として挙げたという。地元の養成所時代からタッグ王座、ポッドキャスト、玩具会社までずっと一緒だそうだ。ほかにニック・ネメス、ミズ、コーディの名も挙げた。自分は返信がひどく遅いほうだと認めている。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:19:35〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4775s"]]}]);
  if (PROFILES["Chelsea Green"]) PROFILES["Chelsea Green"].facts.push({"cat": "暮らし", "t": "巡業ではとにかく忙しい妻", "b": "復帰戦の後、コーディのバスで祝杯をあげていると、チェルシーがドアから『もう行くよ』と呼びに来て、ゆっくり飲めなかったという。同じ部屋に泊まっていても生活の予定が違うほど多忙で、取材の仕事もいつも抱えていると、マット・カードナが話している。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で、マット・カードナの話（公式字幕を全文確認）", "src": [["公式YouTube（54:58〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3298s"]], "by": "第三者の話"});
  if (PROFILES["Kit Wilson"]) PROFILES["Kit Wilson"].facts.push({"cat": "暮らし", "t": "人一倍努力するキット・ウィルソン", "b": "キット・ウィルソンは若いころから人一倍熱心で、資料を作り込み、ジムに通い、食事にも気を使う生粋のプロレスラーだと、マット・カードナが話している。", "sp": "マット・カードナ", "d": "2026-03-26", "how": "コーディの番組で、マット・カードナの話（公式字幕を全文確認）", "src": [["公式YouTube（1:21:15〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4875s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "暮らし", "t": "「いつも役のまま？」が今も刺さる", "b": "以前インタビューで『いつも役に入っているのか』と聞かれ、自分でも分からず胸が痛んだという。試合や興行のことを考えずにいられない自分に、いまもつきまとう問いだそうだ。それでも、自分が何者かを以前よりずっと自覚できるようになったと話す。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（36:38〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=2198s"]]}, {"cat": "家族", "t": "子どもができて早起きに", "b": "子どもが生まれて生活のリズムが変わり、朝早く起きるようになったという。4歳の娘リバティはヨーダを知らず、グローグーしか分からないそうだ。娘にとってヨーダは『年を取ったグローグー』なのだと笑う。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（56:38〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3398s"]]}, {"cat": "暮らし", "t": "テーマパークのそばに住み、エアバスケ", "b": "テーマパークのすぐ近くに住み、思い立つと友人に『いまから行く』と声をかけるという。ハロウィーンのイベントの特別ツアーにも参加しているそうだ。知り合いに手で輪を作って『シュートしてみて』と促す、空気のバスケットボールがお約束の遊びだと話す。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（58:11〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=3491s"]]}, {"cat": "家族", "t": "父ダスティの試作フィギュアを飾る", "b": "マットから父ダスティ・ローデスのフィギュアの試作品を贈られ、父ゆかりの品のそばに飾っているという。自分では欲しいと思っていなかった物が、届くとうれしいのだそうだ。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:10:56〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4256s"]]}, {"cat": "家族", "t": "妻ブランディの店に選手フィギュア", "b": "妻ブランディがロズウェルで営む店では、玩具メーカーを通じて正式に選手のフィギュアを仕入れたという。店頭にエグゼビア・ウッズやティファニー・ストラットンの人形が並ぶのを見て、不思議な気分になったそうだ。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:11:45〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4305s"]]}, {"cat": "好きなもの", "t": "『最後のジェダイ』派で新しもの好き", "b": "スター・ウォーズでは『最後のジェダイ』が大好きだという。テーマパークについても思い出より刷新を望むほうで、古いアトラクションは取り壊して新しいものを入れてほしい派だそうだ。ただ、時代を超えて残るべきものもあると認めている。", "sp": "コーディ・ローデス", "d": "2026-03-26", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-JYa2G09QeSU", "src": [["公式YouTube（1:15:42〜）", "https://www.youtube.com/watch?v=JYa2G09QeSU&t=4542s"]]}]);
  ARTICLES.push({ id: "wdywta-JYa2G09QeSU", d: "2026-03-26", show: "wdywta", who: ["Matt Cardona", "Cody Rhodes"], t: "マット・カードナの回　デスマッチ、復帰、チェルシーとの暮らし", lead: "コーディ・ローデスの番組に出た約85分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Matt Cardona", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-JYa2G09QeSU").map((x) => [x.t, x.b, x.sp])), open: ["コーディとの掛け合い（おごる・おごらない、身長、子ども好きかなど）は冗談の応酬で真偽が判別しにくいため、載せていない。", "デスマッチの話は要点のみとし、凶器や流血の描写は省いた。結婚式に出席した一般の友人の名前も省いている。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=JYa2G09QeSU"]] });
  if (!ROSTER.find((r) => r[1] === "Drew McIntyre")) ROSTER.push(["ドリュー・マッキンタイア", "Drew McIntyre", "lg", "元WWE王者", "", "", ""]);
  if (!PROFILES["Drew McIntyre"]) PROFILES["Drew McIntyre"] = { lead: "約25年のキャリアを、食事と柔軟性の見直しで立て直した選手。故郷への誇りと妻や愛猫への思いを、率直に語る回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Drew%20McIntyre"]], moves: [], facts: [] };
  if (PROFILES["Drew McIntyre"]._weak) { PROFILES["Drew McIntyre"].lead = "約25年のキャリアを、食事と柔軟性の見直しで立て直した選手。故郷への誇りと妻や愛猫への思いを、率直に語る回。"; delete PROFILES["Drew McIntyre"]._weak; }
  PROFILES["Drew McIntyre"].facts.push(...[{"cat": "暮らし", "t": "スタバはナイトロコールドブリュー", "b": "ドリュー・マッキンタイアの定番は、アーモンドミルクを入れたナイトロコールドブリューだという。ホテルでは配達アプリをよく使い、注文名には偽の名前「ジョン」を使っていると話す。名前を呼ばれてもつい自分だと気づかないことがあるそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:43〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=103s"]]}, {"cat": "好きなもの", "t": "甘いものは苦手なのにクッキーにはまる", "b": "もともと甘党ではないが、シェイマスに勧められてコールドブリューとクッキーにはまったという。昔の遠征でシェイマスに毎晩のように勧められ、気づけば週に3、4回食べていたと笑って話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（2:31〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=151s"]]}, {"cat": "体のこと", "t": "初めての5週間の休みで自分を見つめ直した", "b": "約9か月前、人生で初めて5週間の休みを取れたと話す。学校からそのまま大手団体に入り、解雇後すぐに現場へ戻ったため、けがもリハビリもない休みは初めてだった。40歳が近く、体のあちこちが痛み始めていたので、自分の体を点検しようと決めたそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（3:19〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=199s"]]}, {"cat": "体のこと", "t": "食事と柔軟性を見直した", "b": "それまでは食事の管理をせず、ハンバーガーやピザばかりで、1日2回の日も8回の日もあったという。自宅のガレージに来てくれるトレーナーをつけ、食事と可動域のトレーニングを始めた。股関節が固く、ハイキックが物理的にできない状態だったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（4:09〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=249s"]]}, {"cat": "体のこと", "t": "関節の可動域を広げて30歳の頃より調子がいい", "b": "股関節、ひざ、肩の可動域を広げるストレッチを続け、故障を治すより防ぐ準備を重視するようになったという。食事の見直しで炎症も大きく減り、顔の高さまで足が上がるようになった。今は30歳の頃より、いや28歳くらいの頃より調子がいいと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（5:50〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=350s"]]}, {"cat": "暮らし", "t": "引退はまだ先、妻は短いと思っている", "b": "いつまで続けるかについて、妻はもっと短いと思っているようだと話す。それでも自分が幸せで、妻も幸せで、ファンが喜んでくれるなら、スローダウンする理由はないという。同い年のレブロン・ジェームズやロナウドが今も第一線にいることも励みになっているそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（6:37〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=397s"]]}, {"cat": "リングの話", "t": "仕事の失望と、いちばん怖い「静けさ」", "b": "役柄にとって有利なら、個人としてがっかりしても仕事としては納得できるようになったという。レスラーにとって最悪なのは観客が静まり返ることだと語る。初めての大舞台の試合は、直前の大一番の後で、入場しても針の落ちる音が聞こえるほどの静けさだったそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（7:24〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=444s"]]}, {"cat": "リングの話", "t": "「悪者」と呼ばれても論戦なら負けない", "b": "自分は真実を語っているから、自分の中ではいい者のつもりだと話す。タイトルを手にした今、挑発されて戦う理由がなければ背を向けるのは論理的だという。ファンは新しい人気者に乗り換えたと語り、観客との関係を、浮気をされ続けても戻ってしまう関係にたとえた。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（9:01〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=541s"]]}, {"cat": "リングの話", "t": "故郷スコットランドで王座を掲げた夜", "b": "ベルリンで王座を獲った翌日に、故郷グラスゴーの興行へチャンピオンとして初めて登場できたという。家族も会場にいて、約束どおり王座を持ち帰ったと観客に伝えられたそうだ。スコットランド人として初の快挙という点を含め、これ以上ない台本だったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（14:47〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=887s"]]}, {"cat": "リングの話", "t": "浮き沈みの末につかんだ手応え", "b": "キャリアは山と谷の繰り返しだったと話す。トップの一員になれたと感じたのは、年間最大級の大会の前哨戦で、強豪ブロック・レスナーを大乱戦で排除したときの大歓声だったという。観客が本気で信じてくれていると肌で感じた瞬間で、そこから優勝までの流れも自然に盛り上がったと振り返る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（16:26〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=986s"]]}, {"cat": "リングの話", "t": "宿敵CMパンクとの抗争と地獄の金網戦", "b": "CMパンクとの抗争が、自分が試合だけでなく語りと物語もできる選手だと示してくれたと話す。仲は悪くても、リングでは魔法のような相性になるという。金網戦では額から血が噴き出し、試合を止められないよう意識を保つのに必死だったそうだ。17針を縫ったが、子どもの頃に憧れた血まみれの名勝負をやれた自分の最高傑作だと語る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（17:59〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=1079s"]]}, {"cat": "体のこと", "t": "金網戦で背中と首を痛めかけた過去", "b": "金網戦ではこれまで負け続けていて、まだ勝ったことがないと明かす。ランディ・オートンとの試合では金網の途中から落ち、背中や首を折ったと思ったほどだったという。舌を噛み切って血を吐き、無観客の時期だったので誰にも見られなかったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（20:23〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=1223s"]]}, {"cat": "リングに来るまで", "t": "十代で出会ったニック・アルディスの体格", "b": "十代の頃に初めて見たニック・アルディスは自分より筋肉質で、自分も体を作らなければと思ったという。当時は大学生でお金がなく、飲み歩いて遊んでいる日々で、もともと背が高く細身だったそうだ。シェイマスと知り合ったのもその頃で、それから22年ほど経つと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（28:24〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=1704s"]]}, {"cat": "リングの話", "t": "無観客の年に大舞台のメインを飾った", "b": "年間最大の祭典が第二の故郷タンパで開かれ、家族や友人も来る予定だったのに、世の中が止まって観客が入れなくなったという。それでも不安な人々の逃げ場になれればと、カメラ越しにこれまで支えてくれた人へ感謝を伝えたそうだ。ブロックを倒した試合では、彼が自分を強く見せてくれたことにも感謝していると話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（29:16〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=1756s"]]}, {"cat": "暮らし", "t": "SNSでの毒舌は英国流ユーモア", "b": "SNSでの強気な発言は、英国人の友人とのやりとりから生まれているという。ネットで皮肉を言うだけの人とは違い、画面の外でも負けないと冗談めかす。周りの選手からも、あなたには言い返したくないと言われるほどだそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（34:52〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2092s"]]}, {"cat": "リングに来るまで", "t": "独立系での活動が語りの自信を作った", "b": "最初の団体を解雇された後の2014年から17年が転機だったという。インディーで主要な試合を重ね、マイクを持つ回数を増やして自分の声を見つけたと話す。以前は決まりごとにとらわれ、人に気をつかう内気な性格だったため、帰還して20分語った場面を妻に不安を打ち明けながら準備したそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（37:26〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2246s"]]}, {"cat": "暮らし", "t": "3MBの仲間たちと結婚式で再会", "b": "昔のユニット仲間の結婚式に招かれて、久しぶりに集まったと話す。宗教の違う二人が一つにまとまった、色鮮やかで映画のような式だったという。若い頃は悩みも多かった仲間が幸せそうな姿を見て、自分も嬉しくなったそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（39:01〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2341s"]]}, {"cat": "暮らし", "t": "長年、重荷を背負っていた気持ちが軽くなった", "b": "長い間、世界の重みを背負っていた気がすると話す。今も時々そうなるが、若い頃ほど小さなことを大きく考えなくなったという。人生は短いのだから、幸せなうちに楽しむべきだと語る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（40:40〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2440s"]]}, {"cat": "暮らし", "t": "ナッシュビルへの引っ越しはシェイマスのせい", "b": "もともとは引っ越したくなかったが、シェイマスが妻の気持ちをうまく動かしてナッシュビル行きが決まったという。ハロウィンやクリスマスに招かれ、街の良さを見せられたのがきっかけだと笑う。ここに来る前はタンパ近郊に長く住んでいて、ジムや日課も整っていたそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（41:25〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2485s"]]}, {"cat": "暮らし", "t": "猫を連れたキャンピングカーでの大騒動", "b": "猫の体調を考えて、引っ越しにはキャンピングカーを借りたという。運転経験がないまま走り出し、ガソリンスタンドの柱に擦って火花を散らし、タイヤまで傷めてしまったと話す。夜は治安の悪い場所で足止めされ、妻は猫を抱いて怖がっていたそうだ。本人は何度も居眠りしかけたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（42:12〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2532s"]]}, {"cat": "暮らし", "t": "妻のおかげで仕事のオンオフを切り替える", "b": "アレルギーがひどくて倒れそうでも、プロレスの話をするだけで元気になれるほど好きな仕事だと話す。同時に、家に帰ったら仕事を切り離すことを教えてくれたのは妻で、そのおかげでバランスが取れたと感謝している。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（44:41〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2681s"]]}, {"cat": "暮らし", "t": "映画でバティスタと共演", "b": "前に出た映画ではバティスタと共演し、スコットランド訛りの大男という役柄だったという。監督が兄弟の殺し屋のアイデアを出したとき、バティスタが自分を推薦してくれたと話す。自分から仕事を探すタイプではなく、来た話を受けるやり方だそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（45:28〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2728s"]]}, {"cat": "リングの話", "t": "憧れだったカート・アングルから勝利", "b": "カート・アングルを足首固めで降参させる試合を、大会で2度行ったと話す。カートはかつて別団体でも自分を作るために同じ展開を受けてくれた恩人で、手の込んだ見せ方で自分を押し上げてくれたという。人の家族をけなす悪役を演じ、とことん憎まれ役になったと振り返る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（48:41〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2921s"]]}, {"cat": "リングの話", "t": "大型選手コービンの必殺技を返した試合", "b": "当時売り出し中だった敵役コービンの必殺技を、初めて返した選手になったと話す。大一番に向けて、自分を強く見せるための決定的な場面が必要だったという。相手は技を守ってほしいと望んでいたが、会社の判断なので受け入れたそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（50:15〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=3015s"]]}, {"cat": "リングの話", "t": "アンダーテイカーの最後の観客前の試合", "b": "自分は若い頃、アンダーテイカーのそばで多くを学んだと話す。その彼の最後の観客前の試合に出られたことを今も驚きだと語る。入場の際に自分がカメラの前に立ってしまい、気づいて慌ててどいたという失敗談もあり、完璧でないところも本物らしさだと笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（58:28〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=3508s"]]}, {"cat": "リングに来るまで", "t": "2010年にコーディと王座を獲った頃の自惚れ", "b": "2010年にコーディ・ローズとタッグ王座を獲ったとき、二人ともすぐ世界王座を狙えると思い込んでいたという。写真を見返すと恥ずかしいほど自惚れていたと笑う。その後それぞれ大きな挫折と解雇を経験し、遠回りして今の成功にたどり着いたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:02:24〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=3744s"]]}, {"cat": "好きなもの", "t": "ジョーダンのスニーカーにはまった経緯", "b": "ジョーダンは足が大きくて幅広な自分にとって履きやすいから選んだという。イベントで履いていた種類が違うとSNSで大量に指摘され、恥をかいたと笑う。それをきっかけに店で教わり、今は四番や三番のモデルをよく履いていると話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:05:30〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=3930s"]]}, {"cat": "リングの話", "t": "自分が誇れる、あまり語られない試合", "b": "パンデミックの時期に観客が少なかった大会の前に、シェイマスと戦った試合が自慢だと話す。20年来の付き合いを紹介する映像が流れ、驚いたという。顔に戦いの化粧をし、思い切り殴り合い、後に大舞台の三つ巴戦で念願の一騎打ちも実現したと語る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:07:58〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=4078s"]]}, {"cat": "暮らし", "t": "長年の愛猫チャズとの別れ", "b": "家族の猫チャズを亡くしたと明かし、長い肝臓の病気を抱えていたという。最期は家で看取ったが、とてもつらかったと話す。SNSには投稿できず、番組が初めて語る場だそうだ。妻の心の支えとして14年間そばにいた存在で、動物は愛情そのものだと語る。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:12:00〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=4320s"]]}, {"cat": "暮らし", "t": "寝る前に妻と感謝を3つ言う習慣", "b": "妻と二人で、寝る前に感謝していることを3つ声に出して言う習慣があるという。この日挙げたのは、妻、健康、そしてチャズとの思い出だったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-2lGH7281JjM", "src": [["番組のYouTube（1:13:36〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=4416s"]]}]);
  if (PROFILES["Sheamus"]) PROFILES["Sheamus"].facts.push({"cat": "暮らし", "t": "ナッシュビルへ友人を誘い込んだ", "b": "引っ越したがらなかった友人を、ハロウィンやクリスマスに招いて根気よく説得したのがシェイマスだと、ドリュー・マッキンタイアが話している。シェイマスが甘いものを勧める名人でもあるそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で、ドリュー・マッキンタイアの話（字幕を全文確認）", "src": [["番組のYouTube（41:25〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2485s"]], "by": "第三者の話"});
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "人を選ぶが、認めた相手は引き立てる", "b": "ブロック・レスナーは人付き合いが得意ではないが、真剣にやる人だと分かれば相手を引き立ててくれると、ドリュー・マッキンタイアが話している。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で、ドリュー・マッキンタイアの話（字幕を全文確認）", "src": [["番組のYouTube（31:39〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=1899s"]], "by": "第三者の話"});
  if (PROFILES["Kurt Angle"]) PROFILES["Kurt Angle"].facts.push({"cat": "暮らし", "t": "恩人として自分を押し上げてくれた", "b": "カート・アングルは、別団体の頃から自分を押し上げるため、あえて降参する役を受けてくれた恩人だと、ドリュー・マッキンタイアが話している。", "sp": "ドリュー・マッキンタイア", "d": "2026-04-02", "how": "クリス・ヴァン・ヴリートの番組で、ドリュー・マッキンタイアの話（字幕を全文確認）", "src": [["番組のYouTube（48:41〜）", "https://www.youtube.com/watch?v=2lGH7281JjM&t=2921s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-2lGH7281JjM", d: "2026-04-02", show: "ext", who: ["Drew McIntyre"], t: "ドリュー・マッキンタイアの回　体づくり、故郷、愛猫との別れ", lead: "クリス・ヴァン・ヴリートの番組に出た約75分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Drew McIntyre"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-2lGH7281JjM").map((x) => [x.t, x.b, x.sp])), open: ["信仰については触れていない。", "金網戦のくだりなど一部の試合の話は、字幕の崩れから細部を省いた。", "聞き手の宣伝や広告読み上げは除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=2lGH7281JjM"]] });
  if (!ROSTER.find((r) => r[1] === "The Cavinder Twins")) ROSTER.push(["キャビンダー・ツインズ", "The Cavinder Twins", "lg", "元大学バスケの人気双子", "", "", ""]);
  if (!PROFILES["The Cavinder Twins"]) PROFILES["The Cavinder Twins"] = { lead: "ヘイリーとハンナは、五人姉妹の中でただ二組の双子で、大学バスケから発信ビジネスまで常に一緒に歩んできた。競い合いながら支え合うふたりの素顔が語られる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=The%20Cavinder%20Twins"]], moves: [], facts: [] };
  if (PROFILES["The Cavinder Twins"]._weak) { PROFILES["The Cavinder Twins"].lead = "ヘイリーとハンナは、五人姉妹の中でただ二組の双子で、大学バスケから発信ビジネスまで常に一緒に歩んできた。競い合いながら支え合うふたりの素顔が語られる。"; delete PROFILES["The Cavinder Twins"]._weak; }
  PROFILES["The Cavinder Twins"].facts.push(...[{"cat": "暮らし", "t": "ラスベガスで姉妹の1対1対決", "b": "ふたりは賭けの会社と契約し、4月上旬の週末にラスベガスで1対1の試合をするという。去年の3月以来ボールに触っておらず、ヘイリーとハンナは「練習しなきゃ」と話す。どちらも相手の動きを知り尽くしていると言い、ふたりとも自分が勝つつもりでいるそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（0:47〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=47s"]]}, {"cat": "家族", "t": "一番の応援者で一番の競争相手", "b": "ふたりは互いの最大の支えであり、最大の刺激でもあるという。相手がジムに先に来ていると「追いつかなきゃ」と思うそうだ。行き過ぎて口論になることもあるが、その責任感が成功の理由だと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（2:21〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=141s"]]}, {"cat": "家族", "t": "五人姉妹で育ち、今は親友同士", "b": "姉妹は年が近く、小さいころは服の貸し借りでよくけんかをしたという。今は全員が親友で、ハンナは姉妹の近くに住んでいる。ヘイリーはテキサスに住んでいて、家族の食事会に出られず寂しいと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（3:52〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=232s"]]}, {"cat": "家族", "t": "毎週日曜は祖母に電話", "b": "母方の祖母はミシガン州の小さな町に住んでいて、ふたりは毎週日曜に電話をかけているという。祖母の家には日曜に家族が集まる習慣があり、毎年7月4日の祝日にもみんなで帰るそうだ。もう一組の祖父母はフロリダのネイプルズに住み、そちらにはよく会いに行くという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（4:42〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=282s"]]}, {"cat": "家族", "t": "祖父の教えは「今この瞬間にいなさい」", "b": "ヘイリーは、いつも時速160キロで走っている自分たちに、祖父が「立ち止まってゆっくりしなさい」と言うと話す。次は何か、と考えてばかりの自分には大事な言葉だという。祖父母からは、成功は仕事だけでなく愛や暮らしの中にもあると教わったそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（5:29〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=329s"]]}, {"cat": "暮らし", "t": "スマホとの距離の取り方", "b": "ふたりにとって発信は仕事なので、いつもどう収益につなげるかを考えてしまうという。そこで朝は起きてから30分スマホを見ず、夜8時以降は見ないと決めているそうだ。ハンナは時間を区切って使い、アプリの使用時間制限も設定していると話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（7:11〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=431s"]]}, {"cat": "リングに来るまで", "t": "動画の始まりはコロナ中のドリブル", "b": "父が事業をしていたため、ふたりは小さいころから仕事の考え方を身近に見ていたという。発信を始めたのは、コロナ禍の暇つぶしにコートでリズムに合わせてドリブルした動画からで、お金のためではなかったそうだ。その後、大学生が収入を得られる制度が始まる7月1日をきっかけに、収益化を考え始めたと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（8:45〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=525s"]]}, {"cat": "暮らし", "t": "父の言葉は「4年でなく40年の計画」", "b": "収入が入り始めたころ、父から早めに貯めて投資するように言われたという。「4年の計画ではなく40年の計画」というのが父の言葉だそうだ。ふたりは、大学生が投資や税金を学べる授業が必要で、高校でもお金の基礎を教えるべきだと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（12:41〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=761s"]]}, {"cat": "暮らし", "t": "朝の日記で感謝を書き出す", "b": "ふたりは早起きで、朝は穏やかに過ごす「低コルチゾールの朝」を大切にしているという。日記には感謝することを5つ書き、その日の肯定の言葉をひとつ書くそうだ。夜の習慣は崩れがちで、メラトニンを2錠飲んで寝てしまうと笑う。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（15:51〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=951s"]]}, {"cat": "家族", "t": "婚約者ジェイクとの出会い", "b": "ヘイリーは、婚約者のジェイクがインスタグラムのDMで連絡をくれたのが出会いだと話す。マイアミ大学を卒業してすぐの夏で、会ってから10日ほど続けて一緒に過ごし、7月4日の祝日も祝ったそうだ。のちに出会った場所でプロポーズされ、6月に結婚する予定だという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（20:41〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1241s"]]}, {"cat": "家族", "t": "ジェイクはWWEの大ファン", "b": "ジェイクは子どものころ、父親に連れられてWWEの試合を見に行った経験があるという。ヘイリーがWWEの訓練施設を訪ねたときは、いろいろ質問してきたそうだ。リングに上がることにも全面的に賛成で、「やらせよう」という立場だという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（23:04〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1384s"]]}, {"cat": "リングの話", "t": "WWEの大学生向け制度で縁ができた", "b": "ふたりは1年半ほど前にWWEの大学生向け契約制度に署名したという。年間最大級の夏の大会をナッシュビルで見て夢中になり、訓練施設を見学して人に会ったそうだ。ただ、そのときは実際にリングには立てなかったと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（23:04〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1384s"]]}, {"cat": "リングの話", "t": "ベラ・ツインズが憧れの先輩", "b": "ふたりは、ベラ・ツインズがいつも連絡をくれて助けてくれると話す。双子ならではの悩みも含めて相談しているそうだ。ふたりにとっては「設計図」になる存在で、最近ブリーが復帰したのも嬉しいという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（23:51〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1431s"]]}, {"cat": "リングの話", "t": "WWE入りがまだ実現していない理由", "b": "ふたりは、バスケに戻ったり他の事業に手を広げたりと忙しく、WWEの話が自然に止まっていたと説明する。今は時間にも余裕があり、結婚を控えたヘイリーも含めて、前向きに考えているそうだ。エンターテインメントで、競争もあるWWEは自分たちにぴったりだと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（25:31〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1531s"]]}, {"cat": "リングの話", "t": "スマックダウンでの入場を振り返る", "b": "ふたりは、以前スマックダウンで入場した場面を見返して、まあまあだったが「もっとできる」と話す。初めてで緊張もあったという。ふたりで入場の動きを考えたことも思い出し、また再現したいと笑う。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（30:26〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1826s"]]}, {"cat": "リングの話", "t": "悪役か善玉か、まだ決めていない", "b": "ふたりは、タッグ名も含めてこれからだと話す。善玉と悪役のどちらが合うかは「感じながら決めたい」と言い、観客を予想させないほうがいいと考えているそうだ。やるなら存在感を残して、勢いよく入りたいという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（31:12〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=1872s"]]}, {"cat": "リングに来るまで", "t": "幼いころからあらゆるスポーツ", "b": "両親はふたりを水泳、ホッケー、体操など何でもやらせたという。父がホッケーファンで、ふたりは5歳ごろからプールでバック転をしていたそうだ。家族でセルティックスを応援し、ヘイリーはレイ・アレンとロンドに、ハンナはポール・ピアースに憧れたと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（35:13〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2113s"]]}, {"cat": "リングに来るまで", "t": "双子で奨学金をつかむと決めた", "b": "ふたりは小柄なガードで、あまり注目されなかったという。それでも「一緒にプレーする」ことを最優先に、ずっと練習を重ねたそうだ。高校1年のときにサンディエゴ大学から最初の誘いを受け、そのために学校の行事を断ったこともあると話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（36:00〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2160s"]]}, {"cat": "リングに来るまで", "t": "フレズノ州立からマイアミ大学へ", "b": "ふたりは最初の3年をカリフォルニアのフレズノ州立大学で過ごしたという。小さな大学では全国大会に出るハードルが高く、移籍制度を使ってマイアミ大学へ移ったそうだ。ヘイリーはマイアミの環境や指導に惚れ込み、最初は乗り気でなかったハンナを説得したと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（37:35〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2255s"]]}, {"cat": "リングに来るまで", "t": "ハンナが引退を悩み、5年目に戻った", "b": "マイアミでは出場時間の多いヘイリーに対し、ハンナは控えに回ることが多く、競争心の強いハンナにはつらい時期だったという。ふたりは4年で区切るつもりだったが、2カ月ほどたってハンナは、後悔するかもしれないと感じ、5年目を決意したそうだ。一時はテキサスの大学も考えたが、最終的にふたりそろってマイアミに戻ったと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（38:20〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2300s"]]}, {"cat": "リングに来るまで", "t": "一番厳しかったコーチのフィッツ", "b": "ヘイリーは、大学時代に最も大きな影響を受けたのはフィッツコーチだと話す。気分に関係なく毎日やり切ることを求められ、自分でも気づかなかった限界まで押されたという。今も毎週のように連絡を取る恩師で、ハンナも先発でなくても同じ基準を求められたと振り返る。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（41:33〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2493s"]]}, {"cat": "家族", "t": "支えは家族と少人数の輪", "b": "ふたりは「自分の理由」を、家族と将来だと答えている。SNSで多くの意見にさらされるからこそ、自分をよく知る近しい人の言葉を大事にするという。ヘイリーとハンナは、その輪を小さく保つことが人生の鍵だと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（44:45〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2685s"]]}, {"cat": "家族", "t": "人を見る目はヘイリーが慎重", "b": "ヘイリーは、ハンナはすぐ誰とでも仲良くなれると思ってしまうと話す。自分は状況を冷静に見て「ゆっくり行こう」と声をかける役だという。ハンナはそんなヘイリーを「恋愛相談のChatGPT」と呼び、助けられていると話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（46:23〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2783s"]]}, {"cat": "家族", "t": "ヘイリーは静か、ハンナは社交的", "b": "ヘイリーはもともと内向的で、店で飲み物が違っていてもハンナに言ってもらうことが多かったという。ハンナは人前では明るく元気で、ヘイリーはおとなしめだが、家族の前では意見をはっきり言うそうだ。夜遊びで「もう寝る」と言い出すのはヘイリーで、ふたりはバランスがいいと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（50:20〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3020s"]]}, {"cat": "体のこと", "t": "ふたりで向き合った摂食障害", "b": "ふたりはフレズノ州立のころ、食べる量をとことん減らす生活に陥ったといい、回復を始めて約2年になるという。互いに引きずり合ってしまったと振り返る。母は早い段階で気づき、大学のコーチにも相談していたそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（52:45〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3165s"]]}, {"cat": "体のこと", "t": "出場時間への焦りが悪化させた", "b": "マイアミに移ってから、強い相手に勝つために体を絞ろうとしたことも影響したという。ハンナは出場できない日、練習後に長く有酸素運動をしていたそうだ。食事はごく限られたものだけになり、ヘイリーが先に助けが必要だと気づき、栄養士に頼ることにしたという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（54:16〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3256s"]]}, {"cat": "体のこと", "t": "完全には治らない、でも支えになれる", "b": "ふたりは今も回復の途中にあり、食事を先々まで考えてしまう癖が残っていると話す。当時は自分でコントロールできるのが食事だけだったからだという。経験を発信したことで多くの女性から反応があり、同じ悩みを持つ人の力になれるのが一番の励みだそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（56:39〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3399s"]]}, {"cat": "暮らし", "t": "自作のアプリTWOgether", "b": "ふたりは、運動プランや食事の目安を提供するアプリ「TWOgether」を、何もないところから作ったという。そこは前向きなコミュニティで、嫌なことがあった日は、そこへ行って元気をもらうそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（1:03:49〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3829s"]]}, {"cat": "暮らし", "t": "投稿したら見ない「ポスト・アンド・ゴースト」", "b": "ハンナは、投稿したら画面を見ないという決まりを持っているという。気持ちが落ちそうなときは、祖父母やヘイリー、ジェイクと過ごすフォートマイヤーズのビーチへ行き、スマホを置くそうだ。アプリを消してしまう方法も使い、ヘイリーに「大丈夫？」と状況を見てもらうこともあると話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（1:04:41〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3881s"]]}, {"cat": "暮らし", "t": "ハンナの人生観は「自分の船」", "b": "ふたりは「彼女の勝ちは自分の負けじゃない」と心に決め、嫉妬しないようにしているという。ハンナは、自分の人生を船にたとえ、誰を乗せ誰を降ろすかも成り行きだと話す。ヘイリーに浮き沈みは人生だと言われても「それが私の船」と受け止めるそうだ。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（1:08:40〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=4120s"]]}, {"cat": "暮らし", "t": "缶テキーラとサプリの新事業", "b": "ふたりは、缶入りテキーラ「アスカル」の企画とマーケティングを担当し、4月上旬に発売予定だという。もうひとつ、自分たちが顔にならない形のサプリメントブランド「Two Good」も準備中だそうだ。健康とフィットネスは自分たちの得意分野だと話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（1:12:26〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=4346s"]]}]);
  ARTICLES.push({ id: "wys-8sgqdq5hv7A", d: "2026-04-02", show: "wys", who: ["The Cavinder Twins"], t: "キャビンダー・ツインズの回　双子の絆、大学バスケ、摂食障害の経験と次の挑戦", lead: "ステファニー・マクマホンの番組に出た約76分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["The Cavinder Twins"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-8sgqdq5hv7A").map((x) => [x.t, x.b, x.sp])), open: ["ヘイリーとハンナが交互に話す場面が多く、話者を特定できない箇所は「ふたり」とした。", "ステファニー自身や同席者の体験談は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=8sgqdq5hv7A"]] });
  if (!ROSTER.find((r) => r[1] === "Bubba Ray Dudley")) ROSTER.push(["ババ・レイ・ダッドリー", "Bubba Ray Dudley", "gn", "殿堂入り。WWEを離れた", "", "", ""]);
  if (!PROFILES["Bubba Ray Dudley"]) PROFILES["Bubba Ray Dudley"] = { lead: "ECWで名を上げ、相棒のディーボンとともにWWEで六年を駆け抜けたという。お金の折り合いがつかず去ったが、のちに殿堂入りし、関係は良好だと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bubba%20Ray%20Dudley"]], moves: [], facts: [] };
  if (PROFILES["Bubba Ray Dudley"]._weak) { PROFILES["Bubba Ray Dudley"].lead = "ECWで名を上げ、相棒のディーボンとともにWWEで六年を駆け抜けたという。お金の折り合いがつかず去ったが、のちに殿堂入りし、関係は良好だと話す。"; delete PROFILES["Bubba Ray Dudley"]._weak; }
  PROFILES["Bubba Ray Dudley"].facts.push(...[{"cat": "WWEでの日々", "t": "三者通話で始まったWWE入り", "b": "ECWに五年ほどいた頃、写真家の友人を通じてWWE側が興味を持っていると聞いたという。互いに先に電話をかけたくないまま数か月が過ぎ、最後は友人がつないだ三者通話で当時の脚本担当と話すことになったそうだ。ECWのファンだった相手と、すぐに打ち解けたと話す。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（26:23〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=1583s"]]}, {"cat": "WWEでの日々", "t": "ECWの親分に「あと1ドル」を頼んだ", "b": "移籍を決める前、ECWの主宰者に「一晩あと1ドル上げてくれれば残る」と頼んだという。断られたことで、相手側がすでにWWEと話をつけていて、引き止められない事情があるのだと悟ったと話す。ECWへの恩義は今も強く、主宰者のことを心から慕っているそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（28:02〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=1682s"]]}, {"cat": "WWEでの日々", "t": "最初の面談は探り合いだった", "b": "WWEの初面談は、前に来たタッグチームの印象が良くなかったため、同じ種類の人間かどうかを見極める場だったと感じているという。ディーボンと二人でひたすら礼儀正しく話を聞いたと話す。二度目の面談では会長と元幹部の二人だけと向き合ったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（30:35〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=1835s"]]}, {"cat": "WWEでの日々", "t": "「押しはない、機会があるだけ」", "b": "面談で「押しの話をしたい」と切り出すと、会長に「押しなどというものはない。あるのは機会だ」と返されたという。当時の自分にとって、WWEがどんな場所かを知る大きな学びだったと話す。また「ヒールはサインも写真も断る」と言うと、笑って「どちらも応じることになる」と言われ、素直に従ったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（31:28〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=1888s"]]}, {"cat": "WWEでの日々", "t": "デビュー戦の洗礼と角材", "b": "デビュー直後、先輩の強面タッグに角材で襲いかかる場面を任されたという。前に来たタッグが揉めて袋だたきにされた経緯を聞いており、自分たちも試されているのだと理解したと話す。どうせ痛い目に遭うなら全力でやろうとディーボンと決め、思い切り殴ったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（33:00〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=1980s"]]}, {"cat": "WWEでの日々", "t": "本気の仕返しを受けて認められた", "b": "翌週の生放送で、先輩タッグから容赦ない反撃を受けたという。実際の鉄樽やコンクリートの上で、手加減なしの攻めを浴びたと話す。収録が終わると握手と抱擁を交わし、楽屋で皆が待っていたことで仲間に受け入れられたと感じ、そこから万事うまくいったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（36:13〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2173s"]]}, {"cat": "WWEでの日々", "t": "楽屋では二人きり、夜は毎晩外へ", "b": "WWEの楽屋では誰とも親しく礼儀正しく接したが、行動はいつもディーボンと二人だったという。ほぼ毎晩ビールと少しのウイスキーで飲みに出たと話す。ただし翌日にジムへ行き、きちんと動けることが条件で、それができなければ終わりだと語る。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（37:06〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2226s"]]}, {"cat": "WWEでの日々", "t": "二人が一気に名を上げた聖地の一戦", "b": "聖地とも呼ぶニューヨークの大会場で、人気の兄弟タッグとテーブルを使う試合に臨んだという。直前に試合時間を五分削られ、急いで組み立て直したそうだ。負け側だったが「勝たなくても観客の心はつかめる」と考えていて、この試合が自分たちの転機になったと話す。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（38:44〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2324s"]]}, {"cat": "WWEでの日々", "t": "憧れの先人をなぞった瞬間", "b": "この試合で、子どもの頃に憧れた名レスラーが会場の高所に立った場面を自分も再現したかったという。WrestleManiaの名場面のように、一生振り返れる瞬間が欲しかったと話す。そのため、あの一瞬は自分にとって特別だそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（40:17〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2417s"]]}, {"cat": "WWEでの日々", "t": "「ディーボン、テーブルを持ってこい」の誕生", "b": "決め台詞の「テーブルを持ってこい」は、台本があったわけではなく、自然に口から出たものだという。今ではディーボンと自分にとっての代表曲のようなもので、どの場面でも反応が読めると話す。直前に始めた挑発の頭突きとの組み合わせが強力で、必ず観客を沸かせられたそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（41:58〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2518s"]]}, {"cat": "WWEでの日々", "t": "名手ぞろいの名簿で「ショーを盗む」", "b": "当時のWWEは、のちに殿堂入りする顔ぶれがそろう鮫だらけの海のようだったという。それでも二人の目標はいつも一つで、誰が客を呼んだかより、帰りに自分たちの試合が話題になることだったと話す。順番に関係なく、毎回ショーを盗むつもりで出たそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（43:34〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2614s"]]}, {"cat": "WWEでの日々", "t": "伝説の女性選手に叱られて学んだこと", "b": "最初の共演で優しく持ち上げて下ろしたところ、その夜に楽屋で「やるなら男の仲間と同じように投げなさい」と手首をつかまれて言われたという。彼女は自分が会った中で一番タフな人で、誰よりも仲間だったと話す。のちにテーブルの上での名場面を一緒に作り、その高さと軌道は本番まで未経験で、手探りだったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（45:07〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2707s"]]}, {"cat": "WWEでの日々", "t": "「TLC」という名前が出た日", "b": "三組が初めて組んだはしごの試合の後、担当の先輩二人を前に、また同じ顔ぶれでやるなら「TLC」と呼べるかもしれないと口にしたという。直後に「くだらないことを言った」と恥ずかしく思ったと話す。その言葉が覚えられていたのか、数か月後の夏の大会で本当に実現したそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（48:16〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2896s"]]}, {"cat": "WWEでの日々", "t": "年間最大の祭典で歓声が聞こえなかった", "b": "ドーム球場での大一番では、六万人超の大歓声が真上に抜けてしまい、リング上では観客の反応がほとんど聞こえなかったという。そのため「試合は失敗した」と思い、肩を落として戻ったと話す。直前に試合時間が削られたことも重なったそうだ。結果として、あの試合は今も語られる名勝負になった。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（53:46〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3226s"]]}, {"cat": "WWEでの日々", "t": "唯一の言い争いは、見せ場の順番", "b": "その前日、最後の見せ場の順番をめぐって、相手チームの一人と熱く言い争ったという。自分は空中での衝突の方が大きいので最後にすべきだと考えたが、投票の結果、自分たちのはしごからの落下が後になったと話す。言い合いは試合のためだけの喧嘩で、後味は悪くなかったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（57:09〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3429s"]]}, {"cat": "WWEでの日々", "t": "がらんとした会場で見つけた解決策", "b": "空中で槍のように飛び込む場面の、振り子のような動きがなかなか作れなかったという。前日の無人のドームで全員が悩む中、ライノが「はしごを角まで運び、相手が引き戻す形にすれば勢いが生まれる」と提案したそうだ。それが見事にはまり、本番でもそのまま使ったと話す。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（59:33〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3573s"]]}, {"cat": "WWEでの日々", "t": "殿堂入りの場に、ライバルを呼んだ", "b": "殿堂入りの式典では、ほかのライバル二組を壇上に上げて一緒に光を浴びたかったという。ファンが六人そろう姿を見られるのは最後かもしれず、いつも共に脚光を分け合ってきた仲だからだと話す。自分たちだけでなく三組全体の歴史を見せたい思いだったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:03:32〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3812s"]]}, {"cat": "WWEでの日々", "t": "最初のドラフトで相棒と別れた", "b": "初のドラフトで、会長の発案によりディーボンと別々の番組に分かれたという。「手足を失ったよう」で、同じ頭を共有していた相方が隣にいない感覚はとても慣れないものだったと話す。自信を失いながらも、与えられた手札で戦うしかないと割り切ったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:04:22〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3862s"]]}, {"cat": "WWEでの日々", "t": "再結成を告げられた日", "b": "分裂を告げられた時、二人は「見に来る客は個人ではなくタッグを見ている」と反対していたという。のちにニューヨークの会場で会長から「今夜、二人をまた組ませる」と言われ、それだけで十分だったと話す。分裂の試みは思ったほどうまくいかなかったのだろうと感じているそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:06:47〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4007s"]]}, {"cat": "退団の理由", "t": "契約が切れ、育成の場で若手を手伝った", "b": "契約が満了して二ヶ月ほど家にいたが、会社の人に「何もせず給料をもらうのは落ち着かない」と伝え、育成地区へ出向いたという。そこで若い2チームを仕上げ、二人はのちに一軍に呼ばれた。自分から会長に提案して若手を送り出せたことが誇りだと話す。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:07:33〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4053s"]]}, {"cat": "退団の理由", "t": "お金の話で折り合えず、円満に離れた", "b": "WWEの六年間は、最終的に報酬の面で幕を閉じたと本人は話す。会社から条件を下げる提案があり、「六年間言われたことは全部やってきた」と思ったという。自分は交渉しにくい面もあるが、それは仕事のためだと語る。折り合えず、揉め事なく「また道で会おう」と別れたそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:08:18〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4098s"]]}, {"cat": "退団の理由", "t": "十年後に戻り、離れた翌年に殿堂入り", "b": "離れて十年ほど後に古巣へ戻った際は、温かく迎えられたという。去ってから一年後には殿堂入りも果たし、今は会社と良好な関係で不満もないと話す。他団体との違いとして、会長の厳しい視線という「説明責任」はWWEにしかなかったと述べる。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:09:05〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4145s"]]}, {"cat": "WWEでの日々", "t": "生放送で時間超過、「次も凄ければ許す」", "b": "生放送で五分も時間を超えてしまい、クビも覚悟したが、会場が沸いたせいか会長が幕の前で待っていたという。「次に超えるなら、今日と同じくらい良くしろ」とだけ言って去ったそうだ。怒りと最高の称賛が同居した言葉で、直接伝えてくれたことが何よりの褒め言葉だったと話す。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:10:46〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4246s"]]}, {"cat": "WWEでの日々", "t": "十年ぶりの復帰は恒例の大会で", "b": "元選手の運営スタッフからメールが来て、フィラデルフィアで開かれる年始の大会へのサプライズ出場を打診されたという。その大会に出演したことはあっても、実際に参戦するのは初めてだったと話す。ECWの原点の地でもあり、断る理由はなかったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:22:37〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=4957s"]]}, {"cat": "WWEでの日々", "t": "入場した瞬間、頭が真っ白に", "b": "復帰の入場では観客の音の壁に圧倒され、アドレナリンで意識が飛びかけたという。走り出してようやく我に返ったと話す。画面では落ち着いて見えるが、実際は何が起きているか分からなかったそうだ。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-Wtb_zhRRwE4", "src": [["番組のYouTube（1:23:29〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=5009s"]]}]);
  if (PROFILES["Mae Young"]) PROFILES["Mae Young"].facts.push({"cat": "暮らし", "t": "メイ・ヤングの教え", "b": "優しく扱うと「男の仲間と同じように投げなさい」と叱られ、以来ずっと仲間として尊敬しているという。彼女は自分が会った中で一番タフな人だったと、ババ・レイ・ダッドリーが話している。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ババ・レイ・ダッドリーの話（字幕を全文確認）", "src": [["番組のYouTube（45:07〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=2707s"]], "by": "第三者の話"});
  if (PROFILES["Rhyno"]) PROFILES["Rhyno"].facts.push({"cat": "暮らし", "t": "ライノの名案", "b": "空中の見せ場の動きで誰も答えを出せない中、ライノがはしごを使った簡単な方法を提案し、全員が納得したという。ババ・レイ・ダッドリーはその発想に感心したと話している。", "sp": "ババ・レイ・ダッドリー", "d": "2026-04-04", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ババ・レイ・ダッドリーの話（字幕を全文確認）", "src": [["番組のYouTube（59:33〜）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4&t=3573s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-Wtb_zhRRwE4", d: "2026-04-04", show: "ext", who: ["Bubba Ray Dudley"], t: "ババ・レイ・ダッドリーの回　ECWからWWEへ、テーブルとはしごの日々と別れ", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約98分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Bubba Ray Dudley"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-Wtb_zhRRwE4").map((x) => [x.t, x.b, x.sp])), open: ["WWEの話題が中心の回のため、ECW時代・他団体・学校運営などの話は公開項目に入れていない。", "試合の細部や時間の削られ方などは、本人の記憶に基づく語りを要約している。", "聞き手（オースティン）自身の話は拾っていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=Wtb_zhRRwE4"]] });
  if (!ROSTER.find((r) => r[1] === "Blake Monroe")) ROSTER.push(["ブレイク・モンロー", "Blake Monroe", "lg", "華やかな新世代の女子選手", "", "", ""]);
  if (!PROFILES["Blake Monroe"]) PROFILES["Blake Monroe"] = { lead: "ロンドン育ちで日本修行も経験した、華やかさと冷酷さを併せ持つ選手。子どもの頃のファン心を忘れず、順応と全力を信条に歩んできたと語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Blake%20Monroe"]], moves: [], facts: [] };
  if (PROFILES["Blake Monroe"]._weak) { PROFILES["Blake Monroe"].lead = "ロンドン育ちで日本修行も経験した、華やかさと冷酷さを併せ持つ選手。子どもの頃のファン心を忘れず、順応と全力を信条に歩んできたと語る。"; delete PROFILES["Blake Monroe"]._weak; }
  PROFILES["Blake Monroe"].facts.push(...[{"cat": "リングに来るまで", "t": "移籍後の最大の変化は環境の大きさ", "b": "団体の規模の大きさが、女子レスラーとして最大の魅力だったと話す。各国を渡り歩き、何度も引っ越してきたので、新しい挑戦に順応することが自分の誇りだという。今回の変化はこれまでで最も刺激的で、最も大変な章だそうだ。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（3:21〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=201s"]]}, {"cat": "好きなもの", "t": "子どもや家族連れの観客に会うのが楽しい", "b": "大きな大会の週末に子どもや家族連れをたくさん見て、プロレスは誰のためのものでもあると実感したと話す。子どもは感想を隠さず、反応がすぐ分かるので、直接会えることがこの仕事の素敵な部分だという。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（3:21〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=201s"]]}, {"cat": "リングの話", "t": "「グラマー」の役柄は入団前から相談していた", "b": "移籍に際して、自分の役柄を団体側が大きく育ててくれると期待していたそうだ。インディー時代はピンクの衣装でアリアナ・グランデの曲で入場する異色の存在で、リング上の実力は日本での修行に支えられていたという。入団前から、華やかさをどう大きくするかを話し合ってきたと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（4:59〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=299s"]]}, {"cat": "リングの話", "t": "華やかさと冷酷さは二重人格ではなく一人の中に同居", "b": "華やかな面と冷酷な面は別人格ではなく、同じ人物の中に混ざっているものだと説明する。夫の浮気を知った女性のような「怒れる姿」が暗い面のイメージだという。衣装、メイク、マイクで見た目が変わっても、試合運びは一貫していると話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（6:35〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=395s"]]}, {"cat": "リングの話", "t": "役柄づくりをじっくり試せるのが所属の理由", "b": "これまで役柄を腰を据えて練り上げる機会がなかったので、それができる場所を求めていたと話す。偶然生まれる良さもあるが、作り込んで特別にできるものもあるという。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（7:20〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=440s"]]}, {"cat": "リングに来るまで", "t": "日本で年下の選手から学んだ", "b": "日本では15〜16歳の選手と対戦し、自分は20代前半だったが、多くを学んだという。謙虚さと周りから学ぶ姿勢を教わった経験で、今の団体でもスポンジのように吸収する気持ちだと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（8:51〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=531s"]]}, {"cat": "暮らし", "t": "若手には役柄づくりの助言をする", "b": "運動能力の高い新人が多く、苦戦しやすいのは物語や見せ方の部分だと感じている。練習中に技のアイデアや入場演出を提案するのが好きで、先輩風というより友だち同士の会話のようだと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=580s"]]}, {"cat": "リングに来るまで", "t": "本隊へ直行せず育成の舞台を選んだ", "b": "視聴者数が自分の経験した番組で最も高く、さらに本隊には数百万のフォロワーを持つスターがいると話す。そこで育成の場に残り、知名度を積み、自分のブランドを築きながらコーチから学ぶ方が成功の可能性が高いと考えたという。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（10:28〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=628s"]]}, {"cat": "リングに来るまで", "t": "熱心なファン時代の発信が足跡になっている", "b": "物販の仕事をしていた頃からファンとして大会に通う投稿をしていたという。動画サイトには、練習を始める前の日常記録から現在までが残っている。内気な性格を克服し、自信をつけるために発信を始めたと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（12:49〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=769s"]]}, {"cat": "リングに来るまで", "t": "目指す人には「順応」と「全力」を勧める", "b": "夢への道筋は人によって違い、ごく少数の幸運な人を除けば、機会を逃さず順応することが大切だと話す。どんな機会にも全力を尽くし、恥ずかしがらずに技を磨き続けるよう勧めている。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（13:37〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=817s"]]}, {"cat": "リングに来るまで", "t": "演劇と陸上の経験があり、練習は内気だった", "b": "子どもの頃から演技や劇に取り組み、陸上競技もしていたという。マイクは得意だったが、練習でリングに上がる順番が来る前は緊張が強かったそうだ。コーチによく「内気な子はお菓子をもらえない」と励まされたと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（16:01〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=961s"]]}, {"cat": "好きなもの", "t": "子どもの頃の憧れはジェフ・ハーディ", "b": "子ども時代はジェフ・ハーディに夢中で、なりたいと思っていたと話す。今でも本人に会うと緊張して、ただのファンに戻ってしまうそうだ。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（16:01〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=961s"]]}, {"cat": "リングの話", "t": "ライバルとの抗争で誇りに思うのは女子プロレスの価値", "b": "前の団体での長い抗争を振り返り、女子プロレスは男子に負けず、むしろ上回れると示せたことが一番の誇りだという。逆境や制約があっても番組の最高の見せ場になれると話す。観客に何かを感じさせられれば成功だという考えだ。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（18:24〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1104s"]]}, {"cat": "リングに来るまで", "t": "デビュー戦は母国の学校の体育館", "b": "最初の試合は英国の学校の体育館で、強い選手が相手だった。極度に緊張して、ほとんど覚えていないという。兄弟とその友人が観戦に来て、家族で会場を埋めたと話す。緊張は最初の30〜40試合ほど続いたそうだ。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（20:57〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1257s"]]}, {"cat": "家族", "t": "家族はロンドンにいて、海外の試合にはなかなか来られない", "b": "出身はロンドンで、家族や友人は英国に住んでいる。米国まで全員が来るのは難しいため、育成団体が英国で大会を開いてくれれば家族と喜びを分かち合えると話す。家族の前で世界王座を取れたら最高だが、サンタに頼みすぎかもしれないと笑う。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（21:44〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1304s"]]}, {"cat": "好きなもの", "t": "最初に好きになったレスラーはトリッシュ・ストラタスら", "b": "幼い頃はジェフ・ハーディのほか、トリッシュ・ストラタスの入場曲を流して衣装をまねて走り回っていたという。母親は驚いたそうだ。ミッキー・ジェームズやベス・フェニックスの時代に育ったと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（24:55〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1495s"]]}, {"cat": "好きなもの", "t": "サッカーのチャントが好きで、米国の観客は物足りない", "b": "ロンドン育ちで、サッカー場で歌う文化に慣れているため、英国の観客の熱気が好きだという。米国のアメフトは試合が何度も止まる点が苦手で、観客にももっと歌ってほしいと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（26:33〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1593s"]]}, {"cat": "暮らし", "t": "本名はマライアで、リングネームに慣れるまで", "b": "本名はマライアで、新しい名前で呼ばれても最初は反応しなかったという。周りには「ブレイクと呼んで」と頼んで覚えようとしたそうだ。今では自然に受け入れ、その名前になりきるのが楽しいと話す。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で（字幕を全文確認）", "art": "ext-9ny-M2gbfG4", "src": [["番組のYouTube（30:44〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1844s"]]}]);
  if (PROFILES["Kendall Gray"]) PROFILES["Kendall Gray"].facts.push({"cat": "暮らし", "t": "練習相手として元気いっぱい", "b": "エボルブの王座を獲得したばかりで、練習していると子犬のように朝から元気で、こちらまでやる気が出ると、ブレイク・モンローが話している。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で、ブレイク・モンローの話（字幕を全文確認）", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=580s"]], "by": "第三者の話"});
  if (PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"].facts.push({"cat": "暮らし", "t": "SNSの投稿が上手いコーチ", "b": "夜に家で子どもたちと一緒に動画投稿を見ているのでは、と冗談まじりに、ブレイク・モンローが話している。", "sp": "ブレイク・モンロー", "d": "2026-04-08", "how": "リンガー・レスリングの番組で、ブレイク・モンローの話（字幕を全文確認）", "src": [["番組のYouTube（22:30〜）", "https://www.youtube.com/watch?v=9ny-M2gbfG4&t=1350s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-9ny-M2gbfG4", d: "2026-04-08", show: "ext", who: ["Blake Monroe"], t: "ブレイク・モンローの回　華やかさと冷酷さ、新天地での挑戦", lead: "リンガー・レスリングの番組に出た約32分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Blake Monroe"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-9ny-M2gbfG4").map((x) => [x.t, x.b, x.sp])), open: ["信仰についての話は出ていない。", "試合の宣伝や次の大会の予定は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=9ny-M2gbfG4"]] });
  if (!PROFILES["Logan Paul"]) PROFILES["Logan Paul"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Logan%20Paul"]], moves: [], facts: [] };
  if (PROFILES["Logan Paul"].lead === "") PROFILES["Logan Paul"]._weak = 1;
  PROFILES["Logan Paul"].facts.push(...[{"cat": "リングの話", "t": "地下室のスタントが、いまのリングにつながる", "b": "ローガン・ポールは、最初に撮った動画が弟ジェイクと地下室でやったスタントだったと話す。いまはそれを5万人の前のリングでやっているのだと笑う。最初の大舞台のあとにビンス・マクマホンから「君の未来はここにある」と言われたが、当時は聞き流したという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（8:45〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=525s"]]}, {"cat": "リングの話", "t": "控室で見返した自分の技に「レスラーに見える」", "b": "最初の大舞台の直後、ローガンは控室で自分のフロッグスプラッシュなどの映像を見返したそうだ。「レスラーに見えるじゃないか」と驚き、自分の売り込みを自分で信じてしまったと話す。ビンスは正しかったのかもしれない、と思った瞬間だったという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（9:35〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=575s"]]}, {"cat": "リングの話", "t": "ビンスに15分売り込んだが、反応が読めなかった", "b": "WWEに声をかけられたのは、ネットでの影響力があったからだとローガンは話す。大会前に事務所で、話題になる瞬間をつくる案を15分ほど売り込んだが、ビンスはうなずくだけで一言もしゃべらなかったという。担当者にも「たぶん一言も通じてない」と言われたが、あとから届いていたことが分かったそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（10:25〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=625s"]]}, {"cat": "リングの話", "t": "アティテュード・エラのような荒々しさを取り戻したい", "b": "ローガンは、WWEは昔のアティテュード・エラのような勢いを見習うべきだと話す。ほかのレスラーにはない武器は「頭」と創造力で、自分には良いアイデアがあるのに生かされていないと感じているそうだ。既存のファンだけでなく、WWEの外の客層にも届く作品をつくりたいという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（16:07〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=967s"]]}, {"cat": "リングの話", "t": "最初はブーイングされて腹を立てた", "b": "WWEに来た当初、客席にブーイングされてローガンは本気で怒ったそうだ。ところが舞台裏でブルース・プリチャードに「最高だった」と言われ、戸惑ったという。ブーイングが力になると知らなかった、と振り返る。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（43:31〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2611s"]]}, {"cat": "リングの話", "t": "ブーイングは近づくと小さくなる", "b": "ローガンは、WWEのファンは遠くでは大声でブーイングするのに、近づくほど声が小さくなり、最後はサインや自撮りを頼んでくると笑う。いまは歓声のほうが落ち着かず、調子が狂うそうだ。WWEの外の場所のブーイングは本物だとも話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（45:59〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2759s"]]}, {"cat": "リングの話", "t": "最初の大舞台で悪役の面白さに気づいた", "b": "最初のレッスルマニアで、ローガンは夢だったトップロープからの飛び込みをやったそうだ。エディ・ゲレロの決めポーズをまねてからレイ・ミステリオにフロッグスプラッシュを決めると、会場は大ブーイングになったという。その映像が後で一番見られたと知り、悪役を楽しむ感覚をつかんだと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（47:32〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2852s"]]}, {"cat": "リングの話", "t": "WWEを一番の情熱に挙げる、静かなのは最悪", "b": "ローガンは、いま一番情熱を注いでいるのはWWEで、自分から望んでフルタイムの選手になったと話す。好きな役を演じられるところに深い満足があるそうだ。観客が何も反応しない静けさがいちばん悪く、ブーイングのほうがずっとましだという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（53:08〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3188s"]]}]);
  if (!PROFILES["Logan Paul"]) PROFILES["Logan Paul"] = { lead: "9歳で花の写真を撮り、弟ジェイクと地下室でスタント動画を作っていた少年が、いまはリングで同じことをしている。大きな失敗から立ち直った経緯と、ポケモンや恐竜への愛を語った回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Logan%20Paul"]], moves: [], facts: [] };
  if (PROFILES["Logan Paul"]._weak) { PROFILES["Logan Paul"].lead = "9歳で花の写真を撮り、弟ジェイクと地下室でスタント動画を作っていた少年が、いまはリングで同じことをしている。大きな失敗から立ち直った経緯と、ポケモンや恐竜への愛を語った回。"; delete PROFILES["Logan Paul"]._weak; }
  PROFILES["Logan Paul"].facts.push(...[{"cat": "好きなもの", "t": "9歳で花の写真に夢中だった", "b": "9歳のころ、目に見えるものを画面に残すことに不思議なほど夢中になり、デジタルカメラで花ばかり撮っていたという。部屋の壁に花を描きたいと母に頼んだら、父に「男の子はふつうそういうことはしない」と諭され、冗談だとごまかしたそうだ。旅行先のワシントンでは記念碑も撮って回ったと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（3:14〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=194s"]]}, {"cat": "リングに来るまで", "t": "誕生日のお金でビデオカメラを買った", "b": "誕生日にもらったお金を貯めてビデオカメラを買い、カメラの前でふざけては見返すのが楽しくて仕方なかったという。ちょうどYouTubeが始まったころで、10歳でアップロードの意味から自分で覚えたそうだ。ユーチューバーという職業がまだなかった時代の話だと語っている。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（4:46〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=286s"]]}, {"cat": "家族", "t": "弟ジェイクと8年間、誰も観ない動画を作った", "b": "弟のジェイクと二人で、ほとんど誰にも観られない動画を8年間作り続けたという。最初の動画は自宅の地下室でのスタントで、5万人の前のリングで同じことをしているいまにつながっていると話す。小学6年のとき同級生の女の子に見せて「寒い」と言われたのがショックで初期の動画を全部消してしまい、大きな後悔だったが、バックアップが見つかっていまも残っているそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（7:13〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=433s"]]}, {"cat": "リングに来るまで", "t": "WWE入りを後押ししたのは担当者だった", "b": "WWEが声をかけたのはネットでの発信力があったからで、契約前にヴィンス・マクマホンへ自分のアイデアを売り込みに行ったという。WWE側の担当者に「やるべきだ」と説得されて半信半疑で始めたのが、いまでは人生そのものになったそうだ。自分はヴィンスが最後に契約した選手で、それが誇らしいと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（10:25〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=625s"]]}, {"cat": "家族", "t": "妻に「グレッグが出てる」と言われる", "b": "父グレッグは少し常軌を逸したところのある人で、自分にもその性質があると認めている。ときどき妻から父の名を取って「グレッグが出てるよ」と言われるそうだ。たまに少しタガが外れる、という意味だという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（20:15〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1215s"]]}, {"cat": "家族", "t": "子ども時代は父の改修物件で長時間労働", "b": "8〜10歳ごろ、父が買い取って改装する家の片づけを弟と手伝わされ、1日12〜16時間働いたこともあったという。報酬は昼食のファストフードだけで、夏休みがそれで終わるのが本当に嫌だったそうだ。ただ、嫌いなことに全力を尽くした経験があったからこそ、好きなことを見つけたときに迷わず打ち込めたと振り返る。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（20:15〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1215s"]]}, {"cat": "リングに来るまで", "t": "一度やめたアマレスを12歳で再開", "b": "7〜8歳でユースのレスリングを2年やったが、練習場は臭くてきつく、学校で流行っているわけでもなかったので嫌いだったという。12歳のとき学校のコーチに誘われてしぶしぶ顔を出すと、経験があったぶん周りの子より強く、そこから人生の流れが変わったと話す。フットボールでは攻守両方をこなしていたそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（21:51〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1311s"]]}, {"cat": "体のこと", "t": "あだ名は「エビ」、成長期は17歳", "b": "仲間内で一番背が低く小柄で、友人たちに「シュリンプ（エビ）」と呼ばれていたという。背が伸びたのは高校3年の17歳ごろで、かなりの遅咲きだったそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（23:36〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1416s"]]}, {"cat": "暮らし", "t": "21歳で「無敵」だと思い込んだ", "b": "Vineやバズ動画で一気に有名になり、毎日何百万人に肯定されるうちに価値観が歪んだと振り返る。周りをイエスマンで固め、批判を受け付けなかったのが大きな間違いだったという。いまのチームには、言い方は優しくでいいから「ノー」と言ってほしいと伝えているそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（25:56〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1556s"]]}, {"cat": "暮らし", "t": "460日連続で毎日動画を出していた", "b": "当時は10〜20分の編集済みの動画を毎日投稿し、それが460日続いたという。1日12時間以上撮影し、自分が何をしているか考える余裕もなかったそうだ。楽しんでいるつもりだったが、本当に好きだったのは注目を浴びることだったと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（28:22〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1702s"]]}, {"cat": "リングに来るまで", "t": "日本での騒動ですべてを失った", "b": "注目を集めることだけを追っていた時期に、日本で撮影した動画が大きな非難を浴び、11年かけて築いたものをほぼ失ったという。本人は「あれは間違いで、起きる必要のないことだった」と認め、自業自得だったと話す。そのうえで、なぜそうなったのかを自分に問い直したことが、いまの誇れる自分につながったと語っている。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（30:47〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1847s"]]}, {"cat": "リングに来るまで", "t": "ヴィーガン、スカイダイビング、そしてボクシング", "b": "騒動のあと投稿を1か月止め、自分が何者なのか分からなくなったという。自分を探すため、しばらくヴィーガンになったり、スカイダイビングを始めたり、生まれて初めて本気で恋をしたりしたそうだ。最後に始めたボクシングで毎日打ちのめされながら通い続けたことが、自分を謙虚にし、もう一度自分を好きになる道になったと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（33:06〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1986s"]]}, {"cat": "暮らし", "t": "批判を自殺防止の発信につなげた", "b": "騒動で集まった負の注目を、自殺防止のメッセージに変えられたことを誇りに思っているという。ゴールデンゲートブリッジから飛び降りて生還し、いまは講演活動をしているケビン・ハインズを取り上げた動画は、この分野で最も再生された動画になったそうだ。ハインズとはいまでは親しい友人だという。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（37:48〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2268s"]]}, {"cat": "家族", "t": "優先順位の一番上は娘と妻", "b": "20代前半は自分のことばかりだったが、いまは娘と妻、そして家族が何より先だという。妻と娘は優先順位のいちばん上に並んでいるそうだ。観客にどう思われるかを気にしなくなったと話している。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（43:31〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2611s"]]}, {"cat": "家族", "t": "「住所は映さないでね」だけだった母", "b": "母のパムは最高の母親で、家族でいちばん安定している人だという（収録中にも顔を出した）。地下室で危ないスタントをしていても、動画を投稿したいと言っても「どうぞ、住所と名字だけは出さないで」と好きにさせてくれたそうだ。子どもが自然と引かれるものを見守り伸ばすことが大事だと、自身の経験から語っている。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（50:42〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3042s"]]}, {"cat": "体のこと", "t": "唯一のタトゥーはゼニガメ", "b": "子どものころからポケモンカードや石、コインなどを集めるのが好きだったという。ポケモンのゲームにも膨大な時間を費やし、22歳でゼニガメのタトゥーを入れたそうだ。体に刻んでもいいと思えるほど大切なものがほかになかったからで、タトゥーはこれ一つだけだと話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（54:45〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3285s"]]}, {"cat": "暮らし", "t": "入場で身に着けたカードが史上最高額に", "b": "年間最大の祭典のデビュー戦で身に着けて入場したポケモンカードを、約1650万ドルで売ったという。トレーディングカードとして史上最高額で、WWEの記念品としても過去最高になったそうだ。ビジネス、情熱、コンテンツの三つがそろうと自分は一番力を出せると話す。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（55:31〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3331s"]]}, {"cat": "暮らし", "t": "貯金約100万ドルを全部ポケモンに", "b": "知人の起業家に勧められてポケモンカードの世界を知り、資産運用の担当者に預けていた約100万ドルを全額引き出したという。担当者には猛反対されたが押し切り、初版の未開封ボックスやリザードンを買い集めたそうだ。その後、自分の動画で取り上げたことで価格が上がり、買い増しがしにくくなったと笑う。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（57:54〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3474s"]]}, {"cat": "好きなもの", "t": "恐竜の化石で自分を取り戻す", "b": "恐竜が大好きで、化石を眺めると地球がどれほど奇跡的な場所かを思い出せるという。恐竜が億年単位で地上を支配していたのに比べ、人類の歴史はほんの一瞬だと語る。化石を見るたびに地に足がつく感覚があるそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（1:01:09〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3669s"]]}, {"cat": "好きなもの", "t": "子どものころからUFOに夢中", "b": "宇宙人やUFOには子どものころから惹かれていて、いまもネット上の議論をかなり追っているという。ある古いUFO映像を手元に持っていて、いつか適切な時期に公開したいと話す。真偽を確かめるため、関係者に直接話を聞こうとしているそうだ。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-7u9RnJWLk30", "src": [["公式YouTube（1:04:16〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=3856s"]]}]);
  if (PROFILES["Jake Paul"]) PROFILES["Jake Paul"].facts.push({"cat": "暮らし", "t": "ジェイクの成長期は22歳ごろ", "b": "弟ジェイクは背が伸びるのがさらに遅く、20〜21歳ごろの写真ではとても小さかった。成長期が来たのは22歳くらいで、いまではすっかり大柄になったと、ローガン・ポールが話している。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で、ローガン・ポールの話（公式字幕を全文確認）", "src": [["公式YouTube（23:36〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=1416s"]], "by": "第三者の話"});
  if (PROFILES["Bruce Prichard"]) PROFILES["Bruce Prichard"].facts.push({"cat": "暮らし", "t": "ブーイングを「最高だ」とほめた", "b": "WWEに来て初めて観客にブーイングされ腹を立てていたとき、舞台裏でブルース・プリチャードに「最高だった」と言われたという。最初は意味が分からず怒っていたが、やがてそれが自分の力だと気づいたと、ローガン・ポールが話している。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で、ローガン・ポールの話（公式字幕を全文確認）", "src": [["公式YouTube（44:17〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=2657s"]], "by": "第三者の話"});
  if (PROFILES["Vince McMahon"]) PROFILES["Vince McMahon"].facts.push({"cat": "暮らし", "t": "15分の売り込みに無言でうなずいた", "b": "契約前にアイデアを15分ほど熱弁したが、ヴィンス・マクマホンはひと言も発せずうなずくだけだったという。担当者にも「たぶん一言も分かっていなかった」と言われたが、何かは伝わっていたようだと、ローガン・ポールが話している。", "sp": "ローガン・ポール", "d": "2026-04-09", "how": "ステファニーの番組で、ローガン・ポールの話（公式字幕を全文確認）", "src": [["公式YouTube（10:25〜）", "https://www.youtube.com/watch?v=7u9RnJWLk30&t=625s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-7u9RnJWLk30", d: "2026-04-09", show: "wys", who: ["Logan Paul"], t: "ローガン・ポールの回　花の写真と地下室のスタント、失敗からの再出発、ポケモンと恐竜", lead: "ステファニー・マクマホンの番組に出た約74分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Logan Paul"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-7u9RnJWLk30").map((x) => [x.t, x.b, x.sp])), open: ["日本での騒動は本人の語った範囲で要点だけにとどめ、具体的な内容には触れていない。", "観客の反応やリング上の振る舞いに関する話（ブーイングを好む理由など）は、キャラクターに関わる話として素顔の項目からは外した。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=7u9RnJWLk30"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wdywta-hhh" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wdywta-hhh" ? Object.assign(x, { art: "wdywta-znC6s9yaMOA" }) : x);
