  PROFILES["Triple H"].facts.push(...[{"cat": "リングの話", "t": "体つきより「信じられる説得力」", "b": "トリプルHは、レスラーに必ずしもボディビルダーのような体は要らないと話す。大切なのは、その役柄に説得力があることだという。ガンサーのような選手も、カマラのような巨体の選手もいていいと考えていて、いろいろなタイプがいるほうが番組は面白くなるそうだ。子どものころ、アブドーラ・ザ・ブッチャーやカマラも、ロード・ウォリアーズと同じくらい怖かったと振り返っている。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（3:07〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=187s"]]}, {"cat": "リングの話", "t": "「ザ・ゲーム」が生まれたJRとのインタビュー", "b": "トリプルHは、実況のジム・ロスとのインタビューで「ザ・ゲーム」が定着した経緯を語った。台本はなく、聞かれそうな質問への答えを箇条書きで頭に入れていた程度で、あの一言もその場の勢いだったという。撮影では放送できない言葉も出たが、使える角度から撮り直すことになり、手応えを感じたそうだ。決定的だったのは次のNXT収録で、客席にザ・ゲームと書かれたプラカードが数枚あるのを見て、これは行けると確信したと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（20:54〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1254s"]]}, {"cat": "リングの話", "t": "悪役としてのトリプルHを支えた実況ロス", "b": "トリプルHは、ジム・ロスが自分にとって実況席の宿敵のような存在で、ヒールとして大きく押し上げてくれたと話す。スティーブ・オースチンやザ・ロックのような強さや器用さで勝負できない自分は、「頭の切れる策士」で違いを出すしかなかったという。「セレブラル・アサシン」という呼び名は、その考えにぴったりはまった魔法のような一言だったそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（24:59〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1499s"]]}, {"cat": "リングの話", "t": "アーン・アンダーソンの話に学ぶ「欲張りすぎない」考え方", "b": "トリプルHは、選手が小さなことに悩んで消耗しているのを見ると、もどかしくなると話す。そこで引き合いに出したのが、アーン・アンダーソンの昔の演説だ。アーンは、自分は殿堂入りに値する経歴だが、メインに立てたのはリック・フレアーと組んだときだけで、あくまで中堅だったと語ったという。それでも家族を養い、素晴らしい旅をしたと胸を張った。トリプルHは、上を目指す気持ちは大事だが、いま手にしているものを誇ってほしい、道のりそのものが一番の財産だと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（36:31〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=2191s"]]}, {"cat": "リングの話", "t": "WM30の玉座入場と三人の女性たち", "b": "トリプルHは、レッスルマニア30でダニエル・ブライアンと戦った入場を、お気に入りの上位に挙げて2位に置いた。体制側の権力者と、それに逆らう男という構図が絵になり、時間の使い方もよかったそうだ。玉座にシャーロット・フレア、サーシャ・バンクス、アレクサがつく演出で、出る直前に、責任を背負う前に何も背負わず立てるのはこれが最後かもしれない、よく味わうようにと声をかけたという。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:19:03〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4743s"]]}, {"cat": "リングの話", "t": "WM12のアルティメット・ウォリアー戦", "b": "トリプルHは、初めてのレッスルマニアとなった12回大会の入場を、見た目は派手ではないが思い入れがあると話した。ビンス・マクマホンから、ウォリアーは当日まで復帰を明かさないので、そこで戦う相手になってほしいと言われたという。メディアの仕事も任されると聞き、大会前の64日間、毎日休まず宣伝活動に回ったそうだ。入場の順位は7位にしている。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:20:40〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4840s"]]}, {"cat": "リングの話", "t": "WM22の玉座が上がらなかった冒険", "b": "トリプルHは、レッスルマニア22のジョン・シナ戦の入場を4位にした。シナがマフィア風のトミーガン演出をする一方で、自分は玉座でせり上がる趣向だったが、リフトの途中で玉座が引っかかって動かなくなったという。チューバッカの衣装のまま穴から這い出るのは最悪だと焦ったが、隣のスタッフが押して穴にはまり、再び上がり始めてほっとしたそうだ。のちにコーディが玉座を壊す演出を使ったことには、悪意があったとしても、名を上げようとする姿勢が気に入ったと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:23:09〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4989s"]]}, {"cat": "リングの話", "t": "WM31のターミネーター入場の裏話", "b": "トリプルHは、レッスルマニア31の入場を4位としている。映画の企業が入場のスポンサーになり、アーノルド・シュワルツェネッガーに読み上げを頼むと、すぐ快諾してくれたそうだ。ところが小道具のロボットは本番の1週間半前に、映画では全部CGだったと分かり、小道具屋でロボットを買い集めたという。その後、映画のレッドカーペットで貸してほしいと頼まれて笑ったとのこと。当日は、スティングの煙のリハーサルをしていなかったため、迫り台の下が煙で真っ白になり、何も見えないまま上がったと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:29:31〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5371s"]]}, {"cat": "リングの話", "t": "WM29のスカル入場で肌が焼けた", "b": "トリプルHは、ブロック・レスナーと戦ったレッスルマニア29の巨大なドクロの入場を、10位にした。冷却ガスの煙を浴びたところ、リハーサルのときと違って肌が焼けるように痛くなったという。自分の体からジュージューと音が聞こえるのが分かったが、入場は止まらず歩き続けたそうだ。リングのブロックに「何がついてるんだ」と言われて気づき、皮膚が焼けていたと振り返っている。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:31:05〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5465s"]]}, {"cat": "リングの話", "t": "WM21のモーターヘッド生演奏", "b": "トリプルHは、レッスルマニア21のバティスタ戦で、モーターヘッドが入場曲を生演奏した場面を語った。子どものころからのファンで、本人たちが自分のテーマを弾いてくれるのが夢のようだったという。リハーサルは二日酔いでひどく、レミーが歌詞をまともに歌わなかったほどで、ケビン・ダンから中止を勧められたが、本番前に整えば大丈夫だと押し切ったそうだ。本番は圧倒的な迫力になり、友人だったレミーがいたからこそ、さらに思い出深いと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:33:27〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5607s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Triple H")) ROSTER.push(["トリプルH", "Triple H", "lg", "殿堂入りの元WWE王者", "", "", ""]);
  if (!PROFILES["Triple H"]) PROFILES["Triple H"] = { lead: "心の中はいまも、土曜の朝にソファでプロレスを見ていた少年のままだと話す。若手時代は出番のない大会にまで通い、移動の車中でもひたすらプロレスを語り合っていたという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Triple%20H"]], moves: [], facts: [] };
  if (PROFILES["Triple H"]._weak) { PROFILES["Triple H"].lead = "心の中はいまも、土曜の朝にソファでプロレスを見ていた少年のままだと話す。若手時代は出番のない大会にまで通い、移動の車中でもひたすらプロレスを語り合っていたという。"; delete PROFILES["Triple H"]._weak; }
  PROFILES["Triple H"].facts.push(...[{"cat": "暮らし", "t": "年号を覚えるのは大の苦手", "b": "出来事そのものはだいたい覚えているが、それが何年のことだったかはまったく覚えていないという。番組の冒頭から、日付の話になると自分はお手上げだと笑って話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:35〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=95s"]]}, {"cat": "リングに来るまで", "t": "19歳でティーンのボディビル大会に", "b": "1988年にニューハンプシャー州の10代向けボディビル大会で優勝したのは19歳のときで、10代の部に出られる最後の年だったそうだ。ただ、ボディビルダーがプロレスに転向したと思われがちなのは誤解だという。もともとプロレスラーになるためにジムへ通っていた少年で、大会は練習の励みにしていただけ、本業にするつもりはなく向いてもいなかったと話す。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:35〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=95s"]]}, {"cat": "好きなもの", "t": "子どもの頃に怖かったのは怪奇派", "b": "子どものころ、アブドーラ・ザ・ブッチャーやカマラは、筋骨隆々のロード・ウォリアーズと同じくらい恐ろしく見えたという。だから体の大きさや形はいろいろあっていい、と考えるようになったそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（3:57〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=237s"]]}, {"cat": "体のこと", "t": "鍛えるのは長く続けるため", "b": "いまの時代は何が体を健康に保つのかがずっとよく分かっていて、トレーニングはこの世界で長くやっていくための土台だと話す。見た目の説得力のためだけではないという考えだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（7:05〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=425s"]]}, {"cat": "好きなもの", "t": "いまも土曜朝のソファの少年", "b": "プロレスのあらゆる面が好きで、気の合う相手と昔話をしながらプロレス談義をするのが何より楽しいという。立場上そうした機会は減ったが、心の中ではいまも土曜の朝にソファでプロレスを見ていた子どものままだと話す。毎日の車移動で仲間と語り合った日々は、いまでも恋しいそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（8:39〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=519s"]]}, {"cat": "リングに来るまで", "t": "たくさんの師匠に囲まれて育った", "b": "ビンス、パット・パターソン、ジャック・ランザ、アーニー・スカーランド、ダスティ・ローデス、リック・フレアー、ショーン・マイケルズらから少しずつ学べたのは本当に幸運だったという。制作会議に呼ばれるようになると、終わるたびにパターソンに客席へ呼ばれて番組を振り返り、そのあとはランザが待ち構えていたそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（11:49〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=709s"]]}, {"cat": "リングに来るまで", "t": "恩師コワルスキーの教えは10年後に", "b": "師匠のキラー・コワルスキーに教わったことの多くは、当時は意味が分からなかったという。10年ほどたって、自分が別の言い方で同じことを口にしているのに気づき、あのときの言葉はこういう意味だったのかと腑に落ちたそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（15:55〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=955s"]]}, {"cat": "リングに来るまで", "t": "異名「ザ・ゲーム」は台本なし", "b": "異名が生まれたジム・ロスとのインタビューは、台本のないほぼアドリブだったという。収録で汚い言葉まじりに言ってしまったが、口元が見えない角度で使うことになり、手応えを感じたそうだ。次の放送で会場に「ザ・ゲーム」と書いた手作りの看板が5〜6枚見え、これは毎回言うべきだと決めたと話す。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（21:40〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1300s"]]}, {"cat": "家族", "t": "妻ステファニーの自然な気配り", "b": "殿堂入りが決まった妻ステファニーが、部屋にいる一人ひとりにあいさつして全員を場の一員にしていたと、聞き手のコーディが感心すると、本人はそれを意識してやっているとは思わない、あれがあの人そのものなのだと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（26:35〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1595s"]]}, {"cat": "好きなもの", "t": "スポーツにはそれほど詳しくない", "b": "名選手が名コーチになりにくいという話をしながら、自分はそれほどスポーツ好きではないと明かしている。そうした話は、よく一緒に仕事をする相手から聞かされるのだという。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:04:35〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=3875s"]]}, {"cat": "暮らし", "t": "いまのほうがやりがいを感じる", "b": "キャリアの終盤に裏方の仕事を学び始めたいまのほうが、選手として走っていたころより充実していると話す。ジ・アンダーテイカーからは、昔はなぜあんなに苦労を背負い込むのか不思議だったが、いまは自分もやっておけばよかったと言われたそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:06:08〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=3968s"]]}, {"cat": "リングに来るまで", "t": "出番のない大会にも通った若手時代", "b": "入団したてのころ、試合後はプロレスの話を一切したくない先輩が多いことにがっかりしたという。自分は残りの試合も全部見たくて、出場予定のない大会にまで足を運んでいたそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:09:22〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4162s"]]}, {"cat": "リングに来るまで", "t": "車中はひたすらプロレス談義", "b": "ケビン・ナッシュ、スコット・ホール、ショーン・マイケルズ、X-パックとの移動では、ずっとプロレスの話をしていたという。今夜はプロレスの話はやめようと言い出すホールが、真っ先に試合の話を始めるのがお決まりだったそうだ。ウィリアム・リーガルとの友情も、自分を形づくった一つだと話す。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:10:11〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4211s"]]}, {"cat": "好きなもの", "t": "入場のバイクは自分で運転", "b": "警察の先導つきでバイクに乗って入場した回は、最後まで自分で運転していたという。乗ったボスホスはギアが2段しかないオートマで、とんでもなく速いので扱いに気をつかうと話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:20:40〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4840s"]]}, {"cat": "リングに来るまで", "t": "初の大舞台の前に64日連続稼働", "b": "初めて出たレッスルマニアでは、復帰するアルティメット・ウォリアーの相手を任された。ビンスから取材対応も全部やっていいと言われ、本番前は64日間、試合の合間にメディア回りを続けて一日も休まなかったという。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:21:30〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4890s"]]}, {"cat": "家族", "t": "妻と並んだ入場がいちばんの思い出", "b": "これまでの入場で一番に挙げたのは、妻ステファニーと組んだ混合タッグの回だった。妻はひどく緊張していて、水を吹き上げるパフォーマンスを失敗したくないから練習しようと相談してきたそうだ。キャリアの終わりに近い時期に、妻と一緒にあの場に立てたのが格別だったと話す。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:27:51〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5271s"]]}, {"cat": "体のこと", "t": "演出の冷却ガスで肌が焼けた", "b": "ブロック・レスナー戦の入場で冷却ガスを浴びたところ、リハーサルとは違って肌が焼けるように痛んだという。体の中でジュッと音がするのが聞こえ、リングのレスナーに何がついているんだという顔で見られて、ようやく皮膚がやられていたと気づいたそうだ。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:31:50〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5510s"]]}, {"cat": "好きなもの", "t": "子どもの頃からのモーターヘッド好き", "b": "子どものころから大ファンだったモーターヘッドが入場曲を手がけ、大舞台で生演奏してくれたのが格別だったという。リハーサルはひどい出来で中止も検討されたが、本番は圧巻だったそうだ。ボーカルのレミーは親しい友人で、その意味でも特別だったと話す。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:33:27〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5607s"]]}]);
  if (PROFILES["Killer Kowalski"]) PROFILES["Killer Kowalski"].facts.push({"cat": "暮らし", "t": "若いころはボディビル級の肉体", "b": "晩年の映像の印象とは違い、若いころは身長2メートル前後の巨体で、ボディビルの大会に出られそうなほど鍛え上げられていたという。のちに菜食に切り替えて体つきがすっかり変わり、試合では休まず動き続ける驚異的なスタミナの持ち主だったと、トリプルHが話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で、トリプルHの話（公式字幕を全文確認）", "src": [["公式YouTube（17:34〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1054s"]], "by": "第三者の話"});
  if (PROFILES["Bobby Roode"]) PROFILES["Bobby Roode"].facts.push({"cat": "暮らし", "t": "首のけがから裏方の道へ", "b": "首のけがが治まらなかったため、回復を待つあいだに裏方の仕事を学んではどうかと勧めたところ、すぐに飛びついたという。吸収が早く、いまはマイケル・ヘイズの隣で学びながら頭角を現していると、トリプルHが話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で、トリプルHの話（公式字幕を全文確認）", "src": [["公式YouTube（48:04〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=2884s"]], "by": "第三者の話"});
  if (PROFILES["AJ Styles"]) PROFILES["AJ Styles"].facts.push({"cat": "暮らし", "t": "引退後は若手の発掘に", "b": "最後の試合の最中に、早く終わってほしいと思った自分に気づき、もう引き際だと確信したと本人から聞いたという。脚本や制作の仕事は自分に合わないと感じ、若い才能を見つけて育てる道を選んだと、トリプルHが話している。", "sp": "トリプルH", "d": "2026-04-09", "how": "コーディの番組で、トリプルHの話（公式字幕を全文確認）", "src": [["公式YouTube（1:01:29〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=3689s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "好きなもの", "t": "周りにいつもプロレスを流す", "b": "収録場所に来たときも、会場に着いたバスの中でも、必ずプロレスの映像を流しているという。プロレスが周りにないと落ち着かず、楽しみながら見ていても、たいてい何かを学び取っていると話す。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（10:13〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=613s"]]}, {"cat": "家族", "t": "父ダスティがソファの後ろで解説", "b": "子どものころは、父ダスティがソファの後ろから試合の見どころを教えてくれたという。父は息子がショーン・マイケルズを好きな理由が分からなかったが、楽しみを邪魔することはなかったそうだ。長い試合に退屈している息子を見て延長戦に安堵したり、往年の選手が出てくると誰なのか教えてくれたりしたと振り返る。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（20:03〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1203s"]]}, {"cat": "リングに来るまで", "t": "子ども時代の初仕事は実況席の使い走り", "b": "父に連れられて行った大会で、実況席の注文をホワイトボードで受けて届ける係をしていたのが、プロレスでの最初の仕事の一つだという。ボビー・ヒーナンが頼むのはいつもオレンジジュースだけだったそうだ。父は役に立つときでないと自分を舞台裏に連れて行かなかったと話す。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（27:20〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1640s"]]}, {"cat": "家族", "t": "父に紹介された少年の日", "b": "子どものころ、父ダスティにトリプルHを紹介され、この男は大物になると言われたのを覚えているという。父が裏側を説明してくれなかったので、言われるまま握手したものの怖くて、少し離れたところから眺めているほうが好きだったそうだ。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（28:50〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=1730s"]]}, {"cat": "家族", "t": "母に数字を話すと嘘に聞こえる", "b": "最近の興行収入の記録はあまりに大きく、母に説明するとまるで嘘をついているように聞こえてしまうと笑って話している。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（52:01〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=3121s"]]}, {"cat": "リングに来るまで", "t": "演技の先生の言葉", "b": "演技を習った先生から、名声目当てではなく、これを一生の仕事だと思えば伸びると教わったという。小さなCMの仕事も大作と同じ真剣さで取り組み、一歩ごとに学ぶことが大事だと言われたのを覚えていると話す。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:08:34〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=4114s"]]}, {"cat": "体のこと", "t": "初の世界王座は流血のまま病院へ", "b": "リング・オブ・オナーで初めて世界王座を取った夜は、唇が裂けて流血し、ベルトを抱えたまま歩いて病院へ向かったという。その道中で真っ先に返したメッセージの一つが、トリプルHからの祝福だったそうだ。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:26:19〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5179s"]]}, {"cat": "家族", "t": "妻ブランディもレッスルマニアの舞台に", "b": "トリプルHが妻と並んで入場した思い出を語ったのを受けて、自分の妻ブランディもレッスルマニア40に関わらせてもらえたのは同じ理由でありがたかったと礼を述べている。", "sp": "コーディ・ローデス", "d": "2026-04-09", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-znC6s9yaMOA", "src": [["公式YouTube（1:28:44〜）", "https://www.youtube.com/watch?v=znC6s9yaMOA&t=5324s"]]}]);
  ARTICLES.push({ id: "wdywta-znC6s9yaMOA", d: "2026-04-09", show: "wdywta", who: ["Triple H", "Cody Rhodes"], t: "トリプルHの回　19歳のボディビル大会から、妻と並んだ大舞台の入場まで", lead: "コーディ・ローデスの番組に出た約97分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Triple H", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-znC6s9yaMOA").map((x) => [x.t, x.b, x.sp])), open: ["経営・制作面の話（選手への接し方、プロデューサー論、ビジネスの相棒への評価など）は、指示に沿って控えめにし、ほとんど載せていない。", "番組後半の入場ランキングは、本人の体験や家族に関わる回だけを拾い、ほかの入場の裏話（玉座がリフトで止まりかけた件、映画とのタイアップ入場など）は省いた。", "コーディのリング・オブ・オナー時代の行動について語った部分は、ゲスト本人の素顔の話ではないため載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=znC6s9yaMOA"]] });
  if (!ROSTER.find((r) => r[1] === "Stephanie Vaquer")) ROSTER.push(["ステファニー・バッケル", "Stephanie Vaquer", "lg", "", "", "", ""]);
  if (!PROFILES["Stephanie Vaquer"]) PROFILES["Stephanie Vaquer"] = { lead: "19歳で故郷を離れ、12年かけて夢をつかんだ女子世界王者。語学も体も休みなしで磨き続ける、努力家の素顔が見える回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Stephanie%20Vaquer"]], moves: [], facts: [] };
  if (PROFILES["Stephanie Vaquer"]._weak) { PROFILES["Stephanie Vaquer"].lead = "19歳で故郷を離れ、12年かけて夢をつかんだ女子世界王者。語学も体も休みなしで磨き続ける、努力家の素顔が見える回。"; delete PROFILES["Stephanie Vaquer"]._weak; }
  PROFILES["Stephanie Vaquer"].facts.push(...[{"cat": "家族", "t": "働き者の父が一番のお手本", "b": "ステファニー・バッケルは、努力する姿勢は父から学んだと話す。父は一生懸命に働き続けた人で、自分にとってのヒーローだという。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=196s"]]}, {"cat": "家族", "t": "王座獲得の日は父の誕生日だった", "b": "王座を獲得した大会の日は、客席にいた父の誕生日でもあったという。リングを降りてすぐ父を抱きしめ、言葉は少なく「誕生日おめでとう」とだけ伝えたそうだ。自分の犠牲を一番近くで見てきたのは父だと話す。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（3:16〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=196s"]]}, {"cat": "体のこと", "t": "大会直前の体調不良で出場が危ぶまれた", "b": "その前にも、病気でパリの大会への出場が取りやめになったという。さらに王座を獲る大会の1週間前にも体調を崩し、医師からは出場を止められたと話す。父の航空券も取ってあったため、関係者に何度も頼み込み、最終的に出られることになったそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（4:03〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=243s"]]}, {"cat": "家族", "t": "子どもの頃の「王者になる」宣言", "b": "子どもの頃から「いつか王者になる」と言い続け、父は笑っていたという。父は当時信じていなかったかもしれないが、自分は信じていたと話す。父が次の大舞台に来られるかは、ビザや航空券の問題でまだ分からないそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（6:32〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=392s"]]}, {"cat": "リングの話", "t": "イヨ・スカイとの一戦への敬意", "b": "イヨ・スカイを世界屈指の選手として深く尊敬していると話す。二人の試合は大会の中で最も評価され、ランディ・オートンからも「あの大会を作った試合だ」と声をかけられたそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（7:19〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=439s"]]}, {"cat": "リングに来るまで", "t": "日本で修業した経験が今も生きている", "b": "以前日本でトレーニングしていたので、日本のプロレスの流儀や言葉をある程度知っていると話す。そのおかげで、イヨ・スカイとは試合づくりの意思疎通がしやすいという。打ち合わせは日本語と英語、ときにスペイン語も交じるそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（8:59〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=539s"]]}, {"cat": "暮らし", "t": "日本語は少し忘れてしまった", "b": "数週間前、日本のテレビ番組の取材で、早口の丁寧な日本語の質問が聞き取れず申し訳なく思ったという。日本語は話せるが、使わなくなって忘れてきたと話す。ゆっくり話してもらえれば今も大丈夫だそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（9:48〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=588s"]]}, {"cat": "暮らし", "t": "英語は毎日勉強、先生にも習っている", "b": "英語は毎日勉強していて、先生にも習っていると話す。インタビューは断らず何でも受けるようにしているという。育成ブランドでもスペイン語を話す仲間がいたが、あえて英語で話すようにしていたそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（10:40〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=640s"]]}, {"cat": "暮らし", "t": "自分に厳しく、できない日は泣くことも", "b": "語学では自分に厳しくなりすぎ、うまくいかず泣くこともあったと話す。周りに「大丈夫」と言われ、1年ちょっとで理解は9割、話すのは8割ほどできると考え、自分を誇ることにしたという。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（11:27〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=687s"]]}, {"cat": "リングの話", "t": "スペイン語と英語の切り替えが一番大変", "b": "マイクでは、スペイン語から英語へ途中で切り替えるのが頭の中で止まってしまうほど難しいと話す。今はスペイン語中心で一部を英語にする形に挑戦中で、混乱しつつも勉強になっているそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（13:02〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=782s"]]}, {"cat": "リングの話", "t": "母国語のマイクは感情がまっすぐ出る", "b": "スペイン語のマイクは、翻訳を考えなくていいので気持ちがそのまま出ると話す。ラテン系であることや母国語が好きで、スペイン語を人に知ってもらえるのがうれしいという。スペイン語と英語を混ぜたマイクが好きだそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（13:53〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=833s"]]}, {"cat": "リングの話", "t": "リヴ・モーガンの涙は「うそ泣き」？", "b": "リヴ・モーガンをマイクで泣かせたことについて、彼女は演技がうまいので涙は作り物かもしれないと冗談めかして話す。スペイン語にもワニの涙という同じ言い回しがあるそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（15:32〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=932s"]]}, {"cat": "リングの話", "t": "入場曲と入場の見せ方はまだ探している途中", "b": "曲に問題があって新しい曲に変わったと話す。前の曲が好きだったが、新曲も受け入れてほしいという。以前は歩くだけだった入場に、トリプルHと相談して動きを足してきたが、まだ「何か足りない」と感じているそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（17:57〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1077s"]]}, {"cat": "体のこと", "t": "試合前は落ち着き、終わってから高ぶる", "b": "大きな試合の前は周りが緊張していても自分は静かで、集中して落ち着いているという。気持ちが高ぶるのは試合のあとで、自室に戻って一人になってから考え込むそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（19:41〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1181s"]]}, {"cat": "暮らし", "t": "大きな試合の夜は眠れずジムへ", "b": "大きな試合のあとはエネルギーが余って眠れず、夜中にジムへ行って発散することもあると話す。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（21:17〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1277s"]]}, {"cat": "リングに来るまで", "t": "19歳で故郷を出て12年", "b": "12年前、19歳で母国を出てメキシコへ、その後日本、アメリカと渡ったという。知り合いはコーチなど数人で、家族は近くにいなかった。お祝いは自分のタイトルより父の誕生日を優先し、12年ぶりに一緒に食事をしたそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（22:06〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1326s"]]}, {"cat": "リングに来るまで", "t": "プランBを持たず、10年あきらめなかった", "b": "何度もあきらめかけたが、別の道は一度も考えなかったと話す。夢がかなうと信じていたが、現実は想像以上だったという。国際的に名が知られても満足せず、満足したら学ぶのをやめてしまうので「次は何か」と常に考えているそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（23:38〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1418s"]]}, {"cat": "リングの話", "t": "大技は何年もかけて身につけた", "b": "高所からひねりを加える大技は、5〜6年ほど前に回転を増やしたいと思ったのが始まりだという。最初は下のロープから少しずつ練習し、首や脚を痛めながら回数を増やしたそうだ。メキシコ時代は温存し、この団体に来て使う時が来たと感じたと話す。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（29:14〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1754s"]]}, {"cat": "リングの話", "t": "小柄な自分に合わせた独自の技", "b": "人を持ち上げる技を、小柄な自分でも使えるよう工夫して組み合わせたと話す。脚の力と体の使い方に自信があり、技名は自分の名前の頭文字を取ったものだという。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（32:33〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=1953s"]]}, {"cat": "リングの話", "t": "一度は封印した得意技を取り戻した", "b": "自分の得意技が誤解されることがあり、一度は使いたくなくなったと話す。しかし育成ブランドで解説者のブッカー・Tが盛り上げてくれ、またこの技が好きになったという。今も育成ブランドの客席ではその掛け声が聞こえるそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（34:07〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=2047s"]]}, {"cat": "リングの話", "t": "英語が完璧でなくても王者になれると示したい", "b": "10年前はラテン系の選手が王者になるのは難しく、英語が完璧でないと上に行けないと言われたと話す。自分は今も英語を勉強中なので、時代に合わせて業界が変わる時だと考えているそうだ。見た目や体格の決まりごとも変えたいという。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（38:58〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=2338s"]]}, {"cat": "家族", "t": "最多勝のニュースは母が動画で教えてくれた", "b": "2025年に最多勝だったことは、母がテレビを撮影して送ってくれて知ったという。母は英語が読めるが、本人はその時まで知らなかったそうだ。自分に厳しい性格なので、これを機にこれまでの歩みを誇りに思うようにしたいと話す。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（43:52〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=2632s"]]}, {"cat": "リングの話", "t": "プロレスは総合力の芸術だと思う", "b": "試合の運びだけでなく、表情やカメラ、レフェリー、観客の反応、時間配分まで全部に気を配ると話す。以前は戦うことだけだったので、今はカメラを意識する勉強中だという。女子選手は爪やまつ毛、髪まで整えるので、さらに大変だと感じているそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（47:15〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=2835s"]]}, {"cat": "リングに来るまで", "t": "一軍昇格の知らせに迷い、勇気を出した", "b": "育成ブランドが家のように好きで、残りたい気持ちと上へ行きたい気持ちの間で迷ったという。英語にも自信がなかったが、自分に「勇気を出そう」と言い聞かせて決めたそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（49:40〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=2980s"]]}, {"cat": "暮らし", "t": "休みなしの10年と1年半", "b": "この団体に来て1年半、その前の10年も、ほぼ休みなく走ってきたと話す。最後に休暇を取ったのがいつか覚えておらず、趣味もほとんどないという。お菓子づくりを少し試みたが、すぐ「練習しなきゃ」と考えてしまうそうだ。プロレスは自分の人生だと話す。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（51:14〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=3074s"]]}, {"cat": "体のこと", "t": "回復の柱は睡眠・食事・トレーニングと家族", "b": "体の回復には睡眠と食事とトレーニングが大事だと話す。心の回復も必要で、母と姉に毎日連絡して何気ない話をするのがそれだという。12年も家を離れているため、家族と近くにいることが大きな支えだそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（54:23〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=3263s"]]}, {"cat": "体のこと", "t": "大きなけがはなく、体は9割8分ほど", "b": "12年のキャリアで体はあちこち痛むが、今は大きなけがはないと話す。年間最大の祭典に向けては「98.9%」の状態だという。足首や膝を休めたいが休みが取れず、トレーニングも以前ほどできないそうだ。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（55:56〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=3356s"]]}, {"cat": "体のこと", "t": "かつての重傷を越えて今ここにいる", "b": "以前、引退を考えるほどの大きなけがをしたことがあると話す。その後は大きなけががなく、健康でいられることに感謝しているという。応援してくれる家族とファンへの感謝も語った。", "sp": "ステファニー・バッケル", "d": "2026-04-14", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-cQ1Doy8N8rw", "src": [["番組のYouTube（59:56〜）", "https://www.youtube.com/watch?v=cQ1Doy8N8rw&t=3596s"]]}]);
