  PROFILES["AJ Styles"].facts.push(...[{"cat": "リングの話", "t": "引退してまだ禁断症状", "b": "シェイン・ヘルムズに「泣くなよ」と言われたが、1月に引退したばかりでまだレスリングの禁断症状があるから無理だと返したという。リングもロープも、トップロープから飛ぶのも大きな受け身も、AJスタイルズでいることのすべてが大好きだったと話す。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:16:41〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8201s"]]}, {"cat": "リングの話", "t": "選ばれた者だという誇り", "b": "控室の仲間や出会った人たちは忘れられない宝物だという。プロ野球やバスケットボールの選手よりもプロレスラーの数のほうが少なく、それだけ難しい場所にたどり着いたのだから誇りを持ってほしいと、後輩たちに語りかけた。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:18:16〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8296s"]]}, {"cat": "暮らし", "t": "長い移動も好きだった", "b": "変に思われるかもしれないが、長い飛行機や電車の移動、ヨーロッパや日本のツアーも好きだったという。そこだけは少し恋しいかもしれないと話す。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:19:03〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8343s"]]}, {"cat": "家族", "t": "恋しくない理由は家族", "b": "レスリングが恋しいかと聞かれたら答えは「いいえ」で、毎晩家族のもとへ帰れるからだという。誕生日や子どもの試合を見逃すこともなく、日本からビデオ通話で励ます必要もなくなったと話す。妻と2人きりで出かけて向き合う時間ほどいいものはないそうだ。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:19:50〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8390s"]]}, {"cat": "リングの話", "t": "次の「フェノメナル」を探す仕事", "b": "もうフェノメナルAJスタイルズでいる必要はないが、WWEに残って家族の一員でいられ、自分の仕事は次の「フェノメナル」を見つけることだと語った。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:22:18〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8538s"]]}, {"cat": "信仰", "t": "正しい時に正しい場所へ", "b": "自分の信仰と信じるものが、正しい時に正しい場所へ、正しい人が見ている前へ導いてくれたのだと思うという。自分のような男がこんな場所にたどり着くはずはなかったが、ファンのおかげでここにいると話す。", "sp": "AJスタイルズ", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（2:23:08〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=8588s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Stephanie McMahon")) ROSTER.push(["ステファニー・マクマホン", "Stephanie McMahon", "lg", "WWEの元最高経営責任者", "", "", ""]);
  if (!PROFILES["Stephanie McMahon"]) PROFILES["Stephanie McMahon"] = { lead: "母と3人の娘に送り出されて殿堂入り。プロレス一家に育った日々、娘たちを授かるまでの道のり、夫との出会いを語り、最後はヒール時代の口調で締めくくる。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Stephanie%20McMahon"]], moves: [], facts: [] };
  if (PROFILES["Stephanie McMahon"].lead === "母と3人の娘に送り出されて殿堂入り。プロレス一家に育った日々、娘たちを授かるまでの道のり、夫との出会いを語り、最後はヒール時代の口調で締めくくる。") PROFILES["Stephanie McMahon"]._weak = 1;
  PROFILES["Stephanie McMahon"].facts.push(...[{"cat": "家族", "t": "娘たちを授かるまで", "b": "母親になることを何より望んでいたが、夫婦ともに自然には子どもを持てないかもしれないと告げられ、打ちのめされたという。望むものは戦って手に入れるしかないと学び、現代医療と神の恵みによって3人の娘を授かったと話す。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（39:32〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2372s"]]}, {"cat": "家族", "t": "ツアーバスで育った長女", "b": "長女はツアーバスで育ち、母のブリーフケースにつかまって会議室に運ばれ、強面のプロデューサーたちの前で童謡を歌ったという。その長女に「ママやパパではなく、おじいちゃんの仕事がしたい」と言われたこともあるそうだ。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（40:25〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2425s"]]}, {"cat": "家族", "t": "アメフトを続けた次女", "b": "次女は高校の4年間、チームでただ一人の女子としてタックルありのアメリカンフットボールを続け、練習も試合も一度も休まなかったという。娘たちは自分の一番の贈り物であり、自分を映す鏡だと話す。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（41:14〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2474s"]]}, {"cat": "家族", "t": "殿堂に入るべきは母", "b": "本当に殿堂に入るべきなのは、WWE初の最高経営責任者だった母だと語った。両親には愛情と機会に満ちた人生への感謝を伝え、兄シェインについては、いつも守ってくれ、強くなる方法を教えてくれた人だと話した。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（42:02〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2522s"]]}, {"cat": "リングに来るまで", "t": "リビングにリック・フレアー", "b": "「プロレスは人生」という言葉が自分には文字どおり当てはまるという。家の私道には業界の重鎮が簡易ジャグジーを置き、学校から帰るとリック・フレアーが居間にいて、中学3年のプロムにはハルク・ホーガンが見送ってくれたが、それが普通だったそうだ。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（43:33〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2613s"]]}, {"cat": "リングに来るまで", "t": "子どものころから会社の仕事", "b": "子どものころから雑誌のモデルをし、テレビ初登場はロディ・パイパーの家へのハロウィンの訪問だったという。高校を出る前からコピー取りや封筒詰め、電話の取り次ぎをしていて、WWEで働くことだけが望みだったと話す。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（44:24〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2664s"]]}, {"cat": "リングの話", "t": "14歳の「初デート」はアンドレ", "b": "レッスルマニア3を会場で見て、友人のアンドレ・ザ・ジャイアントがハルク・ホーガンに負けたときは落ち込んだという。14歳ごろ、アンドレの行きつけのフレンチレストランで2人で食事をしたのが「初デート」で、人々が彼をじろじろ見るのが嫌だった、自分にとってはただの友達だったと振り返る。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（46:05〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2765s"]]}, {"cat": "リングの話", "t": "小児がん支援への思い", "b": "ファンの支えで、小児がんの治療法を探す基金に何百万ドルも集めてきたという。子どもたちがスーパースターに扮する映像を流し、悲しいものではなく元気が出るものにしたかったと語った。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（48:35〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=2915s"]]}, {"cat": "リングの話", "t": "ビンタは義母仕込み", "b": "自分のビンタで鼓膜を傷めた人には謝りたいが、責任はビンタを教えてくれた義母にあると笑わせた。そのうえで、家族として温かく迎えてくれたことに感謝した。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（52:36〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=3156s"]]}, {"cat": "家族", "t": "先に口説いたのは夫", "b": "制作会議に黒い革ジャンで現れ、足を投げ出して椅子を揺らすトリプルHに、なぜか惹かれたという。選手との交際は禁じられていたが、紙を丸めて投げてきたり、ぎこちないハグをしたりするうち、ある夜「仕事の話で電話してもいいか」と聞かれ、それから話が尽きなかったそうだ。先に口説いてきたのは夫のほうだと念を押した。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（54:13〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=3253s"]]}, {"cat": "暮らし", "t": "すべてを失ったと思った時期", "b": "雑誌の少女、番組のキャラクター、短い間の会長兼共同最高経営責任者と、人生のすべてをWWEの中で生きてきたという。数年前にはそれを全部失ったと思ったが、夫のおかげで、それはずっと自分の一部だと気づけたと話す。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（55:50〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=3350s"]]}, {"cat": "リングの話", "t": "最後はヒールの顔で", "b": "自分はほとんどヒールだったからと、最後は悪役のボスの口調に切り替え、「当然の評価よ」と言い放って観客を立ち上がらせた。", "sp": "ステファニー・マクマホン", "d": "2026-04-17", "how": "WWE殿堂入り式典（WWE公式）で（字幕を全文確認）", "art": "ext-Go9J8JvWhjY", "src": [["番組のYouTube（56:41〜）", "https://www.youtube.com/watch?v=Go9J8JvWhjY&t=3401s"]]}]);
