  if (PROFILES["Liv Morgan"].lead === "") PROFILES["Liv Morgan"]._weak = 1;
  PROFILES["Liv Morgan"].facts.push(...[{"cat": "リングの話", "t": "NXT初のMSGでピザを落とす", "b": "NXT時代、初めてマディソン・スクエア・ガーデンの興行に出たとき、ニューヨークらしさを狙ってピザの箱を持って入場したとリブ・モーガンは話す。ところがピザを落としてブーイングを浴び、とっさに拾って食べ始めたら歓声に変わったそうだ。床に落ちたピザを食べたが、小道具に負けた一戦だったと笑っている。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（4:45〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=285s"]]}, {"cat": "リングの話", "t": "ビールを手にした入場が大失敗", "b": "20歳のころ、OVWで男性客ばかりの小さな会場の興行に出たという。ショーン・スピアーズとのタッグで、かっこよく見えると思ってビールを持って入場したところ、大きなブーイングと罵声を浴びたそうだ。いま振り返ると、必死に格好をつけただけで、まったくクールではなかったと話す。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（6:22〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=382s"]]}, {"cat": "リングの話", "t": "ブーイングにも自分を説明しない", "b": "自分が誤解されている点を聞かれ、特にないとリブ・モーガンは答える。好きでも嫌いでも観客の感じ方は自由で、わざわざ弁明する必要はないという考えだそうだ。説明しても誤解は残るから、そのままにして次へ進むと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（7:14〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=434s"]]}, {"cat": "リングの話", "t": "最初の成功はマネー・イン・ザ・バンク", "b": "WWEでの最初の成功は、マネー・イン・ザ・バンクに勝ち、同じ夜にロンダ・ラウジーへ挑戦権を行使してスマックダウン女子王者になったことだという。支えてくれたファンと喜びを分け合えたのが誇りだと、リブ・モーガンは話す。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（12:13〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=733s"]]}, {"cat": "リングの話", "t": "年間最大の祭典で初のシングル戦", "b": "大舞台のメインカードでの初のシングル戦を前に、ベビーフェイスの走りはしないと笑う。試合は荒々しく野性的になるはずで、相手は自分を叩きのめしにくるし、自分もそうするだけだと話す。以前にナタリアとプレショーでシングル戦をしたのはコロナ禍で無観客だったので、今回は全く違う体験だとして、家族も来るため、いまに集中したいそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（14:38〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=878s"]]}, {"cat": "リングの話", "t": "ドミニクとは別に、自分ひとりで倒す", "b": "相手のステファニーに、仲間の陰に隠れていると小馬鹿にされたり、仕事への姿勢を疑われたりしてきたとリブ・モーガンは話す。だからこの試合では、誰の力も借りず自分ひとりで彼女を倒すつもりだという。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（18:45〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1125s"]]}, {"cat": "リングの話", "t": "一番好きなレスラーはドミニク", "b": "好きなレスラーを聞かれ、迷わずドミニク・ミステリオと答える。冗談ではなく本気で、一番のお気に入りだと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（44:02〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2642s"]]}, {"cat": "リングの話", "t": "手本にするのは90年代ヒールのHBK", "b": "研究する対象として、リブ・モーガンは、90年代のヒール時代のショーン・マイケルズと、昔のヒール時代のクリス・ジェリコの名前を挙げる。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（48:01〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2881s"]]}, {"cat": "リングの話", "t": "NXTバトルロイヤルでのパワーボム失敗", "b": "NXTに出始めたころ、初の女子バトルロイヤルでカメロンにパワーボムを狙ったとリブ・モーガンは話す。気合が入りすぎて回しすぎ、相手が自分の上に落ちてきたという。ほかにも失敗はあるはずだが、いま一番思い出すのはこの場面だそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（49:39〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2979s"]]}, {"cat": "リングの話", "t": "プロデューサーは全員好き、相談はTJ", "b": "特定の好きなプロデューサーはおらず、やり方の違いから学べるし、自分が一番分かっているとも思わないとリブ・モーガンは話す。練習施設で試した動きをTJ・ウィルソンに見せて意見をもらうこともあるそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（55:10〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3310s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Liv Morgan")) ROSTER.push(["リブ・モーガン", "Liv Morgan", "lg", "元女子世界王者", "", "", ""]);
  if (!PROFILES["Liv Morgan"]) PROFILES["Liv Morgan"] = { lead: "長期欠場を経て「もっと欲しがる」のをやめたら、思わぬ仕事が舞い込んできたと語る。歌もダンスも初挑戦で飛び込む、気取らない人柄がのぞく回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Liv%20Morgan"]], moves: [], facts: [] };
  if (PROFILES["Liv Morgan"]._weak) { PROFILES["Liv Morgan"].lead = "長期欠場を経て「もっと欲しがる」のをやめたら、思わぬ仕事が舞い込んできたと語る。歌もダンスも初挑戦で飛び込む、気取らない人柄がのぞく回。"; delete PROFILES["Liv Morgan"]._weak; }
  PROFILES["Liv Morgan"].facts.push(...[{"cat": "リングに来るまで", "t": "NXT時代、ピザを持って入場", "b": "育成ブランド時代、ニューヨークの大会場での初めての試合に、ご当地らしくピザを持って入場したことがあるという。ところがピザが床に落ちてブーイングを浴び、とっさに拾って食べたら歓声に変わったそうだ。小道具に負けた思い出として笑って振り返っている。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（4:45〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=285s"]]}, {"cat": "暮らし", "t": "どう思われても構わない", "b": "自分について誤解されていることは何かと聞かれ、特にないと答えている。好きでも嫌いでも、ファンがどう感じるかは自由で、わざわざ説明する必要は感じないという。説明しても誤解されることはあるので、そのままにして前に進むそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（7:14〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=434s"]]}, {"cat": "暮らし", "t": "ファンは何があっても味方", "b": "停滞していた時期にも、ネットでも会場でも変わらず声援を送ってくれたファンに深く感謝していると話す。自分の成功の多くは、そうして足を運び続けてくれた人たちのおかげだと感じているそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（10:34〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=634s"]]}, {"cat": "暮らし", "t": "口ぐせは「食べた」", "b": "最近よく使う言い回しが、うまくやった、決まっている、という意味で「食べた」と言うものだという。服装がばっちり決まったときなどにも使うそうで、収録中も何度も口にしていた。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（13:02〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=782s"]]}, {"cat": "家族", "t": "家族そろって大舞台へ", "b": "年間最大の祭典で初めて本戦のシングルマッチに出ることになり、家族全員が会場に来ると話している。自分の力で勝ち取った舞台だと感じているので、喜びもひとしおだという。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（15:29〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=929s"]]}, {"cat": "好きなもの", "t": "初めてのちゃんとした葉巻", "b": "収録会場は葉巻バーで、本人は以前に少しふかしたことがある程度。腰を据えて葉巻を味わうのはこの日が初めてだったという。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（22:03〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1323s"]]}, {"cat": "好きなもの", "t": "歌は車とシャワーで", "b": "新曲を自分で歌わないかと持ちかけられたのがきっかけで、ミュージックビデオまで作ることになったという。本人は歌手ではなく、歌うのは車の中とシャワーくらいだそうだ。撮影前に3日間ほど振り付けやダンスを習い、ダンスのレッスンは生まれて初めてだったと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（22:52〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1372s"]]}, {"cat": "暮らし", "t": "欲しがるのをやめたら運が来た", "b": "ケガをする前は日記をつけ、望みを書き出して引き寄せようとするタイプだったという。いくつもの良い仕事を抱えながら、さらに上を求めていたところでケガをして、すべてを失ったそうだ。いまは求めすぎず、毎日をていねいに過ごすようにしたら、思いがけない話が次々に舞い込んできたと話す。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（28:33〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1713s"]]}, {"cat": "好きなもの", "t": "何にでも飛び込む性格", "b": "自分は「かっこつけて断る」タイプではないと話す。歌も踊りもやったことのないことばかりだったが、試せてうれしかったといい、3日間ポップスターになれた経験に感謝している。配信用のジャケット画像には強いこだわりを見せたそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（32:00〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1920s"]]}, {"cat": "家族", "t": "WWEが家族の暮らしを変えた", "b": "WWEに入って人生が変わり、そのおかげで家族や大切な人たちの暮らしも変えられたと話す。入る前の生活を覚えているからこそ、いまがいっそうありがたいという。ずっと夢見てきた場所なので、頼まれた仕事を断ったり不満を言ったりする気にはならないそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（34:16〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2056s"]]}, {"cat": "体のこと", "t": "ケガで深く落ち込んだ", "b": "もともと「起きることには意味がある」と考える、本人いわく楽観的すぎるほどの性格だという。それでもケガだけは前向きに受け止められず、長いあいだ悲しみに沈んでいたそうだ。夏の大型大会が地元開催だったのに欠場せざるを得ず、半年の離脱で戻る場所がどうなっているのかも分からなかったと振り返る。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（41:38〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2498s"]]}, {"cat": "体のこと", "t": "親友ラケルのひと言で前を向く", "b": "落ち込んでいたころ、親友のラケル・ロドリゲスとビデオ通話で話していて「何も信じられない」とこぼしたという。すると「信じられないと感じるときこそ、いちばん信じるべきとき」と返され、そこでようやく自分を哀れむのをやめられたそうだ。心と体の両面で復帰に向かう出発点になったと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（42:25〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2545s"]]}, {"cat": "暮らし", "t": "飛行機では仲間の前で寝られない", "b": "会社の移動機で、みんなが眠りたがっているのに自分だけ昔の話をし続けてしまったことがあるという。仲間と一緒の飛行機で寝るのは、何をされるか分からないので少し怖いと笑って話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（47:16〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2836s"]]}, {"cat": "リングに来るまで", "t": "人気チェーン店で働いていた", "b": "かつて女性店員の制服で知られるレストランチェーンで働き、店のカレンダーにも載る看板店員だったという。その店で出会った一家は、13年ほど前から大会に足を運び、誕生日やクリスマスにも声をかけてくれる大切な応援団だと紹介している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（47:47〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2867s"]]}, {"cat": "好きなもの", "t": "手本は90年代のヒールたち", "b": "参考に見返すのは、90年代の悪役時代のショーン・マイケルズや、かつてのクリス・ジェリコだと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（48:01〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2881s"]]}, {"cat": "リングに来るまで", "t": "初期の失敗はパワーボム", "b": "印象に残っている失敗は、育成ブランドに出始めたころの女子バトルロイヤルだという。張り切ってパワーボムを狙ったものの、勢いよく持ち上げすぎて回転が過ぎ、相手が自分の上に落ちてきてしまったそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（49:39〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2979s"]]}, {"cat": "暮らし", "t": "プロデューサーはみんな好き", "b": "好きな現場プロデューサーを聞かれ、全員好きだと答えている。やり方はそれぞれ違っても、言われたとおりにやってみると学ぶことがあるという。担当でなくても、練習施設で試したことをTJ・ウィルソンに送って意見をもらうことがあるそうだ。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（55:10〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3310s"]]}, {"cat": "暮らし", "t": "もしもの時のチーム", "b": "一緒に戦う仲間を選ぶなら、自分自身、親友のラケル、メイク担当や警備担当などいつも支えてくれる裏方のスタッフ、そしてドミニクを挙げている。勝てるかは怪しいけれど、一緒に散りたいチームだと話している。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（1:01:31〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3691s"]]}]);
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "飛行機に乗るとすぐ眠る", "b": "飛行機に乗るといつもすぐに眠り、到着まで起きないと、リブ・モーガンが話している。疲れているかどうかに関係なく、乗ったらすぐ寝てしまうように見えるという。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で、リブ・モーガンの話（公式字幕を全文確認）", "src": [["公式YouTube（46:29〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2789s"]], "by": "第三者の話"});
  if (PROFILES["Raquel Rodriguez"]) PROFILES["Raquel Rodriguez"].facts.push({"cat": "暮らし", "t": "リブの親友で頼れる存在", "b": "ケガで落ち込んでいたときに支えてくれた、人生でいちばんの親友だと、リブ・モーガンが話している。面白くて頭が良く、いろいろなことに詳しい人だという。", "sp": "リブ・モーガン", "d": "2026-04-23", "how": "コーディの番組で、リブ・モーガンの話（公式字幕を全文確認）", "src": [["公式YouTube（43:13〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2593s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "20歳、ビール片手の入場で大ブーイング", "b": "下積み時代の育成団体で、ショーン・スピアーズと「美男子タッグ」を組んでいた20歳のころ、ビールを手に入場すればかっこいいと思ったという。結果は大ブーイングで、今思えば無理をしているだけに見えたと笑って振り返っている。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（5:30〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=330s"]]}, {"cat": "体のこと", "t": "においがほとんど分からない", "b": "最近はにおいにほとんど気づかないといい、長年、点鼻薬を使いすぎたせいかもしれないと打ち明けている。客席にいた母親に向かって、点鼻薬は良くないと冗談まじりに呼びかけていた。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（16:17〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=977s"]]}, {"cat": "好きなもの", "t": "葉巻は自由に楽しめばいい", "b": "葉巻好きで、葉巻の専門誌の表紙を飾ったこともある。作法にうるさい人もいるが、正しいやり方はないので気にしなくていいと話す。火が消えたら付け直せばよく、吸い方の手本には映画『ソードフィッシュ』の冒頭がおすすめだという。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（20:20〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=1220s"]]}, {"cat": "家族", "t": "母に本気で叱られた最初のバイト", "b": "母親のミシェルは、どんなばかげたことをしても大抵は許してくれたという。ただ一度だけ本気で怒られたのが、初めてのアルバイト先のベーグル店をクビになったときだったそうだ。自分の働く姿勢は母親ゆずりだと話し、会場に来ていた母に感謝を伝えている。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（33:31〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2011s"]]}, {"cat": "暮らし", "t": "飛行機ではうまく眠れない", "b": "移動の飛行機で、首まくらを使って眠ろうとしても、必ず前に倒れてよだれを垂らしてしまうという。うまく眠る方法が分からないままで、いまは試すのをやめたそうだ。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（46:29〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=2789s"]]}, {"cat": "家族", "t": "祭典は家族の再会の場", "b": "父ダスティ・ローデスは2005年にWWEに再雇用され、2007年に殿堂入りしたという。それ以来、年間最大の祭典の時期は家族の再会の場になっていると話している。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（52:48〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3168s"]]}, {"cat": "家族", "t": "父の服を持ってこられても", "b": "父の服を持ってきて着てほしいと言われることがあるが、それは父のものなので遠慮したいという。日本で父のガウンと帽子を着せられたことがあり、それ以来少し身構えるようになったそうだ。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（57:30〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3450s"]]}, {"cat": "体のこと", "t": "額の傷は巡業初戦の名残", "b": "額には化粧で隠している傷があるという。ルイジアナ州での初めての巡業試合で、ロープから全力で戻ったところに相手のひじが当たって大きく切れ、試合はすぐに止められたそうだ。翌週のテレビ初登場は、太い縫い跡を隠すため横を向いて撮ったと話している。", "sp": "コーディ・ローデス", "d": "2026-04-23", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-fMiQIcW6yUA", "src": [["公式YouTube（59:09〜）", "https://www.youtube.com/watch?v=fMiQIcW6yUA&t=3549s"]]}]);
  ARTICLES.push({ id: "wdywta-fMiQIcW6yUA", d: "2026-04-23", show: "wdywta", who: ["Liv Morgan", "Cody Rhodes"], t: "リブ・モーガンの回　ケガからの立ち直りと、3日間のポップスター体験", lead: "コーディ・ローデスの番組に出た約64分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Liv Morgan", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-fMiQIcW6yUA").map((x) => [x.t, x.b, x.sp])), open: ["試合や抗争、ベルトの話題は省いた。", "殿堂入り式典が好きだという話や、飛行機で長く眠れないという発言は、話者がはっきりしないため載せていない。", "信仰について語っている箇所はない（親友の「信じる」という言葉は前向きさの話として扱った）。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=fMiQIcW6yUA"]] });
  if (!PROFILES["Paige"]) PROFILES["Paige"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Paige"]], moves: [], facts: [] };
  if (PROFILES["Paige"].lead === "") PROFILES["Paige"]._weak = 1;
  PROFILES["Paige"].facts.push(...[{"cat": "リングの話", "t": "マニアのリングで感じた久々の熱", "b": "年間最大の祭典での復帰戦で、ペイジはライトの熱さと会場の熱気を「すっかり忘れていた」と話す。リングに上がると、今の女子選手たちについていかなくてはと感じたそうだ。準備期間は忙しく、ジムに行けたのは前の週に一度だけで、それを悔やんでいるという。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:35〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=95s"]]}, {"cat": "リングの話", "t": "復帰が決まるまでの数週間", "b": "親友のライブポッドキャストに顔を出した日、そこにいた知人のエージェントが復帰の意思を尋ねたと、ペイジは語る。「戻りたい」と答えると、その場の電話から30分ほどで社長との面会が決まり、翌週に会ったという。条件は首の状態と薬物検査の二つで、バーミンガムの病院で朝から夕方まで検査を受け、医師から「帰る準備はできたか」と告げられて号泣したそうだ。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（5:39〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=339s"]]}, {"cat": "リングの話", "t": "「デビューして王座を獲る」の復帰劇", "b": "ペイジは、復帰してそのままタッグ王座を獲ったことを冗談まじりに「デビューすれば王座を獲る」と話す。ブリーと組んでの王座奪取は、周囲も予想しておらず、自分でも事前には知らなかった驚きの展開だったという。同じ試合にいた若手選手が2014年に自分のデビューと王座奪取を予言していたことにも触れ、時を経た巡り合わせを喜んでいる。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（20:49〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1249s"]]}, {"cat": "リングの話", "t": "2017年の復帰初日と控室の抱擁", "b": "約1年半の空白のあと初めて戻った日、ペイジは会場に入れないほど怖かったという。花道へ向かう直前、ステファニーが抱きしめて「ここはいつまでもあなたの家」と耳打ちし、入場したら声を出さず歓声を浴びてみるよう助言してくれたそうだ。実際に観客が爆発的に沸き、最高の瞬間になったとペイジは振り返る。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（31:14〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1874s"]]}, {"cat": "リングの話", "t": "引退スピーチの翌日に告げられたGM役", "b": "復帰から約6週間で首のために引退を余儀なくされたが、引退スピーチの機会をもらえたことに感謝していると、ペイジは話す。翌日、ライターたちに囲まれて「SmackDownのGMになる」と告げられ、口外禁止で大喜びしたという。観客の大歓声が新しい闘志をくれ、試合に出ないぶん生放送のマイク数本に集中できたそうだ。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（35:53〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2153s"]]}, {"cat": "リングの話", "t": "台本が直前に変わるマイクの修羅場", "b": "ある日、プロモの台本を本番直前まで見せてもらえず、承認が出たのは入場前のCM中だったとペイジは話す。要点だけを頭に入れ、あとは自分の言葉で埋めたという。バレンタインカードを読む設定のときは、直前に台本を取り上げられてもいいよう暗記しておいたことが役に立ったそうだ。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（37:24〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2244s"]]}, {"cat": "リングの話", "t": "FCW時代のデュスティの厳しいプロモ教室", "b": "育成施設のFCWで、ペイジは10代でデュスティ・ローデスの指導を受けたと話す。仲間の前で即興をさせられたり、見えない手紙を読んで感情を次々変えさせられたりしたという。ある日不機嫌な出来で罵声を返して飛び出したが、デュスティは優しく諭し、本番の観客を想定して取り組むよう励ましてくれたそうだ。次のプロモでは、あえて歌で勝負して手応えをつかんだという。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（41:15〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2475s"]]}, {"cat": "リングの話", "t": "「色を着ろ」に逆らって貫いた個性", "b": "契約の決め手は人と違うところだったのに、当時の育成施設のコーチからは「華やかなディーバらしく色を着ろ」と言われたと、ペイジは話す。入場での叫び声も止められたが、デュスティは「そのままでいい」とコーチと言い争ったそうだ。青いドレスで臨んだ日にライバルだけが褒められて落ち込んだが、自分は誰にも合わせず貫くと決めたという。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（46:44〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2804s"]]}, {"cat": "リングの話", "t": "最後の挑戦で叶えたい試合", "b": "ペイジは、今回の復帰を、おそらく最後の現役の時間と考えて「楽しむこと」を第一の目標に挙げる。叶えたいのは、自分が出られなかった年間の大型バトルロイヤルや、エリミネーションチェンバーなどの特別ルールの試合だという。引退後に舞台裏でバトルロイヤルを見て、うれしい反面、自分が出られず切なかった思い出も語る。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:22:15〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=4935s"]]}, {"cat": "リングの話", "t": "電撃棒で同僚を驚かせた舞台裏", "b": "番組収録班が舞台裏でいたずらをしていた週、ペイジは本物の電撃棒を渡され、あちこちで人を驚かせたという。「いたずら禁止リスト」にいた同僚にも当ててしまい、2か月ほど口をきいてもらえなかったそうだ。ビンスからは「人に電気を当てるのをやめなさい」と軽く叱られた程度で、のちに制作班の人から、座った椅子に仕込まれた電気で仕返しされたと笑って話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:24:38〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=5078s"]]}]);
  if (!PROFILES["Paige"]) PROFILES["Paige"] = { lead: "酒と薬を断って8年、首の検査を乗り越えてWWEに戻ってきたペイジ。どん底で命を救ってくれた父の言葉や、仲間とセラピーに支えられた回復の日々を、涙ながらに率直に語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Paige"]], moves: [], facts: [] };
  if (PROFILES["Paige"]._weak) { PROFILES["Paige"].lead = "酒と薬を断って8年、首の検査を乗り越えてWWEに戻ってきたペイジ。どん底で命を救ってくれた父の言葉や、仲間とセラピーに支えられた回復の日々を、涙ながらに率直に語った。"; delete PROFILES["Paige"]._weak; }
  PROFILES["Paige"].facts.push(...[{"cat": "体のこと", "t": "酒と薬を断って8年", "b": "番組の冒頭で、断酒・断薬から8年になることを祝福された。以前WWEにいた頃は薬物検査に2度引っかかるなど荒れていて、自分でも「手がつけられなかった」と振り返る。当時は若かったとも話している。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（0:46〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=46s"]]}, {"cat": "体のこと", "t": "復帰に向けて体を作り直した", "b": "戻ると決めてから、できる限り健康になろうと食事に気を配ってきたという。それでも本番の直前の週はサイン会続きでジムに1度しか行けず、前日にピザを食べてしまったことを悔やんでいた。リングでは息が上がり、照明の熱さも忘れていたと笑う。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:35〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=95s"]]}, {"cat": "体のこと", "t": "絞りすぎて「肉をつけて」と言われた", "b": "ディーン・マレンコから、体は仕上がっているが少し肉をつけてもいいと助言されたそうだ。本人も食事と運動を真面目にやりすぎて脚が細くなったと感じており、これからはしっかり食べるつもりだと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（3:09〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=189s"]]}, {"cat": "リングに来るまで", "t": "復帰の話は親友の番組収録から", "b": "親友バニーの番組に呼ばれて行った先で、10年以上の付き合いがある芸能エージェントと再会したのがきっかけだという。その場で「戻りたいか」と聞かれて即答し、30分ほどでWWE幹部ニック・カーンとの面会が決まったそうだ。面会の条件は首の状態と薬物検査の2つだった。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（4:48〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=288s"]]}, {"cat": "体のこと", "t": "首の検査で復帰許可、号泣した", "b": "早朝から夕方まで病院で首の精密検査を受け、医師たちが画面を囲んで話し込む様子に不安になったという。結果は問題なしで、医師に抱きつきながら泣いたと話す。前回は首のけがで引退し、女子のロイヤルランブルなど大きな試合に出られなかったことが心残りだったそうだ。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（7:14〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=434s"]]}, {"cat": "体のこと", "t": "鎮痛剤すら飲まなくなった", "b": "薬物検査の前は、ケシの実入りの食べ物でも口にしていないかと心配になるほどだったという。いまはイブプロフェンさえ飲まないほど、医薬品全般に慎重になっている。10年前の自分なら気にもしなかったはずだと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（8:54〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=534s"]]}, {"cat": "家族", "t": "疲れてサインを渋り父に叱られた", "b": "昔、英国ツアーで疲れ切ってファンの前を素通りしようとしたところ、同行していた父に強い口調で叱られ、サインに戻ったそうだ。父からは「人は言われたことより、どう感じさせられたかを覚えている」と教わったという。父に厳しく育てられたので、自分以外の誰かになりようがないとも話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（12:09〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=729s"]]}, {"cat": "家族", "t": "子どもの頃に断られたサイン", "b": "90年代前半、両親が英国の朝の番組で共演したスパイス・ガールズのエマ・バントンに娘へのサインを頼んだが、断られたという。ほかの子にはサインしていたので深く傷ついたそうだ。後年SNSで伝えると本人から謝罪が返ってきたといい、誰にでも悪い瞬間はあると考えるようになったと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（12:59〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=779s"]]}, {"cat": "暮らし", "t": "SNSの意地悪な声がいちばん怖い", "b": "復帰にあたって一番不安だったのは、ネット上でファンが辛辣になることだったという。いまのところ反応は好意的で、つい延々と見てしまうと笑う。ただ百の好意的な声より一つの悪口が刺さるとも認め、評判が変わりやすいことは覚悟していると話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（16:03〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=963s"]]}, {"cat": "体のこと", "t": "ADHDで話があちこちに飛ぶ", "b": "収録中、話題が次々に移ることについて、自分はADHDなのでと説明していた。本人は謝りつつも、明るく話を続けている。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（21:38〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1298s"]]}, {"cat": "体のこと", "t": "若い頃に転がり落ちたどん底", "b": "若い頃に悪い仲間と飲み歩くようになり、健全とはいえない交際の中で薬物にも頼るようになったという。さらに私的な映像が流出し、深く傷ついたそうだ。首の手術で休養していた時期と重なり、会社からの助けの申し出にも「大丈夫」と言い続けていたと振り返る。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（23:14〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1394s"]]}, {"cat": "体のこと", "t": "痩せこけ、周りをすべて遠ざけた", "b": "当時はひどく痩せ、会社が健康状態を確認するほどだったという。家族も友人も会社の人たちも、自分を嫌っていると思い込んで遠ざけていたそうだ。後にレネイやアミー・リーから、あの頃は本気で心配していたと聞かされたと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（24:06〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1446s"]]}, {"cat": "家族", "t": "「父に命を救われた」", "b": "映像流出のあと、自分を傷つけたいと思うほど追い詰められ、隠れた場所から父に電話をかけたという。父は動じず、冗談まじりに温かく受け止めてくれたそうだ。あれが人生で一番どん底の日で、父が命を救ってくれたと涙ながらに語った。同じように苦しむ人には「あなたは一人じゃない」と伝えたいと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（27:20〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1640s"]]}, {"cat": "体のこと", "t": "仲間とセラピーに支えられた回復", "b": "会社の手配でセラピーを受け、そこで「周りの人とのつながりが何より大事」だと学んだという。オーランドで親友2人と暮らし始めると、2人も一緒に酒をやめ、今も続けているそうだ。2人はロサンゼルスへの引っ越しにもついてきた。依存症のカウンセラーを含め、週に3人のセラピストと話していた時期もあるという。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（28:55〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1735s"]]}, {"cat": "体のこと", "t": "PTSDの震えは今も少し残る", "b": "どん底を抜けたあとも強いPTSDがあり、体が震えることがあったという。今も震えは出るが、当時よりは減ったそうだ。最初の復帰の日は怖くて会場に入れず、関係者に迎えに来てもらったと振り返る。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（30:28〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1828s"]]}, {"cat": "体のこと", "t": "支えにしている言葉と前向き思考", "b": "「変えられることなら悩む必要はない、変えられないことならなおさら」という言葉を胸に置いてきたという。外出先で見知らぬ人に心ない言葉を浴びせられ、トイレで泣いたこともあったそうだ。今も前向きでいるのは簡単ではないが、出したものが返ってくると信じていて、外に出て体を動かすことも助けになると話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（34:20〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2060s"]]}, {"cat": "リングに来るまで", "t": "ダスティ・ローデスに鍛えられた", "b": "18〜19歳で育成施設に入り、ダスティ・ローデスのプロモ教室で鍛えられたという。別れ話の設定で演じさせられるなど課題は厳しく、苛立って言い返し飛び出したこともあったそうだ。そのときダスティは追いかけてきて、期待しているからこそ厳しいのだと諭してくれたという。その後は歌ったり映画の場面を再現したりと殻を破れたと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（40:29〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2429s"]]}, {"cat": "リングに来るまで", "t": "「らしさ」を曲げないと決めた日", "b": "契約されたのは人と違う見た目のおかげだったのに、当時のコーチからは華やかな色の服を着るよう言われ、入場の叫び声も止められかけたという。言われたとおり青いドレスを着た日、褒められたのは別の選手だったそうだ。それを機に、誰かに合わせるのはやめて自分らしくいると決めたと話す。とても色白で、ダスティからは「磁器のお姫様」と呼ばれていた。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（46:44〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=2804s"]]}, {"cat": "暮らし", "t": "家ではソファでだらだら", "b": "サイン会などで移動続きの毎日なので、家にいるときはソファで何もせず過ごすのが好きだという。大型犬を飼っており、よだれがひどいので、家に来る客には着替え用のつなぎを用意しているそうだ。家は寒いくらいにしておくのが好みで、そのほうがよく眠れると話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（51:25〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3085s"]]}, {"cat": "暮らし", "t": "9年組むメイク担当は心の支え", "b": "リアリティ番組の現場で出会ったメイク担当と9年一緒に仕事をしており、どこへでも連れて行くという。友人たちを招いた感謝祭の集まりでは、彼が良かれと思って乾燥機にかけたつなぎを全部縮ませてしまったと笑う。いつも前向きにさせてくれる存在だと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（54:28〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3268s"]]}, {"cat": "家族", "t": "父っ子で、母は最高に破天荒", "b": "自分は父親っ子だと認め、車にはねられた日にも試合に出たというタフな父の話を何度もしていた。母のことは「いい意味でぶっ飛んでいる」と愛情を込めて紹介している。人を自分の目で判断することも、両親から教わったと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（57:44〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3464s"]]}, {"cat": "家族", "t": "母は妊娠に気づかず試合をしていた", "b": "レスラーだった母は、試合中にリングの外へ投げ出されたあと体調を崩して病院へ行き、そこで妊娠7か月だと分かったという。お腹がほとんど目立たなかったそうだ。兄とは14か月違いで、本人は約3.5キロで生まれたと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（58:35〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3515s"]]}, {"cat": "体のこと", "t": "側弯症がある", "b": "自分には側弯症があり、母が妊娠に気づかず試合をしていたせいだと冗談めかして話していた。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:00:05〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3605s"]]}, {"cat": "家族", "t": "卵子凍結を考えている", "b": "34歳を前に、卵子凍結をしたいと考えていると打ち明けた。以前は子どもはいらないと思っていたが、いまは欲しいと感じるようになったという。すぐに産むつもりはなく、数年先を見据えての準備だと話す。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-hUnxyeW8Oig", "src": [["公式YouTube（1:00:56〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=3656s"]]}]);
  if (PROFILES["Lyra Valkyria"]) PROFILES["Lyra Valkyria"].facts.push({"cat": "暮らし", "t": "2014年にペイジの王座奪取を予言", "b": "ライラ・ヴァルキリアは2014年、ペイジのデビュー前日に「明日デビューして王座を奪う」とSNSに書いていたと、ペイジが話している。何年も経って同じ試合に出たことを、感慨深い巡り合わせだと語っていた。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で、ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（21:38〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=1298s"]], "by": "第三者の話"});
  if (PROFILES["Danhausen"]) PROFILES["Danhausen"].facts.push({"cat": "暮らし", "t": "4〜5年来の友人で、とてもいいやつ", "b": "ダンハウゼンとは4〜5年ほどの付き合いで、本当に優しく、独特の存在感を持つ人物だと、ペイジが話している。英国でのサイン会と彼のデビューの週末が重なった際も、秘密を守って何も言わなかったと笑っていた。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で、ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（1:15:13〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=4513s"]], "by": "第三者の話"});
  if (PROFILES["Titus O'Neil"]) PROFILES["Titus O'Neil"].facts.push({"cat": "暮らし", "t": "いたずらで怒らせ、2か月口をきいてもらえず", "b": "24歳頃、撮影クルーとのいたずら企画で本物の電気棒を渡され、いたずら禁止リストに入っていたタイタス・オニールに当ててしまったと、ペイジが話している。彼は激怒して2か月口をきいてくれなかったが、慈善活動にも熱心な本当に優しい人だと語っていた。", "sp": "ペイジ", "d": "2026-04-23", "how": "ステファニーの番組で、ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（1:23:53〜）", "https://www.youtube.com/watch?v=hUnxyeW8Oig&t=5033s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-hUnxyeW8Oig", d: "2026-04-23", show: "wys", who: ["Paige"], t: "ペイジの回　どん底から8年、父と仲間に救われて帰ってきた場所", lead: "ステファニー・マクマホンの番組に出た約89分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Paige"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-hUnxyeW8Oig").map((x) => [x.t, x.b, x.sp])), open: ["私的な映像の流出や当時の交際、自分を傷つけたいと考えた時期の話は要点だけにとどめた。友人やカウンセラー、メイク担当など一般の人の実名は省いた。", "犬の話題は聞き手側の飼い犬の話と混ざっており、ゲスト本人のことと確信できた部分（大型犬を飼っている、客用のつなぎ）だけを載せた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=hUnxyeW8Oig"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wys-trick" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wys-trick" ? Object.assign(x, { art: "wys-cE14EHpFkSw" }) : x);
  for (let i = ARTICLES.length - 1; i >= 0; i--) if (ARTICLES[i].id === "wys-trick") ARTICLES.splice(i, 1);
  if (!PROFILES["Trick Williams"]) PROFILES["Trick Williams"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Trick%20Williams"]], moves: [], facts: [] };
  if (PROFILES["Trick Williams"].lead === "") PROFILES["Trick Williams"]._weak = 1;
  PROFILES["Trick Williams"].facts.push(...[{"cat": "リングの話", "t": "観客13人のデビュー戦で進む道を確信", "b": "トリック・ウィリアムズは、フィラデルフィアの道場でスウィート・ダディ・トリックというキャラクターとして初めて試合をしたと話す。客は12〜13人ほどだったが、これまでで一番熱い空気だったという。しゃべる、上半身をさらす、見せるという自分の持ち味を全部ひとつにできると感じ、2日間眠れなかったそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（41:15〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2475s"]]}, {"cat": "リングの話", "t": "一度きりのSmackDown出演", "b": "育成の新世代グループに入って2週間ほどで、SmackDown行きの知らせが来たとトリック・ウィリアムズは話す。アポロ・クルーズのナイジェリア人ボディガード役で後ろに立ったが、カメラの位置が分からず戸惑ったという。入場のパイロの大音量にも心臓が跳ねた。翌週に新型コロナにかかり、その出演は一度で終わったが、あとで役に立つ経験だったと振り返る。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（46:07〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2767s"]]}, {"cat": "リングの話", "t": "全員デビュー予告から、メロとのタッグ結成へ", "b": "育成ブランドの刷新期、「来週みんなテレビに出る」という噂が流れたが、実際に形になるまでには数年かかったとトリック・ウィリアムズは話す。団体からはカーメロ・ヘイズとの「セット」を命じられた。二人とも本当は単独で行きたかったが、メロが挑戦を受けて立ったことで、自分も多くを学べたという。いま二人がそれぞれ活躍していることを誇らしく語っている。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（48:28〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2908s"]]}, {"cat": "リングの話", "t": "コーチは敵だと思っていた自分が変わった", "b": "トリック・ウィリアムズは、軍人の父のもとで「言われたことをやる」運動の世界で育ち、インディー出身者は自分のブランドを自分で握る意識が強かったと話す。メロは周りと相談しながら、いい作品のために動いていたという。ずっとコーチを敵のように見てきたが、仲間と作り上げていく姿勢を学んだと語る。ときには誰かを引き立てる役を引き受けることも大事だという。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（50:05〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3005s"]]}, {"cat": "リングの話", "t": "リル・ヨッティとの大舞台と、ジンジャーブレッドの案", "b": "トリック・ウィリアムズは、かつてメロのためにしたことを、いまリル・ヨッティが自分のためにしてくれていると話す。ジンジャーブレッドマンのTシャツは自分の案だったという。リル・ヨッティは「近道はしたくない、地方の小さな会場から回りたい」と話し、仲間になりたがっているそうだ。二人とも「すべてが魔法のように見えるべきだ」という考えで、ヨッティ自身が試合をしたいと言っているとも明かした。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（52:25〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3145s"]]}, {"cat": "リングの話", "t": "リングで唱える、母の言葉", "b": "大学時代のどん底で、母に「あなたは神がつくった王。誰のものかを忘れるな。誰にも折れない」と言われたとトリック・ウィリアムズは話す。この言葉を、試合前にリングで声に出すこともあれば、心の中だけで唱えることもあるという。緊張していても、全部を出し切れば十分だと思えて、自信になるそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:02:03〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3723s"]]}, {"cat": "リングの話", "t": "同期のオバとジェヴォンと、競い合うライバル関係", "b": "トリック・ウィリアムズは、自分とオバ・フェミ、ジェヴォン・エヴァンスは、みんなが業界の頂点を目指して競い合う仲だと話す。前年の育成ブランドの大会での試合は、観客の記憶に残る内容にしようと意識していたという。競争は健全で、ネットで話題になるたびにお互いが上を目指すと語っている。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:09:58〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=4198s"]]}, {"cat": "リングの話", "t": "白いコートと「レモンペッパー・ステッパーズ」の由来", "b": "トリック・ウィリアムズは、アトランタの大型商業施設で見つけた白いコートを、大事な場面のためにクローゼットに取っておいたと話す。SmackDownでサミ・ゼインに割って入る登場で、白いコート、白いパンツ、白い靴で現れたという。靴の呼び名は、フィラデルフィアで世話になった大叔父スウィート・ベイビー・ジェームスから受け継いだもので、おしゃれな靴スタシー・アダムスのことだそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:27:53〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=5273s"]]}, {"cat": "リングの話", "t": "コートはどこだ、と皆に聞かれた", "b": "白いコートで登場した翌週、マイケル・ヘイズ、ブルース、トリプルHの全員から「コートはどうした」と聞かれたとトリック・ウィリアムズは話す。トリプルHには「エルヴィス・プレスリーがコートを着ていないのは見たことがない」と言われたそうだ。それ以来ずっと着続け、自分は「選ばれし者」だと証しを語る立場でもあるので、白がよく似合うと話している。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:28:41〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=5321s"]]}]);
  if (!PROFILES["Trick Williams"]) PROFILES["Trick Williams"] = { lead: "20年続けたアメフトでNFLを目指し、入団テストで切られた末にプロレスへたどり着いた。残高14セントの日にWWEから連絡が来たという、回り道だらけの道のりを笑いながら語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Trick%20Williams"]], moves: [], facts: [] };
  if (PROFILES["Trick Williams"]._weak) { PROFILES["Trick Williams"].lead = "20年続けたアメフトでNFLを目指し、入団テストで切られた末にプロレスへたどり着いた。残高14セントの日にWWEから連絡が来たという、回り道だらけの道のりを笑いながら語る。"; delete PROFILES["Trick Williams"]._weak; }
  PROFILES["Trick Williams"].facts.push(...[{"cat": "リングに来るまで", "t": "大卒後は食事を選ぶほどお金がなかった", "b": "大学を出たあと、口座を見て昼と夜のどちらを食べるか決めるほど苦しい時期があったという。両親は頼れば助けてくれたはずだが、一人の男として自分の道を探したかったそうだ。いまの感謝の気持ちは、何もなかったころを知っているからだと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:43〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=103s"]]}, {"cat": "暮らし", "t": "朝4時起きで東海岸向けのオンライン授業", "b": "カリフォルニアでリキシの道場に通っていたころは、東海岸の学校向けにオンラインで授業をするため朝4時に起きていたという。日中はフードデリバリーの配達、夜は練習という毎日だったそうだ。フィラデルフィア時代も同じ生活を送り、実家に戻る道はあえて選ばなかったと振り返る。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（2:29〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=149s"]]}, {"cat": "リングに来るまで", "t": "20年アメフト一筋、目標はNFL", "b": "アメフトは20年続け、ずっとNFLを目指していたという。最初はハンプトン大学に奨学生として進んだが、上を目指すには環境が足りないと感じたそうだ。父は地元の州立大学でプレーしており、地元の名門サウスカロライナ大学は憧れの存在だったと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（6:19〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=379s"]]}, {"cat": "リングに来るまで", "t": "コーチの「君はここに収まらない」で転校を意識", "b": "1年目のシーズン後、筋力トレーニングのコーチに呼び止められ、地元の大きな大学への転校を勧められたという。両親は「やっと言ってくれた」と大賛成だったが、本人は友人や恋人もいて一度は迷ったそうだ。兄からは「思い込みの強さが度を越している」と言われるほどの性格だと笑う。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（8:40〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=520s"]]}, {"cat": "家族", "t": "祖父の死をきっかけにハンプトンを去る", "b": "一度は残留を決めたものの、太もも裏を痛め、恋人とも別れ、父の母校との試合では遅刻で前半出場停止になったという。その試合後、母方の祖父が亡くなったと母から聞かされ、祖父は自分の大学での試合を一度も見られなかったそうだ。そこで「自分のいる場所はここではない」と区切りをつけたと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（12:47〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=767s"]]}, {"cat": "リングに来るまで", "t": "スーツ姿で名門大学に直談判", "b": "在籍もしていないのにスーツで名門大学の施設に乗り込み、エレベーターで最上階へ上がって「フットボールをしに来た」と名乗ったという。春に入学すればチャンスをやると言われ、筋肉を20ポンド増やして臨んだそうだ。200人が参加した入団テストで8人に残り、ウォークオン（推薦なしの入部）組の攻撃部門最優秀選手に選ばれたと振り返る。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（14:24〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=864s"]]}, {"cat": "リングに来るまで", "t": "先発をつかんだ年に名将が辞任", "b": "名将スティーブ・スパリアー夫妻は自分にチャンスをくれ、母にもよくしてくれたと感謝を語る。3年目に先発の座をつかんだが、シーズン途中で監督が突然辞任し、チームは立て直せなかったという。辞任の理由は今も知らないそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（17:33〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1053s"]]}, {"cat": "リングに来るまで", "t": "スタジアムの巨大バナーに自分の姿", "b": "いつもトレーニング室にいた努力が買われ、急きょ代役でチームの撮影モデルを務め、カップやチケットに写真が使われたという。監督の辞任後、スタジアムに掲げられていた監督の巨大バナーは、上半身裸の自分の写真に替わったそうだ。ハンプトンを出る決断が正しかったと思わせてくれた出来事だと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（20:45〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1245s"]]}, {"cat": "リングに来るまで", "t": "体育専攻、教育実習先の高校でコーチに", "b": "専攻は体育教育で、最終学年は教育実習の時間が練習と重なり、チームの練習にほとんど出られなかったという。卒業後は実習先の高校に請われてスパイクを履いたまま子どもたちを指導し、代用教員も務めたそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（23:50〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1430s"]]}, {"cat": "リングに来るまで", "t": "夢のお告げどおりイーグルスのキャンプへ", "b": "いくつもの扉をノックし、最後にフィラデルフィア・イーグルスだけが招き入れてくれる夢を見たという。地元出身のアルション・ジェフリーに頼み込んで一緒に練習し、そこで実習先の高校の大先輩でイーグルスのコーチだったデュース・ステイリーと出会ったそうだ。NFL全32チームのコーチ陣に自分の映像を送り続けた末、代理人なしでルーキーのミニキャンプに招かれたが、最後は解雇されたと振り返る。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（25:26〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1526s"]]}, {"cat": "リングに来るまで", "t": "残高14セントの日にWWEから連絡", "b": "代理人が新リーグ向けに送った映像がきっかけで、翌日WWEからテストの誘いが来たという。タイツをはけるか迷ったが、父に「行って何かしてこい」と背中を押されたそうだ。請求を払い終えて口座が14セントになったとき、ちょうど電話が鳴ったと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（32:27〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1947s"]]}, {"cat": "好きなもの", "t": "3歳でストーンコールドに夢中", "b": "アティテュード・エラ世代で、3歳でストーンコールド・スティーブ・オースチンの決め台詞をまね、それが初めて覚えた汚い言葉だったという。母にプロレスを見るのを禁止されたそうだ。話すこと、人前に立つこと、運動能力がすべて生きる仕事だと気づき、アメフトとプロレスが初めてつながったと振り返る。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（32:27〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=1947s"]]}, {"cat": "リングに来るまで", "t": "元NFL選手の講演家に学んだ二つの教訓", "b": "高校に講演に来た元NFL選手に弟子入りし、オールスター戦の関連行事に同行させてもらったという。殿堂入り選手に長々と身の上を語ってしまい、「自分のことは堂々と“フリーエージェント”と名乗れ」と叱られたそうだ。人気選手と同じ場にいるだけで女性が寄ってくるのを見て、肩書きに寄ってくる人に流されてはいけないと学んだとも話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（34:45〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2085s"]]}, {"cat": "リングに来るまで", "t": "観客13人の初試合で天職を確信", "b": "最初のテストでは「プロレスを学んでから来い」と言われ、フィラデルフィアのインディー団体で修業を始めたという。初試合の観客は12〜13人ほどだったが、人生でいちばん熱い空間に感じ、2日間眠れなかったそうだ。話して、脱いで、魅せる、自分の全部を出せる場所だと分かったと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（41:15〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2475s"]]}, {"cat": "リングに来るまで", "t": "コロナ初日に重なった再テスト", "b": "再テストに呼ばれた日がちょうど新型コロナの流行が始まった日で、ソロ・シコア、ジェイド・カーギル、ティファニー・ストラットンらと一緒だったが全員帰されたという。その後ロサンゼルスに移り、リキシの道場で練習を続けたそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（43:45〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2625s"]]}, {"cat": "リングに来るまで", "t": "入団2週間で本隊の番組に、翌週コロナ感染", "b": "ブロン・ブレイカーやカーメロ・ヘイズらと同期で育成施設に入り、わずか2週間で本隊の番組にアポロ・クルーズの護衛役として出たという。カメラの位置も分からず戸惑ったが評判は良く、翌週にコロナに感染して話は立ち消えになったそうだ。初めて入場口をくぐったとき、花火の音の大きさに心臓が飛び出しそうだったと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（45:22〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2722s"]]}, {"cat": "家族", "t": "海軍出身の父と朝5時のジム通い", "b": "父は海軍出身で、子どものころから朝5時に起きて家を掃除し、ジムやランニングに連れて行かれたという。三人兄弟の真ん中で、けがで退役した父が教員、コーチ、車の修理などあらゆる仕事をする姿を見て育ったそうだ。家族のために誇りを捨てて働く父から、怠けることは選択肢にないと学んだと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（57:15〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3435s"]]}, {"cat": "家族", "t": "10歳で弟の鎖骨を折ってしまった", "b": "兄弟で家の中でプロレスごっこをしていて、10歳のとき7歳の弟を高い所からボディスラムで床に落とし、鎖骨を折ってしまったという。両親の留守中で、人生でいちばん怖い日だったそうだ。弟はいまは元気で、左を痛めたことで右も使えるようになったと冗談めかして話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（57:15〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3435s"]]}, {"cat": "家族", "t": "母の言葉を入場時に唱えることも", "b": "母は「あなたたちはいつか有名になる」と子どもたちに言い聞かせ、自信を吹き込んでくれたという。ハンプトンでどん底にいたとき、「自分が何者かを忘れるな、誰にもあなたは壊せない」と励まされたそうだ。その言葉はいまも入場のときに心の中で、時には声に出して唱える支えになっていると話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:01:13〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3673s"]]}, {"cat": "好きなもの", "t": "いちばん恋しいのはペパロニピザ", "b": "チートデイに食べたいのはピザで、生地は薄めが好みだという。いまは豚肉を断っていて、ベーコンも好きだったがやめたそうだ。お菓子の定番クッキーも今は控えていると話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:04:28〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3868s"]]}, {"cat": "好きなもの", "t": "大会後はラッシュと大きな焼きクッキー", "b": "大きな大会が終わると、婚約者のラッシュ・レジェンドとチェーン店の焼きたてチョコチップクッキーにバニラアイスを乗せたデザートを食べに行くという。少しでも罪悪感を減らすため、クッキーはグルテンフリーにしているそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:06:00〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=3960s"]]}, {"cat": "暮らし", "t": "達成感を味わえるのは見返したときだけ", "b": "試合のたびに「ああすればよかった」と粗探しをしてしまい、その場で満足することはほとんどないという。2年ほど前の試合を見返したときに、ようやくその瞬間の特別さを感じるそうだ。遅れて実感するからこそ、ハングリーでいられるのかもしれないと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:11:29〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=4289s"]]}, {"cat": "好きなもの", "t": "遠征先では二人で動物園へ", "b": "時間があれば、行く先々の街でラッシュと地元の動物園に行くのが二人の楽しみだという。好きな動物はライオンだが、ラッシュはゾウ派で「自分のほうが大きくて強い」と言われてしまったそうだ。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:21:41〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=4901s"]]}, {"cat": "リングに来るまで", "t": "初めて会った大叔父の家に月200ドルで下宿", "b": "プロレスを学ぶためフィラデルフィアへ移った際、父の叔父にあたる大叔父の家に月200ドルで1年間住まわせてもらったという。お金は必要だからではなく、自分で払うことで感謝を知るためだったそうだ。毎日シーフードを料理しながら人生訓を語ってくれた粋な人で、高齢の大叔父を気遣いコロナの流行を機に家を出たと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:23:12〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=4992s"]]}, {"cat": "好きなもの", "t": "「スウィート・ダディ・トリック」は大叔父譲り", "b": "インディー時代のリングネーム「スウィート・ダディ・トリック」は、「スウィート・ベイビー・ジェームズ」と呼ばれる遊び人風の大叔父を手本にしたものだという。のちに育成ブランドの大会がフィラデルフィアで開かれた際、大叔父は会場に来て、自作のTシャツを売っていたそうだ。おしゃれな革靴を「レモンペッパー・ステッパーズ」と呼ぶのも大叔父からの受け継ぎだと話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:25:33〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=5133s"]]}, {"cat": "好きなもの", "t": "白いコートはアトランタで見つけた勝負服", "b": "ラッシュの地元アトランタのモールで見つけたコートで、高い買い物だったため大事な場面まで着ずにしまっておいたという。本隊の番組への登場で白ずくめで着たところ大きな話題になり、関係者から次々に「コートはどうした」と聞かれたそうだ。それ以来、白がトレードマークになっていると話す。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-cE14EHpFkSw", "src": [["公式YouTube（1:27:53〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=5273s"]]}]);
  if (PROFILES["Lash Legend"]) PROFILES["Lash Legend"].facts.push({"cat": "暮らし", "t": "育成施設で出会い、最初は相手にされず", "b": "育成施設を恋愛リアリティ番組にたとえるほどで、当初は「レスラーとは付き合わない」と思っていたのに、結局レスラーと婚約したという。最初に口説いたときは手応えがまったくなく、すぐに撤退したが、実は駆け引き上手なだけだったと、トリック・ウィリアムズが話している。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で、トリック・ウィリアムズの話（公式字幕を全文確認）", "src": [["公式YouTube（4:01〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=241s"]], "by": "第三者の話"});
  if (PROFILES["Lash Legend"]) PROFILES["Lash Legend"].facts.push({"cat": "暮らし", "t": "誰より強いのにトカゲは大の苦手", "b": "一緒に暮らす家にトカゲが出ると大騒ぎで、ドアも自分で開けたがらないという。トカゲを捕まえると尻尾が切れることにも驚いていたそうで、捕まえたトカゲは外の茂みに逃がしていると、トリック・ウィリアムズが話している。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で、トリック・ウィリアムズの話（公式字幕を全文確認）", "src": [["公式YouTube（1:19:22〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=4762s"]], "by": "第三者の話"});
  if (PROFILES["Carmelo Hayes"]) PROFILES["Carmelo Hayes"].facts.push({"cat": "暮らし", "t": "コンビ時代に学んだ「一緒に作る」姿勢", "b": "互いに単独で活躍したかったが、コンビを組むよう言われ、カーメロ・ヘイズは前向きに引き受けたという。インディー出身で自分を売り込むことに慣れており、制作陣と関係を築いてアイデアを出す姿から、言われたことをこなすだけでなく共に作り上げることを学んだと、トリック・ウィリアムズが話している。", "sp": "トリック・ウィリアムズ", "d": "2026-04-30", "how": "ステファニーの番組で、トリック・ウィリアムズの話（公式字幕を全文確認）", "src": [["公式YouTube（49:13〜）", "https://www.youtube.com/watch?v=cE14EHpFkSw&t=2953s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-cE14EHpFkSw", d: "2026-04-30", show: "wys", who: ["Trick Williams"], t: "トリック・ウィリアムズの回　ウォークオンの大学アメフトから、観客13人の初試合まで", lead: "ステファニー・マクマホンの番組に出た約91分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Trick Williams"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-cE14EHpFkSw").map((x) => [x.t, x.b, x.sp])), open: ["リル・ヨッティやオバ・フェミ、ジェボン・エバンスとの関係は、大会に向けた話が中心のため載せていない。", "後半のステファニー自身の殿堂入りや家族の話、元交際相手や私人の実名は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=cE14EHpFkSw"]] });
  if (!ROSTER.find((r) => r[1] === "Bayley")) ROSTER.push(["ベイリー", "Bayley", "lg", "", "", "", ""]);
  if (!PROFILES["Bayley"]) PROFILES["Bayley"] = { lead: "プロレスに憧れた内気な少女は、インディーから育成施設、そして頂点へと歩んだ。弱さも迷いも率直に語る、努力家の素顔に迫る回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Bayley"]], moves: [], facts: [] };
  if (PROFILES["Bayley"].lead === "プロレスに憧れた内気な少女は、インディーから育成施設、そして頂点へと歩んだ。弱さも迷いも率直に語る、努力家の素顔に迫る回。") PROFILES["Bayley"]._weak = 1;
  PROFILES["Bayley"].facts.push(...[{"cat": "暮らし", "t": "短い髪は手入れがラクで気に入っている", "b": "ベイリーは、髪を切って1年あまりがたち、ようやく今の短さに慣れたと話す。朝起きてそのまま出かけられるほど手入れがラクで、自分でも男の子になった気分だという。切った当時は楽屋中が騒然とし、本人も1か月ほどは驚きが抜けなかったそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（0:46〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=46s"]]}, {"cat": "好きなもの", "t": "子どものころ専門誌を買い集めていた", "b": "ベイリーは、子どものころ公式の会報誌を定期購読し、スーパーやドラッグストアで見つけたプロレス専門誌も買っていたと話す。知らないインディー選手を知るのが楽しかったという。その専門誌の年間ランキングで1位になり、表紙まで飾ったことを、信じられないと語っている。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（1:34〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=94s"]]}, {"cat": "好きなもの", "t": "ビールは飲むが、苦いIPAは苦手", "b": "ベイリーは、お酒の知識はないがビールは飲むと話す。ただしIPAは自分には強すぎて普段は飲まないという。番組で出されたビールは、初めて飲んだときから気に入っているそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（3:53〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=233s"]]}, {"cat": "家族", "t": "ファン時代、父や継母が会いに連れて行ってくれた", "b": "ベイリーは、10代のころ人気選手に会うため、父の運転で遠くの町まで通ったと話す。ファストフード店の行列に並んで会った選手もいたという。継母も何度か付き添ってくれ、家族は「変わった子だけど応援しよう」という空気だったそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（6:19〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=379s"]]}, {"cat": "リングに来るまで", "t": "憧れはリタ。自分もなれると思えた", "b": "ベイリーは、12、13歳のころ、個性的な服装と髪の女子選手リタを見て、レスラーになりたいと強く思ったと話す。当時は内気なおてんば娘で、自分には無理だと考えていたそうだ。インディーの試合を生で見て、選手も同じ人間だと知り、本気で目指す決心がついたという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（7:04〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=424s"]]}, {"cat": "リングに来るまで", "t": "母に反対され、18歳まで入門を待った", "b": "ベイリーは、17歳のときファン向けのイベントで道場の勧誘を受けたが、母が反対していたため、18歳になるまで待ったと話す。1年後に自分から連絡して入門したそうだ。長いあいだ、道場の練習生で女性は自分ひとりだったという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（8:35〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=515s"]]}, {"cat": "リングに来るまで", "t": "ロープ走りで肋骨が痣だらけになった", "b": "ベイリーは、受け身よりもロープ走りがつらかったと話す。ロープは針金にテープを巻いたもので、肋骨が痣だらけになり、当時の恋人が抱きしめようとしても痛くて触らせられなかったという。慣れるまでは時間がかかったそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（10:11〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=611s"]]}, {"cat": "リングに来るまで", "t": "自信をくれた恩人はセリーナ・ディーブ", "b": "ベイリーは、1年目から技は覚えたが、自信がついたのは入門から3年半ほどたち、セリーナ・ディーブと出会ってからだと話す。セリーナはタッグパートナーとして目をかけ、女子専門の団体につないでくれたそうだ。ベイリーは、感謝してもしきれないと語っている。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（11:03〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=663s"]]}, {"cat": "リングに来るまで", "t": "膝を痛めた日の試合がWWE入りのきっかけに", "b": "ベイリーは、膝を痛めていたのに出場したインディーの大会で、観客席にいた人が声をかけてくれたと話す。その後、思いがけず3日間のトライアウトに呼ばれたという。参加者で女子レスラーは自分だけで、ほかの人に技を教えて回ったのが評価され、契約につながったそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（13:24〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=804s"]]}, {"cat": "リングに来るまで", "t": "育成時代、マイクの練習のたびに泣いていた", "b": "ベイリーは、育成施設の時代は個性もキャラもなく、ただの「プロレスが好きな人」だったと話す。何を話しても面白くないと言われ、自分とは何かを問われて、毎回泣いてしまったそうだ。少人数の特別クラスで根気よく教わったという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（15:00〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=900s"]]}, {"cat": "リングに来るまで", "t": "抱きつき魔のキャラは、ただのファン心から生まれた", "b": "ベイリーは、育成時代に先輩選手を褒めちぎる練習をさせられ、それがきっかけで熱狂的なファンのキャラが生まれたと話す。映画『スーパースター』を見直し、12歳のころの自分を思い出して細部を作ったという。作り物ではなく、本当の自分に近かったことが受けた理由だと振り返っている。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（15:51〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=951s"]]}, {"cat": "好きなもの", "t": "入場のタッセルはマッチョマンへの愛から", "b": "ベイリーは、入場衣装のタッセルは、マッチョマンが好きだったことから来ていると話す。ほかに同じことをする女子がいなかったのも理由だという。髪も、エクステやカールが苦手でポニーテールにしていたら、それがちょうど合ったそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（17:27〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=1047s"]]}, {"cat": "リングの話", "t": "同期の4人とは仲良しというより、負けたくない仲だった", "b": "ベイリーは、サーシャとシャーロット、ベッキーは移動も一緒で親しかったが、自分は少し輪の外にいたと話す。仕事では互いにプロとして向き合い、「でも自分のほうが上になる」と全員が思っていたそうだ。ベイリーは、自分は違うスタイルで、いちばん長く続けられる選手になると信じていたという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（19:52〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=1192s"]]}, {"cat": "リングの話", "t": "30分一本勝負は、眠れないほどの重圧だった", "b": "ベイリーは、サーシャとの30分の特殊マッチが決まったとき、どう組み立てればいいか見当もつかなかったと話す。連日、夜通しメッセージで案を出し合い、目の下にクマができていたという。もともと一度きりの試合のはずが、もう一度組まれたことにも驚いたそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（25:42〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=1542s"]]}, {"cat": "リングの話", "t": "同期が昇格し、ひとりで育成の顔になった", "b": "ベイリーは、王座を取った直後に3人が一軍へ上がり、育成の女子部門で自分がリーダーになったと話す。新人ばかりの中で、相手を良く見せつつ自分も王者らしく見せる技術を身につけたそうだ。もともと人をつなぐのが好きな性格で、自然に役を引き受けたという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（28:00〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=1680s"]]}, {"cat": "リングの話", "t": "初めての年間最大の祭典は、期待と重圧の連続", "b": "ベイリーは、初出場の大舞台で4人での王座戦を任され、「4人で戦う試合は苦手」とプレッシャーを感じていたと話す。ただ、そばに親友のサーシャがいたことで落ち着けたそうだ。子どものころは別の星の出来事に見えた舞台に立ち、家族も会場にいて、一日中感情があふれていたという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（31:17〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=1877s"]]}, {"cat": "体のこと", "t": "肩を痛めて欠場し、観客に冷たくされた", "b": "ベイリーは、肩を脱臼して大きな大会を欠場した初めての離脱経験を語っている。復帰前にファンへ感謝を伝えようとしたが、観客に野次られ、傷ついたそうだ。理由が分からず、早く会場を出たかったという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（34:42〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=2082s"]]}, {"cat": "リングの話", "t": "優しいキャラのせいで大きな試合に呼ばれなかった", "b": "ベイリーは、同期が過酷な試合で活躍する一方、自分は優しいキャラのせいで、そうした場に置かれにくかったと話す。腕相撲の試合や変わった裏の企画ばかりを任され、育成時代より後退したと感じたそうだ。そのころから、変わらなければという焦りが強まったという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（37:57〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=2277s"]]}, {"cat": "リングの話", "t": "初代の女子タッグ王座は、いちばん誇れる思い出", "b": "ベイリーは、サーシャと初代の女子タッグ王者になったことを、最も誇れる出来事のひとつに挙げている。それまでタッグの駆け引きを学ぶ機会はなかったが、真剣に組んでから、複雑な物語が作れる面白さに目覚めたという。多くの女子が並ぶ試合を見せられるのも魅力だと話す。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（39:33〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=2373s"]]}, {"cat": "リングの話", "t": "王座を失い、泣いた週に悪役への転身を決めた", "b": "ベイリーは、大きな檻の試合で王座を失い、泣き崩れたあと、同じ自分では戻れないと考えたと話す。会社に自分の案を伝え、わずか数日でキャラを一新することになったそうだ。親しまれたぬいぐるみを切り、髪も切って、「脱皮するようだった」と語る。怖さもあったが、新しい始まりに感じたという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（48:16〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=2896s"]]}, {"cat": "リングの話", "t": "「お手本」の異名は、マイクから自然に生まれた", "b": "ベイリーは、悪役としての最初のマイクで、自分なりの理由を語ることを大事にしたと話す。ファンがそこから「お手本」と呼び始め、新しい異名として定着したそうだ。当初はエディ・ゲレロのように不機嫌な人物を目指したが、状況の変化で、やや大げさで癇に障る人物に育ったという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（53:18〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=3198s"]]}, {"cat": "暮らし", "t": "試合を見返して褒めてくれる人がいる", "b": "ベイリーは、制作担当のTJ・ウィルソンが誰よりも試合を見返し、良かった点を教えてくれると話す。そのおかげで何を続ければよいか分かるという。心理面ではサーシャに相談し、人によって相談相手を分けているそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（56:26〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=3386s"]]}, {"cat": "暮らし", "t": "サーシャは仕事仲間であり、いちばんの親友", "b": "ベイリーは、サーシャを家族の悩みも相談できる親友だと話す。ライバルとして戦ううちに、どんな試合でも安心して任せられる信頼ができたという。いま別々の物語に進んでいても、毎日のように連絡を取り合っているそうだ。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（1:01:05〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=3665s"]]}, {"cat": "リングの話", "t": "檻の試合は一番やりたくない試合だった", "b": "ベイリーは、はしごやTLCの試合には憧れがあったが、檻の試合は怖くて避けたい種類だったと話す。それでもサーシャとの試合では、過去の試合とは違う使い方を考え抜いたそうだ。昔のキャラのままなら、そうした試合は任されなかったと振り返っている。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（1:06:12〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=3972s"]]}, {"cat": "体のこと", "t": "限界を感じたら、数日ひとりで休みを取る", "b": "ベイリーは、長く走り続けるうちに疲れが出るため、恋人に頼んで数日ひとりで過ごす時間をもらうことがあると話す。遠くの町へ3日ほど行き、頭を切り替えるそうだ。気持ちの整理が仕事に欠かせないという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（1:14:14〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=4454s"]]}, {"cat": "暮らし", "t": "他人ばかり優先せず、自分のことも考えるようにした", "b": "ベイリーは、これまで共演者を良く見せることに力を注いできたが、今年は自分を優先するようになったと話す。それが自分の成長につながったそうだ。自分が上に立てば、周りも引き上げられるという考えだという。", "sp": "ベイリー", "d": "2026-05-02", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pF-xbXNorGM", "src": [["番組のYouTube（1:16:39〜）", "https://www.youtube.com/watch?v=pF-xbXNorGM&t=4599s"]]}]);
