  if (!PROFILES["Shawn Michaels"]) PROFILES["Shawn Michaels"] = { lead: "育成部門で若手を導くショーン・マイケルズが、妻と二人の子との暮らしや、不器用だった若い頃を語る。完璧主義で自分を責めた過去が、いまの優しい指導につながっているという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Shawn%20Michaels"]], moves: [], facts: [] };
  if (PROFILES["Shawn Michaels"]._weak) { PROFILES["Shawn Michaels"].lead = "育成部門で若手を導くショーン・マイケルズが、妻と二人の子との暮らしや、不器用だった若い頃を語る。完璧主義で自分を責めた過去が、いまの優しい指導につながっているという。"; delete PROFILES["Shawn Michaels"]._weak; }
  PROFILES["Shawn Michaels"].facts.push(...[{"cat": "家族", "t": "ドキュメンタリーへの出演は子どもたち次第", "b": "ショーンは、子どもを守りたい気持ちから、ドキュメンタリーに出るかどうかは子どもたちに任せたと話す。娘のシャイアンは引き受けたが、息子のキャメロンはカメラの前に立つのが苦手で断ったそうだ。それでもキャメロンは作品のキービジュアルを手がけ、家族みんなで関われたことをショーンは喜んでいる。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（2:25〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=145s"]]}, {"cat": "家族", "t": "息子の職場で起きた気まずい出来事", "b": "息子のキャメロンが職場の同僚といるところへ、トリプルHが親戚のおじさんのように気軽に話しかけてきたことがあったという。キャメロンは同僚を紹介したいのに、どうしていいか分からず困ったそうだ。二世と呼ばれることに悩む子どもたちへ、ショーンは「仕事ができなければ会社は容赦しない。自分で証明するしかない」と伝えている。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（7:10〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=430s"]]}, {"cat": "家族", "t": "妻レベッカが始めたホームスクール", "b": "キャメロンは赤ちゃんの頃、よだれが多く舌に少し問題があったという。妻のレベッカは「学校でいじめられるかもしれない」と考え、自宅学習を調べ始めた。やると決めたら猛烈に打ち込む人で、幼稚園から卒業まで教え、のちに娘のシャイアンも同じように教えたそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（11:10〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=670s"]]}, {"cat": "家族", "t": "契約の交渉は妻の担当", "b": "レベッカは家族の支えであるだけでなく、仕事の面でも裏で支えている。ショーンによれば、直近の契約を交渉したのも妻だという。会社への思いが強すぎて自分は押しが弱いため、線引きが苦手な部分は妻に任せていると話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（12:45〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=765s"]]}, {"cat": "リングの話", "t": "育成部門では厳しすぎない指導を大事にする", "b": "ショーンによると、育成部門には基礎から応用まで段階を踏んで教える仕組みがあるという。一方で、自分たちが受けた荒っぽい厳しさは必須ではないと考えているそうだ。感情の乱れは弱さではなく別の理由から来ることもあると捉え、まず支えてから立て直す方針だと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（15:52〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=952s"]]}, {"cat": "体のこと", "t": "若い頃は自分を責め、弱さから道を外れた", "b": "ショーンは、大学に行かなかったことで自分には資格がないと思い込んでいたという。若い頃は不安でいっぱいで、強く正しい判断をする代わりに楽な方へ流されたと、自分の弱さを認めている。一緒に過ごした仲間の多くはもう亡くなり、自分も同じ道をたどっていたかもしれないと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（19:00〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=1140s"]]}, {"cat": "リングの話", "t": "初めての試合は相手の顔も知らないまま", "b": "ショーンは、デビュー戦の前に誰からも試合の進め方を教わらなかったという。相手のアート・クルーズとは控室が別で、リングで初めて顔を合わせたそうだ。入場曲もなく、相手の動きを見ながら探り合い、途中で相手が話しかけてくれて試合になった。試合後、先輩のテリー・テイラーに「初めてか」と聞かれ、「悪くなかった」と言われたという。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（22:06〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=1326s"]]}, {"cat": "リングに来るまで", "t": "下積みは週7日の試合から", "b": "ショーンは、最初の半年間に出会ったベテランたちが皆とても親切で、教えることを楽しんでいたと話す。当時は週に7日試合をし、土日は1日2試合という日もあり、最初の週だけで9試合をこなしたそうだ。その後カンザスシティへ移ったが、車の中で先輩に質問を重ねたことが大きな学びだったという。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（24:30〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=1470s"]]}, {"cat": "リングの話", "t": "一人前になるまでには約3年かかる", "b": "ショーンは、まったくの未経験者を本隊で通用するまで育てるには3年が目安だと話す。自分は数か月で何百試合もこなしたが、今は試合数が少なく、育成の場だけでは経験が積みにくいという。そのため他団体との提携や会場を回る興行で、試合経験を増やす工夫をしているそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（27:40〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=1660s"]]}, {"cat": "リングの話", "t": "ダブルノックアウトは舞台裏の指示から生まれた", "b": "ショーンは、テレビ収録後のダークマッチでパット・パターソンから「ダブルノックアウトで、絶対に動くな」と言われたと話す。客席が静まり返るなか、しばらく倒れたまま待つのは地獄のようだったという。それでも観客が席に戻り始め、パットの狙いどおりに試合が盛り上がった。この形は、その後10年ほど二人の定番になったそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（30:08〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=1808s"]]}, {"cat": "リングの話", "t": "「トリプルH」の呼び名は自分が先に言い出した", "b": "ショーンは、後にトリプルHとなる友人を、ダブルAことアーン・アンダーソンになぞらえてずっと内輪で「トリプルH」と呼んでいたと話す。ビンスに一度話したときは「似すぎている」と却下されたが、のちに時期が変わり、その名で呼ぶことが認められたという。呼び名の発案は自分だったと、少し誇らしげに語っている。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（33:30〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2010s"]]}, {"cat": "好きなもの", "t": "高校時代はハードロックを聴いていた", "b": "ショーンは、高校の頃はスコーピオンズやジューダス・プリーストを聴いていたと話す。カーティス・ヘニングは同じ頃カントリーが好きで、よく一緒に車で移動していたという。当時はカセットテープの時代で、そこから生まれた思い出が多いそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（35:05〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2105s"]]}, {"cat": "リングの話", "t": "「ハートブレイク・キッド」の名の由来", "b": "ショーンは、この異名はカーティス・ヘニングが流したクリス・ルドゥーの曲から生まれたと話す。本人は最初「もっと男らしい名前がよかった」と思い、曲の印象も良くなかったという。ただ、プロモで口にしたことで定着したそうだ。名前の発案者としてカーティスの功績を大きく評価している。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（35:05〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2105s"]]}, {"cat": "リングの話", "t": "嫌われ役を受け入れてから楽になった", "b": "ショーンは、理想の自分はもっと強面だったが、与えられたキャラクターを受け入れるほど楽しくなったと話す。観客の反応が大きいほど面白さも増したという。今の若い人から「あの頃のHBKは手に負えない存在だった」と言われると、嬉しくてたまらないそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（36:39〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2199s"]]}, {"cat": "リングの話", "t": "入場したら一瞬、会場を見渡してほしい", "b": "ショーンは、現役当時は競争心が強く、今この瞬間を楽しむ余裕がなかったと振り返る。だから今の若手には、リングへ向かうとき一度立ち止まり、客席を見渡して「自分はここまで来た」と味わうよう教えているという。ここに立てる人は世界でごく少数だという考えからだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（38:22〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2302s"]]}, {"cat": "体のこと", "t": "完璧主義で自分を責め続けた", "b": "ショーンは、現役時代は思い描いたとおりにいかないとひどく気にしたと話す。完璧を求める性格が悪い方向に出て、自分を責め、周囲にも当たってしまったそうだ。仕事に全てを注いでいて他に頼れるものがなかったため、楽しむ余裕を持てなかったと振り返る。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（40:00〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2400s"]]}, {"cat": "リングの話", "t": "良い父になったことで良いコーチになれた", "b": "ショーンは、「良いコーチは良い父になるか」と聞かれ、実際は逆で、良い父であることが良いコーチにつながったと答えたという。我が子に向ける思いやりを選手にも向け、人を簡単に裁かないようにしているそうだ。悩みを抱えた選手が立て直せるよう助けるのが自分の役目だと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（43:08〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2588s"]]}, {"cat": "家族", "t": "厳しい家庭で育ち、兄たちに引け目を感じた", "b": "ショーンは、自分が育った家は規律が厳しく、勝つことが大事にされていたと話す。二人の兄は大学を出ていたが、自分は進学しなかったため、いつも「自分は賢くない」という引け目があったそうだ。やりたいことが周りとまるで違ったことも、不安の理由だったという。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（51:03〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3063s"]]}, {"cat": "リングに来るまで", "t": "12歳でプロレスラーになると決めた", "b": "ショーンは12歳のときにテレビでプロレスの中継を見て、空中技の映像に心をつかまれたという。当時のテキサスの団体には人気の悪役やベテランが多く、その世界がたまらなく格好よく見えたそうだ。母に「プロレスラーになる」と伝えたが「そうね」と軽く流された。それでもその気持ちは冷めなかったと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（51:57〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3117s"]]}, {"cat": "リングに来るまで", "t": "雑誌とケーブルテレビでプロレスにのめり込む", "b": "ショーンは、プロレス雑誌を買い、ランキングを眺めて業界のことを学んだという。やがてケーブルテレビが普及し、ダラスやアトランタ、ニューヨークの団体の試合まで見られるようになった。何人もの名レスラーを画面で追いかけ、大人になっても熱は冷めなかったと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（53:30〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3210s"]]}, {"cat": "家族", "t": "子どもたちも同じ会社で働く", "b": "ショーンの子どもたちは今、それぞれ会社の仕事に就き、自分の仕事が画面に出る喜びを知ったという。選手の見た目や衣装、グラフィックに自分が関わったと家族で盛り上がるそうだ。かつては父の仕事がよく分からなかった子どもたちが、いまは「パパの気持ちが分かった」と言ってくれるとショーンは話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（54:21〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3261s"]]}, {"cat": "暮らし", "t": "時間厳守と「イエス・サー」の習慣", "b": "ショーンの父は軍人で、時間に遅れないことが厳しく身についたという。自分は約束の5分前には着いていて、若い人にも「イエス・サー」と返してしまうそうだ。決まった型のある環境のほうが力を出せるタイプで、周りの人にもそれは知られていると話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:02:24〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3744s"]]}, {"cat": "家族", "t": "結婚はラスベガスの教会で", "b": "ショーンとレベッカは出会って間もなく結婚し、ラスベガスの小さな結婚式場で式を挙げたという。ショーンはそれをとても楽しい思い出として話している。ところが帰宅後も気分が盛り上がったままのショーンと、日常に戻ろうとするレベッカの間には温度差があったそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:03:17〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=3797s"]]}, {"cat": "家族", "t": "会計を学んでいた妻", "b": "レベッカは結婚前、大学で会計を学んでいたという。数字に強く、いまも家の資産管理や税金まわりを仕切っているとショーンは話す。頭が良く働き者で、何にでもなれた人だと誇らしげに語っている。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:07:19〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=4039s"]]}, {"cat": "家族", "t": "掃除より一緒にいる時間を選んでくれる妻", "b": "レベッカは家をきれいに保つよう育てられたが、ショーンが望むのは片づいた家より自分と過ごす時間だと分かっているそうだ。そのため、ショーンが出かけてからこっそり掃除をするという。ショーンは、妻が自然にやってくれることに今も気づけないことが多いと笑っている。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:09:47〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=4187s"]]}, {"cat": "家族", "t": "最初の子は思ったより早く授かった", "b": "結婚の少し前、ショーンは空港から電話中の彼女に「君との子どもがほしい」と伝えたという。結婚後は「半年は二人で楽しもう」と話していたが、数日後には妻が食べ物を次々平らげ、片づけに夢中になる様子から妊娠が分かった。結局まだ6週目で、予定よりずっと早くキャメロンを授かったそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:11:20〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=4280s"]]}, {"cat": "暮らし", "t": "引退後は牧場暮らしを選んだ", "b": "ショーンは、家に戻るべきだと感じて引退し、子どもたちのそばで暮らすことを優先したという。サンアントニオ北部の家と事業を手放し、さらに西へ移って牧場を買ったそうだ。将来が完全に安泰だったわけではないが、そのときの流れに従って決めてきたと話す。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:13:46〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=4426s"]]}, {"cat": "家族", "t": "フロリダ移住は妻の決断が早かった", "b": "育成施設を見学して帰ったショーンの様子から、妻のレベッカはすぐに気持ちを察したという。レベッカ自身も、引退して業界から離れた夫に驚いていたと話す。フロリダ行きを決めてからは、家探しの下調べから荷造りまで進め、1か月で一家の引っ越しを終えたそうだ。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-e0IajG9N2ik", "src": [["公式YouTube（1:16:10〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=4570s"]]}]);
  if (PROFILES["Je'Von Evans"]) PROFILES["Je'Von Evans"].facts.push({"cat": "暮らし", "t": "ジェボン・エヴァンスとは気が合う", "b": "ジェボン・エヴァンスとはお互いをよく分かり合えていて、指導の仕方も他の選手とは変えている、と、ショーン・マイケルズが話している。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で、ショーン・マイケルズの話（公式字幕を全文確認）", "src": [["公式YouTube（44:41〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2681s"]], "by": "第三者の話"});
  if (PROFILES["Trick Williams"]) PROFILES["Trick Williams"].facts.push({"cat": "暮らし", "t": "トリック・ウィリアムズは負けん気の強い働き者", "b": "トリック・ウィリアムズは粘り強い闘争心の持ち主で、仕事をいとわないため、多めに課題を出して鍛えられる選手だった、と、ショーン・マイケルズが話している。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で、ショーン・マイケルズの話（公式字幕を全文確認）", "src": [["公式YouTube（45:30〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2730s"]], "by": "第三者の話"});
  if (PROFILES["Oba Femi"]) PROFILES["Oba Femi"].facts.push({"cat": "暮らし", "t": "オバ・フェミは文句を言わない模範的な選手", "b": "オバ・フェミは不満を言わず、試合の終わり方の案が変えられても受け入れる、いつもプロ意識の高い選手だった、と、ショーン・マイケルズが話している。", "sp": "ショーン・マイケルズ", "d": "2026-05-07", "how": "ステファニーの番組で、ショーン・マイケルズの話（公式字幕を全文確認）", "src": [["公式YouTube（46:20〜）", "https://www.youtube.com/watch?v=e0IajG9N2ik&t=2780s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-e0IajG9N2ik", d: "2026-05-07", show: "wys", who: ["Shawn Michaels"], t: "ショーン・マイケルズの回　家族、若い頃の失敗、そして若手への思い", lead: "ステファニー・マクマホンの番組に出た約88分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Shawn Michaels"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-e0IajG9N2ik").map((x) => [x.t, x.b, x.sp])), open: ["字幕の24分台から27分台の間に約3分の欠けがあり、その部分の話は拾えていない。", "聞き手ステファニー自身や、その家族に関する話は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=e0IajG9N2ik"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wdywta-zelda" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wdywta-zelda" ? Object.assign(x, { art: "wdywta-yatihu9gej4" }) : x);
  for (let i = ARTICLES.length - 1; i >= 0; i--) if (ARTICLES[i].id === "wdywta-zelda") ARTICLES.splice(i, 1);
  if (!ROSTER.find((r) => r[1] === "Kit Wilson")) ROSTER.push(["キット・ウィルソン", "Kit Wilson", "lg", "", "", "", ""]);
