  if (PROFILES["Kit Wilson"].lead === "") PROFILES["Kit Wilson"]._weak = 1;
  PROFILES["Kit Wilson"].facts.push(...[{"cat": "リングの話", "t": "インディー時代、ニック・アルディスとの試合で肘を切る", "b": "デビュー2年目ごろ、イギリスの団体IPWUKでニック・アルディスと対戦したという。リング外へ飛ぶ技を使ったがマットがなく、肘を切って4本縫ったそうだ。控室で手当てを受けていると、コディ・ローズが様子を見に来てくれて、とても嬉しかったと話す。前夜も同じ技で傷を作っていて、学ばなかったと笑う。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（2:33〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=153s"]]}, {"cat": "リングの話", "t": "インディーの更衣室は真冬の路地だった", "b": "PCWという団体の試合では、部屋が貸し切りの宴会に使われ、真冬の路地で着替えることになったという。16フィートの狭いリングで、観客は良く、ギャラも悪くなかったので、悪い思い出ばかりではないそうだ。この団体に推薦してくれたのは、クリス・マスターズだったと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（10:00〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=600s"]]}, {"cat": "リングの話", "t": "ドリュー・マッキンタイアに腕を止められた", "b": "PCWの3WAY戦で悪役側に入り、ドリューが立っているすきに後ろから急所を狙ったという。ところがドリューの太ももが太すぎて腕が挟まり、つかまれて「お前一人じゃ足りない」と言われ、フューチャーショックDDTを受けたそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（10:46〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=646s"]]}, {"cat": "リングの話", "t": "「有害な男らしさ」と戦うキャラクター", "b": "いまのキットは、男が弱さを見せられないことを「有害な男らしさ」と呼んで戦うキャラクターだという。男らしさと女らしさの両方を持つ自分のほうが、マット・カードナより大きな男だと主張する。頂点を目指すと同時に、男たちの新しい文化と、より良い男を作るメッセージの頂点にも立ちたいと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（12:16〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=736s"]]}, {"cat": "リングの話", "t": "マット・カードナの蹴りで歯が欠けた", "b": "マット・カードナに蹴られ、歯が欠けて翌週に歯医者へ行ったという。カードナ本人は「反対側を蹴った」と言うが、蹴りの衝撃で歯がかみ合って震えたのが原因だと話す。子どものころ「ウー・ウー・ウー」と叫ぶカードナを見ていたので、まさか自分が当たるとは思わなかったそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（13:52〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=832s"]]}, {"cat": "リングの話", "t": "ロイヤルランブルに出られなかった日", "b": "出場が確実だと思っていたのに外れ、その日は気持ちを整理するのに苦労したという。翌日は笑顔で出社し、ランブル当日も中国向けの取材やSNSなどあらゆる仕事に動き回った。その姿がザ・ミズに認められるきっかけになったと思っているそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（22:37〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=1357s"]]}, {"cat": "リングの話", "t": "目標はシングルで米国王座かIC王座", "b": "仲間と組んでいたタッグを離れ、シングルに完全に気持ちを切り替えたという。親友のエルトンの今後は分からないが、自分は一人でやり切る覚悟だそうだ。当面の狙いは米国王座かインターコンチネンタル王座で、そこで大きな舞台を得てメッセージを伝えたいと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（32:15〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=1935s"]]}, {"cat": "リングの話", "t": "キャラは「素の自分を盛ったもの」", "b": "キットのキャラクターは作り物ではなく、素の自分をそのまま盛ったものだという。服は母が縫い物の仕事をしている影響で好きになり、いまは自分でも少し縫っているそうだ。最近は自分の声を見つけた気がして、成功の始まりだと感じており、いまは楽しくて仕方ないと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（34:42〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2082s"]]}, {"cat": "リングの話", "t": "急な依頼でシカゴへ、R・トゥルースと即興演技の稽古", "b": "家のトレッドミルで歩いているとき、シカゴでR・トゥルースと即興劇の稽古をしてほしいという連絡が入ったという。妻とディズニーへ行く直前だったが、迷わず引き受けたそうだ。シカゴの劇団セカンド・シティで稽古を受け、「何でも引き受ける」タイプだと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（37:06〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2226s"]]}, {"cat": "リングの話", "t": "タッグチームのお手本はザ・リバイバルとアメリカン・アルファ", "b": "エルトンとのタッグは、ザ・リバイバルに憧れて始まり、昔ながらのタッグの雰囲気を目指したという。アメリカン・アルファのNXT時代も大好きで、完璧だったと語る。古いものに新しい要素を足して独自のものにしたかったそうで、まだやり残したことがあると話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（52:19〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=3139s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Kit Wilson")) ROSTER.push(["キット・ウィルソン", "Kit Wilson", "lg", "スマックダウンの選手", "", "", ""]);
  if (!PROFILES["Kit Wilson"]) PROFILES["Kit Wilson"] = { lead: "母は裁縫の仕事をしていて、自分も裁縫を習い始めた服好き。家では妻と料理をし、4匹の猫と暮らし、友人を呼んで昔のゲーム機でLANパーティーを開くのが楽しみだという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kit%20Wilson"]], moves: [], facts: [] };
  if (PROFILES["Kit Wilson"]._weak) { PROFILES["Kit Wilson"].lead = "母は裁縫の仕事をしていて、自分も裁縫を習い始めた服好き。家では妻と料理をし、4匹の猫と暮らし、友人を呼んで昔のゲーム機でLANパーティーを開くのが楽しみだという。"; delete PROFILES["Kit Wilson"]._weak; }
  PROFILES["Kit Wilson"].facts.push(...[{"cat": "リングに来るまで", "t": "ケントの団体へ毎週車で通った", "b": "練習を始め、デビューしたのはイングランド・ケントのインディー団体だった。毎週車でそこへ通っていたという。キャリア2年目ごろにはこの団体でニック・オールディスと対戦する機会ももらったそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（2:33〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=153s"]]}, {"cat": "暮らし", "t": "お金がなくても身なりは整えた", "b": "インディー時代の初期から、お金はなくても見た目にはこだわり始めていたという。その会場で初めて会ったコーディに靴をほめられ、1年ほど後にはフィン・ベイラー（当時のリングネームはデヴィット）にも靴をほめられたと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（2:33〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=153s"]]}, {"cat": "体のこと", "t": "場外ダイブで肘を4針縫った", "b": "マットのないインディーの会場で、コーナーを飛び越える場外ダイブをして肘を切り、4針縫ったという。2日連続の興行で、前夜に同じ技で少し切っていた傷が翌日に大きく開いたそうだ。控室ではミッキー・ジェームスが消毒してくれ、コーディも様子を見に来てくれたのがうれしかったと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（3:23〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=203s"]]}, {"cat": "好きなもの", "t": "舞台裏の話は知りたくない派", "b": "子どものころから大ファンで、あらゆる番組を見ていたが、視聴率や業界の内幕にはまったく興味がなかったという。好きな作品でも制作の裏側を知ると楽しみが損なわれると感じ、スター・ウォーズのような大作でも事前情報は入れたくないそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（6:38〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=398s"]]}, {"cat": "リングに来るまで", "t": "クリス・マスターズの推薦で出場", "b": "別のインディー団体に出られるようになったのは、思いがけずクリス・マスターズが推薦してくれたおかげだという。そこでは良い試合をいくつもでき、インディーを回っていたドリュー・マッキンタイアとも絡んだそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（10:46〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=646s"]]}, {"cat": "体のこと", "t": "試合で歯が欠け、歯医者へ", "b": "マット・カルドナとの試合で歯が欠け、翌週に歯医者へ行ったという。カルドナの蹴りとは反対側の歯だったが、蹴りの衝撃で歯を食いしばり、振動で欠けたのだろうと話す。子どものころはカルドナの若手時代のキャラクターを見て育ったそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（13:52〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=832s"]]}, {"cat": "リングに来るまで", "t": "2014年に練習を始めた", "b": "プロレスの練習を始めたのは2014年ごろだという。始めた当初は、地元ケント出身のザック・セイバーJr.の指導を何度か受けたそうだ。ただ本格的に組んだことはまだなく、いつかリングで向き合いたいと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（18:39〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=1119s"]]}, {"cat": "家族", "t": "相棒エルトンは親友", "b": "タッグチーム「プリティ・デッドリー」の相棒エルトン・プリンスは親友で、2人ともこの会社に一生いるものだと思っていたという。エルトンの先行きが見えないなか、気持ちを切り替えてシングルに専念していると話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（32:15〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=1935s"]]}, {"cat": "家族", "t": "母はお針子、自分も裁縫を", "b": "服への興味は昔からで、母親が裁縫の仕事をしていることが影響しているという。妻も裁縫をするので、自分も習い始めたところだそうだ。まだ初級で、ファスナー付きの小さなバッグを作れるようになったと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（33:55〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2035s"]]}, {"cat": "暮らし", "t": "ターゲットでレコードと食材", "b": "普段も番組と同じような服装で過ごしているという。大型スーパーのターゲットに行くのが好きで、レコード好きなのでつい売り場を見てしまい、最近はチャーリーXCXのアルバムを買ったそうだ。料理が好きで、妻と一日中料理をしているとも話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（34:42〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2082s"]]}, {"cat": "家族", "t": "結婚式を2回挙げた", "b": "妻とはインディーで出会い、妻は日本でも試合をしていたレスラーのスティービー。2人で英国の育成ブランドにいたが、自分だけ米国の育成施設に呼ばれたため、婚約中だった2人はオーランドの裁判所で8月1日に結婚したという。その後妻も渡米し、ラスベガスの山あいで9月23日に改めて式を挙げたそうだ。付き合って7年になる。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（35:28〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2128s"]]}, {"cat": "暮らし", "t": "4匹の猫と暮らす猫派", "b": "犬ではなく大の猫派で、家には猫が4匹いるという。理想のチームを選ぶ遊びでも、猫たちを付き人にした妻を真っ先に入れていた。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（36:13〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2173s"]]}, {"cat": "暮らし", "t": "ディズニー直前に即興劇の誘い", "b": "ある朝、自宅ガレージのランニングマシンで歩いていたところ、R-トゥルースとシカゴで即興劇の訓練を受けないかと電話が来たという。妻とディズニーへ行く予定だったが、迷わず引き受けたそうだ。何事にも「イエス」と言うタイプだと話し、妻はディズニーが大好きで2人でよく行くという。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（37:06〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2226s"]]}, {"cat": "好きなもの", "t": "サタデー・ナイト・ライブ好き", "b": "英国育ちで米国の番組は見られなかったが、10代で「30 ROCK」にはまり、そこから「サタデー・ナイト・ライブ」をネットで見るようになったという。好きな出演者はカイル・ムーニーで、ベック・ベネットとのコントグループ時代から追っていたそうだ。最近ではマイキー・デイの控えめな芝居が好きだと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（38:45〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2325s"]]}, {"cat": "好きなもの", "t": "007はブロスナン派", "b": "初めてのゲーム機はプレイステーション2とゲームキューブで、007のゲームで遊んだという。兄や友人の兄がNINTENDO64を持っていたので「ゴールデンアイ」もたくさん遊び、ボンドといえばピアース・ブロスナンの顔が浮かぶそうだ。大人になってからはダニエル・クレイグに傾いていると話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（41:10〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2470s"]]}, {"cat": "暮らし", "t": "出不精、楽しみはLANパーティー", "b": "外出は好きではない大の出不精だという。数年前は友人を家に呼び、空き部屋で初代Xboxを4台つないで「Halo」の対戦をしたり、NINTENDO64で「ゴールデンアイ」や「マリオストライカーズ」を遊んだりしていたそうだ。若い参加者が64のコントローラーの持ち方すら分からず驚いたと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（42:46〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2566s"]]}, {"cat": "好きなもの", "t": "ゼルダ好きでコーディのファンに", "b": "子どものころは任天堂好きで、特に「ゼルダの伝説」が大好きだったという。当時の親友と夢中になっていたころ、コーディのブーツにトライフォースの模様があったことで一気にファンになったそうだ。10代は「風のタクト」や「トワイライトプリンセス」の時代で、コロナ禍に「ブレス オブ ザ ワイルド」を遊んだのを最後に、いまはあまりゲームをしないと話す。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（45:57〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2757s"]]}, {"cat": "好きなもの", "t": "ジョン・シナが憧れだった", "b": "子どものころはジョン・シナが一番の存在だったという。いちばん好きな試合は、ロイヤルランブルでのシナ対ウマガ戦だそうだ。理想のチームにはザ・ミズ主演の映画「ザ・マリーン3」の役柄を入れるなど、映画好きの一面ものぞかせた。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（50:44〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=3044s"]]}, {"cat": "リングに来るまで", "t": "憧れのタッグはアメリカン・アルファ", "b": "タッグを組んだ当初に手本にしたのはザ・リバイバルで、そこからミッドナイト・エクスプレスなど往年のチームにさかのぼったという。自分たちが練習を始めたころに勢いのあったアメリカン・アルファの育成ブランド時代は満点だと思うほど好きだそうだ。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（52:19〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=3139s"]]}]);
  if (PROFILES["Drew McIntyre"]) PROFILES["Drew McIntyre"].facts.push({"cat": "暮らし", "t": "太ももで防がれた急所攻撃", "b": "新人のころ、インディーの試合でレフェリーが倒れた隙にドリュー・マッキンタイアへ急所攻撃を狙ったが、太ももが太すぎて腕が挟まって動かなかったという。そのまま「お前一人じゃ足りない」と言われて大技を食らったと、キット・ウィルソンが話している。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で、キット・ウィルソンの話（公式字幕を全文確認）", "src": [["公式YouTube（11:31〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=691s"]], "by": "第三者の話"});
  if (PROFILES["The Miz"]) PROFILES["The Miz"].facts.push({"cat": "暮らし", "t": "返信は「最高」のひと言", "b": "ロイヤルランブル当日、裏方の仕事を積極的に手伝う姿を何度も見られたことで、ザ・ミズに気に入られたという。その後に企画を送ると、めったに返信しないと聞いていたミズからほめ言葉と「最高」のひと言が返ってきて、10代の自分が喜んだと、キット・ウィルソンが話している。", "sp": "キット・ウィルソン", "d": "2026-05-07", "how": "コーディの番組で、キット・ウィルソンの話（公式字幕を全文確認）", "src": [["公式YouTube（23:29〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=1409s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "家族", "t": "幼いころ階段で転び、スティームボートが手当て", "b": "幼いころ、父の仕事先だったWCWの会場に通っていたという。警備担当のダグ・ディリンジャーから大きな通行証をもらい、空いた席で観戦していたが、木の階段で転んで目の下を切ってしまったそうだ。学校を休んで来ていたこともあって気まずかったが、控室でリッキー・スティームボートが手当てしてくれたと話す。ディリンジャーは元警察官で、自分と姉の面倒をよく見てくれた人だったという。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（7:23〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=443s"]]}, {"cat": "リングに来るまで", "t": "真冬の路地裏で着替えた", "b": "英国のインディー団体に出たとき、地下の暖房のある部屋で着替えていたら、その部屋を予約していたパーティー客が来て、真冬に路地裏で着替える羽目になったという。それでも観客は最高で、ギャラも良く、自分にとって良い団体だったと話す。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（10:00〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=600s"]]}, {"cat": "好きなもの", "t": "大の007ファン、父とは推しが違う", "b": "自他ともに認める大の007好きだという。自分にとってのボンドはピアース・ブロスナンで、そう伝えたら父ダスティはショーン・コネリー派で猛反論したそうだ。ロジャー・ムーアの作品もそれぞれ素晴らしいと話す。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（33:55〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2035s"]]}, {"cat": "暮らし", "t": "かつて自分の努力を誇示していた", "b": "若いころは、人一倍努力していることを周りにアピールし、報われるべきだと考える面倒なタイプだったと振り返る。ジムに通い、大会の最後まで残っても、結局は観客に支持されるかどうかだと学んだという。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（38:28〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2308s"]]}, {"cat": "好きなもの", "t": "ブーツのトライフォースに込めた意味", "b": "ゼルダの伝説が好きで、ブーツにトライフォースの模様を入れていたという。知恵・力・勇気という3つの要素が、競争の世界で自分の学びを生かし、野心を持ち、思い切って挑む姿勢に重なると考えたそうだ。任天堂からは丁寧な中止要請が届いたと笑う。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（45:57〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2757s"]]}, {"cat": "好きなもの", "t": "ゲームは少しずつ、半年かけてクリア", "b": "「ゴースト・オブ・ヨウテイ」を遊んだが、ひと晩夢中になっても仕事に出ると2週間空いてしまい、どこへ向かえばいいか分からなくなったという。少しずつ進めた結果、クリアまで半年かかったそうだ。", "sp": "コーディ・ローデス", "d": "2026-05-07", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-yatihu9gej4", "src": [["公式YouTube（48:23〜）", "https://www.youtube.com/watch?v=yatihu9gej4&t=2903s"]]}]);
  ARTICLES.push({ id: "wdywta-yatihu9gej4", d: "2026-05-07", show: "wdywta", who: ["Kit Wilson", "Cody Rhodes"], t: "キット・ウィルソンの回　服と猫とレトロゲーム、インディー時代の思い出", lead: "コーディ・ローデスの番組に出た約54分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kit Wilson", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-yatihu9gej4").map((x) => [x.t, x.b, x.sp])), open: ["「有害な男らしさ」をめぐる主張や王座取りの目標など、現在のキャラクターと筋書きに関わる話は省いた。", "ゼルダの話のうち「もうゲームはあまりしない」という発言は、前後の流れからキット本人の発言と判断した。", "ロイヤルランブル当日の舞台裏のやりとりや、コーディに送った企画書の中身は省いた。", "マット・カルドナとディズニーへよく行っていた話や、会社の部署を回った話は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=yatihu9gej4"]] });
  for (const k in PROFILES) PROFILES[k].facts = PROFILES[k].facts.filter((x) => !(x.art === "wys-finn" && /StationLM/.test(JSON.stringify(x.src)))).map((x) => x.art === "wys-finn" ? Object.assign(x, { art: "wys-p9pNWq_xtj4" }) : x);
