  if (!PROFILES["Finn B\u00e1lor"]) PROFILES["Finn B\u00e1lor"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Finn%20B\u00e1lor"]], moves: [], facts: [] };
  if (PROFILES["Finn B\u00e1lor"].lead === "") PROFILES["Finn B\u00e1lor"]._weak = 1;
  PROFILES["Finn B\u00e1lor"].facts.push(...[{"cat": "リングの話", "t": "話すより試合で表現する人", "b": "フィン・ベイラーは、レスリングが自分を表現する手段で、しゃべりよりも体で伝える方が得意だと話す。メディア出演は避けがちで、トラッシュトークでも、思ってもいないことを言って自分の品位を落とすつもりはないという。ここまで来られたのは自分らしくいたからで、それを変えるべきではないと考えているそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（2:26〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=146s"]]}, {"cat": "リングの話", "t": "初めてのプロモはNXTで", "b": "イギリスではマットレスリング中心、日本ではストロングスタイルでプロモがなく、初めて話す役が回ってきたのはNXTだったという。「自分はフィン・ベイラー、未来だ」という決まった台詞を覚えるだけで緊張したと振り返る。試合中は流れに任せて感情のまま動けるが、台本のある話は演技になるため、いまも学びの途中だそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（7:00〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=420s"]]}, {"cat": "リングの話", "t": "ヘイマンに学んだプロモの考え方", "b": "ポール・ヘイマンから、プロモを試合と同じように扱えと教わったと話す。試合は技を全部決めずに流れで進めるのに、プロモだけ一言一句を暗記するのはおかしいという考えだ。最近は要点を数個だけ決めて臨むようにしており、それがかなり役に立っているそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（8:36〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=516s"]]}, {"cat": "リングの話", "t": "ドミニクの初プロモを見守った夜", "b": "ジャッジメント・デイにドミニクが加わった日、フィン・ベイラーは手伝おうと台本の確認に誘ったが、本人は「何を言うか分からない、その場で考える」と答えたという。心配したのはフィン・ベイラーの方だったが、ドミニクは観客に激しくブーイングを浴び、その熱がユニットを一段上に押し上げたと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（10:09〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=609s"]]}, {"cat": "リングの話", "t": "ヒールよりベビーフェイスが合う", "b": "フィン・ベイラーは、ヒールの方が楽に感じる面はあるが、自分にはベビーフェイスの方が向いていて、観客にも受け入れられやすいと思っているという。ヒールを演じていると川を上流へ泳いでいるような感覚があったそうだ。観客に見せてきたのは自分のごく一部で、素顔を出すのは難しいとも語る。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（11:45〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=705s"]]}, {"cat": "リングの話", "t": "何が良いか分からなくなる怖さ", "b": "長く続けているうちに、自分のアイデアが面白いのかどうか判断できなくなると話す。だから第三者の目になるプロデューサーが大事だという。逆に、試合のつなぎにと入れた、逆さ押さえ込みから転がってドロップキックにつなぐ動きは、日本の元タッグ相手の戸口の技を借りたもので、回を重ねるごとに歓声が増えて定番になったそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（22:18〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1338s"]]}, {"cat": "リングの話", "t": "ユニバーサル王座が頂上だった", "b": "フィン・ベイラーは、ユニバーサル王座を獲った時が自分にとっての山の頂上だったと話す。のちに負傷して王座を手放したことを悲劇と見る人もいるが、本人にとってはそこへ到達できた成功の物語だという。夢をかなえて経済的にも安定したあと、なぜ続けるのかを自問するようになったそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（52:27〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=3147s"]]}, {"cat": "リングの話", "t": "NXT入りの頃の混乱と直通の連絡先", "b": "NXTに来た直後は、名前も人物像も変える必要があり、パフォーマンスセンターの職員が口々に意見を言うため、誰が責任者か分からず戸惑ったとフィン・ベイラーは話す。トリプルHに会ってからは窓口がはっきりした。ほどなく個人の連絡先をもらい、それ以来やり取りがずっと楽になったという。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:28:09〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5289s"]]}, {"cat": "リングの話", "t": "ボディペイントが生まれた経緯", "b": "WWEと契約した際は、アイルランドの妖精役でホーンスワッグルのタッグ相手になる、ペイントは諦めろと言われていたという。ところがトリプルHが腕を組んで「そのボディペイントについて聞かせてくれ」と切り出し、そこから実現が始まったと話す。元は新日本のレッスルキングダムでの飯伏幸太戦の発想で、白い装いの相手に対し、遠くの客席から影と戦っているように見せたくて全身を黒く塗ろうとした。それが形になる過程で悪魔の姿に変わったそうだ。ボディスーツはライガーと被るので避けたという。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:30:33〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5433s"]]}, {"cat": "リングの話", "t": "リングネームの由来と候補だった名前", "b": "フィン・ベイラーという名は、ゲール神話の片目の悪魔王バロールと、それを倒す英雄フィン・マックールを組み合わせたものだと話す。NXT入りのとき渡された候補名の中にはリヴ、ラックスなどもあり、ラックスはトリプルHがドラァグクイーンのルポールと被ると却下したそうだ。マクレガーという案もあったが、将来大スターになる人と同じ名前は避けたかったという。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:33:07〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5587s"]]}]);
  if (!PROFILES["Finn B\u00e1lor"]) PROFILES["Finn B\u00e1lor"] = { lead: "人前で話すより、リングで体を使って表現するほうが性に合うと語る物静かな人。レゴと古代史に没頭し、遠く離れた家族を思いながらマイアミで暮らしている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Finn%20B\u00e1lor"]], moves: [], facts: [] };
  if (PROFILES["Finn B\u00e1lor"]._weak) { PROFILES["Finn B\u00e1lor"].lead = "人前で話すより、リングで体を使って表現するほうが性に合うと語る物静かな人。レゴと古代史に没頭し、遠く離れた家族を思いながらマイアミで暮らしている。"; delete PROFILES["Finn B\u00e1lor"]._weak; }
  PROFILES["Finn B\u00e1lor"].facts.push(...[{"cat": "暮らし", "t": "話すより体で表現したいタイプ", "b": "部屋に入れば目立ちたい人もいるが、自分はできれば背景に溶け込んで眺めていたい側だという。リングでの動きのほうが言葉よりうまく自分を表現できると感じており、ここ数年はメディア出演や講演をなるべく控えてきたそうだ。テレビの短い生出演のような場がいちばん苦手で、じっくり話せる対話のほうが向いていると話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（2:26〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=146s"]]}, {"cat": "好きなもの", "t": "レゴは瞑想代わりの趣味", "b": "育成ブランド入りの際のドキュメンタリーで、レゴを組んでリラックスしていると明かしたところ、試合以上に反響があったという。子どものころから一度も卒業しておらず、1994〜95年ごろに作った城がいちばんの思い出で、いまもネットで探しているそうだ。キャラクター物より、海賊船や警察署のような昔ながらのシリーズが好きで、部品に集中して他のことを考えずに済むのが良いと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（13:16〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=796s"]]}, {"cat": "体のこと", "t": "食事制限をゆるめたのは妻のおかげ", "b": "2010年ごろから2022年ごろまでは食事管理が極端すぎたと本人も認めている。妻の影響でおいしいものを楽しむようになり、いまは週に1回から2週に1回ほど、チーズバーガーとポテトでチートデイをとるそうだ。食べるならパンも含めて全部食べ、そのあと数日しっかり節制するのが自分流だという。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（17:30〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1050s"]]}, {"cat": "家族", "t": "母の手作りチーズケーキは断れない", "b": "普段は間食をしないが、実家に帰って母がチーズケーキを作っていれば必ず食べるという。砕いたビスケットとバターを土台にしたクリーミーなもので、自分でも同じように作るそうだ。収録の日は母がちょうどアメリカに来る予定だと話していた。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（19:07〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1147s"]]}, {"cat": "リングに来るまで", "t": "祖父と父のそばで見たプロレス", "b": "アイルランドでは昔、日曜午後のプロレス番組を見ないとサッカーの結果が分からなかったという。祖父はプロレス目当て、父はサッカーの結果目当てで見ていて、4〜5歳の自分は隣で一緒に画面を眺めていたそうだ。その後衛星放送が始まってWWEの番組を見るようになり、すっかり夢中になったと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（19:53〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1193s"]]}, {"cat": "家族", "t": "兄弟と夜更かしして見た祭典", "b": "アイルランドでは深夜1時の放送だったため、枕を抱えて兄弟と起きて年間最大の祭典を見たという。ジ・アンダーテイカーがアルティメット・ウォリアーを棺に閉じ込めた場面では、台所へ走って母に「ウォリアーが死んじゃう」と訴えたそうだ。当時は続きが分かるまで1週間待つしかなかったと振り返る。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（20:44〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1244s"]]}, {"cat": "好きなもの", "t": "SF映画と歴史ドキュメンタリー", "b": "SFでは『サンシャイン』や『インターステラー』が好きで、キリアン・マーフィーも気に入っているという。『ピーキー・ブラインダーズ』は肩のリハビリ中にシーズン2まで見たが、リハビリを思い出すのでその先は見ていないそうだ。最近は歴史を題材にした作品やドキュメンタリーに関心が移り、『ニュルンベルク』がすばらしかったと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（24:44〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1484s"]]}, {"cat": "好きなもの", "t": "自由時間は古代史の動画に夢中", "b": "空き時間のほとんどを、古代史を扱うYouTube動画を見て過ごしているという。古代エジプト、トルコ、ペルー、ボリビアの遺跡に関心があり、いつか全部訪ねたいそうだ。昔の人々がどんな技術で巨石を切り出し運んだのかが知りたくてたまらないと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（27:09〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1629s"]]}, {"cat": "家族", "t": "歴史好きの妻とは「500年と4000年」", "b": "妻のベロも歴史好きで、ルネサンス期やメディチ家に詳しく、夫婦でローマやフィレンツェを何度か訪れているという。妻はトルコのコンスタンティノープルに行きたがっているそうだ。妻の好きな時代は約500年前、自分は4000年以上前で、好みの「古さ」が違うと笑う。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（27:57〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1677s"]]}, {"cat": "体のこと", "t": "実はかなりの閉所恐怖症", "b": "あまり知られていないが、強い閉所恐怖症だという。飛行機では窓側より、乗り越える人が一人少ない真ん中の席のほうがましだと感じるそうだ。それでもピラミッドの王の間に入るのは夢で、ジムに行くのと同じく、一歩ずつ進むしかないと話している。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（30:21〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=1821s"]]}, {"cat": "暮らし", "t": "陰謀論やUFOは娯楽として楽しむ", "b": "宇宙人やUFO、古代文明の説などの話題に自由時間の多くを費やしているが、どちらの立場にもこだわらないという。地球外生命は存在すると思っている一方、裏付けのない話は信じきれないと話す。夜通し見入ってしまっても、朝には「さあ練習だ」と切り替えるそうで、話を聞かされる妻にはいつもあきれられているという。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（39:28〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=2368s"]]}, {"cat": "暮らし", "t": "マイアミの夜、星に語りかける", "b": "いまはマイアミに住んでおり、妻はテレビ局の夜の番組で働いているため、夜はひとりで過ごすことが多いという。窓から空を見上げて、星に向かって「いるのは分かってる、会いに来いよ」と声をかけるのがほぼ毎晩の習慣だそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（43:33〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=2613s"]]}, {"cat": "家族", "t": "兄弟と比べて感じる後ろめたさ", "b": "自分が仕事に恵まれ、空いた時間を趣味に使えるのに対し、兄弟たちは子育てと仕事に追われているという。兄のオーウェンに話題を振っても、娘のダンスや息子のサッカーの送り迎えで手一杯だと返されるそうだ。その後ろめたさはキャリアが長くなるほど強くなってきたと打ち明けている。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（50:45〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=3045s"]]}, {"cat": "家族", "t": "家族と離れて戦う葛藤と将来の夢", "b": "自分の家族はアイルランド、妻の家族はメキシコシティにいて、アメリカでは夫婦ふたりきりで支えてくれる人が近くにいないという。王座に就いて目標を果たしたあと、大切な人と離れてまで続ける意味を自問するようになったそうだ。引退後はアメリカ、メキシコ、アイルランドで数か月ずつ暮らすのが理想だと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（54:51〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=3291s"]]}, {"cat": "リングに来るまで", "t": "日本でキャリアを終えるつもりだった", "b": "もともとは日本でキャリアを終えるつもりで、WWEで1年ほど試して駄目なら喜んで日本に戻る気だったという。何事も見たまま、はっきりした答えが返ってきて、清潔で整っているところが好きだそうだ。日本語は本で勉強したことはないが、生活の中で道を尋ねたりタクシーで帰ったりできる程度は身についたと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（58:49〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=3529s"]]}, {"cat": "リングに来るまで", "t": "3か月の予定が8年になった日本", "b": "24歳でボストンの叔母の家に移ってインディーで戦っていたところ、スカウトに誘われてロサンゼルスの新日本プロレス系道場で練習を始めたという。その後、若手として3か月来日し、掃除や先輩の洗濯をこなしながら、毎朝スクワット500回などの練習に励んだそうだ。帰国直前に獣神サンダー・ライガーから「戻ってこないか」と声をかけられ、結局8年いたと振り返る。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:00:24〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=3624s"]]}, {"cat": "好きなもの", "t": "学校で得意だったのは美術だけ", "b": "成績はほかの教科がひどく、美術だけがよかったという。いちばん得意なのは鉛筆画で、絵の具も使っていたそうだ。いまも移動中にときどき、デーモンのアイデアなどを落書きすることがあると話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:08:20〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=4100s"]]}, {"cat": "リングに来るまで", "t": "ボディペイントは「影」の発想から", "b": "日本で長く正統派だった自分が悪役に転じ、純白のコスチュームの飯伏幸太と大会場で対戦することになったとき、遠くの客席から「影と戦っている」ように見せたいと考えたのが始まりだという。全身を黒く塗る案が、準備するうちに悪魔のような姿へ変わっていったそうだ。全身タイツはライガーの印象と重なるので避けたとも話している。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:31:25〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5485s"]]}, {"cat": "リングに来るまで", "t": "リングネームはアイルランドの伝説から", "b": "「ベイラー」はゲール神話の一つ目の魔王の名で、それを倒す英雄フィン・マックールと組み合わせたものだという。WWEに入ったときに提示された名前の候補の中には「マクレガー」もあったが、コナー・マクレガーが大スターになると思って避けたそうだ。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:33:07〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5587s"]]}, {"cat": "体のこと", "t": "日本の控室で星を見て心を落ち着けた", "b": "日本では控室が狭く、閉所が苦手なため息苦しく感じることが多かったという。東京湾近くの会場では非常階段に出て星を見上げ、「重力なんて本当はない、飛べる」と自分に言い聞かせて試合前の気持ちを落ち着けていたそうだ。自分に課している決まりごとから離れられて、心が静まったと話す。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-p9pNWq_xtj4", "src": [["公式YouTube（1:36:18〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5778s"]]}]);
  if (PROFILES["Dominik Mysterio"]) PROFILES["Dominik Mysterio"].facts.push({"cat": "暮らし", "t": "初めての大一番でも動じなかった", "b": "ユニットに加わって最初の生放送でのマイクの前、練習しようと声をかけたところ、「何を言うかはまだ決めてない、出てから考える」と平然と答えたという。こちらのほうがよほど緊張していたが、本番は大ブーイングで大成功だったと、フィン・ベイラーが話している。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で、フィン・ベイラーの話（公式字幕を全文確認）", "src": [["公式YouTube（10:09〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=609s"]], "by": "第三者の話"});
  if (PROFILES["Sami Zayn"]) PROFILES["Sami Zayn"].facts.push({"cat": "暮らし", "t": "番号交換を我がことのように喜んだ親友", "b": "育成ブランドの会場の裏でトリプルHから電話番号をもらったとき、離れて見ていたサミ・ゼインが駆け寄り、「バーで美女の番号をもらった友達を見る気分だ、誇らしいよ」と喜んだという。これまで人前で話したことのない話だと、フィン・ベイラーが話している。", "sp": "フィン・ベイラー", "d": "2026-05-14", "how": "ステファニーの番組で、フィン・ベイラーの話（公式字幕を全文確認）", "src": [["公式YouTube（1:28:59〜）", "https://www.youtube.com/watch?v=p9pNWq_xtj4&t=5339s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-p9pNWq_xtj4", d: "2026-05-14", show: "wys", who: ["Finn B\u00e1lor"], t: "フィン・ベイラーの回　レゴ、古代史、家族と離れて戦う葛藤", lead: "ステファニー・マクマホンの番組に出た約98分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Finn B\u00e1lor"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-p9pNWq_xtj4").map((x) => [x.t, x.b, x.sp])), open: ["後半の「歩数計・Apple Watchの通知」をめぐるやりとりは、ゲストと聞き手のどちらの発言か追い切れないため載せていない。", "トリプルHとの出会いや当初の名前の候補リストなど、聞き手側の家族が絡む話は、ゲストの経歴に関わる部分だけ要約した。王座返上やユニットでの立ち位置など筋書きに近い話は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=p9pNWq_xtj4"]] });
  if (!ROSTER.find((r) => r[1] === "Jimmy Hart")) ROSTER.push(["ジミー・ハート", "Jimmy Hart", "lg", "殿堂入りした名マネージャー", "", "", ""]);
  if (!PROFILES["Jimmy Hart"]) PROFILES["Jimmy Hart"] = { lead: "母子家庭で育ち、バンド活動から名テーマ曲の作り手、そしてマネージャーへと歩んだ人。メガホンと派手な上着の裏にある、働き者の素顔を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jimmy%20Hart"]], moves: [], facts: [] };
  if (PROFILES["Jimmy Hart"]._weak) { PROFILES["Jimmy Hart"].lead = "母子家庭で育ち、バンド活動から名テーマ曲の作り手、そしてマネージャーへと歩んだ人。メガホンと派手な上着の裏にある、働き者の素顔を語る。"; delete PROFILES["Jimmy Hart"]._weak; }
  PROFILES["Jimmy Hart"].facts.push(...[{"cat": "家族", "t": "母ひとりの手で育てられた", "b": "ジミー・ハートは母親と二人だけで育ったという。裕福な親も頼れる人もいなかったため、何でも自分でやるしかないと早くから悟ったと話す。この考え方が、その後の生き方の出発点になったそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（0:53〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=53s"]]}, {"cat": "リングに来るまで", "t": "高校時代は食料品店で働いた", "b": "母は仕事を二つ掛け持ちしていたという。ジミーは高校でアメフトのウイングバックをしていたが、放課後は皆が帰宅する中で食料品店へ直行したと話す。袋詰めから始めて、在庫係、瓶回収係へと時給を上げていったそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（1:38〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=98s"]]}, {"cat": "リングに来るまで", "t": "憧れはスプートニク・モンローだった", "b": "子どものころ、会場の入口でプログラムやポップコーンを売って働いていたという。売り切れば、その夜のメインイベントを見られたからだ。スプートニク・モンローの試合と語り口に引き込まれ、毎週通ったと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（2:27〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=147s"]]}, {"cat": "リングに来るまで", "t": "ローラーは直前まで段取りを教えなかった", "b": "メンフィスでは土曜朝の生放送で、ジミーが何試合分もの紹介インタビューを自分でこなしていたという。ジェリー・ローラーは開始直前まで希望を言わなかった。考えすぎるとうまくいかないので、わざとそうしていたのだとジミーは受け止めている。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（3:13〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=193s"]]}, {"cat": "リングに来るまで", "t": "モンローが客席の差別をなくした", "b": "当時は黒人のファンが座れる席が少なく、会場の外に何百人もあふれていたという。スプートニク・モンローが仲間と一緒に興行主へ掛け合い、全員が入れるようにさせたと、ジミーが話している。選手としてのモンローを心から尊敬している様子だった。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（4:47〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=287s"]]}, {"cat": "リングに来るまで", "t": "高校生バンド「ジェントリーズ」で全国へ", "b": "ジミーは、のちにプロレスラーになるローラーと同じ高校に通っていたという。高校生のときにバンド「ジェントリーズ」でメンフィスの素人コンテストを勝ち、列車でマイアミへ向かってテレビ番組に出たと話す。カバー曲の生演奏が評判になり、番組で二度勝ったそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（6:28〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=388s"]]}, {"cat": "リングに来るまで", "t": "平日は学校、週末は全米のテレビへ", "b": "大手レコード会社と契約すると、週末ごとに飛行機で全国の音楽番組に出たという。ビーチ・ボーイズ、シカゴ、ステッペンウルフらと共演し、月曜にはまた学校へ戻る生活だったと話す。1曲のヒットでアルバムを4枚出したそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（8:02〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=482s"]]}, {"cat": "好きなもの", "t": "ダスティは空港の迎えにも冗談を言った", "b": "ダスティ・ローデスは会うたびに、ジミーに「キープ・オン・ダンシング」を歌わせたという。空港への迎えは、ジミーが自分の小型車で行ったそうだ。「高級車で来い」と言われると、「あなたは庶民の味方だから」と返したと、笑って話している。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（8:49〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=529s"]]}, {"cat": "リングに来るまで", "t": "バンド活動は10年以上続いた", "b": "バンドは1960年代半ばから1979年近くまで活動したという。メンバーは入れ替わったが、のちに別のレコード会社へ移って再び盛り上がり、ニール・ヤング作の曲でヒットを出したと話す。ロサンゼルスの有名クラブに2週間出演したときは、ドアーズのメンバーが毎晩のように見に来たそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（9:37〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=577s"]]}, {"cat": "リングに来るまで", "t": "予算ゼロでミュージックビデオを撮った", "b": "メンフィスでは、ローラーに自由に作っていいと言われて、選手のミュージックビデオを作ったという。友人からコルベットを借り、衣料品店で着替えを繰り返して撮ったと話す。バイクが1台しかないときは、同じバイクを二人に順に乗せて並んで走っているように見せたそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（11:09〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=669s"]]}, {"cat": "リングの話", "t": "数々の入場テーマを手がけた", "b": "ニューヨークに移ってからも、ジミーはテーマ曲づくりを任されたという。ショーン・マイケルズの曲は、今も再生数が多いと誇らしげに話す。ルージョー兄弟のように、選手本人が歌えて少し変わった歌詞になるよう工夫したそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（12:44〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=764s"]]}, {"cat": "リングに来るまで", "t": "デビアスの曲は本人の決め台詞を刻んで作った", "b": "テッド・デビアスの入場曲は、彼がマイクで使う言葉を細かく切って組み立てたという。ジミーが入るタイミングを教え、本人が自分の声で読み上げる形にしたそうだ。ほかにもロード・ウォリアーズやハート・ファウンデーションなど、多くの曲に関わったと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（15:53〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=953s"]]}, {"cat": "リングの話", "t": "ダスティの曲は注文だらけで作った", "b": "ダスティ・ローデスに「ヴィンスの許可は取った。曲を書いてくれ」と言われたという。カウベル、メンフィス風の女性コーラス、ホーンと、注文が次々に出たそうだ。聞かせるのが不安だったが、本人は「大好きだ」と言ってくれ、嬉しかったとジミーは話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（16:42〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1002s"]]}, {"cat": "リングの話", "t": "ホーガンのために「アメリカン・メイド」を作った", "b": "ニューヨークを離れて別の団体へ移ったとき、旧テーマが使えなかったので、ホーガンのために別の曲を作ったという。コーディとヤングバックスが日本でその曲を歌っていたことにも触れている。どちらの曲が上かは人それぞれだと、笑って締めた。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（17:34〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1054s"]]}, {"cat": "リングの話", "t": "上着は音楽の師匠の教えから", "b": "ディック・クラークに、観客と同じ服装をしていると、いつか客席側の人間になると教わったという。ジミーは、金を払って見に来る人には違う姿を見せるべきだと受け止めたそうだ。ヴィンス・マクマホンにも好きなように着ていいと言われ、担当選手ごとに上着を作ったと話す。ホーガンからもらったメガホンは、塗装してよいか尋ねたそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（19:57〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1197s"]]}, {"cat": "リングの話", "t": "23人を担当し、選手ごとに衣装を変えた", "b": "ジミーは、WWEで23組を受け持ったという。エルヴィスの物まね役にはコロネル・パーカー風、ルージョー兄弟にはフロリダの葉、ファンク兄弟には革ひも風の上着を用意したそうだ。殿堂入りの指輪も、一緒にリングへ向かった選手たちのおかげだと語る。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（21:31〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1291s"]]}, {"cat": "リングの話", "t": "アンディ・カウフマンはただで来てくれた", "b": "ローラーの家の台所で番組を考えていると、記者から電話が来たという。コメディアンのアンディ・カウフマンが自費で来て、無料で出ると聞き、ジミーたちは大喜びしたそうだ。のちには自分がマネージャーを務め、試合に向かわせたと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（27:50〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1670s"]]}, {"cat": "暮らし", "t": "豪邸は友人の持ち物だった", "b": "ドキュメンタリーに映った豪邸は自分の家ではなく、富豪の友人のものだとジミーは笑って明かす。ホーガンの海辺の店を任されたのをきっかけに、住み込みで働くことになったそうだ。ゲートのある敷地の一角を借りて今も暮らしている。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（34:58〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2098s"]]}, {"cat": "家族", "t": "妻の病気と、家族のこと", "b": "ジミーの妻は認知症で、今は施設に入っているという。子どもたちは独立し、娘は約6年前に亡くなったと静かに話す。息子は二人いるが別々に暮らしており、広い家に一人きりでいるのがつらくなって、自宅を売ったそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（35:44〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2144s"]]}, {"cat": "体のこと", "t": "悪役時代はダーツを撃たれた", "b": "悪役のころは、観客にビールをかけられても怒らず、むしろ受け入れの証だと思っていたという。ルイビルでは試合後の退場中に、自作の吹き矢のようなもので臀部を撃たれたと話す。破傷風の注射を打つことになり、ギャラが飛ぶと嘆いたそうだ。大事には至らなかった。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（38:01〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2281s"]]}, {"cat": "リングに来るまで", "t": "レスリング好きは、おじの家で決まった", "b": "10歳ごろから毎夏、ミシシッピ州のおじの家で過ごしたという。そこで初めてプロレス観戦に連れていかれ、夢中になったそうだ。巡業中の音楽時代も、各地のテレビで地元のレスリングを見ていたと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（41:58〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2518s"]]}, {"cat": "リングに来るまで", "t": "鎖を投げたのが初仕事だった", "b": "ジェリー・ジャレットに、月曜の会場で手を上げたら鎖を投げてくれと頼まれたという。ジミーは野球のように思い切り投げたが、鎖はロープに絡まり、結果的にきれいに決まったそうだ。翌週には、ぶかぶかの衣装で初の試合に出たと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（43:31〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2611s"]]}, {"cat": "リングの話", "t": "ホーガンの誘いでテレビドラマへ同行", "b": "ホーガンのテレビ出演に同行したいと、ヴィンスに相談したという。戻りたくなればいつでも戻れると言われ、ジミー自身は団体を離れたつもりはなかったと話す。のちにホーガンと別の団体へ移る流れになったそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（45:54〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2754s"]]}, {"cat": "好きなもの", "t": "今も毎週の放送を見ている", "b": "ジミーは、月曜、火曜、金曜の放送を欠かさず見ているという。昔のようには変わらないと不満を言う人もいるが、自分は今の番組が好きだと話す。育成番組ではイーサン・ペイジ、リッキー・セインツ、ソル・ルカを気に入っているそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（49:10〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2950s"]]}, {"cat": "リングの話", "t": "同じことを続けるなら変えどきを見る", "b": "「今までと同じことをすれば、同じ結果しか出ない」というのが、ジミーの信条だという。ホーガンの人気が少し落ちたとき、グッズの売れ行きや興行の入りを見て変化を勧めたそうだ。そこで二人の大物が加わり、うまくいったと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（50:41〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=3041s"]]}, {"cat": "リングの話", "t": "ホーガン最後の晴れ舞台で旗を振った", "b": "ホーガンと一緒に大きな番組に出た際、ジミーは旗を持って登場したという。トリプルHに旗を地面につけるなと言われ、全力で掲げ続けたそうだ。観客の反応は荒れたが、翌日ホーガンは視聴率が良かったと電話をくれたという。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（54:44〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=3284s"]]}, {"cat": "暮らし", "t": "子ども向け番組を作りたい", "b": "ジミーは、WWEが手を付けていない子ども向けの朝の番組を提案したという。頭文字で「土曜朝のアクション・クラブ」を意味する「スマックド」という名前も考えたそうだ。自分が司会を務め、人気選手を呼ぶ構想を、すでに企画書にして渡したと話す。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（1:00:56〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=3656s"]]}, {"cat": "暮らし", "t": "メガホンをチャリティーに寄付した", "b": "ジミーのメガホンには、担当した20人以上の名前が入っているという。以前に寄付した1本は、高額で落札されたそうだ。今回はコーディの慈善活動のため、サインを入れて自ら手渡した。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（1:11:30〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=4290s"]]}, {"cat": "リングの話", "t": "グラマー・ガールズは金色の衣装で売り出した", "b": "対戦相手が足りなかった時期に、パット・パターソンの案で、二人を金髪にしたという。美人ではないからこそ「グラマー」と名付けたとジミーは説明する。金色のケープと上着を揃え、7、8か月ほど続いたそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（1:13:11〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=4391s"]]}]);
  if (PROFILES["Danhausen"]) PROFILES["Danhausen"].facts.push({"cat": "暮らし", "t": "グッズが強い人気者", "b": "ダンハウゼンは、グッズの人気が高いとジミー・ハートが話している。入団前から「入れば倉庫が埋まる」と本人に伝えていたそうだ。マネージャー仲間の目から見ても、安心して応援できる選手だという。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で、ジミー・ハートの話（公式字幕を全文確認）", "src": [["公式YouTube（1:08:59〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=4139s"]], "by": "第三者の話"});
  if (PROFILES["The Miz"]) PROFILES["The Miz"].facts.push({"cat": "暮らし", "t": "どんな役もこなせる人", "b": "ミズとは、彼がテレビ番組から出てきた直後に初めて一緒に巡業した、とジミー・ハートが話している。何にでも変われる器用さが魅力だと評している。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で、ジミー・ハートの話（公式字幕を全文確認）", "src": [["公式YouTube（1:04:05〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=3845s"]], "by": "第三者の話"});
  if (PROFILES["Andy Kaufman"]) PROFILES["Andy Kaufman"].facts.push({"cat": "暮らし", "t": "換金されなかった小切手", "b": "アンディ・カウフマンが、亡くなったときにメンフィスで受け取った小切手を引き出しにしまったままだった、とジミー・ハートが話している。夜にはエルヴィスの家の前で張り込んでいたそうだ。", "sp": "ジミー・ハート", "d": "2026-05-21", "how": "コーディの番組で、ジミー・ハートの話（公式字幕を全文確認）", "src": [["公式YouTube（28:37〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1717s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "家族", "t": "父からバンドの話を聞いて育った", "b": "コーディは、父ダスティから早くからジミー・ハートのバンドの話を聞いていたという。ジミーを見るたびに、バンド時代の話を思い出していたそうだ。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（5:37〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=337s"]]}, {"cat": "リングに来るまで", "t": "日本でヤングバックスと曲を歌った", "b": "コーディは、ヤングバックスらと新日本プロレスで戦っていたころ、ホーガンの入場曲を駅で歌っていたという。曲の映像をジミーに送ったことも話している。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（18:22〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1102s"]]}, {"cat": "リングに来るまで", "t": "若手時代に教わった仕事への姿勢", "b": "マイアミの祭典の時期、コーディは試合の内容に悩んでいたという。早朝のテレビ局で、ジミーが自分の名を挙げて売り込んでくれたのを見て、仕事に向き合う姿勢が変わったと話す。今でも思い出すそうだ。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（22:18〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=1338s"]]}, {"cat": "暮らし", "t": "業界の内側を描く作品が苦手", "b": "コーディは、プロレス界の内側を描いた映画や番組を見るのが苦手だという。この世界で育ったので、演出の跡が見えてしまうからだそうだ。聞かれたときは、プロレスがよく見えるように答えを用意していると話す。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（33:25〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2005s"]]}, {"cat": "好きなもの", "t": "ホーガンのドキュメンタリーは繰り返し見ている", "b": "コーディは、ホーガンのドキュメンタリーを何度も見ているという。専用バスに乗った人が閉口するほどだそうだ。見るたびに新しい発見があると話す。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（34:13〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2053s"]]}, {"cat": "家族", "t": "父の腹のあざの話", "b": "コーディは、父ダスティの腹にあざがあり、ファンは「しみ」と呼んでいたと話す。父本人は生まれつきのあざだと言っていたそうだ。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（39:35〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=2375s"]]}, {"cat": "暮らし", "t": "小さな声のファンを忘れたくない", "b": "コーディは、客席には子どもも多く、その声は大人の男性ファンより小さいと話す。年配の男性層の声だけで物事を決めないようにしているそうだ。", "sp": "コーディ・ローデス", "d": "2026-05-21", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-j8aZYhcDXTI", "src": [["公式YouTube（1:02:26〜）", "https://www.youtube.com/watch?v=j8aZYhcDXTI&t=3746s"]]}]);
  ARTICLES.push({ id: "wdywta-j8aZYhcDXTI", d: "2026-05-21", show: "wdywta", who: ["Jimmy Hart", "Cody Rhodes"], t: "ジミー・ハートの回　バンド時代、名曲テーマの誕生、ホーガンとの日々", lead: "コーディ・ローデスの番組に出た約76分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jimmy Hart", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-j8aZYhcDXTI").map((x) => [x.t, x.b, x.sp])), open: ["広告や宣伝の読み上げ部分は除いている。ホーガンのドキュメンタリーや政治的な話題は載せていない。", "体験談の時期や固有名詞は音声の聞き取りに頼る箇所があり、確かでないものは省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=j8aZYhcDXTI"]] });
  PROFILES["Rhea Ripley"].facts.push(...[{"cat": "リングの話", "t": "ステファニーと実現した入場シーンの再現", "b": "大会前の企画で、リア・リプリーはステファニーと一緒に自分の入場を再現したという。メイクもジャケットも本番どおりで、ベストは人生で一番かっこいい持ち物だと気に入っている。自分では「強そうなふりをしているだけ」と笑っている。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（0:51〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=51s"]]}, {"cat": "リングの話", "t": "祖父はプロレス好きだった", "b": "リア・リプリーは、亡くなった祖父が昔からWWEなどのプロレスを見ていたと、デビュー後に祖母から聞いて初めて知ったという。ブルーノ・サンマルチノの時代を思わせる話で、それまで知らなかったと話す。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（11:12〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=672s"]]}, {"cat": "リングの話", "t": "18歳の誕生日の試合で祖母が観戦", "b": "リア・リプリーは18歳の誕生日の試合に、家族全員が見に来ていたという。当時は周りに馴染みたい一心で、自分から椅子で頭を打たれる展開を提案したそうだ。椅子は壊れるほど派手に砕け、今なら勧められない危ない選択だったと振り返る。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（11:12〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=672s"]]}, {"cat": "リングの話", "t": "柵を越えそうになった祖母", "b": "椅子が壊れた瞬間、祖母は柵を越えそうになるほど怒り、その場で試合を始めかねない勢いだったという。相手のハーリー・ワンダーランドを本気で止めに行こうとしたとリア・リプリーは話す。試合後は家族をあおる側に回っていて、痛みはあっても見られてよかったと笑っている。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（12:01〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=721s"]]}, {"cat": "リングの話", "t": "自宅ジムのリングで夫と練習", "b": "リア・リプリーは、夫のマットが1年以上前の負傷から復帰の途中で、自宅のリングでロープ走りなどを始めたと話す。受け身の回転を教えているが、自分はケガが怖くて少し控えめに付き合っているそうだ。友人のトミーも加わり、一緒に体を動かすという。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（24:40〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=1480s"]]}, {"cat": "リングの話", "t": "ネットの反応は試合の判断材料", "b": "リア・リプリーは、ファンアートや反応を見て何が受けて何が受けなかったかを知りたいと話す。うまくいかなかった演出は繰り返したくないからだ。ただ、否定的な声が目に入ると気持ちが乱れるため、見る時間を減らそうとしている。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（32:59〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=1979s"]]}, {"cat": "リングの話", "t": "豪州ツアーで背負いすぎた責任", "b": "リア・リプリーは、オーストラリア公演で「WWEにおける豪州の顔」として、自分のパフォーマンスやファンの振る舞いまで責任を感じたという。家族や周りを喜ばせようとして、心身とも限界に近づいていたそうだ。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（50:33〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=3033s"]]}, {"cat": "リングの話", "t": "3つの興行の後に控室で倒れる", "b": "SmackDown、もう1つの興行、RAWと3つの興行が続いた最後に、リア・リプリーは控室で倒れ、パニック発作を起こしたという。食事も水分もとれておらず、人生で一番細かったと振り返る。この出来事をきっかけに、自分を優先する決断をしたと話す。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（51:22〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=3082s"]]}, {"cat": "リングの話", "t": "ジェイド・カーギルとの大一番に挑む", "b": "リア・リプリーは、年間最大の祭典でジェイド・カーギルと戦うことに胸が高鳴っているという。これまで一度も本格的に戦ったことのない相手で、少し荒れた始まりを経て物語を作っている最中だと話す。名前も見た目も大きな試合になるので、忘れられない瞬間にしたいそうだ。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（1:10:58〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=4258s"]]}, {"cat": "リングの話", "t": "縫った脚と痛めた付け根で臨む本番", "b": "大会直前、リア・リプリーは犬のバリーに脚を裂かれて縫った状態で、さらに脚の付け根も少し痛めていたという。万全ではないが、アドレナリンがあればなんとかなると話す。出場者が多い豪華な番組表の重みを、自分で背負いすぎてしまう癖もあると語る。", "sp": "リア・リプリー", "d": "2026-05-28", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rhea", "src": [["公式YouTube（1:11:53〜）", "https://www.youtube.com/watch?v=B5u8wtyaVNg&t=4313s"]]}]);
