  if (!ROSTER.find((r) => r[1] === "R-Truth")) ROSTER.push(["Rトゥルース", "R-Truth", "lg", "WWEの人気ベテラン", "", "", ""]);
  if (!PROFILES["R-Truth"]) PROFILES["R-Truth"] = { lead: "更生施設から這い上がり、プロレスに人生を救われたと語るRトゥルース。息子の「やる価値があった」の一言に涙した、情の深い素顔が見える回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=R-Truth"]], moves: [], facts: [] };
