  PROFILES["R-Truth"].facts.push(...[{"cat": "リングの話", "t": "遅刻して「レスラー裁判」にかけられた思い出", "b": "若手の頃、レイ・ミステリオとコーヒーを買いに行って約45分遅れ、大人数の試合の前にアンダーテイカーを待たせてしまったという。握手のあと引き寄せられて静かに注意されたそうで、あまりの緊張で少しちびったと笑う。ロッカールームを締める「裁判」は、いじめではなく礼儀を教える場だったと振り返っている。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（8:16〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=496s"]]}, {"cat": "リングの話", "t": "火山噴火で足止めされたヨーロッパ・ツアー", "b": "バスが2台とも壊れ、煙を出しながら坂を登り、27時間かけて空港へ急いだ旅を振り返る。トイレ休憩も食事もほとんどなく、ビールを飲む仲間もいたそうだ。初めて乗った高速列車に感動し、やっと間に合って飛行機が離陸した時には、みんなで拍手したという。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（20:52〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1252s"]]}, {"cat": "家族", "t": "育ちはノースカロライナ州シャーロット", "b": "Rトゥルースは生まれ育った南部の町に深い愛着があり、ナッシュビルやメンフィスなどに住んだこと以外は地元で過ごしたと話す。食卓で返事を曖昧にすると、父親に目で「ちゃんと言え」と合図され、今でも「イエス、マム」と自然に言うそうだ。軍隊にいたのかと聞かれるほど礼儀が身についているという。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（25:33〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1533s"]]}, {"cat": "好きなもの", "t": "高校ではフットボールと陸上、本命は音楽", "b": "高校時代はフットボールと陸上をやっていたが、情熱を注いだのはいつも音楽だったと話す。自分を表現し、人を励まし、慰められる手段だったからだという。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（27:11〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1631s"]]}, {"cat": "好きなもの", "t": "曲のテーマは「自分が自分の応援団になれ」", "b": "自分の曲は、人生は楽なことばかりではないが、自分には乗り越える力があるというメッセージだと話す。アルバムを聴いて落ち込んだ時期や大切な人を亡くした時期に救われたという声が、ファンから届くそうだ。その考え方は両親や周りの人たちから受け継いだと語る。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（27:57〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1677s"]]}, {"cat": "リングに来るまで", "t": "更生施設にいた頃、道を開いてくれた人がいた", "b": "自分は更生施設にいた時期があり、そこで元WCWのカメラマンだった男性に出会ったと話す。最初はラップの活動に投資してほしいと頼んだが、投資ではなく自分で挑戦する機会をあげると言われたという。ほかの収容者の記録を見ていた職員が、写真や話しぶりから「ここにいるべき人間じゃない」と目をかけてくれたのがきっかけだそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（28:45〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1725s"]]}, {"cat": "リングに来るまで", "t": "メンフィスの育成時代、辞める寸前だった", "b": "契約の更新が迫っていた頃、家庭の問題もあり、自分にレスリングは向いていないと辞めかけていたという。そこで声をかけてくれたのがロード・ドッグで、あと2か月ほしいと頼まれ、気にかけてもらえたことが大きな支えになったそうだ。今も会うたびにその時の気持ちがよみがえると話す。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（31:10〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1870s"]]}, {"cat": "リングに来るまで", "t": "プロレスは「遠回りの道」で、人生を救ってくれた", "b": "子どもの頃はニキータ・コロフ、ロン・シモンズ、リッキー・スティムボートなどを見ていたが、自分がレスラーになるとは考えていなかったという。それでも、プロレスは礼儀や社会人としての振る舞いを教え、世界中を旅させてくれた道だと話す。寄り道に見えた道が、実は進むべき道だったのかもしれないと語っている。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（32:45〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1965s"]]}, {"cat": "リングに来るまで", "t": "施設の隅で冗談を言い、踊っていた", "b": "施設ではウエイトを置いた一角で、冗談を言ったり踊ったりして過ごしていたという。それを見ていた男性は、体つきも良く人を楽しませる力があると思ったらしい。出所したら連絡をくれと言われたが、最初は草刈りを頼まれるのだと思い込んでいたそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（35:04〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2104s"]]}, {"cat": "リングに来るまで", "t": "24、25歳でプロレスの誘いを一度断った", "b": "最初に誘われた時はまだ未熟で、お金だけが欲しかったため断ったという。その後の約2年は出入りを繰り返す日々で、「もううんざりだ」と感じて自分から連絡し直したと話す。時間と献身以外は何もかからないという言葉に、何でもやると答えたそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（36:42〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2202s"]]}, {"cat": "リングに来るまで", "t": "初めての飛行機、初めての生観戦", "b": "迎えに来てもらってアトランタへ飛んだのが、人生で初めての飛行機だったという。そこで初めてプロレスの興行を観て、リック・フレアーの入場に沸く観客の熱気に鳥肌が立ったと話す。刑務所で踊っていた姿を思い出せと言われ、キャラクターを「言葉で作ってもらった」ような感覚だったそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（37:32〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2252s"]]}, {"cat": "リングに来るまで", "t": "1回15ドルとホットドッグの下積み", "b": "最初の頃の試合は1回15ドルとホットドッグ程度で、それでも刑務所に戻らずレスリングができるだけで幸せだったという。同じ頃にAJスタイルズも無名だった。ある人から「テレビに出るべきだ」と言われても、まだ目標すら持てずにいたそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（38:18〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2298s"]]}, {"cat": "リングに来るまで", "t": "送ったテープから2週間でWWEへ", "b": "テープを送ると2週間後に連絡があり、面接でビンス・マクマホンに気に入られて契約に至ったという。応募時に身長を約190センチ、体重を約118キロと盛って書いたが、会った瞬間に見抜かれ、実際は約185センチだったと笑う。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（39:50〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2390s"]]}, {"cat": "リングに来るまで", "t": "契約後7か月は試合なしで給料だけ届いた", "b": "契約してからおよそ7か月、試合に出ないまま給料だけが振り込まれたという。申し訳なくなって事務に電話し、返せないと伝えたが問題ないと言われたそうだ。税金のことは後でビンスにも教わり、痛い目を見たと話している。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（40:36〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2436s"]]}, {"cat": "体のこと", "t": "「年を取るから止めるのではなく、止めるから老ける」", "b": "高校のころから運動をやめたことがなく、見た目も動きも昔のままだと言われる秘訣は特にないと話す。ビリー・ガンの言葉を引き、動かなくなると持っているものを失うと考えているそうだ。「車輪が外れるまで走り続ける」というのが口癖だという。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（47:53〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2873s"]]}, {"cat": "暮らし", "t": "人前では暗い顔を見せないと決めている", "b": "自分も嬉しさ、悲しみ、落ち込み、怒りなど普通の人と同じ感情を持っていると話す。ただ、人前に出るときは自分が「灯り」のように見られていると考え、私的な悩みで暗い顔はしないようにしているという。いつでも明るい存在でいるのは、そうした灯りがなかった時期を知っているからだそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（49:30〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2970s"]]}, {"cat": "リングの話", "t": "解雇の報せと、ファンと仲間の大きな反応", "b": "契約を巡る発表のあと、本人は感謝の気持ちだけを伝えるつもりで投稿したという。ところがファンが「トゥルースを返せ」と声を上げ、さらに同僚やリング係、カメラやトラックのスタッフまで声を上げてくれたそうだ。あの反応は一生に一度の「瓶の中の稲妻」のようだったと話す。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（51:59〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3119s"]]}, {"cat": "家族", "t": "25歳の息子の「やる価値があったよ」", "b": "息子は今25歳で、結婚前はシングルファーザーとして育てていたと話す。解雇の知らせを受けた時も息子がそばにいて、「父さん、やる価値があったよ」と言ってくれたそうだ。記念日や卒業式、葬儀など、仕事のために逃した場面は多かったが、その一言で涙が出たという。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（53:34〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3214s"]]}, {"cat": "リングの話", "t": "リトル・ジミーと、空っぽの箱のフィギュア案", "b": "リトル・ジミーは、ジョン・シナのファンの子に話しかけているうちに即興で生まれたという。フィギュア化を提案したが、ステファニー・マクマホンに断られたそうだ。それなら箱だけでも売れるのでは、と冗談を交え、復活を呼びかけている。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:00:04〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3604s"]]}, {"cat": "好きなもの", "t": "カントリーアルバムを「白いアルバム」と命名", "b": "ラップではなくカントリー調のアルバムを出し、プロデューサーと相談して「ホワイト・アルバム」と名づけたそうだ。聴く前に名前だけ見て「白いアルバムか」と手に取る人を驚かせたかった、と笑う。若い頃にウェイロン・ジェニングスなどのカントリー曲を歌っていたことにも触れている。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:00:52〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3652s"]]}, {"cat": "リングの話", "t": "24/7王座は現場のアドリブだらけ", "b": "空港の駐機場、クリスマスのニューヨークの馬車など、あちこちで行われたシーンはほとんど現場の思いつきだったという。馬の御者が、お金を渡すたびにスペイン語で馬に速く走るよう指示していたのが面白かったと話す。結婚式への乱入は、奥さんも一緒に乗ってくれたそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:04:04〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3844s"]]}, {"cat": "リングの話", "t": "「ジョン・シナが子どもの頃の憧れ」はビンスの案", "b": "最初のマイクでシナを見て育ったと話した設定はビンスが書いたもので、観客が信じたので続いたという。技や服装を使う許可をシナに聞くと、むしろ全部やっていいと言われ、シャツに自分の顔を載せるアイデアもシナ本人の提案だったそうだ。心の広い人だと感心している。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:05:50〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=3950s"]]}, {"cat": "リングの話", "t": "「7秒ダンスブレイク」もビンスの指示", "b": "ビンスにマイクの途中で急に踊るよう言われたのが始まりで、ほかの番組でも真似されるほど広まったと話す。怒ったときに7秒踊れば落ち着ける、という冗談も飛び出した。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:08:11〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=4091s"]]}, {"cat": "体のこと", "t": "長年の髪のダメージで、ドレッドを切る決断", "b": "昔はブロンドやストレート、パーマなど髪をいろいろいじっていて、頭皮への負担が大きかったという。ドレッドをつなぎ合わせても髪が薄くなり、インタビュー映像で頭皮が透けて見えたのを見て切ろうと決めたそうだ。ファンからの率直なメッセージも背中を押したと笑う。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:12:07〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=4327s"]]}, {"cat": "リングの話", "t": "悪役を試してもヒールになりきれなかった", "b": "髪を切って新しい印象を出そうと考えた際は、トリプルHに相談してその夜に実行したという。ただ、ファンが求めているのは笑いをくれるRトゥルースで、悪役にすると観客は結局応援してしまう、と話す。昔の悪役のときもビンスに「うまくいかない」と言われたそうだ。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:15:22〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=4522s"]]}, {"cat": "暮らし", "t": "音楽と映画の仕事も続けている", "b": "音楽活動に加えて、9月には映画の撮影が入っていると話す。この先は宇宙の流れに任せて進むつもりで、「可能性は無限」と前向きに語っている。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で（字幕を全文確認）", "art": "ext-aHsNe4MbKwE", "src": [["番組のYouTube（1:19:28〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=4768s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "シナに教わった「迷うより動け」", "b": "迷うくらいならやってしまえ、すでに知っている場所へ行くな、と励まされたことがあると、Rトゥルースが話している。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で、Rトゥルースの話（字幕を全文確認）", "src": [["番組のYouTube（34:17〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2057s"]], "by": "第三者の話"});
  if (PROFILES["Road Dogg"]) PROFILES["Road Dogg"].facts.push({"cat": "暮らし", "t": "辞めかけた時に声をかけてくれた恩人", "b": "育成時代にロード・ドッグがあと2か月だけ頑張ろうと言って、引き留めてくれたと、Rトゥルースが話している。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で、Rトゥルースの話（字幕を全文確認）", "src": [["番組のYouTube（31:10〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=1870s"]], "by": "第三者の話"});
  if (PROFILES["Billy Gunn"]) PROFILES["Billy Gunn"].facts.push({"cat": "暮らし", "t": "「止めるから老ける」の言葉", "b": "ビリー・ガンが言っていた、年を取るから止めるのではなく止めるから老けるという考えに共感していると、Rトゥルースが話している。", "sp": "Rトゥルース", "d": "2026-05-28", "how": "アンダーテイカーの番組で、Rトゥルースの話（字幕を全文確認）", "src": [["番組のYouTube（47:53〜）", "https://www.youtube.com/watch?v=aHsNe4MbKwE&t=2873s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-aHsNe4MbKwE", d: "2026-05-28", show: "ext", who: ["R-Truth"], t: "Rトゥルースの回　更生施設からの再出発と、解雇騒動で知った愛", lead: "アンダーテイカーの番組に出た約81分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["R-Truth"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-aHsNe4MbKwE").map((x) => [x.t, x.b, x.sp])), open: ["更生施設で出会った人など、一般の私人の実名と、収容に関する生々しい経緯は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=aHsNe4MbKwE"]] });
  PROFILES["Becky Lynch"].facts.push(...[{"cat": "リングの話", "t": "若い頃は創作に噛みつき、今は『何とかする』", "b": "ベッキー・リンチは、若い頃なら会社の方針に頭の中で反発し、実際に創作側とぶつかっていただろうと話す。今は賛成でも反対でも仕事として受け止め、自分で成立させるやり方に落ち着いたという。自分の力に自信がついたことと、年数のおかげだそうだ。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（6:26〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=386s"]]}, {"cat": "リングの話", "t": "残る目標はマネー・イン・ザ・バンクの契約書", "b": "ベッキー・リンチは、やり残した目標はマネー・イン・ザ・バンクのブリーフケースだけだと話す。若手の誰かに行くと皆が思っているなかで自分が握り、王者たち全員を怯えさせたいという。この立場の自分だからこそ、みんなが一番嫌がる展開になるのが面白いそうだ。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（7:21〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=441s"]]}, {"cat": "リングの話", "t": "主役級の経験を積んでも、満たされはしなかった", "b": "ベッキー・リンチは、年間最大の祭典のメインイベントも全王座の獲得も済ませたが、それで幸せになるわけではないと気づいたという。収入面では意味があっても、そこを過ぎると大事なのは物語をどう語るかという芸の部分に戻ってくると話す。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（8:08〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=488s"]]}, {"cat": "リングの話", "t": "上に立ったら後輩を引き上げたかった", "b": "ベッキー・リンチは、自分が入った頃にベラ姉妹やトリニティ、タミーナ、ナタリアたちが梯子を下ろしてくれたので、頂点に立ったら同じことをしたいと思っていたという。メインを経験して観客の反応を知った今は、その音が出るよう試合を設計して若手に伝えられる。マキシーンが良い試合をして喜ぶ姿を見るのが、勝つことより満たされると話す。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（8:54〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=534s"]]}, {"cat": "リングの話", "t": "ベルトを失い、審判ジェシカ・カーのせいだと主張", "b": "ベッキー・リンチは、すでにインターコンチネンタル王者ではないのに、うっかり夫にベルトを持ってきてと頼んだ出来事を笑い話にしている。その流れで、ここ半年から一年は審判ジェシカ・カーが担当しなかった試合は10戦10勝だと言い張る。審判の資格を見せてもらっていないとも話し、役柄の理屈を貫いている。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（59:29〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=3569s"]]}, {"cat": "リングの話", "t": "『偉大すぎて当たり前になった』という王者の理屈", "b": "ベッキー・リンチは、自分は長く偉大でありすぎたため当たり前の存在になり、観客が自分を重ねられなくなったのだと語る。登っている間は味方でも、頂点に着くと離れていくという筋立てだ。それでもあのベルトは自分の赤ん坊のようなものだから必ず取り戻すし、ブリーフケースもいつか手にしたいと話す。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（1:09:49〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=4189s"]]}, {"cat": "リングの話", "t": "娘が生まれてからが一番の仕事だった", "b": "ベッキー・リンチは、娘のルーが生まれてからの約3年間が自分の最高の仕事だったと振り返る。毎週飛行機に乗り、週4日はバスで全米各地の興行を回ったという。子どもを連れて各地の子ども博物館や動物園、公園に寄った日々は大変だったが最高だったそうだ。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（1:11:31〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=4291s"]]}, {"cat": "リングの話", "t": "ファーガルやJDと同じ道場から頂点へ", "b": "ベッキー・リンチは、育成時代の仲間ファーガル・デバイとJDを振り返る。JDは12歳で道場に来た小柄な少年で、誰からも愛されたという。エリミネーション・チェンバーの後にファーガルと抱き合い、「誰が想像した？」と感じたそうだ。彼は絶対ここに来ると思っていたとも話す。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（1:14:42〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=4482s"]]}, {"cat": "リングの話", "t": "7年間リングを離れ、奇妙なキャラも乗り越えた", "b": "ベッキー・リンチは、19歳のとき自分の望む道は無理だと諦め、7年間離れていたと話す。戻ったNXTではスチームパンクなど変な設定が多く、アダム・ローズの「ローズバッド」役もこなしたという。運動能力や見た目で勝てなくても、誰より練習量を重ね何事も見下さない姿勢で生き残ったそうだ。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（1:17:49〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=4669s"]]}, {"cat": "リングの話", "t": "『才能がない』と思うことが強みになる", "b": "ベッキー・リンチは、自分はリングの中で生まれつきの才能があったとは思わず、プロレスを理解する頭と観客に心を開く力が持ち味だと話す。だから間違いを教えてほしいと常に聞き続け、より良い物語と試合を目指してきたという。才能に頼ると自惚れて崩れやすいので、そこは足りない方がいいとも考えているそうだ。", "sp": "ベッキー・リンチ", "d": "2026-06-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-becky", "src": [["番組のYouTube（1:21:56〜）", "https://www.youtube.com/watch?v=kk0DxhJqE00&t=4916s"]]}]);
  { const A = ARTICLES.find((a) => a.id === "wys-becky"); if (A) A.points.push(...[["若い頃は創作に噛みつき、今は『何とかする』", "ベッキー・リンチは、若い頃なら会社の方針に頭の中で反発し、実際に創作側とぶつかっていただろうと話す。今は賛成でも反対でも仕事として受け止め、自分で成立させるやり方に落ち着いたという。自分の力に自信がついたことと、年数のおかげだそうだ。", "ベッキー・リンチ"], ["残る目標はマネー・イン・ザ・バンクの契約書", "ベッキー・リンチは、やり残した目標はマネー・イン・ザ・バンクのブリーフケースだけだと話す。若手の誰かに行くと皆が思っているなかで自分が握り、王者たち全員を怯えさせたいという。この立場の自分だからこそ、みんなが一番嫌がる展開になるのが面白いそうだ。", "ベッキー・リンチ"], ["主役級の経験を積んでも、満たされはしなかった", "ベッキー・リンチは、年間最大の祭典のメインイベントも全王座の獲得も済ませたが、それで幸せになるわけではないと気づいたという。収入面では意味があっても、そこを過ぎると大事なのは物語をどう語るかという芸の部分に戻ってくると話す。", "ベッキー・リンチ"], ["上に立ったら後輩を引き上げたかった", "ベッキー・リンチは、自分が入った頃にベラ姉妹やトリニティ、タミーナ、ナタリアたちが梯子を下ろしてくれたので、頂点に立ったら同じことをしたいと思っていたという。メインを経験して観客の反応を知った今は、その音が出るよう試合を設計して若手に伝えられる。マキシーンが良い試合をして喜ぶ姿を見るのが、勝つことより満たされると話す。", "ベッキー・リンチ"], ["ベルトを失い、審判ジェシカ・カーのせいだと主張", "ベッキー・リンチは、すでにインターコンチネンタル王者ではないのに、うっかり夫にベルトを持ってきてと頼んだ出来事を笑い話にしている。その流れで、ここ半年から一年は審判ジェシカ・カーが担当しなかった試合は10戦10勝だと言い張る。審判の資格を見せてもらっていないとも話し、役柄の理屈を貫いている。", "ベッキー・リンチ"], ["『偉大すぎて当たり前になった』という王者の理屈", "ベッキー・リンチは、自分は長く偉大でありすぎたため当たり前の存在になり、観客が自分を重ねられなくなったのだと語る。登っている間は味方でも、頂点に着くと離れていくという筋立てだ。それでもあのベルトは自分の赤ん坊のようなものだから必ず取り戻すし、ブリーフケースもいつか手にしたいと話す。", "ベッキー・リンチ"], ["娘が生まれてからが一番の仕事だった", "ベッキー・リンチは、娘のルーが生まれてからの約3年間が自分の最高の仕事だったと振り返る。毎週飛行機に乗り、週4日はバスで全米各地の興行を回ったという。子どもを連れて各地の子ども博物館や動物園、公園に寄った日々は大変だったが最高だったそうだ。", "ベッキー・リンチ"], ["ファーガルやJDと同じ道場から頂点へ", "ベッキー・リンチは、育成時代の仲間ファーガル・デバイとJDを振り返る。JDは12歳で道場に来た小柄な少年で、誰からも愛されたという。エリミネーション・チェンバーの後にファーガルと抱き合い、「誰が想像した？」と感じたそうだ。彼は絶対ここに来ると思っていたとも話す。", "ベッキー・リンチ"], ["7年間リングを離れ、奇妙なキャラも乗り越えた", "ベッキー・リンチは、19歳のとき自分の望む道は無理だと諦め、7年間離れていたと話す。戻ったNXTではスチームパンクなど変な設定が多く、アダム・ローズの「ローズバッド」役もこなしたという。運動能力や見た目で勝てなくても、誰より練習量を重ね何事も見下さない姿勢で生き残ったそうだ。", "ベッキー・リンチ"], ["『才能がない』と思うことが強みになる", "ベッキー・リンチは、自分はリングの中で生まれつきの才能があったとは思わず、プロレスを理解する頭と観客に心を開く力が持ち味だと話す。だから間違いを教えてほしいと常に聞き続け、より良い物語と試合を目指してきたという。才能に頼ると自惚れて崩れやすいので、そこは足りない方がいいとも考えているそうだ。", "ベッキー・リンチ"]]); }
  if (!ROSTER.find((r) => r[1] === "LA Knight")) ROSTER.push(["LAナイト", "LA Knight", "lg", "人気急上昇のスター", "", "", ""]);
  if (!PROFILES["LA Knight"]) PROFILES["LA Knight"] = { lead: "ふだんはスリムな体型と猫背気味の姿勢を気にし、休みには愛犬とごろごろするのが何よりの楽しみ。遅咲きの人気者は、倹約家で冗談好きな素顔を見せている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=LA%20Knight"]], moves: [], facts: [] };
  if (PROFILES["LA Knight"]._weak) { PROFILES["LA Knight"].lead = "ふだんはスリムな体型と猫背気味の姿勢を気にし、休みには愛犬とごろごろするのが何よりの楽しみ。遅咲きの人気者は、倹約家で冗談好きな素顔を見せている。"; delete PROFILES["LA Knight"]._weak; }
  PROFILES["LA Knight"].facts.push(...[{"cat": "体のこと", "t": "自然に割れた腹筋と、骨盤の前傾の悩み", "b": "子どもの頃は細身で、腹筋は何もしなくても割れていたという。そのせいで腹筋を鍛えず、体幹が弱いまま大人になったと話す。骨盤が前に傾いて姿勢が崩れ、年に1〜2回は背中がつって1週間ほど変な歩き方になるそうだ。いまは体幹とお尻の筋力を整えている。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:32〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=92s"]]}, {"cat": "体のこと", "t": "柔軟性は「伸びた姿勢で強くなる」鍛え方", "b": "ストレッチや可動域の練習はかなりの量をこなしているという。ただ重視するのは、弱い位置を見つけて、そこで力を出せるようにすること。若い頃はフォームも悪く、こうした練習を全くしていなかったと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（2:21〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=141s"]]}, {"cat": "体のこと", "t": "育成施設時代に腰を痛めたトレーニング", "b": "育成施設に入った当時は、スクワットとデッドリフトを短い時間に詰め込んでいたそうだ。ウォームアップが足りず、腰がぼろぼろになったという。スクワットは念入りな準備がないと体に合わないと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（2:21〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=141s"]]}, {"cat": "体のこと", "t": "増量と維持が基本、ときどき絞る", "b": "普段は筋量をつけて維持することが中心で、ときどき自分に気合を入れて少し絞る、と話す。この日も体重を約3キロ落としている最中だった。気になる所が見えると直したくなり、気持ちの面が一番やっかいだという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（4:47〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=287s"]]}, {"cat": "リングに来るまで", "t": "一度は「管理役」に回された時期", "b": "入団当初は、のちに大物となるマネージャー兼レスラーのような道だと説明されて受け入れたという。ところが実際は雰囲気が違い、このままでは先がないと感じるようになったそうだ。本人は自分の経歴を壊されるような気持ちだったと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（11:12〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=672s"]]}, {"cat": "リングの話", "t": "試合に出られず、控えめな声を求められた日々", "b": "マネージャー役の頃は、台本の言葉を調べながら、声を抑えるよう求められたという。ある日は自分の言い方に不満を持たれ、会場を出て車の中で頭を冷やしたそうだ。直後に権力者が退いたことで、自分の立場も変わったと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（11:59〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=719s"]]}, {"cat": "リングに来るまで", "t": "体制交代の直後、トリプルHに連絡して救われた", "b": "リングから外され、解雇されるかもしれないと感じていた頃に、上層部が入れ替わったという。金曜は解雇が多いので電話の電源を切り、翌日にトリプルHへメッセージを送ったそうだ。すぐに通話で「残ってほしい」と言われ、数週間後に元の名前に戻る話が来たという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（18:31〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1111s"]]}, {"cat": "リングの話", "t": "ブレイ・ワイアット戦に向けて存分に話せた", "b": "ブレイ・ワイアットに「やられ役」として当てられると感じていたが、1か月以上のマイクの機会があり、自分らしく話せたことをむしろ好機だったと話す。超自然的な相手とは、茶化しすぎず怖がりすぎない距離の取り方が難しかったそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（20:08〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1208s"]]}, {"cat": "リングの話", "t": "ヒールに戻る指示が、結果的に道を開いた", "b": "ある試合のあとの話で、書き手から悪役に戻るマイクを指示されたが、観客はむしろ歓声を上げたという。トリプルHに理由を聞かれて指示だったと答えた、というやり取りがあったそうだ。はじめから正統派で出ていたら、平凡に終わったかもしれないと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（20:56〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1256s"]]}, {"cat": "リングの話", "t": "記者会見の場でAJスタイルズと大乱闘", "b": "年に一度の最大の祭典の前の取材で、AJスタイルズが椅子を投げたので思わず殴り合いになったという。止めに入る警備がなかなか来ず、本気に見えるよう動き続けたそうだ。これまでの抗争の流れを守るために自然に動いた、と話す。結果はAJが鼻血を出し、後から会社に注意の連絡も来たという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（25:06〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1506s"]]}, {"cat": "リングに来るまで", "t": "1年前に消えた大舞台と、家族のロサンゼルス案内", "b": "地元開催の大会の直前、準備していた出番が2日前に白紙になったという。家族は航空券を取ってしまっていたため、野球観戦や海辺を案内するだけの滞在になったそうだ。翌年のフィラデルフィアでようやく出場でき、家族も面白がっていると話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（29:10〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1750s"]]}, {"cat": "体のこと", "t": "大きなけがも手術もないまま20年", "b": "20年のキャリアで大きな手術や長期欠場はないと話す。鼻を1度折り、脳しんとうも何度かあるが、休みを取るほどではなかったそうだ。首や腰の痛みは誰にでもあるものとして、普段から付き合っている。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（32:21〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1941s"]]}, {"cat": "体のこと", "t": "遅いデビューのおかげで体が消耗していない", "b": "頻繁な地方巡業が多かった時代に長くいた選手は、体がかなり傷んでいると話す。自分は今の比較的楽な日程で稼げる時期に来られたので、結果的に運がよかったと考えているそうだ。年齢の数字ばかり見られたことには理解も示している。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（32:21〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1941s"]]}, {"cat": "暮らし", "t": "旅の間も、愛犬が恋しい", "b": "遠征が続くと家と愛犬が恋しくなると話す。犬と過ごせる年月は10〜15年ほどだと思うと胸が痛み、離れている時間が嫌でたまらないそうだ。若い頃なら大喜びした海外遠征も、いまは気持ちが違うという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（33:12〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=1992s"]]}, {"cat": "暮らし", "t": "引退後は犬の保護施設を開きたい", "b": "いつかは表舞台から静かに消えて、犬の保護施設を開くのが夢だと冗談めかして話す。ただ本人は「かなり本気だ」とも言う。殿堂入りの話が来れば戻るかもしれないが、そうなるとは思っていないそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（33:58〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2038s"]]}, {"cat": "リングに来るまで", "t": "キャラの原点は、TNA時代のイーライ・ドレイク", "b": "TNAに入った2015年に、団体側から「イーライ・ドレイク」という名前を提案されたという。ユニット内では三番手で、ほとんど話す機会がなかった。そこから単独で話す場面を得て、名前を強調して言うくせが定着したそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（37:06〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2226s"]]}, {"cat": "リングに来るまで", "t": "TNA時代のユニットでは「三番手」だった", "b": "当時の仲間にはドリュー・マッキンタイアらがいた。ある試合のあと、先輩のトミー・ドリーマーが仲間の一人を高く評価し、自分は「悪くない」程度だったと話す。結局、ユニットの中では目立たない立場が続いたという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（37:06〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2226s"]]}, {"cat": "リングに来るまで", "t": "「遅すぎた」という焦りの毎年", "b": "年に一度の最大の祭典の時期は、毎年「また逃した」という気持ちで苦しい週だったと話す。本来は10年以上前に出ているべきだったと思っていたそうだ。いまは3度目の出場を終え、気持ちが落ち着いたという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（40:00〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2400s"]]}, {"cat": "リングに来るまで", "t": "今の名前は「LA」が自分、「ナイト」が会社の案", "b": "育成施設に入った2021年、当初はイーライ・ドレイクのまま行く話だったが、直前に変更になったという。「LA」は自分の案、「ナイト」は会社側の案で、組み合わせてLAナイトになった。「LAドノバン」という案も出たが、ひどいと思って断ったそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（41:11〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2471s"]]}, {"cat": "リングの話", "t": "ジョン・シナが手を上げてくれた場面", "b": "2022年の大会で、審判役のジョン・シナが自分を認める仕草をしたとき、すぐ素直に受けるのは違うと考えたという。直前の試合展開があったので、少し言い返すような態度で応じ、あとで周りから「相手はシナだぞ」と言われたそうだ。次の大会では自分から相手の手を上げて敬意を示したと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（47:41〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=2861s"]]}, {"cat": "リングの話", "t": "ローガン・ポールの大技を受け止めた", "b": "サマースラム2024の大技の前、ローガン・ポールには「回りすぎないで、体を平らにして」と伝えただけだという。受け止めたあとは脚をけがしたと思って焦ったが、問題なかったそうだ。ジョン・シナが手を上げる場面を断ったことを、あとで冗談で責められたとも話している。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（50:50〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3050s"]]}, {"cat": "リングの話", "t": "サングラスに映ったローマン・レインズが名場面に", "b": "ローマン・レインズ戦の直前に、サングラスにローマンが映る写真が広まり、ネタにされたという。それを見て、このサングラスはもう変えられないと思ったそうだ。偶然撮れたもので、狙ったわけではないと話す。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（52:26〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3146s"]]}, {"cat": "リングの話", "t": "マイクは「箇条書き」と空気で作る", "b": "台本が箇条書きになり、決めたい言葉だけ会社の指示に合わせているという。向かい合う形のマイクは決まりが多くて苦手で、一人で話すほうが自由で好きだと話す。内容より、口調と話し方が大事だと考えているそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（54:54〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3294s"]]}, {"cat": "リングの話", "t": "スリム・ジムの顔になったきっかけ", "b": "2023年夏に、スナック菓子のスポンサー契約の話が来たという。企画のバトルロイヤルで勝ち、スリム・ジムのLAナイトになったと話す。昔のマッチョマンの広告を覚えているので、自分もそうなれたのは不思議な気持ちだという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（57:12〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3432s"]]}, {"cat": "好きなもの", "t": "ドラムは「初心者より上、達人ではない」", "b": "ドラムの腕前は初心者以上だが達人ではない、と話す。決まったリズムと数回のブレイクなら叩けるが、ドラムソロは苦手だそうだ。インディアナポリスの店で、居合わせたバンドのドラムを借りて数曲叩いたこともあるという。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:00:20〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3620s"]]}, {"cat": "好きなもの", "t": "歌は自信がない", "b": "メイク担当の人たちには歌がうまいと言われるが、自分では全然そう思わないと話す。以前、クリスマスのような企画で少し酔って歌ったときの出来がひどかったと振り返っている。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:00:20〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3620s"]]}, {"cat": "リングの話", "t": "シャンパンで酔った名物マイクの裏話", "b": "ステージで大きなシャンパンボトルを飲み、言い間違えたことがそのまま笑いになったという。もともと平凡な内容だったのが、あの失敗で思い出深い回になったと話す。YouTube番組では、他人の話に入り込まないかぎり何を言ってもいいと言われ、とても楽しかったそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:02:43〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3763s"]]}, {"cat": "リングに来るまで", "t": "TNAでタッグ王座、相手はスコット・スタイナー", "b": "スコット・スタイナーと組んでタッグ王座を獲ったことがあるという。どういう経緯で組まされたかは覚えていないと話す。その後タッグを解消して自分が勝ったと笑い、そのベルの写真を自宅の部屋に飾っているそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:04:16〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=3856s"]]}, {"cat": "リングに来るまで", "t": "高校時代の遊びが「ディック・リック」の名前に", "b": "高校ではクロスカントリーとドラムラインに所属し、友人と手作りでラップのカセットを録ったという。その名前が「ディック・リック」で、のちに団体の企画で同じ名前を使うことになったそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:06:40〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=4000s"]]}, {"cat": "リングに来るまで", "t": "最初のリング名は「ナンバー2」", "b": "2003年ごろにレスラーを目指して練習していた当時の名前は「ナンバー2」だったという。同じショーンという名前の人がもう一人いて、先輩が冗談でそう呼んだのが始まりだ。デビュー後はユニットに入れられたが、浮いていたために途中で離れ、「デュース」と名乗るようになったそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:07:33〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=4053s"]]}, {"cat": "暮らし", "t": "愛犬ハーマンとリーシー", "b": "愛犬は2匹いて、リーシーは怖がりで来客にはよく吠えるが、仲良くなるととても甘えん坊になるという。ハーマンは大きくて陽気な性格で、ハロウィンの写真では「ライオン」の役をしていたそうだ。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:13:10〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=4390s"]]}, {"cat": "暮らし", "t": "お金には堅実で、服は安いものが好き", "b": "長い間お金に困りながらこの道を追ってきたので、いまは老後の心配がなくなったことに感謝していると話す。贅沢は友人を招いて旅費をもつときぐらいで、普段は倹約家だという。着ているのはタンクトップと2千円台の短パンで、高級ブランドに使う人たちを不思議がっている。", "sp": "LAナイト", "d": "2026-06-04", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-vndIUAQ6WGc", "src": [["番組のYouTube（1:14:02〜）", "https://www.youtube.com/watch?v=vndIUAQ6WGc&t=4442s"]]}]);
