  if (PROFILES["Sami Zayn"].lead === "モントリオールの草の上で練習を始め、マスク姿で世界を回った末にWWEへたどり着いたという。旅好きで、自分の持ち場を最高の見せ場にすることにこだわる職人肌の人だ。") PROFILES["Sami Zayn"]._weak = 1;
  PROFILES["Sami Zayn"].facts.push(...[{"cat": "暮らし", "t": "遠征先ではオープンカーを借りる", "b": "普段は燃費のいい控えめなレンタカーを選ぶという。ところがニューメキシコあたりで見かけたオープンカーに乗ってみたところ、日差しと音楽が最高で、すっかり気に入ったそうだ。それ以来、借りられるときはマスタングを選んでいると話す。自宅用の車は2004年式の日産アルティマだという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:36〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=96s"]]}, {"cat": "暮らし", "t": "旅は「貧しく育った者の義務」", "b": "2005年に初めて欧州遠征に呼ばれたときは、二度とない機会かもしれないと思ったという。当時は携帯も通じず、友人のスーパー・ドラゴンと空港で迎えを待つしかなかったそうだ。自分は貧しい家で育ったので、仕事で旅ができるなら現地をしっかり見て回るのが機会への礼儀だと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（3:09〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=189s"]]}, {"cat": "リングの話", "t": "ジャッカス勢との祭典の一戦は自慢の一戦", "b": "大舞台でジャッカスの面々と戦った試合を、とても誇りに思っているという。コメディの試合と片づけられるのは嫌で、構成を分解すれば必要な要素をすべて満たしていると話す。経験のない51歳の相手と約7万5千人を最後の7分間立たせたのは勲章だそうだ。批判した人もいたが、そう言う人はプロレスを分かっていないとまで言う。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（5:31〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=331s"]]}, {"cat": "リングの話", "t": "笑いも本気でやり切る、巨匠の評価も励みに", "b": "何をするにも全力で打ち込むのが信条だという。トップ戦線に絡むには遠回りかもしれないが、10年は記憶に残る試合を選びたかったそうだ。試合後、ヴィンス・マクマホンは芸術作品だと褒めてくれた。一方で、真面目な試合を好むブレットがどう思うかだけ気になっていたと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（13:25〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=805s"]]}, {"cat": "リングの話", "t": "「あれ以上の試合はない」と心が穏やか", "b": "大舞台でこれ以上の試合はもうできないと思えて、心が落ち着いたという。同じ大会でケビンも自分の試合について同じことを言っていたそうだ。今後もっと大きな試合や技術的な試合があっても、あの試合は一番の誇りだと話す。世界王座を取れなくても構わないほどだという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（16:31〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=991s"]]}, {"cat": "家族", "t": "父はシリアでアマチュアレスリング", "b": "モントリオールで育ち、いちばん古い記憶のひとつはホーガンの試合後の姿だという。父がシリアでアマチュアレスリングをしていた人で、一緒にプロレスを見ていたそうだ。派手で大きな存在に幼い頃から心を奪われたと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（17:22〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1042s"]]}, {"cat": "好きなもの", "t": "幼い頃はホーガン、少しして憧れはブレット", "b": "4〜6歳の頃は、ホーガンやウォリアーのような規格外のスターに惹かれたという。8〜9歳になると試合そのものの技術に目が向くようになった。同じカナダ出身のブレット・ハートが最大のヒーローになったそうだ。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（18:59〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1139s"]]}, {"cat": "リングに来るまで", "t": "中2の夢が、18歳で突然かなった", "b": "中学の頃、友人とタッグを組もうと話していたが、転校して三年ほど連絡が途絶えたという。ある日その友人から、ラジオ番組の取材で知り合った地元レスラーが教えてくれると電話があった。月謝は週25ドルで、練習場は友人宅の裏庭だったそうだ。マットレスは一週間で使えなくなり、あとはずっと草の上で受け身を取っていたと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（19:45〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1185s"]]}, {"cat": "リングに来るまで", "t": "最初の試合名は「スティーヴィー・マクフライ」", "b": "練習を約半年積み、初試合を決めるまでにさらに2〜3か月かかったという。リングネームは当日に、響きがかっこいいというだけで決めたそうだ。その後バスと地下鉄で東の端の教会の地下まで出向き、客が三人ほどの会場に自分を売り込んだと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（22:10〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1330s"]]}, {"cat": "家族", "t": "母は「この子に将来はありますか」と尋ねた", "b": "練習を始めて数か月、冬の最後の練習日にコーチが初めて家へ来たという。小柄な母が、本名のラミに将来はあるでしょうかとコーチに聞いたそうだ。本人は未来など考えず、いま試合をしたいだけだったと振り返る。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（22:59〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1379s"]]}, {"cat": "信仰", "t": "母はヒジャブをかぶるムスリム", "b": "本人の話では、母はヒジャブをかぶるイスラム教徒の女性だという。コーチへ息子の進路を聞きに来たのは、その母だったそうだ。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（22:59〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1379s"]]}, {"cat": "リングに来るまで", "t": "マスク時代は「戯画の人物」になれた", "b": "約11年間マスクをかぶって試合をした、エル・ジェネリコ時代があるという。改名は一晩限りのつもりだったそうだ。マスクのおかげで普通の人でなくなり、漫画のような動きを試せる自由があったと話す。素顔になってから表情や話術が評価され、驚かれたという。ただ体の動きで伝える芸と、表情で伝える芸は別物だと語る。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（25:26〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1526s"]]}, {"cat": "リングに来るまで", "t": "失恋をきっかけに世界中へ遠征", "b": "2010年ごろ、唯一の交際相手と別れたという。モントリオールにいる理由がなくなったので、悪いことの中から良い面を探して予定を詰め込んだそうだ。新しい国で試合をするため、できるだけ多くの土地を回ったと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（26:58〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1618s"]]}, {"cat": "リングに来るまで", "t": "ケビン・オーウェンズとはすぐ意気投合", "b": "同じ頃のモントリオールで出会ったケビンとは、考え方がよく似ていたという。二人ともWWEを夢でなく目標として見ていたそうだ。自分は国際的な活動に関心が強く、先のことを細かく決めずにその場を楽しむ性格だと話す。昔の写真を見て、まさかWWEに来るとは思えなかったと笑う。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（28:33〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1713s"]]}, {"cat": "リングに来るまで", "t": "最初にWWEの名を聞いたのは2006年", "b": "ジェイミー・ノーブルから電話があり、WWEで軽量級の番組が始まるかもしれないから映像を送ってほしいと言われたという。訛りが強く、最初は地方の団体の話かと勘違いしていたそうだ。その時は期待しないようにしたと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（31:50〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=1910s"]]}, {"cat": "リングに来るまで", "t": "2010年のエキストラ仕事で自信を失った", "b": "2010年に一度だけWWEの仕事でエキストラをしたという。トロントへ向かう車の中で、自分は小さいし場違いだと自信を失い、ティム・ホートンズの駐車場で気持ちを立て直したそうだ。その一、二年後に受けた入団テストでは気持ちが一変し、自分が全員に見せつけてやると意気込んで臨んだと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（34:13〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2053s"]]}, {"cat": "リングに来るまで", "t": "入団テストの全員一致の合格が支えに", "b": "インディーでは評価されても、WWEの大物たちが自分をどう見るかは分からなかったという。テストは全員一致で合格だった。このとき12人ほどが契約したそうだ。リーガルやジョーイ・マーキュリーが後押ししてくれ、意外にもトリプルHにも気に入られたと話す。その時点で引退してもいいと思えたほど励みになったという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（36:39〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2199s"]]}, {"cat": "リングに来るまで", "t": "本名「ラミ」コールに戸惑った", "b": "育成施設に入った当初、サミ・ゼインの名前がまだなく、本名のラミで試合に出たという。観客にラミと呼ばれて、とても不思議な気持ちになったそうだ。本名のラミはサミと似ていると話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（38:10〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2290s"]]}, {"cat": "リングの話", "t": "セザーロ戦が育成の空気を変えた", "b": "入った頃の育成の現場は型にはまっていて、新しい試みは叱られたという。そこへ一軍経験のあるセザーロが来て、自由にやれる雰囲気が生まれたそうだ。二人で組み立てた試合をきっかけに、現場が自由な場へ変わったと話す。当時厳しかったコーチのテリー・テイラーは、今では師匠のような存在だという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（41:20〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2480s"]]}, {"cat": "リングに来るまで", "t": "名コーチ、ダスティの教えで話術を磨いた", "b": "高い声に悩んだが、話すこと自体は得意だったという。コーチのダスティ・ローデスのもとで約1年半学び、話す力を伸ばしてもらったそうだ。アンダーテイカーに、プロモも試合も客を呼べる出来だと言われたのは大きな自信になったと話す。ダスティから若い頃のロビン・ウィリアムズに似ていると言われ、映像を見て自分はまだまだだと思ったという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（46:12〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2772s"]]}, {"cat": "リングの話", "t": "出世争いをやめ、自分の持ち場で一番を狙う", "b": "以前は、なぜあの人は上にいて自分は違うのかと、ずっと悩んでいたという。ローマン・レインズがその場所にいるのは動かない事実だと悟り、自分の持ち場を世界一面白くすると決めたそうだ。無駄に焦るのをやめたら、幸せになり、試合も良くなったと話す。インディー時代から、自分の試合がカードで一番だと思って戦ってきたという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（51:04〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3064s"]]}, {"cat": "リングに来るまで", "t": "王座は「ここに居場所がある」という証", "b": "契約しても活躍の保証はなく、すぐ解雇されることもあり得たと振り返る。そんな中で育成の王座を取ったことは、かつて自分を認めないと思っていた場所に価値を認められた実感になったそうだ。旧友ケビンと、その団体で教会の地下や公民館でやった抗争を再現できたことも大きかったと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（55:02〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3302s"]]}, {"cat": "リングに来るまで", "t": "憧れのシナと、憧れのブレットに囲まれた初舞台", "b": "一軍の初登場の相手は子どもの頃からの憧れのジョン・シナだったという。紹介役はブレット・ハートで、初めて生で観た大会は1997年のサバイバー・シリーズだったそうだ。当時は双眼鏡でリングを見ていた。そのブレットに紹介してもらえて、まるで円を描いて戻ってきたようだと話す。シナの観客を巻き込む力にも感心したという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（58:12〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3492s"]]}, {"cat": "体のこと", "t": "肩が外れかけても試合を続けた", "b": "この初登場の試合で肩が亜脱臼を起こしたという。肩が外れてすぐ戻る状態で、経験のないことだったそうだ。それでも試合をやり切り、のちに初めての手術を受けて半年か七か月ほど休んだと話す。試合前にはビックスの塗り薬を使うが、効果は気持ちの問題だという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（59:00〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3540s"]]}, {"cat": "体のこと", "t": "長いけがは外から見る機会になった", "b": "けがで休んだ約1年は、プロレス界の外から業界を見る貴重な時間になったという。何が観客に響き、何が響かないかをよく見たそうだ。業界の常識がなぜそうなのか疑う目も持てて、復帰したらやらないことを決められたと話す。誰もが一度は離れてみるとよいと考えている。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:03:03〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3783s"]]}, {"cat": "リングの話", "t": "ニアフォールを抑えた名勝負の裏側", "b": "中邑真輔との育成の大会での一戦は、構成にも自信があるという。育成で流行した大げさなニアフォールの連発が似通ってきたと感じ、あえて決定的な場面を一度だけにしたそうだ。それでも観客の熱は途切れなかった。相手を引き立てながら戦ったことも誇りで、自分にとっては別れの試合だったと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:05:31〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=3931s"]]}, {"cat": "リングの話", "t": "ケビンとの相性は「やられ方」が上手いこと", "b": "ケビンとの試合が最高なのは、互いに相手を壊すほど攻め、相手に壊されるほど受けるからだという。トリプルHは別の試合の後、技の凄さでなく、物語と受けの上手さを褒めたそうだ。お互いが相手より上手に受けようとする姿勢が大事だと教わったと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:09:34〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=4174s"]]}, {"cat": "リングの話", "t": "ヴィンスの一言で悪役に転向", "b": "2017年の夏、伸び悩みを感じてヴィンスに相談したという。返ってきたのは、まだ悪役をやっていないからだ、という答えだったそうだ。それまでずっと正統派だったので意外だったが、転向して性格づけや話術を広げられたと話す。審判役を務めた夜の振る舞いが首脳陣に受け、その後はマイクを持つ機会が増えたという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:13:31〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=4411s"]]}, {"cat": "リングの話", "t": "目標は世界王座に一度だけ就くこと", "b": "世界王座を一度だけ取れたらいい、と話す。ただ王座がすべてではないという。一番取りたかったのは、昔のスターたちが持っていた大陸間王座だったそうだ。ブレットら憧れの名がその系譜に並んでいる。いつか選手を引退したら、ボビー・ヒーナンやポール・ヘイマンのように口で生きたいと話す。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:27:13〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=5233s"]]}, {"cat": "リングの話", "t": "「小さく見せる」のが自分の流儀", "b": "ボビー・ラシュリーとの会話から、自分は意図して小さく戦ってきたと気づいたという。正統派では弱さを、悪役では情けなさを見せたいからだそうだ。だがトップで引っ張る立場に上がるには、これが足かせかもしれないと20年目で気づいたと話す。それでも体が自然にそう動いてしまうという。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-kkeYvZ_nbVI", "src": [["番組のYouTube（1:33:41〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=5621s"]]}]);
  if (PROFILES["Johnny Knoxville"]) PROFILES["Johnny Knoxville"].facts.push({"cat": "暮らし", "t": "ジョニー・ノックスビルの機転", "b": "試合で使った大きなネズミ捕りの仕掛けが、ロープが切れて動かなくなったが、ジョニー・ノックスビルは慌てず対応した、とサミが話している。その日の朝に仕掛けの動かし方を聞いていたため、慣れた選手でも難しい場面を切り抜けられたという。サミは彼に大きな敬意を払っている、と話している。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、サミ・ゼインの話（字幕を全文確認）", "src": [["番組のYouTube（11:51〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=711s"]], "by": "第三者の話"});
  if (PROFILES["Undertaker"]) PROFILES["Undertaker"].facts.push({"cat": "暮らし", "t": "アンダーテイカーの「客を呼んだ」の一言", "b": "育成の現場でサミとケビンの試合とプロモを見たアンダーテイカーが、「あれこそ客を呼ぶやり方だ」と声をかけてくれた、とサミが話している。控室で大声で褒めたのに誰も反応せず、ほんの一瞬不安そうな顔を見せ、もう一度言い直した場面を、ケビンが笑い話にしている、とサミが話している。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、サミ・ゼインの話（字幕を全文確認）", "src": [["番組のYouTube（48:44〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=2924s"]], "by": "第三者の話"});
  if (PROFILES["Paul Heyman"]) PROFILES["Paul Heyman"].facts.push({"cat": "暮らし", "t": "ポール・ヘイマンは歩く恐竜", "b": "ポール・ヘイマンについて、プロレスと関係ない話をするのが一番好きだ、とサミが話している。ヴィンス・マクマホンの父の時代から業界にいる人で、14歳でMSGの裏に入り込んでアンディ・カウフマンとフレディ・ブラッシーに取材した話を聞いたことがある、とサミが話している。", "sp": "サミ・ゼイン", "d": "2026-06-06", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、サミ・ゼインの話（字幕を全文確認）", "src": [["番組のYouTube（1:24:41〜）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI&t=5081s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-kkeYvZ_nbVI", d: "2026-06-06", show: "ext", who: ["Sami Zayn"], t: "サミ・ゼインの回　草の上の練習場からマスク時代、そして大舞台まで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約96分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Sami Zayn"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-kkeYvZ_nbVI").map((x) => [x.t, x.b, x.sp])), open: ["マスク時代の話は、本人が番組で語った範囲だけを載せた。", "字幕は自動生成のため、聞き手の発言と本人の発言が混ざる箇所があり、迷った部分は載せていない。", "試合の結果や筋書きの結末にあたる話は、この記事では扱っていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=kkeYvZ_nbVI"]] });
