  if (!PROFILES["Cathy Kelley"]) PROFILES["Cathy Kelley"] = { lead: "自分は観客と選手をつなぐ「パイプ役」だと語るインタビュアー。人見知りだった少女時代から、筋トレ好きの今の自分まで、変わり続けることを楽しむ人だ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cathy%20Kelley"]], moves: [], facts: [] };
  if (PROFILES["Cathy Kelley"]._weak) { PROFILES["Cathy Kelley"].lead = "自分は観客と選手をつなぐ「パイプ役」だと語るインタビュアー。人見知りだった少女時代から、筋トレ好きの今の自分まで、変わり続けることを楽しむ人だ。"; delete PROFILES["Cathy Kelley"]._weak; }
  PROFILES["Cathy Kelley"].facts.push(...[{"cat": "体のこと", "t": "「ひょろひょろ」から筋トレ好きに", "b": "昔は有酸素運動ばかりで「ひょろひょろ」とからかわれていたという。コロナ禍に心の健康のためウエイトトレーニングを始め、今では1日2回やる日もあるほどはまっているそうだ。電気刺激のスーツを着て鍛えるトレーニングもしていると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=143s"]]}, {"cat": "暮らし", "t": "友だちとのトレーニングが楽しみ", "b": "ピラティスやグループレッスンが好きで、友人と一緒に体を動かす時間が、そのまま友人と過ごす時間になっているという。遠征中は時差や早い便で難しいが、できる日に詰め込んでいると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（4:00〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=240s"]]}, {"cat": "リングの話", "t": "ジョー・テシトーレは家族のよう", "b": "番組の日は、まずメイクとエスプレッソ。リングサイドで実況のジョー・テシトーレの隣に座るのが定番で、ウェイド・バレットに席を追い出されるまでいるという。テシトーレは家族のような存在で、もっと企画を出せと背中を押してくれるそうだ。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（7:09〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=429s"]]}, {"cat": "リングの話", "t": "観客の代わりに話を聞く", "b": "仕事を聞かれると「レスラーにインタビューしている」と答えるという。自分は観客が選手に一番近づける「パイプ役」だと考えていて、反応するときも質問するときも、それを頭に置いていると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（10:23〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=623s"]]}, {"cat": "リングの話", "t": "Rトゥルース復帰で涙", "b": "放送中に初めて涙ぐんだのは、Rトゥルースが一度契約を解かれた後に戻ってきた場面だという。控室の雰囲気を明るくしてくれる人で、別れを言えなかったのがつらかったぶん、戻ってきたのが本当にうれしかったそうだ。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（11:09〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=669s"]]}, {"cat": "好きなもの", "t": "ブロンソン・リードと音楽仲間", "b": "WWEで特に親しいのはケビン・オーエンズとブロンソン・リード。リードとは毎週のように音楽を送り合い、ポップ歌手からデスメタルまで聴くのだという。地球の反対側で育ったダコタ・カイとも、音楽の好みがそっくりだと話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（12:55〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=775s"]]}, {"cat": "リングの話", "t": "リア・リプリーとのSNS動画", "b": "リア・リプリーとは仲が良く、SNS用の短い動画をよく一緒に撮ってきたという。いつも自分が撮りたいものを説明すると、リアが笑いながら付き合ってくれるそうだ。AJスタイルズとは「髪型が同じ」という冗談から一緒に撮るようになったと話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（14:34〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=874s"]]}, {"cat": "暮らし", "t": "ハロウィンは控室で仮装", "b": "アレクサ・ブリスの娘が職場に来る日に、みんなで仮装したことがあるという。本当は海外ドラマの登場人物の全身青塗りをするつもりだったが、衣装が間に合わず、クローゼットにあった服でリア・リプリーに扮したそうだ。控室全員でマイケル・コールの仮装をしたこともあると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（16:56〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1016s"]]}, {"cat": "リングの話", "t": "夢はマネージャー", "b": "試合をしたいとは思わないが、もっと物語に関わりたい気持ちはあり、10年ほど前からマネージャーをやってみたいと話しているという。インディー時代に、ある選手の最後の試合で付き人役を務めたこともあるそうだ。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（20:49〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1249s"]]}, {"cat": "リングの話", "t": "ポール・ヘイマンの隣で学ぶ", "b": "毎週、出番がないときは舞台袖でポール・ヘイマンの隣に座っているという。前髪を切ったら「目が見えない、感情は目で伝えるものだ」と言われたこともあるそうだ。ドキュメンタリーを見ては、昔の団体の話を本人に質問していると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（21:35〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1295s"]]}, {"cat": "リングに来るまで", "t": "恋愛番組の仕事でプロレスにはまる", "b": "プロレスを見始めたのは2012〜13年ごろだという。ロサンゼルスに移って恋愛リアリティ番組の関連番組の仕事をしていたところ、同じ月曜夜に放送していたRAWを番組仲間と見るようになり、すっかりはまったそうだ。好きな選手はAJリーとバティスタだと話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（24:02〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1442s"]]}, {"cat": "リングに来るまで", "t": "とても内気だった学生時代", "b": "中学・高校のころはとても内気で、友だちは1人くらいだったという。クラス中に笑われた記憶もあると話す。大学に行ってから変わり始め、今も1年前の自分が分からないほど変わり続けていたいそうだ。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（25:35〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1535s"]]}, {"cat": "好きなもの", "t": "本と雑学が好き", "b": "心理学や雑学など、興味を持ったテーマを深く調べるのが好きだという。ふだんは2週間に1冊ほど本を読み、長い移動や家で充電するときの過ごし方になっているそうだ。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（28:04〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1684s"]]}, {"cat": "リングの話", "t": "デビューの日は緊張で…", "b": "WWEデビューの日はとても緊張していて、考えすぎてしまったという。自分に一番厳しいので、あの日はうまくできなかったと思っているそうだ。今は自分の役割に自信が持てるようになり、RAWもSmackDownも毎週全部見ていると話す。", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-dbQf9CGCANM", "src": [["番組のYouTube（29:43〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=1783s"]]}]);
  if (PROFILES["Joe Tessitore"]) PROFILES["Joe Tessitore"].facts.push({"cat": "暮らし", "t": "キャシーの番組を聴きながら電話", "b": "テシトーレは、キャシーが自分のことを話しているポッドキャストを聴きながら電話をかけてきたことがあるほどの勉強家で、フットボールの準備をしながらプロレスのことも何でも知っていると、キャシー・ケリーが話している", "sp": "キャシー・ケリー", "d": "2026-06-09", "how": "クリス・ヴァン・ヴリートの番組で、キャシー・ケリーの話（字幕を全文確認）", "src": [["番組のYouTube（7:09〜）", "https://www.youtube.com/watch?v=dbQf9CGCANM&t=429s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-dbQf9CGCANM", d: "2026-06-09", show: "ext", who: ["Cathy Kelley"], t: "キャシー・ケリーの回　控室インタビューの舞台裏と素顔", lead: "クリス・ヴァン・ヴリートの番組に出た約68分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Cathy Kelley"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-dbQf9CGCANM").map((x) => [x.t, x.b, x.sp])), open: ["後半（34分以降）の話は今回は読んでいない。", "スポンサーの宣伝部分は省いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=dbQf9CGCANM"]] });
  if (!ROSTER.find((r) => r[1] === "Angel")) ROSTER.push(["アンヘル", "Angel", "lg", "元クルーザー級王者", "", "", ""]);
  if (!PROFILES["Angel"]) PROFILES["Angel"] = { lead: "メキシコのルチャ一家に生まれ、テレビの人気者から仮面を脱いで世界へ渡った人。二人の娘の父として、家族との時間を何より大切にしているという。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Angel"]], moves: [], facts: [] };
  if (PROFILES["Angel"]._weak) { PROFILES["Angel"].lead = "メキシコのルチャ一家に生まれ、テレビの人気者から仮面を脱いで世界へ渡った人。二人の娘の父として、家族との時間を何より大切にしているという。"; delete PROFILES["Angel"]._weak; }
  PROFILES["Angel"].facts.push(...[{"cat": "家族", "t": "祖父も叔父も覆面レスラーの一家", "b": "母方の祖父は一家の頭であるウンベルト・ガルサで、母はその娘にあたるという。叔父にはエクトル・ガルサとウンベルト・ガルサがおり、祖母の兄である「ニンジャ」ことマリオ・セグラは一家の師匠のような存在だったそうだ。いとこにあたる選手が、いまは同じ団体にいるとアンヘルは話す。顔立ちが叔父たちに似ているため、よく息子と間違えられるという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（0:45〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=45s"]]}, {"cat": "家族", "t": "商売上手な父と、殴り合いの母方", "b": "父はルチャとは無縁の商売人で、昔は車の売買もしていたそうだ。アンヘルは自分の商才は父から、体を張る強さは母方の血から来たと話す。子どもの頃から「1台買って1台半の値で売る」遊びをしていたという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（3:12〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=192s"]]}, {"cat": "リングに来るまで", "t": "10歳で練習を始め、16歳でデビュー", "b": "幼い頃から運動が好きで、叔父たちがテレビの中のヒーローに見えたという。最初の練習は9〜10歳、いったん離れて12歳ごろ戻り、16歳でデビューしたそうだ。学校では試験を「戦略的に」乗り切っていたと、笑いながら話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（4:04〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=244s"]]}, {"cat": "家族", "t": "傷の手当ては、いつも母の仕事", "b": "母は兄弟たちとルチャの世界で育ったため、息子が傷だらけで帰ってきても動じなかったという。「ボコボコで帰ったら家でもう一度やられる」と言われたそうだ。体に残る傷あとは、ほとんど母が手当てしたものだとアンヘルは笑って話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（6:34〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=394s"]]}, {"cat": "リングに来るまで", "t": "デビュー戦は、滑るリングで大失敗", "b": "デビューの日、リングのマットが滑りやすいビニール製に替えられていて、緊張もあって準備した動きがまともにできなかったという。控室でカバンを投げて「もうやらない」と言い、叔父に引き止められたそうだ。祖父とも話し合い、続けることにしたと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（8:11〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=491s"]]}, {"cat": "リングに来るまで", "t": "テレビに出て、名前が一気に広まる", "b": "覆面のまま地元の大手テレビ局の番組に出るようになり、名前が全国に広がったという。叔父たちはルチャ一筋の人たちで、芸能の世界に入ることに戸惑いもあったそうだ。ただ客席が埋まるのを見て、周りも次第に認めてくれたとアンヘルは話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（9:54〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=594s"]]}, {"cat": "リングに来るまで", "t": "出演料は月5000ペソ、だから自分で稼いだ", "b": "テレビ局の出演料は月5000ペソほどで、手取りは3000ペソ前後。ガソリン代にもならないと感じたそうだ。そこで知名度を使ってルチャの出演料を引き上げ、仲間を何人も連れていく「パック」としてプロモーターに売り込んだという。母の車に仲間を乗せて地方へ回ったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（17:13〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=1033s"]]}, {"cat": "リングに来るまで", "t": "いちばん安いギャラは、小銭の17ペソ", "b": "駆け出しの頃のいちばん安いギャラは、小銭で17ペソほどだったそうだ。叔父が興行の売上を持っていったあとの残りだったという。当時は親と同居で家族もなく、楽しいから続けられたと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（24:43〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=1483s"]]}, {"cat": "リングに来るまで", "t": "大学で理学療法を学び、中退する", "b": "大学では理学療法とリハビリを学んだそうだ。祖父がマッサージや治療で有名だったため、さらに術後のリハビリまで扱える専門家になりたかったという。ただテレビの仕事が増え、同じ敷地の高校生にも囲まれて授業に集中できず、4学期目で辞めたと話す。のちにオンラインで再挑戦したが、これも続かなかったそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（28:45〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=1725s"]]}, {"cat": "リングに来るまで", "t": "テレビ番組で、覆面を脱ぐ決断", "b": "番組の企画で、覆面レスラーとして初めてテレビで素顔を完全に見せることになったという。家族に反対されるのが怖く、祖父や叔父たちと話し合ったそうだ。祖父は「顔を知ってもらいたいなら、これ以上の場はない」と背中を押してくれたと話す。約束された報酬は半分ほどしか出なかったが、後悔はないという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（31:05〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=1865s"]]}, {"cat": "リングに来るまで", "t": "批判は、気にしないことにした", "b": "素顔を出したあと、同業者から「ルチャを汚した」と強く批判され、控室でもめたこともあったという。アンヘルは「あの機会が来たら誰でもつかむ」と言い返してきたそうだ。のちに批判した人たちがSNSで踊っているのを見て、時間が正しさを示したと感じたと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（35:08〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=2108s"]]}, {"cat": "リングに来るまで", "t": "バラエティの仲間たちと、体を張った笑い", "b": "テレビ局時代は、シンボルやネウロシスなど仲間と一緒に、ケーキを投げ合ったり服を破り合ったりする番組を作っていたという。仲間たちが得意な役をそれぞれ持ち、アンヘルは踊りで魅せる役だったそうだ。一番大きな会場は、約6万人の闘牛場だったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（41:43〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=2503s"]]}, {"cat": "リングに来るまで", "t": "「ガルサ・ジュニア」で大手団体へ", "b": "その後メキシコの大手団体に入り、「ニンジャの息子」ではなく叔父たちの名を継ぐ形で「ガルサ・ジュニア」を名乗ることになったという。ただ試合が北部ばかりで、全国で名を売りたいアンヘルは会社と対立し、1年ほどで離れて独立系になったそうだ。独立したほうが収入は良かったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（47:59〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=2879s"]]}, {"cat": "家族", "t": "病に倒れた叔父を、9か月で見送る", "b": "叔父は病気が見つかってから約9か月で亡くなり、体重も120〜130キロから50キロほどまで落ちたという。知らせを受けたのは移動のバスの中で、運転手に代わってアクセルを踏みたいほどだったそうだ。その後に祖母、祖父も亡くなり、一家はしばらく不安定になったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（54:36〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=3276s"]]}, {"cat": "リングに来るまで", "t": "WWEの入団テストは、実に4年越し", "b": "最初の連絡はいとこと一緒に受けるテストの誘いで、「若すぎるので来年」と断られたという。翌年はフロリダの施設で数日間吐くほど鍛えられたが、また見送られたそうだ。結局、入団まで4年半かかり、その間は誰にも話せなかったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（57:05〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=3425s"]]}, {"cat": "体のこと", "t": "肩の手術と、契約のお預け", "b": "他団体の契約中に肩の手術を受け、その後WWEの診察を受けた2018年には「半年後に再検査」と言われたそうだ。灸や吸い玉、ストレッチで泣きながらリハビリを続け、半年後には可動域が8割ほど戻ったという。肩については自己責任という条件の契約書に署名したと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（59:35〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=3575s"]]}, {"cat": "暮らし", "t": "英語は嫌いだったが、いまは勉強中", "b": "両親のおかげで小さい頃からバイリンガルの学校に通っていたが、英語は好きではなかったという。アメリカへ渡ってからも英語のレッスンや発音の練習を続けていると話す。大企業のアプリでの予定管理や送迎の仕組みに驚いたそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:04:26〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=3866s"]]}, {"cat": "リングの話", "t": "ビンス・マクマホンとの面談", "b": "面談では、なぜその衣装か、なぜその役か、とすべて理由を問われたという。自分でそのキャラを本当に信じているかを見ていたのだと、あとで知ったそうだ。入る前から圧倒される人だったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:13:22〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=4402s"]]}, {"cat": "リングの話", "t": "RAWデビュー戦と、英語の長いマイク", "b": "RAWでのデビューは、いとことの対決の流れでレイ・ミステリオと戦う形だったという。直前に、ほぼ英語の長いマイクを覚えるよう言われて徹夜したが、当日になって内容が何度も差し替えられたそうだ。最後は「流れに任せろ」と言われて即興でやり切った。あとでこれは新人への洗礼だったと知ったと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:16:32〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=4592s"]]}, {"cat": "リングの話", "t": "出番を待つのも、仕事のうち", "b": "アメリカの団体は、シーズンごとに出番が回ってくるため、しばらく出られない時期もあるという。それでも給料は出ているので、気持ちを切らさず、チャンスが来たらそれを生かせるよう準備しておくのが大事だとアンヘルは話す。入団して約8年、その間に600人以上が解雇されるのを見てきたそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:27:42〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=5262s"]]}, {"cat": "家族", "t": "体を休めて、娘たちの成長を見届ける", "b": "アメリカの団体では試合が週1回ほどで、国内を毎日回っていた頃より体が楽になったという。ひとつ痛い技を受けるごとに現役が短くなると考えていて、40歳で引退するつもりが50歳まで延ばせるかもしれないとアンヘルは話す。空いた時間で、二人の娘の初めての食事や初めてのハイハイ、初めての歩行も見られたそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:30:01〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=5401s"]]}, {"cat": "家族", "t": "娘がレスラー志望なら、止めたい", "b": "二人の娘がレスラーになりたいと言ったら、この世界の厳しさを知っているので反対すると話す。誰にも頼らず生きられる力、人と付き合う力、なんでも自分でやれる力を身につけさせたいそうだ。父の稼ぎを当てにせず、自分で道を切り開いてほしいという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:33:57〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=5637s"]]}, {"cat": "リングの話", "t": "王座を獲った試合で、リング上で婚約", "b": "クルーザー級王座を獲った試合のあと、リングの上で恋人に婚約指輪を渡したという。裏で内緒にしようとしたが、トリプルHに「人生の節目なら大きくやれ」と背中を押されたそうだ。いまでもファンが覚えている場面だと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:36:25〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=5785s"]]}, {"cat": "リングの話", "t": "いちばん痛かった技は、ビッグ・ショー", "b": "一番強く打ってきたのはビッグ・ショーで、胸骨が背骨につくほどだったという。メキシコ時代の対戦では、ラヨ・デ・ハリスコ・ジュニアの一撃で星が飛んだそうだ。レイ・フェニックスの指は、刃物で切られるように焼けて痛いと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:41:57〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=6117s"]]}, {"cat": "リングの話", "t": "アンダーテイカーは最大の師匠", "b": "アンダーテイカーとは長い会話をしたことがあり、業界で最大の師匠のような存在だと話す。写真をお願いしたのは、ザ・ロックとアンダーテイカーの二人だけだという。ほかの選手とは、一緒に試合をして撮った写真のほうが価値があると考えているそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:43:36〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=6216s"]]}, {"cat": "リングの話", "t": "夢の相手は、亡き祖父", "b": "もしも誰とでも戦えるなら、祖父との一騎打ちを選ぶと話す。叔父たちとは試合ができたが、祖父はリングの下から技を教えてくれるだけで、一緒には上がれなかったそうだ。闘牛場のような昔ながらの会場でやってみたいという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:48:31〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=6511s"]]}, {"cat": "リングの話", "t": "ランディ・オートンとのRAWでの一件", "b": "コロナ期の無観客のRAWで、場を盛り上げようとふざけているうちに、オートンにコーナーのポストへ押しつけられたことがあるという。試合の途中で本気を見せるよう促された形で、そのあとはむしろ関係がよくなったそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:51:38〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=6698s"]]}, {"cat": "暮らし", "t": "スマホは、使い方次第で職を奪う", "b": "団体の研修で、怒っているときは書いても投稿せず、頭を冷やしてから読み直すよう教わったという。アンヘルは、スマホは仕事を奪うことも家族を壊すこともある強力な道具だと話す。見返せば、投稿しなくてよかったと思うことがほとんどだそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（1:56:30〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=6990s"]]}, {"cat": "好きなもの", "t": "好物はラザニアとスイス風エンチラーダ", "b": "子どもの頃の好物はラザニアと、スイス風エンチラーダだったそうだ。ラザニアは挽き肉とチーズ、トマトソースにマッシュルームを入れ、紫玉ねぎを加えるのが好みだと話す。ほうれん草は入れない派だという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（2:19:23〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=8363s"]]}, {"cat": "好きなもの", "t": "こだわりの「完璧なタコス」", "b": "大きな小麦粉のトルティーヤに、チーズの皮を焼きつけ、牛タン、リブアイのチチャロン、焼き玉ねぎ、マッシュルームを重ねるという。アボカドと緑のソースをのせ、仕上げに焼いたソーセージを入れるのが理想だと話す。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で（字幕を全文確認）", "art": "ext-s_VqNJxtzcU", "src": [["番組のYouTube（2:20:09〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=8409s"]]}]);
  if (PROFILES["Humberto Garza"]) PROFILES["Humberto Garza"].facts.push({"cat": "暮らし", "t": "祖父は、背中を押す言葉をくれた", "b": "覆面を脱ぐかどうか迷ったとき、祖父は「顔を知ってもらいたいなら、これ以上の場はない」と励ましたと、アンヘルが話している。祖父は若い頃、道化師などいろいろな仕事をしてきた人でもあるという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で、アンヘルの話（字幕を全文確認）", "src": [["番組のYouTube（33:31〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=2011s"]], "by": "第三者の話"});
  if (PROFILES["Hector Garza"]) PROFILES["Hector Garza"].facts.push({"cat": "暮らし", "t": "お金に無頓着で、頼まれると断れなかった", "b": "叔父のエクトルは「お金はない」と言われるとすぐ値引きに応じる優しい人だったので、興行主がそれに甘えることもあったと、アンヘルが話している。そのせいで「叔父さんはこうだった」と比べられ、苦労したそうだ。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で、アンヘルの話（字幕を全文確認）", "src": [["番組のYouTube（50:32〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=3032s"]], "by": "第三者の話"});
  if (PROFILES["Vince McMahon"]) PROFILES["Vince McMahon"].facts.push({"cat": "暮らし", "t": "部屋に入る前から圧倒される人", "b": "ビンス・マクマホンは、部屋に入っただけで足がすくむほどの存在感があり、これまで会った中で最も強烈な人だったと、アンヘルが話している。提案するキャラクターには、すべてに理由が求められたという。", "sp": "アンヘル", "d": "2026-06-15", "how": "ロス・パリェーロス・マモネスの番組で、アンヘルの話（字幕を全文確認）", "src": [["番組のYouTube（1:14:09〜）", "https://www.youtube.com/watch?v=s_VqNJxtzcU&t=4449s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-s_VqNJxtzcU", d: "2026-06-15", show: "ext", who: ["Angel"], t: "アンヘルの回　ルチャ一家の血と、仮面を脱いだ日", lead: "ロス・パリェーロス・マモネスの番組に出た約142分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Angel"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-s_VqNJxtzcU").map((x) => [x.t, x.b, x.sp])), open: ["番組後半のレスラー評や技ランキングの企画は載せていない。", "自動字幕で固有名詞が崩れている箇所（一部の団体名や選手名）は、確信が持てないため書いていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=s_VqNJxtzcU"]] });
  PROFILES["Michin"].facts.push(...[{"cat": "リングの話", "t": "ディーバ時代を見て育った少女時代", "b": "ミチンは2009〜10年ごろにデビューし、その時代に入れてよかったと話す。子どものころ見ていたのは「ディーバ」の時代で、恋愛の三角関係や下着姿の試合が見せ場になりがちだったという。男の子と外で遊ぶ方が好きなおてんば娘だったので、憧れたのはアクションとストーリーのほうだったそうだ。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（9:04〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=544s"]]}, {"cat": "リングの話", "t": "「女子レスラー」でなく「レスラー」として", "b": "インディー時代は、ハードコアや男女混合の試合を多くこなしたとミチンは話す。特別扱いなしで、男子と同じように見られたかったという。練習も男子に混ざって受け、最初の約3カ月は耐えられるかを試すしごきやいじめのような洗礼があったそうだ。ただ、育った環境のおかげで怖くはなかったと語る。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（10:46〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=646s"]]}, {"cat": "リングの話", "t": "全部のポジションを覚える「何でも屋」", "b": "バレーボールでは、アウトサイドヒッターを軸にしつつ、ミドルやリベロなど全ポジションを覚えたとミチンは話す。誰かがけがをしても代わりに入れるようにするためだという。この考え方をレスリングにも持ち込み、日本のスタイル、ルチャ、イギリスのスタイルまで何でも学びたかったそうだ。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（50:29〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=3029s"]]}, {"cat": "リングの話", "t": "メールとテープを送り続けた下積み", "b": "ミチンが始めたころはSNSが盛んでなく、練習したい相手にはメールで頼み、映像は大きな封筒にテープを入れて送ったという。女子団体の入団審査や有名道場の学校にも、そうして応募していたそうだ。今の「バズる一瞬のための技」には腹が立つと話し、地道に積み重ねたからこそ成功が甘くなると語る。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（52:05〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=3125s"]]}, {"cat": "リングの話", "t": "シェルトン・ベンジャミンの助言", "b": "ミチンは2010〜11年ごろ、メリーランドの興行でシェルトン・ベンジャミンと出会い、鶏の手羽先を取り合ったのが始まりだという。彼はミッキー・ジェームスとの試合を見て、名声ではなく好きでやっていると見抜いたそうだ。その後は、30歳を過ぎても続けるための長持ちする体の使い方と試合の組み立て方を教えてくれたと話す。今では自分も同じことを後輩に伝えているという。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:24:10〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=5050s"]]}, {"cat": "リングの話", "t": "「自分にレッスルマニアはない」と思っていた", "b": "ミチンは、これまで何度かレッスルマニアの週が自分の誕生日と重なっていたが、出番がある可能性が出たのは今回が初めてだと話す。一時は「自分のレッスルマニアの瞬間は来ないかもしれないが、夢の中にいるからそれでいい」と思っていたという。話は急に決まり、ジェイ・ウーソの入場に絡むだけでも想像以上のことだったそうだ。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:37:17〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=5837s"]]}, {"cat": "リングの話", "t": "念願のヒールになり、ジェイド・カーギルらと組む", "b": "けがから戻った直後に、B-ファブと一緒にジェイド・カーギルのチームに加わると告げられたとミチンは話す。ずっとなりたかったヒールは、ずっと楽しいという。自分に向けて悪い願いを書く小さなファンがいると聞き、会えば最高にやさしくなると笑っている。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:38:50〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=5930s"]]}, {"cat": "リングの話", "t": "三人とも服装はバラバラのまま", "b": "ジェイド・カーギルはきらびやかなステージ衣装、B-ファブは太ももまでのブーツ、自分はだぼだぼのパンツにクロップトップとスニーカーで、とミチンは話す。周りには同じ服装にそろえてほしいという声もあったが、「個性がそのままで合う」とスパイス・ガールズにたとえて主張したそうだ。ジェイドの高級志向をまねして水はいつも水道水だと笑う場面もあった。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:39:41〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=5981s"]]}, {"cat": "リングの話", "t": "ウィッグを外して、自分らしいスタイルへ", "b": "NXT時代は自分らしさを最大まで盛りすぎて、作り物に見えてしまったとミチンは振り返る。いまはウィッグも青い髪もやめて、好きな服で気楽に出られるという。TNA時代はスカートと「ドールハウス」風のかわいくセクシーな装いで、着ぐるみで戦っている気分だったそうだ。技の最中に下から写真を撮られた経験があり、それ以来、露出の多い衣装を避けているという。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:40:27〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=6027s"]]}, {"cat": "リングの話", "t": "ジミーへのビンタはステファニーを思い浮かべて", "b": "ミチンは、ステファニー・マクマホンのビンタをいつか受けたいと話している。ジミー・ウーソに放った平手打ちも、彼女を思い浮かべて打ったものだったという。マイケル・ヘイズから「ミスするな」と言われたが、頭の中のステファニーを呼び出したと笑う。", "sp": "ミチン", "d": "2026-06-18", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-michin", "src": [["番組のYouTube（1:43:36〜）", "https://www.youtube.com/watch?v=82DjWniHN0k&t=6216s"]]}]);
