  if (!ROSTER.find((r) => r[1] === "Diamond Dallas Page")) ROSTER.push(["ダイヤモンド・ダラス・ペイジ", "Diamond Dallas Page", "lg", "世界王者の元ヨガ指導者", "", "", ""]);
  if (!PROFILES["Diamond Dallas Page"]) PROFILES["Diamond Dallas Page"] = { lead: "遅咲きから世界王者に上りつめ、いまは傷ついた仲間を立て直す活動に打ち込むDDP。呼吸と前向きさを武器に、人を信じて支え続けている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Diamond%20Dallas%20Page"]], moves: [], facts: [] };
  if (PROFILES["Diamond Dallas Page"]._weak) { PROFILES["Diamond Dallas Page"].lead = "遅咲きから世界王者に上りつめ、いまは傷ついた仲間を立て直す活動に打ち込むDDP。呼吸と前向きさを武器に、人を信じて支え続けている。"; delete PROFILES["Diamond Dallas Page"]._weak; }
  PROFILES["Diamond Dallas Page"].facts.push(...[{"cat": "暮らし", "t": "希望を届けるヨガとスタジオ", "b": "コンバック・スタジオとDDPヨガで、自信をなくした人に希望を与えたいと話す。90日間毎日取り組むプログラムでは、本人が見守って背中を押すそうだ。参加者が互いに励まし合う場もでき、利用者は7万8千人に及ぶという。毎週、投稿された体験談を取り上げて称えているとのこと。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（8:58〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=538s"]]}, {"cat": "暮らし", "t": "誇れる5つのこと", "b": "自分が心から誇れるものとして、妻ペイジと娘たち、3度の世界王座、殿堂入り、ジェイク・ロバーツの再起、そしてDDPヨガを挙げている。ヨガは友人の発案で、少人数が励まし合う場から始まったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（9:45〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=585s"]]}, {"cat": "体のこと", "t": "5秒で吸って5秒で吐く呼吸法", "b": "不安やストレスを感じたら、5秒吸って5秒吐く深呼吸をすすめている。神経に働いてストレスのホルモンを抑え、体がゆるむと説明する。恐れと興奮の違いは、息をしているかどうかだけだとも話す。この呼吸の話は、のちにコーディの考え方にも影響したそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（12:58〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=778s"]]}, {"cat": "リングの話", "t": "エディ・ゲレロの献身で得た勝利", "b": "1996年のハロウィーン・ハボックで、エディ・ゲレロに勝った試合を振り返る。エディは肋骨を痛めて息をするのも苦しいはずなのに、最後まで続けて「ダイヤモンド・カッター」を促したという。勝ち自体は上層部に重く見られなかったが、本人にとっては大きな意味があったそうだ。エディのことは、とにかく最高にかっこいい人だったと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（18:34〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1114s"]]}, {"cat": "リングの話", "t": "nWO加入を断る筋書きを提案", "b": "nWOの二人に、自分が一度は加入の誘いを断る筋書きを持ちかけたと話す。二度断ったあと、三度目に仲間になるふりをして裏切るという流れだ。相手との深い信頼がなければ頼めない話だったという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（19:22〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1162s"]]}, {"cat": "リングの話", "t": "スコット・ホールが忘れなかった恩", "b": "かつて自分がスコット・ホールの見た目づくりを手伝った思い出が、この計画を後押ししたと話す。つまようじをくわえる仕草の発案にもからんでいたそうだ。ケビン・ナッシュに「彼は覚えている」と言われ、スコットに話すと快く賛成してくれたという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（21:04〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1264s"]]}, {"cat": "リングの話", "t": "時間を削られた夜に「息をしろ」", "b": "nWOを裏切る夜、番組の進行で試合の持ち時間がどんどん削られ、動揺したという。そのとき、ケビン・ナッシュに「いつも言う通り、息をしろ」と声をかけられて落ち着いたそうだ。生放送だから慌てなくていいと言われ、最後までやり切ったと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（27:04〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1624s"]]}, {"cat": "リングの話", "t": "マッチョマンが技を受けた夜", "b": "スプリング・ストンピードの前夜、マッチョマン・ランディ・サベージが自分から「ダイヤモンド・カッターを受けたい」と言ってくれたという。普段は負けて倒れるだけだった自分に、大きな機会が巡ってきた瞬間だったそうだ。試合では相手が全部を受け止めて、自分を引き立ててくれたと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（28:00〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1680s"]]}, {"cat": "リングの話", "t": "3カウントを聞いた静かな瞬間", "b": "技を決めたあと、本当にカウントが入るのか分からないまま腕を乗せたという。3つ目が入ると会場が大きく沸いたが、二人だけ静けさの中にいるようだったそうだ。上を見たサベージが「次のスプリング・ストンピードも決まりだな」とつぶやいたと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（29:35〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1775s"]]}, {"cat": "体のこと", "t": "失読症とADDを乗り越えた", "b": "ADDと失読症があり、30歳のころは小学3年生ほどの読み書きだったと話す。LAのサーフィン中の事故で出会った友人の紹介で、学習センターに通い始めた。そこで集中力がつき、今は小学6年生レベルまで読めるようになったそうだ。それを前向きに受け止めているという。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（32:47〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=1967s"]]}, {"cat": "暮らし", "t": "目標を立てて自信をつけてきた", "b": "昔から前向きだったのは、目標を決めて実現してきたからだと話す。グラスは半分入っていると考えるタイプで、世の中にはグラスすら持たない人もいると笑う。さらに前向きさを磨いたのが、ダスティ・ローデスの姿だったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（33:37〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2017s"]]}, {"cat": "リングの話", "t": "裏切られても前向きだったダスティ", "b": "舞台裏で、ダスティ・ローデスが何人もの人に陥れられるのを見てきたという。それでも本人は「顔に出すな、前向きでいろ」と励ましてくれたそうだ。息をしながら乗り切る姿が、自分にとって手本になったと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（34:26〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2066s"]]}, {"cat": "リングに来るまで", "t": "ダスティの一言で5年以内に王者へ", "b": "1994年の終わり、38歳のころ。上に上がれない不満を漏らしていたとき、ダスティから「自分が信じないで誰が信じる」と叱られたという。自分は世界王者にはなれないと口にした直後だった。そこで「5年以内に世界王者になる」とメモに書き、4年4か月14日後の1999年4月に本当に王者になったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（35:12〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2112s"]]}, {"cat": "体のこと", "t": "愛用の「パワーカフ」", "b": "自分で使っているトレーニング用具「パワーカフ」が、確かに効くと話す。ステージ前の気合い入れにも役立つようだ。コーディに使わせたところ、途中で疲れ果てて諦めたという場面もあったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（49:38〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2978s"]]}, {"cat": "暮らし", "t": "ヨーロッパ巡りの予定", "b": "ドイツでの質疑応答会と、DDPヨガの講習会を予定しているという。そのあとスコットランド、マンチェスター、ロンドンを巡り、ヨガの講習会やファンとの交流の場を開くそうだ。講習会では、来た人とまず握手や写真から始める流儀だと話す。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（1:05:37〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=3937s"]]}, {"cat": "家族", "t": "妻ペイジは山登りが得意", "b": "妻のペイジは、イタリアのドロミーティで山登りをしてから、ドイツでの催しに合流する予定だと話す。そのあとアルプスで数日過ごし、さらに山を登る計画もあるという。ヨーロッパを回る旅にも、夫婦で一緒に出かけるそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（1:06:25〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=3985s"]]}, {"cat": "好きなもの", "t": "理想の夢のチームを選ぶと", "b": "「夢のチーム」には、ダスティ・ローデス、スーパースター・ビリー・グラハム、ハンサム・ジミー・バリアント、ケビン・ナッシュ、スコット・ホールを挙げている。最後に、コーディも加えて笑いで締めくくったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（1:09:03〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=4143s"]]}]);
  if (PROFILES["Marc Mero"]) PROFILES["Marc Mero"].facts.push({"cat": "暮らし", "t": "マーク・メロが背負った使命", "b": "元仲間のマーク・メロは、団体の保証契約を最初に結んだ人で、批判も受けたが、ダラスは今も優しい人だと思っていると、ダイヤモンド・ダラス・ペイジが話している。メロは学校で子どもたちに語る活動を使命にしていて、その映像が広まり、依頼が殺到したそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で、ダイヤモンド・ダラス・ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（4:01〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=241s"]], "by": "第三者の話"});
  if (PROFILES["Jake Roberts"]) PROFILES["Jake Roberts"].facts.push({"cat": "暮らし", "t": "ジェイク・ロバーツの再起", "b": "ジェイク・ロバーツの再起を手伝った経緯を、ダイヤモンド・ダラス・ペイジが話している。お酒をいきなりやめるのは難しいので、仕事の前に少しずつ減らす方法を教わったという。本人が準備を整えたことが、再起につながったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で、ダイヤモンド・ダラス・ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（59:58〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=3598s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "ダスティが諦めたチーズケーキ", "b": "ダスティ・ローデスに一緒に体を整えようと持ちかけたところ、翌日「冷蔵庫のチーズケーキを全部食べてしまった」と電話があったという話を、ダイヤモンド・ダラス・ペイジが笑いながらしている。いかにもダスティらしい終わり方だったそうだ。", "sp": "ダイヤモンド・ダラス・ペイジ", "d": "2026-06-18", "how": "コーディの番組で、ダイヤモンド・ダラス・ペイジの話（公式字幕を全文確認）", "src": [["公式YouTube（59:58〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=3598s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "家族", "t": "葉巻の煙が漂った幼い日の家", "b": "ジョージア州マリエッタの実家で、居間に葉巻の煙が満ちていた記憶が最初の思い出のひとつだという。父がソファに座り、毛皮のコートとサングラス姿のダラスが葉巻をくゆらせていたそうだ。幼いコーディにとっては、それが普通の光景だったと話す。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（2:27〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=147s"]]}, {"cat": "暮らし", "t": "悲観的な性格だと認める", "b": "自分はとても悲観的で、ダラスとは正反対の性格だと話す。ダラスから教わった「嫌な話を聞いたときは息をしろ」という助言が役に立っているそうだ。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（11:20〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=680s"]]}, {"cat": "暮らし", "t": "部屋では最後に口を開く", "b": "打ち合わせでは、あえてとぼけて、最後に意見を言うのを好むという。息をして間をとれば、反射ではなく本音で答えられるそうだ。声の大きな人より、考え抜いた人に従うべきだとも話す。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（12:11〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=731s"]]}, {"cat": "家族", "t": "父の話を自分で記録に残す", "b": "父が人に裏切られ、責任を押しつけられたのを見てきたため、何でも記録に残すようにしているという。自分の物語を他人に書き換えさせたくないからだそうだ。この番組を気に入っているのも、事実を残せるからだと話す。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（40:02〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2402s"]]}, {"cat": "家族", "t": "妹テイルは記憶力が鋭い", "b": "妹のテイルとはとても仲が良く、父の因縁を忘れない性格だという。コーディが穏やかに対応するのに対し、テイルは容赦しないそうだ。父が受けた仕打ちを、今も覚えているらしい。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（40:53〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2453s"]]}, {"cat": "リングに来るまで", "t": "演技スタジオで学んだ12か月", "b": "ダラスの紹介で、ハワード・ファイン演技スタジオに12か月通ったという。そこで得たものが年々大きく思えると話す。先生とは今も、ときどき電話で近況を話す仲だそうだ。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（44:04〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2644s"]]}, {"cat": "体のこと", "t": "カイロプラクターのとうもろこし検査", "b": "体の不調を知るダラスに連れられて、カイロプラクターを訪ねたことがあるという。「とうもろこしが合わない」と言われ、小瓶を体にかざして手を握る検査を受けたが、何も変化はなかったそうだ。帰ってから笑い話として周りに伝えたという。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（48:05〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=2885s"]]}, {"cat": "家族", "t": "大舞台に家族が集まる習慣", "b": "年に一度の大舞台の時期は、家族が集まって大きな夕食を囲むのが恒例だという。そのために、いい位置で出場したいと思うようになったそうだ。当日はバスの中で、ダラスにコーヒーを入れるやり取りもあったと話す。", "sp": "コーディ・ローデス", "d": "2026-06-18", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-rNe-hqtNhVo", "src": [["公式YouTube（52:09〜）", "https://www.youtube.com/watch?v=rNe-hqtNhVo&t=3129s"]]}]);
  ARTICLES.push({ id: "wdywta-rNe-hqtNhVo", d: "2026-06-18", show: "wdywta", who: ["Diamond Dallas Page", "Cody Rhodes"], t: "ダイヤモンド・ダラス・ペイジの回　呼吸、前向きさ、nWOの裏話", lead: "コーディ・ローデスの番組に出た約70分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Diamond Dallas Page", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-rNe-hqtNhVo").map((x) => [x.t, x.b, x.sp])), open: ["ほかの出演者の私生活（雑誌撮影をめぐる話）や健康法をめぐる冗談は、載せていない。", "字幕に話者名がないため、nWO前後の筋書きの一部は、文脈から判断して載せた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=rNe-hqtNhVo"]] });
  if (!ROSTER.find((r) => r[1] === "Jade Cargill")) ROSTER.push(["ジェイド・カーギル", "Jade Cargill", "lg", "現役の女子スター", "", "", ""]);
  if (!PROFILES["Jade Cargill"]) PROFILES["Jade Cargill"] = { lead: "ウィッグが外れた試合も、額を切った流血も、笑い飛ばして自分の強さに変える。夫や憧れの選手への思いものぞく、素顔たっぷりの回。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Jade%20Cargill"]], moves: [], facts: [] };
  if (PROFILES["Jade Cargill"]._weak) { PROFILES["Jade Cargill"].lead = "ウィッグが外れた試合も、額を切った流血も、笑い飛ばして自分の強さに変える。夫や憧れの選手への思いものぞく、素顔たっぷりの回。"; delete PROFILES["Jade Cargill"]._weak; }
  PROFILES["Jade Cargill"].facts.push(...[{"cat": "リングの話", "t": "自分は「嵐」だという自負", "b": "「私は嵐」という言葉を、周りの空気を自分で動かす存在という意味で使っているという。観客を立たせ、座らせ、何を言わせるかまで自分が決めるのが役目だと話す。行く先々で天気が変わるほどで、それが自分の超能力だと語っている。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（4:06〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=246s"]]}, {"cat": "リングの話", "t": "ティファニー・ストラットンとの相性", "b": "当時の対戦は5度目になるという。相手は身軽で空中技が得意、自分は力強さと運動能力で勝負するタイプで、二人だからできる試合があると話す。いつもと同じ気持ちで臨むだけで、US王座は最初から狙っていたものではなかったそうだ。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（4:53〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=293s"]]}, {"cat": "リングの話", "t": "試合中にウィッグが外れた日", "b": "4人が戦う試合で、コーナーの上でシャーロット・フレアーとやり合う最中にウィッグが外れたという。縫い付けていたのに、自分の髪の毛も一部抜けるほどの勢いだったと話す。ウィッグをつけていることは前から公言していて、隠すつもりはないという。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（6:30〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=390s"]]}, {"cat": "リングの話", "t": "長かった髪を短く切った", "b": "髪は肩よりずっと下まで伸びていたが、あえて切ったのだという。外れた日はキャップもかぶっていて、それが一緒に取れたおかげで坊主頭だと思われずに済んだと笑っている。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（8:46〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=526s"]]}, {"cat": "リングの話", "t": "審判の女性がすぐ駆け寄った", "b": "外れた直後、審判を務めていた女性が駆け寄ってきたという。同じ黒人女性として焦りをわかってくれて、「ついてる、ついてる」と声をかけてくれたそうだ。本人は何を言われたかも覚えておらず、ウィッグを押さえることで頭がいっぱいだったと話す。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（10:30〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=630s"]]}, {"cat": "リングの話", "t": "たった2分34秒が永遠に感じた", "b": "聞き手が計ったところ、外れていた時間は2分34秒だったという。本人には永遠に思えるほど長く、人生で一番恥ずかしかった瞬間だと話す。それでも自分は生きていて、短い髪でも長い髪でも最高だと笑い飛ばした。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=726s"]]}, {"cat": "リングの話", "t": "その場で外さなかった理由", "b": "共演者のジェイ・ウーソは「外して投げればよかった」と言ったという。でも頭の後ろに糸が残っていて外せなかったし、何より変なステレオタイプを演じたくなかったと話す。古い編み込みでよかった、新しければ別の意味で大変だったと冗談も飛ばしている。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（12:55〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=775s"]]}, {"cat": "リングの話", "t": "「失敗」と呼ばれることへの違和感", "b": "髪は自分のキャラクターの一部で、衣装や髪のトラブルは多くの女子選手が経験していると話す。それをすぐ「ミス」と呼ぶ風潮はおかしく、この出来事を文化を伝える機会にしたいという。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（14:34〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=874s"]]}, {"cat": "リングの話", "t": "嫌われても気にしない", "b": "自分は普通の人には身近に感じにくい存在だと自覚していて、それでいいと話す。弱みを打ち明けると逆手に取られるが、そこが悪役を強くするのだという。活動5年ほどでタイトルも獲ってきた実績が妬みを呼ぶのだろうと語っている。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（15:25〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=925s"]]}, {"cat": "体のこと", "t": "階段で額を切った夜", "b": "前から流血したいと思っていたら、その夜に願いがかなってしまったと笑う。階段は本来動く想定だったのに、その動きとは違う形でぶつかり、額を深く切ったそうだ。以前、日本で額を切ったときの経験があったので、最初はそれほど悪いと思わなかったという。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（17:47〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1067s"]]}, {"cat": "体のこと", "t": "客席の反応で傷の深さを知った", "b": "試合中、客席がどよめき、最前列の女性たちが顔をしかめたことで重傷だと気づいたという。周りが気づかう中でも、まだやることがあると続行したそうだ。控室ではトリプルHに形成外科へ行くよう言われ、見慣れているはずの彼の言葉で事の重大さを悟ったと話す。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（19:22〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1162s"]]}, {"cat": "体のこと", "t": "痛みに強く、ひと晩出血が続いた", "b": "鏡を見て驚いたものの、気持ちは落ち着いていたという。夫が離れていかなければいいと考えたほどで、心配は友人の40歳の誕生日に行けなくなることくらいだったそうだ。痛みには強い体質だが、形成外科医が不在でひと晩出血が続き、寝て起きると顔が血だらけだったと話す。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（20:07〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1207s"]]}, {"cat": "暮らし", "t": "傷あとは空港での話題に", "b": "形成外科の腕がよく、傷はほとんど目立たなくなったという。空港などで傷を聞かれ、階段にぶつかったと答えるとレスラーだと驚かれるのがお決まりだそうだ。腕にあざが多く、夫が誤解されないか冗談のネタにもなっていると話す。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（20:57〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1257s"]]}, {"cat": "リングの話", "t": "眉の傷は「キャラの一部」に", "b": "傷は3層の深さがあり、眉が曲がっていたので皮膚を切って整える処置を受けたという。縫った針数はわからず、眉の一部はなくなったそうだ。今はそこに少しだけ絵の具のような色を足して見せていて、前より魅力的になったと満足している。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（21:48〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1308s"]]}, {"cat": "家族", "t": "夫は元メジャーリーガーのブランドン・フィリップス", "b": "夫は元メジャーリーガーのブランドン・フィリップスだという。ホテルのエレベーターで1時間以上閉じ込められた話が話題になり、同乗していたのは本人の友人家族など約10人だったそうだ。夫は混雑が少し苦手だが落ち着いて対応した、とジェイドが話している。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（23:18〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1398s"]]}, {"cat": "家族", "t": "試合の日の夫との約束", "b": "試合当日は集中モードなので、緊急以外は電話しないでと夫に伝えてあるという。連絡は「愛してる」「頑張って」「子どもにキスを」くらいで十分で、夫もそれをよく理解していると話す。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（24:05〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1445s"]]}, {"cat": "リングの話", "t": "次はグランドスラムを狙う", "b": "US王座は最初の目標ではなかったが、取れるなら手に入れたいという。もう一つの王座もリア・リプリーが戻ったら狙うと話す。どんな王座でも自分が持つのが一番似合うと自信をのぞかせた。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（24:56〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1496s"]]}, {"cat": "好きなもの", "t": "夢のタッグ「5人の味方」", "b": "酒場で50人に嫌われても守ってもらうため、時代を問わず選ぶなら、ジャクリーン、チャイナ、ビアンカ・ブレア、サーシャ・バンクスだと答えている。サーシャは口が達者なだけでなく実力で裏づける人だから選んだという。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（26:38〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1598s"]]}, {"cat": "好きなもの", "t": "夢のメインイベントの相手", "b": "時間を戻せるなら対戦したい相手として、チャイナ、ジャクリーン、トリッシュ・ストラタス、ストーン・コールド、ブッカーTを挙げている。ストーン・コールドとブッカーTは憧れの存在で、まだ会えていないそうだ。リングに立つだけで特別な瞬間になるという。", "sp": "ジェイド・カーギル", "d": "2026-06-24", "how": "ザ・リッチ・アイゼン・ショーの番組で（字幕を全文確認）", "art": "ext-yMmhk0S7p9A", "src": [["番組のYouTube（28:15〜）", "https://www.youtube.com/watch?v=yMmhk0S7p9A&t=1695s"]]}]);
  ARTICLES.push({ id: "ext-yMmhk0S7p9A", d: "2026-06-24", show: "ext", who: ["Jade Cargill"], t: "ジェイド・カーギルの回　ウィッグ事件と額の傷を語る", lead: "ザ・リッチ・アイゼン・ショーの番組に出た約52分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Jade Cargill"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-yMmhk0S7p9A").map((x) => [x.t, x.b, x.sp])), open: ["番組後半の聞き手2人による大会の予想トークは、本人が出ていないため省いた", "審判の女性の名前は字幕が崩れていて確信が持てず、載せていない"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=yMmhk0S7p9A"]] });
  if (!ROSTER.find((r) => r[1] === "Rey F\u00e9nix")) ROSTER.push(["レイ・フェニックス", "Rey F\u00e9nix", "lg", "仮面のルチャドール", "", "", ""]);
  if (!PROFILES["Rey F\u00e9nix"]) PROFILES["Rey F\u00e9nix"] = { lead: "メキシコの卸売市場で働きながら練習に通い、兄と二人三脚でリングを駆け上がったという。仮面の下の素顔を、3時間かけてじっくり語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Rey%20F\u00e9nix"]], moves: [], facts: [] };
  if (PROFILES["Rey F\u00e9nix"]._weak) { PROFILES["Rey F\u00e9nix"].lead = "メキシコの卸売市場で働きながら練習に通い、兄と二人三脚でリングを駆け上がったという。仮面の下の素顔を、3時間かけてじっくり語った。"; delete PROFILES["Rey F\u00e9nix"]._weak; }
  PROFILES["Rey F\u00e9nix"].facts.push(...[{"cat": "暮らし", "t": "SNSでは暮らしぶりを見せたくない", "b": "フェニックスは、車や家、プールの有無といった持ち物をSNSで見せるのは好きではないと話す。見せれば、本当かどうか分からない「成功の型」を人に押しつけてしまうと考えているそうだ。成功の形は人それぞれで、物を持つことが幸せとは限らないというのが持論だという。自分も普通の人間のひとりだと強調している。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（5:36〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=336s"]]}, {"cat": "暮らし", "t": "壁も窓もなかった下町の小学校", "b": "育ったのはエカテペックの貧しい地区で、通った小学校には最初、壁も扉も窓もなく、木の杭に柵を渡しただけだったという。校舎は住民や行政の支援で少しずつ整っていき、6年間でその変化を見たと話す。管理人一家が学校の敷地内に住んでいたことも覚えているそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（14:29〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=869s"]]}, {"cat": "家族", "t": "兄は父親のような存在だった", "b": "兄とは6歳違いで、同じ学校に通ったことはないという。家族は昔から結びつきが強く、兄が父親代わりのようになった時期があったと話す。のちに二人ともプロレスに出会って、兄弟であり友人であり仲間という、より強い絆になったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（16:59〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1019s"]]}, {"cat": "リングに来るまで", "t": "12歳から卸売市場で働きながら学校へ", "b": "12〜13歳のころ、午前は兄と中央卸売市場で働き、午後は午後の部の中学に通ったという。帰宅して食事と入浴をすませて登校し、夜は兄とジムで練習するという毎日だったと話す。兄にも母にも「学校は終わらせろ」と言われていたそうだ。中学3年は留年して、結局3年がかりで卒業したという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（18:36〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1116s"]]}, {"cat": "リングに来るまで", "t": "果物の卸売りで雑用係から", "b": "市場ではバナナやパパイヤを扱う店の手伝いから始め、兄が独立してからは兄の店で働いたという。荷運びや掃除、販売までこなす何でも屋で、リンゴやブドウ、キウイなどの高級果物も扱ったそうだ。稼げるなら何でもやるつもりで、トマトやアボカドの仕事にも入ったと話す。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（20:58〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1258s"]]}, {"cat": "家族", "t": "7歳のとき、父が病気で働けなくなった", "b": "フェニックスは7歳のころ、父が生涯にわたる病気になって働けなくなったと話す。特別なケアや検査が必要になり、家の大黒柱の役割を兄が担ったという。のちに父は回復して働くようにもなったが、家計の中心にはもう戻らなかったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（23:21〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1401s"]]}, {"cat": "体のこと", "t": "荒れた時期とセラピーでの気づき", "b": "フェニックスは、中学のころには多くの過ちがあり、悪い付き合いもしたと率直に話す。当時は「なぜ自分だけ」と問いかける子どもだったという。今はセラピーや対話を通じて自分を理解できるようになったそうだ。あの経験があったから、本気でレスラーを目指すと決めたとき何が自分のためにならないか分かったと振り返っている。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（26:37〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1597s"]]}, {"cat": "家族", "t": "母は「怠け者にならず働け」と背中を押した", "b": "母は学業を望んでいたが、周りの事情もあり、いつしか「働くことを覚えなさい」という考えに変わっていったという。レスラーになりたいと伝えたときは「やりたいなら応援する」と受け入れてくれたそうだ。ただ、ケガだらけで稼ぎもないころは「本当に続けるのか」と心配もされたと話す。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（29:06〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1746s"]]}, {"cat": "リングに来るまで", "t": "乗り合いバスの「チェッカー」で生計を立てた", "b": "市場の仕事が早朝からでつらくなり、プロレス仲間の家族の紹介で、乗り合いバスの運行を管理する仕事に就いたという。週3日、午後のシフトを選べたので試合と両立しやすかったと話す。人気団体のテレビに出るようになっても、しばらくこの仕事は続けていたそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（33:07〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=1987s"]]}, {"cat": "リングの話", "t": "デビュー戦は兄との試合で、二人とも失神", "b": "初めての試合は、地元の市場組合が毎年12月12日に開く無料興行で、相手は兄だったという。勢い余ってフェニックスが兄の頭を蹴って気絶させてしまったが、目を覚ました兄は事情を聞いて怒り、お返しにフェニックスも倒したと話す。観客の前での出来事で、今では仲間内の笑い話だそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（43:39〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=2619s"]]}, {"cat": "好きなもの", "t": "日本文化への憧れから「マスカラ・オリエンタル」に", "b": "フェニックスは昔から日本の文化が好きで、忍者や空手家のイメージを重ねた最初のリングネームを付けたという。当時見ていた覆面レスラーの派手なマスクにも惹かれたそうだ。マスクには両親の名前を日本語の文字で入れていたと話す。実物は今もメキシコの母のもとに残っているという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（48:24〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=2904s"]]}, {"cat": "リングに来るまで", "t": "試合当日に会場へ押しかけて出場を頼んだ", "b": "仲間6人で、大きな団体の興行にいきなり訪ねて「第1試合に出させてほしい」と頼み込んだことがあるという。ギャラは出なかったが、観客が投げ銭を投げてくれ、約300ペソで夕食をとったと話す。メキシコでは良い試合に観客がお金を投げる習慣があるそうだ。こうした飛び込みを、当時は何度もやっていたという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（55:38〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=3338s"]]}, {"cat": "好きなもの", "t": "ネットカフェで見た日本の映像に憧れた", "b": "家にはパソコンもゲーム機もなく、10〜15ペソでネットカフェを借りて、古い日本のプロレスを見ていたという。そこで見つけた「日本ツアー」という街歩きの映像が大好きで、何度も見返したと話す。のちに実際に日本の街を歩いたときは、画面で見ていたものが現実になった感動があったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:04:44〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=3884s"]]}, {"cat": "リングに来るまで", "t": "21歳で日本に4か月、言葉の壁の中で", "b": "21歳のとき、日本の団体に派遣されて4か月間、道場で暮らしながら各地をまわったという。外国人なので外出の制限が緩く、事務所の友人や在日の知人が街を案内してくれたと話す。当時の道場ではスペイン語を話すのは自分だけで、身振りで稽古し、現地で英語を覚えていったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:07:10〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=4030s"]]}, {"cat": "リングに来るまで", "t": "週5試合の巡業は、バスで19時間移動も", "b": "メキシコで生活費を賄うには、最低でも週5日の試合が必要だったという。北部をまわる巡業では、毎晩別の街で試合をして、最後は19時間かけて首都に戻る日程だったと話す。試合数は週によって変わり、ギャラは試合ごとの出来高だったので収入は安定しなかったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:14:37〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=4477s"]]}, {"cat": "リングに来るまで", "t": "日本に残りたかったが、帰国を選んだ", "b": "フェニックスは、日本に残って活動したいと周囲に頼み込んだほど気持ちが強かったと話す。ただ契約の問題もあり、兄に電話すると「最後は自分で決めろ」と言われたという。言葉の面でまだ準備が足りず、メキシコで築いた実績も無駄にしたくなかったので帰国を決めたそうだ。帰国後は、日本で学んだことが活きて仕事が増えたという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:19:37〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=4777s"]]}, {"cat": "リングの話", "t": "テレビ向けの試合は、カメラの向こうの2万人を意識する", "b": "会場に3000人いても、テレビの向こうには何万人もいる。そこに気持ちを届ける唯一の道がカメラだと話す。メキシコの試合では、カメラが本人を追いかけるので表情や感情を出せばいい。一方、アメリカ流のプロレスでは自分からカメラに向けて演じる必要があると語っている。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:34:18〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=5658s"]]}, {"cat": "リングの話", "t": "映画のような番組で、演技を学んだ", "b": "アメリカの番組では、死んで生き返る物語や、魔術にかけられて悪の姿になる展開を演じたという。「ゾンビのように振る舞って」などと演技の指導を受け、カメラを意識する術を身につけたと話す。この経験が、のちの試合運びにも生きているそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:36:48〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=5808s"]]}, {"cat": "体のこと", "t": "自分が商品だから、体への投資を惜しまない", "b": "フェニックスは、自分自身が商品なので、体や食事、休養に投資する必要があると話す。20年の経歴で膝や肩はすでに痛んでおり、維持するには通院やリハビリの費用もかかるそうだ。試合は今も大好きだが、「割に合う形で、自分の条件で戦いたい」と考えるようになったという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:49:43〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=6583s"]]}, {"cat": "リングの話", "t": "その番組で、全王座を獲得した最初の選手に", "b": "フェニックスは、その番組でタッグ王座や無差別級王座などをすべて獲得した最初の選手になったと話す。兄は兄で別の物語があり、二人ともメキシコ出身の主力として歴史に残ったと自負している。待遇は豪華なホテルや食事つきで、初めて「スターになった」と感じたそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:52:12〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=6732s"]]}, {"cat": "リングの話", "t": "兄との名勝負は、ロンドンと日本の2試合", "b": "ロンドンの国別対抗トーナメントでは、初戦で兄と当たり、観客が総立ちで拍手した名勝負になったという。負けたが、最高の相手に負けたので満足だったと話す。日本でも約35分の試合をして、メキシコ、アメリカ、イギリス、日本と、あらゆるスタイルを一つの試合で見せたそうだ。互いの動きを知り尽くしているので、先読みしながら試合が進んだという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（1:53:56〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=6836s"]]}, {"cat": "リングの話", "t": "深夜2時の入団テスト、兄の頭突きで目が覚めた", "b": "大きな団体の入団テストで、興行が終わった午前2時ごろになってようやくリングに上がったという。眠気と空腹の中、帰りのタクシー代を残すために何も食べていなかったと話す。リング上で兄が頭をぶつけて「全部出し切れ」と気合を入れ、二人は時間も空腹も忘れて戦ったそうだ。終わると事務所の人たちが拍手していたという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:06:11〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=7571s"]]}, {"cat": "リングの話", "t": "衣装を1週間で仕上げ、団体の人を驚かせた", "b": "事務所で新しいキャラクターの案を見せられ、フェニックスは今の名前の案をすぐ選んだという。仕上がりまでの期間を聞かれて「1週間」と答え、職人に無理を言って急いで作ってもらったと話す。会場のトイレで着替えて見せると、関係者は驚いたそうだ。こうして数週間のうちにデビューが決まったという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:09:30〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=7770s"]]}, {"cat": "リングに来るまで", "t": "団体を離れ、ゼロからアメリカで再出発", "b": "番組が終わったあと、妻となる恋人と暮らしながら、メキシコ国境の街ティファナに移って米国のインディー団体を回り始めたという。最初のギャラは50〜100ドルほどで、シカゴまで遠征したこともあったと話す。兄は子どもが二人いて動けず、一人で賭けに出たそうだ。のちに兄も合流したという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:23:23〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=8603s"]]}, {"cat": "暮らし", "t": "グッズを自分で作り、会場で売って稼いだ", "b": "アメリカではレスラー自身がTシャツや写真を売ると知り、15〜20枚から始めたという。ステッカーやキーホルダー、人形も作り、市場で身につけた商売の勘を活かしたと話す。最終的には1回の大会で70〜80枚が売れるようになったそうだ。日程の管理も自分でこなし、自分自身が主催者との窓口になっていたという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:26:35〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=8795s"]]}, {"cat": "家族", "t": "妻は「一緒に行く」と言って支えてくれた", "b": "全財産を賭けるつもりでいたフェニックスは、恋人に実家へ戻るよう勧めたという。しかし恋人は「一緒に行く」と答え、試合日程の調整やSNSの返信を手伝ってくれたと話す。さらにフェイスブックでグッズの店を開き、メキシコのファンに発送もしてくれたそうだ。この支えで収入が上向いていったという。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:51:12〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=10272s"]]}, {"cat": "家族", "t": "サンディエゴへ移住し、長男が誕生", "b": "収入が増え、滞在資格の変更の機会もあって、ティファナからサンディエゴに移ったという。家賃や光熱費がドル払いになり大変だったが、一部屋だけの小さな部屋で暮らし、妻と一緒にグッズも増やしていったと話す。引っ越し前に授かった長男は、サンディエゴで生まれたそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:54:35〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=10475s"]]}, {"cat": "暮らし", "t": "次男の誕生後、契約を結んで広い家に", "b": "仕事が増えるにつれ、寝室3つとプールのある家を借りられるようになったという。次男が生まれたころ、試合に出ても出なくても決まった額が定期的に入る契約を結んだと話す。家族にとって大きな安心になったそうだ。キャリアは20年になると語っている。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:56:54〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=10614s"]]}, {"cat": "リングの話", "t": "長年の夢だった世界最大の団体へ", "b": "独立系で活躍するうち、世界最大の団体からも以前から打診があったが、忙しくて具体化しなかったという。別の大手団体で5年過ごしたあと、ついに夢だった舞台に立つ機会が来たと話す。サッカー選手がW杯を、バスケ選手がNBAを目指すのと同じ、子どものころからの目標だったそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（2:59:24〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=10764s"]]}, {"cat": "リングの話", "t": "目標は年間最大の祭典の主役と、複数のベルト", "b": "フェニックスは、ロイヤルランブルの優勝や、年間最大の祭典のメインイベント、米国王座や大陸間王座の獲得を目標に挙げる。いつかは最高位の王者にもなれると信じていると話す。「ここまで来たのは、ここで止まるためではない」という言葉が好きだそうだ。", "sp": "レイ・フェニックス", "d": "2026-06-27", "how": "レイ・フェニックスの番組で（字幕を全文確認）", "art": "ext-pq1B-POEs2Q", "src": [["番組のYouTube（3:00:56〜）", "https://www.youtube.com/watch?v=pq1B-POEs2Q&t=10856s"]]}]);
  ARTICLES.push({ id: "ext-pq1B-POEs2Q", d: "2026-06-27", show: "ext", who: ["Rey F\u00e9nix"], t: "レイ・フェニックスの回　仮面の下の素顔と、兄と歩んだ道", lead: "レイ・フェニックスの番組に出た約188分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Rey F\u00e9nix"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-pq1B-POEs2Q").map((x) => [x.t, x.b, x.sp])), open: ["友人や協力者の名前は、字幕で崩れていて確信が持てないものや一般の方の実名は載せていない。", "聞き手自身の話や、番組・SNS企画の宣伝部分は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=pq1B-POEs2Q"]] });
  if (!ROSTER.find((r) => r[1] === "Fallon Henley")) ROSTER.push(["ファロン・ヘンリー", "Fallon Henley", "lg", "", "", "", ""]);
