  if (PROFILES["Fallon Henley"].lead === "") PROFILES["Fallon Henley"]._weak = 1;
  PROFILES["Fallon Henley"].facts.push(...[{"cat": "リングの話", "t": "スマックダウン昇格は夢のよう", "b": "ファロン・ヘンリーは、スマックダウンに上がった実感がまだ湧かず、夢の中にいるようだと話す。ペイジやブリー・ベラ、シャーロット・フレア、アレクサ・ブリスといった名前と同じ場にいることが信じられないという。ブランドの希望は特になく、どちらに行っても才能が集まっているので嬉しかったそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（0:51〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=51s"]]}, {"cat": "リングの話", "t": "ジェイシーとは10年来の仲間", "b": "ファロン・ヘンリーは、ジェイシー・ジェーンと約10年前に同じ道場で練習を始めた間柄だと話す。互いに長いキャリアを知っているので、ユニットとしてのまとまりが出ると語る。後から加わったレイニー・リードは、教えたことをすぐ吸収するスポンジのような存在だという。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（3:25〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=205s"]]}, {"cat": "リングの話", "t": "育成施設のコーチ陣から学んだこと", "b": "ファロン・ヘンリーは、育成施設には優れたコーチが大勢いて、試合のたびに誰かの教えが頭の中で聞こえると話す。ひとつだけ選ぶのは難しいが、長く在籍できたおかげで毎日新しいことを学び、すぐ試せたという。厳しい人も優しい人もいたが、全員が選手を成長させるために動いていたそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（5:08〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=308s"]]}, {"cat": "リングの話", "t": "準備は「できる限り」整えた", "b": "ファロン・ヘンリーは、100パーセント準備が整う日は来ないと言われるが、今は経験と教えのおかげで「できる限りの準備はできている」と感じていると話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（7:32〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=452s"]]}, {"cat": "リングの話", "t": "目標はすべてを動かすこと", "b": "ファロン・ヘンリーは、ファタル・インフルエンスの目標を「あらゆるものを支配すること」だと話す。NXT時代にはほぼ2年にわたって自分たちがNXTを動かしていた自負があり、メインロスターでも同じようにすべてを取りにいきたいと語る。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（24:10〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1450s"]]}, {"cat": "リングの話", "t": "試合の場では誰が相手でも標的", "b": "ファロン・ヘンリーは、憧れの選手が相手でも、試合が始まれば目の前の相手は倒す標的になると話す。会場を離れれば、その対戦は良い思い出として受け止められるそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（33:48〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2028s"]]}, {"cat": "リングの話", "t": "古い試合映像からも学べる", "b": "ファロン・ヘンリーは、NXTでテリー・テイラーの授業で古い試合映像を見ていたと話す。今の試合はずっと速いが、昔の試合には見落としがちな細部が詰まっていて、時代や作風を問わず持ち帰れるものがあると語る。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（37:08〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2228s"]]}, {"cat": "リングの話", "t": "ショーン・マイケルズに教わった「理由」", "b": "ファロン・ヘンリーは、試合の組み立てはNXTでショーン・マイケルズに学んだと話す。やることを指示されるだけでは身につかず、なぜそれをやるのか、どう見せるのかまで教えてもらえたのが大きかったという。試合に物語があるときは特にその理由が大事で、自分とユニットの仲間はそこをつかめたと語る。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（40:18〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2418s"]]}, {"cat": "リングの話", "t": "NXTでメインイベントを何度も経験", "b": "ファロン・ヘンリーは、NXTでは女子がメインイベントを務めることが多く、自分も20〜25試合ほどメインを経験したと話す。先人が土台を築いてくれたので、自分も後に続く人たちのためにその流れを続けたいと語る。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（43:31〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2611s"]]}, {"cat": "リングの話", "t": "対戦したいのはベイリー", "b": "ファロン・ヘンリーは、ロウ側で戦ってみたい相手としてまずベイリーの名を挙げる。ベイリーが主宰するキャンプで女子選手同士が助け合っている様子にも触れ、多忙ななかで続けていることを素晴らしいと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（48:11〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2891s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Fallon Henley")) ROSTER.push(["ファロン・ヘンリー", "Fallon Henley", "lg", "フェイタル・インフルエンス", "", "", ""]);
  if (!PROFILES["Fallon Henley"]) PROFILES["Fallon Henley"] = { lead: "森の奥の小さな町で馬に乗って育ち、プロレスに出会ったのは大学に入ってからだという。亡き双子の姉たちを最大の応援者と呼び、遺された姪を引き取りながら契約をつかんだ。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Fallon%20Henley"]], moves: [], facts: [] };
  if (PROFILES["Fallon Henley"]._weak) { PROFILES["Fallon Henley"].lead = "森の奥の小さな町で馬に乗って育ち、プロレスに出会ったのは大学に入ってからだという。亡き双子の姉たちを最大の応援者と呼び、遺された姪を引き取りながら契約をつかんだ。"; delete PROFILES["Fallon Henley"]._weak; }
  PROFILES["Fallon Henley"].facts.push(...[{"cat": "リングに来るまで", "t": "大学時代の職場で師匠と出会う", "b": "練習を始めたのは2016年ごろで、最初の道場には同じユニットのジェイシー・ジェインもいたという。その後引っ越し、大学に通いながら働いていたジムで、パーソナルトレーナーをしていた女子レスラーと知り合ったそうだ。それまで片道1時間以上かけて通っていたが、彼女の教室は家から20分ほどで、タンパ近郊で練習を続けられたと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（8:18〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=498s"]]}, {"cat": "リングに来るまで", "t": "ボニー・マクソンは「プロレスの母」", "b": "ボニー・マクソンを自分の「プロレスの母」と呼び、レクシー・ファイフやメルセデス・マルティネスにも駆け出しのころ支えてもらったという。ジェイシーとは10年ほど前から同じ場所で練習してきた仲で、キャリアのすべてを知り合っていることが、ユニットとしてのまとまりにつながっていると話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（9:09〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=549s"]]}, {"cat": "体のこと", "t": "肩の手術とコロナで約2年の足止め", "b": "インディー団体での流れをつかみ、ようやく勢いに乗り始めたところで肩の手術が必要になったという。骨棘を取る手術で大事ではなかったが、約1年リングを離れ、続いてコロナ禍でさらに1年ほど止まったそうだ。インディーをもっと思い切り回りたかったという心残りも口にしている。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（9:09〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=549s"]]}, {"cat": "リングに来るまで", "t": "トライアウトは3年連続で3回", "b": "トライアウトは2019年から2021年にかけて計3回受けたという。最初の回はジェイドやアイビー・ナイルと一緒で、アイビーとは今では親しい友人だそうだ。2回目はコロナ禍の最中で、女子だけ10人ほどの小さな規模だったと振り返る。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（9:54〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=594s"]]}, {"cat": "リングに来るまで", "t": "エキストラを重ね、4度目を覚悟した直後に契約", "b": "RAWや育成ブランドの収録にエキストラとして何度も参加しており、エキストラ再開後の最初の収録ではエレクトラ・ロペスとの試合を任されたという。その後、育成施設の練習興行の週に一人で呼ばれ、12月にもう一度トライアウトをと言われて「何か間違っているのか」と落ち込んだそうだ。それでも1週間全力を尽くし、2週間ほどして契約の電話が来たと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（10:44〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=644s"]]}, {"cat": "暮らし", "t": "契約の電話は迷惑電話かと思った", "b": "電話が来たのは金曜の夕方6時ごろで、家でくつろいでいたところだったという。知り合いのいないコネチカットの番号からで、知らない番号には普段出ないうえ迷惑電話も多いので、出るかどうか迷ったそうだ。思い切って出たら、それが契約の知らせだったと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（12:21〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=741s"]]}, {"cat": "家族", "t": "双子の姉の急死と、姪2人との同居", "b": "双子の姉が2人いたが、今はどちらも亡くなっているという。2021年に1人目の姉が臓器の機能不全で急に亡くなり、すでに父親も亡くしていた10代の姪2人が遺されたそうだ。母のいるミシガンや別の姉のいるカリフォルニアに移る選択肢もあったが、22歳ごろだった本人が2LDKの部屋に引き取り、自分は小さいほうの部屋を使ったと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（13:09〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=789s"]]}, {"cat": "リングに来るまで", "t": "断りかけたエキストラの誘い", "b": "姉を亡くした直後にエキストラの誘いが来たが、気持ちの面でとてもできる状態ではなく、断りかけたという。あのとき断っていたら今の自分はなかったと話し、夢をかなえてほしいと願っていた姉に背中を押されたように感じているそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（14:46〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=886s"]]}, {"cat": "家族", "t": "双子の姉はいちばんの応援者", "b": "双子の姉たちは、進む道を決める前から誰よりも応援してくれた存在だったという。両親が手の届かない夢を追うのを不思議がっていた時期も、会うたびに夢を追えと励ましてくれたそうで、今の活動の多くは2人のためだと話す。引き取った姪は、1人が姉の勤めていた職場で働き始め、もう1人は看護学校に通っており、自分の活躍を心から喜んでくれているそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（15:32〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=932s"]]}, {"cat": "リングに来るまで", "t": "森の奥の小さな町で馬と育つ", "b": "根っからのカウガールかと聞かれ、「心は」と答えている。育ったのはとても小さな町で、家の私道は森の中を800mほど入った先にあり、周りには何も見えず何も聞こえず、森の向こうはトウモロコシ畑が続いていたという。子どものころから乗馬をしていたそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（24:57〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1497s"]]}, {"cat": "好きなもの", "t": "愛馬は元競走馬のオリバー", "b": "長く借りていた馬はエドウィン、自分で持っていた馬はオリバーという名前で、オリバーは元競走馬だったという。乗馬は5年ほど続け、障害飛越や馬場馬術などの英国式を中心に競技にも出ていたそうだ。顔や脚の模様の呼び名まで覚えているほど馬に詳しい。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（25:45〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1545s"]]}, {"cat": "暮らし", "t": "いつか農場で馬やヤギを飼いたい", "b": "今は馬を飼っておらず、乗馬が恋しくてたまらないという。将来は土地を持って農場を開き、馬やヤギ、ニワトリを飼うのが目標だそうだ。新しい馬の名前を聞かれると、名前は性格や見た目に合わせて決めるものだから、今は決められないと答えている。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（27:20〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1640s"]]}, {"cat": "リングに来るまで", "t": "プロレスを知ったのは大学時代", "b": "子どものころはプロレスを観ておらず、家族も友人も観る人はいなかったという。大学で進路に迷っていた時期に出会い、ちょうど育成ブランドの黄金期で、ベイリーやアレクサ・ブリス、シャーロット・フレアーらに夢中になったそうだ。大学では犯罪学と経営学の学位を取ったが、何に使うつもりだったかは自分でも分からないと笑う。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（31:28〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1888s"]]}, {"cat": "リングに来るまで", "t": "駆け出しで会ったベイリーが原点", "b": "道場に入って数か月のころ、ダラスで年間最大の祭典が開かれた時期に、出場していた地元の興行にベイリーが来て会えたという。とても親切で誠実だった印象が残り、その後テレビで観るたびに特別な存在になったそうだ。ベイリーとサーシャ・バンクスの2人に、プロレスへの火をつけてもらったと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（35:27〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2127s"]]}, {"cat": "リングに来るまで", "t": "ショーン・マイケルズに学んだ「なぜ」", "b": "試合の組み立ては生まれつきではなく、育成時代にショーン・マイケルズのもとで身につけたものだという。理由を言われないと頭に残らないタイプで、ショーンはリハーサルで一つひとつの動きの「なぜ」を時間をかけて教えてくれたそうだ。テリー・テイラーの授業で昔の試合映像を見たことも、細部の大切さを知るきっかけになったと話す。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（40:18〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2418s"]]}, {"cat": "暮らし", "t": "高校時代はスケートリンクで3つの仕事", "b": "高校時代の初めてのアルバイト先はアイススケートリンクで、少年アイスホッケーのスコア係、事務、併設カフェのバリスタと3つの仕事を掛け持ちしていたという。のちに知り合った同業者が、偶然そのリンクでスケートを教えていたと分かって驚いたそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（51:23〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=3083s"]]}, {"cat": "家族", "t": "父は元空軍、その後35年航空業界", "b": "父は空軍出身で、その後35年にわたって航空業界で働いたという。勤め先はほぼ一つで、ノースウエスト航空がデルタ航空に買収されてからもそのまま勤めたそうだ。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（52:12〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=3132s"]]}, {"cat": "リングに来るまで", "t": "パイロットを目指したが単独飛行で断念", "b": "パイロットになるつもりで、単発のセスナ機を操縦していたことがあるという。腕前は自分でもかなり良かったと話すが、人を乗せた金属の塊に責任を持つことが怖くて乗り越えられなかったそうだ。単独飛行の段階まで進んだところでやめたため、免許は持っていない。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（52:58〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=3178s"]]}]);
  if (PROFILES["Mickie James"]) PROFILES["Mickie James"].facts.push({"cat": "暮らし", "t": "会うたびにハグと助言をくれる", "b": "ミッキー・ジェームスはこれまで会った中でもいちばん親切な人の一人だと、ファロン・ヘンリーが話している。番組の仕事で育成ブランドに来ていた時期は、会うたびにたくさんのハグと助言、褒め言葉をくれたそうで、「あきれるほど優しい」と表現している。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で、ファロン・ヘンリーの話（公式字幕を全文確認）", "src": [["公式YouTube（29:03〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1743s"]], "by": "第三者の話"});
  if (PROFILES["Bayley"]) PROFILES["Bayley"].facts.push({"cat": "暮らし", "t": "多忙でも後輩のためのキャンプを続ける", "b": "ベイリーが主宰する女子選手向けのキャンプについて、女性同士が知識を分け合い、引き上げ合う場として素晴らしいと、ファロン・ヘンリーが話している。忙しいスケジュールの中でその時間を作っていることにも感心しているそうだ。名前の由来は知らないという。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で、ファロン・ヘンリーの話（公式字幕を全文確認）", "src": [["公式YouTube（48:11〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2891s"]], "by": "第三者の話"});
  if (PROFILES["Jordynne Grace"]) PROFILES["Jordynne Grace"].facts.push({"cat": "暮らし", "t": "飛行機の操縦を習い始めた", "b": "ジョーディン・グレースが最近、飛行機の操縦レッスンを受け始めたのを見たと、ファロン・ヘンリーが話している。", "sp": "ファロン・ヘンリー", "d": "2026-07-02", "how": "コーディの番組で、ファロン・ヘンリーの話（公式字幕を全文確認）", "src": [["公式YouTube（53:45〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=3225s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "体のこと", "t": "準備万端の日に限って膝が裂ける", "b": "年間最大の祭典で、タイツを少し引き上げただけで膝の部分が完全に裂けてしまったことがあるという。完璧に準備ができたと思ったときほど思わぬことが起きるもので、最近のキャリアはずっとその連続だと苦笑している。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（7:32〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=452s"]]}, {"cat": "好きなもの", "t": "ゲームの馬に名前を付けられず不満", "b": "プレイステーションの『ゴースト・オブ・ツシマ』を何度も遊んでいるが、馬に自由に名前を付けられず、用意された候補から選ぶしかないのが何より腹立たしいという。今の愛馬「ノブ」は気に入っているものの、自分らしい名前を付けたかったと話す。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（27:20〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1640s"]]}, {"cat": "家族", "t": "馬好きの父の影響で品種を覚えた", "b": "父が大の馬好きだったため、子どものころに馬の品種や毛色の本を読まされたという。役に立ったと感じたのは、ずっと後に『レッド・デッド・リデンプション』を遊んだときくらいだったと笑う。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（28:11〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1691s"]]}, {"cat": "リングに来るまで", "t": "40歳の今も「ここにいるべき人間だ」と唱える", "b": "40歳になった今も、尊敬する人が並ぶ部屋に入ると気後れしそうになるという。そんなときは小声で「自分はここにいるべき人間だ」と自分に言い聞かせることがあるそうだ。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（32:15〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=1935s"]]}, {"cat": "リングに来るまで", "t": "OVW入りの時点で練習経験はゼロ", "b": "育成団体OVWに入ったとき、周りからは父ダスティの息子だから父が憧れで、すでに練習も積んでいるはずだと思われていたという。実際はまったく練習しておらず、自分でリングに立ち、教わったことが通じる手応えを重ねるうちに、プロレスがもっと好きになったそうだ。好きな選手もその時々で変わっていったと話す。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（34:40〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2080s"]]}, {"cat": "リングに来るまで", "t": "師匠の教えは「大技は花火」", "b": "自分を指導した人は、派手な大技を花火にたとえていたという。花火は見れば感動するが年に1、2回で十分で、自分から追い求めるものではない「おまけ」だという教えだそうだ。子どものころ一番好きだった選手はショーン・マイケルズだとも話している。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（38:44〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=2324s"]]}, {"cat": "暮らし", "t": "映画の空軍役で軍の知識を詰め込む", "b": "初めての大作映画で空軍の軍人ガイルを演じることになり、当時の階級や軍の細かな知識を大量に調べて臨んだという。即興の多い現場だったので、誰かに軍のことを聞かれても答えられるよう準備していたが、結局一度も聞かれなかったと笑う。", "sp": "コーディ・ローデス", "d": "2026-07-02", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-7gyw6a5GtIU", "src": [["公式YouTube（52:12〜）", "https://www.youtube.com/watch?v=7gyw6a5GtIU&t=3132s"]]}]);
  ARTICLES.push({ id: "wdywta-7gyw6a5GtIU", d: "2026-07-02", show: "wdywta", who: ["Fallon Henley", "Cody Rhodes"], t: "ファロン・ヘンリーの回　乗馬少女が姉の死を越え、4度目目前のトライアウトで契約をつかむまで", lead: "コーディ・ローデスの番組に出た約55分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Fallon Henley", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-7gyw6a5GtIU").map((x) => [x.t, x.b, x.sp])), open: ["字幕は48分56秒から51分23秒のあいだが欠けており、スケートリンクでスケートを教えていた同業者が誰なのかは字幕から特定できなかった。", "コーディが語った、ファロンとアーロン・ソロにまつわる「アービーズ」のエピソードは、聞き手側の思い出話のため載せていない。", "亡くなった姉たちや姪など、一般の家族の実名は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=7gyw6a5GtIU"]] });
