  if (PROFILES["Dragon Lee"]._weak) { PROFILES["Dragon Lee"].lead = "メキシコの覆面レスラー一家の末っ子として育ち、父の厳しい指導を経てWWEへ。いまは2人の娘の父として、感謝を忘れず穏やかに暮らしている。"; delete PROFILES["Dragon Lee"]._weak; }
  PROFILES["Dragon Lee"].facts.push(...[{"cat": "暮らし", "t": "アメリカ暮らしは約3年", "b": "フロリダで1年、ロサンゼルスで約2年暮らしている。来たころ英語はほとんど話せなかった。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（1:35〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=95s"]]}, {"cat": "暮らし", "t": "英語は仕事漬けの毎日で身についた", "b": "メキシコではオンライン授業を受け、NXT時代は週2回1時間の英語教室に通ったという。それ以上に、毎日6時間ほど施設で過ごして仲間と話すうちに上達したと話す。コーチのテリー・テイラーに説明されて「分かった？」と聞かれ、分からないまま答えた思い出もある。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（2:20〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=140s"]]}, {"cat": "リングの話", "t": "国ごとに違うプロレスの流儀", "b": "日本は強さを前面に出す流儀、メキシコは空中戦と関節技、アメリカはマイクで客とつながる力が大事だと話す。最近のWWEは体の大きさ以上に、見せ場をつかむ機会が増えていると感じているそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（3:55〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=235s"]]}, {"cat": "リングに来るまで", "t": "父の気を引きたくて始めた", "b": "5歳のころ、父が兄たちの指導に付きっきりで、自分もかまってほしくてレスリングを始めたと話す。両親は別居しており、子どもだった自分は父の注目がほしかっただけだったという。親になった今は、当時の父の気持ちが分かるそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（5:32〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=332s"]]}, {"cat": "リングに来るまで", "t": "12歳から格闘技を総合的に学んだ", "b": "12歳ごろから本格的に鍛え始め、カンフー、五輪式レスリング、ボクシングをこなしたという。プロレスの前に土台をそろえる、という父の考えだった。泣くほどきつい日もあったが、今は誇りに思っていると話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（6:22〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=382s"]]}, {"cat": "家族", "t": "父は厳しいコーチだった", "b": "同居していた父は、朝8時にはリングに立つよう決め、起こしにも来ず目覚ましだけ鳴らして出ていったという。家では父、リングではコーチという存在だった。耐え抜けたのは父に誇りに思われたかったからで、今も父は憧れの人だと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（7:15〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=435s"]]}, {"cat": "家族", "t": "兄ふたりも覆面レスラーの末っ子", "b": "兄のルーやドリスティコもレスラーで、本人は三兄弟の末っ子。今は父や兄たちと良い関係で、家族がまとまっていると話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（8:00〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=480s"]]}, {"cat": "リングに来るまで", "t": "最初の覆面名は別の名前だった", "b": "メキシコでのデビュー直前、父の昔のユニット名にちなむプエルトリコ風のリングネームを名乗っていたという。のちに、兄が1年半ほど使っていたドラゴン・リーの名を受け継ぐことになった。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（8:29〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=509s"]]}, {"cat": "家族", "t": "兄の名を継ぐ重さを感じていた", "b": "兄は空中戦の名手で、その名に見合う自信は最初なかったと話す。それでも自分のスタイルを重ねて今に至るという。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（9:37〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=577s"]]}, {"cat": "好きなもの", "t": "マスクの由来はブルース・リー", "b": "マスクの着想はブルース・リーと、家族で続けてきたカンフーだという。陰陽のモチーフもあり、善と悪の両面を表す。亡くなった叔父が兄たちに「ドラゴン」の名を授けたとも話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（9:50〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=590s"]]}, {"cat": "好きなもの", "t": "マスクに足した鱗と故郷の文字", "b": "WWEに来てから鱗の飾りを足したという。側面の日本語は「龍」で、地元ハリスコ州の小さな町への思いも込めている。故郷はテキーラとタコスとマリアッチで知られる土地だそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=674s"]]}, {"cat": "家族", "t": "兄ルーは覆面を外して戦っている", "b": "兄ルーはしばらく覆面で戦ったあと素顔になったという。本人は兄は素顔のほうが似合うと思っている。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（12:03〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=723s"]]}, {"cat": "リングの話", "t": "覆面をはがされた試合の思い", "b": "ガンターとの試合で覆面をはがされたことは、文化的に敬意を欠く行為で重い出来事だったと話す。ただ試合そのものは自分のベストバウトのひとつで、もう一度戦って借りを返したいと語っている。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（12:50〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=770s"]]}, {"cat": "暮らし", "t": "素顔はほとんど知られていない", "b": "レイ・ミステリオ、ペンタと素顔で写った写真が広まったが、撮ってレイが投稿したもので、ここまで広がるとは思わなかったと話す。空港などでは歩き方で気づかれることがあり、サインを頼まれて困ることもあるという。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（15:11〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=911s"]]}, {"cat": "リングの話", "t": "NXTで心に残るのはドミニクとの試合", "b": "北米王座戦でのドミニクとの試合が一番記憶に残っているという。レイとエディ・ゲレロの試合のような相性を感じたと話す。ドミニクがルチャの動きをすぐ覚える点も称賛している。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（16:46〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1006s"]]}, {"cat": "リングの話", "t": "どの団体でも王者になると誓っていた", "b": "所属した団体ではすべてチャンピオンになると自分に約束していたという。NXTでも王座を目標に、機会が来たときのために準備を重ねたと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（18:22〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1102s"]]}, {"cat": "リングの話", "t": "レイ・ミステリオは人生の師", "b": "レイは、スタッフや警備、厨房の人にまで優しく接する人だという。リング以外のことも多く学んだそうだ。最初は敬意から「セニョール」と呼んでいたが、友達だと言われて今は兄弟のような仲だと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（19:55〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1195s"]]}, {"cat": "リングの話", "t": "レイと組めたのは誇り", "b": "子どものころからレイを見て育ち、同じユニットに入れたことを友人たちにうらやましがられるという。年間最大の祭典ではレイと同じリングに立て、感激したと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（22:20〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1340s"]]}, {"cat": "リングの話", "t": "初めてのラダー戦は想像以上に重かった", "b": "王座戦での初のラダー戦では、はしごが偽物だと思っていたら本物で驚いたという。腕や脚をぶつけるほど重く、登るのも大変だったそうだ。見せ場を作りたい気持ちが強く、観客の記憶に残る瞬間を狙っていたと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（23:10〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1390s"]]}, {"cat": "暮らし", "t": "クリスマスのはしごで指を痛めた", "b": "自宅でクリスマスの飾りを付けていてはしごが壊れ、落ちて指を痛めたという。ドウェイン・ジョンソンの映画の場面をまねて自分で指を戻したと笑って話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（23:59〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1439s"]]}, {"cat": "リングの話", "t": "次のレイにはなれないと思っている", "b": "覆面をかぶると必ずレイと比べられるが、レイは別格で誰も代わりになれないと話す。自分はただひとりのドラゴン・リーでいたいという。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（26:23〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1583s"]]}, {"cat": "好きなもの", "t": "アンダーテイカーのバイクに座った", "b": "子どものころから見てきたバイクで、チャンスだと思い、近くにいたCMパンクに背中を押されて写真を撮ったという。後日アンダーテイカーに「傷をつけた」と冗談を言われ、一瞬本気で焦ったそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（27:58〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1678s"]]}, {"cat": "リングの話", "t": "CMパンクが覆面をかぶった", "b": "更衣室に置いていた自分のマスクと上着をCMパンクが着けた写真が出回ったという。パンクはほかのメキシコ人レスラーのマスクもかぶっており、本当はルチャドールになりたいのではと冗談を言っている。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（32:01〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1921s"]]}, {"cat": "リングの話", "t": "AJ・スタイルズとの王者コンビ", "b": "AJとのタッグは自然に決まった流れだったと話す。AJからは父としての姿勢も学んだという。ベルトを巻いた瞬間は夢のようで、AJが肩をつかんで現実だと教えてくれたそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（32:48〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1968s"]]}, {"cat": "家族", "t": "メキシコの仲間との時間を大事にしている", "b": "移動はたいていレイと一緒で、ペンタ、フェニックス、グランデ・アメリカーノらメキシコ勢と過ごすことが多いという。試合の内容より、一緒に過ごした思い出のほうが後まで残ると話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（36:48〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=2208s"]]}, {"cat": "家族", "t": "父の日に娘の手紙で涙した", "b": "子どもは4歳と1歳の2人の娘だという。父の日の前倒しの祝いで、妻が娘の言葉を読み上げ、5歳近い娘の姿に自分の幼い頃を重ねて泣いたと話す。父親の大変さも分かるようになったそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（39:54〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=2394s"]]}, {"cat": "家族", "t": "覆面を脱げば普通のお父さん", "b": "外ではタコスを食べていても誰にも気づかれず、私生活を守れるのがこの仕事の良いところだという。家に帰ると娘たちが迎えてくれるのが最高だと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（44:12〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=2652s"]]}, {"cat": "家族", "t": "親になり両親と義父への見方が変わった", "b": "自分の父母への愛情が増し、昔は厳しいと思った妻の父の気持ちも分かるようになったという。娘が2人いる今は、当時の義父の態度に納得していると笑う。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（45:00〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=2700s"]]}, {"cat": "暮らし", "t": "趣味はゲーム、特にバイオとヒットマン", "b": "今は『アサシン クリード』を遊び、昔からのヒットマン2、バイオハザード2と3も好きだという。バイオは20回ほどクリアしたそうだ。子どもができてからは時間が取れず、娘と一緒にミッキーやマリオのゲームを遊ぶのが楽しみだと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（53:18〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=3198s"]]}, {"cat": "暮らし", "t": "休日は家族と映画と肉焼き", "b": "映画を妻と観たり、義兄弟とカルネ・アサーダ（焼き肉）を囲んだりして過ごす家族思いの性格だという。音楽をかけて歌い、テキーラを一杯飲むのが好きだそうだ。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（54:07〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=3247s"]]}, {"cat": "暮らし", "t": "朝はスマホを投げてから祈る", "b": "デンゼル・ワシントンの話に影響され、朝起きたらスマホを遠くに放り機内モードにすると話す。若くして急逝した友人の話から、一日一日に感謝するようになったという。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（56:00〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=3360s"]]}, {"cat": "体のこと", "t": "飛行機の乱気流が怖くなった", "b": "以前は何も気にしなかったが、子どもができてからは乱気流の際に家族のもとへ帰りたいと強く思うようになったと話す。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-A2ATcV1BcbE", "src": [["番組のYouTube（57:40〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=3460s"]]}]);
  if (PROFILES["Rey Mysterio"]) PROFILES["Rey Mysterio"].facts.push({"cat": "暮らし", "t": "周囲の誰にも優しい師匠", "b": "スタッフや警備、厨房の人にまで丁寧に接し、リング外の生き方も教えてくれる人だと、ドラゴン・リーが話している。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で、ドラゴン・リーの話（字幕を全文確認）", "src": [["番組のYouTube（19:55〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1195s"]], "by": "第三者の話"});
  if (PROFILES["CM Punk"]) PROFILES["CM Punk"].facts.push({"cat": "暮らし", "t": "バイクの写真を後押ししてくれた", "b": "アンダーテイカーのバイクに乗る写真を撮るとき、パンクが背中を押して撮影を手伝ってくれたと、ドラゴン・リーが話している。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で、ドラゴン・リーの話（字幕を全文確認）", "src": [["番組のYouTube（28:44〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=1724s"]], "by": "第三者の話"});
  if (PROFILES["AJ Styles"]) PROFILES["AJ Styles"].facts.push({"cat": "暮らし", "t": "父としても手本になる先輩", "b": "試合だけでなく、父親としての姿や体の手入れの姿勢も勉強になったと、ドラゴン・リーが話している。", "sp": "ドラゴン・リー", "d": "2026-07-23", "how": "クリス・ヴァン・ヴリートの番組で、ドラゴン・リーの話（字幕を全文確認）", "src": [["番組のYouTube（33:33〜）", "https://www.youtube.com/watch?v=A2ATcV1BcbE&t=2013s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-A2ATcV1BcbE", d: "2026-07-23", show: "ext", who: ["Dragon Lee"], t: "ドラゴン・リーの回　覆面の下の父の顔", lead: "クリス・ヴァン・ヴリートの番組に出た約60分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Dragon Lee"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-A2ATcV1BcbE").map((x) => [x.t, x.b, x.sp])), open: ["広告の読み上げは除いた。名前が崩れていた箇所の一部は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=A2ATcV1BcbE"]] });
  if (!PROFILES["Michael Cole"]) PROFILES["Michael Cole"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Michael%20Cole"]], moves: [], facts: [] };
  if (PROFILES["Michael Cole"].lead === "") PROFILES["Michael Cole"]._weak = 1;
  PROFILES["Michael Cole"].facts.push(...[{"cat": "リングの話", "t": "巡業の車でロン・シモンズとJBLに同乗", "b": "マイケル・コールは入社1年目に、制作責任者の計らいで多くの興行に同行し、ロン・シモンズとJBLの車に乗って運転役を務めたという。移動のたびにビールやウイスキーを積み、町ごとにみんなの宿を手配する役だったと話す。この経験で楽屋の選手たちに受け入れられ、長くやっていく覚悟もできたそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（14:17〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=857s"]]}, {"cat": "リングの話", "t": "慣れるまで10年かかると言われた", "b": "入社時、マイケル・コールは「この役に慣れるまで10年かかる」と言われ、報道記者としての自負から驚いたという。車での移動中に学んだ大きなことは「心理」と「感情」の二つだったと話す。善玉と悪玉、試合の心理、観客に好かれる人物像を理解することが出発点だったそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（16:47〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1007s"]]}, {"cat": "リングの話", "t": "JBLが教えてくれたヒールの考え方", "b": "マイケル・コールは、当時トップヒールだったJBLが、会社から勧められたグッズ販売を断ったと聞いて気づきがあったという。悪役なら客に憎まれるべきで、客席で自分のグッズを着られては困るという理屈だった。普段は一人の人間でも、役を信じ切って生きなければ観客は信じないと学んだそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（17:37〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1057s"]]}, {"cat": "リングの話", "t": "感情は教えられない", "b": "マイケル・コールは、実況に必要な二つ目の要素は感情で、これは教えられないと話す。若いころはジム・ロスやビンスらから「記者のように聞こえる、物語の語り手になれ」と言われたという。実況席はストーリーの一部であり、感情に巻き込まれていいのだと理解したそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（19:11〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1151s"]]}, {"cat": "リングの話", "t": "親友だから本気で応援できた", "b": "マイケル・コールは、ジョン・シーナやJBL、トリプルHと長く時間を共にしたことで、試合の実況に本物の感情が出るようになったと話す。シーナのバスに何年も乗った仲で、彼が王座を取れば本当にうれしく、ブロック・レスナーに叩きのめされれば本当に腹が立ったという。ジム・ロスの凄さも、最小限の実況に感情が乗っていた点にあると語った。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（19:56〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1196s"]]}, {"cat": "リングの話", "t": "ジム・ロスの後任と言われ続けた10年", "b": "マイケル・コールは、30歳で入社した自分にとって、10代から業界にいたジム・ロスの後任という重さは大きく、自分の声が見つからず苦しんだと話す。初期はロスの叫び方をまねて、いま聞くと恥ずかしい実況もあったという。ビンスやケビン・ダンに信じてもらえ、ある日ここにいていいのだと思えたそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（22:14〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1334s"]]}, {"cat": "リングの話", "t": "ステフの平手打ちと、ジム・ロスのヒール化", "b": "マイケル・コールは、イギリスでステフに本気で平手打ちされ、数日耳鳴りがしたと話す。また、ジム・ロスをヒールにする企画は会社史上最悪の筋書きだったと振り返る。自分は細身の30歳で、ロスに急所を蹴られる場面もあったが、そこから続いた展開でロスが病気になり、入社半年足らずで月曜の看板番組を任されたという。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（23:47〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1427s"]]}, {"cat": "リングの話", "t": "何度も辞めようと思った", "b": "マイケル・コールは、入社半年ほどで看板番組の実況を任されたとき、できるのかと不安になり、何度も辞めようと考えたと話す。それでも失敗や恥を重ねながら粘り、続けてきたという。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（25:25〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1525s"]]}, {"cat": "リングの話", "t": "実況は自分ではなく選手のためにある", "b": "マイケル・コールは、新しい実況者や聞き手に、実況は自分のためではなく、体を張る選手のためにあると伝えているという。役目は物語を盛り上げて語ることで、それができれば自分も自然にスターになると話す。もう一つは、歴史家やファンを気取らず自然体でいることだそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（26:16〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1576s"]]}, {"cat": "リングの話", "t": "新旧のファンを両立する語り方", "b": "マイケル・コールは、長年のファンを退屈させず、初めて見る人にも分かるよう、数か月続く抗争を2、3文で説明するのがコツだと話す。何より大事なのは、なぜ今夜の試合が前の対戦より重要なのかという「理由」だという。スターの多くは自力では支持されず、実況席が人物像を伝えることで育つ面があると考えているそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（29:33〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1773s"]]}]);
  if (!PROFILES["Michael Cole"]) PROFILES["Michael Cole"] = { lead: "ラジオのニュース記者からWWEの実況席へ転じたマイケル・コール。妻の腎臓病を家族で支えた日々や、雪山での滑落事故まで率直に語っている。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Michael%20Cole"]], moves: [], facts: [] };
  if (PROFILES["Michael Cole"]._weak) { PROFILES["Michael Cole"].lead = "ラジオのニュース記者からWWEの実況席へ転じたマイケル・コール。妻の腎臓病を家族で支えた日々や、雪山での滑落事故まで率直に語っている。"; delete PROFILES["Michael Cole"]._weak; }
  PROFILES["Michael Cole"].facts.push(...[{"cat": "リングに来るまで", "t": "名門の放送学部でスポーツ実況を学んだ", "b": "シラキュース大学の放送学部に進み、もともとはスポーツアナウンサーを目指していたという。同級生で親友のマイク・ティリコと組んで大学のフットボールやバスケットボールを実況していたそうだ。4年生のときには、有望なスポーツキャスターに贈られる奨学金を受けたと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（2:29〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=149s"]]}, {"cat": "リングに来るまで", "t": "就職難でニュース記者の道へ", "b": "卒業当時はスポーツの仕事がなかなか見つからず、地方大学からの誘いも断ったという。そこで在学中に学んでいたニュースの道を選び、新卒としては最年少クラスで全国ネットの記者に採用されたそうだ。最初の拠点はヒューストンだった。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（3:14〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=194s"]]}, {"cat": "リングに来るまで", "t": "原点は映像のないラジオの語り", "b": "CBSニュースで約8年、テレビではなくラジオの記者として働いていたという。映像なしに言葉と声だけで物語を伝えられるところに魅力を感じ、ラジオを「最初の恋」と呼んでいる。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（4:01〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=241s"]]}, {"cat": "リングに来るまで", "t": "ウェイコの立てこもりを51日間取材", "b": "1990年代、大事件に急行する記者として、テキサス州ウェイコの教団施設での立てこもり事件を51日間取材したという。日曜の朝に呼び出され、車で約3時間かけて現地入りしたそうだ。ゴルフ仲間だった弁護士のつてで、教団の指導者に電話インタビューした最初期の記者の一人でもあった。最終日には施設が炎に包まれる様子を、約45分にわたり生中継で伝えたと振り返る。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（4:01〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=241s"]]}, {"cat": "リングに来るまで", "t": "内戦下のサラエボで数か月足止め", "b": "ボスニア内戦中のサラエボにも2度入ったという。2度目は空港が封鎖されて出られなくなり、焼け残ったアパートで数か月暮らしたそうだ。暖房がなく家具を燃やし、水は1日1時間しか出なかったと話す。週に一度、国連の拠点でファクスを借り、当時の恋人で今の妻に無事を知らせていたという。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（8:06〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=486s"]]}, {"cat": "リングに来るまで", "t": "大統領選の取材も3度経験", "b": "大統領選挙の陣営取材も3度担当したという。1992年にはビル・クリントン陣営、1996年にはスティーブ・フォーブスやボブ・ドールの陣営を追ったそうだ。WWEに来たのはその直後だった。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（8:53〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=533s"]]}, {"cat": "リングに来るまで", "t": "出張続きの記者生活に区切り", "b": "1995年にニューヨークのラジオ局へ移る際、出張はさせないと約束されていたという。ところが翌年には大統領選の取材で8か月も家を空けることになったそうだ。結婚して1年ほどの妻に「もう落ち着いてほしい」と言われ、契約更新の時期に転職を考え始めたと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（9:39〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=579s"]]}, {"cat": "リングに来るまで", "t": "旧知のDJの縁でオーディションへ", "b": "最初の仕事はニューヨーク州オールバニのラジオ局で、トッド・ペティンギルの朝の番組でニュースを読んでいたという。そのペティンギルがWWEを離れる際に声をかけてくれ、ケビン・ダンとマイケル・ヘイズのオーディションを受けたそうだ。3〜4か月音沙汰がなく、契約切れ間際に突然採用の電話が来たと笑う。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（10:26〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=626s"]]}, {"cat": "リングに来るまで", "t": "1年のつもりが30年近く", "b": "テレビの経験を積んでニュースの世界に戻るつもりで、WWEには1年ほどいるだけだと本気で思っていたという。それから30年近くたった今も在籍し、この会社とずっと「恋愛関係」にあると話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（11:11〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=671s"]]}, {"cat": "家族", "t": "予定の立つ仕事を妻も歓迎", "b": "WWEへの転職は、妻も受け入れてくれたという。いつどこへ出張し、いつ家にいられるかが前もって分かるからだそうだ。記者時代は真夜中に呼び出され、取材が数日で終わるか1か月かかるかも分からなかったと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（12:46〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=766s"]]}, {"cat": "リングに来るまで", "t": "1年目はJBLらの車の運転手", "b": "ケビン・ダンにとって初めての社員アナウンサーで、きちんと業界を学べるよう1年目はハウスショーの巡業に回されたという。ロン・シモンズとJBLの車に同乗し、運転と、会場を出たあとの酒の用意が自分の役目だったそうだ。この経験のおかげで控室の仲間に受け入れてもらえたと振り返る。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（14:17〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=857s"]]}, {"cat": "リングに来るまで", "t": "「慣れるまで10年」の言葉どおり", "b": "入社時、ケビン・ダンに「この役に慣れるまで10年かかる」と言われたという。数々の報道賞を受けた記者として内心は反発したが、実際に10年かかり、今も学び続けていると話す。初期は上司たちから「記者みたいだ、感情が伝わらない」と何度も指摘されたそうだ。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（16:47〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1007s"]]}, {"cat": "リングに来るまで", "t": "「JRの後任」の重圧と迷い", "b": "長年「ジム・ロスの後任」と言われ続け、自分の声を見つけるまで10年もがいたという。30歳で業界に入り、経験わずか半年の1998年にはRAWの実況を任されたそうだ。当時の自分を「体重68キロほど、口ひげにボサボサ髪の若造」と笑い、会社を辞めようと思ったことも何度もあったと明かす。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（22:14〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1334s"]]}, {"cat": "家族", "t": "父のひと言で結婚を決めた", "b": "1991年にヒューストンで妻と出会い、妻には前の結婚で生まれた2人の子どもがいたという。20代半ばで家族を背負う覚悟が持てずにいたとき、父に「彼女と子どもたちを愛しているなら、ニューヨークへ行く前に指輪を渡せ」と言われたそうだ。プロポーズし、2人の子は自分の子になったと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（33:36〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2016s"]]}, {"cat": "暮らし", "t": "新生活の門出に車が大破", "b": "結婚式の直前にニューヨーク転勤となり、引っ越しのトラックで後ろに乗用車を引いて移動したという。途中の休憩所で、その車が大型トラックに潰され、中の結婚祝いの品も全部だめになったそうだ。2か月後には大雪に見舞われ、雪を見たことのないテキサス育ちの妻は「もう帰りたい」と嘆いたという。今は夫婦でテキサスに戻っていると話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（35:07〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2107s"]]}, {"cat": "家族", "t": "妻の腎臓病と透析の日々", "b": "入社して間もない頃、30歳ほどだった妻の腎機能が5%しか残っていないと分かったという。週3回の透析が始まったが、小柄な妻には負担が大きく、命にかかわるほどだったそうだ。巡業で家を空ける間、免許のない15歳の息子が母を病院へ送っていたといい、罪悪感から何度も辞めようとしたが妻が許さなかったと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（36:41〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2201s"]]}, {"cat": "家族", "t": "義兄の腎臓提供と9・11での延期", "b": "本人も子どもたちも適合せず、移植待ちは5〜6年と言われていたという。そんな中、軍にいた妻の姉の夫が同じ珍しい血液型だと分かり、検査で適合したそうだ。知らせは父とゴルフ中に受け、クラブを放り投げて叫んだと笑う。手術は2001年9月12日の予定だったが同時多発テロで延期され、10月1日に無事成功したという。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（38:22〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2302s"]]}, {"cat": "体のこと", "t": "注射が大の苦手で気絶", "b": "注射針がとにかく苦手だという。妻の移植手術の直前、首の痛み止めの太い注射を打つ場面に付き添っていて、気づいたら床に倒れていたそうだ。医師に「今日の主役はあなたですか」とあきれられたと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（40:41〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2441s"]]}, {"cat": "暮らし", "t": "欠場は29年でわずか4回", "b": "自分は史上最高ではないが、仕事への姿勢だけは誰にも負けないと言い切る。29年間で番組を休んだのは4回だけだという。会社の健康保険のおかげで妻の移植ができ、2人の子を大学に行かせ、老後の備えもできたと感謝を語っている。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（42:24〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2544s"]]}, {"cat": "好きなもの", "t": "JBLに誘われ登山を始めた", "b": "世界七大陸最高峰を目指していたJBLに誘われ、音声スタッフの仲間と一緒に登山を始めたという。初挑戦のカリフォルニアの山は登頂できなかったが、すっかりはまったそうだ。ワイオミング州のグランドティトンは1度目、頂上まであと約25メートルで氷に阻まれたと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（44:02〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2642s"]]}, {"cat": "体のこと", "t": "グランドティトン下山中に滑落", "b": "2度目の挑戦で標高約4250メートルの頂上に立ち、妻とビデオ通話もしたという。ところが下山中、懸垂下降の直後に氷の岩で足を滑らせ、十数メートル転げ落ちて、約600メートルの崖の手前で止まったそうだ。ヘルメットで頭は守られたが足首を痛め、ヘリは2日来られないと言われて自力で下山したという。普段5時間ほどの下りに14時間かかり、足首は骨折ではなく重い捻挫だったと話す。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-EJssz47H41w", "src": [["公式YouTube（46:25〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=2785s"]]}]);
  if (PROFILES["John Bradshaw Layfield"]) PROFILES["John Bradshaw Layfield"].facts.push({"cat": "暮らし", "t": "ヒール時代は自分のグッズを売らせなかった", "b": "王者だった頃のJBLは、悪役の自分を応援するグッズを客席で着てほしくないとして、会社からの商品化の話を断っていたという。キャラクターになりきることの大切さを、その話で学んだと、マイケル・コールが話している。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で、マイケル・コールの話（公式字幕を全文確認）", "src": [["公式YouTube（17:37〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1057s"]], "by": "第三者の話"});
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "何年もシナのバスで移動した仲", "b": "毎週ジョン・シナのツアーバスに同乗して何年も一緒に移動し、親しい友人になったという。友人だからこそ本気で勝ってほしいと思って実況でき、その気持ちが感情として伝わるのだと、マイケル・コールが話している。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で、マイケル・コールの話（公式字幕を全文確認）", "src": [["公式YouTube（19:56〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1196s"]], "by": "第三者の話"});
  if (PROFILES["Jim Ross"]) PROFILES["Jim Ross"].facts.push({"cat": "暮らし", "t": "感情がこもるから史上最高", "b": "同じように物語を伝えていても、ジム・ロスはごく短い実況にも心からの感情がこもっていたから史上最高なのだという。駆け出しの頃は彼の口癖を真似して叫んでいたが、今聞くと恥ずかしいと、マイケル・コールが話している。", "sp": "マイケル・コール", "d": "2026-07-24", "how": "ステファニーの番組で、マイケル・コールの話（公式字幕を全文確認）", "src": [["公式YouTube（20:44〜）", "https://www.youtube.com/watch?v=EJssz47H41w&t=1244s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-EJssz47H41w", d: "2026-07-24", show: "wys", who: ["Michael Cole"], t: "マイケル・コールの回　報道記者から実況席へ、家族と山の話", lead: "ステファニー・マクマホンの番組に出た約52分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Michael Cole"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-EJssz47H41w").map((x) => [x.t, x.b, x.sp])), open: ["実況論（物語の伝え方、新人アナウンサーへの助言など）は素顔の項目から外した。", "ステファニーに平手打ちされた件など、番組内の出来事や筋書きにまつわる話は載せていない。", "妻の前の結婚にまつわる事情は、子どもがいたことだけにとどめた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=EJssz47H41w"]] });
  if (!ROSTER.find((r) => r[1] === "Peter Rosenberg")) ROSTER.push(["ピーター・ローゼンバーグ", "Peter Rosenberg", "lg", "", "", "", ""]);
  if (!PROFILES["Peter Rosenberg"]) PROFILES["Peter Rosenberg"] = { lead: "ESPNとWWEの両方で働くピーター・ローゼンバーグ。プロレスの話題が冷たく扱われていた頃から、局内で少しずつ居場所を作ってきた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Peter%20Rosenberg"]], moves: [], facts: [] };
  if (PROFILES["Peter Rosenberg"].lead === "ESPNとWWEの両方で働くピーター・ローゼンバーグ。プロレスの話題が冷たく扱われていた頃から、局内で少しずつ居場所を作ってきた。") PROFILES["Peter Rosenberg"]._weak = 1;
  PROFILES["Peter Rosenberg"].facts.push(...[{"cat": "暮らし", "t": "ESPNとWWEの両方で働く大会週", "b": "ESPNとWWEの両方で働いているので、ESPNがWWEの大会を放送すると決まったとき、自分もニュースで知ったと、ローゼンバーグは話す。今では大会の週は、ほぼ毎日の番組で宣伝役をこなしているという。忙しいが、良い方向に進んでいると感じているそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（2:20〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=140s"]]}, {"cat": "リングに来るまで", "t": "入社当時のESPNはプロレスに冷たかった", "b": "2015年にESPNに入った頃は、プロレスへの関心はほとんどなく、スポーツの横にプロレスを置くことを嫌がる人もいたと、ローゼンバーグは振り返る。デビッド・シューメーカーと始めたポッドキャスト「チープ・ヒート」は、知られている中で最初のプロレスのポッドキャストだったという。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（3:58〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=238s"]]}, {"cat": "リングの話", "t": "24/7王座を取った夜は一生の宝物", "b": "24/7王座を手にしたのは、自分にとって最高に楽しく意味のある夜だったと、ローゼンバーグは話す。冗談のような王座でも、歴史の記録に名前が残ったことがうれしいという。ロイヤルランブルの大会のさなかに奪い、丸1日近く持っていたそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（7:21〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=441s"]]}, {"cat": "リングの話", "t": "夢は解説席と、選手の代弁者", "b": "1年間、育成ブランドの大会で実況と解説を担当したと、ローゼンバーグは話す。いつかテレビで解説をしてみたいという。選手を見つけて代弁者として付く役割も夢だが、10年近く大会に関われただけで、もう夢はかなったと感じているそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（8:55〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=535s"]]}, {"cat": "リングに来るまで", "t": "新世代の取材者はサム・ロバーツと2人だけだった", "b": "会見の場に入り込んで選手に取材する新しい世代は、かつて自分とサム・ロバーツの2人だけだったと、ローゼンバーグは話す。批判も受けてきたが、最初からそこにいたのは事実だという。今では多くの媒体が取材に来るようになり、驚いているそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（10:25〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=625s"]]}, {"cat": "リングの話", "t": "シナに悪役転向をずっと問い続けてきた", "b": "ジョン・シナが長く善玉を続けたことには以前から疑問を持っていて、2008〜2010年ごろからシナ本人に悪役になる気はないかと尋ねてきたと、ローゼンバーグは話す。よく知られた映像で悪役転向について質問しているのも自分だという。コーディ・ローデスの悪役も、いつか早めに見てみたいそうだ。", "sp": "ピーター・ローゼンバーグ", "d": "2026-07-28", "how": "TMZスポーツの番組で（字幕を全文確認）", "art": "ext-YoGGBAt8Qwg", "src": [["番組のYouTube（15:53〜）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg&t=953s"]]}]);
  ARTICLES.push({ id: "ext-YoGGBAt8Qwg", d: "2026-07-28", show: "ext", who: ["Peter Rosenberg"], t: "ピーター・ローゼンバーグの回　ESPNとWWEの二刀流、24/7王座の思い出", lead: "TMZスポーツの番組に出た約23分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Peter Rosenberg"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-YoGGBAt8Qwg").map((x) => [x.t, x.b, x.sp])), open: ["番組の後半は、大会の予想や現役選手の扱いについての意見が中心で、その部分は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=YoGGBAt8Qwg"]] });
  if (!ROSTER.find((r) => r[1] === "Nick Aldis")) ROSTER.push(["ニック・オールディス", "Nick Aldis", "lg", "スマックダウンの元GM", "", "", ""]);
  if (!PROFILES["Nick Aldis"]) PROFILES["Nick Aldis"] = { lead: "英国出身で、長いあいだ世界のリングで戦ってきたニック・オールディス。若いころの苦労や家族への思いを、ユーモアを交えて語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Nick%20Aldis"]], moves: [], facts: [] };
  if (PROFILES["Nick Aldis"]._weak) { PROFILES["Nick Aldis"].lead = "英国出身で、長いあいだ世界のリングで戦ってきたニック・オールディス。若いころの苦労や家族への思いを、ユーモアを交えて語った。"; delete PROFILES["Nick Aldis"]._weak; }
  PROFILES["Nick Aldis"].facts.push(...[{"cat": "体のこと", "t": "一番の不安は筋肉ではなく試合の体力", "b": "ニック・オールディスは、今回の試合で最も心配したのは見た目ではなく持久力だったと話す。「見せる体」と「リングで動ける体」は別物で、自分には前者しかなかったと上層部に伝えたそうだ。この数週間は、筋肉を増やすより体脂肪を落として動けるようにすることに専念したという。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=98s"]]}, {"cat": "体のこと", "t": "サウジの絶品スイーツと食事制限", "b": "サウジアラビア遠征の食事が大好きで、昼食にはデザートの盛り合わせを楽しんでいたという。現役のころとの違いは、いまはデザートを自分に許していることだと笑って話す。帰国後は食事の準備も含めて、徹底した調整の生活に切り替えたそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（4:01〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=241s"]]}, {"cat": "暮らし", "t": "地元ジムの友人が鬼のトレーナーに", "b": "自宅のあるテネシー州ホワイトハウスの地元ジムに通っている。オーナーの友人「ブル」が、バーピーやケトルベルの猛特訓を見て、「ここからは自分が仕切る」と調整メニューを引き受けたという。そのメニューは相当きつかったと、ニックは笑いながら話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（6:31〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=391s"]]}, {"cat": "リングに来るまで", "t": "出番に備えて待てと言われていた", "b": "大きな舞台に立つ可能性が見えた時期に、ミッキーとランディ・オートンの二人から「数か月前ではなく数週間前に急に決まるから、準備だけはしておけ」と言われていたという。ニック自身は何も売り込まず、起きることは起きると考えて待っていたと話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（7:18〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=438s"]]}, {"cat": "リングの話", "t": "ただの試合ではなく本物の感情がある", "b": "WWEでの初戦の相手に、ニックは、自分が受けられなかった機会を象徴するグンターを挙げる。他の候補との試合なら「試合をしよう」で終わったが、この相手には本物の感情がある実際の抗争だと感じているそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（9:36〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=576s"]]}, {"cat": "リングの話", "t": "グンターとは昔から互いを認め合っていた", "b": "NWAの王者として活動していた頃、ファンの間でグンター(当時はウォルター)との夢の対戦がよく話題になったという。グンターは当時ニックの活動を評価し、SNSやDMで応援の言葉を送ってくれたそうだ。体格もほぼ同じで、考え方も近いとニックは話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（12:53〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=773s"]]}, {"cat": "リングの話", "t": "経歴を見せて初見のファンに伝えたい", "b": "幹部のスーツ姿のGMしか知らないファンも多いため、ニックは自分の経歴を紹介する映像が必要だと考えているという。TNAやNWAとも良い関係があるので、協力して内容のある紹介を作れるはずだと話す。あとは試合で見せるだけだと言う。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（14:31〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=871s"]]}, {"cat": "リングの話", "t": "「信じさせる」が第一のルール", "b": "二人とも古風と言われるが、ニックはただ基準が高いだけだと話す。レスリングで一番大切なのは、自分が信じていれば観客も信じるという点だという。観客に目配せするような「第四の壁」を崩す演出は、手軽に反応を取れるので増えたが、真剣に見せる方が難しいと語る。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（16:02〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=962s"]]}, {"cat": "体のこと", "t": "2年悩んだ腰痛の原因は炎症だった", "b": "GMになったのは負傷のためだという噂を否定している。ただ、休めたおかげで腰の不調に向き合えたという。椎間板ヘルニアだと思い込んでいたが、専門医の診断では背骨の深部の筋肉の強い炎症で、抗炎症薬ですぐに治ったそうだ。ニックは、不調を見ないふりをしていた自分を頑固だったと振り返る。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（20:45〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1245s"]]}, {"cat": "リングに来るまで", "t": "21歳でTNAと契約、早すぎた大抜擢", "b": "ニックは21歳でTNAと契約し、まだ準備ができていない位置に立たされたと話す。その後TNAを離れて苦しい時期を過ごし、WWEにも相手にされなかったという。グンターのように推してくれる人がいなかった悔しさは、今回の抗争の本物の感情の源だと語る。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（27:18〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1638s"]]}, {"cat": "リングに来るまで", "t": "NWAでゼロから築いた足場", "b": "後ろ盾がないまま、NWAと「10ポンズ・オブ・ゴールド」のシリーズで自分の道を切り開いたという。その約1年後にコーディと満員の会場で向き合えたことを、自分の仕事が認められた瞬間だと振り返る。ニックは、あの試合は終盤はコーディの瞬間でも、始まりは自分の瞬間だったと主張する。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（28:05〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1685s"]]}, {"cat": "リングに来るまで", "t": "裏方から始まったWWEへの道", "b": "DDPの助言で、ハンターへ直接連絡を取ったが、しばらく何も起きなかったという。やがてブルースから舞台裏の仕事に誘われ、その後にGMの役を任されたそうだ。今回の試合は、その長い道の先にある確かな証明だと話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（29:00〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1740s"]]}, {"cat": "リングに来るまで", "t": "毎週大西洋を往復した若手時代", "b": "TNAと最初に契約したころは、英国から米国と欧州を行き来する過酷な移動が続いたという。帰宅した日、あまりの疲れに目を開けたまま眠り、当時の恋人を死んだと驚かせたそうだ。それが引っ越しを決めた出来事だったと話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（30:31〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1831s"]]}, {"cat": "リングに来るまで", "t": "移動費を材料に保証契約を勝ち取る", "b": "1年分の渡航費が約7万ドルだったと計算し、それを保証にして米国へ引っ越したいとTNAに交渉したという。22歳の若者としては強気な申し出で、最初は断られたが、上層部が介入して希望通りになったそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（33:08〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=1988s"]]}, {"cat": "リングに来るまで", "t": "WWEに連絡したが電話を切られた", "b": "交渉が難航していた時期にWWEの担当者へ連絡すると、「すぐ電話を」と返信が来たという。ところが契約中だと話すと、会話は打ち切りになった。その後TNAに辞意を伝えると、数時間で望み通りの条件が提示されたそうだ。契約が切れた後もリーガルに連絡したが、実現しなかった。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（34:47〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2087s"]]}, {"cat": "リングの話", "t": "悪役ではなく芯のあるGMに", "b": "ハンターは、悪役のGMは前例が多いので望まず、ニックの体格を生かすよう求めたという。初期には、GMは選手より小さく見せるべきだという意見もあったそうだ。ポール・ヘイマンがその空気を変えてくれたと、ニックは話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（38:52〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2332s"]]}, {"cat": "リングの話", "t": "ローマン・レインズとのソファの場面", "b": "ニックは、あの数分間が自分の役を決定づけたと話す。ローマンは表情も間も一つ一つ考え抜く完璧主義者で、対等に扱ってくれたことに深く感謝しているという。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（40:30〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2430s"]]}, {"cat": "リングの話", "t": "指示に逆らったヘイマンとの生放送", "b": "ランディ・オートンの登場前、ニックが後ろに立つよう指示されていた場面で、ヘイマンは「近づいたら立て」とだけ囁いたという。ニックは従うほかなく、結果は大成功だった。その日初めてビンス・マクマホンに会い、叱られると思っていたが、とても丁寧に褒められたそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（41:18〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2478s"]]}, {"cat": "リングの話", "t": "「幹部に感情はない」の名台詞は即興", "b": "ローマンとのやりとりで、相手の皮肉への返しとして思いつき、役の核になったと話す。冷たく洗練された幹部を作るために、「スーツ」や「サクセッション」といったドラマを見て参考にしたという。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（44:21〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2661s"]]}, {"cat": "リングの話", "t": "オートンのRKOと「最後の一人」の言葉", "b": "最後の試合は2023年10月7日だったと話す。先日のバックラッシュではオートンのRKOを最初に受けた一人で、後でオートンから「最初の一人が君で良かった」と声をかけられたそうだ。ニックは、オートンとの仕事が大好きだと語る。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（49:16〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2956s"]]}, {"cat": "リングに来るまで", "t": "自分から売り込まなかった理由", "b": "ニックは、制作側に入るときも、GMのときも、試合の機会を頼んだことは一度もないという。ハンターに「どんな形でも貢献したい」と伝えた言葉を守るため、口を閉ざしていたそうだ。今回の起用は、グンターの相手として商売になると判断されたのだろうと見ている。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（51:01〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=3061s"]]}, {"cat": "好きなもの", "t": "子どものころはWWF一筋", "b": "子どものころの英国では、WWFが他団体を圧倒していたという。10歳のころ、WCWが全盛でも自分にとってはWWFだけが本物だったと振り返る。入場の衣装がスーツか普段着かといった観客の想像も、レスリングの魅力の一部だと考えているそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（54:14〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=3254s"]]}, {"cat": "リングの話", "t": "初めて見る人に勧める一戦", "b": "自分の試合を知らないファンには、NWA70周年のコーディとの再戦(3本勝負)を勧めたいという。1本目は技術、2本目は場外戦、3本目は大技の応酬と、全部が詰まった王道の一戦だったそうだ。解説陣も豪華だったと話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（59:00〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=3540s"]]}, {"cat": "リングに来るまで", "t": "AJスタイルズ戦は消したい記憶", "b": "TNAでのAJの最後の試合の相手になったことは、不名誉な役回りだったとニックは話す。ファンの悲しみがぶつけられたことが、自分の評価を傷つけたと感じているそうだ。今回の抗争で初めてその過去が役に立っていると笑う。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:06:23〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=3983s"]]}, {"cat": "リングに来るまで", "t": "スティングが目をかけてくれた", "b": "2009年、入社3か月ほどの若手だったニックを、スティングが対戦相手に指名したという。短い試合で相手の見せ場を引き立てたことが、ベテランからの信頼につながったそうだ。4年後の大舞台では、スティングが自らの意思で負けを選び、ニックに箔をつけてくれたと感謝を込めて話す。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:08:48〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=4128s"]]}, {"cat": "リングに来るまで", "t": "TNA時代は自分探しの連続", "b": "役を任されるたびに路線が変わり、自分らしいスタイルを築く余裕がなかったと話す。本当の意味で上達したのはTNAを離れてからで、いまは自分で作り上げた形を大舞台で見せたいのだという。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:20:09〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=4809s"]]}, {"cat": "リングに来るまで", "t": "17歳でデビュー、独立系で積んだ下積み", "b": "17歳でデビューし、18歳で専業のレスラーになったという。主に善玉役を演じ、観客を引き込む技術は身についたが、試合の組み立てや自分のスタイルはまだなかったそうだ。その後、テレビ番組「グラディエーターズ」に出演した。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:21:45〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=4905s"]]}, {"cat": "暮らし", "t": "家族の夏休みを犠牲にして臨む", "b": "毎年楽しみにしていた南フランスへの家族旅行を、この試合のために諦めたという。息子に事情を説明するのはつらかったが、今年は静かな夏になると話したそうだ。妻のミッキーにも大きな負担をかけていると語る。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:26:51〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=5211s"]]}, {"cat": "暮らし", "t": "息子が撮るトレーニング映像", "b": "息子は映画編集アプリで動画を作るのが好きで、父の過酷なトレーニングを撮影してくれているという。夜遅くや朝5時でもついてくるそうだ。ニックは、いつか素材を使って何か作りたいと考えている。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:30:14〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=5414s"]]}, {"cat": "暮らし", "t": "自覚が武器になる", "b": "ニックは、自分に何があり何が足りないかを知る自覚が、以前より身についたと話す。自分を偽らないことが、今回の物語が見る人の共感を呼んだ理由だと考えているそうだ。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-1xShAW169HA", "src": [["番組のYouTube（1:31:54〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=5514s"]]}]);
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "オートンとの関係", "b": "ランディ・オートンは、ニックに「備えておけ、急に決まる」と助言し、バックラッシュでは最初のRKOを受けた彼に温かい言葉をかけたと、ニック・オールディスが話している。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で、ニック・オールディスの話（字幕を全文確認）", "src": [["番組のYouTube（41:18〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=2478s"]], "by": "第三者の話"});
  if (PROFILES["R-Truth"]) PROFILES["R-Truth"].facts.push({"cat": "暮らし", "t": "アール・トゥルースと笑いが止まらない", "b": "アール・トゥルースは収録外でも面白く、台本にない即興で場を笑わせる唯一無二の人だと、ニック・オールディスが話している。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で、ニック・オールディスの話（字幕を全文確認）", "src": [["番組のYouTube（1:13:39〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=4419s"]], "by": "第三者の話"});
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "帽子を逆に被る場面", "b": "ジョン・シナの帽子を逆向きにする仕草は、野球の監督と審判のやりとりを真似た即興で、ファンが深読みしすぎだと、ニック・オールディスが話している。", "sp": "ニック・オールディス", "d": "2026-07-30", "how": "クリス・ヴァン・ヴリートの番組で、ニック・オールディスの話（字幕を全文確認）", "src": [["番組のYouTube（1:16:52〜）", "https://www.youtube.com/watch?v=1xShAW169HA&t=4612s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-1xShAW169HA", d: "2026-07-30", show: "ext", who: ["Nick Aldis"], t: "ニック・オールディスの回　初の大舞台を前に語る素顔", lead: "クリス・ヴァン・ヴリートの番組に出た約94分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Nick Aldis"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-1xShAW169HA").map((x) => [x.t, x.b, x.sp])), open: ["番組の宣伝や、次の大会の意気込みだけの話は省いた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=1xShAW169HA"]] });
