  if (PROFILES["Chad Gable"].lead === "") PROFILES["Chad Gable"]._weak = 1;
  PROFILES["Chad Gable"].facts.push(...[{"cat": "リングの話", "t": "エル・グランデ同士の一戦は期待を超えた", "b": "エル・グランデ・アメリカーノ対エル・グランデ・アメリカーノについて、チャド・ゲイブルは試合が終わるころには特別なものになったと確信していたと話す。高い期待で臨んだが、それを上回る出来だったという。仲間のレスラーから、この試合でレスリングを好きになった理由を思い出したと言われたのが何よりうれしかったそうだ。称賛が多すぎて落ち着かなくなるほどだったとも語っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（4:50〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=290s"]]}, {"cat": "リングの話", "t": "試合終盤に訪れた静かな確信", "b": "試合の終盤、頭から流れた血でマットが染まっているのを見て、観客が山場を待つ静けさに包まれているのを感じたという。その瞬間にチャドは「やりきった」と思ったそうだ。子どものころからファンとして憧れてきた、あの魔法のような試合をつくれたと感じた瞬間だったと話す。まるで嵐の目の中にいるような穏やかさだったという。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（7:57〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=477s"]]}, {"cat": "リングの話", "t": "本戦初の試合でダイヴァリに肘を食らう", "b": "メイン・ロースター入り後、最初の試合は自分の誕生日のハウスショーだったという。相手のダイヴァリにロープへ振られた際、「走り続けるな」と声をかけられたが聞き取れず、そのまま相手の肘に突っ込んでしまった。大きく皮膚がめくれて血が噴き出し、試合は途中で切り上げになったそうだ。履いていた黄色いブーツは父のお下がりだったと振り返っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（9:29〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=569s"]]}, {"cat": "リングの話", "t": "自分が作ったキャラを引き継いだ相手への思い", "b": "マスクマンのキャラを自分が築いたのに、別の人間がそれを引き継いだことには、最初はひっかかりがあったと話す。しかしチャドは、その相手がキャラを最高の形に育てたことを認めている。同じ立場に置かれて不平を言う選手を何度も見てきたが、相手は正反対の姿勢で金に変えたと称賛している。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（20:27〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1227s"]]}, {"cat": "リングの話", "t": "アンダーテイカーの言葉で何かがつながった", "b": "チャドは、アンダーテイカーに長く期待に応えられていない気がして悩んでいたという。ある日、舞台裏で彼から熱い言葉をかけられ、その直後のエル・グランデとのリングサイドの乱闘で何かがはまったそうだ。数分間、グレコローマンのレスラーに戻ったように我を忘れたという。「大事なものを盗まれたらどうするか」と考えろという趣旨の助言が、役の怒りを引き出す鍵になったと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（23:37〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1417s"]]}, {"cat": "リングの話", "t": "JB・ボラッシュとの創作は驚くほど自由", "b": "ミネソタ出身の仲間として、JB・ボラッシュの名前を挙げた。チャドは、アイデアを出すだけでなくこちらの案にも開かれていて、これまでにない形で共同作業ができたと語る。この件は全員でつくった共同作品のようなものだったそうだ。コミュニケーションが取りやすく、一緒に仕事ができてよかったと話している。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（28:20〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1700s"]]}, {"cat": "リングの話", "t": "ショーティ・Gは最初から袋小路だと感じていた", "b": "ショーティ・Gの企画は、エリック・ビショフから伝えられたと話す。チャドは最初から行き詰まりを感じ、「うまくいく」という顔をしながらも、内心では終わりになるかもしれないと思っていたという。自分でその名を名乗った最初のプロモは自分にとって最も落ち込んだ時期だったが、ルーク・ハーパーから届いた励ましのメッセージにずいぶん救われたと話している。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（32:11〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1931s"]]}, {"cat": "リングの話", "t": "NXT黒と金の時代とジェイソン・ジョーダンとの相棒関係", "b": "チャドは、2015〜16年ごろのNXTを、才能が集まり互いに競い合う特別な場だったと振り返る。ジェイソン・ジョーダンとは、アマレス出身の同じ考え方を持つ理想の相棒で、兄弟のように気が合ったそうだ。リバイバルとのライバル関係では、毎晩相手を上回ろうとする本気の競争心があり、あれ以降は感じたことがないという。フロリダの小さなハウスショーでも、三本勝負で30〜40分の試合をやっていたと話している。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（37:55〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2275s"]]}, {"cat": "リングの話", "t": "次の目標は単独のタイトル獲得", "b": "チャドは、ここまでの実績がタッグ中心なので、自分への証明として単独の王座を獲る必要があると話す。公言したことは必ずやり遂げるのが自分の強みで、テレビでインターコンチネンタル王座について神に誓って獲ると言ったことがずっと胸に重くのしかかっているそうだ。それを果たすのが次の一歩だと語っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（45:07〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2707s"]]}, {"cat": "リングの話", "t": "ガンターとの抗争を自分で動かした日々", "b": "ガンターとの抗争が単独王座につながると期待し、チャドは意欲に満ちていたという。ビデオ演出も自分でつくり、ライブイベントでも手応えがあったが、結果的にそこまでだったと話す。会社から先の計画を聞かされていたわけではなく、できることを全部やったうえで受け入れたそうだ。のちにエル・グランデ・アメリカーノでも、マスクを着けた瞬間に解放された気分になり、入場で踊るほどだったと語っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（58:37〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3517s"]]}]);
  if (!ROSTER.find((r) => r[1] === "Chad Gable")) ROSTER.push(["チャド・ゲイブル", "Chad Gable", "lg", "グレコローマン出身の技巧派", "", "", ""]);
  if (!PROFILES["Chad Gable"]) PROFILES["Chad Gable"] = { lead: "家では妻と子どもたちの「ただの父親」でいたいという。幼い頃からグレコローマンに打ち込み、人のせいにせず自分で責任を取る姿勢をレスリングから学んだと語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Chad%20Gable"]], moves: [], facts: [] };
  if (PROFILES["Chad Gable"]._weak) { PROFILES["Chad Gable"].lead = "家では妻と子どもたちの「ただの父親」でいたいという。幼い頃からグレコローマンに打ち込み、人のせいにせず自分で責任を取る姿勢をレスリングから学んだと語る。"; delete PROFILES["Chad Gable"]._weak; }
  PROFILES["Chad Gable"].facts.push(...[{"cat": "家族", "t": "子どもにとっては「ただのパパ」", "b": "最初の子が生まれたときには、すでにメインロスターに上がっていたという。そのため子どもたちは父がWWEの選手であることを特別なことと思っておらず、家で番組を見ることもないそうだ。会場に行くのは好きでも、家ではWWEの話をされることはほとんどなく、本人もそれでいいと話す。家族は自分のすべてだという。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（11:01〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=661s"]]}, {"cat": "家族", "t": "妻とは高校時代からの仲", "b": "結婚して12年、付き合い始めてからは20年以上になるという。妻が高校2年、自分が3年のときからの付き合いで、いわゆる高校時代の恋人同士だそうだ。長続きの秘けつを聞かれると、正直で開かれた話し合いだと答えている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（11:47〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=707s"]]}, {"cat": "リングに来るまで", "t": "最後に始めたグレコローマンにほれ込む", "b": "アマチュアレスリングの3つのスタイルの中では、迷わずグレコローマンが好きだという。始めたのは3つの中で最後、小学5年生ごろだったそうだ。もともと上半身が強く、相手を投げるのに必要な腰の使い方が最初から身についていたと話す。父もその素質に気づき、以来それだけを追いかけてきたという。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（12:32〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=752s"]]}, {"cat": "好きなもの", "t": "6歳の息子に見せたレスリング映画", "b": "子どもにアマチュアレスリングを好きになってもらうなら、高校レスリングを描いた1980年代の青春映画『ビジョン・クエスト』を勧めるという。今年、6歳の息子に見せたところ、とても気に入ってくれたそうだ。幼い子には少し早い場面もあってためらったが、競技の魅力が伝わったと話す。今でも最高のアマレス映画だと考えている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（14:50〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=890s"]]}, {"cat": "リングに来るまで", "t": "少年時代のコーチが戦った伝説の一戦", "b": "心に残る試合として、少年時代のコーチの一人ブランドン・ポールソンが2004年の五輪代表を懸けて戦ったグレコローマンの決勝を挙げる。延長を重ねても決着がつかず、審判が時計を何度も戻して30分以上続いたという。観客は総立ちで拍手を送り、試合後は両者が血だらけで泣きながら抱き合っていたそうだ。レスリングが人生に与えてくれるものの象徴だと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（17:11〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1031s"]]}, {"cat": "暮らし", "t": "人のせいにしない姿勢はレスリングから", "b": "結果の責任はすべて自分にある、というアマチュアレスリングの考え方が今も身についているという。そのおかげで、人生でたいていのことを外のせいにせずに済んできたそうだ。自分の状況はたいてい自分で何とかできるものだと考えていると話す。誰かのせいにするのは簡単なので、それなりの誠実さが要るとも語っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（19:42〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1182s"]]}, {"cat": "リングに来るまで", "t": "コーチを喜ばせたい性分", "b": "アマチュアレスリングを通じて、いつも尊敬するコーチがそばにいたという。そうした人たちを満足させ、求められるものを出したいという気持ちが強いそうだ。自分は目に見える進歩がないと落ち着かない性格だとも話している。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（23:37〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1417s"]]}, {"cat": "リングに来るまで", "t": "ブルガリア出身の厳しい恩師", "b": "初めて本格的に教わったグレコローマンのコーチは、ブルガリア出身の厳しい人だったという。黙って練習をやり抜くこと、口答えせず耐えることを、ほぼすべて教わったそうだ。家族のために異国で生活を築きながら選手を率いる姿を見て、特別なことを成し遂げるには一段上の努力が要ると知ったと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（29:07〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1747s"]]}, {"cat": "家族", "t": "おいの縁でスペシャルオリンピックス大使に", "b": "おいがてんかんを抱えていて、スペシャルオリンピックスに熱心に取り組んでいるという。その縁で、最近ミネソタ州のスペシャルオリンピックスで大使を務めたそうだ。選手たちを応援し、そばにいられたことは、ここ数年でいちばんやりがいのある経験だったと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（31:26〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1886s"]]}, {"cat": "リングに来るまで", "t": "「ショーティ・G」時代は八方ふさがり", "b": "「ショーティ・G」と名乗っていた時期について、最初から身動きが取れないと感じていたという。表向きは「これでいける」という顔をして全力で取り組んだが、内心ではキャリアの致命傷になりかねないと思っていたそうだ。自分をその名で呼んだ最初のプロモの後は、まさにどん底だったと振り返る。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（32:11〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1931s"]]}, {"cat": "リングに来るまで", "t": "NXTの黄金期と、観客100人の長期戦", "b": "2015〜16年ごろのNXTは、限られた場所で何かが生まれている特別な空気があったという。仲間であると同時に誰もが一番を競い合っていて、その熱が魔法を生んだそうだ。当時はフロリダ州内の100人ほどの会場でも、3本勝負で30〜40分戦うことがあり、その頃のハウスショーがいちばん好きな試合だったと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（37:55〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2275s"]]}, {"cat": "体のこと", "t": "名勝負を流しながら傾斜15の走り込み", "b": "有酸素運動では、60分の長期戦の名勝負を選び、ルームランナーの傾斜を15まで上げて試合が終わるまで歩き続けることがあるという。ブレット・ハートとショーン・マイケルズの一戦などを流すそうで、時には60分になる。自宅にトレーニングジムがあり、そこで鍛えている最中に急な出場の電話を受けたこともあったと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（41:10〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2470s"]]}, {"cat": "暮らし", "t": "口に出したことは必ず実現させる", "b": "一度公に宣言したことは、何としてもやり遂げるのが自分の流儀だという。アマチュアの大会のタイトルでも、WWEに入ることでも、そうやって実現してきたそうだ。どうやって形になるかは分からなくても、言った以上は見届けるのが自分の強みだと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（45:52〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2752s"]]}, {"cat": "家族", "t": "弟の対戦相手だったオーティス", "b": "オーティスとは20年近い付き合いで、もとはアマチュアレスリングで自分の弟と対戦していた相手だという。当時は自分がコーチとして、弟の側から彼と向き合っていたそうだ。オーティスの早口が両親にはまったく聞き取れないため、父には「うなずいておけば大事なことは自分が伝える」と教えたと笑う。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（50:38〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3038s"]]}, {"cat": "好きなもの", "t": "壁一面のビデオを集めた少年時代", "b": "少年時代は試合ビデオを交換し合う、筋金入りのコレクターだったという。部屋の壁は録画テープで埋まり、ラベルも全部自作して、郵送でやり取りしていたそうだ。今も当時のヒーローである小橋建太や獣神サンダー・ライガー、スタン・ハンセンの試合を見返していると話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（53:03〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3183s"]]}, {"cat": "好きなもの", "t": "ライガーにあこがれて厚着で練習", "b": "子どもの頃からライガーが大好きだったという。背は低くがっしりしているのに、軽量級の選手のように動く体つきにあこがれたそうだ。アマチュアレスリングの仲間と、ライガーの分厚い体型をまねて、着ぶくれするほど厚い練習着を着ていたと話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（55:26〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3326s"]]}, {"cat": "暮らし", "t": "13年間、仕事を家に持ち帰ってきた", "b": "グンターとの抗争のころ、映像を自主制作するなど、自分でできることは何でもやったという。いくら努力しても結果が出るとは限らない世界だと受け入れたが、働き方は変えていないそうだ。今も友人と次の映像を計画中で、この仕事のことは13年間ずっと家に持ち帰っていると話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（59:23〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3563s"]]}, {"cat": "リングに来るまで", "t": "「相棒を引きずり下ろすな」と言われて", "b": "これまでのタッグパートナーはいつも自分より上だと見られ、ある時は「彼の足を引っ張るな」とはっきり言われたこともあったという。そのため相手と張り合ってきたが、いざ追い越したと感じたときは、少しもうれしくなかったそうだ。他人ではなく、自分の予想を超えたときこそ毎回報われると話す。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（1:04:11〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3851s"]]}, {"cat": "好きなもの", "t": "大のコーヒー好き", "b": "自分と同じくらいコーヒー好きな仲間として、ベイリーの名前を挙げる。同じNXT世代で、仕事への没頭ぶりも同じくらいで、趣味もいろいろ共通しているそうだ。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（1:06:37〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3997s"]]}, {"cat": "好きなもの", "t": "美大出身、海外巡業で写真対決", "b": "美術系の学校に通っていたという。海外巡業ではサミ・ゼインやエグゼビア・ウッズと、同じ被写体を撮って選手仲間の投票で競う写真コンテストを開いたそうで、いちばん大切な思い出の一つだと話す。優勝はサミに譲ったが、美大出身として彼の作品は「ホテルに飾ってある絵以下」だと冗談まじりに語っている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（1:08:15〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=4095s"]]}]);
  if (PROFILES["Otis"]) PROFILES["Otis"].facts.push({"cat": "暮らし", "t": "誰より真の友", "b": "とにかく爆発的で、恐ろしいほど力の強いアスリートだと、ゲイブルが話している。数年前のロイヤルランブルで受けた一撃の重さは、今もあごに残っている気がするそうだ。虫も殺さない優しい人柄で、「いちばん真の友」だという。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で、チャド・ゲイブルの話（公式字幕を全文確認）", "src": [["公式YouTube（51:24〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3084s"]], "by": "第三者の話"});
  if (PROFILES["Luke Harper"]) PROFILES["Luke Harper"].facts.push({"cat": "暮らし", "t": "どん底の夜にくれた励まし", "b": "ショーティ・Gを名乗った最初のプロモの直後、ルーク・ハーパーからすぐに励ましのメッセージが届いたと、ゲイブルが話している。どん底の気分だったが、そのおかげで重荷がかなり軽くなり、一生忘れないという。メインロスターに上がった時から、必要以上に優しくしてくれた一人だったそうだ。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で、チャド・ゲイブルの話（公式字幕を全文確認）", "src": [["公式YouTube（33:49〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2029s"]], "by": "第三者の話"});
  if (PROFILES["Jason Jordan"]) PROFILES["Jason Jordan"].facts.push({"cat": "暮らし", "t": "最初から兄弟のようだった相棒", "b": "アメリカン・アルファで組んだジェイソン・ジョーダンとは、アマチュアレスリング出身同士で考え方がまったく同じ、完璧なパートナーだったと、ゲイブルが話している。出会った日から兄弟のように気が合ったという。理想のチームにも真っ先に名前を挙げている。", "sp": "チャド・ゲイブル", "d": "2026-07-30", "how": "コーディの番組で、チャド・ゲイブルの話（公式字幕を全文確認）", "src": [["公式YouTube（38:41〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2321s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "誕生日の初試合で流血", "b": "WWEでの最初の試合は、テレビデビュー前のハウスショーで、ちょうど自分の誕生日だったという。対戦相手ダイバリの合図が聞き取れずにロープへ走り、肘打ちをまともに受けて額がぱっくり割れたそうだ。履いていた黄色いブーツは父のおさがりだったと振り返る。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（9:29〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=569s"]]}, {"cat": "リングに来るまで", "t": "ジョージアから一人で参加したキャンプ", "b": "育ったジョージア州は野球が盛んで、アマチュアレスリングは競争が激しい土地ではなかったという。大学でも続けることを考えて参加したレスリングキャンプでは、州ごとに呼ばれて四つんばいで歩く練習の際、ジョージアからは自分一人だけで、気まずい思いで往復したそうだ。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（13:19〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=799s"]]}, {"cat": "家族", "t": "父が重んじたのはトーナメント", "b": "父は団体戦にはあまり関心がなく、大事なのは個人のトーナメントだという考えだったという。本人は負けても握手をして引き上げる「良い負け方」を身につけたそうだ。勝っても負けても自分の責任というアマチュアレスリングの厳しさが好きだったと話す。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（18:53〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=1133s"]]}, {"cat": "家族", "t": "アイアンマン戦で父に抑えられた夜", "b": "子どもの頃、ブレット・ハートとショーン・マイケルズの60分戦を見て、決着がつかない展開に思わず声を上げ、父にぎゅっと抑えられたという。家族の影響で昔ながらのルールを知っていたので、延長戦にもすぐ反応したそうだ。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（41:57〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=2517s"]]}, {"cat": "暮らし", "t": "ロープワークは並走で教える", "b": "自身の養成所の子どもたちにロープワークを教えるときは、一緒に並んで走って感覚をつかませるという。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（57:01〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3421s"]]}, {"cat": "リングに来るまで", "t": "同僚6人と比べたリスト", "b": "スターダストになる前、同僚6人の名前を紙に書き、それぞれ自分より優れている点を書き出したことがあるという。ドルフ・ジグラーには「腹筋」と書くなど他愛ないものだったそうだ。ただ、他人ではなく自分自身と競い始めてから、ようやく手応えをつかめたと話す。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（1:02:34〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=3754s"]]}, {"cat": "暮らし", "t": "海外巡業でもホテルから出ない", "b": "海外巡業では、ホテルからあまり出たがらないタイプだという。そのため、選手仲間が開いた写真コンテストの展示が、訪れた街の景色をいちばんよく見た機会だったそうだ。優勝したサミ・ゼインの写真に冗談でサインを頼んだら真剣な手紙が書かれていて、今もかばんに入れていると話す。", "sp": "コーディ・ローデス", "d": "2026-07-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-IccHlqazp7I", "src": [["公式YouTube（1:08:15〜）", "https://www.youtube.com/watch?v=IccHlqazp7I&t=4095s"]]}]);
  ARTICLES.push({ id: "wdywta-IccHlqazp7I", d: "2026-07-30", show: "wdywta", who: ["Chad Gable", "Cody Rhodes"], t: "チャド・ゲイブルの回　グレコローマンで育った責任感と、高校時代からの家族", lead: "コーディ・ローデスの番組に出た約71分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Chad Gable", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-IccHlqazp7I").map((x) => [x.t, x.b, x.sp])), open: ["覆面キャラクター「エル・グランデ・アメリカーノ」に関する話（同士の一戦の手応え、マスクをかぶって解放された感覚など）は役柄・筋書きとして載せていない。", "ジ・アンダーテイカーやAAAの制作陣から受けた指導の話、王座への意気込みは、仕事・筋書きの話として省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=IccHlqazp7I"]] });
  if (!PROFILES["Brie Bella"]) PROFILES["Brie Bella"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Brie%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Brie Bella"].lead === "") PROFILES["Brie Bella"]._weak = 1;
  PROFILES["Brie Bella"].facts.push(...[{"cat": "リングの話", "t": "復帰して知った、子どもに見られる側の気持ち", "b": "ブリーは、今回の復帰は以前と感覚が違うと話す。かつてステファニーと戦ったとき、ステファニーの娘たちが母をスーパーヒーローのように見ていたのが印象に残っているそうだ。当時の自分は子どもを意識していなかったが、今はバーディとバディが自分を見る目を感じられるという。バーディはすでにロイヤルランブルを何度か会場で観たと話している。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（5:34〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=334s"]]}, {"cat": "リングの話", "t": "ロッカールームでZ世代の言葉についていけない", "b": "ブリーは、ロッカールームで若い選手たちの使う言葉が分からず、意味を知って自分でも使いたくなると話す。ところがニッキーと二人で使ってみても「やっぱり無理」となり、ちょっとずれてしまうそうだ。若い世代にはそれがおかしく見えるらしく、大きく目を回されるという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（29:51〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=1791s"]]}, {"cat": "リングの話", "t": "SNSの声に傷つく若手へのひとこと", "b": "ブリーは、ロッカールームでは若い選手ほどSNSのコメントに強く影響されると感じている。数週間前には何人かの女子選手に、投稿者はその人の事情を知らないし、素晴らしいコメントが200件あれば悪いのは数件だけだと伝えたそうだ。ビジネスの感覚で割合を見れば9割以上に好かれているのだから大丈夫、という考えだという。アカウントを閉じる選手もいると聞き、胸が痛むと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（58:34〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=3514s"]]}, {"cat": "リングの話", "t": "「辞める」の平手打ちは力みすぎた", "b": "ブリーは、ステファニーとのストーリーの中で「辞める」と言って平手打ちをする場面が自分の一番の見せ場だったと振り返る。集中しすぎて、叩いた瞬間に「やばい」と思ったそうだ。そのとき歯を食いしばっていたとも話している。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:22:43〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=4963s"]]}, {"cat": "リングの話", "t": "ステファニーとの共演で学んだトップレベルの世界", "b": "ブリーは、ステファニーと同じストーリーに入るとき、台無しにしたくなくて相当緊張したと話す。ステファニー、トリプルH、ブライアンが話し合う様子を間近で見て、「これがトップレベルの考え方か」と感じたそうだ。その場にいるだけで多くを学べた、と振り返っている。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:25:07〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5107s"]]}, {"cat": "リングの話", "t": "台本に縛られない即興がいちばん楽しい", "b": "ブリーは、うまくいったときの即興が一番楽しいと話す。最近のライブイベントでは、ペイジとドミニクを相手に即興のやりとりをして、観客も大きく沸いたそうだ。そこへオバが登場し、そのままリングまで一緒に歩く展開になったという。テレビでは見られない場面だったが、ペイジと「こんなに楽しいのは久しぶり」と話し合ったそうだ。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:25:52〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5152s"]]}, {"cat": "リングの話", "t": "息子に見せたくて戻った、鍛え直しの日々", "b": "ブリーは、自分に挑戦したい気持ちと、息子のバディがレスラーとしての自分を見たことがない点が復帰の理由だと話す。今の女子のレベルは驚くほど高いので、トレーニングを一から変えたそうだ。ボクシングを始め、ほぼ毎日ブライアンと練習し、もともとヨガやピラティス中心だったのに筋力トレーニングにも取り組んだという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:37:47〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5867s"]]}, {"cat": "リングの話", "t": "プロレスは家族、離れても恋しくなる", "b": "ブリーは、ワインブランドやポッドキャストなど自分の活動はあるものの、プロレスからは本当には離れられないと話す。大きな家族のような世界で、長く離れても戻りたくなるそうだ。戻ってみて、年齢に関係なく心から取り組めば何でもできると教わった、と語っている。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:38:37〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5917s"]]}, {"cat": "リングの話", "t": "ニッキーの骨折と、ペイジとのタッグ", "b": "ブリーは、レッスルマニアの2週間前にニッキーが足首を骨折し、自分も出なくていいかもしれないと考えたと話す。しかし、ペイジが加わる案を聞いて「もう一人の姉妹ができる」と興味が湧いたそうだ。シングルと違ってタッグは動く要素が多いとペイジに伝えたが、一緒に戦って楽しかったという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:39:22〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5962s"]]}, {"cat": "リングの話", "t": "ペイジとは似た者同士、ベラ・ツインズの宿題はまだ残る", "b": "ブリーは、ペイジはゴシックな雰囲気だが、お互いを似ていると感じていて、リアリティ番組に出ていた頃から通じるものがあったと話す。ニッキーが戻ってくる日にまたリングで組みたいとも語る。二人で試せたのはほんの少しなので、ベラ・ツインズにはまだ証明すべきことがあると考えているそうだ。ライブ後に深夜2時に就寝して翌日のテレビに向かうような日もあるが、自分が諦めなかったことを誇りに思うという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:40:07〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6007s"]]}, {"cat": "リングの話", "t": "40代でリングに戻るとは思っていなかった", "b": "ブリーは、ボクシングを始めたころは最初の数回は不機嫌だったが、すぐに心に火がついたと話す。復帰前は庭いじりや鶏の世話をする穏やかな時期だったので、40代でまたレスリングをするとは想像していなかったそうだ。無理だと思っていたことが自分にできると分かったのが大きな収穫、という。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:44:01〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6241s"]]}, {"cat": "リングの話", "t": "ドロップキックと肩、復帰後の体の反応", "b": "ブリーは、以前は怖がっていたドロップキックを今は受けられるが、昔は何も感じなかった肩に、今ははっきり痛みが出ると話す。前の晩の試合の後には背中を寝違え、ニッキーがヒーティングパッドを持っていて助かったそうだ。回復が大事だと実感している様子だ。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:45:40〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6340s"]]}, {"cat": "リングの話", "t": "いまの女子たちから学ぶ、古い世代の強さ", "b": "ブリーは、今の女子の時代は本当に素晴らしく、一緒に戦うのが楽しいと話す。自分は昔ながらの考え方で育ったのに対し、若い選手たちは別の形で鍛えられていて、元は様々な競技の出身だと感じているそうだ。それでも相手から、ブリーの打たれ強さに驚かれることが多いという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:46:26〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6386s"]]}]);
  if (!PROFILES["Brie Bella"]) PROFILES["Brie Bella"] = { lead: "40代で復帰した二児の母は、子どもに戦う姿を見せたくてリングに戻ってきた。酒も失敗も笑い話にして、怖いもの知らずで生きると語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Brie%20Bella"]], moves: [], facts: [] };
  if (PROFILES["Brie Bella"]._weak) { PROFILES["Brie Bella"].lead = "40代で復帰した二児の母は、子どもに戦う姿を見せたくてリングに戻ってきた。酒も失敗も笑い話にして、怖いもの知らずで生きると語る。"; delete PROFILES["Brie Bella"]._weak; }
  PROFILES["Brie Bella"].facts.push(...[{"cat": "家族", "t": "復帰で子どもの見る目が変わった", "b": "今回の復帰で、娘のバーディーと息子のバディが自分を見る目が変わったという。以前は父ブライアンばかりを見ていて、バディには『消防士か先生になって自分に挑戦したら』と言われたこともあったそうだ。いまは『あれが自分のママだ』という顔で見てくれるのがうれしいと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（5:34〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=334s"]]}, {"cat": "家族", "t": "息子は技の助言、娘は衣装の助言", "b": "プロレス好きのバディは、腕を取って引くといいなどと試合のアドバイスをしてくるという。一方のバーディーは母がやられる場面が苦手で部屋を出てしまうが、衣装やメイクには厳しく意見をくれるそうだ。娘は派手なピンクにヒョウ柄を合わせるような奇抜な服を着こなし、デザイナーのベッツィ・ジョンソンのようだと笑う。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（7:09〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=429s"]]}, {"cat": "家族", "t": "娘のいじめ問題に向き合う", "b": "ここ2年ほど、娘が学校でいじめに悩んでいることを明かした。自分を守る方法を教えているが本人にはつらく、ホームスクールを望むこともあるという。もう1年様子を見て、それでも変わらなければ環境を見直すつもりだと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（9:36〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=576s"]]}, {"cat": "家族", "t": "双子だから一人の初日を知らない", "b": "いつもニッキーがいたので、初登校や誕生会に一人で入っていく心細さを知らずに育ったという。互いの弱点がもう一方の強みで、運動でも勉強でも補い合ってきたそうだ。突っかかるのはブリー、収めるのはニッキーという役回りだったとも振り返る。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（14:24〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=864s"]]}, {"cat": "体のこと", "t": "試合前後の食事", "b": "試合前はバナナ、鶏むね肉、白米が定番だという。試合後の楽しみはチップスとサルサ、それに持ち歩いているグルテン・乳製品不使用のチョコチップクッキーだそうだ。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（22:34〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=1354s"]]}, {"cat": "暮らし", "t": "アリゾナの砂漠パーティー", "b": "10代をアリゾナで過ごし、砂漠でのパーティーが思い出だという。警察が来たときにビーチサンダルのまま全力で走って逃げ切った話を、笑いながら明かした。星空の下でスマホもなく語り合った90年代の空気が恋しいと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（23:29〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=1409s"]]}, {"cat": "家族", "t": "18歳で双子を産んだ母", "b": "母は18歳でブリーとニッキーを産んだため、娘たちには性のことを包み隠さず話してくれたという。当時は嫌がったが助けになったと振り返る。自分も息子には相手が嫌がることはしないよう教え、娘は強い女性に育てたいと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（33:52〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2032s"]]}, {"cat": "家族", "t": "祖父の『赤いキツネ』の物語", "b": "祖父はいつも赤いキツネの冒険話を聞かせてくれたという。いまもいとこ同士で赤いキツネの絵を送り合い、兄は赤いキツネのタトゥーを入れているそうだ。いとこは13人いて、先日も家族を連れて集まったと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（39:24〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2364s"]]}, {"cat": "体のこと", "t": "グルテンと乳製品が合わない体に", "b": "体調不良が続き、3人の医師にかかって検査した結果、グルテンと乳製品が原因と分かったという。グルテンは混入程度でも5日ほど体調を崩すため、外食にも気をつけているそうだ。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（44:10〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2650s"]]}, {"cat": "暮らし", "t": "週2回のワインがごほうび", "b": "リング復帰中は飲むのを週2回ほどに抑えているという。シャンパンで始めてワインに移る時間が何よりの楽しみだそうだ。ワインの産地ナパに住み、自分のワインブランドも持っている。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（45:47〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2747s"]]}, {"cat": "家族", "t": "4世代の写真が並ぶ試飲室", "b": "自身のワインの試飲室は隠れ家風で、壁にはイタリア系を中心に4世代前までさかのぼる家族の写真を飾っているという。メキシコ系の家族の写真もあるそうだ。入るたびに先祖にあいさつし、自分の性格の多くはこの壁の誰かから来ていると話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（46:34〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2794s"]]}, {"cat": "家族", "t": "ナポリから来た高祖父のワイン", "b": "高祖父の一家はナポリから南フィラデルフィアに移り、肉や魚を売る店の地下で家族用のワインを造っていたという。売ることはなかったそうだ。第二次世界大戦後、祖父と兄弟が南カリフォルニアに移って農業を始め、一家は西海岸に根づいた。店にあった高祖父の金庫は祖母から結婚祝いに譲り受け、一家が持ってきたトランクも大切に保管しているという。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（47:25〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2845s"]]}, {"cat": "家族", "t": "霊媒師が告げた高祖父の名", "b": "10年ほど前、霊媒師タイラー・ヘンリーの番組で心当たりのない男性の名を告げられたという。帰宅すると、その名が受け継いだ高祖父の金庫に記されていて驚いたそうだ。何を伝えたかったのか、いまも知りたいと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（48:56〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=2936s"]]}, {"cat": "暮らし", "t": "Xから離れて十数年", "b": "バーディーを妊娠して以来、ツイッター（現X）にはほとんど入っていないという。批判されても、相手は何かが足りずに吐き出しているだけと受け流すそうだ。コメントに傷つく若手には、9割以上が好意的なのだから気にするなと伝えたと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（57:46〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=3466s"]]}, {"cat": "体のこと", "t": "10時間眠る筋金入りの寝坊", "b": "もともと10時間は眠るタイプで、夫に生きているか確かめられたほどだという。いまも夜9時には寝て、子どもたちは朝7時まで母を起こさないそうだ。眠るときはホワイトノイズのアプリを使っている。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:09:51〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=4191s"]]}, {"cat": "好きなもの", "t": "サッカー少女だった", "b": "子どもの頃にサッカーをしていて、W杯は欠かさず観ているという。ミア・ハムら米国女子代表を見て育ち、いまも女子代表を応援しているそうだ。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:13:41〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=4421s"]]}, {"cat": "リングに来るまで", "t": "息子に見せたくて復帰を決意", "b": "自分に挑戦したかったことに加え、母の試合を知らないバディに見せたかったのが復帰の理由だという。いまの女子のレベルに合わせるため、ボクシングとウエイトトレーニングを始めたそうだ。それまではヨガやピラティス派で、ブライアンとほぼ毎日一緒に鍛えている。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:37:47〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5867s"]]}, {"cat": "体のこと", "t": "40代の体と向き合う", "b": "検査で更年期の前兆が見つかり、ビタミンやホルモンのケアを始めたという。以前は苦手だった試合後のストレッチや整体にもきちんと通っているそうだ。昔は何ともなかった肩が痛むようになり、温熱パッドに助けられていると話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:38:37〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=5917s"]]}, {"cat": "暮らし", "t": "聞かなければ答えはノー", "b": "失敗を恐れない性格で、母からは『後悔しない生き方を』と教わってきたという。頼んでみなければ答えはノーのまま、というのが信条だそうだ。年齢に合わせた生き方には縛られたくないと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:42:23〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6143s"]]}, {"cat": "暮らし", "t": "ニワトリと畑の『ソフトな時代』", "b": "復帰前はニワトリを飼い、庭仕事をする穏やかな暮らしだったという。40代でまたリングに立つとは思っていなかったが、挑戦して自分にできると気づけたと話す。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-rFIB_n7bipA", "src": [["公式YouTube（1:44:01〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6241s"]]}]);
  if (PROFILES["Nikki Bella"]) PROFILES["Nikki Bella"].facts.push({"cat": "暮らし", "t": "ファンを守るために反論する", "b": "以前はネットの批判に言い返していたが今は控えている。ただ自分たちのファンが攻撃されたときは、直接メッセージを送って相手をたしなめることがあると、ブリー・ベラが話している。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で、ブリー・ベラの話（公式字幕を全文確認）", "src": [["公式YouTube（1:00:11〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=3611s"]], "by": "第三者の話"});
  if (PROFILES["Bryan Danielson"]) PROFILES["Bryan Danielson"].facts.push({"cat": "暮らし", "t": "いまは家事も育児もこなす父", "b": "妻の復帰中は手作りの食事やおやつ、工作まで担う『理想のパパ』ぶりで支えてくれていると、ブリー・ベラが話している。", "sp": "ブリー・ベラ", "d": "2026-07-31", "how": "ステファニーの番組で、ブリー・ベラの話（公式字幕を全文確認）", "src": [["公式YouTube（1:40:53〜）", "https://www.youtube.com/watch?v=rFIB_n7bipA&t=6053s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "wys-rFIB_n7bipA", d: "2026-07-31", show: "wys", who: ["Brie Bella"], t: "ブリー・ベラの回　双子の絆、ワイン一家のルーツ、40代の復帰", lead: "ステファニー・マクマホンの番組に出た約109分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Brie Bella"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys-rFIB_n7bipA").map((x) => [x.t, x.b, x.sp])), open: ["ステファニーとの2014年の抗争や、ペイジとのタッグなど筋書きにかかわる話は省いた。", "ドーナツや子育て観のやりとりなど、話者がブリーか聞き手か判別しにくい箇所は載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=rFIB_n7bipA"]] });
  if (!ROSTER.find((r) => r[1] === "Drew McIntyre")) ROSTER.push(["ドリュー・マッキンタイア", "Drew McIntyre", "lg", "", "", "", ""]);
