  if (PROFILES["Drew McIntyre"].lead === "スコットランド育ちで、15歳から遠くの養成学校へ通った努力の人。解雇や母の病気というどん底を、率直な言葉で振り返っている。") PROFILES["Drew McIntyre"]._weak = 1;
  PROFILES["Drew McIntyre"].facts.push(...[{"cat": "家族", "t": "妻と愛猫チャズが画面越しに応援", "b": "ドリューの妻は、仮想の観客席を通じて試合を生で見ていたという。愛猫のチャズを抱えて映っていて、試合中にその姿が目に入ったそうだ。夫婦で喜べたことで、2度目の戴冠は1度目とはまた違う特別な思い出になったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=98s"]]}, {"cat": "リングの話", "t": "23歳で「未来の王者」と言われた", "b": "若いころから「いずれ世界王者になる」と言われ、23歳のときには団体トップ本人にもそう断言されたという。その後は大きな浮き沈みがあり、王者になるのが笑い話に思えた時期もあったそうだ。会社の選んだ男ではなく、ファンが選んだ男として頂点に立てたことが何より大きいと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（2:25〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=145s"]]}, {"cat": "リングの話", "t": "初のベルトを持って夕食へ", "b": "初めて王座を獲った夜、先輩に「ベルトを着けたまま食事に来い」と言われ、チェーンのレストランへ巻いて行ったという。23〜24歳の独身で、自慢げに歩き回るのが楽しくて仕方なかったそうだ。店の人たちにも大喜びされ、写真をたくさん撮られたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（4:10〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=250s"]]}, {"cat": "好きなもの", "t": "幽霊もサメも語る自分の番組", "b": "会社の許可を得て、自分の関心で選んだ人と対談する企画を続けているという。幽霊の専門家やボディビルダー、サメの専門家など、少し変わった趣味の話題が並ぶそうだ。かつては「怒った大男」としか見られなかったが、素顔を知ってもらうことで身近に感じてもらえると話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（5:46〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=346s"]]}, {"cat": "好きなもの", "t": "13歳で見た巨漢レスラーの全力", "b": "子どものころ、兄や友人たちと地元のプロレス興行に通い、いつも最前列に並んでいたという。ある大巨漢の試合を見て、客が少ない小さな会場でも手を抜かない姿に強く心を打たれたそうだ。この印象は大人になっても残り、どこでも全力を出す姿勢につながったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（8:55〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=535s"]]}, {"cat": "リングに来るまで", "t": "4、5歳で隠れて見たプロレス", "b": "初めてプロレスを見たのは、4、5歳のころ、叔母と叔父の家だったという。いとこたちが見ているのを、兄と一緒にこっそり眺めていたそうだ。その場で「大きくなったらレスラーになる」と決め、その気持ちは一度も変わらなかったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（11:22〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=682s"]]}, {"cat": "リングに来るまで", "t": "15歳で12時間かけて養成学校へ", "b": "当時の英国では、プロレスの学校がほぼ2つしか見つからなかったという。母が電話で指導者と話して納得し、友人と一緒に12時間かけて列車で通ったそうだ。入門してみると思ったほど簡単ではなく、投げ落とされてから殴り合い主体のスタイルになったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（12:08〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=728s"]]}, {"cat": "リングに来るまで", "t": "伝説の先輩の一言と大学卒業", "b": "16歳のとき、興行に呼ばれていた米国の往年の名レスラーが練習会で「こいつはものになるかも」と言ってくれたという。故郷から直接、大手団体に入った人はいなかったが、その一言が支えになったそうだ。両親との約束で学業も続け、大学で犯罪学の学位を取ったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（14:30〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=870s"]]}, {"cat": "リングに来るまで", "t": "シェイマスと夢を語り合った日々", "b": "アイルランドのテレビ番組で、のちに同じ団体へ入る仲間と初めて対戦したという。2人ともブレット・ハートのファンで、試合映像を見ながら意見を出し合ったそうだ。相手はボディビルダーの息子で、2時間おきに食べる習慣など、体づくりも教えてもらったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（15:20〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=920s"]]}, {"cat": "リングに来るまで", "t": "体重をごまかして受けた入団テスト", "b": "紹介された担当者へ送る書類で、体重を20ポンドほど多く書いたという。マンチェスターのテストでは友人と一緒に組まされ、好評価を受けたが、その日は決定権のある人がいなかったそうだ。帰りの夜は2人で出かけ、親切な先輩レスラー2人に助言をもらい、半年後に出直して合格したと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（16:06〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=966s"]]}, {"cat": "リングに来るまで", "t": "契約の場で見せた強がり", "b": "採用担当者に「契約を考えている」と言われ、21歳のドリューは「こちらも許可を考えている」と返したという。内心では「お願いだから契約して」と叫んでいたそうだ。契約金は少額だったが、自分で額を大きくしてみせると決めたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（19:18〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=1158s"]]}, {"cat": "リングに来るまで", "t": "入門1週間でテレビ出演が決まる", "b": "育成団体に入ってすぐ、練習で見ていた関係者の前でマイクを持つことになったという。1週間後には電話で「来週の番組に出る」と告げられたそうだ。地元の6年の経験があっても、テレビのカメラの扱いなど知らないことだらけだったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（20:11〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=1211s"]]}, {"cat": "リングに来るまで", "t": "フロリダで出会った恩人ドクター・トム", "b": "育成団体のフロリダ拠点に移り、景色が白黒からカラーに変わったように感じたという。同じ車で通ううちに、ベテランの指導者が少しずつ心理や役作りの考え方を教えてくれたそうだ。自分の成功の多くはこの人のおかげだと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（23:23〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=1403s"]]}, {"cat": "体のこと", "t": "母の病気と荒れた日々", "b": "母が重い病気と診断され、世界でいちばん大切な人だっただけに大きな衝撃を受けたという。毎晩のように飲み歩き、仕事の不満も重なって生活が崩れていったそうだ。この事情は会社に隠し、ごく親しい友人にだけ打ち明けていたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（29:59〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=1799s"]]}, {"cat": "リングの話", "t": "「レスラーを演じるな」の教え", "b": "師と仰ぐ大先輩に、いつも質問攻めにしていたという。「レスラーを演じるのをやめて、レスラーになれ」と言われても、当時は意味が分からなかったそうだ。次の技のことばかり考えて観客を入れていなかったと気づき、力を抜いて瞬間を感じることだと理解したと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（30:50〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=1850s"]]}, {"cat": "体のこと", "t": "折れた手首のまま始まった3人組", "b": "3人組に配属されたころ、手首の骨が壊死して半年ほど痛めていたという。手術が必要だったが、その情報は上層部に伝わらなかったそうだ。デビューの直後に手術を受け、半年は人に触れず触れられず、計画は出だしでつまずいたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（34:42〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=2082s"]]}, {"cat": "リングに来るまで", "t": "解雇のショックと自責", "b": "2014年に解雇されたときは、驚きのあとに「自分が足りなかった」という思いが押し寄せたという。妻（当時は恋人）や父に「夢は終わった」と伝えるのが怖かったそうだ。それでも「次の一手」を考え、鏡の前で自分を責めるのではなく、立て直す覚悟を決めたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（36:20〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=2180s"]]}, {"cat": "リングに来るまで", "t": "解雇の3週間後に独立系へ飛ぶ", "b": "解雇後すぐ、友人が運営するスコットランドの団体に連絡して出場を決めたという。父にだけ話し、誰にも知らせずに飛行機を予約したそうだ。会場では自分の目標を語るマイクを20分ほど続け、「甘えていた自分」から抜け出すきっかけになったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（37:55〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=2275s"]]}, {"cat": "リングに来るまで", "t": "毎週世界を飛び回った独立系の日々", "b": "米国と英国を3週間おきに往復し、休日に豪州へ行ってまた米国の会場へ戻る生活だったという。SNSを使って自分の旅を見せ、各国の団体の王者を兼ねて、一時は7つのタイトルを持っていたそうだ。この時期は独立系プロレスが最も元気だったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（45:06〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=2706s"]]}, {"cat": "リングに来るまで", "t": "電話一本で古巣に戻る決意", "b": "日本行きも考えていた時期に、旧知の指導者から「決める前に話を」と連絡が来たという。育成団体の責任者と40分話し、成長した姿を見てくれていたことが心に響いたそうだ。育成ブランドでなら戻ると決めており、5分で話がまとまったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（48:16〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=2896s"]]}, {"cat": "リングに来るまで", "t": "往復4時間かけて通った名レスラーの教室", "b": "育成ブランドに戻ってすぐ、名レスラーの教室に出向いて学びたいと申し出たという。往復およそ4時間の道のりを、週に2、3回は運転して通ったそうだ。24時間かかっても行くほどの価値があったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（51:31〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=3091s"]]}, {"cat": "リングの話", "t": "細いパンツから生まれた決め技", "b": "得意の大技は、3人組時代に履かされた細いレザーパンツから生まれたという。股が裂けそうで、反対の足も蹴り上げたところ、相手も自分も倒れたそうだ。裏で「痛くなく打てれば武器になる」と言われ、練習を重ねて決め技にしたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（53:08〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=3188s"]]}, {"cat": "リングの話", "t": "巨漢王者を目標に体を作った", "b": "団体の外にいたころから、巨大な王者と戦う姿を想像して体を鍛えたという。体の大きさに加えて、相手側の名参謀とやり合えるよう、アドリブのマイクも磨いたそうだ。大きな試合が決まった瞬間は、実感がわかず思わず座り込んだと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（57:17〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=3437s"]]}, {"cat": "リングの話", "t": "無観客の大舞台を受け入れるまで", "b": "年間最大の祭典が無観客になると知り、地元に近い会場だっただけにしばらく本気で落ち込んだという。それでも、世界が苦しい時期に「楽しめる物語」を届けられると考え直したそうだ。試合では観客がいなくても集中でき、むしろ誰より深く入り込めたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:02:09〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=3729s"]]}, {"cat": "家族", "t": "家族の犠牲を思い出した瞬間", "b": "頂点に立った瞬間、これまでの浮き沈みが頭を駆け巡ったという。結婚式や誕生日、葬儀にも出られず、家族が犠牲になってきたことを思ったそうだ。観客のいない静かな会場だったので、その気持ちをカメラに向けて素直に伝えたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:05:24〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=3924s"]]}, {"cat": "リングの話", "t": "「バットマンには宿敵が必要」", "b": "自分は欠点を抱えたバットマンのような存在でありたい、と語る。完璧なスーパーマンには観客が共感しにくいからだそうだ。そのうえで、名声のある大先輩を「ジョーカー」と位置づけ、マイクにも試合にも全力で挑めたと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:07:51〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=4071s"]]}, {"cat": "暮らし", "t": "妻のアイデアで笑いを取る", "b": "妻はプロレスのファンではないが、外の目線が欲しくて、いつも相談しているという。番組で話題の動物ドキュメンタリーのセリフを言うよう勧められ、実際にカメラに向かって使ったそうだ。小さな工夫でも、見ている人の関心を引くきっかけになればと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:13:30〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=4410s"]]}, {"cat": "リングの話", "t": "対戦相手を研究する習慣", "b": "試合前には相手の決め技と癖を研究し、返し方を考えておくという。以前の一戦でも、相手の得意技を何度も切り返して勝ったそうだ。「対戦するからには宿題をしてくる相手だと思わせたい」と話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:31:58〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=5518s"]]}, {"cat": "リングの話", "t": "大剣の入場を一緒に作り直した", "b": "当初は背中に大剣を背負って入場する案だったが、階段やロープに当たって格好悪いと感じたという。団体トップが自宅の剣を持ち、事務所で振り回して、地面に突き刺す演出を考えてくれたそうだ。懸念を伝えてからわずか1分ほどで形になったと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-pm25SgO41U0", "src": [["番組のYouTube（1:32:45〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=5565s"]]}]);
  if (PROFILES["Sheamus"]) PROFILES["Sheamus"].facts.push({"cat": "暮らし", "t": "若手時代からの親友", "b": "父親がボディビルダーで、体づくりと食事のことを教えてくれたと、ドリューが話している。2時間おきに食べる習慣に驚いたという。お互いにリングと体を高め合う関係だったそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ドリュー・マッキンタイアの話（字幕を全文確認）", "src": [["番組のYouTube（15:20〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=920s"]], "by": "第三者の話"});
  if (PROFILES["Randy Orton"]) PROFILES["Randy Orton"].facts.push({"cat": "暮らし", "t": "自分の凄さに気づいていない", "b": "リーダーと呼ばれるのを嫌がるが、本当は周りを引き上げる存在だと、ドリューが話している。経験が豊富なのに、自信が足りないように見える時もあるそうだ。本人にも「その立場を受け入れるべきだ」と伝えていると話している。", "sp": "ドリュー・マッキンタイア", "d": "2026-08-08", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、ドリュー・マッキンタイアの話（字幕を全文確認）", "src": [["番組のYouTube（1:11:10〜）", "https://www.youtube.com/watch?v=pm25SgO41U0&t=4270s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-pm25SgO41U0", d: "2026-08-08", show: "ext", who: ["Drew McIntyre"], t: "ドリュー・マッキンタイアの回　どん底から夢をつかむまで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約98分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Drew McIntyre"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-pm25SgO41U0").map((x) => [x.t, x.b, x.sp])), open: ["字幕に話者名がないため、聞き手の発言と区別がつかない箇所は載せていない。", "番組の宣伝、ファンが戻ってほしいという意気込みや将来の目標は省いた。", "ドリュー自身の名前以外の固有名詞は、自動字幕で崩れていた箇所は書いていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=pm25SgO41U0"]] });
  if (!ROSTER.find((r) => r[1] === "Chelsea Green")) ROSTER.push(["チェルシー・グリーン", "Chelsea Green", "lg", "女子王座を戴冠した人気者", "", "", ""]);
  if (!PROFILES["Chelsea Green"]) PROFILES["Chelsea Green"] = { lead: "カナダ・ビクトリア出身で、結果にこだわらず楽しむことを大切にしてきた。夫と家を建て、ハリウッド進出と家族を持つ夢も語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Chelsea%20Green"]], moves: [], facts: [] };
  if (PROFILES["Chelsea Green"]._weak) { PROFILES["Chelsea Green"].lead = "カナダ・ビクトリア出身で、結果にこだわらず楽しむことを大切にしてきた。夫と家を建て、ハリウッド進出と家族を持つ夢も語る。"; delete PROFILES["Chelsea Green"]._weak; }
  PROFILES["Chelsea Green"].facts.push(...[{"cat": "リングの話", "t": "結果より仕事ぶりにこだわる", "b": "デビュー1年目は仕事のことで強いストレスを抱えていたが、育成オーディション番組のあとに「なるようにしかならない」と割り切ったという。今は準備の丁寧さ、共演者やファンへの接し方、衣装や見た目の作り込みにこだわり、物語の方向性までは気にしないと話す。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（2:23〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=143s"]]}, {"cat": "リングに来るまで", "t": "2023年の復帰は「ただ感謝」だった", "b": "2014年からずっと走り続けて疲れ切っていたと話す。3か月先の予定ばかり気にして、もっと名前を大きくしなければと考え続けていたそうだ。2023年にトリプルHへ自分から連絡して復帰した時は、再び解雇されるまでは給料をもらって全力で働こうと思っていたという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（4:01〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=241s"]]}, {"cat": "リングの話", "t": "逆さ吊りのまま耐えた王座戦", "b": "ラダー戦の終盤、逆さにぶら下がったまま倒れているふりをして、最後に起き上がる展開だった。つま先だけで体を支えていたため、脚がつり、太もも裏が焼けるようだったという。少しでも動けば仕掛けがばれるので、必死に動かず耐えたと話す。観客が一斉に立ち上がるのを感じて鳥肌が立ったそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（5:37〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=337s"]]}, {"cat": "リングの話", "t": "高所恐怖症なのにラダーの頂上へ", "b": "高い所は苦手だが、世界一高い崖からの飛び込みをしたこともあるという。ただ、ラダーはぐらぐらで脚が震え、腰を下ろしたり向きを変えたりしながら耐えていたと笑う。それでも写真が世界中に出ると考え、よい表情で写ることだけを意識したそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（8:01〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=481s"]]}, {"cat": "リングの話", "t": "王座をマイケル・ヘイズに捧げた", "b": "試合後のインタビューで、思わず王座をマイケル・ヘイズに捧げる言葉が出たと話す。ヘイズは常に味方で、演じ方や準備について厳しく助言してくれる存在だという。ドキュメンタリー番組では批判を浴びた人なので、そこを逆手に取りたかったそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=580s"]]}, {"cat": "暮らし", "t": "裏側を見せる番組が転機になった", "b": "WWEの舞台裏ドキュメンタリー「アンリアル」には、検閲せず普段どおり話すと決めて出たという。放送後、ファンが役柄ではなく素顔の自分を応援してくれるようになり、キャリアが変わったと話す。以前は「うるさい」と思われていたが、努力する姿が伝わったそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（12:04〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=724s"]]}, {"cat": "暮らし", "t": "SNSは便利だが線引きが難しい", "b": "2023年の復帰後はSNSで自分の方向性を示し、会社がそれを見て展開に取り入れてくれたと話す。一方で、ファンが自分を知っている気になるのが負担だという。「すっぴん」の投稿も実は計算して選んだもので、本当の自分を知るのは家族と友人だけだと話す。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（14:23〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=863s"]]}, {"cat": "体のこと", "t": "Xをやめた理由", "b": "Xは創作意欲を満たしてくれた場所だったが、悪意や中傷に巻き込まれるようになり離れたと話す。ネットのいじめが大嫌いで、自分が「ネットの自警団」のようになっていたのも苦しかったそうだ。友人の勧めで今回は本当に離れると決め、仕事とは別にインスタグラムを気軽に楽しみたいという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（16:48〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1008s"]]}, {"cat": "暮らし", "t": "ファンの憶測が職場にも影響した", "b": "SNSでは、誰と仲が悪いか、誰が楽屋のリーダーかといった憶測が広がり、職場の人間関係にも響いたと話す。実際は、同僚同士で連絡を取り合い、服を貸し合い、一緒にジムへ行く仲だという。もしハリウッドで成功したら、その時はもっとしっかり線引きしたいと話す。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（19:07〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1147s"]]}, {"cat": "暮らし", "t": "ホラー映画で映画の世界に目覚めた", "b": "今年出演したホラー映画で、特殊メイクや美術の世界に魅了されたという。もともとホラーのファンではなかったが、プロレスと同じく熱心なファン層があることに気づいたそうだ。次はホラーの「最後に生き残る女性」役をやってみたいと話す。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（22:59〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1379s"]]}, {"cat": "暮らし", "t": "出演経歴を一つずつ積み上げたい", "b": "トロントでの映画の撮影など、小さな役でも受けて経歴を作りたいと話す。「オーディションや自撮り録画を受けるのを大物ぶって嫌がらない」のが信条だという。台本の読み方や現場用語も一から学び直しているそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（23:50〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1430s"]]}, {"cat": "家族", "t": "ジョン・シナ夫妻との年数回のデート", "b": "ジョン・シナ夫妻とは、お互い忙しいため年に数回の食事会で近況を語り合うという。演技への思いも話題になり、シナからは今のやり方で間違っていないと励まされるそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（24:00〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1440s"]]}, {"cat": "暮らし", "t": "旅先の自撮りオーディション", "b": "ヨーロッパ巡業中、休暇を終えてイタリアへ向かう途中に、人気ドラマシリーズの出演オーディションの自撮り録画を24〜48時間以内にと依頼されたという。ホテルの部屋で夫に相手役を頼み、ごみ箱やティッシュ箱でカメラを固定して撮ったそうだ。結果は不採用だったが、全力でやったと演技の先生に認められたという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（27:05〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1625s"]]}, {"cat": "好きなもの", "t": "自分のミームが大好き", "b": "「何でもないと言う恋人が一日じっと見つめてくる」という有名なミームを気に入っていると話す。実際に自分が夫にそうしているのだという。ほかにも、試合に走って入場する場面の映像が、プロレスを知らない友人から送られてくると笑う。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（30:17〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1817s"]]}, {"cat": "体のこと", "t": "眼窩骨折は最も痛いけがだった", "b": "試合中に顔を骨折したことをすぐに悟り、レフェリーに「顔が壊れた」と伝えたという。頬だと思ったが、実際は眼窩の骨で、これまでで最も痛いけがだったと話す。鼻を折った経験もあり、たくさんの骨折歴があるそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（31:52〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1912s"]]}, {"cat": "リングの話", "t": "本心をぶつけたプロモ", "b": "ニック・オルディスとのやりとりは、13年のキャリアで積み上げた苦労をそのまま語ったもので、「本当のことだった」と話す。素材が多すぎて、何度も削るほどだったという。オルディスとは台本づくりでも相性が良く、意見を出し合っているそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（33:28〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2008s"]]}, {"cat": "リングの話", "t": "プロレスらしい語り口が苦手", "b": "いかにも「プロレス的」な抑揚の台詞には鳥肌が立つと話す。演技の授業にも通い、役の背景を作って感情を呼び起こすなど、現実味を出す工夫をしているそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（35:02〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2102s"]]}, {"cat": "体のこと", "t": "復帰時期は自分で確かめた", "b": "診断後、救急外来を出る前から復帰できる時期を医師に確認したという。帰宅後の数日はつらかったが、オーランドで外科医を見つけ、復帰可能日を書面でもらったそうだ。再び骨折すると眼球が下がり、プレートが必要になる可能性があるため、会社が慎重なのも理解していると話す。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（36:36〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2196s"]]}, {"cat": "リングの話", "t": "ガンサーとの合成写真と、盛り上がった冒頭コーナー", "b": "ガンサーと王座を争うという合成写真をSNSに載せたことを笑って話す。男女の選手が絡む場面はめったにないが、あの日は憎たらしい悪役ぶりを楽しめたという。夫のマット・カルドナも登場した番組冒頭は、近年で一番楽しい展開だったと振り返る。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（39:52〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2392s"]]}, {"cat": "好きなもの", "t": "テイラー・シェリダン作品が好き", "b": "好きな映画やドラマは、ほとんどがテイラー・シェリダンの作品だと話す。いま夫と一緒に「ランドマン」を見ていて、いつか出演してみたいと語る。ふだんはリアリティ番組もよく見るそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（41:31〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2491s"]]}, {"cat": "家族", "t": "夫と同じ番組で働く", "b": "夫のマット・カルドナと同じ番組で働くのは、面倒だけど楽しいと話す。スケジュールの違いなど、衝突もあったが乗り越えて、毎週少しずつやりやすくなっているという。夫は自分の服のデザインもしてくれるそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（45:24〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2724s"]]}, {"cat": "暮らし", "t": "自分好みに仕上げた新居", "b": "新しい家では、ネジや取っ手、色まで一つずつ自分で決めたと話す。配管や換気の位置まで把握しているほどで、旅先で好きだったヨーロッパのような、美しく時代を超えた家にしたかったそうだ。夫がロケで不在の間に一人で荷物を運び込んだという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（46:11〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2771s"]]}, {"cat": "リングの話", "t": "髪を賭ける試合と王座への思い", "b": "大きな大会でニッキー・ベラと髪を賭けた試合をしたいと、実際に提案したことがあると話す。夫も大賛成だったそうだ。US王座の価値を高めたいと願っていたが、思うようにはいかなかったという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（47:45〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=2865s"]]}, {"cat": "リングの話", "t": "王座は夢見たことがなかった", "b": "カナダ西部ビクトリア出身のチェルシーは、女子王座を目標にしたことは一度もなかったと話す。厳密な目標を持つのは早くにやめ、流れに身を任せてきた結果、夏の大型大会で王座が転がり込んできたという。自分でも「やり遂げた」と驚いたそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（50:00〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3000s"]]}, {"cat": "リングの話", "t": "自分の帽子が大人気に", "b": "チェルシーのトレードマークの帽子は、ランディ・オートンやコーディ・ローデスらも身につけたと話す。女性選手で帽子の商品を持つのは珍しく、会社に強く働きかけて実現したそうだ。アレクサの商品展開に憧れていたという。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（55:45〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3345s"]]}, {"cat": "暮らし", "t": "カナダの有名人を挙げるのが大好き", "b": "夫の家族とのクリスマスで、カナダ出身の有名人を挙げ合う遊びをするのが定番だという。通っていた高校の卒業生にショーン・メンデスがいると話す。ビクトリアがある島の出身で、同郷のパメラ・アンダーソンも誇りだそうだ。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（58:51〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3531s"]]}, {"cat": "リングに来るまで", "t": "リング名「ジェイダ」の由来", "b": "2014年、ランス・ストームの学校に通いながらカルガリーのアイリッシュパブで働いていたという。初めての試合の直前になっても名前が決まらず、同僚たちと案を出し合ったそうだ。結局、同僚が通った店の女性の名前から、名字のない「ジェイダ」に決まったと笑う。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（1:03:45〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3825s"]]}, {"cat": "暮らし", "t": "今日感謝したいこと", "b": "眼窩のけがが手術にならず、仕事も休まずに済んだことに感謝していると話す。応援してくれたファンと、関わってくれた人たちへの感謝も語った。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（1:10:06〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=4206s"]]}, {"cat": "家族", "t": "次の目標は家族を持つこと", "b": "夫との生活が落ち着き、これから家族を増やしたいと話す。35歳になって、会社とも率直に相談できるようになったそうだ。産み方はまだ決めておらず、代理出産も選択肢の一つだと話している。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-hfzeZ6qJZAE", "src": [["番組のYouTube（1:11:43〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=4303s"]]}]);
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "出演を続けるやり方を励ます", "b": "ジョン・シナは会うたびに、オーディションや小さな役も受け続ける今のやり方で間違っていないと励ましてくれる、と、チェルシー・グリーンが話している。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で、チェルシー・グリーンの話（字幕を全文確認）", "src": [["番組のYouTube（24:00〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=1440s"]], "by": "第三者の話"});
  if (PROFILES["Rhea Ripley"]) PROFILES["Rhea Ripley"].facts.push({"cat": "暮らし", "t": "リング上で最高の相手の一人", "b": "リア・リプリーは世界で最高の選手の一人で、リング上でとても気前がよく、相性も抜群だ、と、チェルシー・グリーンが話している。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で、チェルシー・グリーンの話（字幕を全文確認）", "src": [["番組のYouTube（50:59〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3059s"]], "by": "第三者の話"});
  if (PROFILES["Liv Morgan"]) PROFILES["Liv Morgan"].facts.push({"cat": "暮らし", "t": "王者としての発信が手本", "b": "リヴ・モーガンは防衛戦が少なくても、取材やグッズ、話題づくりなど王座のためにできることを全部やっていて、手本にしたい、と、チェルシー・グリーンが話している。", "sp": "チェルシー・グリーン", "d": "2026-09-03", "how": "クリス・ヴァン・ヴリートの番組で、チェルシー・グリーンの話（字幕を全文確認）", "src": [["番組のYouTube（51:45〜）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE&t=3105s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-hfzeZ6qJZAE", d: "2026-09-03", show: "ext", who: ["Chelsea Green"], t: "チェルシー・グリーンの回　女子王座戴冠、眼窩骨折、そして家族の夢", lead: "クリス・ヴァン・ヴリートの番組に出た約74分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Chelsea Green"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-hfzeZ6qJZAE").map((x) => [x.t, x.b, x.sp])), open: ["番組の宣伝や次の大会の見通しだけの話、ほかの人の名前が崩れていて確信が持てない箇所は省いた"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=hfzeZ6qJZAE"]] });
  PROFILES["Charlotte Flair"].facts.push(...[{"cat": "リングの話", "t": "父の娘として完璧を演じてきた", "b": "父と同じ失敗をすれば同一視されると感じ、父の過ちを埋め合わせるように完璧であろうとしてきたと、シャーロット・フレアーは話す。キャラクターや王座が自分を特別にしたのではなく、素の自分を画面で見せる弱さこそ強さだと気づいたそうだ。助けを求めることも強さだと語っている。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（5:38〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=338s"]]}, {"cat": "リングの話", "t": "ブレスレットをもらえるキャラになった", "b": "この1年で、ファンからブレスレットをもらうようになったとシャーロットは話す。直近のサイン会では腕がブレスレットでいっぱいになり、見てもらえている、愛されていると実感したという。無理に別人を演じなくなったことが、客席との距離を変えたそうだ。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（10:20〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=620s"]]}, {"cat": "リングの話", "t": "2015年に「名前を使い切る」べきだった", "b": "2015年のデビュー当時、努力して認めてもらいたいと訴え続け、10年も承認を追いかけてしまったとシャーロットは振り返る。最初から家名を堂々と背負っていれば、余計な苦労をせずに済んだと思うそうだ。若い世代にも、背景を隠さず武器にしろと伝えたいと話す。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（17:37〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=1057s"]]}, {"cat": "リングの話", "t": "1年近い離脱中の「忘れられる」不安", "b": "けがで1年近くテレビを離れていた間、ファンはまだ自分を覚えているのかと不安だったとシャーロットは語る。事業は自分がいなくても回り続けるという現実も痛感した。そんな時期に、自分と話したがる少女と出会えたことが、忘れられていないという支えになったそうだ。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（27:27〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=1647s"]]}, {"cat": "リングの話", "t": "記事の公開後、入場で起きた大歓声", "b": "自分の素顔を綴った記事は、書き上げるのに2年かかったとシャーロットは話す。その後の女子大会でエプロンに立つと、客席から自分を呼ぶ声が次第に大きくなり、キャリア屈指の歓声になったという。記事を読み、自分を追ってくれたファンが人間としての自分を受け入れてくれたのだと受け止めている。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（35:41〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=2141s"]]}, {"cat": "リングの話", "t": "勝者の意味を見失った時期", "b": "自分が築いたキャラクターには誇りがあるが、いつの間にか王者であることの意味を見失っていたとシャーロットは語る。完璧で無傷で孤高であろうとして傷跡を隠し続け、役が独り歩きしたそうだ。「氷のかたまりは愛せない」という鎧が分厚くなり、自分を閉じ込めていたと振り返っている。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（37:16〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=2236s"]]}, {"cat": "リングの話", "t": "アレクサ・ブリスとのタッグで世界が広がった", "b": "今年は間違いなくキャリア屈指の1年で、そのきっかけに相棒のアレクサ・ブリスの後押しがあったとシャーロットは話す。互いに戦い合ってきた2人で本当に組めるのかとためらったが、ブリスに背中を押されたという。当時は憎まれ役だった自分と人気者の彼女という組み合わせに会社側も慎重だったが、2人の星が互いを輝かせ、部門全体にも光が当たったそうだ。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（38:51〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=2331s"]]}, {"cat": "リングの話", "t": "キアナ・ジェイムスに引き出される", "b": "後輩のキアナ・ジェイムスと試合をすると、こちらも力を引き出されるとシャーロットは話す。大会出場をかけた予選のあと、不安そうな彼女に、長くやってきた自分が本気にさせられていると伝えたそうだ。将来の大スターだと見込み、このまま鍛錬を続けてほしいと語っている。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（49:27〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=2967s"]]}, {"cat": "リングの話", "t": "どんな試合も出し切ると決めた", "b": "大きな試合でも短い試合でも、バックステージのコーナーでも、同じ姿勢で臨むとシャーロットは話す。けがで離れていた間に、機会は一瞬で奪われると身にしみたからだという。やり切らずに帰ることだけはしたくないと語る。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（57:23〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=3443s"]]}, {"cat": "リングの話", "t": "ナタリアの一戦が自分の道を開いた", "b": "ナタリアの「なぜ私じゃないの」という試合が、自分のキャリアを始動させたとシャーロットは話す。育成番組のライブで見たその試合は今も色あせない名勝負で、あれがなければ今の自分はいないと断言する。その姿勢にいまも刺激を受けているそうだ。", "sp": "シャーロット・フレアー", "d": "2026-09-04", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-charlotte", "src": [["番組のYouTube（1:05:29〜）", "https://www.youtube.com/watch?v=9NsemOg7XhA&t=3929s"]]}]);
