  PROFILES["Seth Rollins"].facts.push(...[{"cat": "家族", "t": "娘が生まれ、笑顔が増えた", "b": "父になることは想像していなかったが、いざ娘が生まれると毎日が楽しくて仕方ないと話す。以前より自然に笑っている自分に気づくそうだ。自分本位でいなければ上を目指せない業界にいたからか、親になる姿は思い描けなかったという。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:43〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=103s"]]}, {"cat": "家族", "t": "妻の多忙な時期に授かった子", "b": "妻のベッキー・リンチも子どもを望んでいたが、お互いトップの時期でなかなか機会がなかったという。コロナ禍で試合の予定が止まったことが、ちょうどよい好機になったそうだ。計画した妊娠で、一度で授かったと笑って話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（2:35〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=155s"]]}, {"cat": "家族", "t": "ハワイで挙げた5分の結婚式", "b": "結婚は形式のようなものだったと話す。本当は1年前に挙げたかったが、渡航制限で延びたそうだ。ハワイでごく少数の家族と友人だけが集まり、式は5分で終わり、ケーキとビールで乾杯して数日過ごしたという。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（3:25〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=205s"]]}, {"cat": "家族", "t": "マウイの夕日の浜でプロポーズ", "b": "プロポーズはマウイ島で、レンタルのジープでハナへの道を回っている途中だったという。指輪は持っていたが計画はなく、夕日の岩場の浜で車を止め、振り向いた妻の前でひざまずいたそうだ。偶然そこにいたカメラマンが写真を撮ってくれたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（4:18〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=258s"]]}, {"cat": "リングに来るまで", "t": "祖父と父と見た初めての興行", "b": "4、5歳のころ、プロレス好きの父・祖父・叔父に連れられて初めて生の興行を観たという。ハルク・ホーガンやリック・フレアーを目の前にして夢中になったそうだ。レンタルのビデオ店で古い大会のテープを借り、繰り返し観ていたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（14:46〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=886s"]]}, {"cat": "リングに来るまで", "t": "トランポリンで始めた裏庭プロレス", "b": "ネットで裏庭プロレスの映像が広まった時期に、家にあったトランポリンと仲間とで興行を始めたという。ホームセンターの木材を集め、学校に手作りのチラシを配って、多い日は100人ほど集めたそうだ。寄付の小銭を持って食堂へ行くのが楽しみだったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（15:31〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=931s"]]}, {"cat": "家族", "t": "両親の離婚とトランポリン", "b": "野球やバスケットボールなどのスポーツは両親に習わせてもらったという。トランポリンは両親の離婚の際に、慰めとして買ってもらったものだそうだ。そこで体のコントロールを身につけたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（16:18〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=978s"]]}, {"cat": "リングに来るまで", "t": "車中泊で挑んだ名門道場の入門", "b": "独学でなく正しく学びたいと考え、18歳で車に乗って東部の名門道場の試験を受けにいったという。試験には受かったが入門金が払えず、数日間は車で寝泊まりしたそうだ。恥ずかしさをこらえて故郷に戻り、仕事を見つけたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（17:56〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1076s"]]}, {"cat": "リングに来るまで", "t": "仲間を誘い、車で3時間かけて通った道場", "b": "シカゴに道場ができたと知り、1人では教えられないと言われたため、仲間を3人誘って4人で通い始めたという。週に何回かシカゴと地元を往復し、学校と複数の仕事も続けたそうだ。ダニー・ダニエルズの週末の興行にも付いて回ったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（19:45〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1185s"]]}, {"cat": "家族", "t": "両親の支えがなければ続かなかった", "b": "下積み時代は両親の支えが大きかったと話す。母は唯一の息子が崩れないよう、念のため学校にも行くよう厳しく言っていたそうだ。その後ろ盾がなければ続けられなかっただろうと振り返る。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（20:32〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1232s"]]}, {"cat": "リングに来るまで", "t": "一晩150ドルで始まった団体での日々", "b": "憧れていた団体のブッカーに誘われ、車で22時間かけてフロリダの小さな団体へ試験に行ったという。試合後にその場で契約を持ちかけられ、最初のギャラは一晩150ドルだったが大金に思えたそうだ。試合の組み立て方を学ぶ貴重な場になったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（21:17〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1277s"]]}, {"cat": "リングに来るまで", "t": "いろいろな選手から技を借りて作った型", "b": "隼の飛び技、AJスタイルズやCMパンクの技などを取り入れ、ホーガンらから受け取った華やかさを混ぜたという。試して合わなければ捨てて調整したそうだ。絵は描けないが、動きの良し悪しを見抜く目だけは昔からあったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（23:43〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1423s"]]}, {"cat": "リングに来るまで", "t": "契約を迷い、WWE入りを勝ち取った話", "b": "元同僚の選手が人づてにWWEの人事担当へ話をつないでくれ、仲間の力を借りて映像と書類を送ったという。同じ時期に別の団体からも誘いがあり、口頭で承諾してしまっていたそうだ。ジム・コルネットに止められ、ぎりぎりまで返事を待ってWWEから声がかかったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（25:16〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1516s"]]}, {"cat": "リングに来るまで", "t": "倉庫のような育成施設に衝撃を受けた", "b": "最初に着いた育成施設は飾り気のない倉庫で、期待していた姿とまるで違ったという。直前まで大きな会場でタイトルを賭けて戦っていたため、格下げされた気分だったそうだ。それでも初日から気持ちを切り替え、練習に取り組んだと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（30:09〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=1809s"]]}, {"cat": "リングに来るまで", "t": "恩人ダスティの「自分らしくいろ」", "b": "憧れていたダスティ・ローデスに、育成の場で言われた言葉が支えだったという。型にはめようとする空気の中で、自分らしくいろと励まされたそうだ。映像を見て涙ぐみ、今でも会いたいと話した。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（35:08〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=2108s"]]}, {"cat": "リングの話", "t": "クビ寸前だった育成時代", "b": "育成施設で、元コーチのテリー・テイラーとぶつかり、授業で毎日のように異を唱えていたという。トリプルHに呼ばれ、このまま従わないなら去れと言われたそうだ。ジョーイ・マーキュリーに「役割を演じ分けろ」と諭され、のちに自分から王座への思いを伝えて和解したと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（37:32〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=2252s"]]}, {"cat": "リングの話", "t": "3人組の誕生は急な思いつきだった", "b": "ディーン・アンブローズとは練習試合の相性が抜群だったという。3人は仲が良かったわけではなく、会社側が使い道を探していただけだそうだ。最初に渡されたのはタートルネックと戦闘服だけで、あとは自分たちで形にしたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（42:17〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=2537s"]]}, {"cat": "リングの話", "t": "2年間続いた車での移動と作戦会議", "b": "チームは毎週一緒に移動し、同じ部屋に泊まり、試合の話をし続けたという。ジョーイ・マーキュリーが陰の4人目のように助言してくれたそうだ。ランディ・オートンに奇襲をかけた際は、オートンが本気で怒って大騒ぎになったと笑って話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（47:49〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=2869s"]]}, {"cat": "リングの話", "t": "裏切りを告げられたのは数時間前", "b": "チームの解散は何か月も前から会社に提案されていたが、反対して先延ばしにしたという。裏切りの展開を知らされたのは、本番のわずか数時間前だったそうだ。直後の番組では新しい衣装も音楽もなく、慌てて自分の悪役像を作り上げたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（52:32〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=3152s"]]}, {"cat": "リングの話", "t": "レッスルマニアでの現金化の記憶", "b": "契約書を使って王座を奪った瞬間は、今見ても他人がやったことのように感じるという。夢のようで、その場の喜びを噛みしめる余裕もなかったそうだ。視聴者にとって何年も語り継がれる場面になったことに驚いたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（58:13〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=3493s"]]}, {"cat": "リングの話", "t": "悪役のまま復帰、ファン側に立ちたかった", "b": "膝の大けがからの復帰時、本人は善玉として戻るつもりだったという。客席の反応も好意的だったが、会社の方針で悪役のままになったそうだ。中途半端な立ち位置に長く置かれ、何が悪いのか分からず自信を失ったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:08:42〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=4122s"]]}, {"cat": "リングの話", "t": "会長に直談判して掴んだ王座", "b": "会長のビンス・マクマホンに「あの頃のセスはどこへ行った」と問われ、言い返したという。「機会をくれれば結果で示す」と伝え、大会で王座を狙う案を自分から出したそうだ。この直談判が、試合内容で観客を取り戻すきっかけになったと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:16:11〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=4571s"]]}, {"cat": "リングの話", "t": "ブロック・レスナーに認められるまで", "b": "ブロック・レスナーと戦う年にも、本人はメインイベントを望んでいたという。しかし妻のベッキーがその大会の主役になり、悔しさと喜びの両方を抱えたそうだ。試合順はブロックの提案で最初に変わり、お礼に冷えたビールを控室に届けたと話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:20:23〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=4823s"]]}, {"cat": "リングの話", "t": "善玉として観客に突き放された時期", "b": "善玉の王者としては、自分には「応援したくなる生い立ち」がないと感じていたという。観客は応援したい挑戦者を好むため、上に立つほど冷たくなると話す。トロントの試合で20分戦い、ブーイングから声援に変えたことを誇りにしているそうだ。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:28:35〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=5315s"]]}, {"cat": "リングの話", "t": "無観客で変えた話し方と今のキャラ", "b": "救世主のキャラで勢いに乗った頃、無観客の時代が来て、話し方や間を作り替えたという。復帰後は、妻のスタイリストに勧められた派手なスーツを着て、全く違う役を演じ始めたそうだ。考えすぎず役が自分と一体になると、自由な感覚が生まれると話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:31:48〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=5508s"]]}, {"cat": "暮らし", "t": "地元で営む道場「ブラック＆ブレイブ」", "b": "2014年、旧友のメリック・ブレイブと、アイオワ州ダベンポートに道場を開いたという。名前は2人のタッグ名から付け、運営は友人に任せつつ本人もよく顔を出すそうだ。教える中で基本を見直すことが、自分の勉強にもなると話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:38:26〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=5906s"]]}, {"cat": "好きなもの", "t": "コーヒーが好きで地元に店を開いた", "b": "巡業中にセザーロと一緒にコーヒー店を巡るのが習慣だったという。故郷のダベンポートには自家焙煎のような店がなく、道場の隣にも出店し、さらに市内の反対側にも新店を開いたそうだ。コーヒーとプロレスが好きで、事業も楽しんでいると話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:40:05〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=6005s"]]}, {"cat": "暮らし", "t": "父になって変わった引退への考え方", "b": "レッスルマニアのメインイベントを飾るという夢は、まだ果たしていないそうだ。ただ父になってから優先順位が変わり、契約があと数年残っているのでそれは全うしたいという。娘が学校に上がる頃にまた考えると話す。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-7IOzDwm-KD8", "src": [["番組のYouTube（1:41:44〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=6104s"]]}]);
  if (PROFILES["Joey Mercury"]) PROFILES["Joey Mercury"].facts.push({"cat": "暮らし", "t": "ジョーイ・マーキュリーの助言", "b": "ジョーイ・マーキュリーは、演じる役を常に保ちつつ、相手が求めるものも与える「折り合い」が大事だと教えてくれた、とセス・ロリンズが話している。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、セス・ロリンズの話（字幕を全文確認）", "src": [["番組のYouTube（40:42〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=2442s"]], "by": "第三者の話"});
  if (PROFILES["Brock Lesnar"]) PROFILES["Brock Lesnar"].facts.push({"cat": "暮らし", "t": "ブロック・レスナーの流儀", "b": "ブロック・レスナーは大舞台で何を見せるべきかを理解している人で、若い頃は理解できなかったが今は尊敬していると、セス・ロリンズが話している。", "sp": "セス・ロリンズ", "d": "2026-09-05", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、セス・ロリンズの話（字幕を全文確認）", "src": [["番組のYouTube（1:21:15〜）", "https://www.youtube.com/watch?v=7IOzDwm-KD8&t=4875s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-7IOzDwm-KD8", d: "2026-09-05", show: "ext", who: ["Seth Rollins"], t: "セス・ロリンズの回　裏庭の少年から「ドリップ・ゴッド」へ", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約104分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Seth Rollins"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-7IOzDwm-KD8").map((x) => [x.t, x.b, x.sp])), open: ["ホスト（スティーブ・オースティン）自身の思い出話や、番組の宣伝・スポンサーの話は省いた。", "自動字幕で固有名詞が崩れている箇所があり、確信の持てない名前は載せていない。", "字幕に話者名がないため、文脈から発言者を判断した。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=7IOzDwm-KD8"]] });
  if (!ROSTER.find((r) => r[1] === "Hijo de Dr. Wagner Jr.")) ROSTER.push(["イホ・デ・ドクトル・ワグナーJr.", "Hijo de Dr. Wagner Jr.", "lg", "", "", "", ""]);
  if (!PROFILES["Hijo de Dr. Wagner Jr."]) PROFILES["Hijo de Dr. Wagner Jr."] = { lead: "3代目の覆面を背負い、WWEの舞台にも立つイホ・デ・ドクトル・ワグナーJr.。カメラの向こうの何百万人に向けて戦う難しさを語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Hijo%20de%20Dr.%20Wagner%20Jr."]], moves: [], facts: [] };
  if (PROFILES["Hijo de Dr. Wagner Jr."].lead === "3代目の覆面を背負い、WWEの舞台にも立つイホ・デ・ドクトル・ワグナーJr.。カメラの向こうの何百万人に向けて戦う難しさを語る。") PROFILES["Hijo de Dr. Wagner Jr."]._weak = 1;
  PROFILES["Hijo de Dr. Wagner Jr."].facts.push(...[{"cat": "リングの話", "t": "一番難しかったのはカメラに慣れること", "b": "WWEの番組に出るようになって一番難しかったのは、6台のカメラに向けて体で気持ちを伝えることだったと、ワグナーJr.は話す。会場の数万人だけでなく、画面の向こうの何百万人が見ているという。限られた数分で自分の居場所を勝ち取らなければならないそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（3:08〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=188s"]]}, {"cat": "リングの話", "t": "仕事の環境が大きく変わった", "b": "WWEと組んでからは、毎週の体の検査や医療スタッフ、フロリダの育成拠点での練習など、関わる人が何倍にも増えたと、ワグナーJr.は話す。覆面の下では一人の人間がその変化を学んでいる最中で、メキシコのファンにはもう少し待ってほしいという。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（3:08〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=188s"]]}, {"cat": "家族", "t": "家族は自分の「クッション」", "b": "母は試合のたびに「何時に始まるの」と聞き、父は自分の覆面だけでなく祖父の覆面が受け継がれたことを誇りにしていると、ワグナーJr.は話す。10歳下の弟のことも尊敬しているという。転んだときに受け止め、また押し出してくれる家族を「人生のクッション」と呼んでいる。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（11:21〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=681s"]]}, {"cat": "暮らし", "t": "「過程を楽しめ」の入れ墨", "b": "「過程を楽しめ」という小さな入れ墨を入れていると、ワグナーJr.は話す。目標に着くと人はすぐ次を欲しがるので、デビューからの17年の歩みそのものを大事にしたいという。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（11:21〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=681s"]]}, {"cat": "リングの話", "t": "「重荷」ではなく「責任」", "b": "長い間、記者に「家名の重み」と言われても意味が分からなかったと、ワグナーJr.は話す。好きなものは重荷にならず、自分にとっては先祖が築いた名前への責任だという。WWEに「世界一美しい覆面」と呼ばれたのが最高のほめ言葉だそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=726s"]]}, {"cat": "体のこと", "t": "体は神殿、でも自分で打ちつけている", "b": "17年の間に体は何度も悲鳴を上げたと、ワグナーJr.は話す。体は神殿だと言いながら、その神殿を自分で痛めつけている矛盾があるという。夢は、力と健康を保ってもっと長く戦い続けることだそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（12:06〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=726s"]]}, {"cat": "暮らし", "t": "週に5回飛行機に乗る生活", "b": "日本から戻って1年8か月、休みなく週に5回ほど飛行機に乗っていると、ワグナーJr.は話す。空港と飛行機とホテルが自宅のようなものだという。家にいられる日は自分のベッドを楽しみ、父と映画に行ったり母と夕食をとったりするそうだ。", "sp": "イホ・デ・ドクトル・ワグナーJr.", "d": "2026-09-08", "how": "エル・ウニベルサル紙の番組で（字幕を全文確認）", "art": "ext-GZbsE7ddJMg", "src": [["番組のYouTube（12:56〜）", "https://www.youtube.com/watch?v=GZbsE7ddJMg&t=776s"]]}]);
  ARTICLES.push({ id: "ext-GZbsE7ddJMg", d: "2026-09-08", show: "ext", who: ["Hijo de Dr. Wagner Jr."], t: "イホ・デ・ドクトル・ワグナーJr.の回　6台のカメラ、家族という「クッション」", lead: "エル・ウニベルサル紙の番組に出た約15分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Hijo de Dr. Wagner Jr."].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-GZbsE7ddJMg").map((x) => [x.t, x.b, x.sp])), open: ["大会の宣伝の部分は除いた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=GZbsE7ddJMg"]] });
  if (!ROSTER.find((r) => r[1] === "Lil Yachty")) ROSTER.push(["リル・ヨッティ", "Lil Yachty", "lg", "ラッパー", "", "", ""]);
  if (!PROFILES["Lil Yachty"]) PROFILES["Lil Yachty"] = { lead: "幼稚園の誕生日会もWWF一色だった筋金入りのファン。ラッパーとして成功した後、自腹で会場に通い続けてWWEと契約し、トリック・ウィリアムズの影響で暮らしまで変えた。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Lil%20Yachty"]], moves: [], facts: [] };
  if (PROFILES["Lil Yachty"]._weak) { PROFILES["Lil Yachty"].lead = "幼稚園の誕生日会もWWF一色だった筋金入りのファン。ラッパーとして成功した後、自腹で会場に通い続けてWWEと契約し、トリック・ウィリアムズの影響で暮らしまで変えた。"; delete PROFILES["Lil Yachty"]._weak; }
  PROFILES["Lil Yachty"].facts.push(...[{"cat": "リングの話", "t": "デビュー戦の翌朝は全身が痛い", "b": "デビュー戦の翌朝、肩もひざもすねも腰も痛く、人生で一番の痛みだったという。一番効いたのはバロン・コービンのラリアットで、子どものころJBLのラリアットを見て「どんな感じだろう」と思っていたが、息ができなくなったそうだ。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（0:52〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=52s"]]}, {"cat": "リングの話", "t": "何千回のライブとも違った", "b": "試合中は歓声に囲まれて刺激が強すぎ、時間の感覚がなくなったという。何百回もライブをしてきた会場なのに、まったく違う感覚だったそうだ。最初にロープから跳ぶ技を練習したときは怖くて、しばらくロープの上で固まったと話す。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（4:15〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=255s"]]}, {"cat": "リングの話", "t": "なりたかったのはマネージャー", "b": "もともと試合をするつもりはなく、ポール・ヘイマンに次ぐ「史上2番目のマネージャー」や、ブランドのGMをやってみたかったという。試合はトリプルHが見たかったのではと笑う。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（6:39〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=399s"]]}, {"cat": "リングに来るまで", "t": "幼稚園の誕生日会もWWF", "b": "幼稚園の誕生日会はWWFの「アティテュード」がテーマだったという。兄の影響でWCWも見て、プロレスのゲームを次々に遊び、毎週RAWを見て育ったそうだ。高校でいったん離れたが、2024年に地元アトランタの大会を見に行って、一気に熱が戻ったと話す。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（8:14〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=494s"]]}, {"cat": "リングに来るまで", "t": "自腹で通い続けて契約", "b": "「WWEに入る」という目標を立て、自腹で飛行機とホテルを取って毎週のように大会に通ったという。昔のWWFのTシャツを着たり、客席で携帯ゲーム機の画面を見せたりして話題になったそうだ。音楽担当の人に「床掃除でも何でもやる」と頼み続け、トリックの入場の付き添いをきっかけに、ブルース・プリチャードから契約を持ちかけられたと話す。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（10:36〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=636s"]]}, {"cat": "リングに来るまで", "t": "浮かないように筋を通した", "b": "有名人が突然出てくるとプロレスファンに嫌がられるのを知っていたので、レッスルマニアの前に何度か出て、トリックとの友情を見せてから付き添いたいと頼んだという。数か月は交通費も自分で出していたそうだ。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（13:05〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=785s"]]}, {"cat": "暮らし", "t": "オーランドに家を買うほど本気", "b": "本格的に練習を始めたのは3か月ほど前で、何事も極端にやる性格なので、オーランドに家を買おうとしているほどだという。毎日2回の練習をこなしながら、夜は朝までスタジオで曲を作っていたそうだ。コーチのノーマン・スマイリーの練習には一度も遅れなかったと話す。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（15:24〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=924s"]]}, {"cat": "体のこと", "t": "トリック・ウィリアムズが変えた生活", "b": "トリック・ウィリアムズは兄のような存在で、人生で一番良い影響をくれた人だという。夜型で乱れがちなラッパーの暮らしから、規則正しく健康的なトリックの生き方を見て、食事やトレーニングを変え、体重も落ちたそうだ。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（16:59〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=1019s"]]}, {"cat": "リングの話", "t": "受け身が一番つらかった", "b": "一番難しかったのは受け身で、何か月も頭や背中を打ちながら体に覚えさせたという。運動は苦手で、これまで一度もけがをしたことがないのは何もしてこなかったからだと笑う。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（26:41〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=1601s"]]}, {"cat": "体のこと", "t": "10年続いた薬物をやめた", "b": "10年ほど続けていた薬物（コデイン入りのシロップ）を5〜6か月前にやめたという。離脱症状はつらかったが、トリックの影響も大きかったそうで、「美化するつもりはない、正直に話しているだけ」と強調している。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（27:30〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=1650s"]]}, {"cat": "好きなもの", "t": "ナイキのシューズを特注", "b": "ナイキと契約しているので、練習で履き慣れたナイキのレスリングシューズを、トリックに合わせた白と金で特注したという。服が大好きでもっと派手な衣装も用意していたが、トリックとそろえることを選んだそうだ。", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で（字幕を全文確認）", "art": "ext-ARR4GR7xxmQ", "src": [["番組のYouTube（29:04〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=1744s"]]}]);
  if (PROFILES["Trick Williams"]) PROFILES["Trick Williams"].facts.push({"cat": "暮らし", "t": "規則正しく健康的な生き方", "b": "トリックは毎日の予定がきちんとしていて健康的な生活を送り、妻のために必ずドアを開けて荷物を持つような人で、その姿に影響されて生活を変えたと、リル・ヨッティが話している", "sp": "リル・ヨッティ", "d": "2026-09-15", "how": "クリス・ヴァン・ヴリートの番組で、リル・ヨッティの話（字幕を全文確認）", "src": [["番組のYouTube（16:59〜）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ&t=1019s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-ARR4GR7xxmQ", d: "2026-09-15", show: "ext", who: ["Lil Yachty"], t: "リル・ヨッティの回　デビュー戦の翌日に", lead: "クリス・ヴァン・ヴリートの番組に出た約87分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Lil Yachty"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-ARR4GR7xxmQ").map((x) => [x.t, x.b, x.sp])), open: ["30分以降は今回は読んでいない。", "薬物の話は本人が話した範囲だけを載せた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=ARR4GR7xxmQ"]] });
  if (!ROSTER.find((r) => r[1] === "Joe Tessitore")) ROSTER.push(["ジョー・テシトーレ", "Joe Tessitore", "lg", "実況", "", "", ""]);
  if (!PROFILES["Joe Tessitore"]) PROFILES["Joe Tessitore"] = { lead: "ボクシングやアメフトでも知られる実況の大ベテラン。南イタリアから来た母方の大家族に育てられ、準備に妥協しない姿勢の根っこには、家族への感謝と信仰がある。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Joe%20Tessitore"]], moves: [], facts: [] };
  if (PROFILES["Joe Tessitore"]._weak) { PROFILES["Joe Tessitore"].lead = "ボクシングやアメフトでも知られる実況の大ベテラン。南イタリアから来た母方の大家族に育てられ、準備に妥協しない姿勢の根っこには、家族への感謝と信仰がある。"; delete PROFILES["Joe Tessitore"]._weak; }
  PROFILES["Joe Tessitore"].facts.push(...[{"cat": "家族", "t": "南イタリアから来た母", "b": "母は南イタリアで生まれ育ち、英語を話せないままニューヨークに渡ってきたという。母方は9人きょうだいで、おじやおばが皆で子どもたちを育てたので、いとこは兄弟姉妹のようなものだそうだ。今も健在の母は情熱的で、とても愛情深い人だと話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（4:58〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=298s"]]}, {"cat": "家族", "t": "テレビで英語を話す誇り", "b": "イタリア語なまりの祖父母に囲まれて育ったので、全国放送で英語で話していること自体が、おじやおばにとって特別なことなのだという。母の一家が歩んできた道を思うと、それが原動力になると話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（6:33〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=393s"]]}, {"cat": "好きなもの", "t": "百科事典を読みふける子ども", "b": "子どものころ、1970年代に家に来た百科事典を部屋で読みふけるほど知識欲が強かったという。特にスポーツの歴史が好きだったそうだ。今も、徹底的に調べれば放送は楽になるという考えで準備していると話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（9:40〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=580s"]]}, {"cat": "家族", "t": "妹の死と父", "b": "妹を遺伝性の病気で亡くし、家族は大きな影響を受けたという。父は人のために尽くす気前の良い人だったが、アルコール依存症で、断酒を誇りにしていたそうだ。そうした家庭だったので、子どものころは笑顔の少ない、とても真面目な子だったと話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（11:14〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=674s"]]}, {"cat": "信仰", "t": "カトリックの信仰と許し", "b": "敬虔なカトリック信者で、イエズス会の教育を受けたという。自分も罪人の一人として、亡くなった父の多くのことを許したそうだ。フロントガラスがバックミラーよりずっと大きいのは前を見るためだ、という考えで、過去はあまり振り返らないと話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（14:29〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=869s"]]}, {"cat": "家族", "t": "競馬とカードの大家族", "b": "大家族の集まりでは、料理と長い食卓、そして競馬やトランプ、スポーツの話が中心だったという。親族の多くはピザ店やパン屋、魚屋など食べ物の仕事をしていたそうだ。熱く大げさな話し方は、その食卓で身についたと振り返る。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（17:40〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=1060s"]]}, {"cat": "暮らし", "t": "熱量が強く見えがち", "b": "仕事では常に熱量が9か10に見えてしまい、若いスタッフに誤解されないよう気をつけているという。中途半端を何より嫌い、毎日1%でも良くなろうとしていると話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（19:59〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=1199s"]]}, {"cat": "家族", "t": "家族に仕える父でいたい", "b": "自分はまず息子と娘と妻に仕える人間だと考えているという。夜行便が続いても、家族のためなら苦にならないそうだ。イタリアでは聖ヨセフの日が父の日で、一歩下がって家族を支える存在を大事にしていると話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（25:35〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=1535s"]]}, {"cat": "リングに来るまで", "t": "陸軍式の男子校", "b": "父方の祖父も通った、陸軍の予備役訓練がある私立の男子校に進んだという。毎朝の点検や教練があり、平日は軍服を着て通ったそうだ。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（28:46〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=1726s"]]}, {"cat": "リングに来るまで", "t": "大けがが人生を変えた", "b": "高校のアメフトの練習で足首を大けがし、3度の再建手術を受けたという。松葉づえの時期に、指導役の修道士に首根っこをつかまれ、スピーチと弁論をやるよう命じられたそうだ。内気だった自分が人前で話す道に進んだのは、その修道士のおかげだと話す。", "sp": "ジョー・テシトーレ", "d": "2026-09-15", "how": "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）で（字幕を全文確認）", "art": "ext-TH2gmglpJf0", "src": [["番組のYouTube（29:31〜）", "https://www.youtube.com/watch?v=TH2gmglpJf0&t=1771s"]]}]);
  ARTICLES.push({ id: "ext-TH2gmglpJf0", d: "2026-09-15", show: "ext", who: ["Joe Tessitore"], t: "ジョー・テシトーレの回　大家族とけがが作った実況者", lead: "アンドレ・ウォードの番組（ALL THE SMOKE FIGHT）に出た約90分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Joe Tessitore"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-TH2gmglpJf0").map((x) => [x.t, x.b, x.sp])), open: ["30分以降（放送の仕事や、放送中に倒れた出来事など）は今回は読んでいない。", "父親については本人が話した範囲だけを載せた。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=TH2gmglpJf0"]] });
