  if (!PROFILES["Simone Johnson"]) PROFILES["Simone Johnson"] = { lead: "ザ・ロックの娘として生まれ、四世代続くレスラー一族に育ったシモーン。馬と暮らし、いまは両親の制作会社で映画づくりを学ぶ素顔を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Simone%20Johnson"]], moves: [], facts: [] };
  if (PROFILES["Simone Johnson"]._weak) { PROFILES["Simone Johnson"].lead = "ザ・ロックの娘として生まれ、四世代続くレスラー一族に育ったシモーン。馬と暮らし、いまは両親の制作会社で映画づくりを学ぶ素顔を語った。"; delete PROFILES["Simone Johnson"]._weak; }
  PROFILES["Simone Johnson"].facts.push(...[{"cat": "暮らし", "t": "最近の口ぐせは「グルーヴィー」", "b": "シモーンは、気に入った言葉が頭にこびりつくと、しばらく言い続けてしまうタイプだという。いまのお気に入りは「グルーヴィー」で、本人いわく新しい口ぐせのようなものだそうだ。以前は「ジャクスタポーズ」という言葉を使いすぎていた時期もあったと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（0:54〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=54s"]]}, {"cat": "好きなもの", "t": "乗馬は母の影響で始めた", "b": "乗馬のきっかけは、子どものころ母が馬に乗っていたことだという。シモーンも子どもの時に乗っていたが、いったん離れ、6年ほど前にまた始めたと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（4:49〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=289s"]]}, {"cat": "体のこと", "t": "馬の世話が心を整えてくれる", "b": "馬に乗るのも世話をするのも、気持ちを落ち着かせてくれるとシモーンは話す。頭の中がいっぱいの日や機嫌が悪い日は、動物のために何かすると自分の悩みが小さく思えるそうだ。気分転換として一番効くという。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（5:38〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=338s"]]}, {"cat": "暮らし", "t": "馬を何頭も飼っている", "b": "シモーンは馬を何頭も飼っていて、種類もそれぞれ違うという。名前はフィニアス、バッキー、カソ、キティなど。最初に飼った馬は「スクービー・ドゥー」で、いまは25歳。草を食べて余生をのんびり過ごしているそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（6:26〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=386s"]]}, {"cat": "暮らし", "t": "雄牛「ソウル・ブリー」の写真", "b": "シモーンは、雄牛「ソウル・ブリー」の写真をコーディに送ったという。ブラーマ種の雄牛で、名前は父のブラーマ・ブルのタトゥーにちなんだものだと認めている。大きな犬のようだと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（8:00〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=480s"]]}, {"cat": "家族", "t": "母は最大の憧れのひとり", "b": "自分は母の娘で世界一の幸運だとシモーンは話す。母の物の見方はとても独特で、どんな問題でも自分では思いつかない答えをくれるそうだ。革新的なところが大好きだという。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（10:23〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=623s"]]}, {"cat": "家族", "t": "WWEを離れて母との距離が縮まった", "b": "WWEを離れてから、シモーンは母とより近くで仕事をしているという。新しい仕事の一番の良さは、母と過ごす時間がぐっと増えたことだそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（11:16〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=676s"]]}, {"cat": "暮らし", "t": "両親の制作会社で「ジュニア・エグゼクティブ」", "b": "シモーンは両親の制作会社セブン・バックス・プロダクションズで働いていて、肩書きはジュニア・エグゼクティブらしい。脚本を読んでメモを取り、作家や監督、プロデューサーとの打ち合わせにも同席している。会社は、デジタル部門を含めて15人ほどだという。映画づくりは世界一難しいと言われる通りで、学ぶことばかりだと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（12:05〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=725s"]]}, {"cat": "暮らし", "t": "物議をかもす話題でも声を上げてきた", "b": "シモーンは、世間で議論になる話題や少数派の意見にも触れてきたという。そのたびにネットでは激しく叩かれたが、「声を上げてくれてありがとう」とファンから声が届いたそうだ。それがいちばん誇りに思える出来事だと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（15:59〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=959s"]]}, {"cat": "暮らし", "t": "脚本は他の人のメモを見て読み直す", "b": "シモーンは、脚本を読むとき、自分の感想だけでなくチーム全体の視点でも考えるようにしているという。他のメンバーのメモを見てからもう一度読み返すと、なぜ直したのかが分かり、求められているものがはっきりするそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（18:22〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1102s"]]}, {"cat": "家族", "t": "両親ともに「タイプA」", "b": "ビジネスの勘は父方・母方どちらからかと聞かれ、両親ともに几帳面な「タイプA」の性格だとシモーンは話す。その性質を自分も受け継いで、母のタイプAをできるだけ盗みたいと思っているそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（19:12〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1152s"]]}, {"cat": "リングの話", "t": "NXTで一番相性が良かったのはイーサン・ペイジ", "b": "NXTで一番好きな共演相手はイーサン・ペイジだと、シモーンは即答した。遠慮がなく自信満々で、画面ではちょっと嫌なヤツなのに、最高に面白いのが魅力だという。彼とのやりとりでは、アバの別の顔を引き出せたそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（24:53〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1493s"]]}, {"cat": "好きなもの", "t": "「レッド・デッド2」は馬に乗って遊ぶ", "b": "シモーンは「レッド・デッド・リデンプション2」をプレイしているが、まだクリアしていないという。ずっと馬に乗って走り回っているからだそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（26:29〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1589s"]]}, {"cat": "好きなもの", "t": "「カウガール」とはまだ名乗れない", "b": "自分は乗馬愛好家ではあるが、カウガールを名乗るには早いとシモーンは話す。ウエスタン乗馬で馬を扱う人たちには、まだ認められていない気がするそうだ。ネットで叩かれたくないという。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（27:16〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1636s"]]}, {"cat": "リングに来るまで", "t": "9歳でプロレスを見始め、祖母が待っていた", "b": "シモーンがプロレスを見始めたのは9歳のとき、父が2011年に戻ってきた頃だという。祖母はずっとその時を待っていたようで、家は記念品の博物館のようだったそうだ。毎週末に祖母の家へ行き、ビデオやDVDを見せてもらったと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（39:18〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2358s"]]}, {"cat": "好きなもの", "t": "一番好きなレスラーはエッジ", "b": "シモーンの一番好きなレスラーはエッジで、公の場で話したのは初めてかもしれないという。子どものころは2006年から2009年ごろの試合をよく見ていたそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（40:50〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2450s"]]}, {"cat": "家族", "t": "四世代つづく家系図に圧倒された", "b": "家系図を拡大して見たとき、あまりの広がりに驚いたとシモーンは話す。曾祖父は大酋長ピーター・マイビア、祖父はロッキー・ジョンソン、父はザ・ロックで、シモーンが四世代目になる。とても謙虚な気持ちになる、と話している。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（44:52〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2692s"]]}, {"cat": "好きなもの", "t": "生涯ベストバウトはシャーロット対リア", "b": "一番好きな試合は、2023年のレッスルマニア39でのシャーロット対リア・リプリーだという。現地で見ていて、これまで見た中で最高の試合だと思ったそうだ。二人にはずっと畏敬の念を抱いていると話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（46:32〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2792s"]]}, {"cat": "リングの話", "t": "父の登場とブーイングが見方を変えた", "b": "年間最大の祭典を前にした騒動のあと、NXTの大会の日に、ヘッドライターから「プロモが流れたらブーイングが出るかも」と言われたとシモーンは話す。実際にネット上の批判が広がり、ファンやこの業界の見方が変わったという。いまは、自分の道に自信を持てるようになったので感謝しているそうだ。その日はコーディが気づかってくれたことも覚えている、と話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（48:58〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2938s"]]}, {"cat": "リングの話", "t": "NXTのGM時代のハイライト", "b": "シモーンは、WWE史上最年少のゼネラルマネージャーで、NXT初の女性GMだったという。一番の思い出は、2つ目の女子王座「女子ノースアメリカン王座」を発表できたことだそうだ。2024年から2025年にかけて、女子部門が毎週のように盛り上がった時期にGMを務められて幸せだと話す。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（53:04〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3184s"]]}, {"cat": "リングの話", "t": "WWEを離れる決断は、とてもつらかった", "b": "約1年前から考えていて、契約が切れる2月に向けて決めたとシモーンは話す。理由はいくつもあるが、WWEでは自分が成長できる立場にないと感じたそうだ。在籍した時間には感謝していて、何も変えたくないが、別の世界で学びたかったという。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（56:22〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3382s"]]}, {"cat": "体のこと", "t": "けがを治してから、またリングへ", "b": "リングに戻れるかと聞かれ、戻りたい気持ちはあるとシモーンは話す。ただし、いくつかのけがを先に治す必要があるそうだ。WWEにいた最後の2か月は痛みがひどくて試合ができず、リングに上がれないのがさみしいという。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（59:34〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3574s"]]}, {"cat": "暮らし", "t": "恋人は未経験からプロレスを練習中", "b": "シモーンの恋人のタチアナは、プロレスの練習をしているという。打撃の精度が高く、しかも一度も当てたことがないのが印象的だと話す。テレビの世界から来た人なので、業界を外から見る視点が新鮮で、学ぶことが多いそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（1:04:33〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3873s"]]}, {"cat": "リングに来るまで", "t": "大学進学より、オーランドでの練習を選んだ", "b": "シモーンはニューヨーク大学で政治学を学ぶ予定だったが、オーランドに残ってプロレスを習うことを選んだという。いまも学校に戻ることは頭をよぎるそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（1:07:00〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=4020s"]]}]);
  if (PROFILES["Ethan Page"]) PROFILES["Ethan Page"].facts.push({"cat": "暮らし", "t": "イーサン・ペイジは遠慮のない人気者", "b": "NXTに必要だった存在で、自信にあふれ、画面ではちょっと嫌なヤツなのに、舞台裏では優しくて最高の人だと、シモーンが話している。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で、シモーン・ジョンソンの話（公式字幕を全文確認）", "src": [["公式YouTube（24:53〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1493s"]], "by": "第三者の話"});
  if (PROFILES["Tatum"]) PROFILES["Tatum"].facts.push({"cat": "暮らし", "t": "タトゥムの活躍をずっと応援している", "b": "デビューの時期が近かったこともあり、ずっと応援してきた。ライラとの抗争はNXTで一番好きな抗争のひとつで、今の活躍がうれしい、とシモーンが話している。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で、シモーン・ジョンソンの話（公式字幕を全文確認）", "src": [["公式YouTube（55:36〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3336s"]], "by": "第三者の話"});
  if (PROFILES["Brian Gewirtz"]) PROFILES["Brian Gewirtz"].facts.push({"cat": "暮らし", "t": "ブライアン・ガーウィッツは欠かせない存在", "b": "セブン・バックスでは、父と並んでブライアン・ガーウィッツがかけがえのない存在だと、シモーンが話している。本人は照れるだろうが、素晴らしい人だそうだ。", "sp": "シモーン・ジョンソン", "d": "2026-09-17", "how": "コーディの番組で、シモーン・ジョンソンの話（公式字幕を全文確認）", "src": [["公式YouTube（13:37〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=817s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
