  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "暮らし", "t": "41歳で、お酒を控えめにし始めた", "b": "コーディは41歳になったと話す。年を重ねたと実感する出来事として、コイン収集に興味が出てきたこと、そしてお酒をぐっと減らしたことを挙げている。甘いお酒は想像するだけで体が受けつけなくなったそうだ。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（3:15〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=195s"]]}, {"cat": "暮らし", "t": "庭の巣箱カメラで野鳥を観察", "b": "コーディは庭に、カメラ付きの巣箱を置いているという。新しい鳥が来るたびに通知が届き、ショウジョウコウカンチョウやフィンチ、リスなどが来たそうだ。ブルージェイにはまだ会えていないという。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（4:02〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=242s"]]}, {"cat": "家族", "t": "5歳の娘と、16歳の愛犬", "b": "コーディの娘のリバティは5歳で、愛犬のファラオは16歳だという。この日の朝、ファラオが粗相をしてしまい、バスルームにいたコーディに向かって、娘が「エマージェンシー！」と叫びながらドアを叩いたそうだ。ファラオは無事で、のんびり暮らしていると話す。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（6:26〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=386s"]]}, {"cat": "暮らし", "t": "怒りを静めるのはファンとの交流", "b": "コーディは、感情を自分で整えるようになってきたと話す。試合の結末や筋書きに腹が立っても、ファンと触れ合うと気持ちが落ち着くそうだ。これが一番効く方法になったという。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（8:51〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=531s"]]}, {"cat": "好きなもの", "t": "子どものころ父がくれた馬の図鑑", "b": "コーディは、父が子どものころ世界の馬の品種をまとめた本をくれたと話す。兄のダスティンはそのことを覚えていたそうだ。いまは「レッド・デッド・リデンプション2」で、その頃の馬の記憶がよみがえっているという。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（26:29〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=1589s"]]}, {"cat": "家族", "t": "娘にはスター・ウォーズを押しつけない", "b": "コーディは「スター・ウォーズ」が大好きだという。娘は少し興味を持ち始めたが、無理には勧めないつもりだそうだ。いつか娘が9歳になったとき、自分から「見よう」と言ってくれる日を待っていると話す。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（45:39〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=2739s"]]}, {"cat": "体のこと", "t": "「痛くても出る。けがなら出ない」", "b": "コーディは育成施設での教えとして、「痛みをこらえて試合はしても、けがを抱えて試合はするな」と話す。自分は背中の筋肉を完全に断裂した状態で試合に出たことがあり、説得力がないと笑っている。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（59:34〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=3574s"]]}, {"cat": "家族", "t": "父は中学のフットボールのコーチだった", "b": "コーディの父は、地元の中学生のフットボールのコーチをしていたという。周りの人たちは父をレスラーのダスティではなく「コーチ」と呼んでいたそうだ。高校でも指導してほしいという声があったが、学位がなければ公立校のコーチになれず、実現しなかったと話す。", "sp": "コーディ・ローデス", "d": "2026-09-17", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-b7RYDD87QVs", "src": [["公式YouTube（1:07:50〜）", "https://www.youtube.com/watch?v=b7RYDD87QVs&t=4070s"]]}]);
  ARTICLES.push({ id: "wdywta-b7RYDD87QVs", d: "2026-09-17", show: "wdywta", who: ["Simone Johnson", "Cody Rhodes"], t: "シモーン・ジョンソンの回　馬、一族、そしてWWE退団の決断", lead: "コーディ・ローデスの番組に出た約73分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Simone Johnson", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-b7RYDD87QVs").map((x) => [x.t, x.b, x.sp])), open: ["シモーンとコーディの発言が入り混じる箇所（ドリームチームの話など）は、誰の発言か判断できなかったため載せていない。", "シモーンの信仰についての発言は、今回の記事では扱っていない。", "広告部分、コーディ側の昔話（ファイナル・ボスをめぐる案、カウボーイハットの案など）は省いた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=b7RYDD87QVs"]] });
  PROFILES["Lash Legend"].facts.push(...[{"cat": "リングの話", "t": "放送の経験とバスケの足さばきが武器に", "b": "ラッシュ・レジェンドは、大学時代にスポーツ局やESPNUで実習し、マイクを持って話す経験を積んだという。そのため育成施設のマイクの授業で習うことの多くが、すでに知っている内容だったと話す。バスケの足さばきも約6メートル四方のリングで生きていて、これまでの歩みが全部つながっていると語っている。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（15:25〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=925s"]]}, {"cat": "リングの話", "t": "海外の契約より、マイクの映像に惹かれた", "b": "WNBAを解雇された後、中国やロシアのチームから好条件の話が来ていたが、9〜10か月も海外に住むのは嫌だったとラッシュ・レジェンドは話す。その頃からロック、ストーンコールド、マッチョマンなどのマイク映像をYouTubeで見続けていたという。子どもの頃にもアティテュード時代の番組を見ていたそうだ。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（19:20〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1160s"]]}, {"cat": "リングの話", "t": "募集ページから応募し、1週間で返事が来た", "b": "ラッシュ・レジェンドは、おすすめに出てきた育成施設の動画から公式サイトを調べ、応募ページを見つけたという。人生で初めて応募書類を書き、写真と経歴を添えて送ったところ、1週間以内にキャノンから試験の誘いが届いたそうだ。当時のエージェントには、海外契約を断ってこちらに挑戦すると告げたと話す。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（21:02〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1262s"]]}, {"cat": "リングの話", "t": "初日は「人生で一番きつい」のに大好きだった", "b": "育成施設で初めて練習した日、これまでのどの競技よりも難しいと感じたとラッシュ・レジェンドは話す。それでも受け身を取るたびにアドレナリンが出て、なぜこんなに好きなのかと思ったそうだ。カメラの前で演じることが生まれつき好きだったことも、背中を押したと語っている。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（24:48〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1488s"]]}, {"cat": "リングの話", "t": "この業界で一番学んだのは「忍耐」", "b": "ラッシュ・レジェンドは、自信は元からあったが、この世界でいちばん学んだのは忍耐だと話す。何でもすぐに欲しがる性格で、思い通りにならないことが多かったという。待つ価値を知ってからは、物事は起こるべくして起こると考えるようになったそうだ。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（26:40〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1600s"]]}, {"cat": "リングの話", "t": "NXTのトーク番組は高校時代と同じだった", "b": "NXTではまず「Lashing Out with Lash Legend」というトーク番組を任されたとラッシュ・レジェンドは話す。高校でも自分のトーク番組を持っていたので、ぐるりと元に戻った感覚だったという。毒舌を振るううちにリングにも立つことになったが、今振り返ると、当時はまだ早かったと理解していると語っている。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（27:28〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1648s"]]}, {"cat": "リングの話", "t": "初期の試合で「大成功」と思い込んでいた", "b": "最初の数試合は大成功だと思い込んでいたとラッシュ・レジェンドは話す。何週間もSNSでトレンド入りしていたが、実際には悪い話題ばかりで、後から知ったそうだ。根拠のない自信だったと笑いながら振り返っている。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（28:14〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1694s"]]}, {"cat": "リングの話", "t": "施設の専門コーチを頼り切った", "b": "最初は思ったほど楽にできず、自分の技が正しく出せていると思っても、信頼するコーチに見てもらうと違ったとラッシュ・レジェンドは話す。激しさはフィット・フィンレー、返し技はノーマン・スマイリー、パワー系はマット・ブルームに教わったという。ショーン・マイケルズには、求める姿や立ち居振る舞いを直接聞いたそうだ。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（30:27〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=1827s"]]}, {"cat": "リングの話", "t": "ニア・ジャックスはNXTでの抗争相手だった", "b": "ニア・ジャックスは、NXTに来たいと言って、まずラッシュ・レジェンドとの抗争を望んだ相手だという。互いにパワー型で、ラッシュ・レジェンド自身を持ち上げられる数少ない相手だったため、技の幅も広がったと話す。リングが壊れそうなほどの試合をして、ニアから多くを学んだそうだ。その後、ニアがタッグを組もうと声をかけてくれたとも語っている。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（41:23〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=2483s"]]}, {"cat": "リングの話", "t": "相性の良さが試合の質を決める", "b": "ニア・ジャックスとは敵同士のときから相性がよく、最高の試合の多くは相性の良さから生まれるとラッシュ・レジェンドは話す。逆に、動きのタイミングが合わない相手もいて、水のように滑らかにいかないと感じることがあるという。ただ、信頼するプロデューサーには、思ったより悪くなかったと言われることも多いそうだ。", "sp": "ラッシュ・レジェンド", "d": "2026-09-25", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-lash", "src": [["公式YouTube（43:24〜）", "https://www.youtube.com/watch?v=YOEcWR40VH0&t=2604s"]]}]);
  { const A = ARTICLES.find((a) => a.id === "wys-lash"); if (A) A.points.push(...[["放送の経験とバスケの足さばきが武器に", "ラッシュ・レジェンドは、大学時代にスポーツ局やESPNUで実習し、マイクを持って話す経験を積んだという。そのため育成施設のマイクの授業で習うことの多くが、すでに知っている内容だったと話す。バスケの足さばきも約6メートル四方のリングで生きていて、これまでの歩みが全部つながっていると語っている。", "ラッシュ・レジェンド"], ["海外の契約より、マイクの映像に惹かれた", "WNBAを解雇された後、中国やロシアのチームから好条件の話が来ていたが、9〜10か月も海外に住むのは嫌だったとラッシュ・レジェンドは話す。その頃からロック、ストーンコールド、マッチョマンなどのマイク映像をYouTubeで見続けていたという。子どもの頃にもアティテュード時代の番組を見ていたそうだ。", "ラッシュ・レジェンド"], ["募集ページから応募し、1週間で返事が来た", "ラッシュ・レジェンドは、おすすめに出てきた育成施設の動画から公式サイトを調べ、応募ページを見つけたという。人生で初めて応募書類を書き、写真と経歴を添えて送ったところ、1週間以内にキャノンから試験の誘いが届いたそうだ。当時のエージェントには、海外契約を断ってこちらに挑戦すると告げたと話す。", "ラッシュ・レジェンド"], ["初日は「人生で一番きつい」のに大好きだった", "育成施設で初めて練習した日、これまでのどの競技よりも難しいと感じたとラッシュ・レジェンドは話す。それでも受け身を取るたびにアドレナリンが出て、なぜこんなに好きなのかと思ったそうだ。カメラの前で演じることが生まれつき好きだったことも、背中を押したと語っている。", "ラッシュ・レジェンド"], ["この業界で一番学んだのは「忍耐」", "ラッシュ・レジェンドは、自信は元からあったが、この世界でいちばん学んだのは忍耐だと話す。何でもすぐに欲しがる性格で、思い通りにならないことが多かったという。待つ価値を知ってからは、物事は起こるべくして起こると考えるようになったそうだ。", "ラッシュ・レジェンド"], ["NXTのトーク番組は高校時代と同じだった", "NXTではまず「Lashing Out with Lash Legend」というトーク番組を任されたとラッシュ・レジェンドは話す。高校でも自分のトーク番組を持っていたので、ぐるりと元に戻った感覚だったという。毒舌を振るううちにリングにも立つことになったが、今振り返ると、当時はまだ早かったと理解していると語っている。", "ラッシュ・レジェンド"], ["初期の試合で「大成功」と思い込んでいた", "最初の数試合は大成功だと思い込んでいたとラッシュ・レジェンドは話す。何週間もSNSでトレンド入りしていたが、実際には悪い話題ばかりで、後から知ったそうだ。根拠のない自信だったと笑いながら振り返っている。", "ラッシュ・レジェンド"], ["施設の専門コーチを頼り切った", "最初は思ったほど楽にできず、自分の技が正しく出せていると思っても、信頼するコーチに見てもらうと違ったとラッシュ・レジェンドは話す。激しさはフィット・フィンレー、返し技はノーマン・スマイリー、パワー系はマット・ブルームに教わったという。ショーン・マイケルズには、求める姿や立ち居振る舞いを直接聞いたそうだ。", "ラッシュ・レジェンド"], ["ニア・ジャックスはNXTでの抗争相手だった", "ニア・ジャックスは、NXTに来たいと言って、まずラッシュ・レジェンドとの抗争を望んだ相手だという。互いにパワー型で、ラッシュ・レジェンド自身を持ち上げられる数少ない相手だったため、技の幅も広がったと話す。リングが壊れそうなほどの試合をして、ニアから多くを学んだそうだ。その後、ニアがタッグを組もうと声をかけてくれたとも語っている。", "ラッシュ・レジェンド"], ["相性の良さが試合の質を決める", "ニア・ジャックスとは敵同士のときから相性がよく、最高の試合の多くは相性の良さから生まれるとラッシュ・レジェンドは話す。逆に、動きのタイミングが合わない相手もいて、水のように滑らかにいかないと感じることがあるという。ただ、信頼するプロデューサーには、思ったより悪くなかったと言われることも多いそうだ。", "ラッシュ・レジェンド"]]); }
  if (!ROSTER.find((r) => r[1] === "Kiana James")) ROSTER.push(["キアナ・ジェームズ", "Kiana James", "lg", "元体操選手のレスラー", "", "", ""]);
  if (!PROFILES["Kiana James"]) PROFILES["Kiana James"] = { lead: "体操と陸上の家系に育ち、大学ではチアとダンスに打ち込んだ。初めてのジム企画でも、体操仕込みの身体能力で難メニューを次々こなした。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Kiana%20James"]], moves: [], facts: [] };
  if (PROFILES["Kiana James"]._weak) { PROFILES["Kiana James"].lead = "体操と陸上の家系に育ち、大学ではチアとダンスに打ち込んだ。初めてのジム企画でも、体操仕込みの身体能力で難メニューを次々こなした。"; delete PROFILES["Kiana James"]._weak; }
  PROFILES["Kiana James"].facts.push(...[{"cat": "好きなもの", "t": "プロテインやクレアチンを日課にしている", "b": "クレアチンは今朝も飲んだと話す。差し入れのバスケットにもクレアチンやプロテインが入っていて、ふだんから使っているようだ。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（0:52〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=52s"]]}, {"cat": "リングに来るまで", "t": "体操と陸上の家系で育った", "b": "体操と陸上競技の一家で育ち、体操の経験もあるという。大学では競技チアとダンスにも取り組んだ。人生ずっと体を動かしてきたと話す。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=98s"]]}, {"cat": "暮らし", "t": "普段は決まったメニューを繰り返すタイプ", "b": "自分は習慣の生き物で、いつも同じ種目をやりがちだと話す。苦手で不快なことは、人に手伝ってもらわないと踏み出せないという。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（1:38〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=98s"]]}, {"cat": "暮らし", "t": "ひとりでジムに行くとウォームアップを省きがち", "b": "ひとりのときは準備運動なしでいきなりトレーニングに入ってしまうと話す。この日は教わる場として、ウォームアップの重要性を聞いていた。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（2:28〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=148s"]]}, {"cat": "体のこと", "t": "全身の柔軟性にはコンプレックスがある", "b": "自分は可動域がとても狭く、上半身も下半身も固いと話す。リングの動きを見ると信じられないと言われるが、背中は本当に反らないのだという。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（3:17〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=197s"]]}, {"cat": "リングに来るまで", "t": "試合中にバック転ができるが、背中は固い", "b": "試合の最中にバック転を決められる数少ない選手だと周囲から言われた。本人は、背中が曲がらないので気合いで乗り切っていると話す。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=242s"]]}, {"cat": "リングの話", "t": "試合でのバック転はジムでも話題になった", "b": "リングでの動きを知る周囲は、試合中にバック転ができる人は多くないと驚いていた。本人は、背中が固いので毎回気合いで乗り切っていると話す。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（4:02〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=242s"]]}, {"cat": "体のこと", "t": "懸垂は24、25回できてジム新記録", "b": "ウォームアップ代わりの厳密な懸垂で、ジムの記録に並ぶ回数をこなした。周囲からはほぼ初めて見る強さだと驚かれた。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（9:02〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=542s"]]}, {"cat": "リングに来るまで", "t": "初めての逆立ち腕立てで強烈なキックを見せた", "b": "逆立ち腕立てを初めて試し、勢いよく床を蹴って体が宙に浮くほどだったという。子どものころ体操でマットなしで似た動きをしたことがあると話す。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（10:36〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=636s"]]}, {"cat": "リングに来るまで", "t": "逆立ち歩きは独学で身につけた", "b": "逆立ち歩きは、誰にも教わらず、自分で覚えたと話す。最近は手の返し方のコツを教わり、より楽に向きを変えられるようになった。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（12:58〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=778s"]]}, {"cat": "好きなもの", "t": "外で遊ぶことが大切だと考えている", "b": "今の子どもはお菓子とタブレットばかりで、外で遊ぶ機会が足りないと話す。自分の子ども時代は、母に「外で遊んできなさい」と家から出されていたという。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（14:32〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=872s"]]}, {"cat": "体のこと", "t": "グリップ付きの手袋を愛用している", "b": "鉄棒用の手袋が、棒に張り付くくらい違うと話す。ふだんあまり鉄棒をしないので、使わないと手の皮がむけてしまうそうだ。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（15:21〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=921s"]]}, {"cat": "体のこと", "t": "膝のけがで太ももの筋肉が落ちた", "b": "以前、膝を痛めて太ももの筋肉が大きく落ちたと話す。回復には時間がかかるが、今は強くなって戻ることを目標にしているという。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（16:13〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=973s"]]}, {"cat": "体のこと", "t": "握力が弱くてストラップに頼りがち", "b": "握力が弱いのが悩みで、デッドリフトなどでもストラップを使いたくなると話す。ただ、鍛えれば強くなると助言された。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（20:18〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=1218s"]]}, {"cat": "体のこと", "t": "ペグボードを初挑戦でやり遂げた", "b": "今まで挑戦したことのないペグボードに挑んだ。最初は不安だったが、壁に足を添えながら最後まで登り切り、やったと喜んだ。", "sp": "キアナ・ジェームズ", "d": "2026-09-25", "how": "アリとエミリー（Ari And Emily）の番組で（字幕を全文確認）", "art": "ext-wkW-gfCVu1w", "src": [["番組のYouTube（21:05〜）", "https://www.youtube.com/watch?v=wkW-gfCVu1w&t=1265s"]]}]);
  ARTICLES.push({ id: "ext-wkW-gfCVu1w", d: "2026-09-25", show: "ext", who: ["Kiana James"], t: "キアナ・ジェームズの回　ジムの難関メニューに初挑戦", lead: "アリとエミリー（Ari And Emily）の番組に出た約23分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Kiana James"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-wkW-gfCVu1w").map((x) => [x.t, x.b, x.sp])), open: ["同席者の発言と区別がつきにくい箇所が多く、話者が曖昧な話は載せていない。", "ジムでのトレーニング指導の中身は載せていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=wkW-gfCVu1w"]] });
