  if (!PROFILES["AJ Styles"]) PROFILES["AJ Styles"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=AJ%20Styles"]], moves: [], facts: [] };
  if (PROFILES["AJ Styles"].lead === "") PROFILES["AJ Styles"]._weak = 1;
  PROFILES["AJ Styles"].facts.push(...[{"cat": "リングの話", "t": "TNA時代に忘れられない試合がいくつもある", "b": "TNAで特別な何かを感じたのは、ロウ・キーやジェリー・リンとの試合だったとAJスタイルズは話す。年上の選手とも当たり、コーディの父ダスティ・ローデスにはフィギュア4を極めたが、太い脚を組むのがやっとだったという。ラリー・ズビスコと戦い、ロード・ウォリアーズをやっつける役も任された。アビスのテーブル戦、サモア・ジョーやクリストファー・ダニエルズとの試合、カート・アングルやケビン・ナッシュ、ブッカーTから学べたことが成長を早めたと振り返る。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（3:57〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=237s"]]}, {"cat": "リングの話", "t": "マッチョマンの最後の試合は笑える思い出", "b": "TNAでマッチョマン・ランディ・サベージの最後の試合に出たAJスタイルズは、本来は助けに走って入るはずのマッチョマンが、自分流にゆっくり歩いて出てきたのがおかしかったと話す。試合前の打ち合わせでは、スコット・ホールが説明しようとしても、マッチョマンは別の人に話しかけてしまい、ホールがあきらめたという。スコット・ホールやケビン・ナッシュと同じ試合に立つ緊張のなかで、スーパースターも普通の人と同じようにもめるのだと気づいたそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（24:27〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1467s"]]}, {"cat": "リングの話", "t": "TNAが大きくなっていく手応えを感じた", "b": "オーランドで興行を始め、テレビ局のスパイクTVに乗ったころは、何か大きなことが起きていると全員が感じていたとAJスタイルズは話す。カート・アングルやクリスチャン・ケイジがWWEから来て、視聴率も取れるようになり、最高に楽しい時期だったという。クリスチャンとはリングで初めて組んで、全体を仕切って主導権を握れる「リングの将軍」だと分かり、思った以上にうまくて感心したそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（27:39〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1659s"]]}, {"cat": "リングの話", "t": "バレットクラブのリーダーではないと言う", "b": "ネットではリーダー扱いされるが、AJスタイルズは自分がバレットクラブのリーダーだと名乗ったことはないと話す。「誰にも従わない」という集団なので、自分にも従わなくていいという考えだったという。ギャローズとアンダーソンも含め、全員が同じ重みで大事な存在でいられるようにしたかったそうだ。みんなが楽しんでいる様子が客にも伝わって、かっこいい集団に見えたと考えている。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（30:02〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1802s"]]}, {"cat": "リングの話", "t": "新日本で覚えた「酔っぱらいの法則」", "b": "日本の試合は、効いていないふりをしているわけではないとAJスタイルズは気づいたという。酔ったときは酔ったそぶりをするのではなく、まっすぐ歩こうとするのと同じで、痛くても痛くないように見せるのが新日本の試合の心理だと説明する。石井智宏が頭突きを何度も重ねて、ロープに走ったあとでようやく倒れる流れも、そう考えると納得できるという。四つの章のような長い試合で物語を語れる点にも、すぐ魅力を感じたそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（32:21〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1941s"]]}, {"cat": "リングの話", "t": "フランスの観客は人生で一番の会場だった", "b": "フランスでの試合で、AJスタイルズは悪役のはずなのに観客が「フェノミナル」の歌を歌ってくれて、気分が良かったと話す。南部ジョージア出身で南部なまりの自分が、フランスで国民的ヒーローのように愛されたことに驚いたという。人にもよく「あれが今までで最高の観客だった」と話しているそうだ。コーディとの試合の流れのなかでも、特別な空気になった夜として語っている。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（39:51〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2391s"]]}, {"cat": "リングの話", "t": "コーディとの抗争は悪役の役作りから始まった", "b": "ライブイベントでは、王者のコーディを守るため、トップロープからのカッターは出さないよう何度も念を押したとAJスタイルズは話す。ボビー・ルードから、コーディとの抗争を提案しようと考えていると聞いたときは、世の中に怒る悪役のキャラクターを作っている最中で、王座は動かせないから勝てないと思ったという。それでも再びメインイベントに戻れるのは大きなことだったそうだ。「アイ・クイット」マッチではコーディの母に3回ビンタされ、1回の予定だったと笑う。悪役の自分は普段の自分とは別で、役に入ると違う場所に連れていかれるとも話している。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（42:20〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2540s"]]}, {"cat": "リングの話", "t": "WWE初登場のロイヤルランブルは緊張していた", "b": "他人の家に引っ越してきたような気分で、ほかの選手にどう思われるか不安だったとAJスタイルズは話す。知らない人も多く、知っている人に会えたときは本当にうれしくて、そばに寄っていったという。37歳になっても、人の家に入るなら敬意を示してチームの一員になりたいという気持ちだったそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（47:58〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2878s"]]}, {"cat": "リングの話", "t": "ジョン・シナとの試合はいちばん楽にできた", "b": "AJスタイルズは、ジョン・シナとの試合は自分が経験した中でも特にやりやすかったと話す。なぜあれほど合ったのか今でも分からず、タイミングがそろい、2人とも自分の仕事に誇りを持っていたからかもしれないと考えている。シナとの試合は一つ残らず良かったと言い切り、この相性の理由は本人に聞いてほしいと笑う。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（52:52〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3172s"]]}, {"cat": "リングの話", "t": "37歳でWWEに来たからこそ強かった", "b": "AJスタイルズは37歳でWWEに入ったが、全盛期はTNA時代だったという声には同意しないと話す。WWEに来たときは人生でいちばん良い体で、しかも試合の心理を理解していたので、毎秒のように飛ぶ必要がなかったという。できるからといってやるべきとは限らず、見ている人にも分かりやすい試合のほうが大切だと語る。若いうちは気づきにくいが、年を重ねると意味が分かってくると話している。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:00:42〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3642s"]]}]);
