  if (!PROFILES["AJ Styles"]) PROFILES["AJ Styles"] = { lead: "どこで戦っても「ジョージア州ゲインズビル出身」と名乗り続け、故郷と家族を背負ってリングに立ってきたという。27年の現役を終えた今も、プロレスへの情熱は消えないと話す。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=AJ%20Styles"]], moves: [], facts: [] };
  if (PROFILES["AJ Styles"]._weak) { PROFILES["AJ Styles"].lead = "どこで戦っても「ジョージア州ゲインズビル出身」と名乗り続け、故郷と家族を背負ってリングに立ってきたという。27年の現役を終えた今も、プロレスへの情熱は消えないと話す。"; delete PROFILES["AJ Styles"]._weak; }
  PROFILES["AJ Styles"].facts.push(...[{"cat": "リングに来るまで", "t": "WCW時代の相棒エア・パリス", "b": "WCWではエア・パリスとタッグを組んでいたという。二人はWCWの選手が出場していた別の団体で抗争していて、そこを視察に来た関係者の目に留まり、WCWで機会をもらえたそうだ。今思えばひどい試合だったはずだと笑いつつ、何かを見出してもらえたと振り返る。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（2:26〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=146s"]]}, {"cat": "リングに来るまで", "t": "師匠は「リングで当たった全員」", "b": "誰に一番鍛えられたかと聞かれ、リングで向き合ったすべての相手から学んだと答える。ひどい相手との試合からも、どうすればもっと良くできたかを学べたという。昔は自分の体格が不利だと思っていたが、今ではどんな相手とも組めるちょうどいいサイズだったと感じているそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（9:33〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=573s"]]}, {"cat": "リングに来るまで", "t": "握手はしっかり握る派", "b": "業界でよくある力の抜けた握手について、WCWで出会ったテリー・テイラーがしっかり握る握手だったため、自分もそうしていたという。インディーでそれをとがめられた際に「テリー・テイラーはこうだった」と返したら相手が黙ったそうだ。もともとあの弱い握手は好きではなく、男らしい握手が好きだと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（10:21〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=621s"]]}, {"cat": "リングに来るまで", "t": "プランBはなかった", "b": "若いころは手に入るものは何でも欲しく、少しでも多く経験したくてたまらなかったという。周りに聞くうちに、自分が人並み外れて執着していたと気づいたそうだ。ほかの道は考えず、これしかないと思ってきたからこそ27年続けて引退できたと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（13:43〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=823s"]]}, {"cat": "体のこと", "t": "来年50歳、昔の世代より若い体", "b": "来年50歳になるが、自分の父は35歳の時点で今の自分より老けて見えたという。今の世代は昔の選手よりずっと体に気を配り、年を取っても体を保てるようにしていると話す。必要なら動けるだけのコンディションを保つ工夫を続けてきたそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（14:31〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=871s"]]}, {"cat": "暮らし", "t": "故郷ゲインズビルを背負って戦う", "b": "日本でも、ほかのどの団体でも、入場では必ず「ジョージア州ゲインズビル出身」とコールされてきたという。リングに上がるたびに故郷を代表していて、それは自分の家族を代表することでもあると話す。周りがみな「アトランタ出身」で済ませる中、あえて町の名前を広めたかったそうだ。フロリダ州のゲインズビルと間違えられるのは好まないと笑う。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（15:20〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=920s"]]}, {"cat": "好きなもの", "t": "日本で戦うのが大好きだった", "b": "日本でのプロレスが大好きだったという。リングで見せる力を正当に評価してくれ、全力を出せば観客も応えてくれる、敬意にあふれた文化だと話す。これまで上がった中で最高のリングは新日本プロレスのものだそうで、組み立てを見学したこともあるが、いまだに構造が分からないと感心する。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（32:21〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1941s"]]}, {"cat": "暮らし", "t": "汚い言葉は使わない", "b": "ふだんは汚い言葉を使わないことで知られ、意地悪なキャラクターを演じているときに出る言葉は本当の自分ではないという。日常会話で汚い言葉を連発するのは賢く見えないと考えているそうだ。娘とデートしたい相手が汚い言葉を使っていたら、その時点で見方が変わると話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（43:55〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2635s"]]}, {"cat": "家族", "t": "子どもたちのイニシャルを脇腹に", "b": "脇腹には子どもたちのイニシャルのタトゥーが入っていて、全員のイニシャルが「AJ」なのだという。どうせ入れるなら大きく、多少痛くても構わないと思ったが、かなり痛かったそうだ。娘が生まれるのは予想外だったため場所が残っておらず、娘の分だけ腰のあたりに後から入れたと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（45:59〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2759s"]]}, {"cat": "リングに来るまで", "t": "37歳での入団、緊張の初日", "b": "37歳でWWEに来たとき、最初はとても緊張していたという。まだ自分の家ではない、他人の家に入っていく感覚で、知らない選手たちにどう思われるかが心配だったそうだ。とにかくチームの一員になりたいという敬意の気持ちだったと話す。WWE入団時が人生で一番いい体だったとも振り返る。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（47:58〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2878s"]]}, {"cat": "家族", "t": "引退は家族と地元アトランタで", "b": "引退試合を地元に近いアトランタで迎えられたことは、自分と家族にとって大切な瞬間だったという。気持ちよく、穏やかな心で終えられたと振り返る。引退後に戻るかどうかは、マイケル・ジョーダンの言葉を借りて、戻りたくなったら戻るものだと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（56:04〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3364s"]]}, {"cat": "家族", "t": "プロレスを始めた息子に厳しい父", "b": "息子がプロレスを始め、自分はたぶん一番厳しく当たっているという。期待が高いぶん、息子は何をしても否定されると感じているかもしれないと話す。自分の昔の試合もひどかったことを思い出し、良かった点を伝えて悪い点は全部言わないよう心がけているそうだ。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（58:21〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3501s"]]}, {"cat": "リングに来るまで", "t": "憧れはビリー・キッドマン", "b": "駆け出しのころはビリー・キッドマンのようになりたかったという。シューティングスタープレスを使い始めたのも彼の影響だそうだ。ただ、その技のせいでWCWで叱られたこともあり、一度は本人を投げ飛ばしてやりたいと思ったと笑う。誰でも最初は誰かに憧れ、やがて自分らしさを見つけていくものだと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（59:06〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3546s"]]}, {"cat": "家族", "t": "息子にはあらゆる場で経験を", "b": "育成施設に行く前に、インディーや他団体などあらゆる場所で、いろいろな相手と経験を積んでほしいと考えているという。今は自分の技を多く使っているが、時間がたてば自分らしいものを見つけていくはずだと話す。失敗しないと成長できないが、今は何でも映像に残るので昔より大変だとも語る。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（59:06〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3546s"]]}, {"cat": "暮らし", "t": "ジムを立ち上げ中、リング設営は息子も", "b": "自分のジムを手に入れて準備を進めているところだという。リングをジムに運び込むときは、息子にも設営を手伝わせるつもりだそうだ。息子のためのジムでもあるので当然だと話し、レスラーなら一度か二度はリングの組み立てを覚えるべきだと考えている。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:12:45〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4365s"]]}, {"cat": "体のこと", "t": "最初に衰えを感じたのは「息」", "b": "48歳で引退するまでの道のりで一番感じたのは、どれだけ有酸素運動をしても息が以前ほど続かなくなったことだという。年を重ねるほど、トップロープを蹴って飛ぶ自分のフィニッシュは難しくなったそうだ。そのため試合の中で体力を残しておける時間を意識して作っていたと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:17:36〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4656s"]]}, {"cat": "暮らし", "t": "引退後も育成とインディーに関わる", "b": "引退後は育成施設にたびたび足を運び、インディーの現場も見て回っているという。リングには上がらなくてもプロレスから離れたわけではなく、まだまだ情熱は消えないそうだ。プロレスが好きだから、これからも助けになり貢献していきたいと話す。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:21:46〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4906s"]]}]);
  if (PROFILES["Randy Savage"]) PROFILES["Randy Savage"].facts.push({"cat": "暮らし", "t": "最後の試合の打ち合わせで話を聞かず", "b": "マッチョマンの最後の試合となった打ち合わせで、スコット・ホールが説明しようとするたびに、マッチョマンは別の人に話しかけてしまったという。ついにホールが「もう説明しない」とあきれたそうだ。大スターたちも普通の人と同じように言い合うのだと知って、おかしかったと、AJスタイルズが話している。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で、AJスタイルズの話（公式字幕を全文確認）", "src": [["公式YouTube（23:37〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1417s"]], "by": "第三者の話"});
  if (PROFILES["Christian Cage"]) PROFILES["Christian Cage"].facts.push({"cat": "暮らし", "t": "肌で感じた「リングの司令塔」", "b": "TNAで初めてクリスチャンと組み合ったとき、すぐに試合を思いどおりに組み立てられる司令塔タイプだと分かったという。相手をコントロールし、とっさの判断も速く、本当にうまい選手だと感じたと、AJスタイルズが話している。移籍の決断も当時は大きな一歩だったと評価している。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で、AJスタイルズの話（公式字幕を全文確認）", "src": [["公式YouTube（28:31〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1711s"]], "by": "第三者の話"});
  if (PROFILES["John Cena"]) PROFILES["John Cena"].facts.push({"cat": "暮らし", "t": "なぜか一番かみ合う相手", "b": "ジョン・シナとの試合は、これまでで最も楽にできたものの一つだったという。タイミングも何もかもが合い、どの試合も素晴らしかったが、なぜそこまでかみ合うのか今でも説明できないと、AJスタイルズが話している。二人とも仕事が好きで誇りを持っていたからかもしれないとも語る。", "sp": "AJスタイルズ", "d": "2026-09-30", "how": "コーディの番組で、AJスタイルズの話（公式字幕を全文確認）", "src": [["公式YouTube（52:52〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3172s"]], "by": "第三者の話"});
  if (!PROFILES["Cody Rhodes"]) PROFILES["Cody Rhodes"] = { lead: "", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Cody%20Rhodes"]], moves: [], facts: [] };
  if (PROFILES["Cody Rhodes"].lead === "") PROFILES["Cody Rhodes"]._weak = 1;
  PROFILES["Cody Rhodes"].facts.push(...[{"cat": "リングに来るまで", "t": "「顔が若すぎる」と言われた新人時代", "b": "WWEに入ったばかりのころ、ウィリアム・リーガルから「若すぎる、童顔すぎる、傷でも作れ」と言われていやだったという。年月がたつうちにリーガルの言うとおりだったと分かったそうで、男らしく見えるのは25歳くらいからではと話す。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（17:45〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=1065s"]]}, {"cat": "暮らし", "t": "娘が生まれてから汚い言葉を控える", "b": "娘リバティが生まれてから、汚い言葉を使わないことを強く意識するようになったという。子どもには汚い言葉を使ってほしくないからだと話す。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（44:40〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=2680s"]]}, {"cat": "家族", "t": "父の技は「自分で稼いでから」", "b": "21歳でテレビデビューした直後、リッキー・スティームボートから父ダスティ・ローデスの得意技を使うよう勧められたが断ったという。30代になって自分で受け継ぐ資格を得たと感じるまでは使いたくなかったそうだ。別の名前で出直すよう助言されたこともあるが、父の息子として成功も失敗もしたいと思ったと話す。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:06:19〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=3979s"]]}, {"cat": "家族", "t": "母も姉も「プロレスラー」", "b": "母や姉はリングを組み立てたことは一度もないが、プロレスとともに生きてきたので、自分は二人をレスラーだと考えているという。試合の演出で母が自分の対戦相手を3回も平手打ちしたことも話題にのぼった。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:11:57〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4317s"]]}, {"cat": "リングに来るまで", "t": "リング設営をさぼれるトラック運転", "b": "若いころは父に言われてリングを運ぶトラックを運転していたという。本当の理由は、運転していけば設営をしなくて済んだからだそうだ。会場に着いたら「あとはよろしく」と運転席で待っていたと笑う。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:12:45〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4365s"]]}, {"cat": "暮らし", "t": "葉巻好きがトリプルHにばれる", "b": "葉巻好きは知られていて、葉巻専門誌の表紙を飾ったこともあるという。ツアーバスで一服したあとにトリプルHと抱き合ったら、においですぐ気づかれたそうだ。それ以来、リングで息切れしているように見えたら葉巻のせいにされると思い、ボビー・ルードに監視を頼んだと笑う。バスでは1990〜95年のWCWの試合を動画で繰り返し見ているそうだ。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:18:27〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4707s"]]}, {"cat": "体のこと", "t": "胸のけがのリハビリ中はNXT漬け", "b": "胸の筋肉のけがでリハビリしていた時期は、NXTをずっと見ていたという。若い選手に伝えたいこととして、大技の前にひと呼吸置くことを何度も思い浮かべたそうだ。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:20:58〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4858s"]]}, {"cat": "暮らし", "t": "マリエッタ出身でも「アトランタ」", "b": "出身はジョージア州マリエッタだが、入場コールでは「アトランタ」を使ってきたという。子どものころ姉にしょっちゅうアトランタへ連れ出され、街の文化に触れて育ったからだそうだ。地元を嫌っているわけではないと笑う。", "sp": "コーディ・ローデス", "d": "2026-09-30", "how": "コーディの番組で（公式字幕を全文確認）", "art": "wdywta-QZbjzv0jXss", "src": [["公式YouTube（1:22:34〜）", "https://www.youtube.com/watch?v=QZbjzv0jXss&t=4954s"]]}]);
  ARTICLES.push({ id: "wdywta-QZbjzv0jXss", d: "2026-09-30", show: "wdywta", who: ["AJ Styles", "Cody Rhodes"], t: "AJスタイルズの回　ゲインズビル育ちの礼儀と、プロレスを始めた息子への思い", lead: "コーディ・ローデスの番組に出た約84分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["AJ Styles", "Cody Rhodes"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wdywta-QZbjzv0jXss").map((x) => [x.t, x.b, x.sp])), open: ["食べ物の話題（海外の食事は健康的、など）は話者の切り替わりが追えず載せていない。", "息子をめぐるネット上の議論や、抗争・タイトルマッチの裏話は省いた。", "息子をめぐるネット上の議論でゲストの息子を擁護した話は、他人の件なので載せていない。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=QZbjzv0jXss"]] });
  if (!ROSTER.find((r) => r[1] === "Stephanie McMahon")) ROSTER.push(["ステファニー・マクマホン", "Stephanie McMahon", "lg", "番組の聞き手、殿堂入り", "", "", ""]);
  if (!PROFILES["Stephanie McMahon"]) PROFILES["Stephanie McMahon"] = { lead: "50歳の誕生日を家族や親友とアイルランドで祝ったステファニー。視聴者の質問に、夫との思い出や仕事への向き合い方を率直に語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Stephanie%20McMahon"]], moves: [], facts: [] };
  if (PROFILES["Stephanie McMahon"]._weak) { PROFILES["Stephanie McMahon"].lead = "50歳の誕生日を家族や親友とアイルランドで祝ったステファニー。視聴者の質問に、夫との思い出や仕事への向き合い方を率直に語った。"; delete PROFILES["Stephanie McMahon"]._weak; }
  PROFILES["Stephanie McMahon"].facts.push(...[{"cat": "暮らし", "t": "番組の機材は数か月かけて試した", "b": "この番組の収録機材は、1月から何か月もテストを重ね、2月には試験的な回も収録したという。それでも本番の日は、本人が部屋に入った途端に機材の調子が悪くなったと、スタッフと笑い合っている。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（2:25〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=145s"]]}, {"cat": "家族", "t": "50歳の誕生日はアイルランドで", "b": "50歳の誕生日は、いちばん親しい家族や友人とアイルランドで過ごしたという。以前から家族を連れていきたいほど大好きな国で、夫が準備を整えてくれたと話す。姪や番組スタッフの手助けもあり、本人は「魔法のような誕生日だった」と振り返っている。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（4:51〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=291s"]]}, {"cat": "好きなもの", "t": "甥の手作りクッキーが大好き", "b": "アイルランドでは、甥が焼くチョコチップクッキーが楽しみだったそうだ。一晩冷凍して決まった時間だけ解凍するなど、手のかかる作り方をするという。ブランド化したいと思うほどの味だと話している。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（5:37〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=337s"]]}, {"cat": "好きなもの", "t": "クッキーは外がカリッとした派", "b": "自分でもクッキーを焼き、定番のトールハウス社のレシピがいちばんだと考えているという。バターは溶かして使い、ふんわりよりも少しカリッとした焼き上がりが好みだそうだ。温かくてチョコがとろりとし、アイスを添えたものが理想だと話す。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（7:08〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=428s"]]}, {"cat": "家族", "t": "家族でのディズニー旅行は出費も大きい", "b": "番組の前の回で話したとおり、家族をディズニーに連れていく計画があると触れている。ディズニーは安くないので、お金を稼がなければと冗談めかして話した。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（11:54〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=714s"]]}, {"cat": "暮らし", "t": "番組でいちばん好きなのは素顔に会えること", "b": "番組の好きなところは、ステファニー・マクマホンが警戒を解いて素の姿を見せてくれることだという。価値観や人生の教訓に話を戻すと、その人が何者で何を信じているかが見えてくると話す。そうした話を聞けるのは「特権」だと語っている。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（12:41〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=761s"]]}, {"cat": "リングの話", "t": "部下を厳しく叱ってしまい、後で謝った", "b": "以前、仕事で部下に厳しく当たり、前向きな言葉をかけなかったことがあるという。それを隣の部屋で聞いていた長年のスタッフから、相手が仕事に真剣で努力家だと指摘されたそうだ。本人は後で相手に謝り、許してもらえたと話す。自分の未熟さに気づかせてくれたことに感謝している。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（15:51〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=951s"]]}, {"cat": "暮らし", "t": "間違えたらすぐ謝るようにしている", "b": "先週の収録でも、あるアイデアを「くだらない質問」と言ってしまい、後から考えて番組スタッフに謝ったという。誰かが時間をかけて考えたものだと気づいたからだそうだ。誰でも失敗するものだと話し、人がどれだけ頑張っているかを認める大切さを語っている。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（17:33〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1053s"]]}, {"cat": "家族", "t": "働く母としての背中を見せてきた", "b": "番組スタッフからは、会社で男性ばかりの会議を仕切りながら、娘の学校の読み聞かせのために抜ける姿が手本だったと言われている。ステファニー自身は、母親も長く金融の仕事を続けていたと話す。仕事と子育てをどちらも大切にする姿勢が、周りにも影響を与えているようだ。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（18:20〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1100s"]]}, {"cat": "家族", "t": "夫トリプルHは「魂の伴侶」", "b": "夫のトリプルHを、人生のパートナーであり魂の伴侶だと話す。テレビでは面白くて頭の切れる人だが、本人が恋に落ちたのは何より心の大きさだったという。子どもへの接し方や、女性を支える姿勢にも学んだことが多いそうだ。人の才能を見つけて引き出すのがうまく、娘たちにとっても素晴らしい父だと語る。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（20:44〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1244s"]]}, {"cat": "リングに来るまで", "t": "中学生の頃、夜に抜け出して警察に見つかった", "b": "8年生から9年生の頃、友人の家をこっそり抜け出し、警察に見つかったことがあるという。大きな叱られ方はしなかったそうだ。この話は、50歳の誕生日会で古い友人が披露し、子どもたちも初めて知ったと話す。ほかにもっとひどい話があるようだが、番組では話さなかった。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（24:02〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1442s"]]}, {"cat": "リングの話", "t": "やりたいことはほぼ叶えたと感じている", "b": "やりたかったことはほとんど実現したと話す。何より母になりたかったこと、短い間ながら会社の会長兼CEOを務めたこと、殿堂入りしたことなどを挙げている。50歳を迎え、これから何をするのかと考えているところだという。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（24:50〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1490s"]]}, {"cat": "暮らし", "t": "小児がんの治療法探しは一生の使命", "b": "夢というより、一生続ける約束として小児がんの治療法を見つける活動を挙げている。子どもとその家族を助けたいという思いが、自分の指針になっていると話す。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（25:44〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1544s"]]}, {"cat": "好きなもの", "t": "ヨーグルトの香りと香水は苦手", "b": "ヨーグルトの匂いが好きではなく、香水もあまり好まないそうだ。ただ、男性用のコロンはいいと感じるという。最近いろいろな商品に使われている特定の香りが気になるとも話している。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（27:26〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1646s"]]}, {"cat": "好きなもの", "t": "月旅行が当たり前になる未来を想像", "b": "これからの50年で、月への商用の移動手段が実現すると予想している。冗談まじりに、番組を月や飛行機の上から収録したいとスタッフと盛り上がった。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（28:12〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1692s"]]}, {"cat": "家族", "t": "娘の名前は女優リヴ・タイラーにちなむ", "b": "娘のひとりの名前は、女優のリヴ・タイラーにちなんでつけたという。名前を決めたのは夫で、彼女の見た目が理由だったのではと冗談めかしている。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（30:40〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1840s"]]}, {"cat": "家族", "t": "プロポーズの前、島で踊った曲が結婚式の歌に", "b": "夫が大けがから復帰する数週間前、初めての休暇でフロリダの島に行ったという。雨続きだったが、シェフが流した曲で普段は踊らない夫が誘ってくれたそうだ。そのときに「結婚するならこれが私たちの結婚式の曲」と思い、後日本人にも伝えている。夫が不在のときは、この曲を聞いて彼を思い浮かべていたとも話す。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（31:30〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=1890s"]]}, {"cat": "家族", "t": "プロポーズは2月13日、ホテルの部屋で", "b": "プロポーズは2月13日の金曜日で、夫は前もって本人の父に結婚の許しをもらっていたという。当日は偏頭痛がひどい中、急に泊まりの支度を言われ、ホテルへ向かった。部屋にはバラの花びらがハート形に並び、あの思い出の曲が流れたそうだ。夫が震えながら踊っていたのでダンス嫌いのせいだと思ったが、曲の後にひざまずいて結婚を申し込まれたと話す。驚きすぎて黙り込み、「それは返事なの」と聞かれて「イエス」と答えたそうだ。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（34:06〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=2046s"]]}, {"cat": "好きなもの", "t": "ペイトリオッツのファン", "b": "アメリカンフットボールのニューイングランド・ペイトリオッツを、熱心に応援していると話す。ただ、筋金入りのファンほど胸を張れる立場ではないとも言っている。収録の終わりには、チームのロゴ入りのルルレモンのグッズを披露した。", "sp": "ステファニー・マクマホン", "d": "2026-10-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys--YXVF3Uufg8", "src": [["公式YouTube（36:31〜）", "https://www.youtube.com/watch?v=-YXVF3Uufg8&t=2191s"]]}]);
  ARTICLES.push({ id: "wys--YXVF3Uufg8", d: "2026-10-02", show: "wys", who: ["Stephanie McMahon"], t: "ステファニー・マクマホンの質問コーナー　50歳の誕生日、夫のプロポーズ、そして夢", lead: "ステファニー・マクマホンの番組に出た約38分の回。公式YouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Stephanie McMahon"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "wys--YXVF3Uufg8").map((x) => [x.t, x.b, x.sp])), open: ["ステファニーが視聴者の質問に答える特別回のため、聞き手本人の話を拾った。娘たちと、姪・甥の名前は載せていない。", "夫トリプルHの人柄の話は載せたが、2Kのポスターなど冗談のやりとりは省いた。", "広告部分は除いてある。字幕の話者が混ざる箇所は、聞き手本人の発言と読める部分だけを載せた。"], src: [["公式YouTube（この回の全編）", "https://www.youtube.com/watch?v=-YXVF3Uufg8"]] });
  if (!ROSTER.find((r) => r[1] === "Charlotte Flair")) ROSTER.push(["シャーロット・フレアー", "Charlotte Flair", "lg", "", "", "", ""]);
  if (!PROFILES["Charlotte Flair"]) PROFILES["Charlotte Flair"] = { lead: "名レスラーの娘として育ち、弟の夢を継いでリングへ。完璧を求めて悩みながら、結婚後も次の一歩を探し続ける素顔を語った。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Charlotte%20Flair"]], moves: [], facts: [] };
  if (PROFILES["Charlotte Flair"].lead === "名レスラーの娘として育ち、弟の夢を継いでリングへ。完璧を求めて悩みながら、結婚後も次の一歩を探し続ける素顔を語った。") PROFILES["Charlotte Flair"]._weak = 1;
  PROFILES["Charlotte Flair"].facts.push(...[{"cat": "家族", "t": "結婚式は夫の故郷メキシコで", "b": "結婚式は夫の故郷、メキシコ北部の農場で挙げたという。結婚生活は「最高」だと話している。出張続きの仕事の大変さを、同じ業界で働く夫には説明しなくても分かってもらえるそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（0:48〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=48s"]]}, {"cat": "家族", "t": "新婚旅行は丸7日間のコスタリカ", "b": "新婚旅行はコスタリカに行ったという。本当はまだ行ったことのないギリシャに行きたかったが、移動時間を考えて夫が決めた。旅行の計画はすべて夫がしてくれ、現地では何でもよく食べたと話す。丸7日間の休みはこの仕事では珍しいそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:33〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=93s"]]}, {"cat": "家族", "t": "夫は何でも話せる親友", "b": "夫は自分の一番の親友で、困ったときにまず電話したい相手だと話す。この世界の大変さは、業界を知らない人にはなかなか伝わらない。仕事と無関係の姉に話してもピンとこないが、夫には通じるという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（3:07〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=187s"]]}, {"cat": "リングに来るまで", "t": "弟の夢を引き継いでリングへ", "b": "最初は、弟のあとを追ってWWEの育成施設に入り、一緒に戦うつもりだったと話す。ところが結果的に、弟の夢を自分が受け継ぐことになったという。25歳のときは、自分がここにいるとは想像もしていなかったそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（3:54〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=234s"]]}, {"cat": "家族", "t": "父は忙しくても学校に通ってくれた", "b": "生まれたときから父は王者だったので、家にいる日の父の姿が自分の知るすべてだったと話す。家にいるときは朝食を作り、学校へ迎えに来て、好きだったサラダを昼に届けてくれた。部活の合宿や大学のバレーボールの試合にも車で送ってくれたという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（5:28〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=328s"]]}, {"cat": "リングに来るまで", "t": "体操からバレーボールまで、スポーツ漬けの少女時代", "b": "子どものころは体操をやり、中学で両親からバスケットボールかバレーボールかを選ばされた。父はバスケが好きだったが、本人はバレーボールを選んだという。チアリーディングにも打ち込み、男の子のような活発な子だったと話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（7:02〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=422s"]]}, {"cat": "リングに来るまで", "t": "大学でバレーボールをやめて自分を見失う", "b": "家を離れる不安が強く、地元の大学の奨学金を得てバレーボールを続けた。しかし3年目でやめ、別の大学に移って卒業を目指したという。目標も自分らしさも見失った時期で、卒業は「そういうものだから」と進めただけだったと振り返る。専攻は広報だった。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（7:49〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=469s"]]}, {"cat": "家族", "t": "高校卒業のころに両親が離婚", "b": "高校を卒業したころ両親が離婚し、それで調子を崩したと話す。弟は寄宿学校に入り、家族がばらばらになった落ち着かない時期だったという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（8:37〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=517s"]]}, {"cat": "リングに来るまで", "t": "個人トレーナーを経て、夕食の席で決まった入団", "b": "地元に戻り、父が通っていたジムの元トレーナーの私設スタジオで、パーソナルトレーナーとして働いたという。2年ほどたった殿堂入り式典の夕食の席で、制作スタッフに「なぜやらないのか」と聞かれた。家族にも強く勧められ、その2か月後には育成施設に入っていたそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（9:25〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=565s"]]}, {"cat": "リングに来るまで", "t": "入団初日から体力勝負で負けなかった", "b": "入団テストを受けていなかったため、周りに嫌われているのではと不安だったという。責任者から「特別扱いはしない」と言われると、大学1部リーグの選手だと言い返した。体力を使い切らせる練習で最後まで動き続け、ダスティに「大丈夫だ」と声をかけられたと話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（11:46〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=706s"]]}, {"cat": "家族", "t": "弟リードを亡くして", "b": "弟のリードが亡くなったのは、WWEの育成施設に入って数か月後のことだったという。亡くなる前の感謝祭に帰省しなかったことを、今も悔やんでいると話す。亡くなった翌週には仕事に戻り、その悲しみには「今も向き合えていない」そうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（13:27〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=807s"]]}, {"cat": "家族", "t": "弟の死が両親に残したもの", "b": "弟の死は母と父を深く打ちのめしたという。自分は悲しみに向き合えず、ただ仕事に打ち込んだと話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（15:02〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=902s"]]}, {"cat": "リングに来るまで", "t": "同期の存在が自分を高めた", "b": "育成施設では、反骨のスター候補だったペイジの存在に目を奪われ、自分はただ「リック・フレアーの娘」にすぎないと感じたという。ベッキー、サーシャ、ベイリーといった同期の情熱に刺激を受け、必死で追いつこうとしたと話す。競争が競争を生む環境でなければ、今の自分はなかったかもしれないそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（15:47〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=947s"]]}, {"cat": "リングの話", "t": "自分は根っからのヒール向き", "b": "自分はヒールが向いていると感じていて、好感を持たれる役はやりにくかったと話す。有名な父の娘という立場を説明しても、ぐちに聞こえてしまうそうだ。ブーイングも反応のうちなので、それに乗ればよかったと今は考えているという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（24:45〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=1485s"]]}, {"cat": "リングの話", "t": "ナタリヤ戦で感じた緊張", "b": "育成ブランドの大会でナタリヤと戦った試合は、あの長さの試合が初めてで、口の中がからからだったという。試合では考えすぎず、ナタリヤの導きに従って動いたと話す。父がリングサイドで目立とうとするのは分かっていたが、それは見せ場好きの性格と負けず嫌いの両方だと語っている。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（26:32〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=1592s"]]}, {"cat": "リングの話", "t": "トリプルHに認められたい一心だった", "b": "トリプルHは家族と縁が深く、頼みごとをして特別扱いを期待していると思われるのが怖かったという。そのため試合やキャラクターのことを、もっと相談すればよかったと悔やんでいる。ただ、トリプルHが育てた育成ブランドを任された身として、期待に応えたい気持ちが強かったそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（30:38〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=1838s"]]}, {"cat": "リングの話", "t": "3人で臨んだ初代女子王座戦", "b": "ベッキー、サーシャとの3人による大舞台の試合は、成功しなければ次はないという「やるかやらないか」の覚悟だったと話す。緊張はしていたが、そう思わないようにしていたそうだ。女子の選手が増え、競い合う空気が選手全体を引き上げたとも語っている。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（33:49〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=2029s"]]}, {"cat": "家族", "t": "父とはよくケンカもする", "b": "父とは考えをぶつけ合い、よくケンカもするという。父の助言が的確なときもあれば、的外れだと思うときもあるそうだ。自分は父より運動能力が高いので、月面宙返りをやれと勧められるが、「パパはやらなかったのに」と返すと話す。根っこにあるのは娘への誇りだと受け止めている。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（38:43〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=2323s"]]}, {"cat": "リングの話", "t": "アスカ戦と恩人フィット・フィンレー", "b": "アスカは日本での実績があり、証明するものはなかったが、自分は王者として負けられなかったという。同じ試合で、一緒に準備してくれたのはフィット・フィンレーだった。この試合の直後に王座を失ったことには、「聞きたいことはあった」と笑っている。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（41:53〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=2513s"]]}, {"cat": "好きなもの", "t": "ローブの入場にはこだわりがある", "b": "ローブを着るようになったのは、大きな大会だから着ようと思ったのがきっかけだという。ファンに喜ばれ、そのうち巡業でも着るようになった。維持費が思った以上にかかると笑っていて、昔は黒のパンツとブーツとベストだけで楽だったと話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（42:45〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=2565s"]]}, {"cat": "リングの話", "t": "ベッキー戦で個性を消したことを反省", "b": "女子だけの初の大会でのベッキーとの試合では、ストーリーに合わせてヒールらしい身振りを変えてしまったことを後悔しているという。人気の理由だった持ち味を消してはいけないと学び、観客の反応が賛否どちらでも、まず反応を引き出すことが大事だと話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（56:35〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=3395s"]]}, {"cat": "リングの話", "t": "ロンダ戦は「自分の居場所」を示す試合", "b": "ロンダ・ラウジーとの試合は、物語も盛り上げもないまま組まれ、大舞台の出番を失う危機感があったという。そこで「ここは自分の家だ」と考え、自分から全力で動いたそうだ。理想の相手との試合だったと話している。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（58:12〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=3492s"]]}, {"cat": "リングの話", "t": "急に試合に加えられた大舞台", "b": "自分が突然試合に入れられたことは、観客から反感を買ったと話す。ただし、その後に筋書きの上で何の説明もなかったことが心残りだという。それでも大舞台のメインを務めたことは、自分が口にしたことをやり遂げた満足感があったそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:00:37〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=3637s"]]}, {"cat": "リングの話", "t": "もう一度メインを張れた喜びと、まだ足りない気持ち", "b": "年間最大の祭典のメインは、父でも経験していないことだと言われ、誇りに思っている。その後も一度メインを務められ、昔なら信じられなかったと話す。それでも「もっと欲しい」と話し、満足しないのが自分だという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:03:49〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=3829s"]]}, {"cat": "リングの話", "t": "王座の件は「わざとではなかった」", "b": "番組内で起きた王座をめぐる出来事は、故意ではなく偶然だったと話す。ベッキーとは、二人とも頂点を目指すからこそ意見が合わなかったという。悪役が必要なら引き受けるが、台本のある番組でわざと誰かを傷つけるようなことはしないと語っている。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:07:03〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4023s"]]}, {"cat": "家族", "t": "子どもは「いつかタイミングが来れば」", "b": "仲間のレスラーが子どもを連れて世界を回る姿を見て、仕事と家庭は両立できると感じているという。自分もいつか子どもを持ちたいと話す。ただし、それは時期が来たらの話だそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:07:55〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4075s"]]}, {"cat": "体のこと", "t": "休むのが苦手で、いつも上を目指してしまう", "b": "自分はずっと頂点にいたくて、ペースを落とせない性格だという。2012年に働き始めてから、自分が何者かを見つけてきたと話す。周りに言われないと休まず、立ち止まるのが苦手だそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:11:04〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4264s"]]}, {"cat": "体のこと", "t": "出来が悪かった試合を引きずってしまう", "b": "満足のいく試合ができなかったときは、いつまでも引きずるという。5点満点に届かなければ自分の責任だと感じ、次をよくするしかないと切り替えるそうだ。完璧を求めすぎる自分が、時には足かせになるとも話す。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:13:25〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4405s"]]}, {"cat": "暮らし", "t": "結婚と新婚旅行で初めて取れた長い休み", "b": "ずっと出ずっぱりで、ファンが自分から離れる時間がなかった。結婚と新婚旅行で珍しい休みが取れ、いい機会だったと話す。出すぎることで飽きられるのは何度も見てきたといい、休むことの大切さも感じているそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:17:28〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4648s"]]}, {"cat": "暮らし", "t": "リングの外での新しい挑戦を考えている", "b": "映画などリングの外の仕事にも関心があり、新しい分野に踏み出すことを怖がってはいけないと話す。入場前には「13度王者」という肩書きだけで終わりたくないと自分に言い聞かせるという。次に何をするかは、まだ模索中だそうだ。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で（字幕を全文確認）", "art": "ext-QdwfeQWV6aM", "src": [["番組のYouTube（1:18:20〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=4700s"]]}]);
  if (PROFILES["Fit Finlay"]) PROFILES["Fit Finlay"].facts.push({"cat": "暮らし", "t": "フィット・フィンレーに育ててもらった", "b": "一軍に上がってからは、フィット・フィンレーにほとんど育ててもらったと、シャーロット・フレアーが話している。荒っぽさと、技に込める凄みを教わったという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、シャーロット・フレアーの話（字幕を全文確認）", "src": [["番組のYouTube（44:29〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=2669s"]], "by": "第三者の話"});
  if (PROFILES["Sara Del Rey"]) PROFILES["Sara Del Rey"].facts.push({"cat": "暮らし", "t": "サラ・デル・レイは技術の恩人", "b": "育成施設の主任コーチだったサラ・デル・レイは、リング上の技術で今の自分を作った大きな存在だったと、シャーロット・フレアーが話している。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、シャーロット・フレアーの話（字幕を全文確認）", "src": [["番組のYouTube（17:24〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=1044s"]], "by": "第三者の話"});
  if (PROFILES["Dusty Rhodes"]) PROFILES["Dusty Rhodes"].facts.push({"cat": "暮らし", "t": "ダスティは娘のように気にかけてくれた", "b": "育成施設で、ダスティがマイクの指導役として自分を娘のように気にかけてくれたと、シャーロット・フレアーが話している。弟を亡くしたときも前に進むよう励まされたという。", "sp": "シャーロット・フレアー", "d": "2026-10-03", "how": "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）で、シャーロット・フレアーの話（字幕を全文確認）", "src": [["番組のYouTube（11:46〜）", "https://www.youtube.com/watch?v=QdwfeQWV6aM&t=706s"]], "by": "第三者の話"});
  ARTICLES.push({ id: "ext-QdwfeQWV6aM", d: "2026-10-03", show: "ext", who: ["Charlotte Flair"], t: "シャーロット・フレアーの回　フレアー家に育って、弟の夢を継いで", lead: "ストーン・コールドの対談番組 Broken Skull Sessions（WWE公式）に出た約80分の回。番組のYouTubeの字幕を最初から最後まで読んでまとめた。各項目から、その話が出る時刻の公式動画に飛べる。", points: ["Charlotte Flair"].flatMap((en) => PROFILES[en].facts.filter((x) => x.art === "ext-QdwfeQWV6aM").map((x) => [x.t, x.b, x.sp])), open: ["夫の名前や、「リングの話」の一部の細かい経緯は、字幕が崩れていたため載せていない。", "聞き手のスティーブ・オースティンや同席者自身の思い出話（叔父の逸話など）は含めていない。"], src: [["番組のYouTube（この回の全編）", "https://www.youtube.com/watch?v=QdwfeQWV6aM"]] });
  PROFILES["Je'Von Evans"].facts.push(...[{"cat": "リングの話", "t": "憧れはトリプルHのペディグリー", "b": "ジェボン・エバンスは、トリプルHがテーブル越しにペディグリーを決める場面を見て、これこそ自分がやりたいことだと思ったそうだ。それが原点で、以来ずっと下積みを続けてきたと話す。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（11:56〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=716s"]]}, {"cat": "リングの話", "t": "目標は「史上最高」になること", "b": "ジェボンの大きな目標は、WWEの歴史、そしてプロレス界で最高の選手になることだという。そのためには障害や山を越える必要があると理解しているそうだ。「いつか」では遠い話に聞こえるので、必ず自分で実現させると言い切っている。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（14:22〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=862s"]]}, {"cat": "リングの話", "t": "20年続く「引退ツアー」の構想", "b": "ジェボンは「ヤングOG」と名乗り、楽屋では冗談で「もうすぐ引退する」と言っているという。実際は引退ツアーが20年続くつもりで、年ごとのツアーTシャツまで話が広がった。後半では、目指す先として「殿堂入りツアー」と呼ぶ案も出ている。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（16:44〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=1004s"]]}, {"cat": "リングの話", "t": "はしごなしでケースをつかむ夢", "b": "ジェボンは、マネー・イン・ザ・バンクの契約書入りケースを、はしごを使わずトップロープから跳んでつかめたら最高の見せ場になると話す。誰もやったことがない動きで、練習はできても着地が心配だと笑う。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:02:34〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=3754s"]]}, {"cat": "リングの話", "t": "ケースが揺れたら届くかもしれない", "b": "ジェボンは、揺れて近づいたケースに跳びつく案も口にしている。タイミングの問題だと考えているそうだ。試合が最高に盛り上がった場面で失敗し顔面から落ちても、話題になって王座戦につながるかもしれないと冗談めかして話す。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:04:08〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=3848s"]]}, {"cat": "リングの話", "t": "WrestleManiaのはしご戦で味わった緊張", "b": "ジェボンは、すでにWrestleManiaではしご戦を経験していて、あれ以上大きな舞台はないと思っていたという。それでも今回のマネー・イン・ザ・バンク戦は緊張すると正直に話す。同時にワクワクもしているそうだ。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:04:54〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=3894s"]]}, {"cat": "リングの話", "t": "権利を取って大舞台で使う筋書き", "b": "ジェボンは、ケースを勝ち取れば年間最大の祭典まで持ち続け、そこで自分の大舞台を迎えるのが計画だと話す。セス・ロリンズのやり方を手本にした流れだ。のちに「最年少のマネー・イン・ザ・バンク勝者」になると宣言もしている。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:05:41〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=3941s"]]}, {"cat": "リングの話", "t": "子どものころ夢中になったオーソリティ", "b": "ジェボンは、ボスが選手側に回って好き勝手に振る舞うオーソリティの物語が最高だったと話す。当時は敵として憎んだが、あれほど楽しかったものはないという。ザ・シールドのセスが裏切った場面も、前触れは見えていたが胸が痛んだそうだ。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:06:30〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=3990s"]]}, {"cat": "リングの話", "t": "毎回の入場前に緊張する", "b": "ジェボンは、ステージに出る前は毎回のように緊張すると話す。ゴリラ・ポジションでトリプルHに「いまの歓声はどうだった、自分は受け入れられているか」と尋ねることもあるそうだ。音楽が鳴って観客の前に出ると、思ったほど悪くないと感じるという。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:19:57〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=4797s"]]}, {"cat": "リングの話", "t": "仲間うちの合言葉「アー！」", "b": "ジェボンは、仲間と控室で叫ぶ「アー！」という声を流行らせていて、ジェイ・ウーソともメッセージで送り合っていると話す。マネー・イン・ザ・バンクの跳躍や顔面からの落下の場面にも、この声をかぶせたいと冗談を言っている。", "sp": "ジェボン・エバンス", "d": "2026-10-09", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-jevon", "src": [["番組のYouTube（1:27:10〜）", "https://www.youtube.com/watch?v=OnMAtaCmyGs&t=5230s"]]}]);
  { const A = ARTICLES.find((a) => a.id === "wys-jevon"); if (A) A.points.push(...[["憧れはトリプルHのペディグリー", "ジェボン・エバンスは、トリプルHがテーブル越しにペディグリーを決める場面を見て、これこそ自分がやりたいことだと思ったそうだ。それが原点で、以来ずっと下積みを続けてきたと話す。", "ジェボン・エバンス"], ["目標は「史上最高」になること", "ジェボンの大きな目標は、WWEの歴史、そしてプロレス界で最高の選手になることだという。そのためには障害や山を越える必要があると理解しているそうだ。「いつか」では遠い話に聞こえるので、必ず自分で実現させると言い切っている。", "ジェボン・エバンス"], ["20年続く「引退ツアー」の構想", "ジェボンは「ヤングOG」と名乗り、楽屋では冗談で「もうすぐ引退する」と言っているという。実際は引退ツアーが20年続くつもりで、年ごとのツアーTシャツまで話が広がった。後半では、目指す先として「殿堂入りツアー」と呼ぶ案も出ている。", "ジェボン・エバンス"], ["はしごなしでケースをつかむ夢", "ジェボンは、マネー・イン・ザ・バンクの契約書入りケースを、はしごを使わずトップロープから跳んでつかめたら最高の見せ場になると話す。誰もやったことがない動きで、練習はできても着地が心配だと笑う。", "ジェボン・エバンス"], ["ケースが揺れたら届くかもしれない", "ジェボンは、揺れて近づいたケースに跳びつく案も口にしている。タイミングの問題だと考えているそうだ。試合が最高に盛り上がった場面で失敗し顔面から落ちても、話題になって王座戦につながるかもしれないと冗談めかして話す。", "ジェボン・エバンス"], ["WrestleManiaのはしご戦で味わった緊張", "ジェボンは、すでにWrestleManiaではしご戦を経験していて、あれ以上大きな舞台はないと思っていたという。それでも今回のマネー・イン・ザ・バンク戦は緊張すると正直に話す。同時にワクワクもしているそうだ。", "ジェボン・エバンス"], ["権利を取って大舞台で使う筋書き", "ジェボンは、ケースを勝ち取れば年間最大の祭典まで持ち続け、そこで自分の大舞台を迎えるのが計画だと話す。セス・ロリンズのやり方を手本にした流れだ。のちに「最年少のマネー・イン・ザ・バンク勝者」になると宣言もしている。", "ジェボン・エバンス"], ["子どものころ夢中になったオーソリティ", "ジェボンは、ボスが選手側に回って好き勝手に振る舞うオーソリティの物語が最高だったと話す。当時は敵として憎んだが、あれほど楽しかったものはないという。ザ・シールドのセスが裏切った場面も、前触れは見えていたが胸が痛んだそうだ。", "ジェボン・エバンス"], ["毎回の入場前に緊張する", "ジェボンは、ステージに出る前は毎回のように緊張すると話す。ゴリラ・ポジションでトリプルHに「いまの歓声はどうだった、自分は受け入れられているか」と尋ねることもあるそうだ。音楽が鳴って観客の前に出ると、思ったほど悪くないと感じるという。", "ジェボン・エバンス"], ["仲間うちの合言葉「アー！」", "ジェボンは、仲間と控室で叫ぶ「アー！」という声を流行らせていて、ジェイ・ウーソともメッセージで送り合っていると話す。マネー・イン・ザ・バンクの跳躍や顔面からの落下の場面にも、この声をかぶせたいと冗談を言っている。", "ジェボン・エバンス"]]); }
  if (!ROSTER.find((r) => r[1] === "Drew McIntyre")) ROSTER.push(["ドリュー・マッキンタイア", "Drew McIntyre", "lg", "元WWE王者", "", "", ""]);
  if (!PROFILES["Drew McIntyre"]) PROFILES["Drew McIntyre"] = { lead: "スコットランド出身で、母を支えに夢を追い続けてきたドリュー・マッキンタイア。解雇や喪失を乗り越えた経験と、映画への挑戦を語る。", official: [["WWE公式YouTubeで探す", "https://www.youtube.com/@WWE/search?query=Drew%20McIntyre"]], moves: [], facts: [] };
  if (PROFILES["Drew McIntyre"]._weak) { PROFILES["Drew McIntyre"].lead = "スコットランド出身で、母を支えに夢を追い続けてきたドリュー・マッキンタイア。解雇や喪失を乗り越えた経験と、映画への挑戦を語る。"; delete PROFILES["Drew McIntyre"]._weak; }
  PROFILES["Drew McIntyre"].facts.push(...[{"cat": "暮らし", "t": "リング外で映画『ハイランダー』に出演", "b": "試合から5か月以上離れ、リング外の仕事に挑戦していたと、ドリューは話す。リメイク版『ハイランダー』で一族の長を演じ、撮影現場では先輩俳優の演技を何時間も見て学んだそうだ。WWEで培った経験が演技にそのまま生きたと感じたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（3:15〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=195s"]]}, {"cat": "暮らし", "t": "名優からの出演依頼を最初は信じなかった", "b": "エージェントから、ある名優が出演を望んでいると電話で聞いたとき、冗談だと思って電話を切ったと、ドリューは笑って話す。あとで証拠を出させて本当だと分かったそうだ。脚本を読み、端役ではなく心から関わりたい役だと感じて引き受けたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（8:00〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=480s"]]}, {"cat": "リングの話", "t": "無観客の時期に王者として先頭に立った", "b": "世界が止まった年に初めて王者になり、1日5時間もメディア対応をこなしたと、ドリューは振り返る。カメラに向かって話しかけるなど、新しい見せ方にも挑んだそうだ。みんなで観る人の逃げ場をつくったことを誇りに思うという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（10:20〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=620s"]]}, {"cat": "リングの話", "t": "無観客の金網戦で高所から落ちた", "b": "観客のいない中で金網の上から落ち、舌をかんで血が出たと話す。その血を使って、苦しむ様子を大げさに見せたそうだ。相手とは言葉を交わさず、息を合わせて決着まで運んだ。落下は取り消したいが、あの呼吸の合い方は特別な思い出だという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（11:07〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=667s"]]}, {"cat": "体のこと", "t": "新しいトレーナーのおかげで体が絶好調", "b": "この1年あまり、新しいトレーナーと一緒に鍛えているという。関節の使い方や体の内側からの強化を教わり、体重は自己最大の約130キロ（285ポンド）なのに、ここ12年で一番調子がいいと話す。トレーナーの前向きな生き方にも励まされているそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（12:43〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=763s"]]}, {"cat": "体のこと", "t": "足の裏から鍛え直して土台が安定", "b": "バランスが悪いと感じていたドリューは、足裏をほぐし、つま先立ちやふくらはぎの運動を続けたという。裸足に近い靴も使い始めた。リングに戻ったとき、足腰の安定が以前と別物だと感じたそうだ。妻には「リングの外ではいちばん運動音痴なアスリート」と言われると笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（15:13〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=913s"]]}, {"cat": "暮らし", "t": "毎晩、妻と10〜15分の散歩", "b": "夜は妻と近所を10分から15分ほど歩くのが習慣だという。裸足に近い靴で歩き始めた頃は足が痛んだが、いまは快調だと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（16:51〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1011s"]]}, {"cat": "リングに来るまで", "t": "解雇のあと「続ける」と決めた", "b": "夢の仕事を解雇された直後、同棲を始めたばかりの恋人（のちの妻）と暮らしていたとドリューは話す。鏡を見ながら自問し、レスリングを続けると決めたそうだ。立ち直るまでに要した時間は2週間ほどだったという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（21:40〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1300s"]]}, {"cat": "家族", "t": "珍しい病気を抱えながら母になった母", "b": "母は20代で珍しい病気を発症し、医師には子どもは難しいと言われたとドリューは話す。祖母がもう一人の母のように支え、母はそれでも自分とその兄を産んだそうだ。母は生まれながらの母親だったと語る。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（23:16〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1396s"]]}, {"cat": "家族", "t": "母の背中が「普通」を教えてくれた", "b": "小さなアパートで、母は壁を伝いながら夕食を運んでいたとドリューは話す。子どもの頃はそれが普通だと思っていたそうだ。母は文句を言わず、誰のせいにもしなかったという。その姿が今の自分の考え方の土台だと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（24:04〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1444s"]]}, {"cat": "体のこと", "t": "母を亡くし、ひとりで抱え込んだ", "b": "母の病気を、ごく一部の人にしか話さなかったとドリューは話す。母が亡くなったあと、誰にも打ち明けられず酒に頼る日々が続いたそうだ。仕事にも私生活にも響いたという。つらい人は信頼できる人に話してほしいと呼びかける。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（24:51〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1491s"]]}, {"cat": "体のこと", "t": "悲しみは消えないが「新しい日常」になる", "b": "母を失った痛みは今も消えないが、その痛みは母を思い出させてくれるものだとドリューは話す。親を亡くした人から「乗り越えられるか」と聞かれると、忘れることはないが新しい日常を学ぶのだと答えているそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（25:42〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1542s"]]}, {"cat": "リングに来るまで", "t": "世界を回って故郷で観客を増やした", "b": "2014年から世界各地のインディー団体を回り、実力を知ってもらったとドリューは話す。故郷の団体では観客が1500人から数年で7000人超まで増えたそうだ。ベルトも各地で獲り、メインを張る自信がついたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（26:27〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1587s"]]}, {"cat": "リングの話", "t": "「やっているふり」が本物の自信になった", "b": "かつてのユニット時代は、自信のなさを隠して堂々と振る舞っていたとドリューは話す。トップ級の選手たちと並ぶなか、自分にはマイクと語る物語があると気づいたそうだ。周りに支えられ、ふりが本当の自信に変わったという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（27:12〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1632s"]]}, {"cat": "体のこと", "t": "首の骨折がきっかけで生活を見直した", "b": "試合中に首の骨を折り、8週間をギプス姿で過ごしたとドリューは話す。手術は不要で後遺症もなかったそうだ。じっとしていた間に、妻から飲み歩きをやめないなら別れると言われたという。鏡の中の自分には嘘をつけないと気づき、酒と食事を見直した。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（27:57〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1677s"]]}, {"cat": "家族", "t": "妻が「少年」を「大人」に変えた", "b": "解雇された頃の自分は、実家から出てきたままのピーターパンのような少年だったとドリューは話す。妻のおかげで責任を持つ大人になり、仕事も関係もよくなったそうだ。いまは本番でも実生活でも正直でありたいと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（31:08〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=1868s"]]}, {"cat": "体のこと", "t": "落ち込んだとき、時間と音楽が支えになる", "b": "どんなに暗くても、トンネルの先には光があると、ドリューは話す。いちばん効くのは時間だという。つらいときは、気持ちを変えてくれる音楽をかけたそうだ。ジムで悲しい曲を流して感情を出すこともあると笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（34:30〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2070s"]]}, {"cat": "リングの話", "t": "リングの入り口をくぐると「家に帰った」感じ", "b": "子どもの頃から夢中で、これが自分の役目だという感覚があるとドリューは話す。落ち込んでいたときも、入場口を抜ければ気持ちが戻ったという。若くして渡米し、見知らぬ国で唯一くつろげる場所もリングだったそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（40:12〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2412s"]]}, {"cat": "リングの話", "t": "力まず肩を落とすと、画面で自然になれた", "b": "復帰したころは大きく見せようと胸を張って歩いていたと、ドリューは話す。ポールから「力を抜いてもみんな大きさは分かっている」と何度も言われたそうだ。肩の力を抜けたとき、画面の中でも外でも自分らしくいられたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（42:30〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2550s"]]}, {"cat": "暮らし", "t": "外向的な内向型で、パーティーでは隅にいる", "b": "よく話し、場を盛り上げることもあれば、慣れない場では黙り込むとドリューは話す。妻に連れられたパーティーでは、隅で人をじっと見てしまうそうだ。親しくなればおしゃべりになるという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（42:30〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2550s"]]}, {"cat": "リングに来るまで", "t": "11歳で本を手に入れ、15歳で道場へ", "b": "11歳でプロレスの本を読み、学校でも夢中で語っていたとドリューは話す。14歳から友人と毎日3時間鍛え、15歳のとき母が条件付きで道場通いを許してくれたそうだ。12時間かけて電車を乗り継ぎ、祖母にも旅費を出してもらったという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（46:27〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2787s"]]}, {"cat": "リングに来るまで", "t": "大学を出てすぐ入団し、犯罪学の学位を持つ", "b": "大学で犯罪学を学んでいた5週間後には、もうテレビに出ていたとドリューは話す。入団後は先輩に囲まれて驚いたそうだ。今も人を見る目に学んだことが役立つと話す。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（48:53〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2933s"]]}, {"cat": "リングの話", "t": "抗争では犯罪学の知識を引き合いに出した", "b": "ある選手との抗争で、犯罪学の考え方を持ち出したとドリューは話す。観客に「ネットで検索すれば誰が信頼できるか分かる」と呼びかけたそうだ。その選手の話になると止まらなくなると笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（49:41〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2981s"]]}, {"cat": "好きなもの", "t": "縦型ショートドラマにはまった", "b": "移動中に偶然見た縦型ドラマに引き込まれ、数話続けて観たとドリューは話す。のちにその会社の作品への出演を打診されたそうだ。若い世代に合う形で、将来性があると感じたという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（51:16〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3076s"]]}, {"cat": "リングの話", "t": "母の名を付けた剣を、ついに使えた", "b": "長年、母の名前を付けた剣をリングに持ち込んできたと、ドリューは話す。相手を刺す真似をしたくても、PG番組だからと止められてきたそうだ。映画ではそれを思い切りやれたと笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（55:23〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3323s"]]}, {"cat": "家族", "t": "泣き虫の父と、芯の強かった母", "b": "父は何にでも泣く感情豊かな人で、出演を知らせたときも涙を流したとドリューは話す。母は感情も体も強く、自分は両方の性格を受け継いだと考えているそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（1:00:53〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3653s"]]}, {"cat": "家族", "t": "「いつか巨人になる」と言っていた子ども時代", "b": "父は身長190センチほどで「ビッグ・アンディ」と呼ばれていたとドリューは話す。子どもの頃から自分はもっと大きくなると言い続け、父の背を越えたときの喜びを今も覚えているそうだ。父は最大の応援者だという。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（1:02:28〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3748s"]]}, {"cat": "リングの話", "t": "初のスコットランド凱旋と、母の地での王座防衛", "b": "王座を獲った最初の防衛戦は、故郷スコットランドのグラスゴーだったとドリューは話す。会場で父が涙を流す姿が見えたという。ベルリンで王者になったときは、亡くなって1年足らずの叔母に捧げたそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（1:03:18〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3798s"]]}, {"cat": "好きなもの", "t": "初めて買った腕時計", "b": "時計に興味はなかったが、共演した名優に強く勧められ、初めて高級腕時計を買ったとドリューは話す。撮影の初週、俳優が見せてくれた中から「これだ」と直感で選んだという。スコットランド人らしく、特別な事情で安く手に入れたと笑う。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-4qikcuumAQ8", "src": [["公式YouTube（1:06:31〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=3991s"]]}]);
  if (PROFILES["Batista"]) PROFILES["Batista"].facts.push({"cat": "暮らし", "t": "バティスタが初めての映画出演を後押しした", "b": "若い頃から気にかけてくれたバティスタが、映画に出てみないかと誘ってくれたと、ドリューが話している。緊張していたときも「赤いランプがつけば大丈夫」と励ましてくれたそうだ。", "sp": "ドリュー・マッキンタイア", "d": "2026-10-16", "how": "ステファニーの番組で、ドリュー・マッキンタイアの話（公式字幕を全文確認）", "src": [["公式YouTube（41:45〜）", "https://www.youtube.com/watch?v=4qikcuumAQ8&t=2505s"]], "by": "第三者の話"});
