  PROFILES["The Cavinder Twins"].facts.push(...[{"cat": "信仰", "t": "朝は神の言葉から始める", "b": "カビンダー・ツインズのひとりは、毎朝の日課として朝の黙想（デボーション）と日記を欠かさないという。神の言葉から一日を始めれば、何があってもそこに立ち返れると話す。デボーションを2つ読み、感謝を5つ書き出し、肯定の言葉を1つ書くのが流れで、旅先でも続けているという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（15:51〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=951s"]]}, {"cat": "信仰", "t": "イエスが自分の「why」", "b": "「自分の why（原動力）は何か」と問われ、カビンダー・ツインズのひとりはイエスだと答える。家族、とくに双子の片割れや母、姉妹も大切な存在だと話す。心から支えてくれる人たちに立ち返ることが大事だという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（44:45〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2685s"]]}, {"cat": "信仰", "t": "人を許す場面で聖書を思う", "b": "カビンダー・ツインズのひとりは、人の本性を見抜く話の中で、相手に恵み（グレース）を与えるべきか迷うと話す。聖書に「恵みを示しなさい」とあるので、そうすべきか考えるのだという。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（48:44〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=2924s"]]}, {"cat": "信仰", "t": "承認の拠り所は信仰", "b": "ヘイリー・カビンダーは、SNSの称賛も批判も心を乱すと語る。承認をどこから得るかが大事で、自分とハンナは信仰に立ち返ると話す。", "sp": "キャビンダー・ツインズ", "d": "2026-04-02", "how": "ステファニーの番組で（公式字幕を全文確認）", "art": "wys-8sgqdq5hv7A", "src": [["公式YouTube（1:06:20〜）", "https://www.youtube.com/watch?v=8sgqdq5hv7A&t=3980s"]]}]);
