  const LIM = { s: [-70, 200], e: [-5, 150], f: [-35, 150], k: [-150, 5] };
  let FREE = false; // 正面向きの2D（front2）では、角度を折り返さず、関節の範囲でも丸めない
  const norm = (a, lo) => { if (FREE) return a; a = (a - lo) % 360; if (a <= 0) a += 360; return a + lo; };
