    const a = k.sp.rel[i], b = k.sp.rel[i + 1], m0 = k.sp.tout[i], m1 = k.sp.tin[i + 1];
    const span = k[i + 1][0] - k[i][0];
    const u = span > 0 ? Math.min(1, Math.max(0, (t - k[i][0]) / span)) : 1;
    const u2 = u * u, u3 = u2 * u, h00 = 2 * u3 - 3 * u2 + 1, h10 = u3 - 2 * u2 + u, h01 = -2 * u3 + 3 * u2, h11 = u3 - u2;
    const r = a.map((v, j) => h00 * v + h10 * span * m0[j] + h01 * b[j] + h11 * span * m1[j]);
