        m.hj.position.set(h3[0], h3[1], h3[2]); seg3(m.u, h3, k); m.kj.position.set(k[0], k[1], k[2]); seg3(m.s, k, f);
        const b = Math.atan2(f[0] - k[0], -(f[1] - k[1])) + (l.toe || 0), px = Math.cos(b), py = Math.sin(b);
