    let push = 0;
    if (A.hit) { const d = t - A.hit[0]; if (d < 0) { const u = clampN((d + 0.8) / 0.8, 0, 1); push = u * u * (3 - 2 * u); } else push = Math.exp(-d * 1.5); }
    const r = (camera.aspect < 1.3 ? 520 : 440) * (cfg.r || 1) * (1 - 0.13 * push) * zoomK;
    const a = (az + Math.sin(clock * 0.35) * 6) * R, e = el * R; let tg = cfg.tg;
