const md = (d) => d ? String(+d.slice(0,2)) + "/" + String(+d.slice(3)) : "";
const store = {
  get(k, d){ try { const v = localStorage.getItem("wwe." + k); return v === null ? d : v; } catch (e) { return d; } },
  set(k, v){ try { localStorage.setItem("wwe." + k, v); } catch (e) {} }
};

/* ---------- 視聴済みライン ---------- */
const lineSel = $("line");
