/* ---------- 選手アイコン（英語名から決まる左右対称の模様。顔や写真は使わない） ---------- */
function identHash(s){ let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; }
function identIcon(en, g, big){
  const h = identHash(en); let r = "";
  for (let y = 0; y < 5; y++) for (let x = 0; x < 3; x++) if ((h >> (y * 3 + x)) & 1) { r += `<rect x="${x}" y="${y}" width="1" height="1"/>`; if (x < 2) r += `<rect x="${4 - x}" y="${y}" width="1" height="1"/>`; }
  const c = GTAG[g] === "raw" ? "var(--pink)" : GTAG[g] === "sd" ? "var(--purple)" : GTAG[g] === "nxt" ? "var(--yellow)" : "var(--label)";
  return `<span class="ident${big ? " big" : ""}" aria-hidden="true"><svg viewBox="0 0 5 5" fill="${c}">${r}</svg></span>`;
}
/* ---------- タブ ---------- */
const BTAG = (s) => /smack/i.test(s) ? "sd" : /nxt/i.test(s) ? "nxt" : "raw";
const TABS = ["watch","roster","mic","news","feuds","moves","gloss","hist"];
function show(tab, push){
  if (!TABS.includes(tab)) tab = "watch";
  TABS.forEach((t) => { $("v-" + t).hidden = t !== tab; }); $("v-sub").hidden = true;
  $("v-player").hidden = true; $("v-article").hidden = true; $("v-guide").hidden = true;
  document.querySelectorAll(".tab").forEach((b) => { if (b.dataset.tab === tab) b.setAttribute("aria-current","page"); else b.removeAttribute("aria-current"); });
  store.set("tab", tab);
  if (push) { try { history.replaceState(null, "", "#" + tab); } catch (e) {} window.scrollTo(0, 0); }
}
document.querySelectorAll(".tab").forEach((b) => b.addEventListener("click", () => show(b.dataset.tab, true)));

function chips(el, items, current, onPick){
  el.innerHTML = items.map(([v, label]) => `<button type="button" class="chip" data-v="${esc(v)}" aria-pressed="${v === current}">${esc(label)}</button>`).join("");
  el.onclick = (e) => { const b = e.target.closest(".chip"); if (b) onPick(b.dataset.v); };
}

/* ---------- 名前の照合（異名・技を選手にひもづける） ---------- */
const ALIAS = {"ジェイ・ウーソ":["ジェイ"],"リブ・モーガン":["リブ"],"ベッキー・リンチ":["ベッキー"],"コーディ・ローデス":["コーディ"],"トリック・ウィリアムズ":["トリック"],"シャーロット・フレアー":["シャーロット"],"イヨ・スカイ":["イヨ"],"ビアンカ・ブレア":["ビアンカ"],"ソロ・シコア":["ソロ"],"ラケル・ロドリゲス":["ラケル"],"ローラ・バイス":["ローラ"],"ナイア・ジャックス":["ナイア"],"ドミニク・ミステリオ":["ドミニク"],"レイ・ミステリオ":["レイ"],"タマ・トンガ":["MFT"],"タラ・トンガ":["MFT"],"ブロック・レスナー":["レスナー"],"ジェイド・カーギル":["カーギル"],"ジョン・シナ":["シナ"]};
const NOLAST = new Set(["レイ・ミステリオ","タマ・トンガ","タラ・トンガ","レイニー・リード","ブロンソン・リード","レイ・フェニックス"]);
function keysFor(name){
  const ks = [name].concat(ALIAS[name] || []);
  const parts = name.split("・");
  if (parts.length > 1 && !NOLAST.has(name)) { const last = parts[parts.length - 1]; if (last.length >= 3) ks.push(last); }
  if (name === "ブロンソン・リード") ks.push("ブロンソン・リード");
  if (name === "レイ・フェニックス") ks.push("フェニックス");
  return ks;
}
function mentions(text, name){
  return keysFor(name).some((k) => {
    try { return new RegExp("(?<![ァ-ヶー・A-Za-z])" + k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(?![ァ-ヶー])").test(text); }
    catch (e) { return text.includes(k); }
  });
}

/* ---------- 選手 ---------- */
const GROUPS = [["all","すべて"],["rm","RAW 男子"],["rw","RAW 女子"],["sm","SmackDown 男子"],["sw","SmackDown 女子"],["nm","NXT 男子"],["nw","NXT 女子"],["ot","その他"],["an","実況・解説"],["gn","WWEを去った人"],["lg","レジェンドほか"]];
