/* ---------- 名場面（モーメント集・おすすめ大会・アクシデント集） ---------- */
let histCat = store.get("hist", "moments");
function histWho(en){ const r = ROSTER.find((x) => x[1] === en); if (r) return `<button type="button" class="chip" data-player="${esc(en)}">${esc(r[0])}</button>`; return `<span class="chip">${esc((typeof HIST_JA !== "undefined" && HIST_JA[en]) || en)}</span>`; }
function histDate(d){ const [y, m, dd] = d.split("-").map(Number); return `${y}年${m}月${dd}日`; }
function histLink(q){ return `<div class="linkrow"><a href="https://www.youtube.com/@WWE/search?query=${encodeURIComponent(q)}" target="_blank" rel="noopener">WWE公式YouTubeで探す</a></div>`; }
function renderHist(){
  if (typeof HIST === "undefined") return;
  chips($("c-hist"), [["picks","管理人セレクト"],["today","今日は何の日"],["moments","名場面"],["events","おすすめ大会"],["accidents","アクシデント"],["funny","珍場面"],["trivia","小話"],["names","リングネーム辞典"],["quiz","クイズ"]], histCat, (v) => { histCat = v; store.set("hist", v); renderHist(); });
  if (FEAT.includes(histCat)) { renderFeat(); return; }
  const LEAD = { funny: "思わず笑ってしまう珍場面です。予定外のハプニングも、狙ってやった名コントも入っています。", moments: "WWEの歴史で語り継がれている場面を、古い順に並べています。", events: "大会ごとのおすすめを、見る優先度で3段階に分けています。選び方はサイトの好みです。", accidents: "予定外の出来事やけがが、そのまま歴史に残った場面です。亡くなった方が出た事故は載せていません。", trivia: "リングや会場の裏側にまつわる小話です。出典を各項目の下に付けています。" };
  $("hist-note").textContent = LEAD[histCat];
  const all = HIST[histCat] || [], list = all.filter((x) => seen(x.d)), hidden = all.length - list.length;
  let html = "";
  if (histCat === "events") {
    const TIER = { 1: "まず見たい", 2: "見ておきたい", 3: "好みで選ぶ" };
    [1, 2, 3].forEach((t) => { const xs = list.filter((x) => x.tier === t).sort((a, b) => a.d < b.d ? -1 : 1); if (!xs.length) return;
      html += `<div class="sec">${TIER[t]}</div>` + xs.map((x) => `<article class="card hist">
        <div class="meta"><span class="tag acc">${esc(TIER[t])}</span><span>${esc(histDate(x.d))}</span><span>${esc(x.place)}</span></div>
        <h3>${esc(x.name)}</h3><p>${esc(x.b)}</p>
        <ul class="plain">${x.best.map((m) => `<li>${esc(m)}</li>`).join("")}</ul>
        <p class="note">${esc(x.tip)}</p>${histLink(x.q)}</article>`).join(""); });
  } else if (histCat === "trivia") {
    html = list.map((x) => `<article class="card hist">
      <h3>Q. ${esc(x.q)}</h3><p>${esc(x.a)}</p>${x.note ? `<p class="note">${esc(x.note)}</p>` : ""}
      <div class="linkrow">${x.src.map(([l, u]) => `<a href="${esc(u)}" target="_blank" rel="noopener">出典：${esc(l)}</a>`).join("")}</div></article>`).join("");
  } else {
    html = list.sort((a, b) => !a.d ? 1 : !b.d ? -1 : a.d < b.d ? -1 : 1).map((x) => `<article class="card hist">
      <div class="meta">${x.d ? `<span>${esc(histDate(x.d))}</span>` : ""}<span>${esc(x.ev)}</span></div>
      <h3>${esc(x.t)}</h3>
      <div class="row" style="gap:6px;flex-wrap:wrap">${x.who.map(histWho).join("")}</div>
      <p>${esc(x.b)}</p>${x.why || x.after ? `<p class="note">${esc(x.why || x.after)}</p>` : ""}${histLink(x.q)}</article>`).join("");
  }
  $("l-hist").innerHTML = html + (hidden ? `<div class="card lock"><span class="note">「知識はここまで」より後の項目が${hidden}件あります。</span></div>` : "");
}

