  const cf = e.target.closest("[data-catf]"); if (cf) { const root = cf.closest(".view"); root.querySelectorAll("[data-catf]").forEach((x) => x.classList.toggle("on", x === cf)); root.querySelectorAll(".catblock").forEach((bl) => { const on = !cf.dataset.catf || bl.dataset.cat === cf.dataset.catf; bl.hidden = !on; if (cf.dataset.catf && on) { const mb = bl.querySelector(".morebox"), bt = bl.querySelector("[data-more]"); if (mb) { mb.hidden = false; if (bt) bt.hidden = true; } } }); return; }
  const mo = e.target.closest("[data-more]"); if (mo) { mo.nextElementSibling.hidden = false; mo.hidden = true; return; }
  const sr = e.target.closest("[data-mic]"); if (sr) { openMic(sr.dataset.mic); return; }
